/**
 * Great waterfalls: a river that reaches a drop worth the drive, cut the way real falls cut — the lip
 * holds the river up in a broad pool, the fall has eaten a gorge back upstream into the rock below, and
 * the plunge pool at its foot drains out down that gorge until the river's own bed comes down to meet it.
 *
 * Seven shapes, after the falls everyone knows:
 *   horseshoe  a curved lip wrapped round a round plunge pool (Niagara's Horseshoe)
 *   curtain    a very wide straight lip pouring into a narrow chasm across the river, a knife-edge of rock
 *              beyond it and one slot out down a gorge (Victoria)
 *   cataract   a wide lip broken into strands by islands, the flanks dropping in two tiers (Iguazu)
 *   block      a short straight curtain with talus at its foot (Niagara's American Falls)
 *   plunge     a tall thin ribbon into a small round pool (Angel, High Force)
 *   tiered     a stair of falls and pools down a mountainside (Gullfoss, the Seven Sisters)
 *   punchbowl  a river squeezed through a notch into a broad round bowl (Punch Bowl Falls)
 *
 * Everything is carved into the tile corners before the walls go up (generate.ts stage 7, through
 * landformsLocal.carve), on the cell's own ground well inside the seam band, with water levels laid in
 * `lakeLvl` so the water stage stands each pool exactly where it was planned. The render side
 * (mesher.buildFallChunk) draws a sheet wherever two pieces of water stand apart, so the falls draw
 * themselves; render/landforms.ts adds the spray and a lookout.
 *
 * Its own generator, seeded from the cell: no draw here moves anything else's.
 */
import { N, Biome, Flag, Surface, World, DIRS, EDGE_THEIRS, idx, inB, minCorner, type Landmark } from './tiles';
import { hash2, hashCell, mulberry32, type Rng } from './rng';
import { landformName } from './landforms';

export const FALL_STYLES = ['horseshoe', 'curtain', 'cataract', 'block', 'plunge', 'tiered', 'punchbowl'] as const;
type FallStyle = typeof FALL_STYLES[number];

/** What a fall of each shape is called, from the name word. */
const FALL_NAME: Record<FallStyle, (a: string) => string> = {
  horseshoe: (a) => `${a} Horseshoe Falls`,
  curtain: (a) => `${a} Thunder Falls`,
  cataract: (a) => `the ${a} Cataracts`,
  block: (a) => `${a} Falls`,
  plunge: (a) => `${a} Force`,
  tiered: (a) => `${a} Stair Falls`,
  punchbowl: (a) => `${a} Punchbowl`,
};

/** How much drop, in steps, each shape needs, and whether it needs a real river (not a stream). */
const NEED: Record<FallStyle, { drop: number; big: boolean; w: number }> = {
  horseshoe: { drop: 6, big: true, w: 3 },
  curtain: { drop: 6, big: true, w: 2 },
  cataract: { drop: 6, big: true, w: 1.6 },
  block: { drop: 4, big: false, w: 0.8 },
  plunge: { drop: 9, big: false, w: 1.5 },
  tiered: { drop: 8, big: false, w: 1.3 },
  punchbowl: { drop: 4, big: false, w: 0.7 },
};

/** One county in this many that has a river falling far enough gets a great waterfall. */
const FALLS_CHANCE = 0.7;
const SALT = 61771;
/** The gate switches the falls off to measure a cell without them. */
export const FALLS = { on: true, stats: { cells: 0, sites: 0, plans: 0, made: 0, ms: 0 } };
/** The longest gorge a fall may have eaten back, in tiles along the river. */
const GORGE_MAX = 44;

interface FallsInputs {
  w: World; land: Uint8Array; lakeLvl: Int8Array; river: Uint8Array; noTown: Uint8Array;
  seedHash: number;
  /** Tiles from the cell's edge a carve must keep (the seam band and a margin). */
  keep: number;
  /** Tiles kept clear: the railway's planned line, the town sites, the works. */
  avoid?: Uint8Array;
}

const enum Role { Pool = 1, Basin = 2, Rim = 3 }
interface Cut { role: Role; bed: number; water: number }

/**
 * The tiles a waterfall must stay off: the railway's planned line (it is laid before the corners are
 * carved, and would otherwise be left spanning a gorge it never planned for), each town's site and the
 * works', with a margin. Built in generate.ts from what is planned by stage 7.
 */
export function keepClearMask(
  rails: { pts: number[] }[], towns: { x0: number; z0: number; size: number }[], works: { x: number; z: number; len: number; half: number }[],
): Uint8Array {
  const m = new Uint8Array(N * N);
  const disc = (x: number, z: number, r: number) => {
    const x0 = Math.max(0, Math.floor(x - r)), x1 = Math.min(N - 1, Math.ceil(x + r));
    const z0 = Math.max(0, Math.floor(z - r)), z1 = Math.min(N - 1, Math.ceil(z + r));
    for (let tz = z0; tz <= z1; tz++) for (let tx = x0; tx <= x1; tx++) if (Math.hypot(tx + 0.5 - x, tz + 0.5 - z) <= r) m[tz * N + tx] = 1;
  };
  for (const r of rails) for (let k = 0; k + 1 < r.pts.length; k += 2) disc(r.pts[k], r.pts[k + 1], 4);
  for (const t of towns) {
    // the site and two tiles round it are no place for a fall; water keeps four tiles off (value 2)
    for (const [M, v] of [[4, 2], [2, 1]] as const) {
      for (let z = Math.max(0, t.z0 - M); z < Math.min(N, t.z0 + t.size + M); z++) {
        for (let x = Math.max(0, t.x0 - M); x < Math.min(N, t.x0 + t.size + M); x++) { const i = z * N + x; if (v === 1 || !m[i]) m[i] = v; }
      }
    }
  }
  for (const g of works) disc(g.x + 0.5, g.z + 0.5, Math.max(g.len, g.half) + 4);
  return m;
}

/**
 * Find the best drop on this cell's rivers and carve a waterfall of a fitting shape into it. Returns
 * the landmark (already pushed onto w.landmarks), or null where the dice or the ground said no.
 */
export function carveWaterfalls(inp: FallsInputs): Landmark | null {
  const { w, seedHash } = inp;
  if (!FALLS.on) return null;
  if (hash2(w.cx, w.cz, (seedHash ^ SALT) | 0) >= FALLS_CHANCE) return null;
  const t0 = performance.now();
  try { return carve(inp); } finally { FALLS.stats.ms += performance.now() - t0; }
}

function carve(inp: FallsInputs): Landmark | null {
  const { w, land, lakeLvl, river, seedHash, keep, avoid } = inp;
  const ST = FALLS.stats;
  ST.cells++;
  const rng = mulberry32(hashCell(seedHash, w.cx, w.cz, SALT));
  const c = w.corners;
  const inner = (x: number, z: number, m = 0) => x >= keep + m && z >= keep + m && x < N - keep - m && z < N - keep - m;
  const bed = (i: number) => minCorner(w, i);
  /** Ground a waterfall may be cut into at all. */
  const free = (i: number): boolean => {
    if (!land[i] || river[i] === 3 || lakeLvl[i] > -128 || (avoid && avoid[i] === 1)) return false;
    if (w.flags[i] & (Flag.Field | Flag.Track | Flag.Poi | Flag.Ramp | Flag.Corridor)) return false;
    const b = w.biome[i];
    if (b === Biome.Town || b === Biome.Lava || b === Biome.Salt || b === Biome.Ice || b === Biome.Ocean || b === Biome.Mangrove) return false;
    return w.feature[i] === 0 && w.coastDist[i] > 8;
  };
  const wet = (i: number) => !land[i] || river[i] > 0 || lakeLvl[i] > -128;
  /** Ground a fall's water may stand on: free, and not in the margin kept round a town. */
  const waterOk = (i: number) => free(i) && !(avoid && avoid[i]);

  /** Downhill from s, one tile at a time to the lowest open neighbour; stops short of water, or at `max`. */
  const descend = (s: number, max: number, onRiver: boolean): { path: number[]; wet: boolean } => {
    const path = [s];
    const seen = new Set(path);
    let cur = s, flat = 0;
    for (let k = 0; k < max; k++) {
      const x = cur % N, z = (cur - x) / N;
      let next = -1, low = Infinity, water = false;
      for (const [dx, dz] of DIRS) {
        if (!inner(x + dx, z + dz, 3)) continue;
        const j = idx(x + dx, z + dz);
        if (seen.has(j)) continue;
        if (!onRiver && wet(j) && bed(j) <= bed(cur)) { water = true; break; }
        if (onRiver ? !(river[j] === 1 || river[j] === 2) || !free(j) : !free(j) || river[j]) continue;
        const b = bed(j);
        if (b < low) { low = b; next = j; }
      }
      if (water) return { path, wet: true };
      if (next < 0 || low > bed(cur) + (onRiver ? 1 : 0)) break;
      flat = low < bed(cur) ? 0 : flat + 1;
      if (flat > 3 && !onRiver) break;
      path.push(next); seen.add(next); cur = next;
    }
    return { path, wet: false };
  };

  // how far each tile is from ground a fall may not take (river water counts as takeable), in tiles
  const room = new Uint8Array(N * N);
  for (let i = 0; i < N * N; i++) room[i] = (free(i) || (land[i] && (river[i] === 1 || river[i] === 2))) && !(avoid && avoid[i]) ? 255 : 0;
  for (let z = 0; z < N; z++) for (let x = 0; x < N; x++) {
    const i = z * N + x;
    if (!room[i]) continue;
    let v = room[i];
    if (x > 0) v = Math.min(v, room[i - 1] + 1);
    if (z > 0) v = Math.min(v, room[i - N] + 1, x > 0 ? room[i - N - 1] + 1 : 255, x < N - 1 ? room[i - N + 1] + 1 : 255);
    room[i] = v;
  }
  for (let z = N - 1; z >= 0; z--) for (let x = N - 1; x >= 0; x--) {
    const i = z * N + x;
    if (!room[i]) continue;
    let v = room[i];
    if (x < N - 1) v = Math.min(v, room[i + 1] + 1);
    if (z < N - 1) v = Math.min(v, room[i + N] + 1, x < N - 1 ? room[i + N + 1] + 1 : 255, x > 0 ? room[i + N - 1] + 1 : 255);
    room[i] = v;
  }

  // ---- candidate lips: river tiles walked downstream, and high ground walked downhill ----
  const lips: number[] = [], dry: number[] = [];
  for (let z = keep + 6; z < N - keep - 6; z++) {
    for (let x = keep + 6; x < N - keep - 6; x++) {
      const i = z * N + x;
      if (!free(i)) continue;
      if (river[i] === 1 || river[i] === 2) lips.push(i);
      else if (!river[i] && w.biome[i] !== Biome.Desert && w.biome[i] !== Biome.Canyon) dry.push(i);
    }
  }
  interface Site { s: number; path: number[]; kEnd: number; drop: number; score: number; onRiver: boolean }
  const sites: Site[] = [];
  const consider = (s: number, onRiver: boolean) => {
    const { path } = descend(s, GORGE_MAX + 4, onRiver);
    if (path.length < 4) return;
    // the deepest the bed comes down within a gorge's length, and the first place it gets there
    const top = bed(s);
    let lowest = top, kEnd = -1;
    for (let k = 1; k < Math.min(path.length, GORGE_MAX); k++) {
      const b = bed(path[k]);
      if (b < lowest) { lowest = b; kEnd = k; }
    }
    let drop = top - lowest;
    if (kEnd < 2 || drop < 4) return;
    // a shorter gorge that keeps most of the drop is the better fall
    for (let k = 2; k < kEnd; k++) {
      const d = top - bed(path[k]);
      if (d >= Math.max(4, drop * 0.8)) { kEnd = k; drop = d; break; }
    }
    // room round the lip for the pool, and round the gorge for its walls
    if (room[s] < 5) return;
    for (let k = 1; k <= kEnd; k++) if (room[path[k]] < 2) return;
    // a steep drop over a short run is a fall; a long gentle one is only a gorge
    const score = drop - kEnd * 0.18 + (onRiver ? 4 : 0) + (river[s] === 2 ? 1.5 : 0);
    sites.push({ s, path, kEnd, drop, score, onRiver });
  };
  for (let t = 0; t < Math.min(lips.length, 600); t++) consider(lips[Math.floor(rng() * lips.length)], true);
  for (let t = 0; t < Math.min(dry.length, 1600); t++) consider(dry[Math.floor(rng() * dry.length)], false);
  ST.sites += sites.length;
  if (!sites.length) return null;
  sites.sort((a, b) => b.score - a.score || a.s - b.s);

  // ---- the shape: tried on the best sites until one holds its water ----
  const seenLip = new Set<number>();
  for (const site of sites.slice(0, 150)) {
    if (seenLip.has(site.s)) continue;
    seenLip.add(site.s);
    // high ground with no river of its own is fed from a hanging valley above the lip: a broad one in
    // most cases, so the famous shapes can stand there too
    const big = site.onRiver ? river[site.s] === 2 : rng() < 0.6;
    const fits = FALL_STYLES.filter((st) => site.drop >= NEED[st].drop && (big || !NEED[st].big));
    if (!fits.length) continue;
    // the way out: on from the gorge's foot, downhill to the nearest water
    const out = descend(site.path[site.kEnd], 160, false);
    const outflow = out.wet ? out.path.slice(1) : [];
    // weighted order: the famous shapes first where they fit, then the rest
    const order = fits.map((st) => ({ st, k: rng() * NEED[st].w })).sort((a, b) => b.k - a.k || FALL_STYLES.indexOf(a.st) - FALL_STYLES.indexOf(b.st));
    for (const { st } of order) {
      const plan = planFall(w, st, site.s, site.path, site.kEnd, site.drop, big, rng, room[site.s], waterOk, site.onRiver ? null : { free: waterOk, wet, river });
      if (!plan) continue;
      ST.plans++;
      const outSet = new Set(outflow.filter((i) => !plan.cuts.has(i)));
      if (!check(plan.cuts, w, avoid, free, (i) => wet(i) || outSet.has(i), inner)) continue;
      ST.made++;
      return apply(inp, st, plan, site.drop, big, [...outSet]);
    }
  }
  return null;
}

interface Plan {
  cuts: Map<number, Cut>;
  /** The lip's middle (local tiles), the way the river runs over it, and the fall's half-width. */
  lx: number; lz: number; fx: number; fz: number; half: number;
  /** Where the plunge pool's middle lies, and its reach. */
  bx: number; bz: number; br: number;
  W1: number; W2: number;
}

/** Lay out the tiles of a fall of one shape at lip `s`. Null where the shape cannot fit. */
/** What a fall on dry high ground needs to dig its hanging valley: where it may go and where water already is. */
interface Feed { free: (i: number) => boolean; wet: (i: number) => boolean; river: Uint8Array }

function planFall(
  w: World, st: FallStyle, s: number, path: number[], kEnd: number, drop: number, big: boolean, rng: Rng, space: number,
  free: (i: number) => boolean, feed: Feed | null,
): Plan | null {
  const sx = s % N, sz = (s - sx) / N;
  // the way the river runs over the lip, from the next few tiles of its course
  let fx = 0, fz = 0;
  for (let k = 1; k <= Math.min(5, path.length - 1); k++) {
    const t = path[k], tx = t % N, tz = (t - tx) / N;
    fx += tx - sx; fz += tz - sz;
  }
  const fl = Math.hypot(fx, fz);
  if (fl < 1) return null;
  fx /= fl; fz /= fl;
  const px = -fz, pz = fx;
  const depth = big ? 2 : 1;
  // a river's bed is cut already; on dry ground the pool is dug in below the banks that hold it
  const shift = feed ? depth : 0;
  const lipBed = minCorner(w, s) - shift;
  const Fb = lipBed - drop;
  const W1 = lipBed + depth, W2 = Fb + depth;
  const cuts = new Map<number, Cut>();
  const pool = (i: number) => cuts.set(i, { role: Role.Pool, bed: lipBed, water: W1 });
  const basin = (i: number, b = Fb) => cuts.set(i, { role: Role.Basin, bed: b, water: b + depth });
  const rim = (i: number, top: number) => cuts.set(i, { role: Role.Rim, bed: top, water: -128 });
  // the lip line runs across the downstream face of the lip tile
  const lx = sx + 0.5 + fx * 0.5, lz = sz + 0.5 + fz * 0.5;
  /** Every tile within `r` of the lip line's middle, with its along/across offsets from it. */
  const around = (r: number, f: (i: number, a: number, cc: number, x: number, z: number) => void) => {
    for (let z = Math.floor(lz - r); z <= Math.ceil(lz + r); z++) {
      for (let x = Math.floor(lx - r); x <= Math.ceil(lx + r); x++) {
        if (!inB(x, z)) continue;
        const dx = x + 0.5 - lx, dz = z + 0.5 - lz;
        f(idx(x, z), dx * fx + dz * fz, dx * px + dz * pz, x, z);
      }
    }
  };
  // the gorge the fall has eaten back: the river's course below the lip, cut down to the foot
  const gorge = (hw: number, from = 1) => {
    for (let k = from; k <= kEnd; k++) {
      const t = path[k], tx = t % N, tz = (t - tx) / N;
      const r = Math.ceil(hw);
      for (let dz = -r; dz <= r; dz++) for (let dx = -r; dx <= r; dx++) {
        if (Math.hypot(dx, dz) > hw + 0.01 || !inB(tx + dx, tz + dz)) continue;
        const j = idx(tx + dx, tz + dz);
        if (!cuts.has(j)) basin(j);
      }
    }
  };
  /** The river widening out above a broad lip, tapering back to its own width upstream. */
  const funnel = (half: number, from: number, len: number) => {
    around(half + len + 2, (i, a, cc) => {
      if (a >= from || a < from - len) return;
      const t = (from - a) / len;
      if (Math.abs(cc) <= Math.max(1, half * (1 - 0.8 * t)) && free(i)) pool(i);
    });
  };
  let half = 1, bx = lx + fx, bz = lz + fz, br = 1.5;
  switch (st) {
    case 'horseshoe': {
      const R = Math.min(7.5, space - 3, 3.8 + drop * 0.2 + rng() * 1.5);
      if (R < 3.5) return null;
      const cx = lx + fx * R * 0.6, cz = lz + fz * R * 0.6;
      half = R; bx = cx; bz = cz; br = R;
      gorge(1.2);
      for (let z = Math.floor(cz - R - 14); z <= Math.ceil(cz + R + 14); z++) {
        for (let x = Math.floor(cx - R - 14); x <= Math.ceil(cx + R + 14); x++) {
          if (!inB(x, z)) continue;
          const dx = x + 0.5 - cx, dz = z + 0.5 - cz;
          const a = dx * fx + dz * fz, cc = dx * px + dz * pz, r = Math.hypot(dx, dz), i = idx(x, z);
          if (r <= R) basin(i);
          // the throat: the pool drains out downstream, narrowing into the gorge
          else if (a > 0 && a < R + 7 && Math.abs(cc) <= Math.max(1.2, R * 0.75 - (a - R * 0.4) * 0.4)) basin(i);
          // the crest wraps round the pool from upstream and down both flanks
          else if (r <= R + 3.5 && a <= R * 0.3) pool(i);
          else if (a < -R && a >= -R - 10 && Math.abs(cc) <= (R + 2) * (1 - (-a - R) / 13)) pool(i);
        }
      }
      break;
    }
    case 'curtain': {
      const H = Math.min(space - 2, 6 + Math.floor(rng() * 5));
      if (H < 5) return null;
      half = H; br = H; bx = lx + fx; bz = lz + fz;
      gorge(1, 3);
      around(H + 16, (i, a, cc) => {
        const ac = Math.abs(cc);
        if (a >= -8 && a < 0 && ac <= H) pool(i);
        // the chasm: two tiles wide, as long as the lip, square across the river
        else if (a >= 0 && a < 2 && ac <= H) basin(i);
        // the knife-edge of rock beyond it, with one slot through for the river
        else if (a >= 2 && a < 4.5 && ac <= H + 1) { if (ac > 1.3) rim(i, W1 + 1); else basin(i); }
      });
      funnel(H, -8, 8);
      break;
    }
    case 'cataract': {
      const H = Math.min(space - 2, 5 + Math.floor(rng() * 4));
      if (H < 4) return null;
      half = H; br = H; bx = lx + fx * 2.5; bz = lz + fz * 2.5;
      const ledge = Fb + Math.round(drop / 2);
      gorge(1.2, 4);
      around(H + 14, (i, a, cc, x, z) => {
        const ac = Math.abs(cc);
        if (a >= -7 && a < 0 && ac <= H) {
          // islands on the lip break the curtain into strands, and a few stand out in the river above
          const strand = a >= -1.5 && ac > 1.2 && hash2(x, z, 4711) < 0.3;
          const islet = a < -2.5 && a > -6 && ac > 1.5 && hash2(x, z, 4712) < 0.08;
          if (strand || islet) rim(i, W1 + 1); else pool(i);
        } else if (a >= 0 && a < 4 && ac <= H) {
          // the flanks fall to a ledge first and then again into the pool
          if (a < 1.5 && ac > H * 0.45) basin(i, ledge); else basin(i);
        } else if (a >= 4 && a < 4 + H && ac <= Math.max(1.2, H - (a - 4) * 1.1)) basin(i);
      });
      funnel(H, -7, 8);
      break;
    }
    case 'block': {
      const H = Math.min(space - 1.5, 2.5 + Math.floor(rng() * 3));
      half = H; br = H; bx = lx + fx * 1.5; bz = lz + fz * 1.5;
      gorge(1, 2);
      around(H + 12, (i, a, cc, x, z) => {
        const ac = Math.abs(cc);
        if (a >= -6 && a < 0 && ac <= H) pool(i);
        else if (a >= 0 && a < 3 + H * 0.5 && ac <= H - Math.max(0, a - 2) * 0.8) {
          // talus: fallen rock heaped at the foot of the face
          if (a < 1 && hash2(x, z, 4721) < 0.3) rim(i, Fb + depth + 1); else basin(i);
        }
      });
      funnel(H, -6, 6);
      break;
    }
    case 'plunge': {
      const R = 1.6 + rng() * 1.2;
      half = 0.5; br = R;
      const cx = lx + fx * (R + 0.2), cz = lz + fz * (R + 0.2);
      bx = cx; bz = cz;
      gorge(big ? 1 : 0.5);
      pool(s);
      around(R + 3, (i, a, cc, x, z) => {
        if (Math.hypot(x + 0.5 - cx, z + 0.5 - cz) <= R && a > 0) basin(i);
      });
      break;
    }
    case 'punchbowl': {
      const R = Math.min(space - 1, 3.2 + rng() * 1.6);
      half = 0.5; br = R;
      const cx = lx + fx * (R + 0.3), cz = lz + fz * (R + 0.3);
      bx = cx; bz = cz;
      gorge(1);
      pool(s);
      around(R + 4, (i, a, cc, x, z) => {
        const ac = Math.abs(cc);
        // the notch: rock squeezing the river in on both sides just above the drop
        if (a >= -2.2 && a < 0 && ac >= 0.9 && ac <= 2.6) rim(i, W1 + 1);
        else if (Math.hypot(x + 0.5 - cx, z + 0.5 - cz) <= R && a > 0) basin(i);
      });
      break;
    }
    case 'tiered': {
      // tiers where the river's own bed falls, each pool levelled and widened
      const n = drop >= 15 ? 4 : drop >= 11 ? 3 : 2;
      const lv: number[] = [];
      for (let t = 0; t <= n; t++) lv.push(lipBed - Math.round((drop * t) / n));
      let tier = 0;
      const tierOf: number[] = [];
      for (let k = 0; k <= kEnd; k++) {
        if (k === 0) { tierOf.push(0); continue; }
        while (tier < n && minCorner(w, path[k]) - shift <= lv[tier + 1]) tier++;
        // the first drop is always at the lip
        tierOf.push(Math.max(1, tier));
      }
      // every tier must have a pool of its own at least two tiles long; where the river's own fall is
      // too bunched for that, the stair is spaced out evenly down the gorge instead
      const len = new Array(n + 1).fill(0);
      for (const t of tierOf) len[t]++;
      let even = false;
      for (let t = 1; t <= n; t++) if (len[t] < 2) even = true;
      if (even) {
        if (kEnd < 2 * n + 1) return null;
        for (let k = 1; k <= kEnd; k++) tierOf[k] = Math.min(n, 1 + Math.floor(((k - 1) * n) / kEnd));
      }
      const hw = big ? 1.5 : 1.2;
      const assign = new Map<number, number>();
      for (let k = 0; k <= kEnd; k++) {
        const t = path[k], tx = t % N, tz = (t - tx) / N;
        const r = Math.ceil(hw);
        for (let dz = -r; dz <= r; dz++) for (let dx = -r; dx <= r; dx++) {
          if (Math.hypot(dx, dz) > hw + 0.01 || !inB(tx + dx, tz + dz)) continue;
          const j = idx(tx + dx, tz + dz);
          // a tile beside two tiers belongs to the higher, so no pool drains sideways round a fall
          const prev = assign.get(j);
          if (prev === undefined || tierOf[k] < prev) assign.set(j, tierOf[k]);
        }
      }
      for (const [j, t] of assign) {
        if (t === 0) pool(j);
        else basin(j, lv[t]);
      }
      half = hw; br = hw + 1;
      const mid = path[Math.min(kEnd, Math.floor(kEnd / 2))];
      bx = (mid % N) + 0.5; bz = Math.floor(mid / N) + 0.5;
      break;
    }
  }
  // high ground with no river: a hanging valley above the lip, dug back from it to a spring-fed tarn
  // (or to a river already up there, if the valley meets one)
  if (feed) {
    const wide = half > 2;
    const U = (wide ? 15 : 6) + Math.floor(rng() * 5);
    let fed = false, end = U;
    for (let k = 0; k <= U && !fed; k++) {
      const qx = lx - fx * (k + 0.5), qz = lz - fz * (k + 0.5);
      const here: number[] = [];
      let blocked = false;
      for (let z = Math.floor(qz - 1); z <= Math.ceil(qz + 1); z++) {
        for (let x = Math.floor(qx - 1); x <= Math.ceil(qx + 1); x++) {
          if (!inB(x, z) || Math.hypot(x + 0.5 - qx, z + 0.5 - qz) > 0.75) continue;
          const i = idx(x, z);
          if (feed.river[i] && feed.wet(i) && minCorner(w, i) >= lipBed) { fed = true; continue; }
          if (!cuts.has(i)) { if (feed.free(i)) here.push(i); else blocked = true; }
        }
      }
      // the valley stops short of a road's way, a town or a field; the tarn that feeds it lies there
      if (blocked) { end = k - 2; break; }
      for (const i of here) pool(i);
    }
    if (end < 3 && !fed) return null;
    if (!fed) {
      const qx = lx - fx * (end + 1.5), qz = lz - fz * (end + 1.5), r = 1.6 + rng() * 0.9;
      for (let z = Math.floor(qz - r); z <= Math.ceil(qz + r); z++) {
        for (let x = Math.floor(qx - r); x <= Math.ceil(qx + r); x++) {
          if (inB(x, z) && Math.hypot(x + 0.5 - qx, z + 0.5 - qz) <= r && !cuts.has(idx(x, z)) && feed.free(idx(x, z))) pool(idx(x, z));
        }
      }
    }
  }
  return { cuts, lx, lz, fx, fz, half, bx, bz, br, W1, W2 };
}

/**
 * Will it hold its water? Every tile must be ground a fall may take, and no pool may stand above the
 * dry ground beside it (a leak would hang a sheet of water in mid-air down the side of the valley).
 * A pool tile on ground lower than its bed becomes a rim of rock instead, up to a quarter of them.
 */
function check(cuts: Map<number, Cut>, w: World, avoid: Uint8Array | undefined, free: (i: number) => boolean, wet: (i: number) => boolean, inner: (x: number, z: number, m?: number) => boolean): boolean {
  let pools = 0, rims = 0;
  for (const [i, cut] of cuts) {
    const x = i % N, z = (i - x) / N;
    if (!inner(x, z, 2)) return false;
    if (!free(i)) return false;
    // water keeps further from a town than rock does: its lots and lanes are levelled after the falls are cut
    if (cut.role !== Role.Rim && avoid && avoid[i] === 2) return false;
    if (cut.role === Role.Pool) {
      pools++;
      if (minCorner(w, i) < cut.bed) { cuts.set(i, { role: Role.Rim, bed: cut.water, water: -128 }); rims++; }
    }
  }
  if (pools && rims > pools * 0.25) return false;
  // Where a pool would stand above the dry ground beside it, that ground is built up into a rim of rock
  // at the water's level (a falls' banks are rock); past a third of the water's size in rims, or where
  // the ground may not be touched, the water would leak and the shape does not fit here.
  let leaks = 0, waters = 0;
  const c = w.corners;
  const levee = new Map<number, number>();
  for (const [i, cut] of cuts) {
    if (cut.role === Role.Rim) continue;
    waters++;
    const x = i % N, z = (i - x) / N;
    for (let d = 0; d < 4; d++) {
      const nx = x + DIRS[d][0], nz = z + DIRS[d][1];
      if (!inB(nx, nz)) return false;
      const j = idx(nx, nz);
      const o = cuts.get(j);
      if (o) {
        if (o.role === Role.Rim && Math.max(o.bed, minCorner(w, j)) < cut.water) o.bed = cut.water;
        continue;
      }
      if (wet(j)) continue;
      // the whole tile, not just the shared edge: the water stage spreads a pool onto any bank lower than it
      const ground = minCorner(w, j);
      if (ground >= cut.water) continue;
      if (free(j) && inner(nx, nz, 2)) levee.set(j, Math.max(levee.get(j) ?? -128, cut.water));
      else leaks++;
    }
  }
  if (levee.size > waters * 0.3 + 3) leaks++;
  if (leaks > 0) return false;
  for (const [j, top] of levee) cuts.set(j, { role: Role.Rim, bed: top, water: -128 });
  return true;
}

/** Carve a planned fall into the corners and name it. */
function apply(inp: FallsInputs, st: FallStyle, p: Plan, drop: number, big: boolean, outflow: number[]): Landmark {
  const { w, lakeLvl, noTown } = inp;
  const c = w.corners;
  for (const [i, cut] of p.cuts) {
    const b = i * 4;
    if (cut.role === Role.Rim) {
      for (let k = 0; k < 4; k++) c[b + k] = Math.max(c[b + k], cut.bed);
      w.surface[i] = Surface.Rock;
    } else {
      for (let k = 0; k < 4; k++) c[b + k] = Math.min(c[b + k], cut.bed);
      lakeLvl[i] = cut.water;
      // running water, as a river's is (the level comes from lakeLvl, which the water stage reads first)
      w.flags[i] |= Flag.River;
      if (cut.role === Role.Basin) w.surface[i] = Surface.Rock;
    }
    // walled at every step, as a terrace is: the legaliser must not ease a bank down under its pool
    w.flags[i] |= Flag.Corridor | Flag.Terrace;
    noTown[i] = 1;
    // its water is lakeLvl's now: nothing that walks the river table (the cascade) may re-level it
    inp.river[i] = 0;
  }
  // the stream out of the gorge's foot, down to the nearest water: a bed a step deep that never climbs
  let last = Infinity;
  for (const i of outflow) {
    const b = i * 4;
    const lv = Math.min(minCorner(w, i) - 1, last);
    for (let k = 0; k < 4; k++) c[b + k] = lv;
    last = lv;
    w.flags[i] |= Flag.Stream | Flag.Corridor;
    inp.river[i] = 1;
  }
  // the bare rock round the fall: the lip and the gorge's rim
  for (const [i, cut] of p.cuts) {
    if (cut.role !== Role.Basin) continue;
    const x = i % N, z = (i - x) / N;
    for (const [dx, dz] of DIRS) {
      if (!inB(x + dx, z + dz)) continue;
      const j = idx(x + dx, z + dz);
      if (!p.cuts.has(j) && inp.land[j] && minCorner(w, j) > cut.water) w.surface[j] = Surface.Rock;
    }
  }
  // a lookout on level ground beside the pool, looking back at the fall: kept clear of trees and works
  let look = -1, lookS = Infinity;
  const R = Math.ceil(p.br + 7);
  for (let dz = -R; dz <= R; dz++) {
    for (let dx = -R; dx <= R; dx++) {
      const tx = Math.floor(p.bx) + dx, tz = Math.floor(p.bz) + dz;
      if (tx < inp.keep || tz < inp.keep || tx >= N - inp.keep || tz >= N - inp.keep) continue;
      const i = idx(tx, tz);
      const d = Math.hypot(tx + 0.5 - p.bx, tz + 0.5 - p.bz);
      if (d < p.br + 1.2 || d > p.br + 7 || p.cuts.has(i) || !inp.land[i] || inp.river[i] || lakeLvl[i] > -128) continue;
      if (w.flags[i] & (Flag.Field | Flag.Track | Flag.Poi | Flag.Corridor | Flag.Ramp) || w.biome[i] === Biome.Town || (inp.avoid && inp.avoid[i])) continue;
      const b = i * 4;
      if (c[b] !== c[b + 1] || c[b] !== c[b + 2] || c[b] !== c[b + 3]) continue;
      const side = Math.abs((tx + 0.5 - p.bx) * -p.fz + (tz + 0.5 - p.bz) * p.fx) / d;
      const score = d - side * 2.5;
      if (score < lookS) { lookS = score; look = i; }
    }
  }
  if (look >= 0) { w.flags[look] |= Flag.Poi; w.cleared[look] = 1; }
  const word = landformName('waterfall', inp.seedHash, w.ox + p.lx, w.oz + p.lz).replace(/ Falls$/, '');
  const name = FALL_NAME[st](word);
  const style = FALL_STYLES.indexOf(st);
  const lm: Landmark = {
    kind: 'waterfall', name, x: p.lx, z: p.lz, r: Math.max(6, p.br + 4),
    data: [style, p.W1, p.W2, p.lx, p.lz, p.fx, p.fz, p.half, drop, p.bx, p.bz, p.br, big ? 1 : 0, look],
  };
  w.landmarks.push(lm);
  return lm;
}

/** The parts of a waterfall landmark's data, for the props and the gate. */
export function fallInfo(l: Landmark): {
  style: FallStyle; W1: number; W2: number; lx: number; lz: number; fx: number; fz: number; half: number; drop: number;
  bx: number; bz: number; br: number; big: boolean;
  /** The lookout's tile, or -1. */
  look: number;
} | null {
  const d = l.data;
  if (l.kind !== 'waterfall' || !d || d.length < 13) return null;
  return {
    style: FALL_STYLES[d[0]] ?? 'block', W1: d[1], W2: d[2], lx: d[3], lz: d[4], fx: d[5], fz: d[6], half: d[7], drop: d[8],
    bx: d[9], bz: d[10], br: d[11], big: d[12] === 1, look: d[13] ?? -1,
  };
}

/**
 * After the legaliser, before the water is laid: the legaliser only ever lowers, and where the ground it
 * started from was not yet legal it can bring a bank a step or two under the pool it was meant to hold.
 * Each such bank is built back up, flat, to the pool's level: a lip of rock round the water.
 */
export function holdFalls(w: World, lakeLvl: Int8Array, land: Uint8Array): void {
  const c = w.corners;
  for (const l of w.landmarks) {
    const f = fallInfo(l);
    if (!f) continue;
    const reach = GORGE_MAX + l.r + 20;
    for (let z = Math.max(1, Math.floor(l.z - reach)); z < Math.min(N - 1, Math.ceil(l.z + reach)); z++) {
      for (let x = Math.max(1, Math.floor(l.x - reach)); x < Math.min(N - 1, Math.ceil(l.x + reach)); x++) {
        const i = z * N + x, L = lakeLvl[i];
        if (L <= -128 || L > f.W1 || L < f.W2 || (w.flags[i] & (Flag.Corridor | Flag.Terrace)) !== (Flag.Corridor | Flag.Terrace)) continue;
        for (const [dx, dz] of DIRS) {
          const j = idx(x + dx, z + dz);
          if (!land[j] || lakeLvl[j] > -128 || (w.flags[j] & (Flag.River | Flag.Stream)) || minCorner(w, j) >= L) continue;
          for (let k = 0; k < 4; k++) c[j * 4 + k] = Math.max(c[j * 4 + k], L);
          w.flags[j] |= Flag.Corridor | Flag.Terrace;
          w.surface[j] = Surface.Rock;
        }
      }
    }
  }
}

/**
 * After the towns, roads and railway have had their way with the ground: a fall's pool that some later
 * levelling left standing above a bank beside it is let down to that bank (or drained, where that
 * leaves no water over its bed), so no sheet of water hangs in the air at a lot's edge. Run once at the
 * end of generation; the falls between the pools stay, a little shorter where a pool came down.
 */
export function sealFalls(w: World): void {
  const c = w.corners;
  for (const l of w.landmarks) {
    const f = fallInfo(l);
    if (!f) continue;
    const reach = GORGE_MAX + l.r + 20;
    const mine = new Set<number>();
    for (let z = Math.max(0, Math.floor(l.z - reach)); z < Math.min(N, Math.ceil(l.z + reach)); z++) {
      for (let x = Math.max(0, Math.floor(l.x - reach)); x < Math.min(N, Math.ceil(l.x + reach)); x++) {
        const i = z * N + x;
        const wl = w.water[i];
        if (wl >= f.W2 - 1 && wl <= f.W1 && (w.flags[i] & Flag.Corridor) && !(w.flags[i] & Flag.Stream)) mine.add(i);
      }
    }
    for (let pass = 0; pass < 6; pass++) {
      let changed = false;
      const seen = new Set<number>();
      for (const s of mine) {
        if (seen.has(s) || w.water[s] < 0) continue;
        const L = w.water[s];
        const comp = [s];
        seen.add(s);
        let bank = Infinity;
        for (let h = 0; h < comp.length; h++) {
          const i = comp[h], x = i % N, z = (i - x) / N;
          for (let d = 0; d < 4; d++) {
            const nx = x + DIRS[d][0], nz = z + DIRS[d][1];
            if (!inB(nx, nz)) continue;
            const j = idx(nx, nz);
            if (w.water[j] >= 0) {
              if (w.water[j] === L && mine.has(j) && !seen.has(j)) { seen.add(j); comp.push(j); }
              continue;
            }
            bank = Math.min(bank, c[j * 4 + EDGE_THEIRS[d][0]], c[j * 4 + EDGE_THEIRS[d][1]]);
          }
        }
        if (bank >= L) continue;
        for (const i of comp) w.water[i] = bank > minCorner(w, i) ? bank : -1;
        changed = true;
      }
      if (!changed) break;
    }
  }
}
