import { N, Biome, Flag, World, DIRS, inB, idx } from './tiles';
import type { Rng } from './rng';

/**
 * Mountain cores above `line` become stacked flat terraces (walls between levels).
 *
 * Pointwise on the elevation and the mountain mask, both of which are functions of the global tile,
 * so two cells cut the same steps into the same mountain without either having seen the other. That
 * is why it runs on the padded grid rather than on the cell, and takes arrays rather than a World.
 */
export function applyTerraces(
  c: Int8Array, flags: Uint8Array, mountMask: Float32Array, E: Float32Array, W: number,
  line: number, period: number,
): void {
  const WW = W * W;
  for (let i = 0; i < WW; i++) {
    if (mountMask[i] < 0.5 || E[i] < line) continue;
    const b = i * 4;
    const level = Math.floor(Math.min(c[b], c[b + 1], c[b + 2], c[b + 3]) / period) * period;
    c[b] = c[b + 1] = c[b + 2] = c[b + 3] = level;
    flags[i] |= Flag.Terrace;
  }
}

/**
 * Deep rivers running through desert become canyons: the river corridor (river + one ring)
 * drops by `depth` steps behind vertical walls, with a few straight ramps cut into the rim.
 * Segments where no ramp site exists are left as ordinary river valleys.
 *
 * In 'gorge' mode the same cut is made wherever a big river runs through ground over eight steps
 * outside the desert, and the walls keep the hillside's own colour; each gorge's middle is listed.
 */
export function applyCanyons(w: World, river: Uint8Array, rng: Rng, depth = 4, band = 0, mode: 'canyon' | 'gorge' = 'canyon', found?: [number, number][]): number {
  const NN = N * N;
  const cand = new Uint8Array(NN);
  const gorge = mode === 'gorge';
  for (let i = 0; i < NN; i++) {
    if (river[i] !== 2 || w.coastDist[i] <= 10 || (w.flags[i] & Flag.Corridor)) continue;
    if (gorge ? w.biome[i] === Biome.Desert || w.biome[i] === Biome.Canyon || w.elev[i] < 8 : w.biome[i] !== Biome.Desert) continue;
    // a canyon is the deepest cut anything makes: it stays well clear of a border a neighbour shares
    const x = i % N, z = (i - x) / N;
    if (band && (x < band || z < band || x >= N - band || z >= N - band)) continue;
    cand[i] = 1;
  }
  const seen = new Uint8Array(NN);
  let made = 0;
  for (let s = 0; s < NN; s++) {
    if (!cand[s] || seen[s]) continue;
    // collect segment
    const seg: number[] = [s];
    seen[s] = 1;
    for (let q = 0; q < seg.length; q++) {
      const i = seg[q];
      const x = i % N, z = (i - x) / N;
      for (let d = 0; d < 4; d++) {
        const nx = x + DIRS[d][0], nz = z + DIRS[d][1];
        if (!inB(nx, nz)) continue;
        const j = idx(nx, nz);
        if (cand[j] && !seen[j]) { seen[j] = 1; seg.push(j); }
      }
    }
    if (seg.length < 9 || (gorge && seg.length > 60)) continue;

    const inSeg = new Set(seg);
    const corridor = new Set<number>(seg);
    for (const i of seg) {
      const x = i % N, z = (i - x) / N;
      for (let d = 0; d < 4; d++) {
        const nx = x + DIRS[d][0], nz = z + DIRS[d][1];
        if (!inB(nx, nz)) continue;
        const j = idx(nx, nz);
        if (w.biome[j] !== Biome.Ocean && !inSeg.has(j)) corridor.add(j);
      }
    }

    // ramp sites: river tile P, direction d, tiles P+d*k for k=2..6 nearly level (within one step),
    // not corridor. They get flattened to the ramp profile; the legaliser blends the surroundings.
    const ramps: { tiles: number[]; h0: number }[] = [];
    let cooldown = 0;
    const startOff = Math.floor(rng() * 6);
    for (let q = startOff; q < seg.length; q++) {
      if (cooldown > 0) { cooldown--; continue; }
      const p = seg[q];
      const px = p % N, pz = (p - px) / N;
      for (let d = 0; d < 4; d++) {
        const tiles: number[] = [];
        let lo = 127, hi = -128, ok = true;
        for (let k = 1; k <= 6; k++) {
          const tx = px + DIRS[d][0] * k, tz = pz + DIRS[d][1] * k;
          if (!inB(tx, tz)) { ok = false; break; }
          const t = idx(tx, tz);
          if (k === 1) { if (!corridor.has(t) || inSeg.has(t)) { ok = false; break; } continue; }
          if (corridor.has(t) || river[t] || w.biome[t] === Biome.Ocean || w.water[t] >= 0 || (w.flags[t] & (Flag.Field | Flag.Terrace | Flag.Ramp))) { ok = false; break; }
          for (let cc = 0; cc < 4; cc++) { const h = w.corners[t * 4 + cc]; if (h < lo) lo = h; if (h > hi) hi = h; }
          if (hi - lo > 1) { ok = false; break; }
          tiles.push(t);
        }
        const h0 = lo;
        if (ok && tiles.length === 5) {
          ramps.push({ tiles, h0 });
          // remember direction by storing offsets on the tiles themselves below
          for (let k = 0; k < tiles.length; k++) {
            const t = tiles[k];
            const b = t * 4;
            if (k < 4) {
              // k index 0..3 -> ramp tile k+2 : inner offset -(4-k), outer -(3-k)
              const inner = -(4 - k), outer = -(3 - k);
              // corners on the side facing -d are "inner" (toward the river)
              const facingBack = backCorners(d);
              for (let cc = 0; cc < 4; cc++) c4(w, b, cc, h0 + (facingBack.includes(cc) ? inner : outer));
            } else {
              for (let cc = 0; cc < 4; cc++) c4(w, b, cc, h0); // landing at the top
            }
            w.flags[t] |= Flag.Ramp;
          }
          cooldown = 18;
          break;
        }
      }
    }
    if (ramps.length === 0) continue;

    for (const t of corridor) {
      const b = t * 4;
      for (let cc = 0; cc < 4; cc++) w.corners[b + cc] -= depth;
      w.flags[t] |= Flag.Corridor;
      if (!gorge) w.biome[t] = Biome.Canyon;
    }
    if (found) { const mid = seg[seg.length >> 1]; found.push([mid % N, Math.floor(mid / N)]); }
    if (gorge) { made++; continue; }
    // rim ring gets canyon colouring too
    for (const t of Array.from(corridor)) {
      const x = t % N, z = (t - x) / N;
      for (let d = 0; d < 4; d++) {
        const nx = x + DIRS[d][0], nz = z + DIRS[d][1];
        if (!inB(nx, nz)) continue;
        const j = idx(nx, nz);
        if (!corridor.has(j) && w.biome[j] === Biome.Desert) w.biome[j] = Biome.Canyon;
      }
    }
    made++;
  }
  return made;
}

function c4(w: World, b: number, cc: number, v: number): void { w.corners[b + cc] = v; }

/** Corner indices on the side of a tile that faces direction -d (i.e. toward where we came from). */
function backCorners(d: number): number[] {
  // moving +x: back side is the -x edge: c0, c3.  moving +z: back is -z edge: c0, c1.
  // moving -x: back is +x edge: c1, c2.  moving -z: back is +z edge: c3, c2.
  return [[0, 3], [0, 1], [1, 2], [3, 2]][d];
}
