/**
 * What each kind of cell carries — its towns, harbours, fields and works — and which towns a cell is
 * given, worked out from hashes alone so the macro layer (the railway's stations) and the generator
 * agree about it without either generating anything.
 */
import type { CellKind, TownKind } from './tiles';
import { REGIONS, type RegionSpec } from './regions';
import { cellKind, hasMega, regionAt } from './macro';
import { cell01 } from './rng';

export interface Shape {
  /** Share of the cell below the land threshold: higher leaves less land. Continents ignore it. */
  water: number;
  /** How hard the radial falloff pulls the coast in from the border. Continents have none. */
  falloff: number;
  towns: TownKind[];
  majorPorts: number;
  minorPorts: number;
  fields: number;
  cabins: number;
  beaches: number;
  /** Rock quarries, ski fields and airfields this size of cell supports. */
  quarries: number;
  pistes: number;
  airfields: number;
}

export const SHAPES: Record<Exclude<CellKind, 'sea'>, Shape> = {
  full: { water: 0.46, falloff: 1.35, towns: ['metro', 'city', 'suburb', 'rural'], majorPorts: 2, minorPorts: 3, fields: 4, cabins: 12, beaches: 3, quarries: 2, pistes: 1, airfields: 1 },
  small: { water: 0.72, falloff: 1.8, towns: ['suburb', 'rural'], majorPorts: 1, minorPorts: 2, fields: 2, cabins: 7, beaches: 2, quarries: 1, pistes: 1, airfields: 1 },
  islet: { water: 0.9, falloff: 2.7, towns: [], majorPorts: 0, minorPorts: 1, fields: 0, cabins: 3, beaches: 1, quarries: 0, pistes: 0, airfields: 0 },
  // an atoll: one village on its widest motu, a jetty, and the lagoon
  atoll: { water: 0, falloff: 0, towns: ['rural'], majorPorts: 0, minorPorts: 1, fields: 0, cabins: 3, beaches: 2, quarries: 0, pistes: 0, airfields: 0 },
  // a county has near twice a full island's land, so it carries more farms and cabins to keep the
  // country as lived-in; its towns come from the county rosters below
  continent: { water: 0, falloff: 0, towns: ['metro', 'city', 'suburb', 'rural', 'rural'], majorPorts: 2, minorPorts: 3, fields: 7, cabins: 18, beaches: 2, quarries: 2, pistes: 1, airfields: 1 },
};

/**
 * A cell's shape bent by its biome. A biome island takes the biome's water share, beaches, works
 * and roster; a county keeps a county's shape with its town kinds swapped for the biome's.
 */
export function regionShape(base: Shape, spec: RegionSpec | null, kind: CellKind): Shape {
  if (!spec) return base;
  const s = { ...base };
  const island = kind === 'full' || kind === 'small';
  const small = kind === 'small';
  if (island) {
    // relative to a full island's own numbers, so a small biome island stays small
    if (spec.water !== undefined) s.water = Math.min(0.9, Math.max(0.3, base.water + spec.water - SHAPES.full.water));
    if (spec.falloff !== undefined) s.falloff = base.falloff * spec.falloff / SHAPES.full.falloff;
    s.towns = small ? [spec.tier?.suburb ?? 'suburb', 'rural'] : [...spec.towns];
  } else if (kind === 'continent') {
    s.towns = base.towns.map((t) => spec.tier?.[t] ?? t);
  }
  if (kind === 'islet' || kind === 'atoll') return s;
  const scaled = (v: number | undefined, b: number) => (v === undefined ? b : small ? Math.min(v, Math.max(b, Math.ceil(v / 2))) : v);
  s.beaches = scaled(spec.beaches, base.beaches);
  s.fields = scaled(spec.farms, base.fields);
  s.quarries = scaled(spec.quarries, base.quarries);
  s.pistes = scaled(spec.pistes, base.pistes);
  s.airfields = scaled(spec.airfields, base.airfields);
  return s;
}

/** A megalopolis and the satellite suburbs pressed up against it. */
const MEGA_TOWNS: TownKind[] = ['mega', 'suburb', 'suburb', 'suburb', 'suburb', 'rural'];
/** Some counties are farming country rather than another town cell: a scatter of villages. */
const COUNTRYSIDE: TownKind[] = ['rural', 'rural', 'rural', 'rural', 'rural'];
const COUNTRYSIDE_CHANCE = 0.3;

/**
 * The ways a cell without a biome of its own is settled, picked per cell so neighbours differ: a big
 * city with its satellites, two rival towns, a city among villages, a string of market towns.
 */
const ROSTERS: Partial<Record<CellKind, TownKind[][]>> = {
  full: [
    ['metro', 'city', 'suburb', 'rural'],
    ['metro', 'suburb', 'suburb', 'rural'],
    ['city', 'city', 'suburb', 'rural'],
    ['city', 'suburb', 'rural', 'rural'],
    ['metro', 'city', 'rural', 'rural', 'rural'],
  ],
  small: [
    ['suburb', 'rural'],
    ['rural', 'rural'],
    ['city', 'rural'],
    ['suburb', 'rural', 'rural'],
  ],
  continent: [
    ['metro', 'city', 'suburb', 'rural', 'rural'],
    ['metro', 'suburb', 'suburb', 'rural', 'rural'],
    ['city', 'city', 'suburb', 'rural', 'rural'],
    ['city', 'suburb', 'rural', 'rural', 'rural', 'rural'],
  ],
};

/** The share of cells of each kind that get an airfield, where the biome says nothing about it. */
const AIRFIELD_CHANCE: Partial<Record<CellKind, number>> = { full: 0.5, small: 0.2, continent: 0.35 };

/**
 * How many airfields a cell gets: a roll per cell, so an airport is somewhere to fly to rather than a
 * fixture of every county. A biome that names its airfields keeps them, as do a megalopolis and home,
 * where the aircraft for sale start.
 */
export function airfieldsOf(seedHash: number, cx: number, cz: number, kind: CellKind, shape: Shape, spec: RegionSpec | null): number {
  if (!shape.airfields || spec?.airfields !== undefined) return shape.airfields;
  if ((cx === 0 && cz === 0) || hasMega(seedHash, cx, cz)) return shape.airfields;
  return cell01(seedHash, cx, cz, 61) < (AIRFIELD_CHANCE[kind] ?? 1) ? shape.airfields : 0;
}


/**
 * The towns a cell is planned with, and its shape: the megalopolis six, a farming county's three, or
 * its kind's own roster bent by its biome. The generator plans exactly this; whether every town finds
 * room is another matter, which is why a station asks for its town and falls back when it isn't there.
 */
export function rosterOf(seedHash: number, cx: number, cz: number): { kind: CellKind; shape: Shape; towns: TownKind[]; spec: RegionSpec | null } {
  const kind = cellKind(seedHash, cx, cz);
  if (kind === 'sea') return { kind, shape: SHAPES.islet, towns: [], spec: null };
  const r = regionAt(seedHash, cx, cz);
  const spec = r ? REGIONS[r] : null;
  const shape = regionShape(SHAPES[kind], spec, kind);
  const variants = ROSTERS[kind];
  const towns = hasMega(seedHash, cx, cz) ? MEGA_TOWNS
    : kind === 'continent' && !spec && cell01(seedHash, cx, cz, 31) < COUNTRYSIDE_CHANCE ? COUNTRYSIDE
      // home is always settled the classic way, so every world starts beside a proper city
      : !spec && variants ? variants[cx === 0 && cz === 0 ? 0 : Math.floor(cell01(seedHash, cx, cz, 32) * variants.length)]
        : shape.towns;
  return { kind, shape, towns, spec };
}
