import { Biome, DIRS, Flag, N, RailBit, REGION_KINDS, Surface, World, idx, inB, steepness } from './tiles';
import { hash2 } from './rng';
import { REGIONS } from './regions';
import { insideCurve } from './curves';
import { circuitFenceEdges } from './circuits';
import { ranchFences } from './ranches';

/**
 * The fences a car can knock down: timber or a hedgerow round the fields, drystone on the Moors,
 * snow fences in the Icefield.
 */
export type FenceKind = 'fence' | 'hedge' | 'drystoneWall' | 'snowFence';

/** Fences that slump where they are hit rather than toppling over. */
export const slumps = (kind: FenceKind): boolean => kind === 'drystoneWall' || kind === 'hedge';

/** One fence along an edge of tile (x, z): edge d, standing at (px, pz). */
export interface EdgeFence { kind: FenceKind; d: number; px: number; pz: number }

/** Railway tiles nothing grows or stands on: the line, its bridges' footprint, platforms, loops and the margin. */
export const RAIL_KEEP_CLEAR = RailBit.Track | RailBit.Deck | RailBit.Pad | RailBit.Loop | RailBit.Reserved;

/** Per biome (indexed by a tile's regionK, 0 for none): the chances fences are placed with. */
const FENCE_RULES = [null, ...REGION_KINDS.map((k) => {
  const c = REGIONS[k].clutter;
  // lanterns and snow fences are counted per tile but only stand beside a track, so they are
  // scaled up over the few tiles that qualify
  return { lantern: (c.stoneLantern ?? 0) * 12, snowFence: (c.snowFence ?? 0) * 12, drystone: c.drystoneWall !== undefined };
})];

/** Ground a biome may scatter its clutter on: open, dry, level enough and not in use. */
export function clutterGround(w: World, i: number): boolean {
  if (w.cleared[i] || w.road[i] || w.deckAxis[i] || w.rail[i] & RAIL_KEEP_CLEAR || w.townId[i] >= 0 || w.blocked[i] || w.portId[i] >= 0) return false;
  if (w.flags[i] & (Flag.Track | Flag.Field | Flag.Poi | Flag.Ramp)) return false;
  if (insideCurve(w, i)) return false; // a sweeping bend cuts across its corner
  const b = w.biome[i];
  if (b === Biome.Ocean || b === Biome.Town || b === Biome.Snow || b === Biome.Farm) return false;
  const surf = w.surface[i];
  if (surf === Surface.Salt || surf === Surface.Ice || surf === Surface.Lava || surf === Surface.Cave || surf === Surface.Basalt) return false;
  return steepness(w, i) < 2;
}

/**
 * Every fence that stands on tile (x, z), whether or not a car has knocked it down. The one rule
 * both the props that draw them and the cars that run into them read, so the two never disagree.
 */
export function fencesOn(w: World, x: number, z: number, emit: (f: EdgeFence) => void): void {
  const i = idx(x, z);
  const fl = w.flags[i];
  const rule = w.regionW[i] ? FENCE_RULES[w.regionK[i]] : null;

  // fences around field perimeters; on the Moors, drystone walls round the fields and along the tracks
  if (!(w.rail[i] & (RailBit.Track | RailBit.Pad | RailBit.Loop))) {
    const stone = w.regionW[i] > 127 && rule?.drystone === true;
    if (fl & Flag.Field) {
      // about half the ordinary country's fields are hedged instead of fenced, the whole field alike
      const kind = stone ? 'drystoneWall' : w.regionW[i] <= 127 && hash2(w.fieldId[i], 5, 23) < 0.5 ? 'hedge' : 'fence';
      for (let d = 0; d < 4; d++) {
        const nx = x + DIRS[d][0], nz = z + DIRS[d][1];
        if (!inB(nx, nz)) continue;
        const j = idx(nx, nz);
        if (w.flags[j] & Flag.Field) continue;
        if (fl & Flag.Track && w.flags[j] & Flag.Track) continue; // gate where the track passes
        if (w.roadEdges[i] & (1 << d)) continue; // and where a road does
        emit({ kind, d, px: x + 0.5 + DIRS[d][0] * 0.48, pz: z + 0.5 + DIRS[d][1] * 0.48 });
      }
    } else if (stone && fl & Flag.Track && !w.road[i]) {
      for (let d = 0; d < 4; d++) {
        const nx = x + DIRS[d][0], nz = z + DIRS[d][1];
        if (!inB(nx, nz)) continue;
        const j = idx(nx, nz);
        if (w.flags[j] & (Flag.Track | Flag.Field) || w.road[j] || w.water[j] >= 0 || w.townId[j] >= 0) continue;
        if (hash2(x * 4 + d, z, 19) < 0.2) continue;   // a gap for a gate or a fallen stretch
        emit({ kind: 'drystoneWall', d, px: x + 0.5 + DIRS[d][0] * 0.46, pz: z + 0.5 + DIRS[d][1] * 0.46 });
      }
    }
  }

  // round a race circuit's lot: a timber fence like a field's, knocked flat by a car that means it
  const ce = circuitFenceEdges(w);
  if (ce && ce[i]) {
    for (let d = 0; d < 4; d++) if (ce[i] & (1 << d)) emit({ kind: 'fence', d, px: x + 0.5 + DIRS[d][0] * 0.46, pz: z + 0.5 + DIRS[d][1] * 0.46 });
  }

  // round a ranch's pasture and its yard (world/ranches.ts): post and rail, open where a road crosses on a cattle grid
  const rf = ranchFences(w);
  if (rf && rf.fence[i]) {
    for (let d = 0; d < 4; d++) if (rf.fence[i] & (1 << d)) emit({ kind: 'fence', d, px: x + 0.5 + DIRS[d][0] * 0.48, pz: z + 0.5 + DIRS[d][1] * 0.48 });
  }

  // beside a track in the Icefield: a snow fence, on the first side the track runs past
  if (rule && rule.snowFence > 0 && w.water[i] < 0 && clutterGround(w, i)) {
    for (let d = 0; d < 4; d++) {
      const nx = x + DIRS[d][0], nz = z + DIRS[d][1];
      if (!inB(nx, nz) || !(w.flags[idx(nx, nz)] & Flag.Track)) continue;
      const r = hash2(x, z, 81), wgt = w.regionW[i] / 255;
      if (r >= rule.lantern * wgt && r < rule.snowFence * wgt) {
        emit({ kind: 'snowFence', d, px: x + 0.5 + DIRS[d][0] * 0.3, pz: z + 0.5 + DIRS[d][1] * 0.3 });
      }
      return;
    }
  }
}

/** Key for a fence in `World.knocked`: its tile and edge. */
export const fenceKey = (i: number, d: number): number => i * 4 + d;

/** The standing fence, if any, a car crosses going from tile a over edge d: on a's side of the edge or the far side. */
export function fenceAcross(w: World, a: number, d: number): (EdgeFence & { i: number }) | null {
  const x = a % N, z = (a - x) / N;
  const nx = x + DIRS[d][0], nz = z + DIRS[d][1];
  if (!inB(nx, nz)) return null;
  const hits: (EdgeFence & { i: number })[] = [];
  const b = idx(nx, nz), back = (d + 2) & 3;
  if (!w.knocked.has(fenceKey(a, d))) fencesOn(w, x, z, (f) => { if (f.d === d) hits.push({ ...f, i: a }); });
  if (!hits.length && !w.knocked.has(fenceKey(b, back))) fencesOn(w, nx, nz, (f) => { if (f.d === back) hits.push({ ...f, i: b }); });
  return hits[0] ?? null;
}
