/**
 * A customs post at each county border crossing: the booths stand beside the straight stub of road
 * both counties lay from the shared edge, three or four tiles in, so a driver crossing a county line
 * passes one on the way out and another on the way in. Nothing here levels the ground — the seam band
 * must stay exactly as the two counties each generated it — so a post only goes up where the roadside
 * is already flat.
 */
/** Does the road at tile i run on beyond a border stub: to a town, or through a good stretch of road? */
function joined(w: World, i: number): boolean {
  const seen = new Set<number>([i]);
  const queue = [i];
  for (let h = 0; h < queue.length; h++) {
    const t = queue[h];
    if (w.townId[t] >= 0 || seen.size > 60) return true;
    const x = t % N, z = (t - x) / N;
    for (const [dx, dz] of DIRS) {
      const nx = x + dx, nz = z + dz;
      if (!inB(nx, nz)) continue;
      const j = idx(nx, nz);
      if ((w.road[j] || w.deckAxis[j]) && !seen.has(j)) { seen.add(j); queue.push(j); }
    }
  }
  return false;
}

export function placeCustoms(w: World, rng: Rng, seedHash: number): void {
  for (let d = 0; d < 4; d++) {
    if (!landBorder(seedHash, w.cx, w.cz, d)) continue;
    const [dx, dz] = DIRS[d];
    for (const { at } of crossingAt(seedHash, w.cx, w.cz, d)) {
      const a = Math.max(4, Math.min(N - 5, at));
      // walk in from the border along the crossing's own straight stub
      for (let k = 3; k <= 5; k++) {
        const rx = (d === 0 ? N - 1 : d === 2 ? 0 : a) - dx * k;
        const rz = (d === 1 ? N - 1 : d === 3 ? 0 : a) - dz * k;
        if (!inB(rx, rz) || !w.road[idx(rx, rz)]) continue;
        // only where the crossing's road goes somewhere: a stub never joined to the county's roads gets no post
        if (!joined(w, idx(rx, rz))) break;
        // the post straddles the road: one booth each side, so the lot is three wide across it
        const across = d % 2 === 0 ? 1 : 0;
        const x = across ? rx - 1 : rx - 1, z = across ? rz - 1 : rz - 1;
        const wx = 3, wz = 3;
        let ok = true, lo2 = 127, hi2 = -128;
        for (let zz = z; zz < z + wz && ok; zz++) {
          for (let xx = x; xx < x + wx && ok; xx++) {
            if (!inB(xx, zz)) { ok = false; break; }
            const i = idx(xx, zz);
            if (w.townId[i] >= 0 || w.portId[i] >= 0 || w.rail[i] || w.blocked[i] || w.water[i] >= 0 || waterDepth(w, i) > 0) ok = false;
            if (w.flags[i] & (Flag.Poi | Flag.Corridor | Flag.Ramp)) ok = false;
            for (let q = 0; q < 4; q++) { const c = w.corners[i * 4 + q]; lo2 = Math.min(lo2, c); hi2 = Math.max(hi2, c); }
          }
        }
        if (!ok || hi2 !== lo2) continue;
        const b: Building = {
          kind: 'customsPost', x, z, w: wx, d: wz, facing: (d + 2) & 3, floors: 1,
          seed: Math.floor(rng() * 2 ** 31), solid: true, level: lo2, uid: w.allBuildings.length,
        };
        w.allBuildings.push(b);
        w.countryside.push(b);
        const top = lo2 * STEP + buildingHeight(b);
        const mask = solidMask(b);
        for (let zz = z; zz < z + wz; zz++) {
          for (let xx = x; xx < x + wx; xx++) {
            const i = idx(xx, zz);
            w.flags[i] |= Flag.Poi;
            // the booths block, the lane between them does not: the road runs straight through
            if (mask[(zz - z) * wx + xx - x] && !w.road[i]) { w.blocked[i] = 1; w.roof[i] = Math.max(w.roof[i], top); }
          }
        }
        break;
      }
    }
  }
}

export function placeRoadside(w: World, rng: Rng, band: number, lane?: (gate: number) => void): void {
  const lo = band + 4, hi = N - band - 4;
  const free = (x: number, z: number) => {
    if (x < lo || z < lo || x >= hi || z >= hi) return false;
    const i = idx(x, z);
    return w.townId[i] < 0 && w.portId[i] < 0 && !w.road[i] && !w.rail[i] && !w.blocked[i] && w.feature[i] === 0 && waterDepth(w, i) === 0 && w.water[i] < 0 &&
      !(w.flags[i] & (Flag.Field | Flag.Poi | Flag.Track | Flag.Ramp | Flag.Corridor));
  };
  const clearOfTowns = (x: number, z: number, r: number) => {
    for (const t of w.towns) {
      if (x > t.x0 - r && x < t.x0 + t.size + r && z > t.z0 - r && z < t.z0 + t.size + r) return false;
    }
    return true;
  };
  /** Every tile of the lot free, and flat enough to stand a building on. */
  const flatAt = (x: number, z: number, wx: number, wz: number, spread = 1) => {
    let lo2 = 127, hi2 = -128;
    for (let zz = z; zz < z + wz; zz++) for (let xx = x; xx < x + wx; xx++) {
      if (!inB(xx, zz) || !free(xx, zz)) return false;
      for (let q = 0; q < 4; q++) { const c = w.corners[idx(xx, zz) * 4 + q]; lo2 = Math.min(lo2, c); hi2 = Math.max(hi2, c); }
    }
    return hi2 - lo2 <= spread;
  };
  /** How much of a kind is already standing out here, so an island never fills up with one thing. */
  const placed = new Map<BuildingKind, { x: number; z: number }[]>();
  const apart = (kind: BuildingKind, x: number, z: number, r: number) =>
    !(placed.get(kind) ?? []).some((p) => Math.abs(p.x - x) < r && Math.abs(p.z - z) < r);

  const put = (kind: BuildingKind, x: number, z: number, wx: number, wz: number, facing: number): Building | null => {
    const solid = KIND_SPEC[kind]?.solid !== false;
    let sum = 0;
    for (let zz = z; zz < z + wz; zz++) for (let xx = x; xx < x + wx; xx++) for (let q = 0; q < 4; q++) sum += w.corners[idx(xx, zz) * 4 + q];
    const level = Math.round(sum / (wx * wz * 4));
    const b: Building = { kind, x, z, w: wx, d: wz, facing, floors: 1, seed: Math.floor(rng() * 2 ** 31), solid, level, uid: w.allBuildings.length };
    w.allBuildings.push(b);
    w.countryside.push(b);
    const top = level * STEP + buildingHeight(b);
    const mask = solid ? solidMask(b) : null;
    for (let zz = z; zz < z + wz; zz++) for (let xx = x; xx < x + wx; xx++) {
      const i = idx(xx, zz);
      w.flags[i] |= Flag.Poi;
      // the lot is levelled under it, as a town's is, so nothing stands on a slope
      for (let q = 0; q < 4; q++) w.corners[i * 4 + q] = level;
      if (mask && mask[(zz - z) * wx + xx - x]) { w.blocked[i] = 1; w.roof[i] = Math.max(w.roof[i], top); }
    }
    placed.set(kind, [...(placed.get(kind) ?? []), { x, z }]);
    return b;
  };

  /** The road tile nearest this lot, and which way the lot should face to look at it. */
  const roadBeside = (x: number, z: number, wx: number, wz: number): { gate: number; facing: number } | null => {
    // the four sides, in the DIRS order the facing uses: +x, +z, -x, -z
    const sides: [number, number, number][] = [
      [x + wx, z + Math.floor(wz / 2), 0], [x + Math.floor(wx / 2), z + wz, 1],
      [x - 1, z + Math.floor(wz / 2), 2], [x + Math.floor(wx / 2), z - 1, 3],
    ];
    for (const [rx, rz, facing] of sides) {
      if (!inB(rx, rz)) continue;
      const i = idx(rx, rz);
      if (w.road[i] >= RoadType.Paved) return { gate: i, facing };
    }
    return null;
  };

  /** Trees, water or height near a lot: what each row is really asking about. */
  const near = (x: number, z: number, r: number, test: (i: number) => boolean) => {
    let n = 0;
    for (let zz = z - r; zz <= z + r; zz++) for (let xx = x - r; xx <= x + r; xx++) {
      if (inB(xx, zz) && test(idx(xx, zz))) n++;
    }
    return n;
  };
  const forest = (i: number) => w.biome[i] === Biome.Forest;
  const wet = (i: number) => w.water[i] >= 0 || waterDepth(w, i) > 0;
  const farmed = (i: number) => !!(w.flags[i] & Flag.Field);
  const mean = (x: number, z: number) => {
    let sum = 0;
    for (let q = 0; q < 4; q++) sum += w.corners[idx(x, z) * 4 + q];
    return sum / 4;
  };

  /** How far the nearest town's ground is from a point, in tiles. */
  const townDist = (x: number, z: number) => {
    let best = 999;
    for (const t of w.towns) best = Math.min(best, Math.max(0, Math.abs(x - (t.x0 + t.size / 2)) - t.size / 2, Math.abs(z - (t.z0 + t.size / 2)) - t.size / 2));
    return best;
  };
  const paved = (i: number) => w.road[i] >= RoadType.Paved;

  for (const row of ROWS) {
    // a rare kind is in some counties and not in others: the roll is made whether or not it is used, so
    // one row's luck never moves another's
    const lucky = row.chance === undefined || rng() < row.chance;
    const want = lucky ? row.count[0] + Math.floor(rng() * (row.count[1] - row.count[0] + 1)) : 0;
    for (let n = 0; n < want; n++) {
      let best: { x: number; z: number; facing: number; gate: number; score: number } | null = null;
      for (let tries = 0; tries < 220; tries++) {
        const x = lo + Math.floor(rng() * (hi - lo - row.w)), z = lo + Math.floor(rng() * (hi - lo - row.d));
        if (!clearOfTowns(x, z, row.where === 'road' ? 7 : row.where === 'shore' ? 8 : 12) || !apart(row.kind, x, z, row.where === 'ridge' ? 8 : 24)) continue;
        if (!flatAt(x, z, row.w, row.d, row.where === 'ridge' || row.where === 'shore' ? 2 : 1)) continue;
        if (row.climate) {
          const t = w.temp[idx(x, z)];
          if (row.climate === 'cold' ? t > 0.36 : t < 0.5) continue;
        }
        const beside = roadBeside(x, z, row.w, row.d);
        let score = 0;
        if (row.where === 'any') {
          score = rng();
        } else if (row.where === 'edge') {
          // far from the towns and off the roads, and out toward the county's edge
          const rim = Math.min(x - lo, z - lo, hi - (x + row.w), hi - (z + row.d));
          if (townDist(x, z) < 16) continue;
          score = Math.min(50, townDist(x, z)) * 0.5 - rim * 0.8 - near(x, z, 5, paved) * 3 + rng() * 6;
        } else if (row.where === 'remote') {
          // as far from the towns as the county goes, and off the roads
          score = Math.min(60, townDist(x, z)) - near(x, z, 6, paved) * 2 + rng() * 6;
        } else if (row.where === 'road') {
          if (!beside) continue;
        } else if (row.where === 'forest') {
          const trees = near(x, z, 6, forest);
          if (trees < 24) continue;
          score = trees;
        } else if (row.where === 'shore') {
          // hard against the sea, so the platform's legs stand in open water
          if (w.coastDist[idx(x, z)] > 3) continue;
          score = -w.coastDist[idx(x, z)];
        } else if (row.where === 'water') {
          if (!near(x, z, 3, wet)) continue;
          score = near(x, z, 3, wet);
        } else if (row.where === 'field') {
          const fields = near(x, z, 6, farmed);
          if (fields < 20) continue;
          score = fields;
        } else {
          // the tops and the ridges: as high and as open as the island has
          const i = idx(x, z);
          if (steepness(w, i) > (row.where === 'ridge' ? 2 : 1)) continue;
          if (w.biome[i] === Biome.Ocean || w.biome[i] === Biome.Beach) continue;
          score = mean(x, z) * 4 - near(x, z, 5, forest) * 0.1;
        }
        // a flat lot with a road at the kerb is worth having whatever the row asked for
        if (beside) score += row.where === 'road' ? 0 : 2;
        if (!best || score > best.score) {
          best = { x, z, facing: beside?.facing ?? Math.floor(rng() * 4), gate: beside?.gate ?? -1, score };
          if (row.where === 'road' || row.where === 'water' || row.where === 'any') break;
        }
      }
      if (!best) break;
      const b = put(row.kind, best.x, best.z, row.w, row.d, best.facing);
      // no road at the kerb: run a lane out to the nearest one, the way a farmstead's gate does
      if (b && row.lane && best.gate < 0 && lane) {
        const gx = best.x + Math.floor(row.w / 2), gz = best.z + row.d;
        if (inB(gx, gz) && free(gx, gz)) lane(idx(gx, gz));
      }
    }
  }
}

/** The share of counties with a coast that get a naval dry dock (docs/storychains.html). */
const NAVAL_DOCK_CHANCE = 0.7;
/** The naval dock's lot: this many tiles across, and this many deep from its back to the sea. */
const DOCK_W = 6, DOCK_D = 9;

/**
 * A naval dry dock on the coast (docs/storychains.html): a walled basin a submarine is built in, its gate
 * on the sea and its yard at the back, where a lane runs in from the county's roads. It looks for a
 * stretch of flat dry shore whose seaward edge drops into water deep enough to float the boat out, and
 * faces it at the sea. On a random stream of its own, so adding it moved nothing else in any county.
 */
/** The rolls the two story structures' placers make first (from the macro layer alone): a county that loses its roll never has one. */
export const navalDockRolled = (seedHash: number, cx: number, cz: number): boolean => mulberry32(hashString(`${seedHash}|${cx},${cz}|navalDock`))() < NAVAL_DOCK_CHANCE;
export const spacePadRolled = (seedHash: number, cx: number, cz: number): boolean => mulberry32(hashString(`${seedHash}|${cx},${cz}|spacePad`))() < SPACEPORT_CHANCE;

export function placeNavalDock(w: World, rng: Rng, band: number, lane?: (gate: number) => void): Building | null {
  if (rng() >= NAVAL_DOCK_CHANCE) return null;
  const lo = band + 4, hi = N - band - 4;
  /** Land the dock can stand on: nobody's, no road or rail, a beach at most. */
  const dry = (x: number, z: number) => {
    if (x < lo || z < lo || x >= hi || z >= hi) return false;
    const i = idx(x, z);
    return w.townId[i] < 0 && w.portId[i] < 0 && !w.road[i] && !w.rail[i] && !w.blocked[i] && w.water[i] < 0 && waterDepth(w, i) === 0 &&
      (w.feature[i] === 0 || w.feature[i] === Feature.Beach) && !(w.flags[i] & (Flag.Field | Flag.Poi | Flag.Track | Flag.Ramp | Flag.Corridor));
  };
  /** Shallows the seaward half may be built out over: the dock is dug into the shore and walled. */
  const shoal = (x: number, z: number) => {
    if (x < lo || z < lo || x >= hi || z >= hi) return false;
    const i = idx(x, z);
    return w.townId[i] < 0 && w.portId[i] < 0 && !w.road[i] && !w.rail[i] && !w.blocked[i] && !w.deckAxis[i] && w.water[i] >= 0 && waterDepth(w, i) <= 2 &&
      !(w.flags[i] & (Flag.Poi | Flag.Track | Flag.Ramp | Flag.Corridor));
  };
  const water = (x: number, z: number) => inB(x, z) && w.water[idx(x, z)] >= 0;
  const deep = (x: number, z: number) => water(x, z) && waterDepth(w, idx(x, z)) >= 2;
  let best: { x: number; z: number; bw: number; bd: number; facing: number; score: number } | null = null;
  for (let tries = 0; tries < 1600; tries++) {
    const x = lo + Math.floor(rng() * (hi - lo)), z = lo + Math.floor(rng() * (hi - lo));
    if (w.coastDist[idx(x, z)] > 6) continue;
    for (let facing = 0; facing < 4; facing++) {
      // along x for facings 0 and 2, along z for 1 and 3: the lot is long toward the sea
      const alongX = facing % 2 === 0;
      const bw = alongX ? DOCK_D : DOCK_W, bd = alongX ? DOCK_W : DOCK_D;
      const [fx, fz] = DIRS[facing];
      let ok = true, lo2 = 127, hi2 = -128, land = 0;
      for (let zz = z; zz < z + bd && ok; zz++) for (let xx = x; xx < x + bw && ok; xx++) {
        // how far toward the sea this tile is, 0 at the back row to 1 at the gate
        const along = fx > 0 ? (xx - x) / (bw - 1) : fx < 0 ? (x + bw - 1 - xx) / (bw - 1) : fz > 0 ? (zz - z) / (bd - 1) : (z + bd - 1 - zz) / (bd - 1);
        if (dry(xx, zz)) {
          land++;
          for (let q = 0; q < 4; q++) { const c = w.corners[idx(xx, zz) * 4 + q]; lo2 = Math.min(lo2, c); hi2 = Math.max(hi2, c); }
        } else if (!(along >= 0.45 && shoal(xx, zz))) ok = false;
      }
      // most of it on land, the land flat enough to level, and no bigger a step than the quay could take
      if (!ok || land < bw * bd * 0.45 || hi2 - lo2 > 2 || lo2 < 2) continue;
      // past the gate: open water across it, deep enough a little way out to float a boat away
      const n = alongX ? bd : bw;
      let open = 0, far = 0;
      for (let k2 = 0; k2 < n; k2++) {
        for (let out = 1; out <= 3; out++) {
          const sx = fx > 0 ? x + bw - 1 + out : fx < 0 ? x - out : x + k2;
          const sz = fz > 0 ? z + bd - 1 + out : fz < 0 ? z - out : z + k2;
          if (out === 1 && water(sx, sz)) open++;
          if (out === 3 && deep(sx, sz)) far++;
        }
      }
      if (open < n - 1 || far < n / 2) continue;
      let clear = true;
      for (const t of w.towns) if (x + bw > t.x0 - 6 && x < t.x0 + t.size + 6 && z + bd > t.z0 - 6 && z < t.z0 + t.size + 6) { clear = false; break; }
      if (!clear) continue;
      const score = rng() + land / (bw * bd) + (hi2 === lo2 ? 0.5 : 0);
      if (!best || score > best.score) best = { x, z, bw, bd, facing, score };
    }
    if (best && tries > 500) break;
  }
  if (!best) return null;
  const { x, z, bw, bd, facing } = best;
  // levelled to its land: the shallows it is built out over are filled in under the quay
  let sum = 0, n2 = 0;
  for (let zz = z; zz < z + bd; zz++) for (let xx = x; xx < x + bw; xx++) {
    if (w.water[idx(xx, zz)] >= 0) continue;
    for (let q = 0; q < 4; q++) { sum += w.corners[idx(xx, zz) * 4 + q]; n2++; }
  }
  const level = Math.max(SEA + 1, Math.round(sum / Math.max(1, n2)));
  const b: Building = { kind: 'navalDock', x, z, w: bw, d: bd, facing, floors: 1, seed: Math.floor(rng() * 2 ** 31), solid: true, level, uid: w.allBuildings.length };
  w.allBuildings.push(b);
  w.countryside.push(b);
  const top = level * STEP + buildingHeight(b);
  const mask = solidMask(b);
  for (let zz = z; zz < z + bd; zz++) for (let xx = x; xx < x + bw; xx++) {
    const i = idx(xx, zz);
    w.flags[i] |= Flag.Poi;
    for (let q = 0; q < 4; q++) w.corners[i * 4 + q] = level;
    if (w.water[i] >= 0) { w.water[i] = -1; w.biome[i] = Biome.Beach; }
    w.feature[i] = 0;
    if (mask[(zz - z) * bw + xx - x]) { w.blocked[i] = 1; w.roof[i] = Math.max(w.roof[i], top); }
  }
  // the yard gate: the middle of the landward side, a step out; a lane runs from it to the nearest road
  const [dx, dz] = DIRS[facing];
  const cxm = x + Math.floor(bw / 2), czm = z + Math.floor(bd / 2);
  const gx = dx > 0 ? x - 1 : dx < 0 ? x + bw : cxm, gz = dz > 0 ? z - 1 : dz < 0 ? z + bd : czm;
  if (lane && inB(gx, gz) && dry(gx, gz)) lane(idx(gx, gz));
  return b;
}

/**
 * The share of counties rolled for a spaceport out in the open country, beside the rare wonder
 * (docs/storychains.html). 0.14: about one county in eight ends up with a launch pad, wonder included, once
 * the rolls that find no flat ground are counted (the user, 7 Oct 2026: at 0.5 it was one in two and a half;
 * `npm run padrate` measures it).
 */
const SPACEPORT_CHANCE = 0.14;
/** Its lot: square, a little smaller than the wonder's. */
const PAD_LOT = 12;

/**
 * A launch complex out on open, flat country well away from the towns (docs/storychains.html): the same
 * structure as the spaceport wonder, so the chain Stargazers has a pad to stack its rocket on in most
 * regions, not only the rare island that rolled the wonder. Its gate faces the nearest road, and a lane
 * runs to it. On a random stream of its own, so adding it moved nothing else in any county.
 */
export function placeSpacePad(w: World, rng: Rng, band: number, lane?: (gate: number) => void): Building | null {
  if (rng() >= SPACEPORT_CHANCE) return null;
  if (w.works.some((g) => g.kind === 'wonder' && g.buildings.some((b) => b.kind === 'launchPad'))) return null;
  const lo = band + 4, hi = N - band - 4 - PAD_LOT;
  const free = (i: number) => w.townId[i] < 0 && w.portId[i] < 0 && !w.road[i] && !w.rail[i] && !w.blocked[i] && w.feature[i] === 0 &&
    w.water[i] < 0 && waterDepth(w, i) === 0 && !(w.flags[i] & (Flag.Field | Flag.Poi | Flag.Track | Flag.Ramp | Flag.Corridor));
  let best: { x: number; z: number; score: number } | null = null;
  for (let tries = 0; tries < 900; tries++) {
    const x = lo + Math.floor(rng() * (hi - lo)), z = lo + Math.floor(rng() * (hi - lo));
    let ok = true, lo2 = 127, hi2 = -128;
    for (let zz = z; zz < z + PAD_LOT && ok; zz++) for (let xx = x; xx < x + PAD_LOT && ok; xx++) {
      const i = idx(xx, zz);
      if (!free(i)) { ok = false; break; }
      for (let q = 0; q < 4; q++) { const c = w.corners[i * 4 + q]; lo2 = Math.min(lo2, c); hi2 = Math.max(hi2, c); }
    }
    if (!ok || hi2 - lo2 > 2 || lo2 <= SEA) continue;
    let clear = true;
    for (const t of w.towns) if (x + PAD_LOT > t.x0 - 10 && x < t.x0 + t.size + 10 && z + PAD_LOT > t.z0 - 10 && z < t.z0 + t.size + 10) { clear = false; break; }
    if (!clear) continue;
    const score = rng() + (hi2 === lo2 ? 1 : 0);
    if (!best || score > best.score) best = { x, z, score };
    if (best && tries > 300) break;
  }
  if (!best) return null;
  const { x, z } = best;
  // the gate on the side nearest a road, or the +z side when none is near
  let facing = 1, nearest = Infinity;
  for (let d = 0; d < 4; d++) {
    const [dx, dz] = DIRS[d];
    const mx = x + PAD_LOT / 2 + dx * (PAD_LOT / 2 + 1), mz = z + PAD_LOT / 2 + dz * (PAD_LOT / 2 + 1);
    for (let r2 = 0; r2 < 40; r2++) {
      const tx = Math.floor(mx + dx * r2), tz = Math.floor(mz + dz * r2);
      if (!inB(tx, tz)) break;
      if (w.road[idx(tx, tz)] >= RoadType.Paved) { if (r2 < nearest) { nearest = r2; facing = d; } break; }
    }
  }
  let sum = 0;
  for (let zz = z; zz < z + PAD_LOT; zz++) for (let xx = x; xx < x + PAD_LOT; xx++) for (let q = 0; q < 4; q++) sum += w.corners[idx(xx, zz) * 4 + q];
  const level = Math.round(sum / (PAD_LOT * PAD_LOT * 4));
  const b: Building = { kind: 'launchPad', x, z, w: PAD_LOT, d: PAD_LOT, facing, floors: 1, seed: Math.floor(rng() * 2 ** 31), solid: true, level, uid: w.allBuildings.length };
  w.allBuildings.push(b);
  w.countryside.push(b);
  const top = level * STEP + buildingHeight(b);
  const mask = solidMask(b);
  for (let zz = z; zz < z + PAD_LOT; zz++) for (let xx = x; xx < x + PAD_LOT; xx++) {
    const i = idx(xx, zz);
    w.flags[i] |= Flag.Poi;
    for (let q = 0; q < 4; q++) w.corners[i * 4 + q] = level;
    if (mask[(zz - z) * PAD_LOT + xx - x]) { w.blocked[i] = 1; w.roof[i] = Math.max(w.roof[i], top); }
  }
  const [dx, dz] = DIRS[facing];
  const gx = x + Math.floor(PAD_LOT / 2) + dx * (PAD_LOT / 2 + (dx > 0 ? 0 : 1)), gz = z + Math.floor(PAD_LOT / 2) + dz * (PAD_LOT / 2 + (dz > 0 ? 0 : 1));
  if (lane && inB(gx, gz) && free(idx(gx, gz))) lane(idx(gx, gz));
  return b;
}
