import { N, STEP, Biome, DIRS, EDGE_MINE, Feature, Flag, World, idx, inB, isFlat, minCorner, maxCorner, type Building, type BuildingKind, type Town, type Work } from './tiles';
import type { Rng } from './rng';
import { buildingHeight } from './towns';
import { solidMask } from './footprint';
import { KIND_SPEC } from './townKinds';
import { LIFT, standTowers } from './skiFields';

/**
 * What a canyon's rim village does with the canyon (docs/geology.html, GEN 53 behind NEXT_WORLD), placed after
 * every other building on a stream of its own so nothing else in the county moves:
 *
 * - a mule trail: a gravel track zigzagging from the rim down the talus to the platform bench, cut into the
 *   cliffs at two steps a tile on its straights (so only a vehicle that climbs steep ground, maxGrade 2, gets
 *   back up it) and level at its switchbacks; found by a search over tile, height and heading that drops only on
 *   straights, so it zigzags exactly as much as the drop asks;
 * - a canyon ranch on the platform at the trail's foot: a ranch house and stables, hard to reach, so whatever
 *   goes to or from it pays a premium (Building.remote, game/cargo.ts);
 * - a cable car from the rim village across the canyon to the far rim: two stations and a gondola rope over
 *   the gap (world/skiFields.ts standTowers), its cabins run by the ski lifts' machinery (render/skiLifts.ts).
 */

/** Steps a trail tile drops on a straight: steep ground, which only maxGrade 2 climbs. */
export const TRAIL_DROP = 2;
/** The platform: level ground in the canyon at least this many steps under the rim. */
const DEPTH_MIN = 8;
/** How far from the rim village the trail may wander, and the most states its search may open. */
const REACH = 64, OPEN_MAX = 400_000;

interface CanyonStats { trails: number; trailTiles: number; ranches: number; cableCars: number; why: string[] }
/** Why a rim village got no trail, latest last, and the trails cut (tiles, trailhead to platform), for the gate (`npm run geology`). */
export const CANYON_WHY: string[] = [];
export const TRAILS: { seed: string; cx: number; cz: number; tiles: number[] }[] = [];

/** The canyon's works round each rim village in the county. `canyon` is the generator's mask of canyon-side tiles. */
export function placeCanyonWorks(w: World, rng: Rng, band: number, canyon: Uint8Array): CanyonStats {
  const stats: CanyonStats = { trails: 0, trailTiles: 0, ranches: 0, cableCars: 0, why: [] };
  const rims = w.towns.filter((t) => t.perch === 'rim');
  for (const t of rims.slice(0, 2)) {
    const foot = muleTrail(w, t, band, canyon, stats);
    if (foot !== null) {
      if (canyonRanch(w, rng, foot, band, canyon)) stats.ranches++;
      else stats.why.push(`${t.name}: no level ground for a ranch at the trail's foot`);
    }
    const cc = cableCar(w, rng, t, band, canyon);
    if (cc === true) stats.cableCars++;
    else stats.why.push(`${t.name}: no cable car (${cc})`);
  }
  CANYON_WHY.push(...stats.why);
  if (CANYON_WHY.length > 100) CANYON_WHY.splice(0, CANYON_WHY.length - 100);
  return stats;
}

// ---- the mule trail ----------------------------------------------------------------------------

/** May a trail be cut through this tile? Dry, not built on, no road, rail, landmark or town. */
function cuttable(w: World, i: number): boolean {
  return w.water[i] < 0 && !w.road[i] && !w.rail[i] && !w.blocked[i] && w.townId[i] < 0 && w.portId[i] < 0 && w.feature[i] === Feature.None
    && !(w.flags[i] & (Flag.Poi | Flag.Track | Flag.Ramp | Flag.River | Flag.Stream)) && w.biome[i] !== Biome.Ocean;
}

/** A trail from the rim at village t down to the platform; returns the platform tile it ends at, or null. */
function muleTrail(w: World, t: Town, band: number, canyon: Uint8Array, stats: CanyonStats): number | null {
  const top = t.level, cx = t.x0 + t.size / 2, cz = t.z0 + t.size / 2;
  const lo = band + 4, hi = N - band - 5;
  const inWin = (x: number, z: number) => x >= lo && z >= lo && x <= hi && z <= hi && Math.abs(x - cx) <= REACH && Math.abs(z - cz) <= REACH;
  // the platform: level, dry canyon ground well under the rim
  const plat = (i: number) => canyon[i] && isFlat(w, i) && w.water[i] < 0 && !w.blocked[i] && !w.road[i] && minCorner(w, i) <= top - DEPTH_MIN;
  // the trailhead: rim ground at the village's level, outside the square, beside the drop
  const starts: number[] = [];
  for (let z = Math.floor(cz - REACH); z <= cz + REACH; z++) for (let x = Math.floor(cx - REACH); x <= cx + REACH; x++) {
    if (!inWin(x, z)) continue;
    const i = idx(x, z);
    if (canyon[i] || !isFlat(w, i) || Math.abs(minCorner(w, i) - top) > 2 || !cuttable(w, i)) continue;
    if (x >= t.x0 - 1 && x <= t.x0 + t.size && z >= t.z0 - 1 && z <= t.z0 + t.size) continue;
    let edge = false;
    for (const [dx, dz] of DIRS) if (inB(x + dx, z + dz) && canyon[idx(x + dx, z + dz)]) edge = true;
    if (edge) starts.push(i);
  }
  if (!starts.length) { stats.why.push(`${t.name}: no trailhead on the rim`); return null; }
  starts.sort((a, b) => Math.hypot((a % N) - cx, Math.floor(a / N) - cz) - Math.hypot((b % N) - cx, Math.floor(b / N) - cz));

  // the search: a state is a tile, the height at its exit edge, the way it was entered, and whether it ramps
  type S = { i: number; h: number; d: number; ramp: boolean; g: number; f: number; prev: S | null };
  const key = (i: number, h: number, d: number, ramp: boolean) => ((i * 64 + (h + 16)) * 5 + d) * 2 + (ramp ? 1 : 0);
  const best = new Map<number, number>();
  const heap: S[] = [];
  const push = (s: S) => {
    heap.push(s);
    let k = heap.length - 1;
    while (k > 0) { const p = (k - 1) >> 1; if (heap[p].f <= heap[k].f) break; [heap[p], heap[k]] = [heap[k], heap[p]]; k = p; }
  };
  const pop = (): S => {
    const top0 = heap[0], last = heap.pop()!;
    if (heap.length) {
      heap[0] = last;
      let k = 0;
      for (;;) {
        const l = 2 * k + 1, r = l + 1;
        let m = k;
        if (l < heap.length && heap[l].f < heap[m].f) m = l;
        if (r < heap.length && heap[r].f < heap[m].f) m = r;
        if (m === k) break;
        [heap[m], heap[k]] = [heap[k], heap[m]];
        k = m;
      }
    }
    return top0;
  };
  // cutting or filling more than a little costs, so the trail keeps near the ground it runs over
  const fit = (i: number, hin: number, hout: number) => {
    const g = (minCorner(w, i) + maxCorner(w, i)) / 2, m = (hin + hout) / 2;
    return 1 + Math.min(6, Math.abs(g - m) * 0.25);
  };
  for (const s of starts.slice(0, 6)) push({ i: s, h: minCorner(w, s), d: 4, ramp: false, g: 0, f: 0, prev: null });
  let goal: S | null = null, opened = 0;
  while (heap.length && opened < OPEN_MAX) {
    const s = pop();
    const k0 = key(s.i, s.h, s.d, s.ramp);
    if ((best.get(k0) ?? Infinity) < s.g) continue;
    opened++;
    // arrived: on the platform at its own level
    if (s.prev && plat(s.i) && !s.ramp && s.h === minCorner(w, s.i)) { goal = s; break; }
    const x = s.i % N, z = (s.i - x) / N;
    for (let nd = 0; nd < 4; nd++) {
      // a ramp hands over only through its exit edge: straight on
      if (s.ramp && nd !== s.d) continue;
      if (s.d < 4 && nd === (s.d + 2) % 4) continue;
      const nx = x + DIRS[nd][0], nz = z + DIRS[nd][1];
      if (!inWin(nx, nz)) continue;
      const j = idx(nx, nz);
      const goalTile = plat(j);
      if (!goalTile && !cuttable(w, j)) continue;
      for (const ramp of goalTile ? [false] : [false, true]) {
        const h = ramp ? s.h - TRAIL_DROP : s.h;
        if (goalTile && h !== minCorner(w, j)) continue;
        // a level stretch only where it turns or lands: a straight run keeps dropping
        const turn = s.d < 4 && nd !== s.d;
        const g = s.g + (goalTile ? 0 : fit(j, s.h, h)) + (ramp ? 0 : turn ? 1.6 : 1.2);
        const k = key(j, h, nd, ramp);
        if ((best.get(k) ?? Infinity) <= g) continue;
        best.set(k, g);
        // at least one tile for every two steps still to go down
        push({ i: j, h, d: nd, ramp, g, f: g + Math.max(0, (h - (top - DEPTH_MIN)) / TRAIL_DROP), prev: s });
      }
    }
  }
  if (!goal) { stats.why.push(`${t.name}: no trail down (${opened} states)`); return null; }
  // the path, trailhead first; the trailhead and the platform tile keep their own ground
  const path: S[] = [];
  for (let s: S | null = goal; s; s = s.prev) path.unshift(s);
  const tiles = path.slice(1, -1);
  if (new Set(tiles.map((s) => s.i)).size !== tiles.length) { stats.why.push(`${t.name}: the trail crossed itself`); return null; }
  for (let k = 0; k < tiles.length; k++) {
    const s = tiles[k], hin = path[k].h, b = s.i * 4;
    if (s.ramp) {
      for (let c = 0; c < 4; c++) w.corners[b + c] = hin;
      for (const c of EDGE_MINE[s.d]) w.corners[b + c] = s.h;
    } else for (let c = 0; c < 4; c++) w.corners[b + c] = s.h;
    w.flags[s.i] |= Flag.Track;
    w.cleared[s.i] = 1;
  }
  stats.trails++;
  stats.trailTiles += tiles.length;
  TRAILS.push({ seed: w.seed, cx: w.cx, cz: w.cz, tiles: path.map((s) => s.i) });
  if (TRAILS.length > 50) TRAILS.shift();
  return goal.i;
}

// ---- the canyon ranch ---------------------------------------------------------------------------

/** A building on level ground: the ranch's, hard to reach, out in the country; a station, its cable car's. Null where the ground won't take it. */
function put(w: World, rng: Rng, kind: BuildingKind, x: number, z: number, bw: number, bd: number, facing: number, work?: Work): Building | null {
  let sum = 0, lo = 127, hi = -128;
  for (let zz = z; zz < z + bd; zz++) for (let xx = x; xx < x + bw; xx++) {
    if (!inB(xx, zz)) return null;
    const i = idx(xx, zz);
    if (w.water[i] >= 0 || w.road[i] || w.blocked[i] || (w.flags[i] & (Flag.Track | Flag.Poi))) return null;
    for (let q = 0; q < 4; q++) { const c = w.corners[i * 4 + q]; sum += c; lo = Math.min(lo, c); hi = Math.max(hi, c); }
  }
  if (hi - lo > 1) return null;
  const solid = KIND_SPEC[kind]?.solid !== false;
  const b: Building = { kind, x, z, w: bw, d: bd, facing, floors: work ? 2 : 1, seed: Math.floor(rng() * 2 ** 31), solid, level: Math.round(sum / (bw * bd * 4)), uid: w.allBuildings.length };
  if (!work) b.remote = true;
  w.allBuildings.push(b);
  if (work) work.buildings.push(b); else w.countryside.push(b);
  const top = b.level * STEP + buildingHeight(b);
  const sm = solid ? solidMask(b) : null;
  for (let zz = z; zz < z + bd; zz++) for (let xx = x; xx < x + bw; xx++) {
    const i = idx(xx, zz);
    w.flags[i] |= Flag.Poi;
    if (sm && sm[(zz - z) * bw + xx - x]) { w.blocked[i] = 1; w.roof[i] = Math.max(w.roof[i], top); }
  }
  return b;
}

/** A ranch house and its stables on the platform the trail comes down to, as near its foot as there is room. */
function canyonRanch(w: World, rng: Rng, foot: number, band: number, canyon: Uint8Array): boolean {
  const lv = minCorner(w, foot);
  // the platform the trail lands on: level canyon ground at the foot's height, joined to it
  const shelf = new Set<number>([foot]);
  const queue = [foot];
  const level = (i: number) => canyon[i] && isFlat(w, i) && minCorner(w, i) === lv && w.water[i] < 0;
  for (let q = 0; q < queue.length && shelf.size < 600; q++) {
    const i = queue[q], x = i % N, z = (i - x) / N;
    for (const [dx, dz] of DIRS) {
      if (!inB(x + dx, z + dz)) continue;
      const j = idx(x + dx, z + dz);
      if (!shelf.has(j) && level(j)) { shelf.add(j); queue.push(j); }
    }
  }
  const on = (x0: number, z0: number, n: number) => {
    for (let zz = z0; zz < z0 + 2; zz++) for (let xx = x0; xx < x0 + n; xx++) if (!inB(xx, zz) || !shelf.has(idx(xx, zz))) return false;
    return true;
  };
  const fx = foot % N, fz = (foot - fx) / N;
  // nearest the foot first, leaving the tile the trail lands on and its neighbours clear
  const spots = [...shelf].map((i) => ({ x: i % N, z: Math.floor(i / N) })).filter((p) => Math.max(Math.abs(p.x - fx), Math.abs(p.z - fz)) >= 2
    && p.x >= band + 2 && p.z >= band + 2 && p.x <= N - band - 7 && p.z <= N - band - 4)
    .sort((a, b) => Math.hypot(a.x - fx, a.z - fz) - Math.hypot(b.x - fx, b.z - fz));
  for (const { x, z } of spots) {
    if (!on(x, z, 2)) continue;
    const facing = fz < z ? 3 : 1;
    if (!put(w, rng, 'ranchHouse', x, z, 2, 2, facing)) continue;
    if (on(x + 3, z, 2)) put(w, rng, 'stables', x + 3, z, 2, 2, facing);
    return true;
  }
  return false;
}

// ---- the cable car ------------------------------------------------------------------------------

/** A 3×3 station pad centred on (x, z): free, dry, and within a step of level. Its mean level, or null. */
function padAt(w: World, x: number, z: number, band: number): number | null {
  if (x < band + 3 || z < band + 3 || x > N - band - 4 || z > N - band - 4) return null;
  let lo = 127, hi = -128;
  for (let dz = -1; dz <= 1; dz++) for (let dx = -1; dx <= 1; dx++) {
    const i = idx(x + dx, z + dz);
    if (w.water[i] >= 0 || w.road[i] || w.rail[i] || w.blocked[i] || w.townId[i] >= 0 || (w.flags[i] & (Flag.Poi | Flag.Track))) return null;
    lo = Math.min(lo, minCorner(w, i)); hi = Math.max(hi, maxCorner(w, i));
  }
  return hi - lo <= 1 ? hi : null;
}

/** A gondola from beside the rim village straight across the canyon to the far rim: true, or why not. */
function cableCar(w: World, rng: Rng, t: Town, band: number, canyon: Uint8Array): true | string {
  const cx = t.x0 + t.size / 2, cz = t.z0 + t.size / 2, top = t.level;
  // which way the canyon lies: the middle of its tiles near the village
  let sx = 0, sz = 0, n = 0;
  for (let z = Math.floor(cz - 60); z <= cz + 60; z += 2) for (let x = Math.floor(cx - 60); x <= cx + 60; x += 2) {
    if (inB(x, z) && canyon[idx(x, z)]) { sx += x; sz += z; n++; }
  }
  if (n < 20) return 'no canyon near';
  const mx = sx / n, mz = sz / n;
  let why = 'no pad on the near rim';
  // the near station: a free pad at the rim's level, outside the square and within a few tiles of the drop
  const nears: { x: number; z: number; lv: number; d: number }[] = [];
  for (let z = Math.floor(cz - t.size / 2 - 20); z <= cz + t.size / 2 + 20; z += 2) for (let x = Math.floor(cx - t.size / 2 - 20); x <= cx + t.size / 2 + 20; x += 2) {
    if (!inB(x, z) || (x >= t.x0 - 2 && x <= t.x0 + t.size + 1 && z >= t.z0 - 2 && z <= t.z0 + t.size + 1)) continue;
    let edge = Infinity;
    for (let dz = -10; dz <= 10; dz += 2) for (let dx = -10; dx <= 10; dx += 2) if (inB(x + dx, z + dz) && canyon[idx(x + dx, z + dz)]) edge = Math.min(edge, Math.hypot(dx, dz));
    if (edge > 10 || canyon[idx(x, z)]) continue;
    const lv = padAt(w, x, z, band);
    if (lv !== null && Math.abs(lv - top) <= 2) nears.push({ x, z, lv, d: edge + Math.hypot(x - cx, z - cz) * 0.2 });
  }
  nears.sort((a, b) => a.d - b.d);
  for (const near of nears.slice(0, 6)) for (const turn of [0, 0.25, -0.25, 0.5, -0.5]) {
    const a = Math.atan2(mz - near.z, mx - near.x) + turn, ux = Math.cos(a), uz = Math.sin(a);
    // over the canyon, to level ground on the far side within a few steps of the rim
    let crossed = false, far: { x: number; z: number; lv: number } | null = null;
    for (let s = 3; s < 200 && !far; s++) {
      const x = Math.round(near.x + ux * s), z = Math.round(near.z + uz * s);
      if (!inB(x, z)) break;
      const i = idx(x, z);
      if (canyon[i]) { crossed = true; continue; }
      if (!crossed || s < 24) continue;
      const lv = padAt(w, x, z, band);
      if (lv !== null && Math.abs(lv - top) <= 8) far = { x, z, lv };
    }
    if (!far) { why = 'no pad on the far rim'; continue; }
    const spec = LIFT.gondola;
    const x0 = near.x + 0.5, z0 = near.z + 0.5, x1 = far.x + 0.5, z1 = far.z + 0.5;
    const y0 = near.lv * STEP + spec.rope, y1 = far.lv * STEP + spec.rope;
    const canStand = (x: number, z: number) => {
      const tx = Math.floor(x), tz = Math.floor(z);
      if (!inB(tx, tz)) return false;
      const i = idx(tx, tz);
      return w.water[i] < 0 && !w.road[i] && !w.rail[i] && !w.blocked[i] && w.townId[i] < 0 && !(w.flags[i] & (Flag.Poi | Flag.Track));
    };
    const towers = standTowers(w, 'gondola', x0, z0, y0, x1, z1, y1, canStand);
    if (!towers) { why = 'no towers would carry it'; continue; }
    // the stations' pads levelled, and the stations put up facing each other
    for (const p of [near, far]) for (let dz = -1; dz <= 1; dz++) for (let dx = -1; dx <= 1; dx++) {
      const b = idx(p.x + dx, p.z + dz) * 4;
      for (let c = 0; c < 4; c++) w.corners[b + c] = p.lv;
    }
    const face = (dx: number, dz: number) => (Math.abs(dx) > Math.abs(dz) ? (dx > 0 ? 0 : 2) : (dz > 0 ? 1 : 3));
    const g: Work = {
      kind: 'cableCar', name: `${t.name.replace(/ Rim$/, '')} Cable Car`, x: near.x, z: near.z, level: near.lv,
      facing: face(ux, uz), major: false, buildings: [], cable: [], gate: idx(near.x, near.z),
      lifts: [{ kind: 'gondola', x0, z0, y0: +y0.toFixed(3), x1, z1, y1: +y1.toFixed(3), towers, runs: [] }],
    };
    for (const [p, f] of [[near, face(ux, uz)], [far, face(-ux, -uz)]] as const) put(w, rng, 'liftStation', p.x - 1, p.z - 1, 3, 3, f, g);
    if (g.buildings.length < 2) return 'a station would not stand';
    for (const tw of towers) w.flags[idx(Math.floor(x0 + ((x1 - x0) / Math.hypot(x1 - x0, z1 - z0)) * tw.s), Math.floor(z0 + ((z1 - z0) / Math.hypot(x1 - x0, z1 - z0)) * tw.s))] |= Flag.Poi;
    w.works.push(g);
    return true;
  }
  return why;
}
