/**
 * The Adriatic's towns (the adriatic style) take Croatian names from the coast and its islands, picked by a hash
 * of the name the town was first given, so naming one draws nothing from the town's random stream.
 */
const ADRIATIC_NAMES = [
  'Rovinj', 'Vrsar', 'Lovran', 'Kastav', 'Motovun', 'Grožnjan', 'Bale', 'Fažana', 'Labin', 'Omiš', 'Cavtat', 'Ston',
  'Komiža', 'Supetar', 'Bol', 'Vis', 'Lastovo', 'Primošten', 'Trogir', 'Makarska', 'Volosko', 'Novigrad', 'Umag', 'Poreč',
  'Krk', 'Rab', 'Pag', 'Hvar', 'Korčula', 'Opatija', 'Mošćenice', 'Brela', 'Baška', 'Lopud', 'Šipan', 'Murter', 'Tisno',
  'Skradin', 'Zlarin', 'Pučišća', 'Milna', 'Jelsa', 'Stari Grad', 'Vela Luka', 'Orebić', 'Lumbarda', 'Sveti Lovreč',
  'Mali Lošinj', 'Veli Lošinj', 'Cres', 'Senj', 'Biograd', 'Sutivan', 'Postira', 'Hvarska Luka', 'Piran', 'Izola', 'Kotor',
];
function adriaticName(first: string, id: number, taken: Set<string>): string {
  let h = hashString(`${first}#${id}`) >>> 0;
  for (let k = 0; k < ADRIATIC_NAMES.length; k++, h++) {
    const name = ADRIATIC_NAMES[h % ADRIATIC_NAMES.length];
    if (!taken.has(name)) { taken.add(name); return name; }
  }
  return ADRIATIC_NAMES[h % ADRIATIC_NAMES.length];
}

/** A town in a biome takes its names from the biome's own tables. */
function regionTownName(spec: RegionSpec, kind: TownKind, rng: Rng, taken: Set<string>): string {
  const [a, b] = spec.names;
  let name = '';
  // the tables are short, so draw again rather than name two towns on one island alike
  for (let k = 0; k < 6 && (!name || taken.has(name)); k++) name = a[Math.floor(rng() * a.length)] + b[Math.floor(rng() * b.length)];
  taken.add(name);
  return kind === 'metro' || kind === 'mega' ? `${name} City` : name;
}

function townName(kind: TownKind, rng: Rng): string {
  const [a, b] = NAMES[kind];
  const head = a[Math.floor(rng() * a.length)], tail = b[Math.floor(rng() * b.length)];
  // Foxwood takes no second 'wood'
  const name = head.toLowerCase().endsWith(tail.trim().toLowerCase()) ? head : head + tail;
  return kind === 'metro' ? `${name} City` : name;
}

