/**
 * The kind's taste, leaned by the ground round the town (its square and a margin): canal towns and Edo
 * ports on the coast, frontier towns out on dry country and open plains, Budapest astride a river.
 */
function siteTaste(p: TownPlan, w: World): Partial<Record<Arch, number>> {
  const taste = { ...STYLE_TASTE[p.kind] };
  const m = 8, x0 = Math.max(0, p.x0 - m), z0 = Math.max(0, p.z0 - m), x1 = Math.min(N, p.x0 + p.size + m), z1 = Math.min(N, p.z0 + p.size + m);
  let n = 0, sea = 0, dry = 0, open = 0, river = 0, forest = 0, warm = 0, cold = 0, hill = 0;
  for (let z = z0; z < z1; z++) {
    for (let x = x0; x < x1; x++) {
      const i = idx(x, z), b = w.biome[i];
      n++;
      if (b === Biome.Ocean || b === Biome.Beach || b === Biome.SeaCliff || b === Biome.Lagoon) sea++;
      else if (b === Biome.Desert || b === Biome.Canyon || b === Biome.Salt) dry++;
      else if (b === Biome.Plains || b === Biome.Farm) open++;
      if (b === Biome.Forest || b === Biome.Mangrove || b === Biome.Marsh) forest++;
      if (b === Biome.Lagoon || b === Biome.Mangrove || b === Biome.Beach) warm++;
      if (b === Biome.Snow || b === Biome.Ice) cold++;
      if (b === Biome.Hills || b === Biome.Mountain) hill++;
      if (w.flags[i] & Flag.River) river++;
    }
  }
  if (!n) return taste;
  const add = (a: Arch, v: number) => { taste[a] = (taste[a] ?? 0) + v; };
  const country = p.kind === 'rural' || p.kind === 'suburb';
  if (sea / n > 0.06) {
    add('dutch', 1.6);
    add('japanese', p.kind === 'rural' ? 0.8 : 1.6);
    // and Tokyo round a bay, but only once it is a big city: a village by the sea stays Edo; New York too,
    // round its harbour
    if (p.kind === 'metro' || p.kind === 'mega') { add('tokyo', 1.5); add('newyork', 1.5); }
    // and Osaka on its bay, the merchants' city of canals
    if (p.kind !== 'rural' && p.kind !== 'suburb') add('osaka', p.kind === 'city' ? 0.5 : 1.0);
  }
  if (river >= 6 && (p.kind === 'metro' || p.kind === 'mega')) add('osaka', 0.5);
  if (dry / n > 0.18) {
    add('western', country ? 7 : 2);
    // the same dry country suits a bazaar town, and it keeps its tiles in the biggest cities too
    add('ottoman', country ? 3 : 2.5);
  } else if (open / n > 0.55 && country) add('western', 1.2);
  // hot wet forest is where the pyramids stand; snow and cold forest is onion-dome country
  if (forest / n > 0.25) add('maya', (country ? 3 : 2) * (warm / n > 0.1 ? 1.6 : 1));
  if (cold / n > 0.2) add('russian', country ? 4.5 : 3.5);
  // the classical world round a warm sea, China along the big rivers and the plains, and Southeast Asia
  // where the water is warm and the forest comes down to it
  if (sea / n > 0.05 || dry / n > 0.08) add('roman', country ? 3 : 2.5);
  if (river >= 6) add('chinese', country ? 2 : 2.5);
  if (warm / n > 0.1 || forest / n > 0.2) add('seasia', country ? 4 : 3);
  // the bay city: a coast with hills behind it, and a city rather than a village
  if (sea / n > 0.08 && hill / n > 0.1) add('sanfran', country ? 1.5 : 5);
  // (a megalopolis's shipping channel is a river too, so it is left out: Budapest is a city and a metro's style)
  if (river >= 6 && (p.kind === 'city' || p.kind === 'metro')) add('budapest', 2.5);
  // Paris on the Seine and Washington on the Potomac: a city astride its river
  if (river >= 6 && (p.kind === 'city' || p.kind === 'metro')) { add('paris', 2); add('capital', 1.5); }
  const big = p.kind === 'metro' || p.kind === 'mega';
  // Havana on a warm shore, the Creole quarter where a warm river meets it; Hong Kong wherever a big city has
  // the sea in front and hills behind (Venice is built on its canals, world/canals.ts, never picked here)
  if (sea / n > 0.06) {
    if (warm / n > 0.04 || dry / n > 0.05) add('havana', country ? 0.75 : 1.25);
    if (hill / n > 0.1 && !country) add('hongkong', big ? 2 : 0.75);
    if (big && dry / n > 0.05) add('dubai', 1.5);
  }
  if (river >= 6) {
    if (p.kind === 'city' || p.kind === 'metro') { add('london', 1.25); add('steampunk', 0.42); }
    if (warm / n > 0.04 || forest / n > 0.15) add('neworleans', country ? 0.75 : 1.25);
  }
  // dry country: courtyards and mud, the pink cities, the Mother Road through it and the Strip out in the middle of it
  if (dry / n > 0.18) {
    add('moorish', 1); add('mughal', 1); add('sahel', country ? 1.5 : 0.75);
    if (country) add('motherroad', 2);
    else { add('vegas', 1.25); add('dubai', big ? 1.25 : 0.5); }
  } else if (open / n > 0.55 && country) add('motherroad', 0.5);
  // the cold north is tarred timber, and high cold country prayer flags
  if (cold / n > 0.2) { add('norse', country ? 2 : 1); if (hill / n > 0.15) add('himalayan', 1.5); }
  // the hills: the Andes and the Himalaya in the steep ones, burrows in the green ones, a white city against the mountain
  if (hill / n > 0.25) {
    add('andean', country ? 1.75 : 1.25); add('himalayan', 0.75);
    if (!country && p.kind !== 'mega') add('whitecity', 0.7);
  }
  if (hill / n > 0.08 && hill / n <= 0.4 && dry / n < 0.05 && cold / n < 0.05 && p.kind === 'rural') add('shire', 0.875);
  // Chicago: a city on the flat prairie by a great lake (or astride its river), never a village
  if (!country && (sea / n > 0.04 || river >= 6) && open / n > 0.2 && hill / n < 0.1) add('chicago', big ? 3 : 2);
  if (forest / n > 0.2 && cold / n < 0.1) add('spirit', country ? 0.42 : 0.525);
  return taste;
}

