import * as THREE from 'three';
import { STEP, type Building, type World } from '../world/tiles';
import { buildingHeight } from '../world/towns';
import { CUTAWAY } from './mesher';

/**
 * Seeing the car through whatever it drives behind.
 *
 * Buildings are merged into one mesh per chunk, so a building can't simply be given its own
 * material. Instead every vertex carries an id for its building (or piece of one), and the shader fades the few ids
 * listed in the uniforms below. Each frame a handful of rays is cast from the camera to points
 * around the car: the share of them a building swallows is how far it fades, so a building goes
 * clear gradually as the car slips behind it, and comes back as it drives clear.
 *
 * The id is `uid * PART_SLOTS + part`. An ordinary building is all part 0 and fades as one. A big
 * one (a wonder, a stadium, a port) is cut into its separate pieces when it is drawn (see parts.ts),
 * so driving behind one obelisk on the avenue fades that obelisk, not the pyramid at the end of it.
 */

/** Pieces a building can be cut into; ids are `uid * PART_SLOTS + part`. */
export const PART_SLOTS = 64;

/** One separately fading piece of a big building, in the world's own frame (before ox / oz). */
export interface PartBox { id: number; x0: number; x1: number; y0: number; y1: number; z0: number; z1: number }

/** The pieces each big building was cut into when its chunk was drawn, per world. */
const PARTS = new WeakMap<World, Map<number, PartBox[]>>();
let partsVersion = 0;

/** Record (or with null, forget) how a building was cut up. */
export function setParts(w: World, uid: number, parts: PartBox[] | null): void {
  let m = PARTS.get(w);
  if (!m) PARTS.set(w, (m = new Map()));
  if (parts) m.set(uid, parts);
  else if (!m.delete(uid)) return;
  partsVersion++;
}

/** Most buildings that can be faded at once. */
const MAX_FADED = 8;
/** How see-through a building gets when the car is completely behind it. */
const MIN_ALPHA = 0.1;
/** Rays are cast to the car and to points this far out around it, so the fade starts before it's hidden. */
const SPREAD = [0.45, 1.0];
/** Fade in and out over about this many seconds. */
const EASE = 9;

const XRAY = {
  uFadeId: { value: new Float32Array(MAX_FADED).fill(-1) },
  uFadeA: { value: new Float32Array(MAX_FADED).fill(1) },
};

/** Give a building material the per-vertex id and the fade lookup. Use as `onBeforeCompile`. */
export function xrayShader(shader: { vertexShader: string; fragmentShader: string; uniforms: Record<string, THREE.IUniform> }): void {
  shader.uniforms.uFadeId = XRAY.uFadeId;
  shader.uniforms.uFadeA = XRAY.uFadeA;
  shader.vertexShader = shader.vertexShader
    .replace('#include <common>', '#include <common>\nattribute float aId;\nvarying float vId;')
    .replace('#include <begin_vertex>', '#include <begin_vertex>\nvId = aId;');
  shader.fragmentShader = shader.fragmentShader
    .replace('#include <common>', `#include <common>\nuniform float uFadeId[${MAX_FADED}];\nuniform float uFadeA[${MAX_FADED}];\nvarying float vId;`)
    .replace('#include <color_fragment>', `#include <color_fragment>
  for (int i = 0; i < ${MAX_FADED}; i++) { if (abs(uFadeId[i] - vId) < 0.5) diffuseColor.a = min(diffuseColor.a, uFadeA[i]); }`);
}

/** A prop this close to the line (past its own radius) is as clear as it gets; this far, untouched. */
const PROP_NEAR = 0.0, PROP_FAR = 0.6;
/** How much of a prop is left when the line runs through its middle (buildings keep MIN_ALPHA). */
const PROP_MIN = 0.15;

/**
 * Scenery is too many to trace one by one: trees, rocks, fences and the rest are instanced by the
 * hundred thousand. So each prop tests itself in the vertex shader instead, against the same line
 * of sight the ground's cutaway uses (CUTAWAY: from the followed point to the eye). Every vertex of
 * an instance tests the instance's own bounding sphere (`aBound`, local centre and radius, scaled by
 * the instance), so a tree fades as one; the nearer the line runs to its middle, the clearer it goes.
 * It is stippled away rather than blended, like the ground, so nothing has to be sorted. A merged
 * mesh with no instances (lamp posts) tests each vertex on its own. The shadow pass is untouched: a
 * faded tree still throws its shadow, as a faded building does.
 */
const PROP_CUT_VERT = /* glsl */ `
uniform vec3 uCutA;
uniform vec3 uCutB;
uniform float uCutR;
attribute vec4 aBound;
varying float vCut;
float propCut(vec3 c, float r) {
  vec3 ab = uCutB - uCutA;
  float len = length(ab);
  if (uCutR <= 0.0 || len < 1e-3) return 0.0;
  vec3 dir = ab / len;
  float along = dot(c - uCutA, dir);
  if (along <= 0.0 || along > len + r) return 0.0;
  float d = length(c - uCutA - dir * along);
  // only what stands on the eye's side of the car, and near enough the line to cover it
  return smoothstep(0.0, 0.8, along) * (1.0 - smoothstep(r + ${PROP_NEAR.toFixed(2)}, r + ${PROP_FAR.toFixed(2)}, d));
}
`;
const PROP_CUT_FRAG = /* glsl */ `
varying float vCut;
float bayer2(vec2 a) { a = floor(a); return fract(a.x * 0.5 + a.y * a.y * 0.75); }
float bayer4(vec2 a) { return bayer2(0.5 * a) * 0.25 + bayer2(a); }
`;

/** A prop geometry's bounding sphere on every vertex, for propXray. Once per shared geometry. */
export function propBound(g: THREE.BufferGeometry): void {
  if (g.getAttribute('aBound')) return;
  if (!g.boundingSphere) g.computeBoundingSphere();
  const s = g.boundingSphere!, n = g.getAttribute('position').count, a = new Float32Array(n * 4);
  for (let k = 0; k < n; k++) a.set([s.center.x, s.center.y, s.center.z, s.radius], k * 4);
  g.setAttribute('aBound', new THREE.BufferAttribute(a, 4));
}

/** Stipple a prop away while it stands between the eye and the car. Call last in `onBeforeCompile`. */
export function propXray(shader: { vertexShader: string; fragmentShader: string; uniforms: Record<string, THREE.IUniform> }): void {
  Object.assign(shader.uniforms, CUTAWAY);
  shader.vertexShader = shader.vertexShader
    .replace('#include <common>', `#include <common>
${PROP_CUT_VERT}`)
    .replace('#include <project_vertex>', `#include <project_vertex>
#ifdef USE_INSTANCING
  float cutS = max(length(instanceMatrix[0].xyz), max(length(instanceMatrix[1].xyz), length(instanceMatrix[2].xyz)));
  vCut = propCut((modelMatrix * instanceMatrix * vec4(aBound.xyz, 1.0)).xyz, aBound.w * cutS);
#else
  vCut = propCut((modelMatrix * vec4(transformed, 1.0)).xyz, 0.0);
#endif`);
  shader.fragmentShader = shader.fragmentShader
    .replace('#include <common>', `#include <common>
${PROP_CUT_FRAG}`)
    .replace('#include <clipping_planes_fragment>', `#include <clipping_planes_fragment>
  if (vCut > 0.01 && bayer4(gl_FragCoord.xy) >= 1.0 - ${(1 - PROP_MIN).toFixed(2)} * vCut) discard;`);
}

interface Box { id: number; x0: number; x1: number; z0: number; z1: number; y0: number; y1: number; cx: number; cz: number; cy: number; r: number }

/** Slab test: the distance along the ray at which it enters the box, or -1 if it misses within `far`. */
function hit(ox: number, oy: number, oz: number, dx: number, dy: number, dz: number, b: Box, far: number): boolean {
  let lo = 0, hi = far;
  const axis = (o: number, d: number, min: number, max: number) => {
    if (Math.abs(d) < 1e-6) return o >= min && o <= max;
    const t0 = (min - o) / d, t1 = (max - o) / d;
    lo = Math.max(lo, Math.min(t0, t1));
    hi = Math.min(hi, Math.max(t0, t1));
    return true;
  };
  return axis(ox, dx, b.x0, b.x1) && axis(oy, dy, b.y0, b.y1) && axis(oz, dz, b.z0, b.z1) && lo <= hi;
}

export class XRay {
  private boxes: Box[] = [];
  private world: World | null = null;
  private version = -1;
  private fade = new Map<number, number>();
  private samples: THREE.Vector3[] = [];
  private dir = new THREE.Vector3();
  private right = new THREE.Vector3();
  private up = new THREE.Vector3();
  private tmp = new THREE.Vector3();

  constructor() {
    for (let k = 0; k < 1 + SPREAD.length * 4; k++) this.samples.push(new THREE.Vector3());
  }

  setWorld(w: World | null): void {
    this.world = w;
    this.version = -1;
    this.boxes = [];
    this.fade.clear();
    XRAY.uFadeId.value.fill(-1);
    XRAY.uFadeA.value.fill(1);
    this.rebuild();
  }

  /** One box per building, or one per piece for a building that was cut up. */
  private rebuild(): void {
    this.version = partsVersion;
    this.boxes = [];
    const w = this.world;
    if (!w) return;
    const cut = PARTS.get(w);
    for (const b of w.allBuildings) {
      if (!b.solid || b.gone) continue;
      const parts = cut?.get(b.uid);
      if (parts) for (const p of parts) this.boxes.push(partBox(p, w.ox, w.oz));
      else this.boxes.push(boxOf(b, w.ox, w.oz));
    }
  }

  /** Fade whatever stands between the camera and the car. */
  update(dt: number, camera: THREE.Camera, car: THREE.Vector3): void {
    if (this.version !== partsVersion) this.rebuild();
    const eye = camera.position;
    this.dir.copy(car).sub(eye);
    const dist = this.dir.length();
    if (!this.boxes.length || dist < 1e-3) return;
    this.dir.divideScalar(dist);
    // a little cross of points around the car, across the line of sight
    this.right.set(this.dir.z, 0, -this.dir.x).normalize();
    this.up.copy(this.right).cross(this.dir).normalize();
    this.samples[0].copy(car);
    let n = 1;
    for (const s of SPREAD) {
      this.samples[n++].copy(car).addScaledVector(this.right, s);
      this.samples[n++].copy(car).addScaledVector(this.right, -s);
      this.samples[n++].copy(car).addScaledVector(this.up, s);
      this.samples[n++].copy(car).addScaledVector(this.up, -s);
    }

    const targets = new Map<number, number>();
    for (const b of this.boxes) {
      // only what is near the line of sight, and nearer the camera than the car is
      this.tmp.set(b.cx - eye.x, b.cy - eye.y, b.cz - eye.z);
      const along = this.tmp.dot(this.dir);
      if (along <= 0 || along > dist) continue;
      if (this.tmp.addScaledVector(this.dir, -along).length() > b.r + SPREAD[SPREAD.length - 1]) continue;
      // a piece the car is on or inside can't be standing in front of it: a circuit's banked track, the
      // deck of a plaza. Fading it showed the ground through the track under the car
      if (car.x >= b.x0 && car.x <= b.x1 && car.z >= b.z0 && car.z <= b.z1 && car.y >= b.y0 - 0.2 && car.y <= b.y1 + 0.6) continue;
      let blocked = 0;
      for (let k = 0; k < n; k++) {
        const s = this.samples[k];
        const dx = s.x - eye.x, dy = s.y - eye.y, dz = s.z - eye.z;
        const len = Math.hypot(dx, dy, dz);
        if (hit(eye.x, eye.y, eye.z, dx / len, dy / len, dz / len, b, len)) blocked++;
      }
      if (blocked) targets.set(b.id, 1 - (1 - MIN_ALPHA) * (blocked / n));
    }

    const k = 1 - Math.exp(-dt * EASE);
    for (const [uid, want] of targets) this.fade.set(uid, (this.fade.get(uid) ?? 1) + (want - (this.fade.get(uid) ?? 1)) * k);
    for (const [uid, cur] of this.fade) {
      if (targets.has(uid)) continue;
      const back = cur + (1 - cur) * k;
      if (back > 0.995) this.fade.delete(uid);
      else this.fade.set(uid, back);
    }

    const worst = [...this.fade.entries()].sort((a, b) => a[1] - b[1]).slice(0, MAX_FADED);
    const ids = XRAY.uFadeId.value, alphas = XRAY.uFadeA.value;
    for (let i = 0; i < MAX_FADED; i++) {
      ids[i] = i < worst.length ? worst[i][0] : -1;
      alphas[i] = i < worst.length ? worst[i][1] : 1;
    }
  }

  /** Everything back to full: the camera mode (game/photoMode.ts) keeps every building solid. */
  clear(): void {
    if (!this.fade.size) return;
    this.fade.clear();
    const ids = XRAY.uFadeId.value, alphas = XRAY.uFadeA.value;
    for (let i = 0; i < MAX_FADED; i++) { ids[i] = -1; alphas[i] = 1; }
  }

  /** Console: what is currently faded (building uid / piece), and how far. */
  faded(): string[] {
    return [...this.fade.entries()].map(([id, a]) => `${Math.floor(id / PART_SLOTS)}/${id % PART_SLOTS}: ${a.toFixed(2)}`);
  }
}

function boxOf(b: Building, ox: number, oz: number): Box {
  const y0 = b.level * STEP, h = buildingHeight(b);
  const x = b.x + ox, z = b.z + oz;
  return {
    id: b.uid * PART_SLOTS, x0: x, x1: x + b.w, z0: z, z1: z + b.d, y0: y0 - 0.3, y1: y0 + h,
    cx: x + b.w / 2, cz: z + b.d / 2, cy: y0 + h / 2, r: Math.hypot(b.w, b.d) / 2 + h / 2,
  };
}

function partBox(p: PartBox, ox: number, oz: number): Box {
  const x0 = p.x0 + ox, x1 = p.x1 + ox, z0 = p.z0 + oz, z1 = p.z1 + oz;
  return {
    id: p.id, x0, x1, z0, z1, y0: p.y0, y1: p.y1,
    cx: (x0 + x1) / 2, cz: (z0 + z1) / 2, cy: (p.y0 + p.y1) / 2, r: Math.hypot(x1 - x0, p.y1 - p.y0, z1 - z0) / 2,
  };
}
