import { N, type World } from './tiles';

/**
 * Municipalities (docs/territory.html, "The municipality"): the land each town answers for, as a raster
 * of MUNI × MUNI pixels over the cell, each the id of a town or −1. Every town's own tiles seed a flood
 * over land, four ways, out to MUNI_REACH tiles; a pixel belongs to whichever town reaches it first. So
 * borders fall halfway between towns, follow the coast and never jump a strait, and two towns whose
 * municipalities share an edge are neighbours. Derived, never saved.
 */

/** Tiles to a pixel of the raster. */
export const MUNI_PER = 4;
/** Pixels across it. */
export const MUNI = N / MUNI_PER;
/** How far a town's municipality reaches over land beyond its own tiles, in tiles. */
export const MUNI_REACH = 40;

export function municipalityOf(w: World): Int16Array {
  const out = new Int16Array(MUNI * MUNI).fill(-1);
  const land = new Uint8Array(MUNI * MUNI);
  const dist = new Int16Array(MUNI * MUNI).fill(-1);
  const queue: number[] = [];
  const half = MUNI_PER >> 1;
  for (let pz = 0; pz < MUNI; pz++) {
    for (let px = 0; px < MUNI; px++) {
      const p = pz * MUNI + px;
      // land if the pixel's middle tile is dry; a town claims it if any of its tiles is the town's
      const mid = (pz * MUNI_PER + half) * N + px * MUNI_PER + half;
      land[p] = w.water[mid] >= 0 ? 0 : 1;
      let town = -1;
      for (let dz = 0; dz < MUNI_PER && town < 0; dz++) {
        for (let dx = 0; dx < MUNI_PER; dx++) {
          const id = w.townId[(pz * MUNI_PER + dz) * N + px * MUNI_PER + dx];
          if (id >= 0) { town = id; break; }
        }
      }
      if (town >= 0) { out[p] = town; dist[p] = 0; land[p] = 1; queue.push(p); }
    }
  }
  const reach = Math.round(MUNI_REACH / MUNI_PER);
  for (let head = 0; head < queue.length; head++) {
    const p = queue[head];
    const d = dist[p];
    if (d >= reach) continue;
    const px = p % MUNI, pz = (p / MUNI) | 0;
    const step = (q: number) => {
      if (!land[q] || dist[q] >= 0) return;
      dist[q] = d + 1;
      out[q] = out[p];
      queue.push(q);
    };
    if (px > 0) step(p - 1);
    if (px < MUNI - 1) step(p + 1);
    if (pz > 0) step(p - MUNI);
    if (pz < MUNI - 1) step(p + MUNI);
  }
  return out;
}
