import { hex, scale, type RGB } from '../../world/biomes';
import type { BuildingKind, OpenKind } from '../../world/tiles';
import { Vis } from '../nightLights';
import {
  BRIGHT, DARK, LEAF2, METAL, PATH, STONE, TAU, TRUNK, WARM_GLOW, WATER, WHITE, WOOD, COOL_GLOW,
  pick, styleRoof, styleWall, styledGable, tree, type Draw, type Kit,
} from './kit';
import { greatPark } from './greatPark';
import { kidsRig, pickPalette, pickSurface, playBench, playEquipment, schoolDay } from './playKit';

/**
 * Parks and plazas: twenty-two kinds of open space, from mown meadow to dense grove. They are
 * placed as open lots, so cars and people cross them; only a chapel, a lake or a glasshouse is ever
 * solid. Each is recognisable from the camera's height by its ground pattern, its water and its trees.
 */

const LAWN_MOWN = hex(0x9ad774), GRAVEL = hex(0xc9bfae), HEDGE = hex(0x3f7d3a), COBBLE = hex(0xcfc4ae);
const SAND = hex(0xe9d9a6), REED = hex(0x7a9a4a), CLAY = hex(0xc8683f), COURT_BLUE = hex(0x3f7fb5);
const FLOWERS = [0xf2c14e, 0xe86a92, 0xffffff, 0xb07ad8, 0xf28c38, 0xe2412f];
const lampGlow = hex(0xe8e0c8);

/** A lamp post with a glowing head. */
function lamp(k: Kit, x: number, z: number, h = 0.42): void {
  k.box(x, 0, z, 0.03, h, 0.03, DARK);
  k.glowBox(x, h, z, 0.07, 0.07, 0.07, lampGlow, [17.6, 30, 1.8], WARM_GLOW);
}

/** A park bench facing +z unless turned. */
function bench(k: Kit, x: number, z: number, alongZ = false): void {
  k.box(x, 0.03, z, alongZ ? 0.07 : 0.24, 0.035, alongZ ? 0.24 : 0.07, WOOD);
  k.box(x + (alongZ ? -0.035 : 0), 0.065, z + (alongZ ? 0 : -0.035), alongZ ? 0.015 : 0.24, 0.05, alongZ ? 0.24 : 0.015, WOOD);
  for (const s of [-0.1, 0.1]) k.box(x + (alongZ ? 0 : s), 0, z + (alongZ ? s : 0), 0.02, 0.03, 0.02, DARK);
}

/** A straight path strip on the ground between two local points. */
function path(k: Kit, x0: number, z0: number, x1: number, z1: number, w: number, col: RGB = PATH): void {
  if (Math.abs(z1 - z0) < 1e-6 || Math.abs(x1 - x0) < 1e-6) {
    k.box((x0 + x1) / 2, 0.004, (z0 + z1) / 2, Math.abs(x1 - x0) || w, 0.01, Math.abs(z1 - z0) || w, col);
  } else {
    k.bar([x0, 0.008, z0], [x1, 0.008, z1], w / 2, col);
  }
}

function flagpole(k: Kit, x: number, z: number, h: number, flag: RGB): void {
  k.cyl(x, 0, z, 0.018, h, METAL, 5);
  k.box(x + 0.09, h - 0.14, z, 0.18, 0.11, 0.008, flag);
}

/** A low hedge from one local point to another (axis-aligned). */
function hedge(k: Kit, x0: number, z0: number, x1: number, z1: number, h = 0.08, t = 0.08): void {
  k.box((x0 + x1) / 2, 0, (z0 + z1) / 2, Math.max(t, Math.abs(x1 - x0)), h, Math.max(t, Math.abs(z1 - z0)), HEDGE);
}

/** A fence of posts and a rail round the lot, with a gap for a gate in the middle of the front. */
function fence(k: Kit, W: number, D: number, col: RGB, h = 0.14, gate = 0.4): void {
  const hw = W / 2 - 0.08, hd = D / 2 - 0.08;
  const side = (x0: number, z0: number, x1: number, z1: number) => {
    const len = Math.hypot(x1 - x0, z1 - z0), n = Math.max(1, Math.round(len / 0.3));
    for (let i = 0; i <= n; i++) k.box(x0 + ((x1 - x0) * i) / n, 0, z0 + ((z1 - z0) * i) / n, 0.02, h, 0.02, col);
    k.bar([x0, h * 0.8, z0], [x1, h * 0.8, z1], 0.008, col);
  };
  side(-hw, -hd, hw, -hd);
  side(-hw, -hd, -hw, hd);
  side(hw, -hd, hw, hd);
  side(-hw, hd, -gate / 2, hd);
  side(gate / 2, hd, hw, hd);
}

// ---- 1. meadow -----------------------------------------------------------------------------------

const meadow: Draw = (k, W, D, _b, r) => {
  // a single mown path wandering from the gate to the far corner
  const pts: [number, number][] = [[0, D / 2 - 0.1], [W * 0.12, D * 0.15], [-W * 0.15, -D * 0.12], [-W / 2 + 0.3, -D / 2 + 0.3]];
  for (let i = 1; i < pts.length; i++) path(k, pts[i - 1][0], pts[i - 1][1], pts[i][0], pts[i][1], 0.22, LAWN_MOWN);
  // wildflower patches
  for (let n = Math.floor(W * D * 0.35); n > 0; n--) {
    const x = (r() - 0.5) * (W - 0.6), z = (r() - 0.5) * (D - 0.6);
    k.disc(x, 0.004, z, 0.16 + r() * 0.2, pick(r, FLOWERS), 7);
  }
  for (let i = 0; i < 3; i++) tree(k, -W / 2 + 0.5 + i * (W - 1) / 2 + (r() - 0.5) * 0.4, 0, -D / 2 + 0.35, 1 + r() * 0.3, false);
  // the kissing gate
  for (const s of [-0.18, 0.18]) k.box(s, 0, D / 2 - 0.08, 0.04, 0.18, 0.04, WOOD);
  k.box(0, 0.14, D / 2 - 0.08, 0.4, 0.03, 0.03, WOOD);
};

// ---- 2. civic square -----------------------------------------------------------------------------

const civicSquare: Draw = (k, W, D, _b, r, t) => {
  const stone = pick(r, STONE), accent = t?.accent !== undefined ? hex(t.accent) : null;
  // the plinth and its statue at the back
  for (let s = 0; s < 3; s++) k.box(0, s * 0.04, -D / 2 + 0.6, 1.2 - s * 0.25, 0.04, 0.8 - s * 0.18, scale(stone, 1 - s * 0.04));
  k.box(0, 0.12, -D / 2 + 0.6, 0.3, 0.32, 0.3, stone);
  k.cyl(0, 0.44, -D / 2 + 0.6, 0.07, 0.3, hex(0x6b7a6a), 8);
  k.dome(0, 0.74, -D / 2 + 0.6, 0.07, hex(0x6b7a6a), 8, 2);
  for (const s of [-0.5, 0, 0.5]) flagpole(k, s * (W - 1), -D / 2 + 0.2, 1.1, accent ?? pick(r, BRIGHT));
  for (const [sx, sz] of [[-1, -1], [1, -1], [-1, 1], [1, 1]]) {
    const x = sx * (W / 2 - 0.25), z = sz * (D / 2 - 0.25);
    k.box(x, 0, z, 0.05, 0.9, 0.05, METAL);
    k.glowBox(x, 0.9, z, 0.16, 0.06, 0.1, hex(0xdfe6ea), [17.2, 30, 2.2], COOL_GLOW);
  }
  if (accent) for (const sz of [-1, 1]) k.box(0, 0.003, sz * (D / 2 - 0.06), W - 0.12, 0.012, 0.06, accent);
};

// ---- 3. fountain square --------------------------------------------------------------------------

const fountainSquare: Draw = (k, W, D, _b, r) => {
  const stone = pick(r, STONE);
  k.cyl(0, 0, 0, 0.95, 0.14, stone, 16);
  k.cyl(0, 0.03, 0, 0.87, 0.12, WATER, 16);
  k.glowBox(0, 0.15, 0, 1.1, 0.005, 1.1, WATER, [17.5, 25.5, 1.1], hex(0x9fd8ff));
  k.cyl(0, 0, 0, 0.12, 0.42, stone, 8);
  k.cyl(0, 0.42, 0, 0.45, 0.06, stone, 12);
  k.cyl(0, 0.44, 0, 0.4, 0.045, WATER, 12);
  k.cyl(0, 0.48, 0, 0.07, 0.24, stone, 8);
  k.cyl(0, 0.72, 0, 0.2, 0.04, stone, 10);
  k.cone(0, 0.76, 0, 0.1, 0.2, hex(0xcfeaf6), 8);
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.cyl(sx * (W / 2 - 0.2), 0, sz * (D / 2 - 0.2), 0.05, 0.16, DARK, 6);
};

// ---- 4. greenway ---------------------------------------------------------------------------------

/** A riverside strip: its long side (z) runs beside the water, which lies to -x. */
const greenway: Draw = (k, W, D, _b, r) => {
  path(k, W * 0.15, -D / 2 + 0.1, W * 0.15, D / 2 - 0.1, 0.24);
  for (let z = -D / 2 + 0.3; z < D / 2 - 0.2; z += 0.35) {
    if (r() < 0.6) k.cone(-W / 2 + 0.15 + r() * 0.15, 0, z + r() * 0.2, 0.08, 0.2 + r() * 0.1, REED, 5);
  }
  for (let z = -D / 2 + 1; z < D / 2 - 0.5; z += 2) bench(k, W / 2 - 0.2, z, true);
  for (const f of [-0.35, 0, 0.35]) lamp(k, W / 2 - 0.12, f * D);
  for (let z = -D / 2 + 0.5; z < D / 2; z += 1.6) tree(k, W / 2 - 0.25, 0, z + 0.4, 0.8 + r() * 0.3, false);
};

// ---- 5. picnic ground -----------------------------------------------------------------------------

const picnicGround: Draw = (k, W, D, _b, r) => {
  const table = (x: number, z: number) => {
    k.box(x, 0.12, z, 0.34, 0.03, 0.2, WOOD);
    for (const s of [-1, 1]) k.box(x, 0.06, z + s * 0.17, 0.34, 0.025, 0.07, WOOD);
    for (const s of [-0.13, 0.13]) k.box(x + s, 0, z, 0.03, 0.12, 0.18, scale(WOOD, 0.8));
  };
  for (const [fx, fz] of [[-0.25, -0.2], [0.25, -0.25], [-0.2, 0.25], [0.28, 0.22]]) table(fx * W, fz * D);
  k.box(0, 0, -0.05, 0.28, 0.2, 0.2, hex(0xa4583f));
  k.box(0, 0.2, -0.05, 0.22, 0.02, 0.14, DARK);
  k.cyl(W / 2 - 0.25, 0, D / 2 - 0.25, 0.06, 0.16, hex(0x3f6b4a), 7);
  for (let i = 0; i < 5; i++) {
    const a = r() * TAU, rr = Math.min(W, D) * (0.36 + r() * 0.1);
    tree(k, Math.cos(a) * rr, 0, Math.sin(a) * rr, 0.85 + r() * 0.35, r() < 0.2);
  }
};

// ---- 6. dog run -----------------------------------------------------------------------------------

const dogRun: Draw = (k, W, D, _b, r) => {
  fence(k, W, D, hex(0x8a8f94), 0.16);
  // a lean-to shelter at the back
  for (const s of [-0.3, 0.3]) {
    k.box(s, 0, -D / 2 + 0.18, 0.03, 0.26, 0.03, WOOD);
    k.box(s, 0, -D / 2 + 0.42, 0.03, 0.18, 0.03, WOOD);
  }
  k.bar([-0.36, 0.28, -D / 2 + 0.14], [-0.36, 0.2, -D / 2 + 0.46], 0.01, WOOD);
  k.box(0, 0.24, -D / 2 + 0.3, 0.72, 0.02, 0.36, styleRoof(r));
  k.disc(W / 2 - 0.3, 0.01, 0, 0.06, hex(0x6fa8d8), 8);
  bench(k, -W / 2 + 0.25, D / 2 - 0.4, true);
};

// ---- 7. plaza steps --------------------------------------------------------------------------------

/**
 * Terraces of paving stepping down the slope: the lot is laid out in three levels by the placer, so
 * each terrace is drawn at its own height, highest at the back.
 */
const plazaSteps: Draw = (k, W, D, _b, r) => {
  const stone = pick(r, STONE), band = D / 3;
  for (let i = 0; i < 3; i++) {
    const z = -D / 2 + band * (i + 0.5), y = k.ground(0, z);
    k.box(0, y, z, W - 0.1, 0.02, band - 0.02, scale(stone, 1 - i * 0.03));
    // the riser along the terrace's front edge
    k.box(0, y - 0.25, z + band / 2 - 0.05, W - 0.1, 0.27, 0.1, scale(stone, 0.9));
    for (const sx of [-1, 1]) {
      k.box(sx * (W / 2 - 0.2), y + 0.02, z, 0.24, 0.12, band * 0.6, hex(0x9a8f86));
      tree(k, sx * (W / 2 - 0.2), y + 0.14, z, 0.55, false);
    }
  }
  k.bar([W / 2 - 0.05, k.ground(0, -D / 2 + 0.2) + 0.2, -D / 2 + 0.2], [W / 2 - 0.05, k.ground(0, D / 2 - 0.2) + 0.2, D / 2 - 0.2], 0.012, METAL);
};

// ---- 8. sculpture park -----------------------------------------------------------------------------

const sculpturePark: Draw = (k, W, D, _b, r, t) => {
  path(k, -W / 2 + 0.2, -D / 2 + 0.2, W / 2 - 0.2, D / 2 - 0.2, 0.18, GRAVEL);
  path(k, -W / 2 + 0.2, D / 2 - 0.2, W / 2 - 0.2, -D / 2 + 0.2, 0.18, GRAVEL);
  const colours = t?.accent !== undefined ? [t.accent, 0xf2c14e, 0x2f7fb5, 0xe2412f] : [0xe2412f, 0xf2c14e, 0x2f7fb5, 0x2bb3a3, 0x8e5cc7];
  const spots: [number, number][] = [[-0.3, -0.05], [0.3, -0.05], [0, -0.32], [0, 0.3], [-0.32, 0.3]];
  const order = [0, 1, 2, 3, 4].sort(() => r() - 0.5);
  spots.forEach(([fx, fz], i) => {
    const x = fx * W, z = fz * D, col = hex(colours[i % colours.length]);
    k.box(x, 0, z, 0.26, 0.06, 0.26, hex(0xd8d2c6));
    switch (order[i]) {
      case 0: k.hoop(x, 0.28, z, 0.2, 0.025, col, 12); break;                                      // a tilted ring
      case 1: k.box(x, 0.06, z, 0.18, 0.18, 0.18, col); k.box(x + 0.04, 0.24, z - 0.02, 0.12, 0.12, 0.12, scale(col, 0.8)); break;
      case 2: k.bar([x - 0.08, 0.06, z], [x + 0.1, 0.5, z + 0.04], 0.03, col); break;                  // a leaning bar
      case 3: k.box(x, 0.06, z, 0.08, 0.2, 0.08, WHITE); k.dome(x, 0.26, z, 0.12, col, 10, 3); break; // a sphere on a plinth
      default: for (let s = 0; s < 4; s++) k.box(x - 0.09 + s * 0.06, 0.06, z, 0.025, 0.12 + Math.sin(s) * 0.1 + 0.1, 0.16, col);
    }
  });
  for (let i = 0; i < 4; i++) tree(k, (r() < 0.5 ? -1 : 1) * (W / 2 - 0.35), 0, (r() - 0.5) * (D - 0.8), 0.8 + r() * 0.3, false);
};

// ---- 9. bandstand green ----------------------------------------------------------------------------

const bandstandGreen: Draw = (k, W, D, _b, r) => {
  path(k, -W / 2 + 0.2, 0, W / 2 - 0.2, 0, 0.16);
  path(k, 0, -D / 2 + 0.2, 0, D / 2 - 0.2, 0.16);
  k.hoop(0, 0.004, 0, 1.3, 0.08, PATH, 16, 'xz');
  const trim = pick(r, [0xffffff, 0x2f7fb5, 0x3f7d3a]);
  k.cyl(0, 0, 0, 0.62, 0.12, hex(0xd8d2c6), 8);
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * TAU + TAU / 16;
    k.box(Math.cos(a) * 0.55, 0.12, Math.sin(a) * 0.55, 0.035, 0.46, 0.035, trim);
  }
  k.cyl(0, 0.24, 0, 0.58, 0.02, trim, 8);
  k.cone(0, 0.58, 0, 0.72, 0.36, styleRoof(r), 8);
  // the weekend concert: the canopy lit from inside
  k.tagged(Vis.Weekend, () => k.glowBox(0, 0.54, 0, 0.6, 0.03, 0.6, WHITE, [17.5, 22.5, 2.4], WARM_GLOW));
  for (let i = 0; i < 6; i++) {
    const a = (i / 6) * TAU;
    bench(k, Math.cos(a) * 1.55, Math.sin(a) * 1.55);
  }
  for (const [sx, sz] of [[-1, -1], [1, 1]]) tree(k, sx * (W / 2 - 0.35), 0, sz * (D / 2 - 0.35), 1, false);
};

// ---- 10. memorial -----------------------------------------------------------------------------------

const memorial: Draw = (k, W, D, _b, r) => {
  const stone = hex(0xd9d4c8), dark = hex(0x9a958c);
  hedge(k, -W / 2 + 0.15, -D / 2 + 0.15, W / 2 - 0.15, -D / 2 + 0.15);
  hedge(k, -W / 2 + 0.15, -D / 2 + 0.15, -W / 2 + 0.15, D / 2 - 0.15);
  hedge(k, W / 2 - 0.15, -D / 2 + 0.15, W / 2 - 0.15, D / 2 - 0.15);
  k.box(0, 0, -0.1, 0.8, 0.05, 0.8, dark);
  k.box(0, 0.05, -0.1, 0.56, 0.05, 0.56, stone);
  if (r() < 0.5) {
    k.box(0, 0.1, -0.1, 0.2, 0.7, 0.2, stone);
    k.hip(0, 0.8, -0.1, 0.2, 0.18, 0.2, stone);
  } else {
    k.box(0, 0.1, -0.1, 0.42, 0.42, 0.24, stone);
    k.box(0, 0.52, -0.1, 0.48, 0.05, 0.3, dark);
  }
  k.hoop(0, 0.28, 0.03, 0.08, 0.018, HEDGE, 10);
  for (const s of [-1, 1]) flagpole(k, s * (W / 2 - 0.3), D / 2 - 0.35, 0.9, pick(r, [0xe2412f, 0x2f4d7a]));
};

// ---- 11. skate park ---------------------------------------------------------------------------------

const skatePark: Draw = (k, W, D) => {
  const concrete = hex(0xbcb8b0), edge = hex(0x9a968e);
  // the bowl: quarter-pipes facing in round a square
  const q = (x: number, z: number, w: number, d: number) => k.box(x, 0, z, w, 0.14, d, concrete, edge);
  q(0, -D / 2 + 0.35, W - 0.5, 0.25);
  q(-W / 2 + 0.3, -0.1, 0.25, 0.8);
  // a half pipe down the front: two ramps facing one another
  k.wedge(-0.4, 0, D / 2 - 0.45, 0.8, 0.22, 0.4, concrete);
  k.box(0.4, 0, D / 2 - 0.45, 0.8, 0.22, 0.4, concrete, edge);
  k.bar([0.1, 0.08, 0.1], [0.1, 0.08, -0.5], 0.012, METAL);
  k.bar([0.45, 0.06, 0.2], [0.45, 0.06, -0.3], 0.012, METAL);
  fence(k, W, D, hex(0x8a8f94), 0.2, 0.3);
};

// ---- 12. promenade -----------------------------------------------------------------------------------

/** A strip the length of an avenue: its long side (z) runs beside the road. */
const promenade: Draw = (k, W, D, _b, r) => {
  const stone = pick(r, STONE);
  k.box(0, 0.004, 0, W - 0.1, 0.012, D - 0.1, stone);
  for (let z = -D / 2 + 0.5; z < D / 2; z += 1) {
    for (const s of [-1, 1]) {
      k.box(s * (W / 2 - 0.2), 0, z, 0.16, 0.05, 0.16, hex(0x9a8f86));
      // pleached: a clipped square head on a bare stem
      k.box(s * (W / 2 - 0.2), 0.05, z, 0.03, 0.3, 0.03, TRUNK);
      k.box(s * (W / 2 - 0.2), 0.35, z, 0.26, 0.2, 0.3, LEAF2);
    }
    if (((z + D) | 0) % 2 === 0) bench(k, 0, z + 0.5, true);
  }
  for (let z = -D / 2 + 1.5; z < D / 2; z += 3) lamp(k, 0, z, 0.5);
};

// ---- 13. cemetery -------------------------------------------------------------------------------------

const cemetery: Draw = (k, W, D, b, r) => {
  const stones = [hex(0xcfcac0), hex(0xb9b4aa), hex(0xa8a39a)];
  path(k, 0, D / 2 - 0.1, 0, -D / 2 + 1.1, 0.2, GRAVEL);
  for (let z = -D / 2 + 1.3; z < D / 2 - 0.4; z += 0.38) {
    for (let x = -W / 2 + 0.35; x < W / 2 - 0.3; x += 0.3) {
      if (Math.abs(x) < 0.2 || r() < 0.12) continue;
      const s = stones[Math.floor(r() * 3)], kind = Math.floor(r() * 3);
      if (kind === 0) k.box(x, 0, z, 0.13, 0.13, 0.03, s);
      else if (kind === 1) { k.box(x, 0, z, 0.1, 0.1, 0.03, s); k.dome(x, 0.1, z, 0.05, s, 6, 2); }
      else { k.box(x, 0, z, 0.03, 0.18, 0.03, s); k.box(x, 0.11, z, 0.1, 0.03, 0.03, s); }
    }
  }
  for (let i = 0; i < 3; i++) {
    const x = (r() < 0.5 ? -1 : 1) * (W / 2 - 0.3), z = -D / 2 + 1.3 + r() * (D - 2);
    k.box(x, 0, z, 0.05, 0.15, 0.05, TRUNK);
    k.cone(x, 0.1, z, 0.22, 0.75, hex(0x2f5a3a), 7);
  }
  // the chapel at the back, the one solid thing here
  const wall = hex(0xece6da);
  k.box(0, 0, -D / 2 + 0.5, 0.55, 0.36, 0.7, wall);
  styledGable(k, r, 0, 0.36, -D / 2 + 0.5, 0.6, 0.28, 0.76, styleRoof(r), wall, true);
  k.box(0, 0, -D / 2 + 0.855, 0.12, 0.22, 0.02, hex(0x6b4a3a));
  fence(k, W, D, DARK, 0.16, 0.34);
  void b;
};

// ---- 14. amphitheatre ----------------------------------------------------------------------------------

const amphitheatre: Draw = (k, W, D, _b, r) => {
  const stone = pick(r, STONE);
  // five semicircular tiers facing the stage at the front
  const cz = D / 2 - 0.55, seg = 14;
  for (let tier = 0; tier < 5; tier++) {
    const r0 = 0.75 + tier * 0.34, y = k.ground(0, cz - r0) + tier * 0.06;
    for (let s = 0; s < seg; s++) {
      const a0 = Math.PI + (s / seg) * Math.PI, a1 = Math.PI + ((s + 1) / seg) * Math.PI, am = (a0 + a1) / 2;
      const x = Math.cos(am) * r0, z = cz + Math.sin(am) * r0;
      if (Math.abs(x) > W / 2 - 0.1 || z < -D / 2 + 0.1) continue;
      k.bar([Math.cos(a0) * r0, y + 0.03, cz + Math.sin(a0) * r0], [Math.cos(a1) * r0, y + 0.03, cz + Math.sin(a1) * r0], 0.08, scale(stone, 1 - tier * 0.04));
    }
  }
  // the stage and its shell
  k.box(0, 0, cz + 0.15, 1.2, 0.12, 0.5, hex(0x8d6d48));
  for (let s = 0; s < 8; s++) {
    const a0 = (s / 8) * Math.PI, a1 = ((s + 1) / 8) * Math.PI;
    k.quad([Math.cos(a0) * 0.62, 0.12, cz + 0.4], [Math.cos(a1) * 0.62, 0.12, cz + 0.4], [Math.cos(a1) * 0.62 * 0.7, 0.12 + Math.sin(a1) * 0.62, cz + 0.4], [Math.cos(a0) * 0.62 * 0.7, 0.12 + Math.sin(a0) * 0.62, cz + 0.4], WHITE, [0, 0.3, cz]);
  }
  k.tagged(Vis.Weekend, () => k.glowBox(0, 0.12, cz + 0.15, 1.1, 0.02, 0.45, WHITE, [18, 23, 2.4], WARM_GLOW));
};

// ---- 15. market square ----------------------------------------------------------------------------------

const marketSquare: Draw = (k, W, D, _b, r) => {
  // cobbles as a faint grid of joints
  for (let z = -D / 2 + 0.25; z < D / 2; z += 0.25) k.box(0, 0.004, z, W - 0.1, 0.004, 0.012, scale(COBBLE, 0.9));
  // the market cross
  k.box(0, 0, 0, 0.36, 0.08, 0.36, COBBLE);
  k.cyl(0, 0.08, 0, 0.05, 0.6, scale(COBBLE, 0.85), 8);
  k.box(0, 0.62, 0, 0.26, 0.05, 0.05, scale(COBBLE, 0.85));
  // stalls, only on market day
  k.tagged(Vis.Market, () => {
    const colours = [0xe2412f, 0x2f7fb5, 0x3f9b4a, 0xf2a93b];
    for (let z = -D / 2 + 0.55; z < D / 2 - 0.3; z += 0.95) {
      for (let x = -W / 2 + 0.45; x < W / 2 - 0.3; x += 0.75) {
        if (Math.abs(x) < 0.35 && Math.abs(z) < 0.35) continue;
        const c = hex(colours[Math.floor(r() * colours.length)]);
        k.box(x, 0, z, 0.52, 0.18, 0.32, hex(0xd9cfb8));
        for (let i = 0; i < 3; i++) k.box(x - 0.16 + i * 0.16, 0.18, z + 0.04, 0.12, 0.04, 0.16, pick(r, [0xd8a742, 0x5f9e45, 0xe2412f, 0xf28c38]));
        k.gable(x, 0.34, z, 0.62, 0.14, 0.42, i2(c, x), c);
      }
    }
  });
};
/** Awnings stripe in their colour and white, stall by stall. */
const i2 = (c: RGB, x: number): RGB => (Math.round(x * 4) % 2 === 0 ? c : WHITE);

// ---- 16. lake park ---------------------------------------------------------------------------------------

const lakePark: Draw = (k, W, D, _b, r) => {
  // the perimeter path
  k.hoop(0, 0.004, 0, Math.min(W, D) / 2 - 0.25, 0.1, PATH, 20, 'xz');
  // three overlapping pools make one irregular pond
  const pools: [number, number, number, number][] = [[-0.12 * W, -0.05 * D, 0.26 * W, 0.24 * D], [0.14 * W, 0.08 * D, 0.2 * W, 0.2 * D], [0, -0.18 * D, 0.18 * W, 0.14 * D]];
  for (const [x, z, rx, rz] of pools) k.cyl(x, 0.002, z, rx + 0.12, 0.02, SAND, 16, SAND, rz + 0.12);
  for (const [x, z, rx, rz] of pools) k.cyl(x, 0.006, z, rx, 0.03, WATER, 16, WATER, rz);
  // the island and its willow
  k.cyl(-0.12 * W, 0.01, -0.05 * D, 0.3, 0.05, LAWN_MOWN, 10);
  k.box(-0.12 * W, 0.05, -0.05 * D, 0.06, 0.28, 0.06, TRUNK);
  k.dome(-0.12 * W, 0.18, -0.05 * D, 0.34, hex(0x86b85a), 10, 3);
  // a boardwalk across one arm
  k.box(0.14 * W, 0.06, 0.08 * D, 0.2, 0.03, 0.2 * D * 2.4, WOOD);
  // the boathouse hut on the shore
  const hx = -W / 2 + 0.6, hz = D / 2 - 0.7, wall = styleWall(r);
  k.box(hx, 0, hz, 0.46, 0.28, 0.4, wall);
  styledGable(k, r, hx, 0.28, hz, 0.52, 0.18, 0.46, styleRoof(r), wall);
  for (let i = 0; i < 6; i++) {
    const a = (i / 6) * TAU + r(), rr = Math.min(W, D) / 2 - 0.55;
    tree(k, Math.cos(a) * rr, 0, Math.sin(a) * rr, 0.9 + r() * 0.3, r() < 0.3);
  }
  for (let i = 0; i < 3; i++) bench(k, W / 2 - 0.5, -D / 3 + i * D / 3, true);
};

// ---- 17. courts --------------------------------------------------------------------------------------------

const courts: Draw = (k, W, D, _b, r) => {
  const tennis = r() < 0.55, surface = r() < 0.5 ? COURT_BLUE : CLAY;
  const cw = (W - 0.4) / 2 - 0.1, cd = D - 0.5;
  for (const s of [-1, 1]) {
    const cx = s * (cw / 2 + 0.1);
    k.box(cx, 0.004, 0, cw, 0.01, cd, surface);
    // lines: the outline and the centre
    for (const sz of [-1, 1]) k.box(cx, 0.012, sz * (cd / 2 - 0.1), cw - 0.2, 0.008, 0.025, WHITE);
    for (const sx of [-1, 1]) k.box(cx + sx * (cw / 2 - 0.1), 0.012, 0, 0.025, 0.008, cd - 0.2, WHITE);
    if (tennis) {
      k.box(cx, 0, 0, cw - 0.1, 0.1, 0.015, WHITE);
      k.box(cx, 0.012, 0, 0.025, 0.008, cd * 0.5, WHITE);
    } else {
      k.hoop(cx, 0.014, 0, 0.3, 0.012, WHITE, 12, 'xz');
      for (const sz of [-1, 1]) {
        k.box(cx, 0, sz * (cd / 2 - 0.15), 0.04, 0.34, 0.04, METAL);
        k.box(cx, 0.34, sz * (cd / 2 - 0.2), 0.14, 0.1, 0.02, WHITE);
      }
    }
  }
  fence(k, W, D, hex(0x4f6b4a), 0.3, 0.3);
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
    const x = sx * (W / 2 - 0.1), z = sz * (D / 2 - 0.1);
    k.box(x, 0, z, 0.04, 1.0, 0.04, METAL);
    k.glowBox(x, 1.0, z, 0.2, 0.08, 0.12, hex(0xeef2f5), [17.5, 22, 2.8], COOL_GLOW);
  }
};

// ---- 18. formal garden -------------------------------------------------------------------------------------

const formalGarden: Draw = (k, W, D, _b, r) => {
  path(k, -W / 2 + 0.1, 0, W / 2 - 0.1, 0, 0.2, GRAVEL);
  path(k, 0, -D / 2 + 0.1, 0, D / 2 - 0.1, 0.2, GRAVEL);
  path(k, -W / 2 + 0.2, -D / 2 + 0.2, W / 2 - 0.2, D / 2 - 0.2, 0.12, GRAVEL);
  path(k, -W / 2 + 0.2, D / 2 - 0.2, W / 2 - 0.2, -D / 2 + 0.2, 0.12, GRAVEL);
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
    const qx = sx * W / 4, qz = sz * D / 4, qw = W / 2 - 0.4, qd = D / 2 - 0.4;
    hedge(k, qx - qw / 2, qz - qd / 2, qx + qw / 2, qz - qd / 2);
    hedge(k, qx - qw / 2, qz + qd / 2, qx + qw / 2, qz + qd / 2);
    hedge(k, qx - qw / 2, qz - qd / 2, qx - qw / 2, qz + qd / 2);
    hedge(k, qx + qw / 2, qz - qd / 2, qx + qw / 2, qz + qd / 2);
    k.hoop(qx, 0, qz, Math.min(qw, qd) * 0.28, 0.035, HEDGE, 10, 'xz');
    k.box(qx, 0, qz, 0.04, 0.08, 0.04, TRUNK);
    k.cone(qx, 0.06, qz, 0.14, 0.42, scale(HEDGE, 1.1), 8);
    k.disc(qx + qw * 0.3, 0.006, qz, 0.08, hex(0xe86a92), 6);
  }
  const stone = pick(r, STONE);
  k.cyl(0, 0, 0, 0.16, 0.08, stone, 10);
  k.cyl(0, 0.08, 0, 0.06, 0.14, stone, 8);
  k.cyl(0, 0.22, 0, 0.12, 0.1, stone, 10);
};

// ---- 19. allotments ----------------------------------------------------------------------------------------

const allotments: Draw = (k, W, D, _b, r) => {
  const crops = [0x5f9e45, 0x8fbf4a, 0xb97c3f, 0x3f7d3a, 0xc9a44a];
  for (let z = -D / 2 + 0.45; z < D / 2 - 0.3; z += 0.42) {
    for (let x = -W / 2 + 0.4; x < W / 2 - 0.9; x += 0.55) {
      k.box(x, 0, z, 0.44, 0.06, 0.28, WOOD, hex(0x6b4a2a));
      const c = hex(crops[Math.floor(r() * crops.length)]);
      for (let i = 0; i < 4; i++) k.box(x - 0.15 + i * 0.1, 0.06, z, 0.05, 0.05 + r() * 0.04, 0.2, c);
    }
  }
  const shed = hex(0x6f8a6a);
  k.box(W / 2 - 0.45, 0, -D / 2 + 0.45, 0.46, 0.3, 0.4, shed);
  k.gable(W / 2 - 0.45, 0.3, -D / 2 + 0.45, 0.52, 0.12, 0.46, hex(0x4a4f55), shed);
  k.cyl(W / 2 - 0.45, 0, -D / 2 + 0.85, 0.08, 0.16, hex(0x3f6b4a), 8);
  // the scarecrow
  const sx = W / 2 - 0.5, sz = D / 4;
  k.box(sx, 0, sz, 0.02, 0.36, 0.02, WOOD);
  k.box(sx, 0.26, sz, 0.26, 0.02, 0.02, WOOD);
  k.box(sx, 0.22, sz, 0.1, 0.1, 0.04, hex(0x3f5a73));
  k.dome(sx, 0.36, sz, 0.04, hex(0xe9d9a6), 6, 2);
  fence(k, W, D, WHITE, 0.1, 0.34);
};

// ---- 20. botanical garden -----------------------------------------------------------------------------------

const botanicalGarden: Draw = (k, W, D, b, r) => {
  const beds = [0xe86a92, 0xf2a93b, 0xb07ad8, 0xe2412f, 0xf2c14e];
  for (let i = 0; i < 7; i++) {
    const a = (i / 7) * TAU + r(), rr = Math.min(W, D) * (0.3 + r() * 0.12);
    k.disc(Math.cos(a) * rr, 0.004, Math.sin(a) * rr + 0.3, 0.3 + r() * 0.2, hex(beds[i % beds.length]), 9, 0.18);
  }
  // exotic trees in colours no biome grows
  for (let i = 0; i < 6; i++) {
    const x = (r() - 0.5) * (W - 0.8), z = D / 2 - 0.5 - r() * (D * 0.4);
    if (r() < 0.5) {
      k.box(x, 0, z, 0.05, 0.5, 0.05, TRUNK);
      for (let f = 0; f < 5; f++) { const a = (f / 5) * TAU; k.bar([x, 0.5, z], [x + Math.cos(a) * 0.3, 0.38, z + Math.sin(a) * 0.3], 0.03, hex(0x3f9b4a)); }
    } else {
      k.box(x, 0, z, 0.05, 0.25, 0.05, TRUNK);
      k.dome(x, 0.22, z, 0.24, pick(r, [0xb07ad8, 0xf28c38, 0x2bb3a3, 0xe86a92]), 8, 3);
    }
  }
  // the glasshouse: a glass dome in a classic town, otherwise a long glass house on a low wall
  const gz = -D / 2 + 1.2, glass = hex(0xbfe2ea);
  if (b.seed % 2 === 0) {
    k.cyl(0, 0, gz, 0.95, 0.18, pick(r, STONE), 16);
    k.dome(0, 0.18, gz, 0.9, glass, 14, 5);
    k.glowBox(0, 0.2, gz, 1.0, 0.5, 1.0, glass, [17, 23, 1.2], COOL_GLOW);
  } else {
    k.box(0, 0, gz, 2, 0.14, 1.2, pick(r, STONE));
    k.box(0, 0.14, gz, 1.94, 0.4, 1.14, glass);
    k.gable(0, 0.54, gz, 1.96, 0.36, 1.16, glass, glass);
    k.glowBox(0, 0.16, gz, 1.8, 0.36, 1.0, glass, [17, 23, 1.2], COOL_GLOW);
  }
  // the tea kiosk
  k.box(W / 2 - 0.4, 0, D / 2 - 0.4, 0.34, 0.24, 0.3, styleWall(r));
  k.hip(W / 2 - 0.4, 0.24, D / 2 - 0.4, 0.42, 0.12, 0.38, styleRoof(r));
};

// ---- 21. playground ------------------------------------------------------------------------------------------

/**
 * A town playground: a soft surface (rubber crumb, bark or sand) inside a low fence, three to five pieces of
 * seed-picked equipment in one of the play palettes (playKit.ts), a paved way in from the gate and a bench or
 * two for the parents. A few children play there after school, and all day at weekends and in the summer.
 */
const playground: Draw = (k, W, D, b, r, t) => jungleGyms(k, W, D, b, r, t);

const jungleGyms: Draw = (k, W, D, _b, r) => {
  const pal = pickPalette(r), surf = pickSurface(r);
  const fenceTone = r() < 0.5 ? pick(r, [0x2f3a33, 0x3a3f45, 0x2f4d3a]) : pal.frame;
  // the play ground inside the fence, leaving a paved strip along the front for the benches: all soft
  // surface, or a mown lawn with a soft pad under each piece
  const z0 = -D / 2 + 0.14, z1 = D / 2 - 0.44, sz = (z0 + z1) / 2, sd = z1 - z0, lawn = r() < 0.5;
  k.box(0, 0, sz, W - 0.3, 0.006, sd, lawn ? LAWN_MOWN : surf);
  path(k, 0, D / 2 - 0.08, 0, z1, 0.26, PATH);
  k.box(0, 0, D / 2 - 0.27, W - 0.3, 0.006, 0.3, GRAVEL);
  const area = W * D, rects: { x: number; z: number; w: number; d: number }[] = [];
  const spots = playEquipment(k, 0, sz, W - 0.42, sd - 0.12, r, pal, area >= 9 ? 7 : area >= 6 ? 6 : 4, area >= 9 ? 5 : area >= 6 ? 4 : 3, rects);
  if (lawn) for (const q of rects) k.box(q.x, 0, q.z, q.w + 0.06, 0.012, q.d + 0.06, surf);
  // benches facing in, a bin, and a tree or two where nothing stands
  const bx = Math.min(0.75, W / 2 - 0.4);
  playBench(k, -bx, D / 2 - 0.22, Math.PI);
  if (r() < 0.6) playBench(k, bx, D / 2 - 0.22, Math.PI);
  k.cyl(bx * (r() < 0.5 ? 0.5 : -0.5), 0, D / 2 - 0.2, 0.025, 0.06, DARK, 6);
  for (let n = lawn ? 3 : 1, tries = 0; n > 0 && tries < 12; tries++) {
    const tx = (r() - 0.5) * (W - 0.6), tz = sz + (r() - 0.5) * (sd - 0.4);
    if (rects.some((q) => Math.abs(tx - q.x) < q.w / 2 + 0.2 && Math.abs(tz - q.z) < q.d / 2 + 0.2)) continue;
    tree(k, tx, 0, tz, 0.6 + r() * 0.2, false);
    n--;
  }
  fence(k, W, D, fenceTone, 0.12, 0.3);
  // children: after school on a school day, nine till seven at weekends and in the holidays
  kidsRig(k, {
    spots, run: [{ x: 0, z: sz, w: W - 0.5, d: sd - 0.2 }], parts: 2 + Math.floor(r() * 3),
    when: (h) => (schoolDay() ? (h >= 16 && h < 19 ? 'play' : null) : h >= 9 && h < 19 ? 'play' : null),
  }, r);
};

// ---- 22. grove -------------------------------------------------------------------------------------------------

const grove: Draw = (k, W, D, _b, r) => {
  // bluebells: a wash of colour under the trees
  for (let n = 0; n < W * D * 0.6; n++) k.disc((r() - 0.5) * (W - 0.4), 0.004, (r() - 0.5) * (D - 0.4), 0.2 + r() * 0.15, hex(0x8a7fd0), 7);
  const trees = Math.floor(W * D * 0.6);
  const benchAt: [number, number] = [(r() - 0.5) * (W - 1), (r() - 0.5) * (D - 1)];
  for (let n = 0; n < trees; n++) {
    const x = (r() - 0.5) * (W - 0.4), z = (r() - 0.5) * (D - 0.4);
    if (Math.hypot(x - benchAt[0], z - benchAt[1]) < 0.35) continue;
    tree(k, x, 0, z, 0.9 + r() * 0.5, r() < 0.35);
  }
  bench(k, benchAt[0], benchAt[1]);
};

export const OPEN_DRAW: Record<OpenKind, Draw> = {
  meadow, civicSquare, fountainSquare, greenway, picnicGround, dogRun, plazaSteps, sculpturePark, bandstandGreen,
  memorial, skatePark, promenade, cemetery, amphitheatre, marketSquare, lakePark, courts, formalGarden, allotments,
  botanicalGarden, playground, grove, greatPark,
};

/** Every open-space kind, most open first: the ladder from meadow to grove. */
export const OPEN_KINDS = Object.keys(OPEN_DRAW) as BuildingKind[];
