/**
 * The places people work and play that are not towns: rock quarries cut into a mountainside, ski
 * fields on the snow above them, and airfields on the flat ground below.
 *
 * Terrain first, structures later. Every site is chosen and carved in `growWorks`, which runs while
 * the elevation field is still a float array; the buildings are placed afterwards in `buildWorks`,
 * once the per-tile corners exist and a lot can be levelled the same way a town's is.
 */

import {
  N, SEA, STEP, Biome, Feature, Flag, Lot, World, DIRS, idx, inB,
  type Building, type Work, type WorkKind,
} from './tiles';
import { solidMask } from './footprint';
import { buildingHeight } from './towns';
import { hashString, mulberry32, type Rng } from './rng';
import { NEXT_WORLD } from './nextWorld';
import { PLAN_SIDE, planBuildings, planCentre, planGate, planRects, planTiles, type AirportPlan } from './airportPlans';
import { MINE_CHANCE, MINE_TEST, planMine, type MineKind, type MineLot } from './mines';
import { RESORT_DROP, RESORT_TOP, buildLifts, gradeRun, planLifts, planResort, roughLine, type LiftPlan, type LodgePlan } from './skiFields';

/** A chosen site, carved into the ground but not yet built on. */
export interface WorkSite {
  kind: WorkKind;
  name: string;
  x: number; z: number;       // centre tile of the built part
  level: number;              // the level its pad was cut to, in steps
  facing: number;             // DIRS index the plant or terminal looks along
  major: boolean;
  len: number; half: number;  // the long axis and half-width of the works, in tiles
  /** Pylon tops for a chairlift or a conveyor, in tiles and steps. */
  cable: { x: number; z: number; level: number }[];
  /** Where a road should meet the site. */
  gate: number;
  /** A wonder's one building: its kind and lot, already levelled and claimed. */
  lot?: { kind: Building['kind']; x: number; z: number; w: number; d: number };
  /** A ski field's lifts, planned with their runs cut (world/skiFields.ts). */
  ski?: LiftPlan[];
  /** A two-runway international's layout (world/airportPlans.ts, 0.7.0). */
  plan?: AirportPlan;
  /** A ski resort (0.7.0) and the lodges up its mountain, levelled already (world/skiFields.ts planResort). */
  resort?: boolean;
  lodges?: LodgePlan[];
  /** A mine (0.7.0): which kind, and the lots of its buildings (world/mines.ts). */
  mine?: MineKind;
  lots?: MineLot[];
}

const QUARRY_NAME = ['Ironstone', 'Greyfell', 'Slatehead', 'Millstone', 'Coldbeck', 'Brackencut', 'Hollowpit'];
const SKI_NAME = ['Whiteharrow', 'Cirrus', 'Snowfell', 'Highcairn', 'Silverpine', 'Frostmoor'];
const AIR_NAME = ['Meridian', 'Northreach', 'Calder', 'Halcyon', 'Sable', 'Westgate'];

/**
 * On a continent, nothing carved into the ground may come within this many tiles of a border the
 * neighbouring cell works out for itself. Set for the duration of `growWorks`; zero on an island,
 * whose borders are open sea and agreed on already.
 */
let keepOut = 0;
/** Is (x, z), with `extra` tiles of workings around it, clear of the seam band and of every causeway? */
const clearOfSeam = (x: number, z: number, extra: number): boolean =>
  (keepOut === 0 || (x >= keepOut + extra && z >= keepOut + extra && x < N - keepOut - extra && z < N - keepOut - extra)) &&
  (!causewayGap || !inB(x, z) || causewayGap[idx(x, z)] >= extra + CAUSEWAY_CLEAR);
/** How far every tile is from a causeway (capped), or null when there is none. */
let causewayGap: Uint8Array | null = null;
/** Tiles kept between a causeway and the reach of any work's own margin, so no pit or apron is levelled over its landing. */
const CAUSEWAY_CLEAR = 18;

/** Flatten a rectangle of the elevation field to one level, easing the ground around it. */
function levelRect(E: Float32Array, land: Uint8Array, x0: number, z0: number, wx: number, wz: number, level: number, skirt = 3): void {
  for (let z = z0 - skirt; z < z0 + wz + skirt; z++) {
    for (let x = x0 - skirt; x < x0 + wx + skirt; x++) {
      if (!inB(x, z)) continue;
      const i = idx(x, z);
      if (!land[i]) continue;
      const out = Math.max(0, x0 - x, x - (x0 + wx - 1), z0 - z, z - (z0 + wz - 1));
      if (out === 0) E[i] = level;
      else E[i] = E[i] + (level - E[i]) * (1 - out / (skirt + 1));
    }
  }
}

/** The mean and spread of the ground over a rectangle, or null if any of it is unusable. */
function survey(
  w: World, land: Uint8Array, E: Float32Array, river: Uint8Array,
  x0: number, z0: number, wx: number, wz: number,
): { mean: number; spread: number } | null {
  let lo = Infinity, hi = -Infinity, sum = 0, n = 0;
  for (let z = z0; z < z0 + wz; z++) {
    for (let x = x0; x < x0 + wx; x++) {
      if (!inB(x, z)) return null;
      const i = idx(x, z);
      if (!land[i] || river[i] || w.biome[i] === Biome.Town) return null;
      if (w.feature[i] !== Feature.None || (w.flags[i] & Flag.Field)) return null;
      const e = E[i];
      if (e < lo) lo = e;
      if (e > hi) hi = e;
      sum += e; n++;
    }
  }
  return n ? { mean: sum / n, spread: hi - lo } : null;
}

// ---------------------------------------------------------------------------------------------
// quarries

/**
 * A quarry is a bowl of benches cut into a hillside: two steps down per terrace toward a flat
 * floor, with a gravel apron on the downhill side where the crusher and the hoppers stand.
 */
function cutQuarry(w: World, land: Uint8Array, E: Float32Array, river: Uint8Array, rng: Rng, made: WorkSite[]): boolean {
  const NN = N * N;
  const cands: number[] = [];
  for (let i = 0; i < NN; i++) {
    if (!land[i] || river[i]) continue;
    const b = w.biome[i];
    if (b !== Biome.Mountain && b !== Biome.Hills) continue;
    if (E[i] < 10 || E[i] > 28 || w.coastDist[i] < 8) continue;
    if (w.biome[i] === Biome.Town || w.feature[i] !== Feature.None) continue;
    if (!clearOfSeam(i % N, Math.floor(i / N), 16)) continue;
    cands.push(i);
  }
  if (!cands.length) return false;

  for (let tries = 0; tries < 160; tries++) {
    const seed = cands[Math.floor(rng() * cands.length)];
    const sx = seed % N, sz = (seed - sx) / N;
    if (made.some((q) => Math.hypot(q.x - sx, q.z - sz) < 60)) continue;
    const r = 8 + Math.floor(rng() * 3);
    // the pit needs a downhill side to open onto, or the plant has nowhere to stand
    let dir = -1, drop = 0;
    for (let d = 0; d < 4; d++) {
      const nx = sx + DIRS[d][0] * (r + 4), nz = sz + DIRS[d][1] * (r + 4);
      if (!inB(nx, nz)) continue;
      const j = idx(nx, nz);
      if (!land[j]) continue;
      const fall = E[seed] - E[j];
      if (fall > drop) { drop = fall; dir = d; }
    }
    if (dir < 0 || drop < 3) continue;
    // there has to be enough rock above the floor to be worth quarrying
    let high = -Infinity;
    for (let dz = -r; dz <= r; dz++) for (let dx = -r; dx <= r; dx++) {
      if (!inB(sx + dx, sz + dz)) continue;
      const j = idx(sx + dx, sz + dz);
      if (land[j] && E[j] > high) high = E[j];
    }
    const floor = Math.max(SEA + 2, Math.round(E[seed]) - 6);
    if (high < floor + 7) continue;
    const tiles: number[] = [];
    for (let dz = -r - 1; dz <= r + 1; dz++) {
      for (let dx = -r - 1; dx <= r + 1; dx++) {
        const x = sx + dx, z = sz + dz;
        if (!inB(x, z)) continue;
        const i = idx(x, z);
        if (!land[i] || river[i] || w.biome[i] === Biome.Town || w.feature[i] !== Feature.None) continue;
        const d = Math.hypot(dx, dz);
        if (d > r + 1) continue;
        // each bench is two steps above the one inside it, cut square into the slope
        const bench = Math.max(0, Math.floor((d - 1) / 2));
        const want = floor + bench * 2;
        E[i] = Math.min(E[i], want);
        w.feature[i] = Feature.Quarry;
        w.cleared[i] = 1;                    // nothing grows on a working face
        tiles.push(i);
      }
    }
    if (tiles.length < 60) {
      for (const i of tiles) { w.feature[i] = Feature.None; w.cleared[i] = 0; }
      continue;
    }

    // the apron: a flat shelf just outside the pit on the downhill side
    const [ax, az] = DIRS[dir];
    const px = sx + ax * (r + 3), pz = sz + az * (r + 3);
    const pad = 5;
    levelRect(E, land, px - pad, pz - pad, pad * 2 + 1, pad * 2 + 1, floor + 2, 3);
    for (let dz = -pad; dz <= pad; dz++) {
      for (let dx = -pad; dx <= pad; dx++) {
        if (!inB(px + dx, pz + dz)) continue;
        const i = idx(px + dx, pz + dz);
        if (!land[i]) continue;
        w.feature[i] = Feature.Quarry;
        w.cleared[i] = 1;
      }
    }

    // the conveyor: a short steep belt off the pit floor into the top of the hopper
    const cable: { x: number; z: number; level: number }[] = [];
    for (let k = 0; k <= 2; k++) {
      const t = k / 2;
      const reach = 7 - t * 5;
      cable.push({
        x: px - ax * reach + 0.5,
        z: pz - az * reach + 0.5,
        level: floor + 0.6 + t * 4.2,
      });
    }

    made.push({
      kind: 'quarry',
      name: `${QUARRY_NAME[Math.floor(rng() * QUARRY_NAME.length)]} Quarry`,
      x: px, z: pz, level: floor + 2, facing: (dir + 2) & 3, major: false,
      len: r * 2, half: r, cable, gate: idx(px, pz),
    });
    w.spots.push({ kind: 'quarry', name: made[made.length - 1].name, x: sx + 0.5, z: sz + 0.5, r });
    return true;
  }
  return false;
}

// ---------------------------------------------------------------------------------------------
// ski fields

/**
 * A piste is a corridor of groomed snow running down the fall line of a high mountain, eased to a
 * steady gradient so it can actually be skied, with a lodge at the bottom and a chairlift back up.
 */
function cutPiste(w: World, land: Uint8Array, E: Float32Array, river: Uint8Array, rng: Rng, made: WorkSite[], resort = false): boolean {
  const NN = N * N;
  const tops: number[] = [];
  for (let i = 0; i < NN; i++) {
    if (!land[i] || river[i] || w.feature[i] !== Feature.None) continue;
    const b = w.biome[i];
    if (E[i] < (resort ? RESORT_TOP : 14) || (b !== Biome.Snow && b !== Biome.Mountain)) continue;
    if (!clearOfSeam(i % N, Math.floor(i / N), 8)) continue;
    tops.push(i);
  }
  if (!tops.length) return false;

  for (let tries = 0; tries < 120; tries++) {
    const seed = tops[Math.floor(rng() * tops.length)];
    let x = seed % N, z = (seed - x) / N;
    if (made.some((s) => s.kind === 'ski' && Math.hypot(s.x - x, s.z - z) < 70)) continue;

    // follow the steepest descent to the foot of the mountain
    const path: number[] = [idx(x, z)];
    for (let k = 0; k < (resort ? 140 : 90); k++) {
      let best = -1, bx = x, bz = z, bestE = E[idx(x, z)];
      for (let dz = -1; dz <= 1; dz++) for (let dx = -1; dx <= 1; dx++) {
        if (!dx && !dz) continue;
        const nx = x + dx, nz = z + dz;
        if (!inB(nx, nz)) continue;
        const j = idx(nx, nz);
        if (!land[j] || river[j] || w.biome[j] === Biome.Town || w.feature[j] !== Feature.None) continue;
        if (resort && w.biome[j] === Biome.Ocean) continue;   // a resort's run never ends in a lake dug already
        if (!clearOfSeam(nx, nz, 8)) continue;   // a run that would reach the seam simply stops short
        if (E[j] < bestE) { bestE = E[j]; best = j; bx = nx; bz = nz; }
      }
      if (best < 0) break;
      x = bx; z = bz;
      path.push(best);
      if (E[best] < SEA + 6) break;
    }
    if (path.length < (resort ? 30 : 26)) continue;
    const drop = E[path[0]] - E[path[path.length - 1]];
    if (drop < (resort ? RESORT_DROP : 10)) continue;
    // the first lift will run straight up beside it, foot to top: there has to be open country for that
    if (!roughLine(w, land, E, river, path)) continue;
    // a resort's run often ends in a high valley's hollow, which would fill with a lake: its pad is raised to the
    // hollow's lip, so no water stands over it (and a deep bowl is passed over)
    // (a resort's attempt is undone if it is passed over below: the ground, the pistes and the clearings put back)
    const undo = resort ? { E: E.slice(), feature: w.feature.slice(), cleared: w.cleared.slice() } : null;
    if (resort) {
      const foot = path[path.length - 1], lip = spillOf(E, land, foot);
      if (lip - E[foot] > 6) continue;
      E[foot] = Math.max(E[foot], lip + 0.5);
    }

    // a steady gradient from top to bottom, and a corridor either side of the line
    const lo = E[path[path.length - 1]];
    const half = 3;
    gradeRun(w, land, river, E, path, half);

    const foot = path[path.length - 1], head = path[0];
    const fx = foot % N, fz = (foot - (foot % N)) / N;
    const hx = head % N, hz = (head - (head % N)) / N;
    const base = Math.round(lo);
    levelRect(E, land, fx - 5, fz - 5, 11, 11, base, 3);
    for (let dz = -5; dz <= 5; dz++) for (let dx = -5; dx <= 5; dx++) {
      if (!inB(fx + dx, fz + dz)) continue;
      const i = idx(fx + dx, fz + dz);
      if (land[i]) { w.feature[i] = Feature.Piste; w.cleared[i] = 1; }
    }

    // the lifts: straight cables fanned out from the pad's uphill edge, each to a top with a run back down
    // (world/skiFields.ts), from a generator of their own so nothing else on the island shifts
    const lifts = planLifts(w, land, E, river, mulberry32((foot * 2654435761) ^ (head * 40503) ^ 0x5c1f1e1d), path, drop > 16,
      (x, z) => {
        const i = idx(x, z);
        return !!land[i] && !river[i] && w.biome[i] !== Biome.Town && !(resort && w.biome[i] === Biome.Ocean) && (w.feature[i] === Feature.None || w.feature[i] === Feature.Piste) && clearOfSeam(x, z, 8);
      },
      (x0, z0, wx, wz, lv, skirt) => levelRect(E, land, x0, z0, wx, wz, lv, skirt), resort);
    // (a resort is a big field: a top with room for fewer than three lifts is passed over for another)
    if (!lifts.length || (resort && lifts.length < 3)) {
      if (undo) { E.set(undo.E); w.feature.set(undo.feature); w.cleared.set(undo.cleared); }
      continue;
    }
    // a resort's other runs, its lodges up the mountain and the woods between its runs
    const lodges = resort ? planResort(w, land, E, river, mulberry32((foot * 40503) ^ (head * 2654435761) ^ 0x2e5027), lifts, fx, fz,
      (x, z) => {
        const i = idx(x, z);
        return !!land[i] && !river[i] && w.biome[i] !== Biome.Town && !(resort && w.biome[i] === Biome.Ocean) && (w.feature[i] === Feature.None || w.feature[i] === Feature.Piste) && clearOfSeam(x, z, 8);
      },
      (x0, z0, wx, wz, lv, skirt) => levelRect(E, land, x0, z0, wx, wz, lv, skirt)) : undefined;
    const cable: { x: number; z: number; level: number }[] = [];

    let ni = Math.floor(rng() * SKI_NAME.length);
    // 0.7.0: never two fields of one name in a county (a resort and an ordinary field came out alike)
    if (NEXT_WORLD) for (let t = 0; t < SKI_NAME.length && made.some((m) => m.name.startsWith(`${SKI_NAME[ni]} `)); t++) ni = (ni + 1) % SKI_NAME.length;
    const name = `${SKI_NAME[ni]} ${resort ? 'Ski Resort' : 'Ski Field'}`;
    made.push({
      kind: 'ski', name, x: fx, z: fz, level: base,
      facing: Math.abs(hx - fx) > Math.abs(hz - fz) ? (hx > fx ? 0 : 2) : (hz > fz ? 1 : 3),
      major: drop > 16, len: path.length, half, cable, gate: foot, ski: lifts, ...(resort ? { resort, lodges } : {}),
    });
    w.spots.push({ kind: 'ski', name, x: fx + 0.5, z: fz + 0.5, r: 9 });
    return true;
  }
  return false;
}

/** The level a hollow at tile `from` fills to before it spills (steps): the lowest lip on a way out, its own height where it drains, Infinity for a wide basin. */
function spillOf(E: Float32Array, land: Uint8Array, from: number, reach = 14): number {
  const fx = from % N, fz = (from - fx) / N, e0 = E[from];
  const seen = new Set<number>([from]);
  const open = [from];
  let level = e0;
  for (let pops = 0; pops < 1500 && open.length; pops++) {
    let k = 0;
    for (let j = 1; j < open.length; j++) if (E[open[j]] < E[open[k]]) k = j;
    const i = open[k];
    open[k] = open[open.length - 1];
    open.pop();
    level = Math.max(level, E[i]);
    const x = i % N, z = (i - x) / N;
    if (E[i] < e0 - 0.01 || !land[i]) return level;
    // a basin wider than this is a valley lake: no pad goes in it
    if (Math.hypot(x - fx, z - fz) > reach) return Infinity;
    for (let dz = -1; dz <= 1; dz++) for (let dx = -1; dx <= 1; dx++) {
      if ((!dx && !dz) || !inB(x + dx, z + dz)) continue;
      const j = idx(x + dx, z + dz);
      if (!seen.has(j)) { seen.add(j); open.push(j); }
    }
  }
  return level;
}

// ---------------------------------------------------------------------------------------------
// airfields

/** A municipal strip is one runway and a couple of hangars; an international one is much bigger. */
function cutAirfield(w: World, land: Uint8Array, E: Float32Array, river: Uint8Array, rng: Rng, made: WorkSite[], major: boolean): boolean {
  // the next world: two internationals in three have a second runway, crossing the first or meeting it at a corner
  if (major && NEXT_WORLD) {
    const shape = twinShape(w);
    if (shape && (cutTwin(w, land, E, river, rng, made, shape) || cutTwin(w, land, E, river, rng, made, shape === 'X' ? 'L' : 'X'))) return true;
  }
  const len = major ? 48 : 26;
  const wid = major ? 5 : 3;
  const apron = major ? 12 : 6;
  const depth = wid + apron;

  let best: { x: number; z: number; alongX: boolean; level: number; score: number } | null = major ? scanSite(w, land, E, river, len, depth) : null;
  for (let tries = 0; tries < (major ? 0 : 900); tries++) {
    const alongX = rng() < 0.5;
    const bw = alongX ? len : depth, bd = alongX ? depth : len;
    const lo = 6 + keepOut;
    const x0 = lo + Math.floor(rng() * Math.max(1, N - 2 * lo - bw));
    const z0 = lo + Math.floor(rng() * Math.max(1, N - 2 * lo - bd));
    if (!clearOfSeam(x0, z0, 6) || !clearOfSeam(x0 + bw, z0 + bd, 6)) continue;
    // survey the strip plus a margin, so an airport never lands in a town's lap
    const s = survey(w, land, E, river, x0 - 4, z0 - 4, bw + 8, bd + 8);
    if (!s || s.spread > (major ? 9 : 6)) continue;
    if (s.mean < SEA + 1.5) continue;
    const cx = x0 + bw / 2, cz = z0 + bd / 2;
    if (made.some((a) => a.kind === 'airfield' && Math.hypot(a.x - cx, a.z - cz) < 90)) continue;
    const score = -s.spread;
    if (!best || score > best.score) best = { x: x0, z: z0, alongX, level: Math.round(s.mean), score };
    if (s.spread < 1.5) break;
  }
  if (!best) return false;

  const { x: x0, z: z0, alongX, level } = best;
  const bw = alongX ? len : depth, bd = alongX ? depth : len;
  levelRect(E, land, x0, z0, bw, bd, level, 5);

  // the strip itself down one side, the apron and buildings filling the rest
  for (let z = z0; z < z0 + bd; z++) {
    for (let x = x0; x < x0 + bw; x++) {
      const i = idx(x, z);
      if (!land[i]) continue;
      const across = alongX ? z - z0 : x - x0;
      const along = alongX ? x - x0 : z - z0;
      w.feature[i] = Feature.Airfield;
      w.cleared[i] = 1;
      w.biome[i] = Biome.Town;
      const edge = along < 2 || along >= len - 2;
      if (across < wid) {
        const mid = across === (wid >> 1);
        // a dashed centreline, and a paler bar across each threshold
        w.lot[i] = edge ? Lot.Paved : mid && along % 4 < 2 ? Lot.Paved : Lot.Runway;
      }
      else if (across < wid + 2) w.lot[i] = Lot.Gravel;
      else w.lot[i] = along > 3 && along < len - 3 ? Lot.Apron : Lot.Gravel;
    }
  }

  const cx = Math.round(x0 + bw / 2), cz = Math.round(z0 + bd / 2);
  const gateX = alongX ? cx : x0 + bw - 1;
  const gateZ = alongX ? z0 + bd - 1 : cz;
  const isle = w.name.split(' ')[0];
  made.push({
    kind: 'airfield',
    name: major ? `${AIR_NAME[Math.floor(rng() * AIR_NAME.length)]} International` : `${isle} Municipal Airport`,
    x: cx, z: cz, level, facing: alongX ? 1 : 0, major,
    len, half: wid, cable: [], gate: idx(gateX, gateZ),
  });
  return true;
}

/** Which two-runway layout a county's international is, if any (by the seed alone: no draw from the carving's rng). */
function twinShape(w: World): 'X' | 'L' | null {
  const h = hashString(`${w.seed}|${w.cx},${w.cz}|runways`) % 3;
  return h === 0 ? 'X' : h === 1 ? 'L' : null;
}

/**
 * A two-runway international (world/airportPlans.ts): the flattest place its runways and apron fit (scanTwin),
 * levelled and painted to the plan. None anywhere: the one-runway kind is tried instead. It draws the rng once,
 * for its name, as the one-runway kind does.
 */
function cutTwin(w: World, land: Uint8Array, E: Float32Array, river: Uint8Array, rng: Rng, made: WorkSite[], shape: 'X' | 'L'): boolean {
  const plan = scanTwin(w, land, E, river, shape);
  if (!plan) return false;
  const level = plan.level;
  for (const [x, z, wx, wz] of planRects(plan)) levelRect(E, land, x, z, wx, wz, level, 5);
  const LOTS = { runway: Lot.Runway, paved: Lot.Paved, gravel: Lot.Gravel, apron: Lot.Apron } as const;
  planTiles(plan, (x, z, t) => {
    const i = idx(x, z);
    if (t === 'none' || !land[i]) return;
    w.feature[i] = Feature.Airfield;
    w.cleared[i] = 1;
    w.biome[i] = Biome.Town;
    w.lot[i] = LOTS[t];
  });
  const [cx, cz] = planCentre(plan), [gx, gz] = planGate(plan);
  made.push({
    kind: 'airfield', name: `${AIR_NAME[Math.floor(rng() * AIR_NAME.length)]} International`,
    x: cx, z: cz, level, facing: 1, major: true, len: PLAN_SIDE, half: 5, cable: [], gate: idx(gx, gz),
    plan: { shape, x0: plan.x0, z0: plan.z0, fu: plan.fu, fv: plan.fv },
  });
  return true;
}

/**
 * A twin keeps a tile of clear ground round its runways and apron (the one-runway kind keeps INTL_MARGIN), and may be
 * cut into ground a little steeper (the one-runway kind's is 9 steps): its three pieces span much more of the county.
 */
const TWIN_MARGIN = 1, TWIN_SPREAD = 12;

/**
 * Where a two-runway international's plan fits (world/airportPlans.ts planRects: its two runways with their
 * taxiways, and its apron, each with INTL_MARGIN of clear ground round it; the ground between them is left as it
 * is), looked at everywhere the way scanSite looks, in all four mirrorings: the flattest wins, its level the mean.
 */
function scanTwin(w: World, land: Uint8Array, E: Float32Array, river: Uint8Array, shape: 'X' | 'L'): (AirportPlan & { level: number }) | null {
  const S = N + 1;
  const bad = new Int32Array(S * S);
  for (let z = 0; z < N; z++) {
    for (let x = 0; x < N; x++) {
      const i = idx(x, z);
      const b = !land[i] || river[i] || w.biome[i] === Biome.Town || w.feature[i] !== Feature.None || (w.flags[i] & Flag.Field) ? 1 : 0;
      bad[(z + 1) * S + x + 1] = b + bad[z * S + x + 1] + bad[(z + 1) * S + x] - bad[z * S + x];
    }
  }
  const blocked = (x0: number, z0: number, wx: number, wz: number) =>
    x0 < 0 || z0 < 0 || x0 + wx > N || z0 + wz > N ? 1 : bad[(z0 + wz) * S + x0 + wx] - bad[z0 * S + x0 + wx] - bad[(z0 + wz) * S + x0] + bad[z0 * S + x0];
  const m = TWIN_MARGIN, lo = 6 + keepOut;
  let best: (AirportPlan & { level: number }) | null = null, bestSpread = Infinity;
  for (let z0 = lo; z0 + PLAN_SIDE <= N - lo; z0 += 2) {
    for (let x0 = lo; x0 + PLAN_SIDE <= N - lo; x0 += 2) {
      if (!clearOfSeam(x0, z0, 6) || !clearOfSeam(x0 + PLAN_SIDE, z0 + PLAN_SIDE, 6)) continue;
      for (let f = 0; f < 4; f++) {
        const p: AirportPlan = { shape, x0, z0, fu: (f & 1) === 1, fv: (f & 2) === 2 };
        const rects = planRects(p);
        if (rects.some(([x, z, wx, wz]) => blocked(x - m, z - m, wx + 2 * m, wz + 2 * m))) continue;
        // (every tile of them is usable: the summed table said so) the ground's lowest, highest and mean over all three
        let lo2 = Infinity, hi = -Infinity, sum = 0, n = 0;
        for (const [x, z, wx, wz] of rects) {
          for (let zz = z - m; zz < z + wz + m; zz++) for (let xx = x - m; xx < x + wx + m; xx++) {
            const e = E[idx(xx, zz)];
            if (e < lo2) lo2 = e;
            if (e > hi) hi = e;
            sum += e; n++;
          }
        }
        const spread = hi - lo2, mean = sum / n;
        if (spread > TWIN_SPREAD || mean < SEA + 1.5 || spread >= bestSpread) continue;
        bestSpread = spread;
        best = { ...p, level: Math.round(mean) };
      }
    }
  }
  return best;
}

/** Tiles of clear ground an international keeps round its strip and apron, so it never lands in a town's lap. */
const INTL_MARGIN = 2;

/**
 * Every place an international's rectangle could go, looked at in turn rather than guessed at: a
 * summed table of unusable tiles (water, river, town, feature, field) answers each candidate at once,
 * and only the clear ones are surveyed for their slope. The flattest wins. A megalopolis county has so
 * little open ground left that random tries almost never found it (docs: 3 in 30 got one).
 */
function scanSite(w: World, land: Uint8Array, E: Float32Array, river: Uint8Array, len: number, depth: number): { x: number; z: number; alongX: boolean; level: number; score: number } | null {
  const S = N + 1;
  const bad = new Int32Array(S * S);
  for (let z = 0; z < N; z++) {
    for (let x = 0; x < N; x++) {
      const i = idx(x, z);
      const b = !land[i] || river[i] || w.biome[i] === Biome.Town || w.feature[i] !== Feature.None || (w.flags[i] & Flag.Field) ? 1 : 0;
      bad[(z + 1) * S + x + 1] = b + bad[z * S + x + 1] + bad[(z + 1) * S + x] - bad[z * S + x];
    }
  }
  const blocked = (x0: number, z0: number, wx: number, wz: number) =>
    bad[(z0 + wz) * S + x0 + wx] - bad[z0 * S + x0 + wx] - bad[(z0 + wz) * S + x0] + bad[z0 * S + x0];
  let best: { x: number; z: number; alongX: boolean; level: number; score: number } | null = null;
  const m = INTL_MARGIN;
  for (const alongX of [true, false]) {
    const bw = alongX ? len : depth, bd = alongX ? depth : len;
    const lo = 6 + keepOut;
    for (let z0 = lo; z0 + bd <= N - lo; z0 += 2) {
      for (let x0 = lo; x0 + bw <= N - lo; x0 += 2) {
        if (x0 - m < 0 || z0 - m < 0 || x0 + bw + m > N || z0 + bd + m > N) continue;
        if (blocked(x0 - m, z0 - m, bw + 2 * m, bd + 2 * m)) continue;
        if (!clearOfSeam(x0, z0, 6) || !clearOfSeam(x0 + bw, z0 + bd, 6)) continue;
        const s = survey(w, land, E, river, x0 - m, z0 - m, bw + 2 * m, bd + 2 * m);
        if (!s || s.spread > 9 || s.mean < SEA + 1.5) continue;
        const score = -s.spread;
        if (!best || score > best.score) best = { x: x0, z: z0, alongX, level: Math.round(s.mean), score };
      }
    }
  }
  return best;
}

/** Set the seam band and the causeway clearance the carving keeps to, for this island. */
function setBounds(band: number, causeway?: Uint8Array): void {
  keepOut = band;
  causewayGap = null;
  if (causeway?.some((v) => v)) {
    const gap = new Uint8Array(N * N).fill(255);
    const queue: number[] = [];
    for (let i = 0; i < N * N; i++) if (causeway[i]) { gap[i] = 0; queue.push(i); }
    for (let q = 0; q < queue.length; q++) {
      const i = queue[q], x = i % N, z = (i - x) / N;
      if (gap[i] >= 64) continue;
      for (const [dx, dz] of DIRS) {
        if (!inB(x + dx, z + dz)) continue;
        const j = idx(x + dx, z + dz);
        if (gap[j] > gap[i] + 1) { gap[j] = gap[i] + 1; queue.push(j); }
      }
    }
    causewayGap = gap;
  }
}

/**
 * The international airport of a megalopolis county, carved before the farms are laid out: the city
 * has already taken most of the flat ground, and a runway this long needs the pick of what is left.
 * Returns its site for growWorks to carry on from, or null where there is nowhere flat enough.
 */
export function growIntl(w: World, land: Uint8Array, E: Float32Array, river: Uint8Array, rng: Rng, band = 0, causeway?: Uint8Array): WorkSite | null {
  setBounds(band, causeway);
  const made: WorkSite[] = [];
  return cutAirfield(w, land, E, river, rng, made, true) ? made[0] : null;
}

// ---------------------------------------------------------------------------------------------

/**
 * Carve every quarry, ski field and airfield this island gets. Runs while the elevation field is
 * still floats, before the per-tile corners are rounded out of it.
 */
export function growWorks(
  w: World, land: Uint8Array, E: Float32Array, river: Uint8Array, rng: Rng,
  counts: { quarries: number; pistes: number; airfields: number }, band = 0, causeway?: Uint8Array,
  intl: WorkSite | null = null,
): WorkSite[] {
  setBounds(band, causeway);
  const made: WorkSite[] = intl ? [intl] : [];
  for (let k = 0; k < counts.quarries; k++) if (!cutQuarry(w, land, E, river, rng, made)) break;
  // 0.7.0: now and then a mine, bigger and rarer than a quarry, on a generator of its own (world/mines.ts)
  if (NEXT_WORLD && (hashString(`${w.cx},${w.cz}|mine`) / 2 ** 32 < MINE_CHANCE || MINE_TEST.kind)) {
    const m = planMine(w, land, E, river, mulberry32(hashString(`${w.cx},${w.cz}|mine|plan`)), made, clearOfSeam);
    if (m) made.push(m);
  }
  // 0.7.0: the high country's one ski resort, cut first so the ordinary fields keep their distance (its own generator)
  if (NEXT_WORLD) cutPiste(w, land, E, river, mulberry32(hashString(`${w.cx},${w.cz}|resort`)), made, true);
  for (let k = 0; k < counts.pistes; k++) if (!cutPiste(w, land, E, river, rng, made)) break;
  // an island with a megalopolis gets the one international airport, carved already (growIntl);
  // everywhere else makes do, and so does a megalopolis with nowhere flat enough for a runway that long
  let left = counts.airfields;
  if (left > 0 && intl) left--;
  for (let k = 0; k < left; k++) if (!cutAirfield(w, land, E, river, rng, made, false)) break;
  return made;
}

// ---------------------------------------------------------------------------------------------
// structures

/** Place one building on a site, levelling its footprint the way a town lot is levelled. */
function put(w: World, g: Work, kind: Building['kind'], x: number, z: number, wx: number, wz: number, facing: number, rng: Rng, floors = 1, solid = true, level = g.level): void {
  for (let zz = z; zz < z + wz; zz++) for (let xx = x; xx < x + wx; xx++) if (!inB(xx, zz)) return;
  const b: Building = {
    kind, x, z, w: wx, d: wz, facing, floors, seed: Math.floor(rng() * 2 ** 31),
    solid, level, uid: w.allBuildings.length,
  };
  w.allBuildings.push(b);
  g.buildings.push(b);
  const c = w.corners;
  const top = level * STEP + buildingHeight(b);
  const mask = solid ? solidMask(b) : null;
  // the Colossus's harbour holds sea between its moles: its seabed stays where it was
  const wet = kind === 'colossus';
  for (let zz = z; zz < z + wz; zz++) {
    for (let xx = x; xx < x + wx; xx++) {
      const i = idx(xx, zz);
      if (wet && w.biome[i] === Biome.Ocean) continue;
      if (mask && mask[(zz - z) * wx + xx - x]) { w.blocked[i] = 1; w.roof[i] = Math.max(w.roof[i], top); }
      c[i * 4] = c[i * 4 + 1] = c[i * 4 + 2] = c[i * 4 + 3] = level;
    }
  }
}

/**
 * Claim (Flag.Poi) every lot `buildWorks` will build on, before any road is routed (generate.ts runs this
 * ahead of the towns and their links). The roads were routed first and the works built over them after, so a
 * county road could run straight under a terminal or a hangar (the user, 7 Oct 2026). Mirrors buildWorks'
 * layout: change one, change the other (`npm run roadblocks` catches a miss). A site's gate stays open, as
 * its approach road leaves from there.
 */
export function reserveWorks(w: World, sites: WorkSite[]): void {
  const claim = (x: number, z: number, wx: number, wz: number) => {
    for (let zz = z; zz < z + wz; zz++) for (let xx = x; xx < x + wx; xx++) if (inB(xx, zz)) w.flags[idx(xx, zz)] |= Flag.Poi;
  };
  for (const s of sites) {
    const [fx, fz] = DIRS[s.facing];
    if ((s.kind === 'wonder' || s.kind === 'resort') && s.lot) claim(s.lot.x, s.lot.z, s.lot.w, s.lot.d);
    else if (s.kind === 'quarry') {
      claim(s.x - 2, s.z - 2, 4, 4);
      claim(s.x + fz * 3 - 1, s.z + fx * 3 - 1, 2, 2);
      claim(s.x - fx * 3 - 1, s.z - fz * 3 - 1, 2, 2);
      // the headframe goes up on a roll made while building: its lot is kept either way
      claim(s.x - fz * 5 - 1, s.z - fx * 5 - 1, 3, 3);
    } else if (s.kind === 'ski') {
      claim(s.x - 2, s.z - 2, 5, 3);
      if (s.major) claim(s.x - fz * 5 - 1, s.z - fx * 5 - 1, 2, 2);
      for (const p of s.ski ?? []) { claim(p.bx - 2, p.bz - 2, 5, 5); claim(p.tx - 2, p.tz - 2, 5, 5); }
      for (const l of s.lodges ?? []) claim(l.x - 1, l.z - 1, l.w + 2, l.d + 2);
    } else if (s.kind === 'mine') {
      for (const l of s.lots ?? []) claim(l.x, l.z, l.w, l.d);
    } else if (s.kind === 'airfield' && s.plan) {
      for (const b of planBuildings(s.plan)) claim(b.x, b.z, b.w, b.d);
    } else if (s.kind === 'airfield') {
      const across = s.half + 4;
      const tx = s.facing === 1 ? s.x - 5 : s.x + across - 2;
      const tz = s.facing === 1 ? s.z + across - 2 : s.z - 5;
      const long = s.facing === 1 ? [1, 0] : [0, 1];
      claim(tx, tz, s.facing === 1 ? 10 : 5, s.facing === 1 ? 5 : 10);
      claim(tx + long[0] * (s.major ? 13 : 7), tz + long[1] * (s.major ? 13 : 7), 3, 3);
      for (let k = 0; k < (s.major ? 4 : 2); k++) claim(tx - long[0] * (7 + k * 7), tz - long[1] * (7 + k * 7), s.facing === 1 ? 6 : 5, s.facing === 1 ? 5 : 6);
      if (NEXT_WORLD && s.major) claim(tx + long[0] * 17, tz + long[1] * 17, s.facing === 1 ? 3 : 2, s.facing === 1 ? 2 : 3);
    }
    if (s.gate >= 0 && s.gate < N * N) w.flags[s.gate] &= ~Flag.Poi;
  }
}

/** Stand the plant, the lodge and the terminals on the sites carved earlier. */
export function buildWorks(w: World, sites: WorkSite[], rng: Rng): void {
  for (const s of sites) {
    const g: Work = {
      kind: s.kind, name: s.name, x: s.x, z: s.z, level: s.level, facing: s.facing,
      major: s.major, buildings: [], cable: s.cable, gate: s.gate, ...(s.plan ? { plan: s.plan } : {}), ...(s.resort ? { resort: true } : {}), ...(s.mine ? { mine: s.mine } : {}),
    };
    w.works.push(g);
    const [fx, fz] = DIRS[s.facing];
    const back = s.facing;

    if ((s.kind === 'wonder' || s.kind === 'resort') && s.lot) {
      // the wonder stands on the lot it carved, facing the way the site was laid out
      const l = s.lot;
      put(w, g, l.kind, l.x, l.z, l.w, l.d, s.facing, rng);
    } else if (s.kind === 'mine') {
      // a mine's plant, cranes and huts where world/mines.ts laid them out
      for (const l of s.lots ?? []) put(w, g, l.kind, l.x, l.z, l.w, l.d, l.facing, rng, l.floors, l.solid, l.level);
    } else if (s.kind === 'quarry') {
      // the crusher on the apron, a silo beside it, and a weighbridge hut by the gate
      put(w, g, 'crusher', s.x - 2, s.z - 2, 4, 4, back, rng);
      put(w, g, 'shack', s.x + fz * 3 - 1, s.z + fx * 3 - 1, 2, 2, back, rng);
      put(w, g, 'crates', s.x - fx * 3 - 1, s.z - fz * 3 - 1, 2, 2, back, rng, 1, false);
      // two pits in five also sink a shaft: the headframe and its winding house stand across the apron
      if (rng() < 0.4) put(w, g, 'mineHeadframe', s.x - fz * 5 - 1, s.z - fx * 5 - 1, 3, 3, back, rng);
    } else if (s.kind === 'ski') {
      // the lodge in the middle of the pad, a lift station on its uphill edge for every lift fanned out from
      // it, and a station at the top of each, where the chairs turn round (world/skiFields.ts)
      put(w, g, 'lodge', s.x - 2, s.z - 2, 5, 3, s.facing, rng, s.resort ? 3 : 2);
      const plans = s.ski ?? [];
      const hx = s.x - fz * 5 - 1, hz = s.z - fx * 5 - 1;
      const clashes = plans.some((p) => [[p.bx, p.bz], [p.tx, p.tz]].some(([cx, cz]) => hx <= cx + 2 && cx - 2 <= hx + 1 && hz <= cz + 2 && cz - 2 <= hz + 1));
      if (s.major && !clashes) put(w, g, 'shack', hx, hz, 2, 2, s.facing, rng);
      buildLifts(w, g, plans, (kind, x, z, wx, wz, facing, floors, level) => put(w, g, kind, x, z, wx, wz, facing, rng, floors, true, level));
      // a resort's lodges up the mountain: a bigger one at the summit, a hut partway down
      for (const l of s.lodges ?? []) put(w, g, 'lodge', l.x, l.z, l.w, l.d, l.facing, rng, l.where === 'summit' ? 2 : 1, true, l.level);
    } else if (s.plan) {
      // a two-runway international: its apron's buildings, as its plan lays them (world/airportPlans.ts)
      for (const b of planBuildings(s.plan)) put(w, g, b.kind, b.x, b.z, b.w, b.d, b.facing, rng, b.floors, b.solid);
    } else {
      // an airfield: terminal in the middle of the apron, hangars and a tower along it
      const across = s.half + 4;
      const tx = s.facing === 1 ? s.x - 5 : s.x + across - 2;
      const tz = s.facing === 1 ? s.z + across - 2 : s.z - 5;
      const long = s.facing === 1 ? [1, 0] : [0, 1];
      put(w, g, 'terminal', tx, tz, s.facing === 1 ? 10 : 5, s.facing === 1 ? 5 : 10, (s.facing + 2) & 3, rng, s.major ? 2 : 1);
      put(w, g, 'controlTower', tx + long[0] * (s.major ? 13 : 7), tz + long[1] * (s.major ? 13 : 7), 3, 3, (s.facing + 2) & 3, rng, s.major ? 4 : 2);
      const hangars = s.major ? 4 : 2;
      for (let k = 0; k < hangars; k++) {
        put(w, g, 'hangar', tx - long[0] * (7 + k * 7), tz - long[1] * (7 + k * 7), s.facing === 1 ? 6 : 5, s.facing === 1 ? 5 : 6, (s.facing + 2) & 3, rng);
      }
      // 0.7.0 (docs/models070-audit.md): an international's fire station, past the tower (render/buildings/models070.ts)
      if (NEXT_WORLD && s.major) put(w, g, 'fire', tx + long[0] * 17, tz + long[1] * 17, s.facing === 1 ? 3 : 2, s.facing === 1 ? 2 : 3, (s.facing + 2) & 3, rng);
      const planes = s.major ? 4 : 2;
      for (let k = 0; k < planes; k++) {
        const ox = long[0] * (k * 6 - 3), oz = long[1] * (k * 6 - 3);
        put(w, g, 'airliner', s.x + ox - 2, s.z + oz - 2, 4, 4, s.facing, rng, s.major ? 2 : 1, false);
      }
    }
  }
}
