import { N, STEP, World, type CellKind, type LandformKind } from './tiles';
import { stampOf } from './atlas';
import { runwaysOf } from './runways';
import { municipalityOf } from './municipality';
import { digestOf, type TownDigest } from './townDigest';

/**
 * A county at a glance (the region map and the airport codes): what a cell looks like from high up,
 * small enough to keep dozens of and to post across from a worker. Built from a generated World —
 * the one in memory, or one the survey worker makes and throws away — so nothing here is new
 * generation and the world stays exactly the world.
 */

/** Tiles between the corners of the survey's height grid. */
export const SURVEY_STEP = 4;
/** Corners across the height grid: one more than the squares. */
export const SURVEY_G = N / SURVEY_STEP + 1;
/** Tiles to a pixel of the survey's colour map. */
export const SURVEY_PER = 2;
/** Pixels across the colour map. */
export const SURVEY_C = N / SURVEY_PER;

export interface SurveyAirport { name: string; major: boolean; x: number; z: number; y: number; heading: number; len: number }
/** Somewhere with a name worth a label: a town, a harbour, a wonder, a landform, an airport, a ski field. */
interface SurveySight {
  kind: 'town' | 'port' | 'wonder' | 'landform' | 'airport' | 'ski' | 'quarry' | 'beach';
  name: string;
  /** Local tiles, and the ground's height there in world units. */
  x: number; z: number; y: number;
  /** For a town: its id and kind (the atlas's own name for it wins when it has one); for a landform, which. */
  id?: number; sub?: string; big?: boolean;
  /** For a town: the style it builds in (the region map's Culture view). */
  style?: string;
}

export interface CellSurvey {
  cx: number; cz: number;
  kind: CellKind; name: string;
  /** Height at each grid corner in steps, water surfaces standing in for the bed under them. */
  h: Int8Array;
  /** Palette index per colour-map pixel (world/atlas.ts PALETTE). */
  col: Uint8Array;
  /** The world map's own 32 × 32 stamp, for the atlas when the cell has never been in memory. */
  stamp: Uint8Array;
  /** Every standing building as a box: x, z, w, d, top (world units), five floats each. */
  boxes: Float32Array;
  airports: SurveyAirport[];
  sights: SurveySight[];
  /** Which town answers for each patch of land (world/municipality.ts), for the territory layer. */
  muni: Int16Array;
  /** Each town in a few numbers (docs/townregister.html): the town register's Known scope. */
  towns: TownDigest[];
}

/** Corner (x, z) of the tile lattice, 0..N each way, in steps. */
function cornerAt(w: World, x: number, z: number): number {
  const tx = Math.min(N - 1, x), tz = Math.min(N - 1, z);
  const dx = x - tx, dz = z - tz;
  const k = dz ? (dx ? 2 : 3) : dx ? 1 : 0;
  return w.corners[(tz * N + tx) * 4 + k];
}

export function surveyOf(w: World): CellSurvey {
  const G = SURVEY_G;
  const h = new Int8Array(G * G);
  for (let j = 0; j < G; j++) {
    for (let i = 0; i < G; i++) {
      const x = i * SURVEY_STEP, z = j * SURVEY_STEP;
      let e = cornerAt(w, x, z);
      // water on any of the four tiles meeting here lifts the corner to its surface
      for (let dz = -1; dz <= 0; dz++) for (let dx = -1; dx <= 0; dx++) {
        const tx = x + dx, tz = z + dz;
        if (tx < 0 || tz < 0 || tx >= N || tz >= N) continue;
        const wl = w.water[tz * N + tx];
        if (wl > e) e = wl;
      }
      h[j * G + i] = e;
    }
  }

  const boxes: number[] = [];
  const push = (b: { x: number; z: number; w: number; d: number; floors: number; level: number; gone?: boolean }) => {
    if (b.gone || b.w <= 0 || b.d <= 0) return;
    const tx = Math.min(N - 1, Math.max(0, Math.floor(b.x + b.w / 2))), tz = Math.min(N - 1, Math.max(0, Math.floor(b.z + b.d / 2)));
    const roof = w.roof[tz * N + tx];
    const top = roof > 0 ? roof : b.level * STEP + Math.max(1, b.floors) * 0.9;
    boxes.push(b.x, b.z, b.w, b.d, top);
  };
  for (const b of w.allBuildings) if (b.solid) push(b);
  for (const b of w.countryside) if (b.solid) push(b);
  for (const g of w.works) for (const b of g.buildings) if (b.solid) push(b);

  const groundAt = (x: number, z: number) => cornerAt(w, Math.max(0, Math.min(N, Math.round(x))), Math.max(0, Math.min(N, Math.round(z)))) * STEP;
  const airports: SurveyAirport[] = runwaysOf(w).map((r) => ({
    name: r.name, major: r.major,
    x: (r.ax + r.bx) / 2 - w.ox, z: (r.az + r.bz) / 2 - w.oz, y: r.y,
    heading: r.heading, len: r.len,
  }));

  const sights: SurveySight[] = [];
  for (const t of w.towns) sights.push({ kind: 'town', name: t.name, id: t.id, sub: t.kind, big: t.kind === 'mega' || t.kind === 'metro' || t.kind === 'city', style: t.style, x: t.x0 + t.size / 2, z: t.z0 + t.size / 2, y: t.level * STEP });
  for (const p of w.ports) if (p.major) sights.push({ kind: 'port', name: p.name, x: p.x, z: p.z, y: p.level * STEP });
  for (const g of w.works) {
    if (g.kind === 'wonder') sights.push({ kind: 'wonder', name: g.name, x: g.x, z: g.z, y: g.level * STEP, big: true });
    else if (g.kind === 'airfield') sights.push({ kind: 'airport', name: g.name, x: g.x, z: g.z, y: g.level * STEP, big: g.major });
    else if (g.kind === 'ski') sights.push({ kind: 'ski', name: g.name, x: g.x, z: g.z, y: g.level * STEP });
    // a mine (0.7.0, world/mines.ts), labelled on the region map as a quarry sight with its kind
    else if (g.kind === 'mine') sights.push({ kind: 'quarry', name: g.name, x: g.x, z: g.z, y: g.level * STEP, sub: g.mine, big: g.major });
  }
  for (const l of w.landmarks) {
    if (l.kind === 'skerries' || l.kind === 'fjordCoast') continue;
    sights.push({ kind: 'landform', name: l.name, sub: l.kind as LandformKind, x: l.x, z: l.z, y: groundAt(l.x, l.z), big: l.r > 30 });
  }

  return {
    cx: w.cx, cz: w.cz, kind: w.kind, name: w.name,
    h, col: stampOf(w, SURVEY_PER), stamp: stampOf(w), boxes: new Float32Array(boxes), airports, sights, muni: municipalityOf(w),
    towns: w.towns.map((t) => digestOf(w, t)),
  };
}
