import { DIRS, EDGE_MINE, Flag, N, RailBit, type Bridge, type World } from './tiles';
import { LAND, groundRate } from './land';

/**
 * A road the builder cut down a ledge (the user, 15 Oct 2026: "the whole point of the road builder is that
 * I can build my own shortcut down from this ledge"). The planner may step a narrow road over a step in the
 * ground (planRoutes `cut`); here, before it is laid, the road's own tiles are re-shaped so its surface runs
 * on without a step: each tile either keeps its shape or becomes a straight ramp of at most one step from
 * the edge it is entered by to the edge it leaves by (a corner tile, level). The cheapest set of re-shaped
 * tiles is found by a small search over the height of every edge along the road, with the road's first and
 * last tile and every bridge's ends left as they are. Only the road's tiles move: the ground beside it keeps
 * its height, so the ledge is still a cliff either side of the cutting, as it would be in RollerCoaster
 * Tycoon. Paid for at the land tool's rate, and saved with the land (world/landCodec.ts).
 */

/** The biggest step in the ground the planner will cut a road down, in steps: more wants a bridge or the land tool. */
export const CUT_MAX = 4;
/** What the planner adds for each step of a step it cuts through, in its tile units: a little dearer than going round a short way. */
export const CUT_STEP = 6;

export interface Grade {
  /** New corner values, by corner index (tile × 4 + q). Empty when the road needs no cutting. */
  corners: Map<number, number>;
  tiles: number[];
  lifts: number;
  /** Dollars, at the land tool's rate for the ground it moves. */
  cost: number;
}

const dirOf = (a: number, b: number): number => {
  const dx = (b % N) - (a % N), dz = Math.floor(b / N) - Math.floor(a / N);
  for (let d = 0; d < 4; d++) if (DIRS[d][0] === dx && DIRS[d][1] === dz) return d;
  return -1;
};

/** Can this tile be re-shaped under a road: dry, and nothing on it that its height belongs to. */
function movable(w: World, t: number): boolean {
  return !w.road[t] && !w.rail[t] && !w.blocked[t] && !(w.flags[t] & (Flag.Poi | Flag.Corridor)) && w.water[t] < 0 && !(w.rail[t] & RailBit.Track) && !w.deckAxis[t];
}

/**
 * The re-shaping a narrow road on `nodes` (with `bridges`) needs to run on without a step anywhere along its
 * ground, or why it can't be done. A road with no step in it needs nothing, and comes back empty.
 */
export function gradeRoute(w: World, nodes: number[], bridges: Bridge[]): Grade | { why: string } {
  const out: Grade = { corners: new Map(), tiles: [], lifts: 0, cost: 0 };
  const c = w.corners;
  // which steps along the road are on a deck: the ground runs lie between them
  const onDeck = new Uint8Array(nodes.length);
  for (const b of bridges) for (let k = b.from; k < b.to; k++) onDeck[k] = 1;
  let r0 = 0;
  while (r0 < nodes.length - 1) {
    while (r0 < nodes.length - 1 && onDeck[r0]) r0++;
    let r1 = r0;
    while (r1 < nodes.length - 1 && !onDeck[r1]) r1++;
    if (r1 > r0) {
      const res = gradeRun(w, nodes, r0, r1, c);
      if ('why' in res) return res;
      for (const [k, v] of res) out.corners.set(k, v);
    }
    r0 = r1 + 1;
  }
  return pricedGrade(w, out.corners);
}

/** A set of corner moves as a Grade: the tiles they touch, the steps moved, and the land tool's price for them. */
export function pricedGrade(w: World, corners: Map<number, number>): Grade {
  const out: Grade = { corners, tiles: [], lifts: 0, cost: 0 };
  const tiles = new Set<number>();
  for (const [k, v] of corners) {
    const lift = Math.abs(v - w.corners[k]);
    out.lifts += lift;
    out.cost += lift * LAND.lift * groundRate(w, k >> 2);
    tiles.add(k >> 2);
  }
  out.tiles = [...tiles];
  out.cost = Math.round(out.cost);
  return out;
}

/** One stretch of ground road, nodes r0..r1: the corners it needs, or why it can't be cut. */
function gradeRun(w: World, nodes: number[], r0: number, r1: number, c: Int8Array | Float32Array | number[]): Map<number, number> | { why: string } {
  const pair = (t: number, e: readonly [number, number]): [number, number] => [c[t * 4 + e[0]], c[t * 4 + e[1]]];
  const din = (k: number) => dirOf(nodes[k - 1], nodes[k]);
  const dout = (k: number) => dirOf(nodes[k], nodes[k + 1]);
  // a run with no step in it is left alone
  let step = false;
  for (let k = r0; k < r1 && !step; k++) {
    const a = pair(nodes[k], EDGE_MINE[dout(k)]), b = pair(nodes[k + 1], EDGE_MINE[dout(k) ^ 2]);
    if (a[0] !== b[0] || a[1] !== b[1]) step = true;
  }
  if (!step) return new Map();
  if (r1 - r0 < 2) return { why: 'Too short to cut down a step: start further back from the ledge' };
  // the search: the edge after each node, as the pair of corners on it, with the cheapest way there
  type St = { p: [number, number]; cost: number; from: string | null; how: 'keep' | [number, number] };
  const key = (p: [number, number]) => `${p[0]},${p[1]}`;
  let layer = new Map<string, St>();
  const first = pair(nodes[r0], EDGE_MINE[dout(r0)]);
  layer.set(key(first), { p: first, cost: 0, from: null, how: 'keep' });
  const layers: Map<string, St>[] = [layer];
  for (let k = r0 + 1; k < r1; k++) {
    const t = nodes[k], i = din(k), o = dout(k);
    const ein = EDGE_MINE[i ^ 2], eout = EDGE_MINE[o];
    const natIn = pair(t, ein), natOut = pair(t, eout);
    const turn = i !== o;
    const can = movable(w, t);
    const next = new Map<string, St>();
    const offer = (p: [number, number], cost: number, from: string, how: St['how']) => {
      const kk = key(p), have = next.get(kk);
      if (!have || cost < have.cost) next.set(kk, { p, cost, from, how });
    };
    for (const [kk, s] of layer) {
      // as it is: only where the edge coming in meets it already
      if (s.p[0] === natIn[0] && s.p[1] === natIn[1]) offer(natOut, s.cost, kk, 'keep');
      // re-shaped: from a level edge in, a ramp of at most a step (a corner tile stays level)
      if (!can || s.p[0] !== s.p[1]) continue;
      const a = s.p[0];
      for (const b of turn ? [a] : [a - 1, a, a + 1]) {
        if (b < LAND.floor || a < LAND.floor) continue;
        let lifts = 0;
        for (let q = 0; q < 4; q++) lifts += Math.abs(cornerTo(q, ein, eout, a, b, turn) - c[t * 4 + q]);
        offer([b, b], s.cost + lifts, kk, [a, b]);
      }
    }
    if (!next.size) return { why: 'The ground won’t take a ramp here: a building, a road or water is in the cutting' };
    layers.push(next);
    layer = next;
  }
  // the last node is left as it is: the edge into it must be its own
  const end = nodes[r1];
  const want = key(pair(end, EDGE_MINE[din(r1) ^ 2]));
  const fin = layer.get(want);
  if (!fin) return { why: 'Too steep to cut down in the room there: a road can drop one step a tile' };
  // back along the cheapest way, writing each re-shaped tile
  const corners = new Map<number, number>();
  let s: St = fin;
  for (let li = layers.length - 1, k = r1 - 1; li > 0; li--, k--) {
    if (s.how !== 'keep') {
      const t = nodes[k], i = din(k), o = dout(k);
      const [a, b] = s.how;
      for (let q = 0; q < 4; q++) {
        const v = cornerTo(q, EDGE_MINE[i ^ 2], EDGE_MINE[o], a, b, i !== o);
        if (v !== c[t * 4 + q]) corners.set(t * 4 + q, v);
      }
    }
    s = layers[li - 1].get(s.from!)!;
  }
  return corners;
}

/** Corner q of a re-shaped tile: on the edge it leaves by `b`, otherwise (the edge it is entered by, and a corner tile throughout) `a`. */
function cornerTo(q: number, _ein: readonly [number, number], eout: readonly [number, number], a: number, b: number, turn: boolean): number {
  if (turn) return a;
  return eout[0] === q || eout[1] === q ? b : a;
}
