import type { Building, Town, Work, World } from './tiles';

/**
 * Airports belong to the town they serve (the user, 4 Nov 2026: "are airport buildings/terminals not automatically
 * part of a nearby city?"). An airfield is cut out in the country, clear of every town, and its terminal, tower and
 * hangars stood in no town's lines. Now each airfield is linked to the nearest town on its island within
 * AIRPORT_TOWN_REACH tiles, the way a harbour has its town (Port.town): the town's border takes in the airport's
 * buildings (world/townShape.ts), its card lists the airport and counts its buildings among the town's lots, and
 * the building card names the town.
 *
 * The link is made on the main thread as each island comes in (main.ts islands.prepare), never in generation and
 * never saved, so every county generates as it did (scripts/worldsame.mjs). It is the same rule the town's books
 * already credit an airport's trade by (game/ledger.ts creditFor: the nearest town's square, less half its size,
 * within ECONOMY.countryReach), so everyone online sees the same town and the books don't move.
 */
export const AIRPORT_TOWN_REACH = 60;

/** Link every airfield on this island to the nearest town close enough, or to none (-1). */
export function linkAirports(w: World): void {
  for (const g of w.works) {
    if (g.kind !== 'airfield') continue;
    let best = -1, bestD = AIRPORT_TOWN_REACH;
    for (const t of w.towns) {
      const d = Math.hypot(t.x0 + t.size / 2 - g.x, t.z0 + t.size / 2 - g.z) - t.size / 2;
      if (d < bestD) { bestD = d; best = t.id; }
    }
    g.town = best;
  }
}

/** The airfields that belong to this town. */
export function airportsOf(w: World, t: Town): Work[] {
  return w.works.filter((g) => g.kind === 'airfield' && g.town === t.id);
}

/** The town an airport building belongs to, if its airfield has one. */
export function airportTownOf(w: World, b: Building): Town | null {
  const g = w.works.find((q) => q.kind === 'airfield' && q.buildings.includes(b));
  return g && g.town !== undefined && g.town >= 0 ? w.towns[g.town] ?? null : null;
}

/** The tiles an airfield's buildings stand on, as one box padded by `pad` (its terminal, tower, hangars and the apron between). */
export function airportGrounds(g: Work, pad = 1): { x0: number; z0: number; x1: number; z1: number } | null {
  const bs = g.buildings.filter((b) => !b.gone);
  if (!bs.length) return null;
  let x0 = Infinity, z0 = Infinity, x1 = -Infinity, z1 = -Infinity;
  for (const b of bs) { x0 = Math.min(x0, b.x); z0 = Math.min(z0, b.z); x1 = Math.max(x1, b.x + b.w - 1); z1 = Math.max(z1, b.z + b.d - 1); }
  return { x0: x0 - pad, z0: z0 - pad, x1: x1 + pad, z1: z1 + pad };
}
