import { N, RoadType, idx } from '../../tiles';
import type { Rng } from '../../rng';
import type { Layout, TownPlan } from '../../towns';
import { Dig, sealedLake, seaRiver } from '../water';
import { avenue } from '../kit';
import type { PlanCtx } from '../types';

/** The positions of a regular grid's lines across [lo, hi), `g` apart, centred. */
export function gridLines(lo: number, hi: number, g: number): number[] {
  const n = Math.floor((hi - lo - 2) / g);
  const start = lo + Math.floor((hi - lo - n * g) / 2);
  const out: number[] = [];
  for (let k = 0; k <= n; k++) out.push(start + k * g);
  return out;
}

/** The nearest of these to v. */
export const nearest = (list: number[], v: number): number => list.reduce((b, x) => (Math.abs(x - v) < Math.abs(b - v) ? x : b), list[0]);

/**
 * A full grid of streets over the town's square at these lines, each laid straight edge to edge (a gap where a park
 * or the water is, never a detour), the middle one each way a through road joined to the county.
 */
export function plainGrid(c: Layout, xs: number[], zs: number[], type = RoadType.TwoLane, mainType = RoadType.TwoLane, opts: { bridge?: boolean; x0?: number; z0?: number; x1?: number; z1?: number } = {}): void {
  const t = c.t;
  const x0 = opts.x0 ?? t.x0, z0 = opts.z0 ?? t.z0, x1 = opts.x1 ?? t.x0 + t.size, z1 = opts.z1 ?? t.z0 + t.size;
  const mx = xs[xs.length >> 1], mz = zs[zs.length >> 1];
  for (const x of xs) {
    const nodes = avenue(c, x === mx ? mainType : type, [x + 0.5, z0 + 0.5], [x + 0.5, z1 - 0.5], { main: x === mx, route: false, bridge: opts.bridge });
    if (x === mx) c.ends(nodes);
  }
  for (const z of zs) {
    const nodes = avenue(c, z === mz ? mainType : type, [x0 + 0.5, z + 0.5], [x1 - 0.5, z + 0.5], { main: z === mz, route: false, bridge: opts.bridge });
    if (z === mz) c.ends(nodes);
  }
}

/** The tiles inside any of these discs, inside the square and `rim` tiles in from its edge. */
export function discTiles(p: TownPlan, discs: [number, number, number][], rim = 3): Set<number> {
  const out = new Set<number>();
  for (const [cx, cz, r] of discs) {
    for (let z = Math.floor(cz - r); z <= Math.ceil(cz + r); z++) for (let x = Math.floor(cx - r); x <= Math.ceil(cx + r); x++) {
      if (x < p.x0 + rim || z < p.z0 + rim || x >= p.x0 + p.size - rim || z >= p.z0 + p.size - rim) continue;
      if (Math.hypot(x + 0.5 - cx, z + 0.5 - cz) <= r) out.add(idx(x, z));
    }
  }
  return out;
}

/** A sealed lake on these tiles, a step under the lowest ground round it (false where it won't hold). */
export function lakeOn(p: TownPlan, ctx: PlanCtx, tiles: Set<number>): boolean {
  if (tiles.size < 6) return false;
  const E = ctx.w.elev;
  let lo = Infinity;
  for (const i of tiles) {
    const x = i % N, z = (i - x) / N;
    for (const [dx, dz] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
      const j = idx(x + dx, z + dz);
      if (!tiles.has(j)) lo = Math.min(lo, E[j]);
    }
  }
  if (!Number.isFinite(lo)) return false;
  return sealedLake(p, ctx, tiles, Math.floor(lo) - 1);
}

/** Cut a river through the town at sea level along a random axis, if either end of it can reach the sea. */
export function riverThrough(p: TownPlan, ctx: PlanCtx, rng: Rng, o: { half?: number; amp?: number; island?: boolean; off?: number; axis?: 0 | 1 } = {}): boolean {
  const S = p.size;
  const first: 0 | 1 = o.axis ?? (rng() < 0.5 ? 0 : 1);
  for (const axis of o.axis !== undefined ? [first] : [first, (1 - first) as 0 | 1]) {
    const dig = new Dig(p, ctx);
    const at = Math.round((axis === 0 ? p.z0 : p.x0) + S * (0.5 + (o.off ?? (rng() - 0.5) * 0.16)));
    const half = o.half ?? 2;
    const line = seaRiver(dig, rng, { axis, at, half, amp: o.amp ?? S * 0.07, island: o.island ? { at: Math.round(S * 0.42), len: 7 } : undefined });
    if (!line || !dig.clear()) continue;
    dig.commit();
    (p.carved ??= {}).river = { axis, line, half };
    return true;
  }
  return false;
}

/** A river's middle at a place across the town (null with none). */
export function riverAt(p: TownPlan, s: number): number | null {
  const r = p.carved?.river;
  if (!r) return null;
  const k = Math.max(0, Math.min(r.line.length - 1, Math.round(s - (r.axis === 0 ? p.x0 : p.z0))));
  return r.line[k];
}

/** How far a point is from the plan's river (Infinity with none). */
export function riverDist(p: TownPlan, x: number, z: number): number {
  const r = p.carved?.river;
  if (!r) return Infinity;
  const at = riverAt(p, r.axis === 0 ? x : z)!;
  return Math.abs((r.axis === 0 ? z : x) - at);
}

/** Straight bridges across the plan's river every `every` of the way along it, `reach` either side of its banks. */
export function bridgesOver(c: Layout, p: TownPlan, every: number, reach = 6, type = RoadType.TwoLane): number {
  const r = p.carved?.river;
  if (!r) return 0;
  const S = p.size, s0 = r.axis === 0 ? p.x0 : p.z0;
  let n = 0;
  for (let k = every / 2; k < 0.97; k += every) {
    const s = s0 + Math.round(S * k);
    const at = riverAt(p, s)!;
    const a: [number, number] = r.axis === 0 ? [s + 0.5, at - r.half - reach] : [at - r.half - reach, s + 0.5];
    const b: [number, number] = r.axis === 0 ? [s + 0.5, at + r.half + reach] : [at + r.half + reach, s + 0.5];
    if (avenue(c, type, a, b, { bridge: true, main: false, route: false }).length) n++;
  }
  return n;
}
