/**
 * The ballast bed as something to drive on. Most cars cross at-grade track rather than stopping at
 * it, and when they do they ride up onto the bed the way the mesh draws it (render/railMesh.ts): a
 * flat top a little below the rail head, and shoulders running down to the ground either side. This
 * answers how high that bed is under a point, and how far the rails stand above the ground of a tile.
 *
 * The rails only change when the player lays track (world/railBuild.ts, which replaces `w.rails`), so every
 * tile near a line keeps a pointer to the path sample nearest its centre, built once per list of paths, and a
 * query only walks the segments around it.
 */
import { N, RailBit, STEP, Under, World, idx, inB, heightAt, heightOnTile } from './tiles';
import type { CarStats } from '../game/cars';

/** Ballast top below the rail top, and its half widths at the top and at the toe, in tiles. */
export const BALLAST_DROP = 0.042;
export const BALLAST_TOP = 0.21;
export const BALLAST_TOE = 0.3;

/**
 * How far above the ground the rails may stand, in steps beyond what the car hops as a curb, and
 * still be driven over: the low bank at-grade track rides on. A taller bank is a slope it runs up against.
 */
export const RAIL_HOP = 1;

/** Top speed on the ballast, as a share: loose stone and sleepers are no road. */
export const BALLAST_SPEED = 0.55;

/** Tiles from a sample within which its bed can reach: the widest toe, plus the half diagonal of a tile. */
const REACH = 2.2;

/** Whether the ballast at this sample lies on the ground (a bed to drive on) rather than on a bridge or in a tunnel. */
const bedded = (u: number): boolean => u === Under.Ground || u === Under.Embank || u === Under.Cutting;
/** Whether the track at this sample is carried on a bridge deck: a trestle, viaduct, truss or sea bridge. */
const decked = (u: number): boolean => u === Under.Trestle || u === Under.Viaduct || u === Under.Truss || u === Under.Sea;
/** Half the width a car may drive on a bridge deck per Under, a little inside the slab render/railMesh.ts draws. */
const DECK_HALF: Partial<Record<Under, number>> = {
  [Under.Trestle]: 0.24, [Under.Viaduct]: 0.31, [Under.Truss]: 0.27, [Under.Sea]: 0.29,
};

/**
 * Which land vehicles cross the rails at all. Anything with a little ground clearance does; the
 * low-slung ones that cannot wade even shallow water (a motorbike, a go-kart) catch on the rail head.
 */
export const ridesRails = (s: CarStats): boolean => s.curb > 0 || s.wade > 0;

interface RailIndex {
  /** The list of paths it was built from: a new list (a track laid) means a new index. */
  rails: World['rails'];
  /** Path index in `w.rails` per tile, -1 where no bed reaches. */
  path: Int16Array;
  /** Sample index on that path. */
  samp: Int32Array;
}

const INDEX = new WeakMap<World, RailIndex>();
const DECK_INDEX = new WeakMap<World, RailIndex>();

/** Per tile, the nearest sample the test accepts: the ballast laid on the ground, or the bridge decks. */
function index(w: World, deck = false): RailIndex {
  const cache = deck ? DECK_INDEX : INDEX;
  const accept = deck ? decked : bedded;
  let ix = cache.get(w);
  if (ix && ix.rails === w.rails) return ix;
  const NN = N * N;
  ix = { rails: w.rails, path: new Int16Array(NN).fill(-1), samp: new Int32Array(NN) };

  const dist = new Float32Array(NN).fill(Infinity);
  w.rails.forEach((p, k) => {
    const n = p.s.length;
    for (let i = 0; i < n; i++) {
      if (!accept(p.under[i])) continue;
      const x = p.xz[i * 2], z = p.xz[i * 2 + 1];
      const tx0 = Math.floor(x), tz0 = Math.floor(z);
      for (let dz = -2; dz <= 2; dz++) {
        for (let dx = -2; dx <= 2; dx++) {
          const tx = tx0 + dx, tz = tz0 + dz;
          if (!inB(tx, tz)) continue;
          const t = idx(tx, tz);
          const d = Math.hypot(tx + 0.5 - x, tz + 0.5 - z);
          if (d > REACH || d >= dist[t]) continue;
          dist[t] = d;
          ix!.path[t] = k;
          ix!.samp[t] = i;
        }
      }
    }
  });
  cache.set(w, ix);
  return ix;
}

/**
 * Whether segment i (samples i..i+1) is laid as ballast on the ground. As render/railMesh.ts segClass
 * draws it: the segment from a bridge's last sample onto the bank is the bank's, not the bridge's.
 */
function bedSeg(p: { under: ArrayLike<number> }, i: number): boolean {
  const u = p.under[i];
  return bedded(u) || (decked(u) && bedded(p.under[i + 1]));
}

/** Nearest point on the bedded segments around the tile's sample: distance to the centreline and the rail top there. */
function nearest(w: World, t: number, x: number, z: number, deck = false): { off: number; y: number; px: number; pz: number; u: Under; dx: number; dz: number } | null {
  const ix = index(w, deck);
  const k = ix.path[t];
  if (k < 0) return null;
  const p = w.rails[k], i0 = ix.samp[t], n = p.s.length;
  const accept = deck ? (i: number) => decked(p.under[i]) : (i: number) => bedSeg(p, i);
  let bestD2 = Infinity, y = 0, px = 0, pz = 0, under = Under.Ground, ddx = 0, ddz = 1;
  /** How far along segment j the point projects: 0 at its first sample, 1 at its second. */
  const alongOf = (j: number): number => {
    const ax = p.xz[j * 2], az = p.xz[j * 2 + 1], dx = p.xz[j * 2 + 2] - ax, dz = p.xz[j * 2 + 3] - az;
    return ((x - ax) * dx + (z - az) * dz) / (dx * dx + dz * dz || 1e-9);
  };
  for (let i = Math.max(0, i0 - 3); i <= Math.min(n - 2, i0 + 2); i++) {
    if (!accept(i)) continue;
    const ax = p.xz[i * 2], az = p.xz[i * 2 + 1], bx = p.xz[i * 2 + 2], bz = p.xz[i * 2 + 3];
    const dx = bx - ax, dz = bz - az;
    const along = alongOf(i);
    // A point beyond a segment's end belongs to it only on the outside of a bend: past the next bedded
    // segment's start as well. Past the end of a bank (a bridge, a tunnel or the line's end beyond it)
    // there is no bank: the mesh stops square there, so the bed must too. Rounding it off made an
    // invisible mound a tile and more across, which lifted a road under a viaduct's first span (the user, 7 Oct 2026)
    if (!deck && along < 0 && (i === 0 || !accept(i - 1) || alongOf(i - 1) < 1)) continue;
    if (!deck && along > 1 && (i + 1 > n - 2 || !accept(i + 1) || alongOf(i + 1) > 0)) continue;
    const u = Math.min(1, Math.max(0, along));
    const qx = ax + dx * u, qz = az + dz * u;
    const d2 = (x - qx) * (x - qx) + (z - qz) * (z - qz);
    if (d2 < bestD2) {
      bestD2 = d2;
      y = p.y[i] + (p.y[i + 1] - p.y[i]) * u;
      px = qx;
      pz = qz;
      under = p.under[i];
      const len = Math.hypot(dx, dz) || 1;
      ddx = dx / len; ddz = dz / len;
    }
  }
  if (bestD2 === Infinity) return null;
  return { off: Math.sqrt(bestD2), y, px, pz, u: under, dx: ddx, dz: ddz };
}

/**
 * The height a car rides at over point (x, z) of tile (tx, tz), given the ground there: the ballast
 * top when it is between the rails' shoulders, the shoulder on the way down, else the ground itself.
 * The profile is the one `bank` in render/railMesh.ts draws.
 */
export function railBedAt(w: World, tx: number, tz: number, x: number, z: number, ground: number): number {
  const t = idx(tx, tz);
  const own = bedOf(w, t, x, z, ground);
  if (own > ground || !(w.rail[t] & RailBit.Track)) return own;
  // a diagonal line runs through the tiles' corners, and near one its bank is a neighbour's: read on this tile
  // alone, the bank's top fell to the ground there, and a car driving along it met a step it couldn't take
  // (the user, 19 Oct 2026)
  let best = own;
  for (let dz = -1; dz <= 1; dz++) for (let dx = -1; dx <= 1; dx++) {
    if ((!dx && !dz) || !inB(tx + dx, tz + dz)) continue;
    const n = idx(tx + dx, tz + dz);
    if (w.rail[n] & RailBit.Track) best = Math.max(best, bedOf(w, n, x, z, ground));
  }
  return best;
}

/** railBedAt on track tile t's own stretch of line alone. */
function bedOf(w: World, t: number, x: number, z: number, ground: number): number {
  const near = nearest(w, t, x, z);
  if (!near) return ground;
  const top = near.y - BALLAST_DROP;
  if (near.off <= BALLAST_TOP) return Math.max(ground, top);
  const gc = heightAt(w, near.px, near.pz);
  const toe = BALLAST_TOE + Math.min(1.4, Math.max(0, (top - gc - 0.06) * 1.5));
  if (near.off >= toe) return ground;
  const f = (near.off - BALLAST_TOP) / (toe - BALLAST_TOP);
  return Math.max(ground, top - (top - ground) * f);
}

/** How far the rail top stands above the ground of track tile i, in steps; 0 where no bed is laid on it. */
export function railLift(w: World, i: number): number {
  const ix = index(w);
  const k = ix.path[i];
  if (k < 0) return 0;
  const p = w.rails[k], s = ix.samp[i];
  const tx = i % N, tz = (i - tx) / N;
  const g = heightOnTile(w, tx, tz, p.xz[s * 2], p.xz[s * 2 + 1]);
  return Math.max(0, (p.y[s] - BALLAST_DROP - g) / STEP);
}

/**
 * The top of a railway bridge's deck under point (x, z) of tile (tx, tz), where a car could drive
 * along it, or null off the deck's edge (or where there is no bridge). The car only rides it once it
 * has come onto it from the ballast at the same height (game/car.ts), never from the ground below.
 */
export function railDeckAt(w: World, tx: number, tz: number, x: number, z: number): number | null {
  if (!inB(tx, tz)) return null;
  const near = nearest(w, idx(tx, tz), x, z, true);
  if (!near || near.off > (DECK_HALF[near.u] ?? 0.25)) return null;
  return near.y - BALLAST_DROP;
}

/**
 * The railway bridge deck a car at (x, z) is riding: its top, the nearest point on its centre line and the
 * way the track runs there (either way along it), or null off the deck. The deck is one car wide, so a car
 * on it is held facing along the track (game/car.ts): turned across it, it could neither drive nor turn.
 */
export function railDeckLine(w: World, x: number, z: number): { y: number; px: number; pz: number; dx: number; dz: number } | null {
  const tx = Math.floor(x), tz = Math.floor(z);
  if (!inB(tx, tz)) return null;
  const near = nearest(w, idx(tx, tz), x, z, true);
  if (!near || near.off > (DECK_HALF[near.u] ?? 0.25)) return null;
  return { y: near.y - BALLAST_DROP, px: near.px, pz: near.pz, dx: near.dx, dz: near.dz };
}
