import { N, idx, type Building, type BuildingKind, type Town, type World } from './tiles';
import { airportGrounds } from './airportTowns';

/**
 * A town as one shape: its border traced over the tiles it owns, for the selection ring and the map
 * (docs/towns.html). Pure and headless, so `npm run borders` can check every town of a world.
 *
 * The tiles are `w.townId`, plus the yards of any harbour serving the town and the town's own fields.
 * Gaps of a tile between two arms are closed, holes filled (a park or a lake in the middle is still
 * the town), stray specks dropped; the edge is walked into loops on tile corners and its corners cut
 * with Chaikin's method, which never swings the line outside the stair-step outline it came from.
 */

export interface TownShape {
  /** Closed loops in the cell's own tiles as x, z pairs, the town on their left (see `march`). */
  loops: Float32Array[];
  /** Tiles inside, after closing and filling. */
  area: number;
  /** The middle of the tiles inside. */
  cx: number; cz: number;
  /** The box the mask covers, in tiles, and the mask itself (1 inside) row by row over it. */
  x0: number; z0: number; bw: number; bh: number;
  mask: Uint8Array;
}

/** A piece of the town cut off from the rest is kept only if it is at least this many tiles. */
const SPECK_TILES = 12;
/** Corner-cutting passes. */
const CHAIKIN = 3;

/** The seat, in the order it is looked for: the hall, then the village's or the suburb's own. */
const SEATS: BuildingKind[] = ['cityHall', 'kasbah', 'villageHall', 'communityCentre'];
/** Failing those, the civic building nearest the middle of town. */
const CIVIC_SEATS = new Set<string>(['courthouse', 'postOffice', 'clockTower', 'church', 'chapel', 'marketHall', 'library', 'parliament', 'statehouse', 'meetingHouse', 'fireLookout']);

/**
 * The building that stands for the town: click it close up and the whole town is selected. A city's
 * hall (or the kasbah the Sands put in its place), a village hall, a suburb's community centre, or
 * else the civic building nearest the town's middle. Null when the town has none of them.
 */
export function seatOf(t: Town): Building | null {
  for (const kind of SEATS) {
    const b = t.buildings.find((q) => q.kind === kind && !q.gone);
    if (b) return b;
  }
  const mx = t.x0 + t.size / 2, mz = t.z0 + t.size / 2;
  let best: Building | null = null, bestD = Infinity;
  for (const b of t.buildings) {
    if (b.gone || !CIVIC_SEATS.has(b.kind)) continue;
    const d = Math.hypot(b.x + b.w / 2 - mx, b.z + b.d / 2 - mz);
    if (d < bestD) { bestD = d; best = b; }
  }
  return best;
}

/** What the seat is called on its hover tag. */
export function seatLabel(b: Building): string {
  switch (b.kind as string) {
    case 'cityHall': return 'City hall';
    case 'kasbah': return 'Kasbah';
    case 'villageHall': return 'Village hall';
    case 'communityCentre': return 'Community centre';
    default: return 'Town seat';
  }
}

// ---------------------------------------------------------------------------------------------
// the cache: a trace is cheap, but the border is asked for every tick the card is up

const cache = new WeakMap<World, Map<number, { rev: number; size: number; n: number; shape: TownShape }>>();

/** The town's shape, traced again only when its island has changed since. */
export function shapeOf(w: World, t: Town): TownShape {
  let m = cache.get(w);
  if (!m) cache.set(w, (m = new Map()));
  const c = m.get(t.id);
  if (c && c.rev === w.revision && c.size === t.size && c.n === t.buildings.length) return c.shape;
  const shape = traceTown(w, t);
  m.set(t.id, { rev: w.revision, size: t.size, n: t.buildings.length, shape });
  return shape;
}

// ---------------------------------------------------------------------------------------------
// tracing

export function traceTown(w: World, t: Town): TownShape {
  const id = t.id;
  const ports = new Set(w.ports.filter((p) => p.town === id).map((p) => p.id));
  const fields = t.buildings.filter((b) => b.kind === 'field' && !b.gone);
  // the airports it serves (world/airportTowns.ts): their terminal, tower and hangars, and the apron between
  const airs = w.works.filter((g) => g.kind === 'airfield' && g.town === id).map((g) => airportGrounds(g)).filter((a) => !!a);
  const own = (i: number) => w.townId[i] === id || (ports.size > 0 && ports.has(w.portId[i]));

  // the box around everything the town owns, padded for the closing: the town's own tiles never
  // leave its square, and a harbour's yard is near its buildings, so only those need looking over
  let x0 = N, z0 = N, x1 = -1, z1 = -1;
  const grow = (x: number, z: number) => { if (x < x0) x0 = x; if (z < z0) z0 = z; if (x > x1) x1 = x; if (z > z1) z1 = z; };
  const look = (ax: number, az: number, bx: number, bz: number) => {
    for (let z = Math.max(0, az); z <= Math.min(N - 1, bz); z++) {
      for (let x = Math.max(0, ax); x <= Math.min(N - 1, bx); x++) if (own(z * N + x)) grow(x, z);
    }
  };
  look(t.x0 - 2, t.z0 - 2, t.x0 + t.size + 1, t.z0 + t.size + 1);
  for (const p of w.ports) {
    if (p.town !== id) continue;
    for (const b of p.buildings) look(b.x - 4, b.z - 4, b.x + b.w + 3, b.z + b.d + 3);
    look(Math.floor(p.x) - 8, Math.floor(p.z) - 8, Math.floor(p.x) + 8, Math.floor(p.z) + 8);
  }
  for (const b of fields) { grow(b.x, b.z); grow(b.x + b.w - 1, b.z + b.d - 1); }
  for (const a of airs) { grow(Math.max(0, a.x0), Math.max(0, a.z0)); grow(Math.min(N - 1, a.x1), Math.min(N - 1, a.z1)); }
  if (x1 < 0) {
    // nothing on the ground says so: the town's square is all there is to go on
    x0 = t.x0; z0 = t.z0; x1 = t.x0 + t.size - 1; z1 = t.z0 + t.size - 1;
  }
  const P = 2;
  const bx = x0 - P, bz = z0 - P;
  const bw = x1 - x0 + 1 + P * 2, bh = z1 - z0 + 1 + P * 2;
  const at = (x: number, z: number) => (z - bz) * bw + (x - bx);
  const inCell = (x: number, z: number) => x >= 0 && z >= 0 && x < N && z < N;
  /** Another town's tile: never drawn over. */
  const other = new Uint8Array(bw * bh);
  let mask: Uint8Array = new Uint8Array(bw * bh);
  let any = false;
  for (let z = bz; z < bz + bh; z++) {
    for (let x = bx; x < bx + bw; x++) {
      if (!inCell(x, z)) continue;
      const i = idx(x, z);
      const k = at(x, z);
      if (own(i)) { mask[k] = 1; any = true; }
      else if (w.townId[i] >= 0) other[k] = 1;
    }
  }
  for (const b of fields) {
    for (let z = b.z; z < b.z + b.d; z++) for (let x = b.x; x < b.x + b.w; x++) {
      const k = at(x, z);
      if (k >= 0 && k < mask.length && !other[k]) { mask[k] = 1; any = true; }
    }
  }
  for (const a of airs) {
    for (let z = Math.max(0, a.z0); z <= Math.min(N - 1, a.z1); z++) for (let x = Math.max(0, a.x0); x <= Math.min(N - 1, a.x1); x++) {
      const k = at(x, z);
      if (k >= 0 && k < mask.length && !other[k]) { mask[k] = 1; any = true; }
    }
  }
  if (!any) {
    for (let z = t.z0; z < t.z0 + t.size; z++) for (let x = t.x0; x < t.x0 + t.size; x++) if (inCell(x, z)) mask[at(x, z)] = 1;
  }

  // close: a one-tile gap between two arms is not a notch
  mask = morph(morph(mask, bw, bh, true), bw, bh, false);
  for (let k = 0; k < mask.length; k++) if (other[k]) mask[k] = 0;
  fillHoles(mask, other, bw, bh);
  dropSpecks(mask, bw, bh);

  let area = 0, sx = 0, sz = 0;
  for (let z = 0; z < bh; z++) for (let x = 0; x < bw; x++) {
    if (!mask[z * bw + x]) continue;
    area++; sx += x + 0.5; sz += z + 0.5;
  }
  const loops = march(mask, bw, bh).map((l) => {
    const pts = chaikin(simplify(l), CHAIKIN);
    const out = new Float32Array(pts.length);
    for (let k = 0; k < pts.length; k += 2) { out[k] = pts[k] + bx; out[k + 1] = pts[k + 1] + bz; }
    return out;
  });
  return {
    loops, area,
    cx: area ? bx + sx / area : t.x0 + t.size / 2,
    cz: area ? bz + sz / area : t.z0 + t.size / 2,
    x0: bx, z0: bz, bw, bh, mask,
  };
}

/** Whether a point in the cell's tiles is inside the shape's mask. */
export function inShape(s: TownShape, x: number, z: number): boolean {
  const mx = Math.floor(x) - s.x0, mz = Math.floor(z) - s.z0;
  return mx >= 0 && mz >= 0 && mx < s.bw && mz < s.bh && s.mask[mz * s.bw + mx] === 1;
}

/** A 3 × 3 max (dilate) or min (erode), in two passes: along each row, then down each column. */
function morph(m: Uint8Array, w: number, h: number, max: boolean): Uint8Array {
  const edge = 0; // outside the box is not the town, for either
  const row = new Uint8Array(m.length), out = new Uint8Array(m.length);
  for (let z = 0; z < h; z++) {
    const o = z * w;
    for (let x = 0; x < w; x++) {
      const l = x > 0 ? m[o + x - 1] : edge, c = m[o + x], r = x < w - 1 ? m[o + x + 1] : edge;
      row[o + x] = max ? (l | c | r) : (l & c & r);
    }
  }
  for (let z = 0; z < h; z++) {
    const o = z * w;
    for (let x = 0; x < w; x++) {
      const u = z > 0 ? row[o - w + x] : edge, c = row[o + x], d = z < h - 1 ? row[o + w + x] : edge;
      out[o + x] = max ? (u | c | d) : (u & c & d);
    }
  }
  return out;
}

/** Fill every hole the outside can't reach, unless another town's tiles are in it (a megalopolis's satellite). */
function fillHoles(m: Uint8Array, other: Uint8Array, w: number, h: number): void {
  const seen = new Uint8Array(m.length);
  const stack: number[] = [];
  const push = (k: number) => { if (!seen[k] && !m[k]) { seen[k] = 1; stack.push(k); } };
  for (let x = 0; x < w; x++) { push(x); push((h - 1) * w + x); }
  for (let z = 0; z < h; z++) { push(z * w); push(z * w + w - 1); }
  const flood = () => {
    const got: number[] = [];
    while (stack.length) {
      const k = stack.pop()!;
      got.push(k);
      const x = k % w, z = (k - x) / w;
      if (x > 0) push(k - 1);
      if (x < w - 1) push(k + 1);
      if (z > 0) push(k - w);
      if (z < h - 1) push(k + w);
    }
    return got;
  };
  flood();
  for (let k = 0; k < m.length; k++) {
    if (m[k] || seen[k]) continue;
    push(k);
    const hole = flood();
    if (!hole.some((q) => other[q])) for (const q of hole) m[q] = 1;
  }
}

/** Keep the biggest piece, and any other big enough to be a harbour over the water rather than a speck. */
function dropSpecks(m: Uint8Array, w: number, h: number): void {
  const label = new Int32Array(m.length).fill(-1);
  const sizes: number[] = [];
  for (let k = 0; k < m.length; k++) {
    if (!m[k] || label[k] >= 0) continue;
    const id = sizes.length;
    let n = 0;
    const stack = [k];
    label[k] = id;
    while (stack.length) {
      const q = stack.pop()!;
      n++;
      const x = q % w, z = (q - x) / w;
      const try_ = (r: number) => { if (m[r] && label[r] < 0) { label[r] = id; stack.push(r); } };
      if (x > 0) try_(q - 1);
      if (x < w - 1) try_(q + 1);
      if (z > 0) try_(q - w);
      if (z < h - 1) try_(q + w);
    }
    sizes.push(n);
  }
  if (sizes.length <= 1) return;
  const big = sizes.indexOf(Math.max(...sizes));
  for (let k = 0; k < m.length; k++) if (m[k] && label[k] !== big && sizes[label[k]] < SPECK_TILES) m[k] = 0;
}

/**
 * Walk the mask's edge into closed loops of tile corners, the inside always on the left of the way
 * round (in x across, z down: a lone tile goes down its west side, along its south, up its east).
 * Where two inside tiles meet only at a corner the walk turns toward the inside, so a loop never
 * crosses itself.
 */
function march(m: Uint8Array, w: number, h: number): number[][] {
  const inside = (x: number, z: number) => x >= 0 && z >= 0 && x < w && z < h && m[z * w + x] === 1;
  // edges as start → end, keyed by start corner
  const W1 = w + 1;
  const out = new Map<number, number[]>();
  const edges: [number, number][] = [];
  const add = (ax: number, az: number, bx: number, bz: number) => {
    const a = az * W1 + ax, b = bz * W1 + bx;
    const k = edges.length;
    edges.push([a, b]);
    const l = out.get(a);
    if (l) l.push(k); else out.set(a, [k]);
  };
  for (let z = 0; z < h; z++) for (let x = 0; x < w; x++) {
    if (!inside(x, z)) continue;
    if (!inside(x, z - 1)) add(x + 1, z, x, z);
    if (!inside(x, z + 1)) add(x, z + 1, x + 1, z + 1);
    if (!inside(x - 1, z)) add(x, z, x, z + 1);
    if (!inside(x + 1, z)) add(x + 1, z + 1, x + 1, z);
  }
  const used = new Uint8Array(edges.length);
  const loops: number[][] = [];
  const xy = (c: number): [number, number] => [c % W1, Math.floor(c / W1)];
  for (let s = 0; s < edges.length; s++) {
    if (used[s]) continue;
    const pts: number[] = [];
    let e = s;
    while (!used[e]) {
      used[e] = 1;
      const [a, b] = edges[e];
      const [ax, az] = xy(a), [bx, bz] = xy(b);
      pts.push(ax, az);
      const dx = bx - ax, dz = bz - az;
      const next = (out.get(b) ?? []).filter((k) => !used[k]);
      if (!next.length) break;
      if (next.length === 1) { e = next[0]; continue; }
      // the inside lies at (dz, -dx) from the way we are going: turn that way first
      const want = [[dz, -dx], [dx, dz], [-dz, dx]];
      let pick = next[0];
      for (const [wx, wz] of want) {
        const f = next.find((k) => { const [p, q] = edges[k]; const [px, pz] = xy(p), [qx, qz] = xy(q); return qx - px === wx && qz - pz === wz; });
        if (f !== undefined) { pick = f; break; }
      }
      e = pick;
    }
    if (pts.length >= 6) loops.push(pts);
  }
  return loops;
}

/** Drop the corners a straight run passes through, then split long runs so the cutting stays local. */
function simplify(pts: number[]): number[] {
  const n = pts.length / 2;
  const keep: number[] = [];
  for (let k = 0; k < n; k++) {
    const p = (k + n - 1) % n, q = (k + 1) % n;
    const ax = pts[k * 2] - pts[p * 2], az = pts[k * 2 + 1] - pts[p * 2 + 1];
    const bx = pts[q * 2] - pts[k * 2], bz = pts[q * 2 + 1] - pts[k * 2 + 1];
    if (ax * bz - az * bx !== 0) keep.push(pts[k * 2], pts[k * 2 + 1]);
  }
  if (keep.length < 6) return pts;
  // a long straight side keeps a corner every two tiles, so a cut near its end is only half a tile deep
  const out: number[] = [];
  const m = keep.length / 2;
  for (let k = 0; k < m; k++) {
    const ax = keep[k * 2], az = keep[k * 2 + 1];
    const bx = keep[((k + 1) % m) * 2], bz = keep[((k + 1) % m) * 2 + 1];
    const len = Math.hypot(bx - ax, bz - az);
    const parts = Math.max(1, Math.round(len / 2));
    for (let j = 0; j < parts; j++) out.push(ax + ((bx - ax) * j) / parts, az + ((bz - az) * j) / parts);
  }
  return out;
}

function chaikin(pts: number[], passes: number): number[] {
  let p = pts;
  for (let r = 0; r < passes; r++) {
    const n = p.length / 2;
    const q: number[] = [];
    for (let k = 0; k < n; k++) {
      const ax = p[k * 2], az = p[k * 2 + 1];
      const bx = p[((k + 1) % n) * 2], bz = p[((k + 1) % n) * 2 + 1];
      q.push(ax * 0.75 + bx * 0.25, az * 0.75 + bz * 0.25, ax * 0.25 + bx * 0.75, az * 0.25 + bz * 0.75);
    }
    p = q;
  }
  return p;
}

// ---------------------------------------------------------------------------------------------
// geometry for the gate and the map

/** Whether a point is inside a closed loop (even-odd). */
function inLoop(l: Float32Array, x: number, z: number): boolean {
  let inside = false;
  const n = l.length / 2;
  for (let i = 0, j = n - 1; i < n; j = i++) {
    const xi = l[i * 2], zi = l[i * 2 + 1], xj = l[j * 2], zj = l[j * 2 + 1];
    if ((zi > z) !== (zj > z) && x < ((xj - xi) * (z - zi)) / (zj - zi) + xi) inside = !inside;
  }
  return inside;
}

/** Inside the shape's loops, holes and all (even-odd over every loop). */
export function inLoops(s: TownShape, x: number, z: number): boolean {
  let n = 0;
  for (const l of s.loops) if (inLoop(l, x, z)) n++;
  return n % 2 === 1;
}

/** Whether any two segments of a loop that aren't neighbours cross. For the gate: O(n²), so not for the frame. */
export function selfCrosses(l: Float32Array): boolean {
  const n = l.length / 2;
  const seg = (k: number) => [l[k * 2], l[k * 2 + 1], l[((k + 1) % n) * 2], l[((k + 1) % n) * 2 + 1]];
  for (let i = 0; i < n; i++) {
    const [ax, az, bx, bz] = seg(i);
    for (let j = i + 2; j < n; j++) {
      if (i === 0 && j === n - 1) continue;
      const [cx, cz, dx, dz] = seg(j);
      const d1 = (dx - cx) * (az - cz) - (dz - cz) * (ax - cx);
      const d2 = (dx - cx) * (bz - cz) - (dz - cz) * (bx - cx);
      const d3 = (bx - ax) * (cz - az) - (bz - az) * (cx - ax);
      const d4 = (bx - ax) * (dz - az) - (bz - az) * (dx - ax);
      if (((d1 > 0 && d2 < 0) || (d1 < 0 && d2 > 0)) && ((d3 > 0 && d4 < 0) || (d3 < 0 && d4 > 0))) return true;
    }
  }
  return false;
}
