/** The wonders of the world, as the deeds and the Passport count them (game/sights.ts WONDER_KINDS). */
export const WONDER_SET: ReadonlySet<string> = new Set([
  ...REGION_KINDS.map((r: RegionKind) => REGIONS[r].wonder.kind as string),
  ...ISLAND_WONDERS.map((w) => w.wonder.kind as string),
  ...(NEXT_WORLD ? ANCIENT_KINDS : []),
]);

/** Kinds that read as landmarks without being any style's signature. */
const LANDMARKS = ['landmark', 'clockTower', 'commsTower', 'observationTower', 'triumphalArch', 'lookoutTower', 'leaningTower',
  'stoneCircle', 'greatWall', 'roadsideGiant', 'giantTree', 'castle', 'hilltopCastle', 'moatedCastle', 'watchtower', 'lostTemple',
  'monumentButtes', 'greatGeyser', 'greatKopje', 'khanStatue', 'dam', 'pyramid', 'scenicOverlook', 'fireLookout', 'waterMill',
  'windmillRow', 'glassSpire', 'circusMaximus', 'dinosaurDig', 'trainCemetery', 'ghostTown', 'abandonedMine', 'shipwreck', 'planeWreck',
  'ruinedAbbey', 'bunker', 'crashedSatellite', 'capeLight', 'hermitCabin', 'drownedVillage', 'hangar18', 'crashSite', 'monolith', 'doorToNowhere',
  'giantChair', 'bigfootStatue', 'giantDuck', 'abandonedBus', 'carhenge', 'planeBoneyard', 'meteorCrater', 'whaleBones', 'stoneHeads',
  'giantSundial', 'giantScarecrow', 'giantSnowman', 'ranchGate', 'fukuzumiro', 'yubatake', 'jigoku', 'lakeTorii', 'jetDeau', 'chillon'];

const CAT_OF: Map<string, Cat> = (() => {
  const m = new Map<string, Cat>();
  for (const [cat, kinds] of Object.entries(GROUPS) as [Cat, readonly string[]][]) for (const k of kinds) if (!m.has(k)) m.set(k, cat);
  for (const k of LANDMARKS) if (!m.has(k)) m.set(k, 'landmark');
  // a style's own signature buildings are its landmarks unless a group above has them (an eatery, a market)
  for (const kinds of signatureKinds().values()) for (const k of kinds) if (!m.has(k)) m.set(k, 'landmark');
  return m;
})();

/** What a building kind is for. A wonder is a wonder whatever else it is. */
export function catOf(kind: string): Cat {
  if (WONDER_SET.has(kind)) return 'wonder';
  return CAT_OF.get(kind) ?? 'other';
}

/** Kinds worth naming on the card even though their category is an everyday one. */
const NOTABLE = new Set<string>(['cityHall', 'university', 'hospital', 'museum', 'library', 'cathedral', 'parliament', 'statehouse',
  'ministry', 'courthouse', 'observatory', 'stadium', 'arena', 'raceCircuit', 'racetrack', 'operaHouse', 'concertHall', 'theatre', 'casino',
  'zoo', 'aquarium', 'waterPark', 'fairground', 'rollerCoaster', 'marina', 'golfCourse', 'pleasurePier', 'iceHotel', 'saltHotel',
  'monastery', 'mosque', 'temple', 'synagogue', 'pagoda', 'greatPark', 'botanicalGarden', 'filmStudio', 'dataCentre', 'exchange',
  'departmentStore', 'mall', 'nightMarket', 'bazaar', 'souk', 'floatingMarket', 'airliner', 'controlTower', 'terminus', 'cityStation',
  'gondolaStation', 'funicular', 'skyDock', 'airshipMast']);

/** Is this kind named in the Notable list? */
export function notable(kind: string): boolean {
  const c = catOf(kind);
  return c === 'wonder' || c === 'landmark' || NOTABLE.has(kind);
}

export interface TownDigest {
  key: string;
  name: string;
  kind: TownKind;
  style: Arch;
  region?: RegionKind;
  /** The county's name. */
  county: string;
  /** The town's middle: its cell and the tile in it. */
  at: [number, number, number, number];
  /** A satellite's megalopolis, by key. */
  parent?: string;
  plan?: string;
  onsen?: string;
  lake?: string;
  canals?: true;
  strip?: true;
  perch?: Perch;
  /** Standing buildings (the graduation count), and the tiles inside its lines. */
  built: number;
  area: number;
  /** Standing buildings and lots by category. */
  cats: Record<Cat, number>;
  /** Kinds worth a chip, most first: [kind, how many]. */
  notable: [BuildingKind, number][];
  /** Buildings by the style they are drawn in: [style, how many], most first. */
  styles: [Arch, number][];
  ports: number;
  majorPort: boolean;
  stations: number;
  airports: number;
  /** Other towns reached by a built road. */
  roadsTo: number;
  /** Boarded up; going up under cranes right now. */
  derelict: number;
  sites: number;
  /** Put up by a fleet from its blueprints. */
  playerBuilt: number;
  /** The game day it was taken on; -1 for one surveyed from afar, which knows no clock. */
  day: number;
  /**
   * Players' works in its lines (net/community.ts townWorks): how many, their hearts and their crossings by other fleets.
   * Not the world's: the town index adds it while the town is in memory and keeps the last count after.
   */
  works?: [number, number, number];
}

const blankCats = (): Record<Cat, number> => Object.fromEntries(CATS.map((c) => [c, 0])) as Record<Cat, number>;

/** How long a town's own building site stands, in game hours (render/townMesh.ts BUILD_HOURS). */
const TOWN_BUILD_HOURS = 2;

/**
 * A town's digest as it stands. `hour` is the game clock in hours, for the building sites still up; left out (a
 * survey worker's copy, which knows no clock) the digest counts no sites and its day is -1. `area` may be passed when
 * the caller already has the town's shape.
 */
export function digestOf(w: World, t: Town, hour?: number, area?: number): TownDigest {
  const cats = blankCats();
  const kinds = new Map<BuildingKind, number>();
  const styles = new Map<Arch, number>();
  let derelict = 0, sites = 0, playerBuilt = 0;
  for (const b of t.buildings) {
    if (b.gone) continue;
    cats[catOf(b.kind)]++;
    if (b.derelict) derelict++;
    if (b.erected) playerBuilt++;
    if (hour !== undefined && b.grownAt !== undefined && hour < b.grownAt + (b.buildHours ?? TOWN_BUILD_HOURS)) sites++;
    if (notable(b.kind)) kinds.set(b.kind, (kinds.get(b.kind) ?? 0) + 1);
    if (b.solid) { const s = b.style ?? t.style; styles.set(s, (styles.get(s) ?? 0) + 1); }
  }
  const ports = w.ports.filter((p) => p.town === t.id);
  const roads = new Set(w.links.filter((l) => l.built && (l.from === t.name || l.to === t.name)).map((l) => (l.from === t.name ? l.to : l.from)));
  const parent = t.parent !== undefined && w.towns[t.parent] ? `${w.cx},${w.cz}#${t.parent}` : undefined;
  const d: TownDigest = {
    key: `${w.cx},${w.cz}#${t.id}`, name: t.name, kind: t.kind, style: t.style, county: w.name,
    at: [w.cx, w.cz, Math.round(t.x0 + t.size / 2), Math.round(t.z0 + t.size / 2)],
    built: builtCount(t), area: area ?? shapeOf(w, t).area, cats,
    notable: [...kinds].sort((a, b) => rankNotable(b[0]) - rankNotable(a[0]) || b[1] - a[1] || a[0].localeCompare(b[0])),
    styles: [...styles].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])),
    ports: ports.length, majorPort: ports.some((p) => p.major), stations: w.stations.filter((s) => s.town === t.id).length,
    airports: airportsOf(w, t).length, roadsTo: roads.size, derelict, sites, playerBuilt, day: hour === undefined ? -1 : Math.floor(hour / 24),
  };
  if (t.region) d.region = t.region;
  if (parent) d.parent = parent;
  if (t.plan && t.plan !== 'grid') d.plan = t.plan;
  if (t.onsen) d.onsen = t.onsen;
  if (t.lake) d.lake = t.lake;
  if (t.canals) d.canals = true;
  if (t.strip) d.strip = true;
  if (t.perch) d.perch = t.perch;
  return d;
}

/** Wonders first, then landmarks, then the rest. */
function rankNotable(kind: string): number {
  const c = catOf(kind);
  return c === 'wonder' ? 2 : c === 'landmark' ? 1 : 0;
}

/**
 * The town a player's work belongs to (docs/townregister.html, net/community.ts): the one whose lines hold the most of
 * its tiles, if that is a third of them or more; -1 for none (a long road between towns belongs to nobody).
 */
export function townOfTiles(tiles: readonly number[], townId: ArrayLike<number>): number {
  const n = new Map<number, number>();
  for (const t of tiles) { const id = townId[t]; if (id >= 0) n.set(id, (n.get(id) ?? 0) + 1); }
  let best = -1, most = 0;
  for (const [id, c] of n) if (c > most) { most = c; best = id; }
  return most > 0 && most * 3 >= tiles.length ? best : -1;
}
