import type { Building } from './tiles';

/**
 * Two-runway international airports (docs/rides.html, "Two runways", 0.7.0 behind NEXT_WORLD): a square of
 * SIDE × SIDE tiles holding two full-length runways at right angles, crossing in the middle (`X`) or meeting at
 * a corner (`L`), each with its taxiway shoulder on the apron's side, and the apron and the terminal in the corner
 * the two shoulders bound. The rest of the square is left to the county: a megalopolis county never has a whole
 * square of it clear, and an L's apron road comes in across it.
 *
 * Everything is worked out here from the plan alone (its square, its shape and which way it is mirrored), so the
 * carving (world/industry.ts cutAirfield), the lots claimed ahead of the roads (reserveWorks), the buildings
 * (buildWorks) and the runways read back for flying (world/runways.ts runwaysOf) can never disagree.
 */

/** As kept on the airfield's Work (world/tiles.ts Work.plan): its square's corner, its shape and its mirroring. */
export interface AirportPlan { shape: 'X' | 'L'; x0: number; z0: number; fu: boolean; fv: boolean }

/** The square's side, a runway's width, its shoulder and the apron's side. */
export const PLAN_SIDE = 48;
const WID = 5, SHOULDER = 2, APRON = 20;

/** What a tile of the square is: the ground between the runways and the apron is left as it was (`none`). */
type PlanTile = 'runway' | 'paved' | 'gravel' | 'apron' | 'none';

/** A strip as a runway is read back from it: its rectangle (local tiles), which axis it runs along, and the side its taxiway and apron are on (+1: toward + across). */
export interface PlanStrip { x0: number; z0: number; alongX: boolean; len: number; wid: number; side: 1 | -1 }

/** In the plan's own frame (u along x, v along z before mirroring): where the runways' rows and the apron lie. */
function frame(shape: 'X' | 'L'): { a: number; b: number; apron: [number, number] } {
  // the x-runway's first row (v) and the z-runway's first column (u); the apron's corner nearest the runways
  if (shape === 'X') { const m = (PLAN_SIDE - WID) >> 1; return { a: m, b: m, apron: [m + WID + SHOULDER, m + WID + SHOULDER] }; }
  return { a: 0, b: 0, apron: [WID + SHOULDER, WID + SHOULDER] };
}

/** The plan's tile at (u, v) of its own frame. */
function tileOf(shape: 'X' | 'L', u: number, v: number): PlanTile {
  const f = frame(shape);
  const onX = v >= f.a && v < f.a + WID, onZ = u >= f.b && u < f.b + WID;
  if (onX || onZ) {
    // a dashed centreline down each, and a paler bar across each threshold
    const mid = (onX && v === f.a + (WID >> 1) && u % 4 < 2 && !onZ) || (onZ && u === f.b + (WID >> 1) && v % 4 < 2 && !onX);
    const edge = (onX && (u < 2 || u >= PLAN_SIDE - 2)) || (onZ && (v < 2 || v >= PLAN_SIDE - 2));
    return edge || mid ? 'paved' : 'runway';
  }
  // the taxiway shoulders, the length of each runway on the apron's side
  if ((v >= f.a + WID && v < f.a + WID + SHOULDER) || (u >= f.b + WID && u < f.b + WID + SHOULDER)) return 'gravel';
  const [au, av] = f.apron;
  if (u >= au && u < au + APRON && v >= av && v < av + APRON) return u === au + APRON - 1 || v === av + APRON - 1 ? 'gravel' : 'apron';
  return 'none';
}

/** Local tiles (in the county) of plan point (u, v), mirrored as the plan says. */
const at = (p: AirportPlan, u: number, v: number): [number, number] => [p.x0 + (p.fu ? PLAN_SIDE - 1 - u : u), p.z0 + (p.fv ? PLAN_SIDE - 1 - v : v)];
/** A rectangle [u, u+w) × [v, v+d) of the plan's frame, as local tiles (x, z, w, d). */
function rect(p: AirportPlan, u: number, v: number, w: number, d: number): [number, number, number, number] {
  const x = p.fu ? p.x0 + PLAN_SIDE - u - w : p.x0 + u, z = p.fv ? p.z0 + PLAN_SIDE - v - d : p.z0 + v;
  return [x, z, w, d];
}

/** The rectangles the airport needs clear and level, local tiles (x, z, w, d): each runway with its taxiway, and the apron. */
export function planRects(p: AirportPlan): [number, number, number, number][] {
  const f = frame(p.shape), [au, av] = f.apron;
  return [rect(p, 0, f.a, PLAN_SIDE, WID + SHOULDER), rect(p, f.b, 0, WID + SHOULDER, PLAN_SIDE), rect(p, au, av, APRON, APRON)];
}

/** Every tile of the square, local tiles, and what it is. */
export function planTiles(p: AirportPlan, put: (x: number, z: number, t: PlanTile) => void): void {
  for (let v = 0; v < PLAN_SIDE; v++) for (let u = 0; u < PLAN_SIDE; u++) { const [x, z] = at(p, u, v); put(x, z, tileOf(p.shape, u, v)); }
}

/** The two runways' strips, local tiles: the x-running one first. */
export function planStrips(p: AirportPlan): PlanStrip[] {
  const f = frame(p.shape);
  const [sx, sz] = rect(p, 0, f.a, PLAN_SIDE, WID);
  const [tx, tz] = rect(p, f.b, 0, WID, PLAN_SIDE);
  return [
    { x0: sx, z0: sz, alongX: true, len: PLAN_SIDE, wid: WID, side: p.fv ? -1 : 1 },
    { x0: tx, z0: tz, alongX: false, len: PLAN_SIDE, wid: WID, side: p.fu ? -1 : 1 },
  ];
}

/** The apron's two live stands (both runways share them), local tiles, each nose toward the runway it sits nearest. */
export function planStands(p: AirportPlan): { x: number; z: number; heading: number }[] {
  const [au, av] = frame(p.shape).apron;
  const out: { x: number; z: number; heading: number }[] = [];
  // one by the x-runway's taxiway, nose toward it; one by the z-runway's
  for (const [u, v, toward] of [[au + 9.5, av + 3.5, 'v'], [au + 3.5, av + 9.5, 'u']] as const) {
    const [x, z] = at(p, u, v);
    // the runway is at lower v (or u) in the plan's frame: mirrored, at higher
    const hx = toward === 'u' ? (p.fu ? 1 : -1) : 0, hz = toward === 'v' ? (p.fv ? 1 : -1) : 0;
    out.push({ x: x + 0.5, z: z + 0.5, heading: Math.atan2(hx, hz) });
  }
  return out;
}

/** The apron's buildings, local tiles: the terminal, the tower and two hangars along the outer edges, and a parked airliner. */
export function planBuildings(p: AirportPlan): { kind: Building['kind']; x: number; z: number; w: number; d: number; facing: number; floors: number; solid: boolean }[] {
  const [au, av] = frame(p.shape).apron;
  // facings in the plan's frame: 3 looks toward −v (the x-runway), 2 toward −u (the z-runway), mirrored with the plan
  const face = (f: 2 | 3) => (f === 3 ? (p.fv ? 1 : 3) : (p.fu ? 0 : 2));
  const b = (kind: Building['kind'], u: number, v: number, w: number, d: number, f: 2 | 3, floors: number, solid = true) => {
    const [x, z, rw, rd] = rect(p, au + u, av + v, w, d);
    return { kind, x, z, w: rw, d: rd, facing: face(f), floors, solid };
  };
  return [
    b('terminal', 2, 14, 10, 5, 3, 2),
    b('controlTower', 15, 15, 3, 3, 3, 4),
    b('hangar', 13, 1, 6, 5, 2, 1),
    b('hangar', 13, 7, 6, 5, 2, 1),
    b('airliner', 7, 7, 4, 4, 3, 2, false),
  ];
}

/** Where the approach road meets the airport: the middle of the apron's outer edge, beside the terminal. */
export function planGate(p: AirportPlan): [number, number] {
  const [au, av] = frame(p.shape).apron;
  return at(p, au + APRON - 1, av + APRON - 1 - 2);
}

/** Centre tile of the apron, for the Work's x, z (labels, the camera, the card). */
export function planCentre(p: AirportPlan): [number, number] {
  const [au, av] = frame(p.shape).apron;
  return at(p, au + APRON / 2, av + APRON / 2);
}
