/**
 * Lower corners until every tile is one of the 19 legal shapes and every non-wall edge is
 * continuous. Only ever lowers, so it converges.
 *
 *  - adjacent corners within a tile differ by at most 1
 *  - diagonal corners differ by at most diagLimit[tile] (1 normally, 2 where steep is allowed)
 *  - across a non-wall edge the two tiles agree on both shared corners (taken as the min)
 *
 * The grid width is a parameter because the terrain stages run on a grid padded into every
 * neighbouring cell. That padding is only worth having if a correction cannot travel further than
 * it is wide, so the continuity pass reads the previous state and writes the next: a lowering then
 * moves exactly one tile per pass, and `reach` is a hard bound on how far it can carry. Two cells
 * that share a strip of ground, and agree on everything within `reach` of it, therefore agree on
 * the corners along it — which is the whole of why land can run across a cell border.
 *
 * Returns the number of passes, which is also the furthest anything moved.
 */
export function legalise(
  c: Int8Array, wallX: Uint8Array, wallZ: Uint8Array, diagLimit: Uint8Array, W: number, reach = 28,
): number {
  const WW = W * W;
  const prev = new Int8Array(c.length);

  /** Within one tile: pointwise, so it carries nothing from tile to tile. */
  const shapes = (): boolean => {
    let changed = false;
    for (let i = 0; i < WW; i++) {
      const b = i * 4;
      const lim = diagLimit[i];
      for (let k = 0; k < 4; k++) {
        const ka = b + k, kb = b + ((k + 1) & 3);
        if (c[ka] > c[kb] + 1) { c[ka] = c[kb] + 1; changed = true; }
        else if (c[kb] > c[ka] + 1) { c[kb] = c[ka] + 1; changed = true; }
      }
      if (c[b] > c[b + 2] + lim) { c[b] = c[b + 2] + lim; changed = true; }
      else if (c[b + 2] > c[b] + lim) { c[b + 2] = c[b] + lim; changed = true; }
      if (c[b + 1] > c[b + 3] + lim) { c[b + 1] = c[b + 3] + lim; changed = true; }
      else if (c[b + 3] > c[b + 1] + lim) { c[b + 3] = c[b + 1] + lim; changed = true; }
    }
    return changed;
  };

  shapes();   // the first tidy-up is pointwise, so it costs no travel
  let passes = 0;
  for (; passes < reach; passes++) {
    prev.set(c);
    let changed = false;
    // continuity across non-wall edges, read from the previous state so nothing skips ahead
    for (let z = 0; z < W; z++) {
      for (let x = 0; x < W; x++) {
        const i = z * W + x;
        const b = i * 4;
        if (x < W - 1 && !wallX[i]) {
          const r = b + 4; // tile (x+1, z): my c1 = its c0, my c2 = its c3
          let m = Math.min(prev[b + 1], prev[r]);
          if (c[b + 1] > m) { c[b + 1] = m; changed = true; }
          if (c[r] > m) { c[r] = m; changed = true; }
          m = Math.min(prev[b + 2], prev[r + 3]);
          if (c[b + 2] > m) { c[b + 2] = m; changed = true; }
          if (c[r + 3] > m) { c[r + 3] = m; changed = true; }
        }
        if (z < W - 1 && !wallZ[i]) {
          const d = b + W * 4; // tile (x, z+1): my c3 = its c0, my c2 = its c1
          let m = Math.min(prev[b + 3], prev[d]);
          if (c[b + 3] > m) { c[b + 3] = m; changed = true; }
          if (c[d] > m) { c[d] = m; changed = true; }
          m = Math.min(prev[b + 2], prev[d + 1]);
          if (c[b + 2] > m) { c[b + 2] = m; changed = true; }
          if (c[d + 1] > m) { c[d + 1] = m; changed = true; }
        }
      }
    }
    if (shapes()) changed = true;
    if (!changed) break;
  }
  return passes;
}
