/**
 * Landforms: the shapes the generator points its existing tools at to make places worth finding.
 *
 * Two kinds live here. Cell-anchored giants — a volcano, a caldera, a salt pan, a karst field, mesa
 * country, an atoll — are decided by the macro layer and stay at least 64 tiles inside their cell,
 * clear of the band a neighbour shares, so only the cell that owns one ever draws it. Regional
 * fields — fjords, dunes, badlands, a rift, glaciers, skerries, mountain passes — are pointwise on
 * the global tile, sampled by every cell whose padded grid reaches them, and so agree across a
 * border without either side knowing the other exists.
 */
import { N, SEA, Biome, Surface, type CellKind, type LandformKind } from './tiles';
import { hash2, hashCell, cellNoise } from './rng';
import { Noise2D, smoothstep } from './noise';
import { climateAt, featureAt, featurePlace } from './macro';
import { NEXT_WORLD } from './nextWorld';

const TAU = Math.PI * 2;

/** One mountain from the global peak grid, with an optional saddle notched into its ridge. */
export interface Peak {
  x: number; z: number; x2: number; z2: number; h: number; slope: number;
  /** Where along the ridge (0..1) the pass is, how deep it dips, and over how many tiles. */
  saddle?: { t: number; dip: number; width: number; len: number };
  /** A glacier flowing off it: direction, length and width in tiles. */
  glacier?: { ang: number; len: number; width: number };
}

/**
 * A lobed outline for a lake, a pan or a lava flow, from a hash of where it is: the scale of its radius
 * in each direction, 0.78 to about 1.3, stretched along one axis and with two or three bays. Divide
 * a distance by it to read the shape's own round distance.
 */
export function blobScale(x: number, z: number, salt: number, stretch = 0.22): (ang: number) => number {
  const h = (k: number) => hash2(Math.floor(x), Math.floor(z), salt + k);
  const axis = h(1) * Math.PI, p3 = h(2) * TAU, p5 = h(3) * TAU;
  const a2 = stretch * (0.5 + 0.5 * h(4)), a3 = 0.12 * h(5), a5 = 0.06 * h(6);
  return (ang) => Math.max(0.78, 1 + a2 * Math.cos(2 * (ang - axis)) + a3 * Math.cos(3 * ang + p3) + a5 * Math.cos(5 * ang + p5));
}

/** How far, in tiles, the ground a range stands on is pushed about, so its outline wanders. */
const MOUNT_WARP = 12;

/** Where a global tile reads the ranges from: pushed about by a slow field, the same for every cell. */
export function mountWarp(nB: Noise2D, gx: number, gz: number): [number, number] {
  const u = gx / N, v = gz / N;
  return [gx + MOUNT_WARP * nB.fbm(u * 2.2 + 91, v * 2.2 + 37, 2), gz + MOUNT_WARP * nB.fbm(u * 2.2 + 13, v * 2.2 + 83, 2)];
}

/** Distance from (x, z) to a ridge line, and how far along it the nearest point is. */
export function segNear(x: number, z: number, p: Peak): [number, number] {
  const vx = p.x2 - p.x, vz = p.z2 - p.z;
  const l2 = vx * vx + vz * vz;
  let t = l2 > 0 ? ((x - p.x) * vx + (z - p.z) * vz) / l2 : 0;
  t = t < 0 ? 0 : t > 1 ? 1 : t;
  const dx = x - (p.x + t * vx), dz = z - (p.z + t * vz);
  return [Math.sqrt(dx * dx + dz * dz), t];
}

/** A peak's crest height at a point along its ridge, with the saddle taken out. */
export function crestAt(p: Peak, t: number): number {
  if (!p.saddle) return p.h;
  const s = ((t - p.saddle.t) * p.saddle.len) / p.saddle.width;
  return p.h - p.saddle.dip * Math.exp(-s * s);
}

/** Give some ridges a pass and some cold high peaks a glacier; pure functions of the peak's grid cell. */
export function decoratePeak(p: Peak, seedHash: number, gi: number, gj: number): void {
  const salt = (seedHash & 0xffff) + 900;
  const len = Math.hypot(p.x2 - p.x, p.z2 - p.z);
  if (len > 30 && p.h > 10 && hash2(gi, gj, salt) < 0.55) {
    const dip = Math.min(p.h - 4, Math.max(6, p.h * 0.45));
    p.saddle = { t: 0.3 + hash2(gi, gj, salt + 1) * 0.4, dip, width: 12 + hash2(gi, gj, salt + 2) * 4, len };
  }
  const { temp } = climateAt(seedHash, p.x / N, p.z / N);
  if (p.h >= 15 && temp < 0.42 && hash2(gi, gj, salt + 3) < 0.5) {
    p.glacier = { ang: hash2(gi, gj, salt + 4) * TAU, len: 60 + hash2(gi, gj, salt + 5) * 50, width: 15 + hash2(gi, gj, salt + 6) * 8 };
  }
}

/** What stage 3 knows about a tile, and what the landforms may change about it. */
export interface TileCtx {
  gx: number; gz: number; u: number; v: number;
  /** Coast distance, climate, and the hill mask. */
  cd: number; moisture: number; temp: number; arid: number; hillMask: number;
  /** The lowland before mountains, and the mountain envelope so far. */
  e: number; mount: number;
  /** Outputs: a biome to force (255 for none), a surface, a mountain-mask floor, no towns here. */
  biome: number; surface: number; mask: number; noTown: boolean;
  /** Mesa sides get terraced at every level; a crater or caldera bowl holds a lake at this level. */
  mesaWall: boolean; lake: number;
  /** How much a biome asks for dunes over this tile whatever the erg field says, 0..1. */
  regionErg: number;
  /** And for badlands, 0..1. */
  regionBad: number;
  /** How far a continent's heart and its high country have lifted the ground here, in steps. */
  lift: number;
}

interface Mesa { x: number; z: number; r: number; top: number; ramp: number; axis: number; aspect: number; shape: (ang: number) => number }

/** A named landform decided for this cell, in global tiles. */
export interface Placed { kind: LandformKind; name: string; gx: number; gz: number; r: number; data: number[] }

