  fjordCoast: (a) => `${a} Fjords`,
  riftValley: (a) => `the ${a} Rift`,
  dunes: (a) => `the ${a} Erg`,
  saltFlat: (a) => `${a} Salt Pan`,
  glacier: (a) => `${a} Glacier`,
  karstTowers: (a) => `the ${a} Towers`,
  badlands: (a) => `the ${a} Badlands`,
  mesaCountry: (a) => `${a} Mesas`,
  delta: (a) => `${a} Delta`,
  skerries: (a) => `the ${a} Skerries`,
  mangroves: (a) => `${a} Mangroves`,
  erratics: (a) => `the ${a} Stones`,
  mountainPass: (a) => `${a} Pass`,
  lavaField: (a) => `${a} Lava Field`,
  gorge: (a) => `${a} Gorge`,
  cascade: (a) => `${a} Falls`,
