/** What each landform is called under its name on the overview; the common ones go unlabelled. */
/** How far out from the coast, in tiles, skerries stand. */
export const SKERRY_REACH = 26;

export const LANDFORM_LABEL: Partial<Record<LandformKind, string>> = {
  volcano: 'Volcano', caldera: 'Caldera', atoll: 'Lagoon', fjordCoast: 'Fjord coast', riftValley: 'Rift valley', dunes: 'Sand sea',
  saltFlat: 'Salt flat', glacier: 'Glacier', karstTowers: 'Tower karst', badlands: 'Badlands', mesaCountry: 'Mesa country',
  delta: 'River delta', skerries: 'Skerries', mangroves: 'Mangrove swamp', mountainPass: 'Mountain pass', lavaField: 'Lava field',
  gorge: 'Gorge', cascade: 'Waterfall', tarn: 'Mountain lake', hoodoos: 'Hoodoos', tombolo: 'Sandbar', hotSprings: 'Hot springs',
  seaArch: 'Sea arch', sinkhole: 'Sinkhole', basaltColumns: 'Basalt columns', caveTunnel: 'Cave', naturalBridge: 'Natural bridge',
  erratics: 'Standing stones',
  grove: 'Ancient trees',
  waterfall: 'Great waterfall',
  // a ranch's pasture (world/ranches.ts): only in the next world, so GEN 52's Passport page and deed ladder keep their count
  ...(NEXT_WORLD ? { ranch: 'Ranch' } : {}),
};

/** A landform's name, from a hash of where it is. */
export function landformName(kind: LandformKind, seedHash: number, gx: number, gz: number): string {
  const h = hashCell(seedHash, Math.floor(gx), Math.floor(gz), 991);
  return (NAME_FORM[kind] ?? ((a: string) => a))(NAME_A[h % NAME_A.length]);
}

/**
 * A slow macro field sampled on a lattice of global tiles eight apart and interpolated between,
 * so a per-tile read is four array lookups rather than four hashes. The lattice is anchored to the
 * global origin, so two cells reading the same tile read exactly the same number.
 */
class SlowField {
  private static readonly S = 8;
  private readonly vals: Float32Array;
  private readonly W: number;
  private readonly gx0: number;
  private readonly gz0: number;
  constructor(seedHash: number, x0: number, z0: number, x1: number, z1: number, scale: number, salt: number) {
    const S = SlowField.S;
    this.gx0 = Math.floor(x0 / S) - 1;
    this.gz0 = Math.floor(z0 / S) - 1;
    this.W = Math.ceil(Math.max(x1 - x0, z1 - z0) / S) + 4;
    this.vals = new Float32Array(this.W * this.W);
    for (let j = 0; j < this.W; j++) {
      for (let i = 0; i < this.W; i++) {
        this.vals[j * this.W + i] = cellNoise(seedHash, ((this.gx0 + i) * S) / N, ((this.gz0 + j) * S) / N, scale, salt);
      }
    }
  }
  at(gx: number, gz: number): number {
    const S = SlowField.S, fx = gx / S - this.gx0, fz = gz / S - this.gz0;
    const i = Math.max(0, Math.min(this.W - 2, Math.floor(fx))), j = Math.max(0, Math.min(this.W - 2, Math.floor(fz)));
    const tx = fx - i, tz = fz - j, W = this.W, v = this.vals;
    const a = v[j * W + i] + (v[j * W + i + 1] - v[j * W + i]) * tx;
    const b = v[(j + 1) * W + i] + (v[(j + 1) * W + i + 1] - v[(j + 1) * W + i]) * tx;
    return a + (b - a) * tz;
  }
}

export class Landforms {
  /** Landforms decided for this cell before it is generated, in global tiles. */
  readonly placed: Placed[] = [];
  private volcano: { x: number; z: number; r: number; wind: number; glow: boolean; field: { x: number; z: number; r: number; shape: (ang: number) => number } | null } | null = null;
  private caldera: { x: number; z: number; r: number; rim: number; breach: number } | null = null;
  private salt: { x: number; z: number; r: number; axis: number; shape: (ang: number) => number } | null = null;
  private karst: { x: number; z: number; r: number } | null = null;
  private mesas: Mesa[] = [];
  private mesaField: { x: number; z: number; r: number } | null = null;
  readonly atoll: { x: number; z: number; r: number; bulge: number } | null = null;
  private salt32: number;
  private glaciers: Peak[];
  private warmth: SlowField;
  private ergField: SlowField;
  private ergDir: SlowField;
  private badField: SlowField;
  private riftGate: SlowField;
  private riftLine: SlowField;

  constructor(private seedHash: number, cx: number, cz: number, kind: CellKind, private nA: Noise2D, private nB: Noise2D, private peaks: Peak[]) {
    const ox = cx * N, oz = cz * N;
    const PADX = 48;
    const field = (scale: number, salt: number) => new SlowField(seedHash, ox - PADX, oz - PADX, ox + N + PADX, oz + N + PADX, scale, salt);
    this.warmth = field(5.5, 7);
    this.ergField = field(2.5, 71);
    this.ergDir = field(8, 73);
    this.badField = field(3, 81);
    this.riftGate = field(20, 63);
    this.riftLine = field(6, 61);
    this.glaciers = peaks.filter((p) => p.glacier);
    this.salt32 = hashCell(seedHash, cx, cz, 12) & 0xffff;
    const put = (k: LandformKind, gx: number, gz: number, r: number, data: number[] = []) =>
      this.placed.push({ kind: k, name: landformName(k, seedHash, gx, gz), gx, gz, r, data });
    if (featureAt(seedHash, cx, cz, 'volcano')) {
      const p = featurePlace(seedHash, cx, cz, 'volcano');
      const gx = ox + p.x, gz = oz + p.z;
      const wind = hash2(cx, cz, 7771) * TAU;
      const glow = p.roll < 0.34;
      // one volcano in four has a lava field on its flank
      let field = null;
      if (hash2(cx, cz, 7772) < 0.25 || p.roll > 0.9) {
        const a = hash2(cx, cz, 7773) * TAU, fr = 15 + hash2(cx, cz, 7774) * 12;
        field = { x: gx + Math.cos(a) * p.r * 0.62, z: gz + Math.sin(a) * p.r * 0.62, r: fr, shape: blobScale(gx + a, gz + fr, 4431, 0.3) };
      }
      this.volcano = { x: gx, z: gz, r: p.r, wind, glow, field };
      put('volcano', gx, gz, p.r, [glow ? 1 : 0, wind]);
      if (field) put('lavaField', field.x, field.z, field.r);
    }
    if (featureAt(seedHash, cx, cz, 'caldera')) {
      const p = featurePlace(seedHash, cx, cz, 'caldera');
      this.caldera = { x: ox + p.x, z: oz + p.z, r: p.r, rim: 14 + p.roll * 4, breach: hash2(cx, cz, 7781) * TAU };
      put('caldera', ox + p.x, oz + p.z, p.r);
    }
    if (kind === 'atoll') {
      const p = featurePlace(seedHash, cx, cz, 'atoll');
      this.atoll = { x: ox + p.x, z: oz + p.z, r: p.r, bulge: hash2(cx, cz, 7791) * TAU };
      put('atoll', ox + p.x, oz + p.z, p.r);
    }
    if (featureAt(seedHash, cx, cz, 'saltFlat')) {
      const p = featurePlace(seedHash, cx, cz, 'saltFlat');
      this.salt = { x: ox + p.x, z: oz + p.z, r: p.r, axis: hash2(cx, cz, 7795) * Math.PI, shape: blobScale(ox + p.x, oz + p.z, 4441, 0.18) };
      put('saltFlat', ox + p.x, oz + p.z, p.r);
    }
    if (featureAt(seedHash, cx, cz, 'karstTowers') && !this.volcano && !this.caldera && !this.salt) {
      const p = featurePlace(seedHash, cx, cz, 'karstTowers');
      this.karst = { x: ox + p.x, z: oz + p.z, r: p.r };
      put('karstTowers', ox + p.x, oz + p.z, p.r);
    }
    if (featureAt(seedHash, cx, cz, 'mesaCountry') && !this.volcano && !this.caldera && !this.salt && !this.karst) {
      const p = featurePlace(seedHash, cx, cz, 'mesaCountry');
      const gx = ox + p.x, gz = oz + p.z;
      this.mesaField = { x: gx, z: gz, r: p.r };
      const n = 3 + Math.floor(hash2(cx, cz, 7801) * 5);
      for (let k = 0; k < n * 4 && this.mesas.length < n; k++) {
        const a = hash2(cx, cz, 7810 + k) * TAU, d = Math.sqrt(hash2(cx, cz, 7830 + k)) * (p.r - 12);
        const mx = gx + Math.cos(a) * d, mz = gz + Math.sin(a) * d;
        const m: Mesa = {
          x: mx, z: mz, r: 7 + hash2(cx, cz, 7850 + k) * 7, top: 8 + hash2(cx, cz, 7870 + k) * 5, ramp: hash2(cx, cz, 7890 + k) * TAU,
          // a butte drawn out along the old drainage, with bays eaten into its walls
          axis: hash2(cx, cz, 7910 + k) * Math.PI, aspect: 1 + 0.5 * hash2(cx, cz, 7930 + k), shape: blobScale(mx, mz, 4451, 0.12),
        };
        if (this.mesas.some((o) => Math.hypot(o.x - m.x, o.z - m.z) < (o.r * o.aspect) + (m.r * m.aspect) + 8)) continue;
        this.mesas.push(m);
      }
      put('mesaCountry', gx, gz, p.r);
    }
    // passes and glaciers are named where their crest or their snout lies in this cell
    for (const pk of peaks) {
      if (pk.saddle) {
        const t = pk.saddle.t, rx = pk.x + (pk.x2 - pk.x) * t, rz = pk.z + (pk.z2 - pk.z) * t;
        // the ground was read through the warp, so the saddle stands about where the warp came from
        const [wx, wz] = mountWarp(nB, rx, rz);
        const sx = 2 * rx - wx, sz = 2 * rz - wz;
        if (sx >= ox + 16 && sz >= oz + 16 && sx < ox + N - 16 && sz < oz + N - 16) put('mountainPass', sx, sz, pk.saddle.width, [SEA + pk.h - pk.saddle.dip]);
      }
      if (pk.glacier) {
        const g = pk.glacier, mx = pk.x + Math.cos(g.ang) * g.len * 0.5, mz = pk.z + Math.sin(g.ang) * g.len * 0.5;
        if (mx >= ox && mz >= oz && mx < ox + N && mz < oz + N) put('glacier', mx, mz, g.len * 0.5);
      }
    }
  }

  get hasVolcano(): boolean { return !!this.volcano; }

  /** How much a biome lets the sea in along fjords at a global tile whatever the climate, 0..1 (the Fjordlands). */
  fjordBoost: ((gx: number, gz: number) => number) | null = null;

  // ---- stage 1: the outline of the land ----

  /** Cold cliff coast, 0..1: where fjords may cut in. Pointwise on the global position in cells. */
  fjordZone(u: number, v: number): number {
    const t = 1.25 - v * 0.055 + (this.warmth.at(u * N, v * N) - 0.5) * 0.7;
    const cold = smoothstep(0.44, 0.34, t);
    const boost = this.fjordBoost ? this.fjordBoost(u * N, v * N) : 0;
    if (cold <= 0 && boost <= 0) return 0;
    const cliff = smoothstep(-0.05, 0.45, this.nB.fbm(u * 1.4 + 40, v * 1.4 + 40, 1));
    // fjord country is fjords on every coast, not only where the cliff field says
    return Math.max(cold * cliff, boost * (0.55 + 0.45 * cliff));
  }

  /** The fingers of the fjords: narrow ridged lines in the cold cliff zone, 0..1. */
  fjordFinger(u: number, v: number): number {
    const z = this.fjordZone(u, v);
    if (z <= 0) return 0;
    const ridge = 1 - Math.abs(this.nA.fbm(u * 7 + 71, v * 7 + 13, 2));
    return z * smoothstep(0.9, 0.975, ridge);
  }

  /** How much the fjords cut from the land field here (islands and continents scale differently). */
  fjordCut(u: number, v: number, cont: boolean): number {
    const f = this.fjordFinger(u, v);
    return f <= 0 ? 0 : f * (cont ? 0.9 : 0.42);
  }

  /** The land field of an atoll: a ring broken into motus, with one wide motu for its village. */
  atollLand(gx: number, gz: number): number {
    const a = this.atoll!;
    const dx = gx - a.x, dz = gz - a.z, d = Math.hypot(dx, dz);
    const ang = Math.atan2(dz, dx);
    let da = ang - a.bulge;
    da = Math.atan2(Math.sin(da), Math.cos(da));
    const bulge = 34 * Math.exp(-(da * da) / (2 * 0.36 * 0.36));
    const half = 3.5 + 1.5 * this.nA.fbm(Math.cos(ang) * 3 + 5, Math.sin(ang) * 3 + 9, 2) + bulge;
    // the gaps between motus, never in the village's motu
    const gap = Math.sin(ang * 9 + a.bulge * 3) + 0.7 * this.nA.fbm(Math.cos(ang) * 6 + 1, Math.sin(ang) * 6 + 2, 2);
    if (gap > 0.55 && bulge < 3) return -1;
    return half - Math.abs(d - a.r + bulge * 0.5);
  }

  /** Inside an atoll's ring: the lagoon. */
  inLagoon(gx: number, gz: number): boolean {
    const a = this.atoll;
    return !!a && Math.hypot(gx - a.x, gz - a.z) < a.r - 2;
  }

  // ---- stage 3: relief, biome and surface ----

  /** Dune sand over the hills of an erg: 0..3.2 steps, and how much of an erg this is. */
  dunes(t: TileCtx): [number, number] {
    if (t.arid < 0.45 && t.regionErg <= 0) return [0, 0];
    let erg = smoothstep(0.55, 0.68, this.ergField.at(t.gx, t.gz)) * smoothstep(0.45, 0.6, t.arid) * smoothstep(3, 10, t.cd);
    if (t.regionErg > 0) erg = Math.max(erg, t.regionErg * smoothstep(3, 10, t.cd));
    if (erg <= 0) return [0, 0];
    const dir = this.ergDir.at(t.gx, t.gz) * Math.PI;
    const s = t.gx * Math.cos(dir) + t.gz * Math.sin(dir) + this.nA.fbm(t.u * 6 + 3, t.v * 6 + 8, 2) * 7;
    const ph = s / 17, f = ph - Math.floor(ph);
    const profile = f < 0.72 ? f / 0.72 : (1 - f) / 0.28;
    return [3.2 * profile * erg, erg];
  }

  /** Badland banding strength here, 0..1: arid hill country only. */
  badlands(t: TileCtx): number {
    if (t.hillMask < 0.35 || (t.arid < 0.4 && t.regionBad <= 0)) return 0;
    const hilly = smoothstep(0.35, 0.5, t.hillMask);
    const own = t.arid < 0.4 ? 0 : smoothstep(0.6, 0.7, this.badField.at(t.gx, t.gz)) * smoothstep(0.4, 0.55, t.arid) * hilly;
    // the Red Rock: the same banding over most of its hill country, the rest left as open desert to build on
    const asked = t.regionBad > 0 ? t.regionBad * smoothstep(0.4, 0.52, this.badField.at(t.gx, t.gz)) * hilly : 0;
    return Math.max(own, asked);
  }

  /** A rift trough, 0..1, and how deep: continents only, very rare, pointwise on the global tile. */
  rift(u: number, v: number): number {
    const X = u * N, Z = v * N;
    const gate = smoothstep(0.74, 0.8, this.riftGate.at(X, Z));
    if (gate <= 0) return 0;
    const f = this.riftLine.at(X, Z) - 0.5;
    const e = 6;
    const gx = (this.riftLine.at(X + e, Z) - this.riftLine.at(X - e, Z)) / (2 * e);
    const gz = (this.riftLine.at(X, Z + e) - this.riftLine.at(X, Z - e)) / (2 * e);
    const grad = Math.hypot(gx, gz);            // per tile
    if (grad < 1e-6) return 0;
    const dist = Math.abs(f) / grad;            // tiles from the rift's centre line
    return gate * smoothstep(19, 7, dist);
  }

  /**
   * Everything relief-shaped at one tile of the padded grid: the cell's own giants, and the global
   * fields. Reads and writes the context; `e` comes in as the lowland and goes out as the ground.
   */
  shape(t: TileCtx, cont: boolean): void {
    const { gx, gz } = t;
    const v = this.volcano;
    if (v) {
      const d = Math.hypot(gx - v.x, gz - v.z);
      if (d < v.r + 4) {
        const H = 21;
        let m = H * (1 - d / v.r);
        // the crater: a smooth bowl scooped from the summit
        if (d < 10) m -= 3.5 * (1 + Math.cos((Math.PI * d) / 10));
        // four lava ribs running down the flanks
        const ang = Math.atan2(gz - v.z, gx - v.x);
        for (let k = 0; k < 4; k++) {
          let da = ang - (v.wind + k * (TAU / 4) + 0.4);
          da = Math.atan2(Math.sin(da), Math.cos(da));
          const lat = Math.abs(da) * d;
          if (d > 9 && d < v.r * 0.85 && lat < 3) m += 1.4 * (1 - lat / 3);
        }
        if (m > t.mount) t.mount = m;
        if (d < 6) t.lake = v.glow ? -1 : -2;
        t.noTown = t.noTown || d < v.r * 0.8;
        // the summit: a ragged cap of cinder and old flows, snow lying on the windward side only where
        // it is cold enough, and fresh lava in tongues down the leeward ribs rather than half a disc
        const capR = 22 * (0.8 + 0.35 * (0.5 + 0.5 * this.nA.fbm(Math.cos(ang) * 1.6 + 11, Math.sin(ang) * 1.6 + 5, 2)));
        if (d < capR && SEA + m >= 14) {
          const lee = Math.cos(ang - v.wind + 0.9 * this.nA.fbm(gx * 0.05 + 3, gz * 0.05 + 8, 2)) < -0.15;
          const { temp } = climateAt(this.seedHash, gx / N, gz / N);
          let tongue = false;
          for (let k = 0; k < 4 && !tongue; k++) {
            let da = ang - (v.wind + k * (TAU / 4) + 0.4);
            da = Math.atan2(Math.sin(da), Math.cos(da));
            tongue = Math.abs(da) * d < 2.2 + 1.5 * (0.5 + 0.5 * this.nA.fbm(gx * 0.2, gz * 0.2, 1));
          }
          if (v.glow ? tongue || d < 9 : lee && tongue) { t.biome = Biome.Lava; t.surface = Surface.Lava; }
          else if (!lee && temp < 0.75) { t.biome = Biome.Snow; t.surface = 0; }
          else { t.biome = Biome.Mountain; t.surface = Surface.Rock; }
        }
        if (d < 6 && v.glow) { t.biome = Biome.Lava; t.surface = Surface.Lava; }
      }
      if (v.field) {
        // a flow that ran downhill from the flank: stretched away from the cone, lobed at its toe
        const fx = gx - v.field.x, fz = gz - v.field.z;
        const away = Math.atan2(v.field.z - v.z, v.field.x - v.x);
        const along = fx * Math.cos(away) + fz * Math.sin(away), across = -fx * Math.sin(away) + fz * Math.cos(away);
        const lobes = v.field.shape(Math.atan2(fz, fx)) * (1 + 0.3 * this.nA.fbm(gx * 0.06, gz * 0.06, 3));
        const df = Math.max(Math.hypot(along / 1.45, across / 0.8) / lobes, Math.hypot(fx, fz) / 1.6);
        if (df < v.field.r && t.cd > 3) { t.biome = Biome.Lava; t.surface = Surface.Lava; t.noTown = true; }
      }
    }
    const c = this.caldera;
    if (c) {
      const d = Math.hypot(gx - c.x, gz - c.z);
      if (d < c.r + 36) {
        let da = Math.atan2(gz - c.z, gx - c.x) - c.breach;
        da = Math.atan2(Math.sin(da), Math.cos(da));
        // six to eight rim segments: a polygon, not a circle, and one side broken through
        const facets = 7, fa = Math.atan2(gz - c.z, gx - c.x) + c.breach;
        const poly = Math.cos(Math.PI / facets) / Math.cos(((fa % (TAU / facets)) + TAU / facets) % (TAU / facets) - Math.PI / facets);
        const rr = c.r * poly;
        const breach = smoothstep(0.75, 0.2, Math.abs(da));
        const rim = c.rim * (1 - 0.86 * breach);
        let m: number;
        if (d >= rr) m = rim - 0.5 * (d - rr);
        else m = Math.max(0.6, rim - 0.4 * (rr - d));
        if (d < rr) {
          t.e = Math.min(t.e, m);
          t.mount = m;
          t.noTown = t.noTown || m > 2;
          if (m <= 2.2) { t.lake = SEA + 2; t.mount = 0.4; }
        } else if (m > t.mount) t.mount = m;
      }
    }
    const k = this.karst;
    if (k) {
      const d = Math.hypot(gx - k.x, gz - k.z);
      if (d < k.r + 12) {
        const inside = smoothstep(k.r + 12, k.r, d);
        // a flat wet plain between the towers
        t.e = t.e * (1 - inside) + Math.min(t.e, 1.4) * inside;
        const G = 18, gi = Math.floor(gx / G), gj = Math.floor(gz / G);
        for (let dj = -1; dj <= 1; dj++) {
          for (let di = -1; di <= 1; di++) {
            const px = (gi + di + 0.2 + 0.6 * hash2(gi + di, gj + dj, this.salt32 + 1)) * G;
            const pz = (gj + dj + 0.2 + 0.6 * hash2(gi + di, gj + dj, this.salt32 + 2)) * G;
            if (Math.hypot(px - k.x, pz - k.z) > k.r) continue;
            const ht = 6 + 5 * hash2(gi + di, gj + dj, this.salt32 + 3);
            const m = Math.min(ht, ht - 0.8 * (Math.hypot(gx - px, gz - pz) - 1.2));
            if (m > t.mount) t.mount = m;
            if (m > 2.5) { t.mask = 1; t.biome = Biome.Forest; }
            // the towers and their foot are no place for a street; the flat paddies between them are
            if (m > 0.6) t.noTown = true;
          }
        }
      }
    }
    if (this.mesaField) {
      for (const ms of this.mesas) {
        const ex = gx - ms.x, ez = gz - ms.z;
        if (Math.abs(ex) > ms.r * ms.aspect * 1.2 + 20 || Math.abs(ez) > ms.r * ms.aspect * 1.2 + 20) continue;
        const along = ex * Math.cos(ms.axis) + ez * Math.sin(ms.axis), across = -ex * Math.sin(ms.axis) + ez * Math.cos(ms.axis);
        // distance in the mesa's own round terms: stretched, and lobed by its bays
        const d = Math.hypot(along / ms.aspect, across) / ms.shape(Math.atan2(ez, ex));
        if (d > ms.r + 20) continue;
        let da = Math.atan2(gz - ms.z, gx - ms.x) - ms.ramp;
        da = Math.atan2(Math.sin(da), Math.cos(da));
        const ramp = Math.abs(da) < 0.12;
        const side = ramp ? 0.34 : d - ms.r < ms.top * 0.55 ? 1.25 : 0.6;
        let m: number;
        if (d <= ms.r) m = ms.top;
        else if (ramp) m = ms.top - side * (d - ms.r);
        else {
          // stacked walls, then a talus apron below them
          const wallRun = (ms.top * 0.55) / 1.25;
          m = d - ms.r <= wallRun ? ms.top - 1.25 * (d - ms.r) : ms.top * 0.45 - 0.6 * (d - ms.r - wallRun);
        }
        if (m > t.mount) {
          t.mount = m;
          t.mesaWall = !ramp && d > ms.r + 0.5 && m > ms.top * 0.45;
          // a caprock top and banded walls, the talus fading back into the country below: a butte, not a ring
          t.biome = d <= ms.r ? Biome.Desert : m > ms.top * 0.3 ? Biome.Canyon : 255;
          t.surface = d <= ms.r ? 0 : m > ms.top * 0.3 ? Surface.Rock : 0;
          // the top is flat ground a town may take; the sides are not
          t.mask = d <= ms.r ? 0 : 1;
        }
      }
    }
    // ---- global fields ----
    if (cont) {
      const r = this.rift(t.u, t.v);
      if (r > 0) { t.e -= 6 * r; t.mount -= 6 * r; if (r > 0.8) t.noTown = true; }
    }
    const s = this.salt;
    if (s) {
      // a dry lake bed: longer one way, with bays and a crinkled shore, not a coin on the map
      const sx = gx - s.x, sz = gz - s.z;
      const along = sx * Math.cos(s.axis) + sz * Math.sin(s.axis), across = -sx * Math.sin(s.axis) + sz * Math.cos(s.axis);
      const lobed = s.shape(Math.atan2(sz, sx)) * (1 + 0.14 * this.nA.fbm(gx * 0.05, gz * 0.05, 3));
      // distance in the pan's own round terms, but never reaching further than the old round pan
      // did: the neighbour's cell knows nothing of this one
      const d = Math.max(Math.hypot(along / 1.3, across / 0.8) / lobed, Math.hypot(sx, sz) / 1.12);
      const rim = s.r;
      if (d < rim + 40) {
        const flat = 1.2;
        const ground = Math.max(t.e, t.mount);
        const blend = Math.max(10, Math.abs(ground - flat) / 0.55);
        const f = smoothstep(rim + blend, rim, d);
        if (f > 0) {
          t.e = t.e * (1 - f) + flat * f;
          t.mount = t.mount * (1 - f) + (flat - 1) * f;
        }
        if (d < rim) { t.biome = Biome.Salt; t.surface = Surface.Salt; t.mask = 0; }
        // and no town on its shore either, where the pan's edge would cut through the streets
        if (d < rim + 8) t.noTown = true;
      }
    }
  }

  /** A glacier over the ground here, if any peak's tongue reaches it: lowers into a U and turns to ice. */
  glacier(t: TileCtx, ground: number): number {
    for (const p of this.glaciers) {
      const g = p.glacier!;
      if (Math.abs(t.gx - p.x) > g.len + g.width || Math.abs(t.gz - p.z) > g.len + g.width) continue;
      const ax = Math.cos(g.ang), az = Math.sin(g.ang);
      const rx = t.gx - p.x, rz = t.gz - p.z;
      const along = rx * ax + rz * az, lat = -rx * az + rz * ax;
      if (along < 4 || along > g.len || Math.abs(lat) > g.width / 2 + 3) continue;
      const axis = p.h + t.lift - p.slope * along;
      if (axis < 2) continue;
      const trough = axis - 1.4 + 0.02 * lat * lat;
      const moraine = along > g.len - 8 ? 1.4 * Math.sin(((along - (g.len - 8)) / 8) * Math.PI) : 0;
      const shaped = Math.min(ground, trough + moraine);
      if (Math.abs(lat) <= g.width / 2) {
        t.biome = moraine > 0.5 ? Biome.Mountain : Biome.Ice;
        t.surface = moraine > 0.5 ? Surface.Rock : Surface.Ice;
        t.noTown = true;
        return shaped;
      }
      return Math.min(ground, Math.max(shaped, ground - 1));
    }
    return ground;
  }

  /** Skerries: islets off a cliff coast, pointwise, 0 for none or their height above the sea. */
  skerry(gx: number, gz: number, u: number, v: number, oceanDist: number, fade: number): number {
    if (fade <= 0 || oceanDist < 3 || oceanDist > SKERRY_REACH) return 0;
    if (hash2(Math.floor(gx / 2), Math.floor(gz / 2), 7301) > 0.18) return 0;
    const cliff = smoothstep(0.35, 0.6, smoothstep(-0.35, 0.45, this.nB.fbm(u * 1.4 + 40, v * 1.4 + 40, 1)));
    if (cliff <= 0) return 0;
    const cluster = smoothstep(0.64, 0.76, 0.5 + 0.5 * this.nA.fbm(u * 22 + 5, v * 22 + 9, 2));
    if (cluster <= 0) return 0;
    const bx = Math.floor(gx / 2), bz = Math.floor(gz / 2);
    if (hash2(bx, bz, 7301) > 0.18 * cluster * cliff) return 0;
    return 1 + Math.floor(hash2(gx, gz, 7302) * 3);
  }
}
