const OPEN = new Set<string>(OPEN_KINDS);

/** A kind's grade, before stature. */
function kindGrade(kind: BuildingKind): Grade {
  if (OPEN.has(kind)) return 0;
  return GRADE[kind as Exclude<BuildingKind, OpenKind>] ?? 0;
}

/** Footprint × floors: what stature is measured by. */
export const statureOf = (b: Pick<Building, 'w' | 'd' | 'floors'>): number => b.w * b.d * Math.max(1, b.floors);

/** What a building is as an HQ: its grade, whether it is big for its kind, its slots, charter and prestige floor. */
export interface HqGrade { grade: Grade; plus: boolean; name: string; slots: number; charter: number; prestige: number }

const NO_GRADE: HqGrade = { grade: 0, plus: false, name: '', slots: 0, charter: 0, prestige: 0 };

/** A grade as it reads: "Institution". (A "+" from before the tiers were plain reads as the tier above.) */
export function gradeName(g: Pick<HqGrade, 'grade' | 'plus'>): string {
  return g.grade ? HQ_GRADES[(g.plus ? Math.min(7, g.grade + 1) : g.grade) as Exclude<Grade, 0>].name : '';
}

/** The pips a grade is shown with: ★ per grade. */
export function gradePips(grade: number): string { return '★'.repeat(Math.max(0, grade)); }

/** The grade of a spec, with or without stature. */
export function gradeSpec(grade: Grade, plus: boolean): HqGrade {
  if (!grade) return NO_GRADE;
  // big for its kind: the tier above, outright
  if (plus) return gradeSpec(Math.min(7, grade + 1) as Grade, false);
  const s = HQ_GRADES[grade];
  return { grade, plus: false, name: s.name, slots: s.slots, charter: s.charter, prestige: s.prestige };
}

/** Is this building big for its kind (and so graded a tier up)? */
export function bigForKind(b: Pick<Building, 'kind' | 'w' | 'd' | 'floors'>): boolean {
  const grade = kindGrade(b.kind);
  const p85 = KIND_P85[b.kind];
  return !!grade && grade <= STATURE.maxGrade && p85 !== undefined && statureOf(b) > p85;
}

/** What a building is as an HQ; `harbour` for a harbour bought whole. A derelict one has its grade, but can't be chartered until mended. */
export function gradeOf(b: Pick<Building, 'kind' | 'w' | 'd' | 'floors'>, harbour = false): HqGrade {
  if (harbour) return gradeSpec(HARBOUR_GRADE, false);
  const grade = kindGrade(b.kind);
  if (!grade) return NO_GRADE;
  return gradeSpec(grade, bigForKind(b));
}

/**
 * HQ terms (docs/hq.html, "HQ terms"): what a building costs bought AS the fleet's HQ, by the slots it
 * opens, whatever trade runs through its door. Set from the fleet-size playtests of 30 Sep 2026 so an
 * expert opens each of the first three slots about 15–20 minutes of play after the last (a fleet of four,
 * counting their own car, in about 65–70 minutes). Before this the price was the deed market's: the
 * nearest 3-slot building ran anywhere from $7.7k to $60k. Grades past three slots keep the market price.
 */
const HQ_TERMS: Readonly<Record<number, number>> = { 1: 700, 2: 1_700, 3: 3_800 };

/** HQ terms by the kind of town, gentler than the deed market's 0.75–1.7: a village asks a tenth less, a megalopolis a fifth more. */
const HQ_TERMS_TOWN: Readonly<Record<TownKind, number>> = { rural: 0.9, suburb: 1, city: 1, metro: 1.1, mega: 1.2 };
const HQ_TERMS_COUNTRY = 0.9;

/** The HQ-terms price of a building of this grade in this kind of town, or null when its slots have no terms. */
function hqTermsPrice(g: HqGrade, town: TownKind | null): number | null {
  const base = g.grade ? HQ_TERMS[g.slots] : undefined;
  if (!base) return null;
  return Math.round((base * (town ? HQ_TERMS_TOWN[town] : HQ_TERMS_COUNTRY)) / 50) * 50;
}

/** The prestige floor on a deed's price: the grade's, by the town's price multiplier and the holding premium. */
export function prestigeFloor(g: HqGrade, townMul: number, holding: number): number {
  return g.prestige > 0 ? Math.round((g.prestige * townMul * holding) / 100) * 100 : 0;
}

/** For the rivals and the gate: town kinds ranked, so "a grand address in a big town" can be compared. */
export const TOWN_RANK: Record<TownKind, number> = { rural: 0, suburb: 1, city: 2, metro: 3, mega: 4 };
