import { hex, scale, type RGB } from '../../world/biomes';
import type { Rng } from '../../world/rng';
import { VIS, Vis } from '../nightLights';
import { DARK, METAL, TAU, WOOD, type Kit, type P3 } from './kit';

/**
 * Jungle gyms: the playground equipment every town playground and every school yard is built from (open.ts
 * playground, playB.ts elementarySchool). Each piece is drawn round its own origin at a yaw, in one of a few
 * palettes; `playEquipment` fills a rectangle with three to five seed-picked pieces that don't overlap and
 * hands back where a child can play on each (a swing's pivot, a slide's climb and run, a roundabout's ring),
 * which `kidsRig` then sets a handful of tiny children loose on.
 *
 * Scale: an adult is about 0.12 tall, so a child is 0.08 and a slide's deck stands at about 0.15.
 */

// ---- palettes ----------------------------------------------------------------------------------

interface PlayPalette {
  name: string;
  /** Posts, frames and A-legs. */
  frame: RGB;
  /** Decks, platforms, planks. */
  deck: RGB;
  /** Slides and chutes. */
  slide: RGB;
  /** Little roofs over the towers. */
  roof: RGB;
  /** Side panels, handles, the odd bright bit. */
  accent: RGB;
  /** Swing seats. */
  seat: RGB;
}

const PLAY_PALETTES: readonly PlayPalette[] = [
  { name: 'primary', frame: hex(0xe2412f), deck: hex(0x2f7fb5), slide: hex(0xf2c14e), roof: hex(0x2f7fb5), accent: hex(0x3f9b4a), seat: hex(0x2a2e33) },
  { name: 'timber', frame: hex(0x9a6f45), deck: hex(0x7a5a3a), slide: hex(0x3f9b4a), roof: hex(0x3f7d3a), accent: hex(0xc8a070), seat: hex(0x3a3f45) },
  { name: 'pastel', frame: hex(0x8fc9e8), deck: hex(0xf4b8c8), slide: hex(0xf6e7a8), roof: hex(0xb8a4e0), accent: hex(0xa8e0c0), seat: hex(0x6a6f8a) },
  { name: 'steel', frame: hex(0x9aa3ab), deck: hex(0x4f565e), slide: hex(0xf28c38), roof: hex(0xf28c38), accent: hex(0x2f5f8a), seat: hex(0x2a2e33) },
  { name: 'jungle', frame: hex(0x3f8a4a), deck: hex(0xf2c14e), slide: hex(0xe2412f), roof: hex(0xf2a93b), accent: hex(0x8e5cc7), seat: hex(0x2a2e33) },
];

/**
 * A pick of one of n from the next draw, stirred first: buildings side by side can have seeds that differ by
 * little, and a plain floor(r() * n) on mulberry32's early draws then picks the same for all of them.
 */
export const roll = (r: Rng, n: number): number => Math.min(n - 1, Math.floor(((r() * 7919.37) % 1) * n));

export const pickPalette = (r: Rng): PlayPalette => PLAY_PALETTES[roll(r, PLAY_PALETTES.length)];

/** What a play area is laid with: green, red or blue rubber crumb, bark chips, or sand. */
const SOFT_SURFACES: readonly number[] = [0x4f9a6a, 0xb8543f, 0x3f6fa8, 0x8a5f3a, 0x9a6a42, 0xe6d4a0];
export const pickSurface = (r: Rng): RGB => hex(SOFT_SURFACES[roll(r, SOFT_SURFACES.length)]);

const ROPE = hex(0x6a5a48), SAND = hex(0xe9d9a6), RIM = hex(0x9a7048), LOG = hex(0x8a6440), LOG_END = hex(0xd8b888);

// ---- drawing round a piece's own origin ---------------------------------------------------------

/** A kit offset to (x, z) in a turned frame: the pieces draw round their own origin through this. */
class Pen {
  constructor(readonly k: Kit, private x: number, private z: number) {}
  private p(a: P3): P3 { return [this.x + a[0], a[1], this.z + a[2]]; }
  box(x: number, y: number, z: number, w: number, h: number, d: number, c: RGB, top: RGB = c): void { this.k.box(this.x + x, y, this.z + z, w, h, d, c, top); }
  bar(a: P3, b: P3, r: number, c: RGB): void { this.k.bar(this.p(a), this.p(b), r, c); }
  cyl(x: number, y: number, z: number, r: number, h: number, c: RGB, seg = 6, top: RGB = c): void { this.k.cyl(this.x + x, y, this.z + z, r, h, c, seg, top); }
  cone(x: number, y: number, z: number, r: number, h: number, c: RGB, seg = 6): void { this.k.cone(this.x + x, y, this.z + z, r, h, c, seg); }
  hip(x: number, y: number, z: number, w: number, h: number, d: number, c: RGB): void { this.k.hip(this.x + x, y, this.z + z, w, h, d, c); }
  gable(x: number, y: number, z: number, w: number, h: number, d: number, roof: RGB, end: RGB, alongZ = false): void { this.k.gable(this.x + x, y, this.z + z, w, h, d, roof, end, alongZ); }
  hoop(x: number, y: number, z: number, R: number, t: number, c: RGB, seg: number, plane: 'xy' | 'xz' | 'zy'): void { this.k.hoop(this.x + x, y, this.z + z, R, t, c, seg, plane); }
  quad(a: P3, b: P3, c: P3, d: P3, col: RGB, inside: P3): void { this.k.quad(this.p(a), this.p(b), this.p(c), this.p(d), col, this.p(inside)); }
}

// ---- where children play ------------------------------------------------------------------------

/**
 * A place on a piece a child can play, in the frame the piece was laid out in: a swing (pivot `at`, rope
 * `len`, swinging along `dir`), a run (`path`: climb, cross, slide down, then back on the ground to its start),
 * a ring run round `at` at `rad` (pushing a roundabout), or a seat that rocks (`at`, facing `dir`).
 */
interface PlaySpot {
  kind: 'swing' | 'path' | 'ring' | 'rock';
  at: P3;
  dir: [number, number];
  len: number;
  rad: number;
  path: P3[];
}

type Spotter = (s: Partial<PlaySpot> & { kind: PlaySpot['kind'] }) => void;

/** A piece: its footprint round its origin (x0, x1, z0, z1 at yaw 0) and how to draw it. */
interface Piece {
  name: string;
  fp: [number, number, number, number];
  big?: boolean;
  draw: (p: Pen, c: PlayPalette, r: Rng, spot: Spotter) => void;
}

// ---- the pieces ---------------------------------------------------------------------------------

/** A climbing frame: a lattice of cubes two high, a deck panel in one top cell to sit on. */
const climbingFrame = (r: Rng): Piece => {
  const nx = r() < 0.5 ? 2 : 3, nz = 2, c = 0.15, H = 0.28;
  const hx = (nx * c) / 2, hz = (nz * c) / 2;
  return {
    name: 'climbingFrame', fp: [-hx - 0.04, hx + 0.04, -hz - 0.04, hz + 0.04], big: true,
    draw: (p, pal, _r, spot) => {
      for (let i = 0; i <= nx; i++) for (let j = 0; j <= nz; j++) p.box(-hx + i * c, 0, -hz + j * c, 0.014, H + 0.012, 0.014, pal.frame);
      for (const y of [c, H]) {
        for (let j = 0; j <= nz; j++) p.box(0, y, -hz + j * c, nx * c, 0.01, 0.01, pal.frame);
        for (let i = 0; i <= nx; i++) p.box(-hx + i * c, y + 0.001, 0, 0.01, 0.01, nz * c - 0.014, pal.frame);
      }
      // the deck in one top cell, a hair under the rails' tops
      p.box(-hx + c / 2, H - 0.004, -hz + c / 2, c - 0.02, 0.012, c - 0.02, pal.deck);
      p.box(hx - c / 2, c - 0.004, hz - c / 2, c - 0.02, 0.012, c - 0.02, pal.accent);
      spot({ kind: 'path', path: [[-hx - 0.05, 0, -hz + c / 2], [-hx + c / 2, H + 0.008, -hz + c / 2], [-hx + c / 2, H + 0.008, -hz + c / 2], [hx + 0.05, 0, hz - c / 2]] });
    },
  };
};

/** A slide tower: a deck on four posts under a little roof, panels at its sides, a ladder up the back and a slide off the front. */
const slideTower = (r: Rng): Piece => {
  const H = 0.14 + r() * 0.04, pw = 0.22, L = 0.34 + r() * 0.08, roofed = r() < 0.75, gableRoof = r() < 0.5;
  const twin = r() < 0.3;
  return {
    name: 'slideTower', fp: [twin ? -pw / 2 - 0.4 : -0.15, 0.15, -pw / 2 - 0.16, pw / 2 + L + 0.1], big: true,
    draw: (p, pal, _r, spot) => {
      const top = H + (roofed ? 0.15 : 0.07);
      for (const sx of [-1, 1]) for (const sz of [-1, 1]) p.box(sx * (pw / 2 - 0.01), 0, sz * (pw / 2 - 0.01), 0.018, top, 0.018, pal.frame);
      p.box(0, H - 0.02, 0, pw - 0.01, 0.02, pw - 0.01, pal.deck);
      // side panels
      for (const sx of [-1, 1]) p.box(sx * (pw / 2 - 0.01), H, 0, 0.008, 0.06, pw - 0.04, pal.accent);
      if (roofed) {
        if (gableRoof) p.gable(0, top, 0, pw + 0.06, 0.08, pw + 0.06, pal.roof, pal.roof, true);
        else p.hip(0, top, 0, pw + 0.06, 0.09, pw + 0.06, pal.roof);
      } else {
        p.box(0, top - 0.012, -pw / 2 + 0.01, pw, 0.012, 0.012, pal.frame);
        p.box(0, top - 0.012, pw / 2 - 0.01, pw, 0.012, 0.012, pal.frame);
      }
      // the ladder up the back
      const lz0 = -pw / 2 - 0.12, lz1 = -pw / 2 - 0.01;
      for (const sx of [-0.05, 0.05]) p.bar([sx, 0, lz0], [sx, H, lz1], 0.007, pal.frame);
      for (let i = 1; i <= 3; i++) {
        const f = i / 4;
        p.box(0, H * f, lz0 + (lz1 - lz0) * f, 0.1, 0.008, 0.01, pal.accent);
      }
      // the slide: a sloping bed between two lips, and a run-out at its foot
      const z0 = pw / 2 - 0.005, z1 = pw / 2 + L, sw = 0.045, y1 = 0.03;
      p.quad([-sw, H + 0.002, z0], [sw, H + 0.002, z0], [sw, y1, z1], [-sw, y1, z1], pal.slide, [0, H / 2 - 0.05, (z0 + z1) / 2]);
      for (const sx of [-1, 1]) p.bar([sx * sw, H + 0.015, z0], [sx * sw, y1 + 0.015, z1], 0.008, pal.slide);
      p.box(0, 0, z1 + 0.035, sw * 2 + 0.01, y1, 0.07, pal.slide);
      p.box(0, 0, z1 - 0.02, 0.03, y1 + 0.004, 0.03, pal.frame);
      spot({ kind: 'path', path: [[0, 0, lz0 - 0.03], [0, H, lz1], [0, H, 0], [0, H, z0], [0, y1 + 0.005, z1], [0, 0, z1 + 0.09]] });
      if (twin) {
        // a fireman's pole and a climbing ramp off the side
        p.box(-pw / 2 - 0.08, 0, 0, 0.012, top, 0.012, METAL);
        p.box(-pw / 2 - 0.04, H - 0.012, 0, 0.08, 0.012, 0.012, pal.frame);
        p.quad([-pw / 2 - 0.36, 0.006, -0.06], [-pw / 2 - 0.36, 0.006, 0.06], [-pw / 2, H - 0.02, 0.06], [-pw / 2, H - 0.02, -0.06], pal.deck, [-pw / 2 - 0.15, -0.1, 0]);
        for (let i = 1; i <= 4; i++) {
          const f = i / 5;
          p.box(-pw / 2 - 0.36 * (1 - f), (H - 0.02) * f, 0, 0.012, 0.012, 0.11, pal.accent);
        }
        spot({ kind: 'path', path: [[-pw / 2 - 0.4, 0, 0], [-pw / 2 - 0.02, H, 0], [0, H, 0], [-pw / 2 - 0.08, H, 0.03], [-pw / 2 - 0.08, 0, 0.03]] });
      }
    },
  };
};

/** A swing set: an A-frame each end, a beam across, two or three swings (one a toddler's bucket). */
const swingSet = (r: Rng): Piece => {
  const n = r() < 0.55 ? 2 : 3, gap = 0.2, hw = (n * gap) / 2 + 0.04, H = 0.21, bucket = Math.floor(r() * (n + 2));
  return {
    name: 'swingSet', fp: [-hw - 0.03, hw + 0.03, -0.22, 0.22],
    draw: (p, pal, _r, spot) => {
      for (const sx of [-1, 1]) for (const sz of [-1, 1]) p.bar([sx * hw, 0, sz * 0.13], [sx * hw, H, 0], 0.011, pal.frame);
      p.bar([-hw, H, 0], [hw, H, 0], 0.011, pal.frame);
      for (let i = 0; i < n; i++) {
        const x = -((n - 1) / 2) * gap + i * gap, seatY = 0.045;
        for (const s of [-0.032, 0.032]) p.box(x + s, seatY, 0, 0.004, H - seatY - 0.008, 0.004, i === bucket ? METAL : ROPE);
        if (i === bucket) p.box(x, seatY - 0.02, 0, 0.07, 0.035, 0.05, pal.accent, pal.seat);
        else p.box(x, seatY - 0.008, 0, 0.08, 0.01, 0.035, pal.seat);
        spot({ kind: 'swing', at: [x, H, 0], len: H - seatY, dir: [0, 1] });
      }
    },
  };
};

/** A see-saw (or two side by side): a plank tipped over its pivot, a handle at each end. */
const seeSaw = (r: Rng): Piece => {
  const two = r() < 0.4, L = 0.27;
  return {
    name: 'seeSaw', fp: [-L - 0.03, L + 0.03, -0.07, two ? 0.25 : 0.07],
    draw: (p, pal, rr) => {
      for (const z of two ? [0, 0.18] : [0]) {
        const tip = rr() < 0.5 ? 1 : -1;
        p.box(0, 0, z, 0.05, 0.045, 0.07, pal.frame);
        const a: P3 = [-L, 0.05 - tip * 0.035, z], b: P3 = [L, 0.05 + tip * 0.035, z];
        p.bar(a, b, 0.013, pal.deck);
        for (const [e, s] of [[a, 1], [b, -1]] as [P3, number][]) {
          const hx = e[0] + s * 0.05, hy = e[1] + (b[1] - a[1]) * (s * 0.05) / (2 * L);
          p.bar([hx, hy, z], [hx, hy + 0.045, z], 0.006, pal.accent);
          p.box(hx, hy + 0.04, z, 0.012, 0.01, 0.05, pal.accent);
        }
      }
    },
  };
};

/** A spiral slide: a deck on a pole under a cap, a ladder up, and a corkscrew chute a turn and a bit round it. */
const spiralSlide = (r: Rng): Piece => {
  const H = 0.2 + r() * 0.05, R = 0.15, turns = 1, segs = 10;
  return {
    name: 'spiralSlide', fp: [-0.22, 0.22, -0.34, 0.22], big: true,
    draw: (p, pal, _r, spot) => {
      p.cyl(0, 0, 0, 0.018, H + 0.13, METAL, 6);
      p.cyl(0, H - 0.015, 0, 0.085, 0.015, pal.deck, 8);
      p.hoop(0, H + 0.06, 0, 0.085, 0.005, pal.frame, 8, 'xz');
      for (let i = 0; i < 3; i++) {
        const a = (i / 3) * TAU + 0.5;
        p.box(Math.cos(a) * 0.08, H, Math.sin(a) * 0.08, 0.008, 0.13, 0.008, pal.frame);
      }
      p.cone(0, H + 0.13, 0, 0.11, 0.09, pal.roof, 8);
      // the ladder from the back (-z)
      for (const sx of [-0.04, 0.04]) p.bar([sx, 0, -0.32], [sx, H, -0.09], 0.007, pal.frame);
      for (let i = 1; i <= 3; i++) {
        const f = i / 4;
        p.box(0, H * f, -0.32 + 0.23 * f, 0.08, 0.008, 0.01, pal.accent);
      }
      // the chute: from beside the ladder's head, round and down, left-handed
      const a0 = -Math.PI / 2 + 0.75, path: P3[] = [[0, 0, -0.36], [0, H, -0.09], [0, H, 0]];
      let prev: P3 | null = null;
      for (let i = 0; i <= segs; i++) {
        const f = i / segs, a = a0 + f * turns * TAU * 0.92, y = H - 0.01 - (H - 0.04) * f;
        const pt: P3 = [Math.cos(a) * R, y, Math.sin(a) * R];
        if (prev) p.bar(prev, pt, 0.024, pal.slide);
        prev = pt;
        path.push([pt[0], pt[1] + 0.025, pt[2]]);
      }
      const end = prev!, ea = a0 + turns * TAU * 0.92;
      const out: P3 = [end[0] - Math.sin(ea) * 0.08, 0.012, end[2] + Math.cos(ea) * 0.08];
      p.bar(end, out, 0.024, pal.slide);
      path.push([out[0], 0, out[2]]);
      spot({ kind: 'path', path });
    },
  };
};

/** A dome climber: a half-globe of bars, two rings and four arches. */
const domeClimber = (r: Rng): Piece => {
  const R = 0.18 + r() * 0.04;
  return {
    name: 'domeClimber', fp: [-R - 0.03, R + 0.03, -R - 0.03, R + 0.03], big: true,
    draw: (p, pal, _r, spot) => {
      for (const [el, seg] of [[0.5, 8], [1.0, 6]] as [number, number][]) p.hoop(0, Math.sin(el) * R, 0, Math.cos(el) * R, 0.007, pal.frame, seg, 'xz');
      for (let m = 0; m < 4; m++) {
        const a = (m / 4) * TAU + 0.4;
        let prev: P3 | null = null;
        for (let j = 0; j <= 3; j++) {
          const el = (j / 3) * (Math.PI / 2) * 0.96;
          const pt: P3 = [Math.cos(a) * Math.cos(el) * R, Math.sin(el) * R, Math.sin(a) * Math.cos(el) * R];
          if (prev) p.bar(prev, pt, 0.007, j === 1 ? pal.accent : pal.frame);
          prev = pt;
        }
      }
      spot({ kind: 'path', path: [[R + 0.05, 0, 0], [0.03, R, 0], [0.03, R, 0], [-R - 0.05, 0, 0.02]] });
    },
  };
};

/** Monkey bars: a ladder up each end and a run of rungs across the top to swing along. */
const monkeyBars = (r: Rng): Piece => {
  const L = 0.5 + r() * 0.15, H = 0.2, wd = 0.14;
  return {
    name: 'monkeyBars', fp: [-L / 2 - 0.08, L / 2 + 0.08, -wd / 2 - 0.03, wd / 2 + 0.03],
    draw: (p, pal, _r, spot) => {
      for (const sx of [-1, 1]) {
        for (const sz of [-1, 1]) p.box(sx * L / 2, 0, sz * wd / 2, 0.016, H + 0.01, 0.016, pal.frame);
        for (const y of [0.07, 0.14]) p.box(sx * L / 2, y, 0, 0.01, 0.01, wd - 0.016, pal.accent);
      }
      for (const sz of [-1, 1]) p.box(0, H, sz * wd / 2, L - 0.016, 0.012, 0.012, pal.frame);
      const n = Math.round(L / 0.075);
      for (let i = 1; i < n; i++) p.box(-L / 2 + (L * i) / n, H + 0.001, 0, 0.008, 0.008, wd - 0.014, pal.accent);
      spot({ kind: 'path', path: [[-L / 2 - 0.06, 0, 0], [-L / 2 + 0.03, H - 0.088, 0], [L / 2 - 0.03, H - 0.088, 0], [L / 2 + 0.06, 0, 0]] });
    },
  };
};

/** A roundabout: a low turntable, a post in the middle and handles out to its rim. */
const merryGoRound = (r: Rng): Piece => {
  const R = 0.17 + r() * 0.03, n = r() < 0.5 ? 3 : 4;
  return {
    name: 'merryGoRound', fp: [-R - 0.08, R + 0.08, -R - 0.08, R + 0.08],
    draw: (p, pal, _r, spot) => {
      p.cyl(0, 0, 0, R, 0.025, pal.frame, 10, pal.deck);
      p.cyl(0, 0.025, 0, 0.022, 0.07, pal.accent, 6);
      for (let i = 0; i < n; i++) {
        const a = (i / n) * TAU + 0.3, c = Math.cos(a), s = Math.sin(a), e = R - 0.02;
        p.bar([c * 0.02, 0.08, s * 0.02], [c * e, 0.08, s * e], 0.006, pal.accent);
        p.bar([c * e, 0.025, s * e], [c * e, 0.08, s * e], 0.006, pal.accent);
      }
      spot({ kind: 'ring', at: [0, 0, 0], rad: R + 0.05 });
    },
  };
};

/** Spring riders: two or three animals (a duck, a horse, a bug) on a coil each, on a little pad. */
const springRiders = (r: Rng): Piece => {
  const n = r() < 0.5 ? 2 : 3, gap = 0.17, hw = ((n - 1) * gap) / 2;
  const cols = [0xf2c14e, 0xe2412f, 0x3f9b4a, 0x2f7fb5, 0xff7fae, 0x2bb3a3];
  return {
    name: 'springRiders', fp: [-hw - 0.08, hw + 0.08, -0.07, 0.07],
    draw: (p, _pal, rr, spot) => {
      for (let i = 0; i < n; i++) {
        const x = -hw + i * gap, col = hex(cols[Math.floor(rr() * cols.length)]);
        p.cyl(x, 0, 0, 0.032, 0.008, DARK, 6);
        p.cyl(x, 0.008, 0, 0.011, 0.045, METAL, 5);
        p.box(x, 0.053, 0, 0.1, 0.036, 0.034, col);
        p.box(x + 0.045, 0.089, 0, 0.034, 0.036, 0.03, col);
        p.box(x + 0.022, 0.089, 0, 0.006, 0.026, 0.05, DARK);
        spot({ kind: 'rock', at: [x - 0.012, 0.072, 0], dir: [1, 0] });
      }
    },
  };
};

/** A sandpit in a timber frame, a bucket and a spade left in it. */
const sandpit = (r: Rng): Piece => {
  const w = 0.42 + r() * 0.12, d = 0.34 + r() * 0.08;
  return {
    name: 'sandpit', fp: [-w / 2 - 0.02, w / 2 + 0.02, -d / 2 - 0.02, d / 2 + 0.02],
    draw: (p, pal, rr, spot) => {
      const t = 0.03, h = 0.035;
      for (const sz of [-1, 1]) p.box(0, 0, sz * (d / 2 - t / 2), w, h, t, RIM);
      for (const sx of [-1, 1]) p.box(sx * (w / 2 - t / 2), 0, 0, t, h, d - 2 * t, RIM);
      p.box(0, 0, 0, w - 2 * t, 0.024, d - 2 * t, SAND);
      const bx = (rr() - 0.5) * (w - 0.16), bz = (rr() - 0.5) * (d - 0.16);
      p.cyl(bx, 0.024, bz, 0.016, 0.026, pal.accent, 6, scale(pal.accent, 0.8));
      p.box(bx + 0.05, 0.024, bz + 0.02, 0.014, 0.004, 0.05, pal.frame);
      spot({ kind: 'rock', at: [-bx * 0.5, -0.004, -bz * 0.5 + 0.03], dir: [0, 1] });
    },
  };
};

/** Stepping logs in a zigzag, and a low balance beam beside them. */
const balanceLogs = (r: Rng): Piece => {
  const n = 5;
  return {
    name: 'balanceLogs', fp: [-0.3, 0.3, -0.1, 0.15],
    draw: (p, _pal, rr, spot) => {
      const path: P3[] = [[-0.32, 0, -0.03]];
      for (let i = 0; i < n; i++) {
        const x = -0.24 + (0.48 * i) / (n - 1), z = (i % 2 ? 0.04 : -0.04), h = 0.02 + rr() * 0.04;
        p.cyl(x, 0, z, 0.03, h, LOG, 6, LOG_END);
        path.push([x, h, z]);
      }
      path.push([0.32, 0, 0]);
      p.box(0, 0.035, 0.11, 0.48, 0.016, 0.026, LOG, LOG_END);
      for (const sx of [-0.2, 0.2]) p.box(sx, 0, 0.11, 0.03, 0.035, 0.05, RIM);
      void r;
      spot({ kind: 'path', path });
    },
  };
};

/** A playhouse: a little hut with a door, a window and a pitched roof. */
const playhouse = (r: Rng): Piece => {
  const w = 0.2 + r() * 0.05, d = 0.18;
  return {
    name: 'playhouse', fp: [-w / 2 - 0.03, w / 2 + 0.03, -d / 2 - 0.03, d / 2 + 0.08],
    draw: (p, pal) => {
      p.box(0, 0, 0, w, 0.13, d, pal.deck);
      p.gable(0, 0.13, 0, w + 0.04, 0.08, d + 0.04, pal.roof, pal.deck);
      p.box(-w * 0.2, 0, d / 2 + 0.004, 0.05, 0.09, 0.008, pal.accent);
      p.box(w * 0.22, 0.06, d / 2 + 0.004, 0.05, 0.04, 0.008, hex(0x9cc6d9));
    },
  };
};

const PIECES: { make: (r: Rng) => Piece; w: number }[] = [
  { make: slideTower, w: 3 }, { make: climbingFrame, w: 2 }, { make: spiralSlide, w: 1.5 }, { make: domeClimber, w: 1.2 },
  { make: swingSet, w: 3 }, { make: seeSaw, w: 1.4 }, { make: monkeyBars, w: 1.4 }, { make: merryGoRound, w: 1.5 },
  { make: springRiders, w: 1.6 }, { make: sandpit, w: 1.5 }, { make: balanceLogs, w: 1 }, { make: playhouse, w: 0.8 },
];

/** Pick one piece by weight from those not yet used. */
function choose(r: Rng, used: Set<number>, bigOnly: boolean): number {
  let total = 0;
  const ok = PIECES.map((_p, i) => !used.has(i) && (!bigOnly || i < 4));
  PIECES.forEach((p, i) => { if (ok[i]) total += p.w; });
  let x = r() * total;
  for (let i = 0; i < PIECES.length; i++) {
    if (!ok[i]) continue;
    x -= PIECES[i].w;
    if (x <= 0) return i;
  }
  return PIECES.findIndex((_, i) => ok[i]);
}

/** Map a piece's local point to the frame it was put in. */
const toFrame = (x: number, z: number, c: number, s: number, u: number, v: number): [number, number] => [x + u * c + v * s, z - u * s + v * c];

/**
 * Draw one piece at (x, z) turned by yaw, and pass its play spots, in the kit's frame, to `out`.
 */
function put(k: Kit, x: number, z: number, yaw: number, piece: Piece, pal: PlayPalette, r: Rng, out: PlaySpot[]): void {
  const c = Math.cos(yaw), s = Math.sin(yaw);
  const pt = (q: P3): P3 => { const [X, Z] = toFrame(x, z, c, s, q[0], q[2]); return [X, q[1], Z]; };
  const spot: Spotter = (sp) => {
    const at = pt(sp.at ?? [0, 0, 0]);
    const d = sp.dir ?? [0, 1];
    out.push({
      kind: sp.kind, at, len: sp.len ?? 0, rad: sp.rad ?? 0,
      dir: [d[0] * c + d[1] * s, -d[0] * s + d[1] * c],
      path: (sp.path ?? []).map(pt),
    });
  };
  k.turned(yaw, () => piece.draw(new Pen(k, x * c - z * s, x * s + z * c), pal, r, spot));
}

export interface Rect { x: number; z: number; w: number; d: number }

/**
 * Fill the rectangle w × d centred on (x, z) with three to five seed-picked pieces of play equipment that
 * don't overlap (fewer if they won't fit), one of them a big one (a slide tower, a climbing frame, a spiral
 * slide or a dome). Returns where children can play on them. `max` and `min` bound the count; `rects`, if
 * given, collects each piece's footprint.
 */
export function playEquipment(k: Kit, x: number, z: number, w: number, d: number, r: Rng, pal: PlayPalette, max = 5, min = 3, rects?: Rect[]): PlaySpot[] {
  const want = min + roll(r, max - min + 1);
  const used = new Set<number>();
  const pieces: Piece[] = [];
  for (let i = 0; i < want; i++) {
    const n = choose(r, used, i === 0);
    if (n < 0) break;
    used.add(n);
    pieces.push(PIECES[n].make(r));
  }
  const area = (p: Piece) => (p.fp[1] - p.fp[0]) * (p.fp[3] - p.fp[2]);
  pieces.sort((a, b) => area(b) - area(a));
  const placed: [number, number, number, number][] = [];
  const spots: PlaySpot[] = [];
  const pad = 0.07;
  for (const piece of pieces) {
    for (let tries = 0; tries < 60; tries++) {
      const yaw = Math.floor(r() * 4) * (Math.PI / 2);
      const c = Math.cos(yaw), s = Math.sin(yaw);
      // the footprint's box once turned, about the piece's origin
      let x0 = Infinity, x1 = -Infinity, z0 = Infinity, z1 = -Infinity;
      for (const u of [piece.fp[0], piece.fp[1]]) for (const v of [piece.fp[2], piece.fp[3]]) {
        const [X, Z] = toFrame(0, 0, c, s, u, v);
        x0 = Math.min(x0, X); x1 = Math.max(x1, X); z0 = Math.min(z0, Z); z1 = Math.max(z1, Z);
      }
      const fw = x1 - x0, fd = z1 - z0;
      if (fw > w - 0.04 || fd > d - 0.04) continue;
      const cx = x - w / 2 + 0.02 + r() * (w - 0.04 - fw) - x0, cz = z - d / 2 + 0.02 + r() * (d - 0.04 - fd) - z0;
      const box: [number, number, number, number] = [cx + x0, cx + x1, cz + z0, cz + z1];
      if (placed.some((q) => box[0] < q[1] + pad && box[1] > q[0] - pad && box[2] < q[3] + pad && box[3] > q[2] - pad)) continue;
      placed.push(box);
      rects?.push({ x: (box[0] + box[1]) / 2, z: (box[2] + box[3]) / 2, w: box[1] - box[0], d: box[3] - box[2] });
      put(k, cx, cz, yaw, piece, pal, r, spots);
      break;
    }
  }
  return spots;
}

// ---- small shared things ------------------------------------------------------------------------

/** A park bench facing `yaw` (0 faces +z). */
export function playBench(k: Kit, x: number, z: number, yaw = 0, col: RGB = WOOD): void {
  const c = Math.cos(yaw), s = Math.sin(yaw);
  k.turned(yaw, () => {
    const p = new Pen(k, x * c - z * s, x * s + z * c);
    p.box(0, 0.03, 0, 0.24, 0.035, 0.07, col);
    p.box(0, 0.065, -0.035, 0.24, 0.05, 0.015, col);
    for (const sx of [-0.1, 0.1]) p.box(sx, 0, 0, 0.02, 0.03, 0.05, DARK);
  });
}

// ---- children -----------------------------------------------------------------------------------

const KID_TOPS = [0xe2412f, 0x2f7fb5, 0xf2c14e, 0x3f9b4a, 0xff7fae, 0x8e5cc7, 0x2bb3a3, 0xf28c38, 0xf4f2ec, 0x6fd0f0];
const KID_LEGS = [0x2f3f6a, 0x3a3f45, 0x8a2f3a, 0x5a6a8a, 0x2f5a3a, 0xc8b89a];
const KID_SKIN = [0xf1c7a1, 0xd9a07a, 0x9a6a48, 0x6a4632, 0xf4d9bf];
const KID_HAIR = [0x2a1e16, 0x5a3a20, 0xc89a4a, 0x1a1a1a, 0x8a4a22];
const kc = (r: Rng, a: number[]): RGB => hex(a[Math.floor(r() * a.length)]);

/** A child about 0.083 tall standing at (x, z) on y, facing +z. */
export function kid(k: Kit, x: number, y: number, z: number, r: Rng): void {
  k.box(x, y, z, 0.024, 0.032, 0.016, kc(r, KID_LEGS));
  k.box(x, y + 0.032, z, 0.03, 0.027, 0.02, kc(r, KID_TOPS));
  k.box(x, y + 0.059, z, 0.02, 0.018, 0.018, kc(r, KID_SKIN));
  k.box(x, y + 0.077, z - 0.002, 0.022, 0.006, 0.021, kc(r, KID_HAIR));
}

/** When children are out: playing, heading home out of the front, or not there. */
type KidsTime = 'play' | 'leave' | null;

interface KidsPlan {
  /** The equipment's play spots (playEquipment). */
  spots: PlaySpot[];
  /** Open ground to run about and chase on. */
  run: Rect[];
  /** How many rig parts (each a draw call): at most 8. */
  parts: number;
  /** A ring of children standing about (four-square, a chat): one part holding several. */
  group?: { x: number; z: number; rad: number; n: number };
  /** A child hopping up and down a hopscotch from a to b. */
  hop?: { a: [number, number]; b: [number, number] };
  /** Home time: out of the door at (x, z), down to the front at z = gate, and away along it to x = ±edge. */
  leave?: { door: [number, number]; gate: number; edge: number };
  when: (hour: number) => KidsTime;
}

type Pose = [number, number, number, number, number];

/** A role's pose at time t: x, y, z, yaw, pitch. */
type Role = { kind: 'run' | 'chase' | 'swing' | 'path' | 'ring' | 'rock' | 'hop' | 'group'; at: (t: number) => Pose; single: boolean };

/** The heading of a move from (x0, z0) to (x1, z1), or `keep` if it barely moves. */
const heading = (x0: number, z0: number, x1: number, z1: number, keep: number): number =>
  Math.hypot(x1 - x0, z1 - z0) < 1e-4 ? keep : Math.atan2(x1 - x0, z1 - z0);

function runner(R: Rect, r: Rng): (t: number) => Pose {
  const fa = 0.35 + r() * 0.3, fb = 0.3 + r() * 0.35, pa = r() * TAU, pb = r() * TAU;
  const ax = Math.max(0.02, R.w / 2 - 0.07), az = Math.max(0.02, R.d / 2 - 0.07), bob = r() * 3;
  const xz = (t: number): [number, number] => [R.x + ax * Math.sin(fa * t + pa), R.z + az * Math.sin(fb * t + pb)];
  return (t) => {
    const [x, z] = xz(t), [x1, z1] = xz(t + 0.05);
    return [x, Math.abs(Math.sin(t * 12 + bob)) * 0.01, z, heading(x, z, x1, z1, 0), 0.15];
  };
}

/** Move along a polyline at speeds that suit each leg (slow up, fast down), back on the ground to its start, pausing at the top. */
function follow(path: P3[]): (t: number) => Pose {
  const pts = [...path, [path[0][0], 0, path[0][2]] as P3];
  const legs: { a: P3; b: P3; t0: number; dt: number; yaw: number }[] = [];
  const topY = Math.max(...path.map((p) => p[1]));
  let T = 0, yaw = 0;
  for (let i = 1; i < pts.length; i++) {
    const a = pts[i - 1], b = pts[i], dy = b[1] - a[1], flat = Math.hypot(b[0] - a[0], b[2] - a[2]);
    const len = Math.hypot(flat, dy);
    const speed = dy > 0.03 ? 0.09 : dy < -0.03 ? 0.32 : 0.2;
    let dt = Math.max(0.15, len / speed);
    if (a[1] === topY && b[1] === topY && a[1] > 0.05) dt += 1.2;
    yaw = heading(a[0], a[2], b[0], b[2], yaw);
    legs.push({ a, b, t0: T, dt, yaw });
    T += dt;
  }
  T += 0.6;
  return (t) => {
    const u = ((t % T) + T) % T;
    const leg = legs.find((l) => u < l.t0 + l.dt) ?? legs[legs.length - 1];
    const f = Math.min(1, (u - leg.t0) / leg.dt);
    const x = leg.a[0] + (leg.b[0] - leg.a[0]) * f, y = leg.a[1] + (leg.b[1] - leg.a[1]) * f, z = leg.a[2] + (leg.b[2] - leg.a[2]) * f;
    const ground = y < 0.004 ? Math.abs(Math.sin(t * 11)) * 0.008 : 0;
    return [x, y + ground, z, leg.yaw, 0];
  };
}

/**
 * Up to eight children in one rig: on the swings and slides, pushing a roundabout, rocking on a spring
 * rider, chasing each other across open ground, hopping a hopscotch, standing in a ring; and at home time
 * filing out of the door to the street. They show only when `when` says so; each part is a draw call.
 */
export function kidsRig(k: Kit, plan: KidsPlan, r: Rng): void {
  const parts = Math.min(8, plan.parts);
  if (parts <= 0) return;
  const roles: Role[] = [];
  const order = { swing: 0, path: 1, ring: 2, rock: 3 } as const;
  const spots = [...plan.spots].sort((a, b) => order[a.kind] - order[b.kind] + (r() - 0.5) * 1.6);
  if (plan.group && roles.length < parts) {
    const g = plan.group;
    roles.push({ kind: 'group', single: false, at: (t) => [g.x, Math.abs(Math.sin(t * 5)) * 0.006, g.z, Math.sin(t * 0.4) * 0.25, 0] });
  }
  if (plan.hop && roles.length < parts) {
    const { a, b } = plan.hop, L = Math.hypot(b[0] - a[0], b[1] - a[1]), T = L / 0.1, ph = r() * 10;
    roles.push({
      kind: 'hop', single: true, at: (t) => {
        const u = ((t + ph) % (2 * T)) / T, f = u < 1 ? u : 2 - u;
        const yaw = u < 1 ? heading(a[0], a[1], b[0], b[1], 0) : heading(b[0], b[1], a[0], a[1], 0);
        return [a[0] + (b[0] - a[0]) * f, Math.abs(Math.sin(t * 7)) * 0.028, a[1] + (b[1] - a[1]) * f, yaw, 0];
      },
    });
  }
  // keep two parts for chasing when there's open ground
  const forSpots = plan.run.length ? Math.max(0, parts - roles.length - 2) : parts - roles.length;
  for (const s of spots.slice(0, forSpots)) {
    const ph = r() * 20;
    if (s.kind === 'swing') {
      const amp = 0.45 + r() * 0.2, w = 2.3 + r() * 0.4, yaw = Math.atan2(s.dir[0], s.dir[1]);
      roles.push({
        kind: 'swing', single: true, at: (t) => {
          const th = amp * Math.sin(w * t + ph);
          return [s.at[0] + s.dir[0] * s.len * Math.sin(th), s.at[1] - s.len * Math.cos(th) - 0.03, s.at[2] + s.dir[1] * s.len * Math.sin(th), yaw, -th * 0.6];
        },
      });
    } else if (s.kind === 'path' && s.path.length > 1) {
      const f = follow(s.path);
      roles.push({ kind: 'path', single: true, at: (t) => f(t + ph) });
    } else if (s.kind === 'ring') {
      const w = (r() < 0.5 ? 1 : -1) * (1.1 + r() * 0.5);
      roles.push({
        kind: 'ring', single: true, at: (t) => {
          const a = w * t + ph;
          return [s.at[0] + Math.cos(a) * s.rad, Math.abs(Math.sin(t * 11)) * 0.008, s.at[2] + Math.sin(a) * s.rad, Math.atan2(-Math.sin(a) * w, Math.cos(a) * w), 0.2];
        },
      });
    } else if (s.kind === 'rock') {
      const yaw = Math.atan2(s.dir[0], s.dir[1]), w = 4 + r() * 2;
      roles.push({ kind: 'rock', single: true, at: (t) => [s.at[0], s.at[1], s.at[2], yaw, Math.sin(w * t + ph) * 0.25] });
    }
  }
  // the rest run about: every second one chasing the one before, a step behind on its line
  let lead: ((t: number) => Pose) | null = null;
  for (let i = 0; roles.length < parts && plan.run.length; i++) {
    const R = plan.run[i % plan.run.length];
    if (lead && i % 2 === 1) {
      const f = lead, lag = 0.55 + r() * 0.3;
      roles.push({ kind: 'chase', single: true, at: (t) => f(t - lag) });
      lead = null;
    } else {
      lead = runner(R, r);
      roles.push({ kind: 'run', single: true, at: lead });
    }
  }
  if (!roles.length) return;

  const draws = roles.map((role) => (s: Kit) => {
    if (role.kind === 'group' && plan.group) {
      const g = plan.group;
      for (let i = 0; i < g.n; i++) {
        const a = (i / g.n) * TAU + 0.4;
        s.turned(a, () => kid(s, 0, 0, -g.rad, r));
      }
    } else kid(s, 0, 0, 0, r);
  });

  // home time: the single children walk out of the door one after another, in a loop
  const out = plan.leave, stagger = 1.3, P = 11;
  const walk = (i: number, t: number): Pose | null => {
    if (!out) return null;
    const u = (t + i * stagger) % P, side = i % 2 ? 1 : -1, jx = (((i * 37) % 7) - 3) * 0.02;
    const a: [number, number] = [out.door[0] + jx, out.door[1]], b: [number, number] = [out.door[0] + jx * 2, out.gate], c: [number, number] = [side * out.edge, out.gate];
    const l1 = Math.hypot(b[0] - a[0], b[1] - a[1]), l2 = Math.abs(c[0] - b[0]), v = 0.2;
    const s = u * v;
    if (s < l1) return [a[0] + (b[0] - a[0]) * (s / l1), Math.abs(Math.sin(t * 9 + i)) * 0.006, a[1] + (b[1] - a[1]) * (s / l1), heading(a[0], a[1], b[0], b[1], 0), 0];
    if (s < l1 + l2) { const f = (s - l1) / l2; return [b[0] + (c[0] - b[0]) * f, Math.abs(Math.sin(t * 9 + i)) * 0.006, b[1], side > 0 ? Math.PI / 2 : -Math.PI / 2, 0]; }
    return null;
  };

  let t = r() * 100;
  k.rig(0, 0, 0, draws, (objs, dt, hour) => {
    t += dt;
    const when = plan.when(((hour % 24) + 24) % 24);
    for (let i = 0; i < objs.length; i++) {
      const o = objs[i], role = roles[i];
      let pose: Pose | null = null;
      if (when === 'play') pose = role.at(t);
      else if (when === 'leave' && role.single) pose = walk(i, t);
      if (!pose) { o.visible = false; continue; }
      o.visible = true;
      o.rotation.order = 'YXZ';
      o.position.set(pose[0], pose[1], pose[2]);
      o.rotation.set(pose[4], pose[3], 0);
    }
  });
}

/** True on a school day: not a weekend, not the summer holidays. */
export const schoolDay = (): boolean => VIS.uVis.value[Vis.Weekend] <= 0.5 && VIS.uVis.value[Vis.Summer] <= 0.5;
