export type Rng = () => number;

export function hashString(s: string): number {
  let h = 1779033703 ^ s.length;
  for (let i = 0; i < s.length; i++) {
    h = Math.imul(h ^ s.charCodeAt(i), 3432918353);
    h = (h << 13) | (h >>> 19);
  }
  h = Math.imul(h ^ (h >>> 16), 2246822507);
  h = Math.imul(h ^ (h >>> 13), 3266489909);
  return (h ^ (h >>> 16)) >>> 0;
}

export function mulberry32(seed: number): Rng {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Deterministic per-tile hash in [0,1). */
export function hash2(x: number, z: number, salt = 0): number {
  let h = (x * 374761393 + z * 668265263 + salt * 1274126177) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  h ^= h >>> 16;
  return (h >>> 0) / 4294967296;
}

const WORDS = [
  'plum', 'tomato', 'moss', 'pebble', 'dune', 'lantern', 'maple', 'ferry', 'clover', 'heron',
  'cinder', 'willow', 'saffron', 'meadow', 'harbor', 'quince', 'thistle', 'otter', 'bramble', 'sorrel',
];
/** The words a world-mode suffix is made of (see macro.ts): no random seed is ever built from them. */
const RESERVED = new Set(['isles', 'main']);
const SEED_WORDS = WORDS.filter((w) => !RESERVED.has(w));
/** A fresh "word-word-123" seed, with the suffix for this world mode when it is not 'both'. */
export function randomSeed(mode: 'both' | 'islands' | 'mainland' = 'both'): string {
  const a = SEED_WORDS[Math.floor(Math.random() * SEED_WORDS.length)];
  const b = SEED_WORDS[Math.floor(Math.random() * SEED_WORDS.length)];
  const base = `${a}-${b}-${Math.floor(Math.random() * 900 + 100)}`;
  return base + (mode === 'islands' ? '-isles' : mode === 'mainland' ? '-main' : '');
}

/** Deterministic hash of a cell coordinate pair (plus a salt), as a uint32. */
export function hashCell(seed: number, cx: number, cz: number, salt = 0): number {
  let h = (seed ^ Math.imul(cx | 0, 0x9e3779b1) ^ Math.imul(cz | 0, 0x85ebca6b) ^ Math.imul(salt | 0, 0xc2b2ae35)) | 0;
  h = Math.imul(h ^ (h >>> 16), 0x21f0aaad);
  h = Math.imul(h ^ (h >>> 15), 0x735a2d97);
  return (h ^ (h >>> 15)) >>> 0;
}

/** hashCell as a float in [0, 1). */
export function cell01(seed: number, cx: number, cz: number, salt = 0): number {
  return hashCell(seed, cx, cz, salt) / 4294967296;
}

/**
 * Smooth value noise over cell coordinates, in [0, 1). Used for world-scale bands (climate) so
 * neighbouring islands are alike and distant ones differ, without any island seeing another.
 */
export function cellNoise(seed: number, cx: number, cz: number, scale: number, salt = 0): number {
  const x = cx / scale, z = cz / scale;
  const ix = Math.floor(x), iz = Math.floor(z);
  const fx = x - ix, fz = z - iz;
  const sx = fx * fx * (3 - 2 * fx), sz = fz * fz * (3 - 2 * fz);
  const v = (ax: number, az: number) => cell01(seed, ax, az, 9001 + salt);
  const a = v(ix, iz) + (v(ix + 1, iz) - v(ix, iz)) * sx;
  const b = v(ix, iz + 1) + (v(ix + 1, iz + 1) - v(ix, iz + 1)) * sx;
  return a + (b - a) * sz;
}
