import { NEXT_WORLD } from './nextWorld';
import { CUT_MAX, CUT_STEP } from './roadGrade';
import { buildingAt } from './footprint';
import { naturalDecks } from './landformsLocal';
import { DIAG_STEP, hasDiagonals, markDiagonals, sameLine } from './diagonals';
import {
  N, STEP, Biome, Feature, Flag, RailBit, World, RoadType, DIRS, EDGE_MINE, idx, inB, edgeMismatch, maxCorner, minCorner, steepness, tileMean, waterDepth,
  type Bridge, type Road,
} from './tiles';

/** 'flat' trades length for level ground; 'short' takes the fewest tiles the terrain allows. */
/**
 * How a route is chosen: the flattest way round the hills, the fewest tiles, or a mountain road that
 * turns as often as it likes to keep its grade — the switchbacks of an alpine pass.
 */
export type RouteMode = 'flat' | 'short' | 'hairpin';

interface RoadInfo { name: string; width: number; speed: number; span: number; lift: number }

/**
 * Indexed by RoadType. `speed` is the top-speed multiplier for land vehicles on that surface;
 * `span` the most tiles a bridge of that road type may leap; `lift` is the paving's own thickness
 * above the bare ground, in world units — cosmetic (it keeps the surface from z-fighting the terrain
 * under it), but a car's wheels ride on top of the paving, not the ground under it, so anything that
 * reads a car's height reads this too (see `CarState.surf` in game/car.ts).
 */
export const ROAD_INFO: readonly RoadInfo[] = [
  { name: 'No road', width: 0, speed: 1, span: 0, lift: 0 },
  { name: 'Dirt lane', width: 0.6, speed: 1.1, span: 6, lift: 0.02 },
  { name: 'Brick lane', width: 0.64, speed: 1.18, span: 7, lift: 0.025 },
  { name: 'Paved lane', width: 0.62, speed: 1.25, span: 8, lift: 0.03 },
  { name: 'Two-lane road', width: 0.96, speed: 1.25, span: 12, lift: 0.04 },
  { name: 'Four-lane highway', width: 1.94, speed: 1.25, span: 14, lift: 0.05 },
  { name: 'Gravel track', width: 0.58, speed: 1.13, span: 6, lift: 0.02 },
  { name: 'Cobbled street', width: 0.66, speed: 1.16, span: 7, lift: 0.028 },
  // The speeds are all against bare ground (1): a paved road is +25%, and the interstate +50% — a fifth
  // quicker again than any other paved road. Its width is the whole three tiles, median and all.
  { name: 'Interstate', width: 3, speed: 1.5, span: 16, lift: 0.055 },
  { name: 'On/off ramp', width: 0.5, speed: 1.25, span: 8, lift: 0.03 },
];

/** A road's speed against the paved roads' (1.25): what an interstate is worth over any other tarmac, 1.2. */
const PAVED_SPEED = 1.25;

/**
 * How good each surface is. Where two roads cross, the better one owns the tile and draws its own
 * markings over the other. Gravel is a step up from a dirt lane, cobbles sit between brick and paved.
 */
export const ROAD_RANK: Record<RoadType, number> = {
  [RoadType.None]: 0,
  [RoadType.Dirt]: 1,
  [RoadType.Gravel]: 2,
  [RoadType.Brick]: 3,
  [RoadType.Cobble]: 4,
  [RoadType.Paved]: 5,
  [RoadType.TwoLane]: 6,
  [RoadType.FourLane]: 7,
  // a ramp gives way to whatever it joins: the road it meets owns the junction tile and draws over it
  [RoadType.Ramp]: 5.5,
  [RoadType.Interstate]: 8,
};
export const roadRank = (t: RoadType): number => ROAD_RANK[t] ?? 0;

export function roadSpeedMul(t: RoadType): number { return ROAD_INFO[t].speed; }

/**
 * Four-lane roads are two tiles wide. Their nodes are tile corners (lattice points), each
 * carrying the 2×2 block of tiles around it; every other road's nodes are tiles.
 */
export function isWide(t: RoadType): boolean { return t === RoadType.FourLane; }

/**
 * How a road's nodes sit on the tiles: `false` a tile; `true` a tile corner carrying the 2×2 block round it
 * (four lanes); `'tri'` a tile carrying the 3×3 block round it (the interstate, three tiles wide, its
 * nodes tile middles like a lane's so its centre line runs down the middle of the median).
 */
export type Wide = boolean | 'tri';
/** The node shape of a road type (see Wide). `isWide` stays the four-lane test the older code asks. */
export function shapeOf(t: RoadType): Wide { return t === RoadType.Interstate ? 'tri' : t === RoadType.FourLane; }
/** Tiles a node's block reaches past the node itself along a road: 0 a lane, 1 four lanes (a corner's 2×2), 2 an interstate (a tile's 3×3, both ways). */
export function blockExtra(wide: Wide): number { return wide === 'tri' ? 2 : wide ? 1 : 0; }
/** Half a node's block across, in tiles: where its road's edges are, from its centre. */
export function blockHalf(wide: Wide): number { return wide === 'tri' ? 1.5 : wide ? 1 : 0.5; }
/** The lowest and highest node coordinate a road of this shape may use (its block inside the cell). */
function nodeRim(wide: Wide): [number, number] { return wide === 'tri' ? [1, N - 2] : wide ? [1, N - 1] : [0, N - 1]; }

const clampInt = (v: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, v));

export function nodeAt(wx: number, wz: number, wide: Wide): number {
  if (wide === 'tri') return idx(clampInt(Math.floor(wx), 1, N - 2), clampInt(Math.floor(wz), 1, N - 2));
  if (wide) return idx(clampInt(Math.round(wx), 1, N - 1), clampInt(Math.round(wz), 1, N - 1));
  return idx(clampInt(Math.floor(wx), 0, N - 1), clampInt(Math.floor(wz), 0, N - 1));
}

/** World-space centre of a node: the tile centre, or the lattice point itself. */
export function nodeCenter(node: number, wide: Wide): [number, number] {
  const x = node % N, z = (node - x) / N;
  return wide === true ? [x, z] : [x + 0.5, z + 0.5];
}

/** Tiles a node's road surface covers. For a lattice point (x, z): tiles x-1..x by z-1..z; for an interstate's tile, the 3×3 round it. */
export function nodeTiles(node: number, wide: Wide): number[] {
  if (wide === 'tri') return [node - N - 1, node - N, node - N + 1, node - 1, node, node + 1, node + N - 1, node + N, node + N + 1];
  return wide ? [node - N - 1, node - N, node - 1, node] : [node];
}

/** The two tiles of a wide node's block on its side d. */
export function blockSide(n: number, d: number): number[] {
  const [a, b, c, e] = nodeTiles(n, true);
  return d === 0 ? [b, e] : d === 1 ? [c, e] : d === 2 ? [a, c] : [a, b];
}

/** The tiles of a node's block on its side d, whatever its shape: one for a lane, two for four lanes, three for an interstate. */
function sideTiles(n: number, d: number, wide: Wide): number[] {
  if (wide === 'tri') {
    const fwd = DIRS[d][0] + DIRS[d][1] * N, across = d % 2 === 0 ? N : 1;
    return [n + fwd - across, n + fwd, n + fwd + across];
  }
  return wide ? blockSide(n, d) : [n];
}

/** Why a single tile can't carry a road, or null when it can. Shallow fords are fine. */
export function tileProblem(w: World, i: number): string | null {
  if (w.biome[i] === Biome.Ocean) return 'That’s the open sea';
  if (w.blocked[i] || (w.flags[i] & Flag.Poi)) return 'A building is in the way';
  // the open part of a building's lot (a beach club's pool deck, an office park's lawn) is still its ground:
  // a new road goes round it, unless the building is one that roads run across (a pier, a field's track)
  if (AVOID_LOTS && !w.road[i]) { const b = buildingAt(w, i); if (b && !ROAD_OVER.has(b.kind)) return 'A building’s grounds are in the way'; }
  if (waterDepth(w, i) > 1) return 'Water too deep — a bridge needs dry ground to land on';
  if (steepness(w, i) > 1) return 'Too steep to pave — U to level it';
  const rb = w.rail[i];
  if (rb & (RailBit.Pad | RailBit.Loop)) return 'The station is in the way';
  if ((rb & RailBit.Track) && !w.railAxis[i]) return 'A railway is in the way — cross it where the line runs straight';
  return null;
}

/**
 * Roads kept off buildings' lots (the user, 22 Oct 2026: a link road ran across a beach club's pool deck; 40 such
 * in the 49 counties round the origin, none after). It changes where the generator lays roads, so it goes on with
 * the next world (GEN_VERSION 53, which starts the online world again): it is on with world/nextWorld.ts NEXT_WORLD.
 */
export const AVOID_LOTS = NEXT_WORLD;
/** Buildings whose lots roads may cross: a harbour's piers, quays and cranes, a field's tracks, places you drive into. */
const ROAD_OVER = new Set<string>(['crane', 'pier', 'quay', 'field', 'parking', 'driveIn', 'truckStop', 'gas', 'weighStation', 'promenade', 'mailboxRow', 'triumphalArch', 'ranchGate']);

/**
 * The railway's say in a step from node n to node m along d: Infinity when the road would run along the
 * rails (a road only ever crosses a line square on), else the extra a level crossing costs.
 */
export function railStep(w: World, n: number, m: number, d: number, wide: Wide): number {
  let extra = 0;
  const along = d % 2 === 0 ? 1 : 2;
  for (const t of nodeTiles(n, wide)) if ((w.rail[t] & RailBit.Track) && w.railAxis[t] === along) return Infinity;
  for (const t of nodeTiles(m, wide)) {
    if (!(w.rail[t] & RailBit.Track)) continue;
    if (w.railAxis[t] === along) return Infinity;
    extra = 12;
  }
  return extra;
}

/**
 * Whether a generated road must keep off this node: an airfield's runway, apron and hangars are one
 * fenced ground, which the country roads go round rather than straight across. The route's own ends may
 * still stand on it, which is how an airport's gate road leaves its apron.
 */
function fenced(w: World, n: number, wide: Wide): boolean {
  for (const t of nodeTiles(n, wide)) if (w.feature[t] === Feature.Airfield) return true;
  return false;
}

/** Why a road can't pass through this node, or null when it can. */
export function nodeProblem(w: World, node: number, wide: Wide): string | null {
  const x = node % N, z = (node - x) / N;
  const [lo, hi] = nodeRim(wide);
  if (x < lo || z < lo || x > hi || z > hi) return 'Too close to the edge of the island';
  const tiles = nodeTiles(node, wide);
  for (const t of tiles) {
    const p = tileProblem(w, t);
    if (p) return p;
  }
  if (wide === 'tri') {
    // three tiles across, one continuous carriageway: every seam inside the block meets flush
    for (let dz = -1; dz <= 1; dz++) for (let dx = -1; dx <= 1; dx++) {
      const t = node + dz * N + dx;
      if ((dx < 1 && edgeMismatch(w, t, 0)) || (dz < 1 && edgeMismatch(w, t, 1))) return 'Too lumpy for an interstate — U to level it';
    }
  } else if (wide) {
    // the whole 2×2 block must be one continuous surface
    const [a, b, c] = tiles;
    if (edgeMismatch(w, a, 0) || edgeMismatch(w, c, 0) || edgeMismatch(w, a, 1) || edgeMismatch(w, b, 1)) {
      return 'Too lumpy for four lanes — U to level it';
    }
  }
  return null;
}

function nodeHeight(w: World, n: number, wide: Wide): number {
  if (!wide) return tileMean(w, n);
  const ts = nodeTiles(n, wide);
  let s = 0;
  for (const t of ts) s += tileMean(w, t);
  return s / ts.length;
}

function nodeSteep(w: World, n: number, wide: Wide): number {
  if (!wide) return steepness(w, n);
  let s = 0;
  for (const t of nodeTiles(n, wide)) s = Math.max(s, steepness(w, t));
  return s;
}

// ---------------------------------------------------------------------------------------------
// bridges

/** Height (steps) of side d of a node, where a deck would meet it, or NaN when that side isn't level. */
function edgeLevel(w: World, n: number, d: number, wide: Wide): number {
  let h = NaN;
  for (const t of sideTiles(n, d, wide)) {
    for (const k of EDGE_MINE[d]) {
      const v = w.corners[t * 4 + k];
      if (Number.isNaN(h)) h = v;
      else if (v !== h) return NaN;
    }
  }
  return h;
}

/** The highest corner on side d of a node: where an elevated deck meets it when that side isn't level. */
function edgeTop(w: World, n: number, d: number, wide: Wide): number {
  let h = -Infinity;
  for (const t of sideTiles(n, d, wide)) for (const k of EDGE_MINE[d]) h = Math.max(h, w.corners[t * 4 + k]);
  return h;
}

/**
 * Where a car's wheels meet side d of a node's block, in steps: the middle of each tile's edge there (the
 * height `CarState.crossing` compares a deck's end against), or NaN when the tiles across the road don't
 * agree on it, as a lumpy edge under a wide road won't — a deck can land on that only part way across.
 */
function edgeMid(w: World, n: number, d: number, wide: Wide): number {
  let h = NaN;
  for (const t of sideTiles(n, d, wide)) {
    const v = (w.corners[t * 4 + EDGE_MINE[d][0]] + w.corners[t * 4 + EDGE_MINE[d][1]]) / 2;
    if (Number.isNaN(h)) h = v;
    else if (Math.abs(v - h) > 1e-6) return NaN;
  }
  return h;
}

/** Tiles a straight deck from node a to node b (along d) passes over; tile j of L runs from (j-1)/L to j/L of the deck. */
export function deckTiles(a: number, b: number, d: number, wide: Wide): { tile: number; j: number; L: number }[] {
  const ax = a % N, az = (a - ax) / N, bx = b % N, bz = (b - bx) / N;
  const L = Math.abs(bx - ax) + Math.abs(bz - az) - 1 - blockExtra(wide);
  const step = DIRS[d][0] + DIRS[d][1] * N;
  const out: { tile: number; j: number; L: number }[] = [];
  if (L < 1) return out;
  for (const s of sideTiles(a, d, wide)) for (let j = 1; j <= L; j++) out.push({ tile: s + step * j, j, L });
  return out;
}

/** Steps of air a deck keeps above the ground or water below it. */
const CLEARANCE = 1;
/** Steps of air an overpass keeps over the railway or the road running under it, so traffic fits through. */
export const UNDER_CLEARANCE = 2;

/**
 * A deck from node a to node b along d, if one can stand: both abutment edges level, a gentle
 * enough ramp between them, nothing built underneath and clearance everywhere. Heights in world units.
 */
function bridgeBetween(w: World, a: number, b: number, d: number, wide: Wide): { h0: number; h1: number } | null {
  const ea = edgeLevel(w, a, d, wide), eb = edgeLevel(w, b, (d + 2) & 3, wide);
  if (Number.isNaN(ea) || Number.isNaN(eb)) return null;
  const tiles = deckTiles(a, b, d, wide);
  if (!tiles.length) return null;
  const L = tiles[0].L;
  if (Math.abs(ea - eb) > L * 0.5 + 0.01) return null;
  const along = d % 2 === 0 ? 1 : 2;
  for (const { tile, j } of tiles) {
    if (w.blocked[tile] || (w.flags[tile] & Flag.Poi) || w.deckAxis[tile]) return null;
    // a station, or under a viaduct's own deck, leaves no room
    const rb = w.rail[tile];
    if (rb & (RailBit.Pad | RailBit.Loop | RailBit.Deck)) return null;
    // an overpass crosses the railway square on, the way a level crossing does, and never runs along it
    const overRail = (rb & RailBit.Track) !== 0;
    if (overRail && w.railAxis[tile] === along) return null;
    const deck = Math.min(ea + ((eb - ea) * (j - 1)) / L, ea + ((eb - ea) * j) / L);
    // A deck may skim the water — plenty of rivers run level with their own banks, and a deck that
    // had to clear the surface by a whole step could never leave the bank. Dry ground still needs air,
    // and a railway or a road underneath needs enough for what uses it.
    const wl = w.water[tile];
    const clear = overRail || w.road[tile] ? UNDER_CLEARANCE : CLEARANCE;
    const under = wl >= 0 && !overRail && !w.road[tile] ? Math.max(wl, maxCorner(w, tile)) : maxCorner(w, tile) + clear;
    if (under > deck) return null;
  }
  return { h0: ea * STEP, h1: eb * STEP };
}

/**
 * Where wheels meet a bridge deck at (x, z) on deck tile i: the deck's own height there plus the lift its
 * road is painted at (render/roadMesh.ts drapes the road that far above the deck, as it does above the
 * ground). Without the lift the tyres sink into the road surface the whole way across.
 */
export function deckSurfaceAt(w: World, i: number, x: number, z: number): number {
  const tx = i % N, tz = (i - tx) / N;
  const t = Math.min(1, Math.max(0, w.deckAxis[i] === 1 ? x - tx : z - tz));
  return w.deckLo[i] + (w.deckHi[i] - w.deckLo[i]) * t + ROAD_INFO[w.deckRoad[i]].lift;
}

/** deckAxis of a platform tile: a raised road's end or corner, level at deckLo all round (Bridge.level). */
export const DECK_FLAT = 3;

/**
 * Height (world units) of deck tile i at its side s: a ramp's end at its low or high edge, a platform's
 * level anywhere round it; NaN along a ramp's sides, which are its railings. 0-axis tiles have no deck.
 */
export function deckEdgeAt(w: World, i: number, s: number): number {
  const ax = w.deckAxis[i];
  if (ax === DECK_FLAT) return w.deckLo[i];
  if (ax !== (s % 2 === 0 ? 1 : 2)) return NaN;
  return s < 2 ? w.deckHi[i] : w.deckLo[i];
}

/** Where wheels meet tile i's side s on the ground: the middle of that edge (the corners either end, averaged). */
export function groundEdgeAt(w: World, i: number, s: number): number {
  return (w.corners[i * 4 + EDGE_MINE[s][0]] + w.corners[i * 4 + EDGE_MINE[s][1]]) * 0.5 * STEP;
}

/** The higher corner of tile i's side s on the ground (world units). */
function groundEdgeTop(w: World, i: number, s: number): number {
  return Math.max(w.corners[i * 4 + EDGE_MINE[s][0]], w.corners[i * 4 + EDGE_MINE[s][1]]) * STEP;
}

/** How close a deck's edge must come to what it meets for wheels to roll across: a kerb's height. */
const DECK_MEET = 0.15;

/**
 * Does a deck's end at height h (world units) meet tile i's ground at its side s? At the middle of that edge,
 * or anywhere up to its higher corner: viaducts and spans raised for boats land their ends on a sloping edge's
 * higher corner (edgeTop), a kerb's height over its middle, and before this counted as no meeting at all, cars
 * rolled in under the deck and on along the ground beneath it into the water (the user, 22 Oct 2026).
 */
function deckMeetsGround(w: World, h: number, i: number, s: number): boolean {
  return h > groundEdgeAt(w, i, s) - DECK_MEET && h < groundEdgeTop(w, i, s) + DECK_MEET;
}

/**
 * The deck rules, shared by a car's own physics (CarState.crossing) and every route planner that has to
 * agree with them: a move from tile a into its neighbour b across a's side d, for something that is up on
 * a's deck (`onDeck`) or on the ground under or beside it. 1: it ends up on b's deck; 0: on b's ground;
 * -1: no way (a railing, or the drop at a deck's end); -2: no deck has a say, and the ground's own rules
 * (canCross) decide. Along one span's own deck (the same axis) anything goes, as it always has; from deck to
 * deck otherwise — a ramp onto a platform at a raised corner, platform to platform — only where the two edges
 * meet level; on or off a deck only where its end meets the ground's edge (deckMeetsGround: its middle, or up
 * to its higher corner), which is why a deck's end has to be built there (a bridge whose end stood half a unit
 * proud of its approach had cars driving under it, Oct 2026).
 */
export function deckMove(w: World, a: number, b: number, d: number, onDeck: boolean): number {
  const back = (d + 2) & 3;
  if (onDeck) {
    const ab = w.deckAxis[b];
    if (ab) {
      if (ab !== DECK_FLAT && ab === w.deckAxis[a]) return 1;
      if (Math.abs(deckEdgeAt(w, a, d) - deckEdgeAt(w, b, back)) < DECK_MEET) return 1;
    }
    if (!w.blocked[b] && deckMeetsGround(w, deckEdgeAt(w, a, d), b, back)) return 0;
    return -1;
  }
  if (w.deckAxis[b] && deckMeetsGround(w, deckEdgeAt(w, b, back), a, d)) return 1;
  return -2;
}

/** The most a player's deck end lifts or lowers the ground it lands on to meet it flush, in steps. */
const DECK_END_LEVEL = 2;

/**
 * The ground under each end of a player's raised deck (a viaduct, a span raised for boats), re-shaped so the
 * road runs onto the deck flush (the user, 22 Oct 2026): a deck lands on a sloping edge's higher corner, and
 * cars rolled up the kerb that left (deckMeetsGround lets them), but they were seen to jump onto the deck.
 * The approach tile's edge under the deck's end is set to the deck's height; nothing else moves, as with a
 * road cut down a ledge (world/roadGrade.ts). Corner index (tile × 4 + q) → new height, in steps. A tile left
 * alone: anything that isn't plain dry ground or a straight road, or more than DECK_END_LEVEL steps out.
 */
export function deckEndCorners(w: World, type: RoadType, nodes: number[], bridges: Bridge[]): Map<number, number> {
  const out = new Map<number, number>();
  const wide = shapeOf(type);
  for (const b of bridges) {
    if (!b.raised || b.tunnel || b.level || b.to <= b.from + 1) continue;
    const d = dirBetween(nodes[b.from], nodes[b.from + 1]);
    for (const [n, side, h] of [[nodes[b.from], d, b.h0], [nodes[b.to], (d + 2) & 3, b.h1]] as const) {
      const want = Math.round(h / STEP);
      if (Math.abs(want * STEP - h) > 1e-6) continue;
      const tiles = sideTiles(n, side, wide);
      const ok = tiles.every((t) => {
        if (w.blocked[t] || w.rail[t] || w.deckAxis[t] || w.water[t] >= 0 || (w.flags[t] & (Flag.Poi | Flag.Corridor))) return false;
        // a road already here may only run along the deck's line: a junction's other arms would be left on a step
        const tx = t % N, tz = (t - tx) / N;
        if (w.road[t]) for (const q of [(side + 1) & 3, (side + 3) & 3]) {
          const nx = tx + DIRS[q][0], nz = tz + DIRS[q][1];
          if (inB(nx, nz) && w.road[idx(nx, nz)] && !tiles.includes(idx(nx, nz))) return false;
        }
        return EDGE_MINE[side].every((q) => Math.abs(w.corners[t * 4 + q] - want) <= DECK_END_LEVEL);
      });
      if (!ok) continue;
      for (const t of tiles) for (const q of EDGE_MINE[side]) if (w.corners[t * 4 + q] !== want) out.set(t * 4 + q, want);
    }
  }
  return out;
}

/** The steepest a deck ramps, in steps of height per tile: the same grade a road may climb. */
const DECK_GRADE = 0.5;

/**
 * How high a deck stands at `t` tiles along its length. An ordinary bridge runs straight from one
 * abutment to the other. A flyover has a `peak`: it ramps up at DECK_GRADE, runs level over whatever
 * it is crossing, and ramps back down, so a road can fly over a railway on flat ground.
 */
export function deckHeightAt(br: { h0: number; h1: number; peak?: number; ramp?: number }, L: number, t: number): number {
  if (br.peak === undefined) return br.h0 + ((br.h1 - br.h0) * t) / L;
  if (br.ramp) {
    const r = br.ramp;
    if (t <= r) return br.h0 + ((br.peak - br.h0) * t) / r;
    if (t >= L - r) return br.h1 + ((br.peak - br.h1) * (L - t)) / r;
    return br.peak;
  }
  const slope = DECK_GRADE * STEP;
  const up = (br.peak - br.h0) / slope, down = (br.peak - br.h1) / slope;
  if (t <= up) return br.h0 + slope * t;
  if (t >= L - down) return br.h1 + slope * (L - t);
  return br.peak;
}

/**
 * A flyover from node a to node b along d: a deck that climbs over whatever runs between them —
 * a railway, another road — rather than needing a valley to cross. The crest stands clear of
 * everything under it, the ramps hold the road's own grade, and the piers do the rest.
 */
function flyoverBetween(w: World, a: number, b: number, d: number, wide: Wide): { h0: number; h1: number; peak: number } | null {
  const ea = edgeLevel(w, a, d, wide), eb = edgeLevel(w, b, (d + 2) & 3, wide);
  if (Number.isNaN(ea) || Number.isNaN(eb)) return null;
  const tiles = deckTiles(a, b, d, wide);
  if (!tiles.length) return null;
  const L = tiles[0].L;
  const along = d % 2 === 0 ? 1 : 2;
  // what each tile needs the deck to clear, and whether the whole thing is worth building
  const need = new Map<number, number>();
  let crossing = false;
  for (const { tile, j } of tiles) {
    if (w.blocked[tile] || (w.flags[tile] & Flag.Poi) || w.deckAxis[tile]) return null;
    const rb = w.rail[tile];
    if (rb & (RailBit.Pad | RailBit.Loop | RailBit.Deck)) return null;
    const overRail = (rb & RailBit.Track) !== 0;
    if (overRail && w.railAxis[tile] === along) return null;
    const under = overRail || w.road[tile] ? maxCorner(w, tile) + UNDER_CLEARANCE : Math.max(maxCorner(w, tile), w.water[tile] >= 0 ? w.water[tile] : -Infinity);
    if (overRail || w.road[tile]) crossing = true;
    need.set(j, Math.max(need.get(j) ?? -Infinity, under));
  }
  if (!crossing) return null;
  let peak = Math.max(ea, eb);
  for (const v of need.values()) peak = Math.max(peak, v);
  const up = (peak - ea) / DECK_GRADE, down = (peak - eb) / DECK_GRADE;
  if (up + down > L) return null;
  // every tile of the ramps has to clear what is under it too
  const profile = (t: number) => {
    if (t <= up) return ea + DECK_GRADE * t;
    if (t >= L - down) return eb + DECK_GRADE * (L - t);
    return peak;
  };
  for (const [j, under] of need) {
    if (Math.min(profile(j - 1), profile(j)) < under - 1e-6) return null;
  }
  return { h0: ea * STEP, h1: eb * STEP, peak: peak * STEP };
}

/**
 * A crossing raised well clear of the water: a deck from node a to node b along d that climbs from
 * each abutment at the road's own grade to stand `rise` steps over the water (and clear of the dry
 * ground under it), level across the middle, so the road never has to come down to the waterline to cross. A
 * megalopolis's bridges are built this way. Null where the ramps will not fit between the abutments.
 */
export function raisedBetween(w: World, a: number, b: number, d: number, wide: Wide, rise: number): { h0: number; h1: number; peak: number } | null {
  const ea = edgeLevel(w, a, d, wide), eb = edgeLevel(w, b, (d + 2) & 3, wide);
  if (Number.isNaN(ea) || Number.isNaN(eb)) return null;
  const tiles = deckTiles(a, b, d, wide);
  if (!tiles.length) return null;
  const L = tiles[0].L;
  const along = d % 2 === 0 ? 1 : 2;
  const need = new Map<number, number>();
  for (const { tile, j } of tiles) {
    if (w.blocked[tile] || (w.flags[tile] & Flag.Poi) || w.deckAxis[tile]) return null;
    const rb = w.rail[tile];
    if (rb & (RailBit.Pad | RailBit.Loop | RailBit.Deck)) return null;
    const overRail = (rb & RailBit.Track) !== 0;
    if (overRail && w.railAxis[tile] === along) return null;
    const wet = w.water[tile] >= 0 && waterDepth(w, tile) > 0;
    const under = overRail || w.road[tile] ? maxCorner(w, tile) + UNDER_CLEARANCE
      : wet ? Math.max(w.water[tile] + rise, maxCorner(w, tile)) : maxCorner(w, tile);
    need.set(j, Math.max(need.get(j) ?? -Infinity, under));
  }
  let peak = Math.max(ea, eb);
  for (const v of need.values()) peak = Math.max(peak, v);
  const up = (peak - ea) / DECK_GRADE, down = (peak - eb) / DECK_GRADE;
  if (up + down > L) return null;
  const profile = (t: number) => (t <= up ? ea + DECK_GRADE * t : t >= L - down ? eb + DECK_GRADE * (L - t) : peak);
  for (const [j, under] of need) if (Math.min(profile(j - 1), profile(j)) < under - 1e-6) return null;
  return { h0: ea * STEP, h1: eb * STEP, peak: peak * STEP };
}

/** Surfaces that splash through shallow water on the ground; every other generated road is raised over it. */
const fords = (t: RoadType) => t === RoadType.Dirt || t === RoadType.Gravel;
/** A raised crossing's ramp at each end, in tiles (on the dry bank), and the steps its deck stands over the water. */
const RAISED_RAMP = 1, RAISED_RISE = 1;

/**
 * A raised crossing from node a to node b along d, over shallow water a paved road would otherwise
 * run through: a ramp on the dry tile at each end, then a level deck RAISED_RISE steps over the
 * water. The ramps and the deck stay clear of the ground under them, and nothing else may be there —
 * no building, railway, other road or deck. Null where it will not stand.
 */
function raisedCrossing(w: World, a: number, b: number, d: number, wide: Wide): Bridge | null {
  const ea = edgeLevel(w, a, d, wide), eb = edgeLevel(w, b, (d + 2) & 3, wide);
  if (Number.isNaN(ea) || Number.isNaN(eb)) return null;
  const tiles = deckTiles(a, b, d, wide);
  if (!tiles.length) return null;
  const L = tiles[0].L, R = RAISED_RAMP;
  if (L < 2 * R + 1) return null;
  let peak = Math.max(ea, eb);
  for (const { tile, j } of tiles) {
    if (w.blocked[tile] || (w.flags[tile] & Flag.Poi) || w.deckAxis[tile] || w.road[tile] || w.rail[tile] || w.biome[tile] === Biome.Ocean) return null;
    const wet = w.water[tile] >= 0 && waterDepth(w, tile) > 0;
    // the ramps stand on the bank
    if (wet && (j <= R || j > L - R)) return null;
    peak = Math.max(peak, wet ? w.water[tile] + RAISED_RISE : maxCorner(w, tile));
  }
  const profile = (t: number) => (t <= R ? ea + ((peak - ea) * t) / R : t >= L - R ? eb + ((peak - eb) * (L - t)) / R : peak);
  const far = EDGE_MINE[d], near = EDGE_MINE[(d + 2) & 3];
  for (const { tile, j } of tiles) {
    const c = tile * 4;
    if (profile(j - 1) < Math.max(w.corners[c + near[0]], w.corners[c + near[1]]) - 1e-6) return null;
    if (profile(j) < Math.max(w.corners[c + far[0]], w.corners[c + far[1]]) - 1e-6) return null;
  }
  return { from: 0, to: 0, h0: ea * STEP, h1: eb * STEP, peak: peak * STEP, ramp: R };
}

/**
 * A generated road's bridges with a raised crossing added over every stretch of shallow water its
 * nodes run through on the ground, where one will stand; dirt and gravel keep fording. Stretches a few
 * dry tiles apart share one deck, so the road doesn't bob down between them. Where a crossing will
 * not stand (the road turns in the water, or ends in it) the road still fords.
 */
export function raiseFords(w: World, type: RoadType, nodes: number[], bridges: Bridge[]): Bridge[] {
  const R = RAISED_RAMP;
  if (fords(type) || nodes.length < 2 * R + 3) return bridges;
  const wide = shapeOf(type);
  const out = bridges.slice();
  const spanned = (k: number) => bridges.some((b) => k > b.from && k < b.to);
  const runs: [number, number][] = [];
  for (let k = 0; k < nodes.length; k++) {
    if (spanned(k) || !wetNode(w, nodes[k], wide)) continue;
    const last = runs[runs.length - 1];
    if (last && last[1] === k - 1) last[1] = k;
    else runs.push([k, k]);
  }
  if (!runs.length) return bridges;
  const lay = (i: number, j: number): boolean => {
    const p = i - 1 - R, q = j + 1 + R;
    if (p < 0 || q >= nodes.length || !out.every((b) => q <= b.from || p >= b.to)) return false;
    const d = dirBetween(nodes[p], nodes[p + 1]);
    for (let k = p + 1; k < q; k++) if (dirBetween(nodes[k], nodes[k + 1]) !== d) return false;
    const br = raisedCrossing(w, nodes[p], nodes[q], d, wide);
    if (!br) return false;
    out.push({ ...br, from: p, to: q });
    return true;
  };
  for (let r = 0; r < runs.length; r++) {
    // runs whose ramps would meet go under one deck; failing that, each on its own
    let s = r;
    while (s + 1 < runs.length && runs[s + 1][0] - runs[s][1] <= 2 * R + 2) s++;
    for (let e = s; e >= r; e--) if (lay(runs[r][0], runs[e][1])) { r = e; break; }
  }
  return out.sort((x, y) => x.from - y.from);
}

/** Rock a tunnel keeps over its roof, in steps: less than this and it would be a cutting, not a bore. */
const TUNNEL_COVER = 1.5;

/**
 * A tunnel from node a to node b along d: the road bores straight through the hill between them at a
 * gentle grade, with a portal at each end. It rides the same deck tables a bridge does — the car and
 * the traffic drive the deck's height and ignore the ground — so the hillside is simply drawn over it.
 *
 * Every tile between has to be properly inside the hill (rock over the roof), dry, and clear of
 * buildings, decks and the railway.
 */
function tunnelBetween(w: World, a: number, b: number, d: number, wide: Wide): { h0: number; h1: number; tunnel: true } | null {
  const ea = edgeLevel(w, a, d, wide), eb = edgeLevel(w, b, (d + 2) & 3, wide);
  if (Number.isNaN(ea) || Number.isNaN(eb)) return null;
  const tiles = deckTiles(a, b, d, wide);
  if (!tiles.length) return null;
  const L = tiles[0].L;
  if (Math.abs(ea - eb) > L * DECK_GRADE + 0.01) return null;
  let buried = 0;
  for (const { tile, j } of tiles) {
    if (w.blocked[tile] || (w.flags[tile] & Flag.Poi) || w.deckAxis[tile]) return null;
    // no boring through a station, a viaduct's footings, water or another tunnel
    if (w.rail[tile] & (RailBit.Pad | RailBit.Loop | RailBit.Deck | RailBit.Tunnel)) return null;
    if (w.water[tile] >= 0) return null;
    const roof = Math.max(ea + ((eb - ea) * (j - 1)) / L, ea + ((eb - ea) * j) / L);
    const over = minCorner(w, tile) - roof;
    // the mouths are cut into the hillside, so the first and last tile only have to clear the road;
    // everything between them is properly under the hill
    if (over < (j === 1 || j === L ? 0 : TUNNEL_COVER)) return null;
    if (over >= TUNNEL_COVER) buried++;
  }
  // a bore under a single lump of rock is a cutting; a tunnel is worth the name from a few tiles on
  if (buried < 3) return null;
  return { h0: ea * STEP, h1: eb * STEP, tunnel: true };
}

/** Deck geometry of every bridge in a road, per tile: axis, the heights at its low and high edges, and whether it tolls. */
export function bridgeDecks(r: { type: RoadType; nodes: number[]; bridges?: Bridge[] }): Map<number, { axis: number; lo: number; hi: number; toll: boolean }> {
  const out = new Map<number, { axis: number; lo: number; hi: number; toll: boolean }>();
  const wide = shapeOf(r.type);
  for (const br of r.bridges ?? []) {
    // a raised road's platform: its node's own tiles, level all round
    if (br.level) {
      for (const tile of nodeTiles(r.nodes[br.from], wide)) out.set(tile, { axis: DECK_FLAT, lo: br.h0, hi: br.h0, toll: !!br.toll });
      continue;
    }
    const d = dirBetween(r.nodes[br.from], r.nodes[br.from + 1]);
    const axis = d % 2 === 0 ? 1 : 2, rising = d < 2;
    for (const { tile, j, L } of deckTiles(r.nodes[br.from], r.nodes[br.to], d, wide)) {
      const y0 = deckHeightAt(br, L, j - 1), y1 = deckHeightAt(br, L, j);
      out.set(tile, { axis, lo: rising ? y0 : y1, hi: rising ? y1 : y0, toll: !!br.toll });
    }
  }
  return out;
}

/**
 * Fill in the deck heights of bridges found by a route search (they are re-checked against the terrain).
 * With `rise`, a span over open water is raised that many steps clear of it where its ramps fit
 * (raisedBetween), as a megalopolis's are, before falling back to a deck at the level of its banks.
 */
export function resolveBridges(w: World, type: RoadType, nodes: number[], bridges: Bridge[], rise = 0): Bridge[] {
  const wide = shapeOf(type);
  const out: Bridge[] = [];
  for (const b of bridges) {
    const d = dirBetween(nodes[b.from], nodes[b.from + 1]);
    const wet = rise > 0 && deckTiles(nodes[b.from], nodes[b.to], d, wide).some(({ tile }) => waterDepth(w, tile) > 0);
    const hts = (wet ? raisedBetween(w, nodes[b.from], nodes[b.to], d, wide, rise) : null)
      ?? bridgeBetween(w, nodes[b.from], nodes[b.to], d, wide)
      ?? flyoverBetween(w, nodes[b.from], nodes[b.to], d, wide)
      ?? tunnelBetween(w, nodes[b.from], nodes[b.to], d, wide);
    if (hts) out.push({ from: b.from, to: b.to, ...hts });
  }
  return out;
}

/** A player's span over this many tiles of water or more is raised for boats, this many steps over it… */
export const BOAT_WATER = 4, BOAT_RISE = 3;
/** …and a crossing of a broad river or a strait, higher again. */
export const BROAD_WATER = 10, BROAD_RISE = 4;

/**
 * A player's bridges over broad water raised so boats pass under: a span over BOAT_WATER tiles of water
 * or more climbs at the road's grade to stand BOAT_RISE steps over it (BROAD_RISE over BROAD_WATER), level
 * across the middle (raisedBetween). Where the ramps won't fit between its banks it stays as it was.
 * Tunnels and flyovers are left alone.
 */
function raiseSpans(w: World, type: RoadType, nodes: number[], bridges: Bridge[]): Bridge[] {
  const wide = shapeOf(type);
  const out = bridges.slice();
  for (let n = 0; n < out.length; n++) {
    const b = out[n];
    if (b.tunnel || b.peak !== undefined) continue;
    const d = dirBetween(nodes[b.from], nodes[b.from + 1]);
    const tiles = deckTiles(nodes[b.from], nodes[b.to], d, wide);
    const wet = new Set(tiles.filter(({ tile }) => waterDepth(w, tile) > 0).map(({ j }) => j)).size;
    if (wet < BOAT_WATER) continue;
    // how far back along the straight road the approaches may reach onto the banks, either way: not past
    // a bend, the road's end, or another deck
    const straight = (k: number) => dirBetween(nodes[k], nodes[k + 1]) === d;
    let back = 0, on = 0;
    while (back < APPROACH && b.from - back - 1 >= 0 && straight(b.from - back - 1) && !out.some((o) => o !== b && o.to > b.from - back - 1 && o.from < b.from - back)) back++;
    while (on < APPROACH && b.to + on + 1 < nodes.length && straight(b.to + on) && !out.some((o) => o !== b && o.from < b.to + on + 1 && o.to > b.to + on)) on++;
    // as high as it will go on the shortest approaches that let it, and failing that a little lower
    let done: Bridge | null = null;
    for (const rise of wet >= BROAD_WATER ? [BROAD_RISE, BOAT_RISE, BOAT_RISE - 1] : [BOAT_RISE, BOAT_RISE - 1]) {
      for (let e = 0; e <= Math.max(back, on) && !done; e++) {
        const s = b.from - Math.min(e, back), t = b.to + Math.min(e, on);
        const hts = humpBetween(w, nodes[s], nodes[t], d, wide, rise);
        if (hts) done = { ...b, from: s, to: t, ...hts, raised: 1 };
      }
      if (done) break;
    }
    if (done) out[n] = done;
  }
  return out;
}

/** Nodes of road either side of a span its approaches may climb over to raise it for boats. */
const APPROACH = 5;

/** How steeply a bridge raised for boats climbs from its banks, in steps a tile: steeper than a road may, as a hump-backed bridge does. */
const HUMP_GRADE = 0.75;

/**
 * A span raised for boats from node a to node b along d: it climbs from each bank at HUMP_GRADE to stand
 * `rise` steps over the water, level across the middle. The ramps may run out over the water (never
 * under its surface); dry ground under them only has to stay under the deck, and a road or railway beneath
 * keeps its headroom. Null where the climb won't fit between the banks or something is in the way.
 */
function humpBetween(w: World, a: number, b: number, d: number, wide: Wide, rise: number): { h0: number; h1: number; peak: number; ramp: number } | null {
  // the approaches start on the bank wherever the road is, meeting a sloping edge at its higher corner
  const ea = edgeTop(w, a, d, wide), eb = edgeTop(w, b, (d + 2) & 3, wide);
  const tiles = deckTiles(a, b, d, wide);
  if (!tiles.length) return null;
  const L = tiles[0].L;
  const along = d % 2 === 0 ? 1 : 2;
  const need = new Map<number, number>();
  let peak = Math.max(ea, eb);
  for (const { tile, j } of tiles) {
    if (w.blocked[tile] || (w.flags[tile] & Flag.Poi) || w.deckAxis[tile]) return null;
    const rb = w.rail[tile];
    if (rb & (RailBit.Pad | RailBit.Loop | RailBit.Deck)) return null;
    const overRail = (rb & RailBit.Track) !== 0;
    if (overRail && w.railAxis[tile] === along) return null;
    const wet = w.water[tile] >= 0;
    if (wet) peak = Math.max(peak, w.water[tile] + rise);
    const under = overRail || w.road[tile] ? maxCorner(w, tile) + UNDER_CLEARANCE : wet ? Math.max(w.water[tile], maxCorner(w, tile)) : maxCorner(w, tile);
    need.set(j, Math.max(need.get(j) ?? -Infinity, under));
  }
  const R = Math.ceil(Math.max(peak - ea, peak - eb) / HUMP_GRADE - 1e-9);
  if (R < 1 || 2 * R + 1 > L) return null;
  const profile = (t: number) => (t <= R ? ea + ((peak - ea) * t) / R : t >= L - R ? eb + ((peak - eb) * (L - t)) / R : peak);
  for (const [j, under] of need) if (Math.min(profile(j - 1), profile(j)) < under - 1e-6) return null;
  return { h0: ea * STEP, h1: eb * STEP, peak: peak * STEP, ramp: R };
}

/** The highest a road may be raised above the ground with + and −, in steps. */
export const LIFT_MAX = 8;
/** Nodes in from each end of a straight stretch an elevated deck may start, looking for level ground to meet. */
const ELEVATE_SLACK = 3;

/**
 * An elevated stretch from node a to node b along d: a deck that climbs from each end at the road's
 * grade to stand `lift` steps over the higher of its ends (and a step at least over any ground or water it
 * passes), level along the middle, and clear of any road or railway beneath by the usual margin. Null where it won't stand: the ramps don't
 * fit, or a building, a station or another deck is in the way.
 */
function elevatedBetween(w: World, a: number, b: number, d: number, wide: Wide, lift: number): { h0: number; h1: number; peak: number } | null {
  // an elevated road starts wherever the road does, on level ground or not: on a slope it meets the
  // higher corner of the edge, a kerb's height at most on the low side, and never cuts into the ground
  const ea = edgeTop(w, a, d, wide), eb = edgeTop(w, b, (d + 2) & 3, wide);
  const tiles = deckTiles(a, b, d, wide);
  if (!tiles.length) return null;
  const L = tiles[0].L;
  const along = d % 2 === 0 ? 1 : 2;
  const need = new Map<number, number>();
  let ground = -Infinity;
  for (const { tile, j } of tiles) {
    if (w.blocked[tile] || (w.flags[tile] & Flag.Poi) || w.deckAxis[tile]) return null;
    const rb = w.rail[tile];
    if (rb & (RailBit.Pad | RailBit.Loop | RailBit.Deck)) return null;
    const overRail = (rb & RailBit.Track) !== 0;
    if (overRail && w.railAxis[tile] === along) return null;
    const top = Math.max(maxCorner(w, tile), w.water[tile] >= 0 ? w.water[tile] + 1 : -Infinity);
    ground = Math.max(ground, top);
    need.set(j, Math.max(need.get(j) ?? -Infinity, overRail || w.road[tile] ? maxCorner(w, tile) + UNDER_CLEARANCE : top));
  }
  // `lift` over the higher of its two ends, and a step of air at least over any ground it passes
  let peak = Math.max(ea, eb) + lift;
  peak = Math.max(peak, ground + CLEARANCE);
  for (const v of need.values()) peak = Math.max(peak, v);
  const up = (peak - ea) / DECK_GRADE, down = (peak - eb) / DECK_GRADE;
  if (up + down > L - 1) return null;
  const profile = (t: number) => (t <= up ? ea + DECK_GRADE * t : t >= L - down ? eb + DECK_GRADE * (L - t) : peak);
  for (const [j, under] of need) if (Math.min(profile(j - 1), profile(j)) < under - 1e-6) return null;
  return { h0: ea * STEP, h1: eb * STEP, peak: peak * STEP };
}

/**
 * A road raised `lift` steps off the ground (the builder's + and −): every straight stretch of it long
 * enough for the ramps becomes one elevated deck, taking in any bridge on it; its ends come down to meet
 * the road's ends, and at a bend it comes down and goes up again, since a deck runs straight. A stretch
 * that won't stand keeps its own bridges and stays on the ground. Returns the bridges, and how many
 * stretches were raised.
 */
export function elevate(w: World, type: RoadType, nodes: number[], bridges: Bridge[], lift: number): { bridges: Bridge[]; raised: number } {
  if (lift <= 0 || nodes.length < 3) return { bridges, raised: 0 };
  const wide = shapeOf(type);
  const out: Bridge[] = [];
  let raised = 0;
  for (let p = 0; p < nodes.length - 1;) {
    const d = dirBetween(nodes[p], nodes[p + 1]);
    let q = p + 1;
    while (q < nodes.length - 1 && dirBetween(nodes[q], nodes[q + 1]) === d) q++;
    const inside = bridges.filter((b) => b.from >= p && b.to <= q);
    // where the ground climbs toward an end, the ramp lands on it sooner: the deck may start and come down
    // anywhere in the outer third of the stretch, the road running on the ground up to it; the longest
    // deck that stands is taken
    let deck: Bridge | null = null;
    const slack = Math.max(ELEVATE_SLACK, Math.floor((q - p) / 3));
    for (let s = p; s <= Math.min(p + slack, q) && !deck; s++) {
      for (let e = q; e >= Math.max(q - slack, s + 3) && !deck; e--) {
        // a bridge the deck would only half take in can't be part of it
        if (inside.some((b) => (b.from < s && b.to > s) || (b.from < e && b.to > e))) continue;
        const hts = elevatedBetween(w, nodes[s], nodes[e], d, wide, lift);
        if (hts) deck = { from: s, to: e, ...hts, raised: 2 };
      }
    }
    if (deck) {
      out.push(deck, ...inside.filter((b) => b.to <= deck!.from || b.from >= deck!.to));
      raised++;
    } else out.push(...inside);
    p = q;
  }
  return { bridges: out.sort((x, y) => x.from - y.from), raised };
}

/** The steepest a builder's raised road climbs between two of its platforms, in steps a tile: the most the ground it paves may climb. */
const LIFT_GRADE = 1;

/**
 * A builder's road that starts `a` steps off the ground and ends `b` steps off it (+ and − before the first
 * click set the start, after it the end). Between, the lift runs evenly from one to the other, node by node
 * over the ground under it: a road from +1 to the ground slopes down the whole of its length to land at its
 * far end. Every node in the air is deck:
 *
 * - each raised end, and every corner turned in the air, is a level platform (Bridge.level) over the node's
 *   own tiles, so a road can stop in mid-air and be carried on from there in any direction, and turn;
 * - between them each straight run is one deck sloping evenly from one platform's height to the next's, so
 *   it climbs and falls with the ground under it a run at a time; where the ground would poke through
 *   the deck (or a road under it would lose its headroom) another platform is put in there;
 * - where it comes down it lands on a node of ground at exactly the height of that node's edge, the
 *   height a car rolls on and off at (deckMove).
 *
 * The bridges the route already had stay where they are on the part on the ground. Returns the new list,
 * or why the road can't be raised like that.
 *
 * `opt` (a railway's, game/railBuilder.ts): `sea` keeps the deck that many steps over deep water wherever it runs out
 * over it, so boats pass under; `atA`/`atB` stand a raised end at exactly that height (steps), as a branch leaving a
 * line on a viaduct must.
 */
export function raiseEnds(w: World, type: RoadType, nodes: number[], bridges: Bridge[], a: number, b: number,
  opt?: { sea?: number; atA?: number; atB?: number }): { bridges: Bridge[]; why?: string; raised: number } {
  const K = nodes.length - 1;
  if ((a <= 0 && b <= 0) || K < 1) return { bridges, raised: 0 };
  const wide = shapeOf(type), ext = blockExtra(wide);
  // the lift wanted at each node, in steps over the ground under it
  const l = new Float64Array(K + 1);
  for (let k = 0; k <= K; k++) l[k] = a + ((b - a) * k) / K;
  const dirs: number[] = [];
  for (let k = 1; k <= K; k++) dirs.push(dirBetween(nodes[k - 1], nodes[k]));
  const bend = (k: number) => k > 0 && k < K && dirs[k - 1] !== dirs[k];
  const inSpan = (k: number) => bridges.some((br) => !br.level && k > br.from && k < br.to);
  /** The ground (or water) a node's deck has to stand over, in steps. */
  const top = (k: number) => {
    let h = -Infinity;
    for (const t of nodeTiles(nodes[k], wide)) h = Math.max(h, maxCorner(w, t), w.water[t] >= 0 ? w.water[t] : -Infinity);
    return h;
  };
  /** Deep water under node k (the sea a boat sails): the surface, in steps, or NaN. */
  const deep = (k: number) => {
    let h = NaN;
    for (const t of nodeTiles(nodes[k], wide)) if (w.water[t] >= 0 && (w.biome[t] === Biome.Ocean || waterDepth(w, t) > 1)) h = Number.isNaN(h) ? w.water[t] : Math.max(h, w.water[t]);
    return h;
  };
  /** A platform already standing at node k (the end of a raised road being carried on), in steps; NaN for none. */
  const standing = (k: number) => {
    for (const t of nodeTiles(nodes[k], wide)) if (w.deckAxis[t] === DECK_FLAT) return w.deckLo[t] / STEP;
    return NaN;
  };
  const keyBefore = (g: number) => { let k = g - 1; while (k > 0 && !bend(k)) k--; return k; };
  const keyAfter = (g: number) => { let k = g + 1; while (k < K && !bend(k)) k++; return k; };

  // where the road comes down, if it does: its ground end, or failing that the node nearest it with a deck
  // tile at least between it and the corner (or raised end) before it, on an edge level across the road, and not
  // in the middle of a bridge — the road runs on the ground up to there, and the lift is reckoned from there
  let lo = 0, hi = K, foot = -1;
  if (!(a > 0 && b > 0)) {
    const fromStart = a > 0;
    let found = -1;
    for (let s = 0; s <= Math.floor(K / 2) && found < 0; s++) {
      const k = fromStart ? K - s : s;
      if (inSpan(k)) continue;
      const near = fromStart ? keyBefore(k) : keyAfter(k);
      if (Math.abs(k - near) < ext + 2) continue;
      const d = fromStart ? (dirs[k - 1] + 2) & 3 : dirs[k];
      if (Number.isNaN(edgeMid(w, nodes[k], d, wide))) continue;
      found = k;
    }
    if (found < 0) return { bridges, why: 'No straight, level ground for its ramp to come down on', raised: 0 };
    foot = found;
    if (fromStart) hi = foot - 1; else lo = foot + 1;
    for (let k = 0; k <= K; k++) l[k] = fromStart ? (k < foot ? (a * (foot - k)) / foot : 0) : (k > foot ? (b * (k - foot)) / (K - foot) : 0);
  }
  // the ground's bridges inside the raised part go (the deck carries the road over whatever they spanned);
  // those on the part on the ground stay, and the foot is never inside one (inSpan, above)
  const kept = foot < 0 ? [] : bridges.filter((br) => (foot > hi ? br.from >= foot : br.to <= foot));

  // the platforms: the raised ends, every corner in the air, and (below) wherever the ground pokes up
  const T = new Float64Array(K + 1).fill(NaN);
  const keys = new Set<number>();
  for (let k = lo; k <= hi; k++) {
    if (k === 0 || k === K || bend(k)) keys.add(k);
    T[k] = top(k) + l[k];
    if (opt?.sea) { const d = deep(k); if (!Number.isNaN(d)) T[k] = Math.max(T[k], d + opt.sea); }
  }
  if (a > 0) { const s = standing(0); if (!Number.isNaN(s)) T[0] = s; }
  if (b > 0) { const s = standing(K); if (!Number.isNaN(s)) T[K] = s; }
  if (a > 0 && opt?.atA !== undefined) T[0] = opt.atA;
  if (b > 0 && opt?.atB !== undefined) T[K] = opt.atB;
  // what the road meets where it lands, in steps
  const footH = foot < 0 ? NaN : edgeMid(w, nodes[foot], foot > hi ? (dirs[foot - 1] + 2) & 3 : dirs[foot], wide);

  for (let pass = 0; pass <= K; pass++) {
    const list = [...keys].sort((x, y) => x - y);
    // platforms close enough that no deck tile lies between them stand at one height
    for (let again = true; again;) {
      again = false;
      for (let n = 1; n < list.length; n++) {
        const p = list[n - 1], q = list[n];
        if (q - p <= ext + 1 && Math.abs(T[p] - T[q]) > 1e-9) { T[p] = T[q] = Math.max(T[p], T[q]); again = true; }
      }
    }
    // each straight between two platforms (or a platform and the foot): clear of what is under it, and not too steep
    const stops = foot < 0 ? list : foot > hi ? [...list, foot] : [foot, ...list];
    let split = -1, why = '';
    for (let n = 1; n < stops.length && split < 0 && !why; n++) {
      const p = stops[n - 1], q = stops[n];
      const h0 = p === foot ? footH : T[p], h1 = q === foot ? footH : T[q];
      if (q - p <= ext + 1) {
        // a platform right against the ground where it lands, no ramp between: only if it is at the ground's height
        if ((p === foot || q === foot) && Math.abs(h1 - h0) > 1e-6) { why = 'Too steep where it comes down — give it a longer straight to land on'; break; }
        continue;
      }
      const d = dirs[p];
      const tiles = deckTiles(nodes[p], nodes[q], d, wide);
      const L = tiles[0].L;
      if (Math.abs(h1 - h0) > LIFT_GRADE * L + 1e-6) { why = `Too steep: ${fmtSteps(Math.abs(h1 - h0))} steps in ${L} tile${L === 1 ? '' : 's'} — start or end it lower, or further off`; break; }
      for (const { tile, j } of tiles) {
        if (w.blocked[tile] || (w.flags[tile] & Flag.Poi)) { why = 'A building is in the way of the deck'; break; }
        if (w.deckAxis[tile]) { why = 'Another bridge is in the way'; break; }
        if (w.rail[tile] & (RailBit.Pad | RailBit.Loop | RailBit.Deck)) { why = 'The station is in the way'; break; }
        const under = Math.min(h0 + ((h1 - h0) * (j - 1)) / L, h0 + ((h1 - h0) * j) / L);
        const crossing = (w.rail[tile] & RailBit.Track) !== 0 || w.road[tile] !== RoadType.None;
        // over a road or railway, headroom; over water, the deck above it; over plain ground the deck may cut
        // into a slope a little (a ramp's foot on rising ground), so long as the middle of the tile stays under it
        const wet = w.water[tile] >= 0 ? w.water[tile] : -Infinity;
        // over deep water with `sea` asked for: high enough for a boat under it
        const sea = opt?.sea && wet > -Infinity && (w.biome[tile] === Biome.Ocean || waterDepth(w, tile) > 1) ? opt.sea : 0;
        const need = crossing ? maxCorner(w, tile) + UNDER_CLEARANCE : Math.max(tileMean(w, tile), wet + sea);
        const at = crossing || wet > -Infinity ? under : (h0 + ((h1 - h0) * (j - 0.5)) / L);
        if (at >= need - 1e-6) continue;
        // a platform over the node there, high enough: unless that is where it has to be low
        const m = Math.min(q - 1, Math.max(p + 1, p + j + (ext === 2 ? 1 : 0)));
        if (keys.has(m) || q - p < 2) { why = crossing ? 'Too low to pass over the road or railway here — raise it' : 'The ground rises through the deck here — raise it'; break; }
        split = m;
        T[m] = Math.max(top(m) + l[m], need);
        if (opt?.sea) { const d = deep(m); if (!Number.isNaN(d)) T[m] = Math.max(T[m], d + opt.sea); }
        break;
      }
    }
    if (why) return { bridges, why, raised: 0 };
    if (split < 0) {
      // every platform clear of its own ground, and of a road under it
      for (const k of list) {
        for (const t of nodeTiles(nodes[k], wide)) {
          if (w.blocked[t] || (w.flags[t] & Flag.Poi)) return { bridges, why: 'A building is in the way of the deck', raised: 0 };
          // a raised end may stand on the platform it carries on from, at that platform's height
          const chain = (k === 0 && a > 0) || (k === K && b > 0);
          if (w.deckAxis[t] && !(chain && w.deckAxis[t] === DECK_FLAT && Math.abs(w.deckLo[t] / STEP - T[k]) < 1e-6)) {
            return { bridges, why: chain ? 'Carry a raised road on from its end, at its height' : 'Another bridge is in the way', raised: 0 };
          }
          const crossing = (w.rail[t] & RailBit.Track) !== 0 || (w.road[t] !== RoadType.None && !w.deckAxis[t]);
          if (crossing && T[k] < maxCorner(w, t) + UNDER_CLEARANCE - 1e-6) {
            return { bridges, why: 'Too low to turn over the road or railway here — raise it', raised: 0 };
          }
        }
      }
      const out: Bridge[] = [...kept];
      for (const k of list) out.push({ from: k, to: k, h0: T[k] * STEP, h1: T[k] * STEP, raised: 2, level: true });
      let raised = 0;
      for (let n = 1; n < stops.length; n++) {
        const p = stops[n - 1], q = stops[n];
        if (q - p <= ext + 1) continue;
        out.push({ from: p, to: q, h0: (p === foot ? footH : T[p]) * STEP, h1: (q === foot ? footH : T[q]) * STEP, raised: 2 });
        raised++;
      }
      return { bridges: out.sort((x, y) => x.from - y.from || x.to - y.to), raised };
    }
    keys.add(split);
  }
  return { bridges, why: 'The ground is too broken to raise a road over here', raised: 0 };
}

const fmtSteps = (v: number) => String(Math.round(v * 2) / 2);

/**
 * What a deck of this many tiles costs the route search: a short one well over the road it saves, so a road
 * goes round a pond rather than over it; past LONG_DECK each further tile costs little more than a tile of
 * road, so a long bridge straight over the water beats a road twice its length round by a causeway (the
 * user, 28 Oct 2026: a 70-tile deck weighed 356 and lost to any way round shorter than that).
 */
const LONG_DECK = 14, LONG_TILE = 1.2;
const bridgeCost = (deckLen: number) => 6 + Math.min(deckLen, LONG_DECK) * 5 + Math.max(0, deckLen - LONG_DECK) * LONG_TILE;
/** The price world generation's own roads (findRoute) put on a deck: unchanged, so every county is generated as before. */
const genBridgeCost = (deckLen: number) => 6 + deckLen * 5;
/**
 * Past this many tiles a bridge's span is only worth looking for over water: the search for a longer deck
 * stops at the first dry node it can't land on. A 72-tile span over land checked at every length made
 * planning a road take a second (the user, 15 Oct 2026, raised the longest bridge to 72).
 */
const LAND_SPAN = 14;

/**
 * A flyover's deck is priced as a bridge's, at this share: crossing a busy line or a highway on the
 * level is slow and awkward, so a route that can fly over one is worth more than its tiles suggest.
 */
const FLYOVER_DISCOUNT = 0.45;

/** What boring a tunnel costs the search, per tile: dearer than a deck, and worth it to miss a mountain. */
const tunnelCost = (len: number) => 10 + len * 7;

/**
 * What crossing a road on the level costs a player's route, over and above the step itself: a big
 * junction on a highway is a real piece of engineering, so an overpass beside it starts to look
 * cheap. Generated town streets don't pay it — they are meant to meet each other.
 */
function crossCost(w: World, m: number, wide: Wide): number {
  let worst = 0;
  for (const t of nodeTiles(m, wide)) {
    const r = w.road[t];
    // an interstate is crossed over or under, never on the level: through its median at grade costs like a detour
    if (r === RoadType.Interstate) worst = Math.max(worst, 40);
    else if (r === RoadType.FourLane) worst = Math.max(worst, 14);
    else if (r === RoadType.TwoLane) worst = Math.max(worst, 5);
  }
  return worst;
}

/**
 * How many tiles ahead along d the first thing worth flying over is, or 0 for none within `reach`.
 * A flyover is for a railway or a road big enough to be a nuisance to cross; a town lane is not one,
 * which also keeps the search from trying to vault every street in a city. Allocates nothing.
 */
function crossingAhead(w: World, n: number, d: number, wide: Wide, reach: number): number {
  const step = DIRS[d][0] + DIRS[d][1] * N;
  const x = n % N, z = (n - x) / N;
  const side = wide ? (d % 2 === 0 ? N : 1) : 0;
  const worth = (t: number) => t >= 0 && t < N * N && ((w.rail[t] & RailBit.Track) !== 0 || w.road[t] === RoadType.TwoLane || w.road[t] === RoadType.FourLane || w.road[t] === RoadType.Interstate);
  for (let k = 1; k <= reach; k++) {
    const nx = x + DIRS[d][0] * k, nz = z + DIRS[d][1] * k;
    if (nx < 0 || nz < 0 || nx >= N || nz >= N) return 0;
    const t = n + step * k;
    if (worth(t) || (wide && worth(t - side)) || (wide === 'tri' && worth(t + side))) return k;
  }
  return 0;
}

/** Is the way ahead from node (x, z) along d a gap a bridge might be for? */
function gapAhead(w: World, n: number, d: number, wide: Wide, okNext: boolean, hNext: number, hHere: number): boolean {
  if (!okNext || (!wide && edgeMismatch(w, n, d) !== 0) || hNext < hHere - 1.5) return true;
  // a railway or a road ahead is worth offering to fly over rather than cross on the level
  const ahead = DIRS[d][0] + DIRS[d][1] * N;
  for (const t of nodeTiles(n + ahead, wide)) if ((w.rail[t] & RailBit.Track) || w.road[t]) return true;
  // A ford is passable, so the way ahead isn't blocked — but a river is still a gap, and its dry
  // bank is the only place a deck can leave from. Water ahead is worth offering a bridge over.
  const step = DIRS[d][0] + DIRS[d][1] * N;
  for (const t of nodeTiles(n + step, wide)) if (waterDepth(w, t) > 0) return true;
  return false;
}

/**
 * Does a deck from a to b run across the water under it rather than along it? A canal town's streets
 * bridge its canals square on (world/canals.ts): a deck whose tiles mostly have a dry tile beside them is
 * running down a canal between its quays, and is refused.
 */
function crossesWater(w: World, a: number, b: number, d: number, wide: Wide): boolean {
  const tiles = deckTiles(a, b, d, wide);
  const sx = DIRS[(d + 1) & 3][0], sz = DIRS[(d + 1) & 3][1];
  let beside = 0, wet = 0;
  for (const { tile } of tiles) {
    if (waterDepth(w, tile) <= 0) continue;
    wet++;
    const x = tile % N, z = (tile - x) / N;
    for (const s of [1, -1]) {
      const tx = x + sx * s, tz = z + sz * s;
      if (inB(tx, tz) && waterDepth(w, idx(tx, tz)) <= 0 && w.water[idx(tx, tz)] < 0) { beside++; break; }
    }
  }
  return wet > 0 && beside * 2 <= wet;
}

/** Binary min-heap on typed arrays; the search pushes hundreds of thousands of entries. */
class Heap {
  private k = new Float64Array(1 << 14);
  private v = new Int32Array(1 << 14);
  size = 0;
  push(key: number, val: number): void {
    if (this.size === this.k.length) {
      const k = new Float64Array(this.size * 2); k.set(this.k); this.k = k;
      const v = new Int32Array(this.size * 2); v.set(this.v); this.v = v;
    }
    const k = this.k, v = this.v;
    let i = this.size++;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (k[p] <= key) break;
      k[i] = k[p]; v[i] = v[p];
      i = p;
    }
    k[i] = key; v[i] = val;
  }
  topKey(): number { return this.k[0]; }
  pop(): number {
    const k = this.k, v = this.v;
    const top = v[0];
    const n = --this.size;
    if (n > 0) {
      const key = k[n], val = v[n];
      let i = 0;
      for (;;) {
        let c = 2 * i + 1;
        if (c >= n) break;
        if (c + 1 < n && k[c + 1] < k[c]) c++;
        if (k[c] >= key) break;
        k[i] = k[c]; v[i] = v[c];
        i = c;
      }
      k[i] = key; v[i] = val;
    }
    return top;
  }
}

/** A route: its nodes (bridge spans included, node by node) and the bridges within it. */
/** `raised`: with a lift asked for, how many straight stretches stood up off the ground (elevate). */
export interface Route { nodes: number[]; bridges: Bridge[]; raised?: number }

/**
 * Walk a search's prev chain back from `last`. `jump` says how many node steps a state's arrival
 * leapt (0 = an ordinary step); leaps get their in-between nodes filled back in and become bridges.
 */
function unwind(last: number, prev: Int32Array, jump: Uint8Array, nodeOf: (s: number) => number): Route {
  const rev: number[] = [];
  const spans: [number, number][] = [];
  for (let s = last; s >= 0; s = prev[s]) {
    const n = nodeOf(s);
    rev.push(n);
    const k = jump[s];
    if (k > 0) {
      const step = DIRS[s & 3][0] + DIRS[s & 3][1] * N;
      const landing = rev.length - 1;
      for (let i = 1; i < k; i++) rev.push(n - step * i);
      spans.push([landing, rev.length]);
    }
  }
  const nodes = rev.reverse();
  const L = nodes.length - 1;
  return { nodes, bridges: spans.map(([landing, abutment]) => ({ from: L - abutment, to: L - landing, h0: NaN, h1: NaN })) };
}

/**
 * Step costs for generated roads. `reuse` (< 1) scales steps onto tiles that already carry a road,
 * so crossing streets share their junction; `crowd` is added for running right beside another road.
 */
export interface RouteCost {
  climb: number; slope: number; turn: number; reuse: number; crowd: number;
  /**
   * The grade a road would rather not exceed, in steps a tile, and what each step over it costs. A
   * mountain road that has to climb further than that in a straight line winds instead: switchbacks
   * up a flank, a loop round a knoll.
   */
  grade?: number; gradePen?: number;
}

/** What a step from height a to height b costs a route beyond its climb, for being steeper than it likes. */
function overGrade(c: RouteCost, dh: number): number {
  if (!c.gradePen) return 0;
  const over = Math.abs(dh) - (c.grade ?? 0.5);
  return over > 0 ? over * c.gradePen : 0;
}

function onRoad(w: World, n: number, wide: Wide): boolean {
  for (const t of nodeTiles(n, wide)) if (w.road[t]) return true;
  return false;
}

function besideRoad(w: World, n: number, wide: Wide): boolean {
  for (const t of nodeTiles(n, wide)) {
    const x = t % N, z = (t - x) / N;
    for (let d = 0; d < 4; d++) {
      const nx = x + DIRS[d][0], nz = z + DIRS[d][1];
      if (nx >= 0 && nz >= 0 && nx < N && nz < N && w.road[nz * N + nx]) return true;
    }
  }
  return false;
}

/**
 * Cheapest route between two nodes inside the box [x0, z0, x1, z1): A* over (node, heading), so
 * turns can be priced. Used to lay town streets, port roads and roads between towns; with a
 * `span` it may bridge gaps up to that many tiles.
 */
/**
 * What a generated road of this type pays for each node of shallow water it runs through on the ground,
 * over and above the step: nothing for dirt and gravel, which ford it, and enough for a paved road that
 * it crosses square and short, where layRoad can raise it (raiseFords), rather than wading along a stream.
 */
export const wetCost = (t: RoadType): number => (fords(t) ? 0 : WET_STEP);
/** A paved road's extra per node of shallow water, and for a turn where its raised crossing must run straight. */
const WET_STEP = 2, WET_TURN = 12;

/** Does any tile of this node stand in water on the ground (not under a deck)? */
export function wetNode(w: World, n: number, wide: Wide): boolean {
  for (const t of nodeTiles(n, wide)) if (!w.deckAxis[t] && waterDepth(w, t) > 0) return true;
  return false;
}

/**
 * What a road that pays for water (`wet` > 0) pays for turning (from pd to d at node n, on to m) where a
 * raised crossing needs it straight: onto the water, in it, or on the ramp tile just off it. A crossing
 * runs abutment, ramp, water, ramp, abutment in one line (raiseFords).
 */
function wetTurn(w: World, n: number, m: number, d: number, pd: number, wide: Wide, wet: number): number {
  if (!wet || pd < 0 || d === pd) return 0;
  const back = n - (DIRS[pd][0] + DIRS[pd][1] * N);
  const behind = back >= 0 && back < N * N && wetNode(w, back, wide);
  return behind || wetNode(w, n, wide) || wetNode(w, m, wide) ? WET_TURN : 0;
}

/**
 * Is any tile of this node under a deck too low for a road to run beneath: a raised crossing's ramps,
 * or its deck a step over the ford? A generated road keeps out from under those rather than crossing
 * through them at grade.
 */
function underDeck(w: World, n: number, wide: Wide): boolean {
  for (const t of nodeTiles(n, wide)) {
    if (w.deckAxis[t] && Math.min(w.deckLo[t], w.deckHi[t]) - maxCorner(w, t) * STEP <= UNDER_CLEARANCE * STEP + 1e-6) return true;
  }
  return false;
}

export function findRoute(
  w: World, from: number, to: number, wide: boolean, box: [number, number, number, number], c: RouteCost, span = 0, wet = 0,
  across = false,
): Route | null {
  // The search only knows the decks already on the map, not the ones it is throwing itself, so a long route can
  // pass on the ground beneath its own bridge (a step under it, drawn up on the deck and cut off below) or bridge
  // over its own road. Where it does it searches again keeping clear of where it met itself (GEN 47).
  const route = searchRoute(w, from, to, wide, box, c, span, wet, across);
  if (!route || !ownDeckClash(w, route.nodes, route.bridges, wide).length) return route;
  // first keep its decks off the tiles where it met itself (it crosses there on the ground instead), then its
  // ground off them, then both, each a few times over as it meets itself somewhere else; then keep the ground off
  // all of its decks and its decks off all of its ground; then the same over the whole cell
  for (const mode of ['deck', 'decks', 'ground', 'both'] as const) {
    const avoid = { ground: new Set<number>(), deck: new Set<number>() };
    let r: Route | null = route;
    for (let tries = 0; r && tries < 6; tries++) {
      const clash = ownDeckClash(w, r.nodes, r.bridges, wide);
      if (!clash.length) return r;
      if (mode === 'decks') for (const t of routeTiles(r.nodes, r.bridges, wide).ground) avoid.deck.add(t);
      for (const t of clash) { if (mode !== 'ground') avoid.deck.add(t); if (mode === 'ground' || mode === 'both') avoid.ground.add(t); }
      r = searchRoute(w, from, to, wide, box, c, span, wet, across, avoid);
    }
    if (r && !ownDeckClash(w, r.nodes, r.bridges, wide).length) return r;
  }
  const { ground, deck } = routeTiles(route.nodes, route.bridges, wide);
  const broad = { ground: deck, deck: ground };
  for (const b of [box, [0, 0, N, N] as [number, number, number, number]]) {
    const again = searchRoute(w, from, to, wide, b, c, span, wet, across, broad);
    if (again && !ownDeckClash(w, again.nodes, again.bridges, wide).length) return again;
  }
  // no way that keeps clear of itself: better no road here than one cut off under its own bridge
  return null;
}

/** A route's tiles on the ground (every node outside its spans, abutments included) and under its decks. */
function routeTiles(nodes: number[], bridges: Bridge[], wide: Wide): { ground: Set<number>; deck: Set<number> } {
  const ground = new Set<number>(), deck = new Set<number>();
  for (const b of bridges) {
    if (b.level || b.to <= b.from) continue;
    const d = dirBetween(nodes[b.from], nodes[b.from + 1]);
    for (const { tile } of deckTiles(nodes[b.from], nodes[b.to], d, wide)) deck.add(tile);
  }
  for (let k = 0; k < nodes.length; k++) {
    if (bridges.some((b) => (b.from < k && k < b.to) || (b.level && b.from === k))) continue;
    for (const t of nodeTiles(nodes[k], wide)) ground.add(t);
  }
  return { ground, deck };
}

/**
 * Tiles where a route meets its own bridge badly: a ground node under one of its decks without the air a road
 * keeps under a deck (UNDER_CLEARANCE), or two of its decks on one tile. A route that passes well under its own
 * span (a switchback beneath its own viaduct) is fine, and is laid as two roads (layGenerated). Bridges not yet
 * given heights (a search's) are measured as bridgeBetween would build them.
 */
export function ownDeckClash(w: World, nodes: number[], bridges: Bridge[], wide: Wide): number[] {
  if (!bridges.length) return [];
  const deck = new Map<number, number>(), out: number[] = [];
  for (const b of bridges) {
    if (b.level || b.to <= b.from) continue;
    const d = dirBetween(nodes[b.from], nodes[b.from + 1]);
    const hts = Number.isFinite(b.h0) && Number.isFinite(b.h1) ? b : bridgeBetween(w, nodes[b.from], nodes[b.to], d, wide);
    for (const { tile, j, L } of deckTiles(nodes[b.from], nodes[b.to], d, wide)) {
      if (deck.has(tile)) out.push(tile);
      deck.set(tile, hts ? Math.min(deckHeightAt(hts, L, j - 1), deckHeightAt(hts, L, j)) : -Infinity);
    }
  }
  for (let k = 0; k < nodes.length; k++) {
    if (bridges.some((b) => (b.from < k && k < b.to) || (b.level && b.from === k))) continue;
    for (const t of nodeTiles(nodes[k], wide)) {
      const h = deck.get(t);
      if (h !== undefined && h - maxCorner(w, t) * STEP <= UNDER_CLEARANCE * STEP + 1e-6) out.push(t);
    }
  }
  return out;
}

/**
 * Lay a generated road, cut into two (or more) where it passes under its own deck: the pieces join end to end at
 * a node, and each draws its own decks, so the stretch beneath isn't drawn up on the span above it.
 */
export function layGenerated(w: World, type: RoadType, nodes: number[], town: number, bridges: Bridge[] = []): void {
  const wide = shapeOf(type);
  let start = 0;
  while (start < nodes.length - 1) {
    // grow the piece node by node, a span at a time, until it would run onto (or over) its own ground or deck
    const deck = new Set<number>(), ground = new Set<number>();
    let end = start, cut = -1;
    const addGround = (k: number) => { for (const t of nodeTiles(nodes[k], wide)) ground.add(t); };
    addGround(start);
    while (end < nodes.length - 1) {
      const br = bridges.find((b) => b.from === end && !b.level && b.to > b.from);
      if (br) {
        const d = dirBetween(nodes[br.from], nodes[br.from + 1]);
        const tiles = deckTiles(nodes[br.from], nodes[br.to], d, wide).map(({ tile }) => tile);
        if (tiles.some((t) => ground.has(t) || deck.has(t)) || nodeTiles(nodes[br.to], wide).some((t) => deck.has(t))) { cut = end; break; }
        for (const t of tiles) deck.add(t);
        end = br.to;
        addGround(end);
      } else {
        if (nodeTiles(nodes[end + 1], wide).some((t) => deck.has(t))) { cut = end; break; }
        end++;
        addGround(end);
      }
    }
    if (cut === start) cut = -1; // a piece can't be empty: lay what is left whole
    const stop = cut > start ? cut : nodes.length - 1;
    const piece = nodes.slice(start, stop + 1);
    const own = bridges.filter((b) => b.from >= start && b.to <= stop).map((b) => ({ ...b, from: b.from - start, to: b.to - start }));
    if (piece.length >= 2) layRoad(w, type, piece, town, own);
    start = stop;
    if (stop === nodes.length - 1) break;
  }
}

function searchRoute(
  w: World, from: number, to: number, wide: boolean, box: [number, number, number, number], c: RouteCost, span: number, wet: number,
  across: boolean, avoid?: { ground: ReadonlySet<number>; deck: ReadonlySet<number> },
): Route | null {
  const lo = wide ? 1 : 0;
  const x0 = Math.max(lo, box[0]), z0 = Math.max(lo, box[1]), x1 = Math.min(N, box[2]), z1 = Math.min(N, box[3]);
  const W = x1 - x0, H = z1 - z0;
  if (W <= 0 || H <= 0) return null;
  const fx = from % N, fz = (from - fx) / N, tx = to % N, tz = (to - tx) / N;
  const inside = (x: number, z: number) => x >= x0 && z >= z0 && x < x1 && z < z1;
  if (!inside(fx, fz) || !inside(tx, tz)) return null;
  const okCache = new Int8Array(W * H).fill(-1);
  const ok = (x: number, z: number) => {
    const li = (z - z0) * W + x - x0;
    const n = z * N + x;
    if (okCache[li] < 0) {
      okCache[li] = nodeProblem(w, n, wide) || underDeck(w, n, wide) || (n !== from && n !== to && fenced(w, n, wide))
        || (avoid && nodeTiles(n, wide).some((t) => avoid.ground.has(t))) ? 0 : 1;
    }
    return okCache[li] === 1;
  };
  if (!ok(fx, fz) || !ok(tx, tz)) return null;

  const dist = new Float64Array(W * H * 4).fill(Infinity);
  const prev = new Int32Array(W * H * 4).fill(-1);
  const jump = new Uint8Array(W * H * 4);
  const heap = new Heap();
  const hk = Math.min(1, c.reuse);
  const s0 = ((fz - z0) * W + fx - x0) * 4;
  const h0 = hk * (Math.abs(fx - tx) + Math.abs(fz - tz));
  for (let d = 0; d < 4; d++) { dist[s0 + d] = 0; heap.push(h0, s0 + d); }
  const nodeOf = (s: number) => { const l = s >> 2; return (z0 + Math.floor(l / W)) * N + x0 + (l % W); };
  while (heap.size) {
    const key = heap.topKey();
    const s = heap.pop();
    const li = s >> 2, pd = s & 3;
    const x = x0 + (li % W), z = z0 + Math.floor(li / W);
    const g = dist[s];
    if (key > g + hk * (Math.abs(x - tx) + Math.abs(z - tz)) + 1e-9) continue;
    if (x === tx && z === tz) return unwind(s, prev, jump, nodeOf);
    const n = z * N + x, hn = nodeHeight(w, n, wide);
    const relax = (nx: number, nz: number, d: number, step: number, k: number) => {
      const ns = ((nz - z0) * W + nx - x0) * 4 + d;
      const ng = g + step;
      if (ng < dist[ns]) {
        dist[ns] = ng;
        prev[ns] = s;
        jump[ns] = k;
        heap.push(ng + hk * (Math.abs(nx - tx) + Math.abs(nz - tz)), ns);
      }
    };
    for (let d = 0; d < 4; d++) {
      // never straight back the way it came: after a bridge's leap that would lay a second deck back over the
      // first and bring the road down underneath its own span (tiny-fleet-online 0,-1, GEN 47)
      if (d === (pd ^ 2) && prev[s] >= 0) continue;
      const nx = x + DIRS[d][0], nz = z + DIRS[d][1];
      if (!inside(nx, nz)) continue;
      const m = nz * N + nx;
      const okNext = ok(nx, nz);
      const railCost = okNext ? railStep(w, n, m, d, wide) : 0;
      if (okNext && railCost !== Infinity && (wide || edgeMismatch(w, n, d) === 0)) {
        const dh = nodeHeight(w, m, wide) - hn;
        let step = railCost + 1 + c.climb * Math.abs(dh) + overGrade(c, dh) + c.slope * nodeSteep(w, m, wide) + (d !== pd ? c.turn : 0);
        if (onRoad(w, m, wide)) step *= c.reuse;
        else if (c.crowd && besideRoad(w, m, wide)) step += c.crowd;
        if (wet) step += (wetNode(w, m, wide) ? wet : 0) + wetTurn(w, n, m, d, pd, wide, wet);
        relax(nx, nz, d, step, 0);
      }
      if (span <= 0 || !gapAhead(w, n, d, wide, okNext, nodeHeight(w, m, wide), hn)) continue;
      for (let k = wide ? 3 : 2; k <= span + (wide ? 2 : 1); k++) {
        const bx = x + DIRS[d][0] * k, bz = z + DIRS[d][1] * k;
        if (!inside(bx, bz)) break;
        if (!ok(bx, bz)) continue;
        const b = bz * N + bx;
        if (!bridgeBetween(w, n, b, d, wide)) continue;
        if (across && !crossesWater(w, n, b, d, wide)) break;
        if (avoid && deckTiles(n, b, d, wide).some(({ tile }) => avoid.deck.has(tile))) break;
        relax(bx, bz, d, genBridgeCost(k - 1 - (wide ? 1 : 0)) + c.climb * Math.abs(nodeHeight(w, b, wide) - hn) + (d !== pd ? c.turn : 0), k);
        break;
      }
    }
  }
  return null;
}

/**
 * A generated road pulled straight. The search's turns are cheap beside its climbs, so across gently
 * uneven ground it zigzags a staircase to save a fraction of a step; this walks the route and swaps
 * any stretch for a single L (or a straight run) wherever that costs no more by the same step costs,
 * with each turn weighed as a whole tile. Bridges are left exactly where they are, and a new stretch
 * never runs back over the route itself.
 */
export function straightenRoute(w: World, route: Route, c: RouteCost, reach = 48, wet = 0): Route {
  let nodes = route.nodes.slice();
  let bridges = route.bridges.map((b) => ({ ...b }));
  if (nodes.length < 4) return route;
  const TURN = Math.max(1, c.turn);
  const first = nodes[0], last = nodes[nodes.length - 1];
  const step = (a: number, b: number, pd: number): number => {
    const d = dirBetween(a, b);
    if (nodeProblem(w, b, false) || underDeck(w, b, false) || edgeMismatch(w, a, d) !== 0) return Infinity;
    if (b !== first && b !== last && fenced(w, b, false)) return Infinity;
    const rail = railStep(w, a, b, d, false);
    if (rail === Infinity) return Infinity;
    const dh = nodeHeight(w, b, false) - nodeHeight(w, a, false);
    let cost = rail + 1 + c.climb * Math.abs(dh) + overGrade(c, dh) + c.slope * nodeSteep(w, b, false) + (pd >= 0 && d !== pd ? TURN : 0);
    if (onRoad(w, b, false)) cost *= c.reuse;
    else if (c.crowd && besideRoad(w, b, false)) cost += c.crowd;
    if (wet) cost += (wetNode(w, b, false) ? wet : 0) + wetTurn(w, a, b, d, pd, false, wet);
    return cost;
  };
  /** Cost of walking a node list from index 0, arriving with direction pd, and leaving its last node along out (-1 for none). */
  const walk = (list: number[], pd: number, out: number): number => {
    let sum = 0, d = pd;
    for (let k = 1; k < list.length; k++) {
      if (Math.abs(list[k] - list[k - 1]) !== 1 && Math.abs(list[k] - list[k - 1]) !== N) return Infinity;
      sum += step(list[k - 1], list[k], d);
      if (sum === Infinity) return sum;
      d = dirBetween(list[k - 1], list[k]);
    }
    return sum + (out >= 0 && d !== out && list.length > 1 ? TURN : 0);
  };
  /** An L from a to b: along x first or along z first. */
  const ell = (a: number, b: number, xFirst: boolean): number[] => {
    const ax = a % N, az = (a - ax) / N, bx = b % N, bz = (b - bx) / N;
    const out = [a];
    let x = ax, z = az;
    const goX = () => { while (x !== bx) { x += Math.sign(bx - x); out.push(z * N + x); } };
    const goZ = () => { while (z !== bz) { z += Math.sign(bz - z); out.push(z * N + x); } };
    if (xFirst) { goX(); goZ(); } else { goZ(); goX(); }
    return out;
  };
  const inBridge = (k: number) => bridges.some((br) => k > br.from && k < br.to);
  for (let i = 0; i < nodes.length - 3; i++) {
    if (inBridge(i)) continue;
    for (let j = Math.min(nodes.length - 1, i + reach); j >= i + 3; j--) {
      // the stretch may not hold any part of a bridge, abutments included
      if (bridges.some((br) => br.to > i && br.from < j)) continue;
      const a = nodes[i], b = nodes[j];
      const man = Math.abs((a % N) - (b % N)) + Math.abs(Math.floor(a / N) - Math.floor(b / N));
      if (man > j - i) continue;
      const pd = i > 0 ? dirBetween(nodes[i - 1], a) : -1;
      const out = j < nodes.length - 1 ? dirBetween(b, nodes[j + 1]) : -1;
      const old = walk(nodes.slice(i, j + 1), pd, out);
      const kept = new Set([...nodes.slice(0, i), ...nodes.slice(j + 1)]);
      let best: number[] | null = null, bestCost = old - 1e-6;
      for (const xFirst of [true, false]) {
        const cand = ell(a, b, xFirst);
        if (cand.slice(1, -1).some((n) => kept.has(n))) continue;
        const cost = walk(cand, pd, out);
        if (cost < bestCost) { bestCost = cost; best = cand; }
      }
      if (!best) continue;
      const shift = best.length - (j - i + 1);
      nodes = [...nodes.slice(0, i), ...best, ...nodes.slice(j + 1)];
      bridges = bridges.map((br) => (br.from >= j ? { ...br, from: br.from + shift, to: br.to + shift } : br));
      break;
    }
  }
  return { nodes, bridges };
}

// ---------------------------------------------------------------------------------------------
// the road builder's search

/**
 * Step costs on top of 1 per tile. Flattest pays heavily for every step of height gained or
 * lost, so it will walk a long way round a hill. Shortest only uses them to break ties between
 * equally short routes (they can never add up to the 2 tiles that separate two grid routes).
 */
const WEIGHTS: Record<RouteMode, { climb: number; slope: number; turn: number }> = {
  flat: { climb: 8, slope: 1.5, turn: 0.35 },
  short: { climb: 0.002, slope: 0.001, turn: 0.004 },
  // climbing is dear and turning is nearly free, so the road zigzags up the slope instead of over it
  hairpin: { climb: 26, slope: 0.6, turn: 0.02 },
};

/** What each corner costs an interstate's route on top of its mode's own turn: tiles of road it would rather lay than turn. */
const INTERSTATE_TURN = 8;

/** Where a plan may begin other than its start: a node already reached at some cost, heading along `d`. */
interface RouteSeed { node: number; d: number; cost: number }

export interface RoutePlan {
  w: World;
  start: number;
  wide: Wide;
  mode: RouteMode;
  ok: Uint8Array;       // node can carry this road
  dist: Float64Array;   // per (node, arrival direction)
  prev: Int32Array;
  jump: Uint8Array;     // node steps the arrival leapt over on a bridge (0 = ordinary step)
  /** A narrow road may step over a step in the ground, to be cut down it before it is laid (world/roadGrade.ts). */
  cut?: boolean;
  /** Planned for a railway track (game/railBuilder.ts): roads are crossed, never run along; lines never crossed on the level. */
  rail?: boolean;
  /** A plan carried over a border: the strait bridges it was seeded with, by the far shore node each lands on. */
  strait?: Map<number, StraitDeck>;
  /** Planned `afloat`: the deep-water nodes it lets a raised track stand over (1), which only a deck may carry it across. */
  wet?: Uint8Array;
}

/**
 * Deep water a raised track may stand out over (the user, 3 Nov 2026: rails begun over the ocean): open sea or water
 * too deep to ford, with nothing built in it and no railway already there.
 */
export function seaNode(w: World, n: number): boolean {
  if (w.blocked[n] || (w.flags[n] & Flag.Poi) || (w.rail[n] & (RailBit.Track | RailBit.Pad | RailBit.Loop | RailBit.Deck)) || w.deckAxis[n]) return false;
  return w.biome[n] === Biome.Ocean || waterDepth(w, n) > 1;
}
/** What a tile of deck out over the sea costs the search, over a tile of ground: dear enough that a route only goes out to sea when it must. */
const SEA_STEP = 4;

/**
 * A bridge over the strait between two counties (the user, 15 Oct 2026): a deck can't straddle the border,
 * so it is built in two halves, each in its own county and saved with it, meeting at the line. The near half
 * climbs from its shore node `n` and runs level out to a platform on the border tile `a`; the far half leaves
 * the platform on the tile across the line `b` at the same height and comes down to its shore node `m`. Both
 * stand BOAT_RISE over the sea at the line, so boats pass under. Any road: a four-lane's or an interstate's
 * nodes are blocks of tiles, every one of them checked under the deck (the user, 28 Oct 2026).
 */
export interface StraitDeck { n: number; a: number; b: number; m: number; d: number; h: number; near: Bridge; far: Bridge }

/** The longest strait bridge, shore to shore, in tiles of deck (the user, 15 Oct 2026). */
export const STRAIT_SPAN = 72;

/** Can a strait bridge's deck stand over tile t at height `deck` (steps)? A step of air over water, and never into the ground. */
function straitTile(w: World, t: number, deck: number): boolean {
  if (w.blocked[t] || (w.flags[t] & Flag.Poi) || w.deckAxis[t] || w.road[t] || (w.rail[t] & (RailBit.Pad | RailBit.Loop | RailBit.Deck | RailBit.Track))) return false;
  if (w.water[t] >= 0) return deck >= w.water[t] + 1;
  // over dry ground the ramp may run on it where it leaves the shore, as a raised road's does: never into it
  return deck >= maxCorner(w, t) - 1e-6;
}

/** One half of a strait bridge, from a shore node out along d to the platform at the line: its deck, or null. */
function straitHalf(w: World, shore: number, edge: number, d: number, h: number, eShore: number, wide: Wide): Bridge | null {
  const tiles = deckTiles(shore, edge, d, wide);
  if (!tiles.length) return null;
  const L = tiles[0].L;
  const climb = Math.max(0, h - eShore);
  const ramp = Math.max(1, Math.ceil(climb / HUMP_GRADE - 1e-9));
  if (ramp > L) return null;
  const br: Bridge = { from: 0, to: 0, h0: eShore * STEP, h1: h * STEP, peak: h * STEP, ramp, raised: 1 };
  for (const { tile, j } of tiles) {
    // the deck's lowest point over this tile: where it rises off the shore
    const lo = Math.min(deckHeightAt(br, L, j - 1), deckHeightAt(br, L, j)) / STEP;
    if (!straitTile(w, tile, lo)) return null;
  }
  // and the platform at the line, the whole of its node
  for (const t of nodeTiles(edge, wide)) if (!straitTile(w, t, h)) return null;
  return br;
}

/**
 * The strait bridges a plan could carry over side d into `nb`: for each line across the border, the near
 * shore node the plan reaches, a deck out to the line over water, and the far shore node it lands on, no
 * more than `span` tiles of deck in all. The cheapest landing on each far node, with what it cost.
 */
function straitDecks(plan: RoutePlan, nb: World, d: number, span: number): { deck: StraitDeck; cost: number }[] {
  const w = plan.w, wide = plan.wide;
  if (span < 2) return [];
  const turn = WEIGHTS[plan.mode].turn;
  const back = -(DIRS[d][0] + DIRS[d][1] * N), on = DIRS[d][0] + DIRS[d][1] * N, far = (d + 2) & 3;
  const inside = (n: number) => n >= 0 && n < N * N;
  // a node's block all in the water, or all on dry ground
  const wet = (u: World, n: number) => inside(n) && nodeTiles(n, wide).every((t) => inside(t) && u.water[t] >= 0);
  const dry = (u: World, n: number) => inside(n) && nodeTiles(n, wide).every((t) => inside(t) && u.water[t] < 0);
  const sea = (u: World, n: number) => Math.max(...nodeTiles(n, wide).map((t) => u.water[t]));
  // the highest point of a node's edge facing the water: a four-lane's or an interstate's shore needn't be level
  const top = (u: World, n: number, side: number) => Math.max(...sideTiles(n, side, wide).map((t) => (u.corners[t * 4 + EDGE_MINE[side][0]] + u.corners[t * 4 + EDGE_MINE[side][1]]) / 2));
  const best = new Map<number, { deck: StraitDeck; cost: number }>();
  for (const { a, b } of borderPairs(wide, d)) {
    // only where the line itself is open water on both sides: on land the road crosses on the ground
    if (!wet(w, a) || !wet(nb, b)) continue;
    // the first dry ground each side of the line: the strait's own width
    let kN0 = 0, kF0 = 0;
    for (let k = 1; k < span; k++) if (dry(w, a + back * k)) { kN0 = k; break; }
    for (let k = 1; k < span; k++) if (dry(nb, b + on * k)) { kF0 = k; break; }
    if (!kN0 || !kF0 || kN0 + kF0 > span) continue;
    // each half starts far enough inland for its ramp to climb to the deck before the line: the first node with
    // a level edge to meet it that the plan reaches (the near side) or a road could run on from (the far side), no
    // more than `span` in all. Ground higher than the deck there asks for a higher deck (a number back)
    const nearAt = (h: number): { n: number; k: number; reach: number; half: Bridge } | number | null => {
      let need = 0;
      for (let k = kN0; k + kF0 <= span; k++) {
        const c = a + back * k;
        if (!inside(c) || plan.ok[c] !== 1 || !dry(w, c)) continue;
        const e = edgeMid(w, c, d, wide);
        if (!Number.isFinite(e)) continue;
        if (e > h) { need = Math.max(need, e); continue; }
        // reached heading for the line or along the shore, never from the sea side: the deck runs on from
        // the road's end, not back over the road itself
        let r = Infinity;
        for (let q = 0; q < 4; q++) if (q !== far) r = Math.min(r, plan.dist[c * 4 + q] + (q === d ? 0 : turn));
        if (!Number.isFinite(r)) continue;
        // the first start the whole half stands from: its ramp up off the ground, and a step clear of the sea
        const half = straitHalf(w, c, a, d, h, e, wide);
        if (half) return { n: c, k, reach: r, half };
      }
      return need > h ? need : null;
    };
    const farAt = (h: number, kN: number): { m: number; k: number; half: Bridge } | number | null => {
      let need = 0;
      for (let k = kF0; kN + k <= span; k++) {
        const c = b + on * k;
        if (!inside(c) || !dry(nb, c) || nodeProblem(nb, c, wide)) continue;
        const e = edgeMid(nb, c, far, wide);
        if (!Number.isFinite(e)) continue;
        if (e > h) { need = Math.max(need, e); continue; }
        // the far half is laid from its shore out to the line too, then turned to run from the line
        const half = straitHalf(nb, c, b, far, h, e, wide);
        if (half) return { m: c, k, half };
      }
      return need > h ? need : null;
    };
    // the deck stands BOAT_RISE over the sea at the line, and never below either shore it leaves from; raised
    // to meet a shore higher than that (the user, 28 Oct 2026: bridges between counties should be easy to build)
    let h = Math.ceil(Math.max(Math.max(sea(w, a), sea(nb, b)) + BOAT_RISE, top(w, a + back * kN0, d), top(nb, b + on * kF0, far)));
    if (!Number.isFinite(h)) continue;
    let near: { n: number; k: number; reach: number; half: Bridge } | null = null, land: { m: number; k: number; half: Bridge } | null = null;
    for (let tries = 0; tries < 3; tries++) {
      const nr = nearAt(h);
      if (nr === null) break;
      if (typeof nr === 'number') { h = Math.ceil(nr); continue; }
      const fr = farAt(h, nr.k);
      if (fr === null) break;
      if (typeof fr === 'number') { h = Math.ceil(fr); continue; }
      near = nr; land = fr;
      break;
    }
    if (!near || !land) continue;
    const o = land.half;
    const farHalf: Bridge = { from: 0, to: 0, h0: o.h1, h1: o.h0, peak: o.peak, ramp: o.ramp, raised: 1 };
    const cost = near.reach + bridgeCost(near.k + land.k);
    const have = best.get(land.m);
    if (!have || cost < have.cost) best.set(land.m, { deck: { n: near.n, a, b, m: land.m, d, h: h * STEP, near: near.half, far: farHalf }, cost });
  }
  return [...best.values()];
}

/**
 * Cheapest route from `start` to every node at once: Dijkstra over (node, arrival direction)
 * so turns can be priced. Built once when the start is picked, so hovering anywhere afterwards
 * reads its route straight out of `prev`. With a `span`, gaps up to that wide may be bridged —
 * at a price that only pays off when the detour is long or there is no other way.
 */
/**
 * What the rails' planner (game/railBuilder.ts) pays over a road's: a road tile is crossed, never run along, and a
 * line already there is not crossed on the level at all if there is any other way (world/railRoute.ts refuses it).
 */
const RAIL_ON_ROAD = 40, RAIL_ON_RAIL = 400;

export function planRoutes(w: World, start: number, wide: Wide, mode: RouteMode, span = 0, seeds?: RouteSeed[], flyovers = false, tunnels = false, cut = false, rail = false, afloat = false): RoutePlan {
  // a bore may run further than a deck: it is held up by the hill it is in
  const ext = blockExtra(wide);
  const tunnelTop = Math.round(span * 1.6) + 1 + ext;
  const NN = N * N;
  const [lo, hi] = nodeRim(wide);
  const ok = new Uint8Array(NN);
  const h = new Float32Array(NN);
  const steep = new Uint8Array(NN);
  // `afloat` (a raised track begun out over the sea, game/railBuilder.ts): deep water is somewhere it may be, on deck
  const wet = afloat && !wide ? new Uint8Array(NN) : null;
  for (let z = lo; z <= hi; z++) {
    for (let x = lo; x <= hi; x++) {
      const n = z * N + x;
      h[n] = nodeHeight(w, n, wide);
      if (nodeProblem(w, n, wide)) {
        if (wet && seaNode(w, n)) { ok[n] = 1; wet[n] = 1; }
        continue;
      }
      ok[n] = 1;
      steep[n] = nodeSteep(w, n, wide);
    }
  }
  const dist = new Float64Array(NN * 4).fill(Infinity);
  const prev = new Int32Array(NN * 4).fill(-1);
  const jump = new Uint8Array(NN * 4);
  const plan: RoutePlan = { w, start, wide, mode, ok, dist, prev, jump, ...(cut && !wide ? { cut: true } : {}), ...(rail ? { rail: true } : {}), ...(wet ? { wet } : {}) };
  // an interstate turns as seldom as it can: long straights, and room either side of each corner for a wide sweep
  const wt = wide === 'tri' ? { ...WEIGHTS[mode], turn: WEIGHTS[mode].turn + INTERSTATE_TURN } : WEIGHTS[mode];
  const heap = new Heap();
  if (seeds) {
    // a plan carried on from another cell: every node its road could cross the border onto, each
    // already costing what it took to get there, so one search serves every crossing at once
    for (const sd of seeds) {
      if (!ok[sd.node]) continue;
      const k = sd.node * 4 + sd.d;
      if (sd.cost < dist[k]) { dist[k] = sd.cost; heap.push(sd.cost, k); }
      if (plan.start < 0 || sd.cost < dist[plan.start * 4 + sd.d]) plan.start = sd.node;
    }
    if (!heap.size) return plan;
  } else {
    if (!ok[start]) return plan;
    for (let d = 0; d < 4; d++) { dist[start * 4 + d] = 0; heap.push(0, start * 4 + d); }
  }
  while (heap.size) {
    const key = heap.topKey();
    const s = heap.pop();
    if (key > dist[s]) continue;
    const n = s >> 2, pd = s & 3;
    const x = n % N, z = (n - x) / N;
    const relax = (m: number, d: number, nd: number, k: number) => {
      const ns = m * 4 + d;
      if (nd < dist[ns]) {
        dist[ns] = nd;
        prev[ns] = s;
        jump[ns] = k;
        heap.push(nd, ns);
      }
    };
    for (let d = 0; d < 4; d++) {
      // never straight back the way it came (a deck laid back over the one it just crossed): see findRoute
      if (d === (pd ^ 2) && prev[s] >= 0) continue;
      const nx = x + DIRS[d][0], nz = z + DIRS[d][1];
      if (nx < lo || nz < lo || nx > hi || nz > hi) continue;
      const m = nz * N + nx;
      // out over the sea on deck: no ground to climb or step down, a deck's price a tile
      if (wet && ok[m] && (wet[m] || wet[n])) {
        const rc = railStep(w, n, m, d, wide);
        if (rc !== Infinity) relax(m, d, key + rc + 1 + SEA_STEP + (d !== pd ? wt.turn : 0), 0);
        continue;
      }
      // a wide node's own block check already covers the seam with its neighbour
      const railCost = ok[m] ? railStep(w, n, m, d, wide) : 0;
      // a step in the ground: the builder may cut a narrow road down it (world/roadGrade.ts), at a price
      const mm = ok[m] && !wide ? edgeMismatch(w, n, d) : 0;
      if (ok[m] && railCost !== Infinity && (wide || mm === 0 || (plan.cut && mm <= CUT_MAX))) {
        const railExtra = rail ? (w.road[m] ? RAIL_ON_ROAD : 0) + (w.rail[m] & RailBit.Track ? RAIL_ON_RAIL : 0) : 0;
        relax(m, d, key + railCost + crossCost(w, m, wide) + 1 + wt.climb * Math.abs(h[m] - h[n]) + wt.slope * steep[m] + (d !== pd ? wt.turn : 0) + mm * CUT_STEP + railExtra, 0);
      }

      if (span <= 0) continue;
      const top = span + 1 + ext;
      if (gapAhead(w, n, d, wide, ok[m] === 1, h[m], h[n])) {
        for (let k = 2 + ext; k <= top; k++) {
          const bx = x + DIRS[d][0] * k, bz = z + DIRS[d][1] * k;
          if (bx < lo || bz < lo || bx > hi || bz > hi) break;
          const b = bz * N + bx;
          if (!ok[b]) continue;
          if (!bridgeBetween(w, n, b, d, wide)) {
            // a long span is for water: past a land span's reach, ground a deck can't stand on ends the search
            if (k > LAND_SPAN + ext) break;
            continue;
          }
          relax(b, d, key + bridgeCost(k - 1 - ext) + wt.climb * Math.abs(h[b] - h[n]) + (d !== pd ? wt.turn : 0), k);
          break;
        }
      }
      // A flyover over a railway or a highway, when the builder has asked for big bridges. The crest
      // wants to sit over what it crosses, so only the few spans that put it there are worth trying.
      const at = flyovers ? crossingAhead(w, n, d, wide, Math.floor(top / 2)) : 0;
      if (at) {
        for (let k = Math.max(2 + ext, at * 2 - 1); k <= Math.min(top, at * 2 + 2); k++) {
          const bx = x + DIRS[d][0] * k, bz = z + DIRS[d][1] * k;
          if (bx < lo || bz < lo || bx > hi || bz > hi) break;
          const b = bz * N + bx;
          if (!ok[b] || !flyoverBetween(w, n, b, d, wide)) continue;
          relax(b, d, key + bridgeCost(k - 1 - ext) * FLYOVER_DISCOUNT + (d !== pd ? wt.turn : 0), k);
          break;
        }
      }
      // A tunnel, when the ground ahead climbs: bore through the hill rather than wind over it. The
      // bore itself only stands where there is rock over the roof, so flat ground never offers one.
      if (!tunnels || (ok[m] === 1 && h[m] < h[n] + 0.75)) continue;
      for (let k = 3 + ext; k <= tunnelTop; k++) {
        const bx = x + DIRS[d][0] * k, bz = z + DIRS[d][1] * k;
        if (bx < lo || bz < lo || bx > hi || bz > hi) break;
        const b = bz * N + bx;
        if (!ok[b] || !tunnelBetween(w, n, b, d, wide)) continue;
        relax(b, d, key + tunnelCost(k - 1 - ext) + wt.climb * Math.abs(h[b] - h[n]) + (d !== pd ? wt.turn : 0), k);
        break;
      }
    }
  }
  return plan;
}

/** The planned route to `target` with its bridges (heights filled in), or null when nothing reaches it. */
export function routeWithBridges(plan: RoutePlan, target: number, type: RoadType, opts?: { boats?: boolean; lift?: number; notArriving?: number }): Route | null {
  if (target < 0 || plan.start < 0 || !plan.ok[target] || !plan.ok[plan.start]) return null;
  let best = -1, bestD = Infinity;
  for (let d = 0; d < 4; d++) {
    // a strait bridge's shore is reached heading for the line or along the shore (StraitDeck)
    if (d === opts?.notArriving) continue;
    const v = plan.dist[target * 4 + d];
    if (v < bestD) { bestD = v; best = target * 4 + d; }
  }
  if (best < 0) return null;
  const route = unwind(best, plan.prev, plan.jump, (s) => s >> 2);
  route.bridges = resolveBridges(plan.w, type, route.nodes, route.bridges);
  // the player's own: spans over broad water raised for boats, and the whole road lifted with + and −
  if (opts?.boats) route.bridges = raiseSpans(plan.w, type, route.nodes, route.bridges);
  if (opts?.lift) { const e = elevate(plan.w, type, route.nodes, route.bridges, opts.lift); route.bridges = e.bridges; route.raised = e.raised; }
  return route;
}

/** Nodes from the plan's start to `target` inclusive, or null when nothing reaches it. */
export function routeTo(plan: RoutePlan, target: number): number[] | null {
  return routeWithBridges(plan, target, plan.wide === 'tri' ? RoadType.Interstate : plan.wide ? RoadType.FourLane : RoadType.TwoLane)?.nodes ?? null;
}

// ---------------------------------------------------------------------------------------------
// roads across a cell border

/**
 * Where a road on side d of a cell lands on the far side: for each node that could carry it up to
 * the border, the node across the line and how many node steps the crossing takes. A narrow road
 * steps tile to tile; a four-lane road's nodes are lattice points, and the lattice point on the line
 * itself belongs to neither cell, so it steps two and its blocks meet edge to edge.
 */
function borderPairs(wide: Wide, d: number): { a: number; b: number; steps: number }[] {
  const out: { a: number; b: number; steps: number }[] = [];
  // an interstate's block is a tile either side of its node: its last node stands a tile in from the line
  const [lo, hi] = nodeRim(wide);
  const near = hi, far = lo;
  for (let k = lo; k <= hi; k++) {
    const [ax, az, bx, bz] = d === 0 ? [near, k, far, k] : d === 2 ? [far, k, near, k] : d === 1 ? [k, near, k, far] : [k, far, k, near];
    out.push({ a: az * N + ax, b: bz * N + bx, steps: 1 + blockExtra(wide) });
  }
  return out;
}

/** Can a road run straight on from node a of `w` across side d onto the neighbour's node? */
export function crossesCleanly(w: World, a: number, d: number, wide: Wide): boolean {
  // the tiles of a's block that face the border, and the neighbour's that face them back
  const faces = sideTiles(a, d, wide);
  for (const t of faces) if (edgeMismatch(w, t, d) !== 0 || w.deckAxis[t]) return false;
  return true;
}

/**
 * Carry a plan over side d into the neighbouring cell `nb`: one search there, seeded with every
 * node the first plan reaches on its border at what it cost to get there. The route to anywhere in
 * the neighbour then reads straight out of it, and the node it crossed onto names the near half.
 */
export function planAcross(plan: RoutePlan, nb: World, d: number, span: number, flyovers = false, tunnels = false): RoutePlan {
  const cut = !!plan.cut;
  // and over the strait, where the border is open water, on a bridge built in two halves: for a road or a
  // railway any time, up to STRAIT_SPAN whatever its own span (the user, 28 Oct 2026: across to the next county
  // should be easy; 2 Nov 2026: and for track too)
  const strait = straitDecks(plan, nb, d, STRAIT_SPAN);
  const turn = WEIGHTS[plan.mode].turn;
  const seeds: RouteSeed[] = [];
  for (const { a, b, steps } of borderPairs(plan.wide, d)) {
    if (!plan.ok[a] || !crossesCleanly(plan.w, a, d, plan.wide)) continue;
    let best = plan.dist[a * 4 + d];
    for (let k = 0; k < 4; k++) best = Math.min(best, plan.dist[a * 4 + k] + turn);
    if (!Number.isFinite(best)) continue;
    seeds.push({ node: b, d, cost: best + steps });
  }
  for (const { deck, cost } of strait) seeds.push({ node: deck.m, d, cost });
  const far = planRoutes(nb, -1, plan.wide, plan.mode, span, seeds, flyovers, tunnels, cut, !!plan.rail);

  if (strait.length) far.strait = new Map(strait.map(({ deck }) => [deck.m, deck]));
  return far;
}

/** The node on the near side that a crossing onto `b` (on side d of the near cell) came from. */
export function acrossFrom(b: number, d: number, wide: Wide): number {
  const bx = b % N, bz = (b - bx) / N;
  const [far, near] = nodeRim(wide);
  const flip = (v: number) => (v === far ? near : far);
  return d % 2 === 0 ? bz * N + flip(bx) : flip(bz) * N + bx;
}

interface RouteStats { tiles: number; climb: number; drop: number; sloped: number; bridges: number; deck: number }

/** Length, total climb and drop (in height steps, bridges taken as their ramps), slopes and bridge decking. */
export function routeStats(w: World, nodes: number[], wide: Wide, bridges: Bridge[] = []): RouteStats {
  const onDeck = new Uint8Array(nodes.length);
  let deck = 0;
  for (const b of bridges) {
    // a platform is deck too: its node stands up on it
    if (b.level) { if (!onDeck[b.from]) { onDeck[b.from] = 1; deck++; } continue; }
    for (let k = b.from + 1; k < b.to; k++) if (!onDeck[k]) { onDeck[k] = 1; deck++; }
  }
  let climb = 0, drop = 0, sloped = 0, last = -1;
  for (let k = 0; k < nodes.length; k++) {
    if (onDeck[k]) continue;
    if (nodeSteep(w, nodes[k], wide) > 0) sloped++;
    if (last >= 0) {
      const dh = nodeHeight(w, nodes[k], wide) - nodeHeight(w, nodes[last], wide);
      if (dh > 0) climb += dh; else drop -= dh;
    }
    last = k;
  }
  return { tiles: nodes.length, climb, drop, sloped, bridges: bridges.filter((b) => !b.level).length, deck };
}

/** Direction index from node a to its 4-neighbour b. */
export function dirBetween(a: number, b: number): number {
  const diff = b - a;
  return diff === 1 ? 0 : diff === N ? 1 : diff === -1 ? 2 : 3;
}

function link(w: World, a: number, d: number): void {
  const b = a + DIRS[d][0] + DIRS[d][1] * N;
  w.roadEdges[a] |= 1 << d;
  w.roadEdges[b] |= 1 << ((d + 2) & 3);
}

/** Whether roads crossing here should drop their markings (two roads meeting at right angles). */
export function isJunction(w: World, i: number): boolean {
  return w.roadCover[i] >= 2 && w.roadAxis[i] === 3;
}

/**
 * laneSide bits. A four-lane road's two halves: bit 0/1 the low/high-z half of an x-running road, bit 2/3
 * the low/high-x half of a z-running one. An interstate's rows use the same bits for its two carriageways
 * (its outer rows), and 16 / 32 for the median row of an x- / z-running one.
 */
export const LANE_MEDIAN_X = 16, LANE_MEDIAN_Z = 32;
const LANE_X = [1, LANE_MEDIAN_X, 2], LANE_Z = [4, LANE_MEDIAN_Z, 8];

function applyRoad(w: World, r: Road): void {
  const wide = shapeOf(r.type);
  for (const t of r.tiles) {
    if (roadRank(w.road[t]) < roadRank(r.type)) w.road[t] = r.type;
    if (w.roadCover[t] < 255) w.roadCover[t]++;
  }
  const n = r.nodes;
  const axis = (a: number, b: number) => (Math.abs(b - a) === 1 ? 1 : 2);
  for (let k = 0; k < n.length; k++) {
    const ax = (k > 0 ? axis(n[k - 1], n[k]) : 0) | (k + 1 < n.length ? axis(n[k], n[k + 1]) : 0);
    for (const t of nodeTiles(n[k], wide)) w.roadAxis[t] |= ax;
  }
  if (wide === 'tri') {
    for (let k = 0; k < n.length; k++) {
      // every seam inside the 3×3 is open, as a four-lane block's are: lanes can be changed anywhere
      const c = n[k];
      for (let dz = -1; dz <= 1; dz++) for (let dx = -1; dx <= 1; dx++) {
        const t = c + dz * N + dx;
        if (dx < 1) link(w, t, 0);
        if (dz < 1) link(w, t, 1);
      }
      // which carriageway each row is, for traffic keeping right, and the median between them
      const ax = (k > 0 ? axis(n[k - 1], c) : 0) | (k + 1 < n.length ? axis(c, n[k + 1]) : 0);
      for (let s = -1; s <= 1; s++) {
        if (ax & 1) w.laneSide[c + s * N - 1] |= LANE_X[s + 1], w.laneSide[c + s * N] |= LANE_X[s + 1], w.laneSide[c + s * N + 1] |= LANE_X[s + 1];
        if (ax & 2) w.laneSide[c + s - N] |= LANE_Z[s + 1], w.laneSide[c + s] |= LANE_Z[s + 1], w.laneSide[c + s + N] |= LANE_Z[s + 1];
      }
    }
  } else if (wide) {
    for (let k = 0; k < n.length; k++) {
      const [a, b, c, e] = nodeTiles(n[k], true);
      link(w, a, 0); link(w, c, 0); link(w, a, 1); link(w, b, 1);
      // which half of the carriageway each tile is, for traffic keeping right
      const ax = (k > 0 ? axis(n[k - 1], n[k]) : 0) | (k + 1 < n.length ? axis(n[k], n[k + 1]) : 0);
      if (ax & 1) { w.laneSide[a] |= 1; w.laneSide[b] |= 1; w.laneSide[c] |= 2; w.laneSide[e] |= 2; }
      if (ax & 2) { w.laneSide[a] |= 4; w.laneSide[c] |= 4; w.laneSide[b] |= 8; w.laneSide[e] |= 8; }
    }
  } else {
    for (let k = 1; k < n.length; k++) link(w, n[k - 1], dirBetween(n[k - 1], n[k]));
    // a 45° stretch (world/diagonals.ts): its tiles learn which line runs through them
    markDiagonals(w, r.type, n);
  }
  for (const [tile, deck] of bridgeDecks(r)) {
    w.deckAxis[tile] = deck.axis;
    w.deckLo[tile] = deck.lo;
    w.deckHi[tile] = deck.hi;
    w.deckRoad[tile] = r.type;
    if (deck.toll) w.deckToll[tile] = 1;
    w.roof[tile] = Math.max(w.roof[tile], deck.lo, deck.hi);
  }
}

export function rebuildRoadTables(w: World): void {
  w.road.fill(0);
  w.roadEdges.fill(0);
  w.roadCover.fill(0);
  w.roadAxis.fill(0);
  w.laneSide.fill(0);
  w.roadDiag.fill(0);
  w.deckAxis.fill(0);
  w.deckToll.fill(0);
  w.deckRoad.fill(0);
  for (const r of w.roads) applyRoad(w, r);
  naturalDecks(w);
  w.roadStamp++;
}

/**
 * Add a road along `nodes` (a route from a search); `town` marks it as generated. Bridges must
 * already have their heights (see routeWithBridges / resolveBridges).
 */
export function layRoad(w: World, type: RoadType, nodes: number[], town?: number, bridges: Bridge[] = []): Road {
  const wide = shapeOf(type);
  // a generated paved road never runs through water: it is raised over the shallows it would have forded
  if (town !== undefined) bridges = raiseFords(w, type, nodes, bridges);
  const tiles = new Set<number>();
  for (const n of nodes) for (const t of nodeTiles(n, wide)) tiles.add(t);
  const road: Road = { type, nodes: nodes.slice(), tiles: [...tiles] };
  if (town !== undefined) road.town = town;
  const spans = bridges.filter((b) => Number.isFinite(b.h0) && Number.isFinite(b.h1));
  if (spans.length) road.bridges = spans.map((b) => ({ ...b }));
  w.roads.push(road);
  applyRoad(w, road);
  w.roadStamp++;
  return road;
}

/**
 * Take one tile out of every road that covers it (the bulldozer), splitting those roads into the
 * pieces either side and keeping whatever bridges still sit wholly inside a piece. Returns every
 * tile that needs redrawing, or an empty list if no road was there.
 */
export function clearRoadTile(w: World, tile: number): number[] {
  const touched = new Set<number>();
  const kept: Road[] = [];
  let changed = false;
  for (const r of w.roads) {
    const wide = shapeOf(r.type);
    if (!r.tiles.includes(tile)) { kept.push(r); continue; }
    changed = true;
    for (const t of r.tiles) touched.add(t);
    // split the route wherever a node covers this tile
    const runs: { start: number; nodes: number[] }[] = [];
    let run: number[] = [], start = 0;
    r.nodes.forEach((n, k) => {
      if (nodeTiles(n, wide).includes(tile)) {
        if (run.length > 1) runs.push({ start, nodes: run });
        run = [];
        return;
      }
      if (!run.length) start = k;
      run.push(n);
    });
    if (run.length > 1) runs.push({ start, nodes: run });
    for (const { start: s, nodes } of runs) {
      const tiles = new Set<number>();
      for (const n of nodes) for (const t of nodeTiles(n, wide)) tiles.add(t);
      if (tiles.has(tile)) continue;
      const piece: Road = { type: r.type, nodes, tiles: [...tiles] };
      if (r.town !== undefined) piece.town = r.town;
      const spans = r.bridges?.filter((b) => b.from >= s && b.to <= s + nodes.length - 1);
      if (spans?.length) piece.bridges = spans.map((b) => ({ ...b, from: b.from - s, to: b.to - s }));
      kept.push(piece);
    }
  }
  if (!changed) return [];
  w.roads = kept;
  rebuildRoadTables(w);
  return [...touched];
}

/** Remove the most recently built road. Generated roads can't be undone. */
export function undoRoad(w: World): Road | null {
  const last = w.roads[w.roads.length - 1];
  if (!last || last.town !== undefined) return null;
  w.roads.pop();
  rebuildRoadTables(w);
  return last;
}

// ---------------------------------------------------------------------------------------------
// what the CPU's road vehicles make of the interstate

/** For travel along DIRS[d], the laneSide half (or carriageway) on the driver's right, and the one that isn't. */
const RIGHT = [1, 8, 2, 4], WRONG = [2, 4, 1, 8];
/** The oncoming half of a four-lane road costs a route this much more a tile; the oncoming carriageway of an interstate, and running along its median, more again. */
const WRONG_SIDE = 2, WRONG_WAY = 6, ON_MEDIAN = 4;
/** An interstate tile costs a CPU route this much against any other road's 1: it is that much quicker (PAVED_SPEED / its speed). */
const INTERSTATE_STEP = PAVED_SPEED / ROAD_INFO[RoadType.Interstate].speed;

/**
 * What a step onto road tile b along d costs a CPU vehicle's route (game/traffic.ts landSearch): 1 a tile
 * on any road, less on an interstate in proportion to how much quicker it is, and more on the wrong side
 * of a divided road or along an interstate's grass median.
 */
export function trafficStep(w: World, b: number, d: number): number {
  const r = w.road[b] as RoadType, side = w.laneSide[b];
  if (r === RoadType.Interstate) {
    let step = INTERSTATE_STEP;
    if ((side & WRONG[d]) && !(side & RIGHT[d])) step += WRONG_WAY;
    if (side & (d % 2 === 0 ? LANE_MEDIAN_X : LANE_MEDIAN_Z)) step += ON_MEDIAN;
    return step;
  }
  if (r === RoadType.FourLane && (side & WRONG[d]) && !(side & RIGHT[d])) return 1 + WRONG_SIDE;
  // a step along a 45° diagonal, from one of its tiles to the next: the line is √2 long for two steps
  const db = w.roadDiag[b];
  if (db) {
    const a = b - DIRS[d][0] - DIRS[d][1] * N;
    if (a >= 0 && a < N * N && sameLine(a, w.roadDiag[a], b, db)) return DIAG_STEP;
  }
  return 1;
}

/** Does this county have an interstate? Kept per road stamp, so asking every search costs nothing. */
const hasInterstate = new WeakMap<World, { stamp: number; yes: boolean }>();
/**
 * The least a tile can cost a CPU route here (trafficStep), for its search's distance estimate to stay
 * under the truth: below 1 only where there is an interstate to be quicker on.
 */
export function cheapestStep(w: World): number {
  let c = hasInterstate.get(w);
  if (!c || c.stamp !== w.roadStamp) {
    c = { stamp: w.roadStamp, yes: w.roads.some((r) => r.type === RoadType.Interstate) };
    hasInterstate.set(w, c);
  }
  // a diagonal's steps are cheaper still (√½), where there is one
  return Math.min(c.yes ? INTERSTATE_STEP : 1, hasDiagonals(w) ? DIAG_STEP : 1);
}

/**
 * A CPU driver's cruise on the tile under (x, z), against its everyday cruise: a fifth quicker on an
 * interstate (its speed over any other tarmac's), the same everywhere else. The CPU's cruise is set for
 * ordinary roads (traffic.ts DRIVING), so this is the interstate's +50% over bare ground in its terms.
 */
export function cruiseMul(w: World, x: number, z: number): number {
  const tx = Math.floor(x), tz = Math.floor(z);
  if (tx < 0 || tz < 0 || tx >= N || tz >= N) return 1;
  return w.road[tz * N + tx] === RoadType.Interstate ? ROAD_INFO[RoadType.Interstate].speed / PAVED_SPEED : 1;
}

// ---------------------------------------------------------------------------------------------
// on and off the interstate

/**
 * Tiles a straight line from the middle of tile a to the middle of tile b passes through, in order, each a
 * side-step from the one before: the tiles a ramp's diagonal is laid on, so the line drawn stays on them.
 */
function lineTiles(a: number, b: number): number[] {
  const ax = a % N, az = (a - ax) / N, bx = b % N, bz = (b - bx) / N;
  const nx = Math.abs(bx - ax), nz = Math.abs(bz - az), sx = Math.sign(bx - ax), sz = Math.sign(bz - az);
  const out = [a];
  let x = ax, z = az;
  for (let ix = 0, iz = 0; ix < nx || iz < nz;) {
    // whichever tile edge the line reaches first (through a corner exactly, along x first)
    if (iz >= nz || (ix < nx && (0.5 + ix) / nx <= (0.5 + iz) / nz)) { x += sx; ix++; } else { z += sz; iz++; }
    out.push(z * N + x);
  }
  return out;
}

/** How far along the interstate a ramp's taper runs, and how far out from it, in tiles: a slip road's shallow angle (1 in 3, about 18°). */
const TAPER_LONG = 6, TAPER_OUT = 2;

/**
 * The carriageway an interstate tile is on: the way its traffic flows and the way out from the road, as
 * DIRS indices; null on the median, at a corner, or off the interstate. Traffic keeps right (laneSide).
 */
export function carriageway(w: World, t: number): { flow: number; out: number } | null {
  if (t < 0 || t >= N * N || w.road[t] !== RoadType.Interstate) return null;
  const s = w.laneSide[t] & 63;
  return s === 1 ? { flow: 0, out: 3 } : s === 2 ? { flow: 2, out: 1 } : s === 4 ? { flow: 3, out: 2 } : s === 8 ? { flow: 1, out: 0 } : null;
}

/**
 * The taper of a ramp joining the interstate at tile e: the tiles of a straight line slanting in to e
 * (`on`: an on-ramp, coming in along the traffic) or out from it (an off-ramp, leaving along the traffic),
 * TAPER_LONG along and TAPER_OUT out, in the order the ramp runs. Its far end is where the rest of the ramp
 * is routed to (or from), square on to whatever it meets. Null with why it can't go there.
 */
export function rampTaper(w: World, e: number, on: boolean): { tiles: number[] } | { why: string } {
  const cw = carriageway(w, e);
  if (!cw) return { why: w.road[e] === RoadType.Interstate ? 'Join the interstate on one of its carriageways, not the median or a bend' : 'Not on an interstate' };
  const ex = e % N, ez = (e - ex) / N;
  const along = on ? -1 : 1;
  const px = ex + DIRS[cw.flow][0] * TAPER_LONG * along + DIRS[cw.out][0] * TAPER_OUT;
  const pz = ez + DIRS[cw.flow][1] * TAPER_LONG * along + DIRS[cw.out][1] * TAPER_OUT;
  if (!inB(px, pz)) return { why: 'No room for the slip road before the edge of the island' };
  const p = idx(px, pz);
  const tiles = on ? lineTiles(p, e) : lineTiles(e, p);
  for (const t of tiles) {
    if (t === e) continue;
    const c = carriageway(w, t);
    // the last of it may already lie along the carriageway it joins; anywhere else on an interstate it may not
    if (w.road[t] === RoadType.Interstate) {
      if (!c || c.flow !== cw.flow) return { why: 'The slip road would cross the interstate' };
      continue;
    }
    const why = nodeProblem(w, t, false) ?? (w.deckAxis[t] ? 'A bridge is in the way of the slip road' : null);
    if (why) return { why };
  }
  return { tiles };
}
