import {
  N, STEP, Biome, Flag, Lot, RoadType, World, idx, inB, steepness, waterDepth,
  type Arch, type Building, type BuildingKind, type Town, type TownKind,
} from './tiles';
import {
  CLAIMED_LOTS, KEEP_RELIEF, Layout, TOWN_INFO, buildingHeight, cityPick, megaPick, metroPick, put, withExtras,
  type Found, type Spec,
} from './towns';
import { KIND_SPEC } from './townKinds';
import { rebuildRoadTables } from './roads';
import { solidMask } from './footprint';
import { SEAM_BAND } from './generate';
import { insideCurve } from './curves';
import type { Rng } from './rng';

/**
 * How a town changes after it was generated: it grows (a building, a street, a storey, a better
 * surface, a civic building it lacks, a ring of ground), it wears (a building boarded up), and it
 * mends. Every change is returned as an edit for the cell's delta, and every edit can be applied
 * again from nothing, which is how a grown town comes back on reload. The deciding is done here with
 * a seeded RNG; the accounting that decides *when* lives in `game/ledger.ts`.
 */

/**
 * A building a town put up: kind, x, z, w, d, facing, floors, seed, lot, solid, game hour, and, for one built
 * in a culture the town imported (docs/passport.html), the style it is drawn in. A tuple from before
 * culture has eleven entries and so is in the town's own style.
 */
export type BuildTuple = [BuildingKind, number, number, number, number, number, number, number, number, 0 | 1, number, Arch?];

export type GrowthEdit =
  | { k: 'build'; t: number; b: BuildTuple }
  | { k: 'lift'; u: number; kind?: BuildingKind; floors: number }
  | { k: 'wear'; u: number; on: 0 | 1 }
  | { k: 'ring'; t: number }
  /** Ground the town took in (docs/lobbying.html, territory): tile indices that are its land from now on. */
  | { k: 'claim'; t: number; n: number[] }
  | { k: 'road'; t: RoadType; n: number[]; tw: number; g: 1 };

/** What one step did: the edits to remember, the tiles to redraw, and a few words for the console. */
export interface StepResult { edits: GrowthEdit[]; tiles: number[]; what: string }

/** Solid buildings, the count graduation is measured in. */
export const builtCount = (t: Town): number => t.buildings.filter((b) => b.solid && !b.gone).length;

/** The share of a town's solid buildings drawn in a style it imported rather than its own (docs/passport.html). */
export function foreignShare(t: Town): number {
  let all = 0, foreign = 0;
  for (const b of t.buildings) {
    if (!b.solid || b.gone) continue;
    all++;
    if (b.style && b.style !== t.style) foreign++;
  }
  return all ? foreign / all : 0;
}

/** Never boarded up, however far a town falls: what makes it the place it is. */
const PROTECTED = new Set<BuildingKind>(['cityHall', 'hospital', 'stadium', 'landmark', 'triumphalArch']);
/** Homes and shops go first; civic buildings hold on longest. */
const HOMES = new Set<BuildingKind>([
  'house', 'townhouse', 'apartment', 'bungalow', 'cottage', 'duplex', 'terraceRow', 'trailerPark', 'farmhouse',
  'courtyardBlock', 'towerBlock', 'condoTower', 'mansion', 'retirementHome',
]);
const SHOPS = new Set<BuildingKind>([
  'shop', 'store', 'diner', 'gas', 'grocery', 'mall', 'cafe', 'bakery', 'pub', 'fastFood', 'motel', 'stripMall',
  'bigBox', 'carDealership', 'garage', 'bowlingAlley', 'cinema', 'nightclub', 'office', 'officePark', 'bank', 'hotel',
  'arcade', 'ramenShop', 'sushiBar', 'dumplingHouse', 'noodleBar', 'trattoria', 'curryHouse', 'deli', 'taqueria', 'kebabShop', 'chippy',
]);
/** Lots nobody boards up: they are farmland, sports or car parks rather than gardens. */
const NEVER_WEAR = new Set<BuildingKind>(['field', 'pitch', 'parking', 'plaza', 'windTurbine']);

// ---------------------------------------------------------------------------------------------
// applying edits: the same code runs live and on reload

/** A tile a growing town may build on or pave: dry, unclaimed, not cleared, clear of the seam band. */
export function growable(w: World, t: Town): (i: number) => boolean {
  const band = w.kind === 'continent' ? SEAM_BAND : 3;
  return (i: number) => {
    const x = i % N, z = (i - x) / N;
    if (x < band || z < band || x >= N - band || z >= N - band) return false;
    if (w.cleared[i] || w.blocked[i] || w.portId[i] >= 0 || w.feature[i]) return false;
    if (w.townId[i] >= 0 && w.townId[i] !== t.id) return false;
    // the tile a road's sweep cuts across (world/curves.ts): an airship mast grew in the middle of a bend (20 Oct 2026)
    if (insideCurve(w, i)) return false;
    if (w.water[i] >= 0 || w.biome[i] === Biome.Ocean) return false;
    return true;
  };
}

/** Is this tile ground the town claimed? (A set kept per town: a GEN 53 plan's arms make the list long.) */
const CLAIMS = new WeakMap<Town, { n: number; set: Set<number> }>();
const claimedBy = (t: Town, i: number): boolean => {
  if (!t.claims?.length) return false;
  let c = CLAIMS.get(t);
  if (!c || c.n !== t.claims.length) { c = { n: t.claims.length, set: new Set(t.claims) }; CLAIMS.set(t, c); }
  return c.set.has(i);
};

/** Make the tiles around something new part of the town, as `Layout.finish` would have. */
function develop(w: World, t: Town, x0: number, z0: number, x1: number, z1: number, out: Set<number>): void {
  const paved = t.kind === 'city' || t.kind === 'metro' || t.kind === 'mega';
  for (let z = z0 - 1; z <= z1; z++) {
    for (let x = x0 - 1; x <= x1; x++) {
      if (!inB(x, z)) continue;
      const i = idx(x, z);
      if ((x < t.x0 || z < t.z0 || x >= t.x0 + t.size || z >= t.z0 + t.size) && !claimedBy(t, i)) continue;
      if (w.water[i] >= 0 || w.portId[i] >= 0 || (w.townId[i] >= 0 && w.townId[i] !== t.id)) continue;
      out.add(i);
      w.townId[i] = t.id;
      if (w.flags[i] & Flag.Field) continue;
      w.biome[i] = Biome.Town;
      if (w.lot[i] === Lot.None) w.lot[i] = paved ? Lot.Paved : Lot.Lawn;
    }
  }
}

/** The ground level a lot at (x, z) of (wx, wz) is cut to: its corners' mean, in steps. */
export function lotLevelOf(w: World, x: number, z: number, wx: number, wz: number): number {
  const c = w.corners;
  let sum = 0;
  for (let zz = z; zz < z + wz; zz++) for (let xx = x; xx < x + wx; xx++) for (let q = 0; q < 4; q++) sum += c[idx(xx, zz) * 4 + q];
  return Math.round(sum / (wx * wz * 4));
}

/**
 * Stand a building on the island: on `allBuildings` (its uid its place there) and on its town's list, or the
 * countryside's with no town; its pad cut level, its solid tiles blocked under its roof height, its lot finish
 * laid (`lot` -1 leaves the ground as it is), and, in a town, the ground round it made the town's (develop).
 * Shared by a town's own growth (applyBuild) and a fleet's construction (world/erect.ts applyErect), so the two
 * can never drift. Returns the tiles it changed.
 */
export function placeBuilding(w: World, t: Town | null, b: Building, lot: number): number[] {
  const { kind, x, z, w: wx, d: wz, level } = b;
  const c = w.corners;
  w.allBuildings.push(b);
  if (t) t.buildings.push(b); else w.countryside.push(b);
  const top = level * STEP + buildingHeight(b);
  const mask = b.solid ? solidMask(b) : null;
  const touched = new Set<number>();
  for (let zz = z; zz < z + wz; zz++) {
    for (let xx = x; xx < x + wx; xx++) {
      const i = idx(xx, zz);
      touched.add(i);
      if (lot >= 0) w.lot[i] = lot;
      if (mask && mask[(zz - z) * wx + xx - x]) { w.blocked[i] = 1; w.roof[i] = Math.max(w.roof[i], top); }
      if (CLAIMED_LOTS.has(kind)) w.flags[i] |= Flag.Poi;
      if (!KEEP_RELIEF.has(kind)) c[i * 4] = c[i * 4 + 1] = c[i * 4 + 2] = c[i * 4 + 3] = level;
      // out in the country nothing grows through a floor again
      if (!t) w.cleared[i] = 1;
    }
  }
  if (t) develop(w, t, x, z, x + wx, z + wz, touched);
  w.revision++;
  return [...touched];
}

/** Put up a building a town grew. Returns the tiles it changed. */
export function applyBuild(w: World, t: Town, e: BuildTuple): number[] {
  const [kind, x, z, wx, wz, facing, floors, seed, lot, solid, at, style] = e;
  const level = lotLevelOf(w, x, z, wx, wz);
  const b: Building = { kind, x, z, w: wx, d: wz, facing, floors, seed, solid: solid === 1, level, uid: w.allBuildings.length, grownAt: at };
  if (style && style !== t.style) b.style = style;
  return placeBuilding(w, t, b, lot);
}

/** Raise a building a storey or two, or turn it into the next kind up on the same footprint. */
export function applyLift(w: World, b: Building, floors: number, kind?: BuildingKind): number[] {
  const tiles: number[] = [];
  for (let z = b.z; z < b.z + b.d; z++) for (let x = b.x; x < b.x + b.w; x++) tiles.push(idx(x, z));
  if (kind && kind !== b.kind) {
    for (const i of tiles) { w.blocked[i] = 0; w.roof[i] = 0; }
    b.kind = kind;
  }
  b.floors = floors;
  const top = b.level * STEP + buildingHeight(b);
  const mask = b.solid ? solidMask(b) : null;
  tiles.forEach((i, k) => {
    if (mask && mask[k]) { w.blocked[i] = 1; w.roof[i] = Math.max(w.roof[i], top); }
  });
  w.revision++;
  // more storeys on the same footprint: nothing a vehicle drives over has moved
  if (!kind) w.cosmetic++;
  return tiles;
}

/** What an open lot's ground was before it went to seed, so mending can put it back. */
const lotWas = new WeakMap<Building, Uint8Array>();

/** Board a building up, or take the boards down. An open lot's grass dies with it. */
export function applyWear(w: World, b: Building, on: boolean): number[] {
  const tiles: number[] = [];
  for (let z = b.z; z < b.z + b.d; z++) for (let x = b.x; x < b.x + b.w; x++) tiles.push(idx(x, z));
  if (!!b.derelict === on) return tiles;
  b.derelict = on || undefined;
  if (!b.solid) {
    if (on) {
      lotWas.set(b, Uint8Array.from(tiles, (i) => w.lot[i]));
      for (const i of tiles) if (w.biome[i] === Biome.Town) w.lot[i] = Lot.Waste;
    } else {
      const was = lotWas.get(b);
      tiles.forEach((i, k) => { if (w.lot[i] === Lot.Waste) w.lot[i] = was ? was[k] : Lot.Park; });
    }
  }
  w.revision++;
  w.cosmetic++;
  return tiles;
}

/** The town's square grows two tiles on every side. */
export function applyRing(t: Town): void {
  t.x0 -= 2;
  t.z0 -= 2;
  t.size += 4;
}

/**
 * Take ground into the town (docs/lobbying.html, territory): the tiles are its land from now on, so its
 * border takes them in and its growth may build on them, inside its square or out past it. Nothing
 * else about them changes until the town builds there. Returns the tiles, to redraw.
 */
export function applyClaim(w: World, t: Town, tiles: number[]): number[] {
  const out: number[] = [];
  const claims = (t.claims ??= []);
  for (const i of tiles) {
    // another town or a harbour may have come to own it since, on a replay over a changed world
    if (i < 0 || i >= N * N || (w.townId[i] >= 0 && w.townId[i] !== t.id) || w.portId[i] >= 0) continue;
    w.townId[i] = t.id;
    if (!claims.includes(i)) claims.push(i);
    out.push(i);
  }
  w.revision++;
  w.cosmetic++;
  return out;
}

/** Tiles of territory a won preference takes in. */
export const CLAIM_TILES = 10;

/**
 * The ground a town takes in when a fleet's call for territory wins: `n` tiles along its border, one at
 * a time, each the eligible tile touching the town (as its border is drawn, and as it grows through
 * this pick) nearest the town's heart, so the town fills its nearest bay first rather than reaching.
 * Eligible is ground the town could build on: dry, unclaimed by anyone, not cleared by the player, no
 * road, rail, building, harbour, feature or landmark on it, gentle enough for a lot, clear of the seam.
 * `inside` is the traced shape's mask test (townShape.ts), so a hole the border already rings is not
 * taken. Fewer than `n` when the ground runs out; empty when there is none.
 */
export function chooseClaim(w: World, t: Town, inside: (i: number) => boolean, rng: Rng, n = CLAIM_TILES): number[] {
  const ok = growable(w, t);
  const hall = t.buildings.find((b) => (b.kind === 'cityHall' || b.kind === 'villageHall' || b.kind === 'communityCentre' || b.kind === 'kasbah') && !b.gone);
  const hx = hall ? hall.x + hall.w / 2 : t.x0 + t.size / 2, hz = hall ? hall.z + hall.d / 2 : t.z0 + t.size / 2;
  const eligible = (i: number): boolean => {
    if (inside(i) || w.townId[i] === t.id) return false;
    if (!ok(i) || w.townId[i] >= 0 || w.road[i] || w.rail[i] || w.blocked[i]) return false;
    if (w.flags[i] & (Flag.Poi | Flag.Field)) return false;
    return waterDepth(w, i) === 0 && steepness(w, i) <= 1;
  };
  const ours = (i: number): boolean => inside(i) || w.townId[i] === t.id;
  const taken = new Set<number>();
  const frontier = new Map<number, number>(); // tile → its distance to the heart, with a hair of jitter for ties
  const consider = (i: number) => {
    if (taken.has(i) || frontier.has(i) || !eligible(i)) return;
    const x = i % N, z = (i - x) / N;
    frontier.set(i, Math.hypot(x + 0.5 - hx, z + 0.5 - hz) + rng() * 0.01);
  };
  const near = (i: number): number[] => {
    const x = i % N, z = (i - x) / N, out: number[] = [];
    if (x > 0) out.push(i - 1);
    if (x < N - 1) out.push(i + 1);
    if (z > 0) out.push(i - N);
    if (z < N - 1) out.push(i + N);
    return out;
  };
  // the border today: every tile of the town's, and every eligible tile touching one
  const reach = Math.ceil(t.size / 2) + 24;
  for (let z = Math.max(1, Math.floor(hz - reach)); z < Math.min(N - 1, Math.ceil(hz + reach)); z++) {
    for (let x = Math.max(1, Math.floor(hx - reach)); x < Math.min(N - 1, Math.ceil(hx + reach)); x++) {
      const i = idx(x, z);
      if (!ours(i)) continue;
      for (const j of near(i)) if (!ours(j)) consider(j);
    }
  }
  const out: number[] = [];
  while (out.length < n && frontier.size) {
    let best = -1, bd = Infinity;
    for (const [i, d] of frontier) if (d < bd) { bd = d; best = i; }
    frontier.delete(best);
    taken.add(best);
    out.push(best);
    for (const j of near(best)) consider(j);
  }
  return out;
}

/** Lay a road a town grew (a new street, or a street paved one grade up). */
export function applyTownRoad(w: World, t: Town, e: Extract<GrowthEdit, { k: 'road' }>, lay: (w: World, type: RoadType, nodes: number[], town: number) => { tiles: number[] }): number[] {
  const road = lay(w, e.t, e.n, t.id);
  const touched = new Set<number>(road.tiles);
  for (const i of road.tiles) {
    const x = i % N, z = (i - x) / N;
    develop(w, t, x, z, x + 1, z + 1, touched);
  }
  return [...touched];
}

