// deciding what to do

/** One row of the growth table: its weight for each kind of town. */
type Row = 'building' | 'street' | 'upgrade' | 'pave' | 'civic';
const TABLE: Record<Row, Record<TownKind, number>> = {
  building: { rural: 55, suburb: 55, city: 45, metro: 40, mega: 40 },
  street: { rural: 15, suburb: 15, city: 15, metro: 15, mega: 15 },
  upgrade: { rural: 5, suburb: 10, city: 25, metro: 30, mega: 30 },
  pave: { rural: 10, suburb: 8, city: 5, metro: 5, mega: 5 },
  civic: { rural: 5, suburb: 7, city: 5, metro: 5, mega: 5 },
};
const ROWS: Row[] = ['building', 'street', 'upgrade', 'pave', 'civic'];

/** What a town needs before it can become the next kind up, and how big it must be. */
export const GRADUATION: Partial<Record<TownKind, { to: TownKind; built: number; size: number; needs: BuildingKind[] }>> = {
  // 1.6 × a fresh town of the kind, measured with pr.economy.towns(): rural ~30 built, suburb ~45, city ~90
  rural: { to: 'suburb', built: 48, size: 26, needs: ['school', 'clinic'] },
  suburb: { to: 'city', built: 70, size: 34, needs: ['cityHall'] },
  city: { to: 'metro', built: 140, size: 44, needs: ['stadium'] },
};

/** The kind this town is ready to become, or null. */
export function readyToGraduate(t: Town): TownKind | null {
  const g = GRADUATION[t.kind];
  if (!g || t.parent !== undefined && g.to === 'metro') return null;
  if (builtCount(t) < g.built || t.size < g.size) return null;
  if (!t.buildings.some((b) => !b.gone && g.needs.includes(b.kind))) return null;
  return g.to;
}

