/**
 * Ski fields' lifts and runs (see docs in industry.ts for where a ski field is carved).
 *
 * A ski field is a base pad at the foot of a mountain with a lodge on it, and one to three lifts going up
 * from it. Each lift is a straight cable from a bottom station on the pad's uphill edge to a top station
 * on a levelled shelf near a summit, and each top has a groomed run back down to the pad. Lifts fan out
 * from the pad at different bearings, so no two lines cross or come near each other.
 *
 * Planned in two halves, like every other work: `planLifts` while the elevation field is still floats
 * (choosing the tops, cutting and grading the runs, levelling the station shelves), and `buildLifts` once
 * the per-tile corners exist, when the towers are stood along each line so the rope clears the ground
 * (terraces and cliffs included) everywhere between the stations, and the stations themselves are built.
 */

import { N, SEA, STEP, Biome, Feature, Flag, World, idx, inB, heightAt, type Building, type SkiLift, type Work } from './tiles';
import type { Rng } from './rng';
import { NEXT_WORLD } from './nextWorld';

/** What each kind of lift is built to. Lengths in tiles, heights in world units. */
export const LIFT = {
  chair: {
    /** Rope height above the station floor, and how far apart the up and down ropes run (the bull wheel's width). */
    rope: 0.95, gauge: 0.56,
    /** Rope to the bottom of a carrier (a chair's footrest, a cabin's floor). */
    hang: 0.6,
    /** Shortest and tallest tower, rope height above its foot; longest span between towers on even ground. */
    towerMin: 1.2, towerMax: 3.8, span: 8,
    /** Rope speed (tiles a second), distance between carriers, riders per carrier. */
    speed: 0.75, spacing: 1.9, seats: 2,
  },
  gondola: {
    rope: 0.95, gauge: 0.7,
    hang: 0.5,
    towerMin: 1.4, towerMax: 5.0, span: 12,
    speed: 1.1, spacing: 3.2, seats: 4,
  },
} as const;
type LiftKind = keyof typeof LIFT;

/** A station's platform above its floor (render/townMesh.ts liftStation). */
export const PLATFORM = 0.14;
/**
 * Air under a carrier: at a station's mouth, and out on the line. Out on the line it is planned with a
 * height step to spare, since a road laid later (and graded) may pass under the rope.
 */
const NEAR_AIR = 0.2, FAR_AIR = 0.45 + STEP;
/**
 * How far along the line from a wheel the carriers are still inside its station (a 3x3 square, levelled
 * under them, where they come down to the platform): further on a diagonal line than a square one.
 */
export function stationReach(ux: number, uz: number): number {
  return 1.5 / Math.max(Math.abs(ux), Math.abs(uz), 0.7);
}
/** The clearance a carrier must keep at horizontal distance s along a lift of length L (world units, rope to ground). */
function liftClearance(kind: LiftKind, s: number, L: number, reach: number): number {
  const e = Math.min(s, L - s);
  const t = Math.min(1, Math.max(0, (e - reach) / 3));
  return LIFT[kind].hang + NEAR_AIR + (FAR_AIR - NEAR_AIR) * t;
}

/** The lift's length (tiles, horizontal) and unit direction bottom to top. */
export function liftAxis(l: SkiLift): { L: number; ux: number; uz: number } {
  const dx = l.x1 - l.x0, dz = l.z1 - l.z0, L = Math.hypot(dx, dz) || 1;
  return { L, ux: dx / L, uz: dz / L };
}

/** Rope height (world units) at horizontal distance s from the bottom wheel: straight between supports. */
export function ropeAt(l: SkiLift, s: number, L = liftAxis(l).L): number {
  let ps = 0, py = l.y0;
  for (const t of l.towers) {
    if (s <= t.s) return py + ((t.y - py) * (s - ps)) / (t.s - ps || 1);
    ps = t.s; py = t.y;
  }
  return py + ((l.y1 - py) * (s - ps)) / (L - ps || 1);
}

// ---------------------------------------------------------------------------------------------
// planning, on the float elevation field

/**
 * A lift chosen and its run cut: station centre tiles (each station is the 3x3 round it) and the run top first.
 * A resort's lift has more runs from its top (`extra`), and every run a name and a grade (`names`, `grades`).
 */
export interface LiftPlan { kind: LiftKind; bx: number; bz: number; tx: number; tz: number; run: number[]; extra?: number[][]; names?: string[]; grades?: SkiGrade[] }
/** A run's grade, by how steep it is: green, blue, black. */
type SkiGrade = 'green' | 'blue' | 'black';

/** The ground a ski field may use for a run or a station. */
type SkiOk = (x: number, z: number) => boolean;

type Rect = { x0: number; z0: number; x1: number; z1: number };
const overlap = (a: Rect, b: Rect, gap: number) =>
  a.x0 - gap <= b.x1 && b.x0 - gap <= a.x1 && a.z0 - gap <= b.z1 && b.z0 - gap <= a.z1;
const station = (x: number, z: number): Rect => ({ x0: x - 1, z0: z - 1, x1: x + 1, z1: z + 1 });

/** Shortest distance between segments ab and cd in the plane. */
export function segDist(ax: number, az: number, bx: number, bz: number, cx: number, cz: number, dx: number, dz: number): number {
  const cross = (px: number, pz: number, qx: number, qz: number, rx: number, rz: number) => (qx - px) * (rz - pz) - (qz - pz) * (rx - px);
  const d1 = cross(ax, az, bx, bz, cx, cz), d2 = cross(ax, az, bx, bz, dx, dz);
  const d3 = cross(cx, cz, dx, dz, ax, az), d4 = cross(cx, cz, dx, dz, bx, bz);
  if (((d1 > 0 && d2 < 0) || (d1 < 0 && d2 > 0)) && ((d3 > 0 && d4 < 0) || (d3 < 0 && d4 > 0))) return 0;
  return Math.min(ptSeg(ax, az, cx, cz, dx, dz), ptSeg(bx, bz, cx, cz, dx, dz), ptSeg(cx, cz, ax, az, bx, bz), ptSeg(dx, dz, ax, az, bx, bz));
}
/** Distance from point p to segment ab. */
export function ptSeg(px: number, pz: number, ax: number, az: number, bx: number, bz: number): number {
  const vx = bx - ax, vz = bz - az, l2 = vx * vx + vz * vz;
  const t = l2 ? Math.max(0, Math.min(1, ((px - ax) * vx + (pz - az) * vz) / l2)) : 0;
  return Math.hypot(px - ax - vx * t, pz - az - vz * t);
}

/** Lift lines keep at least this far apart (tiles), anywhere along them. */
export const LINE_GAP = 3;

/**
 * Grade a run down its line to a steady gradient from its top to its foot, easing a corridor either side,
 * and mark the middle of it as groomed piste.
 */
export function gradeRun(w: World, land: Uint8Array, river: Uint8Array, E: Float32Array, path: number[], half = 3): void {
  const hi = E[path[0]], lo = E[path[path.length - 1]];
  for (let k = 0; k < path.length; k++) {
    const want = hi + (lo - hi) * (k / (path.length - 1));
    const cx = path[k] % N, cz = (path[k] - (path[k] % N)) / N;
    for (let dz = -half; dz <= half; dz++) {
      for (let dx = -half; dx <= half; dx++) {
        const nx = cx + dx, nz = cz + dz;
        if (!inB(nx, nz)) continue;
        const j = idx(nx, nz);
        if (!land[j] || river[j] || w.biome[j] === Biome.Town) continue;
        const d = Math.hypot(dx, dz);
        if (d > half) continue;
        const t = 1 - d / (half + 1);
        E[j] = E[j] + (want - E[j]) * t;
        if (d <= half - 1) {
          w.feature[j] = Feature.Piste;
          w.cleared[j] = 1;
        }
      }
    }
  }
}

/**
 * A run from a top down to the foot: each step to whichever neighbour heads for the foot without
 * climbing, preferring the lower ground. Null if it is caught in a hollow or wanders too far.
 */
function descend(E: Float32Array, from: number, fx: number, fz: number, ok: SkiOk): number[] | null {
  let x = from % N, z = (from - x) / N;
  const path = [from];
  const seen = new Set<number>(path);
  const straight = Math.hypot(fx - x, fz - z);
  for (let k = 0; k < 220; k++) {
    if (Math.hypot(fx - x, fz - z) <= 3) {
      path.push(idx(fx, fz));
      return path.length <= straight * 2.4 + 4 ? path : null;
    }
    let best = -1, bx = x, bz = z, score = Infinity;
    const here = E[idx(x, z)];
    for (let dz = -1; dz <= 1; dz++) for (let dx = -1; dx <= 1; dx++) {
      if (!dx && !dz) continue;
      const nx = x + dx, nz = z + dz;
      if (!inB(nx, nz) || !ok(nx, nz)) continue;
      const j = idx(nx, nz);
      if (seen.has(j) || E[j] > here + 0.5) continue;
      const sc = Math.hypot(fx - nx, fz - nz) + 0.45 * E[j] + Math.max(0, E[j] - here) * 3;
      if (sc < score) { score = sc; best = j; bx = nx; bz = nz; }
    }
    if (best < 0) return null;
    x = bx; z = bz;
    path.push(best);
    seen.add(best);
  }
  return null;
}

/**
 * Could a lift run straight from the foot of a run to its top, before anything is cut? Open country the
 * whole way that a rope on towers could clear: what `planLifts` will ask of its first lift.
 */
export function roughLine(w: World, land: Uint8Array, E: Float32Array, river: Uint8Array, path: number[]): boolean {
  const a = path[path.length - 1], b = path[0];
  const ax = a % N, az = (a - ax) / N, bx = b % N, bz = (b - bx) / N;
  const L = Math.hypot(bx - ax, bz - az);
  if (L < 19) return false;
  for (let s = 0; s <= L; s += 0.5) {
    const x = Math.floor(ax + 0.5 + ((bx - ax) * s) / L), z = Math.floor(az + 0.5 + ((bz - az) * s) / L);
    if (!inB(x, z)) return false;
    const i = idx(x, z);
    if (!land[i] || river[i] || w.biome[i] === Biome.Town || E[i] < SEA + 1) return false;
    if (w.feature[i] === Feature.Quarry || w.feature[i] === Feature.Airfield) return false;
    if (E[i] > E[a] + ((E[b] - E[a]) * s) / L + 4) return false;
  }
  return true;
}

/**
 * Choose a ski field's lifts: the first to the top of the run already cut (`path`, top first), and on a
 * big field one or two more to other high points round the pad, each with a run of its own cut back
 * down. Grades the new runs and levels a shelf for every station.
 */
export function planLifts(
  w: World, land: Uint8Array, E: Float32Array, river: Uint8Array, rng: Rng,
  path: number[], major: boolean, ok: SkiOk,
  level: (x0: number, z0: number, wx: number, wz: number, lv: number, skirt: number) => void,
  resort = false,
): LiftPlan[] {
  const foot = path[path.length - 1];
  const fx = foot % N, fz = (foot - fx) / N;
  const base = E[foot];
  // the lodge stands in the middle of the pad (industry.ts buildWorks): stations keep a tile clear of it
  const lodge: Rect = { x0: fx - 2, z0: fz - 2, x1: fx + 2, z1: fz };
  const plans: LiftPlan[] = [];
  const rects: Rect[] = [lodge];

  const usable = (r: Rect) => {
    for (let z = r.z0; z <= r.z1; z++) for (let x = r.x0; x <= r.x1; x++) {
      if (!inB(x, z)) return false;
      const i = idx(x, z);
      if (!land[i] || river[i] || w.biome[i] === Biome.Town || E[i] < SEA + 1 || (resort && w.biome[i] === Biome.Ocean)) return false;
    }
    return true;
  };
  /** The bottom station for a lift toward (tx, tz): out from the pad's middle along the line, clear of the rest. */
  const bottomFor = (tx: number, tz: number): Rect | null => {
    const a0 = Math.atan2(tz - fz, tx - fx);
    // straight out toward the top if there is room, else round the pad's edge beside the stations already there
    for (const da of [0, 0.4, -0.4, 0.8, -0.8, 1.2, -1.2]) {
      for (let r = 4; r <= 7.5; r += 0.5) {
        const s = station(Math.round(fx + Math.cos(a0 + da) * r), Math.round(fz + Math.sin(a0 + da) * r));
        if (rects.some((o) => overlap(s, o, 1)) || !usable(s)) continue;
        if (Math.hypot(tx - s.x0 - 1, tz - s.z0 - 1) > Math.hypot(tx - fx, tz - fz)) continue;
        return s;
      }
    }
    return null;
  };
  /** Is the straight line between two station centres open country, low enough under a rope on towers? */
  const lineOk = (bx: number, bz: number, tx: number, tz: number) => {
    const L = Math.hypot(tx - bx, tz - bz);
    if (L < 14) return false;
    const e0 = E[idx(bx, bz)], e1 = E[idx(tx, tz)];
    if (e1 < e0 + 6) return false;
    for (let s = 0; s <= L; s += 0.5) {
      const x = Math.floor(bx + 0.5 + ((tx - bx) * s) / L), z = Math.floor(bz + 0.5 + ((tz - bz) * s) / L);
      if (!inB(x, z)) return false;
      const i = idx(x, z);
      if (!land[i] || river[i] || w.biome[i] === Biome.Town || E[i] < SEA + 1 || (resort && w.biome[i] === Biome.Ocean)) return false;
      if (w.feature[i] === Feature.Quarry || w.feature[i] === Feature.Airfield) return false;
      // the ground may bulge above the straight line a little: the towers lift the rope over it
      if (E[i] > e0 + ((e1 - e0) * s) / L + 4) return false;
    }
    for (const p of plans) if (segDist(bx, bz, tx, tz, p.bx, p.bz, p.tx, p.tz) < LINE_GAP) return false;
    return true;
  };
  const bearing = (tx: number, tz: number) => Math.atan2(tz - fz, tx - fx);
  const apart = (a: number, b: number) => { const d = Math.abs(a - b) % (Math.PI * 2); return Math.min(d, Math.PI * 2 - d); };

  const add = (tx: number, tz: number, run: number[]): boolean => {
    const top = station(tx, tz);
    if (rects.some((o) => overlap(top, o, 2)) || !usable(top)) return false;
    const b = bottomFor(tx, tz);
    if (!b) return false;
    const bx = b.x0 + 1, bz = b.z0 + 1;
    if (!lineOk(bx, bz, tx, tz)) return false;
    plans.push({ kind: 'chair', bx, bz, tx, tz, run });
    rects.push(b, top);
    return true;
  };

  // the first lift runs up to the top of the run the field was found by
  const head = path[0];
  add(head % N, (head - (head % N)) / N, path);

  // more lifts on a big field (and now and then on a small one), fanned out round the pad
  // (a resort in the high country, 0.7.0, up to four more, from further out and higher up)
  const more = resort ? 4 : major ? 2 : rng() < 0.45 ? 1 : 0;
  const reach = resort ? RESORT_REACH : 48, rise = resort ? 10 : 6;
  // the candidate tops: high ground the field may use, a fair way out from the pad
  const tops: number[] = [];
  for (let z = fz - reach; z <= fz + reach; z++) for (let x = fx - reach; x <= fx + reach; x++) {
    if (!inB(x, z)) continue;
    const r = Math.hypot(x - fx, z - fz);
    if (r < 15 || r > reach || E[idx(x, z)] < base + rise || !ok(x, z)) continue;
    tops.push(idx(x, z));
  }
  for (let k = 0; k < more && tops.length; k++) {
    let best: { tx: number; tz: number; run: number[]; score: number } | null = null;
    for (let t = 0; t < 220; t++) {
      const i = tops[Math.floor(rng() * tops.length)];
      const tx = i % N, tz = (i - tx) / N, r = Math.hypot(tx - fx, tz - fz);
      const b = bearing(tx, tz);
      // side by side up the same face is how most fields grow, but a lift of its own toward another top scores better
      const spread = Math.min(...plans.map((p) => apart(b, bearing(p.tx, p.tz))));
      if (spread < 0.1) continue;
      const score = E[i] - base - r * 0.05 - Math.max(0, 0.6 - spread) * 6;
      if (best && score <= best.score) continue;
      const top = station(tx, tz);
      if (rects.some((o) => overlap(top, o, 2)) || !usable(top)) continue;
      const bot = bottomFor(tx, tz);
      if (!bot || !lineOk(bot.x0 + 1, bot.z0 + 1, tx, tz)) continue;
      const run = descend(E, i, fx, fz, ok);
      if (!run || run.length < 18) continue;
      best = { tx, tz, run, score };
    }
    if (!best || !add(best.tx, best.tz, best.run)) break;
    gradeRun(w, land, river, E, best.run);
  }

  // the longest lift on a big field is a gondola, if it is long enough to be worth one
  if (major) {
    let long: LiftPlan | null = null, len = 0;
    for (const p of plans) { const l = Math.hypot(p.tx - p.bx, p.tz - p.bz); if (l > len) { len = l; long = p; } }
    if (long && len >= 26) long.kind = 'gondola';
  }

  // a level shelf for every station: the bottom ones at the pad's level, the tops where they stand
  for (const p of plans) {
    level(p.bx - 1, p.bz - 1, 3, 3, Math.round(base), 2);
    level(p.tx - 1, p.tz - 1, 3, 3, Math.round(E[idx(p.tx, p.tz)]), 2);
    for (let dz = -1; dz <= 1; dz++) for (let dx = -1; dx <= 1; dx++) {
      for (const [cx, cz] of [[p.bx, p.bz], [p.tx, p.tz]]) {
        const j = idx(cx + dx, cz + dz);
        if (land[j]) { w.feature[j] = Feature.Piste; w.cleared[j] = 1; }
      }
    }
  }
  return plans;
}
/** How far out of each station a resort's line is cut down (tiles). */
const NOTCH = 8;

/**
 * A resort's lines leave their stations up steep high-country ground: each is cut down out of both its
 * stations, its banks eased back a step a tile, so the rope clears the ground where no tower can stand yet.
 */
function notchLines(E: Float32Array, land: Uint8Array, plans: LiftPlan[], base: number): void {
  for (const p of plans) {
    const e0 = Math.round(base), e1 = Math.round(E[idx(p.tx, p.tz)]);
    const L = Math.hypot(p.tx - p.bx, p.tz - p.bz), ux = (p.tx - p.bx) / L, uz = (p.tz - p.bz) / L, slope = (e1 - e0) / L;
    for (let s = 1.5; s <= NOTCH; s += 0.5) for (let o = -3; o <= 3; o += 0.5) {
      const bank = Math.max(0, Math.abs(o) - 1.5);
      for (const [cx, cz, h] of [[p.bx + ux * s, p.bz + uz * s, e0 + slope * s * 0.8], [p.tx - ux * s, p.tz - uz * s, e1 - slope * s * 1.2 - 1]]) {
        const x = Math.floor(cx - uz * o + 0.5), z = Math.floor(cz + ux * o + 0.5);
        if (inB(x, z) && land[idx(x, z)]) E[idx(x, z)] = Math.min(E[idx(x, z)], h + bank);
      }
    }
  }
}

// ---------------------------------------------------------------------------------------------
// resorts (0.7.0, NEXT_WORLD): the big fields of the high country

/** A field whose top stands this high (steps: higher than any ordinary county's ground) and drops this far is a resort. */
export const RESORT_TOP = 30, RESORT_DROP = 18;
/** How far out from the pad a resort's lifts reach (tiles). */
const RESORT_REACH = 64;
/** A resort's woods: from this far either side of a run to this far (tiles), and only up to this share of the mountain (the tree line). */
const GLADE_MIN = 2, GLADE_MAX = 9, TREE_LINE = 0.7;
/** What a resort's other runs pay to climb a step, and to come within two tiles of a run already cut (away from the pad). */
const CLIMB = 4, CROWD = 4;

/**
 * The cheapest way down from `from` to the pad at (fx, fz) over ground a run may use: short, hardly ever uphill
 * (the grading cuts a little rise away), and clear of the runs already cut (`avoid`) until they all come in to
 * the pad. Null where there is none, or it wanders too far.
 */
function carve(E: Float32Array, from: number, fx: number, fz: number, ok: SkiOk, avoid: Uint8Array, join: Map<number, { run: number[]; k: number }>): number[] | null {
  const sx = from % N, sz = (from - sx) / N;
  const x0 = Math.max(0, Math.min(sx, fx) - 16), z0 = Math.max(0, Math.min(sz, fz) - 16);
  const W = Math.min(N - 1, Math.max(sx, fx) + 16) - x0 + 1, H = Math.min(N - 1, Math.max(sz, fz) + 16) - z0 + 1;
  const cost = new Float32Array(W * H).fill(Infinity), prev = new Int32Array(W * H).fill(-1);
  const heap: number[] = [], key: number[] = [];
  const push = (c: number, k: number) => {
    heap.push(k); key.push(c);
    for (let i = heap.length - 1; i > 0;) {
      const up = (i - 1) >> 1;
      if (key[up] <= key[i]) break;
      [heap[up], heap[i]] = [heap[i], heap[up]]; [key[up], key[i]] = [key[i], key[up]];
      i = up;
    }
  };
  const pop = (): number => {
    const top = heap[0], lastK = heap.pop()!, lastC = key.pop()!;
    if (heap.length) {
      heap[0] = lastK; key[0] = lastC;
      for (let i = 0; ;) {
        const l = i * 2 + 1, r = l + 1;
        let m = i;
        if (l < heap.length && key[l] < key[m]) m = l;
        if (r < heap.length && key[r] < key[m]) m = r;
        if (m === i) break;
        [heap[m], heap[i]] = [heap[i], heap[m]]; [key[m], key[i]] = [key[i], key[m]];
        i = m;
      }
    }
    return top;
  };
  const k0 = (sz - z0) * W + sx - x0;
  cost[k0] = 0;
  push(0, k0);
  let end = -1, near = Infinity;
  const far = Math.hypot(fx - sx, fz - sz);
  for (let n = 0; heap.length && n < 400000; n++) {
    const c = key[0], k = pop();
    if (c > cost[k]) continue;
    const x = (k % W) + x0, z = Math.floor(k / W) + z0;
    near = Math.min(near, Math.hypot(fx - x, fz - z));
    // at the pad, or into a run already cut, well down the mountain (the rest of the way down is that run's)
    const d = Math.hypot(fx - x, fz - z);
    if (d <= 5 || (join.has(idx(x, z)) && d < far * 0.6)) { end = k; break; }
    const e = E[idx(x, z)];
    for (let dz = -1; dz <= 1; dz++) for (let dx = -1; dx <= 1; dx++) {
      if (!dx && !dz) continue;
      const nx = x + dx, nz = z + dz;
      if (nx < x0 || nz < z0 || nx >= x0 + W || nz >= z0 + H || !ok(nx, nz)) continue;
      const j = idx(nx, nz), d = E[j] - e;
      const step = (dx && dz ? 1.414 : 1) + Math.max(0, d) * CLIMB + (avoid[j] && Math.hypot(fx - nx, fz - nz) > 10 ? CROWD : 0);
      const nk = (nz - z0) * W + nx - x0;
      if (c + step < cost[nk]) { cost[nk] = c + step; prev[nk] = k; push(c + step, nk); }
    }
  }
  if (end < 0) { resortWhy(`no way down (nearest the pad ${near.toFixed(0)} tiles)`); return null; }
  const path: number[] = [];
  for (let k = end; k >= 0; k = prev[k]) path.push(idx((k % W) + x0, Math.floor(k / W) + z0));
  path.reverse();
  const into = join.get(path[path.length - 1]);
  if (into) path.push(...into.run.slice(into.k + 1));
  else path.push(idx(fx, fz));
  if (path.length > far * 2.4 + 4) { resortWhy(`wanders ${path.length}`); return null; }
  return path;
}
/** A run's grade by its drop a tile (steps): green under the first, blue under the second, black above. */
const GREEN_MAX = 0.35, BLUE_MAX = 0.6;

const RUN_NAMES: Record<SkiGrade, string[]> = {
  green: ['Bunny Hop', 'Lazy Susan', 'Meadowlark', 'Sunday Drive', 'Easy Street', 'Cub Run', 'Lollipop', 'Marmot Meander', 'Daisy Chain', 'Homeward Bound', 'Sleepy Hollow', 'Sugar Bowl'],
  blue: ['Bluebird', 'Ptarmigan', 'Corkscrew', 'Silver Fox', 'Timberline', 'Snowdrift', 'Fox Trot', 'Cloud Nine', 'Elk Ridge', 'Moonshine', 'Whistler', 'Juniper'],
  black: ['Widowmaker', "Devil's Elbow", 'Free Fall', "Eagle's Nest", 'Big Couloir', 'Powder Keg', 'The Wall', 'Avalanche', 'Kamikaze', 'Hellfire', 'Gunbarrel', 'Rattlesnake'],
};

/** Why a resort's extra runs were not cut (for `npm run skilifts`). */
const RESORT_WHY: string[] = [];
const resortWhy = (why: string) => { RESORT_WHY.push(why); if (RESORT_WHY.length > 200) RESORT_WHY.shift(); };
/** A lodge up the mountain: its lot (levelled), level, facing and where it stands. */
export interface LodgePlan { x: number; z: number; w: number; d: number; level: number; facing: number; where: 'summit' | 'mid' }

/** A run's grade from its drop (steps) over its length (tiles). */
export function gradeOf(drop: number, len: number): SkiGrade {
  const g = drop / Math.max(1, len);
  return g < GREEN_MAX ? 'green' : g < BLUE_MAX ? 'blue' : 'black';
}

/**
 * Make a big field a resort: a run or two more from each top, leaning off down faces of their own, every run
 * named and graded; a lodge at the top of the highest lift (most of the time) and one beside the longest run
 * partway down (now and then); and the woods kept between the runs, below the tree line (Feature.Glade, where
 * render/props.ts grows a forest). Returns the lodges, levelled already.
 */
export function planResort(
  w: World, land: Uint8Array, E: Float32Array, river: Uint8Array, rng: Rng,
  plans: LiftPlan[], fx: number, fz: number, ok: SkiOk,
  level: (x0: number, z0: number, wx: number, wz: number, lv: number, skirt: number) => void,
): LodgePlan[] {
  const onRun = new Uint8Array(N * N);
  const mark = (path: number[]) => {
    for (const i of path) {
      const x = i % N, z = (i - x) / N;
      for (let dz = -2; dz <= 2; dz++) for (let dx = -2; dx <= 2; dx++) if (inB(x + dx, z + dz)) onRun[idx(x + dx, z + dz)] = 1;
    }
  };
  // every run's tiles, to be joined further down
  const join = new Map<number, { run: number[]; k: number }>();
  const joinable = (run: number[]) => run.forEach((i, k) => { if (!join.has(i)) join.set(i, { run, k }); });
  for (const p of plans) { mark(p.run); joinable(p.run); }
  // more runs from each top, off to either side of the first
  for (const p of plans) {
    p.extra = [];
    const L = Math.hypot(p.tx - p.bx, p.tz - p.bz) || 1, ux = (p.tx - p.bx) / L, uz = (p.tz - p.bz) / L;
    const topE = E[idx(p.tx, p.tz)];
    for (const side of rng() < 0.5 ? [1, -1] : [-1, 1]) {
      let start = -1;
      for (const o of [3, 4, 5]) {
        const x = Math.round(p.tx - uz * o * side + ux), z = Math.round(p.tz + ux * o * side + uz);
        if (!inB(x, z) || !ok(x, z) || E[idx(x, z)] < topE - 3) continue;
        start = idx(x, z);
        break;
      }
      if (start < 0) { resortWhy('no start beside the top'); continue; }
      // the cheapest way down from there, clear of the runs already cut: a face of its own
      const run = carve(E, start, fx, fz, ok, onRun, join);
      if (!run) continue;
      if (run.length < 18) { resortWhy(`short run ${run.length}`); continue; }
      // a face of its own: much of it clear of the runs already cut (they all come together at the pad)
      let own = 0;
      for (const i of run) if (!onRun[i]) own++;
      if (own < run.length * 0.45) { resortWhy(`shared ${own}/${run.length}`); continue; }
      gradeRun(w, land, river, E, run, 2);
      mark(run);
      joinable(run);
      p.extra.push(run);
    }
  }
  // every run named, by its grade, no two alike
  const used = new Set<string>();
  for (const p of plans) {
    p.names = []; p.grades = [];
    for (const r of [p.run, ...p.extra!]) {
      const g = gradeOf(E[r[0]] - E[r[r.length - 1]], r.length);
      const pool = RUN_NAMES[g].filter((n) => !used.has(n));
      const name = pool.length ? pool[Math.floor(rng() * pool.length)] : `${RUN_NAMES[g][0]} ${used.size + 1}`;
      used.add(name);
      p.names.push(name); p.grades.push(g);
    }
  }

  // the lodges up the mountain: never under a line, on a run or a station
  const stations = plans.flatMap((p) => [station(p.bx, p.bz), station(p.tx, p.tz)]);
  const lodges: LodgePlan[] = [];
  const lotOk = (x0: number, z0: number, lv: number, onPiste: boolean) => {
    const r: Rect = { x0, z0, x1: x0 + 3, z1: z0 + 2 };
    if (stations.some((o) => overlap(r, o, 1)) || lodges.some((l) => overlap(r, { x0: l.x, z0: l.z, x1: l.x + 3, z1: l.z + 2 }, 2))) return false;
    for (let z = r.z0; z <= r.z1; z++) for (let x = r.x0; x <= r.x1; x++) {
      if (!inB(x, z) || !ok(x, z)) return false;
      const i = idx(x, z);
      if (Math.abs(E[i] - lv) > 2.5 || (!onPiste && w.feature[i] === Feature.Piste)) return false;
    }
    const cx = x0 + 2, cz = z0 + 1.5;
    return plans.every((p) => ptSeg(cx, cz, p.bx + 0.5, p.bz + 0.5, p.tx + 0.5, p.tz + 0.5) >= 4);
  };
  const lodge = (x0: number, z0: number, lv: number, where: LodgePlan['where']) => {
    level(x0, z0, 4, 3, lv, 2);
    for (let z = z0; z < z0 + 3; z++) for (let x = x0; x < x0 + 4; x++) { const i = idx(x, z); w.feature[i] = Feature.Piste; w.cleared[i] = 1; }
    lodges.push({ x: x0, z: z0, w: 4, d: 3, level: lv, facing: facingOf(fx - x0 - 2, fz - z0 - 1), where });
  };
  // at the top of the highest lift, looking down the valley
  const high = plans.reduce((a, b) => (E[idx(b.tx, b.tz)] > E[idx(a.tx, a.tz)] ? b : a));
  if (rng() < 0.6) {
    const lv = Math.round(E[idx(high.tx, high.tz)]);
    search: for (const r of [4, 5, 6]) for (let a = 0; a < 16; a++) {
      const ang = (a / 16) * Math.PI * 2;
      const x0 = Math.round(high.tx + Math.cos(ang) * r) - 2, z0 = Math.round(high.tz + Math.sin(ang) * r) - 1;
      if (lotOk(x0, z0, lv, true)) { lodge(x0, z0, lv, 'summit'); break search; }
    }
  }
  // partway down the longest run, beside it
  if (rng() < 0.45) {
    let long: number[] = [];
    for (const p of plans) for (const r of [p.run, ...p.extra!]) if (r.length > long.length) long = r;
    search: for (const f of [0.45, 0.55, 0.35, 0.65]) {
      const k = Math.floor(long.length * f), a = long[Math.max(0, k - 2)], b = long[Math.min(long.length - 1, k + 2)];
      const ax = a % N, az = (a - ax) / N, bx = b % N, bz = (b - bx) / N, d = Math.hypot(bx - ax, bz - az) || 1;
      const mx = long[k] % N, mz = (long[k] - mx) / N;
      for (const o of [5, -5, 6, -6, 7, -7]) {
        const cx = Math.round(mx - ((bz - az) / d) * o), cz = Math.round(mz + ((bx - ax) / d) * o);
        if (!inB(cx, cz)) continue;
        const lv = Math.round(E[idx(cx, cz)]);
        if (lotOk(cx - 2, cz - 1, lv, false)) { lodge(cx - 2, cz - 1, lv, 'mid'); break search; }
      }
    }
  }

  // the lines cut down out of their stations, now every run is graded (a run started beside a top may have raised the ground)
  notchLines(E, land, plans, E[idx(fx, fz)]);

  // the woods between the runs, below the tree line: a forest the runs are cut through
  let top = -Infinity;
  for (const p of plans) top = Math.max(top, E[idx(p.tx, p.tz)]);
  const base = E[idx(fx, fz)], line = base + (top - base) * TREE_LINE;
  const R = RESORT_REACH + GLADE_MAX;
  const dist = new Uint8Array(N * N).fill(255);
  const q: number[] = [];
  for (let z = fz - R; z <= fz + R; z++) for (let x = fx - R; x <= fx + R; x++) {
    if (inB(x, z) && w.feature[idx(x, z)] === Feature.Piste) { dist[idx(x, z)] = 0; q.push(idx(x, z)); }
  }
  for (let k = 0; k < q.length; k++) {
    const i = q[k], x = i % N, z = (i - x) / N;
    if (dist[i] >= GLADE_MAX) continue;
    for (const [dx, dz] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
      const nx = x + dx, nz = z + dz;
      if (!inB(nx, nz) || Math.abs(nx - fx) > R || Math.abs(nz - fz) > R) continue;
      const j = idx(nx, nz);
      if (dist[j] !== 255) continue;
      dist[j] = dist[i] + 1;
      q.push(j);
    }
  }
  for (const i of q) {
    if (dist[i] < GLADE_MIN || w.feature[i] !== Feature.None || E[i] >= line) continue;
    const x = i % N, z = (i - x) / N;
    if (ok(x, z)) w.feature[i] = Feature.Glade;
  }
  return lodges;
}

// ---------------------------------------------------------------------------------------------
// building, on the finished corners

/** The ground (or still water) at a point, world units. */
function surfaceAt(w: World, x: number, z: number): number {
  const g = heightAt(w, x, z);
  const tx = Math.floor(x), tz = Math.floor(z);
  if (!inB(tx, tz)) return g;
  const wl = w.water[idx(tx, tz)];
  return wl >= 0 ? Math.max(g, wl * STEP) : g;
}

/** The highest ground anywhere under a carrier's width at s along the line (both ropes, and their carriers either side). */
export function groundUnder(w: World, kind: LiftKind, x0: number, z0: number, ux: number, uz: number, s: number): number {
  const half = LIFT[kind].gauge / 2 + 0.18;
  const px = x0 + ux * s, pz = z0 + uz * s;
  let g = -Infinity;
  for (const o of [-half, -half / 2, 0, half / 2, half]) g = Math.max(g, surfaceAt(w, px - uz * o, pz + ux * o));
  return g;
}

/** Why standTowers last gave up. */
let towerFail = '';

/**
 * Stand towers along a straight line so the rope (straight between supports) keeps a carrier its
 * clearance over the ground everywhere between the stations. Each pass puts a tower under the worst
 * shortfall; then long spans over even ground get one in the middle. Null where no tower tall enough
 * can stand where one is needed (a cliff the cable cannot clear, or water, a road, a building).
 */
export function standTowers(
  w: World, kind: LiftKind, x0: number, z0: number, y0: number, x1: number, z1: number, y1: number,
  canStand: (x: number, z: number) => boolean,
  /**
   * A resort's line, up steep summits: a tower may stand closer outside a station's mouth, and is stood tall enough
   * for the worst shortfall it is put up for (inside the station, where the rope must come in level).
   */
  resort = false,
): { s: number; y: number; foot: number }[] | null {
  const gap = resort ? 0.1 : 0.4;
  const spec = LIFT[kind];
  const L = Math.hypot(x1 - x0, z1 - z0), ux = (x1 - x0) / L, uz = (z1 - z0) / L;
  const sup: { s: number; y: number; foot: number }[] = [{ s: 0, y: y0, foot: NaN }, { s: L, y: y1, foot: NaN }];
  const rope = (s: number) => {
    for (let k = 1; k < sup.length; k++) {
      if (s <= sup[k].s) { const a = sup[k - 1], b = sup[k]; return a.y + ((b.y - a.y) * (s - a.s)) / (b.s - a.s || 1); }
    }
    return y1;
  };
  // the ground and the clearance it needs, every fifth of a tile between the station mouths
  const S: number[] = [], need: number[] = [];
  const reach = stationReach(ux, uz);
  // inside each station the carriers pass over its platform: the rope may not dip toward it as it comes in
  for (let s = 0.5; s < reach; s += 0.2) {
    S.push(s, L - s);
    need.push(y0 - spec.rope + PLATFORM + 0.05 + spec.hang, y1 - spec.rope + PLATFORM + 0.05 + spec.hang);
  }
  for (let s = reach; s <= L - reach; s += 0.2) {
    S.push(s);
    need.push(groundUnder(w, kind, x0, z0, ux, uz, s) + liftClearance(kind, s, L, reach));
  }
  const footAt = (s: number) => heightAt(w, x0 + ux * s, z0 + uz * s);
  const needAt = (s: number) => groundUnder(w, kind, x0, z0, ux, uz, s) + liftClearance(kind, s, L, reach);
  const free = (s: number) => s >= reach + gap && s <= L - reach - gap && !sup.some((t) => Math.abs(t.s - s) < 1.1) && canStand(x0 + ux * s, z0 + uz * s);
  const insert = (t: { s: number; y: number; foot: number }) => { sup.push(t); sup.sort((a, b) => a.s - b.s); };

  for (let pass = 0; pass < 48; pass++) {
    let worst = 0, ws = -1, wneed = 0;
    for (let k = 0; k < S.length; k++) {
      const d = need[k] - rope(S[k]);
      if (d > worst) { worst = d; ws = S[k]; wneed = need[k]; }
    }
    if (ws < 0) break;
    let placed = false;
    for (const off of [0, 0.3, -0.3, 0.6, -0.6, 1, -1, 1.5, -1.5, 2, -2, 2.6, -2.6, 3.2, -3.2]) {
      const s = ws + off;
      if (!free(s)) continue;
      const foot = footAt(s);
      const y = Math.max(needAt(s) + 0.1, rope(s), foot + spec.towerMin, resort ? wneed + 0.02 : 0);
      if (y - foot > spec.towerMax) continue;
      insert({ s, y, foot });
      placed = true;
      break;
    }
    if (!placed) { towerFail = `${worst.toFixed(2)} short ${ws.toFixed(1)} tiles up (needs ${needAt(ws).toFixed(2)}, ground at the foot ${footAt(ws).toFixed(2)})`; return null; }
  }
  for (let k = 0; k < S.length; k++) if (need[k] - rope(S[k]) > 1e-3) { towerFail = 'still short after 48 towers'; return null; }

  // no span longer than the lift is built for, where a tower can stand at the height the rope already runs
  for (let pass = 0; pass < 24; pass++) {
    let split = false;
    for (let k = 1; k < sup.length && !split; k++) {
      const a = sup[k - 1], b = sup[k];
      if (b.s - a.s <= spec.span) continue;
      for (const off of [0, 0.5, -0.5, 1, -1, 1.5, -1.5, 2, -2]) {
        const s = (a.s + b.s) / 2 + off;
        if (!free(s)) continue;
        const foot = footAt(s);
        const y = Math.max(rope(s), foot + spec.towerMin);
        if (y - foot > spec.towerMax) continue;
        insert({ s, y, foot });
        split = true;
        break;
      }
      // a long span over a hollow is how real lifts cross one: leave it
      if (!split) continue;
    }
    if (!split) break;
  }
  return sup.slice(1, -1).map((t) => ({ s: +t.s.toFixed(3), y: +t.y.toFixed(3), foot: +t.foot.toFixed(3) }));
}

/**
 * A run's tiles as a smoothed line of points, top first, stopping short of the pad's middle. A point
 * that has ended up in a pond or a stream (water laid after the run was cut) is moved across to the
 * nearest dry ground beside it, or the run stops there.
 */
function runPoints(w: World, run: number[], fx: number, fz: number, tx: number, tz: number): number[] {
  const raw: [number, number][] = run.map((i) => [(i % N) + 0.5, Math.floor(i / N) + 0.5]);
  const out: number[] = [];
  const dry = (x: number, z: number) => { const a = Math.floor(x), b = Math.floor(z); return inB(a, b) && w.water[idx(a, b)] < 0; };
  for (let k = 0; k < raw.length; k++) {
    let sx = 0, sz = 0, n = 0;
    for (let j = Math.max(0, k - 2); j <= Math.min(raw.length - 1, k + 2); j++) { sx += raw[j][0]; sz += raw[j][1]; n++; }
    let x = sx / n, z = sz / n;
    if (!dry(x, z)) {
      const a = raw[Math.max(0, k - 1)], b = raw[Math.min(raw.length - 1, k + 1)];
      const dx = b[0] - a[0], dz = b[1] - a[1], d = Math.hypot(dx, dz) || 1;
      let moved = false;
      for (const o of [0.7, -0.7, 1.4, -1.4, 2.1, -2.1]) {
        if (dry(x - (dz / d) * o, z + (dx / d) * o)) { x -= (dz / d) * o; z += (dx / d) * o; moved = true; break; }
      }
      if (!moved) break;
    }
    // off the top station's shelf before the run starts, and done once the pad is reached
    if (Math.hypot(x - tx - 0.5, z - tz - 0.5) < 2.2 && out.length === 0) continue;
    out.push(+x.toFixed(2), +z.toFixed(2));
    if (Math.hypot(x - fx - 0.5, z - fz - 0.5) < 5) break;
  }
  return out;
}

/** Why planned lifts were dropped when it came to building them, latest last (for the gate, `npm run skilifts`). */
export const LIFT_DROPS: string[] = [];
const drop = (why: string) => { LIFT_DROPS.push(why); if (LIFT_DROPS.length > 200) LIFT_DROPS.shift(); };

/** Facing (DIRS index) nearest a direction. */
const facingOf = (dx: number, dz: number) => (Math.abs(dx) > Math.abs(dz) ? (dx > 0 ? 0 : 2) : (dz > 0 ? 1 : 3));

/**
 * Stand the planned lifts on a ski field: towers along each line (dropping a lift whose rope cannot
 * clear the finished ground), its two stations, the line cut through any trees, and its run.
 */
export function buildLifts(
  w: World, g: Work, plans: LiftPlan[],
  put: (kind: Building['kind'], x: number, z: number, wx: number, wz: number, facing: number, floors: number, level: number) => void,
): void {
  // everything already built: a line never passes over a building, nor a tower stand on one
  const taken = new Uint8Array(N * N);
  for (const b of w.allBuildings) {
    for (let z = b.z; z < b.z + b.d; z++) for (let x = b.x; x < b.x + b.w; x++) if (inB(x, z)) taken[idx(x, z)] = 1;
  }
  const rects = plans.flatMap((p) => [station(p.bx, p.bz), station(p.tx, p.tz)]);
  const inStation = (x: number, z: number, skip: Rect[] = []) => rects.some((r) => !skip.includes(r) && x >= r.x0 && x <= r.x1 && z >= r.z0 && z <= r.z1);
  const fx = g.x, fz = g.z;
  const lifts: SkiLift[] = [];
  const keep: { p: LiftPlan; l: SkiLift; topLevel: number }[] = [];

  for (const p of plans) {
    const own = [station(p.bx, p.bz), station(p.tx, p.tz)];
    const own0 = rects.find((r) => r.x0 === own[0].x0 && r.z0 === own[0].z0)!, own1 = rects.find((r) => r.x0 === own[1].x0 && r.z0 === own[1].z0)!;
    let sum = 0;
    for (let dz = -1; dz <= 1; dz++) for (let dx = -1; dx <= 1; dx++) for (let q = 0; q < 4; q++) sum += w.corners[idx(p.tx + dx, p.tz + dz) * 4 + q];
    const topLevel = Math.round(sum / 36);
    const spec = LIFT[p.kind];
    // a resort's lines, and with 0.7.0 every field's, get the towers steep summits need (see canStand, standTowers)
    const steep = NEXT_WORLD || !!p.names;
    const x0 = p.bx + 0.5, z0 = p.bz + 0.5, x1 = p.tx + 0.5, z1 = p.tz + 0.5;
    const y0 = g.level * STEP + spec.rope, y1 = topLevel * STEP + spec.rope;
    if (y1 < y0 + 1) { drop(`${g.name}: top ${y1} not above bottom ${y0}`); continue; }
    const L = Math.hypot(x1 - x0, z1 - z0), ux = (x1 - x0) / L, uz = (z1 - z0) / L;
    // nothing built under the line, and no other station in its way
    let clear = true;
    for (let s = 0; s <= L && clear; s += 0.25) {
      for (const o of [-0.7, 0, 0.7]) {
        const x = Math.floor(x0 + ux * s - uz * o), z = Math.floor(z0 + uz * s + ux * o);
        if (!inB(x, z)) { clear = false; break; }
        if (inStation(x, z, [own0, own1])) { clear = false; break; }
        if (inStation(x, z) ) continue;
        if (taken[idx(x, z)]) { clear = false; break; }
      }
    }
    if (!clear) { drop(`${g.name}: something built under the line from ${x0},${z0}`); continue; }
    for (const l of lifts) if (segDist(x0, z0, x1, z1, l.x0, l.z0, l.x1, l.z1) < LINE_GAP) clear = false;
    for (const o of w.works) for (const l of o.lifts ?? []) if (segDist(x0, z0, x1, z1, l.x0, l.z0, l.x1, l.z1) < LINE_GAP) clear = false;
    if (!clear) { drop(`${g.name}: too near another line`); continue; }
    const canStand = (x: number, z: number) => {
      const tx = Math.floor(x), tz = Math.floor(z);
      if (!inB(tx, tz)) return false;
      const i = idx(tx, tz);
      // a resort's top often stands on a summit steeper than its line, where the rope needs a tower right by the
      // station to come in level: one may stand on the ground kept round its own stations (reserveWorks)
      const own = steep && [[p.bx, p.bz], [p.tx, p.tz]].some(([cx, cz]) => Math.max(Math.abs(tx - cx), Math.abs(tz - cz)) <= 2);
      return w.water[i] < 0 && !w.road[i] && !w.rail[i] && !w.blocked[i] && !taken[i] && w.townId[i] < 0 && w.portId[i] < 0 &&
        (!(w.flags[i] & Flag.Poi) || own) && w.feature[i] !== Feature.Quarry && w.feature[i] !== Feature.Airfield && !inStation(tx, tz);
    };
    const towers = standTowers(w, p.kind, x0, z0, y0, x1, z1, y1, canStand, steep);
    if (!towers) { drop(`${g.name}: no towers would carry the rope from ${x0},${z0} to ${x1},${z1}: ${towerFail}`); continue; }
    const runs: number[][] = [], names: string[] = [], grades: SkiGrade[] = [];
    [p.run, ...(p.extra ?? [])].forEach((r, k) => {
      const pts = runPoints(w, r, fx, fz, p.tx, p.tz);
      if (pts.length < 8) return;
      runs.push(pts);
      if (p.names) { names.push(p.names[k]); grades.push(p.grades![k]); }
    });
    const l: SkiLift = { kind: p.kind, x0, z0, y0: +y0.toFixed(3), x1, z1, y1: +y1.toFixed(3), towers, runs, ...(p.names ? { names, grades } : {}) };
    lifts.push(l);
    keep.push({ p, l, topLevel });
  }

  for (const { p, l, topLevel } of keep) {
    const floors = p.kind === 'gondola' ? 2 : 1;
    const dx = p.tx - p.bx, dz = p.tz - p.bz;
    put('liftStation', p.bx - 1, p.bz - 1, 3, 3, facingOf(dx, dz), floors, g.level);
    put('liftStation', p.tx - 1, p.tz - 1, 3, 3, facingOf(-dx, -dz), floors, topLevel);
    const { L, ux, uz } = liftAxis(l);
    // the towers' feet are claimed, so no road is run through one; the line is cut through the trees and kept clear of buildings
    for (const t of l.towers) {
      const i = idx(Math.floor(l.x0 + ux * t.s), Math.floor(l.z0 + uz * t.s));
      w.flags[i] |= Flag.Poi;
    }
    for (let s = 0; s <= L; s += 0.25) {
      for (const o of [-0.6, 0, 0.6]) {
        const x = Math.floor(l.x0 + ux * s - uz * o), z = Math.floor(l.z0 + uz * s + ux * o);
        if (!inB(x, z)) continue;
        const i = idx(x, z);
        w.flags[i] |= Flag.Corridor;
        w.cleared[i] = 1;
      }
    }
  }
  // a resort's runs come down to the lift nearest where they finish, and end at the back of its queue
  for (const l of lifts) {
    if (!l.names) continue;
    l.ends = l.runs.map((pts) => {
      const ex = pts[pts.length - 2], ez = pts[pts.length - 1];
      let best = 0;
      for (let k = 1; k < lifts.length; k++) if (Math.hypot(lifts[k].x0 - ex, lifts[k].z0 - ez) < Math.hypot(lifts[best].x0 - ex, lifts[best].z0 - ez)) best = k;
      const e = lifts[best], { ux, uz } = liftAxis(e);
      // the back of the queue, or beside it where a stream runs behind the station
      for (const [a, o] of [[RUN_OUT, 0], [RUN_OUT, 1], [RUN_OUT, -1], [1.2, 1.8], [1.2, -1.8]]) {
        const qx = e.x0 - ux * a - uz * o, qz = e.z0 - uz * a + ux * o;
        if (!inB(Math.floor(qx), Math.floor(qz)) || w.water[idx(Math.floor(qx), Math.floor(qz))] >= 0) continue;
        pts.push(+qx.toFixed(2), +qz.toFixed(2));
        break;
      }
      return best;
    });
  }
  g.lifts = lifts;
}
/** Where a resort's run ends, back from its lift's bottom wheel (tiles): the back of the queue. */
export const RUN_OUT = 2;
