import { N, STEP, World, DIRS, idx, inB, heightOnTile, type Jump } from './tiles';
import { ROAD_INFO } from './roads';

/**
 * Jump ramps and boost pads (the user, 18 Oct 2026): flashy road pieces that shove any car well past its
 * top speed, and kickers at the end of a straight run-up that throw it across a river, a canyon or off a
 * cliff onto the road waiting on the far side. The worldgen lays them (jumpsGen.ts); this is what the car's
 * physics (game/car.ts), the CPU's routes (game/traffic.ts) and the renderer (render/jumps.ts) read.
 *
 * A jump is one way: from the run-up, over the gap, onto the landing. The flight is a true ballistic arc
 * under AIR_G, but its horizontal speed is the jump's own `v` whatever the car came in at (the pads before
 * the kicker are for the drama, not the physics), so every flight lands on the landing tile, and the gate
 * (scripts/jumps.ts) can check every arc clears its gap before anyone drives it.
 */

/** Gravity in the air, world units/s² (a tile is a world unit across): floaty enough to watch, quick enough to feel. */
export const AIR_G = 7;
/** Height of the kicker's lip above the road, world units; it curves up from nothing at the tile's near edge. */
const KICK_H = 0.42;
/** How far across the kicker (0..1 along the jump) a car is when it leaves the lip: the arc's nominal start. */
export const KICK_AT = 0.8;
/** The earliest a car on the kicker is thrown: a fast one may be a frame short of KICK_AT. */
export const KICK_FROM = 0.7;
/** Height of the landing deck's lip on the gap side, sloping away to the road on the far edge of its tile. */
export const LAND_H = 0.14;
/** Air (world units) every point of an arc keeps over whatever is under it, the water's surface included. */
export const CLEAR = 0.3;
/** Seconds a boost pad's surge lasts, fading as it goes. */
export const SURGE_SECS = 1.9;
/** A pad's kick: the car is put straight to (1 + this) × its top speed for the ground it is on... */
export const SURGE_KICK = 0.6;
/** ...and its top speed lifted by up to this share, fading over SURGE_SECS. */
export const SURGE_TOP = 0.9;

interface JumpIndex { kick: Map<number, Jump>; land: Map<number, Jump> }
const INDEX = new WeakMap<Jump[], JumpIndex>();

function index(w: World): JumpIndex {
  let ix = INDEX.get(w.jumps);
  if (!ix) {
    ix = { kick: new Map(), land: new Map() };
    for (const j of w.jumps) { ix.kick.set(j.kick, j); ix.land.set(j.land, j); }
    INDEX.set(w.jumps, ix);
  }
  return ix;
}

/** The jump whose kicker is tile i, if any. */
export function jumpFrom(w: World, i: number): Jump | undefined {
  return w.jumps.length ? index(w).kick.get(i) : undefined;
}

/** The jump that lands on tile i, if any. */
export function jumpOnto(w: World, i: number): Jump | undefined {
  return w.jumps.length ? index(w).land.get(i) : undefined;
}

/** How far across tile (tx, tz) the point (x, z) is, 0..1, going along DIRS[d]. */
export function across(d: number, tx: number, tz: number, x: number, z: number): number {
  const u = d === 0 ? x - tx : d === 1 ? z - tz : d === 2 ? tx + 1 - x : tz + 1 - z;
  return Math.min(1, Math.max(0, u));
}

/**
 * What a kicker or a landing deck adds to the road's height at (x, z): the kicker curves up to KICK_H at its
 * lip, the landing deck falls away from LAND_H on the gap side to the road. Only while the road is there (a
 * bulldozed jump is just ground).
 */
export function rampLift(w: World, x: number, z: number): number {
  if (!w.jumps.length) return 0;
  const tx = Math.floor(x), tz = Math.floor(z);
  if (!inB(tx, tz)) return 0;
  const i = idx(tx, tz);
  if (!w.road[i]) return 0;
  const ix = index(w);
  const k = ix.kick.get(i);
  if (k) { const u = across(k.d, tx, tz, x, z); return KICK_H * u * u; }
  const l = ix.land.get(i);
  if (l) return LAND_H * (1 - across(l.d, tx, tz, x, z));
  return 0;
}

/** The height a car's wheels ride at on a jump's tiles at (x, z): the ground, the road's paving and the ramp. */
export function jumpSurface(w: World, x: number, z: number): number {
  const tx = Math.floor(x), tz = Math.floor(z);
  const i = idx(tx, tz);
  return heightOnTile(w, tx, tz, x, z) + (w.road[i] ? ROAD_INFO[w.road[i]].lift : 0) + rampLift(w, x, z);
}

/** A flight in progress: launched from (x0, y0, z0) along (fx, fz) at v tiles/s and vy up, landing at t = T. */
export interface Flight { jump: Jump; t: number; T: number; x0: number; y0: number; z0: number; fx: number; fz: number; v: number; vy: number; xL: number; zL: number; yL: number }

/** The middle of tile i. */
const mid = (i: number): [number, number] => [(i % N) + 0.5, Math.floor(i / N) + 0.5];

/**
 * The arc from a car leaving jump j's lip at (x, z, y) to the landing tile: the jump's own horizontal speed,
 * the lateral offset kept, and the climb that brings it down exactly on the landing deck. Null if the car
 * is somehow already level with the landing.
 */
export function flightFrom(w: World, j: Jump, x: number, z: number, y: number): Flight | null {
  const [dx, dz] = DIRS[j.d];
  const [lx, lz] = mid(j.land);
  const D = (lx - x) * dx + (lz - z) * dz;
  if (D < 0.5) return null;
  const xL = x + dx * D, zL = z + dz * D;
  const yL = jumpSurface(w, xL, zL);
  const T = D / j.v;
  const vy = (yL - y + (AIR_G * T * T) / 2) / T;
  return { jump: j, t: 0, T, x0: x, y0: y, z0: z, fx: dx, fz: dz, v: j.v, vy, xL, zL, yL };
}

/** Where a flight is t seconds after the lip. */
export function flightAt(f: Flight, t: number): { x: number; y: number; z: number; vy: number } {
  return { x: f.x0 + f.fx * f.v * t, z: f.z0 + f.fz * f.v * t, y: f.y0 + f.vy * t - (AIR_G * t * t) / 2, vy: f.vy - AIR_G * t };
}

/** Jump j's nominal lip: the point KICK_AT across its kicker, on its centreline. */
export function lipOf(w: World, j: Jump): { x: number; y: number; z: number } {
  const [dx, dz] = DIRS[j.d];
  const [kx, kz] = mid(j.kick);
  const x = kx + dx * (KICK_AT - 0.5), z = kz + dz * (KICK_AT - 0.5);
  return { x, z, y: jumpSurface(w, x, z) };
}

/** The highest thing at (x, z) a flying car must keep over: the ground, the water's surface, a roof, a deck. */
export function topAt(w: World, x: number, z: number): number {
  const tx = Math.floor(x), tz = Math.floor(z);
  if (!inB(tx, tz)) return Infinity;
  const i = idx(tx, tz);
  let h = heightOnTile(w, tx, tz, x, z);
  if (w.water[i] >= 0) h = Math.max(h, w.water[i] * STEP);
  if (w.blocked[i]) h = Math.max(h, w.roof[i] || h + 3);
  if (w.deckAxis[i]) h = Math.max(h, Math.max(w.deckLo[i], w.deckHi[i]) + 0.3);
  return h;
}

/**
 * Does jump j's nominal arc clear everything between its kicker and its landing tile by CLEAR, across the
 * width of a car? `air` is the most daylight under it (how much of a jump it is), `low` the least.
 */
export function arcClears(w: World, j: Jump): { ok: boolean; air: number; low: number; why?: string } {
  const lip = lipOf(w, j);
  const f = flightFrom(w, j, lip.x, lip.z, lip.y);
  if (!f) return { ok: false, air: 0, low: 0, why: 'no flight' };
  const sx = f.fz, sz = -f.fx;
  let air = 0, low = Infinity;
  const STEPS = 64;
  for (let s = 1; s < STEPS; s++) {
    const p = flightAt(f, (f.T * s) / STEPS);
    const i = idx(Math.floor(p.x), Math.floor(p.z));
    // over the kicker it is leaving and the deck it is coming down onto, it may be as low as it likes
    if (i === j.kick || i === j.land) continue;
    let top = -Infinity;
    for (const o of [-0.35, 0, 0.35]) top = Math.max(top, topAt(w, p.x + sx * o, p.z + sz * o));
    const c = p.y - top;
    air = Math.max(air, c);
    low = Math.min(low, c);
    if (c < CLEAR) return { ok: false, air, low: c, why: `arc ${c.toFixed(2)} over tile ${i}` };
  }
  return { ok: true, air, low };
}

/**
 * The direction a boost pad on tile i shoves, or -1 for no pad (a bulldozed road takes its pad with it):
 * 0..3 a one-way pad (DIRS), TWO_WAY + 0 or 1 a two-way pad along that axis (DIRS[0] or DIRS[1]), which shoves
 * a car going either way along it (the user, 3 Nov 2026).
 */
export function padAt(w: World, i: number): number {
  return w.boost[i] && w.road[i] ? w.boost[i] - 1 : -1;
}

/** padAt's first two-way code: TWO_WAY + the axis (0 along DIRS[0], 1 along DIRS[1]). */
export const TWO_WAY = 4;
