import { DIRS, STEP, type Building } from './tiles';
import { hashString, mulberry32, type Rng } from './rng';

/**
 * The four stadiums a city can build, and the team that plays in each (docs/stadiums.html).
 *
 *  - bowl:     the open oval every city had before: low stands all round, a soccer pitch.
 *  - gridiron: an American football stadium after the NFL's big rectangular houses — two tiers on all four
 *              sides, a white canopy over the upper deck, a video board hung over the middle of the field.
 *  - ballpark: an old brick ballpark after Fenway and Wrigley — a grandstand wrapped round home plate and down
 *              the lines, a tall green wall in left, bleachers in right, a hand-turned scoreboard in centre
 *              and a red marquee out front.
 *  - pillow:   a soccer arena after Munich's Allianz Arena — a closed ring of inflated diamond cushions that
 *              glow in the team's colour after dark, a roof over the stands and an open eye over the pitch.
 *
 * Everything here is in the model's local frame (as render/townMesh.ts draws it): origin the middle of the
 * lot, +z the way it faces, W across and D deep. The renderer, the car's walls (world/footprint.ts), the
 * pedestrians in the stands and the match-day runtime (game/stadiums.ts) all read the same plan.
 */

export type StadiumDesign = 'bowl' | 'gridiron' | 'ballpark' | 'pillow';
export type Sport = 'soccer' | 'football' | 'baseball';
export const STADIUM_DESIGNS: readonly StadiumDesign[] = ['bowl', 'gridiron', 'ballpark', 'pillow'];
export const SPORT_OF: Record<StadiumDesign, Sport> = { bowl: 'soccer', pillow: 'soccer', gridiron: 'football', ballpark: 'baseball' };
export const SPORT_NAME: Record<Sport, string> = { soccer: 'Soccer', football: 'Football', baseball: 'Baseball' };

/** A rectangle of the field in the local frame: centre, its length along `axis`, its width across it. */
export interface FieldRect { cx: number; cz: number; len: number; wid: number; axis: 'x' | 'z' }

export interface StadiumPlan {
  design: StadiumDesign;
  sport: Sport;
  W: number;
  D: number;
  /** Height of the seating under a local point, or null where there are no seats. */
  seatY(x: number, z: number): number | null;
  /** The parts a car meets. */
  solid(x: number, z: number): boolean;
  /** The playing surface. */
  field: FieldRect;
  /** Where a concert's stage goes: its middle, the way it faces (0 = +z), its width and depth. */
  stage: { x: number; z: number; yaw: number; w: number; d: number };
  /** The general-admission floor in front of the stage. */
  pit: FieldRect;
  /** The big screen: its middle, size, and the way it faces; `two` shows the other side too. */
  board: { x: number; y: number; z: number; w: number; h: number; yaw: number; two?: boolean };
  /** The board out front with the team's name on it, facing +z. */
  sign: { x: number; y: number; z: number; w: number; h: number; col: number };
  /** A ballpark's diamond: home plate, the way to centre field (unit), the base path, the fence. */
  diamond?: { hx: number; hz: number; dx: number; dz: number; base: number; fence: number };
}

/** The lot as the model sees it: W across its front, D deep. */
export function modelDims(b: Building): { W: number; D: number } {
  const alongZ = b.facing % 2 === 1;
  return { W: alongZ ? b.w : b.d, D: alongZ ? b.d : b.w };
}

/** Which of the four a stadium is: its own seed decides, and a ballpark needs room for its outfield. */
export function stadiumDesignOf(b: Building): StadiumDesign {
  const { W, D } = modelDims(b);
  const r = mulberry32((b.seed ^ 0x5ad1) >>> 0);
  r();
  let d = STADIUM_DESIGNS[Math.floor(r() * STADIUM_DESIGNS.length)];
  if (d === 'ballpark' && (W < 7 || D < 6)) d = 'gridiron';
  return d;
}

const PLANS = new Map<string, StadiumPlan>();

/** The plan of a stadium building. */
export function stadiumPlanOf(b: Building): StadiumPlan {
  const { W, D } = modelDims(b);
  return stadiumPlan(stadiumDesignOf(b), W, D);
}

export function stadiumPlan(design: StadiumDesign, W: number, D: number): StadiumPlan {
  const key = `${design}|${W}|${D}`;
  let p = PLANS.get(key);
  if (!p) PLANS.set(key, (p = design === 'gridiron' ? gridiron(W, D) : design === 'ballpark' ? ballpark(W, D) : design === 'pillow' ? pillow(W, D) : bowl(W, D)));
  return p;
}

// ---- the four plans -------------------------------------------------------------------------------

/** The old oval: the stands rise from the pitch's ellipse to the outer wall. */
export const BOWL_H = 1.05;
function bowl(W: number, D: number): StadiumPlan {
  const ax = W / 2 - 0.25, az = D / 2 - 0.25, ix = ax * 0.64, iz = az * 0.6;
  const pw = ix * 1.3, pd = iz * 1.25;
  return {
    design: 'bowl', sport: 'soccer', W, D,
    seatY: (x, z) => {
      const r = Math.hypot(x / ax, z / az);
      if (r < 0.66 || r > 0.97) return null;
      return 0.15 + Math.min(1, Math.max(0, (r - 0.62) / 0.38)) * (BOWL_H - 0.15);
    },
    solid: (x, z) => (x / ax) ** 2 + (z / az) ** 2 <= 1.02 && (x / ix) ** 2 + (z / iz) ** 2 >= 1,
    field: { cx: 0, cz: 0, len: pw, wid: pd, axis: 'x' },
    stage: { x: -pw / 2 + 0.35, z: 0, yaw: Math.PI / 2, w: Math.min(pd * 0.75, 1.7), d: 0.55 },
    pit: { cx: -pw * 0.12, cz: 0, len: pw * 0.5, wid: pd * 0.8, axis: 'x' },
    board: { x: 0, y: BOWL_H + 0.24, z: -az * 0.98 + 0.05, w: 1.1, h: 0.38, yaw: 0 },
    sign: { x: 0, y: 0.38, z: az + 0.03, w: Math.min(ax * 0.9, 2.6), h: 0.3, col: 0x2a2d33 },
  };
}

/** The rectangle of stands round a football field: the depth across them, 0 at the field and 1 at the wall. */
interface RectStands { OX: number; OZ: number; IX: number; IZ: number; sd: number }
export const GRID_LOWER = 0.42, GRID_UPPER = 0.52, GRID_TOP = 1.45;
export function gridStands(W: number, D: number): RectStands {
  const OX = W / 2 - 0.2, OZ = D / 2 - 0.2;
  const sd = Math.min(1.6, Math.max(0.9, Math.min(OX, OZ) * 0.42));
  return { OX, OZ, IX: OX - sd, IZ: OZ - sd, sd };
}
/** How far up a two-tier rake a depth is (0 field, 1 wall): the lower tier, the club level's face, the upper deck. */
function gridHeight(t: number): number {
  if (t <= GRID_LOWER) return 0.1 + (t / GRID_LOWER) * 0.55;
  if (t <= GRID_UPPER) return 0.65 + ((t - GRID_LOWER) / (GRID_UPPER - GRID_LOWER)) * 0.15;
  return 0.8 + ((t - GRID_UPPER) / (1 - GRID_UPPER)) * (GRID_TOP - 0.8);
}
function gridiron(W: number, D: number): StadiumPlan {
  const s = gridStands(W, D);
  const depth = (x: number, z: number) => Math.max((Math.abs(x) - s.IX) / s.sd, (Math.abs(z) - s.IZ) / s.sd);
  const alongX = s.IX >= s.IZ;
  const long = alongX ? s.IX : s.IZ, short = alongX ? s.IZ : s.IX;
  const len = 2 * long * 0.94, wid = Math.min(2 * short * 0.86, len / 1.9);
  const field: FieldRect = { cx: 0, cz: 0, len, wid, axis: alongX ? 'x' : 'z' };
  const end = -len / 2 + 0.38;
  return {
    design: 'gridiron', sport: 'football', W, D,
    seatY: (x, z) => {
      const t = depth(x, z);
      if (t < 0.04 || t > 0.97 || (t > GRID_LOWER - 0.02 && t < GRID_UPPER + 0.03)) return null;
      return gridHeight(t);
    },
    solid: (x, z) => { const t = depth(x, z); return t >= 0 && t <= 1.03; },
    field,
    stage: alongX ? { x: end, z: 0, yaw: Math.PI / 2, w: Math.min(wid * 0.8, 1.9), d: 0.6 } : { x: 0, z: end, yaw: 0, w: Math.min(wid * 0.8, 1.9), d: 0.6 },
    pit: { cx: alongX ? -len * 0.12 : 0, cz: alongX ? 0 : -len * 0.12, len: len * 0.48, wid: wid * 0.9, axis: field.axis },
    board: { x: 0, y: 2.05, z: 0, w: Math.min(1.5, short * 0.9), h: 0.5, yaw: alongX ? 0 : Math.PI / 2, two: true },
    sign: { x: 0, y: 0.95, z: s.OZ + 0.03, w: Math.min(2 * s.OX * 0.7, 3.4), h: 0.3, col: 0x1f2329 },
  };
}

/** A ballpark's shape: the foul gap, the grandstand's depth, home plate, the fence's radius, the stands' reach. */
export interface Park { f: number; sd: number; zH: number; R: number; L: number; bl: number; OX: number; OZ: number }
const S2 = Math.SQRT1_2;
export function parkOf(W: number, D: number): Park {
  const OX = W / 2 - 0.2, OZ = D / 2 - 0.2;
  const f = 0.32, sd = Math.min(1.1, Math.max(0.75, Math.min(OX, OZ) * 0.3)), bl = 0.55;
  const zH = OZ - (f + sd) * Math.SQRT2 - 0.05;
  const R = Math.min(zH + OZ - (bl + 0.25), (OX - 0.3) / S2, (zH + OZ - 0.3) / S2);
  const L = Math.min(R * 0.8, (OX - 0.1) / S2 - (f + sd));
  return { f, sd, zH, R, L, bl, OX, OZ };
}
/** Coordinates down the lines from home plate: u along first base's, v along third's. */
const parkUV = (k: Park, x: number, z: number): { u: number; v: number } => {
  const px = x, pz = z - k.zH;
  return { u: S2 * (px - pz), v: -S2 * (px + pz) };
};
/** Depth into the grandstand (0 by the foul line, 1 at the back), or null off it. */
function parkStand(k: Park, x: number, z: number): number | null {
  const { u, v } = parkUV(k, x, z);
  if (u > k.L || v > k.L) return null;
  const t = Math.max((-v - k.f) / k.sd, (-u - k.f) / k.sd);
  return t >= 0 && t <= 1 ? t : null;
}
/** The outfield bleachers: out past the fence in right and centre (left has the wall). */
function parkBleacher(k: Park, x: number, z: number): number | null {
  const { u, v } = parkUV(k, x, z);
  if (u < 0 || v < 0 || u < v * 0.62) return null;
  const r = Math.hypot(x, z - k.zH), t = (r - k.R - 0.1) / k.bl;
  if (t < 0 || t > 1 || Math.abs(x) > k.OX || z < -k.OZ) return null;
  return t;
}
/** Left field's tall wall, from the foul pole round toward centre. */
const parkMonster = (k: Park, x: number, z: number): boolean => {
  const { u, v } = parkUV(k, x, z);
  return u >= -0.05 && v >= -0.05 && u < v * 0.62;
};
function ballpark(W: number, D: number): StadiumPlan {
  const k = parkOf(W, D);
  const cfz = k.zH - k.R;
  return {
    design: 'ballpark', sport: 'baseball', W, D,
    seatY: (x, z) => {
      const t = parkStand(k, x, z);
      if (t !== null) return t < 0.05 || t > 0.95 ? null : 0.12 + t * 0.85;
      const b = parkBleacher(k, x, z);
      return b === null || b > 0.95 ? null : 0.08 + b * 0.42;
    },
    solid: (x, z) => {
      if (parkStand(k, x, z) !== null || parkBleacher(k, x, z) !== null) return true;
      const { u, v } = parkUV(k, x, z);
      const r = Math.hypot(x, z - k.zH);
      if (u >= -0.06 && v >= -0.06 && r >= k.R && r <= k.R + 0.1) return true;
      // the marquee's posts out front
      return Math.abs(z - (k.OZ - 0.12)) < 0.06 && Math.abs(Math.abs(x - (-k.OX * 0.55)) - 0.7) < 0.06;
    },
    field: { cx: 0, cz: k.zH - k.R * 0.5, len: k.R, wid: k.R * 1.2, axis: 'z' },
    stage: { x: 0, z: cfz + 0.55, yaw: 0, w: Math.min(2.0, k.R * 0.5), d: 0.6 },
    pit: { cx: 0, cz: k.zH - k.R * 0.5, len: k.R * 0.42, wid: k.R * 0.75, axis: 'z' },
    board: { x: 0, y: 1.2, z: cfz - 0.1 - k.bl - 0.06, w: 1.3, h: 0.45, yaw: 0 },
    sign: { x: -k.OX * 0.55, y: 0.42, z: k.OZ - 0.12, w: 1.5, h: 0.28, col: 0xb8262a },
    diamond: { hx: 0, hz: k.zH, dx: 0, dz: -1, base: k.R * 0.29, fence: k.R },
  };
}

/** The arena's superellipse: its half-sizes, and how far out (0 middle, 1 the skin) a point is. */
const PILLOW_N = 4;
export const PILLOW_IN = 0.53, PILLOW_OUT = 0.93, PILLOW_ROOF = 0.72;
export const pillowAxes = (W: number, D: number) => ({ A: W / 2 - 0.2, B: D / 2 - 0.2 });
const pillowRho = (A: number, B: number, x: number, z: number): number =>
  ((Math.abs(x) / A) ** PILLOW_N + (Math.abs(z) / B) ** PILLOW_N) ** (1 / PILLOW_N);
/** A point on the superellipse at angle a, scaled by f. */
export const pillowAt = (A: number, B: number, a: number, f: number): [number, number] => {
  const c = Math.cos(a), s = Math.sin(a), e = 2 / PILLOW_N;
  return [Math.sign(c) * Math.abs(c) ** e * A * f, Math.sign(s) * Math.abs(s) ** e * B * f];
};
const pillowSeatH = (rho: number): number => 0.12 + ((rho - PILLOW_IN) / (PILLOW_OUT - PILLOW_IN)) * 1.15;
function pillow(W: number, D: number): StadiumPlan {
  const { A, B } = pillowAxes(W, D);
  const alongX = A >= B;
  const len = 2 * (alongX ? A : B) * 0.42, wid = 2 * (alongX ? B : A) * 0.4;
  const end = -len / 2 + 0.36;
  return {
    design: 'pillow', sport: 'soccer', W, D,
    seatY: (x, z) => {
      const r = pillowRho(A, B, x, z);
      return r < PILLOW_IN + 0.02 || r > PILLOW_OUT - 0.02 ? null : pillowSeatH(r);
    },
    solid: (x, z) => { const r = pillowRho(A, B, x, z); return r >= PILLOW_IN && r <= 1.01; },
    field: { cx: 0, cz: 0, len, wid, axis: alongX ? 'x' : 'z' },
    stage: alongX ? { x: end, z: 0, yaw: Math.PI / 2, w: Math.min(wid * 0.8, 1.6), d: 0.55 } : { x: 0, z: end, yaw: 0, w: Math.min(wid * 0.8, 1.6), d: 0.55 },
    pit: { cx: alongX ? -len * 0.1 : 0, cz: alongX ? 0 : -len * 0.1, len: len * 0.5, wid: wid * 0.85, axis: alongX ? 'x' : 'z' },
    board: { x: 0, y: 1.12, z: -B * PILLOW_ROOF + 0.12, w: Math.min(1.3, A * 0.45), h: 0.36, yaw: 0 },
    sign: { x: 0, y: 0.32, z: B * 1.0 + 0.04, w: Math.min(A * 0.8, 2.6), h: 0.26, col: 0x1d2026 },
  };
}

// ---- seats, and the frame ---------------------------------------------------------------------------

/** Seats over the stands on a jittered grid, `gap` apart: x, y (the seat), z, flattened. */
export function seatsOf(p: StadiumPlan, gap: number, r: Rng): number[] {
  const out: number[] = [];
  for (let z = -p.D / 2 + gap / 2; z < p.D / 2; z += gap) {
    for (let x = -p.W / 2 + gap / 2; x < p.W / 2; x += gap) {
      const jx = x + (r() - 0.5) * gap * 0.35, jz = z + (r() - 0.5) * gap * 0.35;
      const y = p.seatY(jx, jz);
      if (y !== null) out.push(jx, y, jz);
    }
  }
  return out;
}

/** A point in a field rectangle: a along its length, c across. */
export function fieldPt(f: FieldRect, a: number, c: number): { x: number; z: number } {
  return f.axis === 'x' ? { x: f.cx + a, z: f.cz + c } : { x: f.cx + c, z: f.cz + a };
}

/** Where the model stands: the middle of the lot, its floor, and the way it faces. */
export function stadiumFrame(b: Building): { ox: number; oy: number; oz: number; yaw: number } {
  return { ox: b.x + b.w / 2, oy: b.level * STEP, oz: b.z + b.d / 2, yaw: Math.atan2(DIRS[b.facing][0], DIRS[b.facing][1]) };
}
/** Local to island coordinates, as the model is drawn (Kit.place). */
export function stadiumToIsland(b: Building, x: number, z: number): { x: number; z: number } {
  const f = stadiumFrame(b), c = Math.cos(f.yaw), s = Math.sin(f.yaw);
  return { x: f.ox + x * c + z * s, z: f.oz - x * s + z * c };
}
/** Island to local coordinates. */
export function stadiumToLocal(b: Building, wx: number, wz: number): { x: number; z: number } {
  const f = stadiumFrame(b), c = Math.cos(f.yaw), s = Math.sin(f.yaw);
  const dx = wx - f.ox, dz = wz - f.oz;
  return { x: dx * c - dz * s, z: dx * s + dz * c };
}

// ---- the teams ---------------------------------------------------------------------------------------

const MASCOTS = [
  'Sealions', 'Comets', 'Mariners', 'Foxes', 'Rovers', 'Pilots', 'Lynx', 'Herons', 'Ironclads', 'Stags',
  'Gulls', 'Thunder', 'Otters', 'Falcons', 'Pioneers', 'Badgers', 'Owls', 'Wolves', 'Hornets', 'Rockets',
  'Kestrels', 'Bison', 'Corsairs', 'Lumberjacks', 'Rams', 'Anchors', 'Mustangs', 'Ravens', 'Clippers', 'Bears',
  'Cyclones', 'Puffins', 'Steamers', 'Coyotes', 'Pelicans', 'Bulldogs', 'Narwhals', 'Wildcats', 'Express', 'Monarchs',
  'Navigators', 'Beacons', 'Raptors', 'Tritons', 'Highlanders', 'Grizzlies', 'Volts', 'Torches', 'Barons', 'Cranes',
  'Dolphins', 'Ospreys', 'Rangers', 'Miners', 'Spartans', 'Tigers', 'Gators', 'Mavericks', 'Sentinels', 'Rebels',
];
const COLOURS: [number, number][] = [
  [0xd63a2f, 0xf4f2ec], [0x1f4e9a, 0xf2c14e], [0x2f8f4a, 0xf4f2ec], [0x5b2d8e, 0xf2c14e], [0xf28c1e, 0x1f2329],
  [0x0f7c8c, 0xf4f2ec], [0x8a1c2b, 0xd9a441], [0x1f2329, 0xe2412f], [0x2aa6de, 0x1f2a5a], [0xf2c14e, 0x2a3f8f],
  [0x3a7d2f, 0xf2c14e], [0xc4246b, 0x1f2329], [0x6b7a8c, 0x1a3c6e], [0x1f2a5a, 0xc9ccd2], [0xe8642c, 0x0e4d64],
];

/** Two shirt colours too alike to tell apart across a field. */
function near(a: number, b: number): boolean {
  const d = Math.hypot(((a >> 16) & 255) - ((b >> 16) & 255), ((a >> 8) & 255) - ((b >> 8) & 255), (a & 255) - (b & 255));
  return d < 120;
}

export interface Team { town: string; nick: string; name: string; abbr: string; colour: number; alt: number }

/** A town's team: its nickname and colours come from the town's name, so it is the same wherever it is met. */
export function teamOf(town: string, avoid?: Team, accent?: number): Team {
  const h = hashString(`team|${town}`);
  let nick = MASCOTS[h % MASCOTS.length];
  if (avoid && nick === avoid.nick) nick = MASCOTS[(h + 7) % MASCOTS.length];
  let [colour, alt] = COLOURS[Math.floor(h / MASCOTS.length) % COLOURS.length];
  // a missing accent comes back from a save as null (JSON has no undefined), so only a real number counts
  if (typeof accent === 'number' && Number.isFinite(accent)) colour = accent;
  // a visiting side wears something you can tell apart from the home shirts
  for (let k = 1; avoid && near(colour, avoid.colour) && k < COLOURS.length; k++) [colour, alt] = COLOURS[(Math.floor(h / MASCOTS.length) + k * 4) % COLOURS.length];
  // three letters: a word's initial each for a town of three words, else the first word's letters
  const words = town.toUpperCase().replace(/[^A-Z ]/g, '').split(/\s+/).filter(Boolean);
  const abbr = (words.length >= 2 ? (words.map((w) => w[0]).join('') + words[words.length - 1].slice(1)).slice(0, 3) : (words[0] ?? nick.toUpperCase()).slice(0, 3)).padEnd(3, 'X');
  return { town, nick, name: `${town} ${nick}`, abbr, colour, alt };
}

/** The line on the gate: "Home of the Caldonia Sealions". */
export const homeOf = (t: Team): string => `Home of the ${t.name}`;

// ---- the acts that play them -------------------------------------------------------------------------

const BAND_ADJ = ['Velvet', 'Neon', 'Paper', 'Electric', 'Midnight', 'Silver', 'Crystal', 'Golden', 'Static', 'Wild', 'Lunar', 'Glass', 'Cosmic', 'Scarlet', 'Hollow', 'Echo'];
const BAND_NOUN = ['Comets', 'Harbour', 'Satellites', 'Foxes', 'Tides', 'Machines', 'Lanterns', 'Parade', 'Wolves', 'Arcade', 'Weather', 'Rivals', 'Motel', 'Highway', 'Orchard', 'Signal'];
const SOLO = ['Mara Vale', 'Jules Okoro', 'Kit Delaney', 'Sol Reyes', 'Nova Lin', 'Remy Castell', 'Ivy Monroe', 'Theo Blanc', 'Luz Marin', 'Ash Ferrow'];
const SONG_A = ['Neon', 'Paper', 'Summer', 'Highway', 'Satellite', 'Golden', 'Midnight', 'Harbour', 'Electric', 'Last', 'Velvet', 'Silver', 'Ocean', 'Radio', 'City', 'Wildfire'];
const SONG_B = ['Hearts', 'Lights', 'Static', 'Skyline', 'Dreams', 'Rain', 'Avenue', 'Fever', 'Sunset', 'Echoes', 'Signals', 'Days', 'Waves', 'Ghosts', 'Roads', 'Gold'];

export interface Act { name: string; tour: string; songs: string[] }

export function actFor(seed: number): Act {
  const r = mulberry32(seed >>> 0);
  const p = <T>(a: readonly T[]) => a[Math.floor(r() * a.length)];
  const roll = r();
  const name = roll < 0.45 ? `The ${p(BAND_ADJ)} ${p(BAND_NOUN)}` : roll < 0.75 ? `${p(SOLO)} & the ${p(BAND_NOUN)}` : p(SOLO);
  const n = 6 + Math.floor(r() * 3);
  const songs: string[] = [];
  while (songs.length < n) {
    const s = `${p(SONG_A)} ${p(SONG_B)}`;
    if (!songs.includes(s)) songs.push(s);
  }
  return { name, tour: `${p(SONG_A)} ${p(SONG_B)} Tour`, songs };
}
