import { N, SEA, Biome, Flag, idx, inB, type World } from '../tiles';
import type { Rng } from '../rng';
import type { TownPlan } from '../towns';
import type { PlanCtx, PlanId } from './types';

/**
 * The water a city plan cuts into its town before tiles (docs/cityplans.html, "Two kinds of new water"):
 *
 * - sea-level cuts joined to the sea (rivers, canals, moats, basins, straits, the water round islands), dug the way
 *   the megalopolis's channel and the canal towns' canals are: below sea level, their banks quay walls (Flag.Corridor),
 *   the coastline recomputed after;
 * - sealed lakes at the town's own level, dug the way the oases are, held by the town's ground all round.
 *
 * Every cut is a dry run first: nothing is dug unless the whole of it will go.
 */

type Carver = (p: TownPlan, ctx: PlanCtx, rng: Rng) => boolean;
/** Each plan's carving, where it has any (its family's file fills it in). */
export const CARVERS: Partial<Record<PlanId, Carver>> = {};

const D4 = [[1, 0], [0, 1], [-1, 0], [0, -1]] as const;
const DEBUG = !!(globalThis as { process?: { env: Record<string, string | undefined> } }).process?.env?.PLAN_DEBUG;

/** A cut being planned: tile → depth below sea level. */
export class Dig {
  readonly want = new Map<number, number>();
  constructor(readonly p: TownPlan, readonly ctx: PlanCtx) {}
  mark(x: number, z: number, depth = 2): void {
    x = Math.round(x); z = Math.round(z);
    if (!inB(x, z)) return;
    const i = idx(x, z);
    this.want.set(i, Math.max(this.want.get(i) ?? 0, depth));
  }
  /** A disc of water. */
  disc(cx: number, cz: number, r: number, depth = 2): void {
    for (let z = Math.floor(cz - r); z <= Math.ceil(cz + r); z++) for (let x = Math.floor(cx - r); x <= Math.ceil(cx + r); x++) if (Math.hypot(x + 0.5 - cx, z + 0.5 - cz) <= r) this.mark(x, z, depth);
  }
  /** A band of water `half` either side of the segment a → b, stepped finely so it stays one piece. */
  stroke(ax: number, az: number, bx: number, bz: number, half: number, depth = 2): void {
    const L = Math.max(1, Math.ceil(Math.hypot(bx - ax, bz - az) * 2));
    for (let s = 0; s <= L; s++) {
      const x = ax + ((bx - ax) * s) / L, z = az + ((bz - az) * s) / L;
      for (let dz = -half; dz <= half; dz++) for (let dx = -half; dx <= half; dx++) this.mark(x + dx, z + dz, depth);
    }
  }
  /** Is a tile the town's own (inside its square, or one of its arms)? */
  own(i: number): boolean {
    const p = this.p, x = i % N, z = (i - x) / N;
    if (x >= p.x0 && z >= p.z0 && x < p.x0 + p.size && z < p.z0 + p.size) return true;
    return !!p.carved?.arms?.includes(i);
  }
  /**
   * Straight out from (x, z) along DIRS[d], `half` either side, until the cut is open sea all across; false (and
   * nothing marked) if it reaches the seam band, a causeway or another town's ground first.
   */
  toSea(x: number, z: number, d: number, half: number, depth = 2, reach = 90): boolean {
    const { w, land, band, causeway } = this.ctx;
    const [ox, oz] = D4[d];
    const add: number[] = [];
    for (let s = 0; s <= reach; s++) {
      let open = 0;
      for (let o = -half; o <= half; o++) {
        const tx = Math.round(x + ox * s + (d % 2 === 0 ? 0 : o)), tz = Math.round(z + oz * s + (d % 2 === 0 ? o : 0));
        const why = !inB(tx, tz) || tx < band || tz < band || tx >= N - band || tz >= N - band ? 'the band'
          : causeway && causeway[idx(tx, tz)] ? 'a causeway' : w.biome[idx(tx, tz)] === Biome.Town && !this.own(idx(tx, tz)) ? 'another town' : '';
        if (why) { if (DEBUG) console.log(`toSea from ${x},${z} dir ${d}: ${why} at ${tx},${tz} after ${s}`); return false; }
        const i = idx(tx, tz);
        if (!land[i] && w.elev[i] < SEA) open++;
        else add.push(i);
      }
      if (open === 2 * half + 1) {
        for (const i of add) this.want.set(i, Math.max(this.want.get(i) ?? 0, depth));
        return true;
      }
    }
    return false;
  }
  /** Will every tile of the cut go: on the map, clear of the band, no causeway, no other town's ground, no rail? */
  clear(): boolean {
    const { w, band, causeway } = this.ctx;
    for (const i of this.want.keys()) {
      const x = i % N, z = (i - x) / N;
      if (x < band + 1 || z < band + 1 || x >= N - band - 1 || z >= N - band - 1) return false;
      if (causeway && causeway[i]) return false;
      if (w.biome[i] === Biome.Town && !this.own(i)) return false;
    }
    return true;
  }
  /** Dig it: below sea level, open water, its banks quay walls. Remembered on the plan for the corners. */
  commit(): void {
    const { w, land, river } = this.ctx;
    const carved = (this.p.carved ??= {});
    const water = (carved.water ??= []);
    for (const [i, depth] of this.want) {
      land[i] = 0;
      river[i] = 0;
      w.biome[i] = Biome.Ocean;
      w.elev[i] = SEA - depth;
      w.flags[i] |= Flag.Corridor;
      water.push(i);
    }
    // the square's held biome (towns.ts softenSite keeps it to give back undeveloped ground): water stays water
    const p = this.p;
    for (const i of this.want.keys()) {
      const x = i % N, z = (i - x) / N;
      if (x >= p.x0 && z >= p.z0 && x < p.x0 + p.size && z < p.z0 + p.size && p.biome.length) p.biome[(z - p.z0) * p.size + x - p.x0] = Biome.Ocean;
    }
  }
}

/**
 * A sealed lake on these tiles at `level` (a step under the town's ground round it): the ground dug out under it and
 * its tiles open water. False, with nothing dug, if any tile is the sea's or another town's, or the rim round it
 * would let it spill (a rim tile lower than the lake).
 */
export function sealedLake(p: TownPlan, ctx: PlanCtx, tiles: Set<number>, level: number): boolean {
  const { w, land } = ctx, E = w.elev;
  for (const i of tiles) {
    const x = i % N, z = (i - x) / N;
    if (!inB(x, z) || !land[i]) return false;
    if (x < ctx.band + 2 || z < ctx.band + 2 || x >= N - ctx.band - 2 || z >= N - ctx.band - 2) return false;
    for (const [dx, dz] of D4) {
      const nx = x + dx, nz = z + dz;
      if (!inB(nx, nz)) return false;
      const j = idx(nx, nz);
      if (tiles.has(j)) continue;
      if (!land[j] || E[j] < level + 1) return false;
    }
  }
  const carved = (p.carved ??= {});
  (carved.lakes ??= []).push({ tiles: [...tiles], level });
  for (const i of tiles) {
    E[i] = Math.min(E[i], level - 2);
    ctx.river[i] = 0;
    w.biome[i] = Biome.Ocean;
    w.flags[i] |= Flag.Corridor;
    const x = i % N, z = (i - x) / N;
    if (x >= p.x0 && z >= p.z0 && x < p.x0 + p.size && z < p.z0 + p.size && p.biome.length) p.biome[(z - p.z0) * p.size + x - p.x0] = Biome.Ocean;
  }
  return true;
}

/** A plan mask for the corners (generate.ts): its water flat at its floor, its banks flat at their own height. */
const PLAN_WATER = 1, PLAN_BANK = 3;

/**
 * After every town is planned (generate.ts): the plans' lakes held at their levels, and a mask of their water and
 * the ground beside it, for the corners to be set from so each bank is a quay wall. Null when no plan dug anything.
 */
export function planWater(w: World, plans: TownPlan[], lakeLvl: Int8Array): { mask: Uint8Array; moved: boolean } | null {
  let mask: Uint8Array | null = null, moved = false;
  const m = () => (mask ??= new Uint8Array(N * N));
  for (const p of plans) {
    const c = p.carved;
    if (!c) continue;
    for (const lake of c.lakes ?? []) {
      for (const i of lake.tiles) { lakeLvl[i] = lake.level; m()[i] = PLAN_WATER; }
    }
    if (c.water?.length || c.reclaimed) moved = true;
    for (const i of c.water ?? []) m()[i] = PLAN_WATER;
    for (const i of c.raised ?? []) m()[i] = PLAN_BANK;
    // the ground along every bank: one tile of it, flat, so the wall stands sheer
    for (const i of [...(c.water ?? []), ...(c.lakes ?? []).flatMap((l) => l.tiles)]) {
      const x = i % N, z = (i - x) / N;
      for (const [dx, dz] of D4) {
        if (!inB(x + dx, z + dz)) continue;
        const j = idx(x + dx, z + dz);
        if (!m()[j] && w.biome[j] !== Biome.Ocean) m()[j] = PLAN_BANK;
      }
    }
  }
  return mask ? { mask, moved } : null;
}

/** Set the plans' water and banks flat (the canal towns' way: world/canals.ts setCanalCorners). */
export function planCorners(mask: Uint8Array, E: Float32Array, set: (i: number, h: number) => void): void {
  for (let i = 0; i < mask.length; i++) if (mask[i]) set(i, Math.round(E[i]));
}

/**
 * A river through the town at sea level: across the square along `axis` (0: running along x, 1: along z) about the
 * line `at`, wandering `amp` either side, `half` tiles either side of its middle, carried straight on out to the sea
 * from both edges of the square where it can reach it. Where only one end reaches the sea, the river is an inlet from
 * that side that ends in a basin `end` of the way across. An island may be left in it (`island`: how far along, its
 * length). The middle line it ended up on is returned (one value per step across the square), or null if neither end
 * reaches the sea (nothing marked).
 */
export function seaRiver(dig: Dig, rng: Rng, o: { axis: 0 | 1; at: number; half: number; amp: number; island?: { at: number; len: number }; end?: number }): number[] | null {
  const p = dig.p, S = p.size;
  const s0 = o.axis === 0 ? p.x0 : p.z0;
  const ph = rng() * Math.PI * 2, turns = 0.6 + rng() * 0.5;
  const centre = (s: number) => Math.round(o.at + o.amp * Math.sin(ph + (s / S) * Math.PI * 2 * turns));
  const xy = (s: number, u: number): [number, number] => (o.axis === 0 ? [s0 + s, u] : [u, s0 + s]);
  // try each end out to the sea first: the dig is only kept if one of them gets there
  const head = new Dig(p, dig.ctx), tail = new Dig(p, dig.ctx);
  const [hx, hz] = xy(0, centre(0)), [tx, tz] = xy(S - 1, centre(S - 1));
  const back = o.axis === 0 ? 2 : 3, on = o.axis === 0 ? 0 : 1;
  const atHead = head.toSea(hx, hz, back, o.half), atTail = tail.toSea(tx, tz, on, o.half);
  if (!atHead && !atTail) return null;
  const from = atHead ? 0 : Math.round(S * (1 - (o.end ?? 0.8))), to = atTail ? S - 1 : Math.round(S * (o.end ?? 0.8));
  const line: number[] = [];
  for (let s = 0; s < S; s++) {
    const c = centre(s);
    line.push(c);
    if (s < from || s > to) continue;
    const isle = o.island && s >= o.island.at && s < o.island.at + o.island.len;
    const half = isle ? o.half + 2 : o.half;
    for (let u = -half; u <= half; u++) {
      if (isle && Math.abs(u) <= 1) continue;
      const [x, z] = xy(s, c + u);
      dig.mark(x, z, Math.abs(u) <= half - 1 ? 3 : 2);
    }
    // a bend steps across a tile at a time, so the river stays one piece
    const n = centre(s + 1);
    if (s < to && n !== c) for (let u = -half; u <= half; u++) { const [x, z] = xy(s, n + u); if (!(isle && Math.abs(n + u - c) <= 1)) dig.mark(x, z, 2); }
  }
  // a basin where an inlet ends
  if (!atHead) { const [x, z] = xy(from, centre(from)); dig.disc(x + 0.5, z + 0.5, o.half + 2, 2); }
  if (!atTail) { const [x, z] = xy(to, centre(to)); dig.disc(x + 0.5, z + 0.5, o.half + 2, 2); }
  for (const d of [head, tail]) for (const [i, dep] of d.want) dig.want.set(i, Math.max(dig.want.get(i) ?? 0, dep));
  return line;
}

/** The side of the square the sea is nearest to (DIRS order), or -1 past `reach`. */
export function nearestSeaSide(dig: Dig, reach = 26): number {
  const { w, land, band } = dig.ctx, p = dig.p;
  let best = -1, bestD = reach + 1;
  const D = [[1, 0], [0, 1], [-1, 0], [0, -1]];
  for (let d = 0; d < 4; d++) for (const f of [0.2, 0.35, 0.5, 0.65, 0.8]) {
    const along = Math.round(p.size * f);
    const mx = d === 0 ? p.x0 + p.size - 1 : d === 2 ? p.x0 : p.x0 + along;
    const mz = d === 1 ? p.z0 + p.size - 1 : d === 3 ? p.z0 : p.z0 + along;
    for (let s = 1; s <= reach; s++) {
      const x = mx + D[d][0] * s, z = mz + D[d][1] * s;
      if (!inB(x, z) || x < band || z < band || x >= N - band || z >= N - band) break;
      if (!land[idx(x, z)] && w.elev[idx(x, z)] < SEA) { if (s < bestD) { bestD = s; best = d; } break; }
    }
  }
  return best;
}
