import { N, STEP, Biome, Flag, World, idx, inB, steepness, waterDepth, type Building, type BuildingKind } from './tiles';
import type { FieldInfo } from './biomes';
import type { Rng } from './rng';
import { buildingHeight } from './towns';
import type { RegionSpec } from './regions';
import { solidMask } from './footprint';
import { KIND_SPEC } from './townKinds';

/**
 * Buildings out in the country, belonging to no town: wind farms strung along the hills and the
 * coast, and an orchard or a windmill beside a farm's fields. Kept clear of the seam band, so a
 * county never has to agree with its neighbour about them.
 */
export function placeCountryside(w: World, fields: FieldInfo[], rng: Rng, band: number, spec: RegionSpec | null = null, lane?: (gate: number) => void): void {
  const lo = band + 4, hi = N - band - 4;
  const free = (x: number, z: number) => {
    if (x < lo || z < lo || x >= hi || z >= hi) return false;
    const i = idx(x, z);
    return w.townId[i] < 0 && w.portId[i] < 0 && !w.road[i] && !w.rail[i] && !w.blocked[i] && w.feature[i] === 0 && waterDepth(w, i) === 0 && w.water[i] < 0 &&
      !(w.flags[i] & (Flag.Field | Flag.Poi | Flag.Track | Flag.Ramp | Flag.Corridor));
  };
  const clearOfTowns = (x: number, z: number, r: number) => {
    for (const t of w.towns) {
      if (x > t.x0 - r && x < t.x0 + t.size + r && z > t.z0 - r && z < t.z0 + t.size + r) return false;
    }
    return true;
  };
  const put = (want: BuildingKind, x: number, z: number, wx: number, wz: number, solidWanted: boolean): Building | null => {
    // the biome's own version of a turbine or a mill, or none at all
    const to = spec?.swaps[want];
    if (to === null) return null;
    const kind = to ?? want;
    // a kind the towns leave open (a canopy walkway, fish racks) is open out here too
    const solid = solidWanted && KIND_SPEC[kind]?.solid !== false;
    let sum = 0;
    for (let zz = z; zz < z + wz; zz++) for (let xx = x; xx < x + wx; xx++) for (let q = 0; q < 4; q++) sum += w.corners[idx(xx, zz) * 4 + q];
    const level = Math.round(sum / (wx * wz * 4));
    const b: Building = { kind, x, z, w: wx, d: wz, facing: Math.floor(rng() * 4), floors: 1, seed: Math.floor(rng() * 2 ** 31), solid, level, uid: w.allBuildings.length };
    w.allBuildings.push(b);
    w.countryside.push(b);
    const top = level * STEP + buildingHeight(b);
    // only the parts of the model that stand up block, as in a town
    const mask = solid ? solidMask(b) : null;
    for (let zz = z; zz < z + wz; zz++) for (let xx = x; xx < x + wx; xx++) {
      const i = idx(xx, zz);
      w.flags[i] |= Flag.Poi;
      if (mask && mask[(zz - z) * wx + xx - x]) { w.blocked[i] = 1; w.roof[i] = Math.max(w.roof[i], top); }
    }
    return b;
  };

  // ---- wind farms: on the highest open ground of hills, plains and cliff tops ----
  const cands: number[] = [];
  for (let z = lo; z < hi; z += 2) {
    for (let x = lo; x < hi; x += 2) {
      const i = idx(x, z), b = w.biome[i];
      if (b !== Biome.Hills && b !== Biome.Plains && b !== Biome.SeaCliff) continue;
      if (!free(x, z) || steepness(w, i) > 1 || !clearOfTowns(x, z, 10)) continue;
      cands.push(i);
    }
  }
  const height = (i: number) => w.corners[i * 4] + (w.coastDist[i] < 10 ? 2 : 0);
  cands.sort((a, b) => height(b) - height(a));
  const farms = Math.min(cands.length ? 1 + Math.floor(rng() * 3) : 0, Math.floor(cands.length / 40));
  const hubs: number[] = [];
  for (let f = 0; f < farms; f++) {
    const top = cands.slice(0, Math.max(1, Math.floor(cands.length * 0.2)));
    const hub = top.find((i) => hubs.every((h) => Math.hypot((h % N) - (i % N), Math.floor(h / N) - Math.floor(i / N)) > 40) && rng() < 0.3);
    if (hub === undefined) continue;
    hubs.push(hub);
    const hx = hub % N, hz = Math.floor(hub / N);
    const want = 3 + Math.floor(rng() * 5);
    let placed = 0;
    for (let tries = 0; tries < 80 && placed < want; tries++) {
      const a = rng() * Math.PI * 2, r = 3 + rng() * 9;
      const x = Math.round(hx + Math.cos(a) * r), z = Math.round(hz + Math.sin(a) * r);
      if (!inB(x, z) || !free(x, z) || steepness(w, idx(x, z)) > 1) continue;
      if (w.countryside.some((b) => b.kind === 'windTurbine' && Math.hypot(b.x - x, b.z - z) < 3.2)) continue;
      put('windTurbine', x, z, 1, 1, true);
      placed++;
    }
  }

  if (spec) placeRegional(w, spec, rng, lo, hi, free, clearOfTowns, put);

  // ---- beside the fields: an orchard or a windmill ----
  for (const f of fields) {
    if (rng() < 0.45) continue;
    const orchard = rng() < 0.6;
    const [wx, wz] = orchard ? [3, 3] : [1, 1];
    const edge = f.tiles.filter((t) => {
      const x = t % N, z = Math.floor(t / N);
      return !(inB(x + 1, z) && w.flags[idx(x + 1, z)] & Flag.Field) || !(inB(x, z + 1) && w.flags[idx(x, z + 1)] & Flag.Field);
    });
    for (let tries = 0; tries < 30; tries++) {
      if (!edge.length) break;
      const t = edge[Math.floor(rng() * edge.length)];
      const x = (t % N) + 1 + Math.floor(rng() * 2), z = Math.floor(t / N) + Math.floor(rng() * 2) - 1;
      let ok = clearOfTowns(x, z, 4);
      let lo2 = 127, hi2 = -128;
      for (let zz = z; zz < z + wz && ok; zz++) for (let xx = x; xx < x + wx && ok; xx++) {
        if (!inB(xx, zz) || !free(xx, zz)) { ok = false; break; }
        for (let q = 0; q < 4; q++) { const c = w.corners[idx(xx, zz) * 4 + q]; lo2 = Math.min(lo2, c); hi2 = Math.max(hi2, c); }
      }
      if (!ok || hi2 - lo2 > (orchard ? 2 : 1)) continue;
      put(orchard ? 'orchard' : 'windmill', x, z, wx, wz, !orchard);
      break;
    }
  }

  // ---- a farmstead working the fields: the house, a barn and a silo, and a lane out to the road ----
  const flatAt = (x: number, z: number, wx: number, wz: number) => {
    let lo2 = 127, hi2 = -128;
    for (let zz = z; zz < z + wz; zz++) for (let xx = x; xx < x + wx; xx++) {
      if (!inB(xx, zz) || !free(xx, zz)) return false;
      for (let q = 0; q < 4; q++) { const c = w.corners[idx(xx, zz) * 4 + q]; lo2 = Math.min(lo2, c); hi2 = Math.max(hi2, c); }
    }
    return hi2 - lo2 <= 1;
  };
  const steadChance = w.kind === 'continent' ? 0.75 : 0.35;
  for (const f of fields) {
    if (rng() >= steadChance) continue;
    const [fx, fz] = f.center;
    let home: Building | null = null;
    for (let tries = 0; tries < 40 && !home; tries++) {
      const a = rng() * Math.PI * 2, r = 6 + rng() * 5;
      const x = Math.round(fx + Math.cos(a) * r), z = Math.round(fz + Math.sin(a) * r);
      if (!clearOfTowns(x, z, 8) || !flatAt(x - 1, z - 1, 3, 3)) continue;
      home = put('farmhouse', x, z, 1, 1, true);
    }
    if (!home) continue;
    for (let tries = 0; tries < 30; tries++) {
      const x = home.x + Math.floor(rng() * 7) - 3, z = home.z + Math.floor(rng() * 7) - 3;
      if (Math.abs(x - home.x) < 2 && Math.abs(z - home.z) < 2) continue;
      if (!flatAt(x, z, 2, 2)) continue;
      const barn = put('barn', x, z, 2, 2, true);
      if (barn && rng() < 0.6) {
        for (const [sx, sz] of [[x + 2, z], [x - 1, z + 1], [x, z + 2], [x + 1, z - 1]]) if (flatAt(sx, sz, 1, 1)) { put('silo', sx, sz, 1, 1, true); break; }
      }
      break;
    }
    // the yard gate: the first free side of the house
    if (lane) {
      for (const [dx, dz] of [[0, 1], [1, 0], [0, -1], [-1, 0]]) {
        const gx = home.x + dx, gz = home.z + dz;
        if (inB(gx, gz) && free(gx, gz)) { lane(idx(gx, gz)); break; }
      }
    }
  }
}

/**
 * The biome's own buildings out in the country: tent camps on the sand, crofts scattered over the
 * heath, huts up on the passes, shrines by the tracks, stilt houses at the water's edge. Each is
 * put where its table row says: high ground, low ground, the shore, beside water or anywhere.
 */
function placeRegional(
  w: World, spec: RegionSpec, rng: Rng, lo: number, hi: number,
  free: (x: number, z: number) => boolean, clearOfTowns: (x: number, z: number, r: number) => boolean,
  put: (kind: BuildingKind, x: number, z: number, wx: number, wz: number, solid: boolean) => Building | null,
): void {
  const wetBeside = (x: number, z: number, wx: number, wz: number) => {
    for (let zz = z - 1; zz <= z + wz; zz++) for (let xx = x - 1; xx <= x + wx; xx++) {
      if (inB(xx, zz) && (xx < x || zz < z || xx >= x + wx || zz >= z + wz) && w.water[idx(xx, zz)] >= 0) return true;
    }
    return false;
  };
  for (const row of spec.country) {
    for (let n = 0; n < row.count; n++) {
      let best: { x: number; z: number; score: number } | null = null;
      for (let t = 0; t < 160; t++) {
        const x = lo + Math.floor(rng() * Math.max(1, hi - lo - row.w)), z = lo + Math.floor(rng() * Math.max(1, hi - lo - row.d));
        let ok = clearOfTowns(x, z, 6), lo2 = 127, hi2 = -128;
        for (let zz = z; zz < z + row.d && ok; zz++) for (let xx = x; xx < x + row.w && ok; xx++) {
          if (!free(xx, zz)) { ok = false; break; }
          for (let q = 0; q < 4; q++) { const c = w.corners[idx(xx, zz) * 4 + q]; lo2 = Math.min(lo2, c); hi2 = Math.max(hi2, c); }
        }
        if (!ok || hi2 - lo2 > 1) continue;
        if (w.countryside.some((b) => Math.hypot(b.x - x, b.z - z) < 6)) continue;
        const i = idx(x, z);
        let score = rng();
        if (row.where === 'high' || row.where === 'pass') score -= lo2 * 0.4;
        else if (row.where === 'low') score += lo2 * 0.4;
        else if (row.where === 'shore') { if (w.coastDist[i] > 4) continue; }
        else if (row.where === 'water') { if (!wetBeside(x, z, row.w, row.d)) continue; }
        if (!best || score < best.score) best = { x, z, score };
        if (row.where === 'any' || row.where === 'shore' || row.where === 'water') break;
      }
      if (best) put(row.kind, best.x, best.z, row.w, row.d, row.kind !== 'cairnField' && row.kind !== 'reserveGate' && row.kind !== 'tentCamp');
    }
  }
}
