import { Flag, Lot, RoadType, idx, inB } from '../../tiles';
import { grow, put, type Layout, type TownPlan } from '../../towns';
import { LAYERS } from '../layers';
import { CARVERS, Dig, nearestSeaSide, seaRiver } from '../water';
import { avenue, dfCores, dfFlat, finishTown, parkAt, path, reserve, ring, type Pt } from '../kit';
import { discTiles, gridLines, lakeOn, nearest, riverAt, riverThrough } from './shared';
import type { ParkSite } from '../../towns';

/**
 * Grids with a twist (docs/cityplans.html): Manhattan, Barcelona's Eixample, the chessboard capitals (and the Roman
 * castrum), San Francisco's grid over its hills, Milton Keynes's grid roads and Chicago's lakefront.
 */

/** The square's frame turned so `side` (DIRS order) is "down": s runs along that side, u in from the far side. */
export function framed(p: TownPlan, side: number): (s: number, u: number) => Pt {
  const S = p.size, x0 = p.x0, z0 = p.z0;
  return (s, u) => {
    switch (side) {
      case 0: return [x0 + S - u, z0 + s];      // the sea to the east: u counts in from the west edge… mirrored
      case 1: return [x0 + s, z0 + S - u];
      case 2: return [x0 + u, z0 + s];
      default: return [x0 + s, z0 + u];
    }
  };
}

/** Lines of a grid laid in pieces, skipping these holes (rectangles x0, z0, x1, z1 exclusive). */
export function gridAround(c: Layout, xs: number[], zs: number[], holes: [number, number, number, number][], type = RoadType.TwoLane, opts: { bridge?: boolean } = {}): void {
  const t = c.t, X0 = t.x0, Z0 = t.z0, S = t.size;
  const inHole = (x: number, z: number) => holes.some(([a, b, cc, d]) => x >= a && x < cc && z >= b && z < d);
  const mx = xs[xs.length >> 1], mz = zs[zs.length >> 1];
  const run = (pts: Pt[], main: boolean) => {
    // split the line where it enters a hole
    let seg: Pt[] = [];
    const lay = () => { if (seg.length >= 2) { const n = avenue(c, type, seg[0], seg[seg.length - 1], { main, route: false, bridge: opts.bridge }); if (main) c.ends(n); } seg = []; };
    for (const q of pts) { if (inHole(Math.floor(q[0]), Math.floor(q[1]))) lay(); else seg.push(q); }
    lay();
  };
  for (const x of xs) { const pts: Pt[] = []; for (let z = Z0; z < Z0 + S; z++) pts.push([x + 0.5, z + 0.5]); run(pts, x === mx); }
  for (const z of zs) { const pts: Pt[] = []; for (let x = X0; x < X0 + S; x++) pts.push([x + 0.5, z + 0.5]); run(pts, z === mz); }
}

// ---------------------------------------------------------------------------------------------
// Manhattan

CARVERS.manhattan = (p, ctx, rng) => {
  // two rivers straight down the town's length a sixth in from either side, out to the sea both ways if they can be
  const S = p.size;
  const side = nearestSeaSide(new Dig(p, ctx), 30);
  const axis: 0 | 1 = side === 1 || side === 3 ? 1 : 0;   // the island runs toward the sea: its rivers too
  const dig = new Dig(p, ctx);
  const lo = (axis === 0 ? p.z0 : p.x0);
  const west = seaRiver(dig, rng, { axis, at: lo + Math.round(S * 0.12), half: 3, amp: 0, end: 0.97 });
  const east = seaRiver(dig, rng, { axis, at: lo + Math.round(S * 0.86), half: 2, amp: 0, end: 0.97 });
  if (!west || !east || !dig.clear()) return false;
  dig.commit();
  (p.carved ??= {}).note = { axis, west: lo + Math.round(S * 0.12), east: lo + Math.round(S * 0.86), tip: side };
  return true;
};

LAYERS.manhattan = (c, p, rng) => {
  const S = p.size, x0 = p.x0, z0 = p.z0;
  const n = p.carved?.note;
  if (!n) return false;
  const axis = n.axis as 0 | 1;
  // s along the island, u across it
  const P = (s: number, u: number): Pt => (axis === 0 ? [s, u] : [u, s]);
  const s0 = axis === 0 ? x0 : z0, s1 = s0 + S, uW = n.west + 4, uE = n.east - 3;
  const tipAtEnd = n.tip === 0 || n.tip === 1;   // the sea (and downtown) at the high end of s
  c.bridgeSpan = 10;
  // Central Park first (its ring is two avenues and two streets): two avenues wide, five long, uptown
  const parkU = Math.round(uW + (uE - uW) * 0.38), parkLen = Math.min(30, Math.round(S * 0.34)), parkS = tipAtEnd ? s0 + Math.round(S * 0.14) : s1 - Math.round(S * 0.14) - parkLen;
  const cp = axis === 0 ? parkAt(c, parkS, parkU, parkLen, 8, rng) : parkAt(c, parkU, parkS, 8, parkLen, rng);
  // the avenues, every eight tiles across the island, the length of it; the streets every three
  const avs: number[] = [];
  for (let u = uW; u <= uE; u += 8) avs.push(u);
  for (const u of avs) {
    const main = u === avs[avs.length >> 1];
    const nodes = avenue(c, main ? RoadType.FourLane : RoadType.TwoLane, P(s0 + 0.5, u + 0.5), P(s1 - 0.5, u + 0.5), { main, route: false });
    if (main) c.ends(nodes);
  }
  for (let s = s0 + 2; s < s1 - 1; s += 3) avenue(c, RoadType.TwoLane, P(s + 0.5, uW + 0.5), P(s + 0.5, uE + 0.5), { main: false, route: false });
  // the bridges: three or four over the narrow river, one long one over the broad
  for (const f of [0.3, 0.55, 0.8]) {
    const s = s0 + Math.round(S * f);
    avenue(c, RoadType.TwoLane, P(s + 0.5, uE - 2), P(s + 0.5, Math.min(n.east + 6, (axis === 0 ? z0 : x0) + S - 1)), { bridge: true, main: false, route: false });
  }
  const sw = s0 + Math.round(S * (tipAtEnd ? 0.2 : 0.8));
  c.ends(avenue(c, RoadType.FourLane, P(sw, uW + 1), P(sw, Math.max(n.west - 6, (axis === 0 ? z0 : x0) + 1)), { bridge: true, main: true, route: false }));
  // Broadway: a diagonal down the island in two stretches, a square at each kink
  const b0 = tipAtEnd ? s0 + 4 : s1 - 5, dir = tipAtEnd ? 1 : -1;
  const len = Math.floor((uE - uW) * 0.5);
  const k1: Pt = P(b0 + dir * len + 0.5, uW + len + 0.5), k2: Pt = P(b0 + dir * (len + Math.round(S * 0.3)) + 0.5, uW + len + 0.5);
  const tail = Math.min(len, Math.floor((uE - uW) * 0.45));
  const broadway = path(c, RoadType.TwoLane, [P(b0 + 0.5, uW + 0.5), k1, k2, P(b0 + dir * (len + Math.round(S * 0.3) + tail) + 0.5, uW + len - tail + 0.5)], { main: true });
  for (const k of [k1, k2]) put(c, 'fountainSquare', { near: k, maxDist: 3 });
  // the roles: the hall and the exchange downtown at the tip, the statue on the water off it, midtown's towers
  const tipS = tipAtEnd ? s1 - 6 : s0 + 6, midS = s0 + Math.round(S * 0.55);
  c.anchors.seat = P(tipS, (uW + uE) / 2 - 3);
  c.anchors.landmark = P(midS, (uW + uE) / 2);
  c.anchors.museum = P(parkS + parkLen / 2, parkU + 10);
  c.anchors.arch = P(tipS + dir * 2, uW - 1);
  c.anchors.stadium = P(s0 + Math.round(S * 0.3), uE - 3);
  put(c, 'memorial', { near: P(tipS + dir * 3, uW + 1), maxDist: 6, waterside: 'prefer' });
  c.dfAt = dfCores(c, [P(midS, (uW + uE) / 2), P(tipS, (uW + uE) / 2)], S * 0.42);
  finishTown(c, { grow: 4, parks: cp ? [cp] : [], axis: broadway });
  return true;
};

// ---------------------------------------------------------------------------------------------
// Cerdà's Eixample

LAYERS.eixample = (c, p, rng) => {
  const S = p.size, x0 = p.x0, z0 = p.z0, mega = p.kind === 'mega';
  const g = mega ? 8 : 7;
  // the old walled quarter in one corner (the sea's, if the sea is near)
  const qs = Math.round(S * 0.32), corner = Math.floor(rng() * 4);
  const qx0 = corner & 1 ? x0 + S - qs : x0, qz0 = corner & 2 ? z0 + S - qs : z0;
  const hole: [number, number, number, number] = [qx0, qz0, qx0 + qs, qz0 + qs];
  const xs = gridLines(x0, x0 + S, g), zs = gridLines(z0, z0 + S, g);
  gridAround(c, xs, zs, [hole]);
  // Glòries: where the Diagonal, the Meridiana and the Gran Via meet
  const gx = nearest(xs, x0 + S * (corner & 1 ? 0.36 : 0.64)), gz = nearest(zs, z0 + S * (corner & 2 ? 0.36 : 0.64));
  const glo: Pt = [gx + 0.5, gz + 0.5];
  const gran = avenue(c, RoadType.FourLane, [x0 + 1, gz], [x0 + S - 1, gz], { main: true, route: false });
  c.ends(gran);
  const edge = (from: Pt, dx: number, dz: number): Pt => {
    const ex = dx > 0 ? x0 + S - 1 - from[0] : from[0] - x0, ez = dz > 0 ? z0 + S - 1 - from[1] : from[1] - z0;
    const k = Math.floor(Math.min(ex, ez));
    return [from[0] + dx * k, from[1] + dz * k];
  };
  // the Diagonal: right across the grid through Glòries; the Meridiana: off it the other way
  const dxq = corner & 1 ? 1 : -1, dzq = corner & 2 ? 1 : -1;   // toward the old quarter
  const diag = [...avenue(c, RoadType.TwoLane, glo, edge(glo, dxq, -dzq), { four: true }), ...avenue(c, RoadType.TwoLane, glo, edge(glo, -dxq, dzq), { four: true })];
  avenue(c, RoadType.TwoLane, glo, edge(glo, -dxq, -dzq), { four: true });
  ring(c, RoadType.TwoLane, gx, gz, 3, 2, { main: false });
  // the old quarter: brick lanes grown off a Rambla from the grid down to its far corner
  const ram: Pt[] = [[qx0 + qs / 2 + 0.5, corner & 2 ? qz0 + 0.5 : qz0 + qs - 0.5], [qx0 + qs / 2 + 0.5, corner & 2 ? qz0 + qs - 1.5 : qz0 + 1.5]];
  c.ends(avenue(c, RoadType.Paved, ram[0], ram[1], { main: true }));
  const sq: Pt = [qx0 + qs / 2, qz0 + qs / 2];
  // the chamfers: every block's corners cut back to a little paved square
  const cham: number[] = [];
  for (const x of xs) for (const z of zs) {
    if (x >= hole[0] && x < hole[2] && z >= hole[1] && z < hole[3]) continue;
    for (const [dx, dz] of [[1, 1], [-1, 1], [1, -1], [-1, -1]]) { const i = idx(x + dx, z + dz); if (inB(x + dx, z + dz) && !c.w.road[i]) cham.push(i); }
  }
  reserve(c, cham);
  // the roles: the cathedral on its own block mid-grid, the hall in the old quarter, the tower at Glòries
  c.anchors.temple = [nearest(xs, x0 + S * 0.5) + g / 2, nearest(zs, z0 + S * 0.5) - g / 2];
  c.anchors.seat = sq;
  c.anchors.landmark = [gx + 2.5, gz + 2.5];
  c.anchors.arch = [qx0 + (corner & 1 ? -2 : qs + 2), qz0 + qs / 2];
  c.anchors.market = [ram[0][0] + 2, (ram[0][1] + ram[1][1]) / 2];
  c.dfAt = dfFlat(0.5, { at: glo, r: S * 0.14 });
  c.capAt = (x, z) => (Math.hypot(x - glo[0], z - glo[1]) < S * 0.14 ? 0 : 8);
  // brick lanes through the old quarter (grown off the Rambla and the grid's ends)
  const keep = c.t.surface;
  c.t.surface = 'brick';
  grow(c, c.t.roads + (mega ? 10 : 6), RoadType.Paved);
  c.t.surface = keep;
  finishTown(c, { grow: 0, axis: diag });
  for (const i of cham) if (c.w.townId[i] === c.t.id && !c.w.road[i] && !c.w.blocked[i]) c.w.lot[i] = Lot.Plaza;
  return true;
};


// ---------------------------------------------------------------------------------------------
// the chessboard capitals: Chang'an, Heian-kyō, Beijing; and the Roman castrum

LAYERS.chessboard = (c, p, rng) => {
  const S = p.size, x0 = p.x0, z0 = p.z0, kind = p.kind;
  if (kind === 'city') return castrum(c, p);
  const g = kind === 'mega' ? 10 : 9;
  const xs = gridLines(x0, x0 + S, g), zs = gridLines(z0, z0 + S, g);
  // the palace city at the head of the axis, along the north wall
  const pw = Math.round(S * 0.26), pd = Math.round(S * 0.16);
  const px0 = Math.round(x0 + S / 2 - pw / 2), pz0 = z0 + 1;
  const garden = parkAt(c, px0 + 2, pz0 + 1, pw - 4, Math.min(8, pd - 6), rng);
  gridAround(c, xs, zs, [[px0, pz0, px0 + pw, pz0 + pd]]);
  // the ward lanes: a cross in every ward
  for (let a = 0; a + 1 < xs.length; a++) for (let b = 0; b + 1 < zs.length; b++) {
    const mx = Math.round((xs[a] + xs[a + 1]) / 2), mz = Math.round((zs[b] + zs[b + 1]) / 2);
    if (mx >= px0 && mx < px0 + pw && mz < pz0 + pd) continue;
    avenue(c, RoadType.Paved, [mx + 0.5, zs[b] + 1.5], [mx + 0.5, zs[b + 1] - 0.5], { main: false });
    avenue(c, RoadType.Paved, [xs[a] + 1.5, mz + 0.5], [xs[a + 1] - 0.5, mz + 0.5], { main: false });
  }
  // the great avenue: from the south gate straight up to the palace's gate, four lanes and a planted median
  const ax = Math.round(x0 + S / 2);
  const axis = avenue(c, RoadType.FourLane, [ax, z0 + S - 1], [ax, pz0 + pd], { main: true });
  c.ends(axis);
  // the walls: a watchtower at every corner and over every gate
  for (const [fx, fz] of [[0, 0], [1, 0], [0, 1], [1, 1], [0.5, 1], [0, 0.5], [1, 0.5]]) put(c, 'watchtower', { near: [x0 + 1 + fx * (S - 3), z0 + 1 + fz * (S - 3)], maxDist: 3 });
  // the roles: the palace (the hall), the East and West markets in mirror image, temples and pagodas on the wards
  c.anchors.seat = [ax + 0.5, pz0 + pd - 3];
  c.anchors.palace = [ax - 6, pz0 + pd - 3];
  c.anchors.garden = [ax + 6, pz0 + pd - 3];
  for (const side of [-1, 1]) put(c, 'marketHall', { near: [ax + side * S * 0.27, z0 + S * 0.6], maxDist: 5 });
  for (let k = 0; k < 4; k++) put(c, 'pagoda', { near: [x0 + S * (k & 1 ? 0.8 : 0.2), z0 + S * (k & 2 ? 0.82 : 0.42)], maxDist: 6 });
  c.dfAt = dfFlat(0.6);
  c.maxFloors = 6;
  finishTown(c, { grow: 0, parks: garden ? [garden] : [], axis });
  return true;
};

/** The Roman castrum: cardo and decumanus crossing at the forum, the insulae on a grid, the amphitheatre outside. */
function castrum(c: Layout, p: TownPlan): boolean {
  const S = p.size, x0 = p.x0, z0 = p.z0;
  const xs = gridLines(x0 + 2, x0 + S - 2, 6), zs = gridLines(z0 + 2, z0 + S - 2, 6);
  const fx = nearest(xs, x0 + S / 2), fz = nearest(zs, z0 + S / 2);
  gridAround(c, xs.filter((x) => x !== fx), zs.filter((z) => z !== fz), [[fx - 3, fz - 3, fx + 4, fz + 4]]);
  // the cardo and the decumanus, gate to gate
  const cardo = avenue(c, RoadType.TwoLane, [fx + 0.5, z0 + 0.5], [fx + 0.5, z0 + S - 0.5], { main: true, route: false });
  c.ends(cardo);
  c.ends(avenue(c, RoadType.TwoLane, [x0 + 0.5, fz + 0.5], [x0 + S - 0.5, fz + 0.5], { main: true, route: false }));
  c.anchors.seat = [fx + 3.5, fz + 3.5];
  c.anchors.market = [fx - 2.5, fz - 2.5];
  put(c, 'forum', { near: [fx - 3, fz + 3], maxDist: 4 });
  put(c, 'colosseum', { near: [x0 + S - 4, z0 + S - 4], maxDist: 8 }) ?? put(c, 'amphitheatre', { near: [x0 + S - 4, z0 + S - 4], maxDist: 8 });
  for (const [ax, az] of [[0, 0], [1, 0], [0, 1], [1, 1]]) put(c, 'watchtower', { near: [x0 + 1 + ax * (S - 3), z0 + 1 + az * (S - 3)], maxDist: 3 });
  c.dfAt = dfCores(c, [[fx, fz]], S * 0.6);
  c.maxFloors = 5;
  finishTown(c, { grow: 0, axis: cardo });
  return true;
}

// ---------------------------------------------------------------------------------------------
// San Francisco's grid over its hills

LAYERS.hillsgrid = (c, p, rng) => {
  const S = p.size, x0 = p.x0, z0 = p.z0, mega = p.kind === 'mega';
  const w = c.w;
  // the highest ground: the peak left with no streets, a park
  let hx = x0 + S / 2, hz = z0 + S / 2, hh = -Infinity;
  for (let z = z0 + 6; z < z0 + S - 6; z += 2) for (let x = x0 + 6; x < x0 + S - 6; x += 2) { const e = w.elev[idx(x, z)]; if (e > hh) { hh = e; hx = x; hz = z; } }
  const peak = discTiles(p, [[hx + 0.5, hz + 0.5, S * 0.07]], 2);
  for (const i of peak) if (!w.road[i]) w.flags[i] |= Flag.Poi;
  // the grid, laid straight over the hills: where a block is too steep for a street the street stops (the stairs)
  const g = mega ? 6 : 5;
  const xs = gridLines(x0, x0 + S, g), zs = gridLines(z0, z0 + S, g);
  const mxx = xs[xs.length >> 1], mzz = zs[zs.length >> 1];
  for (const x of xs) { const n = avenue(c, RoadType.TwoLane, [x + 0.5, z0 + 0.5], [x + 0.5, z0 + S - 0.5], { main: x === mxx, route: false }); if (x === mxx) c.ends(n); }
  for (const z of zs) { const n = avenue(c, RoadType.TwoLane, [x0 + 0.5, z + 0.5], [x0 + S - 0.5, z + 0.5], { main: z === mzz, route: false }); if (z === mzz) c.ends(n); }
  for (const i of peak) w.flags[i] &= ~Flag.Poi;
  reserve(c, peak);
  // Market Street: a divided diagonal from the waterfront corner up into the hills
  const side = p.carved?.seaSide ?? Math.floor(rng() * 4);
  const fromX = side === 0 ? x0 + S - 2 : side === 2 ? x0 + 1 : x0 + S * 0.8, fromZ = side === 1 ? z0 + S - 2 : side === 3 ? z0 + 1 : z0 + S * 0.8;
  const towardX = hx > fromX ? 1 : -1, towardZ = hz > fromZ ? 1 : -1;
  const k = Math.floor(Math.min(Math.abs(hx - fromX), Math.abs(hz - fromZ)) * 0.8);
  const market = avenue(c, RoadType.TwoLane, [fromX + 0.5, fromZ + 0.5], [fromX + 0.5 + towardX * k, fromZ + 0.5 + towardZ * k], { four: true });
  // the long park running out from the peak toward the far edge (Golden Gate Park)
  const gp = parkAt(c, Math.max(x0 + 3, Math.min(x0 + S - 28, hx - 26)), Math.min(z0 + S - 12, hz + S * 0.12), Math.min(26, Math.round(S * 0.32)), 8, rng);
  // the roles: the tower on the highest buildable ground, the hall at Market Street's foot, the towers there
  put(c, 'observationTower', { highest: true, zone: 'any' });
  c.anchors.seat = [fromX + towardX * 6, fromZ + towardZ * 3];
  c.anchors.landmark = [fromX + towardX * 3, fromZ + towardZ * 6];
  c.dfAt = dfCores(c, [[fromX + towardX * 4, fromZ + towardZ * 4]], S * 0.5);
  finishTown(c, { grow: 2, parks: gp ? [gp] : [], axis: market });
  return true;
};

CARVERS.hillsgrid = (p, ctx) => {
  (p.carved ??= {}).seaSide = nearestSeaSide(new Dig(p, ctx), 30);
  return true;
};

// ---------------------------------------------------------------------------------------------
// Milton Keynes's grid roads

CARVERS.gridroads = (p, ctx, rng) => {
  // the river its linear park follows, where one can be cut to the sea; and a balancing lake
  riverThrough(p, ctx, rng, { half: 1, amp: p.size * 0.1, off: 0.18 });
  const S = p.size;
  lakeOn(p, ctx, discTiles(p, [[p.x0 + S * 0.25, p.z0 + S * 0.25, S * 0.05]]));
  return true;
};

LAYERS.gridroads = (c, p, rng) => {
  const S = p.size, x0 = p.x0, z0 = p.z0, mega = p.kind === 'mega';
  const G = mega ? 21 : 19;
  const xs = gridLines(x0, x0 + S, G), zs = gridLines(z0, z0 + S, G);
  if (xs.length < 3 || zs.length < 3) return false;
  c.bridgeSpan = 6;
  // the grid roads, a roundabout at every crossing (the line stops at the ring and takes up again past it)
  for (const x of xs) for (const z of zs) ring(c, RoadType.TwoLane, x, z, 2, 0, { main: true });
  for (const x of xs) for (let b = 0; b + 1 < zs.length; b++) avenue(c, RoadType.TwoLane, [x + 0.5, zs[b] + 2.5], [x + 0.5, zs[b + 1] - 1.5], { main: true, bridge: true });
  for (const z of zs) for (let a = 0; a + 1 < xs.length; a++) avenue(c, RoadType.TwoLane, [xs[a] + 2.5, z + 0.5], [xs[a + 1] - 1.5, z + 0.5], { main: true, bridge: true });
  // and on out to the edge of town, the county's roads joining there
  for (const x of [xs[0], xs[xs.length - 1]]) { c.ends(avenue(c, RoadType.TwoLane, [x + 0.5, z0 + 0.5], [x + 0.5, zs[0] - 1.5], { main: true })); c.ends(avenue(c, RoadType.TwoLane, [x + 0.5, zs[zs.length - 1] + 2.5], [x + 0.5, z0 + S - 0.5], { main: true })); }
  // the centre: one square of the grid in a fine boulevard grid
  const ca = xs.length >> 1, cb = zs.length >> 1;
  const cx0 = xs[ca - 1] ?? xs[0], cx1 = xs[ca], cz0 = zs[cb - 1] ?? zs[0], cz1 = zs[cb];
  for (let x = cx0 + 5; x < cx1 - 2; x += 5) avenue(c, RoadType.TwoLane, [x + 0.5, cz0 + 1.5], [x + 0.5, cz1 - 0.5], { main: false });
  for (let z = cz0 + 5; z < cz1 - 2; z += 5) avenue(c, RoadType.TwoLane, [cx0 + 1.5, z + 0.5], [cx1 - 0.5, z + 0.5], { main: false });
  const centre: Pt = [(cx0 + cx1) / 2, (cz0 + cz1) / 2];
  // the linear park along the river: its banks kept open
  const r = p.carved?.river;
  if (r) {
    const band: number[] = [];
    const s0 = r.axis === 0 ? x0 : z0;
    for (let s = s0; s < s0 + S; s++) { const at = riverAt(p, s)!; for (let u = at - r.half - 3; u <= at + r.half + 3; u++) { const [x, z] = r.axis === 0 ? [s, u] : [u, s]; if (inB(x, z) && !c.w.road[idx(x, z)]) band.push(idx(x, z)); } }
    reserve(c, band);
  }
  // the roles: hall, mall and theatre in the centre; the pagoda by the lake
  c.anchors.seat = [centre[0] - 4, centre[1] - 4];
  c.anchors.landmark = [centre[0] + 3, centre[1] + 2];
  c.anchors.stadium = [xs[xs.length - 1] - 8, zs[zs.length - 1] - 8];
  put(c, 'pagoda', { near: [x0 + S * 0.25, z0 + S * 0.32], maxDist: 6 });
  c.dfAt = dfCores(c, [centre], S * 0.32);
  void rng;
  // the estates: curving streets and closes grown into each square off its grid roads
  finishTown(c, { grow: mega ? 46 : 26, growType: RoadType.Paved });
  return true;
};

// ---------------------------------------------------------------------------------------------
// Chicago's lakefront

CARVERS.lakefront = (p, ctx, rng) => {
  const S = p.size, dig = new Dig(p, ctx);
  const side = nearestSeaSide(dig, 30);
  if (side < 0) return false;
  // the river: in from the lake square to the shore, half the town deep, then forking along the shore both ways
  const F = (s: number, u: number): [number, number] => {
    // u: in from the shore side; s: along it
    switch (side) {
      case 0: return [p.x0 + S - 1 - u, p.z0 + s];
      case 1: return [p.x0 + s, p.z0 + S - 1 - u];
      case 2: return [p.x0 + u, p.z0 + s];
      default: return [p.x0 + s, p.z0 + u];
    }
  };
  const stemS = Math.round(S * (0.45 + (rng() - 0.5) * 0.1)), fork = Math.round(S * 0.5);
  for (let u = 0; u <= fork; u++) for (let o = -1; o <= 1; o++) { const [x, z] = F(stemS + o, u); dig.mark(x, z, 2); }
  for (const sgn of [-1, 1]) {
    for (let s = 0; s < S * 0.42; s++) {
      const bend = Math.round(s * 0.18);
      for (let o = -1; o <= 0; o++) { const [x, z] = F(stemS + sgn * s, fork + bend + o); dig.mark(x, z, 2); }
    }
  }
  // out to the lake from the stem's mouth
  const [mx, mz] = F(stemS, 0);
  if (!dig.toSea(mx, mz, side, 1) || !dig.clear()) return false;
  dig.commit();
  (p.carved ??= {}).seaSide = side;
  (p.carved.note ??= {}).stem = stemS;
  (p.carved.note ??= {}).fork = fork;
  return true;
};

LAYERS.lakefront = (c, p, rng) => {
  const S = p.size, x0 = p.x0, z0 = p.z0, mega = p.kind === 'mega';
  const side = p.carved?.seaSide;
  if (side === undefined) return false;
  const stem = p.carved?.note?.stem ?? S / 2, fork = p.carved?.note?.fork ?? S / 2;
  const F = (s: number, u: number): Pt => {
    switch (side) {
      case 0: return [x0 + S - 1 - u + 0.5, z0 + s + 0.5];
      case 1: return [x0 + s + 0.5, z0 + S - 1 - u + 0.5];
      case 2: return [x0 + u + 0.5, z0 + s + 0.5];
      default: return [x0 + s + 0.5, z0 + u + 0.5];
    }
  };
  c.bridgeSpan = 6;
  // the lakefront park: the whole shore kept as parkland, in a run of great parks
  const parks: ParkSite[] = [];
  for (let s = 3; s + 14 < S - 3; s += 16) {
    if (Math.abs(s + 7 - stem) < 9) continue;
    const [ax, az] = F(s, 1), [bx, bz] = F(s + 13, 6);
    const pk = parkAt(c, Math.min(ax, bx) - 0.5, Math.min(az, bz) - 0.5, Math.abs(bx - ax) + 1, Math.abs(bz - az) + 1, rng);
    if (pk) parks.push(pk);
  }
  // the grid, dense, bridged over the river at every street
  const g = mega ? 6 : 5;
  const xs = gridLines(x0, x0 + S, g), zs = gridLines(z0, z0 + S, g);
  gridAround(c, xs, zs, [], RoadType.TwoLane, { bridge: true });
  // Lake Shore Drive: four lanes along behind the parks
  const lsd = avenue(c, RoadType.FourLane, F(1, 9), F(S - 2, 9), { main: true, bridge: true });
  c.ends(lsd);
  // the roles: the towers in the fork (the Loop), the fountain and the stadium along the shore
  const loop = F(stem + 6, fork - 6);
  c.anchors.landmark = loop;
  c.anchors.seat = F(stem + 10, fork - 10);
  c.anchors.museum = F(stem - 10, 12);
  c.anchors.stadium = F(Math.round(S * 0.85), 14);
  c.anchors.garden = F(stem + 12, 4);
  c.dfAt = dfCores(c, [loop], S * 0.45);
  finishTown(c, { grow: 0, parks, axis: lsd });
  return true;
};

