import type { Building, BuildingKind } from './tiles';

/**
 * Which parts of some biome buildings block vehicles, in the model's local frame (origin mid-lot,
 * +z the way it faces, W across and D deep). Kinds left out fill their lot. See footprint.ts.
 */
type Solid = (lx: number, lz: number) => boolean;
export const boxes = (...list: { x: number; z: number; w: number; d: number }[]): Solid =>
  (lx, lz) => list.some((p) => Math.abs(lx - p.x) <= p.w / 2 && Math.abs(lz - p.z) <= p.d / 2);

export const REGION_SHAPES_B: Partial<Record<BuildingKind, (W: number, D: number, b: Building) => Solid>> = {
  // ---- the Green ----
  // the drying shed along the back; the patio in front is flat
  plantation: (W, D) => boxes({ x: 0, z: -D / 2 + 0.5, w: W - 0.1, d: 0.9 }),
  // the pyramid with its projecting stair, and the two platforms; the causeway is open
  lostTemple: () => boxes(
    { x: 0, z: -1.5, w: 7, d: 7 }, { x: 0, z: 2.6, w: 2.2, d: 1.3 },
    { x: -4.8, z: 1.3, w: 2.2, d: 3.6 }, { x: 4.8, z: 1.3, w: 2.2, d: 3.6 },
  ),
  // ---- the Heights ----
  mountainHut: () => boxes({ x: -0.15, z: -0.25, w: 1.5, d: 1.0 }),
  dairy: (W, D) => boxes({ x: 0, z: -0.3, w: 1.5, d: 1.0 }, { x: W / 2 - 0.35, z: D / 2 - 0.35, w: 0.6, d: 0.54 }),
  // the parapet rows either side; the four rows of crest between them carry the road
  dam: () => (_x, z) => Math.abs(z) > 2.05,
  // ---- the Moors ----
  distillery: (W, D) => boxes({ x: 0, z: -D / 2 + 0.4, w: W - 0.25, d: 0.6 }, { x: 0.35, z: 0.35, w: 0.9, d: 0.6 }),
  // the curtain wall, its towers, the keep and the hall; the gate passage and the bailey are open
  castle: () => {
    const e = 5.2;
    const inner = boxes({ x: -1.4, z: -2.2, w: 3.0, d: 2.6 }, { x: 2.9, z: -3.2, w: 2.5, d: 1.4 });
    return (x, z) => {
      if (z > 4 && Math.abs(x) < 1) return false;
      const ring = Math.max(Math.abs(x), Math.abs(z)) >= e - 0.3;
      const tower = Math.hypot(Math.abs(x) - e, Math.abs(z) - e) <= 0.8;
      return ring || tower || inner(x, z);
    };
  },
};
