import { hex, scale, type RGB } from '../../world/biomes';
import { mulberry32, type Rng } from '../../world/rng';
import { DARK, METAL, TAU, WHITE, WOOD, type Kit, type P3 } from './kit';

/**
 * Concession stands: an ice-cream kiosk under a giant cone, a hot-dog cart under a big umbrella, a snack shack with
 * a fold-up awning and a menu board, a lemonade stand, a crêpe hut. Each faces +z in its own frame, with a short queue
 * in front, a bin beside it and maybe a picnic table or two.
 *
 * A stand is drawn in three passes from one seed (so every pass makes the same choices): the stand itself, what is
 * out only while it is open (the queue, the vendor at the hatch, the awning propped up, people at the tables) and
 * what only shows once it has shut (shutters, a cover). `concessionRow` puts the open and shut passes of every stand
 * it is given into one rig of two parts, swapped by the hour; `concession` draws one stand open, all static.
 */

type ConcessionKind = 'iceCream' | 'hotDog' | 'snack' | 'lemonade' | 'crepe';
export const CONCESSIONS: readonly ConcessionKind[] = ['iceCream', 'hotDog', 'snack', 'lemonade', 'crepe'];
/** The hours a stand is open: its queue and vendor are out from the first to the second. */
const CONCESSION_HOURS: [number, number] = [9, 20];

type Part = 'all' | 'stand' | 'day' | 'night';

const SKIN = [0xf1c7a1, 0xd9a07a, 0x9a6a48, 0x6a4632, 0xf4d9bf];
const TOPS = [0xe2412f, 0x2f7fb5, 0xf2c14e, 0x3f9b4a, 0xf4f2ec, 0x8e5cc7, 0xff7fae, 0x2bb3a3, 0xf2a93b];
const LEGS = [0x3a4a6a, 0x2e3440, 0x5a4a3a, 0x6a6f78, 0x8a7a5a];
const BIN = hex(0x2f6a45), BIN_LID = hex(0x24543a), HATCH = hex(0x2e2a28), SHUTTER = hex(0xc9ccd0);
const PASTELS = [0xf6b8c8, 0xbfe8d0, 0xf6e7a8, 0xc9dcf2];
const SCOOPS = [0xf6b8c8, 0xf4ecd8, 0x8a5a3a, 0xbfe8d0];

const pickc = (r: Rng, a: readonly number[]): RGB => hex(a[Math.floor(r() * a.length) % a.length]);

/** A person standing at (x, z), about 1.8 m to a car's 4 (a child a good deal shorter). */
function standingPerson(k: Kit, x: number, z: number, top: RGB, skin: RGB, legs: RGB, kid = false): void {
  const s = kid ? 0.7 : 1;
  k.box(x, 0, z, 0.03 * s, 0.045 * s, 0.022 * s, legs);
  k.box(x, 0.045 * s, z, 0.036 * s, 0.045 * s, 0.026 * s, top);
  k.box(x, 0.09 * s, z, 0.026 * s, 0.026 * s, 0.026 * s, skin);
}

/** Someone sitting on a bench whose seat is at y. */
function seatedPerson(k: Kit, x: number, y: number, z: number, top: RGB, skin: RGB): void {
  k.box(x, y, z, 0.034, 0.042, 0.024, top);
  k.box(x, y + 0.042, z, 0.025, 0.025, 0.025, skin);
}

/** A disc standing on its edge: a wheel (axis 'x' or 'z'), a round sign; `cap` colours its two faces. */
export function drum(k: Kit, x: number, y: number, z: number, r: number, t: number, col: RGB, axis: 'x' | 'z', cap: RGB = col, seg = 10): void {
  const at = (a: number, s: number): P3 => axis === 'x'
    ? [x + (s * t) / 2, y + Math.sin(a) * r, z + Math.cos(a) * r]
    : [x + Math.cos(a) * r, y + Math.sin(a) * r, z + (s * t) / 2];
  const I: P3 = [x, y, z];
  for (let i = 0; i < seg; i++) {
    const a0 = (i / seg) * TAU, a1 = ((i + 1) / seg) * TAU;
    k.quad(at(a0, -1), at(a1, -1), at(a1, 1), at(a0, 1), col, I);
    for (const s of [-1, 1]) k.tri(axis === 'x' ? [x + (s * t) / 2, y, z] : [x, y, z + (s * t) / 2], at(a0, s), at(a1, s), cap, I);
  }
}

/** A striped canopy sloping from the wall (z0, y0) out to (z1, y1), with a scalloped valance along its edge. */
function awning(k: Kit, x: number, w: number, z0: number, y0: number, z1: number, y1: number, a: RGB, b: RGB, n: number): void {
  const sw = w / n;
  for (let i = 0; i < n; i++) {
    const xa = x - w / 2 + i * sw, xb = xa + sw, xm = (xa + xb) / 2, col = i % 2 ? b : a;
    k.quad([xa, y0, z0], [xb, y0, z0], [xb, y1, z1], [xa, y1, z1], col, [xm, Math.min(y0, y1) - 0.2, (z0 + z1) / 2]);
    k.tri([xa, y1, z1], [xb, y1, z1], [xm, y1 - 0.022, z1], col, [xm, y1 - 0.01, z1 - 0.1]);
  }
}

/** A striped umbrella: a low cone of alternating panels on (x, y, z), its rim at y. */
export function brolly(k: Kit, x: number, y: number, z: number, R: number, h: number, a: RGB, b: RGB, seg = 8): void {
  const A: P3 = [x, y + h, z], I: P3 = [x, y + h / 4, z];
  for (let s = 0; s < seg; s++) {
    const a0 = (s / seg) * TAU, a1 = ((s + 1) / seg) * TAU;
    k.tri([x + Math.cos(a0) * R, y, z + Math.sin(a0) * R], [x + Math.cos(a1) * R, y, z + Math.sin(a1) * R], A, s % 2 ? b : a, I);
  }
}

function bin(k: Kit, x: number, z: number): void {
  k.cyl(x, 0, z, 0.026, 0.075, BIN, 8);
  k.cyl(x, 0.075, z, 0.029, 0.008, BIN_LID, 8);
}

/** A picnic table along x with its two benches. */
function picnic(k: Kit, x: number, z: number, wood: RGB): void {
  const leg = scale(wood, 0.8);
  k.box(x, 0.06, z, 0.17, 0.01, 0.08, wood);
  for (const s of [-1, 1]) k.box(x + s * 0.065, 0, z, 0.012, 0.06, 0.07, leg);
  for (const s of [-1, 1]) {
    k.box(x, 0.035, z + s * 0.075, 0.17, 0.008, 0.03, wood);
    for (const t of [-1, 1]) k.box(x + t * 0.065, 0, z + s * 0.075, 0.01, 0.035, 0.02, leg);
  }
}

/** The choices one stand makes, all drawn from its seed before anything is drawn, so every pass agrees. */
interface Look {
  wall: RGB; trim: RGB; roof: RGB; stripe: RGB; sign: RGB; scoop: RGB; scoop2: RGB;
  queue: { x: number; z: number; top: RGB; skin: RGB; legs: RGB; kid: boolean }[];
  vendor: { top: RGB; skin: RGB };
  tables: { x: number; z: number; diners: { x: number; s: number; top: RGB; skin: RGB }[] }[];
  binX: number;
}

/** Where the queue stands, from the front of the stand outward, bending away to one side. */
const QUEUE: [number, number][] = [[0, 0.085], [0.015, 0.165], [0.06, 0.235], [0.13, 0.27]];

function lookOf(v: ConcessionKind, r: Rng, front: number, tables: [number, number][]): Look {
  const side = r() < 0.5 ? -1 : 1;
  const n = 2 + Math.floor(r() * 3);
  const person = () => ({ top: pickc(r, TOPS), skin: pickc(r, SKIN), legs: pickc(r, LEGS) });
  const queue = QUEUE.slice(0, n).map(([x, z]) => ({ x: x * side, z: front + z, ...person(), kid: r() < 0.2 }));
  const vendor = { top: v === 'iceCream' || v === 'crepe' ? WHITE : pickc(r, TOPS), skin: pickc(r, SKIN) };
  const tbl = tables.map(([x, z]) => {
    const diners: Look['tables'][number]['diners'] = [];
    for (const s of [-1, 1]) for (const dx of [-0.045, 0.045]) if (r() < 0.35) diners.push({ x: dx, s, top: pickc(r, TOPS), skin: pickc(r, SKIN) });
    return { x, z, diners };
  });
  const wall = v === 'iceCream' ? pickc(r, PASTELS) : v === 'snack' ? pickc(r, [0x7fc4d8, 0xf4f2ec, 0xe8d3b0, 0xdbe8c9]) : v === 'crepe' ? pickc(r, [0x2f5f9e, 0x3f7d5a, 0x8a3a3a]) : WOOD;
  const stripe = v === 'iceCream' ? pickc(r, [0xe8608a, 0x5ab8a0, 0x7aa6e0]) : v === 'crepe' ? pickc(r, [0x2f5f9e, 0xd23a3a]) : v === 'lemonade' ? hex(0xf2d23b) : pickc(r, [0xe2412f, 0x2f7fb5, 0xf2a93b, 0x3f9b4a]);
  return {
    wall, trim: WHITE, roof: pickc(r, [0x8a3a2e, 0x4f6b4a, 0x5a5f6b, 0x3f5a73]), stripe,
    sign: pickc(r, [0xe2412f, 0xf2c14e, 0x2f7fb5]), scoop: pickc(r, SCOOPS), scoop2: pickc(r, SCOOPS),
    queue, vendor, tables: tbl, binX: (0.2 + r() * 0.03) * -side,
  };
}

/** How far in front of its middle a stand's counter is: where its queue begins. */
const FRONT: Record<ConcessionKind, number> = { iceCream: 0.13, hotDog: 0.1, snack: 0.17, lemonade: 0.09, crepe: 0.13 };

/** One pass of one stand, facing +z in its own frame at (x, z). */
function drawStand(k: Kit, x: number, z: number, v: ConcessionKind, L: Look, part: Part): void {
  const S = part === 'all' || part === 'stand', D = part === 'all' || part === 'day', N = part === 'night';
  // the vendor at the hatch: a head and shoulders standing in the opening
  const atHatch = (y: number, zf: number) => {
    k.box(x - 0.03, y, z + zf, 0.044, 0.04, 0.012, L.vendor.top);
    k.box(x - 0.03, y + 0.04, z + zf, 0.026, 0.026, 0.014, L.vendor.skin);
  };
  switch (v) {
    case 'iceCream': {
      if (S) {
        k.box(x, 0, z, 0.3, 0.2, 0.22, L.wall);
        k.box(x, 0, z, 0.31, 0.03, 0.23, L.trim);
        k.box(x, 0.2, z, 0.33, 0.025, 0.25, WHITE);
        k.box(x, 0.075, z + 0.11, 0.2, 0.085, 0.008, HATCH);
        k.box(x, 0.07, z + 0.125, 0.22, 0.01, 0.035, WHITE);
        awning(k, x, 0.27, z + 0.111, 0.192, z + 0.2, 0.158, L.stripe, WHITE, 6);
        // the giant cone on the roof, standing on its point
        k.cyl(x, 0.225, z, 0.008, 0.01, DARK, 5);
        k.cone(x, 0.36, z, 0.045, -0.13, hex(0xd9a35a), 8);
        k.dome(x, 0.36, z, 0.052, L.scoop, 8, 3);
        k.dome(x, 0.395, z, 0.034, L.scoop2, 8, 2);
        k.box(x, 0.426, z, 0.014, 0.014, 0.014, hex(0xd2243a));
        k.box(x + 0.153, 0.07, z, 0.006, 0.08, 0.1, L.stripe);
        bin(k, x + L.binX, z + 0.1);
      }
      if (D) atHatch(0.08, 0.121);
      if (N) k.box(x, 0.073, z + 0.118, 0.206, 0.09, 0.008, SHUTTER);
      break;
    }
    case 'hotDog': {
      if (S) {
        k.box(x, 0.05, z, 0.24, 0.085, 0.13, METAL);
        k.box(x, 0.055, z + 0.067, 0.22, 0.07, 0.006, L.sign);
        k.box(x, 0.08, z + 0.071, 0.22, 0.012, 0.004, hex(0xf2c14e));
        k.box(x, 0.135, z, 0.2, 0.01, 0.1, DARK);
        for (const s of [-1, 1]) drum(k, x + 0.05, 0.045, z + s * 0.078, 0.045, 0.012, DARK, 'z', METAL);
        k.box(x - 0.1, 0, z, 0.016, 0.05, 0.016, DARK);
        k.bar([x - 0.12, 0.12, z - 0.04], [x - 0.17, 0.15, z - 0.04], 0.005, DARK);
        k.bar([x - 0.12, 0.12, z + 0.04], [x - 0.17, 0.15, z + 0.04], 0.005, DARK);
        k.bar([x - 0.17, 0.15, z - 0.045], [x - 0.17, 0.15, z + 0.045], 0.006, DARK);
        // the big umbrella, and a hot dog on top of it
        k.box(x, 0.135, z - 0.058, 0.012, 0.21, 0.012, WHITE);
        brolly(k, x, 0.33, z - 0.058, 0.23, 0.07, hex(0xe2412f), hex(0xf2c14e));
        k.bar([x - 0.05, 0.415, z - 0.058], [x + 0.05, 0.415, z - 0.058], 0.016, hex(0xe0b070));
        k.bar([x - 0.064, 0.427, z - 0.058], [x + 0.064, 0.427, z - 0.058], 0.0095, hex(0xb2452e));
        k.bar([x - 0.04, 0.438, z - 0.058], [x + 0.04, 0.438, z - 0.058], 0.003, hex(0xf2c14e));
        k.box(x + 0.085, 0.145, z + 0.035, 0.012, 0.03, 0.012, hex(0xe2412f));
        k.box(x + 0.065, 0.145, z + 0.035, 0.012, 0.03, 0.012, hex(0xf2c14e));
        bin(k, x + L.binX, z + 0.06);
      }
      if (D) {
        standingPerson(k, x - 0.02, z - 0.115, L.vendor.top, L.vendor.skin, hex(0x2e3440));
        for (const s of [-0.05, 0, 0.05]) k.box(x + s, 0.145, z, 0.035, 0.012, 0.018, hex(0xe0b070));
      }
      if (N) k.box(x, 0.135, z, 0.21, 0.025, 0.11, hex(0x5a6a7a));
      break;
    }
    case 'snack': {
      if (S) {
        k.box(x, 0, z, 0.38, 0.22, 0.26, L.wall);
        k.gable(x, 0.22, z, 0.42, 0.09, 0.3, L.roof, L.wall);
        k.box(x, 0.07, z + 0.13, 0.26, 0.1, 0.008, HATCH);
        k.box(x, 0.065, z + 0.15, 0.28, 0.01, 0.04, WOOD);
        // the sign board across the ridge
        k.box(x, 0.29, z, 0.26, 0.065, 0.014, L.sign);
        k.box(x, 0.315, z + 0.0085, 0.2, 0.014, 0.004, WHITE);
        k.box(x, 0.315, z - 0.0085, 0.2, 0.014, 0.004, WHITE);
        // the menu board
        const bx = x - L.binX * 1.3, bz = z + 0.16;
        for (const s of [-1, 1]) k.bar([bx + s * 0.04, 0, bz - 0.02], [bx + s * 0.04, 0.14, bz], 0.004, WOOD);
        k.box(bx, 0.025, bz, 0.09, 0.11, 0.01, hex(0x2f3a34));
        for (let i = 0; i < 4; i++) k.box(bx - 0.005, 0.045 + i * 0.022, bz + 0.0065, 0.06 - (i % 2) * 0.016, 0.005, 0.003, WHITE);
        k.box(bx, 0.135, bz, 0.095, 0.01, 0.012, WOOD);
        bin(k, x + L.binX * 1.2, z + 0.06);
      }
      if (D) {
        // the awning folded up over the counter on two struts
        const y0 = 0.178, z0 = z + 0.134, y1 = 0.228, z1 = z + 0.275, w = 0.28;
        const flap = L.stripe;
        k.quad([x - w / 2, y0, z0], [x + w / 2, y0, z0], [x + w / 2, y1, z1], [x - w / 2, y1, z1], flap, [x, y0 - 0.2, (z0 + z1) / 2]);
        k.quad([x - w / 2, y0, z0], [x + w / 2, y0, z0], [x + w / 2, y1, z1], [x - w / 2, y1, z1], scale(flap, 0.8), [x, y0 + 0.2, (z0 + z1) / 2]);
        for (const s of [-1, 1]) k.bar([x + s * 0.12, 0.075, z + 0.155], [x + s * 0.12, 0.222, z + 0.26], 0.003, DARK);
        atHatch(0.08, 0.141);
      }
      if (N) k.box(x, 0.064, z + 0.138, 0.28, 0.118, 0.008, L.stripe);
      break;
    }
    case 'lemonade': {
      if (S) {
        k.box(x, 0, z, 0.28, 0.11, 0.14, WOOD);
        k.box(x, 0.015, z + 0.072, 0.26, 0.08, 0.006, hex(0xf2d23b));
        k.box(x, 0.05, z + 0.0765, 0.26, 0.012, 0.004, WHITE);
        for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.box(x + sx * 0.128, 0.11, z + sz * 0.058, 0.012, 0.15, 0.012, WHITE);
        for (let i = 0; i < 5; i++) {
          const c = i % 2 ? WHITE : L.stripe;
          k.gable(x + (i - 2) * 0.064, 0.26, z, 0.064, 0.05, 0.2, c, c);
        }
        // the lemon-slice sign on its post
        k.box(x + 0.09, 0.3, z, 0.01, 0.04, 0.01, WHITE);
        drum(k, x + 0.09, 0.385, z, 0.048, 0.014, hex(0xf2c81e), 'z', hex(0xfbeea0), 12);
        for (let i = 0; i < 3; i++) {
          const a = (i / 3) * Math.PI, dx = Math.cos(a) * 0.036, dy = Math.sin(a) * 0.036;
          for (const s of [-1, 1]) k.bar([x + 0.09 - dx, 0.385 - dy, z + s * 0.0085], [x + 0.09 + dx, 0.385 + dy, z + s * 0.0085], 0.002, hex(0xe8b81a));
        }
        k.cyl(x - 0.07, 0.11, z - 0.01, 0.022, 0.05, hex(0xf6e7a0), 8);
        k.cyl(x - 0.07, 0.16, z - 0.01, 0.024, 0.008, WHITE, 8);
        for (const s of [0, 0.03, 0.06]) k.cyl(x + 0.0 + s, 0.11, z + 0.03, 0.009, 0.022, WHITE, 6);
        bin(k, x + L.binX, z + 0.05);
      }
      if (D) standingPerson(k, x + 0.02, z - 0.115, L.vendor.top, L.vendor.skin, hex(0x3a4a6a), true);
      if (N) k.box(x, 0.022, z + 0.081, 0.12, 0.05, 0.006, WHITE);
      break;
    }
    case 'crepe': {
      if (S) {
        k.box(x, 0, z, 0.3, 0.2, 0.22, L.wall);
        k.box(x, 0, z, 0.31, 0.025, 0.23, WHITE);
        k.gable(x, 0.2, z, 0.34, 0.14, 0.27, L.roof, L.wall);
        k.box(x, 0.075, z + 0.11, 0.2, 0.085, 0.008, HATCH);
        k.box(x, 0.07, z + 0.125, 0.22, 0.01, 0.035, WOOD);
        awning(k, x, 0.26, z + 0.111, 0.185, z + 0.19, 0.152, L.stripe, WHITE, 6);
        // the round crêpe on the ridge, chocolate over it
        const cy = 0.4;
        drum(k, x, cy, z, 0.064, 0.012, hex(0xd9a35a), 'z', hex(0xf0cf8e), 12);
        for (const s of [-1, 1]) for (const [dx, dy] of [[-0.03, 0.01], [0, -0.012], [0.028, 0.016]]) {
          k.bar([x + dx - 0.018, cy + dy - 0.006, z + s * 0.0075], [x + dx + 0.018, cy + dy + 0.006, z + s * 0.0075], 0.003, hex(0x5a3222));
        }
        // churros in a cup on the counter
        k.cyl(x + 0.075, 0.08, z + 0.13, 0.013, 0.02, hex(0xd2243a), 6);
        for (const [dx, dz] of [[-0.005, 0], [0.005, 0.004], [0, -0.005]]) k.bar([x + 0.075 + dx, 0.09, z + 0.13 + dz], [x + 0.075 + dx * 3, 0.14, z + 0.13 + dz * 3], 0.003, hex(0xc8873a));
        bin(k, x + L.binX, z + 0.1);
      }
      if (D) atHatch(0.08, 0.121);
      if (N) k.box(x, 0.073, z + 0.118, 0.206, 0.09, 0.008, SHUTTER);
      break;
    }
  }
  // the queue, and anyone sitting at the tables
  if (D) for (const q of L.queue) standingPerson(k, x + q.x, z + q.z, q.top, q.skin, q.legs, q.kid);
  for (const t of L.tables) {
    if (S) picnic(k, x + t.x, z + t.z, WOOD);
    if (D) for (const d of t.diners) seatedPerson(k, x + t.x + d.x, 0.043, z + t.z + d.s * 0.075, d.top, d.skin);
  }
}

/** One pass of a stand at (x, z) turned by yaw (its front, +z, then faces (sin yaw, cos yaw)). */
function concessionPart(k: Kit, x: number, z: number, yaw: number, seed: number, variant: ConcessionKind, part: Part, tables: [number, number][] = []): void {
  const L = lookOf(variant, mulberry32(seed), FRONT[variant], tables);
  const c = Math.cos(yaw), s = Math.sin(yaw);
  k.turned(yaw, () => drawStand(k, x * c - z * s, x * s + z * c, variant, L, part));
}

/** One stand, open and all static: the stand, its queue and vendor (`r` picks the variant when none is asked for). */
export function concession(k: Kit, x: number, z: number, yaw: number, r: Rng, variant?: ConcessionKind, tables: [number, number][] = []): void {
  const v = variant ?? CONCESSIONS[Math.floor(r() * CONCESSIONS.length) % CONCESSIONS.length];
  concessionPart(k, x, z, yaw, Math.floor(r() * 4294967296), v, 'all', tables);
}

export interface StandSpot { x: number; z: number; yaw: number; variant: ConcessionKind; seed: number; tables: [number, number][] }

/**
 * Several stands in one model: the stands drawn into the model itself, and what comes and goes with the hour
 * (queues, vendors, propped awnings / shutters and covers) in one rig of two parts for all of them.
 */
export function concessionRow(k: Kit, spots: StandSpot[], hours: [number, number] = CONCESSION_HOURS): void {
  if (!spots.length) return;
  for (const s of spots) concessionPart(k, s.x, s.z, s.yaw, s.seed, s.variant, 'stand', s.tables);
  k.rig(0, 0, 0, [
    (q) => { for (const s of spots) concessionPart(q, s.x, s.z, s.yaw, s.seed, s.variant, 'day', s.tables); },
    (q) => { for (const s of spots) concessionPart(q, s.x, s.z, s.yaw, s.seed, s.variant, 'night', s.tables); },
  ], (parts, _dt, hour) => {
    const open = hour >= hours[0] && hour < hours[1];
    parts[0].visible = open;
    parts[1].visible = !open;
  });
}
