import * as THREE from 'three';
import { heightAt, type Arch, type Building, type BuildingKind, type Town, World } from '../../world/tiles';
import { hex, mix, scale, type RGB } from '../../world/biomes';
import type { Rng } from '../../world/rng';
import { FLOOR } from '../../world/towns';
import { GlowBuf, NEVER, VIS, Vis, visShader, visDepthMaterial, type Sched } from '../nightLights';
import { SIGN_WORDS, glyphMaterial, glyphUv } from './signGlyphs';
import { osakaDress } from './osakaSigns';
import { stripSigns } from './stripSigns';
import { xrayShader } from '../xray';
import { eventLightShader } from '../eventLights';

/**
 * The drawing kit every building is made from: flat-coloured primitives in a building's local frame,
 * the eight architectural styles, window schedules, and the few shared pieces (a tower, a crown, a
 * car, a tree, a portico) most models are built out of. The models themselves live beside it, one
 * file per group, and `townMesh.ts` turns them into chunk geometry.
 */

export const townMaterial = new THREE.MeshStandardMaterial({ vertexColors: true, flatShading: true, roughness: 0.82, metalness: 0, transparent: true });
townMaterial.onBeforeCompile = (shader) => { xrayShader(shader); visShader(shader); eventLightShader(shader); };

export type P3 = [number, number, number];
export const TAU = Math.PI * 2;
/** A glyph's tint when none is asked for: the atlas's own white. */
const GLYPH_WHITE: RGB = [1, 1, 1];

// ---------------------------------------------------------------------------------------------
// moving parts

/** How a moving part turns: steadily, or as the hour or minute hand of the day clock. */
type SpinMode = 'turn' | 'hour' | 'minute' | 'geyser';

interface Spinner { obj: THREE.Object3D; axis: 'x' | 'y' | 'z'; speed: number; mode: SpinMode; tag: Vis }

/**
 * Every moving part in the scene: a ferris wheel, windmill and turbine sails, clock hands. They are
 * the one thing chunk geometry cannot do, so each is its own small mesh, turned in the frame loop.
 */
const SPINNERS = new Set<Spinner>();

function attached(o: THREE.Object3D): boolean {
  let p: THREE.Object3D | null = o;
  while (p) {
    if ((p as THREE.Scene).isScene) return true;
    p = p.parent;
  }
  return false;
}

/**
 * A ride: several parts, each its own small mesh in one frame, moved every frame by a tick of its own
 * (a ferris wheel and its level-hanging gondolas, a carousel and its bobbing horses, a coaster's cars).
 */
export type RigTick = (parts: THREE.Object3D[], dt: number, hour: number) => void;
interface Rig { root: THREE.Object3D; parts: THREE.Object3D[]; tick: RigTick; tag: Vis }
const RIGS = new Set<Rig>();

/** A moving part a kit has drawn, kept with the kit until the group meshes() hands out is shown. */
type Mover = { spinner: Spinner } | { rig: Rig };

/**
 * Put a model's moving parts (back) in the frame loop: called whenever the group holding them is added
 * to a parent. Only what is in the scene is turned, so a chunk the stream holds out of it (its shaders
 * still compiling, or kept spare after the view has left it) falls out of the lists, and comes back
 * here when it is shown again. A part used to leave the lists for good the first frame it was found
 * out of the scene, and since chunks wait out of it for their shaders and come and go as the camera
 * turns, the rides were all but always dropped before they were ever seen to move.
 */
function wake(movers: Mover[]): void {
  for (const m of movers) {
    if ('spinner' in m) SPINNERS.add(m.spinner);
    else RIGS.add(m.rig);
  }
}

/** Turn every moving part in the scene; let go of the ones that have left it (see wake). */
let clock = 0;

export function animateParts(dt: number, hour: number): void {
  clock += dt;
  for (const sp of SPINNERS) {
    if (!attached(sp.obj)) { SPINNERS.delete(sp); continue; }
    sp.obj.visible = VIS.uVis.value[sp.tag] > 0.5;
    if (sp.mode === 'geyser') {
      // quiet for most of a minute or two, then a plume that shoots up and falls back over eight seconds
      const period = 50 + (sp.speed % 40), phase = (clock + sp.speed) % period;
      const up = phase < 8 ? Math.sin((Math.PI * phase) / 8) : 0;
      sp.obj.scale.set(0.6 + up * 0.4, Math.max(0.01, up), 0.6 + up * 0.4);
      sp.obj.visible = sp.obj.visible && up > 0.02;
    } else if (sp.mode === 'turn') sp.obj.rotation[sp.axis] += sp.speed * dt;
    else if (sp.mode === 'hour') sp.obj.rotation[sp.axis] = -((hour % 12) / 12) * TAU;
    else sp.obj.rotation[sp.axis] = -(hour % 1) * TAU;
  }
  for (const rg of RIGS) {
    if (!attached(rg.root)) { RIGS.delete(rg); continue; }
    rg.root.visible = VIS.uVis.value[rg.tag] > 0.5;
    if (rg.root.visible) rg.tick(rg.parts, Math.min(dt, 0.1), hour);
  }
}

/**
 * Appends flat-coloured primitives in a building's local frame (front = +z) to one vertex buffer,
 * and windows / lights that glow after dark to a second.
 */
/**
 * Faces a building draws in the same plane as another, facing the same way, overlapping it and in another
 * colour (a door laid flush on a wall, a roof slab level with a parapet's top): the depth buffer can't tell
 * them apart, so which one shows changes as the camera moves, and the building flashes. `settleFights` lifts
 * each such face off the one under it by FIGHT_LIFT along its normal, a layer at a time, the face drawn later
 * on top (what was drawn later was meant to sit on what was there). Found by `npm run zfight`.
 */
/** Same plane within this, world units. */
const FIGHT_PLANE = 4e-4;
/** A layer's lift. The depth buffer resolves this out to about 300 units from the camera (near plane 2); an odd step (0.0033) was tried and collided with more of the models' own decal offsets. */
const FIGHT_LIFT = 4e-3;

export function settleFights(bufs: { pos: number[]; col: number[]; from: number }[]): number {
  // every triangle from each buffer's `from` on, in the order drawn (solid first, then its surface detail)
  let n = 0;
  for (const b of bufs) n += Math.max(0, b.pos.length / 9 - b.from);
  if (n < 2) return 0;
  const buf = new Uint8Array(n), tri = new Int32Array(n), col = new Int32Array(n);
  const nx = new Float64Array(n), ny = new Float64Array(n), nz = new Float64Array(n), dd = new Float64Array(n);
  const key = new Int32Array(n);
  let m = 0;
  for (let bi = 0; bi < bufs.length; bi++) {
    const p = bufs[bi].pos, c = bufs[bi].col;
    for (let t = bufs[bi].from, T = p.length / 9; t < T; t++) {
      const i = t * 9;
      const ux = p[i + 3] - p[i], uy = p[i + 4] - p[i + 1], uz = p[i + 5] - p[i + 2];
      const vx = p[i + 6] - p[i], vy = p[i + 7] - p[i + 1], vz = p[i + 8] - p[i + 2];
      let cx = uy * vz - uz * vy, cy = uz * vx - ux * vz, cz = ux * vy - uy * vx;
      const L = Math.hypot(cx, cy, cz);
      if (L < 1e-9) continue;
      cx /= L; cy /= L; cz /= L;
      buf[m] = bi; tri[m] = t; nx[m] = cx; ny[m] = cy; nz[m] = cz;
      dd[m] = cx * p[i] + cy * p[i + 1] + cz * p[i + 2];
      key[m] = ((Math.round(cx * 200) + 200) * 401 + (Math.round(cy * 200) + 200)) * 401 + (Math.round(cz * 200) + 200);
      col[m] = Math.round(c[i] * 255) * 65536 + Math.round(c[i + 1] * 255) * 256 + Math.round(c[i + 2] * 255);
      m++;
    }
  }
  // pass one over every face; then, while anything moved, again over just the faces in the planes the lifted
  // ones moved into (a lifted face can land on a decal the model drew a layer up)
  let pick: Int32Array = new Int32Array(m);
  for (let k = 0; k < m; k++) pick[k] = k;
  let lifted = 0;
  for (let pass = 0; pass < 4 && pick.length > 1; pass++) {
    const order = pick.slice().sort((a, b) => key[a] - key[b] || dd[a] - dd[b]);
    const layer = new Int32Array(m);
    const moved: number[] = [];
    for (let s = 0; s < order.length;) {
      let e = s + 1, mixed = false;
      const c0 = col[order[s]];
      while (e < order.length && key[order[e]] === key[order[s]] && dd[order[e]] - dd[order[e - 1]] < FIGHT_PLANE) { if (col[order[e]] !== c0) mixed = true; e++; }
      if (mixed) {
        const g = order.subarray(s, e);
        if (settleGroup(bufs, g, buf, tri, col, nx, ny, nz, layer)) for (const k of g) if (layer[k]) { dd[k] += layer[k] * FIGHT_LIFT; moved.push(k); }
      }
      s = e;
    }
    lifted += moved.length;
    if (!moved.length || pass === 3) break;
    // the faces now sharing a plane with a moved one: every face of the same facing within FIGHT_PLANE of where it went
    const at = new Map<number, number[]>();
    for (const k of moved) { let l = at.get(key[k]); if (!l) at.set(key[k], (l = [])); l.push(dd[k]); }
    for (const l of at.values()) l.sort((a, b) => a - b);
    const next: number[] = [];
    for (let k = 0; k < m; k++) {
      const l = at.get(key[k]);
      if (!l) continue;
      let lo = 0, hi = l.length;
      while (lo < hi) { const mid = (lo + hi) >> 1; if (l[mid] < dd[k] - FIGHT_PLANE) lo = mid + 1; else hi = mid; }
      if (lo < l.length && l[lo] <= dd[k] + FIGHT_PLANE) next.push(k);
    }
    pick = Int32Array.from(next);
  }
  return lifted;
}

/**
 * One plane's faces: each laid flat, the pairs whose bounds overlap found by a sweep along one axis, and then,
 * in the order drawn, each face put a layer above the highest earlier face of another colour it really overlaps.
 */
function settleGroup(bufs: { pos: number[] }[], ks: Int32Array, buf: Uint8Array, tri: Int32Array, col: Int32Array,
  nx: Float64Array, ny: Float64Array, nz: Float64Array, layer: Int32Array): number {
  const g = Array.from(ks).sort((a, b) => buf[a] - buf[b] || tri[a] - tri[b]);
  const G = g.length, k0 = g[0];
  // a basis in the plane
  const ax = Math.abs(nx[k0]) < 0.9 ? 1 : 0, ay = 1 - ax;
  let ex = -nz[k0] * ay, ey = nz[k0] * ax, ez = nx[k0] * ay - ny[k0] * ax;
  const el = Math.hypot(ex, ey, ez); ex /= el; ey /= el; ez /= el;
  const fx = ny[k0] * ez - nz[k0] * ey, fy = nz[k0] * ex - nx[k0] * ez, fz = nx[k0] * ey - ny[k0] * ex;
  const P = new Float64Array(G * 6), lo0 = new Float64Array(G), hi0 = new Float64Array(G), lo1 = new Float64Array(G), hi1 = new Float64Array(G);
  for (let j = 0; j < G; j++) {
    const p = bufs[buf[g[j]]].pos, i = tri[g[j]] * 9;
    for (let v = 0; v < 3; v++) {
      const X = p[i + v * 3], Y = p[i + v * 3 + 1], Z = p[i + v * 3 + 2];
      P[j * 6 + v * 2] = X * ex + Y * ey + Z * ez;
      P[j * 6 + v * 2 + 1] = X * fx + Y * fy + Z * fz;
    }
    // counter-clockwise
    const o = j * 6;
    if ((P[o + 2] - P[o]) * (P[o + 5] - P[o + 1]) - (P[o + 4] - P[o]) * (P[o + 3] - P[o + 1]) < 0) {
      const tx = P[o + 2], ty = P[o + 3]; P[o + 2] = P[o + 4]; P[o + 3] = P[o + 5]; P[o + 4] = tx; P[o + 5] = ty;
    }
    lo0[j] = Math.min(P[o], P[o + 2], P[o + 4]); hi0[j] = Math.max(P[o], P[o + 2], P[o + 4]);
    lo1[j] = Math.min(P[o + 1], P[o + 3], P[o + 5]); hi1[j] = Math.max(P[o + 1], P[o + 3], P[o + 5]);
  }
  // candidate pairs (earlier, later) whose bounds overlap by more than a hair, from a sweep along the first axis
  const byLo = Array.from({ length: G }, (_, j) => j).sort((a, b) => lo0[a] - lo0[b]);
  const under: number[][] = Array.from({ length: G }, () => []);
  const active: number[] = [];
  for (const j of byLo) {
    let w = 0;
    for (const i of active) {
      if (hi0[i] <= lo0[j] + 1e-6) continue;
      active[w++] = i;
      if (col[g[i]] === col[g[j]] || hi1[i] <= lo1[j] + 1e-6 || hi1[j] <= lo1[i] + 1e-6 || hi0[j] <= lo0[i] + 1e-6) continue;
      if (i < j) under[j].push(i); else under[i].push(j);
    }
    active.length = w;
    active.push(j);
  }
  let lifted = 0;
  const A: [number, number][] = [[0, 0], [0, 0], [0, 0]], B: [number, number][] = [[0, 0], [0, 0], [0, 0]];
  for (let j = 1; j < G; j++) {
    if (!under[j].length) continue;
    let top = -1;
    for (const i of under[j]) {
      if (layer[g[i]] <= top) continue;
      for (let v = 0; v < 3; v++) { A[v][0] = P[i * 6 + v * 2]; A[v][1] = P[i * 6 + v * 2 + 1]; B[v][0] = P[j * 6 + v * 2]; B[v][1] = P[j * 6 + v * 2 + 1]; }
      if (shared(B, A) > 1e-6) top = layer[g[i]];
    }
    if (top < 0) continue;
    const k = g[j];
    layer[k] = top + 1;
    const p = bufs[buf[k]].pos, i = tri[k] * 9, lift = layer[k] * FIGHT_LIFT;
    for (let v = 0; v < 3; v++) { p[i + v * 3] += nx[k] * lift; p[i + v * 3 + 1] += ny[k] * lift; p[i + v * 3 + 2] += nz[k] * lift; }
    lifted++;
  }
  return lifted;
}

/** Twice the signed area of a polygon in the plane. */
function area2(p: [number, number][]): number {
  let s = 0;
  for (let k = 0; k < p.length; k++) { const q = p[k], r = p[(k + 1) % p.length]; s += q[0] * r[1] - r[0] * q[1]; }
  return s;
}
/** The area two counter-clockwise triangles share (one clipped by the other). */
function shared(a: [number, number][], b: [number, number][]): number {
  let poly = a;
  for (let k = 0; k < 3 && poly.length; k++) {
    const A = b[k], B = b[(k + 1) % 3];
    const inside = (p: [number, number]) => (B[0] - A[0]) * (p[1] - A[1]) - (B[1] - A[1]) * (p[0] - A[0]) > 1e-9;
    const next: [number, number][] = [];
    for (let m = 0; m < poly.length; m++) {
      const P = poly[m], Q = poly[(m + 1) % poly.length];
      const pin = inside(P), qin = inside(Q);
      if (pin) next.push(P);
      if (pin !== qin) {
        const dx = Q[0] - P[0], dy = Q[1] - P[1];
        const den = (B[0] - A[0]) * dy - (B[1] - A[1]) * dx;
        if (Math.abs(den) > 1e-12) {
          const s = ((B[0] - A[0]) * (A[1] - P[1]) - (B[1] - A[1]) * (A[0] - P[0])) / den;
          next.push([P[0] + dx * s, P[1] + dy * s]);
        }
      }
    }
    poly = next;
  }
  return poly.length >= 3 ? Math.abs(area2(poly)) / 2 : 0;
}

export class Kit {
  pos: number[] = [];
  col: number[] = [];
  ids: number[] = [];
  vis: number[] = [];
  /**
   * Surface detail a hair proud of a wall (window frames, shutters, lintels, half-timbering): drawn
   * like the rest but in a mesh of its own that throws no shadow. Those strips sit 0.014 off the wall,
   * so their shadows were invisible, yet they were a good share of a city's shadow triangles (the lag
   * audit, Oct 2026).
   */
  private dpos: number[] = [];
  private dcol: number[] = [];
  private dids: number[] = [];
  private dvis: number[] = [];
  readonly glow = new GlowBuf();
  /** How many surface-detail triangles have been drawn: where a building's own begin, for settle(). */
  get detailCount(): number { return this.dpos.length / 9; }
  /** Lift the faces drawn since these counts that would flash against another (settleFights). */
  settle(from: number, dfrom: number): number {
    return settleFights([{ pos: this.pos, col: this.col, from }, { pos: this.dpos, col: this.dcol, from: dfrom }]);
  }

  /** Textured quads of sign lettering (signGlyphs.ts): positions and their atlas coordinates. */
  private glyphPos: number[] = [];
  private glyphUv: number[] = [];
  private glyphCol: number[] = [];
  private ox = 0; private oy = 0; private oz = 0; private c = 1; private s = 0;
  private yaw = 0;
  private moving: THREE.Object3D[] = [];
  /** The moving parts drawn so far, nested kits' too: woken whenever their group is put in the scene. */
  private movers: Mover[] = [];
  /**
   * How the town's fortunes show on what is drawn next: a derelict building is dull, brown and dark
   * with its windows boarded; a new one has no lights on yet.
   */
  mode: 'derelict' | 'new' | null = null;

  /** Which Vis tag the next primitives carry, solid and glowing alike. */
  get tag(): Vis { return this.glow.tag; }
  set tag(v: Vis) { this.glow.tag = v; }

  /** Draw some parts as surface detail (see dpos): seen and lit as ever, casting no shadow. */
  detail(draw: () => void): void {
    if (this.pos === this.dpos) { draw(); return; }
    const was = [this.pos, this.col, this.ids, this.vis];
    this.pos = this.dpos; this.col = this.dcol; this.ids = this.dids; this.vis = this.dvis;
    try { draw(); } finally { [this.pos, this.col, this.ids, this.vis] = was; }
  }

  /** Draw some parts under a tag, then go back to whatever was showing before. */
  tagged(v: Vis, draw: () => void): void {
    const was = this.tag;
    this.tag = v;
    draw();
    this.tag = was;
  }

  constructor(private w: World) {}

  /** The world being drawn. */
  get world(): World { return this.w; }

  /** Ground height under a local point, relative to the frame's origin (for things that follow slopes). */
  ground(lx: number, lz: number): number {
    return heightAt(this.w, this.ox + lx * this.c + lz * this.s, this.oz - lx * this.s + lz * this.c) - this.oy;
  }

  place(x: number, y: number, z: number, yaw: number): void {
    this.ox = x; this.oy = y; this.oz = z; this.c = Math.cos(yaw); this.s = Math.sin(yaw);
    this.yaw = yaw;
  }

  /** Draw some parts with the frame's origin moved to local (x, z) and turned a further `yaw`: one model inside another's lot. */
  within(x: number, z: number, yaw: number, draw: () => void): void {
    const { ox, oy, oz, c, s, yaw: was } = this;
    this.place(ox + x * c + z * s, oy, oz - x * s + z * c, was + yaw);
    draw();
    this.ox = ox; this.oy = oy; this.oz = oz; this.c = c; this.s = s; this.yaw = was;
  }

  /** Draw some parts with the frame turned a further `yaw` about its own origin. */
  turned(yaw: number, draw: () => void): void {
    const { c, s, yaw: was } = this;
    this.place(this.ox, this.oy, this.oz, was + yaw);
    draw();
    this.c = c; this.s = s; this.yaw = was;
  }

  private tf(p: P3): P3 {
    return [this.ox + p[0] * this.c + p[2] * this.s, this.oy + p[1], this.oz - p[0] * this.s + p[2] * this.c];
  }

  /** A triangle wound to face away from `inside`, a point within the solid it bounds. */
  tri(a: P3, b: P3, c: P3, col: RGB, inside: P3): void {
    const A = this.tf(a), B = this.tf(b), Cc = this.tf(c), I = this.tf(inside);
    const ux = B[0] - A[0], uy = B[1] - A[1], uz = B[2] - A[2];
    const vx = Cc[0] - A[0], vy = Cc[1] - A[1], vz = Cc[2] - A[2];
    const nx = uy * vz - uz * vy, ny = uz * vx - ux * vz, nz = ux * vy - uy * vx;
    const mx = (A[0] + B[0] + Cc[0]) / 3 - I[0], my = (A[1] + B[1] + Cc[1]) / 3 - I[1], mz = (A[2] + B[2] + Cc[2]) / 3 - I[2];
    const [p, q] = nx * mx + ny * my + nz * mz < 0 ? [Cc, B] : [B, Cc];
    this.pos.push(A[0], A[1], A[2], p[0], p[1], p[2], q[0], q[1], q[2]);
    if (this.mode === 'derelict') col = neglect(col);
    for (let k = 0; k < 3; k++) {
      this.col.push(col[0], col[1], col[2]);
      this.ids.push(this.glow.id);
      this.vis.push(this.glow.tag);
    }
  }

  quad(a: P3, b: P3, c: P3, d: P3, col: RGB, inside: P3): void {
    this.tri(a, b, c, col, inside);
    this.tri(a, c, d, col, inside);
  }

  /** Box centred on (x, z) standing on y. The bottom face is never seen, so it is skipped. */
  box(x: number, y: number, z: number, w: number, h: number, d: number, col: RGB, top: RGB = col): void {
    const x0 = x - w / 2, x1 = x + w / 2, z0 = z - d / 2, z1 = z + d / 2, y1 = y + h;
    const I: P3 = [x, y + h / 2, z];
    this.quad([x0, y1, z0], [x1, y1, z0], [x1, y1, z1], [x0, y1, z1], top, I);
    this.quad([x0, y, z1], [x1, y, z1], [x1, y1, z1], [x0, y1, z1], col, I);
    this.quad([x0, y, z0], [x1, y, z0], [x1, y1, z0], [x0, y1, z0], col, I);
    this.quad([x1, y, z0], [x1, y, z1], [x1, y1, z1], [x1, y1, z0], col, I);
    this.quad([x0, y, z0], [x0, y, z1], [x0, y1, z1], [x0, y1, z0], col, I);
    if (frameBeam && h >= FRAME_MIN && h <= FRAME_MAX_H && w >= FRAME_MIN && d >= FRAME_MIN && Math.max(w, d) <= FRAME_MAX_W && isFramedWall(col)) {
      this.frame(x, y, z, w, h, d, frameBeam);
    }
  }

  /**
   * Half-timbering over the four walls of a box: posts at the corners and between, a rail at every
   * storey and at the sill line, and a brace in the end bays of each storey. Flat strips a hair proud
   * of the plaster, under the windows, which stand a little further out.
   */
  private frame(x: number, y: number, z: number, w: number, h: number, d: number, beam: RGB): void {
    const t = 0.017, e = 0.0035, I: P3 = [x, y + h / 2, z];
    const floors = Math.max(1, Math.round(h / FLOOR));
    const sh = h / floors;
    // a wall along u from -L/2 to L/2 at the given offset; `at` puts a (u, v) point on it
    const wall = (L: number, at: (u: number, v: number) => P3) => {
      const strip = (a: [number, number], b: [number, number], c: [number, number], dd: [number, number]) =>
        this.quad(at(a[0], a[1]), at(b[0], b[1]), at(c[0], c[1]), at(dd[0], dd[1]), beam, I);
      const post = (u: number, v0: number, v1: number) => strip([u - t / 2, v0], [u + t / 2, v0], [u + t / 2, v1], [u - t / 2, v1]);
      const rail = (v: number) => strip([-L / 2, v - t / 2], [L / 2, v - t / 2], [L / 2, v + t / 2], [-L / 2, v + t / 2]);
      const n = Math.max(2, Math.round(L / Math.max(0.15, L / 12)));
      for (let i = 0; i <= n; i++) {
        const u = -L / 2 + t / 2 + ((L - t) * i) / n;
        post(u, y, y + h);
      }
      rail(y + h - t / 2);
      for (let f = 0; f < floors; f++) {
        const v0 = y + f * sh;
        if (f > 0) rail(v0);
        rail(v0 + sh * 0.42);
        // braces in the two end bays, leaning in toward the middle
        const bay = (L - t) / n;
        if (bay > 0.05) {
          for (const side of [-1, 1]) {
            const uo = side * (L / 2 - t / 2), ui = side * (L / 2 - t / 2 - bay);
            strip([uo - t / 2, v0], [uo + t / 2, v0], [ui + t / 2, v0 + sh], [ui - t / 2, v0 + sh]);
          }
        }
      }
    };
    const x0 = x - w / 2 - e, x1 = x + w / 2 + e, z0 = z - d / 2 - e, z1 = z + d / 2 + e;
    this.detail(() => {
      wall(w, (u, v) => [x + u, v, z1]);
      wall(w, (u, v) => [x + u, v, z0]);
      wall(d, (u, v) => [x1, v, z + u]);
      wall(d, (u, v) => [x0, v, z + u]);
    });
  }

  /** A king post up the middle of a gable end and a collar across it, the end's triangle standing in the plane `at` gives. */
  private gableFrame(half: number, y: number, h: number, beam: RGB, at: (u: number, v: number) => P3, I: P3): void {
    const t = 0.017, c = y + h * 0.42, cw = half * (1 - 0.42);
    this.detail(() => {
      this.quad(at(-t / 2, y), at(t / 2, y), at(t / 2, y + h * 0.95), at(-t / 2, y + h * 0.95), beam, I);
      this.quad(at(-cw, c - t / 2), at(cw, c - t / 2), at(cw, c + t / 2), at(-cw, c + t / 2), beam, I);
    });
  }

  /** Pitched roof over a w×d base; the ridge runs along x (or z). */
  gable(x: number, y: number, z: number, w: number, h: number, d: number, roof: RGB, end: RGB, alongZ = false): void {
    const x0 = x - w / 2, x1 = x + w / 2, z0 = z - d / 2, z1 = z + d / 2, yt = y + h;
    const I: P3 = [x, y + h / 3, z];
    if (!alongZ) {
      this.quad([x0, y, z1], [x1, y, z1], [x1, yt, z], [x0, yt, z], roof, I);
      this.quad([x0, y, z0], [x1, y, z0], [x1, yt, z], [x0, yt, z], roof, I);
      this.tri([x0, y, z0], [x0, y, z1], [x0, yt, z], end, I);
      this.tri([x1, y, z0], [x1, y, z1], [x1, yt, z], end, I);
      if (frameBeam && h >= FRAME_MIN * 0.6 && isFramedWall(end)) {
        for (const [px, s] of [[x0, -1], [x1, 1]] as [number, number][]) {
          this.gableFrame(d / 2, y, h, frameBeam, (u, v) => [px + s * 0.0035, v, z + u], I);
        }
      }
    } else {
      this.quad([x1, y, z0], [x1, y, z1], [x, yt, z1], [x, yt, z0], roof, I);
      this.quad([x0, y, z0], [x0, y, z1], [x, yt, z1], [x, yt, z0], roof, I);
      this.tri([x0, y, z0], [x1, y, z0], [x, yt, z0], end, I);
      this.tri([x0, y, z1], [x1, y, z1], [x, yt, z1], end, I);
      if (frameBeam && h >= FRAME_MIN * 0.6 && isFramedWall(end)) {
        for (const [pz, s] of [[z0, -1], [z1, 1]] as [number, number][]) {
          this.gableFrame(w / 2, y, h, frameBeam, (u, v) => [x + u, v, pz + s * 0.0035], I);
        }
      }
    }
  }

  /** Four-sided pyramid (a negative h points it down). */
  hip(x: number, y: number, z: number, w: number, h: number, d: number, col: RGB): void {
    const x0 = x - w / 2, x1 = x + w / 2, z0 = z - d / 2, z1 = z + d / 2;
    const A: P3 = [x, y + h, z], I: P3 = [x, y + h / 4, z];
    this.tri([x0, y, z0], [x1, y, z0], A, col, I);
    this.tri([x1, y, z0], [x1, y, z1], A, col, I);
    this.tri([x1, y, z1], [x0, y, z1], A, col, I);
    this.tri([x0, y, z1], [x0, y, z0], A, col, I);
  }

  /** Upright (elliptical) cylinder with a top cap. */
  cyl(x: number, y: number, z: number, r: number, h: number, col: RGB, seg = 8, top: RGB = col, rz = r): void {
    const I: P3 = [x, y + h / 2, z];
    for (let s = 0; s < seg; s++) {
      const a0 = (s / seg) * TAU, a1 = ((s + 1) / seg) * TAU;
      const p0x = x + Math.cos(a0) * r, p0z = z + Math.sin(a0) * rz, p1x = x + Math.cos(a1) * r, p1z = z + Math.sin(a1) * rz;
      this.quad([p0x, y, p0z], [p1x, y, p1z], [p1x, y + h, p1z], [p0x, y + h, p0z], col, I);
      this.tri([x, y + h, z], [p0x, y + h, p0z], [p1x, y + h, p1z], top, I);
    }
  }

  cone(x: number, y: number, z: number, r: number, h: number, col: RGB, seg = 8): void {
    const I: P3 = [x, y + h / 4, z], A: P3 = [x, y + h, z];
    for (let s = 0; s < seg; s++) {
      const a0 = (s / seg) * TAU, a1 = ((s + 1) / seg) * TAU;
      this.tri([x + Math.cos(a0) * r, y, z + Math.sin(a0) * r], [x + Math.cos(a1) * r, y, z + Math.sin(a1) * r], A, col, I);
    }
  }

  /** Hemisphere on y. */
  dome(x: number, y: number, z: number, r: number, col: RGB, seg = 12, rings = 4): void {
    const I: P3 = [x, y, z];
    for (let j = 0; j < rings; j++) {
      const p0 = (j / rings) * Math.PI / 2, p1 = ((j + 1) / rings) * Math.PI / 2;
      const r0 = Math.cos(p0) * r, r1 = Math.cos(p1) * r, y0 = y + Math.sin(p0) * r, y1 = y + Math.sin(p1) * r;
      for (let s = 0; s < seg; s++) {
        const a0 = (s / seg) * TAU, a1 = ((s + 1) / seg) * TAU;
        const c0 = Math.cos(a0), s0 = Math.sin(a0), c1 = Math.cos(a1), s1 = Math.sin(a1);
        this.quad([x + c0 * r0, y0, z + s0 * r0], [x + c1 * r0, y0, z + s1 * r0], [x + c1 * r1, y1, z + s1 * r1], [x + c0 * r1, y1, z + s0 * r1], col, I);
      }
    }
  }

  // ---- things that light up ----

  private gtri(a: P3, b: P3, c: P3, inside: P3, day: RGB, s: Sched, g: RGB): void {
    if (this.mode) s = NEVER;
    if (this.mode === 'derelict') day = neglect(scale(day, 0.45));
    this.glow.tri(this.tf(a), this.tf(b), this.tf(c), this.tf(inside), day, s, g);
  }

  /** A window pane on a wall facing local direction `face` (0 +x, 1 +z, 2 -x, 3 -z); (x, z) lies on the wall. */
  pane(x: number, y: number, z: number, w: number, h: number, face: number, day: RGB, s: Sched, g: RGB): void {
    const e = 0.006, y1 = y + h;
    if (this.mode === 'derelict' && w > 0.05 && h > 0.05) {
      // two planks nailed across the pane
      for (const f of [0.3, 0.68]) {
        if (face === 1 || face === 3) this.box(x, y + h * f, z + (face === 1 ? 0.012 : -0.012), w * 1.12, h * 0.14, 0.012, PLANK);
        else this.box(x + (face === 0 ? 0.012 : -0.012), y + h * f, z, 0.012, h * 0.14, w * 1.12, PLANK);
      }
    }
    if (face === 1 || face === 3) {
      const sz = face === 1 ? 1 : -1, zz = z + sz * e, I: P3 = [x, y + h / 2, zz - sz * 0.1];
      this.gtri([x - w / 2, y, zz], [x + w / 2, y, zz], [x + w / 2, y1, zz], I, day, s, g);
      this.gtri([x - w / 2, y, zz], [x + w / 2, y1, zz], [x - w / 2, y1, zz], I, day, s, g);
    } else {
      const sx = face === 0 ? 1 : -1, xx = x + sx * e, I: P3 = [xx - sx * 0.1, y + h / 2, z];
      this.gtri([xx, y, z - w / 2], [xx, y, z + w / 2], [xx, y1, z + w / 2], I, day, s, g);
      this.gtri([xx, y, z - w / 2], [xx, y1, z + w / 2], [xx, y1, z - w / 2], I, day, s, g);
    }
  }

  /** A triangle that glows on its schedule, wound to face away from `inside`: a facet of a lit skin. */
  glowTri(a: P3, b: P3, c: P3, inside: P3, day: RGB, s: Sched, g: RGB): void {
    this.gtri(a, b, c, inside, day, s, g);
  }

  /** A quad that glows on its schedule, wound to face away from `inside`: a lit panel on a curved skin. */
  glowQuad(a: P3, b: P3, c: P3, d: P3, inside: P3, day: RGB, s: Sched, g: RGB): void {
    this.gtri(a, b, c, inside, day, s, g);
    this.gtri(a, c, d, inside, day, s, g);
  }

  /** A box that glows on its schedule: lamps, signs, beacons. */
  glowBox(x: number, y: number, z: number, w: number, h: number, d: number, day: RGB, s: Sched, g: RGB): void {
    const x0 = x - w / 2, x1 = x + w / 2, z0 = z - d / 2, z1 = z + d / 2, y1 = y + h;
    const I: P3 = [x, y + h / 2, z];
    const q = (a: P3, b: P3, c: P3, e: P3) => { this.gtri(a, b, c, I, day, s, g); this.gtri(a, c, e, I, day, s, g); };
    q([x0, y1, z0], [x1, y1, z0], [x1, y1, z1], [x0, y1, z1]);
    q([x0, y, z1], [x1, y, z1], [x1, y1, z1], [x0, y1, z1]);
    q([x0, y, z0], [x1, y, z0], [x1, y1, z0], [x0, y1, z0]);
    q([x1, y, z0], [x1, y, z1], [x1, y1, z1], [x1, y1, z0]);
    q([x0, y, z0], [x0, y, z1], [x0, y1, z1], [x0, y1, z0]);
  }


  /**
   * A square-section bar from a to b in the local frame: the one primitive that runs at an angle,
   * for conveyor belts, chairlift cables and the trestles under them.
   */
  bar(a: P3, b: P3, r: number, col: RGB): void {
    const dx = b[0] - a[0], dy = b[1] - a[1], dz = b[2] - a[2];
    const len = Math.hypot(dx, dy, dz);
    if (len < 1e-5) return;
    const ux = dx / len, uy = dy / len, uz = dz / len;
    // any two perpendiculars will do; pick the one least parallel to the run
    let px = -uz, py = 0, pz = ux;
    let pl = Math.hypot(px, py, pz);
    if (pl < 1e-4) { px = 1; py = 0; pz = 0; pl = 1; }
    px /= pl; py /= pl; pz /= pl;
    const qx = uy * pz - uz * py, qy = uz * px - ux * pz, qz = ux * py - uy * px;
    const corner = (t: number, s1: number, s2: number): P3 => [
      a[0] + dx * t + (px * s1 + qx * s2) * r,
      a[1] + dy * t + (py * s1 + qy * s2) * r,
      a[2] + dz * t + (pz * s1 + qz * s2) * r,
    ];
    const mid: P3 = [a[0] + dx / 2, a[1] + dy / 2, a[2] + dz / 2];
    const c = [
      corner(0, -1, -1), corner(0, 1, -1), corner(0, 1, 1), corner(0, -1, 1),
      corner(1, -1, -1), corner(1, 1, -1), corner(1, 1, 1), corner(1, -1, 1),
    ];
    this.quad(c[0], c[1], c[5], c[4], col, mid);
    this.quad(c[1], c[2], c[6], c[5], col, mid);
    this.quad(c[2], c[3], c[7], c[6], col, mid);
    this.quad(c[3], c[0], c[4], c[7], col, mid);
    this.quad(c[3], c[2], c[1], c[0], col, mid);
    this.quad(c[4], c[5], c[6], c[7], col, mid);
  }

  // ---- shapes the first forty-seven buildings never needed ----

  /** A hoop of bars in the local plane through (x, y, z): 'xy' stands upright facing +z, 'xz' lies flat. */
  hoop(x: number, y: number, z: number, radius: number, thick: number, col: RGB, seg = 16, plane: 'xy' | 'xz' | 'zy' = 'xy'): void {
    const at = (a: number): P3 => {
      const u = Math.cos(a) * radius, v = Math.sin(a) * radius;
      return plane === 'xy' ? [x + u, y + v, z] : plane === 'xz' ? [x + u, y, z + v] : [x, y + v, z + u];
    };
    for (let i = 0; i < seg; i++) this.bar(at((i / seg) * TAU), at(((i + 1) / seg) * TAU), thick, col);
  }

  /**
   * A ramp: a box whose top slopes from nothing at the back (-z) to h at the front (+z). A skate
   * park's quarter-pipes, a grandstand's rake, the tiers of an amphitheatre.
   */
  wedge(x: number, y: number, z: number, w: number, h: number, d: number, col: RGB): void {
    const x0 = x - w / 2, x1 = x + w / 2, z0 = z - d / 2, z1 = z + d / 2, y1 = y + h;
    const I: P3 = [x, y + h / 3, z + d / 6];
    this.quad([x0, y, z0], [x1, y, z0], [x1, y1, z1], [x0, y1, z1], col, I);
    this.quad([x0, y, z1], [x1, y, z1], [x1, y1, z1], [x0, y1, z1], col, I);
    this.tri([x0, y, z0], [x0, y, z1], [x0, y1, z1], col, I);
    this.tri([x1, y, z0], [x1, y, z1], [x1, y1, z1], col, I);
  }

  /** A flat coloured disc lying on y, for pools, rose windows, flower beds and clock faces laid down. */
  disc(x: number, y: number, z: number, r: number, col: RGB, seg = 12, rz = r): void {
    this.cyl(x, y, z, r, 0.006, col, seg, col, rz);
  }

  /**
   * One band of a round shell about (x, z), from radius r0 at y0 to r1 at y1: a cooling tower's wall.
   * `inner` draws the inside of it too, for a shell open at the top that is seen into from above.
   */
  band(x: number, z: number, y0: number, r0: number, y1: number, r1: number, seg: number, col: RGB, inner?: RGB): void {
    for (let s = 0; s < seg; s++) {
      const a0 = (s / seg) * TAU, a1 = ((s + 1) / seg) * TAU, am = (a0 + a1) / 2;
      const q: P3[] = [
        [x + Math.cos(a0) * r0, y0, z + Math.sin(a0) * r0], [x + Math.cos(a1) * r0, y0, z + Math.sin(a1) * r0],
        [x + Math.cos(a1) * r1, y1, z + Math.sin(a1) * r1], [x + Math.cos(a0) * r1, y1, z + Math.sin(a0) * r1],
      ];
      this.quad(q[0], q[1], q[2], q[3], col, [x, (y0 + y1) / 2, z]);
      // wound toward the axis: the point it faces away from lies well outside the wall
      const far = 4 * Math.max(r0, r1);
      if (inner) this.quad(q[0], q[1], q[2], q[3], inner, [x + Math.cos(am) * far, (y0 + y1) / 2, z + Math.sin(am) * far]);
    }
  }

  /** An upright disc facing +z: a clock face, a rose window, a sign. */
  face(x: number, y: number, z: number, r: number, col: RGB, seg = 12): void {
    const I: P3 = [x, y, z - 0.05];
    for (let i = 0; i < seg; i++) {
      const a0 = (i / seg) * TAU, a1 = ((i + 1) / seg) * TAU;
      this.tri([x, y, z], [x + Math.cos(a0) * r, y + Math.sin(a0) * r, z], [x + Math.cos(a1) * r, y + Math.sin(a1) * r, z], col, I);
    }
  }

  /**
   * A moving part, pivoting at local (px, py, pz) about the local axis: `draw` builds it around its
   * own origin in a kit of its own, and the frame loop turns it (see animateParts).
   */
  spin(px: number, py: number, pz: number, axis: 'x' | 'y' | 'z', speed: number, draw: (k: Kit) => void, mode: SpinMode = 'turn'): void {
    const sub = new Kit(this.w);
    sub.glow.id = this.glow.id;
    sub.tag = this.tag;
    sub.mode = this.mode;
    draw(sub);
    const inner = sub.meshes();
    if (!inner) return;
    const at = this.tf([px, py, pz]);
    const outer = new THREE.Group();
    outer.position.set(at[0], at[1], at[2]);
    outer.rotation.y = this.yaw;
    outer.userData.moves = true; // the stream leaves its matrices live (render/stream.ts freezeStatic)
    outer.add(inner);
    this.moving.push(outer);
    this.movers.push(...sub.movers, { spinner: { obj: inner, axis, speed, mode, tag: this.tag } });
  }

  /**
   * A ride with parts that move every frame (see RigTick): each of `parts` is drawn round its own origin
   * in a kit of its own, all in the frame of local (px, py, pz), and `tick` places them.
   */
  rig(px: number, py: number, pz: number, parts: ((k: Kit) => void)[], tick: RigTick): void {
    const at = this.tf([px, py, pz]);
    const outer = new THREE.Group();
    outer.position.set(at[0], at[1], at[2]);
    outer.rotation.y = this.yaw;
    outer.userData.moves = true; // the stream leaves its matrices live (render/stream.ts freezeStatic)
    const objs = parts.map((draw) => {
      const sub = new Kit(this.w);
      sub.glow.id = this.glow.id;
      sub.tag = this.tag;
      sub.mode = this.mode;
      draw(sub);
      const o = sub.meshes() ?? new THREE.Group();
      outer.add(o);
      this.movers.push(...sub.movers);
      return o;
    });
    tick(objs, 0, 12);
    this.moving.push(outer);
    this.movers.push({ rig: { root: outer, parts: objs, tick, tag: this.tag } });
  }

  /**
   * A character laid flat on a face: corners a (bottom left as read), b (bottom right), c (top right),
   * d (top left), in the local frame. `col` tints it (white by default): a neon letter is its tube's colour.
   */
  glyph(ch: string, a: P3, b: P3, c: P3, d: P3, col: RGB = GLYPH_WHITE): void {
    const { u0, v0, u1, v1 } = glyphUv(ch);
    const A = this.tf(a), B = this.tf(b), C = this.tf(c), D = this.tf(d);
    this.glyphPos.push(...A, ...B, ...C, ...A, ...C, ...D);
    this.glyphUv.push(u0, v0, u1, v0, u1, v1, u0, v0, u1, v1, u0, v1);
    for (let i = 0; i < 6; i++) this.glyphCol.push(col[0], col[1], col[2]);
  }

  meshes(): THREE.Group | null {
    const parts: THREE.Object3D[] = [];
    // (the lettering needs a canvas for its atlas: the gate scripts, run under node, go without it)
    if (this.glyphPos.length && typeof document !== 'undefined') {
      const g = new THREE.BufferGeometry();
      g.setAttribute('position', new THREE.Float32BufferAttribute(this.glyphPos, 3));
      g.setAttribute('uv', new THREE.Float32BufferAttribute(this.glyphUv, 2));
      g.setAttribute('color', new THREE.Float32BufferAttribute(this.glyphCol, 3));
      g.computeBoundingSphere();
      const m = new THREE.Mesh(g, glyphMaterial());
      m.renderOrder = 2;
      parts.push(m);
    }
    const solid = (pos: number[], col: number[], ids: number[], vis: number[], casts: boolean) => {
      if (!pos.length) return;
      const g = new THREE.BufferGeometry();
      g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
      g.setAttribute('color', new THREE.Float32BufferAttribute(col, 3));
      g.setAttribute('aId', new THREE.Float32BufferAttribute(ids, 1));
      g.setAttribute('aVis', new THREE.Float32BufferAttribute(vis, 1));
      g.computeVertexNormals();
      g.computeBoundingSphere();
      const m = new THREE.Mesh(g, townMaterial);
      m.castShadow = casts;
      m.receiveShadow = true;
      m.customDepthMaterial = visDepthMaterial;
      parts.push(m);
    };
    solid(this.pos, this.col, this.ids, this.vis, true);
    solid(this.dpos, this.dcol, this.dids, this.dvis, false);
    const lit = this.glow.mesh();
    if (lit) parts.push(lit);
    parts.push(...this.moving);
    if (!parts.length) return null;
    const group = new THREE.Group();
    group.add(...parts);
    if (this.movers.length) {
      // the group going into a chunk, or a chunk going into the scene, wakes its moving parts
      const movers = this.movers, onAdded = () => wake(movers);
      group.addEventListener('added', onAdded);
      for (const o of this.moving) o.addEventListener('added', onAdded);
    }
    return group;
  }
}

// ---------------------------------------------------------------------------------------------
// palette

export const WALLS = [0xf2e6d0, 0xe8d3b0, 0xcfe0e8, 0xf4d6c6, 0xdbe8c9, 0xf1f0ea, 0xe6c9a8, 0xc9d3e6, 0xf6e7a8];
export const ROOFS = [0x8a4a3a, 0x5a5f6b, 0x6b4a3a, 0x3f5a73, 0x7a6a5a, 0xa0523d, 0x4f6b4a];
