/** The style of the building currently being drawn; set once per building in drawBuilding. */
export let cur: StyleSpec = STYLES.classic;
/** Draw the next building in this style. */
export function setStyle(a: Arch, roll = 0): void {
  cur = STYLES[a];
  curArch = a;
  offStrip = false;
  const t = cur.timber;
  frameBeam = t ? hex(t[Math.min(t.length - 1, Math.floor(roll * t.length))]) : null;
  frameWalls = t ? cur.walls.map(hex) : [];
}
/** The beam colour of the building being drawn, when its style is half-timbered, and the wall colours it frames. */
let frameBeam: RGB | null = null;
let frameWalls: RGB[] = [];
const isFramedWall = (c: RGB): boolean =>
  frameWalls.some((f) => Math.abs(f[0] - c[0]) < 1e-3 && Math.abs(f[1] - c[1]) < 1e-3 && Math.abs(f[2] - c[2]) < 1e-3);
/** Half-timbering is drawn on walls from this tall, and not on anything bigger than a big hall. */
const FRAME_MIN = 0.14, FRAME_MAX_H = 1.6, FRAME_MAX_W = 3.2;
/** Which style that is, for the models that change shape rather than colour with it. */
export let curArch: Arch = 'classic';
/**
 * The building being drawn stands in a Las Vegas but off its Strip (world/strip.ts frontsStrip): no signs, no neon,
 * no lit-up variants, plain stucco. Set after setStyle (which clears it) by whoever draws a town's buildings.
 */
export let offStrip = false;
export function setOffStrip(v: boolean): void { offStrip = v; }
export const styleWall = (r: Rng): RGB => pick(r, cur.walls);
export const styleRoof = (r: Rng): RGB => pick(r, cur.roofs);
export const styleGlass = (r: Rng): RGB => pick(r, cur.glass);
export const styleTrim = (): RGB => hex(cur.trim);

/** Planks over a boarded window (they go through the colour of neglect like everything else). */
const PLANK: RGB = hex(0xb09268);
const RUST: RGB = hex(0x6b5540);
/** A colour gone to seed: pulled toward a dull brown, and a third darker. */
function neglect(c: RGB): RGB {
  return scale(mix(c, RUST, 0.42), 0.68);
}

// ---------------------------------------------------------------------------------------------
// night life

/**
 * When one window in this kind of building is lit. Homes come on through the evening and go dark
 * by bedtime; offices light at dusk and empty out; shops close; hospitals and gas stations never sleep.
 */
export function windowSched(kind: BuildingKind, r: Rng): Sched {
  switch (kind) {
    case 'house': case 'farmhouse': case 'townhouse': case 'bungalow': case 'cottage': case 'duplex': case 'terraceRow':
    case 'mansion': case 'trailerPark':
      return r() < 0.2 ? NEVER : [17 + r() * 3, 20.5 + r() * 4, 1.3];
    case 'courtyardBlock': case 'towerBlock': case 'condoTower': case 'retirementHome':
      return r() < 0.15 ? NEVER : [17 + r() * 4, 21 + r() * (r() < 0.2 ? 9 : 4.5), 1.3];
    case 'officePark': case 'techCampus': case 'ministry': case 'exchange':
      return r() < 0.25 ? NEVER : [16.5 + r() * 1.5, 18 + r() * (r() < 0.12 ? 12 : 4), 1.5];
    case 'bank': case 'carDealership': case 'bigBox': case 'stripMall': case 'departmentStore': case 'marketHall': case 'garage':
    case 'cafe': case 'bowlingAlley':
      return [16.5 + r() * 1.5, 20.5 + r() * 2.5, 1.6];
    case 'hotel': case 'motel': case 'fastFood': case 'casino': case 'prison': case 'busStation': case 'powerPlant':
    case 'logisticsDepot': case 'factory': case 'dataCentre': case 'fuelDepot':
      return r() < 0.1 ? NEVER : [16.8 + r() * 1.2, 30, 1.5];
    case 'courthouse': case 'postOffice': case 'communityCentre': case 'university': case 'villageHall': case 'waterworks':
    case 'observatory': case 'recyclingCentre':
      return [17 + r() * 1.2, 18.5 + r() * 3, 1.3];
    case 'kindergarten':
      return [16.5, 17, 1.2];
    case 'cathedral': case 'chapel': case 'mosque': case 'temple':
      return [18 + r(), 20.5 + r() * 1.5, 1.4];
    case 'pub': case 'brewery':
      return [16 + r(), 23.5, 1.7];
    case 'nightclub':
      return [22, 28, 1.8];
    case 'bakery':
      return [28, 31, 1.6];
    case 'cinema': case 'theatre': case 'arena': case 'concertHall': case 'iceRink':
      return [17, 23 + r() * 0.5, 1.5];
    case 'sportsHall':
      return [16.5, 22, 1.4];
    case 'apartment':
      return r() < 0.15 ? NEVER : [17 + r() * 4, 21 + r() * (r() < 0.15 ? 9 : 4.5), 1.3];
    case 'office': case 'skyscraper': case 'landmark':
      return r() < 0.25 ? NEVER : [16.5 + r() * 1.5, 18 + r() * (r() < 0.12 ? 12 : 4), 1.5];
    case 'shop': case 'store': case 'grocery': case 'mall':
      return [16.5 + r() * 1.5, 20.5 + r() * 2.5, 1.6];
    case 'diner': case 'gas': case 'police': case 'fire': case 'hospital': case 'harbourOffice':
      return r() < 0.1 ? NEVER : [16.8 + r() * 1.2, 30, 1.5];
    case 'clinic': case 'library': case 'museum': case 'school': case 'cityHall':
      return [17 + r() * 1.2, 18.5 + r() * 3, 1.3];
    case 'church':
      return [18 + r(), 20.5 + r() * 1.5, 1.4];
    default:
      return [17.5 + r() * 2, 21 + r() * 4, 1.3];
  }
}

const COOL = new Set<BuildingKind>([
  'office', 'skyscraper', 'landmark', 'hospital', 'police', 'officePark', 'techCampus', 'ministry', 'exchange', 'dataCentre',
  'prison', 'powerPlant', 'logisticsDepot', 'university', 'sportsHall', 'iceRink', 'busStation',
]);
const SHOPS = new Set<BuildingKind>([
  'shop', 'store', 'grocery', 'mall', 'gas', 'diner', 'bank', 'carDealership', 'bigBox', 'stripMall', 'cafe', 'bakery',
  'departmentStore', 'marketHall', 'fastFood', 'garage',
]);

export function windowGlow(kind: BuildingKind, r: Rng): RGB {
  if (cur.glow !== undefined) {
    // the style's own warmth: paper-white in the Terraces, amber on the Whitewash
    const g = hex(cur.glow);
    if (COOL.has(kind)) return mix(g, COOL_GLOW, 0.45);
    if (SHOPS.has(kind)) return mix(g, SHOP_GLOW, 0.35);
    return r() < 0.06 ? TV_GLOW : g;
  }
  if (COOL.has(kind)) return COOL_GLOW;
  if (SHOPS.has(kind)) return SHOP_GLOW;
  return r() < 0.12 ? TV_GLOW : WARM_GLOW;
}

/** One window with its own schedule. */
export function win(k: Kit, b: Building, r: Rng, x: number, y: number, z: number, w: number, h: number, face: number, day = GLASS): void {
  const s = cur;
  if (s.winScale === undefined && s.pane === undefined && !s.shutter && s.lintel === undefined && s.frame === undefined) {
    k.pane(x, y, z, w, h, face, day, windowSched(b.kind, r), windowGlow(b.kind, r));
    return;
  }
  const small = w < 0.36;
  if (small && s.winScale !== undefined) {
    y += (h * (1 - s.winScale)) / 2;
    w *= s.winScale; h *= s.winScale;
  }
  if (s.pane !== undefined && (day === GLASS || day === GLASS_LIGHT)) day = hex(s.pane);
  // a bay window stands out of the wall: the box first, then the pane on its face
  if (s.bay !== undefined && small && h >= 0.06 && b.floors <= 4) {
    const out = s.bay, wall = styleWall(r), cap = hex(s.trim);
    const bw = w + 0.06, bh = h + 0.06, by = y - 0.03;
    if (face === 1 || face === 3) {
      const dz = face === 1 ? out / 2 : -out / 2;
      k.box(x, by, z + dz, bw, bh, out, wall);
      k.box(x, by + bh, z + dz, bw + 0.03, 0.02, out + 0.03, cap);
      z += face === 1 ? out : -out;
    } else {
      const dx = face === 0 ? out / 2 : -out / 2;
      k.box(x + dx, by, z, out, bh, bw, wall);
      k.box(x + dx, by + bh, z, out + 0.03, 0.02, bw + 0.03, cap);
      x += face === 0 ? out : -out;
    }
  }
  k.pane(x, y, z, w, h, face, day, windowSched(b.kind, r), windowGlow(b.kind, r));
  // a strip a hair proud of the wall: only its face, since its edges are too thin ever to be seen and
  // a box for each sash and bar made a framed tower ten times the triangles of any other
  const flat = (along: number, yy: number, wa: number, hh: number, col: RGB) => {
    const a0 = along - wa / 2, a1 = along + wa / 2, y1 = yy + hh, o = 0.014;
    if (face === 1 || face === 3) {
      const zz = z + (face === 1 ? o : -o);
      k.quad([x + a0, yy, zz], [x + a1, yy, zz], [x + a1, y1, zz], [x + a0, y1, zz], col, [x + along, yy + hh / 2, z]);
    } else {
      const xx = x + (face === 0 ? o : -o);
      k.quad([xx, yy, z + a0], [xx, yy, z + a1], [xx, y1, z + a1], [xx, y1, z + a0], col, [x, yy + hh / 2, z + along]);
    }
  };
  // the strips are surface detail: no shadow (Kit.detail)
  k.detail(() => {
    if (s.frame !== undefined && small && h >= 0.06 && b.floors <= 8) {
      // white sashes: a sill, a head and two jambs round the pane, and a glazing bar across it
      const f = hex(s.frame), t = 0.012;
      flat(0, y - t, w + 2 * t, t, f);
      flat(0, y + h, w + 2 * t, t, f);
      for (const sd of [-1, 1]) flat(sd * (w / 2 + t / 2), y, t, h, f);
      flat(0, y + h * 0.55, w, t * 0.6, f);
    }
    // shutters and lintels only on low buildings, where they read and cost little
    if (!small || h < 0.06 || b.floors > 5) return;
    if (s.shutter) {
      const col = hex(s.shutter[Math.abs(Math.floor(x * 7 + z * 5 + y * 13)) % s.shutter.length]);
      for (const sd of [-1, 1]) flat(sd * (w / 2 + w * 0.22), y, w * 0.42, h, col);
    }
    if (s.lintel !== undefined) flat(0, y + h + 0.004, w * 1.3, 0.022, hex(s.lintel));
  });
}

/** n windows side by side, centred on (x, z), along the wall facing `face`. */
export function row(k: Kit, b: Building, r: Rng, x: number, y: number, z: number, width: number, h: number, n: number, face: number, day = GLASS): void {
  const cell = width / n;
  for (let i = 0; i < n; i++) {
    const o = -width / 2 + cell * (i + 0.5);
    if (face === 1 || face === 3) win(k, b, r, x + o, y, z, cell * 0.78, h, face, day);
    else win(k, b, r, x, y, z + o, cell * 0.78, h, face, day);
  }
}

/** A block with a ring of windows on every storey, massed and banded to its style; returns its top. */
export function tower(k: Kit, b: Building, r: Rng, x: number, y: number, z: number, w: number, d: number, floors: number, body: RGB, glass: RGB, band = 0.11): number {
  const h = floors * FLOOR;
  if (cur.plinth && y < FLOOR * 0.5 && floors > 1) {
    // a stone ground floor under the timber
    k.box(x, y, z, w, FLOOR, d, pick(r, cur.plinth));
    k.box(x, y + FLOOR, z, w, h - FLOOR, d, body);
  } else k.box(x, y, z, w, h, d, body);
  const wide = Math.max(band, cur.band);
  if (cur.massing === 'ribbed') {
    // piers running the full height at the corners, in the trim colour
    for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
      k.box(x + sx * (w / 2 - 0.025), y, z + sz * (d / 2 - 0.025), 0.08, h + 0.02, 0.08, styleTrim());
    }
  } else if (cur.massing === 'slab') {
    // blank end walls, the windows sandwiched between them
    for (const sx of [-1, 1]) k.box(x + sx * (w / 2 - 0.02), y, z, 0.07, h, d + 0.03, scale(body, 0.88));
  }
  const nx = Math.max(1, Math.round(w / 0.3)), nz = Math.max(1, Math.round(d / 0.3));
  for (let f = 0; f < floors; f++) {
    const fy = y + f * FLOOR + 0.07;
    row(k, b, r, x, fy, z + d / 2, w - 0.04, wide, nx, 1, glass);
    row(k, b, r, x, fy, z - d / 2, w - 0.04, wide, nx, 3, glass);
    row(k, b, r, x + w / 2, fy, z, d - 0.04, wide, nz, 0, glass);
    row(k, b, r, x - w / 2, fy, z, d - 0.04, wide, nz, 2, glass);
    if (cur.course > 0.3 && f > 0) {
      const t = 0.014 * cur.course;
      k.box(x, y + f * FLOOR - t / 2, z, w + 0.025, t, d + 0.025, styleTrim());
    }
  }
  if (cur.crown === 'curved' && !(cur.modernTall && floors > 12)) {
    // a little tiled skirt every third floor, the way a tall eastern building steps its eaves
    const skirt = scale(pick(r, cur.roofs), 0.9);
    for (let f = 3; f < floors; f += 3) k.box(x, y + f * FLOOR - 0.01, z, w + 0.1, 0.022, d + 0.1, skirt);
  }
  if (cur.balcony && floors >= cur.balcony.min && (!cur.balcony.flowers || floors <= 10)) {
    const only = cur.balcony.only;
    for (let f = 1; f < floors; f++) {
      // a Haussmann front has its balconies on the second floor and the fifth, not on every one
      if (only && !only.includes(f) && !(f === floors - 1 && only.includes(-1))) continue;
      for (const sz of [1, -1]) balcony(k, x, y + f * FLOOR, z + sz * d / 2, w * 0.86, sz > 0 ? 1 : 3);
    }
  }
  if (cur.massing === 'veranda' && y < FLOOR * 0.5) veranda(k, r, x, y, z, w, d, Math.min(FLOOR, h) * 0.92);
  if (cur.massing === 'porch' && y < FLOOR * 0.5) porch(k, r, x, y, z, w, d, Math.min(FLOOR, h) * 0.92);
  if (cur.massing === 'turret' && floors >= 2 && Math.min(w, d) >= 0.5) {
    // a round turret on each corner, standing proud of the walls and a storey above them, under a slate cone
    const R = Math.min(0.2, Math.min(w, d) * 0.16), top = y + h + FLOOR * 0.6;
    // the caps are tiled in the style's colours when it flies any, all four the same on one building
    const cone = cur.pennant ? pick(r, cur.pennant) : styleRoof(r);
    for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
      const tx = x + sx * (w / 2 - R * 0.35), tz = z + sz * (d / 2 - R * 0.35);
      k.cyl(tx, y, tz, R, top - y, body, 8);
      k.cyl(tx, top, tz, R * 1.15, 0.03, styleTrim(), 8);
      k.cone(tx, top + 0.03, tz, R * 1.2, R * 2.6, cone, 8);
      if (cur.pennant) pennant(k, tx, top + 0.03 + R * 2.6, tz, 0.16, pick(r, cur.pennant));
    }
    if (cur.pennant && y < FLOOR * 0.5) {
      // two long banners hung from the parapet down the front, in a colour of their own with a gold hem
      const col = pick(r, cur.pennant), hem = hex(0xe0b23a), bh = Math.min(h * 0.55, 0.9), bw = Math.min(0.12, w * 0.12);
      for (const sx of [-1, 1]) {
        const bx = x + sx * w * 0.22, fz = z + d / 2 + 0.012;
        k.box(bx, y + h - bh, fz, bw, bh, 0.012, col);
        k.box(bx, y + h - bh, fz + 0.004, bw, 0.03, 0.012, hem);
        k.box(bx, y + h - bh * 0.55, fz + 0.004, bw * 0.4, bw * 0.4, 0.012, hem);
      }
    }
  }
  if (cur.massing === 'arcaded' && floors > 2) {
    // a colonnade along the front at street level
    for (let i = 0; i < nx; i++) {
      const o = -w / 2 + (w / nx) * (i + 0.5);
      k.cyl(x + o, y, z + d / 2 + 0.03, (w / nx) * 0.13, FLOOR * 0.94, styleTrim(), 6);
    }
  }
  return y + h;
}

/**
 * When a style's signs are lit: from dusk until the last train has long gone. Not too bright: a strong
 * glow washes a saturated pink or cyan out to white, and neon is all colour.
 */
export const NEON_HOURS: Sched = [17, 30.5, 1.35];

/** One of the style's neon colours, or a fallback pink where it has none. */
export function neonColour(r: Rng): RGB {
  const cols = cur.neon;
  return hex(cols ? cols[Math.floor(r() * cols.length)] : 0xff2e7a);
}

/**
 * A vertical blade sign standing out from a front at (x, z), a panel a storey from y0 to y1: each panel
 * its own colour by day and lit after dark, on a dark frame.
 */
export function bladeSign(k: Kit, r: Rng, x: number, y0: number, y1: number, z: number, out = 0.24): void {
  if (y1 - y0 < FLOOR * 0.8) return;
  k.box(x, y0 - 0.02, z + out / 2, 0.045, y1 - y0 + 0.04, out + 0.02, DARK);
  const panels: [number, number][] = [];
  for (let fy = y0; fy + FLOOR * 0.5 < y1; fy += FLOOR) {
    const c = neonColour(r), top = Math.min(y1, fy + FLOOR) - 0.012;
    k.glowBox(x, fy + 0.012, z + out / 2 + 0.004, 0.07, top - fy - 0.012, out, scale(c, 0.62), NEON_HOURS, c);
    panels.push([fy + 0.012, top]);
  }
  // what the sign says, a character a panel from the top down, on both faces of the blade
  const word = [...SIGN_WORDS[Math.floor(r() * SIGN_WORDS.length)]];
  const za = z + 0.004 + out * 0.1, zb = z + 0.004 + out * 0.9;
  panels.reverse().forEach(([b, t], i) => {
    const ch = word[i % word.length], h = t - b, m = Math.max(0, (h - (zb - za)) / 2), yb = b + m, yt = t - m;
    for (const sx of [1, -1]) {
      const fx = x + sx * 0.037;
      // read from outside that face: its right hand runs toward the street on one side, the wall on the other
      const [zl, zr] = sx > 0 ? [zb, za] : [za, zb];
      k.glyph(ch, [fx, yb, zl], [fx, yb, zr], [fx, yt, zr], [fx, yt, zl]);
    }
  });
}

/**
 * What a style hangs on its street buildings whichever model each draws, called by townMesh's
 * drawBuilding in the building's own frame (front +z, lot W by D): Tokyo's neon, New York's fire
 * escapes and rooftop water tanks.
 */
export function styleDress(k: Kit, r: Rng, W: number, D: number, floors: number): void {
  const w = W - 0.16, d = D - 0.2;
  // a Las Vegas hangs the Strip's own signs, and only on the Strip; every other neon style its blade signs
  if (curArch === 'vegas') { if (!offStrip) stripSigns(k, r, w, d, floors); } else if (cur.neon) neonSigns(k, r, 0, 0, 0, w, d, floors);
  if (cur.fireEscape !== undefined && floors >= 4 && floors <= 10) fireEscape(k, r, w, d, floors, hex(cur.fireEscape));
  if (cur.waterTank !== undefined && floors >= 5 && floors <= 24 && r() < 0.5) waterTank(k, r, w, d, floors * FLOOR, hex(cur.waterTank));
  if (cur.bigSigns && floors >= 2 && floors <= 16 && w >= 0.55 && r() < cur.bigSigns) osakaDress(k, r, w, d, floors, FLOOR);
  if (cur.laundry && floors >= 2 && floors <= 6 && r() < 0.5) laundry(k, r, w, d, floors, cur.laundry);
  if (cur.chochin && floors <= 4 && r() < 0.7) chochin(k, r, w, d, cur.chochin);
}

/** The lantern hours: lit from dusk to past midnight. */
const CHOCHIN_HOURS: Sched = [17.2, 25.5, 1.4];

/**
 * A paper lantern (chōchin) hung under the eave beside the door, a black cap and foot, lit after dark (an onsen
 * town's StyleSpec.chochin); one either side of the door on a wide front.
 */
function chochin(k: Kit, r: Rng, w: number, d: number, cols: readonly number[]): void {
  const col = pick(r, cols), y = FLOOR * 0.62, z = d / 2 + 0.07, two = w > 0.75 && r() < 0.5;
  const at = two ? [-w * 0.3, w * 0.3] : [(r() < 0.5 ? -1 : 1) * w * 0.32];
  for (const x of at) {
    k.box(x, y + 0.075, z - 0.035, 0.006, 0.006, 0.07, DARK);
    k.box(x, y + 0.06, z, 0.042, 0.012, 0.042, DARK);
    k.glowBox(x, y - 0.02, z, 0.05, 0.08, 0.05, col, CHOCHIN_HOURS, scale(col, 1.25));
    k.box(x, y - 0.032, z, 0.036, 0.012, 0.036, DARK);
  }
}

/**
 * A washing line across a front, under a window a floor or two up: a bracket at each end, the line sagging
 * between them and three to six things pegged out on it (the Adriatic's StyleSpec.laundry).
 */
function laundry(k: Kit, r: Rng, w: number, d: number, floors: number, cloth: readonly number[]): void {
  const f = 1 + Math.floor(r() * Math.min(2, floors - 1)), y = f * FLOOR - 0.01, z = d / 2 + 0.06, x0 = -w / 2 + 0.05, x1 = w / 2 - 0.05;
  const sag = 0.02, n = 3 + Math.floor(r() * 4), line = hex(0xd8d4cc);
  for (const x of [x0, x1]) k.box(x, y - 0.01, z - 0.03, 0.01, 0.01, 0.07, DARK);
  k.bar([x0, y, z], [0, y - sag, z], 0.003, line);
  k.bar([0, y - sag, z], [x1, y, z], 0.003, line);
  for (let i = 0; i < n; i++) {
    const t = (i + 0.5) / n, x = x0 + (x1 - x0) * t, yy = y - sag * (1 - Math.abs(2 * t - 1));
    const cw = 0.05 + r() * 0.05, ch = 0.04 + r() * 0.06;
    k.box(x, yy - ch, z, cw, ch, 0.006, pick(r, cloth));
  }
}

/** A fire escape down a front: a landing at every floor from the second, a rail round it and a stair between. */
function fireEscape(k: Kit, r: Rng, w: number, d: number, floors: number, iron: RGB): void {
  const fw = Math.min(0.42, w * 0.4), x = (r() < 0.5 ? -1 : 1) * (w / 2 - fw / 2 - 0.06), z = d / 2 + 0.05;
  for (let f = 1; f < floors; f++) {
    const y = f * FLOOR;
    k.box(x, y, z, fw, 0.012, 0.1, iron);
    k.box(x, y + 0.06, z + 0.05, fw, 0.008, 0.008, iron);
    for (const s of [-1, 1]) k.box(x + s * fw / 2, y, z + 0.05, 0.008, 0.06, 0.008, iron);
    // the stair runs down to the landing below, turning one way and then the other
    if (f > 1) {
      const s = f % 2 ? 1 : -1;
      k.bar([x - s * fw * 0.4, y, z + 0.02], [x + s * fw * 0.4, y - FLOOR + 0.012, z + 0.02], 0.008, iron);
    }
  }
  // and the drop ladder, folded up over the street
  k.box(x + fw * 0.3, FLOOR * 0.55, z + 0.03, 0.05, FLOOR * 0.45, 0.008, iron);
}

/** A wooden water tank on four steel legs, a band or two round it and a pointed lid, near a back corner of the roof. */
function waterTank(k: Kit, r: Rng, w: number, d: number, roof: number, wood: RGB): void {
  const R = 0.09 + r() * 0.04, x = (r() < 0.5 ? -1 : 1) * Math.max(0, w / 2 - R - 0.12), z = -Math.max(0, d / 2 - R - 0.12), y = roof + 0.02;
  const steel = hex(0x3a3a3e), legs = 0.14;
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.box(x + sx * R * 0.6, y, z + sz * R * 0.6, 0.015, legs, 0.015, steel);
  k.box(x, y + legs - 0.01, z, R * 1.7, 0.012, R * 1.7, steel);
  k.cyl(x, y + legs, z, R, 0.26, wood, 10);
  for (const b of [0.07, 0.18]) k.cyl(x, y + legs + b, z, R * 1.02, 0.012, steel, 10);
  k.cone(x, y + legs + 0.26, z, R * 1.08, 0.1, scale(wood, 0.8), 10);
}

/**
 * The signs on a street building in a neon style (StyleSpec.neon), whichever model it draws (called by
 * townMesh's drawBuilding): a lit fascia over the shops, a blade sign up a front corner once there is a
 * floor above them (both corners on a wide front), and now and then a billboard on the roof.
 */
function neonSigns(k: Kit, r: Rng, x: number, y: number, z: number, w: number, d: number, floors: number): void {
  const h = floors * FLOOR;
  const fc = neonColour(r);
  k.glowBox(x, y + FLOOR * 0.74, z + d / 2 + 0.018, w * 0.86, 0.07, 0.03, scale(fc, 0.62), NEON_HOURS, fc);
  if (floors < 2) return;
  const reach = FLOOR * Math.min(floors, 2 + Math.floor(r() * 8));
  const side = r() < 0.5 ? -1 : 1;
  bladeSign(k, r, x + side * (w / 2 - 0.08), y + FLOOR * 0.95, y + Math.min(h - 0.04, reach), z + d / 2);
  if (w > 1.2 && floors >= 3 && r() < 0.5) bladeSign(k, r, x - side * (w / 2 - 0.08), y + FLOOR * 0.95, y + Math.min(h - 0.04, reach * 0.7), z + d / 2);
  // a billboard on the roof, facing the street on two legs
  if (floors >= 3 && floors <= 14 && r() < 0.35) {
    const bw = w * 0.78, bz = z - d * 0.12, top = y + h;
    for (const sx of [-0.35, 0.35]) k.box(x + sx * bw, top, bz - 0.03, 0.03, 0.14, 0.03, DARK);
    k.box(x, top + 0.12, bz - 0.03, bw + 0.04, 0.38, 0.03, DARK);
    const c = neonColour(r);
    k.glowBox(x, top + 0.14, bz, bw, 0.34, 0.02, scale(c, 0.62), NEON_HOURS, c);
  }
}

/** A flagpole standing on (x, y, z) with a pennant flying off it: a long strip tapering to a point, streaming +x. */
export function pennant(k: Kit, x: number, y: number, z: number, h: number, col: RGB): void {
  k.box(x, y, z, 0.012, h, 0.012, hex(0x2a2a2e));
  const fy = y + h - 0.055;
  k.box(x + 0.05, fy, z, 0.09, 0.045, 0.008, col);
  k.box(x + 0.12, fy + 0.01, z, 0.06, 0.025, 0.008, col);
}

/** Whatever this style puts on top of a tall building; returns the new top. */
export function topOff(k: Kit, r: Rng, x: number, y: number, z: number, w: number, d: number, body: RGB): number {
  switch (cur.crown) {
    case 'step': {
      let top = y;
      for (let i = 0; i < 3; i++) {
        const f = 1 - i * 0.22;
        k.box(x, top, z, w * f, 0.08, d * f, i % 2 ? styleTrim() : body);
        top += 0.08;
      }
      k.cyl(x, top, z, 0.025, 0.4, METAL, 6);
      return top + 0.4;
    }
    case 'spire': {
      k.box(x, y, z, w + 0.05, 0.06, d + 0.05, styleTrim());
      for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
        k.cone(x + sx * (w / 2 - 0.05), y + 0.06, z + sz * (d / 2 - 0.05), 0.05, 0.26, body, 6);
      }
      k.cone(x, y + 0.06, z, Math.min(w, d) * 0.36, 0.62, body, 8);
      return y + 0.68;
    }
    case 'pitched':
      if (cur.form) return roofOver(k, r, x, y, z, w, d, body, styleRoof(r));
      k.gable(x, y, z, w + 0.05, 0.16 + Math.min(w, d) * 0.1, d + 0.05, styleRoof(r), body, d > w);
      return y + 0.2 + Math.min(w, d) * 0.1;
    case 'sawtooth':
      for (let i = 0; i < 3; i++) {
        k.gable(x, y, z - d / 2 + (d / 3) * (i + 0.5), w + 0.03, 0.12, d / 3, styleRoof(r), body);
      }
      return y + 0.14;
    case 'wall':
      return flatTop(k, r, x, y, z, w, d, body);
    case 'dome': {
      const top = flatTop(k, r, x, y, z, w, d, body);
      if (r() < 0.35) {
        const R = Math.min(w, d) * 0.22;
        k.cyl(x, top, z, R * 1.02, 0.08, body, 12);
        k.dome(x, top + 0.08, z, R, styleTrim(), 12, 4);
        return top + 0.08 + R;
      }
      return top;
    }
    case 'hipped': {
      const h = Math.min(0.9, 0.14 + Math.min(w, d) * cur.pitch * 0.55);
      k.hip(x, y, z, w + 2 * cur.eaves, h, d + 2 * cur.eaves, styleRoof(r));
      return y + h;
    }
    case 'dutch': {
      // a row of steep gables end-on to the street, each behind its own stepped, neck or bell front, front and back
      const n = Math.max(1, Math.round(w / 0.8)), gw = w / n, h = Math.min(0.7, gw * 0.85), roof = styleRoof(r), trim = styleTrim();
      for (let i = 0; i < n; i++) {
        const gx = x - w / 2 + gw * (i + 0.5), kind = GABLES[Math.floor(r() * GABLES.length)];
        k.gable(gx, y, z, gw, h, d, roof, body, true);
        for (const s of [1, -1] as const) gableFace(k, gx, y, z + s * (d / 2 + 0.012), gw + 0.02, h * 1.12, body, trim, kind, true, s);
        hoist(k, gx, y + h * 0.8, z + d / 2 + 0.012, true, 1);
      }
      return y + h * 1.12 + 0.06;
    }
    case 'onion': {
      // a low hip, a drum on the ridge and an onion over it: green or oxblood roof, gilded dome
      const h = Math.min(0.7, 0.12 + Math.min(w, d) * cur.pitch * 0.4);
      k.hip(x, y, z, w + 2 * cur.eaves, h, d + 2 * cur.eaves, styleRoof(r));
      const R = Math.min(0.26, Math.min(w, d) * 0.2);
      return onionDome(k, x, y + h, z, R, pick(r, ONION_SKINS), styleTrim());
    }
    case 'cupola': {
      // a steep hip laid in patterned tiles over a white ledge, and a domed tower on the front corner
      const h = Math.min(0.8, 0.14 + Math.min(w, d) * cur.pitch * 0.5), roof = styleRoof(r), accent = pick(r, cur.tiles ?? cur.roofs);
      k.box(x, y - 0.03, z, w + 0.06, 0.03, d + 0.06, styleTrim());
      tiledHip(k, x, y, z, w + 0.04, h, d + 0.04, roof, accent);
      let top = y + h;
      if (Math.min(w, d) >= 0.7) {
        const R = Math.min(0.22, Math.min(w, d) * 0.18), cx = x + w / 2 - R, cz = z + d / 2 - R, dy = y + 0.26;
        k.cyl(cx, y, cz, R, 0.26, body, 10);
        k.cyl(cx, dy, cz, R * 1.1, 0.025, styleTrim(), 10);
        k.dome(cx, dy + 0.025, cz, R, accent, 10, 3);
        k.cyl(cx, dy + 0.025 + R * 0.9, cz, R * 0.28, 0.08, styleTrim(), 6);
        k.cone(cx, dy + 0.105 + R * 0.9, cz, R * 0.3, 0.16, accent, 6);
        top = Math.max(top, dy + 0.265 + R * 0.9);
      }
      return top;
    }
    case 'false': {
      // a flat roof behind a tall square front with a heavy cornice across its top
      const top = flatTop(k, r, x, y, z, w, d, body), fh = 0.18, cap = scale(body, 0.68);
      k.box(x, y, z + d / 2 - 0.02, w + 0.02, fh, 0.04, body);
      k.box(x, y + fh, z + d / 2 - 0.02, w + 0.08, 0.025, 0.07, cap);
      return Math.max(top, y + fh + 0.025);
    }
    case 'curved': {
      const h = Math.min(0.8, 0.14 + Math.min(w, d) * cur.pitch * 0.5);
      flared(k, x, y, z, w + 2 * cur.eaves, h, d + 2 * cur.eaves, styleRoof(r), body, d > w);
      return y + h;
    }
    case 'battlement': {
      // a walk behind a crenellated parapet: merlons all round, a gap between each
      const t = 0.045, ph = 0.07, mh = 0.07, trim = styleTrim();
      k.box(x, y, z, w - 2 * t, 0.006, d - 2 * t, scale(body, 0.8));
      for (const sz of [-1, 1]) k.box(x, y, z + sz * (d / 2 - t / 2), w + 0.02, ph, t, body);
      for (const sx of [-1, 1]) k.box(x + sx * (w / 2 - t / 2), y, z, t, ph, d - 2 * t, body);
      k.box(x, y + ph - 0.012, z, w + 0.04, 0.012, d + 0.04, trim);
      const merlons = (len: number, place: (o: number) => void) => {
        const n = Math.max(2, Math.round(len / 0.13));
        for (let i = 0; i < n; i += 2) place(-len / 2 + (len / n) * (i + 0.5));
      };
      merlons(w, (o) => { for (const sz of [-1, 1]) k.box(x + o, y + ph, z + sz * (d / 2 - t / 2), w / Math.max(2, Math.round(w / 0.13)), mh, t, body); });
      merlons(d, (o) => { for (const sx of [-1, 1]) k.box(x + sx * (w / 2 - t / 2), y + ph, z + o, t, mh, d / Math.max(2, Math.round(d / 0.13)), body); });
      return y + ph + mh;
    }
    case 'mansard': {
      // the steep lower slope in zinc, a low hip over it, a dormer every bay front and back, and stacks
      const roof = styleRoof(r), trim = styleTrim(), mh = 0.26, inset = 0.07;
      k.box(x, y, z, w + 0.05, 0.04, d + 0.05, trim);
      const y0 = y + 0.04, y1 = y0 + mh, a = w / 2, b = d / 2, ia = a - inset, ib = d / 2 - inset;
      const I: P3 = [x, y0 + mh / 2, z];
      k.quad([x - a, y0, z + b], [x + a, y0, z + b], [x + ia, y1, z + ib], [x - ia, y1, z + ib], roof, I);
      k.quad([x - a, y0, z - b], [x + a, y0, z - b], [x + ia, y1, z - ib], [x - ia, y1, z - ib], roof, I);
      k.quad([x + a, y0, z - b], [x + a, y0, z + b], [x + ia, y1, z + ib], [x + ia, y1, z - ib], roof, I);
      k.quad([x - a, y0, z - b], [x - a, y0, z + b], [x - ia, y1, z + ib], [x - ia, y1, z - ib], roof, I);
      const top = Math.min(0.16, Math.min(w, d) * 0.12);
      k.hip(x, y1, z, ia * 2, top, ib * 2, scale(roof, 0.9));
      const n = Math.max(1, Math.round(w / 0.3));
      for (let i = 0; i < n; i++) {
        const dx = x - a + (w / n) * (i + 0.5);
        for (const s of [1, -1] as const) {
          const dz = z + s * (b - inset * 0.55);
          k.box(dx, y0 + 0.05, dz, 0.1, 0.13, 0.06, trim);
          k.pane(dx, y0 + 0.07, dz + s * 0.031, 0.06, 0.08, s > 0 ? 1 : 3, styleGlass(r), [18, 24, 1.1], WARM_GLOW);
          k.gable(dx, y0 + 0.18, dz, 0.11, 0.05, 0.07, roof, trim);
        }
      }
      for (const sx of [-1, 1]) {
        k.box(x + sx * (a - 0.05), y0, z, 0.07, mh + top + 0.08, 0.24, scale(body, 0.95));
        for (let j = -1; j <= 1; j++) k.cyl(x + sx * (a - 0.05), y0 + mh + top + 0.08, z + j * 0.07, 0.018, 0.04, hex(0xb8603a), 6);
      }
      return y1 + top;
    }
    case 'chhatri': {
      // a cusped parapet, a little domed kiosk on four legs at each corner, and now and then a marble dome
      const trim = styleTrim(), ph = 0.07;
      k.box(x, y, z, w + 0.05, 0.03, d + 0.05, trim);
      const top = flatTop(k, r, x, y + 0.03, z, w, d, body);
      const R = Math.min(0.11, Math.min(w, d) * 0.13);
      if (Math.min(w, d) >= 0.5) {
        for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
          const cx = x + sx * (w / 2 - R), cz = z + sz * (d / 2 - R);
          for (const a of [-1, 1]) for (const b of [-1, 1]) k.box(cx + a * R * 0.6, top, cz + b * R * 0.6, 0.016, 0.1, 0.016, trim);
          k.box(cx, top + 0.1, cz, R * 2.1, 0.014, R * 2.1, trim);
          k.dome(cx, top + 0.114, cz, R * 0.85, trim, 8, 3);
        }
      }
      if (Math.min(w, d) >= 0.9 && r() < 0.4) {
        const D = Math.min(w, d) * 0.2;
        k.cyl(x, top, z, D * 1.05, 0.08, body, 12);
        return onionDome(k, x, top + 0.08, z, D, hex(0xf4efe4), trim);
      }
      return top + ph + 0.12;
    }
    case 'toron': {
      // a mud parapet drawn up into a pinnacle at each corner and along the front, palm sticks left in the wall
      const top = flatTop(k, r, x, y, z, w, d, body), stick = hex(cur.vigas ?? 0x4a3222);
      const n = Math.max(2, Math.round(w / 0.32));
      for (let i = 0; i <= n; i++) {
        const px = x - w / 2 + 0.03 + ((w - 0.06) * i) / n;
        for (const sz of [-1, 1]) {
          k.cone(px, top - 0.02, z + sz * (d / 2 - 0.03), 0.035, 0.13, body, 5);
          if (y > 0.5) for (const dy of [0.12, 0.3]) k.box(px + 0.05, y - dy, z + sz * (d / 2 + 0.03), 0.014, 0.014, 0.06, stick);
        }
      }
      return top + 0.11;
    }
    case 'parapet':
      k.box(x, y, z, w + 0.06, 0.04, d + 0.06, styleTrim());
      k.box(x, y + 0.04, z, w + 0.02, 0.09, d + 0.02, body);
      k.box(x, y + 0.13, z, w + 0.06, 0.035, d + 0.06, styleTrim());
      return y + 0.17;
    default:
      k.box(x, y, z, w + 0.03, 0.05, d + 0.03, scale(body, 0.9));
      return y + 0.05;
  }
}

// ---------------------------------------------------------------------------------------------
// the biomes' pieces: flat tops, flared eaves, verandas, balconies and style-aware small roofs

/** A flat roof behind a parapet flush with the wall, with roof beams poking out if the style has vigas; returns the top. */
export function flatTop(k: Kit, r: Rng, x: number, y: number, z: number, w: number, d: number, wall: RGB): number {
  const t = Math.min(0.035, w * 0.08), ph = 0.06;
  const cap = cur.form === 'hip' ? styleTrim() : wall;
  k.box(x, y, z, w - 2 * t, 0.006, d - 2 * t, scale(pick(r, cur.roofs), 0.96));
  for (const sz of [-1, 1]) k.box(x, y, z + sz * (d / 2 - t / 2), w, ph, t, cap);
  for (const sx of [-1, 1]) k.box(x + sx * (w / 2 - t / 2), y, z, t, ph, d - 2 * t, cap);
  // a painted frieze round the top of the wall, standing a hair proud of it
  if (cur.frieze !== undefined) k.box(x, y - 0.075, z, w + 0.014, 0.06, d + 0.014, hex(cur.frieze));
  if (cur.vigas !== undefined) {
    const n = Math.max(2, Math.round(w / 0.11)), beam = hex(cur.vigas);
    for (let i = 0; i < n; i++) {
      const o = -w / 2 + (w / n) * (i + 0.5);
      for (const sz of [-1, 1]) k.box(x + o, y - 0.045, z + sz * (d / 2 + 0.025), 0.022, 0.022, 0.05, beam);
    }
  }
  return y + ph;
}

/**
 * A tiled roof whose lower slopes flatten and whose eave corners turn up, the ridge running along x
 * (or z) and capped with a dark beam that curls up at each end.
 */
export function flared(k: Kit, x: number, y: number, z: number, w: number, h: number, d: number, roof: RGB, end: RGB, alongZ = false): void {
  const L = (alongZ ? d : w) / 2, H = (alongZ ? w : d) / 2;
  const P = (u: number, v: number, yy: number): P3 => (alongZ ? [x + v, yy, z + u] : [x + u, yy, z + v]);
  const I = P(0, 0, y + h * 0.2);
  const knee = y + h * 0.3, lift = h * 0.22, a = Math.min(L * 0.3, 0.14);
  const dark = scale(roof, 0.7);
  for (const sv of [-1, 1]) {
    const e = sv * H, kv = sv * H * 0.5;
    // the flared lower slope in three strips, the outer two turned up at the corners
    const us = [-L, -L + a, L - a, L], ys = [y + lift, y, y, y + lift];
    for (let i = 0; i < 3; i++) k.quad(P(us[i], e, ys[i]), P(us[i + 1], e, ys[i + 1]), P(us[i + 1], kv, knee), P(us[i], kv, knee), roof, I);
    k.quad(P(-L, kv, knee), P(L, kv, knee), P(L, 0, y + h), P(-L, 0, y + h), roof, I);
  }
  for (const su of [-1, 1]) {
    const u = su * L, c = P(u, 0, y + lift);
    k.tri(c, P(u, -H, y + lift), P(u, -H * 0.5, knee), end, I);
    k.tri(c, P(u, -H * 0.5, knee), P(u, 0, y + h), end, I);
    k.tri(c, P(u, 0, y + h), P(u, H * 0.5, knee), end, I);
    k.tri(c, P(u, H * 0.5, knee), P(u, H, y + lift), end, I);
    k.bar(P(u * 0.98, 0, y + h + 0.01), P(u + su * 0.07, 0, y + h + 0.09), 0.018, dark);
  }
  k.bar(P(-L, 0, y + h + 0.01), P(L, 0, y + h + 0.01), 0.022, dark);
}

/** A roofed colonnade round every face of a ground floor of w×d, `h` tall. */
export function veranda(k: Kit, r: Rng, x: number, y: number, z: number, w: number, d: number, h: number): void {
  const out = Math.min(0.12, Math.max(0.07, Math.min(w, d) * 0.12)), post = styleTrim();
  const roof = cur.plinth ? hex(0x7a5232) : pick(r, cur.roofs);
  k.box(x, y + h, z, w + 2 * out + 0.02, 0.025, d + 2 * out + 0.02, roof);
  k.box(x, y, z, w + 2 * out, 0.02, d + 2 * out, scale(pick(r, cur.walls), 0.86));
  const run = (len: number) => Math.max(1, Math.round(len / 0.26));
  const nx = run(w + 2 * out), nz = run(d + 2 * out);
  for (let i = 0; i <= nx; i++) {
    const px = x - w / 2 - out + ((w + 2 * out) * i) / nx;
    for (const sz of [-1, 1]) k.box(px, y, z + sz * (d / 2 + out - 0.01), 0.018, h, 0.018, post);
  }
  for (let i = 1; i < nz; i++) {
    const pz = z - d / 2 - out + ((d + 2 * out) * i) / nz;
    for (const sx of [-1, 1]) k.box(x + sx * (w / 2 + out - 0.01), y, pz, 0.018, h, 0.018, post);
  }
}

/** A balcony `w` long on the wall facing `face` (1 front, 3 back), its floor at y. */
export function balcony(k: Kit, x: number, y: number, z: number, w: number, face: 1 | 3): void {
  const spec = cur.balcony;
  if (!spec) return;
  const sz = face === 1 ? 1 : -1, rail = hex(spec.rail), dep = 0.07;
  k.box(x, y - 0.012, z + sz * dep / 2, w, 0.014, dep, spec.flowers ? hex(0x8a5a36) : styleTrim());
  k.box(x, y, z + sz * (dep - 0.006), w, 0.045, 0.012, rail);
  if (spec.flowers) k.box(x, y + 0.045, z + sz * (dep - 0.006), w * 0.92, 0.022, 0.03, hex(0xd8344a), hex(0xe8506a));
}

// ---------------------------------------------------------------------------------------------
// the themed towns' pieces: Dutch gable fronts, Zsolnay-tiled hips, frontier false fronts and porches

/** The three shapes a Dutch gable front takes: crow-stepped, a tall neck on scrolled shoulders, or a bell curve. */
type GableKind = 'step' | 'neck' | 'bell';
export const GABLES: readonly GableKind[] = ['step', 'neck', 'bell'];
/** How wide each tier of a bell gable is, bottom to top, as a share of the front. */
const BELL = [1, 0.92, 0.8, 0.64, 0.5, 0.4];

/**
 * A gable front standing up from a wall's top at y: `width` across and `h` tall, in the plane z = `z`
 * (`axisZ`) or x = `x`, its outer face flush with that plane on the `sign` side. Every tier is coped in
 * the trim colour, the way the brick fronts on an Amsterdam canal are edged in white stone.
 */
export function gableFace(k: Kit, x: number, y: number, z: number, width: number, h: number, wall: RGB, trim: RGB, kind: GableKind, axisZ: boolean, sign: 1 | -1): void {
  const t = 0.05;
  const put = (u: number, v: number, bw: number, bh: number, depth: number, col: RGB, out = 0) => {
    const c = sign * (out - depth / 2);
    if (axisZ) k.box(x + u, v, z + c, bw, bh, depth, col);
    else k.box(x + c, v, z + u, depth, bh, bw, col);
  };
  const cope = (v: number, bw: number) => put(0, v, bw + 0.02, 0.018, t + 0.012, trim, 0.006);
  switch (kind) {
    case 'step': {
      const n = 4, th = h / n;
      for (let i = 0; i < n; i++) {
        const bw = width * (1 - i / (n + 0.4));
        put(0, y + i * th, bw, th, t, wall);
        cope(y + (i + 1) * th - 0.018, bw);
      }
      put(0, y + h, 0.05, 0.08, 0.05, trim);
      return;
    }
    case 'neck': {
      const base = h * 0.34, nw = width * 0.42, nh = h * 0.56;
      put(0, y, width, base, t, wall);
      cope(y + base - 0.018, width);
      // scrolled shoulders either side of the neck, in the trim colour
      for (const s of [-1, 1]) {
        put(s * (nw / 2 + width * 0.07), y + base, width * 0.12, nh * 0.45, t * 0.8, trim);
        put(s * (nw / 2 + width * 0.03), y + base + nh * 0.45, width * 0.05, nh * 0.2, t * 0.8, trim);
      }
      put(0, y + base, nw, nh, t, wall);
      // a little pediment on the neck
      const py = y + base + nh;
      if (axisZ) k.gable(x, py, z - sign * t / 2, nw + 0.04, h * 0.12, t + 0.01, trim, trim, true);
      else k.gable(x - sign * t / 2, py, z, t + 0.01, h * 0.12, nw + 0.04, trim, trim, false);
      return;
    }
    default: {
      const th = h / BELL.length;
      for (let i = 0; i < BELL.length; i++) {
        const bw = width * BELL[i];
        put(0, y + i * th, bw, th, t, wall);
        if (i === 0 || BELL[i] < BELL[i - 1] - 0.1) cope(y + i * th - 0.009, BELL[i - 1] ? width * BELL[i - 1] : bw);
      }
      cope(y + h - 0.018, width * BELL[BELL.length - 1]);
      put(0, y + h, width * 0.2, 0.04, t, trim);
    }
  }
}

/** The hoist beam under the peak of a Dutch gable, a hook hanging off its end. */
export function hoist(k: Kit, x: number, y: number, z: number, axisZ: boolean, sign: 1 | -1): void {
  const beam = hex(0x3a2e26);
  if (axisZ) {
    k.box(x, y, z + sign * 0.05, 0.025, 0.025, 0.1, beam);
    k.box(x, y - 0.05, z + sign * 0.095, 0.006, 0.05, 0.006, DARK);
  } else {
    k.box(x + sign * 0.05, y, z, 0.1, 0.025, 0.025, beam);
    k.box(x + sign * 0.095, y - 0.05, z, 0.006, 0.05, 0.006, DARK);
  }
}

/**
 * A hipped roof laid in patterned glazed tiles: five courses from eaves to peak, each face alternating
 * its courses between the base colour and the accent, and each face a step out of turn with the next,
 * so the colours zigzag round the roof as they do on Matthias Church and the Budapest markets.
 */
export function tiledHip(k: Kit, x: number, y: number, z: number, w: number, h: number, d: number, base: RGB, accent: RGB): void {
  const n = 5, I: P3 = [x, y + h / 4, z];
  for (let j = 0; j < n; j++) {
    const f0 = j / n, f1 = (j + 1) / n;
    const ax = (w / 2) * (1 - f0), az = (d / 2) * (1 - f0), bx = (w / 2) * (1 - f1), bz = (d / 2) * (1 - f1);
    const y0 = y + h * f0, y1 = y + h * f1;
    const corners0: P3[] = [[x - ax, y0, z - az], [x + ax, y0, z - az], [x + ax, y0, z + az], [x - ax, y0, z + az]];
    const corners1: P3[] = [[x - bx, y1, z - bz], [x + bx, y1, z - bz], [x + bx, y1, z + bz], [x - bx, y1, z + bz]];
    for (let s = 0; s < 4; s++) {
      const col = (j + s) % 2 === 0 ? base : accent;
      const a = corners0[s], b = corners0[(s + 1) % 4], c = corners1[(s + 1) % 4], e = corners1[s];
      if (j === n - 1) k.tri(a, b, [x, y + h, z], col, I);
      else k.quad(a, b, c, e, col, I);
    }
  }
}

/** Board colours for a frontier sign. */
const SIGNS = [0x3a2a1e, 0x7a2a22, 0x2f4a3a, 0xe8dcc0, 0x2a3a5a];

/**
 * A frontier roof: a gable end-on to the street hidden behind a tall square false front, sometimes with a
 * raised middle step, a heavy cornice along its top and a painted sign board across it; returns the top.
 */
export function falseFront(k: Kit, r: Rng, x: number, y: number, z: number, w: number, d: number, wall: RGB, roof: RGB): number {
  const h = Math.min(0.36, w * cur.pitch * 0.55);
  k.gable(x, y, z, w + 0.04, h, d + 0.04, roof, wall, true);
  // the front stands just proud of the gable end behind it, so the two never share a plane
  const ff = z + d / 2 + 0.031, fh = h + 0.14, cap = scale(wall, 0.66);
  k.box(x, y, ff - 0.025, w + 0.04, fh, 0.05, wall);
  const stepped = r() < 0.4;
  k.box(x, y + fh, ff - 0.03, w + 0.08, 0.022, 0.08, cap);
  if (stepped) {
    k.box(x, y + fh + 0.022, ff - 0.025, w * 0.42, 0.07, 0.05, wall);
    k.box(x, y + fh + 0.092, ff - 0.03, w * 0.42 + 0.04, 0.02, 0.07, cap);
  }
  // the sign, and a line of pale letters painted on it
  const sign = pick(r, SIGNS), ink = sign[0] + sign[1] + sign[2] > 2 ? hex(0x3a2a1e) : hex(0xf2e8cc);
  const sw = Math.min(w * 0.72, 0.9), sy = y + fh * 0.3;
  k.box(x, sy, ff + 0.004, sw, fh * 0.42, 0.01, sign);
  const n = Math.max(3, Math.round(sw / 0.07));
  for (let i = 0; i < n; i++) if (r() < 0.85) k.box(x - sw * 0.4 + (sw * 0.8 * (i + 0.5)) / n, sy + fh * 0.14, ff + 0.011, (sw * 0.8) / n * 0.6, fh * 0.14, 0.004, ink);
  return y + fh + (stepped ? 0.112 : 0.022);
}

/** A boardwalk porch along the front of a ground floor w×d standing on y: plank deck, posts, a tin roof over it, a hitching rail. */
export function porch(k: Kit, r: Rng, x: number, y: number, z: number, w: number, d: number, h: number): void {
  const out = 0.16, fz = z + d / 2, plank = hex(0x8a6a48), post = hex(0x6e5438), roof = pick(r, cur.roofs);
  k.box(x, y, fz + out / 2, w + 0.04, 0.03, out, plank);
  const n = Math.max(2, Math.round(w / 0.28));
  for (let i = 0; i <= n; i++) k.box(x - w / 2 + 0.01 + ((w - 0.02) * i) / n, y + 0.03, fz + out - 0.012, 0.02, h - 0.03, 0.02, post);
  k.box(x, y + h, fz + out / 2, w + 0.06, 0.02, out + 0.03, roof);
  k.box(x, y + 0.03 + h * 0.4, fz + out - 0.012, w, 0.014, 0.014, post);
}

/**
 * The small roof of a block w×d standing to y, in this style's form: a flat top behind a parapet, a
 * steep or low gable, a hip, or flared eaves; returns the top. `form` overrides the style's own.
 */
export function roofOver(k: Kit, r: Rng, x: number, y: number, z: number, w: number, d: number, wall: RGB, roof: RGB, form = cur.form): number {
  const e = cur.eaves, m = Math.min(w, d);
  switch (form) {
    case 'flat':
      return flatTop(k, r, x, y, z, w, d, wall);
    case 'hip': {
      const h = Math.min(0.9, m * cur.pitch * 0.9);
      if (cur.tiles) tiledHip(k, x, y, z, w + 2 * e, h, d + 2 * e, roof, pick(r, cur.tiles));
      else k.hip(x, y, z, w + 2 * e, h, d + 2 * e, roof);
      return y + h;
    }
    case 'curved': {
      const h = Math.min(0.8, m * cur.pitch * 1.1);
      flared(k, x, y, z, w + 2 * e, h, d + 2 * e, roof, wall, d > w * 1.2);
      return y + h;
    }
    case 'dutch': {
      // one gable per bay of about 0.9 across, so a wide building reads as a row of canal houses
      const n = Math.max(1, Math.round(w / 0.9)), gw = w / n, h = Math.min(0.75, gw * cur.pitch * 0.7 + 0.05);
      for (let i = 0; i < n; i++) {
        const gx = x - w / 2 + gw * (i + 0.5), kind = GABLES[Math.floor(r() * GABLES.length)];
        k.gable(gx, y, z, gw + 0.02, h, d + 0.02, roof, wall, true);
        gableFace(k, gx, y, z + d / 2 + 0.012, gw + 0.02, h * 1.12, wall, styleTrim(), kind, true, 1);
        hoist(k, gx, y + h * 0.8, z + d / 2 + 0.012, true, 1);
      }
      return y + h * 1.12 + 0.06;
    }
    case 'false':
      return falseFront(k, r, x, y, z, w, d, wall, roof);
    case 'low': {
      // end-on to the street, the eaves reaching out past both gables too
      const endOn = w <= d * 1.5, span = endOn ? w : d;
      const h = Math.min(0.7, span * cur.pitch * 0.8);
      k.gable(x, y, z, w + 2 * e, h, d + 2 * e, roof, wall, endOn);
      return y + h;
    }
    default: {
      const h = Math.min(0.62, m * cur.pitch * (m > 1 ? 0.5 : 0.9));
      k.gable(x, y, z, w + 2 * e, h, d + 2 * e, roof, wall, d > w * 1.2);
      return y + h;
    }
  }
}

/**
 * A drop-in for `k.gable` on a building's main roof: the old styles get exactly that gable, the
 * biomes' styles their own form over the same footprint.
 */
export function styledGable(k: Kit, r: Rng, x: number, y: number, z: number, w: number, h: number, d: number, roof: RGB, end: RGB, alongZ = false): void {
  switch (cur.form) {
    case undefined: k.gable(x, y, z, w, h, d, roof, end, alongZ); return;
    case 'flat': flatTop(k, r, x, y, z, w - 0.04, d - 0.04, end); return;
    case 'hip':
      if (cur.tiles) tiledHip(k, x, y, z, w, h, d, roof, pick(r, cur.tiles));
      else k.hip(x, y, z, w, h, d, roof);
      return;
    case 'curved': flared(k, x, y, z, w + cur.eaves, h, d + cur.eaves, roof, end, alongZ); return;
    case 'low': k.gable(x, y, z, w + cur.eaves, Math.min(h, 0.22), d + cur.eaves, roof, end, alongZ); return;
    case 'dutch': {
      // the same gable, with a stepped, neck or bell front on both its ends
      const H = Math.max(h, Math.min(w, d) * cur.pitch * 0.6), kind = GABLES[Math.floor(r() * GABLES.length)];
      k.gable(x, y, z, w, H, d, roof, end, alongZ);
      for (const s of [1, -1] as const) {
        if (alongZ) gableFace(k, x, y, z + s * (d / 2 + 0.012), w + 0.02, H * 1.12, end, styleTrim(), kind, true, s);
        else gableFace(k, x + s * (w / 2 + 0.012), y, z, d + 0.02, H * 1.12, end, styleTrim(), kind, false, s);
      }
      return;
    }
    case 'false': {
      // the roof, and a square false front standing up over the street side
      const H = Math.min(h, 0.3);
      k.gable(x, y, z, w, H, d, roof, end, alongZ);
      k.box(x, y, z + d / 2 + 0.005, w + 0.02, H + 0.14, 0.05, end);
      k.box(x, y + H + 0.14, z + d / 2 + 0.005, w + 0.06, 0.025, 0.07, scale(end, 0.68));
      return;
    }
    default: k.gable(x, y, z, w, Math.max(h, Math.min(w, d) * cur.pitch * 0.8), d, roof, end, alongZ);
  }
}

/** Which of the fleet's road models a parked car is drawn after, and how often each turns up. */
type ParkedModel = 'tomato' | 'mule' | 'bramble' | 'postie' | 'wasabi' | 'sunny' | 'cabbie';
const PARKED: [ParkedModel, number][] = [['tomato', 0.36], ['mule', 0.53], ['bramble', 0.68], ['postie', 0.79], ['wasabi', 0.89], ['sunny', 0.97], ['cabbie', 1]];
const TYRE = hex(0x26282c), LAMP = hex(0xfff2b0), TAIL = hex(0xb02020), CAB_YELLOW = hex(0xf2c12e), CANOPY = hex(0x26313a);

/**
 * A parked car, a third the size of the ones that drive and drawn after them (render/vehicleMeshes.ts): the
 * Tomato hatchback, the Mule pickup with its crate, the Bramble 4x4 under its roof box, the Postie van, the
 * low Wasabi with its ducktail, the open Sunny and the yellow Cabbie. Which one stands in a bay comes from
 * where the bay is, so a car park is a mix and the same car park is the same mix every time. Tyres under
 * it, bumpers, head and tail lamps, glass all round the cabin; nine or ten boxes a car.
 */
export function car(k: Kit, x: number, z: number, alongX: boolean, col: RGB, model?: ParkedModel): void {
  const roll = Math.abs(Math.sin(x * 127.1 + z * 311.7 + col[0] * 74.7 + col[2] * 19.3) * 43758.5453) % 1;
  const kind = model ?? PARKED.find(([, upTo]) => roll < upTo)![0];
  // half the cars are parked nose-in and half tail-in
  const f = (Math.abs(Math.sin(x * 39.346 + z * 11.135) * 24634.63) % 1) < 0.5 ? 1 : -1;
  // a box in the car's own frame: `s` across it, `a` along it toward its nose
  const p = (s: number, y: number, a: number, ws: number, h: number, la: number, c: RGB, top: RGB = c) => {
    if (alongX) k.box(x + a * f, y, z + s, la, h, ws, c, top);
    else k.box(x + s, y, z + a * f, ws, h, la, c, top);
  };
  const paint = kind === 'cabbie' ? CAB_YELLOW : col;
  const low = kind === 'wasabi' || kind === 'sunny';
  const W = kind === 'bramble' ? 0.215 : 0.2, L = 0.36, y0 = low ? 0.035 : 0.05, bodyH = low ? 0.055 : 0.075, deck = y0 + bodyH;
  // the tyres, one box an axle, standing a hair proud of the sills
  const tr = kind === 'bramble' ? 0.075 : low ? 0.055 : 0.065;
  for (const a of [0.115, -0.115]) p(0, 0, a, W + 0.025, tr, tr, TYRE);
  // the body, its bumpers and its lamps
  p(0, y0, 0, W, bodyH, L, paint);
  for (const s of [1, -1]) p(0, y0 - 0.01, s * (L / 2 + 0.004), W + 0.012, 0.026, 0.014, DARK);
  p(0, y0 + bodyH * 0.45, L / 2 + 0.002, W * 0.8, 0.02, 0.008, LAMP);
  p(0, y0 + bodyH * 0.45, -L / 2 - 0.002, W * 0.8, 0.018, 0.008, TAIL);
  switch (kind) {
    case 'mule':
      // the cab forward of the middle, the bed's sides and tailgate behind it, a crate in the bed
      p(0, deck, 0.04, W * 0.88, 0.075, 0.13, GLASS, paint);
      for (const s of [1, -1]) p(s * (W / 2 - 0.01), deck, -0.105, 0.016, 0.04, 0.15, paint);
      p(0.02, deck, -0.1, 0.07, 0.055, 0.07, WOOD);
      break;
    case 'bramble':
      // a tall cabin most of its length, the yellow box on the roof rack, the spare on the back door
      p(0, deck, -0.03, W * 0.92, 0.095, 0.25, GLASS, paint);
      p(0, deck + 0.1, -0.035, W * 0.62, 0.04, 0.13, CAB_YELLOW);
      p(0, y0 + 0.03, -L / 2 - 0.018, 0.1, 0.1, 0.03, TYRE);
      break;
    case 'postie':
      // the cab forward and the tall box body behind it, a white band down each side
      p(0, deck, 0.125, W * 0.9, 0.07, 0.095, GLASS, paint);
      p(0, deck, -0.05, W, 0.17, 0.245, paint);
      p(0, deck + 0.075, -0.05, W + 0.006, 0.02, 0.24, WHITE);
      break;
    case 'wasabi':
      // a dark canopy set low, and the ducktail on its struts
      p(0, deck, -0.02, W * 0.78, 0.045, 0.15, CANOPY);
      p(0, deck + 0.025, -L / 2 + 0.02, W, 0.01, 0.045, paint);
      p(0, deck, -L / 2 + 0.02, W * 0.6, 0.025, 0.012, TYRE);
      break;
    case 'sunny':
      // open: a windscreen, two seats and the folded hood behind them
      p(0, deck, 0.05, W * 0.84, 0.045, 0.012, GLASS);
      p(0, deck - 0.012, -0.03, W * 0.72, 0.03, 0.1, hex(0xd9a066));
      p(0, deck, -0.105, W * 0.84, 0.022, 0.04, DARK);
      break;
    case 'cabbie':
      // the chequer band is a dark stripe at this size; the roof sign glows after dark
      p(0, deck, -0.015, W * 0.9, 0.07, 0.18, GLASS, paint);
      p(0, y0 + bodyH * 0.55, 0, W + 0.006, 0.014, 0.16, DARK);
      if (alongX) k.glowBox(x - 0.015 * f, deck + 0.07, z, 0.035, 0.022, 0.07, LAMP, [17, 31, 1.2], SHOP_GLOW);
      else k.glowBox(x, deck + 0.07, z - 0.015 * f, 0.07, 0.022, 0.035, LAMP, [17, 31, 1.2], SHOP_GLOW);
      break;
    default:
      // the hatchback: glass all round a cabin set back of the middle, the roof in the body's colour
      p(0, deck, -0.03, W * 0.9, 0.072, 0.19, GLASS, paint);
  }
}

export function tree(k: Kit, x: number, y: number, z: number, s: number, pine: boolean): void {
  k.box(x, y, z, 0.06 * s, 0.22 * s, 0.06 * s, TRUNK);
  if (pine) {
    k.cone(x, y + 0.15 * s, z, 0.26 * s, 0.5 * s, PINE, 7);
    k.cone(x, y + 0.42 * s, z, 0.19 * s, 0.4 * s, PINE, 7);
  } else {
    const cy = y + 0.42 * s;
    k.hip(x, cy, z, 0.5 * s, 0.32 * s, 0.5 * s, LEAF);
    k.hip(x, cy, z, 0.5 * s, -0.2 * s, 0.5 * s, LEAF2);
  }
}

/** Steps, a row of columns and a pediment across the front of a civic building. */
export function portico(k: Kit, z: number, w: number, colH: number, cols: number, stone: RGB, roof: RGB): void {
  k.box(0, 0, z + 0.12, w + 0.1, 0.05, 0.36, stone);
  for (let i = 0; i < cols; i++) k.cyl(-w / 2 + 0.08 + (i * (w - 0.16)) / (cols - 1), 0.05, z + 0.05, 0.045, colH, WHITE, 6);
  k.box(0, 0.05 + colH, z, w + 0.06, 0.06, 0.32, stone);
  k.gable(0, 0.11 + colH, z, w + 0.06, 0.2, 0.32, roof, stone, true);
}

export type Draw = (k: Kit, W: number, D: number, b: Building, r: Rng, t: Town | null) => void;

/** What an onion dome is leafed in: gold, green-blue, silver and oxblood, as the domes of a Russian church are. */
export const ONION_SKINS: readonly number[] = [0xd8a83a, 0x2f7a72, 0xb8bcc0, 0x7a2f2a, 0x2f5a8a];

/**
 * An onion dome on its drum, from the drum's foot at y: the drum, a bulb of five bands that swells past
 * the drum and pinches back in, a little neck and a cross. Returns the height of the cross's tip.
 */
export function onionDome(k: Kit, x: number, y: number, z: number, R: number, skin: RGB, trim: RGB): number {
  k.cyl(x, y, z, R * 0.72, R * 1.1, trim, 10, trim);
  let top = y + R * 1.1;
  // the bulb: each band is a slice of the onion, out to its widest a third of the way up and in to a point
  const bands: [number, number][] = [[0.82, 0.3], [1, 0.34], [0.96, 0.3], [0.74, 0.28], [0.44, 0.26], [0.2, 0.22]];
  for (const [f, hf] of bands) {
    const h = R * hf;
    k.cyl(x, top, z, R * f, h, skin, 10, skin);
    top += h;
  }
  k.cone(x, top, z, R * 0.18, R * 0.5, skin, 8);
  top += R * 0.5;
  // the cross: a shaft, its arm and the slanted footrest of an Orthodox one
  k.box(x, top, z, R * 0.05, R * 0.66, R * 0.05, trim);
  k.box(x, top + R * 0.44, z, R * 0.34, R * 0.05, R * 0.05, trim);
  k.box(x, top + R * 0.2, z, R * 0.22, R * 0.045, R * 0.045, trim);
  return top + R * 0.66;
}

// ---- small style details, shared by the town-mesh basics and their alternatives ----

/** A block's corner boards or timber posts, for the ribbed biome styles (timber, eastern). */
export function corners(k: Kit, x: number, z: number, w: number, d: number, h: number): void {
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.box(x + sx * (w / 2 - 0.01), 0, z + sz * (d / 2 - 0.01), 0.035, h, 0.035, styleTrim());
  if (cur.course > 0.6) k.box(x, h * 0.55, z, w + 0.012, 0.025, d + 0.012, styleTrim());
}

/** An engawa: a low timber deck round a ground floor, and on a two-storey building a pent roof over it at the first floor. */
export function engawa(k: Kit, x: number, z: number, w: number, d: number, two: boolean, roof: [number, number, number]): void {
  k.box(x, 0, z, w + 0.1, 0.035, d + 0.1, hex(cur.engawa ?? 0x7a5a3e));
  if (two) k.box(x, FLOOR - 0.012, z, w + 0.12, 0.02, d + 0.12, scale(roof, 0.92));
}

/** A Georgian doorcase round a door w×h on a front facing +z at z: two columns and a little pediment. */
export function doorcase(k: Kit, x: number, z: number, w: number, h: number, col: [number, number, number]): void {
  for (const s of [-1, 1]) k.box(x + s * (w / 2 + 0.012), 0, z, 0.018, h, 0.018, col);
  k.box(x, h, z, w + 0.05, 0.018, 0.024, col);
  k.gable(x, h + 0.018, z, w + 0.05, 0.045, 0.024, col, col, true);
}
