import { N, RoadType, idx } from '../../tiles';
import { put, type Layout } from '../../towns';
import { LAYERS } from '../layers';
import { CARVERS } from '../water';
import { COMPASS, avenue, dfCores, dfFlat, etoile, finishTown, parkAt, path, rect, reserve, ring, type Pt } from '../kit';
import { bridgesOver, discTiles, gridLines, lakeOn, nearest, plainGrid, riverAt, riverDist, riverThrough } from './shared';

/**
 * Capitals and axes (docs/cityplans.html): planned seats of government, a grand axis, monuments placed on purpose
 * and the city built to frame them. L'Enfant's Washington, Haussmann's Paris, the Plano Piloto, Chandigarh's
 * sectors, Putrajaya's garden capital and the mandala.
 */

// ---------------------------------------------------------------------------------------------
// L'Enfant's Washington

LAYERS.lenfant = (c, p, rng) => {
  const S = p.size, x0 = p.x0, z0 = p.z0, mega = p.kind === 'mega';
  const g = mega ? 8 : 7;
  const xs = gridLines(x0, x0 + S, g), zs = gridLines(z0, z0 + S, g);
  if (xs.length < 5 || zs.length < 5) return false;
  // the Capitol a little east of the middle, the monument a third of the town to its west, the White House north of it
  const capX = nearest(xs, x0 + S * 0.64), capZ = nearest(zs, z0 + S * 0.56);
  const monX = nearest(xs, x0 + S * 0.3), whZ = nearest(zs, z0 + S * 0.26);
  if (capX - monX < 2 * g || capZ - whZ < 2 * g) return false;
  // the Mall: a great park from the monument's square to the Capitol's, its ring the streets round it
  const mall = parkAt(c, monX + 2, capZ - 3, capX - monX - 3, 6, rng);
  // the President's Park: north from the monument toward the White House
  const ellipse = parkAt(c, monX - 3, whZ + 3, 6, capZ - whZ - 7, rng) ?? parkAt(c, monX - 2, whZ + 3, 4, capZ - whZ - 8, rng);
  // the grid, laid round them
  plainGrid(c, xs, zs);
  // the avenues: four-lane diagonals out of the Capitol and the White House, divided by a planted median
  const cap: Pt = [capX + 0.5, capZ + 0.5], wh: Pt = [monX + 0.5, whZ + 0.5];
  const reach = (from: Pt, dx: number, dz: number): Pt => {
    const ex = dx > 0 ? x0 + S - 1 - from[0] : from[0] - x0;
    const ez = dz > 0 ? z0 + S - 1 - from[1] : from[1] - z0;
    const n = Math.floor(Math.min(ex, ez));
    return [from[0] + dx * n, from[1] + dz * n];
  };
  const axis: number[] = [];
  // Pennsylvania Avenue: the Capitol toward the White House
  const penn = Math.min(capX - monX, capZ - whZ);
  axis.push(...avenue(c, RoadType.TwoLane, cap, [capX - penn + 0.5, capZ - penn + 0.5], { four: true }));
  for (const [dx, dz] of [[1, -1], [1, 1], [-1, 1]] as const) avenue(c, RoadType.TwoLane, cap, reach(cap, dx, dz), { four: true });
  for (const [dx, dz] of [[1, -1], [-1, -1]] as const) avenue(c, RoadType.TwoLane, wh, reach(wh, dx, dz), { four: true });
  // circles where the avenues cross the grid's avenues, a few blocks out
  for (const [px, pz] of [[capX + 2 * g, capZ - 2 * g], [capX + 2 * g, capZ + 2 * g], [monX + 2 * g, whZ - 2 * g]]) {
    if (px > x0 + 6 && px < x0 + S - 7 && pz > z0 + 6 && pz < z0 + S - 7) ring(c, RoadType.TwoLane, px, pz, 3, 2, { main: false });
  }
  // the roles: the Capitol at the head of the Mall, the White House on the cross axis, the obelisk where they meet,
  // the Lincoln at the Mall's west end, the Jefferson across the basin to the south, the museums along the Mall
  c.anchors.seat = [capX + 2.5, capZ + 0.5];
  c.anchors.palace = [monX + 0.5, whZ - 1.5];
  c.anchors.tower = [monX + 0.5, capZ + 0.5];
  c.anchors.arch = [monX - 3.5, capZ + 0.5];
  c.anchors.garden = [monX + 0.5, capZ + 6.5];
  c.anchors.museum = [(monX + capX) / 2, capZ + 4.5];
  c.anchors.landmark = [capX - 1.5, whZ - 1.5];
  c.dfAt = dfCores(c, [[(monX + capX) / 2, whZ + 0.5]], S * 0.5);
  // the Height Act: nothing over twelve floors, whatever the style
  c.maxFloors = 12;
  finishTown(c, { grow: mega ? 10 : 6, parks: [mall, ellipse].filter((s) => !!s) as never, axis });
  return true;
};

// ---------------------------------------------------------------------------------------------
// Haussmann's Paris

CARVERS.etoiles = (p, ctx, rng) => {
  // the Seine, with its island, where the sea can be reached; a Paris with no river is still a Paris
  riverThrough(p, ctx, rng, { half: 2, island: true, amp: p.size * 0.06 });
  return true;
};

LAYERS.etoiles = (c, p, rng) => {
  const S = p.size, x0 = p.x0, z0 = p.z0, mega = p.kind === 'mega';
  const r = p.carved?.river;
  // the river runs along `ra` (0: along x); s is the way along it, u across
  const ra = r?.axis ?? 0;
  const P = (s: number, u: number): Pt => (ra === 0 ? [x0 + s * S, z0 + u * S] : [x0 + u * S, z0 + s * S]);
  const clear = (pt: Pt, need: number) => riverDist(p, pt[0], pt[1]) > need;
  c.bridgeSpan = 9;
  // the grands boulevards: an octagon round the old centre, over the river on its bridges
  const C: Pt = [x0 + S / 2, z0 + S / 2];
  ring(c, RoadType.TwoLane, C[0], C[1], Math.round(S * 0.3), Math.round(S * 0.12), { bridge: true });
  // the main étoile out on the west bank, the axe historique through it the length of the town, along the river
  const riverU = r ? (riverAt(p, (ra === 0 ? x0 : z0) + Math.round(S * 0.25))! - (ra === 0 ? z0 : x0)) / S : 0.5;
  const sideU = riverU > 0.5 ? 0.28 : 0.72;
  const E1 = P(0.22, sideU);
  if (!clear(E1, 7)) E1[ra === 0 ? 1 : 0] += (sideU < 0.5 ? -1 : 1) * 5;
  const axisU = Math.round(ra === 0 ? E1[1] : E1[0]);
  const axis = ra === 0
    ? avenue(c, RoadType.FourLane, [x0 + 1, axisU], [x0 + S - 1, axisU], { main: true, bridge: true })
    : avenue(c, RoadType.FourLane, [axisU, z0 + 1], [axisU, z0 + S - 1], { main: true, bridge: true });
  c.ends(axis);
  etoile(c, RoadType.TwoLane, E1[0], E1[1], 4, Math.round(S * 0.2), COMPASS, 'arch');
  // two more (three in a megalopolis), each a smaller star, on the far bank and down the river
  const stars: Pt[] = [P(0.74, 1 - sideU), P(0.62, sideU < 0.5 ? 0.16 : 0.84)];
  if (mega) stars.push(P(0.4, 1 - sideU));
  for (const s of stars) if (clear(s, 6)) etoile(c, RoadType.TwoLane, s[0], s[1], 3, Math.round(S * 0.13), COMPASS);
  // bridges straight across the river every few blocks
  bridgesOver(c, p, mega ? 0.11 : 0.16);
  // the Champ de Mars: a long lawn back from the river on the far bank, its tower at the water's end
  const lw = 6, ll = mega ? 16 : 12;
  const ls = (ra === 0 ? x0 : z0) + Math.round(S * 0.38);
  const lr = r ? riverAt(p, ls)! : (ra === 0 ? z0 : x0) + S * 0.5;
  const toward = sideU < 0.5 ? 1 : -1;
  const near = lr + toward * ((r?.half ?? 0) + 4);
  const u0 = toward > 0 ? near : near - ll;
  const lawn = ra === 0 ? parkAt(c, ls - lw / 2, u0, lw, ll, rng) : parkAt(c, u0, ls - lw / 2, ll, lw, rng);
  if (lawn) c.anchors.tower = ra === 0 ? [ls, toward > 0 ? u0 - 1 : u0 + ll + 1] : [toward > 0 ? u0 - 1 : u0 + ll + 1, ls];
  // the roles: the museum at the axis's far end, the cathedral by the island, La Défense out past the main étoile
  const axisEnd = P(0.6, sideU);
  c.anchors.museum = ra === 0 ? [axisEnd[0], axisU + 2.5] : [axisU + 2.5, axisEnd[1]];
  if (r) { const s = (ra === 0 ? x0 : z0) + Math.round(S * 0.45), at = riverAt(p, s)!; c.anchors.temple = ra === 0 ? [s, at - toward * (r.half + 4)] : [at - toward * (r.half + 4), s]; }
  const def: Pt = ra === 0 ? [x0 + 4, axisU + 3.5] : [axisU + 3.5, z0 + 4];
  c.anchors.landmark = def;
  c.anchors.seat = P(0.5, sideU < 0.5 ? 0.4 : 0.6);
  // one height for the whole city (Haussmann's six to eight floors), and the towers only out at La Défense
  c.dfAt = dfFlat(0.5, { at: def, r: S * 0.16 });
  c.capAt = (x, z) => (Math.hypot(x - def[0], z - def[1]) < S * 0.16 ? 0 : 8);
  finishTown(c, { grow: mega ? 64 : 36, parks: lawn ? [lawn] : [], axis });
  return true;
};

// ---------------------------------------------------------------------------------------------
// Lúcio Costa's Brasília

CARVERS.planopiloto = (p, ctx, rng) => {
  // Lake Paranoá: a crescent of water wrapped round the east of the plan (or the west, mirrored)
  const S = p.size, east = rng() < 0.5;
  const cx = east ? p.x0 + S * 0.9 : p.x0 + S * 0.1;
  const discs: [number, number, number][] = [];
  for (let k = 0; k <= 6; k++) {
    const a = -0.9 + (k / 6) * 1.8;
    discs.push([cx + (east ? -1 : 1) * Math.cos(a) * S * 0.06, p.z0 + S * 0.5 + Math.sin(a) * S * 0.36, S * 0.07]);
  }
  (p.carved ??= {}).note = { east: east ? 1 : 0 };
  lakeOn(p, ctx, discTiles(p, discs));
  return true;
};

LAYERS.planopiloto = (c, p, rng) => {
  const S = p.size, x0 = p.x0, z0 = p.z0;
  const east = (p.carved?.note?.east ?? 1) === 1, sx = east ? 1 : -1;
  const X = (f: number) => Math.round(east ? x0 + S * f : x0 + S * (1 - f)) + 0.5;
  const Z = (f: number) => Math.round(z0 + S * f) + 0.5;
  // the Monumental Axis: across the town, the Three Powers at its head by the lake
  const axisZ = Z(0.5);
  const head = X(0.74), tail = X(0.04);
  const axis = avenue(c, RoadType.FourLane, [Math.min(head, tail), axisZ], [Math.max(head, tail), axisZ], { main: true });
  c.ends(axis);
  // the Esplanade: a lawn down the axis from the crossing to the Three Powers
  const espW = Math.round(S * 0.2);
  const esp = parkAt(c, Math.min(X(0.46), X(0.46) + sx * espW) + (east ? 0 : 1), axisZ + 2, espW, 5, rng);
  // the wings: the residential highway bowed out toward the lake, north and south of the axis
  const top = Z(0.05), bot = Z(0.95), bow = Math.round(S * 0.16);
  const wx = X(0.3);
  const knee1: Pt = [wx + sx * bow, top + bow], knee2: Pt = [wx + sx * bow, bot - bow];
  const wings = path(c, RoadType.TwoLane, [[wx, top], knee1, knee2, [wx, bot]], { four: true, main: true });
  if (wings.length) c.ends([wings[0], wings[wings.length - 1]]);
  // superquadras: a ring of local road a block either side of the wings, each with its way onto the highway
  for (let f = 0.13; f < 0.9; f += 0.105) {
    if (Math.abs(f - 0.5) < 0.07) continue;
    const z = Z(f);
    const off = Math.max(0, Math.min(bow, f < 0.5 ? (f - 0.05) * S : (0.95 - f) * S));
    const hx = wx + sx * off;
    for (const side of [-1, 1]) {
      const qx = hx + side * 7;
      ring(c, RoadType.Paved, qx, z, 3, 0, { main: false, route: false });
      avenue(c, RoadType.Paved, [qx - side * 3, z], [hx, z], { main: false });
    }
  }
  // ministries in two rows down the Esplanade, the Congress and its twin towers at the head
  c.anchors.seat = [head + sx * 1.5, axisZ];
  c.anchors.palace = [head - sx * 2, axisZ - 3.5];
  c.anchors.temple = [X(0.36), axisZ - 3.5];
  c.anchors.tower = [tail + sx * 2, axisZ - 1.5];
  c.anchors.museum = [X(0.42), axisZ + 3.5];
  c.anchors.landmark = [head - sx * 4, axisZ - 4.5];
  for (const f of [0.5, 0.56, 0.62, 0.68]) for (const side of [-1, 1]) put(c, 'ministry', { near: [X(f), axisZ + side * 4.5], maxDist: 3 });
  // six floors on pilotis everywhere; the towers only at the head
  c.dfAt = dfFlat(0.45, { at: [head, axisZ], r: 8 });
  c.capAt = (x, z) => (Math.hypot(x - head, z - axisZ) < 9 ? 0 : 7);
  finishTown(c, { grow: 14, parks: esp ? [esp] : [], axis });
  return true;
};

// ---------------------------------------------------------------------------------------------
// Le Corbusier's Chandigarh

CARVERS.sectors = (p, ctx) => {
  // Sukhna Lake by the Capitol, off the north-east corner
  const S = p.size;
  lakeOn(p, ctx, discTiles(p, [[p.x0 + S * 0.86, p.z0 + S * 0.1, S * 0.06], [p.x0 + S * 0.8, p.z0 + S * 0.12, S * 0.05]]));
  return true;
};

LAYERS.sectors = (c, p) => {
  const S = p.size, x0 = p.x0, z0 = p.z0, mega = p.kind === 'mega';
  const G = mega ? 20 : 17;
  // the Capitol's precinct across the top, the sectors below it
  const capD = Math.round(S * 0.2);
  const xs = gridLines(x0, x0 + S, G), zs = gridLines(z0 + capD, z0 + S, G);
  if (xs.length < 3 || zs.length < 2) return false;
  // the V2 roads: four lanes, sector to sector
  for (const x of xs) c.ends(avenue(c, RoadType.FourLane, [x, z0 + capD - 1], [x, z0 + S - 1], { main: true, route: false }));
  for (const z of zs) c.ends(avenue(c, RoadType.FourLane, [x0 + 1, z], [x0 + S - 1, z], { main: true, route: false }));
  const mx = nearest(xs, x0 + S * 0.5);
  c.ends(avenue(c, RoadType.FourLane, [mx, z0 + 2], [mx, z0 + capD], { main: true }));
  avenue(c, RoadType.TwoLane, [x0 + S * 0.25, z0 + capD - 2.5], [x0 + S * 0.75, z0 + capD - 2.5], { main: false });
  // inside every sector: its market street bent across the middle, a lane down it, a green strip through it
  const cells: Pt[] = [];
  const xb = [x0, ...xs, x0 + S - 1], zb = [z0 + capD - 1, ...zs, z0 + S - 1];
  for (let a = 0; a + 1 < xb.length; a++) for (let b = 0; b + 1 < zb.length; b++) {
    const sx0 = xb[a] + 1, sx1 = xb[a + 1] - 1, sz0 = zb[b] + 1, sz1 = zb[b + 1] - 1;
    if (sx1 - sx0 < 9 || sz1 - sz0 < 9) continue;
    const cz = Math.round((sz0 + sz1) / 2), cx = Math.round((sx0 + sx1) / 2);
    cells.push([cx + 0.5, cz + 0.5]);
    path(c, RoadType.TwoLane, [[sx0 - 0.5, cz + 0.5], [cx - 1.5, cz + 0.5], [cx - 1.5, cz + 2.5], [sx1 + 0.5, cz + 2.5]], { main: false });
    avenue(c, RoadType.Paved, [cx + 3.5, sz0 - 0.5], [cx + 3.5, sz1 + 0.5], { main: false });
    // the green strip: kept open for good
    reserve(c, rect(cx - 4, sz0 + 1, 2, sz1 - sz0 - 1).filter((i) => !c.w.road[i]));
  }
  // the roles: the Capitol (hall, assembly, high court) in its precinct, the city centre's sector in the middle
  const capX = x0 + S * 0.5;
  c.anchors.seat = [capX - 7, z0 + capD * 0.45];
  c.anchors.palace = [capX + 7, z0 + capD * 0.45];
  c.anchors.arch = [capX, z0 + capD * 0.3];
  const want: Pt = [capX, z0 + S * 0.58];
  const centre = cells.reduce((b, q) => (Math.hypot(q[0] - want[0], q[1] - want[1]) < Math.hypot(b[0] - want[0], b[1] - want[1]) ? q : b), cells[0] ?? want);
  c.anchors.landmark = [centre[0] + 2, centre[1] - 3];
  c.anchors.museum = [centre[0] - 5, centre[1] + 4];
  put(c, 'ministry', { near: [capX - 13, z0 + capD * 0.45], maxDist: 6 });
  c.dfAt = dfCores(c, [centre], S * 0.45);
  finishTown(c, { grow: mega ? 24 : 14, growType: RoadType.Paved });
  return true;
};

// ---------------------------------------------------------------------------------------------
// Putrajaya

CARVERS.gardencapital = (p, ctx, rng) => {
  const S = p.size, cx = p.x0 + S * 0.5, cz = p.z0 + S * 0.6;
  const discs: [number, number, number][] = [[cx, cz, S * 0.17]];
  for (let k = 0; k < 4; k++) {
    const a = rng() * Math.PI * 2;
    discs.push([cx + Math.cos(a) * S * 0.16, cz + Math.sin(a) * S * 0.13, S * (0.07 + rng() * 0.04)]);
  }
  const tiles = discTiles(p, discs, 4);
  // the core island left standing in the middle
  const isle = S * 0.075;
  for (const i of [...tiles]) { const x = i % N, z = (i - x) / N; if (Math.hypot(x + 0.5 - cx, z + 0.5 - cz) < isle) tiles.delete(i); }
  (p.carved ??= {}).pts = { isle: [cx, cz] };
  return lakeOn(p, ctx, tiles);
};

LAYERS.gardencapital = (c, p, rng) => {
  const S = p.size, x0 = p.x0, z0 = p.z0, mega = p.kind === 'mega';
  const [ix, iz] = p.carved?.pts?.isle ?? [x0 + S / 2, z0 + S * 0.6];
  c.bridgeSpan = 12;
  // the boulevard: north to south through the island, over the lake on its bridges
  const bx = Math.round(ix);
  const axis = avenue(c, RoadType.FourLane, [bx, z0 + 2], [bx, z0 + S - 1], { main: true, bridge: true });
  c.ends(axis);
  // a cross boulevard over the island, and precinct roads round the lake and round the island
  c.ends(avenue(c, RoadType.TwoLane, [x0 + 1, Math.round(iz) + 0.5], [x0 + S - 1, Math.round(iz) + 0.5], { main: true, bridge: true }));
  ring(c, RoadType.TwoLane, ix, iz, Math.round(S * 0.34), Math.round(S * 0.12), { bridge: true });
  ring(c, RoadType.Paved, ix, iz, Math.max(3, Math.round(S * 0.075) - 2), 2, { main: false });
  // the wetlands up in a corner
  const wet = parkAt(c, x0 + 4, z0 + 4, mega ? 14 : 10, mega ? 9 : 7, rng);
  // the roles: the domed seat at the boulevard's head, the mosque on the water, ministries round the shore
  c.anchors.seat = [bx + 2.5, z0 + 4.5];
  c.anchors.temple = [ix + S * 0.2, iz - S * 0.2];
  c.anchors.landmark = [ix + 3, iz + 2];
  c.anchors.museum = [ix - 4, iz - 2];
  for (let k = 0; k < (mega ? 6 : 3); k++) {
    const a = (k / (mega ? 6 : 3)) * Math.PI * 2 + 0.3;
    put(c, 'ministry', { near: [ix + Math.cos(a) * S * 0.28, iz + Math.sin(a) * S * 0.24], maxDist: 5 });
  }
  c.dfAt = dfCores(c, [[ix, iz]], S * 0.6);
  c.capAt = (x, z) => (Math.hypot(x - ix, z - iz) < S * 0.1 ? 0 : 9);
  finishTown(c, { grow: mega ? 18 : 10, parks: wet ? [wet] : [], axis });
  return true;
};

// ---------------------------------------------------------------------------------------------
// the mandala: Madurai's square rings round the temple, Jaipur's walls

CARVERS.mandala = (p, ctx) => {
  // the temple tank: a small square pool beside the middle
  const S = p.size, cx = p.x0 + Math.round(S * 0.5), cz = p.z0 + Math.round(S * 0.5);
  const t = new Set<number>();
  for (let z = cz + 4; z < cz + 7; z++) for (let x = cx + 4; x < cx + 7; x++) t.add(idx(x, z));
  lakeOn(p, ctx, t);
  return true;
};

LAYERS.mandala = (c, p) => {
  const S = p.size, x0 = p.x0, z0 = p.z0, city = p.kind === 'city';
  const cx = x0 + Math.round(S * 0.5), cz = z0 + Math.round(S * 0.5);
  // three square rings, the inner one round the temple's precinct
  for (const f of [0.42, 0.29, 0.15]) ring(c, RoadType.TwoLane, cx, cz, Math.round(S * f), 0, { main: f > 0.3 });
  // four axial streets out from the inner ring to four gates
  const inner = Math.round(S * 0.15);
  for (const [dx, dz] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
    c.ends(avenue(c, RoadType.TwoLane, [cx + dx * inner + 0.5, cz + dz * inner + 0.5], [cx + dx * Math.floor(S / 2 - 1) + 0.5, cz + dz * Math.floor(S / 2 - 1) + 0.5], { main: true }));
  }
  // the temple and its tank, the palace in one quarter, a gate tower at each gate
  c.anchors.temple = [cx + 0.5, cz + 0.5];
  c.anchors.seat = [cx - S * 0.22, cz - S * 0.22];
  c.anchors.market = [cx + S * 0.22, cz - S * 0.22];
  put(c, city ? 'temple' : 'cathedral', { near: [cx + 0.5, cz + 0.5], maxDist: 4 }) ?? put(c, 'temple', { near: [cx + 0.5, cz + 0.5], maxDist: 6 });
  for (const [dx, dz] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) put(c, 'watchtower', { near: [cx + dx * (S / 2 - 2) + 0.5 + dz * 2, cz + dz * (S / 2 - 2) + 0.5 + dx * 2], maxDist: 3 });
  c.dfAt = dfCores(c, [[cx, cz]], S * 0.55);
  c.maxFloors = city ? 4 : 6;
  finishTown(c, { grow: city ? 4 : 8 });
  return true;
};

export type { Layout };
