import { N, Biome, Lot, RoadType, idx, inB, type BuildingKind, type World } from './tiles';
import { cell01, hashCell, mulberry32, type Rng } from './rng';
import { NEXT_WORLD } from './nextWorld';
import {
  type Layout, type Pt, type Spec, type TownPlan,
  civic, eateries, factionSites, grow, playSites, put, putOne, shuffled, MAIN,
} from './towns';
import { avenue, knit, layNodes } from './plans/kit';
import { lakeOn } from './plans/families/shared';
import type { PlanCtx } from './plans/types';
import { FLAVOUR_LABEL, ONSEN_FLAVOURS, ONSEN_HOOKS, type OnsenFlavour } from './onsenKinds';

/**
 * Onsen towns (GEN 53, behind world/nextWorld.ts NEXT_WORLD): Japan's hot-spring towns in the hills and the forest.
 *
 * One village, suburb or small city in a few on wooded or hilly ground is rolled as one, on a salt of its own after
 * the canal towns (so no other town's roll moves), and given the look of one of six real ones:
 *
 *   Hakone    the Hayakawa through Yumoto, the Meiji-era Fukuzumirō on its bank, the ropeway up over Ōwakudani's
 *             sulphur vents, and the stream running out into a lake with the shrine's torii standing in it
 *   Kusatsu   the yubatake steaming in the middle of the square, wooden troughs cooling the water
 *   Kinosaki  a willow-lined canal under little stone bridges and its seven public baths (sotoyu)
 *   Ginzan    tall timber ryokan facing each other across a narrow river, gas lamps along the banks
 *   Beppu     the hells: boiling pools of cobalt blue and blood red on the edge of town, concrete resort hotels
 *   Dōgo      the grand bathhouse of Dōgo Onsen Honkan on its square, a covered arcade of souvenir shops
 *
 * A stream (two tiles wide, a sealed lake a step under its banks, cut the way the city plans cut theirs: plans/water.ts)
 * runs through the middle of the square wherever the ground along it is level enough, lanes along both banks and
 * a few little bridges across. Then the ryokan line it: Ginzan's tall inns, a Fukuzumirō, a concrete resort ryokan up the
 * slope and family minshuku, the baths, foot baths, the yubatake, the shrine and the temple, tea houses and souvenir
 * shops, steam rising everywhere (render/buildings/onsen*.ts, render/onsenDress.ts).
 */

/** The share of the towns on onsen ground that are built as one. */
const ONSEN_CHANCE = 0.2;
const SALT = 5170;
const KINDS = new Set(['rural', 'suburb', 'city']);

const FLAVOURS = ONSEN_FLAVOURS;

/** Gates only (scripts/onsen.ts): build every town on onsen ground as one, of this flavour if one is given. */
export const ONSEN_TEST: { all: boolean; flavour: OnsenFlavour | null } = { all: false, flavour: null };

/**
 * Onsen ground: wooded or hilly country round the square (the margin, and the ground the square was before it was
 * a town), with no desert, salt or canyon in it.
 */
function onsenGround(w: World, p: TownPlan): boolean {
  const m = 8;
  let n = 0, rough = 0, dry = 0;
  const tally = (b: number) => {
    n++;
    if (b === Biome.Hills || b === Biome.Forest || b === Biome.Mountain || b === Biome.Snow) rough++;
    else if (b === Biome.Desert || b === Biome.Canyon || b === Biome.Salt) dry++;
  };
  for (let z = p.z0 - m; z < p.z0 + p.size + m; z++) {
    for (let x = p.x0 - m; x < p.x0 + p.size + m; x++) {
      if (!inB(x, z)) continue;
      const inside = x >= p.x0 && z >= p.z0 && x < p.x0 + p.size && z < p.z0 + p.size;
      tally(inside ? p.biome[(z - p.z0) * p.size + x - p.x0] : w.biome[idx(x, z)]);
    }
  }
  return n > 0 && rough / n >= 0.3 && dry / n < 0.08;
}

/** Which flavours suit a town of this size: Ginzan is a village's, Beppu a city's (and a suburb's). */
function flavourFor(kind: string, roll: number): OnsenFlavour {
  // (weights: Hakone, the best known, half as often again as any other)
  const list: [OnsenFlavour, number][] = kind === 'rural' ? [['hakone', 3], ['ginzan', 2], ['kinosaki', 2], ['kusatsu', 2], ['dogo', 2]]
    : kind === 'suburb' ? [['hakone', 3], ['kinosaki', 2], ['kusatsu', 2], ['dogo', 2], ['beppu', 2], ['ginzan', 2]]
      : [['beppu', 2], ['hakone', 3], ['dogo', 2], ['kusatsu', 2], ['kinosaki', 2]];
  if (ONSEN_TEST.flavour) return ONSEN_TEST.flavour;
  let t = roll * list.reduce((s, [, w]) => s + w, 0);
  for (const [f, w] of list) if ((t -= w) < 0) return f;
  return list[0][0];
}

/**
 * Pick this cell's onsen towns among its plans and cut their streams (generate.ts, after the canal towns and before
 * the plans' water is held). Each its own hashed roll; nothing else in the cell moves.
 */
export function planOnsen(w: World, plans: TownPlan[], ctx: PlanCtx, seedHash: number): void {
  if (!NEXT_WORLD) return;
  plans.forEach((p, k) => {
    if (!KINDS.has(p.kind) || p.parent !== undefined || p.perch || p.channel || p.canals || p.strip) return;
    // (a town laid out to a city plan of its own keeps it: only one on today's layout may be an onsen town)
    if (p.plan !== undefined && p.plan !== 'grid') return;
    if (!onsenGround(w, p)) return;
    if (!ONSEN_TEST.all && cell01(seedHash, w.cx, w.cz, SALT + k) >= ONSEN_CHANCE) return;
    const rng = mulberry32(hashCell(seedHash, w.cx, w.cz, SALT + 40 + k));
    const flavour = flavourFor(p.kind, rng());
    p.onsen = true;
    const note = ((p.carved ??= {}).note ??= {});
    note.onsen = FLAVOURS.indexOf(flavour);
    // Kusatsu's middle is its yubatake, not a river: a stream there only now and then
    if (flavour !== 'kusatsu' || rng() < 0.35) cutStream(p, ctx, rng, flavour === 'hakone');
  });
}

/** The flavour a planned onsen town was given. */
export function flavourOf(p: TownPlan): OnsenFlavour {
  return FLAVOURS[p.carved?.note?.onsen ?? 0] ?? 'hakone';
}

const TAU = Math.PI * 2;

/**
 * The stream: two tiles wide, wandering a tile or so either way, along whichever line across the middle of the square
 * has the longest run of level banks (no more than two steps between the lowest and the highest), never nearer the
 * edge than two tiles so the town's ground holds it all round. A Hakone runs it out into a lake at its lower end.
 */
function cutStream(p: TownPlan, ctx: PlanCtx, rng: Rng, lake: boolean): boolean {
  const S = p.size, E = ctx.w.elev;
  const ph = rng() * TAU, turns = 0.45 + rng() * 0.6, amp = S >= 30 ? 1.6 : 1.1;
  let best: { axis: 0 | 1; line: number[]; a: number; b: number; score: number } | null = null;
  const tileAt = (axis: 0 | 1, s: number, u: number) => (axis === 0 ? idx(p.x0 + s, u) : idx(u, p.z0 + s));
  for (const axis of [0, 1] as const) {
    for (let off = -0.16; off <= 0.161; off += 0.04) {
      const at = Math.round((axis === 0 ? p.z0 : p.x0) + S * (0.5 + off));
      const line: number[] = [];
      for (let s = 0; s < S; s++) line.push(Math.round(at + amp * Math.sin(ph + (s / S) * TAU * turns)));
      const lo: number[] = [], hi: number[] = [];
      for (let s = 0; s < S; s++) {
        const e1 = E[tileAt(axis, s, line[s] - 1)], e2 = E[tileAt(axis, s, line[s] + 2)];
        lo.push(Math.min(e1, e2));
        hi.push(Math.max(e1, e2));
      }
      // the longest run of level banks inside the square, two tiles in from either end
      for (let a = 2; a < S - 2; a++) {
        let mn = Infinity, mx = -Infinity;
        for (let b = a; b < S - 2; b++) {
          mn = Math.min(mn, lo[b]);
          mx = Math.max(mx, hi[b]);
          if (mx - mn > 2) break;
          const score = b - a + 1 - Math.abs(off) * S * 0.6;
          if (!best || score > best.score) best = { axis, line, a, b, score };
        }
      }
    }
  }
  if (!best || best.b - best.a + 1 < Math.max(10, Math.round(S * 0.5))) return false;
  const { axis, line, a, b } = best;
  // its corridor levelled: the banks and the lanes beside them one height (their middling one) three tiles either side,
  // easing back to the ground over two more, so the water lies a step under a level quay the whole way rather than in
  // a gorge wherever the ground was higher
  const banks: number[] = [];
  for (let s = a; s <= b; s++) banks.push(E[tileAt(axis, s, line[s] - 1)], E[tileAt(axis, s, line[s] + 2)]);
  banks.sort((p, q) => p - q);
  const B = Math.round(banks[banks.length >> 1]);
  const ease = (i: number, d: number) => {
    if (d <= 3) E[i] = B;
    else if (d <= 5) E[i] = B + (E[i] - B) * ((d - 3) / 3);
  };
  const inside = (x: number, z: number) => x >= p.x0 && z >= p.z0 && x < p.x0 + S && z < p.z0 + S;
  for (let s = Math.max(0, a - 3); s <= Math.min(S - 1, b + 3); s++) {
    const off = s < a ? a - s : s > b ? s - b : 0;
    for (let u = line[s] - 6; u <= line[s] + 7; u++) {
      const [x, z] = axis === 0 ? [p.x0 + s, u] : [u, p.z0 + s];
      if (!inB(x, z) || !inside(x, z)) continue;
      const d = Math.max(u < line[s] ? line[s] - u : u > line[s] + 1 ? u - line[s] - 1 : 0, off);
      ease(idx(x, z), d + (off ? 2 : 0));
    }
  }
  const tiles = new Set<number>();
  for (let s = a; s <= b; s++) for (const u of [0, 1]) tiles.add(tileAt(axis, s, line[s] + u));
  // the lake at the stream's lower end, round and a few tiles across (Lake Ashi, with the shrine's torii in it)
  let pond: [number, number] | undefined;
  if (lake) {
    const endA = E[tileAt(axis, a, line[a] - 1)] + E[tileAt(axis, a, line[a] + 2)];
    const endB = E[tileAt(axis, b, line[b] - 1)] + E[tileAt(axis, b, line[b] + 2)];
    const s = endA <= endB ? a : b, back = s === a ? 1 : -1;
    const r = S >= 30 ? 3.2 : 2.6;
    const sc = Math.max(r + 3, Math.min(S - r - 3, s + back * Math.round(r * 0.6)));
    const [cx, cz] = axis === 0 ? [p.x0 + sc + 0.5, line[s] + 1] : [line[s] + 1, p.z0 + sc + 0.5];
    const disc = new Set<number>();
    for (let z = Math.floor(cz - r); z <= Math.ceil(cz + r); z++) for (let x = Math.floor(cx - r); x <= Math.ceil(cx + r); x++) {
      if (x < p.x0 + 3 || z < p.z0 + 3 || x >= p.x0 + S - 3 || z >= p.z0 + S - 3) continue;
      if (Math.hypot(x + 0.5 - cx, z + 0.5 - cz) <= r) disc.add(idx(x, z));
    }
    // its shore levelled with the stream's quays
    for (let z = Math.floor(cz - r - 5); z <= Math.ceil(cz + r + 5); z++) for (let x = Math.floor(cx - r - 5); x <= Math.ceil(cx + r + 5); x++) {
      if (!inB(x, z) || !inside(x, z)) continue;
      ease(idx(x, z), Math.max(0, Math.hypot(x + 0.5 - cx, z + 0.5 - cz) - r));
    }
    // (kept only if it holds level with the stream: one sealed lake)
    const both = new Set([...tiles, ...disc]);
    if (disc.size >= 12 && level(both, E) - level(tiles, E) >= -1 && lakeOn(p, ctx, both)) pond = [cx, cz];
  }
  if (!pond && !lakeOn(p, ctx, tiles)) return false;
  const carved = (p.carved ??= {});
  carved.river = { axis, line, half: 1 };
  const note = (carved.note ??= {});
  note.a = a;
  note.b = b;
  if (pond) (carved.pts ??= {}).pond = pond;
  return true;
}

/** The level a sealed lake on these tiles would take: a step under the lowest ground round it. */
function level(tiles: Set<number>, E: Float32Array): number {
  let lo = Infinity;
  for (const i of tiles) {
    const x = i % N, z = (i - x) / N;
    for (const [dx, dz] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
      const j = idx(x + dx, z + dz);
      if (!tiles.has(j)) lo = Math.min(lo, E[j]);
    }
  }
  return Math.floor(lo) - 1;
}

// ---------------------------------------------------------------------------------------------
// the layout

/**
 * An onsen town (the onsen style): the through road crossing the stream on a bridge in the middle of town, lanes along
 * both banks and little bridges every few lots, the ryokan facing the water from both sides, the baths, the square
 * with its yubatake, shops and tea houses along the way in, and the flavour's own: Hakone's Fukuzumirō, ropeway and
 * lake torii, Kinosaki's seven baths, Beppu's hells and resort hotels, Dōgo's grand bathhouse. A city is then finished
 * as any city (its hall, its school, its streets of shops and flats); a village or a suburb fills in with two-storey
 * timber houses, shops under them near the middle.
 */
function onsenTown(c: Layout, p: TownPlan): boolean {
  const kind = c.t.kind, big = kind === 'city', mid = kind !== 'rural';
  const fl = flavourOf(p);
  c.t.onsen = FLAVOUR_LABEL[fl];
  const r = p.carved?.river ?? null, note = p.carved?.note ?? {};
  const pond = p.carved?.pts?.pond;
  c.bridgeSpan = 5;
  const C = c.centre();
  // the stream's frame: s along it (a tile across the square), u across it (its tiles are line[s] and line[s] + 1)
  const s0 = r ? (r.axis === 0 ? c.t.x0 : c.t.z0) : 0;
  const F = (s: number, u: number): Pt => (r!.axis === 0 ? [s0 + s + 0.5, u + 0.5] : [u + 0.5, s0 + s + 0.5]);
  const a = note.a ?? 0, b = note.b ?? 0;
  const streamMid = Math.round((a + b) / 2);
  // 1. the through road: across the stream where it is in the middle, or straight through
  let main: number[];
  if (r) {
    const [d0, d1] = r.axis === 0 ? [3, 1] : [2, 0];
    main = c.street(RoadType.TwoLane, [c.edge(d0), F(streamMid, r.line[streamMid] + 0.5), c.edge(d1)], MAIN, 8);
  } else {
    const d = Math.floor(c.rng() * 4);
    main = c.street(RoadType.TwoLane, [c.edge(d), C, c.edge((d + 2) % 4)], MAIN, 8);
  }
  c.ends(main);
  // 2. a lane along each bank, and little bridges across every few lots
  if (r) {
    for (const side of [-1, 1]) {
      const nodes: number[] = [];
      for (let s = a; s <= b; s++) {
        const u = side < 0 ? r.line[s] - 1 : r.line[s] + 2;
        const [x, z] = F(s, u);
        const n = idx(Math.floor(x), Math.floor(z));
        // a bend steps across, so the lane stays one piece
        if (nodes.length) {
          const prev = nodes[nodes.length - 1], px = prev % N, pz = (prev - px) / N, nx = n % N, nz = (n - nx) / N;
          if (px !== nx && pz !== nz) nodes.push(r.axis === 0 ? idx(px, nz) : idx(nx, pz));
        }
        nodes.push(n);
      }
      layNodes(c, RoadType.Paved, nodes, { main: false, route: true });
    }
    const every = big ? 10 : 8;
    for (let s = a + 4; s <= b - 3; s += every) {
      if (Math.abs(s - streamMid) < 5) continue;
      avenue(c, RoadType.Paved, F(s, r.line[s] - 1), F(s, r.line[s] + 2), { bridge: true, main: false, route: false });
    }
  }
  // 3. lanes up the slopes (never over the stream: only the through road and the little bridges cross it), and the whole
  // of it made one network
  c.bridgeSpan = 0;
  grow(c, c.t.roads + (big ? 9 : mid ? 6 : 3), RoadType.Paved);
  knit(c);
  if (!c.t.entry.length && main.length) c.ends(main);

  // 4. the square: Kusatsu's yubatake (now and then elsewhere), Dōgo's grand bathhouse
  const want = (p0: number) => c.rng() < p0;
  const nearC: Partial<Spec> = { near: C, maxDist: big ? 12 : 9 };
  if (fl === 'kusatsu' || want(0.35)) put(c, 'yubatake', nearC) ?? put(c, 'yubatake', { zone: 'any' });
  if (fl === 'dogo' || (mid && want(0.6))) put(c, 'dogoHonkan', nearC) ?? put(c, 'dogoHonkan', { zone: 'any' });
  // 5. the ryokan facing the stream from both banks (Ginzan's close together and tall), then anywhere
  const inns = kind === 'rural' ? c.int(3, 5) : kind === 'suburb' ? c.int(5, 7) : c.int(7, 10);
  const along: Pt[] = [];
  if (r) {
    for (let s = a + 1; s <= b - 1; s += fl === 'ginzan' ? 2 : 3) {
      along.push(F(s, r.line[s] - 2.5), F(s, r.line[s] + 3.5));
    }
  }
  const banks = shuffled(c, along);
  // Hakone's Fukuzumirō by the water (in Ginzan and Kinosaki too, and in one other town in three)
  if (fl === 'hakone' || fl === 'ginzan' || fl === 'kinosaki' || want(0.34)) {
    const at = banks.find((q) => q);
    (at ? put(c, 'fukuzumiro', { near: at, maxDist: 6 }) : null) ?? put(c, 'fukuzumiro', { zone: 'any' }) ?? put(c, 'fukuzumiro', { zone: 'any', w: 2, d: 3 });
  }
  let placed = 0;
  for (const at of banks) {
    if (placed >= inns) break;
    const floors = fl === 'ginzan' ? c.int(3, 4) : c.int(2, 4);
    if (put(c, 'ryokan', { near: at, maxDist: 2.5, floors })) placed++;
  }
  for (let k = 0; placed < inns && k < inns; k++) if (put(c, 'ryokan', { floors: c.int(2, 4) })) placed++;
  // a concrete resort ryokan or two up the slope (Beppu's and Atami's)
  const resorts = fl === 'beppu' ? (big ? 3 : 2) : big ? 2 : mid ? 1 : want(0.3) ? 1 : 0;
  for (let k = 0; k < resorts; k++) put(c, 'resortRyokan', { highest: true }) ?? put(c, 'resortRyokan', { zone: 'any', w: 3, d: 3 });
  for (let k = kind === 'rural' ? c.int(1, 2) : c.int(2, 3); k > 0; k--) put(c, 'minshuku');
  // 6. the baths: Kinosaki's seven, a couple anywhere else; a foot bath or two by the water
  const baths = fl === 'kinosaki' ? (kind === 'rural' ? 4 : 6) : mid ? 2 : 1;
  const bathAt = shuffled(c, along.length ? along : [C]);
  for (let k = 0; k < baths; k++) put(c, 'bathhouse', { near: bathAt[k % bathAt.length], maxDist: 5, zone: 'any' }) ?? put(c, 'bathhouse', { zone: 'any' });
  for (let k = mid ? 2 : 1; k > 0; k--) put(c, 'ashiyu', r ? { near: F(streamMid + c.int(-6, 6), r.line[streamMid] + 0.5), maxDist: 6 } : nearC) ?? put(c, 'ashiyu');
  // 7. the flavour's own: the hells, the ropeway, the lake torii
  const hells = fl === 'beppu' ? c.int(2, 3) : want(0.2) ? 1 : 0;
  for (let k = 0; k < hells; k++) put(c, 'jigoku') ?? put(c, 'jigoku', { zone: 'any' });
  if (fl === 'hakone' || want(0.15)) put(c, 'ropeway', { highest: true }) ?? put(c, 'ropeway', { zone: 'any' }) ?? put(c, 'ropeway', { zone: 'any', w: 5, d: 3 });
  if (pond) put(c, 'lakeTorii', { near: pond, maxDist: 6 });
  // 8. a shrine and a temple, tea, the souvenir street along the way in, somewhere to eat
  put(c, 'shrine', { zone: 'mid' });
  if (mid || want(0.5)) put(c, 'temple');
  if (want(0.4)) put(c, 'pagoda');
  for (let k = mid ? 2 : 1; k > 0; k--) put(c, 'teaHouse');
  const shops = kind === 'rural' ? 3 : kind === 'suburb' ? 5 : 7;
  for (let k = 0; k < shops; k++) c.place({ kind: 'shop', w: 1, d: 1, floors: 2, zone: 'core', lot: Lot.Plaza });
  eateries(c, kind, { lot: Lot.Plaza });
  put(c, 'bakery');
  // and what any town needs
  c.place({ kind: 'parking', w: 3, d: 2, zone: 'edge', solid: false, lot: Lot.Asphalt });
  if (mid) put(c, 'busStation');
  if (!big) {
    c.place({ kind: 'store', w: 1, d: 1, zone: 'core', floors: 2, lot: Lot.Plaza });
    put(c, 'postOffice', { w: 1, d: 1 });
    c.place({ kind: 'gas', w: 2, d: 2, zone: 'edge', lot: Lot.Asphalt });
    c.place({ kind: 'clinic', w: 2, d: 2, zone: 'mid', lot: Lot.Plaza });
    if (mid) {
      c.place({ kind: 'school', w: 3, d: 2, zone: 'mid', lot: Lot.Plaza });
      c.place({ kind: 'fire', w: 2, d: 2, zone: 'edge', lot: Lot.Paved });
      c.place({ kind: 'police', w: 2, d: 2, zone: 'mid', lot: Lot.Paved });
      c.place({ kind: 'grocery', w: 2, d: 2, zone: 'mid', lot: Lot.Plaza });
      put(c, 'villageHall') ?? put(c, 'communityCentre');
    } else {
      put(c, 'villageHall');
      // the slopes behind a village: tea, an orchard, the woods' timber
      putOne(c, shuffled(c, ['orchard', 'greenhouse', 'sawmill'] as BuildingKind[]));
    }
    factionSites(c, kind);
    if (NEXT_WORLD) playSites(c, kind);
    // and the rest: two-storey timber houses, shops under them near the middle, a minshuku now and then
    c.fill((df) => {
      const q = c.rng();
      if (df < 0.45 && q < 0.3) return [{ kind: 'shop', w: 1, d: 1, floors: 2, lot: Lot.Plaza }, { kind: 'townhouse', w: 1, d: 1, floors: 2, lot: Lot.Plaza }];
      if (q < 0.015) return [{ kind: 'minshuku', w: 1, d: 1, floors: 2, lot: Lot.Gravel }, { kind: 'townhouse', w: 1, d: 1, floors: 2, lot: Lot.Plaza }];
      if (df > 0.7 && q < 0.5) return [{ kind: 'house', w: 1, d: 1, lot: Lot.Lawn }];
      return [{ kind: 'townhouse', w: 1, d: 1, floors: df < 0.5 ? c.int(2, 3) : 2, lot: Lot.Plaza }];
    });
    c.finish((df) => (df < 0.55 ? Lot.Plaza : Lot.Lawn));
  } else {
    // a city: its hall, museum, school, streets of shops and flats, as any city's
    civic(c, 'city');
  }
  return true;
}

ONSEN_HOOKS.lay = onsenTown;
