import type { Arch, TownKind, World } from '../tiles';
import type { Layout, TownPlan } from '../towns';
import type { PlanCtx, SiteWants } from './types';

/**
 * Where world/towns.ts calls out to the city plans (world/plans/index.ts fills these in when it is loaded, which
 * world/generate.ts does), so towns.ts needn't import the plans and the plans may import towns.ts. Every call
 * site is behind NEXT_WORLD: with it off nothing here is ever called.
 */
interface PlanHooks {
  /** Before a town's site is looked for: its ranked plans and what they ask of the ground (null: no plan). */
  wants?: (w: World, kind: TownKind, index: number, biome: boolean) => SiteWants | null;
  /** A candidate square's extra score (lower is better) for what the plan asks. */
  siteScore?: (wants: SiteWants, x0: number, z0: number, size: number, std: number, wet: number) => number;
  /** The site is found: settle which of the ranked plans it takes (and how much relief that plan keeps). */
  settle?: (p: TownPlan, wants: SiteWants, ctx: PlanCtx) => void;
  /** The site is softened: cut what the plan needs into it. False if it can't, and the town falls back. */
  carve?: (p: TownPlan, ctx: PlanCtx) => boolean;
  /** The style roll's leanings, tilted toward the plan's home styles. */
  taste?: (p: TownPlan, taste: Partial<Record<Arch, number>>) => Partial<Record<Arch, number>>;
  /** A megalopolis's suburb's site score for its plan (lower is better): the Finger Plan's suburbs at its fingertips. */
  satellite?: (host: TownPlan, cx: number, cz: number) => number;
  /** Lay the town out to its plan. False (nothing laid) to be laid out as any town its size. */
  lay?: (c: Layout, p: TownPlan) => boolean;
}

export const PLAN_HOOKS: PlanHooks = {};
