import { N, Flag, RailBit, RoadType, World, edgeMismatch, idx, inB, steepness, type Bridge } from './tiles';
import { tileProblem, type Route } from './roads';
import { DIAG_MIN, diagonalType, staircase } from './diagonals';
import { hash2 } from './rng';

/**
 * Laying 45° diagonals (world/diagonals.ts): the road builder's diagonal mode, and the generator's country
 * roads cutting the corner across open land.
 */

const dirOf = (a: number, b: number) => { const d = b - a; return d === 1 ? 0 : d === N ? 1 : d === -1 ? 2 : d === -N ? 3 : -1; };

// ---------------------------------------------------------------------------------------------
// the road builder

/** Where a diagonal from `start` toward the cursor at `hover` ends: on the 45° line nearest it, the same number of tiles across as up. */
export function diagonalEnd(start: number, hover: number): number {
  const sx = start % N, sz = Math.floor(start / N), hx = hover % N, hz = Math.floor(hover / N);
  const dx = hx - sx, dz = hz - sz;
  const k = Math.round((Math.abs(dx) + Math.abs(dz)) / 2);
  const ex = sx + (dx < 0 ? -k : k), ez = sz + (dz < 0 ? -k : k);
  return inB(ex, ez) ? idx(ex, ez) : -1;
}

/**
 * The builder's diagonal from `start` to `end` (which must lie on a 45° line from it, two or more tiles each
 * way): its staircase of tiles, leaving square off a road the start stands on (so it meets that road at a
 * junction, not along it), every tile one a road can be laid on and every step one a car can drive. It may
 * cross other lanes; not the interstate, four lanes, a ramp, a bridge or the railway. A diagonal has no
 * bridges and no raised ends.
 */
export function diagonalRoute(w: World, type: RoadType, start: number, end: number): { route: Route } | { why: string } {
  if (!diagonalType(type)) return { why: 'Diagonals are lanes: dirt, gravel, brick, cobbles, paved or two-lane' };
  if (end < 0) return { why: 'That runs off the edge of the island' };
  const sx = start % N, sz = Math.floor(start / N), ex = end % N, ez = Math.floor(end / N);
  if (Math.abs(ex - sx) < 2) return { why: 'Drag further: a diagonal runs at least two tiles across and two up' };
  // off a road running along x it leaves along z first (and along x off any other)
  const e = w.roadEdges[start];
  const alongX = (e & 5) !== 0, alongZ = (e & 10) !== 0;
  const first: 0 | 1 = alongX && !alongZ ? 1 : 0;
  const nodes = staircase(start, end, first);
  if (!nodes) return { why: 'Not a 45° line' };
  for (let k = 1; k < nodes.length; k++) {
    const t = nodes[k], p = nodes[k - 1];
    const why = tileProblem(w, t);
    if (why) return { why };
    if (w.rail[t] & RailBit.Track) return { why: 'A diagonal can’t cross the railway: meet it square on with an ordinary road' };
    if (w.deckAxis[t]) return { why: 'A bridge is in the way of the diagonal' };
    const r = w.road[t] as RoadType;
    if (r && !diagonalType(r)) return { why: 'A diagonal can’t cross an interstate, four lanes or a ramp' };
    if (edgeMismatch(w, p, dirOf(p, t)) !== 0) return { why: 'A step in the ground across the diagonal — U to level it' };
  }
  return { route: { nodes, bridges: [] as Bridge[] } };
}

// ---------------------------------------------------------------------------------------------
// the generator: a country road cuts a long corner on the diagonal

/** Each leg of a corner must run at least this far for the corner to be cut. */
const LEG_MIN = 10;
/** The longest cut: tiles across (and up) the diagonal. */
const CUT_MAX = 22;
/** The shortest: anything less is barely a diagonal. */
const CUT_MIN = 4;
/** Tiles of straight road kept before and after the cut, so it meets the road square on. */
const KEEP = 2;
/** How far a diagonal keeps from any town's square, and from a harbour. */
const TOWN_GAP = 6;
/**
 * Share of the corners that could be cut that are: more near the county's edges, out where the long roads
 * between counties run across the empty land, fewer in its middle.
 */
const CHANCE_EDGE = 0.65, CHANCE_MID = 0.25, EDGE_BAND = 56;
/** The most a county cuts. */
const PER_CELL = 3;

const CUTS = new WeakMap<World, number>();
/** Each cut's staircase of tiles, corner tile first to last, by county (for the gates and the survey). */
const CUT_TILES = new WeakMap<World, number[][]>();

/** Can a generated diagonal run over tile t, coming from p? */
function openGround(w: World, t: number, p: number, d: number): boolean {
  if (w.road[t] || w.blocked[t] || w.deckAxis[t] || w.rail[t] || w.water[t] >= 0 || w.feature[t]) return false;
  if (w.flags[t] & (Flag.Field | Flag.Poi | Flag.River | Flag.Stream | Flag.Ramp | Flag.Terrace)) return false;
  if (w.townId[t] >= 0 || w.portId[t] >= 0 || steepness(w, t) > 1 || tileProblem(w, t)) return false;
  return edgeMismatch(w, p, d) === 0;
}

/** Is tile t at least TOWN_GAP from every town's square and harbour? */
function farFromTowns(w: World, t: number): boolean {
  const x = t % N, z = Math.floor(t / N);
  for (const tn of w.towns) {
    const dx = Math.max(tn.x0 - x, 0, x - (tn.x0 + tn.size - 1)), dz = Math.max(tn.z0 - z, 0, z - (tn.z0 + tn.size - 1));
    if (Math.max(dx, dz) < TOWN_GAP) return false;
  }
  for (const p of w.ports) if (Math.abs(p.x - x) < TOWN_GAP + 4 && Math.abs(p.z - z) < TOWN_GAP + 4) return false;
  return true;
}

/**
 * A generated country road with its long corners cut on the diagonal: wherever it turns square between two
 * straights each LEG_MIN or more long, out in open country well clear of any town, it may (a roll per corner,
 * a few a county at most) leave the first straight some way before the corner and run at 45° to the second,
 * the same number of tiles across as up — the same count of tiles as the corner it replaces, so the bridges
 * along the road keep their places, and a √2 the shorter drive. Every tile of the cut must be open, dry,
 * fairly flat ground no road, field, railway or building has, with level edges between them. Deterministic:
 * the rolls are hashed from the cell and the corner.
 */
export function cutCorners(w: World, route: Route, type: RoadType): Route {
  if (!diagonalType(type) || route.nodes.length < 2 * LEG_MIN + 1) return route;
  let cuts = CUTS.get(w) ?? 0;
  if (cuts >= PER_CELL) return route;
  let nodes = route.nodes;
  const busy = (a: number, b: number) => route.bridges.some((br) => br.from < b && br.to > a);
  let from = 1;
  for (;;) {
    // the straights, as [first node, last node, direction]
    const dirs: number[] = [];
    for (let k = 0; k < nodes.length - 1; k++) dirs.push(dirOf(nodes[k], nodes[k + 1]));
    let found = false;
    for (let c = Math.max(from, 1); c < nodes.length - 1; c++) {
      const a = dirs[c - 1], b = dirs[c];
      if (a < 0 || b < 0 || a === b || ((a + b) & 1) === 0) continue;
      let s = c - 1; while (s > 0 && dirs[s - 1] === a) s--;
      let e = c; while (e + 1 < dirs.length && dirs[e + 1] === b) e++;
      const legIn = c - s, legOut = e + 1 - c;
      if (legIn < LEG_MIN || legOut < LEG_MIN) continue;
      const corner = nodes[c];
      const cx = corner % N, cz = Math.floor(corner / N);
      const nearEdge = Math.min(cx, cz, N - 1 - cx, N - 1 - cz) < EDGE_BAND;
      if (hash2(cx + w.cx * 1013, cz + w.cz * 7919, 8111) >= (nearEdge ? CHANCE_EDGE : CHANCE_MID)) continue;
      // as long a cut as the ground allows, from the longest down
      for (let k = Math.min(legIn - KEEP, legOut - KEEP, CUT_MAX); k >= CUT_MIN; k--) {
        if (2 * k < DIAG_MIN || busy(c - k, c + k)) continue;
        const P = nodes[c - k], Q = nodes[c + k];
        const stair = staircase(P, Q, (a % 2) as 0 | 1);
        if (!stair) continue;
        const rest = new Set([...nodes.slice(0, c - k), ...nodes.slice(c + k + 1)]);
        let good = true;
        for (let q = 1; q < stair.length - 1 && good; q++) {
          const t = stair[q];
          good = !rest.has(t) && openGround(w, t, stair[q - 1], dirOf(stair[q - 1], t)) && farFromTowns(w, t);
        }
        // and the last step onto the road again
        if (good) good = edgeMismatch(w, stair[stair.length - 2], dirOf(stair[stair.length - 2], Q)) === 0;
        if (!good) continue;
        nodes = [...nodes.slice(0, c - k), ...stair, ...nodes.slice(c + k + 1)];
        cuts++;
        const list = CUT_TILES.get(w) ?? [];
        list.push(stair);
        CUT_TILES.set(w, list);
        from = c + k + 1;
        found = true;
        break;
      }
      if (found) break;
    }
    if (!found || cuts >= PER_CELL) break;
  }
  CUTS.set(w, cuts);
  return nodes === route.nodes ? route : { ...route, nodes };
}

/** The diagonals the generator cut in a county, each as its staircase from the tile it leaves the road at to the one it rejoins it at. */
export function cutsIn(w: World): number[][] { return CUT_TILES.get(w) ?? []; }
