/**
 * Motor-racing circuits (docs/circuits.html): a rare wonder of the open country, a big flat lot with a
 * real track on it — a banked NASCAR tri-oval, a steep short-track bullring, a twisting grand prix
 * circuit or an old concrete bowl — ringed by grandstands, with a pit lane, a painted grid and a
 * chequered line. The races on it are run by game/circuits.ts; this is the ground they run on.
 *
 * Everything here is in the model's frame, as a building's model is drawn (origin mid-lot, +z the way
 * the lot faces, which is the front: the road comes in there), and depends only on the design, which is
 * read back from the lot's size. So worldgen, the footprint, the renderer, the car's wheels (the banking)
 * and the race all read one plan, and nothing about it is saved.
 *
 * Every design is run the same way round: along the front straight toward -x, so the ovals turn left as
 * an oval should. The start line is on the front straight, the grid behind it, the pit lane on its
 * infield side and the main grandstand across the track from the pits, between the track and the gate.
 */
import { N, DIRS, STEP, Biome, Flag, Lot, SEA, idx, inB, type Building, type World } from './tiles';
import type { WorkSite } from './industry';
import type { Rng } from './rng';

type CircuitDesign = 'speedway' | 'bullring' | 'grandprix' | 'heritage';
export const CIRCUIT_DESIGNS: readonly CircuitDesign[] = ['speedway', 'bullring', 'grandprix', 'heritage'];

interface Spec {
  /** The lot in the model's frame: across the front, and deep. Unique to the design, which is how it is read back. */
  W: number; D: number;
  /** Half the track's width, in tiles. */
  half: number;
  /** Lift of the outer edge in the turns, and on the straights, world units. */
  bank: number; flatBank: number;
  /** A bowl (the old concrete tracks: steepest at the top) rather than a plane. */
  concave: boolean;
  /** A wall round the outside of the track. */
  wall: boolean;
  /** Open ground between the track's outer edge (or its wall) and the stands. */
  runoff: number;
  label: string;
  /** Its name; `{w}` is the county's. */
  names: string[];
  /** What its races are called. */
  races: string[];
}

const CIRCUIT_SPECS: Record<CircuitDesign, Spec> = {
  speedway: {
    W: 46, D: 31, half: 1.6, bank: 0.55, flatBank: 0.12, concave: false, wall: true, runoff: 0.6, label: 'Superspeedway',
    names: ['Thunder Valley Speedway', 'Kestrel Motor Speedway', 'Redline International Speedway', 'Big Sky Superspeedway', '{w} Motor Speedway', '{w} International Speedway'],
    races: ['{w} 300', 'Thunder 200', 'Summer Showdown', 'Firecracker 250', 'Night Classic'],
  },
  bullring: {
    W: 36, D: 28, half: 1.6, bank: 0.75, flatBank: 0.24, concave: false, wall: true, runoff: 0.5, label: 'Short track',
    names: ['The Bullring', '{w} Short Track', 'Coliseum Raceway', 'The Half-Mile', '{w} Bowl'],
    races: ['Saturday Night 100', 'Bullring Brawl', '{w} Short Track 150', 'Last Lap Scramble'],
  },
  grandprix: {
    W: 52, D: 34, half: 1.6, bank: 0, flatBank: 0, concave: false, wall: false, runoff: 1.6, label: 'Grand prix circuit',
    names: ['Circuit de {w}', '{w} Grand Prix Circuit', 'Autodromo di {w}', '{w} International Circuit', 'Parc Motor Circuit'],
    races: ['{w} Grand Prix', 'Sprint Trophy', 'Autumn Cup', 'Champions’ Sprint'],
  },
  heritage: {
    W: 48, D: 27, half: 1.6, bank: 0.7, flatBank: 0, concave: true, wall: true, runoff: 0.6, label: 'Old banked circuit',
    names: ['Brookmere Motor Circuit', 'The Old Banking', '{w} Motordrome', 'Weybridge Park Circuit', '{w} Bowl Circuit'],
    races: ['Vintage Trophy', 'Members’ Handicap', 'Double Twelve', 'Gold Star Sprint'],
  },
};

/** The design a lot of this size (model frame: W across, D deep) was laid out for. */
export function designOf(W: number, D: number): CircuitDesign {
  for (const d of CIRCUIT_DESIGNS) if (CIRCUIT_SPECS[d].W === W && CIRCUIT_SPECS[d].D === D) return d;
  return 'speedway';
}

/** A lot's model-frame size (W across the front, D deep) from its tile rectangle and facing. */
export const modelDims = (b: Building): [number, number] => (b.facing % 2 === 1 ? [b.w, b.d] : [b.d, b.w]);

// ---- the plan ------------------------------------------------------------------------------------

/** A box in the model's frame, centred on (x, z) and turned by `a` (Kit.turned's yaw): `len` along its x, `dep` along its z. */
export interface OBox { x: number; z: number; a: number; len: number; dep: number; h: number }

/** A grandstand: an OBox whose +z (in its own turned frame) faces the track. */
export interface Stand extends OBox { rows: number; main: boolean; roof: boolean }

export interface Slot { x: number; z: number; heading: number; s: number; u: number }

export interface CircuitPlan {
  design: CircuitDesign;
  spec: Spec;
  W: number; D: number; half: number;
  /** The centreline, closed, every DS tiles: x and z interleaved. Point 0 is on the start line. */
  n: number;
  px: Float32Array; pz: Float32Array;
  /** Unit tangent (the way the race runs) and the lift of the outer edge at each point. */
  tx: Float32Array; tz: Float32Array;
  bank: Float32Array;
  /** Signed curvature (+ bends right) and how much of a corner each point is (0..1), for kerbs. */
  curv: Float32Array; corner: Float32Array;
  /** Lap length, tiles. */
  len: number;
  /** Which side of the track (sign of the right-hand normal) is the outside, for banking and the wall; 0 for a road circuit. */
  outer: 1 | 0;
  stands: Stand[];
  /** Solid things that are not stands: the pit building, the tower, the podium, trucks, the gantry's legs. */
  solids: OBox[];
  pitBuilding: OBox[];
  /** The pit lane, from where it leaves the track to where it rejoins: points and their lateral offset from the centreline. */
  pit: { s: number; u: number }[];
  /** Where the pit lane runs at its full offset: [s0, s1] (s0 may be negative: before the line). */
  pitFull: [number, number];
  pitOff: number;
  /** Cars park here in the pit lane, nearest the exit first. */
  garages: Slot[];
  /** The starting grid: pole first. */
  grid: Slot[];
  /** The gate: its x on the front edge, and the z where the entrance lane meets the track's outer edge. */
  gateX: number; gateZ: number;
  /** How far along the lap the entrance lane meets the track. */
  gateS: number;
  /** Tower, podium and the leaderboard pylon (speedway), in the model's frame. */
  tower: { x: number; z: number } | null;
  podium: { x: number; z: number; a: number } | null;
  pylon: { x: number; z: number } | null;
  /** The start gantry's two legs. */
  gantry: [{ x: number; z: number }, { x: number; z: number }];
  /** Grass in the infield where spectators park, in the model's frame. */
  parking: { x: number; z: number; a: number }[];
  /** The raster: RES cells a tile. */
  gw: number; gd: number;
  lift: Float32Array;
  /** 0 grass, 1 track, 2 apron / pit lane, 3 wall (solid), 4 pit wall (solid). */
  zone: Uint8Array;
  /** Along the lap, tiles from the line, where a cell is on or beside the track; -1 elsewhere. */
  sAt: Float32Array;
  uAt: Float32Array;
}

/** Centreline spacing, tiles. */
export const DS = 0.5;
/** Raster cells a tile. */
const RES = 4;

type Pt = { x: number; z: number; t: number };

/** An oval: two straights of Ls joined by half circles of radius R, round a middle at z = zc; -x along the front, turning left. */
function oval(Ls: number, R: number, zc: number, bulge: number): Pt[] {
  const pts: Pt[] = [];
  const st = 0.1;
  for (let x = Ls / 2; x > -Ls / 2; x -= st) pts.push({ x, z: zc + R, t: 0 });
  for (let a = 0; a < Math.PI; a += st / R) pts.push({ x: -Ls / 2 - R * Math.sin(a), z: zc + R * Math.cos(a), t: 1 });
  for (let x = -Ls / 2; x < Ls / 2; x += st) pts.push({ x, z: zc - R, t: 0 });
  for (let a = 0; a < Math.PI; a += st / R) pts.push({ x: Ls / 2 + R * Math.sin(a), z: zc - R * Math.cos(a), t: 1 });
  // the tri-oval: the front straight bowed out toward the grandstand in one long curve
  if (bulge) for (const p of pts) if (p.z > zc && Math.abs(p.x) < Ls / 2) p.z += bulge * Math.cos((Math.PI * p.x) / Ls) ** 2;
  return pts;
}

/** A closed centripetal Catmull–Rom spline through the control points, densely sampled. */
function spline(ctrl: { x: number; z: number }[], per = 60): Pt[] {
  const out: Pt[] = [];
  const n = ctrl.length;
  const tj = (a: { x: number; z: number }, b: { x: number; z: number }) => Math.sqrt(Math.hypot(b.x - a.x, b.z - a.z)) || 1e-4;
  for (let i = 0; i < n; i++) {
    const p0 = ctrl[(i - 1 + n) % n], p1 = ctrl[i], p2 = ctrl[(i + 1) % n], p3 = ctrl[(i + 2) % n];
    const t0 = 0, t1 = t0 + tj(p0, p1), t2 = t1 + tj(p1, p2), t3 = t2 + tj(p2, p3);
    for (let k = 0; k < per; k++) {
      const t = t1 + ((t2 - t1) * k) / per;
      const lerp = (a: { x: number; z: number }, b: { x: number; z: number }, ta: number, tb: number) => {
        const f = (t - ta) / (tb - ta);
        return { x: a.x + (b.x - a.x) * f, z: a.z + (b.z - a.z) * f };
      };
      const A1 = lerp(p0, p1, t0, t1), A2 = lerp(p1, p2, t1, t2), A3 = lerp(p2, p3, t2, t3);
      const B1 = lerp(A1, A2, t0, t2), B2 = lerp(A2, A3, t1, t3);
      const C = lerp(B1, B2, t1, t2);
      out.push({ x: C.x, z: C.z, t: 0 });
    }
  }
  return out;
}

/** Resample a closed polyline every `ds` tiles, carrying `t` along. */
function resample(src: Pt[], ds: number): Pt[] {
  const cum = [0];
  for (let i = 1; i <= src.length; i++) {
    const a = src[i - 1], b = src[i % src.length];
    cum.push(cum[i - 1] + Math.hypot(b.x - a.x, b.z - a.z));
  }
  const total = cum[src.length];
  const n = Math.max(8, Math.round(total / ds));
  const step = total / n;
  const out: Pt[] = [];
  let j = 0;
  for (let k = 0; k < n; k++) {
    const s = k * step;
    while (cum[j + 1] < s) j++;
    const a = src[j], b = src[(j + 1) % src.length];
    const f = (s - cum[j]) / Math.max(1e-6, cum[j + 1] - cum[j]);
    out.push({ x: a.x + (b.x - a.x) * f, z: a.z + (b.z - a.z) * f, t: a.t + (b.t - a.t) * f });
  }
  return out;
}

/** The grand prix circuit's corners, in fractions of the lot (x across, z deep), as it runs: -x along the front. */
const GP_CTRL: [number, number][] = [
  [0.52, 0.58], [0.2, 0.58], [-0.2, 0.58], [-0.52, 0.58],
  // turn 1 down into the esses at the left end
  [-0.74, 0.46], [-0.8, 0.18], [-0.7, 0.0], [-0.8, -0.2],
  // the hairpin at the back left
  [-0.82, -0.48], [-0.66, -0.66], [-0.46, -0.56],
  // back through the infield: a kink in and out again
  [-0.28, -0.34], [-0.08, -0.36], [0.06, -0.62],
  // the long back straight and the sweeper at the right end
  [0.3, -0.7], [0.62, -0.66], [0.82, -0.48],
  [0.86, -0.1], [0.76, 0.2], [0.82, 0.44], [0.7, 0.58],
];

/** The line through a design's corners, before it is cut to DS and started at the line. */
function centreline(design: CircuitDesign, W: number, D: number): Pt[] {
  const s = CIRCUIT_SPECS[design];
  // the front straight sits in front of the grandstand, which stands between the track and the gate
  const standDeep = design === 'grandprix' ? 3.4 : design === 'heritage' ? 3 : 3.8;
  const zFront = D / 2 - 0.4 - standDeep - s.runoff - (s.wall ? 0.5 : 0) - s.half;
  switch (design) {
    case 'speedway': {
      const R = 8.2, bulge = 1.6, zc = zFront - bulge - R;
      const Ls = W - 2 * R - 2 * (s.half + 0.5 + s.runoff + 2.6) - 0.8;
      return oval(Ls, R, zc, bulge);
    }
    case 'bullring': {
      const R = 7.4, zc = zFront - R;
      const Ls = W - 2 * R - 2 * (s.half + 0.5 + s.runoff + 3.2) - 0.8;
      return oval(Ls, R, zc, 0);
    }
    case 'heritage': {
      const R = 6.8, zc = zFront - R;
      const Ls = W - 2 * R - 2 * (s.half + 0.5 + s.runoff + 1.8) - 0.8;
      return oval(Ls, R, zc, 0);
    }
    case 'grandprix': {
      const ax = W / 2 - 3.6, az = zFront / 0.58;
      return spline(GP_CTRL.map(([x, z]) => ({ x: x * ax, z: z * az })));
    }
  }
}

const smoothstep = (a: number, b: number, x: number) => { const t = Math.max(0, Math.min(1, (x - a) / (b - a))); return t * t * (3 - 2 * t); };
const wrapS = (s: number, len: number) => ((s % len) + len) % len;

/** A point on the centreline `s` tiles from the line (wrapping), with its tangent: interpolated. */
export function along(p: CircuitPlan, s: number): { x: number; z: number; tx: number; tz: number; bank: number } {
  const f = wrapS(s, p.len) / DS;
  const i = Math.floor(f) % p.n, j = (i + 1) % p.n, k = f - Math.floor(f);
  const tx = p.tx[i] + (p.tx[j] - p.tx[i]) * k, tz = p.tz[i] + (p.tz[j] - p.tz[i]) * k;
  const l = Math.hypot(tx, tz) || 1;
  return { x: p.px[i] + (p.px[j] - p.px[i]) * k, z: p.pz[i] + (p.pz[j] - p.pz[i]) * k, tx: tx / l, tz: tz / l, bank: p.bank[i] + (p.bank[j] - p.bank[i]) * k };
}

/** The point `u` tiles to the right of the centreline at `s` (the right-hand normal of the way the race runs). */
export function offsetAt(p: CircuitPlan, s: number, u: number): { x: number; z: number; heading: number } {
  const a = along(p, s);
  return { x: a.x + a.tz * u, z: a.z - a.tx * u, heading: Math.atan2(a.tx, a.tz) };
}

/** The lift of the track surface `u` tiles right of the centreline where its outer edge is lifted `bank`. */
export function bankLift(p: CircuitPlan, bank: number, u: number): number {
  if (!p.outer || bank <= 0) return 0;
  const h = p.half;
  const t = Math.max(0, Math.min(1, (u + h) / (2 * h)));
  return bank * (p.spec.concave ? t ** 1.7 : t);
}

/** Is a model-frame point inside an OBox (grown by `m`)? */
export function inOBox(o: OBox, x: number, z: number, m = 0): boolean {
  const dx = x - o.x, dz = z - o.z;
  // the box's own x axis in the model is (cos a, -sin a), its z axis (sin a, cos a)
  const c = Math.cos(o.a), s = Math.sin(o.a);
  const lx = dx * c - dz * s, lz = dx * s + dz * c;
  return Math.abs(lx) <= o.len / 2 + m && Math.abs(lz) <= o.dep / 2 + m;
}

/** A model-frame point from a point in an OBox's own frame. */
function fromOBox(o: OBox, lx: number, lz: number): { x: number; z: number } {
  const c = Math.cos(o.a), s = Math.sin(o.a);
  return { x: o.x + lx * c + lz * s, z: o.z - lx * s + lz * c };
}

/** The yaw (Kit.turned) that turns a box's +z toward (dx, dz). */
export const yawFacing = (dx: number, dz: number): number => Math.atan2(dx, dz);

const PLANS = new Map<CircuitDesign, CircuitPlan>();

/** The plan for a design: built once, shared by every circuit of that design. */
export function circuitPlan(design: CircuitDesign): CircuitPlan {
  let p = PLANS.get(design);
  if (!p) { p = buildPlan(design); PLANS.set(design, p); }
  return p;
}

/** The plan for a circuit's lot. */
export const planOf = (b: Building): CircuitPlan => { const [W, D] = modelDims(b); return circuitPlan(designOf(W, D)); };

function buildPlan(design: CircuitDesign): CircuitPlan {
  const spec = CIRCUIT_SPECS[design];
  const { W, D, half } = spec;
  let pts = resample(centreline(design, W, D), DS);
  // start on the line: the front straight's point nearest x = startX
  const startX = design === 'speedway' ? 1.5 : 0;
  let best = 0, bd = Infinity;
  for (let i = 0; i < pts.length; i++) {
    const p = pts[i];
    if (p.z < 0) continue;
    const d = Math.abs(p.x - startX) + (p.t > 0.01 ? 99 : 0);
    if (d < bd) { bd = d; best = i; }
  }
  pts = [...pts.slice(best), ...pts.slice(0, best)];
  const n = pts.length;
  const px = new Float32Array(n), pz = new Float32Array(n), tx = new Float32Array(n), tz = new Float32Array(n);
  for (let i = 0; i < n; i++) { px[i] = pts[i].x; pz[i] = pts[i].z; }
  for (let i = 0; i < n; i++) {
    const a = (i - 1 + n) % n, b = (i + 1) % n;
    const dx = px[b] - px[a], dz = pz[b] - pz[a], l = Math.hypot(dx, dz) || 1;
    tx[i] = dx / l; tz[i] = dz / l;
  }
  const curv = new Float32Array(n);
  for (let i = 0; i < n; i++) {
    const a = (i - 1 + n) % n, b = (i + 1) % n;
    // right-hand normal (tz, -tx): how fast the tangent swings toward it
    curv[i] = ((tx[b] - tx[a]) * tz[i] + (tz[b] - tz[a]) * -tx[i]) / (2 * DS);
  }
  const smooth = (src: ArrayLike<number>, r: number): Float32Array => {
    const out = new Float32Array(n);
    for (let i = 0; i < n; i++) {
      let sum = 0;
      for (let k = -r; k <= r; k++) sum += src[(i + k + n) % n];
      out[i] = sum / (2 * r + 1);
    }
    return out;
  };
  // the banking: the turns of an oval, eased in and out over a few tiles either side
  const turn = smooth(pts.map((p) => p.t), 10);
  const bank = new Float32Array(n);
  for (let i = 0; i < n; i++) bank[i] = spec.flatBank + (spec.bank - spec.flatBank) * smoothstep(0.05, 0.95, turn[i]);
  const absK = smooth(Array.from(curv, Math.abs), 3);
  const corner = new Float32Array(n);
  for (let i = 0; i < n; i++) corner[i] = smoothstep(0.08, 0.2, absK[i]);
  const len = n * DS;
  const outer: 1 | 0 = spec.wall || spec.bank > 0 ? 1 : 0;

  const p: CircuitPlan = {
    design, spec, W, D, half, n, px, pz, tx, tz, bank, curv, corner, len, outer,
    stands: [], solids: [], pitBuilding: [], pit: [], pitFull: [0, 0], pitOff: half + 1.5, garages: [], grid: [],
    gateX: 0, gateZ: 0, gateS: 0, tower: null, podium: null, pylon: null,
    gantry: [{ x: 0, z: 0 }, { x: 0, z: 0 }], parking: [],
    gw: W * RES, gd: D * RES, lift: new Float32Array(0), zone: new Uint8Array(0), sAt: new Float32Array(0), uAt: new Float32Array(0),
  };

  // ---- the front straight: from where it leaves the last turn (s < 0, +x) to turn 1 (s > 0, -x) ----
  const straight = (k: number) => corner[(k + n) % n] <= 0.3 && pts[(k + n) % n].t <= 0.3;
  let e1 = 0, e0 = 0;
  while (e1 < n / 2 && straight(e1 + 1)) e1++;
  while (e0 > -n / 2 && straight(e0 - 1)) e0--;
  const frontEnd = e1 * DS, frontStart = e0 * DS;

  // ---- the gate: in the front edge, onto the front straight short of turn 1 ----
  p.gateS = Math.max(3, frontEnd - 3.5);
  const g = along(p, p.gateS);
  p.gateX = Math.round(g.x * 2) / 2;
  p.gateZ = g.z + half + (spec.wall ? 0.5 : 0);

  // ---- the pit lane: on the infield side of the front straight, around the line ----
  const pitOff = p.pitOff;
  const full1 = Math.min(3.5, frontEnd - 1), full0 = full1 - 11;
  const ramp = 5;
  p.pitFull = [full0, full1];
  for (let s = full0 - ramp; s <= full1 + ramp + 1e-6; s += DS) {
    const f = s < full0 ? smoothstep(full0 - ramp, full0, s) : s > full1 ? 1 - smoothstep(full1, full1 + ramp, s) : 1;
    p.pit.push({ s, u: -pitOff * f });
  }
  // cars park in the lane, nearest the exit first
  for (let k = 0; k < 6; k++) {
    const s = full1 - 0.8 - k * 1.6;
    const o = offsetAt(p, s, -pitOff);
    p.garages.push({ x: o.x, z: o.z, heading: o.heading, s, u: -pitOff });
  }
  // the pit building behind the lane, in straight runs of a few tiles, where the straight is
  const bDep = 1.7, bOff = pitOff + 0.8 + 0.25 + bDep / 2;
  const b0 = Math.max(full0, frontStart) + 0.3, b1 = full1 - 0.3;
  const pieces = Math.max(1, Math.round((b1 - b0) / 4.2));
  for (let k = 0; k < pieces; k++) {
    const s0 = b0 + ((b1 - b0) * k) / pieces, s1 = b0 + ((b1 - b0) * (k + 1)) / pieces;
    const a = offsetAt(p, s0, -bOff), b = offsetAt(p, s1, -bOff);
    const dx = b.x - a.x, dz = b.z - a.z, l = Math.hypot(dx, dz) || 1;
    // its front (+z) to the track: the chord's right-hand normal
    const box: OBox = { x: (a.x + b.x) / 2, z: (a.z + b.z) / 2, a: yawFacing(dz / l, -dx / l), len: l + 0.08, dep: bDep, h: 0.75 };
    p.pitBuilding.push(box);
    p.solids.push(box);
  }
  // ---- the raster: nearest centreline point to every cell near the track ----
  rasterise(p);

  // the race control tower at the pit building's exit end, the podium behind its middle
  {
    const mid = p.pitBuilding[Math.floor(p.pitBuilding.length / 2)];
    // pieces run with s, so the exit end is the far end of the last piece: its local -x (the chord runs toward -x of the box)
    const end = p.pitBuilding[p.pitBuilding.length - 1];
    const t = fromOBox(end, -(end.len / 2 + 0.8), -0.2);
    const tower: OBox = { x: t.x, z: t.z, a: end.a, len: 1.1, dep: 1.1, h: 2.2 };
    if (clearFor(p, tower, 0.1)) { p.tower = { x: t.x, z: t.z }; p.solids.push(tower); }
    const q = fromOBox(mid, 0, -(mid.dep / 2 + 1.1));
    const podium: OBox = { x: q.x, z: q.z, a: mid.a, len: 1.6, dep: 0.9, h: 0.5 };
    if (clearFor(p, podium, 0.1)) { p.podium = { x: q.x, z: q.z, a: mid.a }; p.solids.push(podium); }
  }
  // the grid: two by two behind the line, pole on the inside
  for (let k = 0; k < 8; k++) {
    const s = len - (1.6 + 2.2 * Math.floor(k / 2) + (k % 2) * 1.1);
    const u = k % 2 === 0 ? -0.84 : 0.84;
    const o = offsetAt(p, s, u);
    p.grid.push({ x: o.x, z: o.z, heading: o.heading, s, u });
  }
  // the gantry over the line
  {
    const a = offsetAt(p, 0, -(half + 0.35)), b = offsetAt(p, 0, half + (spec.wall ? 0.75 : 0.45));
    p.gantry = [{ x: a.x, z: a.z }, { x: b.x, z: b.z }];
    for (const q of p.gantry) p.solids.push({ x: q.x, z: q.z, a: 0, len: 0.22, dep: 0.22, h: 1.4 });
  }

  // ---- grandstands ----
  standsFor(p, pts);

  // ---- the speedway's leaderboard pylon, in the tri-oval's infield ----
  if (design === 'speedway') {
    const o = offsetAt(p, 0, -(pitOff + 5.8));
    const pylon: OBox = { x: o.x, z: o.z, a: 0, len: 0.8, dep: 0.8, h: 3 };
    if (clearFor(p, pylon, 0.2)) { p.pylon = { x: o.x, z: o.z }; p.solids.push(pylon); }
  }
  // team trucks parked in the paddock behind the pit building
  for (const box of p.pitBuilding) {
    for (const off of [-1, 1]) {
      const q = fromOBox(box, off * box.len * 0.22, -(box.dep / 2 + 1.3));
      const truck: OBox = { x: q.x, z: q.z, a: box.a, len: 1.6, dep: 0.55, h: 0.5 };
      if (clearFor(p, truck, 0.3)) p.solids.push(truck);
    }
  }
  // spectators park on the infield grass
  parkingFor(p);
  return p;
}

/** Fill the raster: lift, zone, and where along the lap each cell near the track lies. */
function rasterise(p: CircuitPlan): void {
  const { gw, gd, n, half, W, D, spec } = p;
  const lift = new Float32Array(gw * gd), zone = new Uint8Array(gw * gd), sAt = new Float32Array(gw * gd).fill(-1), uAt = new Float32Array(gw * gd).fill(NaN);
  const dist = new Float32Array(gw * gd).fill(Infinity);
  const reach = half + 2.9;
  for (let i = 0; i < n; i++) {
    const j = (i + 1) % n;
    const ax = p.px[i], az = p.pz[i], bx = p.px[j], bz = p.pz[j];
    const ex = bx - ax, ez = bz - az, l2 = ex * ex + ez * ez || 1;
    const x0 = Math.max(0, Math.floor((Math.min(ax, bx) - reach + W / 2) * RES)), x1 = Math.min(gw - 1, Math.ceil((Math.max(ax, bx) + reach + W / 2) * RES));
    const z0 = Math.max(0, Math.floor((Math.min(az, bz) - reach + D / 2) * RES)), z1 = Math.min(gd - 1, Math.ceil((Math.max(az, bz) + reach + D / 2) * RES));
    for (let gz = z0; gz <= z1; gz++) {
      for (let gx = x0; gx <= x1; gx++) {
        const x = (gx + 0.5) / RES - W / 2, z = (gz + 0.5) / RES - D / 2;
        const f = Math.max(0, Math.min(1, ((x - ax) * ex + (z - az) * ez) / l2));
        const cx = ax + ex * f, cz = az + ez * f;
        const d = Math.hypot(x - cx, z - cz);
        const c = gz * gw + gx;
        if (d >= dist[c] || d > reach) continue;
        dist[c] = d;
        const l = Math.sqrt(l2);
        // right-hand normal of the segment: (ez, -ex)
        uAt[c] = ((x - ax) * ez - (z - az) * ex) / l;
        sAt[c] = (i + f) * DS;
      }
    }
  }
  const gateHalf = 1.5;
  for (let c = 0; c < gw * gd; c++) {
    if (sAt[c] < 0) continue;
    const s = sAt[c], u = uAt[c];
    const i = Math.floor(s / DS) % n, j = (i + 1) % n, k = s / DS - Math.floor(s / DS);
    const bank = p.bank[i] + (p.bank[j] - p.bank[i]) * k;
    const x = ((c % gw) + 0.5) / RES - W / 2, z = (Math.floor(c / gw) + 0.5) / RES - D / 2;
    const atGate = Math.abs(x - p.gateX) < gateHalf && z > p.gateZ - half - 1.2;
    if (Math.abs(u) <= half) {
      zone[c] = 1;
      lift[c] = bankLift(p, bank, u);
    } else if (u > half) {
      // the outside: the wall, and the gap in it where the entrance lane comes in (ramped down to the lane)
      if (p.outer) {
        if (atGate) { lift[c] = bank * Math.max(0, 1 - (u - half) / 1.4); zone[c] = 2; }
        else if (spec.wall && u <= half + 0.5) { lift[c] = bank; zone[c] = u > half + 0.08 ? 3 : 1; }
        else lift[c] = 0;
      }
    } else {
      // the inside: the apron, and the pit lane and its wall along the front straight
      const inPit = inPitLane(p, s, u);
      if (inPit === 2) zone[c] = 4;
      else if (inPit === 1 || (p.outer && u >= -half - 0.9)) zone[c] = 2;
    }
  }
  p.lift = lift; p.zone = zone; p.sAt = sAt; p.uAt = uAt;
}

/** Is (s, u) on the pit lane (1), on the pit wall between it and the track (2), or neither (0)? */
function inPitLane(p: CircuitPlan, s: number, u: number): 0 | 1 | 2 {
  const s0 = p.pit[0].s, s1 = p.pit[p.pit.length - 1].s;
  // s runs 0..len; the lane straddles the line, so unwrap onto it
  const ss = s > p.len / 2 ? s - p.len : s;
  if (ss < s0 || ss > s1) return 0;
  const f = (ss - s0) / DS, i = Math.min(p.pit.length - 2, Math.floor(f)), k = f - i;
  const lane = p.pit[i].u + (p.pit[i + 1].u - p.pit[i].u) * k;
  if (ss >= p.pitFull[0] + 0.3 && ss <= p.pitFull[1] - 0.3 && u < -p.half - 0.3 && u > -p.half - 0.7) return 2;
  return Math.abs(u - lane) <= 0.75 && lane < -0.2 ? 1 : 0;
}

/** Nothing solid within `m` of this box, it's on the lot, and it keeps off the track, the pit lane and the gate lane. */
function clearFor(p: CircuitPlan, o: OBox, m: number): boolean {
  const { W, D } = p;
  const dbg = (globalThis as { CIRCUIT_WHY?: string[] }).CIRCUIT_WHY;
  const no = (why: string) => { dbg?.push(`${why} @ ${o.x.toFixed(1)},${o.z.toFixed(1)}`); return false; };
  for (let a = -0.5; a <= 0.5 + 1e-6; a += 0.125) {
    for (let b = -0.5; b <= 0.5 + 1e-6; b += 0.25) {
      const q = fromOBox(o, a * o.len, b * o.dep);
      if (Math.abs(q.x) > W / 2 - 0.35 || Math.abs(q.z) > D / 2 - 0.35) return no(`edge ${q.x.toFixed(1)},${q.z.toFixed(1)}`);
      if (Math.abs(q.x - p.gateX) < 1.7 && q.z > p.gateZ - 1) return no("gate");
      const c = cellOf(p, q.x, q.z);
      if (c >= 0 && p.sAt[c] >= 0 && (p.zone[c] !== 0 || Math.abs(p.uAt[c]) < p.half + m + 0.5)) return no(`track zone ${p.zone[c]} u ${p.uAt[c].toFixed(2)}`);
      // stands in a run share their ends, and fan apart round a curve: only a real overlap counts
      for (const s of p.stands) if (inOBox(s, q.x, q.z, -0.25)) return no('overlap');
      for (const s of p.solids) if (inOBox(s, q.x, q.z, m)) return no('overlap');
    }
  }
  return true;
}

const cellOf = (p: CircuitPlan, x: number, z: number): number => {
  const gx = Math.floor((x + p.W / 2) * RES), gz = Math.floor((z + p.D / 2) * RES);
  return gx < 0 || gz < 0 || gx >= p.gw || gz >= p.gd ? -1 : gz * p.gw + gx;
};

/** Stand segments along the outside of the track wherever they fit: the main stand first, then the turns. */
function standsFor(p: CircuitPlan, pts: Pt[]): void {
  const { spec, half, len, design } = p;
  const wallW = spec.wall ? 0.5 : 0;
  // the gate's lane comes in across the outside of the front straight: runs there stop either side of it
  const g0 = p.gateS - 2.9, g1 = p.gateS + 2.9;
  const run = (s0: number, s1: number, side: 1 | -1, dep: number, h: number, seg: number, main: boolean, roof: boolean) => {
    if (side === 1 && s0 < g1 && s1 > g0) {
      if (g0 - s0 > 1.5) run(s0, g0, side, dep, h, seg, main, roof);
      if (s1 - g1 > 1.5) run(g1, s1, side, dep, h, seg, main, roof);
      return;
    }
    const pieces = Math.max(1, Math.round((s1 - s0) / seg));
    for (let k = 0; k < pieces; k++) {
      const s = s0 + ((s1 - s0) * k) / pieces, e = s0 + ((s1 - s0) * (k + 1)) / pieces;
      const off = half + wallW + spec.runoff;
      const a = offsetAt(p, s, side * off), b = offsetAt(p, e, side * off);
      const dx = b.x - a.x, dz = b.z - a.z, l = Math.hypot(dx, dz);
      if (l < 1.2) continue;
      // outward from the track: the chord's normal on this side
      const nx = side * (dz / l), nz = side * (-dx / l);
      const o: Stand = {
        x: (a.x + b.x) / 2 + nx * (dep / 2), z: (a.z + b.z) / 2 + nz * (dep / 2),
        a: yawFacing(-nx, -nz), len: l + 0.02, dep, h, rows: Math.max(3, Math.floor(dep / 0.34)), main, roof,
      };
      if (clearFor(p, o, 0.05)) p.stands.push(o);
    }
  };
  const straightEnd = (() => { let s = 0; for (let k = 0; k < p.n / 2; k++) { if (pts[k].t > 0.3 || p.corner[k] > 0.4) break; s = k * DS; } return s; })();
  const straightStart = (() => { let s = len; for (let k = p.n - 1; k > p.n / 2; k--) { if (pts[k].t > 0.3 || p.corner[k] > 0.4) break; s = k * DS; } return s - len; })();
  switch (design) {
    case 'speedway':
      run(straightStart, straightEnd, 1, 3.8, 1.9, 4.5, true, true);
      run(straightEnd, len + straightStart, 1, 2.4, 1.2, 3.2, false, false);
      break;
    case 'bullring':
      run(straightStart, straightEnd, 1, 3.8, 2.1, 4, true, true);
      run(straightEnd, len + straightStart, 1, 3.2, 1.9, 2.8, false, false);
      break;
    case 'heritage':
      run(straightStart, straightEnd, 1, 3, 1.3, 5, true, true);
      run(straightEnd + 3, len + straightStart - 3, 1, 2.2, 1.0, 4, false, false);
      break;
    case 'grandprix': {
      run(straightStart, straightEnd, 1, 3.4, 1.6, 5, true, true);
      // a stand on the outside of each of the slow corners
      const done: number[] = [];
      const order = Array.from({ length: p.n }, (_, i) => i).sort((a, b) => Math.abs(p.curv[b]) - Math.abs(p.curv[a]));
      for (const i of order) {
        if (Math.abs(p.curv[i]) < 0.14 || done.length >= 4) break;
        const s = i * DS;
        if (done.some((q) => Math.abs(q - s) < 16 && Math.abs(q - s) < len - 16)) continue;
        done.push(s);
        const side: 1 | -1 = p.curv[i] > 0 ? -1 : 1;
        const before = p.stands.length;
        run(s - 5, s + 5, side, 2.2, 1.0, 3, false, false);
        if (p.stands.length === before) done.pop();
      }
      break;
    }
  }
}

/** A grid of parking spaces on the infield grass, clear of everything. */
function parkingFor(p: CircuitPlan): void {
  const { W, D } = p;
  for (let z = -D / 2 + 2; z < D / 2 - 2; z += 0.9) {
    for (let x = -W / 2 + 2; x < W / 2 - 2; x += 0.62) {
      const c = cellOf(p, x, z);
      if (c < 0) continue;
      // inside the loop only: a cell the track's left (inward) side looks onto, well clear of it
      if (p.sAt[c] >= 0) continue;
      if (!insideLoop(p, x, z)) continue;
      const box: OBox = { x, z, a: Math.PI / 2, len: 0.4, dep: 0.8, h: 0.2 };
      if (!clearFor(p, box, 0.45)) continue;
      p.parking.push({ x, z, a: 0 });
    }
  }
}

/** Is a point inside the loop the track makes (an even-odd test on the centreline)? */
function insideLoop(p: CircuitPlan, x: number, z: number): boolean {
  let inside = false;
  for (let i = 0, j = p.n - 1; i < p.n; j = i++) {
    const zi = p.pz[i], zj = p.pz[j];
    if ((zi > z) !== (zj > z) && x < ((p.px[j] - p.px[i]) * (z - zi)) / (zj - zi) + p.px[i]) inside = !inside;
  }
  return inside;
}

/** A stand's rows of seats, front (low, nearest the track) to back, in the stand's own frame: centre z, the seat's height, and the row's depth. */
export function standRows(p: CircuitPlan, s: Stand): { z: number; y: number; d: number }[] {
  // a road circuit's stands have a wall of tyres along their foot
  const front = s.dep / 2 - (p.design === 'grandprix' ? 0.42 : 0.18), back = -s.dep / 2 + 0.22;
  const d = (front - back) / s.rows;
  return Array.from({ length: s.rows }, (_, r) => ({ z: front - d * (r + 0.5), y: 0.1 + ((r + 1) * s.h * 0.8) / s.rows, d }));
}

/** Where the spectators sit: model-frame points (y above the lot), every seat of every stand, in a fixed shuffled order. */
const SEATS = new Map<CircuitDesign, Float32Array>();
export function seatsOf(p: CircuitPlan): Float32Array {
  let out = SEATS.get(p.design);
  if (out) return out;
  const list: number[] = [];
  for (const s of p.stands) {
    for (const row of standRows(p, s)) {
      for (let x = -s.len / 2 + 0.14; x <= s.len / 2 - 0.14; x += 0.19) {
        const q = fromOBox(s, x, row.z);
        list.push(q.x, row.y, q.z);
      }
    }
  }
  // shuffled, so a filling stand fills all over rather than row by row
  const n = list.length / 3;
  let h = 2166136261;
  for (let i = n - 1; i > 0; i--) {
    h = Math.imul(h ^ i, 16777619) >>> 0;
    const j = h % (i + 1);
    for (let k = 0; k < 3; k++) { const t = list[i * 3 + k]; list[i * 3 + k] = list[j * 3 + k]; list[j * 3 + k] = t; }
  }
  out = new Float32Array(list);
  SEATS.set(p.design, out);
  return out;
}

// ---- asking the plan about a point ------------------------------------------------------------------

/** Bilinear lift of the track surface at a model-frame point. */
export function liftAt(p: CircuitPlan, x: number, z: number): number {
  const fx = (x + p.W / 2) * RES - 0.5, fz = (z + p.D / 2) * RES - 0.5;
  const gx = Math.floor(fx), gz = Math.floor(fz);
  if (gx < 0 || gz < 0 || gx >= p.gw - 1 || gz >= p.gd - 1) return 0;
  const kx = fx - gx, kz = fz - gz, c = gz * p.gw + gx;
  const a = p.lift[c], b = p.lift[c + 1], d = p.lift[c + p.gw], e = p.lift[c + p.gw + 1];
  return (a * (1 - kx) + b * kx) * (1 - kz) + (d * (1 - kx) + e * kx) * kz;
}

/** The zone of a model-frame point: 0 grass, 1 track, 2 apron / pit lane, 3 wall, 4 pit wall. */
export function zoneAt(p: CircuitPlan, x: number, z: number): number {
  const c = cellOf(p, x, z);
  return c < 0 ? 0 : p.zone[c];
}

/** Along the lap (tiles from the line) and across it (tiles right of the centreline) at a model-frame point, or null off the track's surroundings. */
export function lapAt(p: CircuitPlan, x: number, z: number): { s: number; u: number } | null {
  const c = cellOf(p, x, z);
  return c < 0 || p.sAt[c] < 0 ? null : { s: p.sAt[c], u: p.uAt[c] };
}

/** Is a model-frame point solid: a stand, the pit building, the wall? */
export function circuitSolid(p: CircuitPlan, x: number, z: number): boolean {
  const { W, D } = p;
  if (Math.abs(x) > W / 2 || Math.abs(z) > D / 2) return false;
  // the fence round the lot is an ordinary one a car can knock flat (circuitFenceEdges, world/fences.ts)
  const zn = zoneAt(p, x, z);
  if (zn === 3 || zn === 4) return true;
  for (const s of p.stands) if (inOBox(s, x, z)) return true;
  for (const s of p.solids) if (inOBox(s, x, z)) return true;
  return false;
}

// ---- the world frame ----------------------------------------------------------------------------

/** How a circuit's model frame sits in its island: origin, height and yaw, as townMesh places the model. */
export function frameOf(b: Building): { ox: number; oy: number; oz: number; c: number; s: number; yaw: number } {
  const yaw = Math.atan2(DIRS[b.facing][0], DIRS[b.facing][1]);
  return { ox: b.x + b.w / 2, oy: b.level * STEP, oz: b.z + b.d / 2, c: Math.cos(yaw), s: Math.sin(yaw), yaw };
}

/** Island tiles from a model-frame point. */
export function toIsland(f: ReturnType<typeof frameOf>, lx: number, lz: number): { x: number; z: number } {
  return { x: f.ox + lx * f.c + lz * f.s, z: f.oz - lx * f.s + lz * f.c };
}

/** A model-frame point from island tiles. */
export function toModel(f: ReturnType<typeof frameOf>, x: number, z: number): { x: number; z: number } {
  const dx = x - f.ox, dz = z - f.oz;
  return { x: dx * f.c - dz * f.s, z: dx * f.s + dz * f.c };
}

/** A model-frame heading to an island heading. */
const headingToIsland = (f: ReturnType<typeof frameOf>, h: number): number => h + f.yaw;

/** The circuits of an island. */
export function circuitsOf(w: World): Building[] {
  const out: Building[] = [];
  for (const g of w.works) for (const b of g.buildings) if (b.kind === 'raceCircuit' && !b.gone) out.push(b);
  return out;
}

/** The circuit whose lot covers island tile (tx, tz), if any: cached per island. */
const TILE_CIRCUIT = new WeakMap<World, { rev: number; at: Map<number, Building> }>();
function circuitOnTile(w: World, i: number): Building | null {
  let c = TILE_CIRCUIT.get(w);
  if (!c || c.rev !== w.revision) {
    c = { rev: w.revision, at: new Map() };
    for (const b of circuitsOf(w)) for (let z = b.z; z < b.z + b.d; z++) for (let x = b.x; x < b.x + b.w; x++) if (inB(x, z)) c.at.set(idx(x, z), b);
    TILE_CIRCUIT.set(w, c);
  }
  return c.at.get(i) ?? null;
}

/**
 * Per tile, the edges (bit d) where a circuit's lot meets the land round it: its perimeter fence, an
 * ordinary fence a car can knock flat (world/fences.ts), open at the gate and wherever a stand's back
 * makes the boundary. Cached per island.
 */
const FENCE_EDGES = new WeakMap<World, { rev: number; m: Uint8Array }>();
export function circuitFenceEdges(w: World): Uint8Array | null {
  if (!w.works.length) return null;
  let c = FENCE_EDGES.get(w);
  if (c && c.rev === w.revision) return c.m;
  const m = new Uint8Array(N * N);
  for (const b of circuitsOf(w)) {
    const p = planOf(b), f = frameOf(b);
    const inLot = (x: number, z: number) => x >= b.x && x < b.x + b.w && z >= b.z && z < b.z + b.d;
    for (let z = b.z; z < b.z + b.d; z++) for (let x = b.x; x < b.x + b.w; x++) {
      if (!inB(x, z)) continue;
      for (let d = 0; d < 4; d++) {
        const nx = x + DIRS[d][0], nz = z + DIRS[d][1];
        if (inLot(nx, nz) || !inB(nx, nz)) continue;
        const e = toModel(f, x + 0.5 + DIRS[d][0] * 0.5, z + 0.5 + DIRS[d][1] * 0.5);
        if (e.z > 0 && Math.abs(e.x - p.gateX) < 1.5) continue;
        if (p.stands.some((s) => inOBox(s, e.x, e.z, 0.25))) continue;
        m[idx(x, z)] |= 1 << d;
      }
    }
  }
  FENCE_EDGES.set(w, { rev: w.revision, m });
  return m;
}

/** The lift of a circuit's banked track under island point (x, z), world units; 0 anywhere else. */
export function circuitLift(w: World, x: number, z: number): number {
  if (!w.works.length) return 0;
  const tx = Math.floor(x), tz = Math.floor(z);
  if (!inB(tx, tz)) return 0;
  const b = circuitOnTile(w, idx(tx, tz));
  if (!b) return 0;
  const p = planOf(b);
  if (!p.outer) return 0;
  const m = toModel(frameOf(b), x, z);
  return liftAt(p, m.x, m.z);
}

/** Is island tile i part of a circuit's track (or pit lane): driven like a paved road? */
export function onCircuitTrack(w: World, i: number): boolean {
  if (!w.works.length) return false;
  const b = circuitOnTile(w, i);
  if (!b) return false;
  const x = i % N, z = (i - x) / N;
  const p = planOf(b), m = toModel(frameOf(b), x + 0.5, z + 0.5);
  const zn = zoneAt(p, m.x, m.z);
  return zn === 1 || zn === 2;
}

// ---- worldgen: finding the room for one ---------------------------------------------------------

/** One ordinary cell in this many gets a circuit, where there is room for one. */
export const CIRCUIT_CHANCE = 0.14;
export const CIRCUIT_SALT = 5807;
/** Tiles out from the gate that must be dry land, and the share of that lane that has to be. */
const GATE_REACH = 6, GATE_DRY = 0.85;

/**
 * Find the flat open ground a circuit needs, level it and claim it. Run before the farms spread over
 * the open country (as the international airport is), so the space is still there to be had.
 */
export function planCircuit(
  w: World, land: Uint8Array, E: Float32Array, river: Uint8Array, lakeLvl: Int8Array, rng: Rng, band: number, design: CircuitDesign,
): WorkSite | null {
  const spec = CIRCUIT_SPECS[design];
  const lo = band + 8;
  let best: { x: number; z: number; f: number; facing: number; lv: number; score: number; spread: number } | null = null;
  const diag = (globalThis as { CIRCUIT_DIAG?: object[] }).CIRCUIT_DIAG;
  const why: Record<string, number> = {};
  let minSpread = Infinity;
  const plan = circuitPlan(design);
  /** The tile one out from the gate, for a lot centred on (cx, cz) facing `facing`. */
  const gateTile = (cx: number, cz: number, facing: number): [number, number] => {
    const [fx, fz] = DIRS[facing];
    const yaw = Math.atan2(fx, fz), c = Math.cos(yaw), sn = Math.sin(yaw);
    const gl = { x: plan.gateX, z: spec.D / 2 + 1 };
    return [Math.floor(cx + gl.x * c + gl.z * sn), Math.floor(cz - gl.x * sn + gl.z * c)];
  };
  /** Dry ground out from a gate: a lane three wide, GATE_REACH long. A gate onto the sea or a lake gets no road. */
  const dryAhead = (cx: number, cz: number, facing: number): number => {
    const [gx, gz] = gateTile(cx, cz, facing), [fx, fz] = DIRS[facing];
    let dry = 0;
    for (let k = 0; k < GATE_REACH; k++) {
      for (let s = -1; s <= 1; s++) {
        const x = gx + fx * k + fz * s, z = gz + fz * k + fx * s;
        if (!inB(x, z)) continue;
        const i = idx(x, z);
        if (land[i] && lakeLvl[i] <= -128 && !river[i]) dry++;
      }
    }
    return dry / (GATE_REACH * 3);
  };
  /** Which way the lot faces: of its two ends, the one whose gate opens onto dry land, then toward the island's middle. */
  const faceOf = (x0: number, z0: number, wx: number, wz: number, f: number): { facing: number; dry: number } => {
    const cx = x0 + wx / 2, cz = z0 + wz / 2;
    const mid = f % 2 === 1 ? (N / 2 - cz > 0 ? 1 : 3) : (N / 2 - cx > 0 ? 0 : 2);
    const other = (mid + 2) % 4;
    const a = dryAhead(cx, cz, mid), b = dryAhead(cx, cz, other);
    return b > a + 0.2 ? { facing: other, dry: b } : { facing: mid, dry: a };
  };
  for (let t = 0; t < 1600; t++) {
    const f = Math.floor(rng() * 4);
    const [wx, wz] = f % 2 === 1 ? [spec.W, spec.D] : [spec.D, spec.W];
    const x0 = lo + Math.floor(rng() * Math.max(1, N - 2 * lo - wx)), z0 = lo + Math.floor(rng() * Math.max(1, N - 2 * lo - wz));
    const s = survey(w, land, E, river, lakeLvl, x0 - 2, z0 - 2, wx + 4, wz + 4, lo, diag ? why : undefined);
    if (s) minSpread = Math.min(minSpread, s.spread);
    if (!s || s.spread > 8 || s.min < SEA + 1.2) { if (s) why[s.spread > 8 ? 'spread' : 'low'] = (why[s.spread > 8 ? 'spread' : 'low'] ?? 0) + 1; continue; }
    // well away from the towns, but not so far it's an expedition
    const tn = townNear(w, x0 + wx / 2, z0 + wz / 2, 60);
    if (tn < 12) { why.town = (why.town ?? 0) + 1; continue; }
    // the gate faces the nearest town, so the road comes in at the front
    const score = s.spread * 1.5 + Math.min(40, tn - 12) * 0.04 + rng() * 0.6;
    if (best && score >= best.score) continue;
    // and it has to open onto land a road can come in over
    const face = faceOf(x0, z0, wx, wz, f);
    if (face.dry < GATE_DRY) { why.gate = (why.gate ?? 0) + 1; continue; }
    best = { x: x0, z: z0, f, facing: face.facing, lv: Math.round(s.mean), score, spread: s.spread };
  }
  diag?.push({ design, cell: [w.cx, w.cz], ok: !!best, minSpread, why });
  if (!best) return null;
  const [wx, wz] = best.f % 2 === 1 ? [spec.W, spec.D] : [spec.D, spec.W];
  // facing the island's middle, where the roads are, unless that end opens onto water (faceOf)
  const cx = best.x + wx / 2, cz = best.z + wz / 2;
  const facing = best.facing;
  // level it, easing the ground round it (further, the more there was to cut)
  const skirt = 6 + Math.round(best.spread);
  for (let z = best.z - skirt; z < best.z + wz + skirt; z++) {
    for (let x = best.x - skirt; x < best.x + wx + skirt; x++) {
      if (!inB(x, z)) continue;
      const i = idx(x, z);
      if (!land[i] || w.biome[i] === Biome.Town) continue;
      const out = Math.max(0, best.x - x, x - (best.x + wx - 1), best.z - z, z - (best.z + wz - 1));
      if (out === 0) E[i] = best.lv;
      else E[i] += (best.lv - E[i]) * (1 - out / (skirt + 1));
    }
  }
  // a stream it lands on is stopped at its fence, as one that runs into a town is
  for (let z = best.z - 1; z <= best.z + wz; z++) for (let x = best.x - 1; x <= best.x + wx; x++) if (inB(x, z)) river[idx(x, z)] = 0;
  for (let z = best.z; z < best.z + wz; z++) {
    for (let x = best.x; x < best.x + wx; x++) {
      const i = idx(x, z);
      w.biome[i] = Biome.Town;
      w.lot[i] = Lot.Lawn;
      w.cleared[i] = 1;
      // a landmark's ground: the road network goes round it, not across the track
      w.flags[i] |= Flag.Poi;
      river[i] = 0;
    }
  }
  const forms = spec.names;
  let name = forms[Math.floor(rng() * forms.length)];
  name = name.replace('{w}', w.name.split(' ')[0]);
  const W = spec.W, D = spec.D;
  // the gate: on the front edge, where the plan's entrance lane is, one tile out
  const [gx, gz] = gateTile(cx, cz, facing);
  return {
    kind: 'wonder', name, x: Math.floor(cx), z: Math.floor(cz), level: best.lv, facing, major: true,
    len: Math.max(W, D), half: Math.min(W, D) / 2, cable: [], gate: idx(Math.max(0, Math.min(N - 1, gx)), Math.max(0, Math.min(N - 1, gz))),
    lot: { kind: 'raceCircuit', x: best.x, z: best.z, w: wx, d: wz },
  };
}

function survey(w: World, land: Uint8Array, E: Float32Array, river: Uint8Array, lakeLvl: Int8Array, x0: number, z0: number, wx: number, wz: number, lo: number, why?: Record<string, number>) {
  let min = Infinity, max = -Infinity, sum = 0, wet = 0;
  const no = (k: string) => { if (why) why[k] = (why[k] ?? 0) + 1; return null; };
  for (let z = z0; z < z0 + wz; z++) {
    for (let x = x0; x < x0 + wx; x++) {
      if (x < lo || z < lo || x >= N - lo || z >= N - lo) return no('edge');
      const i = idx(x, z);
      if (!land[i]) return no('sea');
      if (river[i]) { wet++; if (wet > wx * wz * 0.06) return no('river'); }
      if (lakeLvl[i] > -128) return no('lake');
      if (w.biome[i] === Biome.Town) return no('townpad');
      if (w.feature[i]) return no('feature');
      if (w.flags[i] & Flag.Field) return no('field');
      if (w.flags[i] & Flag.Corridor) return no('corridor');
      const e = E[i];
      if (e < min) min = e;
      if (e > max) max = e;
      sum += e;
    }
  }
  return { mean: sum / (wx * wz), spread: max - min, min, max };
}

function townNear(w: World, x: number, z: number, r: number): number {
  let best = Infinity;
  for (const t of w.towns) best = Math.min(best, Math.max(0, Math.abs(x - (t.x0 + t.size / 2)) - t.size / 2, Math.abs(z - (t.z0 + t.size / 2)) - t.size / 2));
  if (best <= r) return best;
  const step = 3;
  for (let dz = -r; dz <= r; dz += step) {
    for (let dx = -r; dx <= r; dx += step) {
      const tx = Math.round(x + dx), tz = Math.round(z + dz);
      if (!inB(tx, tz) || w.biome[idx(tx, tz)] !== Biome.Town) continue;
      best = Math.min(best, Math.hypot(dx, dz));
    }
  }
  return best;
}

/** A race's name at a circuit, rolled from a number. */
export function raceName(b: Building, w: World, roll: number): string {
  const spec = planOf(b).spec;
  return spec.races[Math.abs(roll) % spec.races.length].replace('{w}', w.name.split(' ')[0]);
}
