import { N, SEA, Biome, Flag, RoadType, idx, inB } from '../../tiles';
import { grow, put, type TownPlan } from '../../towns';
import { LAYERS } from '../layers';
import { CARVERS, Dig, nearestSeaSide, seaRiver } from '../water';
import { avenue, dfCores, finishTown, ring, type Pt } from '../kit';
import { bridgesOver, discTiles, gridLines, lakeOn, riverAt, riverThrough } from './shared';
import { gridAround } from './grids';
import type { PlanCtx } from '../types';

/**
 * Water cities (docs/cityplans.html): the channel city generalised. Budapest's and Prague's river of bridges, a
 * harbour's old basins turned into a quarter of towers, Hong Kong's strait under its peak, Stockholm's islands,
 * Tenochtitlan's island in its lake, and Dubai's coast with its palm.
 */

/** Which way the river runs and where, as tile points: s along it, u across (u = its middle at s). */
function riverFrame(p: TownPlan) {
  const r = p.carved!.river!;
  return (s: number, du: number): Pt => {
    const at = riverAt(p, s)!;
    return r.axis === 0 ? [s + 0.5, at + du + 0.5] : [at + du + 0.5, s + 0.5];
  };
}

/** Which bank stands higher: +1 the bank at larger u, -1 the other. */
function highBank(p: TownPlan, ctx: { w: { elev: Float32Array } }): number {
  const r = p.carved!.river!, S = p.size, s0 = r.axis === 0 ? p.x0 : p.z0;
  let plus = 0, minus = 0;
  for (let s = s0 + 4; s < s0 + S - 4; s += 3) {
    const at = riverAt(p, s)!;
    for (let d = r.half + 4; d < S * 0.35; d += 3) {
      const a = r.axis === 0 ? idx(s, at + d) : idx(at + d, s), b = r.axis === 0 ? idx(s, at - d) : idx(at - d, s);
      if (a >= 0 && a < N * N) plus += ctx.w.elev[a];
      if (b >= 0 && b < N * N) minus += ctx.w.elev[b];
    }
  }
  return plus >= minus ? 1 : -1;
}

// ---------------------------------------------------------------------------------------------
// the river of bridges: Budapest, Prague

CARVERS.bridges = (p, ctx, rng) => {
  if (!riverThrough(p, ctx, rng, { half: 4, amp: p.size * 0.05, island: true, off: (rng() - 0.5) * 0.08 })) return false;
  (p.carved!.note ??= {}).high = highBank(p, ctx);
  return true;
};

LAYERS.bridges = (c, p) => {
  const r = p.carved?.river;
  if (!r) return false;
  const S = p.size, mega = p.kind === 'mega', s0 = r.axis === 0 ? p.x0 : p.z0;
  const F = riverFrame(p), hi = p.carved?.note?.high ?? 1;
  c.bridgeSpan = 12;
  // the bridges: five or six straight over the river, each its own design (bridgeDesigns picks by the crossing)
  bridgesOver(c, p, mega ? 0.15 : 0.19, 8, RoadType.FourLane);
  // the flat bank: half-rings of boulevard round the old centre and a radial avenue out of it
  const mid = s0 + Math.round(S * 0.5);
  const [ox, oz] = F(mid, -hi * (r.half + 2));
  for (const f of [0.22, 0.38]) {
    const R = Math.round(S * f), pts: Pt[] = [];
    for (let a = 0; a <= Math.PI + 0.01; a += Math.PI / 8) {
      const along = Math.cos(a) * R, out = Math.sin(a) * R;
      pts.push(c.clampPt(...(r.axis === 0 ? [ox + along, oz - hi * out] as Pt : [ox - hi * out, oz + along] as Pt)));
    }
    c.ends(c.street(RoadType.TwoLane, pts));
  }
  const ad: Pt = r.axis === 0 ? [1, -hi] : [-hi, 1];
  const len = Math.round(S * 0.3);
  const rad = avenue(c, RoadType.TwoLane, [ox + ad[0] * 3, oz + ad[1] * 3], c.clampPt(ox + ad[0] * len, oz + ad[1] * len), { four: true, main: true });
  // a quay road along both banks
  for (const side of [-1, 1]) c.ends(c.street(RoadType.TwoLane, [F(s0 + 1, side * (r.half + 2)), F(s0 + Math.round(S / 2), side * (r.half + 2)), F(s0 + S - 2, side * (r.half + 2))]));
  // the castle hill: the highest ground on the high bank, lanes winding up to it
  let best: Pt = F(mid, hi * (r.half + 10)), bestH = -Infinity;
  for (let s = s0 + 6; s < s0 + S - 6; s += 2) for (let d = r.half + 6; d < S * 0.4; d += 2) {
    const [x, z] = F(s, hi * d);
    if (!inB(Math.floor(x), Math.floor(z))) continue;
    const e = c.w.elev[idx(Math.floor(x), Math.floor(z))];
    if (e > bestH && c.inTown(Math.floor(x), Math.floor(z))) { bestH = e; best = [x, z]; }
  }
  c.street(RoadType.TwoLane, [F(mid, hi * (r.half + 2)), between(F(mid, hi * (r.half + 2)), best, 0.5), best]);
  // the roles: the castle on the hill, the parliament on the flat bank's waterfront, the basilica on the ring
  c.anchors.palace = best;
  c.anchors.temple = [ox + ad[0] * S * 0.2, oz + ad[1] * S * 0.2];
  c.anchors.seat = F(mid + 6, -hi * (r.half + 4));
  put(c, 'parliament', { near: F(mid - 6, -hi * (r.half + 4)), maxDist: 6, waterside: 'prefer' });
  put(c, 'thermalBath', { near: F(s0 + Math.round(S * 0.3), hi * (r.half + 4)), maxDist: 8 });
  c.anchors.landmark = [ox + ad[0] * S * 0.32, oz + ad[1] * S * 0.32];
  // mid-rise along the river, towers away from it
  c.dfAt = (x, z) => {
    const d = Math.abs((r.axis === 0 ? z : x) - riverAt(p, r.axis === 0 ? x : z)!);
    return d < S * 0.15 ? 0.5 : Math.max(0, 0.5 - (d - S * 0.15) / (S * 0.5));
  };
  finishTown(c, { grow: mega ? 40 : 24, axis: rad });
  return true;
};

const DEBUG = !!(globalThis as { process?: { env: Record<string, string | undefined> } }).process?.env?.PLAN_DEBUG;

const between = (a: Pt, b: Pt, f: number): Pt => [a[0] + (b[0] - a[0]) * f, a[1] + (b[1] - a[1]) * f];

// ---------------------------------------------------------------------------------------------
// harbour regeneration: Düsseldorf's MedienHafen, Hamburg's HafenCity, the Docklands

CARVERS.harbour = (p, ctx, rng) => {
  if (!riverThrough(p, ctx, rng, { half: 3, amp: p.size * 0.04 })) return false;
  // the old basins: a comb of them off one bank, each three wide and a quarter of the town long
  const r = p.carved!.river!, S = p.size, s0 = r.axis === 0 ? p.x0 : p.z0;
  const side = rng() < 0.5 ? 1 : -1, dig = new Dig(p, ctx);
  const first = s0 + Math.round(S * 0.52), n = p.kind === 'mega' ? 4 : 3, L = Math.round(S * 0.24);
  for (let k = 0; k < n; k++) {
    const s = first + k * 8;
    if (s + 3 >= s0 + S - 3) break;
    const at = riverAt(p, s)!;
    for (let u = r.half; u <= r.half + L; u++) for (let o = 0; o < 3; o++) {
      const [x, z] = r.axis === 0 ? [s + o, at + side * u] : [at + side * u, s + o];
      dig.mark(x, z, 2);
    }
  }
  if (!dig.clear()) return true;
  dig.commit();
  (p.carved!.note ??= {}).side = side;
  (p.carved!.note!).first = first;
  (p.carved!.note!).n = n;
  (p.carved!.note!).L = L;
  return true;
};

LAYERS.harbour = (c, p) => {
  const r = p.carved?.river;
  if (!r) return false;
  const S = p.size, mega = p.kind === 'mega', s0 = r.axis === 0 ? p.x0 : p.z0;
  const F = riverFrame(p), note = p.carved?.note ?? {};
  const side = note.side ?? 1, first = note.first ?? s0 + S / 2, n = note.n ?? 0, L = note.L ?? 0;
  c.bridgeSpan = 9;
  // three bridges over the river, cable-stayed
  bridgesOver(c, p, 0.3, 7, RoadType.FourLane);
  // the promenade along the harbour bank, the piers between the basins as dead-end avenues off it
  const prom = c.street(RoadType.TwoLane, [F(s0 + 1, side * (r.half + 1)), F(s0 + Math.round(S / 2), side * (r.half + 1)), F(s0 + S - 2, side * (r.half + 1))]);
  c.ends(prom);
  for (let k = 0; k < n - 1; k++) {
    const s = first + k * 8 + 5;
    avenue(c, RoadType.TwoLane, F(s, side * (r.half + 1)), F(s, side * (r.half + L)), { main: false });
    // cranes kept along the pier, landmark towers on it
    for (let q = 6; q < L - 2; q += 6) c.place({ kind: 'crane', w: 1, d: 1, near: F(s + 1, side * (r.half + q)), maxDist: 2, frontage: false, solid: false });
  }
  const pier = first + 5;
  // the old town across the river: brick lanes
  const keep = c.t.surface;
  c.t.surface = 'brick';
  c.street(RoadType.TwoLane, [F(s0 + 1, -side * (r.half + 2)), F(s0 + Math.round(S / 2), -side * (r.half + 2)), F(s0 + S - 2, -side * (r.half + 2))]);
  grow(c, c.t.roads + (mega ? 18 : 10), RoadType.Brick);
  c.t.surface = keep;
  // the roles: the TV tower by the water, the towers on the piers, the hall in the old town
  put(c, 'commsTower', { near: F(first - 6, side * (r.half + 3)), maxDist: 4, zone: 'any' });
  c.anchors.landmark = F(pier, side * (r.half + L * 0.5));
  c.anchors.seat = F(s0 + Math.round(S * 0.35), -side * (r.half + 6));
  c.anchors.museum = F(pier + 8, side * (r.half + L * 0.4));
  c.anchors.temple = F(s0 + Math.round(S * 0.25), -side * (r.half + 10));
  c.dfAt = dfCores(c, [F(pier + 4, side * (r.half + L * 0.5))], S * 0.5);
  finishTown(c, { grow: mega ? 22 : 12, axis: prom });
  return true;
};

// ---------------------------------------------------------------------------------------------
// the vertical harbour: Hong Kong

CARVERS.vertical = (p, ctx, rng) => {
  // the strait: a wide sea cut straight across the town, out to the sea at both ends where it can be
  const dig = new Dig(p, ctx), S = p.size;
  const axis: 0 | 1 = rng() < 0.5 ? 0 : 1;
  const at = (axis === 0 ? p.z0 : p.x0) + Math.round(S * 0.42);
  const line = seaRiver(dig, rng, { axis, at, half: 5, amp: S * 0.02 });
  if (!line || !dig.clear()) return false;
  dig.commit();
  (p.carved ??= {}).river = { axis, line, half: 5 };
  return true;
};

LAYERS.vertical = (c, p) => {
  const r = p.carved?.river;
  if (!r) return false;
  const S = p.size, x0 = p.x0, z0 = p.z0, s0 = r.axis === 0 ? x0 : z0, F = riverFrame(p);
  c.bridgeSpan = 14;
  // which side is the island (the higher)
  let a = 0, b = 0;
  for (let s = s0 + 4; s < s0 + S - 4; s += 4) for (let d = r.half + 4; d < S * 0.4; d += 4) {
    const [ax, az] = F(s, d), [bx, bz] = F(s, -d);
    if (inB(Math.floor(ax), Math.floor(az))) a += c.w.elev[idx(Math.floor(ax), Math.floor(az))];
    if (inB(Math.floor(bx), Math.floor(bz))) b += c.w.elev[idx(Math.floor(bx), Math.floor(bz))];
  }
  const isle = a >= b ? 1 : -1;
  // Kowloon: a dense grid over the flat side
  const g = 4;
  const xs = gridLines(x0, x0 + S, g), zs = gridLines(z0, z0 + S, g);
  const flatHole: [number, number, number, number] = r.axis === 0
    ? (isle > 0 ? [x0, Math.min(...r.line) - 1, x0 + S, z0 + S] : [x0, z0, x0 + S, Math.max(...r.line) + 2])
    : (isle > 0 ? [Math.min(...r.line) - 1, z0, x0 + S, z0 + S] : [x0, z0, Math.max(...r.line) + 2, z0 + S]);
  gridAround(c, xs, zs, [flatHole]);
  // the island: one shore road with the towers along it, streets up the slope as far as they will climb
  const shore = c.street(RoadType.FourLane, [F(s0 + 1, isle * (r.half + 3)), F(s0 + Math.round(S / 2), isle * (r.half + 3)), F(s0 + S - 2, isle * (r.half + 3))]);
  c.ends(shore);
  for (let s = s0 + 6; s < s0 + S - 6; s += 9) c.street(RoadType.TwoLane, [F(s, isle * (r.half + 3)), F(s + 3, isle * (r.half + 12)), F(s - 1, isle * (r.half + 20))]);
  // the crossing: a long bridge over the strait (where the tunnel would be)
  bridgesOver(c, p, 0.5, 6, RoadType.FourLane);
  // the peak: the lookout on the summit
  put(c, 'observationTower', { highest: true, zone: 'any' });
  c.anchors.landmark = F(s0 + Math.round(S * 0.5), isle * (r.half + 4));
  c.anchors.seat = F(s0 + Math.round(S * 0.4), isle * (r.half + 5));
  c.anchors.museum = F(s0 + Math.round(S * 0.6), -isle * (r.half + 4));
  // towers on every lot near the water
  c.dfAt = (x, z) => Math.min(1, Math.abs((r.axis === 0 ? z : x) - riverAt(p, r.axis === 0 ? x : z)!) / (S * 0.32));
  finishTown(c, { grow: 20, axis: shore });
  return true;
};

// ---------------------------------------------------------------------------------------------
// the archipelago: Stockholm

CARVERS.archipelago = (p, ctx, rng) => {
  const dig = new Dig(p, ctx), S = p.size;
  // channels across the town both ways, wandering, and a ring of water round the old town's islet
  let any = false;
  for (const [axis, f] of [[0, 0.32], [0, 0.68], [1, 0.4], [1, 0.74]] as [0 | 1, number][]) {
    const d2 = new Dig(p, ctx);
    const line = seaRiver(d2, rng, { axis, at: (axis === 0 ? p.z0 : p.x0) + Math.round(S * f), half: 2, amp: S * 0.05, end: 0.95 });
    if (!line) continue;
    any = true;
    for (const [i, d] of d2.want) dig.want.set(i, Math.max(dig.want.get(i) ?? 0, d));
  }
  if (!any) return false;
  const cx = p.x0 + Math.round(S * 0.4), cz = p.z0 + Math.round(S * 0.32);
  for (let z = cz - 10; z <= cz + 10; z++) for (let x = cx - 10; x <= cx + 10; x++) {
    const d = Math.hypot(x + 0.5 - cx, z + 0.5 - cz);
    if (d >= 6 && d < 8.5) dig.mark(x, z, 2);
  }
  if (!dig.clear()) return false;
  dig.commit();
  (p.carved ??= {}).pts = { old: [cx, cz] };
  return true;
};

LAYERS.archipelago = (c, p) => {
  const S = p.size, x0 = p.x0, z0 = p.z0, mega = p.kind === 'mega';
  const [ox, oz] = p.carved?.pts?.old ?? [x0 + S * 0.4, z0 + S * 0.32];
  c.bridgeSpan = 8;
  // every island its own grid, the streets hopping the channels on short bridges
  const g = mega ? 7 : 6;
  gridAround(c, gridLines(x0, x0 + S, g), gridLines(z0, z0 + S, g), [[ox - 9, oz - 9, ox + 10, oz + 10]], RoadType.TwoLane, { bridge: true });
  // the old town's islet: brick lanes inside a street round its shore, bridged to the islands round it
  const keep = c.t.surface;
  c.t.surface = 'brick';
  ring(c, RoadType.TwoLane, ox, oz, 4, 2, { main: false });
  for (const [dx, dz] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) avenue(c, RoadType.TwoLane, [ox + dx * 4 + 0.5, oz + dz * 4 + 0.5], [ox + dx * 11 + 0.5, oz + dz * 11 + 0.5], { bridge: true, main: false });
  c.t.surface = keep;
  // the roles: palace and cathedral on the old town's islet, the hall on a waterfront, a museum island
  c.anchors.palace = [ox + 2, oz - 1];
  c.anchors.temple = [ox - 2, oz + 1];
  c.anchors.seat = [ox + S * 0.25, oz + S * 0.2];
  c.anchors.museum = [x0 + S * 0.75, z0 + S * 0.75];
  c.dfAt = dfCores(c, [[x0 + S * 0.6, z0 + S * 0.55]], S * 0.55);
  c.capAt = (x, z) => (Math.hypot(x - ox, z - oz) < 9 ? 5 : 0);
  finishTown(c, { grow: mega ? 20 : 12 });
  return true;
};

// ---------------------------------------------------------------------------------------------
// the causeway lake: Tenochtitlan

CARVERS.causeway = (p, ctx) => {
  const S = p.size, cx = p.x0 + S / 2, cz = p.z0 + S / 2;
  const R = S * 0.47, r = S * 0.27;
  const tiles = discTiles(p, [[cx, cz, R]], 2);
  // the island left standing, cut through by chinampa canals every fifth tile (joined to the lake at both ends)
  for (const i of [...tiles]) {
    const x = i % N, z = (i - x) / N, d = Math.hypot(x + 0.5 - cx, z + 0.5 - cz);
    if (d < r) {
      const inPrecinct = Math.abs(x + 0.5 - cx) < 6 && Math.abs(z + 0.5 - cz) < 6;
      const canal = (x - Math.round(cx)) % 5 === 0 && !inPrecinct && d < r - 2 ? true : false;
      if (!canal) tiles.delete(i);
    }
  }
  (p.carved ??= {}).pts = { isle: [cx, cz] };
  (p.carved.note ??= {}).r = r;
  return lakeOn(p, ctx, tiles);
};

LAYERS.causeway = (c, p) => {
  const S = p.size, mega = p.kind === 'mega';
  const [cx, cz] = p.carved?.pts?.isle ?? [p.x0 + S / 2, p.z0 + S / 2];
  const r = p.carved?.note?.r ?? S * 0.27;
  c.bridgeSpan = 30;
  // the three causeways, north, west and south, out over the lake on their decks to the shore
  const axis: number[] = [];
  for (const [dx, dz] of [[0, -1], [-1, 0], [0, 1]]) {
    const n = avenue(c, RoadType.FourLane, [Math.round(cx + dx * 4), Math.round(cz + dz * 4)], [Math.round(cx + dx * (S / 2 - 1)), Math.round(cz + dz * (S / 2 - 1))], { main: true, bridge: true });
    c.ends(n);
    axis.push(...n);
  }
  // the chinampas: streets between the canals, across the island
  for (let z = Math.round(cz - r) + 2; z < cz + r - 1; z += 3) {
    const half = Math.sqrt(Math.max(0, r * r - (z + 0.5 - cz) ** 2)) - 2;
    if (half < 4) continue;
    avenue(c, RoadType.Paved, [cx - half, z + 0.5], [cx + half, z + 0.5], { main: false, bridge: true, route: false });
  }
  ring(c, RoadType.TwoLane, cx, cz, Math.round(r) - 1, Math.round(r * 0.4), { main: false, bridge: true });
  // the sacred precinct: the pyramid, the palace beside it, the market at the north causeway's head
  put(c, 'stepPyramid', { near: [cx + 0.5, cz + 0.5], maxDist: 3 }) ?? put(c, 'temple', { near: [cx + 0.5, cz + 0.5], maxDist: 3 });
  c.anchors.seat = [cx + 7, cz + 0.5];
  c.anchors.market = [cx + 0.5, cz - 8];
  put(c, 'aqueduct', { near: [p.x0 + S * 0.12, cz - S * 0.2], maxDist: 8, zone: 'any' });
  c.dfAt = dfCores(c, [[cx, cz]], r * 1.6);
  c.maxFloors = 5;
  finishTown(c, { grow: mega ? 8 : 4, axis });
  return true;
};

// ---------------------------------------------------------------------------------------------
// fronds: Dubai's coast and its palm

CARVERS.fronds = (p, ctx: PlanCtx, rng) => {
  const dig = new Dig(p, ctx), S = p.size, { w, land } = ctx;
  const side = nearestSeaSide(dig, 30);
  if (DEBUG) console.log(`fronds: sea side ${side}`);
  if (side < 0) return false;
  // the frame: s along the coast, u out to sea from the square's sea-side edge (u < 0 inland)
  const F = (s: number, u: number): [number, number] => {
    switch (side) {
      case 0: return [p.x0 + S - 1 + u, p.z0 + s];
      case 1: return [p.x0 + s, p.z0 + S - 1 + u];
      case 2: return [p.x0 - u, p.z0 + s];
      default: return [p.x0 + s, p.z0 - u];
    }
  };
  /** The palm's tiles off the shore at s (d out from the square's edge), or null where it runs into something. */
  function palmAt(ps: number, d0: number): number[] | null {
    const palm = new Set<number>();
    const add = (s: number, u: number) => { const [x, z] = F(s, u); if (inB(x, z)) palm.add(idx(x, z)); };
    // (the trunk runs on out to the crescent's middle, so the crescent is reached by road)
    for (let u = 1; u <= d0 + reach + 1; u++) for (let o = -1; o <= 1; o++) add(ps + o, u);
    for (let u = 8; u <= reach - 10; u += 4) {
      const len = 9 - Math.abs(u - (reach - 8) / 2) * 0.3;
      for (let o = 2; o <= len; o++) { add(ps + o, d0 + u); add(ps - o, d0 + u); add(ps + o, d0 + u + 1); add(ps - o, d0 + u + 1); }
    }
    for (let a = 0; a <= Math.PI; a += 0.02) {
      const s = ps + Math.cos(a) * 14, u = d0 + reach - 14 + Math.sin(a) * 14;
      add(Math.round(s), Math.round(u)); add(Math.round(s), Math.round(u) + 1);
    }
    // the sea is raised into land; the shore it crosses on the way out is taken in as it is
    const out: number[] = [];
    let sea = 0;
    for (const i of palm) {
      const x = i % N, z = (i - x) / N;
      if (x >= p.x0 && z >= p.z0 && x < p.x0 + S && z < p.z0 + S) continue;
      const why = x < ctx.band + 2 || z < ctx.band + 2 || x >= N - ctx.band - 2 || z >= N - ctx.band - 2 ? 'the seam band' : ctx.causeway?.[i] ? 'a causeway' : w.biome[i] === Biome.Town ? 'another town' : '';
      if (why) { if (DEBUG) console.log(`fronds: palm runs into ${why} at ${x},${z} (shore ${d0} out)`); return null; }
      out.push(i);
      if (!land[i]) sea++;
    }
    if (DEBUG) console.log(`fronds: side ${side}, shore ${d0} out, palm ${palm.size} tiles, ${sea} of them sea`);
    return sea >= 60 ? out : null;
  }
  // the palm, off the stretch of the town's shore the sea comes nearest: a trunk out from the beach, fronds either
  // side of it, the crescent round its head
  const seaAt = (s: number): number => {
    for (let u = 1; u <= 40; u++) { const [x, z] = F(s, u); if (!inB(x, z)) return Infinity; const i = idx(x, z); if (!land[i] && w.elev[i] < SEA) return u; }
    return Infinity;
  };
  const cands: [number, number][] = [];
  for (let s = Math.round(S * 0.18); s <= Math.round(S * 0.82); s += 3) { const d = seaAt(s); if (Number.isFinite(d)) cands.push([s, d + rng() * 0.5]); }
  cands.sort((q, r) => q[1] - r[1]);
  const reach = 34;
  let ps = 0, d0 = 0, arms: number[] = [];
  for (const [s0, dd] of cands.slice(0, 8)) {
    const got = palmAt(s0, Math.floor(dd));
    if (got) { ps = s0; d0 = Math.floor(dd); arms = got; break; }
  }
  if (!arms.length) return false;
  const armBiome = new Uint8Array(N * N), raised: number[] = [];
  for (const i of arms) {
    armBiome[i] = land[i] ? w.biome[i] : Biome.Beach;
    w.biome[i] = Biome.Town;
    w.flags[i] &= ~Flag.Corridor;
    // (raised land stands in the sea behind a sea wall: walled, so the corners pass leaves its edge sheer)
    if (!land[i]) { land[i] = 1; w.elev[i] = SEA + 2; raised.push(i); w.flags[i] |= Flag.Corridor; }
    ctx.river[i] = 0;
  }
  // the trunk eased down from the town to the beach so a road can run out along it (the shore is often a bank)
  const top = p.level;
  for (let u = 1; u <= d0 + 2; u++) for (let o = -2; o <= 2; o++) {
    const [x, z] = F(ps + o, u);
    if (!inB(x, z)) continue;
    const i = idx(x, z);
    if (!land[i]) continue;
    const t = Math.min(1, u / Math.max(1, d0));
    w.elev[i] = top + (SEA + 2 - top) * t;
  }
  // the creek: an inlet cut in from the sea a quarter of the way along
  const cs = Math.round(S * 0.82);
  for (let u = 0; u >= -Math.round(S * 0.35); u--) for (let o = -1; o <= 1; o++) { const [x, z] = F(cs + o + Math.round(Math.sin(u * 0.2) * 2), u); dig.mark(x, z, 2); }
  const [mx, mz] = F(cs, 0);
  if (dig.toSea(mx, mz, side, 1) && dig.clear()) dig.commit();
  const c = (p.carved ??= {});
  c.arms = arms;
  c.armBiome = armBiome;
  c.reclaimed = true;
  c.raised = raised;
  c.seaSide = side;
  c.note = { ps, reach, cs, d0 };
  return true;
};

LAYERS.fronds = (c, p) => {
  const S = p.size, side = p.carved?.seaSide, note = p.carved?.note;
  if (side === undefined || !note) return false;
  const F = (s: number, u: number): Pt => {
    switch (side) {
      case 0: return [p.x0 + S - 1 + u + 0.5, p.z0 + s + 0.5];
      case 1: return [p.x0 + s + 0.5, p.z0 + S - 1 + u + 0.5];
      case 2: return [p.x0 - u + 0.5, p.z0 + s + 0.5];
      default: return [p.x0 + s + 0.5, p.z0 - u + 0.5];
    }
  };
  const { ps, reach, cs } = note, d0 = note.d0 ?? 0;
  c.bridgeSpan = 6;
  // the coast highway: four lanes the length of the town a little in from the shore, towers either side of it
  const hwU = -Math.round(S * 0.22);
  const hw = avenue(c, RoadType.FourLane, F(1, hwU), F(S - 2, hwU), { main: true, bridge: true });
  c.ends(hw);
  for (const du of [-5, 5]) avenue(c, RoadType.TwoLane, F(1, hwU + du), F(S - 2, hwU + du), { main: false, bridge: true });
  // the beach road, and streets down to it
  avenue(c, RoadType.TwoLane, F(1, -2), F(S - 2, -2), { main: false, bridge: true });
  for (let s = 4; s < S - 3; s += 8) avenue(c, RoadType.TwoLane, F(s, -(S - 2)), F(s, -2), { main: false, bridge: true, route: false });
  // and inland, behind the towers, the villas' streets out into the desert
  for (let u = hwU - 13; u > -(S - 3); u -= 9) avenue(c, RoadType.Paved, F(1, u), F(S - 2, u), { main: false, route: false });
  // the palm: its trunk road out from the beach road, a cul-de-sac down every frond, the crescent's road
  avenue(c, RoadType.TwoLane, F(ps, -2), F(ps, d0 + reach), { main: true });
  for (let u = 8; u <= reach - 10; u += 4) {
    const len = Math.floor(9 - Math.abs(u - (reach - 8) / 2) * 0.3);
    avenue(c, RoadType.Paved, F(ps - len, d0 + u), F(ps + len, d0 + u), { main: false });
  }
  const cres: Pt[] = [];
  for (let a = 0.15; a <= Math.PI - 0.15; a += Math.PI / 10) cres.push(F(Math.round(ps + Math.cos(a) * 14), Math.round(d0 + reach - 14 + Math.sin(a) * 14)));
  c.street(RoadType.Paved, cres);
  // the roles: the supertall on the highway, the sail hotel at the crescent's tip, the souk on the creek
  c.anchors.landmark = F(Math.round(S * 0.45), hwU - 3);
  c.anchors.seat = F(Math.round(S * 0.6), hwU + 3);
  c.anchors.market = F(cs - 4, -Math.round(S * 0.15));
  put(c, 'hotel', { near: F(ps + 14, d0 + reach - 14), maxDist: 6, floors: 30 });
  // towers along the highway, villas on the palm, desert behind
  const along = (x: number, z: number) => (side % 2 === 0 ? Math.abs(x - F(0, hwU)[0]) : Math.abs(z - F(0, hwU)[1]));
  c.dfAt = (x, z) => Math.min(1, along(x, z) / (S * 0.25));
  finishTown(c, { grow: 10, axis: hw });
  return true;
};

