import { N, SEA, Biome, DIRS, Feature, Flag, idx, inB, type BuildingKind, type World } from './tiles';
import type { Rng } from './rng';
import type { WorkSite } from './industry';

/**
 * Mines (0.7.0, NEXT_WORLD): bigger and rarer than the quarries, a county now and then gets one of four, on the
 * ground it needs, each a work of kind 'mine' with its plant on an apron and its rigs at work (render/quarryRigs.ts):
 *
 *   openPit    a deep, wide pit of benches in open hill country, a haul road spiralling down it; the processing
 *              plant, a tailings pond and a crawler crane on the apron
 *   cutFace    a cliff of benches cut into the side of a great range (or the high country's mountains), a derrick crane over the face and the
 *              crusher on the floor in front of it
 *   gravelPit  a shallow pit on the flat beside a river, its screening plant on the apron and a dredge out on the
 *              water
 *   stripMine  long cuts across open plains with ridges of spoil between them, a walking dragline at the working
 *              cut and the coal tipple at the end
 *
 * Planned while the elevation field is floats, like the quarries (world/industry.ts growWorks), on a generator
 * of the county's own; the lots are claimed by reserveWorks and built by buildWorks from `site.lots`.
 */

export type MineKind = 'openPit' | 'cutFace' | 'gravelPit' | 'stripMine';
/** Out of every hundred counties, how many look for ground for a mine. */
export const MINE_CHANCE = 0.3;
const MINE_SALT = 0x6d696e65;

/** A lot a mine's buildings stand on: kind, place and size, which way it looks, floors, solid or not, level. */
export interface MineLot { kind: BuildingKind; x: number; z: number; w: number; d: number; facing: number; floors: number; solid: boolean; level: number }

const NAMES = ['Copperhead', 'Redrock', 'Blackwater', 'Ironbridge', 'Greystone', 'Coldwell', 'Ravenscar', 'Highmoor', 'Saltash', 'Kestrel'];
const TITLE: Record<MineKind, string> = { openPit: 'Open Pit Mine', cutFace: 'Cut', gravelPit: 'Gravel Pit', stripMine: 'Strip Mine' };

type Keep = (x: number, z: number, extra: number) => boolean;
interface Ctx { w: World; land: Uint8Array; E: Float32Array; river: Uint8Array; rng: Rng; made: WorkSite[]; keep: Keep }

/** Tests only: a kind tried first whatever the order (scripts), and why the last tries failed. */
export const MINE_TEST: { kind: MineKind | null } = { kind: null };
const MINE_WHY: string[] = [];
const why = (s: string) => { MINE_WHY.push(s); if (MINE_WHY.length > 100) MINE_WHY.shift(); };

/** One mine for this county, of whichever kind its ground suits (tried in a random order), or null. */
export function planMine(w: World, land: Uint8Array, E: Float32Array, river: Uint8Array, rng: Rng, made: WorkSite[], keep: Keep): WorkSite | null {
  const c: Ctx = { w, land, E, river, rng, made, keep };
  // the two that need rarer ground first, in either order; then the strip mine and the gravel pit
  const kinds: MineKind[] = rng() < 0.5 ? ['openPit', 'cutFace'] : ['cutFace', 'openPit'];
  kinds.push(...(rng() < 0.5 ? ['stripMine', 'gravelPit'] as const : ['gravelPit', 'stripMine'] as const));
  if (MINE_TEST.kind) kinds.splice(0, kinds.length, MINE_TEST.kind);
  for (const kind of kinds) {
    const s = kind === 'openPit' ? openPit(c) : kind === 'cutFace' ? cutFace(c) : kind === 'gravelPit' ? gravelPit(c) : stripMine(c);
    if (s) return s;
  }
  return null;
}

// ---------------------------------------------------------------------------------------------

/** Water to come: a river or stream (a great river's included) or a lake dug already (its water is laid at the end). */
const wet = (c: Ctx, i: number) => !!c.river[i] || !!(c.w.flags[i] & (Flag.River | Flag.Stream)) || c.w.biome[i] === Biome.Ocean;
// (farmland may be dug up: the fields are laid out again round the workings afterwards, world/biomes.ts reshapeFields)
const free = (c: Ctx, i: number) => !!c.land[i] && !wet(c, i) && c.w.biome[i] !== Biome.Town && c.w.feature[i] === Feature.None;
const away = (c: Ctx, x: number, z: number) => !c.made.some((q) => Math.hypot(q.x - x, q.z - z) < 50) && townNear(c, x, z, 60);

/** Level a rectangle to `lv`, its skirt eased into the ground round it (as industry.ts levelRect). */
function level(c: Ctx, x0: number, z0: number, wx: number, wz: number, lv: number, skirt = 3): void {
  for (let z = z0 - skirt; z < z0 + wz + skirt; z++) for (let x = x0 - skirt; x < x0 + wx + skirt; x++) {
    if (!inB(x, z)) continue;
    const i = idx(x, z);
    if (!c.land[i] || c.w.biome[i] === Biome.Town) continue;
    const out = Math.max(0, x0 - x, x - (x0 + wx - 1), z0 - z, z - (z0 + wz - 1));
    c.E[i] = out === 0 ? lv : c.E[i] + (lv - c.E[i]) * (1 - out / (skirt + 1));
  }
}
/** Mark ground as the mine's working: nothing grows or is built on it. */
function work(c: Ctx, i: number): void { c.w.feature[i] = Feature.Quarry; c.w.cleared[i] = 1; c.w.flags[i] &= ~Flag.Field; }

/**
 * The ground within r of (x, z): free for a mine (all of it, or all but a `slack` share, which the digging leaves
 * alone), and the spread of its height. Null where it isn't.
 */
function survey(c: Ctx, x: number, z: number, r: number, slack = 0): { lo: number; hi: number } | null {
  let lo = Infinity, hi = -Infinity, n = 0, bad = 0;
  for (let dz = -r; dz <= r; dz++) for (let dx = -r; dx <= r; dx++) {
    if (Math.hypot(dx, dz) > r) continue;
    if (!inB(x + dx, z + dz)) return null;
    const i = idx(x + dx, z + dz);
    n++;
    // never a river or a town in the workings, whatever the slack
    if (wet(c, i) || c.w.biome[i] === Biome.Town) return null;
    if (!free(c, i)) { bad++; continue; }
    lo = Math.min(lo, c.E[i]); hi = Math.max(hi, c.E[i]);
  }
  return bad <= n * slack ? { lo, hi } : null;
}
/** Is there a river within `r` tiles of any tile of this rectangle (water would spread into a working beside it)? */
function riverNear(c: Ctx, x0: number, z0: number, wx: number, wz: number, r: number): boolean {
  for (let z = z0 - r; z < z0 + wz + r; z++) for (let x = x0 - r; x < x0 + wx + r; x++) if (inB(x, z) && wet(c, idx(x, z))) return true;
  return false;
}

/**
 * The apron beside a pit: a level pad of `pad` tiles each way centred `out` tiles from the pit's centre in direction
 * d, all free ground, levelled to `lv`. Returns its centre or null.
 */
function apron(c: Ctx, x: number, z: number, d: number, out: number, pad: number, lv: number, slack = 0.12): { x: number; z: number } | null {
  const ax = x + DIRS[d][0] * out, az = z + DIRS[d][1] * out;
  // dry ground off the shore (the sea spreads into low ground beside it), all but a little of it free; nothing wet
  let bad = 0;
  for (let dz = -pad; dz <= pad; dz++) for (let dx = -pad; dx <= pad; dx++) {
    if (!inB(ax + dx, az + dz)) return null;
    const i = idx(ax + dx, az + dz);
    if (wet(c, i) || c.w.biome[i] === Biome.Town || c.w.coastDist[i] < 6 || !c.land[i]) return null;
    if (!free(c, i)) bad++;
  }
  if (bad > (pad * 2 + 1) ** 2 * slack) return null;
  level(c, ax - pad, az - pad, pad * 2 + 1, pad * 2 + 1, lv);
  for (let dz = -pad; dz <= pad; dz++) for (let dx = -pad; dx <= pad; dx++) work(c, idx(ax + dx, az + dz));
  return { x: ax, z: az };
}

/** Is there a town's pad within `r` tiles (towns are laid out already; the roads grow out from them)? */
function townNear(c: Ctx, x: number, z: number, r: number): boolean {
  for (let dz = -r; dz <= r; dz += 3) for (let dx = -r; dx <= r; dx += 3) {
    if (Math.hypot(dx, dz) <= r && inB(x + dx, z + dz) && c.w.biome[idx(x + dx, z + dz)] === Biome.Town) return true;
  }
  return false;
}

function site(c: Ctx, kind: MineKind, px: number, pz: number, r: number, a: { x: number; z: number }, d: number, lv: number, lots: MineLot[], major: boolean): WorkSite {
  const name = `${NAMES[Math.floor(c.rng() * NAMES.length)]} ${TITLE[kind]}`;
  c.w.spots.push({ kind: 'quarry', name, x: px + 0.5, z: pz + 0.5, r });
  // the gate: the apron's outer edge, away from the pit, where its road comes in
  const gx = Math.max(0, Math.min(N - 1, a.x + DIRS[d][0] * 6)), gz = Math.max(0, Math.min(N - 1, a.z + DIRS[d][1] * 6));
  return {
    kind: 'mine', name, x: a.x, z: a.z, level: lv, facing: (d + 2) & 3, major, len: r * 2, half: r, cable: [],
    gate: idx(gx, gz), mine: kind, lots,
  };
}

/** The downhill side of a point (the DIRS index whose ground `out` tiles away is lowest), and how far it falls. */
function downhill(c: Ctx, x: number, z: number, out: number): { d: number; fall: number } {
  let d = -1, fall = -Infinity;
  for (let k = 0; k < 4; k++) {
    const nx = x + DIRS[k][0] * out, nz = z + DIRS[k][1] * out;
    if (!inB(nx, nz) || !c.land[idx(nx, nz)]) continue;
    const f = c.E[idx(x, z)] - c.E[idx(nx, nz)];
    if (f > fall) { fall = f; d = k; }
  }
  return { d, fall };
}

/** The open-pit mine: a bowl of benches with a haul road spiralling down it, its plant on the apron. */
function openPit(c: Ctx): WorkSite | null {
  const { w, E, rng } = c;
  const cands: number[] = [];
  for (let i = 0; i < N * N; i++) {
    const b = w.biome[i];
    if ((b !== Biome.Hills && b !== Biome.Plains && b !== Biome.Mountain) || E[i] < SEA + 8 || E[i] > 30 || !free(c, i) || w.coastDist[i] < 10) continue;
    if (!c.keep(i % N, Math.floor(i / N), 26)) continue;
    cands.push(i);
  }
  for (let t = 0; t < 150 && cands.length; t++) {
    const seed = cands[Math.floor(rng() * cands.length)], sx = seed % N, sz = (seed - sx) / N;
    if (!away(c, sx, sz)) continue;
    const R = 10 + Math.floor(rng() * 4);
    const sv = survey(c, sx, sz, R + 2, 0.08);
    if (!sv) { why('pit: ground taken'); continue; }
    if (sv.hi - sv.lo > 14) { why('pit: too rough'); continue; }
    if (riverNear(c, sx - R, sz - R, R * 2 + 1, R * 2 + 1, 2)) { why('pit: water near'); continue; }
    const { d } = downhill(c, sx, sz, R + 7);
    if (d < 0) { why('pit: no downhill'); continue; }
    const rim = Math.round(sv.lo), floor = Math.max(SEA + 3, rim - 10);
    if (rim - floor < 4) { why('pit: too low'); continue; }
    const a = apron(c, sx, sz, d, R + 8, 5, rim);
    if (!a) { why('pit: no apron'); continue; }
    // benches a step and a half wide, two steps apart; a ramp spiralling down through them, a road a tile wide
    const turn = rng() * Math.PI * 2, dir = rng() < 0.5 ? 1 : -1;
    for (let dz = -R - 1; dz <= R + 1; dz++) for (let dx = -R - 1; dx <= R + 1; dx++) {
      const dist = Math.hypot(dx, dz);
      if (dist > R + 1 || !inB(sx + dx, sz + dz)) continue;
      const i = idx(sx + dx, sz + dz);
      if (!free(c, i)) continue;
      const bench = floor + Math.floor(dist / 1.5) * 2;
      let want = bench;
      // the ramp: where the angle round the pit matches how far out it is, the ground runs smoothly up the benches
      const ang = Math.atan2(dz, dx), on = turn + dir * dist * 0.42;
      const off = Math.abs(((ang - on) % (Math.PI * 2) + Math.PI * 3) % (Math.PI * 2) - Math.PI) * dist;
      if (off < 1.1 && dist > 2) { want = floor + (dist / 1.5) * 2 - 1; c.w.flags[i] |= Flag.Track; }
      E[i] = Math.min(E[i], want);
      work(c, i);
    }
    const lv = rim, ax = a.x, az = a.z, back = (d + 2) & 3;
    const across = DIRS[(d + 1) & 3];
    const lots: MineLot[] = [
      { kind: 'oreMill', x: ax - 3, z: az - 2, w: 6, d: 4, facing: back, floors: 2, solid: true, level: lv },
      { kind: 'tailings', x: ax + across[0] * 9 - 3, z: az + across[1] * 9 - 3, w: 7, d: 7, facing: back, floors: 1, solid: false, level: lv },
      { kind: 'crawlerCrane', x: ax - across[0] * 5 - 1, z: az - across[1] * 5 - 1, w: 2, d: 3, facing: back, floors: 1, solid: true, level: lv },
      { kind: 'shack', x: ax + DIRS[d][0] * 4 - 1 - across[0] * 3, z: az + DIRS[d][1] * 4 - 1 - across[1] * 3, w: 2, d: 2, facing: back, floors: 1, solid: true, level: lv },
    ];
    // the tailings pond's ground: levelled beside the apron
    const tl = lots[1];
    if (!rectFree(c, tl.x, tl.z, tl.w, tl.d)) lots.splice(1, 1);
    else { level(c, tl.x, tl.z, tl.w, tl.d, lv, 2); for (let z = tl.z; z < tl.z + tl.d; z++) for (let x = tl.x; x < tl.x + tl.w; x++) work(c, idx(x, z)); }
    return site(c, 'openPit', sx, sz, R, a, d, lv, lots, true);
  }
  return null;
}

/** A cliff of benches cut into a great range's side, a derrick over the face, the crusher on the floor. */
function cutFace(c: Ctx): WorkSite | null {
  const { w, E, rng } = c;
  const cands: number[] = [];
  for (let i = 0; i < N * N; i++) {
    if ((w.biome[i] !== Biome.Mountain && w.biome[i] !== Biome.Snow) || E[i] < 22 || !free(c, i) || !c.keep(i % N, Math.floor(i / N), 20)) continue;
    // only ground with a steep enough side to cut into (a range's flanks are mostly gentle)
    const x = i % N, z = (i - x) / N;
    if (!DIRS.some(([dx, dz]) => inB(x + dx * 9, z + dz * 9) && E[idx(x + dx * 9, z + dz * 9)] - E[i] >= 6)) continue;
    cands.push(i);
  }
  for (let t = 0; t < 150 && cands.length; t++) {
    const seed = cands[Math.floor(rng() * cands.length)], sx = seed % N, sz = (seed - sx) / N;
    if (!away(c, sx, sz)) continue;
    // the uphill side, rising steeply: the face is cut into it
    let up = -1, rise = 0;
    for (let k = 0; k < 4; k++) {
      const nx = sx + DIRS[k][0] * 9, nz = sz + DIRS[k][1] * 9;
      if (!inB(nx, nz)) continue;
      const r2 = E[idx(nx, nz)] - E[seed];
      if (r2 > rise) { rise = r2; up = k; }
    }
    if (up < 0 || rise < 6) { why('cut: no slope'); continue; }
    const R = 9, floor = Math.round(E[seed]);
    // only the ground the face is cut into has to be clear (a mountain stream may run past below it)
    const [cux, cuz] = DIRS[up];
    let bad = 0, n = 0, stop = false;
    for (let dz = -R; dz <= R && !stop; dz++) for (let dx = -R; dx <= R; dx++) {
      if (dx * cux + dz * cuz < -1 || Math.hypot(dx, dz) > R) continue;
      if (!inB(sx + dx, sz + dz)) { stop = true; break; }
      const i = idx(sx + dx, sz + dz);
      n++;
      if (w.biome[i] === Biome.Town) { stop = true; break; }
      // (a stream's tiles and anything else in the way are left as they are)
      if (!free(c, i)) bad++;
    }
    if (stop || bad > n * 0.15) { why(`cut: ground ${stop ? 'wet/edge/town' : `${bad}/${n} taken`}`); continue; }
    const down = (up + 2) & 3;
    const a = apron(c, sx, sz, down, 5, 3, floor, 0.25);
    if (!a) { why('cut: no apron'); continue; }
    const [ux, uz] = DIRS[up];
    for (let dz = -R; dz <= R; dz++) for (let dx = -R; dx <= R; dx++) {
      const along = dx * ux + dz * uz, dist = Math.hypot(dx, dz);
      if (along < -1 || dist > R || !inB(sx + dx, sz + dz)) continue;
      const i = idx(sx + dx, sz + dz);
      // (a stream and two tiles either side of it are left as they are: its water would spread into the cut)
      if (!free(c, i) || riverNear(c, sx + dx, sz + dz, 1, 1, 2)) continue;
      // benches stepping up into the mountain, each 3 tiles deep and two steps high: a cut cliff of steps
      E[i] = Math.min(E[i], floor + Math.max(0, Math.floor(along / 3)) * 2);
      work(c, i);
    }
    const back = up;
    const across = DIRS[(up + 1) & 3];
    const lots: MineLot[] = [
      { kind: 'crusher', x: a.x - 2, z: a.z - 2, w: 4, d: 4, facing: back, floors: 1, solid: true, level: floor },
      { kind: 'derrick', x: sx - across[0] * 4 - 1, z: sz - across[1] * 4 - 1, w: 2, d: 2, facing: back, floors: 1, solid: true, level: floor },
      { kind: 'shack', x: a.x + across[0] * 3 - 1, z: a.z + across[1] * 3 - 1, w: 2, d: 2, facing: back, floors: 1, solid: true, level: floor },
    ];
    // the derrick stands on the face's floor: levelled under it
    const dl = lots[1];
    level(c, dl.x, dl.z, 2, 2, floor, 1);
    return site(c, 'cutFace', sx, sz, R, a, down, floor, lots, false);
  }
  return null;
}

/** A shallow gravel pit on the flat beside a river, its screening plant on the apron and a dredge on the water. */
function gravelPit(c: Ctx): WorkSite | null {
  const { w, E, rng, river } = c;
  const cands: number[] = [];
  for (let i = 0; i < N * N; i++) {
    if (!free(c, i) || E[i] > SEA + 8 || w.coastDist[i] < 12 || (w.biome[i] !== Biome.Plains && w.biome[i] !== Biome.Hills && w.biome[i] !== Biome.Forest)) continue;
    const x = i % N, z = (i - x) / N;
    if (!c.keep(x, z, 16)) continue;
    // a river within a few tiles
    let wet = false;
    for (let dz = -4; dz <= 4 && !wet; dz++) for (let dx = -4; dx <= 4; dx++) if (inB(x + dx, z + dz) && river[idx(x + dx, z + dz)]) { wet = true; break; }
    if (wet) cands.push(i);
  }
  for (let t = 0; t < 150 && cands.length; t++) {
    const seed = cands[Math.floor(rng() * cands.length)], sx = seed % N, sz = (seed - sx) / N;
    if (!away(c, sx, sz)) continue;
    // the pit sits back from the river by a few tiles, on the far side from it
    let rx = 0, rz = 0, n = 0;
    for (let dz = -6; dz <= 6; dz++) for (let dx = -6; dx <= 6; dx++) if (inB(sx + dx, sz + dz) && river[idx(sx + dx, sz + dz)]) { rx += dx; rz += dz; n++; }
    if (!n) continue;
    const away2 = Math.abs(rx) > Math.abs(rz) ? (rx > 0 ? 2 : 0) : rz > 0 ? 3 : 1;
    // back from the river far enough that its water can't spread into the pit (generate.ts spreads it two tiles)
    const R = 7, px = sx + DIRS[away2][0] * (R + 3), pz = sz + DIRS[away2][1] * (R + 3);
    const sv = survey(c, px, pz, R);
    if (!sv || sv.hi - sv.lo > 2.5 || riverNear(c, px - R, pz - R, R * 2 + 1, R * 2 + 1, 3)) continue;
    const top = Math.round(sv.lo), floor = Math.max(SEA + 3, top - 2);
    if (top - floor < 1) continue;
    const a = apron(c, px, pz, away2, R + 5, 4, top);
    if (!a) continue;
    for (let dz = -R; dz <= R; dz++) for (let dx = -R; dx <= R; dx++) {
      const dist = Math.hypot(dx, dz);
      if (dist > R || !inB(px + dx, pz + dz)) continue;
      const i = idx(px + dx, pz + dz);
      E[i] = Math.min(E[i], dist < R - 1.5 ? floor : top - 1);
      work(c, i);
    }
    const back = (away2 + 2) & 3, across = DIRS[(away2 + 1) & 3];
    const lots: MineLot[] = [
      { kind: 'gravelPlant', x: a.x - 2, z: a.z - 1, w: 4, d: 3, facing: back, floors: 1, solid: true, level: top },
      { kind: 'crates', x: a.x + across[0] * 3 - 1, z: a.z + across[1] * 3 - 1, w: 2, d: 2, facing: back, floors: 1, solid: false, level: top },
      { kind: 'shack', x: a.x - across[0] * 3 - 1, z: a.z - across[1] * 3 - 1, w: 2, d: 2, facing: back, floors: 1, solid: true, level: top },
    ];
    return site(c, 'gravelPit', px, pz, R, a, away2, top, lots, false);
  }
  return null;
}

/** A strip mine: long cuts across flat open plains, spoil heaped between them, the dragline at the working cut. */
function stripMine(c: Ctx): WorkSite | null {
  const { w, E, rng } = c;
  const cands: number[] = [];
  for (let i = 0; i < N * N; i++) {
    if (w.biome[i] !== Biome.Plains || E[i] < SEA + 5 || w.coastDist[i] < 8 || !free(c, i) || !c.keep(i % N, Math.floor(i / N), 22)) continue;
    cands.push(i);
  }
  const L = 20, Wd = 12;
  for (let t = 0; t < 150 && cands.length; t++) {
    const seed = cands[Math.floor(rng() * cands.length)], sx = seed % N, sz = (seed - sx) / N;
    if (!away(c, sx, sz)) continue;
    const alongX = rng() < 0.5;
    const wx = alongX ? L : Wd, wz = alongX ? Wd : L, x0 = sx - (wx >> 1), z0 = sz - (wz >> 1);
    // clear ground, but for a stream or two: those are left running, uncut, with a margin either side
    let wetN = 0, stop = false;
    for (let z = z0; z < z0 + wz && !stop; z++) for (let x = x0; x < x0 + wx; x++) {
      if (!inB(x, z)) { stop = true; break; }
      const i = idx(x, z);
      if (wet(c, i)) { wetN++; continue; }
      if (!free(c, i)) { stop = true; break; }
    }
    if (stop || wetN > wx * wz * 0.12) { why('strip: ground taken'); continue; }
    const nearWet = (x: number, z: number) => riverNear(c, x, z, 1, 1, 2);
    let lo = Infinity, hi = -Infinity;
    for (let z = z0; z < z0 + wz; z++) for (let x = x0; x < x0 + wx; x++) { lo = Math.min(lo, E[idx(x, z)]); hi = Math.max(hi, E[idx(x, z)]); }
    if (hi - lo > 4) { why('strip: not flat'); continue; }
    const top = Math.round(lo);
    // the apron at one end of the strips
    const d = alongX ? (rng() < 0.5 ? 0 : 2) : (rng() < 0.5 ? 1 : 3);
    const a = apron(c, sx, sz, d, L / 2 + 6, 4, top);
    if (!a) { why('strip: no apron'); continue; }
    // the cuts run across the long way, three tiles wide each, with a ridge of spoil between; the last one working
    for (let z = z0; z < z0 + wz; z++) for (let x = x0; x < x0 + wx; x++) {
      const k = alongX ? x - x0 : z - z0, i = idx(x, z);
      if (nearWet(x, z)) continue;
      const row = Math.floor(k / 3) % 2;
      E[i] = row ? top + 1 : Math.max(SEA + 3, top - 2);
      work(c, i);
    }
    const back = (d + 2) & 3, across = DIRS[(d + 1) & 3];
    // the dragline on the spoil beside the working cut, nearest the apron
    const k0 = (d === 0 || d === 1) ? (alongX ? wx : wz) - 4 : 1;
    const dlx = alongX ? x0 + k0 : sx - 2, dlz = alongX ? sz - 2 : z0 + k0;
    if (riverNear(c, dlx, dlz, 4, 4, 2)) { why('strip: no dry spoil for the dragline'); continue; }
    const lots: MineLot[] = [
      { kind: 'coalTipple', x: a.x - 1, z: a.z - 1, w: 3, d: 3, facing: back, floors: 2, solid: true, level: top },
      { kind: 'dragline', x: dlx, z: dlz, w: 4, d: 4, facing: back, floors: 1, solid: true, level: top + 1 },
      { kind: 'shack', x: a.x + across[0] * 3 - 1, z: a.z + across[1] * 3 - 1, w: 2, d: 2, facing: back, floors: 1, solid: true, level: top },
    ];
    level(c, dlx, dlz, 4, 4, top + 1, 1);
    return site(c, 'stripMine', sx, sz, 10, a, d, top, lots, true);
  }
  return null;
}

/**
 * After the roads are laid (generate.ts, after linkWorks): a mine no road reaches from a town is given up, its plant
 * taken down and its working left as an abandoned pit, since nothing could come or go there.
 */
export function dropStrandedMines(w: World): void {
  for (let k = w.works.length - 1; k >= 0; k--) {
    const g = w.works[k];
    if (g.kind !== 'mine' || roadToTown(w, g.gate)) continue;
    for (const b of g.buildings) {
      b.gone = true;
      for (let z = b.z; z < b.z + b.d; z++) for (let x = b.x; x < b.x + b.w; x++) if (inB(x, z)) { w.blocked[idx(x, z)] = 0; w.roof[idx(x, z)] = 0; }
    }
    w.works.splice(k, 1);
    const s = w.spots.findIndex((p) => p.name === g.name);
    if (s >= 0) w.spots.splice(s, 1);
  }
}
/** Is there a road at (or two tiles round) this tile that runs, road to road, into a town? */
function roadToTown(w: World, gate: number): boolean {
  const seen = new Set<number>(), q: number[] = [];
  for (let dz = -2; dz <= 2; dz++) for (let dx = -2; dx <= 2; dx++) {
    const x = (gate % N) + dx, z = Math.floor(gate / N) + dz;
    if (inB(x, z) && w.road[idx(x, z)]) { seen.add(idx(x, z)); q.push(idx(x, z)); }
  }
  for (let k = 0; k < q.length && k < 40000; k++) {
    if (w.townId[q[k]] >= 0) return true;
    const x = q[k] % N, z = Math.floor(q[k] / N);
    for (const [dx, dz] of DIRS) {
      if (!inB(x + dx, z + dz)) continue;
      const j = idx(x + dx, z + dz);
      if (w.road[j] && !seen.has(j)) { seen.add(j); q.push(j); }
    }
  }
  return false;
}

function rectFree(c: Ctx, x0: number, z0: number, wx: number, wz: number): boolean {
  for (let z = z0; z < z0 + wz; z++) for (let x = x0; x < x0 + wx; x++) {
    if (!inB(x, z)) { why('rect: edge'); return false; }
    const i = idx(x, z);
    if (!free(c, i)) { why(`rect: ${!c.land[i] ? 'sea' : wet(c, i) ? 'wet' : c.w.biome[i] === Biome.Town ? 'town' : `feature ${c.w.feature[i]}`}`); return false; }
  }
  return true;
}
