import { N, SEA, RoadType, idx } from '../../tiles';
import { put, type Layout, type TownPlan } from '../../towns';
import { LAYERS } from '../layers';
import { CARVERS, Dig, nearestSeaSide } from '../water';
import { avenue, dfCores, finishTown, parkAt, type Pt } from '../kit';
import { gridLines } from './shared';
import { gridAround } from './grids';

/**
 * Hills kept (docs/cityplans.html): towns that keep most of their hill (towns.ts softenSite, by the plan's
 * keepRelief) and build round it. Siena's hill town, Edinburgh's citadel and new town, Valparaíso's amphitheatre.
 */

/** The highest ground in the square (sampled), `pad` in from its edge. */
function summit(c: Layout, p: TownPlan, pad = 6): Pt {
  let best: Pt = [p.x0 + p.size / 2, p.z0 + p.size / 2], h = -Infinity;
  for (let z = p.z0 + pad; z < p.z0 + p.size - pad; z += 2) for (let x = p.x0 + pad; x < p.x0 + p.size - pad; x += 2) {
    const e = c.w.elev[idx(x, z)];
    if (e > h) { h = e; best = [x + 0.5, z + 0.5]; }
  }
  return best;
}

/** Points round a centre at radius r (a closed loop of n points), clamped into the town. */
function loop(c: Layout, at: Pt, r: number, n: number, phase = 0): Pt[] {
  const out: Pt[] = [];
  for (let k = 0; k <= n; k++) { const a = phase + (k / n) * Math.PI * 2; out.push(c.clampPt(at[0] + Math.cos(a) * r, at[1] + Math.sin(a) * r)); }
  return out;
}

// ---------------------------------------------------------------------------------------------
// the hill town: Siena, Assisi, Mont-Saint-Michel

LAYERS.hilltown = (c, p, rng) => {
  const S = p.size, top = summit(c, p, Math.round(S * 0.25));
  const keep = c.t.surface;
  c.t.surface = c.t.surface === 'dirt' ? 'dirt' : 'cobble';
  // three ridges from the piazza at the top down to three gates
  const a0 = rng() * Math.PI * 2;
  const ridges: number[][] = [];
  for (let k = 0; k < 3; k++) {
    const a = a0 + (k * Math.PI * 2) / 3;
    const out = c.clampPt(top[0] + Math.cos(a) * S * 0.6, top[1] + Math.sin(a) * S * 0.6);
    const r = c.street(RoadType.TwoLane, [top, [top[0] + Math.cos(a) * S * 0.2, top[1] + Math.sin(a) * S * 0.2], out]);
    c.ends(r);
    ridges.push(r);
  }
  // the streets round the hill along its contours
  for (const f of [0.14, 0.26, 0.38]) c.street(RoadType.TwoLane, loop(c, top, S * f, 10, a0));
  c.t.surface = keep;
  // the lower town along the valley road on the square's lowest side
  let low = 0, lowH = Infinity;
  for (let d = 0; d < 4; d++) {
    let s = 0;
    for (let k = 4; k < S - 4; k += 4) { const x = d === 0 ? p.x0 + S - 3 : d === 2 ? p.x0 + 2 : p.x0 + k, z = d === 1 ? p.z0 + S - 3 : d === 3 ? p.z0 + 2 : p.z0 + k; s += c.w.elev[idx(x, z)]; }
    if (s < lowH) { lowH = s; low = d; }
  }
  const v = (u: number): [Pt, Pt] => low % 2 === 0
    ? [[low === 0 ? p.x0 + S - 1.5 - u : p.x0 + 1.5 + u, p.z0 + 1], [low === 0 ? p.x0 + S - 1.5 - u : p.x0 + 1.5 + u, p.z0 + S - 1]]
    : [[p.x0 + 1, low === 1 ? p.z0 + S - 1.5 - u : p.z0 + 1.5 + u], [p.x0 + S - 1, low === 1 ? p.z0 + S - 1.5 - u : p.z0 + 1.5 + u]];
  const [va, vb] = v(1);
  c.ends(c.street(RoadType.TwoLane, [va, vb]));
  // the walls' towers round the brow, the cathedral and the hall on the top, the tower over the piazza
  for (const pt of loop(c, top, S * 0.44, 8, a0 + 0.3).slice(0, 8)) put(c, 'watchtower', { near: pt, maxDist: 3, zone: 'any' });
  c.anchors.temple = [top[0] + 3, top[1] - 3];
  c.anchors.seat = [top[0] - 3, top[1] + 3];
  c.anchors.tower = [top[0] + 3, top[1] + 3];
  c.anchors.market = top;
  put(c, 'marketSquare', { near: top, maxDist: 4 });
  c.dfAt = dfCores(c, [top], S * 0.6);
  c.maxFloors = 4;
  finishTown(c, { grow: c.t.kind === 'city' ? 6 : 12, growType: RoadType.Cobble, axis: ridges[0] });
  return true;
};

// ---------------------------------------------------------------------------------------------
// the citadel and new town: Edinburgh

LAYERS.citadel = (c, p, rng) => {
  const S = p.size, x0 = p.x0, z0 = p.z0, mega = p.kind === 'mega';
  const rock = summit(c, p, Math.round(S * 0.15));
  // the Royal Mile runs from the castle across the town along whichever way has the more room
  const ax: 0 | 1 = Math.abs(rock[0] - (x0 + S / 2)) >= Math.abs(rock[1] - (z0 + S / 2)) ? 0 : 1;
  const dir = (ax === 0 ? rock[0] < x0 + S / 2 : rock[1] < z0 + S / 2) ? 1 : -1;
  const P = (s: number, u: number): Pt => (ax === 0 ? [rock[0] + dir * s, rock[1] + u] : [rock[0] + u, rock[1] + dir * s]);
  const mile = Math.round(S * 0.55);
  const keep = c.t.surface;
  c.t.surface = 'cobble';
  const royal = avenue(c, RoadType.TwoLane, P(3, 0), P(mile, 0), { main: true });
  c.ends(royal);
  // the closes: short dead ends off both sides of it, a herringbone
  for (let s = 6; s < mile; s += 3) for (const side of [-1, 1]) avenue(c, RoadType.Paved, P(s, 0), P(s, side * 4), { main: false });
  c.t.surface = keep;
  // the valley garden below the Old Town where the loch was, and beyond it the New Town's grid
  const gU = (rng() < 0.5 ? 1 : -1) * 10, gLen = Math.min(30, mile - 4);
  const g0 = P(6, gU), g1 = P(6 + gLen, gU + Math.sign(gU) * 6);
  const garden = parkAt(c, Math.min(g0[0], g1[0]), Math.min(g0[1], g1[1]), Math.abs(g1[0] - g0[0]), Math.abs(g1[1] - g0[1]), rng);
  const nu = gU + Math.sign(gU) * 9;
  const streets: number[][] = [];
  for (const k of [0, 5, 10]) streets.push(avenue(c, RoadType.TwoLane, P(4, nu + Math.sign(gU) * k), P(4 + gLen + 4, nu + Math.sign(gU) * k), { main: k === 5 }));
  for (let s = 4; s <= 4 + gLen + 4; s += 7) avenue(c, RoadType.TwoLane, P(s, nu), P(s, nu + Math.sign(gU) * 10), { main: false });
  c.ends(streets[1]);
  // the bridges over the valley from the Old Town to the New, and the road down to the port
  for (const s of [12, 22]) c.street(RoadType.TwoLane, [P(s, 0), P(s, nu)]);
  // the rest of the town round them
  const hole = [P(-4, -6), P(mile + 2, nu + Math.sign(gU) * 12)];
  gridAround(c, gridLines(x0, x0 + S, 7), gridLines(z0, z0 + S, 7), [[Math.min(hole[0][0], hole[1][0]), Math.min(hole[0][1], hole[1][1]), Math.max(hole[0][0], hole[1][0]), Math.max(hole[0][1], hole[1][1])]]);
  // the roles: the castle on its rock, the palace at the Mile's foot, the monument in the gardens, a hill park
  c.anchors.palace = P(1, 2);
  c.anchors.seat = P(mile - 2, -3);
  c.anchors.temple = P(Math.round(mile * 0.45), -3);
  c.anchors.tower = garden ? [garden.x + garden.w / 2, garden.z - 1] : P(15, gU);
  c.anchors.museum = P(16, nu + Math.sign(gU) * 3);
  put(c, 'moatedCastle', { near: P(0, 0), maxDist: 5, zone: 'any' }) ?? put(c, 'watchtower', { near: P(0, 0), maxDist: 4, zone: 'any' });
  c.dfAt = dfCores(c, [P(mile * 0.5, 0), P(16, nu + Math.sign(gU) * 5)], S * 0.5);
  c.capAt = (x, z) => (Math.hypot(x - rock[0], z - rock[1]) < mile ? 7 : 0);
  finishTown(c, { grow: mega ? 14 : 8, parks: garden ? [garden] : [], axis: royal });
  return true;
};

// ---------------------------------------------------------------------------------------------
// the amphitheatre: Valparaíso, Genoa, Naples

CARVERS.amphitheatre = (p, ctx) => {
  const dig = new Dig(p, ctx);
  const side = nearestSeaSide(dig, 30);
  if (side < 0) return false;
  // the bay brought right up to the town: a harbour three tiles deep along its sea side, open to the sea
  const S = p.size;
  const F = (s: number, u: number): [number, number] => {
    switch (side) {
      case 0: return [p.x0 + S - 1 - u, p.z0 + s];
      case 1: return [p.x0 + s, p.z0 + S - 1 - u];
      case 2: return [p.x0 + u, p.z0 + s];
      default: return [p.x0 + s, p.z0 + u];
    }
  };
  for (let s = 3; s < S - 3; s++) for (let u = 0; u < 3; u++) { const [x, z] = F(s, u); dig.mark(x, z, 2); }
  // its mouth where the sea comes nearest the quay
  const { land } = ctx;
  const seaAt = (s: number): number => {
    for (let u = 1; u <= 40; u++) { const [x, z] = F(s, -u); if (x < 0 || z < 0 || x >= N || z >= N) return Infinity; const i = idx(x, z); if (!land[i] && ctx.w.elev[i] < SEA) return u; }
    return Infinity;
  };
  const mouths: [number, number][] = [];
  for (let s = 6; s < S - 6; s += 3) mouths.push([s, seaAt(s)]);
  mouths.sort((q, r) => q[1] - r[1]);
  const low = p.level <= SEA + 9;
  let clear = false;
  for (const [s, d] of mouths.slice(0, 6)) {
    if (!low || !Number.isFinite(d)) break;
    const trial = new Dig(p, ctx);
    for (const [i, dep] of dig.want) trial.want.set(i, dep);
    const [mx, mz] = F(s, 0);
    if (trial.toSea(mx, mz, side, 2) && trial.clear()) { for (const [i, dep] of trial.want) dig.want.set(i, dep); clear = true; break; }
  }
  if ((globalThis as { process?: { env: Record<string, string | undefined> } }).process?.env?.PLAN_DEBUG) console.log(`amphitheatre: side ${side}, level ${p.level}, harbour ${clear}`);
  // (where a causeway or the county's edge stands between, the basin is dug all the same, a dock behind its sea wall)
  if (low && (clear || dig.clear())) dig.commit();
  (p.carved ??= {}).seaSide = side;
  return true;
};

LAYERS.amphitheatre = (c, p) => {
  const S = p.size, side = p.carved?.seaSide;
  if (side === undefined) return false;
  // s along the shore, u up from it
  const P = (s: number, u: number): Pt => {
    switch (side) {
      case 0: return [p.x0 + S - 1.5 - u, p.z0 + s + 0.5];
      case 1: return [p.x0 + s + 0.5, p.z0 + S - 1.5 - u];
      case 2: return [p.x0 + 1.5 + u, p.z0 + s + 0.5];
      default: return [p.x0 + s + 0.5, p.z0 + 1.5 + u];
    }
  };
  // the port's flat strip along the shore: a quay road and a tight grid behind it
  const quay = avenue(c, RoadType.FourLane, P(1, 4), P(S - 2, 4), { main: true });
  c.ends(quay);
  const strip = Math.round(S * 0.2);
  for (const u of [8, 12, strip]) avenue(c, RoadType.TwoLane, P(1, u), P(S - 2, u), { main: false });
  for (let s = 3; s < S - 2; s += 6) avenue(c, RoadType.TwoLane, P(s, 4), P(s, strip), { main: false });
  // up the bowl: switchback streets zigzagging from the strip to the rim road, every few blocks
  const rim = Math.round(S * 0.85);
  c.ends(c.street(RoadType.TwoLane, [P(1, rim), P(S / 2, rim + 2), P(S - 2, rim)]));
  for (let s = 6; s < S - 6; s += 14) {
    const pts: Pt[] = [];
    for (let u = strip, k = 0; u <= rim; u += 6, k++) pts.push(P(s + (k % 2 ? 6 : 0), u));
    c.street(RoadType.TwoLane, pts);
  }
  // the terraces: contour streets across the slope between them
  for (const f of [0.38, 0.55, 0.7]) c.street(RoadType.Paved, [P(2, S * f), P(S / 2, S * f + 1), P(S - 3, S * f)]);
  // the roles: the port and customs house on the quay, the cathedral on the shore, the lookout on the rim
  c.anchors.seat = P(S * 0.5, 7);
  c.anchors.temple = P(S * 0.3, 7);
  c.anchors.market = P(S * 0.65, 3);
  put(c, 'canalWarehouse', { near: P(S * 0.2, 2), maxDist: 4, waterside: 'prefer' });
  put(c, 'observationTower', { highest: true, zone: 'any' });
  // dense and stepped all the way up, a little less toward the rim
  c.dfAt = (x, z) => {
    const u = side === 0 ? p.x0 + S - x : side === 2 ? x - p.x0 : side === 1 ? p.z0 + S - z : z - p.z0;
    return 0.25 + 0.6 * (u / S);
  };
  c.capAt = (x, z) => { const u = side === 0 ? p.x0 + S - x : side === 2 ? x - p.x0 : side === 1 ? p.z0 + S - z : z - p.z0; return u < S * 0.2 ? 0 : 8; };
  finishTown(c, { grow: 14, axis: quay });
  return true;
};
