/**
 * Great parks: a Central Park or a Golden Gate Park in about one big city or megalopolis in six. A whole block of
 * town ringed by streets on all four sides — a square one, or a long one three times as long as it is wide — laid
 * out inside as a landscaped park: a web of footpaths, open meadows and ball fields, usually a lake of some odd shape
 * (often with an island), sometimes a park drive meandering through it that traffic uses like any other street,
 * groves and allées of trees, flower beds, and a bandstand, boathouse, fountain, tea house or glasshouse.
 *
 * The town lays the block (world/towns.ts `greatPark`); everything inside it is one Building of kind `greatPark`
 * whose layout is a pure function of its seed and size (`parkPlan`), so the generator (the drive's tiles), the
 * footprint (the lake and the buildings block cars), the model (render/buildings/greatPark.ts) and the trees
 * (instanced with the country's own, render/props.ts via `chunkParkProps`) all read the same plan. The seed carries
 * the landscaping theme in its low three bits and whether a drive runs through in the fourth, which the town settles
 * from the climate and its style when it lays the block (`parkSeed`).
 *
 * Everything here is in the model's local frame: the origin in the middle of the lot, x across W, z along D.
 */
import { DIRS, N, World, idx, type Building } from './tiles';
import type { TreeKind, ClutterKind, CropKind } from './regions';
import { mulberry32, type Rng } from './rng';

/** The landscaping a park is laid out in. */
export type ParkTheme = 'english' | 'french' | 'japanese' | 'prairie' | 'tropical' | 'pinewood' | 'mediterranean';
export const PARK_THEMES: ParkTheme[] = ['english', 'french', 'japanese', 'prairie', 'tropical', 'pinewood', 'mediterranean'];
/** How its footpaths are laid out. */
type PathDesign = 'loops' | 'web' | 'radial' | 'grid' | 'figure8' | 'serpentine';
const PATH_DESIGNS: PathDesign[] = ['loops', 'web', 'radial', 'grid', 'figure8', 'serpentine'];
type PondKind = 'blob' | 'kidney' | 'lobed' | 'chain' | 'basin' | 'canal' | 'quatrefoil';

/** One body of water: a star-shaped outline, `r[k]` the radius (× R) at angle 2πk/PSEG in its stretched frame. */
export interface Pond {
  x: number; z: number; R: number; ax: number; az: number; rot: number; r: number[]; kind: PondKind;
  island: { x: number; z: number; r: number } | null;
}
export interface ParkPath {
  pts: [number, number][];
  w: number;
  /** The points that stand over water: they are carried on a little bridge. */
  bridge: boolean[];
  main: boolean;
}
export type FeatureKind =
  | 'bandstand' | 'boathouse' | 'fountain' | 'gazebo' | 'teahouse' | 'pagoda' | 'obelisk' | 'statue' | 'playground'
  | 'glasshouse' | 'bench' | 'lamp' | 'plaza' | 'kiosk' | 'temple';
export interface Feature { kind: FeatureKind; x: number; z: number; yaw: number; r: number }
interface Bed { x: number; z: number; w: number; d: number; col: number; hedge: boolean; round: boolean }
export interface Field { x: number; z: number; w: number; d: number; yaw: number; kind: 'ball' | 'pitch' | 'lawn' }
export interface Meadow { x: number; z: number; rx: number; rz: number; rot: number; r: number[] }
type PlantKind = TreeKind | ClutterKind | CropKind | 'tuft' | 'rock';
export interface Plant { kind: PlantKind; x: number; z: number; s: number; yaw: number; tint?: [number, number, number] }

export interface ParkPlan {
  W: number; D: number; theme: ParkTheme; design: PathDesign;
  /** The drive's tiles inside the lot, in order from one ring road to the other (local tile coords), or null. */
  road: [number, number][] | null;
  roadSet: Set<number>;
  ponds: Pond[];
  meadows: Meadow[];
  fields: Field[];
  paths: ParkPath[];
  /** Junctions where three or more paths meet. */
  junctions: [number, number, number][];
  beds: Bed[];
  /** Clipped hedge rings round a formal park's plazas. */
  hedges: { x: number; z: number; r: number }[];
  features: Feature[];
  plants: Plant[];
  /** The path graph's nodes and edges, for the gate: every node reached from every other. */
  graph: { nodes: [number, number][]; edges: [number, number][] };
}

/** Samples round a pond's outline. */
export const PSEG = 32;

// ---- the seed ----------------------------------------------------------------------------------------------

/** The theme a park's seed carries (its low three bits; the eighth value is English again). */
const themeOf = (seed: number): ParkTheme => PARK_THEMES[(seed >>> 0) & 7] ?? 'english';
/** Whether the seed says a park drive runs through it (bit 3). */
const hasDrive = (seed: number): boolean => ((seed >>> 3) & 1) === 1;
/** A seed carrying this theme and drive. */
export const parkSeed = (roll: number, theme: ParkTheme, drive: boolean): number =>
  ((roll >>> 0) & ~15) | (drive ? 8 : 0) | PARK_THEMES.indexOf(theme);

// ---- small geometry ----------------------------------------------------------------------------------------

const TAU = Math.PI * 2;
type P = [number, number];

function segsCross(a: P, b: P, c: P, d: P): boolean {
  const o = (p: P, q: P, r: P) => Math.sign((q[0] - p[0]) * (r[1] - p[1]) - (q[1] - p[1]) * (r[0] - p[0]));
  return o(a, b, c) * o(a, b, d) < 0 && o(c, d, a) * o(c, d, b) < 0;
}

/** The pond's radius toward local point (x, z), and how far out the point is, in the pond's stretched frame. */
function pondReach(p: Pond, x: number, z: number): [number, number] {
  const dx = x - p.x, dz = z - p.z, c = Math.cos(-p.rot), s = Math.sin(-p.rot);
  const u = (dx * c - dz * s) / p.ax, v = (dx * s + dz * c) / p.az;
  let a = Math.atan2(v, u);
  if (a < 0) a += TAU;
  const f = (a / TAU) * PSEG, k = Math.floor(f) % PSEG, t = f - Math.floor(f);
  const r = (p.r[k] * (1 - t) + p.r[(k + 1) % PSEG] * t) * p.R;
  return [r, Math.hypot(u, v)];
}

/** Is local (x, z) on the water of this pond, `m` tiles of margin counted as water too (negative: well inside)? */
export function inPond(p: Pond, x: number, z: number, m = 0): boolean {
  const [r, d] = pondReach(p, x, z);
  const scale = Math.min(p.ax, p.az);
  if (d * scale > r * scale + m) return false;
  if (p.island && Math.hypot(x - p.island.x, z - p.island.z) < p.island.r - m) return false;
  return true;
}

/** A point on the pond's outline at angle a (in its own frame), pushed out by `out` tiles. */
export function pondEdge(p: Pond, a: number, out = 0): P {
  const f = (((a % TAU) + TAU) % TAU) / TAU * PSEG, k = Math.floor(f) % PSEG, t = f - Math.floor(f);
  const r = (p.r[k] * (1 - t) + p.r[(k + 1) % PSEG] * t) * p.R;
  const u = Math.cos(a) * (r * p.ax + out), v = Math.sin(a) * (r * p.az + out);
  const c = Math.cos(p.rot), s = Math.sin(p.rot);
  return [p.x + u * c - v * s, p.z + u * s + v * c];
}

/** The outline of a meadow, as for a pond. */
export function meadowEdge(m: Meadow, a: number): P {
  const f = (((a % TAU) + TAU) % TAU) / TAU * PSEG, k = Math.floor(f) % PSEG, t = f - Math.floor(f);
  const r = m.r[k] * (1 - t) + m.r[(k + 1) % PSEG] * t;
  const u = Math.cos(a) * r * m.rx, v = Math.sin(a) * r * m.rz;
  const c = Math.cos(m.rot), s = Math.sin(m.rot);
  return [m.x + u * c - v * s, m.z + u * s + v * c];
}

function inMeadow(m: Meadow, x: number, z: number, shrink = 0): boolean {
  const dx = x - m.x, dz = z - m.z, c = Math.cos(-m.rot), s = Math.sin(-m.rot);
  const u = (dx * c - dz * s) / m.rx, v = (dx * s + dz * c) / m.rz;
  let a = Math.atan2(v, u);
  if (a < 0) a += TAU;
  const f = (a / TAU) * PSEG, k = Math.floor(f) % PSEG, t = f - Math.floor(f);
  const r = m.r[k] * (1 - t) + m.r[(k + 1) % PSEG] * t;
  return Math.hypot(u, v) < r - shrink;
}

/** A wobbly outline: 1 plus a few harmonics. */
function wobble(rng: Rng, amp: number, harmonics: number[]): number[] {
  const ph = harmonics.map(() => rng() * TAU), am = harmonics.map(() => amp * (0.4 + rng() * 0.6));
  const out: number[] = [];
  for (let k = 0; k < PSEG; k++) {
    const a = (k / PSEG) * TAU;
    let r = 1;
    harmonics.forEach((h, j) => { r += am[j] * Math.cos(h * a + ph[j]) / h; });
    out.push(r);
  }
  return out;
}

function pondShape(rng: Rng, kind: PondKind): number[] {
  const out: number[] = [];
  const ph = rng() * TAU, lobes = rng() < 0.5 ? 3 : 4, hw = 0.38 + rng() * 0.2;
  const base = kind === 'blob' || kind === 'chain' ? wobble(rng, 0.42, [2, 3, 5]) : wobble(rng, 0.12, [2, 3]);
  for (let k = 0; k < PSEG; k++) {
    const a = (k / PSEG) * TAU;
    switch (kind) {
      case 'kidney': out.push(base[k] * (1 - 0.42 * Math.max(0, Math.cos(a - ph)) ** 3 + 0.12 * Math.cos(2 * (a - ph)))); break;
      case 'lobed': out.push(base[k] * (0.82 + 0.26 * Math.cos(lobes * a + ph))); break;
      case 'basin': out.push(1); break;
      case 'quatrefoil': out.push(0.74 + 0.26 * Math.abs(Math.cos(2 * a))); break;
      // a long rectangle: the radius to its edge at this angle (it is stretched by ax/az afterwards)
      case 'canal': out.push(Math.min(1 / Math.max(1e-3, Math.abs(Math.cos(a))), hw / Math.max(1e-3, Math.abs(Math.sin(a))))); break;
      default: out.push(base[k]);
    }
  }
  return out;
}

// ---- the plan ----------------------------------------------------------------------------------------------

const PLAN = new Map<string, ParkPlan>();

/** A park's plan, from its seed and the size of its lot (local W across, D deep), worked out once. */
export function parkPlan(seed: number, W: number, D: number): ParkPlan {
  const key = `${seed >>> 0}|${W}|${D}`;
  let p = PLAN.get(key);
  if (!p) {
    p = makePlan(seed >>> 0, W, D);
    if (PLAN.size > 256) PLAN.clear();
    PLAN.set(key, p);
  }
  return p;
}

/** The plan of a great park building, in the model's frame (its facing turns W and D). */
export function planOf(b: Building): ParkPlan {
  const alongZ = b.facing % 2 === 1;
  return parkPlan(b.seed, alongZ ? b.w : b.d, alongZ ? b.d : b.w);
}

/** Which themes allow a little bridge over the water where a path meets it. */
const BRIDGES: Record<ParkTheme, boolean> = { english: true, french: false, japanese: true, prairie: true, tropical: true, pinewood: true, mediterranean: false };
/** The path layouts each theme leans to, with weights. */
const DESIGNS: Record<ParkTheme, Partial<Record<PathDesign, number>>> = {
  english: { loops: 3, figure8: 2, web: 1, serpentine: 1, radial: 1 },
  french: { grid: 4, radial: 3 },
  japanese: { serpentine: 3, loops: 2, figure8: 1 },
  prairie: { serpentine: 2, loops: 2, web: 1, figure8: 1 },
  tropical: { loops: 2, radial: 2, web: 1, figure8: 1 },
  pinewood: { web: 2, serpentine: 2, loops: 2 },
  mediterranean: { radial: 2, grid: 2, loops: 1, figure8: 1 },
};

const pickW = <T extends string>(rng: Rng, table: Partial<Record<T, number>>): T => {
  const e = Object.entries(table) as [T, number][];
  let t = rng() * e.reduce((s, [, v]) => s + v, 0);
  for (const [k, v] of e) { t -= v; if (t < 0) return k; }
  return e[e.length - 1][0];
};

function makePlan(seed: number, W: number, D: number): ParkPlan {
  const theme = themeOf(seed);
  const rng = mulberry32(seed ^ 0x9e3779b9);
  const hw = W / 2, hd = D / 2;
  const long = Math.max(W, D) >= Math.min(W, D) * 1.8;
  const alongX = W >= D;
  const design: PathDesign = long && rng() < 0.2 ? (theme === 'french' ? 'grid' : 'serpentine') : pickW(rng, DESIGNS[theme]);

  // ---- the drive: runs and jogs across the long way, from one ring road to the other
  let road: [number, number][] | null = null;
  const roadSet = new Set<number>();
  if (hasDrive(seed)) {
    road = [];
    const along = alongX ? W : D, across = alongX ? D : W;
    const lo = across >= 7 ? 2 : 1, hi = across - 1 - lo;
    let u = lo + Math.floor(rng() * (hi - lo + 1));
    const put = (s: number, uu: number) => road!.push(alongX ? [s, uu] : [uu, s]);
    let s = 0;
    while (s < along) {
      const run = Math.min(along - s, s === 0 ? 2 + Math.floor(rng() * 4) : 3 + Math.floor(rng() * 4));
      for (let k = 0; k < run; k++) put(s + k, u);
      s += run;
      if (s >= along - 1) { while (s < along) put(s++, u); break; }
      // a jog across, two to four tiles, staying a tile or two in from the side
      const span = 2 + Math.floor(rng() * 3);
      let to = u + (rng() < 0.5 ? -span : span);
      if (to < lo || to > hi) to = u + (to < lo ? span : -span);
      to = Math.max(lo, Math.min(hi, to));
      const step = Math.sign(to - u);
      while (u !== to) { u += step; put(s - 1, u); }
    }
    for (const [tx, tz] of road) roadSet.add(tz * W + tx);
  }
  /** Distance from local (x, z) to the drive's tiles (Infinity with none), for anything that must keep off it. */
  const roadDist = (x: number, z: number): number => {
    if (!road) return Infinity;
    const tx = Math.floor(x + hw), tz = Math.floor(z + hd);
    let best = Infinity;
    for (let dz = -2; dz <= 2; dz++) {
      for (let dx = -2; dx <= 2; dx++) {
        const a = tx + dx, b = tz + dz;
        if (a < 0 || b < 0 || a >= W || b >= D || !roadSet.has(b * W + a)) continue;
        const cx = Math.max(a - hw, Math.min(a + 1 - hw, x)), cz = Math.max(b - hd, Math.min(b + 1 - hd, z));
        best = Math.min(best, Math.hypot(x - cx, z - cz));
      }
    }
    return best;
  };
  const inside = (x: number, z: number, m: number) => Math.abs(x) <= hw - m && Math.abs(z) <= hd - m;

  // ---- the water
  const ponds: Pond[] = [];
  const wet = (x: number, z: number, m = 0) => ponds.some((p) => inPond(p, x, z, m));
  const m0 = Math.min(W, D);
  const pondFits = (p: Pond, gap: number): boolean => {
    for (let k = 0; k < PSEG; k++) {
      const [x, z] = pondEdge(p, (k / PSEG) * TAU);
      if (!inside(x, z, 0.75) || roadDist(x, z) < 0.6) return false;
      for (const q of ponds) if (q !== p && inPond(q, x, z, gap)) return false;
    }
    return roadDist(p.x, p.z) > 0.6 || !road;
  };
  const tryPond = (kind: PondKind, R: number, ax: number, az: number, rot: number, at?: P, tries = 40, gap = 0.9): Pond | null => {
    for (let t = 0; t < tries; t++) {
      const shrink = 1 - t / (tries * 1.6);
      const p: Pond = {
        x: at && t < 4 ? at[0] : (rng() - 0.5) * (W - 2 * R * ax - 1.5), z: at && t < 4 ? at[1] : (rng() - 0.5) * (D - 2 * R * az - 1.5),
        R: R * shrink, ax, az, rot, r: pondShape(rng, kind), kind, island: null,
      };
      if (pondFits(p, gap)) { ponds.push(p); return p; }
    }
    return null;
  };
  const along = alongX ? 0 : Math.PI / 2;
  const stretch = long ? 1.4 + rng() * 0.8 : 1 + rng() * 0.35;
  const lake = (R: number) => {
    const kind: PondKind = pickW(rng, theme === 'japanese' ? { lobed: 3, kidney: 2, chain: 2 } : theme === 'tropical' ? { lobed: 2, blob: 2, kidney: 1 } : { blob: 3, kidney: 2, chain: 2, lobed: 1 });
    const p = tryPond(kind === 'chain' ? 'blob' : kind, R, stretch, 1, along + (rng() - 0.5) * 0.8);
    if (p && kind === 'chain') {
      // a second basin joined to the first: a lake in two arms (Stow Lake, the Lake in Central Park)
      const a = rng() * TAU, [ex, ez] = pondEdge(p, a, -p.R * 0.25);
      tryPond('blob', p.R * (0.55 + rng() * 0.2), 1 + rng() * 0.4, 1, rng() * Math.PI, [ex, ez], 4, -10);
    }
    return p;
  };
  const roll = rng();
  if (theme === 'french') {
    if (roll < 0.5) tryPond('canal', Math.max(W, D) * (0.18 + rng() * 0.08), 1, 0.9, along, [0, 0], 20);
    if (roll > 0.3) tryPond(rng() < 0.5 ? 'basin' : 'quatrefoil', m0 * (0.09 + rng() * 0.05), 1, 1, 0, roll < 0.5 ? [alongX ? -hw * 0.6 : 0, alongX ? 0 : -hd * 0.6] : [0, 0], 20);
  } else if (theme === 'mediterranean' && roll < 0.45) {
    tryPond(rng() < 0.5 ? 'basin' : 'quatrefoil', m0 * (0.1 + rng() * 0.05), 1, 1, 0, [0, 0], 20);
  } else if (roll < (theme === 'prairie' ? 0.7 : theme === 'mediterranean' ? 0.9 : 0.94)) {
    const R = m0 * (theme === 'pinewood' ? 0.22 + rng() * 0.08 : theme === 'prairie' ? 0.13 + rng() * 0.06 : 0.17 + rng() * 0.08);
    lake(R);
    if (rng() < (theme === 'japanese' ? 0.5 : 0.3)) tryPond(rng() < 0.5 ? 'lobed' : 'blob', m0 * (0.08 + rng() * 0.05), 1 + rng() * 0.3, 1, rng() * Math.PI);
  }
  // an island in a big enough lake
  for (const p of ponds) {
    const small = p.R * Math.min(p.ax, p.az);
    if (p.kind === 'canal' || p.kind === 'basin' || p.kind === 'quatrefoil' || small < 1.3) continue;
    if (rng() > (theme === 'japanese' ? 0.7 : 0.45)) continue;
    const a = rng() * TAU, off = small * 0.25 * rng();
    const isl = { x: p.x + Math.cos(a) * off, z: p.z + Math.sin(a) * off, r: small * (0.26 + rng() * 0.1) };
    let fits = true;
    for (let k = 0; k < 12 && fits; k++) {
      const b = (k / 12) * TAU;
      if (!inPond({ ...p, island: null }, isl.x + Math.cos(b) * (isl.r + 0.3), isl.z + Math.sin(b) * (isl.r + 0.3))) fits = false;
    }
    if (fits) p.island = isl;
  }

  // ---- the meadows: open lawns the trees keep back from
  const meadows: Meadow[] = [];
  const nMeadow = theme === 'prairie' ? 3 + Math.floor(rng() * 2) : theme === 'french' ? 1 : 1 + Math.floor(rng() * 3);
  for (let n = 0, tries = 0; n < nMeadow && tries < 60; tries++) {
    const rx = m0 * (0.14 + rng() * 0.12) * (long ? 1.3 : 1), rz = m0 * (0.12 + rng() * 0.1);
    const m: Meadow = { x: (rng() - 0.5) * (W - 2 * rx - 1), z: (rng() - 0.5) * (D - 2 * rz - 1), rx, rz, rot: rng() * Math.PI, r: wobble(rng, 0.3, [2, 3]) };
    let ok = true;
    for (let k = 0; k < 16 && ok; k++) {
      const [x, z] = meadowEdge(m, (k / 16) * TAU);
      if (!inside(x, z, 0.4) || wet(x, z, 0.4)) ok = false;
    }
    if (ok && !wet(m.x, m.z, 0.6)) { meadows.push(m); n++; }
  }

  // ---- the footpaths
  const nodes: (P & { gate?: boolean })[] = [];
  const addNode = (x: number, z: number, gate = false): number => {
    nodes.push(Object.assign([x, z] as P, gate ? { gate } : {}));
    return nodes.length - 1;
  };
  const cand: [number, number, boolean, number][] = []; // a, b, main, bend
  const link = (a: number, b: number, main = false, bend = (rng() - 0.5) * 0.5) => { if (a !== b && a >= 0 && b >= 0) cand.push([a, b, main, bend]); };
  // the gates: a few along every side, clear of the corners and of where the drive comes in
  const gates: number[] = [];
  const roadEnds = road ? [road[0], road[road.length - 1]] : [];
  for (let side = 0; side < 4; side++) {
    const len = side % 2 === 0 ? D : W, n = Math.max(1, Math.round(len / 7));
    for (let g = 0; g < n; g++) {
      const t = -len / 2 + ((g + 0.5) / n) * len + (rng() - 0.5) * Math.min(2, len / (n * 3));
      const x = side === 0 ? hw - 0.02 : side === 2 ? -hw + 0.02 : Math.max(-hw + 1.2, Math.min(hw - 1.2, t));
      const z = side === 1 ? hd - 0.02 : side === 3 ? -hd + 0.02 : Math.max(-hd + 1.2, Math.min(hd - 1.2, t));
      if (roadEnds.some(([tx, tz]) => Math.hypot(tx + 0.5 - hw - x, tz + 0.5 - hd - z) < 1.6)) continue;
      if (roadDist(x, z) < 0.3 || wet(x, z, 0.5)) continue;
      gates.push(addNode(x, z, true));
    }
  }
  const free = (x: number, z: number, m = 0.45) => inside(x, z, 0.6) && !wet(x, z, m) && roadDist(x, z) > 0.35;
  const near = (from: P, among: number[]): number => {
    let best = -1, bd = Infinity;
    for (const j of among) { const d = Math.hypot(nodes[j][0] - from[0], nodes[j][1] - from[1]); if (d < bd) { bd = d; best = j; } }
    return best;
  };
  const inner: number[] = [];
  const ringOf = (cx: number, cz: number, rx: number, rz: number, n: number, main: boolean): number[] => {
    const ids: number[] = [];
    for (let k = 0; k < n; k++) {
      const a = (k / n) * TAU;
      const x = cx + Math.cos(a) * rx, z = cz + Math.sin(a) * rz;
      ids.push(free(x, z) ? addNode(x, z) : -1);
    }
    for (let k = 0; k < n; k++) {
      const a = ids[k], b = ids[(k + 1) % n];
      if (a >= 0 && b >= 0) link(a, b, main, 0.08);
    }
    const kept = ids.filter((i) => i >= 0);
    inner.push(...kept);
    return kept;
  };
  const scatter = (count: number, spacing: number) => {
    for (let t = 0, n = 0; n < count && t < count * 30; t++) {
      const x = (rng() - 0.5) * (W - 1.6), z = (rng() - 0.5) * (D - 1.6);
      if (!free(x, z) || inner.some((j) => Math.hypot(nodes[j][0] - x, nodes[j][1] - z) < spacing)) continue;
      inner.push(addNode(x, z));
      n++;
    }
  };
  const knit = (k: number, reach: number, bend: number) => {
    for (const a of inner) {
      const by = inner.filter((b) => b !== a).sort((p, q) => Math.hypot(nodes[p][0] - nodes[a][0], nodes[p][1] - nodes[a][1]) - Math.hypot(nodes[q][0] - nodes[a][0], nodes[q][1] - nodes[a][1]));
      for (const b of by.slice(0, k)) if (Math.hypot(nodes[b][0] - nodes[a][0], nodes[b][1] - nodes[a][1]) < reach) link(a, b, false, (rng() - 0.5) * bend);
    }
  };
  const A = Math.max(W, D), C = Math.min(W, D);
  const axisPt = (s: number, u: number): P => (alongX ? [s, u] : [u, s]);
  switch (design) {
    case 'loops': scatter(Math.max(5, Math.round((W * D) / 16)), 2.4); knit(3, 5, 0.8); break;
    case 'web': scatter(Math.max(7, Math.round((W * D) / 10)), 1.9); knit(3, 4.2, 0.3); break;
    case 'radial': {
      const hub = free(0, 0, 0.6) ? addNode(0, 0) : -1;
      const ring = ringOf(0, 0, hw * 0.62, hd * 0.62, 10 + 2 * Math.floor(rng() * 3), true);
      if (hub >= 0) { inner.push(hub); ring.forEach((r, k) => { if (k % 2 === 0) link(hub, r, true, 0); }); }
      if (A > C * 1.4) ringOf(0, 0, hw * 0.3, hd * 0.3, 8, false);
      break;
    }
    case 'grid': {
      const ns = Math.max(3, Math.round(A / 4.5)), nu = C >= 9 ? 3 : 2;
      const ids: number[][] = [];
      for (let i = 0; i < ns; i++) {
        ids.push([]);
        for (let j = 0; j < nu; j++) {
          const s = -A / 2 + ((i + 0.5) / ns) * A, u = -C / 2 + ((j + 0.5) / nu) * C;
          const [x, z] = axisPt(s, u);
          const id = free(x, z, 0.35) ? addNode(x, z) : -1;
          ids[i].push(id);
          if (id >= 0) inner.push(id);
        }
      }
      for (let i = 0; i < ns; i++) for (let j = 0; j < nu; j++) {
        if (i + 1 < ns) link(ids[i][j], ids[i + 1][j], j === Math.floor(nu / 2), 0);
        if (j + 1 < nu) link(ids[i][j], ids[i][j + 1], false, 0);
        // the diagonals of a patte d'oie, now and then
        if (i + 1 < ns && j + 1 < nu && rng() < 0.3) link(ids[i][j], ids[i + 1][j + 1], false, 0);
      }
      break;
    }
    case 'figure8': {
      const off = A * 0.22;
      for (const sg of [-1, 1]) {
        const [cx, cz] = axisPt(sg * off, (rng() - 0.5) * C * 0.1);
        ringOf(cx, cz, alongX ? Math.min(off * 0.95, A * 0.22) : C * 0.32, alongX ? C * 0.32 : Math.min(off * 0.95, A * 0.22), 9, true);
      }
      scatter(2, 2.5);
      break;
    }
    case 'serpentine': {
      const n = Math.max(4, Math.round(A / 2.4)), amp = C * (0.18 + rng() * 0.12), ph = rng() * TAU, waves = 1 + rng() * 1.5;
      let prev = -1;
      for (let i = 0; i <= n; i++) {
        const s = -A / 2 + 0.9 + (i / n) * (A - 1.8);
        const [x, z] = axisPt(s, Math.sin(ph + (i / n) * waves * TAU) * amp);
        if (!free(x, z)) { prev = -1; continue; }
        const id = addNode(x, z);
        inner.push(id);
        if (prev >= 0) link(prev, id, true, (rng() - 0.5) * 0.3);
        prev = id;
      }
      scatter(Math.max(2, Math.round((W * D) / 40)), 2.6);
      knit(2, 4.5, 0.6);
      break;
    }
  }
  // a walk round the shore of each lake, joined to the paths near it
  for (const p of ponds) {
    if (p.kind === 'canal') continue;
    const n = Math.max(8, Math.round(Math.PI * 2 * p.R * Math.max(p.ax, p.az) / 1.2));
    const ids: number[] = [];
    for (let k = 0; k < n; k++) {
      const [x, z] = pondEdge(p, (k / n) * TAU, 0.42);
      const ok = inside(x, z, 0.35) && roadDist(x, z) > 0.3 && !ponds.some((q) => q !== p && inPond(q, x, z, 0.35));
      ids.push(ok ? addNode(x, z) : -1);
    }
    for (let k = 0; k < n; k++) if (ids[k] >= 0 && ids[(k + 1) % n] >= 0) link(ids[k], ids[(k + 1) % n], false, 0.02);
    inner.push(...ids.filter((i) => i >= 0));
  }
  // every gate leads in to the nearest path
  for (const g of gates) link(g, near(nodes[g], inner), false, (rng() - 0.5) * 0.4);

  // lay every link as a curve, bent clear of the water if it can be, bridged if the theme bridges, dropped if neither
  const paths: ParkPath[] = [];
  const edges: [number, number][] = [];
  const done = new Set<string>();
  const curve = (a: P, b: P, bend: number): P[] => {
    const L = Math.hypot(b[0] - a[0], b[1] - a[1]);
    const n = Math.max(2, Math.ceil(L / 0.35));
    const cx = (a[0] + b[0]) / 2 - ((b[1] - a[1]) / (L || 1)) * bend * L, cz = (a[1] + b[1]) / 2 + ((b[0] - a[0]) / (L || 1)) * bend * L;
    const out: P[] = [];
    for (let i = 0; i <= n; i++) {
      const t = i / n, u = 1 - t;
      out.push([u * u * a[0] + 2 * u * t * cx + t * t * b[0], u * u * a[1] + 2 * u * t * cz + t * t * b[1]]);
    }
    return out;
  };
  const laid: P[][] = [];
  const crossesLaid = (pts: P[]): boolean => {
    for (const q of laid) {
      for (let i = 1; i < pts.length; i++) {
        for (let j = 1; j < q.length; j++) if (segsCross(pts[i - 1], pts[i], q[j - 1], q[j])) return true;
      }
    }
    return false;
  };
  const tryLay = (a: number, b: number, main: boolean, bend: number, strict: boolean): boolean => {
    const key = a < b ? `${a},${b}` : `${b},${a}`;
    if (done.has(key)) return true;
    const A0 = nodes[a], B0 = nodes[b];
    if (Math.hypot(A0[0] - B0[0], A0[1] - B0[1]) < 0.3) return false;
    for (const bd of [bend, -bend, bend + 0.25, -bend - 0.25, 0.5, -0.5, 0]) {
      const pts = curve(A0, B0, bd);
      if (pts.some(([x, z], i) => !inside(x, z, i === 0 || i === pts.length - 1 ? 0 : 0.12) || wet(x, z, 0.12))) continue;
      if (strict && crossesLaid(pts)) continue;
      paths.push({ pts, w: main ? 0.26 : 0.17, bridge: pts.map(() => false), main });
      laid.push(pts);
      edges.push([a, b]);
      done.add(key);
      return true;
    }
    if (BRIDGES[theme]) {
      const pts = curve(A0, B0, 0);
      const over = pts.map(([x, z]) => wet(x, z, 0.1));
      let span = 0;
      for (let i = 0; i < pts.length; i++) if (over[i]) span += 0.35;
      // a short crossing of one stretch of water, with dry ground at both ends
      const runs = over.reduce((n, v, i) => n + (v && !over[i - 1] ? 1 : 0), 0);
      if (span <= 2.4 && runs === 1 && !over[0] && !over[pts.length - 1] && pts.every(([x, z]) => inside(x, z, 0.05)) && (!strict || !crossesLaid(pts))) {
        paths.push({ pts, w: main ? 0.26 : 0.18, bridge: over, main });
        laid.push(pts);
        edges.push([a, b]);
        done.add(key);
        return true;
      }
    }
    return false;
  };
  // main paths first, then the rest; a path may not cross another one already laid (they meet at nodes)
  cand.sort((p, q) => Number(q[2]) - Number(p[2]));
  for (const [a, b, main, bend] of cand) tryLay(a, b, main, bend, !main);

  // stitch: every piece joined to the biggest, nearest pair first; a piece that can't be joined is dropped
  const used = (): number[] => [...new Set(edges.flat())];
  for (let round = 0; round < 40; round++) {
    const parent = new Map<number, number>();
    const find = (i: number): number => { while (parent.get(i)! !== i) i = parent.get(i)!; return i; };
    for (const i of used()) parent.set(i, i);
    for (const [a, b] of edges) parent.set(find(a), find(b));
    const comps = new Map<number, number[]>();
    for (const i of used()) { const r = find(i); comps.set(r, [...(comps.get(r) ?? []), i]); }
    if (comps.size <= 1) break;
    const sorted = [...comps.values()].sort((p, q) => q.length - p.length);
    const main = sorted[0], rest = sorted.slice(1).flat();
    const pairs: [number, number, number][] = [];
    for (const a of rest) for (const b of main) pairs.push([a, b, Math.hypot(nodes[a][0] - nodes[b][0], nodes[a][1] - nodes[b][1])]);
    pairs.sort((p, q) => p[2] - q[2]);
    let joined = false;
    for (const [a, b] of pairs.slice(0, 24)) if (tryLay(a, b, false, (rng() - 0.5) * 0.3, false)) { joined = true; break; }
    if (!joined) {
      // drop the smallest piece that will not join
      const drop = new Set(sorted[sorted.length - 1]);
      for (let k = edges.length - 1; k >= 0; k--) {
        if (drop.has(edges[k][0])) { edges.splice(k, 1); paths.splice(k, 1); laid.splice(k, 1); }
      }
    }
  }
  const deg = new Map<number, number>();
  for (const [a, b] of edges) { deg.set(a, (deg.get(a) ?? 0) + 1); deg.set(b, (deg.get(b) ?? 0) + 1); }
  const junctions: [number, number, number][] = [];
  for (const [i, n] of deg) if (n >= 3 && !nodes[i].gate) junctions.push([nodes[i][0], nodes[i][1], n]);

  // ---- a raster of what is taken (paths, water, the drive), an eighth of a tile a cell
  const R8 = 8, GW = W * R8, GD = D * R8;
  const busy = new Uint8Array(GW * GD);
  const cellOf = (x: number, z: number) => {
    const gx = Math.floor((x + hw) * R8), gz = Math.floor((z + hd) * R8);
    return gx < 0 || gz < 0 || gx >= GW || gz >= GD ? -1 : gz * GW + gx;
  };
  const stamp = (x: number, z: number, r: number) => {
    const g = Math.ceil(r * R8);
    const gx = Math.floor((x + hw) * R8), gz = Math.floor((z + hd) * R8);
    for (let dz = -g; dz <= g; dz++) for (let dx = -g; dx <= g; dx++) {
      if (dx * dx + dz * dz > g * g) continue;
      const a = gx + dx, b = gz + dz;
      if (a >= 0 && b >= 0 && a < GW && b < GD) busy[b * GW + a] = 1;
    }
  };
  for (const p of paths) for (const [x, z] of p.pts) stamp(x, z, p.w / 2 + 0.05);
  const taken = (x: number, z: number) => { const c = cellOf(x, z); return c < 0 || busy[c] === 1; };
  const features: Feature[] = [];
  /** A free round spot of radius r: on the lot, off the water, the drive, the paths and anything already put down. */
  const spot = (x: number, z: number, r: number, pathGap = 0.12): boolean => {
    if (!inside(x, z, r + 0.15) || wet(x, z, r + 0.15) || roadDist(x, z) < r + 0.25) return false;
    for (let k = 0; k < 9; k++) {
      const a = (k / 8) * TAU, rr = k === 8 ? 0 : r + pathGap;
      if (taken(x + Math.cos(a) * rr, z + Math.sin(a) * rr)) return false;
    }
    return !features.some((f) => Math.hypot(f.x - x, f.z - z) < f.r + r + 0.1);
  };
  const place = (kind: FeatureKind, r: number, where: () => P | null, tries = 60, yaw?: number): Feature | null => {
    for (let t = 0; t < tries; t++) {
      const p = where();
      if (!p || !spot(p[0], p[1], r)) continue;
      const f: Feature = { kind, x: p[0], z: p[1], yaw: yaw ?? Math.round(rng() * 4) * (Math.PI / 2), r };
      features.push(f);
      stamp(f.x, f.z, r);
      return f;
    }
    return null;
  };
  const anywhere = (): P => [(rng() - 0.5) * (W - 1.5), (rng() - 0.5) * (D - 1.5)];
  const byPath = (gap: number) => (): P | null => {
    const p = paths[Math.floor(rng() * paths.length)];
    if (!p) return null;
    const i = Math.floor(rng() * (p.pts.length - 1)), [ax, az] = p.pts[i], [bx, bz] = p.pts[i + 1];
    const L = Math.hypot(bx - ax, bz - az) || 1, sg = rng() < 0.5 ? -1 : 1;
    return [ax - ((bz - az) / L) * sg * (p.w / 2 + gap), az + ((bx - ax) / L) * sg * (p.w / 2 + gap)];
  };

  // the hub: where a radial or formal park's main paths meet, a plaza with a fountain or an obelisk
  const hub = junctions.reduce<[number, number, number] | null>((b, j) => (!b || j[2] > b[2] || (j[2] === b[2] && Math.hypot(j[0], j[1]) < Math.hypot(b[0], b[1])) ? j : b), null);
  if (hub && (design === 'radial' || design === 'grid' || theme === 'french' || theme === 'mediterranean' || rng() < 0.4)) {
    const r = design === 'radial' || theme === 'french' ? 0.62 : 0.45;
    if (inside(hub[0], hub[1], r + 0.2) && !wet(hub[0], hub[1], r + 0.2) && roadDist(hub[0], hub[1]) > r + 0.2) {
      features.push({ kind: 'plaza', x: hub[0], z: hub[1], yaw: 0, r });
      const k: FeatureKind = theme === 'french' ? (rng() < 0.6 ? 'fountain' : 'obelisk') : theme === 'japanese' ? 'statue' : rng() < 0.6 ? 'fountain' : 'statue';
      features.push({ kind: k, x: hub[0], z: hub[1], yaw: 0, r: 0.01 });
    }
  }
  // a boathouse on the shore of the biggest lake, a tea house or a gazebo on another bank, a temple on the island
  const bigLake = ponds.filter((p) => p.kind !== 'basin' && p.kind !== 'quatrefoil' && p.kind !== 'canal').sort((a, b) => b.R * b.ax - a.R * a.ax)[0];
  if (bigLake) {
    const shore = (out: number) => (): P => pondEdge(bigLake, rng() * TAU, out);
    if (theme !== 'japanese' && theme !== 'prairie') {
      // half in the water: it stands on the bank and its slip runs out over the lake
      for (let t = 0; t < 40; t++) {
        const a = rng() * TAU, [x, z] = pondEdge(bigLake, a, 0.22), [ix, iz] = pondEdge(bigLake, a, -0.4);
        if (!inside(x, z, 0.6) || roadDist(x, z) < 0.8 || taken(x, z)) continue;
        if (features.some((f) => Math.hypot(f.x - x, f.z - z) < f.r + 0.7)) continue;
        // the slip points out over the water
        const yaw = Math.atan2(ix - x, iz - z);
        features.push({ kind: 'boathouse', x, z, yaw, r: 0.42 });
        stamp(x, z, 0.4);
        break;
      }
    }
    if (theme === 'japanese') place('teahouse', 0.42, shore(0.75), 60);
    else if (rng() < 0.5) place('gazebo', 0.3, shore(0.65), 40);
    if (bigLake.island && bigLake.island.r > 0.45) {
      const i = bigLake.island;
      features.push({ kind: theme === 'japanese' ? 'pagoda' : theme === 'tropical' ? 'kiosk' : 'temple', x: i.x, z: i.z, yaw: rng() * TAU, r: Math.min(0.32, i.r * 0.6) });
    }
  }
  // the park's buildings and set pieces, by theme
  if (theme === 'english' || theme === 'prairie' || theme === 'pinewood' || rng() < 0.25) place('bandstand', 0.38, byPath(0.38 + 0.3), 80);
  if ((theme === 'english' || theme === 'tropical') && rng() < 0.6) place('glasshouse', 0.75, byPath(0.75 + 0.3), 120);
  if (theme === 'japanese') place('pagoda', 0.3, anywhere);
  if (theme === 'french' || theme === 'mediterranean') place('obelisk', 0.18, byPath(0.18 + 0.3), 80);
  if (theme !== 'japanese' && theme !== 'french' && rng() < 0.6) place('playground', 0.6, byPath(0.6 + 0.3), 100);
  if (rng() < 0.7) place('kiosk', 0.2, byPath(0.2 + 0.3), 80);
  if (theme !== 'japanese') for (let n = 0; n < 2; n++) place('statue', 0.12, byPath(0.12 + 0.3), 60);

  // ---- the open ground: a ball field or two, a pitch, and the lawns
  const fields: Field[] = [];
  const wantFields = theme === 'french' || theme === 'japanese' ? 0 : theme === 'prairie' ? 2 : 1 + (rng() < 0.5 ? 1 : 0);
  for (let n = 0, t = 0; n < wantFields && t < 80; t++) {
    const big = rng() < 0.5, fw = big ? 2.6 : 2.0, fd = big ? 1.7 : 1.4, yaw = alongX ? 0 : Math.PI / 2;
    const [x, z] = anywhere();
    const ex = alongX ? fw / 2 : fd / 2, ez = alongX ? fd / 2 : fw / 2;
    let ok = inside(x, z, Math.max(ex, ez) + 0.3);
    for (let gz = -ez; gz <= ez && ok; gz += 0.25) for (let gx = -ex; gx <= ex && ok; gx += 0.25) {
      if (taken(x + gx, z + gz) || wet(x + gx, z + gz, 0.2) || roadDist(x + gx, z + gz) < 0.3) ok = false;
    }
    if (!ok || features.some((f) => Math.abs(f.x - x) < ex + f.r + 0.2 && Math.abs(f.z - z) < ez + f.r + 0.2)) continue;
    fields.push({ x, z, w: fw, d: fd, yaw, kind: big ? 'pitch' : 'ball' });
    for (let gz = -ez; gz <= ez; gz += 0.2) for (let gx = -ex; gx <= ex; gx += 0.2) stamp(x + gx, z + gz, 0.15);
    n++;
  }

  // ---- beds and hedges
  const beds: Bed[] = [];
  const hedges: { x: number; z: number; r: number }[] = [];
  const BED_COLS = theme === 'tropical' ? [0xe2412f, 0xf28c38, 0xe86a92, 0xf2c14e, 0xb07ad8] : theme === 'mediterranean' ? [0x9a7fd0, 0xb07ad8, 0xf2c14e, 0xe8e2d4]
    : theme === 'french' ? [0xe86a92, 0xe2412f, 0xf4f2ec, 0xf2c14e, 0x8a7fd0] : [0xe86a92, 0xf2c14e, 0xffffff, 0xb07ad8, 0xf28c38, 0xe2412f];
  const bedCol = () => BED_COLS[Math.floor(rng() * BED_COLS.length)];
  if (theme === 'french' || (theme === 'mediterranean' && rng() < 0.6)) {
    // parterres: hedged rectangles of flowers either side of the main axis
    for (let t = 0, n = 0; t < 80 && n < 8; t++) {
      const bw = 1.1 + rng() * 0.6, bd = 0.7 + rng() * 0.4;
      const [x, z] = anywhere();
      let ok = inside(x, z, Math.max(bw, bd) / 2 + 0.3);
      for (let gz = -bd / 2 - 0.1; gz <= bd / 2 + 0.1 && ok; gz += 0.2) for (let gx = -bw / 2 - 0.1; gx <= bw / 2 + 0.1 && ok; gx += 0.2) {
        if (taken(x + gx, z + gz) || wet(x + gx, z + gz, 0.1) || roadDist(x + gx, z + gz) < 0.2) ok = false;
      }
      if (!ok || features.some((f) => Math.abs(f.x - x) < bw / 2 + f.r + 0.15 && Math.abs(f.z - z) < bd / 2 + f.r + 0.15)) continue;
      beds.push({ x, z, w: bw, d: bd, col: bedCol(), hedge: true, round: false });
      for (let gz = -bd / 2; gz <= bd / 2; gz += 0.2) for (let gx = -bw / 2; gx <= bw / 2; gx += 0.2) stamp(x + gx, z + gz, 0.15);
      n++;
    }
  }
  const nRound = theme === 'japanese' || theme === 'pinewood' ? 0 : theme === 'tropical' ? 7 : theme === 'prairie' ? 1 : 4;
  for (let n = 0; n < nRound; n++) {
    for (let t = 0; t < 30; t++) {
      const [x, z] = byPath(0.75)() ?? anywhere();
      const r = 0.25 + rng() * 0.25;
      if (!spot(x, z, r)) continue;
      beds.push({ x, z, w: r * 2, d: r * 2 * (0.7 + rng() * 0.6), col: bedCol(), hedge: false, round: true });
      stamp(x, z, r);
      break;
    }
  }
  // the hub plaza of a French park gets a hedge ring
  if (theme === 'french') for (const f of features) if (f.kind === 'plaza') hedges.push({ x: f.x, z: f.z, r: f.r + 0.12 });

  // ---- benches and lamps along the paths
  for (const p of paths) {
    let run = 0.8 + rng();
    for (let i = 1; i < p.pts.length; i++) {
      const [ax, az] = p.pts[i - 1], [bx, bz] = p.pts[i];
      const L = Math.hypot(bx - ax, bz - az);
      run -= L;
      if (run > 0 || p.bridge[i]) continue;
      run = p.main ? 1.6 + rng() * 1.2 : 2.6 + rng() * 2;
      const sg = rng() < 0.5 ? -1 : 1, nx = -((bz - az) / (L || 1)) * sg, nz = ((bx - ax) / (L || 1)) * sg;
      const kind: FeatureKind = rng() < (p.main ? 0.45 : 0.25) ? 'lamp' : 'bench';
      const x = bx + nx * (p.w / 2 + 0.1), z = bz + nz * (p.w / 2 + 0.1);
      if (!inside(x, z, 0.15) || wet(x, z, 0.1) || roadDist(x, z) < 0.15) continue;
      if (features.some((f) => Math.hypot(f.x - x, f.z - z) < f.r + 0.2)) continue;
      // a bench faces the path
      features.push({ kind, x, z, yaw: Math.atan2(-nx, -nz), r: 0.1 });
    }
  }
  for (const f of features) if (f.kind === 'bench' || f.kind === 'lamp') stamp(f.x, f.z, 0.12);

  // ---- the planting
  const plants: Plant[] = [];
  const trees: P[] = [];
  const treeOk = (x: number, z: number, gap: number, wetGap = 0.32): boolean => {
    if (!inside(x, z, 0.25) || wet(x, z, wetGap) || roadDist(x, z) < 0.38 || taken(x, z)) return false;
    for (let k = 0; k < 4; k++) if (taken(x + DIRS[k][0] * 0.22, z + DIRS[k][1] * 0.22)) return false;
    if (fields.some((f) => Math.abs(x - f.x) < (f.yaw ? f.d : f.w) / 2 + 0.35 && Math.abs(z - f.z) < (f.yaw ? f.w : f.d) / 2 + 0.35)) return false;
    if (features.some((f) => Math.hypot(f.x - x, f.z - z) < f.r + 0.3)) return false;
    return !trees.some(([tx, tz]) => Math.hypot(tx - x, tz - z) < gap);
  };
  const MIX: Record<ParkTheme, Partial<Record<TreeKind, number>>> = {
    english: { oak: 4, round: 3, birch: 1, poplar: 1, cherry: 0.6 },
    french: { round: 3, poplar: 3, oak: 1, cypress: 1 },
    japanese: { cherry: 4, pine: 2, windPine: 2, round: 1, bamboo: 1.2 },
    prairie: { oak: 3, round: 2, birch: 1, poplar: 1 },
    tropical: { palm: 4, canopy: 2, datePalm: 1.5, bamboo: 1, round: 1 },
    pinewood: { pine: 4, stonePine: 2, birch: 2, spruce: 1.5, oak: 1 },
    mediterranean: { stonePine: 3, cypress: 3, olive: 3, palm: 1 },
  };
  const shoreTree: Partial<Record<ParkTheme, TreeKind>> = { english: 'willow', japanese: 'cherry', tropical: 'palm', prairie: 'willow', pinewood: 'birch', mediterranean: 'cypress', french: 'poplar' };
  const addTree = (kind: TreeKind, x: number, z: number) => {
    trees.push([x, z]);
    plants.push({ kind, x, z, s: 0.85 + rng() * 0.45, yaw: rng() * TAU });
  };
  const dense = theme === 'pinewood' ? 1.15 : theme === 'prairie' ? 0.45 : theme === 'french' ? 0.7 : 0.85;
  const cap = Math.round(W * D * 0.8 * dense);
  // allées: straight main paths in a formal park are lined with trees both sides
  if (theme === 'french' || theme === 'mediterranean' || (design === 'grid' && rng() < 0.7) || (design === 'radial' && rng() < 0.5)) {
    const kind: TreeKind = theme === 'mediterranean' ? 'cypress' : theme === 'french' ? (rng() < 0.5 ? 'poplar' : 'round') : 'round';
    for (const p of paths) {
      if (!p.main) continue;
      let run = 0.3;
      for (let i = 1; i < p.pts.length; i++) {
        const [ax, az] = p.pts[i - 1], [bx, bz] = p.pts[i], L = Math.hypot(bx - ax, bz - az);
        run -= L;
        if (run > 0) continue;
        run = 0.75;
        for (const sg of [-1, 1]) {
          const x = bx - ((bz - az) / (L || 1)) * sg * (p.w / 2 + 0.32), z = bz + ((bx - ax) / (L || 1)) * sg * (p.w / 2 + 0.32);
          if (treeOk(x, z, 0.5)) addTree(kind, x, z);
        }
      }
    }
  }
  // the water's edge
  for (const p of ponds) {
    const k = shoreTree[theme];
    if (!k || p.kind === 'canal' || p.kind === 'basin' || p.kind === 'quatrefoil') continue;
    const n = Math.round(p.R * Math.max(p.ax, p.az) * 2.2);
    for (let i = 0; i < n; i++) {
      const [x, z] = pondEdge(p, rng() * TAU, 0.35 + rng() * 0.35);
      if (treeOk(x, z, 0.6, 0.22)) addTree(k, x, z);
    }
    if (p.island) {
      const i = p.island;
      for (let t = 0; t < 4; t++) {
        const a = rng() * TAU, rr = i.r * (0.3 + rng() * 0.5), x = i.x + Math.cos(a) * rr, z = i.z + Math.sin(a) * rr;
        if (Math.hypot(x - i.x, z - i.z) < i.r - 0.15 && !features.some((f) => Math.hypot(f.x - x, f.z - z) < f.r + 0.2) && !trees.some(([tx, tz]) => Math.hypot(tx - x, tz - z) < 0.45)) {
          trees.push([x, z]);
          plants.push({ kind: k, x, z, s: 0.8 + rng() * 0.3, yaw: rng() * TAU });
        }
      }
    }
  }
  // groves: stands of one or two kinds, the meadows kept open between them
  const groves = Math.max(3, Math.round((W * D) / 22));
  for (let g = 0; g < groves && trees.length < cap; g++) {
    const [gx, gz] = anywhere();
    if (meadows.some((m) => inMeadow(m, gx, gz, -0.2))) continue;
    const k1 = pickW(rng, MIX[theme]), k2 = pickW(rng, MIX[theme]);
    const R = 0.9 + rng() * (theme === 'pinewood' ? 2.2 : 1.6), n = Math.round(R * R * 2.4 * dense);
    for (let t = 0; t < n * 3 && trees.length < cap; t++) {
      const a = rng() * TAU, rr = Math.sqrt(rng()) * R, x = gx + Math.cos(a) * rr, z = gz + Math.sin(a) * rr;
      if (meadows.some((m) => inMeadow(m, x, z, 0.1)) || !treeOk(x, z, 0.5)) continue;
      addTree(rng() < 0.7 ? k1 : k2, x, z);
    }
  }
  // and a scatter of single trees over the rest, a lone one now and then out on a meadow
  for (let t = 0; t < W * D * 2 && trees.length < cap; t++) {
    const [x, z] = anywhere();
    const onMeadow = meadows.some((m) => inMeadow(m, x, z, 0));
    if (onMeadow && rng() > 0.04) continue;
    if (!onMeadow && rng() > 0.35) continue;
    if (treeOk(x, z, onMeadow ? 1.6 : 0.7)) addTree(pickW(rng, MIX[theme]), x, z);
  }
  // the low planting: reeds at the water, shrubs in the borders, flowers in the grass, lanterns by the paths
  const low = (kind: PlantKind, x: number, z: number, s = 1, tint?: [number, number, number]) => {
    plants.push({ kind, x, z, s, yaw: rng() * TAU, ...(tint ? { tint } : {}) });
  };
  for (const p of ponds) {
    if (p.kind === 'canal' || p.kind === 'basin' || p.kind === 'quatrefoil') continue;
    for (let i = 0, n = Math.round(p.R * Math.max(p.ax, p.az) * 3); i < n; i++) {
      const [x, z] = pondEdge(p, rng() * TAU, -0.05 + rng() * 0.18);
      if (inside(x, z, 0.3) && !taken(x, z) && roadDist(x, z) > 0.3) low('reeds', x, z, 0.8 + rng() * 0.5);
    }
  }
  const LAVENDER: [number, number, number] = [0.66, 0.5, 0.95];
  const FLOWERS: [number, number, number][] = [[1.0, 0.86, 0.22], [1.0, 0.98, 0.94], [0.72, 0.52, 0.95], [1.0, 0.6, 0.78], [1.0, 0.45, 0.35]];
  const lowCount = Math.round(W * D * (theme === 'prairie' ? 0.9 : 0.35));
  for (let t = 0, n = 0; t < lowCount * 4 && n < lowCount; t++) {
    const [x, z] = anywhere();
    if (!inside(x, z, 0.2) || wet(x, z, 0.15) || roadDist(x, z) < 0.3 || taken(x, z)) continue;
    if (features.some((f) => Math.hypot(f.x - x, f.z - z) < f.r + 0.15)) continue;
    if (fields.some((f) => Math.abs(x - f.x) < (f.yaw ? f.d : f.w) / 2 + 0.2 && Math.abs(z - f.z) < (f.yaw ? f.w : f.d) / 2 + 0.2)) continue;
    const onMeadow = meadows.some((m) => inMeadow(m, x, z, 0));
    let kind: PlantKind;
    switch (theme) {
      // (a field crop's model fills a whole tile, too big for a clump of flowers: the wild flowers are tufts, tinted)
      case 'prairie': kind = onMeadow ? 'tuft' : rng() < 0.5 ? 'tuft' : 'shrub'; break;
      case 'japanese': kind = rng() < 0.4 ? 'rock' : rng() < 0.5 ? 'shrub' : 'fern'; if (onMeadow) continue; break;
      case 'tropical': kind = rng() < 0.6 ? 'fern' : 'shrub'; if (onMeadow) continue; break;
      case 'pinewood': kind = rng() < 0.5 ? 'fern' : rng() < 0.5 ? 'heather' : 'rock'; break;
      case 'mediterranean': kind = rng() < 0.55 ? 'tuft' : 'shrub'; if (onMeadow && rng() < 0.6) continue; break;
      case 'french': kind = 'shrub'; if (onMeadow) continue; break;
      default: kind = onMeadow ? 'tuft' : rng() < 0.6 ? 'shrub' : 'tuft';
    }
    low(kind, x, z, kind === 'rock' ? 0.5 + rng() * 0.6 : 0.8 + rng() * 0.5, kind === 'tuft' ? (theme === 'mediterranean' ? LAVENDER : FLOWERS[Math.floor(rng() * FLOWERS.length)]) : undefined);
    n++;
  }
  if (theme === 'japanese') {
    for (const p of paths) {
      for (let i = 4; i < p.pts.length; i += 7) {
        const [ax, az] = p.pts[i - 1], [bx, bz] = p.pts[i], L = Math.hypot(bx - ax, bz - az) || 1;
        const x = bx - ((bz - az) / L) * (p.w / 2 + 0.16), z = bz + ((bx - ax) / L) * (p.w / 2 + 0.16);
        if (p.bridge[i] || !inside(x, z, 0.2) || wet(x, z, 0.1) || roadDist(x, z) < 0.25) continue;
        if (features.some((f) => Math.hypot(f.x - x, f.z - z) < f.r + 0.15)) continue;
        low('stoneLantern', x, z, 0.9);
      }
    }
  }

  return {
    W, D, theme, design, road, roadSet, ponds, meadows, fields, paths, junctions, beds, hedges, features, plants,
    graph: { nodes: nodes.map((n) => [n[0], n[1]] as P), edges },
  };
}

// ---- what the park is solid in, for the car (world/footprint.ts) -------------------------------------------

/** The water, and the buildings that stand on the lot; the lawns, the paths and the drive are open. */
export function parkSolid(p: ParkPlan): (x: number, z: number) => boolean {
  const solid = p.features.filter((f) => f.kind === 'boathouse' || f.kind === 'glasshouse' || f.kind === 'teahouse' || f.kind === 'bandstand' || f.kind === 'pagoda' || f.kind === 'temple');
  return (x, z) => p.ponds.some((q) => inPond(q, x, z, 0)) || solid.some((f) => Math.hypot(f.x - x, f.z - z) < f.r);
}

// ---- the planting in a chunk, in world tiles (render/props.ts) ---------------------------------------------

/** A plant of a great park, placed in world tiles. */
interface ParkPlant { kind: PlantKind; x: number; z: number; s: number; yaw: number; tint?: [number, number, number] }

/** Local to world, as townMesh's Kit.place turns a model by its facing. */
export function parkToWorld(b: Building, lx: number, lz: number): [number, number] {
  const yaw = Math.atan2(DIRS[b.facing][0], DIRS[b.facing][1]), c = Math.cos(yaw), s = Math.sin(yaw);
  return [b.x + b.w / 2 + lx * c + lz * s, b.z + b.d / 2 - lx * s + lz * c];
}

/** Every great park standing in a world. */
export function greatParks(w: World): Building[] {
  const out: Building[] = [];
  for (const t of w.towns) for (const b of t.buildings) if (b.kind === 'greatPark' && !b.gone) out.push(b);
  return out;
}

/**
 * The trees and low planting of every great park on this chunk's tiles, kept off any tile the player has cleared
 * or a road has since been laid over.
 */
export function chunkParkProps(w: World, x0: number, z0: number, size: number): ParkPlant[] {
  const out: ParkPlant[] = [];
  for (const t of w.towns) {
    if (t.x0 > x0 + size + 4 || t.z0 > z0 + size + 4 || t.x0 + t.size < x0 - 4 || t.z0 + t.size < z0 - 4) continue;
    for (const b of t.buildings) {
      if (b.kind !== 'greatPark' || b.gone) continue;
      if (b.x > x0 + size || b.z > z0 + size || b.x + b.w < x0 || b.z + b.d < z0) continue;
      const p = planOf(b);
      for (const pl of p.plants) {
        const [x, z] = parkToWorld(b, pl.x, pl.z);
        const tx = Math.floor(x), tz = Math.floor(z);
        if (tx < x0 || tz < z0 || tx >= x0 + size || tz >= z0 + size || tx < 0 || tz < 0 || tx >= N || tz >= N) continue;
        const i = idx(tx, tz);
        if (w.cleared[i] || w.road[i]) continue;
        out.push({ kind: pl.kind, x, z, s: pl.s, yaw: pl.yaw, ...(pl.tint ? { tint: pl.tint } : {}) });
      }
    }
  }
  return out;
}
