/** Every plan, in the registry's order. */
export const PLAN_IDS = Object.keys(PLAN_INFO) as PlanId[];

/** The plans a town of this size may take, in the registry's order (today's three left out: they are the rolls' floor). */
export function plansFor(kind: 'mega' | 'metro' | 'city'): PlanId[] {
  return PLAN_IDS.filter((id) => id !== 'grid' && id !== 'strip' && PLAN_INFO[id].tiers.includes(kind));
}
