import * as THREE from 'three';
import type { RGB } from '../world/biomes';
import { xrayShader } from './xray';
import { eventLightShader } from './eventLights';

/**
 * When something glows: [on hour, off hour, strength]. Hours run 12..36 so an evening can carry on
 * past midnight (25 = 1 am, 30 = 6 am). An on hour after the off hour never lights.
 */
export type Sched = [number, number, number];
export const NEVER: Sched = [99, 0, 0];

/**
 * Shared by every night-light material; the day/night cycle writes them each frame. `uFlick` is a town whose lights
 * stutter in sevens after Still Waters' blackout (game/story.ts, 0.7.0): its middle (world x, z), radius and 1 while
 * it lasts; `uClock` the seconds it counts by.
 */
export const NIGHT = { uHour: { value: 8 }, uNight: { value: 0 }, uFlick: { value: new THREE.Vector4(0, 0, 0, 0) }, uClock: { value: 0 } };

/**
 * Parts of a building that only show at some times: a fairground that comes for the summer, market
 * stalls on market days, an outdoor rink in winter, a bandstand lit on weekend evenings. Every vertex
 * carries one of these tags, and the clock switches the tags on and off, so the geometry is built
 * once with every variant in it and nothing is rebuilt when the season turns or the weekend comes.
 */
export enum Vis { Always = 0, Summer = 1, NotSummer = 2, Market = 3, NotMarket = 4, Winter = 5, NotWinter = 6, Weekend = 7 }

/** Slot k is 1 while parts tagged k are showing; written by the day/night cycle. */
export const VIS = { uVis: { value: [1, 1, 0, 0, 1, 0, 1, 0] as number[] } };

/** Collapse any vertex whose tag is switched off, so its triangles vanish without a rebuild. */
export function visShader(shader: THREE.WebGLProgramParametersWithUniforms): void {
  shader.uniforms.uVis = VIS.uVis;
  shader.vertexShader = shader.vertexShader
    .replace('#include <common>', '#include <common>\nattribute float aVis;\nuniform float uVis[8];')
    .replace('#include <begin_vertex>', '#include <begin_vertex>\nif (uVis[int(aVis + 0.5)] < 0.5) transformed = vec3(0.0);');
}

/** The shadow pass has to hide the same parts, or an out-of-season ride would still cast a shadow. */
export const visDepthMaterial = new THREE.MeshDepthMaterial({ depthPacking: THREE.RGBADepthPacking });
visDepthMaterial.onBeforeCompile = (shader) => visShader(shader);

const SCHEDULE_GLSL = /* glsl */ `
  float hh = uHour < 12.0 ? uHour + 24.0 : uHour;
  float lit = step(vSched.x, hh) * step(hh, vSched.y) * smoothstep(0.15, 0.6, uNight);
  // inside a flickering town, every seventh second the lights stutter seven times
  if (uFlick.w > 0.5 && length(vFlickXZ - uFlick.xy) < uFlick.z) {
    float ft = mod(uClock, 7.0);
    lit *= ft < 1.0 ? 0.2 + 0.8 * step(0.45, fract(ft * 7.0)) : 1.0;
  }
`;
const FLICK_UNIFORMS = 'uniform vec4 uFlick;\nuniform float uClock;\nvarying vec2 vFlickXZ;';

/**
 * Windows and lamp heads: ordinary lit surfaces by day (their vertex colour), glowing with their own
 * colour through their scheduled hours after dark, and darker glass when unlit at night.
 */
export const glowMaterial = new THREE.MeshStandardMaterial({ vertexColors: true, flatShading: true, roughness: 0.35, metalness: 0.1, transparent: true });
glowMaterial.onBeforeCompile = (shader) => {
  shader.uniforms.uHour = NIGHT.uHour;
  shader.uniforms.uNight = NIGHT.uNight;
  shader.uniforms.uFlick = NIGHT.uFlick;
  shader.uniforms.uClock = NIGHT.uClock;
  xrayShader(shader); // windows fade with the building they are in
  visShader(shader);  // and come and go with it
  shader.vertexShader = shader.vertexShader
    .replace('#include <common>', '#include <common>\nattribute vec3 aSched;\nattribute vec3 aGlow;\nvarying vec3 vSched;\nvarying vec3 vGlow;\nvarying vec2 vFlickXZ;')
    .replace('#include <begin_vertex>', '#include <begin_vertex>\nvSched = aSched;\nvGlow = aGlow;\nvFlickXZ = (modelMatrix * vec4(transformed, 1.0)).xz;');
  shader.fragmentShader = shader.fragmentShader
    .replace('#include <common>', `#include <common>\nuniform float uHour;\nuniform float uNight;\nvarying vec3 vSched;\nvarying vec3 vGlow;\n${FLICK_UNIFORMS}`)
    .replace('#include <emissivemap_fragment>', `#include <emissivemap_fragment>
${SCHEDULE_GLSL}
  diffuseColor.rgb *= 1.0 - 0.6 * uNight * (1.0 - lit);
  totalEmissiveRadiance += vGlow * vSched.z * 0.55 * lit;`);
  // and a building lit up for an event lights its windows with it (render/eventLights.ts)
  eventLightShader(shader);
};

/** Soft additive pools of light on the ground under street lamps. */
export const poolMaterial = new THREE.ShaderMaterial({
  uniforms: { uHour: NIGHT.uHour, uNight: NIGHT.uNight, uFlick: NIGHT.uFlick, uClock: NIGHT.uClock },
  vertexShader: /* glsl */ `
    attribute vec3 aSched; attribute vec3 aGlow; attribute vec2 aSpot;
    varying vec3 vSched; varying vec3 vGlow; varying vec2 vSpot; varying vec2 vFlickXZ;
    void main() {
      vSched = aSched; vGlow = aGlow; vSpot = aSpot;
      vFlickXZ = (modelMatrix * vec4(position, 1.0)).xz;
      gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
    }`,
  fragmentShader: /* glsl */ `
    uniform float uHour; uniform float uNight; uniform vec4 uFlick; uniform float uClock;
    varying vec3 vSched; varying vec3 vGlow; varying vec2 vSpot; varying vec2 vFlickXZ;
    void main() {
      ${SCHEDULE_GLSL}
      float f = clamp(1.0 - length(vSpot), 0.0, 1.0);
      gl_FragColor = vec4(vGlow * vec3(1.0, 0.86, 0.66) * vSched.z * 0.55 * f * f * lit, 1.0);
    }`,
  transparent: true,
  depthWrite: false,
  side: THREE.DoubleSide,
  blending: THREE.AdditiveBlending,
  polygonOffset: true,
  polygonOffsetFactor: -4,
  polygonOffsetUnits: -8,
});

type P3 = [number, number, number];

/** Geometry drawn with glowMaterial: positions in world space, each triangle faced away from `inside`. */
export class GlowBuf {
  pos: number[] = [];
  col: number[] = [];
  sched: number[] = [];
  glow: number[] = [];
  ids: number[] = [];
  vis: number[] = [];
  /** uid of the building being drawn, so its windows fade with it (-1 for street lamps and the like). */
  id = -1;
  /** The Vis tag for everything drawn next. */
  tag: Vis = Vis.Always;

  tri(a: P3, b: P3, c: P3, inside: P3, day: RGB, s: Sched, g: RGB): void {
    const ux = b[0] - a[0], uy = b[1] - a[1], uz = b[2] - a[2];
    const vx = c[0] - a[0], vy = c[1] - a[1], vz = c[2] - a[2];
    const nx = uy * vz - uz * vy, ny = uz * vx - ux * vz, nz = ux * vy - uy * vx;
    const mx = (a[0] + b[0] + c[0]) / 3 - inside[0], my = (a[1] + b[1] + c[1]) / 3 - inside[1], mz = (a[2] + b[2] + c[2]) / 3 - inside[2];
    const [p, q] = nx * mx + ny * my + nz * mz < 0 ? [c, b] : [b, c];
    this.pos.push(a[0], a[1], a[2], p[0], p[1], p[2], q[0], q[1], q[2]);
    for (let k = 0; k < 3; k++) {
      this.col.push(day[0], day[1], day[2]);
      this.sched.push(s[0], s[1], s[2]);
      this.glow.push(g[0], g[1], g[2]);
      this.ids.push(this.id);
      this.vis.push(this.tag);
    }
  }

  /** Axis-aligned box standing on y, in world space (bottom face skipped). */
  box(x: number, y: number, z: number, w: number, h: number, d: number, day: RGB, s: Sched, g: RGB): void {
    const x0 = x - w / 2, x1 = x + w / 2, z0 = z - d / 2, z1 = z + d / 2, y1 = y + h;
    const I: P3 = [x, y + h / 2, z];
    const q = (a: P3, b: P3, c: P3, e: P3) => { this.tri(a, b, c, I, day, s, g); this.tri(a, c, e, I, day, s, g); };
    q([x0, y1, z0], [x1, y1, z0], [x1, y1, z1], [x0, y1, z1]);
    q([x0, y, z1], [x1, y, z1], [x1, y1, z1], [x0, y1, z1]);
    q([x0, y, z0], [x1, y, z0], [x1, y1, z0], [x0, y1, z0]);
    q([x1, y, z0], [x1, y, z1], [x1, y1, z1], [x1, y1, z0]);
    q([x0, y, z0], [x0, y, z1], [x0, y1, z1], [x0, y1, z0]);
  }

  mesh(): THREE.Mesh | null {
    if (this.pos.length === 0) return null;
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute(this.pos, 3));
    g.setAttribute('color', new THREE.Float32BufferAttribute(this.col, 3));
    g.setAttribute('aSched', new THREE.Float32BufferAttribute(this.sched, 3));
    g.setAttribute('aGlow', new THREE.Float32BufferAttribute(this.glow, 3));
    g.setAttribute('aId', new THREE.Float32BufferAttribute(this.ids, 1));
    g.setAttribute('aVis', new THREE.Float32BufferAttribute(this.vis, 1));
    g.computeVertexNormals();
    g.computeBoundingSphere();
    const m = new THREE.Mesh(g, glowMaterial);
    m.receiveShadow = true;
    return m;
  }
}

/** Light-pool triangles: world positions plus each vertex's offset from the lamp in radii. */
export class PoolBuf {
  pos: number[] = [];
  spot: number[] = [];
  sched: number[] = [];
  glow: number[] = [];

  vert(x: number, y: number, z: number, sx: number, sz: number, s: Sched, g: RGB): void {
    this.pos.push(x, y, z);
    this.spot.push(sx, sz);
    this.sched.push(s[0], s[1], s[2]);
    this.glow.push(g[0], g[1], g[2]);
  }

  mesh(): THREE.Mesh | null {
    if (this.pos.length === 0) return null;
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute(this.pos, 3));
    g.setAttribute('aSpot', new THREE.Float32BufferAttribute(this.spot, 2));
    g.setAttribute('aSched', new THREE.Float32BufferAttribute(this.sched, 3));
    g.setAttribute('aGlow', new THREE.Float32BufferAttribute(this.glow, 3));
    g.computeBoundingSphere();
    const m = new THREE.Mesh(g, poolMaterial);
    m.renderOrder = 2;
    return m;
  }
}
