import { Lot, RoadType, idx, inB } from '../../tiles';
import { grow, put, type TownPlan } from '../../towns';
import { LAYERS } from '../layers';
import { CARVERS, Dig, nearestSeaSide } from '../water';
import { COMPASS, avenue, dfCores, dfFlat, finishTown, parkAt, reserve, ring, spokes, type Pt } from '../kit';
import { bridgesOver, gridLines, lakeOn, riverThrough } from './shared';
import { gridAround } from './grids';

/**
 * Rings and walls (docs/cityplans.html): cities that grew out from a fortress, a castle or a garden, ring by ring.
 * Moscow's and Beijing's rings and radials, Palmanova's star fort, Amsterdam's canal ring (opened to any style),
 * Edo's spiral moat, Howard's garden city and the medina.
 */

// ---------------------------------------------------------------------------------------------
// ring and radial: Moscow, Beijing, Vienna

CARVERS.rings = (p, ctx, rng) => {
  // the river round the citadel: a wide bend through the middle, where the sea can be reached
  riverThrough(p, ctx, rng, { half: 2, amp: p.size * 0.12, off: 0.08 });
  return true;
};

LAYERS.rings = (c, p) => {
  const S = p.size, x0 = p.x0, z0 = p.z0, mega = p.kind === 'mega';
  const cx = x0 + S / 2, cz = z0 + S / 2;
  c.bridgeSpan = 9;
  // the boulevard ring where the citadel's wall stood, the garden ring, the third ring, and the orbital
  ring(c, RoadType.TwoLane, cx, cz, Math.round(S * 0.13), Math.round(S * 0.05), { bridge: true });
  ring(c, RoadType.TwoLane, cx, cz, Math.round(S * 0.25), Math.round(S * 0.1), { bridge: true });
  ring(c, RoadType.FourLane, cx, cz, Math.round(S * 0.37), 0, { bridge: true });
  if (mega) ring(c, RoadType.FourLane, cx, cz, Math.round(S * 0.47), 0, { bridge: true });
  // the radials: four lanes on the square ones (the county's roads come in on them), lanes on the diagonals
  const sq = spokes(c, RoadType.FourLane, cx, cz, Math.round(S * 0.06), Math.round(S * 0.5), COMPASS.slice(0, 4), { bridge: true });
  for (const n of sq) c.ends(n);
  spokes(c, RoadType.TwoLane, cx, cz, Math.round(S * 0.08), Math.round(S * 0.5), COMPASS.slice(4), { bridge: true });
  bridgesOver(c, p, 0.2);
  // the citadel at the heart, the cathedral beside it, the great square at its gate; tower blocks on the third ring
  c.anchors.seat = [cx + 0.5, cz + 0.5];
  c.anchors.palace = [cx - 4, cz - 4];
  c.anchors.temple = [cx + 4, cz - 4];
  c.anchors.arch = [cx + 0.5, cz + 6];
  c.anchors.landmark = [cx + S * 0.37 * 0.7, cz - S * 0.37 * 0.7];
  c.anchors.stadium = [cx - S * 0.3, cz + S * 0.3];
  if (c.t.style === 'russian') put(c, 'kremlin', { near: [cx + 0.5, cz + 0.5], maxDist: 5 });
  // towers on the third ring rather than in the middle: the historic core stays mid-rise
  const third = S * 0.37;
  c.dfAt = (x, z) => {
    const d = Math.hypot(x - cx, z - cz);
    return d < S * 0.15 ? 0.5 : Math.min(1, Math.abs(d - third) / (S * 0.26));
  };
  finishTown(c, { grow: mega ? 40 : 22 });
  return true;
};

// ---------------------------------------------------------------------------------------------
// the star fort: Palmanova, Naarden, Bourtange

/** The fort's middle and radius (to its bastions' tips): the whole square for a small town, the old core of a big one. */
function fortOf(p: TownPlan): { cx: number; cz: number; R: number } {
  const S = p.size;
  const R = p.kind === 'mega' ? S * 0.26 : p.kind === 'metro' ? S * 0.36 : S * 0.44;
  return { cx: p.x0 + S / 2, cz: p.z0 + S / 2, R };
}

/** Is (x, z) inside an eight-pointed star of tip radius R (inner corners at `k` of it) about (cx, cz)? */
function inStar(x: number, z: number, cx: number, cz: number, R: number, k = 0.72): boolean {
  const dx = x - cx, dz = z - cz, d = Math.hypot(dx, dz);
  if (d > R) return false;
  let a = Math.atan2(dz, dx) / (Math.PI / 4);   // in eighths of a turn
  a = Math.abs(a - Math.round(a));                // 0 at a tip, 0.5 between
  const edge = R * (1 - (1 - k) * (a / 0.5));      // straight-ish faces from tip to inner corner
  return d <= edge;
}

CARVERS.starfort = (p, ctx) => {
  const { cx, cz, R } = fortOf(p);
  const moat = new Set<number>();
  for (let z = Math.floor(cz - R - 4); z <= Math.ceil(cz + R + 4); z++) for (let x = Math.floor(cx - R - 4); x <= Math.ceil(cx + R + 4); x++) {
    if (!inB(x, z)) continue;
    const X = x + 0.5, Z = z + 0.5;
    if (inStar(X, Z, cx, cz, R + 3) && !inStar(X, Z, cx, cz, R)) moat.add(idx(x, z));
  }
  return lakeOn(p, ctx, moat);
};

LAYERS.starfort = (c, p) => {
  const { cx, cz, R } = fortOf(p);
  const S = p.size, x0 = p.x0, z0 = p.z0, small = p.kind === 'city';
  c.bridgeSpan = 6;
  // the piazza: an octagon at the middle, its eight streets out to the bastions, a ring street inside the walls
  ring(c, RoadType.TwoLane, cx, cz, 4, 2, { main: false });
  spokes(c, RoadType.TwoLane, cx, cz, 5, Math.round(R * 0.62), COMPASS, { main: false });
  ring(c, RoadType.TwoLane, cx, cz, Math.round(R * 0.48), Math.round(R * 0.2), { main: false });
  // three gates over the moat, and the roads on out to the edge of town
  for (const [dx, dz] of [[1, 0], [-1, 0], [0, 1]]) {
    const a: Pt = [cx + dx * (R * 0.5), cz + dz * (R * 0.5)], b: Pt = [cx + dx * (S / 2 - 1), cz + dz * (S / 2 - 1)];
    c.ends(avenue(c, RoadType.TwoLane, c.clampPt(...a), c.clampPt(...b), { main: true, bridge: true }));
  }
  // outside the moat a big town grows on a grid
  if (!small) {
    const h: [number, number, number, number] = [Math.floor(cx - R - 4), Math.floor(cz - R - 4), Math.ceil(cx + R + 5), Math.ceil(cz + R + 5)];
    gridAround(c, gridLines(x0, x0 + S, 7), gridLines(z0, z0 + S, 7), [h]);
  }
  // a watchtower on every bastion's tip, the church on the piazza, the hall off it
  for (const [dx, dz] of COMPASS) {
    const f = dx && dz ? Math.SQRT1_2 : 1;
    put(c, 'watchtower', { near: [cx + dx * f * (R - 2), cz + dz * f * (R - 2)], maxDist: 3, zone: 'any' });
  }
  c.anchors.temple = [cx + 0.5, cz - 6];
  c.anchors.seat = [cx + 6, cz + 0.5];
  c.anchors.market = [cx - 6, cz + 0.5];
  c.dfAt = (x, z) => (Math.hypot(x - cx, z - cz) < R ? 0.6 : Math.min(1, 0.2 + (Math.hypot(x - cx, z - cz) - R) / (S * 0.4)));
  c.capAt = (x, z) => (Math.hypot(x - cx, z - cz) < R + 3 ? 4 : 0);
  finishTown(c, { grow: small ? 3 : 10 });
  return true;
};

// ---------------------------------------------------------------------------------------------
// the canal ring: Amsterdam's grachtengordel, in any style and at any size

/** The square's frame with the sea's side as "down": s along it, u in from it. */
function seaFrame(p: TownPlan, side: number) {
  const S = p.size;
  return (s: number, u: number): [number, number] => {
    switch (side) {
      case 0: return [p.x0 + S - 1 - u, p.z0 + s];
      case 1: return [p.x0 + s, p.z0 + S - 1 - u];
      case 2: return [p.x0 + u, p.z0 + s];
      default: return [p.x0 + s, p.z0 + u];
    }
  };
}

CARVERS.canalring = (p, ctx, rng) => {
  const dig = new Dig(p, ctx);
  const side = nearestSeaSide(dig, 26);
  if (side < 0) return false;
  const S = p.size, F = seaFrame(p, side);
  const cs = S / 2 + (rng() - 0.5) * S * 0.1, cu = -S * 0.06;
  const radii = (p.kind === 'city' ? [0.3, 0.46, 0.62] : [0.26, 0.38, 0.5, 0.62]).map((f) => S * f);
  // the rings
  for (let u = 1; u < S - 1; u++) for (let s = 1; s < S - 1; s++) {
    const d = Math.hypot(s - cs, u - cu);
    for (const R of radii) if (d >= R - 1 && d < R + 1) { const [x, z] = F(s, u); dig.mark(x, z, 2); }
  }
  // the river in from inland to the middle, and the radial canals between the rings
  for (let u = 0; u < S - 1; u++) for (const o of [-1, 0, 1]) { const [x, z] = F(Math.round(cs) + o, u); dig.mark(x, z, 3); }
  for (const a of [0.55, 1.1, 2.05, 2.6]) {
    for (let t = radii[0]; t <= radii[radii.length - 1]; t += 0.5) {
      const s = Math.round(cs + Math.cos(a) * t), u = Math.round(cu + Math.sin(a) * t);
      if (s < 1 || u < 1 || s >= S - 1 || u >= S - 1) continue;
      const [x, z] = F(s, u); dig.mark(x, z, 2);
    }
  }
  // the harbour front and the river out to open water
  const [mx, mz] = F(Math.round(cs), 0);
  if (!dig.toSea(mx, mz, side, 1) || !dig.clear()) return false;
  dig.commit();
  const c = (p.carved ??= {});
  c.seaSide = side;
  c.note = { cs, cu, r0: radii[0], r1: radii[radii.length - 1], n: radii.length };
  return true;
};

LAYERS.canalring = (c, p) => {
  const n = p.carved?.note, side = p.carved?.seaSide;
  if (!n || side === undefined) return false;
  const S = p.size, F = seaFrame(p, side);
  const P = (s: number, u: number): Pt => { const [x, z] = F(Math.round(s), Math.round(u)); return [x + 0.5, z + 0.5]; };
  c.bridgeSpan = 5;
  // the quays: a street inside every canal of the ring, round from the harbour front to the harbour front
  const radii: number[] = [];
  for (let k = 0; k < n.n; k++) radii.push(n.r0 + ((n.r1 - n.r0) * k) / Math.max(1, n.n - 1));
  const keep = c.t.surface;
  if (c.t.kind !== 'mega') c.t.surface = 'brick';
  for (const R of radii) {
    const pts: Pt[] = [];
    for (let a = 0.12; a <= Math.PI - 0.12; a += 0.18) pts.push(c.clampPt(...P(n.cs + Math.cos(a) * (R - 2.5), n.cu + Math.sin(a) * (R - 2.5))));
    c.street(RoadType.TwoLane, pts);
  }
  // the radial streets out over every ring, on their bridges, to the edge of town
  for (const a of [0.3, 0.85, 1.57, 2.3, 2.85]) {
    const from = P(n.cs + Math.cos(a) * 3, n.cu + Math.sin(a) * 3 + 2);
    const out = Math.max(n.r1 + 6, 0);
    const to = c.clampPt(...P(n.cs + Math.cos(a) * out, n.cu + Math.sin(a) * out));
    c.ends(c.street(RoadType.TwoLane, [from, to]));
  }
  c.t.surface = keep;
  // the harbour front: a street along the water the width of the old town
  avenue(c, RoadType.TwoLane, P(n.cs - n.r1, 2), P(n.cs + n.r1, 2), { main: true, bridge: true });
  // past the outer canal a modern town on a grid
  if (c.t.kind !== 'city') {
    const g = c.t.kind === 'mega' ? 7 : 6;
    const xs = gridLines(p.x0, p.x0 + S, g), zs = gridLines(p.z0, p.z0 + S, g);
    const [ax, az] = P(n.cs - n.r1 - 3, 0), [bx, bz] = P(n.cs + n.r1 + 3, n.r1 + 3);
    gridAround(c, xs, zs, [[Math.min(ax, bx), Math.min(az, bz), Math.max(ax, bx), Math.max(az, bz)]]);
  }
  // the roles: Dam square with the palace and the church at the rings' middle, the station on the harbour front
  c.anchors.seat = P(n.cs + 4, 5);
  c.anchors.temple = P(n.cs - 5, 6);
  c.anchors.museum = P(n.cs, n.r1 + 4);
  put(c, 'busStation', { near: P(n.cs + 7, 2), maxDist: 5, waterside: 'prefer' });
  c.dfAt = (x, z) => {
    // low inside the rings; the towers out past them
    const [hx, hz] = P(n.cs, n.cu);
    const d = Math.hypot(x - hx, z - hz);
    return d < n.r1 + 2 ? 0.7 : Math.max(0.1, 1 - (d - n.r1) / (S * 0.5));
  };
  c.capAt = (x, z) => { const [hx, hz] = P(n.cs, n.cu); return Math.hypot(x - hx, z - hz) < n.r1 + 2 ? 5 : 0; };
  finishTown(c, { grow: c.t.kind === 'city' ? 4 : 12 });
  return true;
};

// ---------------------------------------------------------------------------------------------
// the castle spiral: Edo

CARVERS.spiral = (p, ctx) => {
  const dig = new Dig(p, ctx);
  const side = nearestSeaSide(dig, 26);
  if (side < 0) return false;
  const S = p.size, cx = p.x0 + S / 2, cz = p.z0 + S / 2;
  // half-turns about two centres a little apart, the radius growing each half-turn: a spiral out from the castle
  const step = S * 0.055;
  let r = S * 0.07, a0 = -Math.PI / 2, end: [number, number] = [cx, cz];
  for (let k = 0; k < 7 && r < S * 0.44; k++) {
    const ccz = cz + (k % 2 ? -step / 2 : step / 2);
    for (let a = a0; a <= a0 + Math.PI + 0.01; a += 0.02) {
      const x = cx + Math.cos(a) * r, z = ccz + Math.sin(a) * r;
      dig.mark(x, z, 2); dig.mark(x + 0.5, z, 2);
      end = [x, z];
    }
    a0 += Math.PI;
    r += step;
  }
  // and from the outer end of it out to the bay
  if (!dig.toSea(end[0], end[1], side, 1) || !dig.clear()) return false;
  dig.commit();
  (p.carved ??= {}).seaSide = side;
  return true;
};

LAYERS.spiral = (c, p) => {
  const S = p.size, x0 = p.x0, z0 = p.z0, mega = p.kind === 'mega';
  const cx = x0 + S / 2, cz = z0 + S / 2, side = p.carved?.seaSide ?? 1;
  c.bridgeSpan = 5;
  // the wards: a grid over the whole spiral, each street bridging the moat wherever it crosses it
  const g = mega ? 8 : 7;
  gridAround(c, gridLines(x0, x0 + S, g), gridLines(z0, z0 + S, g), [[Math.floor(cx - 4), Math.floor(cz - 4), Math.ceil(cx + 5), Math.ceil(cz + 5)]], RoadType.TwoLane, { bridge: true });
  ring(c, RoadType.TwoLane, cx, cz, 5, 2, { main: false, bridge: true });
  // the castle at the heart, a ring of shrines round it, the merchants' bridge where the spiral meets the bay
  const toward: Pt = [side === 0 ? 1 : side === 2 ? -1 : 0, side === 1 ? 1 : side === 3 ? -1 : 0];
  const bay: Pt = [cx + toward[0] * S * 0.4, cz + toward[1] * S * 0.4];
  c.anchors.seat = [cx + 0.5, cz + 0.5];
  c.anchors.palace = [cx - 6, cz + 0.5];
  c.anchors.market = bay;
  c.anchors.landmark = [bay[0] - toward[1] * 6, bay[1] - toward[0] * 6];
  for (let k = 0; k < 6; k++) { const a = (k / 6) * Math.PI * 2; put(c, k % 2 ? 'pagoda' : 'temple', { near: [cx + Math.cos(a) * S * 0.3, cz + Math.sin(a) * S * 0.3], maxDist: 6 }); }
  // low inside (the estates), the merchant town dense by the bay, towers past it
  c.dfAt = dfCores(c, [bay], S * 0.6);
  c.capAt = (x, z) => (Math.hypot(x - cx, z - cz) < S * 0.22 ? 3 : 0);
  finishTown(c, { grow: mega ? 14 : 8 });
  return true;
};

// ---------------------------------------------------------------------------------------------
// Howard's garden city

LAYERS.gardencity = (c, p, rng) => {
  const S = p.size, x0 = p.x0, z0 = p.z0, mega = p.kind === 'mega';
  const cx = x0 + S / 2, cz = z0 + S / 2;
  // the central garden (a great park, its ring the first ring street)
  const gs = mega ? 14 : 11;
  const garden = parkAt(c, cx - gs / 2, cz - gs / 2, gs, gs, rng);
  // the civic ring, the Grand Avenue (a ring of parkland), the outer ring by the railway, and the boulevards
  ring(c, RoadType.TwoLane, cx, cz, Math.round(gs / 2 + 6), 3, { main: false });
  const ga = Math.round(S * 0.28);
  ring(c, RoadType.TwoLane, cx, cz, ga - 3, Math.round((ga - 3) * 0.4), { main: false });
  ring(c, RoadType.TwoLane, cx, cz, ga + 3, Math.round((ga + 3) * 0.4), { main: false });
  ring(c, RoadType.FourLane, cx, cz, Math.round(S * 0.42), 0, { main: true });
  const b = spokes(c, RoadType.TwoLane, cx, cz, Math.round(gs / 2 + 2), Math.round(S * 0.5), COMPASS, { main: true });
  for (const n of b.slice(0, 4)) c.ends(n);
  // the Grand Avenue's parkland and the green belt: kept open for good
  const keep: number[] = [];
  for (let z = z0; z < z0 + S; z++) for (let x = x0; x < x0 + S; x++) {
    const i = idx(x, z);
    if (c.w.road[i]) continue;
    const d = Math.max(Math.abs(x + 0.5 - cx), Math.abs(z + 0.5 - cz));
    const oct = Math.max(d, (Math.abs(x + 0.5 - cx) + Math.abs(z + 0.5 - cz)) * 0.72);
    if ((oct > ga - 2 && oct < ga + 2) || d > S * 0.44) keep.push(i);
  }
  reserve(c, keep);
  // the roles round the garden: hall, theatre, library, museum, hospital; the crystal palace (a glass arcade)
  const R = gs / 2 + 4;
  c.anchors.seat = [cx + R, cz + 0.5];
  c.anchors.museum = [cx - R, cz + 0.5];
  c.anchors.temple = [cx + 0.5, cz - R];
  c.anchors.market = [cx + 0.5, cz + R];
  put(c, 'library', { near: [cx + R * 0.7, cz - R * 0.7], maxDist: 4 });
  put(c, 'theatre', { near: [cx - R * 0.7, cz + R * 0.7], maxDist: 4 });
  put(c, 'botanicalGarden', { near: [cx - R * 0.7, cz - R * 0.7], maxDist: 5 });
  c.dfAt = dfFlat(0.7);
  c.maxFloors = mega ? 6 : 4;
  finishTown(c, { grow: mega ? 16 : 8, growType: RoadType.Paved, parks: garden ? [garden] : [] });
  for (const i of keep) if (c.w.townId[i] === c.t.id && !c.w.road[i] && !c.w.blocked[i]) c.w.lot[i] = Lot.Park;
  return true;
};

// ---------------------------------------------------------------------------------------------
// the medina: Fez, Marrakech

LAYERS.medina = (c, p, rng) => {
  const S = p.size, x0 = p.x0, z0 = p.z0, kind = p.kind;
  // a big town keeps its new town on a grid on one side; the medina is the rest
  const newSide = kind === 'city' ? -1 : Math.floor(rng() * 4);
  const nw = kind === 'mega' ? Math.round(S * 0.38) : Math.round(S * 0.32);
  const mx0 = newSide === 2 ? x0 + nw : x0, mx1 = newSide === 0 ? x0 + S - nw : x0 + S;
  const mz0 = newSide === 3 ? z0 + nw : z0, mz1 = newSide === 1 ? z0 + S - nw : z0 + S;
  const mcx = (mx0 + mx1) / 2, mcz = (mz0 + mz1) / 2, mw = mx1 - mx0, md = mz1 - mz0;
  // the souk: one street winding from gate to gate across the medina, past the great mosque
  const pts: Pt[] = [];
  const along = mw >= md;
  for (let k = 0; k <= 6; k++) {
    const f = k / 6;
    const wob = (rng() - 0.5) * (along ? md : mw) * 0.35;
    pts.push(along ? c.clampPt(mx0 + 0.5 + f * (mw - 1), mcz + wob) : c.clampPt(mcx + wob, mz0 + 0.5 + f * (md - 1)));
  }
  const keep = c.t.surface;
  c.t.surface = 'brick';
  const souk = c.street(RoadType.TwoLane, pts);
  c.ends(souk);
  // the lanes: grown off it and off each other, dead ends and all
  grow(c, c.t.roads + (kind === 'mega' ? 70 : kind === 'metro' ? 46 : 24), RoadType.Brick);
  c.t.surface = keep;
  // the new town: a grid, and a boulevard from it to the gate
  if (newSide >= 0) {
    const nx0 = newSide === 0 ? x0 + S - nw : x0, nx1 = newSide === 2 ? x0 + nw : x0 + S;
    const nz0 = newSide === 1 ? z0 + S - nw : z0, nz1 = newSide === 3 ? z0 + nw : z0 + S;
    const g = 6;
    const xs = gridLines(nx0, nx1, g), zs = gridLines(nz0, nz1, g);
    for (const x of xs) c.ends(avenue(c, RoadType.TwoLane, [x + 0.5, nz0 + 0.5], [x + 0.5, nz1 - 0.5], { main: true, route: false }));
    for (const z of zs) avenue(c, RoadType.TwoLane, [nx0 + 0.5, z + 0.5], [nx1 - 0.5, z + 0.5], { main: false, route: false });
    c.street(RoadType.FourLane, [[(nx0 + nx1) / 2, (nz0 + nz1) / 2], [mcx, mcz]]);
  }
  // the walls' towers, the kasbah at the wall, the mosque on the souk, the bazaar along it
  for (const [fx, fz] of [[0, 0], [1, 0], [0, 1], [1, 1], [0.5, 0], [0.5, 1], [0, 0.5], [1, 0.5]]) put(c, 'watchtower', { near: [mx0 + 1 + fx * (mw - 3), mz0 + 1 + fz * (md - 3)], maxDist: 3, zone: 'any' });
  const mid = pts[3];
  c.anchors.temple = mid;
  c.anchors.seat = [mx0 + 3, mz0 + 3];
  c.anchors.market = pts[2];
  put(c, 'bazaar', { near: pts[4], maxDist: 6 }) ?? put(c, 'souk', { near: pts[4], maxDist: 6 });
  put(c, 'mosque', { near: mid, maxDist: 6 });
  const inMedina = (x: number, z: number) => x >= mx0 && x < mx1 && z >= mz0 && z < mz1;
  c.dfAt = (x, z) => (inMedina(x, z) ? 0.6 : Math.max(0.1, Math.hypot(x - mcx, z - mcz) / S - 0.2));
  c.capAt = (x, z) => (inMedina(x, z) ? 4 : 0);
  finishTown(c, { grow: 0 });
  return true;
};

