import * as THREE from 'three';
import { PART_SLOTS } from './xray';

/**
 * Buildings lit up for an event (docs/events.html): a champion's landmark in its club's colours, a skyline
 * flashing at midnight on New Year's Eve, towers in rainbow bands. Buildings are merged into one mesh per chunk,
 * so they can't be given materials of their own; instead the town's and the windows' shaders read a few slots
 * here, each a box on the ground in world tiles and the building inside it to light (by its id, as the x-ray
 * fades one: `uid * PART_SLOTS + part`), or every building in the box. The box keeps one county's building 12
 * from lighting another's. Set once at start (the arrays are fixed), so lighting one never recompiles a shader.
 */

/** Slots: one or two an event, three events staged at once. */
export const LIGHT_SLOTS = 8;

type LightMode = 'solid' | 'bands' | 'rainbow' | 'flash' | 'chase' | 'twinkle' | 'dark';
const MODE: Record<LightMode, number> = { solid: 0, bands: 1, rainbow: 2, flash: 3, chase: 4, twinkle: 5, dark: 6 };

export const EVENT_LIGHTS = {
  /** x0, z0, x1, z1 in world tiles; an empty slot has x0 > x1. */
  uEvBox: { value: Array.from({ length: LIGHT_SLOTS }, () => new THREE.Vector4(1, 1, 0, 0)) },
  /** The building's uid (-1: every building in the box), the mode, the strength, a phase. */
  uEvMode: { value: Array.from({ length: LIGHT_SLOTS }, () => new THREE.Vector4(-1, 0, 0, 0)) },
  uEvColA: { value: Array.from({ length: LIGHT_SLOTS }, () => new THREE.Color()) },
  uEvColB: { value: Array.from({ length: LIGHT_SLOTS }, () => new THREE.Color()) },
  /** Only what is higher than this (world units): a city's towers lit and not its houses. */
  uEvMinY: { value: new Array(LIGHT_SLOTS).fill(-1e6) as number[] },
  uEvTime: { value: 0 },
};

const VERT_HEAD = /* glsl */ `
varying vec3 vEvP;
`;
const FRAG_HEAD = /* glsl */ `
uniform vec4 uEvBox[${LIGHT_SLOTS}];
uniform vec4 uEvMode[${LIGHT_SLOTS}];
uniform vec3 uEvColA[${LIGHT_SLOTS}];
uniform vec3 uEvColB[${LIGHT_SLOTS}];
uniform float uEvMinY[${LIGHT_SLOTS}];
uniform float uEvTime;
varying vec3 vEvP;
vec3 evHue(float h) { return clamp(abs(mod(h * 6.0 + vec3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0); }
`;
const FRAG_BODY = /* glsl */ `
  // a blackout's share of this fragment's own light put out (taken off at the end, opaque_fragment)
  float evDark = 0.0;
  {
    float evB = floor((vId + 0.5) / ${PART_SLOTS.toFixed(1)});
    // how upright this face is: a slot for a whole city lights walls only, not its roofs, squares and lawns
    float evWall = 1.0 - abs(inverseTransformDirection(normal, viewMatrix).y);
    for (int i = 0; i < ${LIGHT_SLOTS}; i++) {
      vec4 bx = uEvBox[i];
      vec4 md = uEvMode[i];
      float walls = step(9.5, md.y);
      float mode = md.y - walls * 10.0;
      // a blackout (mode 6) puts out the street lamps' heads too, which carry no building's id
      if ((vId >= 0.0 || abs(mode - 6.0) < 0.5) && md.z > 0.0 && vEvP.x >= bx.x && vEvP.x <= bx.z && vEvP.z >= bx.y && vEvP.z <= bx.w && (md.x < 0.0 || abs(evB - md.x) < 0.5) && (walls < 0.5 || evWall > 0.6) && vEvP.y >= uEvMinY[i]) {
        vec3 c = uEvColA[i];
        float k = md.z;
        md.y = mode;
        if (md.y > 5.5) { evDark = max(evDark, min(1.0, k)); diffuseColor.rgb *= 1.0 - 0.55 * min(1.0, k); continue; }
        if (md.y > 0.5 && md.y < 1.5) c = mix(uEvColA[i], uEvColB[i], step(0.5, fract(vEvP.y * 1.6 + uEvTime * 0.25 + md.w)));
        else if (md.y > 1.5 && md.y < 2.5) c = evHue(fract(vEvP.y * 0.45 - uEvTime * 0.12 + md.w));
        else if (md.y > 2.5 && md.y < 3.5) k *= 0.25 + 0.75 * step(0.0, sin(uEvTime * 9.0 + md.w + (vEvP.x + vEvP.z) * 0.15));
        else if (md.y > 3.5 && md.y < 4.5) c = mix(uEvColA[i], uEvColB[i], step(0.5, fract((vEvP.x + vEvP.z) * 0.08 - uEvTime * 0.6 + md.w)));
        else if (md.y > 4.5) {
          // strings of bulbs: every building its own colour, in bands up its walls, twinkling
          float hb = fract(sin(evB * 12.9898) * 43758.5453);
          c = evHue(fract(hb + floor(vEvP.y * 3.0) * 0.17));
          k *= step(0.55, fract(vEvP.y * 3.0)) * (0.55 + 0.45 * sin(uEvTime * 3.0 + hb * 30.0 + (vEvP.x + vEvP.z) * 1.7));
        }
        totalEmissiveRadiance += c * k;
        diffuseColor.rgb = mix(diffuseColor.rgb, c, 0.3 * min(1.0, k));
      }
    }
  }
`;

/** Give a building material the event lights. Call after xrayShader (it needs vId) in `onBeforeCompile`. */
export function eventLightShader(shader: { vertexShader: string; fragmentShader: string; uniforms: Record<string, THREE.IUniform> }): void {
  Object.assign(shader.uniforms, EVENT_LIGHTS);
  shader.vertexShader = shader.vertexShader
    .replace('#include <common>', `#include <common>\n${VERT_HEAD}`)
    .replace('#include <begin_vertex>', '#include <begin_vertex>\nvEvP = (modelMatrix * vec4(transformed, 1.0)).xyz;');
  shader.fragmentShader = shader.fragmentShader
    .replace('#include <common>', `#include <common>\n${FRAG_HEAD}`)
    .replace('#include <emissivemap_fragment>', `#include <emissivemap_fragment>\n${FRAG_BODY}`)
    .replace('#include <opaque_fragment>', 'outgoingLight -= totalEmissiveRadiance * evDark * 0.94;\n#include <opaque_fragment>');
}

export interface LightSpec {
  /** World tiles. */
  x0: number; z0: number; x1: number; z1: number;
  /** The building's uid, or -1 for every building in the box. */
  uid: number;
  mode: LightMode;
  a: number; b?: number;
  /** 0..about 2. */
  strength: number;
  /** Walls only (a whole city lit: its roofs, squares and lawns stay as they are). */
  walls?: boolean;
  /** Only above this height, world units (a city's towers and not its houses). */
  minY?: number;
  phase?: number;
}

/** Light a slot (or with null, put it out). */
export function setLight(slot: number, s: LightSpec | null): void {
  const L = EVENT_LIGHTS;
  if (slot < 0 || slot >= LIGHT_SLOTS) return;
  L.uEvMinY.value[slot] = s?.minY ?? -1e6;
  if (!s || s.strength <= 0) {
    L.uEvBox.value[slot].set(1, 1, 0, 0);
    L.uEvMode.value[slot].set(-1, 0, 0, 0);
    return;
  }
  L.uEvBox.value[slot].set(s.x0, s.z0, s.x1, s.z1);
  L.uEvMode.value[slot].set(s.uid, MODE[s.mode] + (s.walls ? 10 : 0), s.strength, s.phase ?? 0);
  L.uEvColA.value[slot].setHex(s.a);
  L.uEvColB.value[slot].setHex(s.b ?? s.a);
}

/** Put every slot out. */
export function clearLights(): void { for (let i = 0; i < LIGHT_SLOTS; i++) setLight(i, null); }
