import { DIRS, N, STEP, idx, inB, type Arch, type Building, type BuildingKind, type Town, type TownKind, type World } from './tiles';
import { hashString, mulberry32 } from './rng';
import { plannedDealer } from './macro';
import { runwaysOf } from './runways';
import { solidMask } from './footprint';
import { buildingHeight } from './towns';
import { NEXT_WORLD } from './nextWorld';

/**
 * Storefronts: the buildings a player goes into. Every cell with a town has one Auto Shop and one car dealer
 * (Oct 2026), and may have a boat dealer by its harbour and an aircraft dealer by its airfield, and every one has a tavern of the town's own sort (a saloon out west, an
 * izakaya in Edo, a taverna on the white islands). Each is a real building of that kind with a kerb in
 * front of it, where game/outlets.ts and game/tavern put their entrance rings: when the town has none of
 * the kind already, the likeliest small building on a street is made into one. Marked on the building as
 * `storefront`, and the dealer's trade on the world as `dealerTrade`, both found again on every load.
 */

type Storefront = 'shop' | 'dealer' | 'tavern';
type DealerTrade = 'land' | 'air' | 'sea';

const SIZE: Record<TownKind, number> = { rural: 0, suburb: 1, city: 2, metro: 3, mega: 4 };
/** A cell's chance of a boat dealer when it has a harbour a boat can berth at, and of an aircraft dealer when it has an airfield. */
const EXTRA_DEALER = { sea: 0.5, air: 0.5 };
/** How far apart two storefronts of a cell stand at least, in tiles. */
export const APART = 6;

/** What an ordinary small building on a street may be made into a shop or a tavern from. */
const SMALL = new Set<string>([
  'house', 'townhouse', 'shop', 'store', 'cafe', 'bakery', 'diner', 'fastFood', 'grocery', 'cottage', 'bungalow', 'duplex',
  'office', 'generalStore', 'farmShop', 'croft', 'rondavel', 'stiltHouse', 'shrimpShack', 'apartment',
]);
/** And what a dealership's forecourt may take over. */
const WIDE = new Set<string>([
  'stripMall', 'bank', 'officePark', 'shop', 'store', 'office', 'townhouse', 'house', 'apartment', 'grocery', 'marketHall',
  'departmentStore', 'bigBox', 'mansion', 'duplex', 'motel', 'cafe', 'diner', 'generalStore', 'tradingPost', 'warehouse',
]);

