/** The sort of tavern a town keeps. */
export function tavernSort(t: Town): TavernSort {
  if (t.region === 'shallows') return { word: 'Tiki Bar', kind: 'tikiBar', icon: '🍹', the: false };
  if (t.region === 'moors') return { word: 'Inn', kind: 'pub', icon: '🍺', the: true };
  return SORTS[t.style] ?? TAVERN;
}

const ADJ = ['Crooked', 'Rusty', 'Drowsy', 'Gilded', 'Lucky', 'Black', 'Salty', 'Silver', 'Leaky', 'Weary', 'Merry', 'Hollow',
  'Copper', 'Sly', 'Tipsy', 'Broken', 'Wandering', 'Red', 'Blind', 'Last'];
const NOUN = ['Lantern', 'Anchor', 'Fox', 'Wheel', 'Crow', 'Gasket', 'Barrel', 'Moth', 'Kettle', 'Compass', 'Piston', 'Hound',
  'Cartwheel', 'Heron', 'Spanner', 'Mule', 'Oyster', 'Magpie', 'Tollgate', 'Chance'];

/** A tavern's name: "The Crooked Lantern", "Silver Heron Saloon", always the same for the same place. */
export function tavernName(seed: string, w: World, b: Building, t: Town): string {
  const sort = tavernSort(t);
  const h = hashString(`tavern|${seed}|${w.cx},${w.cz}|${b.uid}`);
  const a = ADJ[h % ADJ.length], n = NOUN[(h >>> 7) % NOUN.length];
  return sort.the ? `The ${a} ${n}` : `${a} ${n} ${sort.word}`;
}

/**
 * The kerb in front of a building: the road tile its front looks onto, else the nearest road tile along
 * its edges; an open lot's own middle as a last resort. In the cell's own tiles.
 */
export function kerbOf(w: World, b: Building): { x: number; z: number } | null {
  const cx = b.x + b.w / 2, cz = b.z + b.d / 2;
  const road = (x: number, z: number) => inB(x, z) && w.road[idx(x, z)] > 0 && !w.blocked[idx(x, z)];
  if (b.solid) {
    const [dx, dz] = DIRS[b.facing];
    const fx = Math.floor(cx + dx * (b.w / 2 + 0.5)), fz = Math.floor(cz + dz * (b.d / 2 + 0.5));
    if (road(fx, fz)) return { x: fx + 0.5 - dx * 0.2, z: fz + 0.5 - dz * 0.2 };
  }
  let best: { x: number; z: number } | null = null, bestD = Infinity;
  for (let z = b.z - 1; z <= b.z + b.d; z++) {
    for (let x = b.x - 1; x <= b.x + b.w; x++) {
      const edgeX = x === b.x - 1 || x === b.x + b.w, edgeZ = z === b.z - 1 || z === b.z + b.d;
      let ok = false;
      if (edgeX || edgeZ) ok = !(edgeX && edgeZ) && road(x, z);
      else if (!b.solid) ok = (x === b.x || z === b.z || x === b.x + b.w - 1 || z === b.z + b.d - 1) && DIRS.some(([dx, dz]) => road(x + dx, z + dz));
      if (!ok) continue;
      const d = Math.hypot(x + 0.5 - cx, z + 0.5 - cz);
      if (d < bestD) { bestD = d; best = { x: x + 0.5, z: z + 0.5 }; }
    }
  }
  return best ?? (b.solid ? null : { x: cx, z: cz });
}

/** The kerb straight out from a building's front: the only kind a storefront's ring may stand on. */
function frontKerb(w: World, b: Building): { x: number; z: number } | null {
  if (!b.solid) return null;
  const k = kerbOf(w, b);
  if (!k) return null;
  const [dx, dz] = DIRS[b.facing];
  const fx = Math.floor(b.x + b.w / 2 + dx * (b.w / 2 + 0.5)), fz = Math.floor(b.z + b.d / 2 + dz * (b.d / 2 + 0.5));
  if (Math.floor(k.x) !== fx || Math.floor(k.z) !== fz) return null;
  // 0.7.0 (NEXT_WORLD): never a bridge's deck, where a canal plan's street crosses its water (world/plans
  // canalring): a car can't stop there, so a shop or dealer facing one is no storefront
  if (NEXT_WORLD && w.water[idx(fx, fz)] >= 0) return null;
  return k;
}

/**
 * A boat dealer's berth: a quay tile a car can stand on with open water beside it, a few tiles along from
 * the pier head so its ring never sits on the harbour's own.
 */
export function berthOf(w: World, avoid: { x: number; z: number } | null): { x: number; z: number; port: number } | null {
  const ports = [...w.ports].sort((a, b) => Number(b.major) - Number(a.major));
  for (const p of ports) {
    const [dx, dz] = DIRS[p.dir];
    const rx = p.root % N, rz = (p.root - rx) / N, k = p.major ? 3 : 1;
    const hx = rx + 0.5 + dx * k, hz = rz + 0.5 + dz * k;
    let best: { x: number; z: number } | null = null, bestD = Infinity;
    for (let z = rz - 8; z <= rz + 8; z++) {
      for (let x = rx - 8; x <= rx + 8; x++) {
        if (!inB(x, z)) continue;
        const i = idx(x, z);
        if (!w.edges[i] || w.blocked[i] || w.water[i] >= 0) continue;
        const cx = x + 0.5, cz = z + 0.5;
        const dHead = Math.hypot(cx - hx, cz - hz);
        if (dHead < 3.5) continue;
        if (avoid && Math.hypot(cx - avoid.x, cz - avoid.z) < APART) continue;
        let wet = false;
        for (const [ex, ez] of DIRS) if (inB(x + ex, z + ez) && w.water[idx(x + ex, z + ez)] >= 0) wet = true;
        if (!wet) continue;
        const d = dHead + (w.road[i] > 0 ? 0 : 1.5);
        if (d < bestD) { bestD = d; best = { x: cx, z: cz }; }
      }
    }
    if (best) return { ...best, port: p.id };
  }
  return null;
}

/** Make a building into another kind on the same footprint, fixing what its new height blocks. */
function remake(w: World, b: Building, kind: BuildingKind, floors: number): void {
  if (b.kind === kind && b.floors === floors) return;
  const tiles: number[] = [];
  for (let z = b.z; z < b.z + b.d; z++) for (let x = b.x; x < b.x + b.w; x++) tiles.push(idx(x, z));
  for (const i of tiles) { w.blocked[i] = 0; w.roof[i] = 0; }
  b.kind = kind;
  b.floors = floors;
  const top = b.level * STEP + buildingHeight(b);
  const mask = solidMask(b);
  tiles.forEach((i, k) => { if (mask[k]) { w.blocked[i] = 1; w.roof[i] = Math.max(w.roof[i], top); } });
}

interface Pick { t: Town; b: Building; at: { x: number; z: number } }

/**
 * A building for a storefront in the towns given, best town first: one already of the kind (`have`) if
 * any stands on a kerb, else one of `from` that fits `fits`, which is made into `make`. Clear of `avoid`.
 */
function choose(w: World, towns: Town[], have: Set<string>, from: Set<string>, fits: (b: Building) => boolean,
  avoid: { x: number; z: number }[], rnd: () => number): Pick | null {
  const clear = (p: { x: number; z: number }) => avoid.every((a) => Math.hypot(p.x - a.x, p.z - a.z) >= APART);
  for (const pass of [0, 1]) {
    for (const t of towns) {
      const found: Pick[] = [];
      for (const b of t.buildings) {
        if (b.gone || b.derelict || b.storefront || !b.solid) continue;
        if (pass === 0 ? !have.has(b.kind) : !(from.has(b.kind) && fits(b))) continue;
        const at = frontKerb(w, b);
        if (at && clear(at)) found.push({ t, b, at });
      }
      if (found.length) return found[Math.floor(rnd() * found.length)];
    }
  }
  return null;
}

/** The cell's storefronts: its Auto Shop, its dealer (and which trade), its tavern. Run once, as the world is made. */
export function placeStorefronts(w: World): void {
  w.dealerTrade = null;
  const towns = w.towns.filter((t) => t.buildings.length);
  if (!towns.length) return;
  const rnd = mulberry32(hashString(`storefronts|${w.seed}|${w.cx},${w.cz}`));
  const bySize = [...towns].sort((a, b) => SIZE[b.kind] - SIZE[a.kind] || b.buildings.length - a.buildings.length);
  const biggest = SIZE[bySize[0].kind];
  const taken: { x: number; z: number }[] = [];

  // a cell the macro layer promised a land dealer (world/spawn.ts chose starts by it) gets one, whatever its towns
  const planned = plannedDealer(hashString(w.seed), w.cx, w.cz);
  // a boat dealer by a harbour a boat can berth at, an aircraft dealer by an airfield: each a roll of its own
  // (EXTRA_DEALER), so a cell may have either, both or neither besides its car dealer
  w.dealerExtra = [];
  if (w.ports.length && berthOf(w, null) && rnd() < EXTRA_DEALER.sea) w.dealerExtra.push('sea');
  if (runwaysOf(w).length && rnd() < EXTRA_DEALER.air) w.dealerExtra.push('air');
  void planned; void biggest;
  // and a car dealer in every cell with a town (Oct 2026): in the biggest town where it can be
  {
    const trade: DealerTrade = 'land';
    if (trade === 'land') {
      const big = bySize.filter((t) => SIZE[t.kind] === biggest);
      const fits = (b: Building) => b.w >= 2 && b.d >= 2 && b.w <= 3 && b.d <= 3;
      const got = choose(w, big, new Set(['carDealership']), WIDE, fits, taken, rnd)
        ?? choose(w, bySize, new Set(['carDealership']), WIDE, fits, taken, rnd)
        ?? choose(w, bySize, new Set(), WIDE, (b) => b.w * b.d >= 2 && b.w <= 3 && b.d <= 3, taken, rnd)
        // and failing a wide lot, any lot with a kerb, even a village's one-tile shopfront
        ?? choose(w, bySize, new Set(), WIDE, (b) => b.w <= 3 && b.d <= 3, taken, rnd)
        ?? choose(w, bySize, new Set(), SMALL, (b) => b.w <= 3 && b.d <= 3, taken, rnd);
      if (got) {
        remake(w, got.b, 'carDealership', 1);
        got.b.storefront = 'dealer';
        taken.push(got.at);
        w.dealerTrade = 'land';
      }
    }
  }
  // no lot for a car dealer anywhere: the cell's first dealer is its boat or aircraft one
  if (!w.dealerTrade && w.dealerExtra.length) w.dealerTrade = w.dealerExtra.shift()!;

  // then the shop, in any town (the bigger the likelier)
  const order = (salt: number): Town[] => {
    const weights = towns.map((t) => 1 + SIZE[t.kind]);
    let r = ((rnd() + salt) % 1) * weights.reduce((s, v) => s + v, 0);
    let first = towns[0];
    for (let i = 0; i < towns.length; i++) { if ((r -= weights[i]) < 0) { first = towns[i]; break; } }
    return [first, ...towns.filter((t) => t !== first)];
  };
  const one = (b: Building) => b.w === 1 && b.d === 1;
  const shopTowns = order(0);
  const shop = choose(w, shopTowns, new Set(['garage']), SMALL, one, taken, rnd)
    ?? choose(w, shopTowns, new Set(), SMALL, (b) => b.w <= 2 && b.d <= 2, taken, rnd);
  if (shop) {
    remake(w, shop.b, 'garage', 1);
    shop.b.storefront = 'shop';
    taken.push(shop.at);
  }

  // and the tavern: in the town the shop isn't in, if there is another
  const tavTowns = order(0.37);
  if (shop && tavTowns.length > 1 && tavTowns[0] === shop.t) tavTowns.push(tavTowns.shift()!);
  let tavern: Pick | null = null;
  for (const t of tavTowns) {
    const sort = tavernSort(t);
    const fits = sort.kind === 'teaHouse' ? (b: Building) => b.w === 2 && b.d === 2
      : sort.kind === 'taverna' ? (b: Building) => b.w >= 2 && b.w <= 3 && b.d >= 1 && b.d <= 2 : one;
    tavern = choose(w, [t], new Set([sort.kind]), SMALL, fits, taken, rnd);
    if (tavern) { remake(w, tavern.b, sort.kind, sort.kind === 'saloon' || sort.kind === 'pub' ? 2 : 1); break; }
    // no lot the shape of its own sort: a pub, drawn in the town's style, on any small lot
    tavern = choose(w, [t], new Set(['pub']), SMALL, (b) => b.w <= 2 && b.d <= 2, taken, rnd);
    if (tavern) { remake(w, tavern.b, 'pub', 2); break; }
  }
  if (tavern) {
    tavern.b.storefront = 'tavern';
    taken.push(tavern.at);
  }
}

/** The storefront buildings of a cell, with their kerbs and towns. */
export function storefronts(w: World, kind: Storefront): { t: Town; b: Building; at: { x: number; z: number } }[] {
  const out: { t: Town; b: Building; at: { x: number; z: number } }[] = [];
  for (const t of w.towns) {
    for (const b of t.buildings) {
      if (b.storefront !== kind || b.gone) continue;
      const at = kerbOf(w, b);
      if (at) out.push({ t, b, at });
    }
  }
  return out;
}
