/**
 * The turning year.
 *
 * Seasons are cheap on purpose: nothing about the world is rebuilt when one turns. The ground, the
 * leaves and the water all read a handful of shared uniforms, so spring greens, autumn ambers,
 * lying snow and ice on the shallows are a few numbers changing rather than a megabyte of geometry.
 */

/** Game days in a year: one day to a season, so a whole year is about forty minutes of real time. */
export const DAYS_PER_YEAR = 4;

const SEASON_NAMES = ['spring', 'summer', 'autumn', 'winter'] as const;
export type SeasonName = (typeof SEASON_NAMES)[number];

/** World height (in world units) above which snow lies whatever the season. */
export const PERMANENT_SNOW = 8.2;

/** Written every frame by the day/night cycle; read by the ground, leaf and water shaders. */
export const SEASON = {
  /** Seconds since the world loaded, for anything that ripples or falls. */
  uTime: { value: 0 },
  /** How far through the year, 0..4: 0 spring, 1 summer, 2 autumn, 3 winter. */
  uYear: { value: 1 },
  /** Fresh-green spring growth, 0..1. */
  uSpring: { value: 0 },
  /** Turning leaves, 0..1. */
  uAutumn: { value: 0 },
  /** Bare, drab winter, 0..1. */
  uWinter: { value: 0 },
  /** How much snow is lying, 0..1, and the height above which it lies. */
  uSnow: { value: 0 },
  uSnowLine: { value: PERMANENT_SNOW },
  /**
   * The height above which snow lies all year where the camera is looking, in world units: the ordinary
   * line, or high country's own, so a tableland's trees are not white from edge to edge.
   */
  uSnowFloor: { value: PERMANENT_SNOW },
  /** Alpenglow, 0..1: the rose light on the high peaks when the sun is just down or just up. */
  uAlpen: { value: 0 },
  /** How hard the shallows have frozen, 0..1. */
  uFreeze: { value: 0 },
};

/** Weights for the four seasons at a point in the year, blended so nothing switches abruptly. */
export function seasonAt(days: number, hour: number): {
  year: number; name: SeasonName; spring: number; summer: number; autumn: number; winter: number;
} {
  const t = (((days + hour / 24) / DAYS_PER_YEAR) % 1 + 1) % 1;   // 0..1 through the year
  const year = t * 4;
  const w = [0, 0, 0, 0];
  // a season is at full strength in the middle of its own day and hands over at the boundaries
  for (let k = 0; k < 4; k++) {
    let d = Math.abs(year - (k + 0.5));
    if (d > 2) d = 4 - d;
    w[k] = Math.max(0, 1 - d);
  }
  const sum = w[0] + w[1] + w[2] + w[3] || 1;
  return {
    year,
    name: SEASON_NAMES[Math.floor(year) % 4],
    spring: w[0] / sum, summer: w[1] / sum, autumn: w[2] / sum, winter: w[3] / sum,
  };
}

/**
 * How hard it is snowing, 0..1. Winter brings a settled cover down the mountains, and now and then
 * a storm rolls in and whitens everything down to the shore for a while.
 */
export function snowfallAt(days: number, hour: number, seed: number): number {
  const { winter } = seasonAt(days, hour);
  if (winter <= 0.02) return 0;
  // storms come and go a few times a day, on their own deterministic rhythm
  const t = days + hour / 24;
  const a = Math.sin(t * 11.7 + seed * 0.013);
  const b = Math.sin(t * 4.3 + seed * 0.027);
  const storm = Math.max(0, a * 0.6 + b * 0.6 - 0.35) / 0.85;
  return Math.min(1, winter * (0.45 + 0.55 * Math.min(1, storm)));
}

/** GLSL shared by the ground and leaf shaders: how a colour turns through the year. */
export const SEASON_GLSL = /* glsl */ `
uniform float uSpring;
uniform float uAutumn;
uniform float uWinter;
uniform float uSnow;
uniform float uSnowLine;
uniform float uSnowFloor;
uniform float uAlpen;

/** How much of a colour is living green, which is what the seasons act on. */
float greenness(vec3 c) {
  return clamp((c.g - max(c.r, c.b)) * 3.2, 0.0, 1.0);
}

/** Turn a colour through the year; leaf is 1 for anything that actually grows. */
vec3 turnSeason(vec3 c, float leaf) {
  float veg = max(greenness(c), 0.0) * leaf;
  if (veg > 0.001) {
    vec3 fresh = mix(c, vec3(0.60, 0.85, 0.36), 0.35);
    vec3 amber = mix(c, vec3(0.86, 0.52, 0.16), 0.80);
    vec3 drab  = mix(c, vec3(0.56, 0.53, 0.40), 0.62);
    c = mix(c, fresh, uSpring * veg);
    c = mix(c, amber, uAutumn * veg);
    c = mix(c, drab, uWinter * veg);
  }
  return c;
}

/** How deep the snow lies at this height. */
float snowCover(float worldY) {
  float lying = uSnow * smoothstep(uSnowLine, uSnowLine + 1.6, worldY);
  float always = smoothstep(uSnowFloor, uSnowFloor + 2.2, worldY);
  return clamp(max(lying, always), 0.0, 1.0);
}
`;

/**
 * The weather's shared uniforms, written each frame by render/weather.ts. They sit here beside the
 * season's so that every material already wired with seasonUniforms() receives them too; a shader
 * only has to include WEATHER_GLSL (fragment) or WEATHER_VERT_GLSL (vertex) to use them.
 */
export const WEATHER = {
  /** The same clock as uTime, under its own name so a shader may declare both. */
  uWxTime: SEASON.uTime,
  /** How wet the ground is, 0..1: lags the rain, and dries slowly after it. */
  uWet: { value: 0 },
  /** Cloud shadows drifting over the ground, 0..1. */
  uCloud: { value: 0 },
  /** Heat haze: a shimmer and a mirage toward the sky colour in the distance, 0..1. */
  uHaze: { value: 0 },
  /** Mist, 0..1; it lies below uMistH, or above it when uMistTop is 1 (low cloud on the moor). */
  uMist: { value: 0 },
  uMistTop: { value: 0 },
  uMistH: { value: 3 },
  uMistCol: { value: [0.86, 0.88, 0.89] as [number, number, number] },
  /** The sky colour right now, for the mirage and puddle reflections. */
  uSkyCol: { value: [0.81, 0.9, 0.96] as [number, number, number] },
  /** Wind strength 0..1 and the unit direction it blows toward on the ground plane (x, z). */
  uWind: { value: 0 },
  uWindDir: { value: [0.7, 0.7] as [number, number] },
  /** 1 in daylight, 0 at night: cloud shadows need a sun to cast them. */
  uDaylight: { value: 1 },
  /** Distance from the camera to what it looks at, so distance effects start beyond the car. */
  uFocusD: { value: 70 },
};

/** Fragment GLSL: cloud shadow, mist and haze. Needs a world-space position from the vertex shader. */
export const WEATHER_GLSL = /* glsl */ `
uniform float uWxTime;
uniform float uWet;
uniform float uCloud;
uniform float uHaze;
uniform float uMist;
uniform float uMistTop;
uniform float uMistH;
uniform vec3 uMistCol;
uniform vec3 uSkyCol;
uniform float uWind;
uniform vec2 uWindDir;
uniform float uDaylight;
uniform float uFocusD;

float wxHash(vec2 p) {
  p = fract(p * vec2(0.1031, 0.1030));
  p += dot(p, p.yx + 33.33);
  return fract((p.x + p.y) * p.x);
}
float wxNoise(vec2 p) {
  vec2 i = floor(p), f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(wxHash(i), wxHash(i + vec2(1.0, 0.0)), f.x), mix(wxHash(i + vec2(0.0, 1.0)), wxHash(i + vec2(1.0, 1.0)), f.x), f.y);
}

/** Multiply a lit colour by this: 1 in the sun, darker under a drifting cloud. */
float cloudShade(vec2 xz) {
  if (uCloud <= 0.001) return 1.0;
  vec2 p = (xz - uWindDir * uWxTime * (1.5 + 5.0 * uWind)) * 0.06;
  float c = wxNoise(p) * 0.65 + wxNoise(p * 2.3 + 7.1) * 0.35;
  return 1.0 - uCloud * uDaylight * 0.5 * smoothstep(0.46, 0.56, c);
}

/** Mist lying in the valleys (or hanging on the tops), and haze blurring the distance into the sky. */
vec3 weatherAir(vec3 col, vec3 wp) {
  if (uMist > 0.001) {
    float low = 1.0 - smoothstep(uMistH - 0.5, uMistH + 2.0, wp.y);
    float high = smoothstep(uMistH - 1.0, uMistH + 2.5, wp.y);
    float drift = 0.7 + 0.3 * wxNoise(wp.xz * 0.045 + uWindDir * uWxTime * 0.06);
    col = mix(col, uMistCol, clamp(uMist * mix(low, high, uMistTop) * drift * 0.6, 0.0, 1.0));
  }
  if (uHaze > 0.001) {
    float d = distance(wp, cameraPosition);
    float far = smoothstep(0.92, 1.16, d / uFocusD);   // the top of the frame is ~1.15 × the focus distance
    float shimmer = 0.5 + 0.5 * sin(wp.x * 0.9 + wp.z * 0.4 + uWxTime * 5.0) * sin(d * 0.35 - uWxTime * 3.0);
    col = mix(col, uSkyCol, uHaze * far * (0.5 + 0.35 * shimmer));
  }
  return col;
}
`;

/** Vertex GLSL: heat shimmer on distant geometry and the wind's sway for foliage. */
export const WEATHER_VERT_GLSL = /* glsl */ `
uniform float uWxTime;
uniform float uHaze;
uniform float uWind;
uniform vec2 uWindDir;
uniform float uFocusD;

/** A world-space offset for a point wobbling in the heat; add it to the vertex's height. */
float hazeWobble(vec3 wp) {
  if (uHaze <= 0.001) return 0.0;
  float d = distance(wp, cameraPosition);
  float k = uHaze * smoothstep(1.0, 1.2, d / uFocusD);
  return k * 0.22 * sin(wp.x * 0.8 + uWxTime * 4.0) * sin(wp.z * 0.7 + uWxTime * 3.3);
}

/** Sway for a leaf vertex at world position wp standing 'up' units above its root; 0 in still air. */
vec3 windSway(vec3 wp, float up) {
  if (uWind <= 0.001) return vec3(0.0);
  float ph = dot(wp.xz, vec2(0.37, 0.29)) + uWxTime * (1.2 + 2.4 * uWind);
  float s = uWind * up * (0.05 + 0.035 * sin(ph) + 0.015 * sin(ph * 2.7));
  return vec3(uWindDir.x, 0.0, uWindDir.y) * s;
}
`;

/** Wire the season uniforms into a material's shader. */
export function seasonUniforms(shader: { uniforms: Record<string, { value: unknown }> }): void {
  Object.assign(shader.uniforms, WEATHER);
  shader.uniforms.uTime = SEASON.uTime;
  shader.uniforms.uSpring = SEASON.uSpring;
  shader.uniforms.uAutumn = SEASON.uAutumn;
  shader.uniforms.uWinter = SEASON.uWinter;
  shader.uniforms.uSnow = SEASON.uSnow;
  shader.uniforms.uSnowLine = SEASON.uSnowLine;
  shader.uniforms.uSnowFloor = SEASON.uSnowFloor;
  shader.uniforms.uAlpen = SEASON.uAlpen;
  shader.uniforms.uFreeze = SEASON.uFreeze;
}

/** Vertex-shader snippet that hands the fragment shader the world height of the vertex. */
export const WORLD_Y_VERT = /* glsl */ `
#ifdef USE_INSTANCING
  vWorldY = (modelMatrix * instanceMatrix * vec4(transformed, 1.0)).y;
#else
  vWorldY = (modelMatrix * vec4(transformed, 1.0)).y;
#endif
`;
