import { N, SEA, idx, inB, type Arch, type TownKind, type World } from '../tiles';
import { hashString, mulberry32 } from '../rng';
import type { Layout, TownPlan } from '../towns';
import { PLAN_HOOKS } from './hooks';
import { PLAN_INFO, plansFor } from './registry';
import type { PlanCtx, PlanId, SiteWants } from './types';
import { CARVERS, planCorners, planWater } from './water';
import { LAYERS } from './layers';
import { COMPASS } from './kit';
import './families/grids';
import './families/capitals';
import './families/rings';
import './families/watercities';
import './families/corridors';
import './families/hills';

export { PLAN_INFO, planCorners, planWater };

/**
 * The city plans (docs/cityplans.html): which plan each town takes, and the hooks world/towns.ts calls (hooks.ts).
 *
 * A megalopolis's first choice is dealt from a deck: the plans shuffled from the seed for each block of 4 × 4
 * counties and dealt one a county, so no two megalopolises in a block start from the same plan. A big city or a
 * small city rolls its own, hashed, and keeps today's layout ('grid') in 40% / 70% of towns. The site then takes the
 * first plan of the town's ranked list it can hold (the first choice, then its fallbacks), ending at 'grid'.
 */

/** Gates only (scripts/cityplans.ts): every town that can take this plan is given it first. */
export const PLAN_TEST: { force: PlanId | null } = { force: null };
/** Gates only (PLAN_DEBUG=1): say why plans fall back. */
const DEBUG = !!(globalThis as { process?: { env: Record<string, string | undefined> } }).process?.env?.PLAN_DEBUG;
/** Gates only: how long the last towns' plans took to carve and to lay, by town name (ms). */
export const PLAN_TIME = new Map<string, { carve: number; lay: number }>();

/** The share of big cities and of small cities that keep today's layout. */
const KEEP_TODAY: Partial<Record<TownKind, number>> = { metro: 0.4, city: 0.7 };

/** The deck's block of counties, a side. */
const BLOCK = 4;

const mod = (a: number, n: number) => ((a % n) + n) % n;

function shuffle<T>(list: T[], seed: number): T[] {
  const out = list.slice(), rng = mulberry32(seed);
  for (let k = out.length - 1; k > 0; k--) { const j = Math.floor(rng() * (k + 1)); [out[k], out[j]] = [out[j], out[k]]; }
  return out;
}

/** The plans a megalopolis in this county is dealt (first choice), from its block's deck. */
function megaDeal(seed: string, cx: number, cz: number): PlanId {
  const bx = Math.floor(cx / BLOCK), bz = Math.floor(cz / BLOCK);
  const deck = shuffle([...plansFor('mega'), 'channel'] as PlanId[], hashString(`${seed}|plans|deck|${bx},${bz}`));
  return deck[(mod(cx, BLOCK) + BLOCK * mod(cz, BLOCK)) % deck.length];
}

/** A plan's chain: itself, then its fallbacks this size of town may take, ending at 'grid'. */
function chainOf(id: PlanId, kind: TownKind): PlanId[] {
  const out: PlanId[] = [];
  const add = (p: PlanId) => {
    if (out.includes(p)) return;
    if (p !== 'grid' && !PLAN_INFO[p].tiers.includes(kind)) return;
    out.push(p);
  };
  add(id);
  for (const f of PLAN_INFO[id].fallback) add(f);
  add('grid');
  return out;
}

/** A town's ranked plans: its first choice and that one's chain. */
function rankPlans(w: World, kind: TownKind, index: number): PlanId[] {
  if (kind !== 'mega' && kind !== 'metro' && kind !== 'city') return ['grid'];
  const force = PLAN_TEST.force;
  if (force) return force === 'grid' || PLAN_INFO[force].tiers.includes(kind) ? chainOf(force, kind) : ['grid'];
  if (kind === 'mega') return chainOf(megaDeal(w.seed, w.cx, w.cz), kind);
  const h = hashString(`${w.seed}|plans|${w.cx},${w.cz}|${index}|${kind}`);
  const rng = mulberry32(h);
  if (rng() < (KEEP_TODAY[kind] ?? 0)) return ['grid'];
  const list = plansFor(kind);
  return chainOf(list[Math.floor(rng() * list.length) % list.length], kind);
}

// ---------------------------------------------------------------------------------------------
// the site

/** The sea's distance from each side of a square (DIRS order: east, south, west, north), Infinity past `reach`. */
function seaSides(w: World, land: Uint8Array, x0: number, z0: number, size: number, band: number, reach = 24): number[] {
  const out = [Infinity, Infinity, Infinity, Infinity];
  const D = [[1, 0], [0, 1], [-1, 0], [0, -1]];
  for (let d = 0; d < 4; d++) {
    for (const f of [0.2, 0.35, 0.5, 0.65, 0.8]) {
      const along = Math.round(size * f);
      const mx = d === 0 ? x0 + size - 1 : d === 2 ? x0 : x0 + along;
      const mz = d === 1 ? z0 + size - 1 : d === 3 ? z0 : z0 + along;
      for (let s = 1; s <= reach; s++) {
        const x = mx + D[d][0] * s, z = mz + D[d][1] * s;
        if (!inB(x, z) || x < band || z < band || x >= N - band || z >= N - band) break;
        const i = idx(x, z);
        if (!land[i] && w.elev[i] < SEA) { out[d] = Math.min(out[d], s); break; }
      }
    }
  }
  return out;
}

/** What a found site is like, read before it is softened. */
interface SiteInfo { sea: number[]; std: number; rise: number; level: number; river: number }

function siteInfo(p: TownPlan, ctx: PlanCtx): SiteInfo {
  const E = ctx.w.elev;
  let sum = 0, sq = 0, lo = Infinity, hi = -Infinity, wet = 0;
  for (let z = p.z0; z < p.z0 + p.size; z++) for (let x = p.x0; x < p.x0 + p.size; x++) {
    const i = idx(x, z), e = E[i];
    sum += e; sq += e * e; lo = Math.min(lo, e); hi = Math.max(hi, e);
    if (ctx.river[i] >= 2) wet++;
  }
  const n = p.size * p.size, mean = sum / n;
  return { sea: seaSides(ctx.w, ctx.land, p.x0, p.z0, p.size, ctx.band, 30), std: Math.sqrt(Math.max(0, sq / n - mean * mean)), rise: hi - lo, level: p.level, river: wet };
}

/** The plans that cut sea-level water through their town (the rest only want the sea in sight). */
const DIGS = new Set<PlanId>(['manhattan', 'lakefront', 'canalring', 'spiral', 'archipelago', 'fronds', 'vertical']);

/** Will this site take this plan? Its asks only: whatever else it needs is tried when it carves. */
export function fits(id: PlanId, s: SiteInfo): boolean {
  const want = PLAN_INFO[id].wants;
  if (!want) return true;
  if (want.sea && !s.sea.some((d) => d <= 24)) return false;
  if (want.relief && s.std < 0.6 && s.rise < 3) return false;
  // the amphitheatre rises from a bay: the sea right at its foot, and low enough to bring the bay up to its quay
  if (id === 'amphitheatre' && (!s.sea.some((d) => d <= 16) || s.level > SEA + 9)) return false;
  // water dug at sea level wants a town low enough that its banks are quays, not gorges
  if ((want.river || DIGS.has(id)) && s.level > SEA + 6) return false;
  return true;
}

/** Is any of the sea within reach of the square's rim? (8 samples of the distance to the coast.) */
function seaNear(w: World, x0: number, z0: number, size: number): boolean {
  for (const [fx, fz] of [[0, 0], [0.5, 0], [1, 0], [1, 0.5], [1, 1], [0.5, 1], [0, 1], [0, 0.5]]) {
    const x = Math.min(N - 1, Math.round(x0 + fx * (size - 1))), z = Math.min(N - 1, Math.round(z0 + fz * (size - 1)));
    if (w.coastDist[idx(x, z)] <= 22) return true;
  }
  return false;
}

PLAN_HOOKS.wants = (w, kind, index) => {
  if (kind !== 'mega' && kind !== 'metro' && kind !== 'city') return null;
  const ranked = rankPlans(w, kind, index);
  const want = PLAN_INFO[ranked[0]].wants ?? {};
  return { w, kind, ranked, river: !!want.river, relief: !!want.relief, sea: !!want.sea, arms: !!want.arms };
};

PLAN_HOOKS.siteScore = (wants: SiteWants, x0, z0, size, std, wet) => {
  let s = 0;
  if (wants.river) s -= 1.2 * Math.min(1, wet / (size * 2));
  // a hill plan takes the hills the usual score turns away from (and gives back the penalty they carry)
  if (wants.relief) s -= Math.min(2.5, std * 0.8) + Math.max(0, std - 1.5) * 0.5;
  if (wants.sea && seaNear(wants.w, x0, z0, size)) s -= 1.5;
  // arms want room every way: the middle of the county
  if (wants.arms) s += 0.012 * Math.hypot(x0 + size / 2 - N / 2, z0 + size / 2 - N / 2);
  return s;
};

PLAN_HOOKS.settle = (p, wants, ctx) => {
  const info = siteInfo(p, ctx);
  if (DEBUG) console.log(`plans: ${p.kind} at ${ctx.w.cx},${ctx.w.cz} ranked ${wants.ranked.join(' > ')}; sea ${info.sea.map((d) => (d === Infinity ? '-' : d)).join('/')}, std ${info.std.toFixed(2)}, rise ${info.rise.toFixed(1)}, level ${info.level}`);
  const id = wants.ranked.find((r) => fits(r, info)) ?? 'grid';
  p.plan = id;
  const keep = PLAN_INFO[id].keepRelief;
  if (keep !== undefined) p.keepRelief = keep;
};

PLAN_HOOKS.carve = (p, ctx) => {
  // the plan and then its chain, each tried on the site in turn, until one cuts what it needs (or needs nothing)
  const info = siteInfo(p, ctx);
  const chain = chainOf(p.plan as PlanId, p.kind);
  for (const id of chain) {
    if (id !== p.plan && !fits(id, info)) continue;
    // the channel is towns.ts's to dig: hand back to it
    if (id === 'channel') { p.plan = 'channel'; return false; }
    const carve = CARVERS[id];
    if (!carve || carve(p, ctx, mulberry32(hashString(`${ctx.w.seed}|plans|carve|${ctx.w.cx},${ctx.w.cz}|${p.x0},${p.z0}|${id}`)))) {
      p.plan = id;
      return true;
    }
    if (DEBUG) console.log(`plans: ${id} would not carve at ${ctx.w.cx},${ctx.w.cz} (${p.kind} at ${p.x0},${p.z0})`);
  }
  p.plan = 'grid';
  return true;
};

PLAN_HOOKS.satellite = (host, cx, cz) => {
  const note = host.carved?.note;
  if (host.plan !== 'fingers' || !note?.n) return 0;
  const hx = host.x0 + host.size / 2, hz = host.z0 + host.size / 2;
  let best = Infinity;
  for (let k = 0; k < note.n; k++) {
    const code = note[`f${k}`];
    const [dx, dz] = COMPASS[Math.floor(code / 1000)], L = code % 1000;
    best = Math.min(best, Math.hypot(hx + dx * (host.size / 2 + L) - cx, hz + dz * (host.size / 2 + L) - cz));
  }
  return best * 0.05;
};

PLAN_HOOKS.taste = (p, taste) => {
  const lean = PLAN_INFO[p.plan as PlanId]?.styles;
  if (!lean) return taste;
  const out: Partial<Record<Arch, number>> = { ...taste };
  for (const k of Object.keys(out) as Arch[]) out[k] = (out[k] ?? 0) * (lean[k] ?? 1);
  return out;
};

PLAN_HOOKS.lay = (c: Layout, p: TownPlan) => {
  const id = p.plan as PlanId;
  const lay = LAYERS[id];
  if (!lay) return false;
  const t0 = performance.now();
  const ok = lay(c, p, mulberry32(hashString(`${c.w.seed}|plans|lay|${c.w.cx},${c.w.cz}|${p.x0},${p.z0}|${id}`)));
  const key = `${c.w.cx},${c.w.cz}|${c.t.name}`;
  PLAN_TIME.set(key, { carve: PLAN_TIME.get(key)?.carve ?? 0, lay: performance.now() - t0 });
  return ok;
};
