import type { KindSpec } from './townKinds';
import { Lot } from './tiles';

/**
 * Places to play (GEN 53, world/nextWorld.ts): an elementary school with its yard of jungle gyms, a go-kart
 * course with karts racing round it, and an archery range with archers at the line; and (0.7.0) the rare outdoor
 * mall, shops and a cinema round open-air walks in its car parks (world/malls.ts), and the private beach resort on a warm
 * shore, placed as a work of its own (world/beachResorts.ts). The towns put the others up
 * (world/towns.ts, behind NEXT_WORLD), a playground beside every school. One table, spread into the game's
 * per-kind tables (townKinds, towns' heights, economy, estate, hqGrade, cargo labels, traffic tags, the
 * gallery's sizes), so a fourth would be added here once. The models are in render/buildings/play*.ts.
 */

export const PLAY_KINDS = [
  'elementarySchool', 'kartTrack', 'archeryRange', 'outdoorMall', 'beachResort',
  // a mine's buildings (world/mines.ts, 0.7.0)
  'oreMill', 'tailings', 'crawlerCrane', 'derrick', 'gravelPlant', 'dragline', 'coalTipple',
] as const;

export type PlayKind = (typeof PLAY_KINDS)[number];

interface Info {
  label: string;
  icon: string;
  /** The lot in tiles: W across its front, D deep. */
  size: [number, number];
  /** How tall the model stands, in world units (towns.ts buildingHeight). */
  h: number;
  /** What it costs to knock down (economy.ts), which sets a lot's floor price. */
  price: number;
  /** As an HQ (hqGrade.ts). */
  grade: 0 | 1 | 2 | 3;
  zone: KindSpec['zone'];
  lot: Lot;
  /** What kind of place a trip there is (game/traffic.ts TAG_OF). */
  tag: 'work' | 'leisure' | 'shop';
}

export const PLAY_INFO: Record<PlayKind, Info> = {
  elementarySchool: { label: 'Elementary school', icon: '🏫', size: [4, 3], h: 0.95, price: 549, grade: 3, zone: 'mid', lot: Lot.Lawn, tag: 'work' },
  kartTrack: { label: 'Go-kart track', icon: '🏎️', size: [6, 4], h: 0.5, price: 449, grade: 1, zone: 'edge', lot: Lot.Lawn, tag: 'leisure' },
  archeryRange: { label: 'Archery range', icon: '🏹', size: [5, 3], h: 0.45, price: 249, grade: 1, zone: 'edge', lot: Lot.Lawn, tag: 'leisure' },
  beachResort: { label: 'Beach resort', icon: '🏝️', size: [16, 12], h: 1.75, price: 4999, grade: 3, zone: 'edge', lot: Lot.Plaza, tag: 'leisure' },
  oreMill: { label: 'Ore processing plant', icon: '🏭', size: [6, 4], h: 1.3, price: 1999, grade: 2, zone: 'edge', lot: Lot.Gravel, tag: 'work' },
  tailings: { label: 'Tailings pond', icon: '🟫', size: [7, 7], h: 0.15, price: 199, grade: 0, zone: 'edge', lot: Lot.Gravel, tag: 'work' },
  crawlerCrane: { label: 'Crawler crane', icon: '🏗️', size: [2, 3], h: 2.2, price: 499, grade: 0, zone: 'edge', lot: Lot.Gravel, tag: 'work' },
  derrick: { label: 'Derrick crane', icon: '🏗️', size: [2, 2], h: 2.6, price: 399, grade: 0, zone: 'edge', lot: Lot.Gravel, tag: 'work' },
  gravelPlant: { label: 'Gravel screening plant', icon: '🏭', size: [4, 3], h: 0.9, price: 899, grade: 1, zone: 'edge', lot: Lot.Gravel, tag: 'work' },
  dragline: { label: 'Walking dragline', icon: '🏗️', size: [4, 4], h: 2.4, price: 1499, grade: 0, zone: 'edge', lot: Lot.Gravel, tag: 'work' },
  coalTipple: { label: 'Coal tipple', icon: '⛏️', size: [3, 3], h: 1.4, price: 999, grade: 1, zone: 'edge', lot: Lot.Gravel, tag: 'work' },
  outdoorMall: { label: 'Outdoor mall', icon: '🛍️', size: [10, 8], h: 1.05, price: 1499, grade: 3, zone: 'edge', lot: Lot.Asphalt, tag: 'shop' },
};

const pick = <T>(f: (i: Info) => T): Record<PlayKind, T> => Object.fromEntries(PLAY_KINDS.map((k) => [k, f(PLAY_INFO[k])])) as Record<PlayKind, T>;

/** Spread into townKinds' KIND_SPEC. */
export const PLAY_SPEC = pick((i): KindSpec => ({ w: i.size[0], d: i.size[1], zone: i.zone, lot: i.lot, gap: 1, apart: 10 }));
export const PLAY_HEIGHT = pick((i) => i.h);
export const PLAY_PRICE = pick((i) => i.price);
export const PLAY_ICON = pick((i) => i.icon);
export const PLAY_LABEL = pick((i) => i.label);
export const PLAY_GRADE = pick((i) => i.grade);
export const PLAY_SIZE = pick((i) => i.size);
export const PLAY_TAG = pick((i) => i.tag);
const isPlayKind = (k: string): k is PlayKind => k in PLAY_INFO;
