/**
 * Giant groves: a rare find out in the country, a stand of trees several times the size of any other.
 * Coast redwoods in damp temperate woods, a great spreading oak alone in temperate farmland, a grove
 * of bottle-trunked baobabs on the savanna, and a banyan in the wet tropics whose aerial roots stand
 * round it like a cloister. Each grove is a named landform ('grove'), so riding into one announces it
 * and it shows on the map, the region map and the tourist board.
 *
 * Placement is a pure function of the seed and the finished cell (no rng draws, so nothing else in the
 * generator shifts): at most one grove a cell, tried on about a fifth of them (most of the Big Timber's), sited where the climate
 * suits a species and enough clear ground stands round it. The trees themselves are worked out from
 * the landmark when a chunk's props are built (groveTrees), against the tiles as they are then, so a
 * road laid later, a lot, or the bulldozer clears them exactly as it clears any other tree.
 */
import { N, Biome, Flag, Surface, World, idx, inB, steepness, type Landmark } from './tiles';
import { hash2, hashCell } from './rng';
import { RAIL_KEEP_CLEAR } from './fences';
import { insideCurve } from './curves';
import { blobScale, landformName } from './landforms';

export type GiantKind = 'giantRedwood' | 'greatOak' | 'giantBaobab' | 'banyan';
/** Indexed by a grove landmark's data[0]. */
export const GIANT_KINDS: GiantKind[] = ['giantRedwood', 'greatOak', 'giantBaobab', 'banyan'];

interface GroveSpec {
  /** Its name from the landform word: "Kestrel Redwoods", "the Kestrel Oak". */
  name: (a: string) => string;
  /** Radius range in tiles, and the lattice the trees stand on. */
  r: [number, number]; spacing: number;
  /** Share of lattice points that grow a tree. */
  density: number;
  /** Tiles kept clear of roads, rail, lots and buildings round each tree (its crown and roots). */
  clear: number;
  /** Tiles round a tree where no ordinary tree grows (under its crown). */
  shade: number;
  /** Fewest trees a site must hold. */
  min: number;
  /** One great tree in the middle that the grove is named for (it must be able to stand). */
  centre: boolean;
  /** Instance scale of the others, and of the centre tree. */
  scale: [number, number]; centreScale: number;
  /** How far the trunk reaches from its middle, for seating it on a slope. */
  foot: number;
}

export const GROVE_SPECS: Record<GiantKind, GroveSpec> = {
  giantRedwood: { name: (a) => `${a} Redwoods`, r: [7, 11], spacing: 2, density: 0.72, clear: 1, shade: 0, min: 12, centre: true, scale: [0.82, 1.12], centreScale: 1.3, foot: 0.3 },
  greatOak: { name: (a) => `the ${a} Oak`, r: [6, 6], spacing: 4, density: 0.4, clear: 2, shade: 1, min: 1, centre: true, scale: [0.72, 0.9], centreScale: 1.15, foot: 0.26 },
  giantBaobab: { name: (a) => `${a} Baobabs`, r: [7, 10], spacing: 3, density: 0.7, clear: 1, shade: 1, min: 6, centre: false, scale: [0.8, 1.12], centreScale: 1, foot: 0.62 },
  banyan: { name: (a) => `the ${a} Banyan`, r: [8, 8], spacing: 5, density: 0.5, clear: 2, shade: 2, min: 1, centre: true, scale: [0.72, 0.9], centreScale: 1.12, foot: 0.3 },
};

/** Share of cells that try for a grove at all, and of the Big Timber's (a giant forest already). */
const GROVE_CHANCE = 0.16;
const BIG_TIMBER_CHANCE = 0.7;

interface GiantTree {
  kind: GiantKind;
  /** Its tile (local), and where on it the trunk stands. */
  tx: number; tz: number; x: number; z: number;
  yaw: number; s: number;
}

/** Ground an ordinary tree would grow on, wide open enough for a giant, given how far it must be kept clear. */
function giantGround(w: World, x: number, z: number, clear: number): boolean {
  if (x < 3 + clear || z < 3 + clear || x >= N - 3 - clear || z >= N - 3 - clear) return false;
  const i = idx(x, z);
  if (w.water[i] >= 0 || w.cleared[i] || steepness(w, i) >= 2 || w.surface[i] !== Surface.None) return false;
  const b = w.biome[i];
  if (b !== Biome.Plains && b !== Biome.Hills && b !== Biome.Forest && b !== Biome.Farm) return false;
  if (w.flags[i] & Flag.Field || insideCurve(w, i)) return false;
  for (let dz = -clear; dz <= clear; dz++) {
    for (let dx = -clear; dx <= clear; dx++) {
      const j = idx(x + dx, z + dz);
      if (w.road[j] || w.deckAxis[j] || w.rail[j] & RAIL_KEEP_CLEAR || w.blocked[j] || w.townId[j] >= 0 || w.portId[j] >= 0 || w.lot[j] || w.feature[j]) return false;
      if (w.flags[j] & (Flag.Track | Flag.Poi | Flag.Ramp) || w.biome[j] === Biome.Town) return false;
    }
  }
  return true;
}

/** The giant trees of one grove, against the tiles as they stand now. The centre tree, if any, comes first. */
export function groveTrees(w: World, l: Landmark): GiantTree[] {
  const kind = GIANT_KINDS[l.data?.[0] ?? 0] ?? 'giantRedwood';
  const sp = GROVE_SPECS[kind];
  const cx = Math.floor(l.x), cz = Math.floor(l.z);
  const gx0 = w.ox + cx, gz0 = w.oz + cz;
  const shape = blobScale(gx0, gz0, 7111, 0.3);
  const S = sp.spacing, reach = Math.ceil(l.r / S) + 1;
  const out: GiantTree[] = [];
  for (let j = -reach; j <= reach; j++) {
    for (let i = -reach; i <= reach; i++) {
      const centre = i === 0 && j === 0 && sp.centre;
      // the lattice point's own hashes, on global lattice ids so a grove reads the same from any cell
      const li = gx0 + i * S, lj = gz0 + j * S;
      let tx = cx + i * S, tz = cz + j * S;
      if (!centre) {
        tx += Math.floor(hash2(li, lj, 7101) * S) - (S >> 1);
        tz += Math.floor(hash2(li, lj, 7102) * S) - (S >> 1);
        if (hash2(li, lj, 7103) >= sp.density) continue;
      }
      const dx = tx - cx, dz = tz - cz;
      if (Math.hypot(dx, dz) > l.r * (dx || dz ? shape(Math.atan2(dz, dx)) : 1)) continue;
      if (!inB(tx, tz) || !giantGround(w, tx, tz, sp.clear)) continue;
      const r1 = hash2(li, lj, 7104), r2 = hash2(li, lj, 7105), r3 = hash2(li, lj, 7106), r4 = hash2(li, lj, 7107);
      const t: GiantTree = {
        kind, tx, tz,
        x: tx + 0.35 + r1 * 0.3, z: tz + 0.35 + r2 * 0.3,
        yaw: r3 * Math.PI * 2,
        s: centre ? sp.centreScale : sp.scale[0] + (sp.scale[1] - sp.scale[0]) * r4,
      };
      if (centre) out.unshift(t);
      else out.push(t);
    }
  }
  // two trees too close (jitter can bring neighbours side by side): the later one goes
  return out.filter((t, k) => !out.some((o, m) => m < k && Math.abs(o.tx - t.tx) <= (S > 2 ? 1 : 0) && Math.abs(o.tz - t.tz) <= (S > 2 ? 1 : 0)));
}

/**
 * The giants standing on one chunk's tiles, and the tiles under any grove's crowns where ordinary
 * trees give way (which may be in the next chunk over).
 */
export function chunkGiants(w: World, x0: number, z0: number, size: number): { trees: GiantTree[]; shade: Set<number> | null } {
  const trees: GiantTree[] = [];
  let shade: Set<number> | null = null;
  for (const l of w.landmarks) {
    if (l.kind !== 'grove') continue;
    const pad = l.r + 4;
    if (l.x + pad < x0 || l.z + pad < z0 || l.x - pad > x0 + size || l.z - pad > z0 + size) continue;
    const sp = GROVE_SPECS[GIANT_KINDS[l.data?.[0] ?? 0] ?? 'giantRedwood'];
    for (const t of groveTrees(w, l)) {
      if (t.tx >= x0 && t.tz >= z0 && t.tx < x0 + size && t.tz < z0 + size) trees.push(t);
      const r = sp.shade;
      for (let dz = -r; dz <= r; dz++) for (let dx = -r; dx <= r; dx++) {
        const x = t.tx + dx, z = t.tz + dz;
        if (x < x0 || z < z0 || x >= x0 + size || z >= z0 + size) continue;
        (shade ??= new Set()).add(idx(x, z));
      }
    }
  }
  return { trees, shade };
}

/** Which species, if any, suits a site: its climate, its ground and its biome. */
function speciesFor(w: World, i: number, moist: number, roll: number): GiantKind | null {
  const t = w.temp[i], b = w.biome[i];
  if (w.region === 'bigtimber' && (b === Biome.Forest || b === Biome.Hills)) return 'giantRedwood';
  const open = b === Biome.Plains || b === Biome.Hills, wood = b === Biome.Forest || b === Biome.Hills;
  const fits: GiantKind[] = [];
  // redwoods in damp woods from the cool north to the warm temperate; banyans in the wet tropics
  if (t >= 0.26 && t < 0.8 && moist >= 0.6 && wood) fits.push('giantRedwood');
  if (t >= 0.72 && moist >= 0.6 && (wood || open)) fits.push('banyan');
  // baobabs on dry warm savanna; a great oak alone in temperate farmland and meadow
  if (t >= 0.66 && moist >= 0.2 && moist < 0.58 && open) fits.push('giantBaobab');
  if (t >= 0.38 && t < 0.86 && moist >= 0.32 && moist < 0.75 && (open || b === Biome.Farm)) fits.push('greatOak');
  return fits.length ? fits[Math.floor(roll * fits.length)] : null;
}

/**
 * Site this cell's grove, if it has one. Called once the cell is finished (roads, rail, towns, works,
 * POIs), so a grove never lands on any of them; `moisture` is the generator's per-tile moisture.
 */
export function placeGroves(w: World, moisture: Float32Array, seedHash: number, band: number): void {
  const roll = hashCell(seedHash, w.cx, w.cz, 7001) / 4294967296;
  if (roll >= (w.region === 'bigtimber' ? BIG_TIMBER_CHANCE : GROVE_CHANCE)) return;
  const keep = band + 20, span = N - 2 * keep;
  if (span < 20) return;
  for (let k = 0; k < 80; k++) {
    const h = hashCell(seedHash, w.cx, w.cz, 7010 + k);
    const x = keep + (h % span), z = keep + ((h >>> 12) % span);
    const i = idx(x, z);
    const kind = speciesFor(w, i, moisture[i], hash2(w.cx, w.cz, 7003 + (seedHash & 0xffff)));
    if (!kind) continue;
    const sp = GROVE_SPECS[kind];
    const r = sp.r[0] + Math.floor(hash2(w.ox + x, w.oz + z, 7002) * (sp.r[1] - sp.r[0] + 1));
    // clear of every other named place
    if (w.landmarks.some((o) => Math.hypot(o.x - x, o.z - z) < Math.min(o.r, 40) + r + 6)) continue;
    const l: Landmark = { kind: 'grove', name: '', x: x + 0.5, z: z + 0.5, r, data: [GIANT_KINDS.indexOf(kind)] };
    const trees = groveTrees(w, l);
    if (trees.length < sp.min || (sp.centre && (trees[0]?.tx !== x || trees[0]?.tz !== z))) continue;
    l.name = sp.name(landformName('grove', seedHash, w.ox + x, w.oz + z));
    w.landmarks.push(l);
    return;
  }
}
