/**
 * The twenty biomes, as one table.
 *
 * A biome is the existing generator pointed somewhere: the same peaks, rivers, Layout, kit and
 * visitor system, given different numbers. Every column below is read by exactly one layer — the
 * terrain in generate.ts, the palette in mesher.ts, the weather in render/weather.ts, the trees in
 * props.ts, the towns in towns.ts — and none of those layers knows the biomes by name. Which cells
 * carry one is decided in macro.ts from hashes alone.
 */
import {
  REGION_KINDS, type Arch, type BuildingKind, type CellKind, type RegionKind, type TownKind,
} from './tiles';

/** The palette keys a biome may repaint; anything left out keeps the ordinary colour. */
export type PaletteKey =
  | 'plains' | 'hills' | 'forest' | 'beach' | 'cliffTop' | 'desert' | 'canyon' | 'mountainLow' | 'mountainHigh'
  | 'snow' | 'track' | 'lawn' | 'park' | 'yard' | 'bedSand' | 'bedMud' | 'marsh' | 'dune' | 'duneShade'
  | 'cliffEarthTop' | 'cliffEarthBot' | 'cliffPaleTop' | 'cliffPaleBot' | 'cliffGreyTop' | 'cliffGreyBot'
  | 'waterShallow' | 'waterMid' | 'waterDeep';

/** The tree shapes a biome can grow. The first five are the ordinary ones. */
export type TreeKind =
  | 'round' | 'poplar' | 'pine' | 'spruce' | 'palm'
  | 'datePalm' | 'canopy' | 'acacia' | 'baobab' | 'cypress' | 'olive' | 'cherry' | 'bamboo' | 'windPine'
  | 'oak' | 'birch' | 'willow' | 'stonePine' | 'redwood';

/** What stands in a field, one instance a tile (see world/crops.ts). */
export type CropKind = 'wheat' | 'maize' | 'sunflower' | 'pumpkin' | 'lavender'
  // a Dutch bulb field's bands and a rice paddy (world/crops.ts fieldPlan, 0.7.0)
  | 'tulipRed' | 'tulipYellow' | 'tulipPink' | 'tulipWhite' | 'tulipPurple' | 'rice'
  // an oil palm plantation's palms, one a tile (0.7.0)
  | 'oilPalm';

/** Ground clutter: the small things a biome scatters where trees would not stand. */
export type ClutterKind =
  | 'shrub' | 'heather' | 'termiteMound' | 'reeds' | 'fern' | 'haystack' | 'stoneLantern' | 'snowFence'
  | 'beachHut' | 'drystoneWall' | 'iceberg' | 'mooredBoat';

/** The animals and people that wander a biome's country without any pathfinding. */
export type HerdKind = 'camels' | 'sledTeam' | 'herd' | 'sheep' | 'cattle' | 'goats' | 'surfers' | 'hikers' | 'pilgrims' | 'horses';

export interface RegionSpec {
  kind: RegionKind;
  /** "the Sands", and what it is: "desert". */
  title: string;
  label: string;

  // ---------------- where ----------------
  /** Climate at the cell centre an anchor needs, from climateAt. */
  temp?: [number, number];
  wet?: [number, number];
  /** The cell kinds an anchor may be. */
  cells: CellKind[];
  /** A continental anchor must have a coast. */
  coastal?: boolean;
  /** A megalopolis may grow here. */
  mega?: boolean;
  /** Suffixes for a biome island's name ("Amber Sands", "Cinder Cay"). */
  islandSuffix: string[];
  /** How a county in the biome is named: "Harrow Riding · the Veldt" keeps its county name. */

  // ---------------- 1 · terrain ----------------
  /** Climate targets, blended in by the region weight. */
  moisture?: number;
  arid?: number;
  temperature?: number;
  /** The hill mask forced toward this (0 off, 1 everywhere), and a multiplier on hill height. */
  hills?: number;
  hillAmp?: number;
  /** The massif gate forced toward this, for where mountains stand (0 none, 1 everywhere). */
  massif?: number;
  /** The tallest a mountain may stand here, in steps. */
  peakCap?: number;
  /** A multiplier on the lowland relief (swell and hills). */
  relief?: number;
  /** The most any land may rise above the sea here, in steps. */
  cap?: number;
  /** Long dunes over the whole cell. */
  erg?: boolean;
  /** The sea-cliff field forced toward this (0 all beach, 1 all cliff). */
  cliff?: number;
  /** A shelf of shallow sea round the coast this many tiles wide. */
  shelf?: number;
  /** The height in world units above which snow lies all year; null never snows; undefined as normal. */
  snowLine?: number | null;
  /** Shape of a biome island: the share left to water, how hard the coast is pulled in. */
  water?: number;
  falloff?: number;
  /** Broad beaches on an island or county, and how many of the rest of its works. */
  beaches?: number;
  farms?: number;
  quarries?: number;
  pistes?: number;
  airfields?: number;
  /** Extra lakes dug, and waterholes or oases: bowl lakes with a ring of trees. */
  lakes?: number;
  /** Rivers: a multiplier on how many start, and whether they run dry (wadis). */
  rivers?: number;
  dryRivers?: boolean;
  /** Landforms this biome never has, and those it asks for. */
  forbid?: string[];
  /** Cell landforms every cell of the biome carries, whatever the roll says: its volcano, its salt pan, its towers, its mesas. */
  ask?: ('volcano' | 'saltFlat' | 'karstTowers' | 'mesaCountry')[];
  /** The sea let in along fjords, whatever the climate. */
  fjords?: boolean;
  /** Banded badland hills wherever the ground is hilly. */
  badlands?: boolean;
  /** The share of its open country under old lava flows, and under salt crust. */
  lava?: number;
  salt?: number;
  /** Every low warm shore is mangrove swamp. */
  mangroves?: boolean;

  // ---------------- 2 · palette ----------------
  palette: Partial<Record<PaletteKey, number>>;
  /** Crops, in the biome's own colours. */
  crops?: number[];
  /** What grows in each of those colours' patches, one per entry of `crops`. */
  cropKinds?: CropKind[];
  /** Sky tint mixed into the day sky and the fog. */
  sky: number;
  /** Map colour for its land pixels. */
  atlas: number;
  /** Autumn leaf colour, where it differs. */
  autumn?: number;
  /** Round trees blossom pink in spring. */
  blossom?: boolean;

  // ---------------- 4 · props and folk ----------------
  /** Trees per tile on forest, hills, plains and beach, replacing the ordinary density. */
  treeDensity: { forest: number; hills: number; plains: number; beach: number };
  /** The tree mix, as weights. */
  trees: Partial<Record<TreeKind, number>>;
  /** Ground clutter per tile. */
  clutter: Partial<Record<ClutterKind, number>>;
  /** Cacti are an ordinary desert's; a biome says whether it keeps them. */
  cacti?: boolean;
  herds: HerdKind[];
  /** Beachgoers all year rather than in summer. */
  beachAllYear?: boolean;

  // ---------------- 5 · towns ----------------
  /** The roster for a biome island (a county keeps its own, with kinds swapped). */
  towns: TownKind[];
  /** What a county's town kinds become here (a metro in the Icefield is a city). */
  tier?: Partial<Record<TownKind, TownKind>>;
  site?: 'coast' | 'oasis' | 'valley' | 'cliffTop' | 'levee' | 'clearing' | 'lee';
  taste: Partial<Record<Arch, number>>;
  /** Street surface per town kind: brick, dirt, or as normal. */
  surface: Partial<Record<TownKind, 'brick' | 'dirt' | 'paved' | 'cobble'>>;
  /** Town names: first parts and second parts. */
  names: [string[], string[]];
  /** Kinds the builders place that this biome replaces, or drops (null). */
  swaps: Partial<Record<BuildingKind, BuildingKind | null>>;
  /** The village grid step (6 elsewhere). */
  grid?: number;
  /** A multiplier on the eased margin round a town. */
  margin?: number;
  /** The biome's own buildings out in the country, with how many a cell gets. */
  country: { kind: BuildingKind; count: number; w: number; d: number; where: 'any' | 'high' | 'low' | 'shore' | 'water' | 'pass' }[];
  /** The wonder, and its footprint in tiles. */
  wonder: { kind: BuildingKind; name: string[]; w: number; d: number; where: 'flat' | 'high' | 'shore' | 'valley' | 'cape' | 'lake' | 'harbour' };
  /** The lamp a town's streets are lit with. */
  lamp?: 'lantern' | 'torch' | 'none';
}

