import { N, STEP, Biome, DIRS, Feature, Flag, World, idx, inB, steepness, waterDepth, type Building, type BuildingKind } from './tiles';
import type { Rng } from './rng';
import type { RegionSpec } from './regions';
import { buildingHeight } from './towns';
import { solidMask } from './footprint';
import { KIND_SPEC } from './townKinds';
import { ranchBrand } from './ranchKinds';

/**
 * Ranches (GEN 53, world/nextWorld.ts): a homestead yard — the ranch house, the hands' bunkhouse, a barn, the
 * stables, a hay barn, a silo and a round corral behind an arch with the ranch's name on it — on the edge of a
 * great fenced pasture of two to four paddocks, where its herd of cattle or of horses grazes (game/herds.ts keeps
 * them inside the fence). Out in open grass country: the Golden Hills, the Steppe, the Red Rock, the Veldt, and the
 * ordinary counties' plains, more where a town is built in the Old West's style. The fence is an ordinary one a
 * car can knock flat (world/fences.ts); where a road crosses the fence line it rides over a cattle grid instead.
 * Placed last of all the buildings, on a random stream of its own, so nothing else in the county moves for it.
 */

export interface Ranch {
  /** "Lazy K Ranch": its arch's brand (ranchKinds.ts ranchBrand, from the arch's seed) and the word. */
  name: string;
  stock: 'cattle' | 'horses';
  /** Every tile inside the pasture's fence, ascending. Its roads are in it, its yard and buildings are not. */
  pasture: number[];
  /** The homestead yard: a tile rectangle on the pasture's edge, fenced, with the arch in its front row. */
  yard: { x: number; z: number; w: number; d: number };
  /** The DIRS index the arch looks out along, and the tile under its middle, where the lane runs in. */
  facing: number;
  gate: number;
  /** Where the herd goes to drink: the troughs of the pump windmills out in the pasture. */
  water: { x: number; z: number }[];
  /** The middle of the pasture, for its name on the map. */
  x: number; z: number;
}

/** The share of counties of each biome with a ranch; an ordinary county's chance is ORDINARY, more with a western town. */
const CHANCE: Partial<Record<RegionSpec['kind'], number>> = { goldhills: 0.75, steppe: 0.6, redrock: 0.4, veldt: 0.3 };
const ORDINARY = 0.3, WESTERN = 0.45;
/** A paddock's share of open grass at least, and of ground that can't be pasture at most (roads, trees and streams are the rest). */
const MAIN_NICE = 0.7, MAIN_HARD = 0.1;
/** Why a county that rolled a ranch has none, counted for scripts/ranches.ts. */
export const RANCH_WHY = new Map<string, number>();
const why = (s: string) => RANCH_WHY.set(s, (RANCH_WHY.get(s) ?? 0) + 1);
/** The share of a biome's ranches that run horses rather than cattle. */
const HORSES: Partial<Record<RegionSpec['kind'], number>> = { steppe: 0.8, goldhills: 0.35, redrock: 0.4 };
const HORSES_ELSE = 0.3;
/** A second ranch in the county, once the first is placed. */
const SECOND = 0.35;

/** Tiles kept between a pasture and a town's square, and between two ranches. */
const TOWN_CLEAR = 10, RANCH_CLEAR = 6;
/** The yard, across its front (u) and from the front back (v). */
const YARD_W = 11, YARD_D = 8;

/** Where each building of the yard stands, in the yard's frame: u across from its front-left, v back from the front. */
type Face = 'front' | 'left' | 'right' | 'back';
const LAYOUT: { kind: BuildingKind; u: number; v: number; bu: number; bv: number; face: Face; must?: true }[] = [
  { kind: 'ranchGate', u: 4, v: 0, bu: 3, bv: 1, face: 'front', must: true },
  { kind: 'ranchHouse', u: 1, v: 1, bu: 2, bv: 2, face: 'right', must: true },
  { kind: 'bunkhouse', u: 7, v: 1, bu: 1, bv: 2, face: 'left' },
  { kind: 'silo', u: 9, v: 1, bu: 1, bv: 1, face: 'left' },
  { kind: 'barn', u: 1, v: 4, bu: 2, bv: 2, face: 'right' },
  { kind: 'stables', u: 7, v: 4, bu: 2, bv: 2, face: 'left' },
  { kind: 'ranchCorral', u: 4, v: 5, bu: 3, bv: 3, face: 'back' },
  { kind: 'hayBarn', u: 8, v: 6, bu: 2, bv: 2, face: 'left' },
];
/** The drive from the arch up the middle of the yard, laid as a lane: its far end. */
const DRIVE_U = 5, DRIVE_V = 4;

/** Summed counts over a tile predicate, for any rectangle's count in four reads. */
class Area {
  private s = new Int32Array((N + 1) * (N + 1));
  constructor(f: (i: number) => number) {
    for (let z = 0; z < N; z++) {
      let row = 0;
      for (let x = 0; x < N; x++) {
        row += f(z * N + x);
        this.s[(z + 1) * (N + 1) + x + 1] = this.s[z * (N + 1) + x + 1] + row;
      }
    }
  }
  /** The count over [x0, x0 + w) × [z0, z0 + d). */
  sum(x0: number, z0: number, w: number, d: number): number {
    const a = this.s, W = N + 1;
    return a[(z0 + d) * W + x0 + w] - a[z0 * W + x0 + w] - a[(z0 + d) * W + x0] + a[z0 * W + x0];
  }
}

/** The ranches of a county (generate.ts calls it after the story chains' stages, before roads under buildings are mended). */
export function placeRanches(w: World, rng: Rng, band: number, spec: RegionSpec | null, lane?: (gate: number) => void): void {
  if (w.kind === 'islet' || w.kind === 'atoll' || w.kind === 'sea') return;
  const western = w.towns.some((t) => t.style === 'western' || t.style === 'motherroad');
  const chance = spec ? CHANCE[spec.kind] ?? 0 : ORDINARY + (western ? WESTERN : 0);
  // every roll is drawn whatever the dice say, so each county's stream reads the same way
  const roll = rng(), second = rng(), horses = rng();
  if (roll >= chance) return;
  why('rolled');
  const lo = band + 6, hi = N - band - 6;

  // what can never be pasture, and the open grass country a herd wants
  const nearTown = new Uint8Array(N * N);
  for (const t of w.towns) {
    for (let z = Math.max(0, t.z0 - TOWN_CLEAR); z < Math.min(N, t.z0 + t.size + TOWN_CLEAR); z++) {
      for (let x = Math.max(0, t.x0 - TOWN_CLEAR); x < Math.min(N, t.x0 + t.size + TOWN_CLEAR); x++) nearTown[z * N + x] = 1;
    }
  }
  const taken = new Uint8Array(N * N);
  const hardAt = (i: number): boolean => {
    const x = i % N, z = (i - x) / N;
    if (x < lo || z < lo || x >= hi || z >= hi || nearTown[i] || taken[i]) return true;
    if (w.townId[i] >= 0 || w.portId[i] >= 0 || w.rail[i] || w.blocked[i] || w.deckAxis[i] || w.feature[i] !== Feature.None) return true;
    if (w.flags[i] & (Flag.Field | Flag.Poi | Flag.Ramp | Flag.Corridor | Flag.River | Flag.Terrace)) return true;
    if (w.biome[i] === Biome.Ocean || waterDepth(w, i) > 1 || steepness(w, i) > 2) return true;
    return false;
  };
  const GRASS = new Set<number>([Biome.Plains, Biome.Hills, Biome.Desert, Biome.Farm]);
  const niceAt = (i: number): boolean => !hardAt(i) && GRASS.has(w.biome[i]) && !w.road[i] && w.water[i] < 0 && steepness(w, i) <= 1;

  const count = second < SECOND ? 2 : 1;
  for (let k = 0; k < count; k++) {
    const hard = new Area((i) => (hardAt(i) ? 1 : 0));
    const nice = new Area((i) => (niceAt(i) ? 1 : 0));
    const fits = (x0: number, z0: number, rw: number, rd: number, nMin: number, hMax: number): number => {
      if (x0 < lo || z0 < lo || x0 + rw > hi || z0 + rd > hi) return -1;
      const a = rw * rd, n = nice.sum(x0, z0, rw, rd) / a, h = hard.sum(x0, z0, rw, rd) / a;
      return n >= nMin && h <= hMax ? n : -1;
    };

    // ---- the main pasture: as big a rectangle of open grass as the county has ----
    let main: { x: number; z: number; w: number; d: number } | null = null, best = -Infinity;
    for (let t = 0; t < 700; t++) {
      const rw = 18 + Math.floor(rng() * 24), rd = 16 + Math.floor(rng() * 22);
      if (hi - lo - rw < 1 || hi - lo - rd < 1) continue;
      const x0 = lo + Math.floor(rng() * (hi - lo - rw)), z0 = lo + Math.floor(rng() * (hi - lo - rd));
      const n = fits(x0, z0, rw, rd, MAIN_NICE, MAIN_HARD);
      if (n < 0) continue;
      const score = rw * rd * n + rng() * 60;
      if (score > best) { best = score; main = { x: x0, z: z0, w: rw, d: rd }; }
    }
    if (!main) { why('no open ground'); return; }

    // ---- the yard: on the side of the pasture a road comes nearest to, with its arch looking at the road ----
    const roads: number[] = [];
    for (let i = 0; i < N * N; i++) if (w.road[i] && !w.blocked[i] && !w.deckAxis[i]) roads.push(i);
    const roadDist = (i: number): number => {
      const x = i % N, z = (i - x) / N;
      let d = Infinity;
      for (const r of roads) { const rx = r % N, rz = (r - rx) / N; d = Math.min(d, Math.abs(rx - x) + Math.abs(rz - z)); }
      return d;
    };
    const inMain = (x: number, z: number) => x >= main!.x && z >= main!.z && x < main!.x + main!.w && z < main!.z + main!.d;
    let yard: { d: number; ox: number; oz: number; score: number } | null = null;
    for (let d = 0; d < 4; d++) {
      const F = DIRS[d], R = DIRS[(d + 1) & 3];
      // the front row: the rectangle's tiles along side d
      const along = d % 2 === 0 ? main.d : main.w;
      for (let s = 0; s < along; s += 2) {
        const fx = d === 0 ? main.x + main.w - 1 : d === 2 ? main.x : main.x + s;
        const fz = d === 1 ? main.z + main.d - 1 : d === 3 ? main.z : main.z + s;
        // the yard's front-left tile: from where along the side the scan is, back so u runs along R
        const ox = fx, oz = fz;
        let ok = true, lo2 = 127, hi2 = -128;
        for (let v = 0; v < YARD_D && ok; v++) {
          for (let u = 0; u < YARD_W && ok; u++) {
            const x = ox + u * R[0] - v * F[0], z = oz + u * R[1] - v * F[1];
            if (!inMain(x, z)) { ok = false; break; }
            const i = idx(x, z);
            if (hardAt(i) || w.road[i] || w.water[i] >= 0) { ok = false; break; }
            for (let q = 0; q < 4; q++) { const c = w.corners[i * 4 + q]; lo2 = Math.min(lo2, c); hi2 = Math.max(hi2, c); }
          }
        }
        if (!ok || hi2 - lo2 > 2) continue;
        // the tile in front of the arch's middle, out on the road side
        const gx = ox + DRIVE_U * R[0] + F[0], gz = oz + DRIVE_U * R[1] + F[1];
        if (!inB(gx, gz) || hardAt(idx(gx, gz)) && !w.road[idx(gx, gz)]) continue;
        const rd = roadDist(idx(gx, gz));
        if (rd > 60) continue;
        const score = rd + (hi2 - lo2) * 4 + rng() * 3;
        if (!yard || score < yard.score) yard = { d, ox, oz, score };
      }
    }
    if (!yard) { why('no yard'); return; }
    const F = DIRS[yard.d], R = DIRS[(yard.d + 1) & 3];
    const at = (u: number, v: number) => ({ x: yard!.ox + u * R[0] - v * F[0], z: yard!.oz + u * R[1] - v * F[1] });
    const c0 = at(0, 0), c1 = at(YARD_W - 1, YARD_D - 1);
    const yr = { x: Math.min(c0.x, c1.x), z: Math.min(c0.z, c1.z), w: Math.abs(c1.x - c0.x) + 1, d: Math.abs(c1.z - c0.z) + 1 };
    const inYard = (x: number, z: number) => x >= yr.x && z >= yr.z && x < yr.x + yr.w && z < yr.z + yr.d;

    // ---- one to three more paddocks off the other sides, so the whole thing sprawls ----
    const rects = [main];
    const extra = 1 + Math.floor(rng() * 3);
    for (let e = 0; e < extra; e++) {
      for (let t = 0; t < 40; t++) {
        const base = rects[Math.floor(rng() * rects.length)];
        const side = Math.floor(rng() * 4);
        if (base === main && side === yard.d) continue;
        const pw = 12 + Math.floor(rng() * 18), pd = 10 + Math.floor(rng() * 14);
        // [pw across the side, pd out from it], turned to the side
        const rw = side % 2 === 0 ? pd : pw, rd = side % 2 === 0 ? pw : pd;
        const slide = (n: number, m: number) => Math.floor(rng() * (n + m - 8)) - m + 4;
        const x0 = side === 0 ? base.x + base.w : side === 2 ? base.x - rw : base.x + slide(base.w, rw);
        const z0 = side === 1 ? base.z + base.d : side === 3 ? base.z - rd : base.z + slide(base.d, rd);
        // nothing in front of the arch
        let blocksGate = false;
        for (let z = z0; z < z0 + rd && !blocksGate; z++) for (let x = x0; x < x0 + rw && !blocksGate; x++) {
          const gx = x - yr.x, gz = z - yr.z;
          if (gx >= -3 && gz >= -3 && gx < yr.w + 3 && gz < yr.d + 3 && !inMain(x, z)) blocksGate = true;
        }
        if (blocksGate || fits(x0, z0, rw, rd, MAIN_NICE - 0.05, MAIN_HARD + 0.02) < 0) continue;
        rects.push({ x: x0, z: z0, w: rw, d: rd });
        break;
      }
    }

    // ---- the pasture: every tile of the paddocks that can be, the yard taken out, tidied to one piece ----
    const mask = new Uint8Array(N * N);
    for (const r of rects) for (let z = r.z; z < r.z + r.d; z++) for (let x = r.x; x < r.x + r.w; x++) {
      const i = idx(x, z);
      if (!hardAt(i) && !inYard(x, z)) mask[i] = 1;
    }
    // spurs one tile wide are pared off, then all but the biggest piece
    for (let pass = 0; pass < 3; pass++) {
      const cut: number[] = [];
      for (let i = 0; i < N * N; i++) {
        if (!mask[i]) continue;
        const x = i % N, z = (i - x) / N;
        let n = 0;
        for (const [dx, dz] of DIRS) if (inB(x + dx, z + dz) && mask[idx(x + dx, z + dz)]) n++;
        if (n <= 1) cut.push(i);
      }
      for (const i of cut) mask[i] = 0;
    }
    const comp = new Int32Array(N * N).fill(-1);
    let bestC = -1, bestN = 0, nc = 0;
    for (let s = 0; s < N * N; s++) {
      if (!mask[s] || comp[s] >= 0) continue;
      const stack = [s];
      comp[s] = nc;
      let n = 0;
      while (stack.length) {
        const i = stack.pop()!;
        n++;
        const x = i % N, z = (i - x) / N;
        for (const [dx, dz] of DIRS) {
          if (!inB(x + dx, z + dz)) continue;
          const j = idx(x + dx, z + dz);
          if (mask[j] && comp[j] < 0) { comp[j] = nc; stack.push(j); }
        }
      }
      if (n > bestN) { bestN = n; bestC = nc; }
      nc++;
    }
    const pasture: number[] = [];
    for (let i = 0; i < N * N; i++) if (mask[i] && comp[i] === bestC) pasture.push(i);
    if (pasture.length < 300) { why('pasture too small'); return; }

    // ---- the buildings: the yard's, then a pump windmill or two out in the pasture ----
    const put = (kind: BuildingKind, x: number, z: number, bw: number, bd: number, facing: number, flagAll = true): Building | null => {
      let sum = 0, lo2 = 127, hi2 = -128;
      for (let zz = z; zz < z + bd; zz++) for (let xx = x; xx < x + bw; xx++) for (let q = 0; q < 4; q++) {
        const c = w.corners[idx(xx, zz) * 4 + q];
        sum += c; lo2 = Math.min(lo2, c); hi2 = Math.max(hi2, c);
      }
      if (hi2 - lo2 > 1) return null;
      const solid = KIND_SPEC[kind]?.solid !== false;
      const b: Building = { kind, x, z, w: bw, d: bd, facing, floors: 1, seed: Math.floor(rng() * 2 ** 31), solid, level: Math.round(sum / (bw * bd * 4)), uid: w.allBuildings.length };
      w.allBuildings.push(b);
      w.countryside.push(b);
      const top = b.level * STEP + buildingHeight(b);
      const sm = solid ? solidMask(b) : null;
      for (let zz = z; zz < z + bd; zz++) for (let xx = x; xx < x + bw; xx++) {
        const i = idx(xx, zz);
        if (flagAll) w.flags[i] |= Flag.Poi;
        if (sm && sm[(zz - z) * bw + xx - x]) { w.blocked[i] = 1; w.roof[i] = Math.max(w.roof[i], top); }
      }
      return b;
    };
    const faceOf = (f: Face) => f === 'front' ? yard!.d : f === 'back' ? (yard!.d + 2) & 3 : f === 'right' ? (yard!.d + 1) & 3 : (yard!.d + 3) & 3;
    let gate: Building | null = null;
    let failed = false;
    for (const s of LAYOUT) {
      const a = at(s.u, s.v), b2 = at(s.u + s.bu - 1, s.v + s.bv - 1);
      const x = Math.min(a.x, b2.x), z = Math.min(a.z, b2.z), bw = Math.abs(b2.x - a.x) + 1, bd = Math.abs(b2.z - a.z) + 1;
      // the arch's posts are its ground; the lane runs in under the middle of it
      const b = put(s.kind, x, z, bw, bd, faceOf(s.face), s.kind !== 'ranchGate');
      if (s.kind === 'ranchGate' && b) {
        gate = b;
        for (const u of [s.u, s.u + s.bu - 1]) { const p = at(u, s.v); w.flags[idx(p.x, p.z)] |= Flag.Poi; }
      }
      if (!b && s.must) { failed = true; break; }
    }
    if (failed || !gate) {
      // the ground let the arch or the house down after all: take back what went up
      while (w.countryside.length && w.allBuildings.length && w.countryside[w.countryside.length - 1].uid >= (gate?.uid ?? w.allBuildings.length)) {
        const b = w.countryside.pop()!;
        w.allBuildings.pop();
        for (let zz = b.z; zz < b.z + b.d; zz++) for (let xx = b.x; xx < b.x + b.w; xx++) { const i = idx(xx, zz); w.flags[i] &= ~Flag.Poi; w.blocked[i] = 0; w.roof[i] = 0; }
      }
      why('yard not level');
      return;
    }
    const inPasture = new Uint8Array(N * N);
    for (const i of pasture) inPasture[i] = 1;
    const yc = { x: yr.x + yr.w / 2, z: yr.z + yr.d / 2 };
    const water: { x: number; z: number }[] = [];
    const pumps = pasture.length > 1400 ? 2 : 1;
    for (let p = 0; p < pumps; p++) {
      let pick = -1, ps = -Infinity;
      for (let t = 0; t < 120; t++) {
        const i = pasture[Math.floor(rng() * pasture.length)];
        const x = i % N, z = (i - x) / N;
        if (!niceAt(i) || steepness(w, i) > 0) continue;
        // with room round it for the trough and the herd
        let room = true;
        for (const [dx, dz] of [...DIRS, [1, 1], [-1, 1], [1, -1], [-1, -1]]) if (!inB(x + dx, z + dz) || !inPasture[idx(x + dx, z + dz)] || w.road[idx(x + dx, z + dz)]) room = false;
        if (!room) continue;
        const s = Math.min(30, Math.hypot(x - yc.x, z - yc.z)) + Math.min(...water.map((q) => Math.hypot(q.x - x, q.z - z)), 30) + rng() * 4;
        if (s > ps) { ps = s; pick = i; }
      }
      if (pick < 0) break;
      const x = pick % N, z = (pick - x) / N;
      if (put('pumpWindmill', x, z, 1, 1, Math.floor(rng() * 4))) water.push({ x: x + 0.5, z: z + 0.5 });
    }
    // the windmills stand inside the fence (the herd's pen leaves out their tiles: game/herds.ts penOf)
    const grass = pasture;

    // ---- the lane: in under the arch from the nearest road, and on up the drive to the corral ----
    const gp = at(DRIVE_U, 0), dp = at(DRIVE_U, DRIVE_V);
    if (lane) {
      lane(idx(gp.x, gp.z));
      if (w.road[idx(gp.x, gp.z)]) lane(idx(dp.x, dp.z));
    }

    for (const i of grass) w.feature[i] = Feature.Pasture;
    for (let z = yr.z; z < yr.z + yr.d; z++) for (let x = yr.x; x < yr.x + yr.w; x++) w.feature[idx(x, z)] = Feature.Pasture;
    // and a margin round it all, so the next ranch keeps its distance
    for (const i of [...grass, ...Array.from({ length: yr.w * yr.d }, (_, k) => idx(yr.x + (k % yr.w), yr.z + Math.floor(k / yr.w)))]) {
      const x = i % N, z = (i - x) / N;
      for (let dz = -RANCH_CLEAR; dz <= RANCH_CLEAR; dz += 2) for (let dx = -RANCH_CLEAR; dx <= RANCH_CLEAR; dx += 2) if (inB(x + dx, z + dz)) taken[idx(x + dx, z + dz)] = 1;
    }
    let sx = 0, sz = 0;
    for (const i of grass) { sx += (i % N) + 0.5; sz += Math.floor(i / N) + 0.5; }
    const stockRoll = k === 0 ? horses : rng();
    const name = `${ranchBrand(gate.seed)} Ranch`;
    w.ranches.push({
      name, stock: stockRoll < (spec ? HORSES[spec.kind] ?? HORSES_ELSE : HORSES_ELSE) ? 'horses' : 'cattle',
      pasture: grass, yard: yr, facing: yard.d, gate: idx(gp.x, gp.z), water, x: sx / grass.length, z: sz / grass.length,
    });
    // a named place: its label, its announcement as the car rides in, its stamp in the Passport
    w.landmarks.push({ kind: 'ranch', name, x: sx / grass.length, z: sz / grass.length, r: Math.sqrt(grass.length / Math.PI) });
  }
}

// ---- reading a county's ranches ----------------------------------------------------------------------------

/** Per tile, 1 + the index of the ranch whose pasture it is in (0 for none), and the same for the ranches' yards. */
const PASTURE = new WeakMap<World, { n: number; pasture: Uint8Array; yard: Uint8Array }>();
export function ranchTiles(w: World): { pasture: Uint8Array; yard: Uint8Array } | null {
  if (!w.ranches?.length) return null;
  let c = PASTURE.get(w);
  if (c && c.n === w.ranches.length) return c;
  const pasture = new Uint8Array(N * N), yard = new Uint8Array(N * N);
  w.ranches.forEach((r, k) => {
    for (const i of r.pasture) pasture[i] = k + 1;
    for (let z = r.yard.z; z < r.yard.z + r.yard.d; z++) for (let x = r.yard.x; x < r.yard.x + r.yard.w; x++) yard[idx(x, z)] = k + 1;
  });
  c = { n: w.ranches.length, pasture, yard };
  PASTURE.set(w, c);
  return c;
}

/**
 * The ranches' fences and cattle grids: per tile, bit d where a fence stands along its edge d, and every edge a
 * road crosses the fence line on (tile * 4 + d), where a cattle grid lies instead. The pasture is fenced round,
 * except against a field (whose own fence serves) and where a track goes through; the yard is fenced where it
 * meets neither the pasture nor a road, and open under the arch. Cached per revision: a road laid changes it.
 */
const FENCES = new WeakMap<World, { rev: number; fence: Uint8Array; grids: number[] }>();
export function ranchFences(w: World): { fence: Uint8Array; grids: number[] } | null {
  const t = ranchTiles(w);
  if (!t) return null;
  let c = FENCES.get(w);
  if (c && c.rev === w.revision) return c;
  const fence = new Uint8Array(N * N), grids: number[] = [];
  for (let i = 0; i < N * N; i++) {
    const p = t.pasture[i], y = t.yard[i];
    if (!p && !y) continue;
    const x = i % N, z = (i - x) / N;
    for (let d = 0; d < 4; d++) {
      const nx = x + DIRS[d][0], nz = z + DIRS[d][1];
      if (!inB(nx, nz)) continue;
      const j = idx(nx, nz);
      if (p ? t.pasture[j] === p : t.yard[j] === y || t.pasture[j] === y) continue;
      if (w.flags[j] & Flag.Field) continue;
      if (w.flags[i] & Flag.Track && w.flags[j] & Flag.Track) continue;
      if (w.roadEdges[i] & (1 << d) || (w.road[i] && w.road[j])) {
        // a road over the pasture's fence line rides a cattle grid; the yard's drive goes in under the arch
        if (p && !t.yard[j]) grids.push(i * 4 + d);
        continue;
      }
      if (y && w.ranches[y - 1].gate === i && w.ranches[y - 1].facing === d) continue;
      fence[i] |= 1 << d;
    }
  }
  c = { rev: w.revision, fence, grids };
  FENCES.set(w, c);
  return c;
}
