import { mulberry32 } from './rng';

/**
 * Outdoor malls (0.7.0, NEXT_WORLD), after Old Orchard in Skokie: a village of shops round open-air walks, with
 * fountains, planted beds and trees, a cinema and two big department-store anchors along the back, and car parks
 * on three sides. One lot (world/playKinds.ts `outdoorMall`), laid out here from its seed, so the model
 * (render/buildings/mall.ts) and its hitbox (world/footprint.ts) agree: only the buildings are solid, the walks and
 * the car parks are open. A rare find on the edge of a suburb or a city (world/towns.ts playSites).
 *
 * Local frame as every model's: the origin in the lot's middle, +z the way it faces (the road), W across, D deep.
 */

/** One building of the mall: a box centred at (x, z), and which way its shopfront looks (+x, -x or +z). */
export interface MallUnit { x: number; z: number; w: number; d: number; h: number; kind: 'shop' | 'eatery' | 'cinema' | 'anchor'; face: 'px' | 'nx' | 'pz' }
/** A parking bay's centre, and whether its car lies along x. */
interface MallBay { x: number; z: number; alongX: boolean }
interface MallPlan {
  units: MallUnit[];
  /** The walks between the shops (paved), as boxes. */
  walks: { x: number; z: number; w: number; d: number }[];
  bays: MallBay[];
  fountains: { x: number; z: number; r: number }[];
  trees: [number, number][];
  /** Lamp posts over the car parks. */
  lamps: [number, number][];
  /** The village's extent: x0..x1 across, z0..z1 deep. */
  core: { x0: number; x1: number; z0: number; z1: number };
}

/** The front car park's depth and the side ones' width (tiles). */
const FRONT = 2.5, SIDE = 1.6;
/** A bay's width, and the share of bays with a car in them. */
const BAY = 0.29, FULL = 0.62;

export function mallPlan(seed: number, W: number, D: number): MallPlan {
  const r = mulberry32(seed ^ 0x6d616c6c);
  const core = { x0: -W / 2 + SIDE + 0.1, x1: W / 2 - SIDE - 0.1, z0: -D / 2 + 0.15, z1: D / 2 - FRONT - 0.1 };
  const units: MallUnit[] = [];
  const cw = core.x1 - core.x0;
  // along the back: the cinema and the two anchors, the cinema in the middle or at one end
  const back = 1.5, bz = core.z0 + back / 2;
  const cin = Math.min(2.6, cw * 0.38), anchor = (cw - cin - 0.3) / 2;
  const order = r() < 0.6 ? ['anchor', 'cinema', 'anchor'] : r() < 0.5 ? ['cinema', 'anchor', 'anchor'] : ['anchor', 'anchor', 'cinema'];
  let x = core.x0;
  for (const k of order) {
    const w = k === 'cinema' ? cin : anchor;
    units.push({ x: x + w / 2, z: bz, w, d: back, h: k === 'cinema' ? 1.05 : 0.78, kind: k as MallUnit['kind'], face: 'pz' });
    x += w + 0.15;
  }
  // down each side, a row of shops or of places to eat, their fronts turned in to the walk
  const sz0 = core.z0 + back + 0.35, sz1 = core.z1, depth = 1.15;
  const eatLeft = r() < 0.5;
  for (const side of [-1, 1]) {
    const n = 2 + Math.floor(r() * 2), len = (sz1 - sz0 - 0.15 * (n - 1)) / n;
    const eats = (side < 0) === eatLeft;
    for (let k = 0; k < n; k++) {
      const z = sz0 + k * (len + 0.15) + len / 2;
      const kind = (r() < 0.75) === eats ? 'eatery' : 'shop';
      units.push({ x: side < 0 ? core.x0 + depth / 2 : core.x1 - depth / 2, z, w: depth, d: len, h: 0.5 + r() * 0.18, kind, face: side < 0 ? 'px' : 'nx' });
    }
  }
  // always somewhere to eat and somewhere to shop down the sides
  const sides = units.filter((u) => u.face !== 'pz');
  if (!sides.some((u) => u.kind === 'eatery')) sides[0].kind = 'eatery';
  if (!sides.some((u) => u.kind === 'shop')) sides[sides.length - 1].kind = 'shop';
  // a pavilion of small shops in the middle now and then, the walks running round it
  const mid = core.x1 - core.x0 - depth * 2;
  const walks = [{ x: 0, z: (sz0 - 0.3 + sz1) / 2, w: mid, d: sz1 - sz0 + 0.3 }];
  walks.push({ x: (core.x0 + core.x1) / 2, z: core.z0 + back + 0.17, w: cw, d: 0.34 });
  const fountains: MallPlan['fountains'] = [], trees: [number, number][] = [];
  const cz = (sz0 + sz1) / 2;
  if (mid > 2.4 && r() < 0.5) {
    units.push({ x: 0, z: cz, w: Math.min(1.3, mid - 1.4), d: Math.min(1.1, (sz1 - sz0) * 0.4), h: 0.42, kind: r() < 0.5 ? 'eatery' : 'shop', face: 'pz' });
    fountains.push({ x: 0, z: sz0 + 0.45, r: 0.28 });
  } else fountains.push({ x: 0, z: cz, r: 0.38 });
  for (const sx of [-1, 1]) for (const z of [sz0 + 0.35, sz1 - 0.25]) trees.push([sx * (mid / 2 - 0.3), z]);
  // the car parks: two rows of bays either side of an aisle across the front, a row each down the sides
  const bays: MallBay[] = [];
  for (const z of [D / 2 - 0.35, D / 2 - FRONT + 0.55]) {
    for (let bx = -W / 2 + 0.35; bx <= W / 2 - 0.35; bx += BAY) {
      // the way in from the road is kept clear down the middle
      if (Math.abs(bx) < 0.45) continue;
      bays.push({ x: bx, z, alongX: false });
    }
  }
  for (const side of [-1, 1]) {
    for (let bz2 = -D / 2 + 0.35; bz2 <= D / 2 - FRONT - 0.2; bz2 += BAY) bays.push({ x: side * (W / 2 - 0.3), z: bz2, alongX: true });
  }
  const parked = bays.filter(() => r() < FULL);
  const lamps: [number, number][] = [];
  for (let lx = -W / 2 + 1.2; lx <= W / 2 - 1.2; lx += 2.2) lamps.push([lx, D / 2 - FRONT / 2 + 0.1]);
  for (const side of [-1, 1]) lamps.push([side * (W / 2 - SIDE + 0.15), -D / 2 + 1.2], [side * (W / 2 - SIDE + 0.15), D / 2 - FRONT - 1]);
  return { units, walks, bays: parked, fountains, trees, lamps, core };
}

/** The buildings only: the walks, the fountains' plazas and the car parks can be driven over. */
export function mallSolid(p: MallPlan): (x: number, z: number) => boolean {
  return (x, z) => p.units.some((u) => Math.abs(x - u.x) <= u.w / 2 && Math.abs(z - u.z) <= u.d / 2);
}
