/**
 * The layouts of the two big story structures (docs/storychains.html): the spaceport's launch complex and
 * the naval dry dock. One plan each, read by the drawing (render/buildings/works.ts) and by the footprint
 * (world/footprint.ts), so the walls a car meets are where the model stands.
 *
 * Both are in the model's local frame: origin at the middle of the lot, +z the way it faces (the gate road
 * for the pad, the sea for the dock), W across and D deep.
 */

export interface Box { x: number; z: number; w: number; d: number; h: number }
interface Disc { x: number; z: number; r: number }

/** The launch complex on its 14-tile lot: the pad and its rocket at the back, the halls by the gate. */
interface PadPlan {
  /** How much smaller than the 14-tile wonder this lot is (1 for the wonder). */
  s: number;
  /** The rocket's axis, on the mound. */
  cz: number;
  /** The mound's radius, and the hardstand's round it. */
  mound: number;
  stand: number;
  /** The launch umbilical tower beside the rocket: its centre, half its width, its height. */
  tower: { x: number; z: number; half: number; h: number };
  /** The vehicle assembly building and the launch control centre. */
  vab: Box;
  lcc: Box;
  /** The two propellant spheres, and the sound-suppression water tower. */
  lox: Disc;
  lh2: Disc;
  water: Disc & { h: number };
}

export function padPlan(W: number, D: number): PadPlan {
  const s = Math.max(0.4, Math.min(W, D) / 14);
  const cz = -D / 2 + 4.6 * s;
  return {
    s, cz,
    mound: 2.3 * s,
    stand: 3.4 * s,
    tower: { x: -1.5 * s, z: cz, half: 0.34 * s, h: 8.8 * s },
    vab: { x: -W / 2 + 2.5 * s, z: D / 2 - 2.0 * s, w: 4.0 * s, d: 3.0 * s, h: 4.8 * s },
    lcc: { x: W / 2 - 2.0 * s, z: D / 2 - 1.5 * s, w: 3.0 * s, d: 1.5 * s, h: 1.2 * s },
    lox: { x: -W / 2 + 1.5 * s, z: cz - 0.6 * s, r: 0.8 * s },
    lh2: { x: W / 2 - 1.5 * s, z: cz - 0.6 * s, r: 0.8 * s },
    water: { x: W / 2 - 1.4 * s, z: -D / 2 + 1.3 * s, r: 0.65 * s, h: 2.7 * s },
  };
}

/** The naval dry dock on its 6 × 9 lot: the walled basin open to the sea at the front, the shops at the back. */
interface DockPlan {
  /** The basin: its inside width, its back wall and its front (the gate, at the lot's seaward edge). */
  bw: number;
  back: number;
  front: number;
  /** The walls' height above the floor, and how thick they are. */
  wall: number;
  thick: number;
  /** The fabrication hall, on the left of the back of the lot (the right is the yard gate). */
  hall: Box;
  /** The pump house, on the right-hand apron. */
  pump: Box;
}

export function dockPlan(W: number, D: number): DockPlan {
  const bw = Math.max(1.2, Math.min(2.8, W - 2.8));
  const back = -D / 2 + 1.9;
  return {
    bw, back, front: D / 2, wall: 0.72, thick: 0.28,
    hall: { x: -W / 2 + 1.75, z: -D / 2 + 0.8, w: 3.1, d: 1.4, h: 1.7 },
    pump: { x: W / 2 - 0.55, z: back + 1.2, w: 0.7, d: 0.9, h: 0.7 },
  };
}
