import type { FactionKind } from './factionKinds';
import type { WildKind } from './wildKinds';
import type { AncientKind } from './ancientKinds';
import type { PlayKind } from './playKinds';
import type { RanchKind } from './ranchKinds';
import type { OnsenKind } from './onsenKinds';
import type { LakeKind } from './lakeKinds';
/** World constants and the tile data model (Rollercoaster Tycoon style). */

export const N = 256;          // tiles per side
export const STEP = 0.5;       // world units per height step
export const SEA = 2;          // sea level in steps
export const CHUNK = 16;       // tiles per chunk side
export const CHUNKS = N / CHUNK;

export enum Biome {
  Ocean = 0, Beach = 1, SeaCliff = 2, Plains = 3, Hills = 4, Forest = 5,
  Farm = 6, Desert = 7, Canyon = 8, Mountain = 9, Snow = 10, Town = 11,
  Lava = 12, Salt = 13, Ice = 14, Marsh = 15, Mangrove = 16, Lagoon = 17,
}

/**
 * What the ground under the wheels is made of, where that is not simply what grows there: dune
 * sand, a salt pan, glacier ice, cooled lava, marsh, banded badland rock, a cave floor. The car
 * reads grip and top speed from it.
 */
export enum Surface { None = 0, Rock = 1, Sand = 2, Salt = 3, Ice = 4, Lava = 5, Marsh = 6, Cave = 7, Basalt = 8 }

/** The twenty-nine landforms the generator can make. */
export type LandformKind =
  | 'volcano' | 'caldera' | 'atoll' | 'fjordCoast' | 'riftValley' | 'dunes' | 'saltFlat' | 'glacier'
  | 'karstTowers' | 'badlands' | 'mesaCountry' | 'delta' | 'skerries' | 'mangroves' | 'erratics' | 'mountainPass' | 'lavaField'
  | 'gorge' | 'cascade' | 'oxbows' | 'tarn' | 'hoodoos' | 'tombolo'
  | 'hotSprings' | 'seaArch' | 'sinkhole' | 'basaltColumns' | 'caveTunnel' | 'naturalBridge'
  /** A rare stand of giant trees (world/groves.ts). */
  | 'grove'
  /** A great waterfall of one of seven shapes (world/waterfalls.ts). */
  | 'waterfall'
  /** Not ground at all: a ranch's pasture, named on the map like a landform (world/ranches.ts, GEN 53). */
  | 'ranch';

/**
 * A named landform: where it is (local tiles), how far it reaches, and whatever its props need to
 * be drawn — the crater's level, a tunnel's two portals and its roof, a column field's steps.
 */
export interface Landmark {
  kind: LandformKind;
  name: string;
  x: number; z: number; r: number;
  /** Free-form numbers for the props: meaning depends on the kind. */
  data?: number[];
}

/** Ground finish on town tiles. */
export enum Lot {
  None = 0, Lawn = 1, Paved = 2, Park = 3, Pitch = 4, Yard = 5, Asphalt = 6, Plaza = 7, Deck = 8,
  Runway = 9, Apron = 10, Piste = 11, Gravel = 12, Sand = 13,
  /** A park gone to seed: dead grass. */
  Waste = 14,
  /** A flooded rice terrace: water drawn on the lot, a sky mirror. */
  Paddy = 15,
}

/** What occupies a tile besides a town or a harbour. */
export enum Feature {
  None = 0, Beach = 1, Quarry = 2, Piste = 3, Airfield = 4,
  /** A ranch's pasture and its yard (world/ranches.ts, GEN 53): nothing else is put down on them. */
  Pasture = 5,
  /** A ski resort's woods, kept between its runs below the tree line (world/skiFields.ts planResort, 0.7.0). */
  Glade = 6,
}

export type TownKind = 'rural' | 'suburb' | 'city' | 'metro' | 'mega';

/**
 * What a cell holds. Decided by a hash of its coordinates, so density never drifts. A `continent`
 * cell is land that carries on into every continental neighbour rather than an island of its own.
 */
export type CellKind = 'full' | 'small' | 'islet' | 'atoll' | 'sea' | 'continent';
/** Parks and plazas, from the most open to the most enclosed. */
export type OpenKind =
  | 'meadow' | 'civicSquare' | 'fountainSquare' | 'greenway' | 'picnicGround' | 'dogRun' | 'plazaSteps'
  | 'sculpturePark' | 'bandstandGreen' | 'memorial' | 'skatePark' | 'promenade' | 'cemetery' | 'amphitheatre'
  | 'marketSquare' | 'lakePark' | 'courts' | 'formalGarden' | 'allotments' | 'botanicalGarden' | 'playground' | 'grove'
  // a Central Park: a whole block of a big city ringed by its streets (world/greatParks.ts)
  | 'greatPark';
export type CivicKind =
  | 'courthouse' | 'postOffice' | 'villageHall' | 'communityCentre' | 'kindergarten' | 'university' | 'busStation'
  | 'prison' | 'cathedral' | 'chapel' | 'mosque' | 'temple' | 'substation' | 'powerPlant' | 'recyclingCentre'
  | 'ministry' | 'waterworks' | 'observatory';
export type BusinessKind =
  | 'hotel' | 'motel' | 'bank' | 'carDealership' | 'bigBox' | 'stripMall' | 'cafe' | 'bakery' | 'officePark'
  | 'techCampus' | 'factory' | 'brewery' | 'logisticsDepot' | 'pub' | 'fastFood' | 'garage' | 'marketHall'
  | 'departmentStore' | 'exchange' | 'dataCentre';
export type VenueKind =
  | 'cinema' | 'theatre' | 'arena' | 'concertHall' | 'bowlingAlley' | 'casino' | 'zoo' | 'aquarium' | 'lido'
  | 'waterPark' | 'miniGolf' | 'fairground' | 'racetrack' | 'iceRink' | 'nightclub' | 'sportsHall'
  // the grand opera house on a big city's square (render/buildings/showbiz.ts)
  | 'operaHouse';
export type HomeKind =
  | 'bungalow' | 'cottage' | 'duplex' | 'terraceRow' | 'mansion' | 'retirementHome' | 'trailerPark'
  | 'courtyardBlock' | 'towerBlock' | 'condoTower';
export type LandmarkKind =
  | 'commsTower' | 'observationTower' | 'clockTower' | 'parkingGarage' | 'triumphalArch' | 'windTurbine' | 'fuelDepot';
export type CountryKind = 'windmill' | 'sawmill' | 'greenhouse' | 'orchard' | 'vineyard' | 'farmShop' | 'stables';

/**
 * The twenty biomes: whole islands, and swaths of a continent, that are one thing through and through.
 * In code a biome is a Region, because Biome is the per-tile ground class.
 */
export type RegionKind =
  | 'sands' | 'icefield' | 'shallows' | 'green' | 'heights' | 'moors' | 'veldt' | 'fens' | 'terraces' | 'whitewash' | 'goldhills'
  // and nine more: a volcanic coast, fjord country, giant forest, red-rock badlands, a bay of limestone towers,
  // open steppe, a salt pan, a mangrove delta and a lavender plateau
  | 'firecoast' | 'fjords' | 'bigtimber' | 'redrock' | 'dragonbay' | 'steppe' | 'saltpan' | 'mangrove' | 'lavender';
/** In a fixed order: a tile's `regionK` is 1 + the index here, 0 for none. */
export const REGION_KINDS: readonly RegionKind[] = [
  'sands', 'icefield', 'shallows', 'green', 'heights', 'moors', 'veldt', 'fens', 'terraces', 'whitewash', 'goldhills',
  'firecoast', 'fjords', 'bigtimber', 'redrock', 'dragonbay', 'steppe', 'saltpan', 'mangrove', 'lavender',
];

