import { N, DIRS, World, idx, inB, type Building, type BuildingKind } from './tiles';
import { REGION_SHAPES_A } from './regionShapesA';
import { REGION_SHAPES_B } from './regionShapesB';
import { REGION_SHAPES_C } from './regionShapesC';
import { EXPANSION_SHAPES } from './expansionShapes';
import { ANCIENT_SHAPES, type AncientKind } from './ancientKinds';
import { circuitPlan, circuitSolid, designOf } from './circuits';
import { stadiumDesignOf, stadiumPlan } from './stadiums';
import { parkPlan, parkSolid } from './greatParks';
import { dockPlan, padPlan } from './spacePlans';
import { mallPlan, mallSolid } from './malls';
import { resortPlan, resortSolid } from './beachResorts';

/**
 * Which tiles of a building's lot actually block vehicles.
 *
 * A lot is a rectangle, but most models only fill part of it: a stadium is a ring of stands round an
 * open pitch, a gas station is a canopy on four thin posts with the shop at the back, a school sits
 * at the back of its yard. Only the tall, solid parts of the model should have a hitbox, so the flat
 * ground inside and around them can be driven on.
 *
 * Each shape below is written in the same local frame as the model in `render/townMesh.ts`: the
 * origin is the middle of the lot, +z points the way the building faces, x runs across its front,
 * and the lot is W wide by D deep. Kinds with no shape here fill their lot, as before.
 */

/** A box in the local frame: centre (x, z), w across and d deep. */
interface Part { x: number; z: number; w: number; d: number }

/** Is this local point inside the solid part of the model? */
type Solid = (lx: number, lz: number) => boolean;

const boxes = (...list: Part[]): Solid =>
  (lx, lz) => list.some((p) => Math.abs(lx - p.x) <= p.w / 2 && Math.abs(lz - p.z) <= p.d / 2);

const SHAPES: Partial<Record<BuildingKind, (W: number, D: number, b: Building) => Solid>> = {
  // a circuit: its stands, pit building, walls and fence; the track, the infield and the paddock are open
  raceCircuit: (W, D) => { const p = circuitPlan(designOf(W, D)); return (x, z) => circuitSolid(p, x, z); },
  // the stands only, of whichever of the four it is (world/stadiums.ts): the pitch inside them is open
  stadium: (W, D, b) => stadiumPlan(stadiumDesignOf(b), W, D).solid,
  // a great park's lake and its buildings (world/greatParks.ts): the lawns, paths and the drive through it are open
  greatPark: (W, D, b) => parkSolid(parkPlan(b.seed, W, D)),
  // the tower and the terrace round its foot; the lot's corners are lawn you can drive over
  coitTower: (W, D) => {
    const T = Math.min(W, D) / 2 - 0.3;
    return (x, z) => Math.hypot(x, z) <= T;
  },
  // the Eiffel Tower stands on its four feet: the Champ de Mars between them is open
  eiffelTower: (W, D) => {
    const b = Math.min(W, D) / 2 - 0.2 - 0.09;
    return (x, z) => Math.abs(Math.abs(x) - b) <= 0.24 && Math.abs(Math.abs(z) - b) <= 0.24;
  },
  // the monument's shaft and the paving round it; the lawn beyond the flags is open
  washingtonMonument: () => (x, z) => Math.abs(x) <= 0.3 && Math.abs(z) <= 0.3,
  // the house and its wings; the North Lawn and its fountain in front are open
  whiteHouse: (W, D) => {
    const w = Math.min(W - 1.4, 2.2), d = Math.min(D - 1.0, 1.1);
    return boxes({ x: 0, z: -0.1, w: w + 1.8, d: d + 0.3 }, { x: 0, z: -0.1 - d / 2, w: 0.8, d: 0.7 });
  },
  // the rotunda on its podium and the basin (water) in front; the lawns under the cherries are open
  jeffersonMemorial: (W, D) => {
    const R = Math.min(W, D) * 0.2 + 0.3, cz = -D * 0.12;
    return (x, z) => Math.hypot(x, z - cz) <= R + 0.1 || (Math.abs(z - (D / 2 - 0.55)) <= 0.45 && Math.abs(x) <= W / 2 - 0.25);
  },
  // the Louvre's wings and the pyramid; the rest of the court is open
  louvrePyramid: (W, D) => {
    const w = W - 0.3, d = D - 0.3, dep = 0.7, pr = Math.min(w, d) * 0.18;
    return boxes({ x: 0, z: -d / 2 + dep / 2, w: w + 0.1, d: dep + 0.1 }, { x: -(w / 2 - dep / 2), z: 0, w: dep + 0.1, d }, { x: w / 2 - dep / 2, z: 0, w: dep + 0.1, d },
      { x: 0, z: d * 0.12, w: pr * 2.1, d: pr * 2.1 });
  },
  // the Bean in the middle of its plaza (render/buildings/chicago.ts cloudGate); the plaza round it is open
  cloudGate: (W) => {
    const rx = Math.min(0.62, W * 0.22) + 0.06, rz = rx * 0.6;
    return (x, z) => (x / rx) ** 2 + (z / rz) ** 2 <= 1;
  },
  // the Adriatic's (render/buildings/adriatic.ts): the walls, gate and round tower stand on the back half of the
  // gate's lot, the dry moat and the bridge in front are open; the church and its campanile, the terrace open
  pileGate: (W, D) => boxes({ x: 0, z: -D / 4, w: W, d: D / 2 + 0.1 }),
  // an onsen town's (render/buildings/onsen*.ts): the ropeway's two stations, its tower and the egg stall, the sulphur
  // valley between open; the resort ryokan's slab and bath wing, its drive and porte-cochère open
  ropeway: (W, D) => {
    const lx = -W / 2 + 0.75, ux = W / 2 - 0.6, tx = (lx + ux) / 2 + 0.1;
    return boxes({ x: lx, z: 0, w: 1.2, d: D - 0.7 }, { x: ux, z: 0, w: 1.15, d: D - 0.4 }, { x: tx, z: 0, w: 0.45, d: 0.45 }, { x: lx + 0.9, z: D / 2 - 0.35, w: 0.42, d: 0.3 });
  },
  resortRyokan: (W, D) => {
    const sw = Math.min(W - 1.0, 3.0), sx = -(W - sw) / 2 + 0.2, sz = -0.25, sd = 1.15, bx = sx + sw / 2 + 0.55;
    return boxes({ x: sx, z: sz + 0.06, w: sw + 0.06, d: sd + 0.14 }, { x: bx, z: sz + 0.1, w: 0.85, d: 1.5 });
  },
  stEuphemia: (W, D, b) => {
    const nw = Math.min(W - 0.3, 1.2), nd = Math.min(D - 0.9, 1.7), cz = D / 2 - 0.35 - nd / 2, sw = 0.36;
    const tx = ((b.seed & 1) ? 1 : -1) * Math.min(nw / 2 - 0.05, W / 2 - sw / 2 - 0.08), tz = Math.max(-D / 2 + sw / 2 + 0.08, cz - nd / 2 - 0.05);
    return boxes({ x: 0, z: cz + 0.03, w: nw + 0.06, d: nd + 0.1 }, { x: tx, z: tz, w: sw + 0.1, d: sw + 0.1 });
  },
  // the cocoon's elliptical foot and its entrance; the plaza round it is open
  cocoonTower: (W, D) => {
    const rx = (Math.min(W, D) - 0.3) * 0.34 + 0.05, rz = rx * 0.72;
    return (x, z) => (x / rx) ** 2 + (z / rz) ** 2 <= 1 || (Math.abs(x) <= rx * 0.6 && z >= 0 && z <= rz + 0.2);
  },
  // the colonnade along the front of the government building's plaza is open between its columns
  metroGovTower: (W, D) => boxes({ x: -W / 2 + 0.85, z: -0.2, w: 1.5, d: D - 0.9 }, { x: 0.45, z: -0.15, w: Math.min(W - 1.6, 2.2) + 0.1, d: Math.min(D - 0.9, 1.3) + 0.1 }),
  // the rotunda, its colonnade and the lagoon (which is water, and blocks); the lawn round them is open
  palaceFineArts: (W, D) => {
    const w = W - 0.4, d = D - 0.4, lz = d / 2 - d * 0.28, rz = -d / 2 + d * 0.3, R = Math.min(w, d) * 0.2;
    const lagoon = { x: 0, z: lz, w: w * 0.86 + 0.1, d: d * 0.42 + 0.1 };
    const inBox = (p: Part) => (x: number, z: number) => Math.abs(x - p.x) <= p.w / 2 && Math.abs(z - p.z) <= p.d / 2;
    const water = inBox(lagoon);
    return (x, z) => water(x, z) || Math.hypot(x, z - rz) <= R + 0.3
      || (Math.abs(z - rz) < d * 0.34 && Math.abs(x) > w / 2 - 0.5 && Math.abs(x) < w / 2 + 0.1);
  },
  // the hall on its plinth and the stupa beside it; the forecourt in front of the steps is open
  wat: (W, D) => {
    const w = Math.min(W - 0.5, 1.6), d = Math.min(D - 0.6, 2.0), pz = -D / 2 + d / 2 + 0.3;
    return boxes(
      { x: 0, z: pz, w: w + 0.4, d: d + 0.4 },
      { x: w / 2 + 0.34, z: pz - d / 4, w: 0.44, d: 0.44 },
    );
  },
  // only the piers block: the whole point of an aqueduct is the road running under its arches
  aqueduct: (W, D) => {
    const alongX = W >= D;
    const len = (alongX ? W : D) - 0.2, bays = Math.max(3, Math.round(len / 0.7)), bay = len / bays;
    const parts: Part[] = [];
    for (let i = 0; i <= bays; i++) {
      const o = -len / 2 + bay * i;
      parts.push({ x: alongX ? o : 0, z: alongX ? 0 : o, w: alongX ? 0.22 : 0.46, d: alongX ? 0.46 : 0.22 });
    }
    return boxes(...parts);
  },
  // the four posts of a ceremonial gateway; the street goes through it
  paifang: (W) => {
    const w = Math.min(W - 0.2, 2.6);
    return boxes(...[-1.5, -0.5, 0.5, 1.5].map((sx) => ({ x: (sx * w) / 3.4, z: 0, w: 0.2, d: 0.26 })));
  },
  // the two halves of a split gate, with the path clear between them
  splitGate: (W) => {
    const gap = 0.38, tw = Math.min(0.42, (W - 0.4 - gap) / 2);
    return boxes(...[-1, 1].map((sx) => ({ x: sx * (gap / 2 + tw / 2), z: 0, w: tw + 0.06, d: tw })));
  },
  // the whole oval (render/buildings/rome.ts): the arena inside is the hypogeum's walls and the timber floor, closed
  // in by the ring, and no car gets in to it; the lot's corners outside the wall are open
  colosseum: (W, D) => {
    const ax = W / 2 - 0.25, az = D / 2 - 0.25;
    return (x, z) => (x / ax) ** 2 + (z / az) ** 2 <= 1.02;
  },
  // Rome's: St Peter's square is open between Bernini's arms, which stand in the outer columns of tiles; the
  // Vittoriano's low front terraces either side of its stair are open; the foot of the Spanish Steps is open
  stPeters: (W, D) => {
    const fz = -D / 2 + Math.min(2.4, D * 0.44);
    return (x, z) => z <= fz + 0.15 || Math.abs(x) >= W / 2 - 1;
  },
  vittoriano: (W, D) => (x, z) => z <= -D / 2 + 1.3 || Math.abs(x) <= W * 0.2,
  spanishSteps: (_W, D) => (_x, z) => z <= D / 2 - 1,
  // the basilica across the head and the colonnade down each side: the paving between them is a square
  forum: (W, D) => {
    const w = W - 0.2, d = D - 0.2;
    return boxes(
      { x: 0, z: -d / 2 + Math.min(d * 0.34, 1.1), w: Math.min(w - 0.4, 2.4), d: Math.min(d * 0.3, 0.9) + 0.4 },
      { x: -(w / 2 - 0.16), z: 0, w: 0.4, d: d - 0.3 },
      { x: w / 2 - 0.16, z: 0, w: 0.4, d: d - 0.3 },
    );
  },
  // the two platforms either side: the sunken alley between them is open, and worth driving down
  ballCourt: (W, D) => {
    const alongX = W >= D;
    const len = (alongX ? W : D) - 0.3, span = (alongX ? D : W) - 0.3;
    const alley = Math.min(0.95, span * 0.46), pw = (span - alley) / 2, off = (alley + pw) / 2;
    return boxes(
      { x: alongX ? 0 : off, z: alongX ? off : 0, w: alongX ? len : pw, d: alongX ? pw : len },
      { x: alongX ? 0 : -off, z: alongX ? -off : 0, w: alongX ? len : pw, d: alongX ? pw : len },
    );
  },
  // the shop at the back; the forecourt under the canopy is open (its posts are matchsticks)
  gas: () => boxes({ x: 0, z: -0.62, w: 1.2, d: 0.6 }),
  school: () => boxes({ x: 0, z: -0.55, w: 3.5, d: 1.3 }, { x: 0, z: 0.2, w: 0.7, d: 0.2 }),
  hospital: () => boxes({ x: 0, z: -0.2, w: 3.6, d: 2.4 }),
  grocery: () => boxes({ x: 0, z: -0.27, w: 2.7, d: 1.3 }),
  // the hall, and the glass entrance standing proud of its front
  mall: () => boxes({ x: 0, z: -0.25, w: 4.6, d: 2.3 }, { x: 0, z: 0.9, w: 1.1, d: 0.3 }),
  police: () => boxes({ x: 0, z: -0.2, w: 1.6, d: 1.2 }),
  clinic: () => boxes({ x: 0, z: -0.2, w: 1.5, d: 1.2 }),
  fire: () => boxes({ x: -0.1, z: -0.15, w: 1.5, d: 1.3 }, { x: 0.75, z: -0.55, w: 0.36, d: 0.36 }),
  // the hall itself; the portico steps across the front are flat enough to drive over
  library: (W, D) => boxes({ x: 0, z: -D / 2 + 0.1 + (D - 0.75) / 2, w: W - 0.3, d: D - 0.75 }),
  museum: (W, D) => boxes({ x: 0, z: -D / 2 + 0.1 + (D - 0.75) / 2, w: W - 0.2, d: D - 0.75 }),
  cityHall: () => boxes({ x: 0, z: -0.4, w: 2.5, d: 1.9 }),
  church: () => boxes({ x: 0, z: -0.18, w: 0.66, d: 1.32 }, { x: 0, z: 0.6, w: 0.32, d: 0.32 }),
  barn: () => boxes({ x: 0, z: 0, w: 1.4, d: 1.3 }),
  warehouse: (W, D) => boxes({ x: 0, z: 0, w: W - 0.3, d: D - 0.3 }),
  boathouse: (W, D) => boxes({ x: 0, z: -0.1, w: W - 0.3, d: D - 0.5 }),
  // the works': the hopper and the screening tower stand on a pad low enough to drive onto
  crusher: () => boxes({ x: -0.5, z: 0, w: 1.1, d: 1.1 }, { x: 0.75, z: -0.25, w: 0.8, d: 0.8 }),
  // the canopy is overhead on four thin posts; only the wall across the back, round the bull wheel, stands in the way
  liftStation: (W, D) => boxes({ x: 0, z: -(D - 0.8) / 2, w: W - 0.9, d: 0.45 }),
  // the shaft; the cab spreads out well above a car's roof
  controlTower: () => boxes({ x: 0, z: 0, w: 0.7, d: 0.7 }),

  // ---- the newer kinds: only the parts that stand up block ----
  cemetery: (_W, D) => boxes({ x: 0, z: -D / 2 + 0.5, w: 0.6, d: 0.76 }),
  lakePark: (W, D) => (x, z) =>
    ((x + 0.12 * W) / (0.26 * W)) ** 2 + ((z + 0.05 * D) / (0.24 * D)) ** 2 <= 1 ||
    ((x - 0.14 * W) / (0.2 * W)) ** 2 + ((z - 0.08 * D) / (0.2 * D)) ** 2 <= 1,
  botanicalGarden: (_W, D) => boxes({ x: 0, z: -D / 2 + 1.2, w: 2, d: 1.9 }),
  courthouse: (W, D) => boxes({ x: 0, z: -D / 2 + 0.1 + (D - 0.9) / 2, w: W - 0.3, d: D - 0.9 }),
  postOffice: (W, D) => boxes({ x: 0, z: -0.12, w: W - 0.2, d: D - 0.45 }),
  villageHall: (W, D) => boxes({ x: 0, z: -0.14, w: W - 0.34, d: D - 0.5 }),
  communityCentre: (W, D) => boxes({ x: 0, z: -D / 2 + 0.1 + D * 0.275, w: W - 0.3, d: D * 0.55 }),
  kindergarten: (W, D) => boxes({ x: 0, z: -D / 2 + 0.4, w: W - 0.3, d: 0.6 }, { x: -W / 2 + 0.45, z: 0, w: 0.6, d: D - 0.6 }),
  university: (W, D) => boxes(
    { x: 0, z: -D / 2 + 0.6, w: W - 0.3, d: 0.9 },
    { x: -W / 2 + 0.6, z: 0.2, w: 0.9, d: D - 1.3 },
    { x: W / 2 - 0.6, z: 0.2, w: 0.9, d: D - 1.3 },
  ),
  busStation: (W, D) => boxes({ x: -W / 2 + 0.45, z: 0, w: 0.7, d: D - 0.4 }),
  cathedral: (W, D) => boxes({ x: 0, z: -0.35, w: W * 0.42 + 0.5, d: D - 1.0 }, { x: 0, z: -0.35 - (D - 1.0) * 0.18, w: W - 0.2, d: 0.6 }),
  mosque: (W, D) => boxes({ x: 0, z: -D / 2 + 0.2 + D * 0.25, w: W - 0.4, d: D * 0.5 }),
  // three bins under a canopy on posts, a weighbridge and bottle banks: all low enough to drive through
  recyclingCentre: () => () => false,
  powerPlant: (W, D) => (x, z) =>
    boxes({ x: -W / 2 + 1.3, z: -0.3, w: 2.2, d: 1.4 })(x, z) || Math.hypot(x - (W / 2 - 1.1), z - (-D / 2 + 1.2)) <= 0.9,
  waterworks: (W, D) => (x, z) =>
    Math.hypot(x + W / 4, z + D / 4) <= 0.62 || Math.hypot(x - (W / 4 - 0.1), z - 0.1) <= 0.62 ||
    boxes({ x: -W / 4 + 0.1, z: D / 2 - 0.5, w: 0.8, d: 0.5 })(x, z),
  motel: (W, D) => boxes({ x: -0.3, z: -D / 2 + 0.35, w: W - 1.2, d: 0.5 }, { x: W / 2 - 0.4, z: -D / 2 + 0.4, w: 0.5, d: 0.6 }),
  carDealership: (W, D) => boxes({ x: 0, z: -D / 2 + 0.45, w: W - 0.3, d: 0.7 }),
  bigBox: (W, D) => boxes({ x: 0, z: -D / 2 + 0.1 + (D - 1.4) / 2, w: W - 0.2, d: D - 1.4 }),
  stripMall: (W, D) => boxes({ x: 0, z: -D / 2 + 0.41, w: W - 0.2, d: 0.62 }),
  // an outdoor mall's buildings (world/malls.ts): its car parks and walks are open
  outdoorMall: (W, D, b) => mallSolid(mallPlan(b.seed, W, D)),
  // a beach resort's buildings (world/beachResorts.ts): the deck, the pools, the gardens and the beach are open
  beachResort: (W, D, b) => resortSolid(resortPlan(b.seed, W, D)),
  // a mine's machines stand on part of their lots only (render/buildings/mines.ts): the boom swings over open ground
  dragline: () => boxes({ x: 0, z: -0.2, w: 1.8, d: 2.0 }),
  derrick: () => boxes({ x: 0, z: 0, w: 0.4, d: 0.4 }),
  crawlerCrane: (W, D) => boxes({ x: 0, z: -0.15, w: 0.9, d: D - 0.6 }),
  officePark: (W, D) => boxes({ x: -W / 2 + 0.75, z: -D / 2 + 0.5, w: 1.3, d: 0.8 }, { x: W / 2 - 0.45, z: -0.1, w: 0.7, d: 1.4 }),
  techCampus: (W, D) => boxes(
    { x: -W / 4, z: -D / 4, w: W * 0.34, d: D * 0.3 }, { x: W / 4, z: -D / 4, w: W * 0.34, d: D * 0.3 },
    { x: -W / 4, z: D / 4, w: W * 0.34, d: D * 0.3 }, { x: W / 4, z: D / 4, w: W * 0.34, d: D * 0.3 },
  ),
  factory: (W, D) => boxes({ x: -0.3, z: -D / 2 + 0.1 + (D - 1.1) / 2, w: W - 0.8, d: D - 1.1 }),
  brewery: (W, D) => boxes({ x: 0, z: -0.3, w: W - 0.3, d: D - 0.9 }),
  logisticsDepot: (W, D) => boxes({ x: 0, z: -D / 2 + 0.1 + (D - 1.4) / 2, w: W - 0.3, d: D - 1.4 }),
  fastFood: () => boxes({ x: -0.1, z: -0.1, w: 0.56, d: 0.5 }),
  dataCentre: (W, D) => boxes({ x: -0.2, z: -D / 2 + 0.1 + (D - 0.8) / 2, w: W - 0.9, d: D - 0.8 }),
  arena: (W, D) => (x, z) => Math.hypot(x, z) <= Math.min(W, D) / 2 - 0.45,
  // the glass foyer and the three shells behind it; the podium they stand on is only a step
  concertHall: (W) => (x, z) =>
    boxes({ x: 0, z: 0.5, w: W - 0.9, d: 0.6 })(x, z) ||
    ([[-0.55, -0.35, 0.9], [0.2, -0.1, 0.75], [0.75, 0.25, 0.55]] as const).some(([sx, sz, rad]) =>
      z <= sz + 0.25 && ((x - sx) / rad) ** 2 + ((z - sz) / (rad * 0.8)) ** 2 <= 1),
  casino: (W, D) => boxes({ x: 0, z: -D / 2 + 0.1 + (D - 1.0) / 2, w: W - 0.3, d: D - 1.0 }),
  aquarium: (W, D) => boxes({ x: 0, z: -0.1, w: W - 0.3, d: D - 0.5 }),
  lido: (W) => boxes({ x: W / 2 - 0.3, z: 0.1, w: 0.44, d: 1.4 }),
  zoo: (_W, D) => boxes({ x: -0.35, z: D / 2 - 0.35, w: 0.3, d: 0.34 }, { x: 0.35, z: D / 2 - 0.35, w: 0.3, d: 0.34 }),
  iceRink: (W, D) => boxes({ x: 0, z: -0.12, w: W - 0.2, d: D - 0.5 }),
  sportsHall: (W, D) => boxes({ x: 0, z: -0.2, w: W - 0.2, d: D - 0.6 }),
  bungalow: () => boxes({ x: -0.12, z: -0.1, w: 0.62, d: 0.5 }),
  mansion: (_W, D) => boxes({ x: 0, z: -D / 2 + 0.55, w: 1.56, d: 0.6 }),
  retirementHome: (W, D) => boxes(
    { x: 0, z: -D / 2 + 0.375, w: W - 0.2, d: 0.55 },
    { x: -(W / 2 - 0.375), z: 0, w: 0.55, d: D - 0.4 }, { x: W / 2 - 0.375, z: 0, w: 0.55, d: D - 0.4 },
  ),
  courtyardBlock: (W, D) => (x, z) => boxes({ x: 0, z: 0, w: W - 0.2, d: D - 0.2 })(x, z) && !boxes({ x: 0, z: 0.1, w: W - 1.8, d: D - 1.8 })(x, z),
  towerBlock: (W, D) => boxes({ x: 0, z: -0.2, w: W - 0.7, d: D - 1.0 }),
  triumphalArch: (W) => boxes({ x: -(W - 0.3) / 2 + 0.15, z: 0, w: 0.3, d: 0.6 }, { x: (W - 0.3) / 2 - 0.15, z: 0, w: 0.3, d: 0.6 }),
  fuelDepot: () => (x, z) => Math.hypot(x + 0.45, z + 0.45) <= 0.36 || Math.hypot(x - 0.45, z + 0.45) <= 0.36 || Math.hypot(x, z - 0.25) <= 0.3,
  sawmill: (W, D) => boxes({ x: W / 2 - 0.3, z: -D / 2 + 0.3, w: 0.36, d: 0.3 }, { x: 0, z: -D / 2 + 0.55, w: 1.0, d: 0.16 }),
  stables: (W, D) => boxes({ x: 0, z: -D / 2 + 0.35, w: W - 0.3, d: 0.5 }),

  // ---- houses of worship ----
  // the hall and its front bay; the steps up to the doors are flat enough to drive over
  synagogue: (W, D) => boxes({ x: 0, z: 0, w: Math.min(W - 0.3, 2.6), d: D - 0.4 }),
  orthodoxChurch: (W, D) => boxes(
    { x: 0, z: 0, w: Math.min(W - 0.3, 2.2), d: D - 0.35 },
    { x: 0, z: 0, w: Math.min(W - 0.3, 2.2) + 0.5, d: (D - 0.35) * 0.36 }, { x: 0, z: (D - 0.35) / 2 - 0.1, w: 0.6, d: 0.3 },
  ),
  staveChurch: (W, D) => {
    const gw = Math.min(W - 0.5, D - 0.5, 1.5) + 0.7;
    return boxes({ x: 0, z: 0, w: gw, d: gw }, { x: 0, z: gw / 2 + 0.15, w: 0.32, d: 0.2 });
  },
  // the plinth is a step up, so only the dome itself stops a car
  stupa: (W, D) => { const R2 = Math.min(W, D) / 2 - 0.25; return (x, z) => Math.hypot(x, z) <= R2 + 0.1; },

  // ---- the working country and the road hauler's stops ----
  // the headframe legs, the hoist house and the ore bins; the skip road between them is open
  mineHeadframe: (W, D) => boxes(
    { x: 0, z: 0, w: Math.min(0.72, W - 0.4), d: Math.min(0.72, W - 0.4) },
    { x: 0, z: -Math.min(D / 2 - 0.2, 0.9), w: 0.9, d: 0.55 },
    { x: -Math.min(W / 2 - 0.4, 1.0), z: D / 2 - 0.5, w: 0.5, d: 0.5 }, { x: Math.min(W / 2 - 0.4, 1.0), z: D / 2 - 0.5, w: 0.5, d: 0.5 },
  ),
  // the two shelters and the gate office; the yard between them is open ground
  lumberYard: (W, D) => boxes(
    { x: -W / 4, z: -0.2, w: Math.min(W / 2 - 0.3, 1.6), d: Math.min(D - 1.0, 1.6) },
    { x: W / 4, z: -0.2, w: Math.min(W / 2 - 0.3, 1.6), d: Math.min(D - 1.0, 1.6) },
    { x: W / 2 - 0.35, z: D / 2 - 0.35, w: 0.5, d: 0.44 }, { x: 0, z: -D / 2 + 0.35, w: 2.1, d: 0.5 },
  ),
  // the shed; the loading apron in front of it is open
  cannery: (W, D) => boxes({ x: 0, z: -D / 2 + Math.min(D - 0.6, 2.2) / 2 + 0.3, w: W - 0.5, d: Math.min(D - 0.6, 2.2) }),
  // the silos and the tipping shed
  grainElevator: (W, D) => {
    const n = Math.max(3, Math.min(5, Math.floor(W / 0.62))), span = (n - 1) * 0.6;
    return boxes({ x: 0, z: -0.1, w: span + 0.6, d: 0.6 }, { x: 0, z: D / 2 - 0.5, w: Math.min(W - 0.6, 1.8), d: 0.7 });
  },
  // the dock is a hole in the quay with a ship in it, and the fitting shop behind
  dryDock: (W, D) => boxes(
    { x: 0, z: 0, w: Math.min(W - 0.8, 2.0), d: Math.min(D - 0.8, 3.0) },
    { x: 0, z: -D / 2 + 0.35, w: W - 0.8, d: 0.5 },
  ),
  // the two towers and the reactor hall; the switchyard is a fenced-off strip of gravel
  coolingTowers: (W, D) => {
    const R2 = Math.min(0.62, W / 4 - 0.1), gap = Math.min(W / 2 - R2 - 0.2, R2 * 1.5), cz = -D / 2 + R2 + 0.4;
    return (x, z) => Math.hypot(x + gap, z - cz) <= R2 || Math.hypot(x - gap, z - cz) <= R2
      || boxes({ x: 0, z: D / 2 - 0.9, w: W - 1.0, d: 0.9 })(x, z);
  },
  // the deck on its legs, out over the water
  oilRig: (W, D) => boxes({ x: 0, z: 0, w: Math.min(W - 0.3, 2.4), d: Math.min(D - 0.3, 2.4) }),
  // the rocket on its mound and the tower beside it, the two halls, the propellant spheres and the water
  // tower's legs (world/spacePlans.ts); the crawlerway, the hardstand and the press stand are driveable
  launchPad: (W, D) => {
    const p = padPlan(W, D);
    const solid = boxes(
      { x: p.tower.x, z: p.tower.z, w: p.tower.half * 2 + 0.1, d: p.tower.half * 2 + 0.1 },
      { x: p.vab.x, z: p.vab.z, w: p.vab.w, d: p.vab.d },
      { x: p.lcc.x, z: p.lcc.z, w: p.lcc.w, d: p.lcc.d },
    );
    const round = [{ x: 0, z: p.cz, r: 1.0 * p.s }, p.lox, p.lh2, { x: p.water.x, z: p.water.z, r: p.water.r * 0.9 }];
    return (x, z) => solid(x, z) || round.some((c) => Math.hypot(x - c.x, z - c.z) <= c.r);
  },
  // the walled basin (a car can't drive into it), the fabrication hall and the pump house; the aprons
  // either side of the basin and the yard at the back right are open
  navalDock: (W, D) => {
    const p = dockPlan(W, D);
    return boxes(
      { x: 0, z: (p.back + p.front) / 2 - p.thick / 2, w: p.bw + p.thick * 2, d: p.front - p.back + p.thick },
      { x: p.hall.x, z: p.hall.z, w: p.hall.w, d: p.hall.d },
      { x: p.pump.x, z: p.pump.z, w: p.pump.w, d: p.pump.d },
    );
  },
  // the booths either side of the lane; the lane itself is the road through
  customsPost: (W) => {
    const lane = Math.min(W * 0.5, 1.2);
    return boxes({ x: -(lane / 2 + 0.3), z: 0, w: 0.42, d: 0.5 }, { x: lane / 2 + 0.3, z: 0, w: 0.42, d: 0.5 });
  },
  // the diner and the pumps; the forecourt and the bays are open
  truckStop: (W, D) => boxes(
    { x: -W / 4, z: -D / 2 + 0.6, w: Math.min(W / 2, 2.0), d: 0.9 },
    { x: W / 4, z: -0.3, w: 0.5, d: 0.16 }, { x: W / 4, z: 0.3, w: 0.5, d: 0.16 },
  ),
  // the office beside the bridge; the weighbridge deck is flat and driven over
  weighStation: (W, D) => boxes({ x: -W / 2 + 0.45, z: -D / 2 + 0.45, w: 0.6, d: 0.6 }),
  // the tunnel's two side walls; a car drives through between them
  carWash: (W, D) => {
    const tw = Math.min(W - 0.5, 1.3), tl = Math.min(D - 0.4, 2.2);
    // the walls and the brushes inside them; a car drives up the lane between
    return boxes({ x: -tw / 2 - 0.08, z: 0, w: 0.34, d: tl }, { x: tw / 2 + 0.08, z: 0, w: 0.34, d: tl }, { x: W / 2 - 0.3, z: D / 2 - 0.3, w: 0.14, d: 0.14 });
  },
  // the hoarding round three sides, the car stacks and the crane
  scrapyard: (W, D) => (x, z) => Math.abs(x) >= W / 2 - 0.14 || z <= -D / 2 + 0.14
    || boxes({ x: -W / 2 + 1.0, z: -D / 2 + 1.0, w: 1.5, d: 1.5 }, { x: W / 2 - 0.7, z: -0.1, w: 0.5, d: 0.7 },
      { x: -W / 2 + 0.5, z: D / 2 - 0.4, w: 0.5, d: 0.4 })(x, z),

  // ---- landmarks and roadside fun ----
  roadsideGiant: () => boxes({ x: 0, z: 0, w: 0.4, d: 0.4 }),
  // the screen at the back and the snack bar in the middle; the ranks of cars are parked, not built
  driveIn: (W, D) => boxes(
    { x: 0, z: -D / 2 + 0.3, w: Math.min(W - 0.9, 4.6) + 0.1, d: 0.3 },
    { x: 0, z: D / 2 - 1.15, w: 1.1, d: 0.55 }, { x: -W / 2 + 0.45, z: D / 2 - 0.22, w: 0.45, d: 0.12 },
  ),
  // the station along the front and the ticket booth (render/buildings/novelty.ts); a car can roll under the rest of the track
  rollerCoaster: (W, D) => {
    const x0 = W / 2 - 0.5, zf = D / 2 - 0.5;
    return boxes({ x: x0 - 1.6, z: zf - 0.03, w: 1.45, d: 0.62 }, { x: x0 - 0.4, z: D / 2 - 0.2, w: 0.32, d: 0.26 });
  },
  waterMill: (W, D) => boxes({ x: 0, z: 0, w: Math.min(W - 0.4, 1.4), d: Math.min(D - 0.4, 1.4) }),
  leaningTower: () => (x, z) => Math.hypot(x, z) <= 0.34,
  greatWall: (W, D) => boxes({ x: 0, z: 0, w: W - 0.2, d: Math.min(0.9, D - 0.4) }),
  // the standing stones, each its own little block
  stoneCircle: (W, D) => {
    const R2 = Math.min(W, D) / 2 - 0.45;
    return (x, z) => { const d = Math.hypot(x, z); return d >= R2 - 0.16 && d <= R2 + 0.16; };
  },
  airshipMast: () => boxes({ x: 0, z: 0, w: 0.34, d: 0.34 }),

  // ---- the railway's: the station buildings block; forecourts, platforms and canopy posts are open ----
  terminus: (W, D) => {
    const bd = Math.min(1.7, D * 0.34), back = D / 2 - 0.15 - bd;
    return boxes({ x: 0, z: back + bd / 2, w: Math.min(W - 1.2, W * 0.72), d: bd }, { x: 0, z: back + 0.1, w: 0.8, d: 0.7 });
  },
  cityStation: (W, D) => {
    const hd = Math.min(1.3, D * 0.34), gw = Math.min(2.2, W * 0.18), gd = Math.min(1.4, D * 0.36);
    return boxes(
      { x: -W * 0.05, z: D / 2 - 0.05 - hd / 2, w: Math.min(3.4, W * 0.3), d: hd + 0.2 },
      { x: W / 2 - 0.2 - gw / 2, z: D / 2 - 0.1 - gd / 2, w: gw, d: gd },
    );
  },
  townStation: (W, D) => {
    const hd = Math.min(1.0, D * 0.36);
    return boxes({ x: -W * 0.08, z: D / 2 - 0.05 - hd / 2, w: Math.min(2.4, W * 0.34), d: hd }, { x: W / 2 - 0.45, z: D / 2 - 0.3, w: 0.46, d: 0.32 });
  },
  halt: (W, D) => boxes({ x: W > 2.5 ? W * 0.08 : 0, z: D / 2 - 0.08, w: Math.min(1.0, W * 0.3), d: 0.2 }),
  goodsYard: (W, D) => {
    const gw = Math.min(4, W * 0.3), gd = Math.min(1.8, D * 0.38);
    return boxes(
      { x: -W / 2 + gw / 2 + 0.4, z: D / 2 - 0.45 - gd / 2, w: gw, d: gd },
      { x: W / 2 - 1.0, z: D / 2 - 0.45, w: 1.1, d: 0.5 },
      { x: (W * 0.08 - 0.6 + W / 2 - 0.25) / 2, z: -D / 2 + 0.75, w: W / 2 - 0.25 - W * 0.08 + 0.6, d: 0.4 },
    );
  },
  harbourDepot: (W, D) => {
    const tw = Math.min(6, W * 0.55), td = Math.min(1.5, D * 0.4), tx = -W / 2 + tw / 2 + 0.3;
    const cx0 = tx + tw / 2 + 0.3, cx1 = W / 2 - 0.1;
    return boxes(
      { x: tx, z: D / 2 - 0.45 - td / 2, w: tw, d: td },
      { x: (cx0 + cx1) / 2, z: D / 2 - 0.52, w: cx1 - cx0, d: 0.82 },
    );
  },
};

/** Sample points per tile side. */
const SAMPLES = 8;
/** A tile the model covers at least this much of may block vehicles... */
const PART_SHARE = 0.3;
/** ...and one whose middle it covers always does. */
const SOLID_SHARE = 0.5;
/**
 * A tile in between blocks only if the model lines a side a car can reach it from: within HUG_DEPTH
 * of that edge along at least HUG_SHARE of it. A car is stopped with its centre on a blocked tile's
 * edge and its nose already nearly half a tile in, so a wall that close is met about where the car
 * stops; one set further back would stop it against thin air, so that tile is left drivable.
 */
const HUG_DEPTH = 0.6, HUG_SHARE = 0.5;

/**
 * One byte per tile of the lot (row-major over [b.x, b.x+b.w) × [b.z, b.z+b.d)): 1 where the model
 * is solid enough to block, 0 where the ground is clear. Kinds without a shape are solid throughout.
 */
export function solidMask(b: Building): Uint8Array {
  const mask = new Uint8Array(b.w * b.d).fill(1);
  const make = SHAPES[b.kind] ?? REGION_SHAPES_A[b.kind] ?? REGION_SHAPES_B[b.kind] ?? REGION_SHAPES_C[b.kind] ?? EXPANSION_SHAPES[b.kind] ?? ANCIENT_SHAPES[b.kind as AncientKind];
  if (!make) return mask;
  // the model's frame: +z is the way it faces, and W × D is the lot turned to match
  const alongZ = b.facing % 2 === 1;
  const W = alongZ ? b.w : b.d, D = alongZ ? b.d : b.w;
  const solid = make(W, D, b);
  const yaw = Math.atan2(DIRS[b.facing][0], DIRS[b.facing][1]);
  const c = Math.cos(yaw), s = Math.sin(yaw);
  const cx = b.x + b.w / 2, cz = b.z + b.d / 2;
  const S = SAMPLES, step = 1 / S;
  // which samples of each tile are inside the model, and how many
  const hit = new Uint8Array(b.w * b.d * S * S);
  const hits = new Uint16Array(b.w * b.d);
  for (let tz = 0; tz < b.d; tz++) {
    for (let tx = 0; tx < b.w; tx++) {
      const t = tz * b.w + tx;
      for (let sz = 0; sz < S; sz++) {
        for (let sx = 0; sx < S; sx++) {
          const dx = b.x + tx + (sx + 0.5) * step - cx, dz = b.z + tz + (sz + 0.5) * step - cz;
          if (solid(dx * c - dz * s, dx * s + dz * c)) { hit[t * S * S + sz * S + sx] = 1; hits[t]++; }
        }
      }
      mask[t] = hits[t] >= PART_SHARE * S * S ? 1 : 0;
    }
  }
  // a circuit's walls are thin and long, and a car must meet every inch of them: any tile they touch is
  // blocked, and the car's own wall test (solidAt) finds where on it the wall really is
  if (b.kind === 'raceCircuit') {
    for (let t = 0; t < mask.length; t++) mask[t] = hits[t] > 0 ? 1 : 0;
    return mask;
  }
  // start with every tile the model covers much of, then let go of the partly covered ones that line none
  // of the sides a car can reach them from, all at once each round, until none is let go
  const near = Math.ceil(HUG_DEPTH * S), lanes = HUG_SHARE * S;
  const at = (t: number, side: number, lane: number, k: number) =>
    hit[t * S * S + (side === 0 ? lane * S + k : side === 1 ? lane * S + S - 1 - k : side === 2 ? k * S + lane : (S - 1 - k) * S + lane)];
  const lines = (t: number, side: number) => {
    let lined = 0;
    for (let lane = 0; lane < S; lane++) {
      for (let k = 0; k < near; k++) if (at(t, side, lane, k)) { lined++; break; }
    }
    return lined >= lanes;
  };
  for (;;) {
    const drop: number[] = [];
    for (let tz = 0; tz < b.d; tz++) {
      for (let tx = 0; tx < b.w; tx++) {
        const t = tz * b.w + tx;
        if (!mask[t] || hits[t] >= SOLID_SHARE * S * S) continue;
        let reached = false, held = false;
        // sides: -x, +x, -z, +z
        for (let side = 0; side < 4 && !held; side++) {
          const nx = tx + (side === 0 ? -1 : side === 1 ? 1 : 0), nz = tz + (side === 2 ? -1 : side === 3 ? 1 : 0);
          if (nx >= 0 && nz >= 0 && nx < b.w && nz < b.d && mask[nz * b.w + nx]) continue;
          reached = true;
          held = lines(t, side);
        }
        if (reached && !held) drop.push(t);
      }
    }
    if (!drop.length) break;
    for (const t of drop) mask[t] = 0;
  }
  // a solid part too small to cover much of any tile (a pump house across a tile corner) still blocks
  // the tiles it covers most of, so it is never driven clean through
  const GW = b.w * S, part = new Int32Array(GW * b.d * S).fill(-1);
  const sample = (gx: number, gz: number) => {
    const tx = Math.floor(gx / S), tz = Math.floor(gz / S);
    return (tz * b.w + tx) * S * S + (gz - tz * S) * S + (gx - tx * S);
  };
  for (let g0 = 0; g0 < part.length; g0++) {
    const x0 = g0 % GW, z0 = (g0 - x0) / GW;
    if (part[g0] >= 0 || !hit[sample(x0, z0)]) continue;
    const stack = [g0], per = new Map<number, number>();
    part[g0] = g0;
    while (stack.length) {
      const g = stack.pop()!, gx = g % GW, gz = (g - gx) / GW;
      const t = Math.floor(gz / S) * b.w + Math.floor(gx / S);
      per.set(t, (per.get(t) ?? 0) + 1);
      for (const [nx, nz] of [[gx + 1, gz], [gx - 1, gz], [gx, gz + 1], [gx, gz - 1]]) {
        if (nx < 0 || nz < 0 || nx >= GW || nz >= b.d * S) continue;
        const n = nz * GW + nx;
        if (part[n] < 0 && hit[sample(nx, nz)]) { part[n] = g0; stack.push(n); }
      }
    }
    if ([...per.keys()].some((t) => mask[t])) continue;
    const most = Math.max(...per.values());
    if (most >= 0.15 * S * S) for (const [t, n] of per) if (n >= most * 0.9) mask[t] = 1;
  }
  return mask;
}

// ---------------- the walls themselves, for the car ----------------

/** The solid test for a building, in its local frame; null when it fills its whole lot. */
const SOLID_OF = new WeakMap<Building, Solid | null>();

function solidOf(b: Building): Solid | null {
  let s = SOLID_OF.get(b);
  if (s !== undefined) return s;
  const make = SHAPES[b.kind] ?? REGION_SHAPES_A[b.kind] ?? REGION_SHAPES_B[b.kind] ?? REGION_SHAPES_C[b.kind] ?? EXPANSION_SHAPES[b.kind] ?? ANCIENT_SHAPES[b.kind as AncientKind];
  const alongZ = b.facing % 2 === 1;
  const W = alongZ ? b.w : b.d, D = alongZ ? b.d : b.w;
  s = make ? make(W, D, b) : null;
  SOLID_OF.set(b, s);
  return s;
}

/**
 * The walls of the model a building actually draws (its variant, in its town's style), in the same local
 * frame as SHAPES; undefined where there is none to go by. Set by the renderer (render/modelFootprint.ts):
 * worldgen and the headless gates never see it, so the tile mask above is untouched by it.
 */
type ModelSolid = (w: World, b: Building) => Solid | null | undefined;
let modelSolid: ModelSolid | null = null;
export function setModelSolid(f: ModelSolid | null): void { modelSolid = f; }

/**
 * Is world point (wx, wz), in tiles, inside the solid part of this building? A kind without a shape
 * is solid over its whole lot. This is the wall the car meets: a blocked tile only says a wall is
 * somewhere on it, and the car drives on until it reaches it. Given the world it stands in, the walls
 * are the drawn model's own, where the renderer can say what they are.
 */
export function solidAt(b: Building, wx: number, wz: number, w?: World): boolean {
  const s = (w && modelSolid?.(w, b)) || solidOf(b);
  const dx = wx - (b.x + b.w / 2), dz = wz - (b.z + b.d / 2);
  if (!s) return Math.abs(dx) <= b.w / 2 && Math.abs(dz) <= b.d / 2;
  const yaw = Math.atan2(DIRS[b.facing][0], DIRS[b.facing][1]);
  const c = Math.cos(yaw), sn = Math.sin(yaw);
  return s(dx * c - dz * sn, dx * sn + dz * c);
}

/** Which building stands on each tile, by index into `w.allBuildings`, rebuilt when the world changes. */
const BUILDING_AT = new WeakMap<World, { rev: number; n: number; at: Int32Array }>();

/** The building whose lot covers tile i, or null: the ground's own obstacles (a rock, a wall) have none. */
export function buildingAt(w: World, i: number): Building | null {
  let ix = BUILDING_AT.get(w);
  // the world's generator adds buildings without a new revision: a new count is a change too
  if (!ix || ix.rev !== w.revision || ix.n !== w.allBuildings.length) {
    ix = { rev: w.revision, n: w.allBuildings.length, at: new Int32Array(N * N).fill(-1) };
    w.allBuildings.forEach((b, k) => {
      if (b.gone) return;
      for (let z = b.z; z < b.z + b.d; z++) for (let x = b.x; x < b.x + b.w; x++) if (inB(x, z)) ix!.at[idx(x, z)] = k;
    });
    BUILDING_AT.set(w, ix);
  }
  const k = ix.at[i];
  const b = k < 0 ? null : w.allBuildings[k];
  return b && !b.gone ? b : null;
}
