import { N, STEP, Biome, DIRS, Flag, RailBit, World, idx, inB, waterDepth, type Building, type RailsideKind } from './tiles';
import type { Rng } from './rng';
import { buildingHeight } from './towns';
import { solidMask } from './footprint';
import { KIND_SPEC } from './townKinds';

/**
 * Works beside the railway (held for 0.8.0, world/nextWorld.ts NEXT_080; the user, 28 Oct 2026): ten kinds of
 * place that make or take goods by the trainload, each standing a tile or few off a county's own main line,
 * facing it, where a train stopped alongside reaches its loading edge (game/cargo.ts buildSites). Placed after
 * every other building, on a random stream of their own (generate.ts), so nothing else in a county moves.
 */

export const RAILSIDE_KINDS: ReadonlySet<string> = new Set<RailsideKind>([
  'lumberSiding', 'coalLoader', 'tankFarm', 'stockyard', 'cementLoadout', 'inlandPort', 'mailDepot', 'ballastPit', 'produceShed', 'breweryRail',
]);

interface Row {
  kind: RailsideKind;
  w: number; d: number;
  /** The share of counties with track that get one, before a lot is looked for. */
  chance: number;
  /** What the lot wants round it: a score, or null where it won't do. */
  want: (c: Ctx, x: number, z: number) => number | null;
}

interface Ctx {
  w: World;
  near: (x: number, z: number, r: number, test: (i: number) => boolean) => number;
  townDist: (x: number, z: number, big?: boolean) => number;
  buildingNear: (x: number, z: number, r: number, kinds: Set<string>) => boolean;
}

const QUARRYISH = new Set(['crusher', 'mineHeadframe', 'gravelPlant', 'oreMill', 'coalTipple', 'quarry', 'cementPlant', 'abandonedMine']);
const OIL = new Set(['refinery', 'oilRig', 'majorPort', 'containerTerminal']);
const STATIONS = new Set(['terminus', 'cityStation', 'townStation', 'halt']);

const forest = (w: World) => (i: number) => w.biome[i] === Biome.Forest;
const farmed = (w: World) => (i: number) => !!(w.flags[i] & Flag.Field);
const grass = (w: World) => (i: number) => w.biome[i] === Biome.Plains || w.biome[i] === Biome.Farm || !!(w.flags[i] & Flag.Field);
const high = (w: World) => (i: number) => w.biome[i] === Biome.Mountain || w.biome[i] === Biome.Hills;

const ROWS: Row[] = [
  { kind: 'lumberSiding', w: 4, d: 3, chance: 0.6, want: (c, x, z) => { const t = c.near(x, z, 6, forest(c.w)); return t >= 18 ? t : null; } },
  { kind: 'coalLoader', w: 3, d: 3, chance: 0.45, want: (c, x, z) => (c.buildingNear(x, z, 40, QUARRYISH) ? 40 : c.near(x, z, 8, high(c.w)) >= 12 ? 10 : null) },
  { kind: 'tankFarm', w: 5, d: 4, chance: 0.4, want: (c, x, z) => (c.buildingNear(x, z, 50, OIL) ? 30 - c.w.coastDist[idx(x, z)] * 0.2 : c.w.coastDist[idx(x, z)] <= 16 ? 5 : null) },
  { kind: 'stockyard', w: 5, d: 4, chance: 0.5, want: (c, x, z) => { const g = c.near(x, z, 6, grass(c.w)); return g >= 60 && c.townDist(x, z) >= 8 ? g : null; } },
  { kind: 'cementLoadout', w: 3, d: 3, chance: 0.4, want: (c, x, z) => (c.buildingNear(x, z, 40, QUARRYISH) ? 20 : null) },
  { kind: 'inlandPort', w: 6, d: 4, chance: 0.45, want: (c, x, z) => { const d = c.townDist(x, z, true); return d <= 24 ? 30 - d : null; } },
  { kind: 'mailDepot', w: 4, d: 2, chance: 0.7, want: (c, x, z) => (c.buildingNear(x, z, 14, STATIONS) ? 20 : null) },
  { kind: 'ballastPit', w: 4, d: 4, chance: 0.4, want: (c, x, z) => { const d = c.townDist(x, z); return d >= 18 ? Math.min(40, d) : null; } },
  { kind: 'produceShed', w: 4, d: 3, chance: 0.55, want: (c, x, z) => { const f = c.near(x, z, 6, farmed(c.w)); return f >= 20 ? f : null; } },
  { kind: 'breweryRail', w: 4, d: 3, chance: 0.35, want: (c, x, z) => { const d = c.townDist(x, z); return d >= 3 && d <= 18 ? 20 - d : null; } },
];

/** Tiles from a lot's edge to the line it serves: next to it is a tile off, no further than this. */
const OFF_MIN = 1, OFF_MAX = 4;
/** Two works of any of these kinds stand at least this far apart, in tiles. */
const APART = 14;

/** The ten rail-side works of a county with a main line, where each finds a lot. `lane` runs a track out to the roads from a gate tile. */
export function placeRailside(w: World, rng: Rng, band: number, lane?: (gate: number) => void): Building[] {
  const out: Building[] = [];
  // only the county's own main line: track at ground level, not a deck or a tunnel
  const track = (i: number) => (w.rail[i] & RailBit.Track) !== 0 && !(w.rail[i] & (RailBit.Deck | RailBit.Tunnel));
  // tiles from the line, out to OFF_MAX + a lot's width, by a flood from every track tile
  const dist = new Uint8Array(N * N).fill(255);
  let q: number[] = [];
  for (let i = 0; i < N * N; i++) if (track(i)) { dist[i] = 0; q.push(i); }
  if (!q.length) return out;
  for (let s = 1; s <= OFF_MAX + 1 && q.length; s++) {
    const next: number[] = [];
    for (const i of q) {
      const x = i % N, z = (i - x) / N;
      for (const [dx, dz] of DIRS) {
        const tx = x + dx, tz = z + dz;
        if (!inB(tx, tz)) continue;
        const j = idx(tx, tz);
        if (dist[j] !== 255) continue;
        dist[j] = s;
        next.push(j);
      }
    }
    q = next;
  }
  const lo = band + 4, hi = N - band - 4;
  const free = (x: number, z: number) => {
    if (x < lo || z < lo || x >= hi || z >= hi) return false;
    const i = idx(x, z);
    return w.townId[i] < 0 && w.portId[i] < 0 && !w.road[i] && !w.rail[i] && !w.blocked[i] && w.feature[i] === 0 && waterDepth(w, i) === 0 && w.water[i] < 0
      && !(w.flags[i] & (Flag.Poi | Flag.Track | Flag.Ramp | Flag.Corridor));
  };
  /** Every tile of the lot free, flat enough, and the lot's nearest tile OFF_MIN..OFF_MAX from the line. */
  const lotOk = (x: number, z: number, wx: number, wz: number) => {
    let lo2 = 127, hi2 = -128, nearest = 255;
    for (let zz = z; zz < z + wz; zz++) for (let xx = x; xx < x + wx; xx++) {
      if (!inB(xx, zz) || !free(xx, zz)) return false;
      const i = idx(xx, zz);
      nearest = Math.min(nearest, dist[i]);
      for (let k = 0; k < 4; k++) { const c = w.corners[i * 4 + k]; lo2 = Math.min(lo2, c); hi2 = Math.max(hi2, c); }
    }
    return hi2 - lo2 <= 1 && nearest >= OFF_MIN && nearest <= OFF_MAX;
  };
  const ctx: Ctx = {
    w,
    near: (x, z, r, test) => {
      let n = 0;
      for (let zz = z - r; zz <= z + r; zz++) for (let xx = x - r; xx <= x + r; xx++) if (inB(xx, zz) && test(idx(xx, zz))) n++;
      return n;
    },
    townDist: (x, z, big = false) => {
      let best = 999;
      for (const t of w.towns) {
        if (big && t.kind !== 'city' && t.kind !== 'metro' && t.kind !== 'mega') continue;
        best = Math.min(best, Math.max(0, Math.abs(x - (t.x0 + t.size / 2)) - t.size / 2, Math.abs(z - (t.z0 + t.size / 2)) - t.size / 2));
      }
      return best;
    },
    buildingNear: (x, z, r, kinds) => w.allBuildings.some((b) => !b.gone && kinds.has(b.kind) && Math.abs(b.x + b.w / 2 - x) <= r && Math.abs(b.z + b.d / 2 - z) <= r),
  };
  // the lots near enough the line to look at: every tile OFF_MIN..OFF_MAX off it, as a lot's corner
  const spots: number[] = [];
  for (let i = 0; i < N * N; i++) if (dist[i] >= OFF_MIN && dist[i] <= OFF_MAX && free(i % N, (i - (i % N)) / N)) spots.push(i);
  if (!spots.length) return out;

  for (const row of ROWS) {
    // the roll is made whether or not the row finds a lot, so one row's luck never moves another's
    if (rng() >= row.chance) continue;
    let best: { x: number; z: number; score: number } | null = null;
    for (let tries = 0; tries < 260; tries++) {
      const s = spots[Math.floor(rng() * spots.length)];
      // the spot is any corner of the lot
      const x = (s % N) - (rng() < 0.5 ? 0 : row.w - 1), z = Math.floor(s / N) - (rng() < 0.5 ? 0 : row.d - 1);
      if (!lotOk(x, z, row.w, row.d)) continue;
      if (out.some((b) => Math.abs(b.x - x) < APART && Math.abs(b.z - z) < APART)) continue;
      const score = row.want(ctx, x + Math.floor(row.w / 2), z + Math.floor(row.d / 2));
      if (score === null) continue;
      if (!best || score + rng() * 4 > best.score) best = { x, z, score: score + rng() * 4 };
    }
    if (!best) continue;
    const b = put(w, rng, row.kind, best.x, best.z, row.w, row.d, faceLine(w, dist, best.x, best.z, row.w, row.d));
    out.push(b);
    // a lane to the roads from the side away from the line
    if (lane) {
      const back = (b.facing + 2) % 4, [dx, dz] = DIRS[back];
      const gx = b.x + Math.floor(b.w / 2) + (dx > 0 ? Math.ceil(b.w / 2) : dx < 0 ? -Math.floor(b.w / 2) - 1 : 0);
      const gz = b.z + Math.floor(b.d / 2) + (dz > 0 ? Math.ceil(b.d / 2) : dz < 0 ? -Math.floor(b.d / 2) - 1 : 0);
      if (inB(gx, gz) && free(gx, gz)) lane(idx(gx, gz));
    }
  }
  return out;
}

/** Which way a lot faces to look at the line: the side its nearest track tile is on (DIRS order: +x, +z, −x, −z). */
function faceLine(w: World, dist: Uint8Array, x: number, z: number, wx: number, wz: number): number {
  // the mean distance along each side's outer row: the side nearest the line is the front
  const side = (d: number): number => {
    let sum = 0, n = 0;
    const [dx, dz] = DIRS[d];
    for (let k = 0; k < (dx ? wz : wx); k++) {
      const tx = dx > 0 ? x + wx : dx < 0 ? x - 1 : x + k, tz = dz > 0 ? z + wz : dz < 0 ? z - 1 : z + k;
      sum += inB(tx, tz) ? dist[idx(tx, tz)] : 255;
      n++;
    }
    return sum / Math.max(1, n);
  };
  void w;
  let best = 0, bestD = Infinity;
  for (let d = 0; d < 4; d++) { const v = side(d); if (v < bestD) { bestD = v; best = d; } }
  return best;
}

/** A works on its lot, levelled, its solid part blocking the ground, as a roadside building is (world/roadside.ts). */
function put(w: World, rng: Rng, kind: RailsideKind, x: number, z: number, wx: number, wz: number, facing: number): Building {
  const solid = KIND_SPEC[kind]?.solid !== false;
  let sum = 0;
  for (let zz = z; zz < z + wz; zz++) for (let xx = x; xx < x + wx; xx++) for (let q = 0; q < 4; q++) sum += w.corners[idx(xx, zz) * 4 + q];
  const level = Math.round(sum / (wx * wz * 4));
  const b: Building = { kind, x, z, w: wx, d: wz, facing: facing as Building['facing'], floors: 1, seed: Math.floor(rng() * 2 ** 31), solid, level, uid: w.allBuildings.length };
  w.allBuildings.push(b);
  w.countryside.push(b);
  const top = level * STEP + buildingHeight(b);
  const mask = solid ? solidMask(b) : null;
  for (let zz = z; zz < z + wz; zz++) for (let xx = x; xx < x + wx; xx++) {
    const i = idx(xx, zz);
    w.flags[i] |= Flag.Poi;
    for (let q = 0; q < 4; q++) w.corners[i * 4 + q] = level;
    if (mask && mask[(zz - z) * wx + xx - x]) { w.blocked[i] = 1; w.roof[i] = Math.max(w.roof[i], top); }
  }
  return b;
}
