import type { Building, BuildingKind } from './tiles';

/**
 * Which parts of some biome buildings block vehicles, in the model's local frame (origin mid-lot,
 * +z the way it faces, W across and D deep). Kinds left out fill their lot. See footprint.ts.
 */
type Solid = (lx: number, lz: number) => boolean;
export const boxes = (...list: { x: number; z: number; w: number; d: number }[]): Solid =>
  (lx, lz) => list.some((p) => Math.abs(lx - p.x) <= p.w / 2 && Math.abs(lz - p.z) <= p.d / 2);

/**
 * The moated castle's plan (render/buildings/medieval.ts draws to it): the moat's outer and inner
 * banks, the curtain wall's half-width and thickness, the drawbridge's half-width and the gate's.
 */
export const MOAT = { outer: 6.5, inner: 5.0, wall: 4.3, thick: 0.44, bridge: 0.6, gate: 0.45 } as const;

export const REGION_SHAPES_C: Partial<Record<BuildingKind, (W: number, D: number, b: Building) => Solid>> = {
  // ---- the Veldt ----
  // the terrace with the lodge, the guest hut and the viewing deck on its stilts; the pool and parking are open
  safariLodge: (W, D) => boxes({ x: -0.35, z: -0.45, w: 1.9, d: 1.6 }, { x: W / 2 - 0.45, z: -D / 2 + 0.45, w: 0.6, d: 0.6 }, { x: W / 2 - 0.55, z: 0.35, w: 0.86, d: 1.0 }),
  // the boulder stack and the lodge deck on its flank; the track to the stair is open
  greatKopje: () => (x, z) => Math.hypot(x, z + 0.6) <= 4.3 || boxes({ x: -1.0, z: 3.0, w: 2.6, d: 1.4 })(x, z),
  // ---- the Fens ----
  // the house with its gallery and the two garçonnières; the avenue, gardens and landing are open
  plantationManor: () => boxes({ x: 0, z: -3.6, w: 6.6, d: 4.4 }, { x: -4.7, z: -5.4, w: 1.1, d: 1.1 }, { x: 4.7, z: -5.4, w: 1.1, d: 1.1 }),
  generalStore: (W, D) => boxes({ x: 0, z: -0.12, w: W - 0.4, d: D - 0.4 }),
  // ---- the Terraces ----
  // the moat, the stone base with its walls, turrets and keep; the causeway to the gate is open
  hilltopCastle: () => (x, z) => Math.abs(x) <= 5.65 && Math.abs(z) <= 5.65 && !(Math.abs(x) <= 0.65 && z >= 4.1),
  teaHouse: () => boxes({ x: -0.2, z: -0.3, w: 1.4, d: 1.08 }),
  bathhouse: () => boxes({ x: 0, z: -0.42, w: 1.5, d: 0.86 }),
  // ---- the Whitewash ----
  // the stepped plinth; the approach and the rocks round the headland are open
  capeTemple: () => boxes({ x: 0, z: -0.6, w: 6.2, d: 10.2 }),
  // ---- the Golden Hills ----
  // the church, its bell wall and the convento's range; the garden, the fountain and the arcade's walk are open
  mission: (W, D) => boxes({ x: -W / 2 + 3.4, z: -D / 2 + 3.3, w: 3.7, d: 5.6 }, { x: W / 2 - 2.2, z: -0.4, w: 2.4, d: D - 3.2 }),
  ranchHouse: (W) => boxes({ x: -0.15, z: -0.2, w: W - 0.8, d: 1.0 }),
  wineryBarn: (W, D) => boxes({ x: 0, z: -0.1, w: W - 0.5, d: D - 0.7 }),
  taverna: (W, D) => boxes({ x: -W / 2 + 0.5, z: -D / 2 + 0.3, w: 0.86, d: 0.52 }),
  // ---- broadcasting: the mast's foot (its guys are open ground), the tower's four legs, the stations' buildings ----
  radioMast: () => (x, z) => Math.hypot(x, z) <= 0.3,
  radioTower: () => boxes({ x: 0, z: 0, w: 1.5, d: 1.5 }),
  radioStation: () => boxes({ x: 0, z: -0.2, w: 1.45, d: 1.05 }, { x: -0.62, z: 0.55, w: 0.4, d: 0.4 }),
  newsStation: (W, D) => boxes({ x: 0, z: -0.15, w: W - 0.35, d: D - 0.6 }),
  // ---- a medieval town's own, and the moated castle ----
  watchtower: () => (x, z) => Math.hypot(x, z) <= 0.33,
  // the market hall under the guildhall is open to walk through, but not to drive: the whole block
  guildhall: (W, D) => boxes({ x: 0, z: -0.1, w: W - 0.3, d: D - 0.45 }),
  titheBarn: (W, D) => boxes({ x: 0, z: -0.1, w: W - 0.2, d: D - 0.45 }, { x: 0, z: D / 2 - 0.5, w: 0.66, d: 0.5 }),
  // ---- the themed towns' own ----
  // the thermal bath's back range and its two wings; the courtyard of pools between them is open to the street
  thermalBath: (W, D) => {
    const w = W - 0.2, d = D - 0.2, bd = 0.72, sw = 0.56, wd = d - bd - 0.1, wz = -d / 2 + bd + wd / 2;
    return boxes({ x: 0, z: -d / 2 + bd / 2, w, d: bd }, { x: -(w / 2 - sw / 2), z: wz, w: sw, d: wd }, { x: w / 2 - sw / 2, z: wz, w: sw, d: wd });
  },
  // the moat, the walls and their towers, the keep, the hall and the chapel; the drawbridge, the gate
  // passage and the bailey are open, so a car can drive over the moat and into the courtyard
  moatedCastle: () => {
    const { outer: O, inner: I, wall: e, thick: t, bridge, gate } = MOAT;
    const inside = boxes({ x: 0, z: -1.4, w: 2.9, d: 2.9 }, { x: 0, z: 0.2, w: 0.6, d: 0.7 }, { x: -2.9, z: 1.5, w: 1.5, d: 2.7 }, { x: 2.9, z: 1.9, w: 1.3, d: 2.0 },
      { x: 0.9, z: 1.6, w: 0.6, d: 0.6 }, { x: -e, z: 0, w: 1, d: 1 }, { x: e, z: 0, w: 1, d: 1 }, { x: 0, z: -e, w: 1, d: 1 });
    return (x, z) => {
      const m = Math.max(Math.abs(x), Math.abs(z));
      if (z > 0 && Math.abs(x) <= bridge && m >= e - t) return false;          // the drawbridge
      if (z > 0 && Math.abs(x) <= gate && m >= e - t - 0.6) return false;       // and the gate passage
      if (m >= I && m <= O) return true;                                        // the moat
      if (Math.abs(m - e) <= t / 2 + 0.05) return true;                         // the curtain wall
      if (Math.hypot(Math.abs(x) - e, Math.abs(z) - e) <= 0.82) return true;    // its corner towers
      if (z > e - 0.6 && z < e + 0.8 && Math.abs(x) <= 1.6) return true;        // the gatehouse
      return m < e && inside(x, z);
    };
  },
};
