export interface CarStats {
  name: string;
  /** The player's own vehicles with every biome stamped (game/passportRewards.ts): this share less of the pace rough ground costs is lost. */
  trek?: number;
  topSpeed: number;      // tiles/s on the flat
  accel: number;         // tiles/s^2
  brake: number;         // tiles/s^2
  coast: number;         // tiles/s^2 deceleration with no input
  reverseCap: number;    // tiles/s
  weight: number;        // scales the gravity term
  uphillPenalty: number; // top-speed reduction per step of grade
  downhillBonus: number; // extra top speed (tiles/s) per step of downhill grade
  maxGrade: number;      // steepest tile it can climb (1 = slope, 2 = steep)
  curb: number;          // edge mismatch it can hop, in steps
  wade: number;          // max water depth in steps
  steerRate: number;     // rad/s at walking pace
  color: number;
  // optional extras used by the cheat vehicles
  halfLen?: number;      // half body length used for slope sampling (default 0.45)
  halfWid?: number;      // half body width (default 0.3)
  lean?: number;         // body roll into turns; negative sways outward
  swimSpeed?: number;    // amphibious: top speed when afloat in deep water
  draft?: number;        // amphibious: how deep it sits when afloat
  surface?: SurfaceMul;  // top-speed multipliers by ground type
  bumpMul?: number;      // suspension kick on bumps (default 1)
  springK?: number;      // suspension stiffness (default 120)
  trailer?: { hitch: number; length: number }; // hitch behind centre, hitch-to-axle length
  tyres?: { single?: boolean; width?: number }; // tracks: one line (a motorbike), tyre width as a share of halfWid (default 0.38)
  scale?: number;        // model scale (sizes above are already multiplied by it)
  // ---- set by workshop parts (game/parts.ts); a stock vehicle has none of these ----
  grip?: number;         // off-road grip multiplier (tyres), capped at full grip
  roadMul?: number;      // top-speed multiplier on a road (big tyres are slower on tarmac)
  rough?: number;        // share (0–1) of what rough ground takes off top speed that tyres win back, up to dirt-lane pace
  heft?: number;         // how much a fence feels this car (bull bar)
  glance?: number;       // sine to an obstacle below which a hit is a slide (default 0.7)
  bounce?: number;       // share of speed kept, reversed, off a wall head on (default 0.1)
  drift?: DriftStats;    // a handbrake: holding Space slides the tail round a corner
  burnout?: boolean;     // a race gearbox marks the road pulling away
  chirp?: boolean;       // race brakes mark the road in a hard stop
}

/** A handbrake: how much faster the car rotates, how quickly its travel follows its nose, and the speed it scrubs. */
interface DriftStats { yaw: number; follow: number; drag: number }

interface SurfaceMul { track?: number; offroad?: number; sand?: number; snow?: number; farm?: number }

