import { N, CHUNK, RoadType, World, idx, inB, type Building } from './tiles';
import { hash2 } from './rng';

/**
 * Diagonal roads: roads at exactly 45° (docs: the user's request, Oct 2026).
 *
 * A diagonal is laid on the tiles a 45° line passes through — a staircase, one tile across and one up,
 * over and over — so everything that works by tiles works on it unchanged: its tiles are road, joined
 * edge to edge (roadEdges), a car crosses from one to the next over an ordinary tile edge, a route over
 * it is a route over road tiles, a save stores its nodes like any other road's. What makes it a diagonal
 * is only the shape of its nodes: any stretch of a road whose steps strictly alternate between two
 * square directions, at least DIAG_MIN steps long, is a diagonal (`diagRuns`). Nothing is stored for it,
 * so old saves, the online server and every edit carry diagonals with no new field.
 *
 * Every step's midpoint (the middle of the tile edge it crosses) lies on one straight 45° line, and that
 * line is the road: drawn as one straight ribbon (render/roadMesh.ts), driven by the CPU along it
 * (curves.ts `smoothRamps` → `smoothDiagonals`), and costed at √½ a tile per step (roads.ts trafficStep)
 * so a route takes it as the short cut it is. The ribbon fills the middle of each staircase tile and
 * leaves a triangle on the far side of it: that triangle is the verge, and where a grid-aligned building
 * stands beside it, its front yard (`yardsOf`): a lawn with a path to the door, or a garden with shrubs,
 * flowers and a tree.
 *
 * Diagonals are lanes only: dirt, gravel, brick, cobbles, paved and two-lane. Four lanes, the interstate and
 * the ramps keep their own shapes, and a diagonal carries no bridge or raised deck (the decks are straight
 * and square to the grid).
 */

/** The fewest alternating steps that make a diagonal (two tiles across and two up): fewer is a jog. */
export const DIAG_MIN = 4;
/** What a step along a diagonal costs a CPU route against a square step's 1: the line is √2 long for two steps. */
export const DIAG_STEP = Math.SQRT1_2;

const DX = [1, 0, -1, 0], DZ = [0, 1, 0, -1];

/** Road types that may run diagonally. */
export function diagonalType(t: RoadType): boolean {
  return t !== RoadType.None && t !== RoadType.FourLane && t !== RoadType.Interstate && t !== RoadType.Ramp;
}

function dirOf(a: number, b: number): number {
  const d = b - a;
  return d === 1 ? 0 : d === N ? 1 : d === -1 ? 2 : d === -N ? 3 : -1;
}

/**
 * One diagonal stretch of a road: its steps i..j (step k runs from nodes[k] to nodes[k + 1]) alternate
 * between directions a (step i) and b. Its line: `o` 1 for x − z = c (running +x+z or −x−z), 2 for
 * x + z = c; every step's midpoint lies on it.
 */
interface DiagRun { i: number; j: number; a: number; b: number; o: 1 | 2; c: number }

/** The diagonal stretches of a road of this type along these nodes, in order (two may share a step: a V). */
export function diagRuns(type: RoadType, nodes: readonly number[]): DiagRun[] {
  const out: DiagRun[] = [];
  if (!diagonalType(type) || nodes.length < DIAG_MIN + 1) return out;
  const n = nodes.length - 1;
  const dirs: number[] = [];
  for (let k = 0; k < n; k++) dirs.push(dirOf(nodes[k], nodes[k + 1]));
  const perp = (p: number, q: number) => p >= 0 && q >= 0 && ((p + q) & 1) === 1;
  let k = 0;
  while (k < n - 1) {
    if (!perp(dirs[k], dirs[k + 1])) { k++; continue; }
    let j = k + 1;
    while (j + 1 < n && dirs[j + 1] === dirs[j - 1]) j++;
    if (j - k + 1 >= DIAG_MIN) {
      const a = dirs[k], b = dirs[k + 1];
      const [mx, mz] = stepMid(nodes, k);
      const o: 1 | 2 = (DX[a] + DX[b]) * (DZ[a] + DZ[b]) > 0 ? 1 : 2;
      out.push({ i: k, j, a, b, o, c: o === 1 ? mx - mz : mx + mz });
      k = j;
    } else k++;
  }
  return out;
}

/** The middle of step k of a road: the middle of the tile edge between nodes[k] and nodes[k + 1]. */
function stepMid(nodes: readonly number[], k: number): [number, number] {
  const a = nodes[k], b = nodes[k + 1];
  return [((a % N) + (b % N)) / 2 + 0.5, (Math.floor(a / N) + Math.floor(b / N)) / 2 + 0.5];
}

/** The nearest point to (x, z) on line (o, c). */
export function onLine(o: 1 | 2, c: number, x: number, z: number): [number, number] {
  if (o === 1) { const e = (x - z - c) / 2; return [x - e, z + e]; }
  const e = (x + z - c) / 2;
  return [x - e, z - e];
}

/**
 * The tile code a diagonal leaves on each tile strictly inside it (w.roadDiag): which line passes the
 * tile, and on which side of the middle — 1 / 2: x − z = (x − z of the middle) ± ½; 3 / 4: x + z = (x + z of the middle) ± ½.
 */
function diagCode(t: number, o: 1 | 2, c: number): number {
  const tx = t % N, tz = Math.floor(t / N);
  if (o === 1) return c > tx - tz ? 1 : 2;
  return c > tx + tz + 1 ? 3 : 4;
}

/** The line a tile's code names. */
export function lineOf(t: number, code: number): { o: 1 | 2; c: number } {
  const tx = t % N, tz = Math.floor(t / N);
  if (code <= 2) return { o: 1, c: tx - tz + (code === 1 ? 0.5 : -0.5) };
  return { o: 2, c: tx + tz + 1 + (code === 3 ? 0.5 : -0.5) };
}

/** Does line (o, c) run through tile t's staircase (half a tile off its middle, either side)? */
export function inBand(t: number, o: 1 | 2, c: number): boolean {
  const tx = t % N, tz = Math.floor(t / N);
  return Math.abs((o === 1 ? tx - tz : tx + tz + 1) - c) === 0.5;
}

/** Do two coded tiles lie on the same diagonal line? */
export function sameLine(a: number, ca: number, b: number, cb: number): boolean {
  if (!ca || !cb) return false;
  const p = lineOf(a, ca), q = lineOf(b, cb);
  return p.o === q.o && p.c === q.c;
}

/** Mark the tiles strictly inside each diagonal of a road (rebuilt with the other road tables). */
export function markDiagonals(w: World, type: RoadType, nodes: readonly number[]): void {
  for (const r of diagRuns(type, nodes)) {
    for (let k = r.i + 1; k <= r.j; k++) {
      const t = nodes[k];
      if (!w.roadDiag[t]) w.roadDiag[t] = diagCode(t, r.o, r.c);
    }
  }
}

/** Does any road here run diagonally? Kept per road stamp. */
const ANY = new WeakMap<World, { stamp: number; yes: boolean }>();
export function hasDiagonals(w: World): boolean {
  let c = ANY.get(w);
  if (!c || c.stamp !== w.roadStamp) {
    let yes = false;
    for (const r of w.roads) if (diagRuns(r.type, r.nodes).length) { yes = true; break; }
    c = { stamp: w.roadStamp, yes };
    ANY.set(w, c);
  }
  return c.yes;
}

/**
 * A road's centre line as points: tile middles along its square stretches, and each diagonal stretch as
 * one straight segment from its first step's middle to its last's (a road that starts or ends on a
 * diagonal starts or ends on the line, level with its end tile's middle). `nodePt[k]` is the point of node
 * k, -1 for a node inside a diagonal. Null for a road with no diagonal in it.
 */
export function roadLine(type: RoadType, nodes: readonly number[]): { pts: [number, number][]; nodePt: Int32Array } | null {
  const runs = diagRuns(type, nodes);
  if (!runs.length) return null;
  const n = nodes.length;
  const centre = (k: number): [number, number] => [(nodes[k] % N) + 0.5, Math.floor(nodes[k] / N) + 0.5];
  const pts: [number, number][] = [];
  const nodePt = new Int32Array(n).fill(-1);
  const push = (p: [number, number]) => {
    const q = pts[pts.length - 1];
    if (q && Math.abs(q[0] - p[0]) < 1e-9 && Math.abs(q[1] - p[1]) < 1e-9) return;
    pts.push(p);
  };
  const inside = new Int32Array(n).fill(-1);   // the run a node lies strictly inside
  runs.forEach((r, ri) => { for (let k = r.i + 1; k <= r.j; k++) inside[k] = ri; });
  for (let k = 0; k < n; k++) {
    const starts = runs.find((r) => r.i === k);
    const ri = inside[k];
    if (ri >= 0) {
      const r = runs[ri];
      // its last node inside: the line ends at the middle of its last step (or on the line at the road's end)
      if (k === r.j) {
        if (r.j === n - 2 && !starts) { const [x, z] = centre(n - 1); push(onLine(r.o, r.c, x, z)); nodePt[n - 1] = pts.length - 1; return { pts, nodePt }; }
        push(stepMid(nodes, r.j));
      }
      if (starts && k !== r.j) push(stepMid(nodes, k));
      continue;
    }
    if (starts && k === 0) {
      const [x, z] = centre(0);
      push(onLine(starts.o, starts.c, x, z));
      nodePt[0] = pts.length - 1;
      continue;
    }
    push(centre(k));
    nodePt[k] = pts.length - 1;
    if (starts) push(stepMid(nodes, k));
  }
  return { pts, nodePt };
}

// ---------------------------------------------------------------------------------------------
// the CPU's routes along a diagonal

/**
 * A CPU route's points along the diagonals it takes: every point whose tile lies inside a diagonal, reached
 * from and left for tiles of the same staircase, moves onto the line — the middles of a staircase's tiles
 * project onto it evenly spaced, so the car drives the straight 45° line the road is drawn as rather than
 * stepping across and up it tile by tile.
 */
export function smoothDiagonals(w: World, pts: { x: number; z: number; tile: number }[]): { x: number; z: number; tile: number }[] {
  if (pts.length < 3 || !hasDiagonals(w)) return pts;
  let out: { x: number; z: number; tile: number }[] | null = null;
  for (let k = 1; k < pts.length - 1; k++) {
    const t = pts[k].tile, code = t >= 0 && t < N * N ? w.roadDiag[t] : 0;
    if (!code) continue;
    const { o, c } = lineOf(t, code);
    const p = pts[k - 1].tile, q = pts[k + 1].tile;
    if (p === t || q === t || !inBand(p, o, c) || !inBand(q, o, c)) continue;
    // only a point that stands at its tile's middle (not one already moved onto a curve)
    const cx = (t % N) + 0.5, cz = Math.floor(t / N) + 0.5;
    if (Math.abs(pts[k].x - cx) > 1e-6 || Math.abs(pts[k].z - cz) > 1e-6) continue;
    const [x, z] = onLine(o, c, cx, cz);
    out ??= pts.slice();
    out[k] = { x, z, tile: t };
  }
  return out ?? pts;
}

// ---------------------------------------------------------------------------------------------
// the verges and front yards

/**
 * The triangle of a diagonal's tile that its road leaves free: the part beyond the ribbon's edge (its
 * half-width, and a hair of kerb), as a polygon of x z pairs; with the corner the triangle is square at
 * (`rx`, `rz`) and how long its two square legs are. Null where the road leaves none.
 */
export function freeTriangle(w: World, t: number): { poly: number[]; rx: number; rz: number; leg: number; o: 1 | 2; s: number } | null {
  const code = w.roadDiag[t];
  if (!code) return null;
  const { o, c } = lineOf(t, code);
  const tx = t % N, tz = Math.floor(t / N);
  // which side of the line the tile's middle is: the free side
  const mid = (o === 1 ? tx - tz : tx + tz + 1) - c;
  const s = mid > 0 ? 1 : -1;
  const half = Math.min(0.5, (ROAD_HALF[w.road[t] as RoadType] ?? 0.31));
  const edge = half * Math.SQRT2 + 0.06;
  const leg = 1.5 - edge;
  if (leg < 0.2) return null;
  let poly = [tx, tz, tx + 1, tz, tx + 1, tz + 1, tx, tz + 1];
  // keep s·f(x, z) ≥ edge, f = x − z − c (o 1) or x + z − c (o 2)
  poly = o === 1 ? clip(poly, s, -s, -s * c - edge) : clip(poly, s, s, -s * c - edge);
  if (poly.length < 6) return null;
  // the corner furthest from the line: square-on to the two tile edges that meet there
  let rx = tx, rz = tz, best = -Infinity;
  for (const [x, z] of [[tx, tz], [tx + 1, tz], [tx + 1, tz + 1], [tx, tz + 1]]) {
    const f = s * ((o === 1 ? x - z : x + z) - c);
    if (f > best) { best = f; rx = x; rz = z; }
  }
  return { poly, rx, rz, leg, o, s };
}

/** Half a road's width by type, where a diagonal's ribbon reaches out to (render/roadMesh.ts draws the same). */
const ROAD_HALF: Partial<Record<RoadType, number>> = {
  [RoadType.Dirt]: 0.3, [RoadType.Brick]: 0.32, [RoadType.Paved]: 0.31, [RoadType.TwoLane]: 0.48, [RoadType.Gravel]: 0.29, [RoadType.Cobble]: 0.33,
};

/** Keep the part of a polygon (x z pairs) where a·x + b·z + c ≥ 0. */
function clip(poly: number[], a: number, b: number, c: number): number[] {
  const out: number[] = [];
  const len = poly.length;
  for (let k = 0; k < len; k += 2) {
    const px = poly[k], pz = poly[k + 1], qx = poly[(k + 2) % len], qz = poly[(k + 3) % len];
    const fp = a * px + b * pz + c, fq = a * qx + b * qz + c;
    if (fp >= 0) out.push(px, pz);
    if ((fp >= 0) !== (fq >= 0)) { const u = fp / (fp - fq); out.push(px + (qx - px) * u, pz + (qz - pz) * u); }
  }
  return out;
}

type YardPlant = { kind: 'shrub' | 'tuft' | 'round' | 'oak' | 'poplar' | 'birch' | 'palm' | 'stonePine'; x: number; z: number; s: number; yaw: number; tint?: [number, number, number] };

/**
 * The free triangle of a diagonal's tile, and what is made of it: a front yard when a building stands
 * against it (`uid`), its front (`front`) when the building faces it; a plain verge otherwise. A yard is
 * a garden (`lawn` false: a bed of shrubs along the building, flowers, a small tree) or a lawn with a path
 * from the door to the road.
 */
export interface Yard {
  tile: number;
  poly: number[];
  /** The building it belongs to (its uid), or -1 for a verge with nobody behind it. */
  uid: number;
  front: boolean;
  lawn: boolean;
  /** In a town: a verge there is mown grass too. */
  town: boolean;
  /** The path from the door to the road's edge: a quad (x z pairs), on a lawn in front of a building. */
  path?: number[];
  /** The bed along the building's side of a garden: a smaller triangle in the square corner. */
  bed?: number[];
  plants: YardPlant[];
}

/** Kinds of building that keep no front garden: what is not a house or a shop with a door to the street. */
const NO_YARD = new Set<Building['kind']>(['park', 'pitch', 'plaza', 'field', 'parking', 'greatPark', 'pier', 'quay', 'crane', 'containers']);

const YARDS = new WeakMap<World, { key: string; yards: Yard[]; byChunk: Map<number, Yard[]> }>();


/** Every free triangle beside this county's diagonals: front yards, lawns and verges. Kept until the roads or buildings change. */
export function yardsOf(w: World): Yard[] {
  const key = `${w.roadStamp}|${w.revision}|${w.allBuildings.length}`;
  const have = YARDS.get(w);
  if (have && have.key === key) return have.yards;
  const yards: Yard[] = [];
  if (hasDiagonals(w)) {
    // who stands on each tile: the town buildings (a quick index of our own, not the walls')
    const at = new Int32Array(N * N).fill(-1);
    w.allBuildings.forEach((b, k) => {
      // open lots (parks, pitches, fields) are their own ground: only something standing there keeps a yard
      if (b.gone || !b.solid || NO_YARD.has(b.kind)) return;
      for (let z = b.z; z < b.z + b.d; z++) for (let x = b.x; x < b.x + b.w; x++) if (inB(x, z)) at[idx(x, z)] = k;
    });
    for (let t = 0; t < N * N; t++) {
      if (!w.roadDiag[t] || w.deckAxis[t]) continue;
      const f = freeTriangle(w, t);
      if (!f) continue;
      const tx = t % N, tz = Math.floor(t / N);
      // the two tiles across the triangle's square legs (the tile edges that meet at its square corner): whoever stands there owns it
      const legs: { nb: number; d: number }[] = [];
      for (const d of [f.rx === tx ? 2 : 0, f.rz === tz ? 3 : 1]) {
        const nx = tx + (d === 0 ? 1 : d === 2 ? -1 : 0), nz = tz + (d === 1 ? 1 : d === 3 ? -1 : 0);
        if (inB(nx, nz)) legs.push({ nb: idx(nx, nz), d });
      }
      let owner = -1, front = false, side = -1;
      for (const { nb, d } of legs) {
        const k = at[nb];
        if (k < 0) continue;
        const b = w.allBuildings[k];
        const faces = b.facing === ((d + 2) & 3);
        if (owner < 0 || (faces && !front)) { owner = k; front = faces; side = d; }
      }
      const town = w.townId[t] >= 0;
      if (owner < 0 && !town) continue;
      const b = owner >= 0 ? w.allBuildings[owner] : null;
      const lawn = !b || hash2(b.seed & 0xffff, b.uid, 41) < 0.5;
      const y: Yard = { tile: t, poly: f.poly, uid: b ? b.uid : -1, front, lawn, town, plants: [] };
      // the triangle's corners: the square corner and the ends of its two legs
      const ux = tx + 0.5 - f.rx > 0 ? 1 : -1, uz = tz + 0.5 - f.rz > 0 ? 1 : -1;
      const L = Math.min(1, f.leg);
      const ax = f.rx + ux * L, az = f.rz, bx = f.rx, bz = f.rz + uz * L;
      if (b) {
        const salt = b.uid * 7 + t;
        if (lawn) {
          // a path from the door straight out to the road, square off the building's face, on the face toward the road
          if (front && L > 0.55) {
            const along = side % 2 === 0;   // the building is across an x edge: the path runs along x
            const m = 0.5;                  // the middle of the face's tile edge
            const pw = 0.07;
            const reach = L - m;            // how far the triangle reaches out at the middle of its leg
            if (along) {
              const z0 = f.rz + uz * m;
              const x0 = f.rx, x1 = f.rx + ux * Math.max(0.05, reach);
              y.path = [x0, z0 - pw, x1, z0 - pw, x1, z0 + pw, x0, z0 + pw];
            } else {
              const x0 = f.rx + ux * m;
              const z0 = f.rz, z1 = f.rz + uz * Math.max(0.05, reach);
              y.path = [x0 - pw, z0, x0 + pw, z0, x0 + pw, z1, x0 - pw, z1];
            }
          }
          // a clipped shrub either side of the door, in the corner
          if (hash2(salt, 3, 43) < 0.7) y.plants.push({ kind: 'shrub', x: f.rx + ux * 0.14, z: f.rz + uz * 0.14, s: 0.45, yaw: hash2(salt, 4, 44) * 6.28 });
        } else {
          // a garden: a bed along the building, shrubs in it, flowers out toward the road, and a tree if there is room
          const bl = Math.min(0.42, L * 0.45);
          y.bed = [f.rx, f.rz, f.rx + ux * bl, f.rz, f.rx, f.rz + uz * bl];
          y.plants.push({ kind: 'shrub', x: f.rx + ux * 0.12, z: f.rz + uz * 0.28, s: 0.42 + hash2(salt, 5, 45) * 0.15, yaw: hash2(salt, 6, 46) * 6.28 });
          y.plants.push({ kind: 'shrub', x: f.rx + ux * 0.28, z: f.rz + uz * 0.12, s: 0.4 + hash2(salt, 7, 47) * 0.15, yaw: hash2(salt, 8, 48) * 6.28 });
          const tints: [number, number, number][] = [[1, 0.86, 0.22], [1, 0.98, 0.94], [0.72, 0.52, 0.95], [1, 0.6, 0.78], [1, 0.45, 0.4]];
          const tint = tints[Math.floor(hash2(salt, 9, 49) * tints.length) % tints.length];
          for (let q = 0; q < 3; q++) {
            const u = 0.2 + hash2(salt, 10 + q, 50) * 0.5, v = 0.15 + hash2(salt, 20 + q, 51) * 0.3;
            if (u + v > 0.85) continue;
            // a point in the triangle (square corner + u along one leg + v along the other, scaled to its size)
            y.plants.push({ kind: 'tuft', x: f.rx + ux * L * u, z: f.rz + uz * L * v, s: 1 + hash2(salt, 30 + q, 52) * 0.5, yaw: hash2(salt, 40 + q, 53) * 6.28, tint });
          }
          if (L >= 0.7 && hash2(salt, 11, 54) < 0.75) {
            const warm = w.temp[t] > 0.72, cold = w.temp[t] < 0.35;
            const r = hash2(salt, 12, 55);
            const kind: YardPlant['kind'] = warm ? (r < 0.5 ? 'palm' : 'stonePine') : cold ? 'birch' : r < 0.4 ? 'round' : r < 0.75 ? 'oak' : 'poplar';
            // at the triangle's middle: a third of the way out along each leg
            y.plants.push({ kind, x: (f.rx + ax + bx) / 3, z: (f.rz + az + bz) / 3, s: 0.42 + hash2(salt, 13, 56) * 0.12, yaw: hash2(salt, 14, 57) * 6.28 });
          }
        }
      }
      yards.push(y);
    }
  }
  const byChunk = new Map<number, Yard[]>();
  for (const y of yards) {
    const k = Math.floor((y.tile % N) / CHUNK) + Math.floor(Math.floor(y.tile / N) / CHUNK) * 1000;
    let l = byChunk.get(k);
    if (!l) byChunk.set(k, (l = []));
    l.push(y);
  }
  YARDS.set(w, { key, yards, byChunk });
  return yards;
}

/** The yards on one 16-tile chunk. */
export function chunkYards(w: World, cx: number, cz: number): Yard[] {
  yardsOf(w);
  return YARDS.get(w)!.byChunk.get(cx + cz * 1000) ?? [];
}

/** Does a building have a yard on a diagonal (the gates count them)? */
export function yardFor(w: World, uid: number): Yard[] {
  return yardsOf(w).filter((y) => y.uid === uid);
}

// ---------------------------------------------------------------------------------------------
// a 45° staircase between two tiles

/**
 * The tiles of a 45° road from tile a to tile b (|dx| = |dz|, at least two each way), stepping first along
 * `first` (0 x, 1 z): a staircase, alternating one tile across and one up. Null if a and b don't lie on a 45° line.
 */
export function staircase(a: number, b: number, first: 0 | 1): number[] | null {
  const ax = a % N, az = Math.floor(a / N), bx = b % N, bz = Math.floor(b / N);
  const dx = bx - ax, dz = bz - az;
  if (Math.abs(dx) !== Math.abs(dz) || Math.abs(dx) < 2) return null;
  const sx = Math.sign(dx), sz = Math.sign(dz);
  const out = [a];
  let x = ax, z = az;
  for (let k = 0; k < 2 * Math.abs(dx); k++) {
    if ((k % 2 === 0) === (first === 0)) x += sx; else z += sz;
    out.push(idx(x, z));
  }
  return out;
}
