import {
  N, SEA, CHUNK, CHUNKS, Biome, Feature, Flag, RoadType, Surface, DIRS, EDGE_MINE, EDGE_THEIRS, idx, inB, type World,
} from './tiles';

/**
 * Earthworks (docs/terrain.html): the rules for moving the ground and the water after an island is
 * generated. Pure and headless — no renderer, no DOM, no wallet — so the gate can hammer it.
 *
 * The unit is the lift: one corner of one tile moved one step. A plan works out every corner and every
 * water level a step would change, what that costs, and whether it is allowed; commit writes it into
 * the world and into the island's overlay, the running difference from what the generator made, which
 * is all the save keeps (see landCodec.ts).
 */
export const LAND = {
  /** Dollars a lift, in ordinary ground. */
  lift: 2,
  /** Multipliers by what the ground is made of. */
  soft: 1, ice: 2, rock: 3,
  /** A tile under water before or after the step: dredging and reclaiming. The larger of this and the ground's applies. */
  wet: 2.5,
  /** Dollars a tile a step of water level, for the water tool. */
  water: 3,
  /** Highest and lowest a corner may go, in steps. The floor is the sea bed every cell's rim is forced to. */
  ceiling: 26,
  floor: SEA - 5,
  /** Most tiles one smooth step may ripple through before it is refused rather than bankrupting anyone. */
  ripple: 600,
  /** Strokes Z can take back. */
  undo: 32,
};

export type Style = 'cliff' | 'smooth';

/**
 * The highest a corner may be raised on this county: the ordinary ceiling, or eight steps over the
 * county's own highest ground where big country stands taller. An island stays under the old roof; a
 * county with a ninety-step range in it may be built up to nearly its peaks.
 */
function ceilingOf(w: World): number {
  return Math.min(120, Math.max(LAND.ceiling, w.peak + 8));
}

/** What a stroke acts on: whole tiles, or — at brush 1 — one corner (0–3) of one tile. */
export interface Selection { tiles: number[]; corner?: number }

export interface Plan {
  ok: boolean;
  /** Why nothing happens, when `ok` is false or nothing moved. */
  reason: string | null;
  /** New corner values, by corner index (tile × 4 + q). */
  corners: Map<number, number>;
  /** New water levels, by tile. */
  water: Map<number, number>;
  /** New ground class, by tile: sea bed brought above water becomes beach. */
  biome: Map<number, number>;
  /** Every tile whose corners or water change. */
  tiles: number[];
  lifts: number;
  cost: number;
  /** Selected tiles that sat the step out, and why the first of them did. */
  refused: number[];
  /** Edges where water would stand against nothing, as tile × 4 + direction: the reason for refusing. */
  leaks: number[];
  /** Tiles the step flooded as a consequence (letting water in, or ground dug below the sea). */
  flooded: number;
  /** Tiles the step dried out. */
  dried: number;
  /** Sea tiles made dry land, and dry tiles opened to the sea. */
  reclaimed: number;
  opened: number;
}

// ---------------------------------------------------------------------------------------------
// what won't move

const enum Fix { Free = 0, Building = 1, Town = 2, Harbour = 3, Rail = 4, Bridge = 5, Road = 6, Works = 7, Border = 8, Wide = 9, Pad = 10 }

const FIX_REASON: Record<number, string> = {
  [Fix.Building]: 'A building stands here: bulldoze it first (X)',
  [Fix.Town]: 'Town land: make the town your territory to grade it',
  [Fix.Pad]: 'A building stood here: its pad stays as it was',
  [Fix.Harbour]: 'The harbour needs its water',
  [Fix.Rail]: 'The railway is in the way',
  [Fix.Bridge]: 'A bridge lands here',
  [Fix.Road]: 'A road is in the way — smooth style can ease it',
  [Fix.Works]: 'The works are in the way',
  [Fix.Border]: 'Too near the county line',
  [Fix.Wide]: 'A four-lane road is in the way',
};

/** How far out to sea from a harbour's pier root its approach is kept, and how wide either side. */
const HARBOUR_REACH = 14;
const HARBOUR_HALF = 5;

/**
 * Towns whose land the player may grade, by town id: the ones their fleet holds as territory. Their
 * open ground then moves like the country's; their buildings, roads and everything else stay guarded.
 */
export type TownGate = (town: number) => boolean;

interface Masks {
  stamp: string;
  /** Every town tile not under a building is Town. */
  mask: Uint8Array;
  /** The same with town land left out: what a held town's tile answers to. */
  bare: Uint8Array;
}

const fixCache = new WeakMap<World, Masks>();

/**
 * Why each tile of an island can't be dug, or 0. Anything whose height is stored rather than read
 * from the ground when it is drawn — buildings, harbours, rails, bridge decks, works — would float or
 * drown, so it is refused. Cached against the island's revision and its roads.
 */
export function fixedMask(w: World): Uint8Array {
  return masks(w).mask;
}

function masks(w: World): Masks {
  const stamp = `${w.revision}:${w.roadStamp}:${w.roads.length}`;
  const have = fixCache.get(w);
  if (have && have.stamp === stamp) return have;
  const m = new Uint8Array(N * N);
  const set = (i: number, f: Fix) => { if (!m[i] || f < m[i]) m[i] = f; };
  const foot = (b: { x: number; z: number; w: number; d: number; gone?: boolean }, f: Fix) => {
    if (b.gone) return;
    for (let z = b.z; z < b.z + b.d; z++) for (let x = b.x; x < b.x + b.w; x++) if (inB(x, z)) set(idx(x, z), f);
  };
  // ground a bulldozed building left: a claimed lot keeps its Poi flag after it comes down (demolish.ts)
  const razed = new Uint8Array(N * N);
  for (const b of w.allBuildings) {
    if (b.gone) for (let z = b.z; z < b.z + b.d; z++) for (let x = b.x; x < b.x + b.w; x++) if (inB(x, z)) razed[idx(x, z)] = 1;
  }
  for (let i = 0; i < N * N; i++) {
    if (w.blocked[i] || (w.flags[i] & Flag.Poi && !razed[i])) set(i, Fix.Building);
    else if (w.portId[i] >= 0) set(i, Fix.Harbour);
    else if (w.rail[i]) set(i, Fix.Rail);
    else if (w.deckAxis[i]) set(i, Fix.Bridge);
    else if (w.feature[i] === Feature.Quarry || w.feature[i] === Feature.Piste || w.feature[i] === Feature.Airfield) set(i, Fix.Works);
    else if (w.road[i] === RoadType.FourLane || w.road[i] === RoadType.Interstate) set(i, Fix.Wide);
    else if (w.road[i]) set(i, Fix.Road);
  }
  for (const b of w.allBuildings) foot(b, Fix.Building);
  for (const b of w.countryside) foot(b, Fix.Building);
  for (const wk of w.works) for (const b of wk.buildings) foot(b, Fix.Works);
  for (const s of w.stations) if (s.building) foot(s.building, Fix.Rail);
  // a harbour's approach: the water its ships come in on
  for (const p of w.ports) {
    const x0 = p.root % N, z0 = (p.root - x0) / N;
    const [fx, fz] = DIRS[p.dir];
    for (let k = 0; k <= HARBOUR_REACH; k++) {
      for (let s = -HARBOUR_HALF; s <= HARBOUR_HALF; s++) {
        const x = x0 + fx * k - fz * s, z = z0 + fz * k + fx * s;
        if (inB(x, z)) set(idx(x, z), Fix.Harbour);
      }
    }
  }
  // a bridge or tunnel's abutments want dead-level ground, and so does the tile beyond them
  for (const r of w.roads) {
    if (!r.bridges?.length || r.type === RoadType.FourLane || r.type === RoadType.Interstate) continue;
    for (const br of r.bridges) {
      for (const n of [r.nodes[br.from], r.nodes[br.to]]) {
        if (n === undefined) continue;
        const x = n % N, z = (n - x) / N;
        for (let dz = -1; dz <= 1; dz++) for (let dx = -1; dx <= 1; dx++) if (inB(x + dx, z + dz)) set(idx(x + dx, z + dz), Fix.Bridge);
      }
    }
  }
  // a building a town or a fleet put up since generation cut its pad from the ground under it, and a save
  // replays that cut after the earthworks (delta.ts applyDelta): its footprint stays put once it is gone
  for (const b of w.allBuildings) {
    if (!b.gone || b.grownAt === undefined) continue;
    for (let z = b.z; z < b.z + b.d; z++) for (let x = b.x; x < b.x + b.w; x++) if (inB(x, z)) set(idx(x, z), Fix.Pad);
  }
  // the outermost ring: the other half of those vertices lives in a neighbour's save. Bare ground and roads there
  // move only with that neighbour in memory (Opts.edges); a railway, a building, a harbour or works there stay held
  // for what they are (the user, 6 Nov 2026: since earthworks carry over the line, the ring's own mark let ground
  // under a track on the line be moved, which a track's stored heights can't follow)
  for (let k = 0; k < N; k++) for (const i of [idx(0, k), idx(N - 1, k), idx(k, 0), idx(k, N - 1)]) if (!m[i] || m[i] === Fix.Road) m[i] = Fix.Border;
  // town land: the town grades its own, unless it is the player's territory
  const town = m.slice();
  for (let i = 0; i < N * N; i++) if (w.townId[i] >= 0 && m[i] !== Fix.Building && m[i] !== Fix.Border) town[i] = Fix.Town;
  const out = { stamp, mask: town, bare: m };
  fixCache.set(w, out);
  return out;
}

/** What holds a tile still (0 for nothing): a held town's tile answers for what is on it, not for being town land. */
function fixOf(ms: Masks, w: World, i: number, towns?: TownGate): number {
  const f = ms.mask[i];
  return f === Fix.Town && towns?.(w.townId[i]) ? ms.bare[i] : f;
}

/** Why a tile can't be dug in this style, or null. Roads give way to smooth work only. */
export function landProblem(w: World, i: number, style: Style = 'cliff', towns?: TownGate): string | null {
  const f = fixOf(masks(w), w, i, towns);
  if (!f) return null;
  if (f === Fix.Road && style === 'smooth') return null;
  return FIX_REASON[f];
}

// ---------------------------------------------------------------------------------------------
// prices

/** What the ground on a tile is made of, as a price multiplier. */
export function groundRate(w: World, i: number): number {
  const b = w.biome[i], s = w.surface[i];
  if (b === Biome.Mountain || b === Biome.Snow || b === Biome.Canyon || b === Biome.SeaCliff || b === Biome.Lava
    || s === Surface.Rock || s === Surface.Basalt || s === Surface.Lava || s === Surface.Cave) return LAND.rock;
  if (b === Biome.Ice || s === Surface.Ice) return LAND.ice;
  return LAND.soft;
}

// ---------------------------------------------------------------------------------------------
// the overlay: how far each corner and each water level now stands from the generator's

/**
 * The overlay: corner and water differences, the chunks holding any, and the tiles that were sea bed
 * brought out of the water — drawn as beach while dry, and sea again if they are ever dug back under.
 * Ground class is a pure function of the ground, so a reload gets it right from the differences alone.
 */
interface Overlay { c: Int8Array; wt: Int8Array; chunks: Set<number>; sea: Set<number> }
const overlays = new WeakMap<World, Overlay>();

export function overlayOf(w: World, make = false): Overlay | null {
  let o = overlays.get(w);
  if (!o && make) overlays.set(w, (o = { c: new Int8Array(N * N * 4), wt: new Int8Array(N * N), chunks: new Set(), sea: new Set() }));
  return o ?? null;
}

const chunkOf = (i: number): number => {
  const x = i % N, z = (i - x) / N;
  return Math.floor(z / CHUNK) * CHUNKS + Math.floor(x / CHUNK);
};

// ---------------------------------------------------------------------------------------------
// planning

/** The other tile-corners that share a vertex with corner c, in the same cell. */
function partners(c: number, out: number[]): number[] {
  out.length = 0;
  const i = c >> 2, q = c & 3;
  const x = i % N, z = (i - x) / N;
  // the vertex this corner sits on
  const vx = x + (q === 1 || q === 2 ? 1 : 0), vz = z + (q === 2 || q === 3 ? 1 : 0);
  // tiles round a vertex, with the corner of each that sits on it
  const round: [number, number, number][] = [[vx - 1, vz - 1, 2], [vx, vz - 1, 3], [vx - 1, vz, 1], [vx, vz, 0]];
  for (const [tx, tz, tq] of round) {
    if (!inB(tx, tz)) continue;
    const k = idx(tx, tz) * 4 + tq;
    if (k !== c) out.push(k);
  }
  return out;
}

interface Opts {
  style: Style;
  /** Tiles with a vehicle on them: they sit the step out. */
  occupied?: Set<number>;
  /** Towns whose open ground the player may grade (their territory). */
  towns?: TownGate;
  /**
   * Whether a tile of the outermost ring may move: the county over that line is in memory, and the tool carries the
   * step over it (game/landTool.ts carry, acrossEdge, planPinned). Without it the ring holds still, as it always did.
   */
  edges?: (i: number) => boolean;
}

/** May this tile move in this style? Free ground; a road, for smooth work; the outer ring, where `edges` opens it. */
function movableIn(ms: Masks, w: World, i: number, opts: Opts): boolean {
  if (opts.occupied?.has(i)) return false;
  const f = fixOf(ms, w, i, opts.towns);
  if (f === Fix.Border) return !!opts.edges?.(i);
  return f === Fix.Free || (f === Fix.Road && opts.style === 'smooth');
}

/**
 * A corner on a county's edge as the neighbouring counties have it (the user, 5 Nov 2026): the vertex it sits on is
 * shared with the county over the line (two at a county's corner, three at its vertex), each listed as [dx, dz, that
 * county's corner]. Empty for a corner inside the county.
 */
export function acrossEdge(k: number): [number, number, number][] {
  const i = k >> 2, q = k & 3;
  const x = i % N, z = (i - x) / N;
  const vx = x + (q === 1 || q === 2 ? 1 : 0), vz = z + (q === 2 || q === 3 ? 1 : 0);
  if (vx > 0 && vx < N && vz > 0 && vz < N) return [];
  const out: [number, number, number][] = [];
  for (let dz = -1; dz <= 1; dz++) for (let dx = -1; dx <= 1; dx++) {
    if (!dx && !dz) continue;
    const bx = vx - dx * N, bz = vz - dz * N;
    if (bx < 0 || bx > N || bz < 0 || bz > N) continue;
    for (const [tx, tz, tq] of [[bx - 1, bz - 1, 2], [bx, bz - 1, 3], [bx - 1, bz, 1], [bx, bz, 0]] as const) {
      if (inB(tx, tz)) out.push([dx, dz, idx(tx, tz) * 4 + tq]);
    }
  }
  return out;
}

/**
 * The ripple of a step (planLand, planPinned): from the corners in `queue`, keep every tile a legal shape (adjacent
 * corners within a step, the diagonal within two) and, in smooth style, joined vertices joined. Writes into `nv`;
 * the reason it can't, or null.
 */
function ripple(w: World, nv: Map<number, number>, pinned: Set<number>, canTile: (i: number) => boolean, style: Style, touched: Set<number>): string | null {
  const c = w.corners;
  const val = (k: number): number => nv.get(k) ?? c[k];
  const moveDir = new Map<number, number>();
  for (const [k, v] of nv) moveDir.set(k, Math.sign(v - c[k]));
  const queue = [...nv.keys()];
  const buf: number[] = [];
  const nudge = (k: number, lo: number, hi: number): boolean => {
    if (pinned.has(k)) return true;
    const i = k >> 2;
    if (!canTile(i)) return true;
    const v = val(k);
    const want = Math.max(lo, Math.min(hi, v));
    if (want === v) return true;
    const d = Math.sign(want - c[k]);
    const was = moveDir.get(k);
    // a corner never turns back: if two pulls disagree, the step is not one the ground can take
    if (was !== undefined && was !== 0 && d !== 0 && d !== was) return false;
    if (want === c[k]) nv.delete(k); else nv.set(k, want);
    moveDir.set(k, d);
    touched.add(i);
    queue.push(k);
    return true;
  };
  let guard = 0;
  for (let head = 0; head < queue.length; head++) {
    if (++guard > 200000 || touched.size > LAND.ripple) return 'Too big a job for one step: use a smaller brush';
    const k = queue[head];
    const h = val(k);
    const i = k >> 2, q = k & 3;
    for (let q2 = 0; q2 < 4; q2++) {
      if (q2 === q) continue;
      const lim = (q2 - q + 4) % 4 === 2 ? 2 : 1;
      if (!nudge(i * 4 + q2, h - lim, h + lim)) return 'The ground can’t take that shape';
    }
    if (style === 'smooth') {
      for (const k2 of partners(k, buf)) {
        if (c[k2] !== c[k]) continue; // a step here already: a cliff stays a cliff
        if (!nudge(k2, h, h)) return 'The ground can’t take that shape';
      }
    }
  }
  return null;
}

/** A step's corners priced, its water settled and checked: the plan as planLand and planPinned give it. */
function finishPlan(w: World, nv: Map<number, number>, refused: number[]): Plan {
  const c = w.corners;
  const p = emptyPlan(null);
  p.refused = refused;
  p.corners = nv;
  const tiles = new Set<number>();
  for (const k of nv.keys()) tiles.add(k >> 2);
  for (const [k, v] of nv) {
    const i = k >> 2;
    const lifts = Math.abs(v - c[k]);
    p.lifts += lifts;
    const wet = w.water[i] >= 0;
    p.cost += lifts * LAND.lift * Math.max(groundRate(w, i), wet ? LAND.wet : 1);
  }
  settleWater(w, p, tiles);
  // wet after the step and dry before: reclaiming charges at the wet rate too
  for (const [k, v] of nv) {
    const i = k >> 2;
    if (w.water[i] < 0 && (p.water.get(i) ?? -1) >= 0) {
      const lifts = Math.abs(v - c[k]);
      p.cost += lifts * LAND.lift * (Math.max(groundRate(w, i), LAND.wet) - groundRate(w, i));
    }
  }
  p.cost = Math.round(p.cost);
  p.tiles = [...tiles];
  // a road the smooth style eased must still be a road afterwards
  const broken = roadBroken(w, p);
  if (broken) return { ...emptyPlan(broken), refused };
  p.ok = p.leaks.length === 0;
  if (!p.ok) p.reason = 'Water would stand against nothing';
  return p;
}

/**
 * A step carried over a county line (game/landTool.ts carry): the corners on the line go to the heights the county
 * over it gave them (`pins`), and the ripple follows on from them here as a step of its own would. Every corner on
 * the line with the county at (fromDx, fromDz) is held where it is or where it is pinned, so the step never runs back.
 */
export function planPinned(w: World, pins: Map<number, number>, fromDx: number, fromDz: number, opts: Opts): Plan {
  const ms = masks(w);
  const nv = new Map<number, number>();
  const pinned = new Set<number>();
  for (const [k, v] of pins) { pinned.add(k); if (w.corners[k] !== v) nv.set(k, v); }
  if (!nv.size) return emptyPlan('Already there');
  // the line it came over holds still: its corners are the other county's too
  for (let k0 = 0; k0 < N; k0++) for (const i of [idx(0, k0), idx(N - 1, k0), idx(k0, 0), idx(k0, N - 1)]) {
    for (let q = 0; q < 4; q++) {
      const k = i * 4 + q;
      if (!pinned.has(k) && acrossEdge(k).some(([dx, dz]) => dx === fromDx && dz === fromDz)) pinned.add(k);
    }
  }
  const pinTiles = new Set([...pins.keys()].map((k) => k >> 2));
  // a pinned corner on a tile held for what is on it (a track, a building, a harbour) can't follow: the carry is
  // refused, and the line stays a cliff, as when the ground there can't take it
  for (const i of pinTiles) if (!movableIn(ms, w, i, { ...opts, edges: () => true })) return emptyPlan(FIX_REASON[fixOf(ms, w, i, opts.towns)] ?? 'Held still');
  const canTile = (i: number) => (opts.style === 'cliff' ? pinTiles.has(i) : movableIn(ms, w, i, opts));
  const why = ripple(w, nv, pinned, canTile, opts.style, new Set(pinTiles));
  if (why) return emptyPlan(why);
  return finishPlan(w, nv, []);
}

function emptyPlan(reason: string | null): Plan {
  return {
    ok: false, reason, corners: new Map(), water: new Map(), biome: new Map(), tiles: [], lifts: 0, cost: 0,
    refused: [], leaks: [], flooded: 0, dried: 0, reclaimed: 0, opened: 0,
  };
}

/**
 * One step of the land tool: `dir` +1 raises, −1 lowers. The selected corners go to one step past the
 * lowest (or highest) of them, which levels a rough patch before it lifts it, as RollerCoaster Tycoon 2's
 * tool did. `level` instead brings every selected corner to that height at once (the Shift drag).
 */
export function planLand(w: World, sel: Selection, dir: 1 | -1 | 0, opts: Opts, level = 0): Plan {
  const { style } = opts;
  const refused: number[] = [];
  let why: string | null = null;
  const ms = masks(w);
  const movable = (i: number): boolean => movableIn(ms, w, i, opts);
  const selTiles = new Set<number>();
  for (const i of sel.tiles) {
    if (movable(i)) selTiles.add(i);
    else {
      refused.push(i);
      why ??= opts.occupied?.has(i) ? 'Move the vehicle first' : landProblem(w, i, style, opts.towns);
    }
  }
  if (!selTiles.size) { const p = emptyPlan(why ?? 'Nothing to move'); p.refused = refused; return p; }

  const c = w.corners;
  const nv = new Map<number, number>();
  const val = (k: number): number => nv.get(k) ?? c[k];
  const pinned = new Set<number>();
  const seed: number[] = [];
  for (const i of selTiles) {
    if (sel.corner !== undefined && sel.tiles.length === 1) seed.push(i * 4 + sel.corner);
    else for (let q = 0; q < 4; q++) seed.push(i * 4 + q);
  }
  // where the selected corners go
  if (dir === 0) {
    const t = Math.max(LAND.floor, Math.min(ceilingOf(w), level));
    for (const k of seed) { pinned.add(k); if (c[k] !== t) nv.set(k, t); }
  } else {
    let lo = Infinity, hi = -Infinity;
    for (const k of seed) { lo = Math.min(lo, c[k]); hi = Math.max(hi, c[k]); }
    const t = dir > 0 ? lo + 1 : hi - 1;
    if (dir > 0 && t > ceilingOf(w)) { const p = emptyPlan('As high as the ground goes'); p.refused = refused; return p; }
    if (dir < 0 && t < LAND.floor) { const p = emptyPlan('As deep as it can be dug'); p.refused = refused; return p; }
    for (const k of seed) {
      pinned.add(k);
      if (dir > 0 ? c[k] < t : c[k] > t) nv.set(k, t);
    }
  }
  if (!nv.size) { const p = emptyPlan('Already there'); p.refused = refused; return p; }

  // the ripple: keep every tile a legal shape — adjacent corners within a step, the diagonal within
  // two — and, in smooth style, keep joined vertices joined. Cliff style only reshapes the selected tiles.
  const canTile = (i: number) => (style === 'cliff' ? selTiles.has(i) : movable(i));
  const why2 = ripple(w, nv, pinned, canTile, style, new Set<number>(selTiles));
  if (why2) { const p = emptyPlan(why2); p.refused = refused; return p; }
  return finishPlan(w, nv, refused);
}

/**
 * The water tool: `dir` +1 fills a step, −1 drains a step. The selected tiles go to one common level,
 * lowest first. The sea is nobody's: its level never moves, and nothing may be drained below it.
 */
export function planWater(w: World, sel: Selection, dir: 1 | -1, opts: Omit<Opts, 'style'>): Plan {
  const refused: number[] = [];
  let why: string | null = null;
  const pick: number[] = [];
  for (const i of sel.tiles) {
    const problem = opts.occupied?.has(i) ? 'Move the vehicle first' : landProblem(w, i, 'cliff', opts.towns);
    if (problem) { refused.push(i); why ??= problem; continue; }
    if (w.water[i] === SEA) { refused.push(i); why ??= 'That’s the sea. Raise the land instead'; continue; }
    pick.push(i);
  }
  if (!pick.length) { const p = emptyPlan(why ?? 'Nothing to fill'); p.refused = refused; return p; }
  const mc = (i: number) => minC(w.corners, i);
  const lvl = (i: number) => (w.water[i] >= 0 ? w.water[i] : mc(i));
  let lo = Infinity, hi = -Infinity;
  for (const i of pick) { lo = Math.min(lo, lvl(i)); hi = Math.max(hi, lvl(i)); }
  const t = dir > 0 ? lo + 1 : hi - 1;
  if (t > ceilingOf(w)) { const p = emptyPlan('As high as water goes'); p.refused = refused; return p; }
  const p = emptyPlan(null);
  p.refused = refused;
  let steps = 0;
  for (const i of pick) {
    const l = lvl(i);
    if (dir > 0 ? l >= t : l <= t) continue;
    const m = mc(i);
    const nw = t > m ? t : -1;
    // below the sea is the sea's: a pond can't be drained under it, nor filled to a level under it
    if ((nw >= 0 && nw < SEA) || (nw < 0 && m < SEA)) { refused.push(i); p.reason ??= 'Not below the sea'; continue; }
    if (nw === w.water[i]) continue;
    p.water.set(i, nw);
    seaBed(w, p, i, w.water[i], nw);
    steps += Math.abs((nw >= 0 ? nw : m) - l);
    if (nw >= 0 && w.water[i] < 0) p.flooded++;
    if (nw < 0 && w.water[i] >= 0) p.dried++;
  }
  if (!p.water.size) { p.reason ??= dir > 0 ? 'Already full' : 'Already dry'; return p; }
  p.tiles = [...p.water.keys()];
  p.cost = Math.round(steps * LAND.water);
  p.leaks = newLeaks(w, p, new Set(p.tiles));
  p.ok = p.leaks.length === 0;
  if (!p.ok) p.reason = 'Water would stand against nothing: bank it first';
  p.reason ??= null;
  return p;
}

const minC = (c: Int8Array, i: number): number => Math.min(c[i * 4], c[i * 4 + 1], c[i * 4 + 2], c[i * 4 + 3]);

/**
 * What the water does after a land step: a tile raised to its own water level dries out (and sea bed
 * brought out of the sea becomes beach); a dry tile dug below the sea fills with it, because the sea
 * plane is under the whole world anyway; a dry tile opened onto a lake takes the lake's level, if it
 * can hold it. Then no edge may be left with water standing against nothing that wasn't before.
 */
function settleWater(w: World, p: Plan, tiles: Set<number>): void {
  const nc = (k: number) => p.corners.get(k) ?? w.corners[k];
  const mc = (i: number) => Math.min(nc(i * 4), nc(i * 4 + 1), nc(i * 4 + 2), nc(i * 4 + 3));
  const wl = (i: number) => p.water.get(i) ?? w.water[i];
  for (const i of tiles) {
    const m = mc(i);
    const was = w.water[i];
    let now = was;
    if (now >= 0 && m >= now) now = -1;
    if (now < 0 && m < SEA) now = SEA;
    if (now !== was) p.water.set(i, now);
  }
  // letting water in: a dug tile beside a lake whose bank it has taken away takes the lake's level
  for (let pass = 0; pass < 8; pass++) {
    let grew = false;
    for (const i of tiles) {
      if (wl(i) >= 0) continue;
      const x = i % N, z = (i - x) / N;
      let fill = -1;
      for (let d = 0; d < 4; d++) {
        const nx = x + DIRS[d][0], nz = z + DIRS[d][1];
        if (!inB(nx, nz)) continue;
        const j = idx(nx, nz);
        const L = wl(j);
        if (L < 0) continue;
        if (bankAt(p, w, j, (d + 2) % 4) < L) fill = Math.max(fill, L);
      }
      if (fill > mc(i)) { p.water.set(i, fill); grew = true; }
    }
    if (!grew) break;
  }
  for (const [i, v] of p.water) {
    const was = w.water[i];
    if (v === was) { p.water.delete(i); continue; }
    tiles.add(i);
    if (v >= 0 && was < 0) { p.flooded++; if (v === SEA) p.opened++; }
    if (v < 0 && was >= 0) p.dried++;
    seaBed(w, p, i, was, v);
  }
  p.leaks = newLeaks(w, p, tiles);
}

/**
 * Ground class follows the water: sea bed brought out of it is beach, and beach that was sea bed goes
 * back to sea when it is flooded again — whichever tool did it — so a reload, which only knows the
 * differences, always agrees with play.
 */
function seaBed(w: World, p: Plan, i: number, was: number, now: number): void {
  if (now < 0 && was >= 0 && w.biome[i] === Biome.Ocean) { p.biome.set(i, Biome.Beach); p.reclaimed++; }
  if (now >= 0 && was < 0 && overlayOf(w)?.sea.has(i)) p.biome.set(i, Biome.Ocean);
}

/**
 * The height water on tile i can stand to across its edge d: the lower of the two shared vertices,
 * each taken at the higher of the two tiles' own corners there. Planned values where the plan has them.
 */
function bankAt(p: Plan | null, w: World, i: number, d: number): number {
  const x = i % N, z = (i - x) / N;
  const nx = x + DIRS[d][0], nz = z + DIRS[d][1];
  const j = idx(nx, nz);
  const v = (k: number) => p?.corners.get(k) ?? w.corners[k];
  const m = EDGE_MINE[d], t = EDGE_THEIRS[d];
  return Math.min(Math.max(v(i * 4 + m[0]), v(j * 4 + t[0])), Math.max(v(i * 4 + m[1]), v(j * 4 + t[1])));
}

/** Leak edges (tile × 4 + direction) round these tiles, before (p null) or after the plan. */
function leaksAround(w: World, p: Plan | null, tiles: Set<number>): Set<number> {
  const wl = (i: number) => (p?.water.get(i) ?? w.water[i]);
  const region = new Set<number>();
  for (const i of tiles) {
    region.add(i);
    const x = i % N, z = (i - x) / N;
    for (let d = 0; d < 4; d++) if (inB(x + DIRS[d][0], z + DIRS[d][1])) region.add(idx(x + DIRS[d][0], z + DIRS[d][1]));
  }
  const out = new Set<number>();
  for (const i of region) {
    const L = wl(i);
    if (L < 0) continue;
    const x = i % N, z = (i - x) / N;
    for (let d = 0; d < 4; d++) {
      const nx = x + DIRS[d][0], nz = z + DIRS[d][1];
      if (!inB(nx, nz)) continue;
      const j = idx(nx, nz);
      if (wl(j) >= 0) continue; // two waters: a waterfall where they differ, drawn already
      if (bankAt(p, w, i, d) < L) out.add(i * 4 + d);
    }
  }
  return out;
}

function newLeaks(w: World, p: Plan, tiles: Set<number>): number[] {
  const before = leaksAround(w, null, tiles);
  const after = leaksAround(w, p, tiles);
  const out: number[] = [];
  for (const e of after) if (!before.has(e)) out.push(e);
  return out;
}

/** Every leak on an island, the generator's own included: for the console. */
export function allLeaks(w: World): number[] {
  const all = new Set<number>();
  for (let i = 0; i < N * N; i++) all.add(i);
  return [...leaksAround(w, null, all)];
}

/** A road tile the plan would leave too steep, too wet or with a step across its line, or null if none. */
function roadBroken(w: World, p: Plan): string | null {
  const nc = (k: number) => p.corners.get(k) ?? w.corners[k];
  const ok = (useP: boolean, i: number): boolean => {
    const v = (k: number) => (useP ? nc(k) : w.corners[k]);
    const cs = [v(i * 4), v(i * 4 + 1), v(i * 4 + 2), v(i * 4 + 3)];
    if (Math.max(...cs) - Math.min(...cs) > 1) return false;
    const L = useP ? (p.water.get(i) ?? w.water[i]) : w.water[i];
    if (L >= 0 && L - Math.min(...cs) > 1) return false;
    const x = i % N, z = (i - x) / N;
    for (let d = 0; d < 4; d++) {
      if (!(w.roadEdges[i] & (1 << d))) continue;
      const nx = x + DIRS[d][0], nz = z + DIRS[d][1];
      if (!inB(nx, nz)) continue;
      const j = idx(nx, nz);
      const m = EDGE_MINE[d], t = EDGE_THEIRS[d];
      if (v(i * 4 + m[0]) !== v(j * 4 + t[0]) || v(i * 4 + m[1]) !== v(j * 4 + t[1])) return false;
    }
    return true;
  };
  const check = new Set<number>();
  for (const i of p.tiles) {
    check.add(i);
    const x = i % N, z = (i - x) / N;
    for (let d = 0; d < 4; d++) if (inB(x + DIRS[d][0], z + DIRS[d][1])) check.add(idx(x + DIRS[d][0], z + DIRS[d][1]));
  }
  for (const i of check) if (w.road[i] && ok(false, i) && !ok(true, i)) return 'The road would be broken: ease it with a bigger brush';
  return null;
}

// ---------------------------------------------------------------------------------------------
// committing and taking back

/** What a stroke changed, as the values before it: enough to put everything back. */
export interface Undo { corners: Map<number, number>; water: Map<number, number>; biome: Map<number, number> }
export const emptyUndo = (): Undo => ({ corners: new Map(), water: new Map(), biome: new Map() });

/** Write a plan into the island and its overlay, remembering the old values in `undo` (first write wins). */
export function commitPlan(w: World, p: Plan, undo: Undo): void {
  const o = overlayOf(w, true)!;
  for (const [k, v] of p.corners) {
    if (!undo.corners.has(k)) undo.corners.set(k, w.corners[k]);
    o.c[k] += v - w.corners[k];
    w.corners[k] = v;
    o.chunks.add(chunkOf(k >> 2));
  }
  for (const [i, v] of p.water) {
    if (!undo.water.has(i)) undo.water.set(i, w.water[i]);
    o.wt[i] += v - w.water[i];
    w.water[i] = v;
    o.chunks.add(chunkOf(i));
  }
  for (const [i, v] of p.biome) {
    if (!undo.biome.has(i)) undo.biome.set(i, w.biome[i]);
    if (v === Biome.Beach && w.biome[i] === Biome.Ocean) o.sea.add(i);
    if (v === Biome.Ocean) o.sea.delete(i);
    w.biome[i] = v;
  }
}

/**
 * Write a set of corner heights into the island and its overlay, as a stroke of the land tool would, with
 * the old values in `undo`: a road the builder cut down a ledge (world/roadGrade.ts).
 */
export function commitCorners(w: World, corners: Map<number, number>, undo: Undo): void {
  const o = overlayOf(w, true)!;
  for (const [k, v] of corners) {
    if (!undo.corners.has(k)) undo.corners.set(k, w.corners[k]);
    o.c[k] += v - w.corners[k];
    w.corners[k] = v;
    o.chunks.add(chunkOf(k >> 2));
  }
}

/** Put a stroke back. Returns the tiles it touched. */
export function revert(w: World, u: Undo): number[] {
  const o = overlayOf(w, true)!;
  const tiles = new Set<number>();
  for (const [k, v] of u.corners) { o.c[k] += v - w.corners[k]; w.corners[k] = v; tiles.add(k >> 2); }
  for (const [i, v] of u.water) { o.wt[i] += v - w.water[i]; w.water[i] = v; tiles.add(i); }
  for (const [i, v] of u.biome) {
    if (v === Biome.Ocean) o.sea.delete(i);
    else if (w.biome[i] === Biome.Ocean) o.sea.add(i);
    w.biome[i] = v;
    tiles.add(i);
  }
  return [...tiles];
}
