/**
 * The brooks (world/brooks.ts) drawn per chunk: a thin ribbon of water draped over the ground, in the
 * chunk's own water mesh so it shares the water's material, freezes with the shallows in winter and
 * costs no draw of its own; and, where the ground steps down under it, a little fall in the chunk's
 * fall mesh (the same scrolling sheet and foam the rivers' falls use). A brook passes under a road or a
 * railway in a culvert, and is not drawn where it has reached open water.
 */
import { N, CHUNK, RailBit, World, heightAt, idx, inB } from '../world/tiles';
import { C, mix, type RGB } from '../world/biomes';
import { brooksOf } from '../world/brooks';

/** What the chunk builders in mesher.ts offer: a triangle with colours and one extra channel. */
interface Tris {
  tri(ax: number, ay: number, az: number, bx: number, by: number, bz: number, cx: number, cy: number, cz: number, ca: RGB, cb: RGB, cc: RGB, e?: number): void;
}

/** A brook resampled every SPACING tiles, with the ribbon's half-width and sideways normal at each sample. */
interface Dense { x: Float32Array; z: Float32Array; nx: Float32Array; nz: Float32Array; half: Float32Array; x0: number; z0: number; x1: number; z1: number }
const SPACING = 0.25;
/** How far above the ground the ribbon floats, so it never sinks into a fold of the terrain. */
const LIFT = 0.045;
/** A rise this sudden between two samples is a step the brook pours over, not a slope it runs down. */
const STEP_Y = 0.2;

const cache = new WeakMap<World, { src: Float32Array[]; dense: Dense[] }>();

function denseOf(w: World): Dense[] {
  const src = brooksOf(w);
  const hit = cache.get(w);
  if (hit && hit.src === src) return hit.dense;
  const dense: Dense[] = [];
  for (const b of src) {
    const n = b.length / 2;
    if (n < 2) continue;
    const xs: number[] = [], zs: number[] = [];
    let total = 0;
    for (let k = 0; k + 1 < n; k++) total += Math.hypot(b[k * 2 + 2] - b[k * 2], b[k * 2 + 3] - b[k * 2 + 1]);
    for (let k = 0; k + 1 < n; k++) {
      const ax = b[k * 2], az = b[k * 2 + 1], bx = b[k * 2 + 2], bz = b[k * 2 + 3];
      const L = Math.hypot(bx - ax, bz - az), m = Math.max(1, Math.round(L / SPACING));
      for (let q = 0; q < m; q++) { xs.push(ax + ((bx - ax) * q) / m); zs.push(az + ((bz - az) * q) / m); }
    }
    xs.push(b[(n - 1) * 2]); zs.push(b[(n - 1) * 2 + 1]);
    const M = xs.length;
    const d: Dense = {
      x: new Float32Array(xs), z: new Float32Array(zs), nx: new Float32Array(M), nz: new Float32Array(M), half: new Float32Array(M),
      x0: Infinity, z0: Infinity, x1: -Infinity, z1: -Infinity,
    };
    let run = 0;
    for (let k = 0; k < M; k++) {
      const a = Math.max(0, k - 1), c = Math.min(M - 1, k + 1);
      const dx = xs[c] - xs[a], dz = zs[c] - zs[a], l = Math.hypot(dx, dz) || 1;
      d.nx[k] = -dz / l; d.nz[k] = dx / l;
      if (k) run += Math.hypot(xs[k] - xs[k - 1], zs[k] - zs[k - 1]);
      // a trickle at the spring, a little wider by the time it reaches the river
      d.half[k] = 0.06 + 0.1 * Math.min(1, run / Math.max(8, total)) + (k === 0 ? -0.03 : 0);
      d.x0 = Math.min(d.x0, xs[k]); d.x1 = Math.max(d.x1, xs[k]); d.z0 = Math.min(d.z0, zs[k]); d.z1 = Math.max(d.z1, zs[k]);
    }
    dense.push(d);
  }
  cache.set(w, { src, dense });
  return dense;
}

/** Ground a brook is not drawn over: open water, a road or a railway (a culvert), a building. */
function hidden(w: World, x: number, z: number): boolean {
  const tx = Math.floor(x), tz = Math.floor(z);
  if (!inB(tx, tz)) return true;
  const i = idx(tx, tz);
  return w.water[i] >= 0 || w.road[i] > 0 || w.blocked[i] > 0 || (w.rail[i] & (RailBit.Track | RailBit.Pad | RailBit.Loop)) !== 0;
}

/** Each pair of neighbouring samples whose first lies in chunk (cx, cz), both on open ground. */
function eachStretch(w: World, cx: number, cz: number, f: (d: Dense, k: number, ya: number, yb: number) => void): void {
  const X0 = cx * CHUNK, Z0 = cz * CHUNK, X1 = X0 + CHUNK, Z1 = Z0 + CHUNK;
  for (const d of denseOf(w)) {
    if (d.x1 < X0 - 1 || d.x0 > X1 + 1 || d.z1 < Z0 - 1 || d.z0 > Z1 + 1) continue;
    const M = d.x.length;
    for (let k = 0; k + 1 < M; k++) {
      const ax = d.x[k], az = d.z[k];
      if (ax < X0 || ax >= X1 || az < Z0 || az >= Z1) continue;
      if (hidden(w, ax, az) || hidden(w, d.x[k + 1], d.z[k + 1])) continue;
      f(d, k, heightAt(w, ax, az), heightAt(w, d.x[k + 1], d.z[k + 1]));
    }
  }
}

const RIBBON: RGB = mix(C.waterShallow, C.waterMid, 0.35);

/** The ribbons of water, into the chunk's water mesh (extra channel: 1, freezes like the shallows). */
export function brookWater(b: Tris, w: World, cx: number, cz: number): void {
  if (!brooksOf(w).length) return;
  const col = RIBBON;
  const up = (x0: number, y0: number, z0: number, x1: number, y1: number, z1: number, x2: number, y2: number, z2: number) => {
    const ny = (z1 - z0) * (x2 - x0) - (x1 - x0) * (z2 - z0);
    if (ny >= 0) b.tri(x0, y0, z0, x1, y1, z1, x2, y2, z2, col, col, col, 1);
    else b.tri(x0, y0, z0, x2, y2, z2, x1, y1, z1, col, col, col, 1);
  };
  const quad = (d: Dense, ka: number, kb: number, ax: number, az: number, ya: number, bx: number, bz: number, yb: number) => {
    const ha = d.half[ka], hb = d.half[kb];
    const pax = d.nx[ka] * ha, paz = d.nz[ka] * ha, pbx = d.nx[kb] * hb, pbz = d.nz[kb] * hb;
    up(ax + pax, ya, az + paz, bx + pbx, yb, bz + pbz, bx - pbx, yb, bz - pbz);
    up(ax + pax, ya, az + paz, bx - pbx, yb, bz - pbz, ax - pax, ya, az - paz);
  };
  eachStretch(w, cx, cz, (d, k, ya, yb) => {
    const ax = d.x[k], az = d.z[k], bx = d.x[k + 1], bz = d.z[k + 1];
    if (Math.abs(ya - yb) <= STEP_Y) { quad(d, k, k + 1, ax, az, ya + LIFT, bx, bz, yb + LIFT); return; }
    // a step: run level to the edge, and on level from the foot of it
    const mx = (ax + bx) / 2, mz = (az + bz) / 2;
    quad(d, k, k, ax, az, ya + LIFT, mx, mz, ya + LIFT);
    quad(d, k + 1, k + 1, mx, mz, yb + LIFT, bx, bz, yb + LIFT);
  });
}

/** The little falls where a brook pours over a step, into the chunk's fall mesh. */
export function brookFalls(b: Tris, w: World, cx: number, cz: number): void {
  if (!brooksOf(w).length) return;
  const top = C.waterShallow, deep = C.waterMid, foam: RGB = [0.94, 0.98, 1];
  eachStretch(w, cx, cz, (d, k, ya, yb) => {
    if (ya - yb <= STEP_Y) return;
    const ax = d.x[k], az = d.z[k], bx = d.x[k + 1], bz = d.z[k + 1];
    const mx = (ax + bx) / 2, mz = (az + bz) / 2;
    const h = Math.max(d.half[k], d.half[k + 1]) * 1.1;
    const px = d.nx[k] * h, pz = d.nz[k] * h;
    const yt = ya + LIFT, yf = yb + LIFT;
    b.tri(mx - px, yt, mz - pz, mx + px, yt, mz + pz, mx + px, yf, mz + pz, top, top, deep, 1);
    b.tri(mx - px, yt, mz - pz, mx + px, yf, mz + pz, mx - px, yf, mz - pz, top, deep, deep, 1);
    // foam where it lands, a splash the size of the drop
    const l = Math.hypot(bx - ax, bz - az) || 1, fx = ((bx - ax) / l) * (0.12 + (ya - yb) * 0.12), fz = ((bz - az) / l) * (0.12 + (ya - yb) * 0.12);
    const fy = yf + 0.01, s = 1.5;
    b.tri(mx - px * s, fy, mz - pz * s, mx + px * s, fy, mz + pz * s, mx + px * s + fx, fy, mz + pz * s + fz, foam, foam, foam, 0);
    b.tri(mx - px * s, fy, mz - pz * s, mx + px * s + fx, fy, mz + pz * s + fz, mx - px * s + fx, fy, mz - pz * s + fz, foam, foam, foam, 0);
  });
}

/** For the gate: how many little falls the brooks of a world pour over. */
function brookFallCount(w: World): number {
  let n = 0;
  for (let cz = 0; cz < N / CHUNK; cz++) for (let cx = 0; cx < N / CHUNK; cx++) {
    eachStretch(w, cx, cz, (_d, _k, ya, yb) => { if (ya - yb > STEP_Y) n++; });
  }
  return n;
}

