import { N, SEA, Biome, DIRS, Lot, idx, inB, type World } from './tiles';
import { mulberry32, type Rng } from './rng';
import type { WorkSite } from './industry';

/**
 * Private beach resorts (0.7.0, NEXT_WORLD): now and then on a warm sandy shore, a walled all-inclusive complex
 * as big as a town block. Guest wings curve round a pool deck that opens on the beach (a lagoon pool with a
 * swim-up bar, an infinity pool along its front, hot tubs, cabanas), restaurants and bars at the water's edge,
 * loungers and umbrellas down the beach, a jetty and a water-sports hut; behind it all the lobby under its
 * porte-cochère at the end of a palm-lined drive. One lot (world/playKinds.ts `beachResort`) on a work site of its
 * own (kind 'resort'), planned here with its road gate at the back; the model is render/buildings/resort.ts and
 * its hitbox (world/footprint.ts) takes the buildings only, from the same `resortPlan`.
 *
 * Local frame as every model's: the origin in the lot's middle, +z the way it faces (the sea), W across, D deep.
 */

/** Out of every hundred counties, how many look for a shore to put a resort on. */
export const RESORT_CHANCE = 0.45;
export const RESORT_SALT = 0x7e507;
/** The lot: W along the shore, D inland from it. */
const RESORT_W = 16, RESORT_D = 12;
/** Warm enough for one: the shore's temperature (w.temp, 0..1). */
const WARM = 0.62;
/** The sea runs out this far in front of it, clear, across most of its width. */
const OPEN_SEA = 3;

const NAMES = ['Coral', 'Palmera', 'Azure', 'Sandpiper', 'Blue Lagoon', 'Sunset', 'Tradewinds', 'Seashell', 'Bougainvillea', 'Hibiscus', 'Flamingo', 'Marbella'];
const KINDS = ['Beach Resort', 'Resort & Spa', 'Beach Club & Resort', 'Grand Resort'];

/**
 * A resort's lot on this county's shore: a straight run of warm, sandy, low coast with open sea in front,
 * clear of the towns and the seam band; levelled and claimed. Null where there is none.
 */
export function planBeachResort(w: World, land: Uint8Array, E: Float32Array, river: Uint8Array, rng: Rng, band: number): WorkSite | null {
  const lo = band + 12;
  const coast: number[] = [];
  for (let i = 0; i < N * N; i++) if (land[i] && w.coastDist[i] === 1 && !river[i] && w.biome[i] === Biome.Beach && w.temp[i] > WARM) coast.push(i);
  if (coast.length < RESORT_W) return null;
  let best: { x: number; z: number; d: number; score: number; lv: number } | null = null;
  for (let t = 0; t < 600; t++) {
    const i = coast[Math.floor(rng() * coast.length)];
    const x = i % N, z = (i - x) / N;
    for (let d = 0; d < 4; d++) {
      const [dx, dz] = DIRS[d];
      const px = -dz, pz = dx, half = RESORT_W >> 1;
      // the lot: the shore row at k = 0, inland to k = -(D - 1); dry, low, out of town, mostly sand along its front
      let ok = true, sum = 0, mn = Infinity, mx = -Infinity, sand = 0, sea = 0;
      for (let k = -(RESORT_D - 1); k <= 0 && ok; k++) {
        for (let o = -half; o < RESORT_W - half && ok; o++) {
          const tx = x + dx * k + px * o, tz = z + dz * k + pz * o;
          if (tx < lo || tz < lo || tx >= N - lo || tz >= N - lo) { ok = false; break; }
          const j = idx(tx, tz);
          if (!land[j] || river[j] || w.biome[j] === Biome.Town || E[j] < SEA + 0.5) { ok = false; break; }
          sum += E[j]; mn = Math.min(mn, E[j]); mx = Math.max(mx, E[j]);
          if (k >= -1 && w.biome[j] === Biome.Beach) sand++;
        }
      }
      if (!ok || mx - mn > 4 || sand < RESORT_W) continue;
      // open sea in front of most of it; and the shore running on as land past both ends of its front (where it
      // bends round, the sea comes into a corner of the lot)
      let first = 0;
      for (let k = 1; k <= OPEN_SEA; k++) for (let o = -half; o < RESORT_W - half; o++) {
        const tx = x + dx * k + px * o, tz = z + dz * k + pz * o;
        if (inB(tx, tz) && !land[idx(tx, tz)]) { sea++; if (k === 1) first++; }
      }
      if (first < RESORT_W * 0.6 || sea < RESORT_W * OPEN_SEA * 0.7) continue;
      let ends = true;
      for (const o of [-half - 1, RESORT_W - half]) for (const k of [0]) {
        const tx = x + dx * k + px * o, tz = z + dz * k + pz * o;
        if (!inB(tx, tz) || !land[idx(tx, tz)]) ends = false;
      }
      if (!ends) continue;
      const lv = Math.max(SEA + 1, Math.round(sum / (RESORT_W * RESORT_D)));
      // flattest first, and a town within reach (its guests come by road)
      const score = (mx - mn) + Math.min(40, townNear(w, x, z)) * 0.05 + rng();
      if (!best || score < best.score) best = { x, z, d, score, lv };
    }
  }
  if (!best) return null;
  const [dx, dz] = DIRS[best.d];
  const px = -dz, pz = dx, half = RESORT_W >> 1;
  let x0 = N, z0 = N, x1 = -1, z1 = -1;
  for (let k = -(RESORT_D - 1); k <= 0; k++) {
    for (let o = -half; o < RESORT_W - half; o++) {
      const tx = best.x + dx * k + px * o, tz = best.z + dz * k + pz * o;
      x0 = Math.min(x0, tx); z0 = Math.min(z0, tz); x1 = Math.max(x1, tx); z1 = Math.max(z1, tz);
    }
  }
  const wx = x1 - x0 + 1, wz = z1 - z0 + 1;
  // levelled, its edges eased into the ground round it; then claimed: no trees, nothing else built there
  for (let z = z0 - 3; z <= z1 + 3; z++) for (let x = x0 - 3; x <= x1 + 3; x++) {
    if (!inB(x, z)) continue;
    const i = idx(x, z);
    if (!land[i] || w.biome[i] === Biome.Town) continue;
    const out = Math.max(0, x0 - x, x - x1, z0 - z, z - z1);
    E[i] = out === 0 ? best.lv : E[i] + (best.lv - E[i]) * (1 - out / 4);
  }
  for (let z = z0; z <= z1; z++) for (let x = x0; x <= x1; x++) {
    const i = idx(x, z);
    w.biome[i] = Biome.Town;
    w.lot[i] = Lot.Plaza;
    w.cleared[i] = 1;
    river[i] = 0;
  }
  const name = `The ${NAMES[Math.floor(rng() * NAMES.length)]} ${KINDS[Math.floor(rng() * KINDS.length)]}`;
  // the road comes in at the back, the landward side, to the lobby's porte-cochère
  const gx = best.x - dx * RESORT_D, gz = best.z - dz * RESORT_D;
  return {
    kind: 'resort', name, x: Math.floor(x0 + wx / 2), z: Math.floor(z0 + wz / 2), level: best.lv, facing: best.d, major: true,
    len: Math.max(wx, wz), half: Math.min(wx, wz) / 2, cable: [], gate: idx(Math.max(0, Math.min(N - 1, gx)), Math.max(0, Math.min(N - 1, gz))),
    lot: { kind: 'beachResort', x: x0, z: z0, w: wx, d: wz },
  };
}

/** Tiles to the nearest town pad (already town ground at this stage), up to 60. */
function townNear(w: World, x: number, z: number): number {
  let best = 60;
  for (let dz = -60; dz <= 60; dz += 4) for (let dx = -60; dx <= 60; dx += 4) {
    if (inB(x + dx, z + dz) && w.biome[idx(x + dx, z + dz)] === Biome.Town) best = Math.min(best, Math.hypot(dx, dz));
  }
  return best;
}

// ---------------------------------------------------------------------------------------------
// the layout

/** A building of the resort: a box centred at (x, z), turned `yaw` (radians, about y), w along its front, d deep, h tall. */
interface ResortBlock { x: number; z: number; w: number; d: number; h: number; yaw: number; kind: 'wing' | 'lobby' | 'restaurant' | 'bar' | 'hut' }
interface ResortPlan {
  blocks: ResortBlock[];
  /** The lagoon pool as overlapping ovals (x, z, rx, rz), the swim-up bar in it, the infinity pool along the deck's front. */
  lagoon: [number, number, number, number][];
  swimBar: { x: number; z: number; r: number };
  infinity: { x: number; z: number; w: number; d: number };
  tubs: { x: number; z: number; r: number }[];
  cabanas: [number, number][];
  /** Loungers (and an umbrella over every other one): on the deck and down the beach. */
  loungers: { x: number; z: number; yaw: number }[];
  palms: [number, number][];
  /** The pool deck and the beach strip (z from-to), and the entry drive (x half-width, z from-to). */
  deck: { x0: number; x1: number; z0: number; z1: number };
  beach: { z0: number; z1: number };
  drive: { half: number; z0: number; z1: number };
  jetty: { x: number; len: number };
}

export function resortPlan(seed: number, W: number, D: number): ResortPlan {
  const r = mulberry32(seed ^ 0x72657372);
  const front = D / 2, back = -D / 2;
  const beach = { z0: front - 2.3, z1: front };
  const deck = { x0: -W / 2 + 2.6, x1: W / 2 - 2.6, z0: back + 3.6, z1: beach.z0 - 0.2 };
  const blocks: ResortBlock[] = [];
  // the guest wings: blocks on an arc round the deck, opening to the sea, the lobby in the middle of the back
  const cx = 0, cz = deck.z1 - 0.6, R = Math.min(W / 2 - 1.1, cz - back - 1.6);
  const n = 7, from = Math.PI * 1.15, to = Math.PI * 1.85;
  for (let k = 0; k < n; k++) {
    const a = from + ((to - from) * k) / (n - 1);
    const x = cx + Math.cos(a) * R, z = cz + Math.sin(a) * R;
    const len = (2 * R * Math.sin((to - from) / (n - 1) / 2)) * 0.92;
    const lobby = k === (n >> 1);
    // turned to face the deck's middle: a block's front (+z in its own frame) looks at it
    const yaw = Math.atan2(cx - x, cz - z);
    blocks.push({ x, z, w: len, d: lobby ? 1.5 : 1.2, h: lobby ? 1.05 : 1.25 + r() * 0.5, yaw, kind: lobby ? 'lobby' : 'wing' });
  }
  // restaurants and bars at the water's edge: one each side of the deck, a beach bar on the sand
  for (const s of [-1, 1]) {
    blocks.push({ x: s * (W / 2 - 1.6), z: beach.z0 - 0.75, w: 2.4, d: 1.3, h: 0.5, yaw: 0, kind: (s < 0) === (r() < 0.5) ? 'restaurant' : 'bar' });
  }
  const barX = (r() < 0.5 ? -1 : 1) * (W * 0.18);
  blocks.push({ x: barX, z: beach.z0 + 0.7, w: 1.1, d: 0.8, h: 0.42, yaw: 0, kind: 'bar' });
  blocks.push({ x: -barX * 2.1, z: beach.z0 + 0.6, w: 0.9, d: 0.7, h: 0.36, yaw: 0, kind: 'hut' });
  // the pools: a lagoon of three or four ovals with a swim-up bar, an infinity pool along the front, hot tubs
  const lz = (deck.z0 + deck.z1) / 2 - 0.2;
  const lagoon: ResortPlan['lagoon'] = [[-1.7, lz, 1.5, 1.05], [0.5, lz - 0.5, 1.6, 1.15], [1.9, lz + 0.5, 1.1, 0.85]];
  if (r() < 0.5) lagoon.push([-0.4, lz + 0.8, 1.0, 0.7]);
  const swimBar = { x: 0.3, z: lz - 0.4, r: 0.36 };
  const infinity = { x: 0, z: deck.z1 - 0.45, w: (deck.x1 - deck.x0) * 0.62, d: 0.55 };
  const tubs = [{ x: deck.x0 + 0.5, z: lz - 1.3, r: 0.24 }, { x: deck.x1 - 0.5, z: lz - 1.3, r: 0.24 }, { x: deck.x1 - 0.6, z: deck.z1 - 0.5, r: 0.22 }];
  const cabanas: [number, number][] = [[deck.x0 + 0.45, lz + 0.4], [deck.x0 + 0.45, lz + 1.4], [deck.x1 - 0.45, lz + 0.4], [deck.x1 - 0.45, lz + 1.4]];
  const loungers: ResortPlan['loungers'] = [];
  for (let x = deck.x0 + 1.2; x <= deck.x1 - 1.2; x += 0.42) {
    if (Math.abs(x) > infinity.w / 2 + 0.1) loungers.push({ x, z: deck.z1 - 0.4, yaw: 0 });
  }
  for (const row of [beach.z0 + 1.35, beach.z0 + 1.85]) {
    for (let x = -W / 2 + 0.6; x <= W / 2 - 0.6; x += 0.55) {
      if (Math.abs(x - barX) < 1 || Math.abs(x + barX * 2.1) < 0.9) continue;
      loungers.push({ x, z: row, yaw: 0 });
    }
  }
  // palms: down both sides of the drive, round the deck and along the back of the beach
  const drive = { half: 0.5, z0: back, z1: back + 1.6 };
  const palms: [number, number][] = [];
  for (const s of [-1, 1]) {
    for (let z = back + 0.3; z <= back + 1.5; z += 0.6) palms.push([s * 0.95, z]);
    palms.push([s * (deck.x1 - 0.2), deck.z0 + 0.2], [s * (W / 2 - 0.4), beach.z0 - 2.2], [s * (W / 2 - 0.35), back + 0.5]);
  }
  for (let x = -W / 2 + 1.5; x <= W / 2 - 1.5; x += 2.3) if (Math.abs(x) > 0.8) palms.push([x, beach.z0 + 0.15]);
  // no palm grows inside a building, nor so close that its crown is in the wall (the user, 25 Oct 2026)
  const grown = resortSolid({ blocks: blocks.map((b) => ({ ...b, w: b.w + 0.9, d: b.d + 0.9 })) } as ResortPlan);
  const clear = palms.filter(([x, z]) => !grown(x, z));
  return { blocks, lagoon, swimBar, infinity, tubs, cabanas, loungers, palms: clear, deck, beach, drive, jetty: { x: -barX * 1.2, len: 2.2 } };
}

/** The buildings only: the deck, the pools, the gardens and the beach are open ground. */
export function resortSolid(p: ResortPlan): (x: number, z: number) => boolean {
  return (x, z) => p.blocks.some((b) => {
    const c = Math.cos(b.yaw), s = Math.sin(b.yaw), dx = x - b.x, dz = z - b.z;
    // into the block's own frame (the inverse of the turn render/buildings/kit.ts `turned` makes)
    const lx = dx * c - dz * s, lz = dx * s + dz * c;
    return Math.abs(lx) <= b.w / 2 && Math.abs(lz) <= b.d / 2;
  });
}
