import { N, Biome, RailBit, REGION_KINDS, World, idx, waterDepth } from './tiles';
import { REGIONS } from './regions';
import { municipalityOf } from './municipality';

/**
 * The world map: one 32 × 32 pixel stamp per island, so eight tiles to a pixel, and a record of
 * which of those pixels the player has ever been near. Everything else stays black.
 */
export const MAP_PIX = 32;
export const TILES_PER_PIX = N / MAP_PIX;
/** How near the player, or a unit of their fleet, must pass for a map pixel to be revealed, in tiles. */
export const SIGHT = 100;

/** Palette index 0 is fog: somewhere nobody has been. The rest are what the ground looks like. */
export const PALETTE: readonly number[] = [
  0x0a0d11, // 0  fog
  0x2b5580, // 1  deep sea
  0x3a86c2, // 2  sea
  0x74c4e6, // 3  shallows
  0xefe2a9, // 4  beach
  0x8fd06c, // 5  plains
  0xa2d873, // 6  hills
  0x4f9a52, // 7  forest
  0xd8a742, // 8  farmland
  0xe9d59e, // 9  desert
  0xd0a072, // 10 canyon
  0x8e9a86, // 11 mountain
  0xf2f5f8, // 12 snow
  0xb3cf82, // 13 sea cliff
  0xd8d2c6, // 14 town
  0x6d7176, // 15 road
  0x3a3634, // 16 lava
  0xf3f1ea, // 17 salt
  0xdcecf4, // 18 ice
  0x7d9a5a, // 19 marsh
  0x4f7a3e, // 20 mangrove
  0x7fe3d8, // 21 lagoon
  0xc0603f, // 22 badlands
  0xeccf94, // 23 dunes
  // 24..33: the ten biomes, in REGION_KINDS order, so a biome shows on the map as a patch of its own colour
  ...REGION_KINDS.map((k) => REGIONS[k].atlas),
  0x45403c, // 34 railway (appended, so saved maps keep their indices)
];
const FOG = 0;
const SEA_DEEP = 1, SEA_MID = 2, SEA_SHALLOW = 3, BEACH = 4, TOWN = 14, ROAD = 15, RAIL = 34;

const BIOME_PIX: Record<number, number> = {
  [Biome.Ocean]: SEA_MID,
  [Biome.Beach]: BEACH,
  [Biome.SeaCliff]: 13,
  [Biome.Plains]: 5,
  [Biome.Hills]: 6,
  [Biome.Forest]: 7,
  [Biome.Farm]: 8,
  [Biome.Desert]: 9,
  [Biome.Canyon]: 10,
  [Biome.Mountain]: 11,
  [Biome.Snow]: 12,
  [Biome.Town]: TOWN,
  [Biome.Lava]: 16,
  [Biome.Salt]: 17,
  [Biome.Ice]: 18,
  [Biome.Marsh]: 19,
  [Biome.Mangrove]: 20,
  [Biome.Lagoon]: 21,
};

export const cellKey = (cx: number, cz: number): string => `${cx},${cz}`;

/** A town the map knows of, whether or not its island is in memory: its id, name and kind, and its middle in the cell's tiles. */
export interface Place { id: number; name: string; kind: string; x: number; z: number }

/**
 * One island as map pixels. Each pixel takes the eight-by-eight block of tiles under it: a road
 * running through it wins, then a railway (on the ground or overhead), then a town, then whatever the ground mostly is, with open water read
 * by how deep it gets.
 */
export function stampOf(w: World, per = TILES_PER_PIX): Uint8Array {
  const P = N / per;
  const out = new Uint8Array(P * P);
  const tally = new Int16Array(PALETTE.length);
  // a road or a railway wins its pixel once it crosses it: four tiles in the map's eight-by-eight, two in a finer one's
  const lines = Math.max(2, per / 2);
  for (let pz = 0; pz < P; pz++) {
    for (let px = 0; px < P; px++) {
      tally.fill(0);
      let roads = 0, rails = 0, town = 0, wet = 0, depth = 0;
      const x0 = px * per, z0 = pz * per;
      for (let z = z0; z < z0 + per; z++) {
        for (let x = x0; x < x0 + per; x++) {
          const i = idx(x, z);
          if (w.road[i]) roads++;
          if (w.rail[i] & (RailBit.Track | RailBit.Deck)) rails++;
          if (w.townId[i] >= 0 || w.portId[i] >= 0) town++;
          const d = waterDepth(w, i);
          if (d > 0 && w.biome[i] === Biome.Lagoon) tally[21]++;
          else if (d > 0) { wet++; depth += d; }
          else if (w.surface[i] === 1 && (w.biome[i] === Biome.Canyon || w.biome[i] === Biome.Desert)) tally[22]++;
          else if (w.surface[i] === 2) tally[23]++;
          // a biome's colour wins its open land; its towns, roads and water keep theirs
          else if (w.regionK[i] && w.regionW[i] > 160 && w.biome[i] !== Biome.Town) tally[23 + w.regionK[i]]++;
          else tally[BIOME_PIX[w.biome[i]] ?? 5]++;
        }
      }
      const area = per * per;
      let v: number;
      if (roads >= lines) v = ROAD;
      else if (rails >= lines) v = RAIL;
      else if (town >= area / 3) v = TOWN;
      else if (wet > area / 2) {
        const mean = depth / wet;
        v = mean <= 1.2 ? SEA_SHALLOW : mean <= 3.5 ? SEA_MID : SEA_DEEP;
      } else {
        let best = 5, bestN = -1;
        for (let k = 1; k < RAIL; k++) if (tally[k] > bestN) { bestN = tally[k]; best = k; }
        v = best;
      }
      out[pz * P + px] = v;
    }
  }
  return out;
}

/**
 * What the player has seen of the world, and what it looked like. Islands hand over their stamp
 * while they are in memory; pixels are copied out of it as the player passes within sight of them,
 * and those copies are what the map is drawn from and what a saved game keeps.
 */
export class Atlas {
  /** Revealed pixels per cell, 0 where the player has never been near. */
  private seen = new Map<string, Uint8Array>();
  /** Each cell's run-length encoding as last saved (toSave), dropped when a pixel of it changes: a save re-encodes only those. */
  private encoded = new Map<string, string | null>();
  /** The full stamp of every island that has been in memory this session. */
  private stamps = new Map<string, Uint8Array>();
  /** The towns of every island ever in memory, by cell, so the map can name them after it has gone. */
  private places = new Map<string, Place[]>();
  /** Each cell's municipalities (world/municipality.ts), from the island in memory or a survey; not saved. */
  private munis = new Map<string, Int16Array>();
  private lastX = NaN;
  private lastZ = NaN;
  /** Goes up whenever a pixel is revealed or the record is replaced: the maps redraw their fog on a change. */
  version = 0;

  get cells(): number { return this.seen.size; }

  clear(): void {
    this.version++;
    this.seen.clear();
    this.encoded.clear();
    this.stamps.clear();
    this.places.clear();
    this.munis.clear();
    this.lastX = NaN;
  }

  /** Take an island's picture. Called when it arrives, and again when the player changes it. */
  /** An island's picture on the map; `made` is one already worked out for it as it now stands (its survey's). */
  stamp(w: World, made?: { stamp: Uint8Array; muni: Int16Array }): void {
    this.stamps.set(cellKey(w.cx, w.cz), made?.stamp ?? stampOf(w));
    this.munis.set(cellKey(w.cx, w.cz), made?.muni ?? municipalityOf(w));
    this.note(w);
    this.lastX = NaN;   // let the next reveal run even if the player hasn't moved
  }

  /** Write down an island's towns as they are now: a town that graduates changes its name and kind. */
  note(w: World): void {
    this.places.set(cellKey(w.cx, w.cz), w.towns.map((t) => ({ id: t.id, name: t.name, kind: t.kind, x: t.x0 + t.size / 2, z: t.z0 + t.size / 2 })));
  }

  /** Every town the map knows of, with its cell, whose middle the player has seen. */
  knownPlaces(): (Place & { cx: number; cz: number })[] {
    const out: (Place & { cx: number; cz: number })[] = [];
    for (const [k, list] of this.places) {
      const [cx, cz] = k.split(',').map(Number);
      const seen = this.seen.get(k);
      if (!seen) continue;
      for (const p of list) {
        const px = Math.min(MAP_PIX - 1, Math.max(0, Math.floor(p.x / TILES_PER_PIX)));
        const pz = Math.min(MAP_PIX - 1, Math.max(0, Math.floor(p.z / TILES_PER_PIX)));
        if (seen[pz * MAP_PIX + px]) out.push({ ...p, cx, cz });
      }
    }
    return out;
  }

  /** One town the map knows of, by its key `cx,cz#id`. */
  place(key: string): (Place & { cx: number; cz: number }) | null {
    const [cell, id] = key.split('#');
    const p = this.places.get(cell)?.find((q) => q.id === Number(id));
    if (!p) return null;
    const [cx, cz] = cell.split(',').map(Number);
    return { ...p, cx, cz };
  }

  revealed(cx: number, cz: number): Uint8Array | undefined { return this.seen.get(cellKey(cx, cz)); }

  /** A cell's municipalities, when its island has been in memory or surveyed this session. */
  muni(cx: number, cz: number): Int16Array | undefined { return this.munis.get(cellKey(cx, cz)); }

  /** Every town the atlas knows of, seen or not, with its cell: territory's far towns. */
  allPlaces(): (Place & { cx: number; cz: number })[] {
    const out: (Place & { cx: number; cz: number })[] = [];
    for (const [k, list] of this.places) {
      const [cx, cz] = k.split(',').map(Number);
      for (const p of list) out.push({ ...p, cx, cz });
    }
    return out;
  }

  /** Has the player (or their fleet) been within sight of this world point? */
  seenAt(gx: number, gz: number): boolean {
    const px = Math.floor(gx / TILES_PER_PIX), pz = Math.floor(gz / TILES_PER_PIX);
    const cx = Math.floor(px / MAP_PIX), cz = Math.floor(pz / MAP_PIX);
    const c = this.seen.get(cellKey(cx, cz));
    return !!c && c[(pz - cz * MAP_PIX) * MAP_PIX + (px - cx * MAP_PIX)] !== FOG;
  }

  /**
   * A cell surveyed from afar (world/survey.ts) lends its picture and its towns, where the map has none
   * of its own from the island in memory: the fleet can reveal it, and its towns can be named.
   */
  adopt(cx: number, cz: number, stamp: Uint8Array, towns: { id: number; name: string; kind: string; x: number; z: number }[], muni?: Int16Array): void {
    const k = cellKey(cx, cz);
    if (muni && !this.munis.has(k)) this.munis.set(k, muni);
    if (!this.stamps.has(k)) this.stamps.set(k, stamp);
    if (!this.places.has(k)) this.places.set(k, towns.map((t) => ({ ...t })));
  }

  /** Reveal everything within sight of the player, wherever they are standing. */
  reveal(w: World, lx: number, lz: number, sight = SIGHT): void {
    const gx = w.ox + lx, gz = w.oz + lz;
    if (Math.abs(gx - this.lastX) < TILES_PER_PIX / 2 && Math.abs(gz - this.lastZ) < TILES_PER_PIX / 2) return;
    this.lastX = gx;
    this.lastZ = gz;
    this.revealAt(gx, gz, sight);
  }

  /**
   * Reveal everything within sight of a world point, wherever the cell's picture is known: the
   * player's own sweep, and the fleet's (a unit of yours out on the road finds places for you too).
   */
  revealAt(gx: number, gz: number, sight = SIGHT): void {
    const px = Math.floor(gx / TILES_PER_PIX), pz = Math.floor(gz / TILES_PER_PIX);
    const r = Math.round(sight / TILES_PER_PIX);
    for (let dz = -r; dz <= r; dz++) {
      for (let dx = -r; dx <= r; dx++) {
        if (dx * dx + dz * dz > r * r) continue;
        const qx = px + dx, qz = pz + dz;
        const cx = Math.floor(qx / MAP_PIX), cz = Math.floor(qz / MAP_PIX);
        const stamp = this.stamps.get(cellKey(cx, cz));
        if (!stamp) continue;                    // that island isn't in memory: nothing to copy
        const i = (qz - cz * MAP_PIX) * MAP_PIX + (qx - cx * MAP_PIX);
        const c = this.cellOf(cx, cz);
        if (c[i] === stamp[i]) continue;
        c[i] = stamp[i];
        this.version++;
        this.encoded.delete(cellKey(cx, cz));
      }
    }
  }

  /** The rectangle of cells with anything revealed in them, or null when nothing is. */
  bounds(): { x0: number; z0: number; x1: number; z1: number } | null {
    let x0 = Infinity, z0 = Infinity, x1 = -Infinity, z1 = -Infinity;
    for (const k of this.seen.keys()) {
      const [cx, cz] = k.split(',').map(Number);
      x0 = Math.min(x0, cx); z0 = Math.min(z0, cz);
      x1 = Math.max(x1, cx); z1 = Math.max(z1, cz);
    }
    return Number.isFinite(x0) ? { x0, z0, x1, z1 } : null;
  }

  private cellOf(cx: number, cz: number): Uint8Array {
    const k = cellKey(cx, cz);
    let c = this.seen.get(k);
    if (!c) this.seen.set(k, (c = new Uint8Array(MAP_PIX * MAP_PIX)));
    return c;
  }

  // ---- saving -------------------------------------------------------------------------------

  /** Run-length encode each cell; fog runs long, so a barely-explored island costs a few bytes. */
  toSave(): Record<string, string> {
    const out: Record<string, string> = {};
    for (const [k, c] of this.seen) {
      const had = this.encoded.get(k);
      if (had !== undefined) { if (had !== null) out[k] = had; continue; }
      const bytes: number[] = [];
      let v = c[0], run = 1;
      for (let i = 1; i <= c.length; i++) {
        if (i < c.length && c[i] === v && run < 255) { run++; continue; }
        bytes.push(v, run);
        v = c[i];
        run = 1;
      }
      if (bytes.length >= c.length) { this.encoded.set(k, null); continue; }     // no saving to be had; skip the cell
      let s = '';
      for (const b of bytes) s += String.fromCharCode(b);
      out[k] = btoa(s);
      this.encoded.set(k, out[k]);
    }
    return out;
  }

  placesToSave(): Record<string, [number, string, string, number, number][]> {
    const out: Record<string, [number, string, string, number, number][]> = {};
    for (const [k, list] of this.places) if (this.seen.has(k)) out[k] = list.map((p) => [p.id, p.name, p.kind, p.x, p.z]);
    return out;
  }

  placesFromSave(rec: Record<string, [number, string, string, number, number][]> | undefined): void {
    for (const [k, list] of Object.entries(rec ?? {})) {
      if (!Array.isArray(list)) continue;
      this.places.set(k, list.map(([id, name, kind, x, z]) => ({ id, name, kind, x, z })));
    }
  }

  fromSave(rec: Record<string, string> | undefined): void {
    this.version++;
    this.seen.clear();
    this.encoded.clear();
    for (const [k, enc] of Object.entries(rec ?? {})) {
      try {
        const s = atob(enc);
        const c = new Uint8Array(MAP_PIX * MAP_PIX);
        let at = 0;
        for (let i = 0; i + 1 < s.length && at < c.length; i += 2) {
          const v = s.charCodeAt(i), run = s.charCodeAt(i + 1);
          for (let n = 0; n < run && at < c.length; n++) c[at++] = v;
        }
        this.seen.set(k, c);
      } catch {
        /* a map that won't decode just stays dark */
      }
    }
  }
}
