export const GEN_VERSION = NEXT_080 ? 54 : NEXT_WORLD ? 53 : 52;

/** The share of ordinary cells (no biome) that get the moated castle, and the salt its roll is hashed with. */
const CASTLE_CHANCE = 0.15, CASTLE_SALT = 1811;

/**
 * The ancient wonders (GEN 53): the share of the Whitewash's and the Sands' wonder cells that have one of them
 * instead of their own, the share of warm ordinary cells without a castle that have one, how warm such a cell's
 * land must be on average (w.temp), and the salt the rolls are hashed with.
 */
const ANCIENT_REGION = 0.5, ANCIENT_CHANCE = 0.1, ANCIENT_WARM = 0.45, ANCIENT_SALT = 5303;
/** Which of them a biome's cells may have: the Aegean's temples, tomb, statue and light; Babylon's and Alexandria's. */
const ANCIENT_OF: Partial<Record<RegionSpec['kind'], AncientKind[]>> = {
  whitewash: ['colossus', 'pharos', 'mausoleum', 'templeArtemis', 'statueZeus'],
  sands: ['hangingGardens', 'pharos'],
};
const ANCIENT_ANYWHERE: AncientKind[] = ['colossus', 'pharos', 'hangingGardens', 'templeArtemis', 'statueZeus', 'mausoleum'];

/** The ancient wonders a cell's hashed rolls allow it (before its warmth and its coast are known), or null. */
function ancientPool(seedHash: number, cx: number, cz: number, spec: RegionSpec | null): AncientKind[] | null {
  if (spec) {
    const own = ANCIENT_OF[spec.kind];
    if (!own || !regionWonder(seedHash, cx, cz) || promisedBiome(seedHash, cx, cz)) return null;
    return cell01(seedHash, cx, cz, ANCIENT_SALT) < ANCIENT_REGION ? own : null;
  }
  if (cell01(seedHash, cx, cz, CASTLE_SALT) < CASTLE_CHANCE || cell01(seedHash, cx, cz, ANCIENT_SALT) >= ANCIENT_CHANCE) return null;
  return ANCIENT_ANYWHERE;
}

/**
 * Which ancient wonder a cell has, if any, from hashed rolls (so no other cell's draws move). A biome's
 * promised cell keeps the biome's own wonder; an ordinary cell needs warm land; an inland cell has none of the
 * two that want the sea. Which one is dealt round the grid (cx + 2cz, turned by the seed), so the same one is
 * never in two counties side by side.
 */
function ancientWonder(seedHash: number, cx: number, cz: number, spec: RegionSpec | null, w: World, land: Uint8Array, coastal: boolean): AncientKind | null {
  let pool = ancientPool(seedHash, cx, cz, spec);
  if (!pool) return null;
  if (!spec) {
    let sum = 0, n = 0;
    for (let i = 0; i < N * N; i += 7) if (land[i]) { sum += w.temp[i]; n++; }
    if (!n || sum / n < ANCIENT_WARM) return null;
  }
  if (!coastal) pool = pool.filter((k) => k !== 'colossus' && k !== 'pharos');
  if (!pool.length) return null;
  const turn = Math.floor(cell01(seedHash, 0, 0, ANCIENT_SALT + 3) * pool.length);
  return pool[(((cx + 2 * cz + turn) % pool.length) + pool.length) % pool.length];
}

/**
 * Could this county have an ancient wonder? The cheap half of ancientWonder, without generating it: a gate
 * (scripts/ancient.ts) builds only the counties this says yes to.
 */
export function ancientMaybe(seed: string, cx: number, cz: number): boolean {
  setWorldMode(parseSeed(seed).mode);
  const seedHash = hashString(seed);
  if (cellKind(seedHash, cx, cz) === 'sea') return false;
  const own = new RegionField(seedHash).cellRegion(cx, cz);
  return !!ancientPool(seedHash, cx, cz, own ? REGIONS[REGION_KINDS[own - 1]] : null);
}

/**
 * How much ground beyond its own borders a cell works out alongside its own, in tiles.
 *
 * Two neighbouring cells overlap by 2 × PAD, and inside that overlap every input is a function of
 * the global tile, so both compute exactly the same thing. Beyond the overlap they diverge — one
 * cell's padded grid simply stops where the other's carries on — so the two agree on the ground
 * they share only as long as nothing travels from that divergence to the border. The legaliser
 * carries corrections one tile per pass and gives up after LEGALISE_REACH of them, which leaves a
 * dozen tiles of margin: that is the whole of why land can run across a cell border.
 */
export const PAD = 40;
const P = N + 2 * PAD;
const PP = P * P;
/** Nothing stochastic — town, farm, port, canyon, lake, beach or quarry — comes this near a land border. */
export const SEAM_BAND = 40;
/** The furthest the legaliser may carry a correction. Comfortably inside PAD, and that is the point. */
const LEGALISE_REACH = 28;

/** Half-width of a causeway, in tiles. */
const CAUSEWAY_HALF = 1;
/** Tiles at the inland end of a causeway over which it climbs to meet the island. */
const CAUSEWAY_RAMP = 10;
/**
 * The steepest a causeway may climb to its landing, in steps a tile: ground too high to reach from the
 * border by then is no landing yet, and the causeway cuts on into it until the climb will do.
 */
const LANDING_GRADE = 0.8;
/** How many tiles wider each side a causeway flares where it lands, over as many tiles. */
const CAUSEWAY_FLARE = 2;
/**
 * Rings of each cell forced to this ocean depth, so the sea bed lines up across every water border.
 * It is the open ocean's own depth (and OPEN_SEA's), so the rim and an empty sea cell never show as
 * a square of shallows in the deep.
 */
const RIM = 3;
const RIM_DEPTH = SEA - 5;
/** Tiles over which a continent's land fades away on a side that faces open water. */
const COAST_FADE = 24;
/**
 * How many more fades' worth a continent's coast may be pushed back from a water border. Where the
 * macro field is still strong at the border the fade alone draws the coast, and a fade of constant
 * depth draws it as a ruler line; a noisy depth gives it bays and headlands instead.
 */
const COAST_WOBBLE = 1.1;
/** The finer ragged edge laid over it, in the same fades. */
const COAST_JAG = 0.4;

// ---------------- the shape of the ground ----------------
//
// Everything below is built so that no two neighbouring tiles differ by more than MAX_GRADE. That
// is what makes the terrain legal by construction: the legaliser is left with nothing to do but
// tidy up rounding, so its reach no longer depends on how tall the world is allowed to be.

/** The steepest the ground is ever built, in height steps per tile. */
/** How fast the land climbs away from the water, and so the ceiling on height near a coast. */
const SHORE = 0.65;
/** Coast distance is never needed beyond this, which is what keeps the padding at PAD tiles. */
const COAST_CAP = 32;

/**
 * How much higher than the shore cone a sea cliff stands. Added to the cone rather than steepening
 * it, so the extra height arrives along the coast over the width of the cliff band rather than in
 * one tile: a cliff is a drop into the water, which is walled, not a wall of land facing inland.
 */
const CLIFF_LIFT = 2.8;

/** The gentle swell a whole landmass sits on. */
const BASE_AMP = 3.0;
/** Hill country, in two sizes, under a mask that decides where it is. */
const HILL_BIG = 2.2;
const HILL_SMALL = 1.1;

/** Peaks are hash-placed on a global grid this many tiles apart. */
const PEAK_GRID = 104;
/** The most a mountain rises above the ground it stands on, in steps. */
const PEAK_MAX = 21;
/** How much taller a mountain may stand in the heart of a high-country zone, in steps. */
const PEAK_UPLIFT = 40;
/** The steepest flank any mountain may have: its radius is its height divided by this. */
const PEAK_SLOPE = 0.5;
/** Texture laid over the bare cones, small enough to leave the slope bound intact. */
const PEAK_TEX = 0.7;
/** The longest ridge line a peak may be drawn out into. */
const RIDGE_MAX = 90;
/** How much of a peak's height its crest gains and loses along the ridge, either way. */
const CREST_WOBBLE = 0.22;
/** Spurs and gullies down a mountainside, in steps. */
const SPUR_AMP = 1.5;

const BEACH_A = ['Long', 'Silver', 'Shell', 'Gull', 'Driftwood', 'Sunset', 'Cobble', 'Pelican', 'Tern', 'Bright'];
const BEACH_B = [' Sands', ' Beach', ' Strand', ' Bay', ' Cove', ' Shore'];
function beachName(h: number, k: number): string {
  return BEACH_A[(h + k * 7) % BEACH_A.length] + BEACH_B[(h >>> (3 + k)) % BEACH_B.length];
}

/**
 * Test hook for the seam.
 *
 * The padded intermediates, handed out when a harness asks, so two neighbouring cells can be
 * generated side by side and checked tile for tile where their grids overlap. That check is the
 * real proof continents rest on; the drivable-continuity assertion in the console is its shadow.
 */
const PROBE: { on?: (name: string, data: unknown) => void } = {};
/** Console chatter for the harnesses. */
export const DEBUG = { bench: false };

/** The macro layer, re-exported so the console and the rest of the game can ask about a cell. */
export { cellKind, hasMega, straitAt, crossingAt, riverAt, contField, continentName, CONT_THR } from './macro';

// ---------------- noise, one instance per seed ----------------

/**
 * Two noise fields per seed rather than per cell, always sampled in global tile coordinates. That
 * one change is what lets a hill, a coastline or a mountain range run on across a border as though
 * the border were not there.
 */
const noiseCache = new Map<number, [Noise2D, Noise2D]>();
function noiseFor(seedHash: number): [Noise2D, Noise2D] {
  let n = noiseCache.get(seedHash);
  if (!n) {
    const rng = mulberry32(seedHash ^ 0x5f3759df);
    n = [new Noise2D(rng), new Noise2D(rng)];
    if (noiseCache.size > 3) noiseCache.delete(noiseCache.keys().next().value as number);
    noiseCache.set(seedHash, n);
  }
  return n;
}

// ---------------- the continental coast, as a function of the global tile ----------------

/**
 * How much land the cell containing this global tile keeps here: 1 well inside it, easing to 0 over
 * the last stretch before any side that faces open water, and exactly 0 in the forced sea-bed rim.
 *
 * It is keyed on whichever cell contains the tile, never on the cell doing the asking, so a cell
 * reading into its neighbour's ground works out precisely what that neighbour will.
 *
 * On a continent the depth of the fade wanders with noise read at the global tile, so a coast drawn
 * by the fade rather than by the macro field still comes out ragged. It only ever deepens the fade,
 * never shallows it, so the rim stays exactly where it was.
 */
function landFade(gx: number, gz: number, kinds: (cx: number, cz: number) => CellKind, nA: Noise2D): number {
  const cx = Math.floor(gx / N), cz = Math.floor(gz / N);
  const lx = gx - cx * N, lz = gz - cz * N;
  const cont = kinds(cx, cz) === 'continent';
  let f = 1, wobble = -1;
  for (let d = 0; d < 4; d++) {
    if (cont && kinds(cx + DIRS[d][0], cz + DIRS[d][1]) === 'continent') continue;
    const dist = d === 0 ? N - 1 - lx : d === 1 ? N - 1 - lz : d === 2 ? lx : lz;
    let t = (dist - RIM) / COAST_FADE;
    if (cont && t > 0 && t < 1 + COAST_WOBBLE + COAST_JAG) {
      if (wobble < 0) {
        // broad bays and headlands, and a ragged edge on them that no clamp flattens into a straight run
        const broad = clamp(0.5 + 0.9 * nA.fbm(gx / N * 3.3 + 71.3, gz / N * 3.3 + 13.9, 3), 0, 1);
        const jag = 0.5 + 0.5 * nA.fbm(gx / N * 14 - 37.1, gz / N * 14 + 52.7, 2);
        wobble = COAST_WOBBLE * broad + COAST_JAG * clamp(jag, 0, 1);
      }
      t -= wobble;
    }
    if (t < f) f = t < 0 ? 0 : t;
  }
  return f <= 0 ? 0 : f >= 1 ? 1 : f * f * (3 - 2 * f);
}

// ---------------- mountains as explicit shapes ----------------


/**
 * Every mountain whose flanks could reach this box, placed by hash on a global grid so a range runs
 * across as many cells as it needs. Each is a cone, or a ridge of them, at a slope the ground is
 * allowed to have — which is why the legaliser never gets to shred one into a chamfered pyramid,
 * and why a taller height cap would need nothing here but a bigger number.
 */
function peaksNear(seedHash: number, nB: Noise2D, x0: number, z0: number, x1: number, z1: number, rf: RegionField, geo: Geology): Peak[] {
  const reach = (PEAK_MAX + PEAK_UPLIFT) / (PEAK_SLOPE * 0.7) + RIDGE_MAX;
  const gi0 = Math.floor((x0 - reach) / PEAK_GRID), gi1 = Math.floor((x1 + reach) / PEAK_GRID);
  const gj0 = Math.floor((z0 - reach) / PEAK_GRID), gj1 = Math.floor((z1 + reach) / PEAK_GRID);
  const salt = seedHash & 0xffff;
  const out: Peak[] = [];
  for (let gj = gj0; gj <= gj1; gj++) {
    for (let gi = gi0; gi <= gi1; gi++) {
      const px = (gi + hash2(gi, gj, salt + 1)) * PEAK_GRID;
      const pz = (gj + hash2(gi, gj, salt + 2)) * PEAK_GRID;
      // where the ranges are: a slow field over three or four cells, so peaks come in company
      let massif = smoothstep(0.46, 0.7, 0.5 + 0.5 * nB.fbm(px / N * 0.3 + 61, pz / N * 0.3 + 17, 3));
      // a biome raises its ranges or flattens them, read where the peak stands so both sides agree
      const reg = rf.at(px, pz);
      const rs = reg.w > 0 ? regionOf(reg.k) : null;
      if (rs && rs.massif !== undefined) massif += (rs.massif - massif) * reg.w;
      // high country is mountain country, and its mountains stand taller
      const up = geo.uplift(px, pz);
      massif = Math.max(massif, 0.75 * up);
      // but a tableland country is flat-topped, not peaked
      if (up > 0.2) massif *= 1 - geo.tableGate(px, pz);
      if (massif <= 0.001) continue;
      if (hash2(gi, gj, salt + 3) > 0.3 + 0.65 * massif) continue;
      const cap = PEAK_MAX + PEAK_UPLIFT * up;
      let h = Math.min(cap, 4 + cap * massif * (0.4 + 0.6 * hash2(gi, gj, salt + 4)));
      if (rs && rs.peakCap !== undefined) h += (Math.min(h, rs.peakCap) - h) * reg.w;
      let x2 = px, z2 = pz;
      if (hash2(gi, gj, salt + 6) < 0.55) {
        // ridges in one massif line up, because the angle comes from a field, not from the site
        const ang = nB.fbm(px / N * 0.25 + 13, pz / N * 0.25 + 7, 2) * Math.PI * 2;
        const len = RIDGE_MAX * massif * (0.3 + 0.7 * hash2(gi, gj, salt + 7));
        x2 = px + Math.cos(ang) * len;
        z2 = pz + Math.sin(ang) * len;
      }
      const peak: Peak = { x: px, z: pz, x2, z2, h, slope: PEAK_SLOPE * (0.7 + 0.3 * hash2(gi, gj, salt + 5)) };
      // a pass notched into some ridges, a glacier off some cold high peaks
      decoratePeak(peak, seedHash, gi, gj);
      out.push(peak);
    }
  }
  return out;
}

// ---------------- helpers that take the grid width ----------------

/** Multi-source BFS distance (4-neighbour) from every tile where src[i] != 0, stopping at `cap`. */
function bfsDistance(src: Uint8Array, out: Uint16Array, W: number, cap: number): void {
  const WW = W * W;
  out.fill(cap);
  const queue = new Int32Array(WW);
  let head = 0, tail = 0;
  for (let i = 0; i < WW; i++) if (src[i]) { out[i] = 0; queue[tail++] = i; }
  while (head < tail) {
    const i = queue[head++];
    const nd = out[i] + 1;
    if (nd > cap) continue;
    const x = i % W, z = (i - x) / W;
    for (let d = 0; d < 4; d++) {
      const nx = x + DIRS[d][0], nz = z + DIRS[d][1];
      if (nx < 0 || nz < 0 || nx >= W || nz >= W) continue;
      const j = nz * W + nx;
      if (out[j] > nd) { out[j] = nd; queue[tail++] = j; }
    }
  }
}

/**
 * Thin an island down to its largest piece.
 *
 * A continent never goes through here: which component is the largest depends on how much of the
 * land the grid happens to cover, and two cells cover different ground, so the answer would differ
 * between them. Continental land is exactly where the global field says it is, rocks and all.
 */
function keepComponents(mask: Uint8Array, W: number, edgeCounts: boolean, minSize: number): number {
  const WW = W * W;
  const label = new Int32Array(WW).fill(-1);
  const sizes: number[] = [];
  const edge: boolean[] = [];
  const queue = new Int32Array(WW);
  for (let s = 0; s < WW; s++) {
    if (!mask[s] || label[s] >= 0) continue;
    const id = sizes.length;
    let head = 0, tail = 0, size = 0, touches = false;
    queue[tail++] = s; label[s] = id;
    while (head < tail) {
      const i = queue[head++]; size++;
      const x = i % W, z = (i - x) / W;
      if (x === 0 || z === 0 || x === W - 1 || z === W - 1) touches = true;
      for (let d = 0; d < 4; d++) {
        const nx = x + DIRS[d][0], nz = z + DIRS[d][1];
        if (nx < 0 || nz < 0 || nx >= W || nz >= W) continue;
        const j = nz * W + nx;
        if (mask[j] && label[j] < 0) { label[j] = id; queue[tail++] = j; }
      }
    }
    sizes.push(size);
    edge.push(touches);
  }
  let big = 0;
  for (let k = 1; k < sizes.length; k++) if (sizes[k] > sizes[big]) big = k;
  let count = 0;
  for (let i = 0; i < WW; i++) {
    if (mask[i]) {
      const k = label[i];
      if (!(k === big || (edgeCounts && (edge[k] || sizes[k] >= minSize)))) mask[i] = 0;
    }
    if (mask[i]) count++;
  }
  return count;
}

/** An all-ocean cell: nothing to generate, and its sea bed lines up with every neighbour's rim. */
function emptySea(w: World): World {
  w.water.fill(SEA);
  w.corners.fill(RIM_DEPTH);
  w.biome.fill(Biome.Ocean);
  w.elev.fill(RIM_DEPTH);
  w.coastDist.fill(0);
  w.spawn = { x: N / 2 + 0.5, z: N / 2 + 0.5, heading: 0 };
  return w;
}

/**
 * Lay the causeway decks into the tile corners as one smooth surface a road can take. Every corner
 * of a deck that touches the ground it lands on takes that ground's own corner, so the two meet
 * flush however the shore was eased; from there the deck climbs or falls one step a tile at most
 * to SEA + 1, and on the border it is SEA + 1 exactly, so both halves of a causeway agree.
 */
function layDecks(c: Int8Array, causeway: Uint8Array, land: Uint8Array, E: Float32Array): void {
  const V = N + 1;
  // the tile touching each corner of a tile, and which of its corners that is (0 NW, 1 NE, 2 SE, 3 SW)
  const around = (vx: number, vz: number): [number, number][] => {
    const out: [number, number][] = [];
    for (const [dx, dz, k] of [[-1, -1, 2], [0, -1, 3], [-1, 0, 1], [0, 0, 0]] as const) {
      const tx = vx + dx, tz = vz + dz;
      if (inB(tx, tz)) out.push([idx(tx, tz), k]);
    }
    return out;
  };
  // ground a deck lands on: real land, never a skerry it happens to pass
  const ground = landingMask(land.map((v, i) => (causeway[i] ? 0 : v)));
  const deck = new Uint8Array(V * V);
  const g = new Float32Array(V * V).fill(NaN);
  const dist = new Int32Array(V * V).fill(-1);
  const queue: number[] = [];
  for (let vz = 0; vz < V; vz++) {
    for (let vx = 0; vx < V; vx++) {
      const v = vz * V + vx;
      let isDeck = false, h = NaN;
      for (const [t, k] of around(vx, vz)) {
        if (causeway[t]) isDeck = true;
        else if (ground[t] && Number.isNaN(h)) h = c[t * 4 + k];
      }
      if (!isDeck) continue;
      deck[v] = 1;
      if (!Number.isNaN(h)) { g[v] = h; dist[v] = 0; queue.push(v); }
    }
  }
  // spread each landing's height along the deck, remembering how far it has come
  for (let q = 0; q < queue.length; q++) {
    const v = queue[q], vx = v % V, vz = (v - vx) / V;
    for (const [dx, dz] of DIRS) {
      const nx = vx + dx, nz = vz + dz;
      if (nx < 0 || nz < 0 || nx >= V || nz >= V) continue;
      const u = nz * V + nx;
      if (!deck[u] || dist[u] >= 0) continue;
      dist[u] = dist[v] + 1;
      g[u] = g[v];
      queue.push(u);
    }
  }
  const lv = SEA + 1;
  const height = (vx: number, vz: number, t: number): number => {
    const v = vz * V + vx;
    // never further from SEA + 1 than a step a tile from the border allows
    const reach = Math.min(vx, vz, N - vx, N - vz);
    if (dist[v] < 0) return clamp(Math.round(E[t]), lv - reach, lv + reach);
    const ramp = Math.max(CAUSEWAY_RAMP, Math.abs(g[v] - lv));
    return clamp(Math.round(g[v] + (lv - g[v]) * Math.min(1, dist[v] / ramp)), lv - reach, lv + reach);
  };
  const out = new Int8Array(NN * 4);
  for (let i = 0; i < NN; i++) {
    if (!causeway[i]) continue;
    const x = i % N, z = (i - x) / N;
    out[i * 4] = height(x, z, i);
    out[i * 4 + 1] = height(x + 1, z, i);
    out[i * 4 + 2] = height(x + 1, z + 1, i);
    out[i * 4 + 3] = height(x, z + 1, i);
  }
  for (let i = 0; i < NN; i++) {
    if (!causeway[i]) continue;
    for (let q = 0; q < 4; q++) c[i * 4 + q] = out[i * 4 + q];
  }
}

/** A causeway's landing must be a piece of land at least this many tiles, so a skerry never ends one short. */
const LANDING_MIN = 64;
/** Nor a sandbar off the side of it: a landing is part of a piece at least this share of the biggest. */
const LANDING_SHARE = 0.1;

/** 1 on every tile of a 4-connected piece of land big enough to land on: LANDING_MIN tiles and a LANDING_SHARE of the biggest, or the biggest. */
function landingMask(land: Uint8Array): Uint8Array {
  const label = new Int32Array(NN).fill(-1);
  const sizes: number[] = [];
  const stack: number[] = [];
  for (let s = 0; s < NN; s++) {
    if (!land[s] || label[s] >= 0) continue;
    const k = sizes.length;
    let size = 0;
    label[s] = k;
    stack.push(s);
    while (stack.length) {
      const i = stack.pop()!;
      size++;
      const x = i % N, z = (i - x) / N;
      for (let d = 0; d < 4; d++) {
        const nx = x + DIRS[d][0], nz = z + DIRS[d][1];
        if (!inB(nx, nz)) continue;
        const j = idx(nx, nz);
        if (land[j] && label[j] < 0) { label[j] = k; stack.push(j); }
      }
    }
    sizes.push(size);
  }
  const biggest = sizes.reduce((a, b) => Math.max(a, b), 0);
  const need = Math.min(biggest, Math.max(LANDING_MIN, Math.ceil(biggest * LANDING_SHARE)));
  const out = new Uint8Array(NN);
  for (let i = 0; i < NN; i++) if (label[i] >= 0 && sizes[label[i]] >= need) out[i] = 1;
  return out;
}

/**
 * The causeways leaving this island. Each runs straight inland from its landing on the border
 * until it meets the island, rising over the last stretch to meet the ground it lands on.
 */
function carveCauseways(w: World, seedHash: number, land: Uint8Array, E: Float32Array, causeway: Uint8Array, again = false): void {
  /** Land a causeway may end on: not a skerry or a speck, but a piece at least LANDING_MIN big (or the biggest there is). */
  let solidMask: Uint8Array | null = null;
  const solid = (i: number): boolean => {
    if (!solidMask) {
      // laid again, the old deck is neither a landing nor what makes the land it touches big enough
      const ground = again ? land.map((v, i) => (causeway[i] ? 0 : v)) : land;
      solidMask = landingMask(ground);
    }
    if (solidMask[i] !== 1) return false;
    if (!again) return true;
    // laid again after a channel was cut: never onto the ragged, half-drowned bank it leaves
    const x = i % N, z = (i - x) / N;
    for (let dz = -1; dz <= 1; dz++) for (let dx = -1; dx <= 1; dx++) {
      if (inB(x + dx, z + dz) && solidMask[idx(x + dx, z + dz)] !== 1) return false;
    }
    return true;
  };
  for (let d = 0; d < 4; d++) {
    const at = straitAt(seedHash, w.cx, w.cz, d);
    if (at < 0 || (again && !w.straits.some((s) => s.dir === d))) continue;
    const [dx, dz] = DIRS[d];
    // start on the border tile and walk inland (against d)
    const sx = d === 0 ? N - 1 : d === 2 ? 0 : clamp(at, 2, N - 3);
    const sz = d === 1 ? N - 1 : d === 3 ? 0 : clamp(at, 2, N - 3);
    /** Each tile of the embankment, and which way it is widened: across whichever leg it is on. */
    const run: { i: number; wx: number; wz: number }[] = [];
    let hit = -1;
    for (let k = 0; k < N; k++) {
      const x = sx - dx * k, z = sz - dz * k;
      if (!inB(x, z)) break;
      const i = idx(x, z);
      if (solid(i) && k > RIM && E[i] - SEA - 1 <= k * LANDING_GRADE) { hit = i; break; }
      run.push({ i, wx: dx ? 0 : 1, wz: dz ? 0 : 1 });
    }
    if (hit < 0) {
      // The straight line misses this island altogether. The neighbour builds its half from the
      // same landing whatever happens here, so rather than leave that half ending in open water,
      // head in until level with the nearest land and turn along the shore to meet it.
      let best = -1, bestD = Infinity;
      for (let i = 0; i < NN; i++) {
        if (!solid(i)) continue;
        const x = i % N, z = (i - x) / N;
        const lat = d % 2 === 0 ? z : x;
        if (lat < 48 || lat >= N - 48) continue;   // never swing out toward another border
        const dd = Math.hypot(x - sx, z - sz);
        if (dd < bestD) { bestD = dd; best = i; }
      }
      if (best < 0) continue;
      const bx = best % N, bz = (best - bx) / N;
      const depth = d % 2 === 0 ? Math.abs(bx - sx) : Math.abs(bz - sz);
      const lat = d % 2 === 0 ? bz - sz : bx - sx;
      // square off the border for long enough that both cells agree and the flare clears it, then sweep
      // round to the island on a curve rather than turning a right angle out at sea
      const square = Math.min(depth, RIM + CAUSEWAY_FLARE + 6);
      const path: [number, number][] = [];
      for (let k = 0; k <= square; k++) path.push([sx - dx * k, sz - dz * k]);
      const p1x = sx - dx * square, p1z = sz - dz * square;
      const cnx = sx - dx * depth, cnz = sz - dz * depth;
      const steps = Math.max(8, 4 * (depth - square + Math.abs(lat)));
      for (let s2 = 1; s2 <= steps; s2++) {
        const t = s2 / steps, u = 1 - t;
        const qx = Math.round(u * u * p1x + 2 * u * t * cnx + t * t * bx);
        const qz = Math.round(u * u * p1z + 2 * u * t * cnz + t * t * bz);
        const [lx, lz] = path[path.length - 1];
        if (qx === lx && qz === lz) continue;
        // keep the strip 4-connected: a diagonal hop goes by way of the tile along the curve's heading
        if (qx !== lx && qz !== lz) {
          const hx = 2 * u * (cnx - p1x) + 2 * t * (bx - cnx), hz = 2 * u * (cnz - p1z) + 2 * t * (bz - cnz);
          path.push(Math.abs(hx) >= Math.abs(hz) ? [qx, lz] : [lx, qz]);
        }
        path.push([qx, qz]);
      }
      run.length = 0;
      let x = sx, z = sz;
      for (let k = 0; k < path.length; k++) {
        [x, z] = path[k];
        if (!inB(x, z)) break;
        const i = idx(x, z);
        if (solid(i) && run.length > RIM && E[i] - SEA - 1 <= run.length * LANDING_GRADE) { hit = i; break; }
        // widened across whichever way the strip is heading here
        const [nx, nz] = path[Math.min(path.length - 1, k + 1)], [px, pz] = path[Math.max(0, k - 1)];
        const alongX = Math.abs(nx - px) >= Math.abs(nz - pz);
        run.push({ i, wx: alongX ? 0 : 1, wz: alongX ? 1 : 0 });
      }
    }
    if (hit < 0 || run.length < 2) continue;
    const target = Math.max(SEA + 1, E[hit]);
    const ramp = Math.min(Math.max(CAUSEWAY_RAMP, Math.ceil((target - SEA - 1) / LANDING_GRADE)), run.length - 1);
    run.forEach(({ i, wx, wz }, k) => {
      const fromEnd = run.length - 1 - k;
      const t = ramp > 0 ? clamp(1 - fromEnd / ramp, 0, 1) : 0;
      const h = SEA + 1 + (target - SEA - 1) * t;
      const x = i % N, z = (i - x) / N;
      // the last few tiles flare out, clear of the border, so no water beside the landing drags the shore under the deck
      const half = fromEnd < CAUSEWAY_FLARE && k > RIM + CAUSEWAY_FLARE ? CAUSEWAY_HALF + CAUSEWAY_FLARE - fromEnd : CAUSEWAY_HALF;
      for (let o = -half; o <= half; o++) {
        const ax = x + wx * o, az = z + wz * o;
        if (!inB(ax, az)) continue;
        const j = idx(ax, az);
        if (Math.abs(o) > CAUSEWAY_HALF && land[j]) continue;
        land[j] = 1;
        E[j] = t > 0.5 ? Math.max(E[j], h) : h;
        causeway[j] = 1;
        // only the flat seaward stretch gets walls; the ramp blends into the island
        if (t < 0.5) w.flags[j] |= Flag.Corridor;
      }
    });
    // and the shore either side of the tile it lands on is filled in to the landing's height
    {
      const { wx, wz } = run[run.length - 1];
      const x = hit % N, z = (hit - x) / N;
      if (run.length - 1 > RIM + CAUSEWAY_FLARE) {
        for (let o = -(CAUSEWAY_HALF + CAUSEWAY_FLARE); o <= CAUSEWAY_HALF + CAUSEWAY_FLARE; o++) {
          const ax = x + wx * o, az = z + wz * o;
          if (!inB(ax, az)) continue;
          const j = idx(ax, az);
          if (land[j]) continue;
          land[j] = 1;
          E[j] = target;
          causeway[j] = 1;
        }
      }
    }
    if (!again) w.straits.push({ dir: d, at: d % 2 === 0 ? sz : sx, half: CAUSEWAY_HALF });
  }
}

// ---------------- rivers across a county border ----------------

/** How far either side of its border a river crossing's channel runs: exactly the seam band. */
const RIVER_REACH = SEAM_BAND;
/** How far a crossing's channel may wander to either side of its line, in tiles. */
const RIVER_WANDER = 3;

/** A river crossing, in global tiles: every tile of its channel, and the inner end on each side. */
interface Channel { tiles: [number, number][]; ends: [[number, number], [number, number]] }

/**
 * The channel a river cuts across the border above or to the east of cell (ax, az): along x when
 * `axis` is 0, along z when it is 1. A pure function of the shared edge, so the county on each
 * side cuts precisely the same trench through the strip of ground they both work out.
 */
function riverChannel(seedHash: number, ax: number, az: number, axis: number): Channel | null {
  const d = axis === 0 ? 0 : 1;
  const at = riverAt(seedHash, ax, az, d);
  if (at < 0) return null;
  const phase = riverPhase(seedHash, ax, az, d);
  const border = axis === 0 ? (ax + 1) * N : (az + 1) * N;
  const base = axis === 0 ? az * N + at : ax * N + at;
  // it crosses the line itself squarely and wanders once it is clear of it
  const off = (t: number) => Math.round(RIVER_WANDER * Math.sin(phase + t * 0.13) * Math.min(1, Math.abs(t + 0.5) / 12));
  const tile = (t: number, o: number): [number, number] => (axis === 0 ? [border + t, base + o] : [base + o, border + t]);
  const tiles: [number, number][] = [];
  let last = off(-RIVER_REACH);
  for (let t = -RIVER_REACH; t < RIVER_REACH; t++) {
    const o = off(t);
    // a sideways step claims every tile between, so the channel stays 4-connected
    for (let k = Math.min(o, last); k <= Math.max(o, last); k++) tiles.push(tile(t, k));
    last = o;
  }
  return { tiles, ends: [tile(-RIVER_REACH, off(-RIVER_REACH)), tile(RIVER_REACH - 1, off(RIVER_REACH - 1))] };
}

/**
 * Carry a river crossing on into the county: the cheapest way, downhill by preference, from the
 * inner end of its channel to a river or a lake already there. Where none is in reach it runs on
 * a short way as a stream, so it never simply stops at the edge of the band.
 */
function joinRiver(
  land: Uint8Array, river: Uint8Array, lakeLvl: Int8Array, E: Float32Array, band: number, sx: number, sz: number, salt = 0,
): boolean {
  const lo = band, hi = N - band;
  if (sx < lo || sz < lo || sx >= hi || sz >= hi) return false;
  const start = idx(sx, sz);
  if (!land[start]) return false;
  const cost = new Float32Array(NN).fill(Infinity);
  const prev = new Int32Array(NN).fill(-1);
  const heap = new MinHeap();
  cost[start] = 0;
  heap.push(0, start);
  let found = -1, lowest = start;
  while (heap.size) {
    const i = heap.pop();
    if (river[i] >= 2 || lakeLvl[i] > -128) { found = i; break; }
    if (cost[i] > 420) break;
    if (cost[i] < 40 && E[i] < E[lowest]) lowest = i;
    const x = i % N, z = (i - x) / N;
    for (let d = 0; d < 4; d++) {
      const nx = x + DIRS[d][0], nz = z + DIRS[d][1];
      if (nx < lo || nz < lo || nx >= hi || nz >= hi) continue;
      const j = idx(nx, nz);
      if (!land[j]) continue;
      // rounded to the array's own precision, or a cost stored rounded up would queue the tile forever
      // a slow field of easier and harder ground, or every equally cheap way is a ruler-straight run
      const c = Math.fround(cost[i] + 1 + 2.5 * Math.max(0, E[j] - E[i]) + 1.6 * cellNoise(salt, nx, nz, 11, 917));
      if (c < cost[j]) { cost[j] = c; prev[j] = i; heap.push(c, j); }
    }
  }
  const end = found >= 0 ? found : lowest;
  const kind = found >= 0 ? 2 : 1;
  for (let i = end; i >= 0; i = prev[i]) if (lakeLvl[i] <= -128 && river[i] < kind) river[i] = kind;
  return found >= 0;
}

/**
 * Lakes: the sinks an inland county needs, having no ocean for its rivers to reach.
 *
 * Each is a smooth bowl, dug at a gentler slope than the ground is allowed anywhere else, so its
 * rim needs no legalising and no cascade can start there.
 */
function digLakes(
  w: World, land: Uint8Array, lakeLvl: Int8Array, rng: () => number, band: number, want: number, noTown: Uint8Array,
): number {
  const E = w.elev;
  const made: [number, number, number][] = [];
  const keep = band + 24;
  const span = N - 2 * keep;
  if (span < 20) return 0;
  for (let tries = 0; tries < 400 && made.length < want; tries++) {
    const x = keep + Math.floor(rng() * span);
    const z = keep + Math.floor(rng() * span);
    const i = idx(x, z);
    // never on a mountain's top: a lake wants a basin, and a summit is not one
    if (!land[i] || E[i] < SEA + 2.5 || w.coastDist[i] < 24 || w.biome[i] === Biome.Mountain || w.biome[i] === Biome.Snow || w.biome[i] === Biome.Canyon) continue;
    if (made.some(([mx, mz, mr]) => Math.hypot(mx - x, mz - z) < mr * 3)) continue;
    const depth = 3 + Math.floor(rng() * 3);
    const R = depth * 2 + 3;
    const level = Math.round(E[i]) - 1;
    // a lobed, stretched bowl rather than a stamped circle; the bays keep its sides as gentle
    const shape = blobScale(w.ox + x, w.oz + z, 4401);
    const reach = Math.ceil(R * 1.35);
    for (let dz = -reach; dz <= reach; dz++) {
      for (let dx = -reach; dx <= reach; dx++) {
        if (!inB(x + dx, z + dz)) continue;
        const d = Math.hypot(dx, dz) / shape(Math.atan2(dz, dx));
        if (d > R) continue;
        const j = idx(x + dx, z + dz);
        if (!land[j]) continue;
        const t = 1 - d / R;
        E[j] -= depth * t * t * (3 - 2 * t);
        if (E[j] < level - 0.2) { lakeLvl[j] = level; w.biome[j] = Biome.Ocean; }
        // no town on the lake or its shore: a town's pad would raise the ground and leave the lake's
        // level standing over its streets
        noTown[j] = 1;
      }
    }
    made.push([x, z, R]);
  }
  return made.length;
}

/** A watercourse shorter than this that reaches no water is dropped rather than given a pond. */
const STUB_RIVER = 30;

/**
 * Every river and stream must end somewhere: the sea, a lake, or a river crossing the county's border.
 * A course the seam band cut short, a town sat on, or a joining stream ran out of reach on, reaches
 * none of them. A short one is dropped; a longer one ends in a pond dug at its lowest tile (or the
 * lowest nearby that is clear of towns, fields, works and the band), the way a real stream ends in a mere.
 */
function tidyRivers(
  w: World, river: Uint8Array, land: Uint8Array, E: Float32Array, lakeLvl: Int8Array, noTown: Uint8Array, band: number,
  towns: { x0: number; z0: number; size: number }[], works: { x: number; z: number; len: number; half: number }[],
  causeway: Uint8Array, mouths: number[], salt: number,
): void {
  const seen = new Uint8Array(NN);
  const inBand = (x: number, z: number) => band > 0 && (x < band || z < band || x >= N - band || z >= N - band);
  const mouthNear = (x: number, z: number) => mouths.some((m) => Math.abs((m % N) - x) + Math.abs(Math.floor(m / N) - z) <= 3);
  const clearFor = (x: number, z: number, R: number): boolean => {
    const m = Math.ceil(R * 1.35) + 2;
    if (inBand(x - m, z - m) || inBand(x + m, z + m) || x - m < 2 || z - m < 2 || x + m >= N - 2 || z + m >= N - 2) return false;
    for (const t of towns) if (x + m >= t.x0 - 3 && x - m < t.x0 + t.size + 3 && z + m >= t.z0 - 3 && z - m < t.z0 + t.size + 3) return false;
    for (const g of works) if (Math.hypot(x - g.x, z - g.z) < Math.max(g.len, g.half) + m + 4) return false;
    for (let dz = -m; dz <= m; dz++) for (let dx = -m; dx <= m; dx++) {
      const j = idx(x + dx, z + dz);
      if (!land[j] || causeway[j] || w.feature[j] || (w.flags[j] & Flag.Field) || w.biome[j] === Biome.Town) return false;
    }
    return true;
  };
  for (let s0 = 0; s0 < NN; s0++) {
    if (!river[s0] || river[s0] === 3 || seen[s0]) continue;
    const q = [s0];
    seen[s0] = 1;
    let out = false, low = s0;
    for (let h = 0; h < q.length; h++) {
      const i = q[h], x = i % N, z = (i - x) / N;
      if (E[i] < E[low]) low = i;
      for (let d = 0; d < 4; d++) {
        const nx = x + DIRS[d][0], nz = z + DIRS[d][1];
        if (!inB(nx, nz)) continue;
        const j = idx(nx, nz);
        if (river[j] === 3) out = true;
        else if (river[j] && !seen[j]) { seen[j] = 1; q.push(j); }
      }
    }
    // the water must reach the sea, a lake or a border crossing at its downstream end, not merely leave one
    if (!out) {
      for (const i of q) {
        if (E[i] > E[low] + 0.2) continue;
        const x = i % N, z = (i - x) / N;
        // flowing out over the border by a river crossing counts as getting somewhere
        if (mouthNear(x, z)) { out = true; break; }
        for (let d = 0; d < 4 && !out; d++) {
          const nx = x + DIRS[d][0], nz = z + DIRS[d][1];
          if (inB(nx, nz) && (!land[idx(nx, nz)] || lakeLvl[idx(nx, nz)] > -128)) out = true;
        }
        if (out) break;
      }
    }
    if (out) continue;
    if (q.length < STUB_RIVER) { for (const i of q) river[i] = 0; continue; }
    // a pond at the lowest tile that has room for one
    const byLow = q.slice().sort((a, b) => E[a] - E[b]);
    const R = 4 + Math.min(3, Math.floor(q.length / 60));
    const at = byLow.find((i) => clearFor(i % N, Math.floor(i / N), R));
    // nowhere to dig one: a modest stream goes, a real river stays as it is
    if (at === undefined) { if (q.length < STUB_RIVER * 3) for (const i of q) river[i] = 0; continue; }
    const px = at % N, pz = (at - px) / N;
    const level = Math.round(E[at]);
    // the stretch below the pond, run on to the band or the town that cut it, goes with the cut
    for (const i of q) if (E[i] < E[at] - 0.05) river[i] = 0;
    const shape = blobScale(w.ox + px, w.oz + pz, 4461 + (salt & 0xff));
    const reach = Math.ceil(R * 1.35);
    for (let dz = -reach; dz <= reach; dz++) {
      for (let dx = -reach; dx <= reach; dx++) {
        const d = Math.hypot(dx, dz) / shape(Math.atan2(dz, dx));
        if (d > R) continue;
        const j = idx(px + dx, pz + dz);
        const t = 1 - d / R;
        E[j] -= 2.5 * t * t * (3 - 2 * t);
        if (E[j] < level - 0.2) { lakeLvl[j] = level; w.biome[j] = Biome.Ocean; river[j] = 0; }
        noTown[j] = 1;
      }
    }
  }
}

export function generateWorld(seed: string, cx = 0, cz = 0): World {
  const t0 = performance.now();
  const w = new World();
  w.seed = seed;
  w.cx = cx;
  w.cz = cz;
  w.ox = cx * N;
  w.oz = cz * N;
  // the world mode rides on the seed; the hash stays the whole string's, suffix and all
  setWorldMode(parseSeed(seed).mode);
  const seedHash = hashString(seed);
  const h = hashCell(seedHash, cx, cz);
  w.kind = cellKind(seedHash, cx, cz);
  w.name = cellName(seedHash, cx, cz, w.kind);
  if (w.kind === 'sea') {
    emptySea(w);
    // the railway still crosses the open sea, on a viaduct
    if (railLines(seedHash, cx, cz).length) {
      const NN0 = N * N;
      const ctx: RailCtx = {
        w, seedHash, land: new Uint8Array(NN0), E: w.elev, river: new Uint8Array(NN0), lakeLvl: new Int8Array(NN0).fill(-128),
        towns: [], works: [], fields: [], causeway: new Uint8Array(NN0), pE0: null, pLand0: null, P, PAD,
      };
      finishRail(ctx, planRail(ctx));
    }
    w.stats.genMs = performance.now() - t0;
    return w;
  }
  const cont = w.kind === 'continent';
  /** A cell with open water on it: every island has some, an inland county has none. */
  const coastal = !cont || coastalContinent(seedHash, cx, cz);
  if (cont) w.continent = continentName(seedHash, cx, cz);
  // the biome this cell belongs to, and how far into one every tile of the padded grid is
  const rf = new RegionField(seedHash);
  const ownRegion = rf.cellRegion(cx, cz);
  w.region = ownRegion ? REGION_KINDS[ownRegion - 1] : null;
  const spec = w.region ? REGIONS[w.region] : null;
  const shape = regionShape(SHAPES[w.kind], spec, w.kind);
  w.mega = hasMega(seedHash, cx, cz);
  const rng = mulberry32(h);
  const [nA, nB] = noiseFor(seedHash);
  /** Salt for every per-tile hash on this cell, so no two cells share a pattern. */
  const salt = h & 0xffff;
  const ox = w.ox, oz = w.oz;
  /** Tiles kept clear of anything stochastic, so no local edit can reach a border land shares. */
  const band = cont ? SEAM_BAND : 0;

  // the kinds of the cells this padded grid reaches into, looked up once rather than per tile
  const kindCache = new Map<number, CellKind>();
  const kinds = (kx: number, kz: number): CellKind => {
    const k = (kx + 4096) * 8192 + (kz + 4096);
    let v = kindCache.get(k);
    if (v === undefined) { v = cellKind(seedHash, kx, kz); kindCache.set(k, v); }
    return v;
  };

  const geo = geologyFor(seedHash);
  const peaks = peaksNear(seedHash, nB, ox - PAD, oz - PAD, ox + N + PAD, oz + N + PAD, rf, geo);
  const lf = new Landforms(seedHash, cx, cz, w.kind, nA, nB, peaks);
  lf.fjordBoost = (gx, gz) => {
    const reg = rf.at(gx, gz);
    return reg.w > 0 && regionOf(reg.k)?.fjords ? reg.w : 0;
  };

  // the continent's own geology: great ranges, tablelands and the rivers that drain them, all in global tiles
  const ranges: Range[] = cont ? geo.rangesNear(ox - PAD, oz - PAD, ox + N + PAD, oz + N + PAD) : [];
  const riverNet = cont ? geo.riversNear(ox - PAD, oz - PAD, ox + N + PAD, oz + N + PAD) : { edges: [], lakes: [], mouths: [] };
  const rr = geo.rasterRivers(riverNet, ox - PAD, oz - PAD, P);

  // ======== 1. the land, on a grid padded into every neighbour ========
  const pLand = new Uint8Array(PP);
  const pE = new Float32Array(PP);
  const pFade = new Float32Array(PP);
  {
    const L = new Float32Array(PP);
    for (let pz = 0; pz < P; pz++) {
      const gz = oz + pz - PAD;
      for (let px = 0; px < P; px++) {
        const gx = ox + px - PAD;
        const i = pz * P + px;
        const fade = landFade(gx, gz, kinds, nA);
        pFade[i] = fade;
        const own = px >= PAD && px < PAD + N && pz >= PAD && pz < PAD + N;
        if (!own && kinds(Math.floor(gx / N), Math.floor(gz / N)) !== 'continent') { L[i] = -9; continue; }
        const u = gx / N, v = gz / N;
        if (own && lf.atoll) {
          // an atoll: a ring of motus round a lagoon, nothing in the middle
          L[i] = lf.atollLand(gx, gz);
        } else if (own && !cont) {
          // an island: a radial falloff pulls its coast in from the border
          const dx = ((px - PAD) / N - 0.5) * 2, dz = ((pz - PAD) / N - 0.5) * 2;
          const d = Math.sqrt(dx * dx + dz * dz);
          const wx = nA.fbm(u * 2 + 3.1, v * 2 + 7.7, 2) * 0.12;
          const wz = nA.fbm(u * 2 - 5.2, v * 2 + 1.3, 2) * 0.12;
          L[i] = nA.fbm((u + wx) * 2.6, (v + wz) * 2.6, 4) * 0.7 + (1 - Math.pow(d, 1.5) * shape.falloff) - lf.fjordCut(u, v, false);
        } else {
          // a continent: land wherever the macro field is over its threshold, with a fractal coast,
          // and in cold cliff country the sea let in along the fjords
          const macro = contField(seedHash, u, v) - CONT_THR;
          const coast = nA.fbm(u * 1.16 + 3.1, v * 1.16 + 7.7, 3) * 0.055 + nA.fbm(u * 4.3 - 5.2, v * 4.3 + 1.3, 2) * 0.022;
          L[i] = (macro + coast) * 8 * fade + (fade - 1) * 2 - lf.fjordCut(u, v, true) * fade;
        }
      }
    }
    for (let i = 0; i < PP; i++) pLand[i] = L[i] > 0 && pFade[i] > 0 ? 1 : 0;
    if (!cont) {
      // an island's water share is a percentile of its own tiles, exactly as it always was, and
      // only its own land is thinned: the pad beyond it is whatever its neighbours hold
      const own = new Float32Array(NN);
      for (let z = 0; z < N; z++) for (let x = 0; x < N; x++) own[z * N + x] = L[(z + PAD) * P + x + PAD];
      const thr = lf.atoll ? 0 : own.sort()[Math.floor(NN * shape.water)];
      const inner = new Uint8Array(NN);
      for (let z = 0; z < N; z++) {
        for (let x = 0; x < N; x++) {
          const p = (z + PAD) * P + x + PAD;
          inner[z * N + x] = L[p] > thr && pFade[p] > 0 ? 1 : 0;
        }
      }
      // an atoll is all its motus, not only the biggest
      if (!lf.atoll) keepComponents(inner, N, false, 0);
      for (let z = 0; z < N; z++) for (let x = 0; x < N; x++) pLand[(z + PAD) * P + x + PAD] = inner[z * N + x];
    }
  }

  // ======== 2. distances ========
  const pCoast = new Uint16Array(PP);
  const pOcean = new Uint16Array(PP);
  const seaMask = new Uint8Array(PP);
  const redistance = (): void => {
    for (let i = 0; i < PP; i++) seaMask[i] = pLand[i] ? 0 : 1;
    bfsDistance(seaMask, pCoast, P, COAST_CAP);
    // one past the skerries' reach, so open sea beyond it never reads as within it
    bfsDistance(pLand, pOcean, P, SKERRY_REACH + 1);
  };
  redistance();
  PROBE.on?.('pLand', pLand.slice());
  PROBE.on?.('pCoast', pCoast.slice());

  // ======== 3. climate, elevation and biomes, all sampled in global tiles ========
  const pMountMask = new Float32Array(PP);
  const pCliff = new Uint8Array(PP);
  const pMoist = new Float32Array(PP);
  const pBiome = new Uint8Array(PP);
  const pFlags = new Uint8Array(PP);
  const pTemp = new Float32Array(PP);
  const pSurf = new Uint8Array(PP);
  const pNoTown = new Uint8Array(PP);
  const pLakeHint = new Int8Array(PP).fill(-128);
  const pMesa = new Float32Array(PP);
  const pBad = new Float32Array(PP);
  const pRegK = new Uint8Array(PP);
  const pRegW = new Float32Array(PP);
  /** The ground before any mountain stood on it, and the lift under it: relief is measured from here. */
  const pBase = new Float32Array(PP);
  /** A great range's walled core, a canyon's walls, and the stepped ground a mountain keeps above its line. */
  const pCore = new Float32Array(PP);
  const pCanyonWall = new Float32Array(PP);
  const pTerr = new Float32Array(PP);
  /** How high snow lies here all year, in steps (0 for the ordinary line). */
  const pSnow = new Uint8Array(PP);
  /** A bench levelled for a mountain village, and a mesa or tableland top. */
  const pBench = new Uint8Array(PP);
  let fjordTiles = 0, fjordX = 0, fjordZ = 0, duneTiles = 0, duneX = 0, duneZ = 0, badTiles = 0, badX = 0, badZ = 0, skerries = 0, skX = 0, skZ = 0, riftTiles = 0, riftX = 0, riftZ = 0;
  const ctx: TileCtx = { gx: 0, gz: 0, u: 0, v: 0, cd: 0, moisture: 0, temp: 0, arid: 0, hillMask: 0, e: 0, mount: 0, biome: 255, surface: 0, mask: -1, noTown: false, mesaWall: false, lake: -128, regionErg: 0, regionBad: 0, lift: 0 };
  {
    for (let pz = 0; pz < P; pz++) {
      const gz = oz + pz - PAD;
      for (let px = 0; px < P; px++) {
        const gx = ox + px - PAD;
        const i = pz * P + px;
        const u = gx / N, v = gz / N;
        const cd = pCoast[i];

        // how far into a biome this tile is: its climate is pulled toward the biome's by that much
        const reg = rf.at(gx, gz);
        const rw = reg.w, rs = rw > 0 ? regionOf(reg.k) : null;
        pRegK[i] = reg.k;
        pRegW[i] = rw;
        // the wet/dry band climateAt reads, some cells across: a dry country's forests thin out and a
        // wet country's dry hollows stay green, so desert and forest meet at a band's edge, not everywhere
        const wetBand = cellNoise(seedHash, u, v, 3.1, 43);
        let moisture = clamp(0.5 + 0.55 * nA.fbm(u * 3.5 + 17, v * 3.5 + 29, 3) + (wetBand - 0.5) * 0.35, 0, 1);
        if (rs && rs.moisture !== undefined) moisture += (rs.moisture - moisture) * rw;
        // temperature is a band across the whole lattice, read at the tile rather than once per cell,
        // so it runs on smoothly over every border: the band climateAt reads, plus a local wobble
        const warm = clamp(1.25 - v * 0.055 + (cellNoise(seedHash, u, v, 5.5, 7) - 0.5) * 0.7, -0.15, 1.15);
        let tempRaw = clamp(warm + (cellNoise(seedHash, u, v, 9, 11) - 0.5) * 0.25 + 0.12 * nA.fbm(u * 4 + 51, v * 4 + 3, 2), 0, 1);
        if (rs && rs.temperature !== undefined) tempRaw += (rs.temperature - tempRaw) * rw;
        // a continent's heart dries out into steppe and desert while its coasts stay green
        const inland = continentality(seedHash, u, v) * smoothstep(8, 30, cd);
        // and only dry country turns to desert, however far inland
        const dryBand = smoothstep(0.5, 0.34, wetBand);
        let arid = clamp((smoothstep(0.38, 0.26, moisture) * smoothstep(0.45, 0.62, tempRaw) + 0.4 * inland) * dryBand, 0, 1);
        if (rs && rs.arid !== undefined) arid += (rs.arid - arid) * rw;
        pMoist[i] = moisture;
        pTemp[i] = tempRaw;

        if (!pLand[i]) {
          // skerries off a cliff coast: islets agreed by every cell that can see them
          const sk = lf.skerry(gx, gz, u, v, pOcean[i], pFade[i]);
          if (sk > 0 && !lf.inLagoon(gx, gz) && !(rs && rw > 0.5 && rs.forbid?.includes('skerries'))) {
            pLand[i] = 1;
            pE[i] = SEA + sk;
            pBiome[i] = Biome.SeaCliff;
            pCliff[i] = 1;
            pNoTown[i] = 1;
            if (px >= PAD && pz >= PAD && px < PAD + N && pz < PAD + N) { skerries++; skX += px - PAD; skZ += pz - PAD; }
            continue;
          }
          // the shelf falls away from every shore alike, to the rim's depth nine tiles out; dropping straight
          // to it beside a shore in the fade-free band dragged that shore's corners under the water
          pE[i] = Math.max(RIM_DEPTH, SEA - 1 - Math.floor(Math.min(Math.max(1, pOcean[i]) - 1, 8) / 2));
          pBiome[i] = Biome.Ocean;
          // a resort's shelf: shallow turquoise water a long way out from the beach
          if (rs && rs.shelf && rw > 0.5 && pFade[i] > 0 && pOcean[i] <= Math.min(rs.shelf, 18)) pE[i] = Math.max(pE[i], SEA - 1);
          if (lf.inLagoon(gx, gz)) {
            // an atoll's lagoon: shallow, turquoise, and deep enough for the boat
            pE[i] = SEA - 2;
            pBiome[i] = Biome.Lagoon;
          } else if (pFade[i] > 0 && lf.fjordFinger(u, v) > 0.05) {
            // a fjord's floor is deep water right up to its head
            pE[i] = Math.min(pE[i], SEA - 4);
          }
          continue;
        }

        // ---- lowland: a gentle swell with hill country laid over it ----
        const hillRaw = smoothstep(0.30, 0.74, 0.5 + 0.5 * nB.fbm(u * 2 + 20, v * 2 + 9, 3));
        let hillMask = hillRaw;
        if (rs && rs.hills !== undefined) hillMask += (rs.hills - hillMask) * rw;
        const relief = rs && rs.relief !== undefined ? 1 + (rs.relief - 1) * rw : 1;
        const amp = rs && rs.hillAmp !== undefined ? 1 + (rs.hillAmp - 1) * rw : 1;
        const swell = BASE_AMP * (0.5 + 0.5 * nA.fbm(u * 2.4, v * 2.4, 4)) * relief;
        let hills = hillMask * amp * relief * (HILL_BIG * nA.billow(u * 3.8, v * 3.8, 3) + HILL_SMALL * nA.billow(u * 7.5, v * 7.5, 2));
        // the Golden Hills: broad smooth domes forty tiles across, no creases, flat enough between to farm
        if (rs && rs.kind === 'goldhills') {
          const dome = 0.5 + 0.5 * nA.fbm(u * 5.5 + 17.3, v * 5.5 - 3.1, 2);
          hills += rw * 7 * dome * dome;
        }
        ctx.gx = gx; ctx.gz = gz; ctx.u = u; ctx.v = v; ctx.cd = cd; ctx.moisture = moisture; ctx.temp = tempRaw;
        ctx.arid = arid; ctx.hillMask = hillMask; ctx.biome = 255; ctx.surface = 0; ctx.mask = -1; ctx.noTown = false;
        ctx.mesaWall = false; ctx.lake = -128; ctx.regionErg = rs && rs.erg ? rw : 0; ctx.regionBad = rs && rs.badlands ? rw : 0;
        // an erg: long dunes take the place of the hills
        const [dune, erg] = lf.dunes(ctx);
        if (erg > 0) hills = hills * (1 - erg) + dune;
        // badlands: the same hills, sharpened, to be terraced at every step
        const bad = lf.badlands(ctx);
        if (bad > 0) hills += bad * 1.2 * nA.billow(u * 14 + 3, v * 14 + 7, 2);
        let e = 1.1 + swell + hills;
        // high country, and a continent's heart lifted over its coasts
        const U = cont ? geo.uplift(gx, gz) : 0;
        const lift = cont ? geo.lift(gx, gz, U) : 0;
        const rh = geo.rangeAt(ranges, gx, gz);
        e += rh.foot;

        // ---- mountains: the envelope of cones, never steeper than the ground may be ----
        // read through a slow warp, so a range's foot wanders instead of tracing a capsule round its ridge
        const [mwx, mwz] = mountWarp(nB, gx, gz);
        let mount = 0;
        for (const p of peaks) {
          const [dist, t] = segNear(mwx, mwz, p);
          const base = crestAt(p, t) - p.slope * dist;
          if (base + p.h * CREST_WOBBLE <= mount || base + p.h * CREST_WOBBLE <= 0) continue;
          // the crest rises and falls along the ridge into summits and cols, read where on the ridge it is
          const rx = p.x + (p.x2 - p.x) * t, rz = p.z + (p.z2 - p.z) * t;
          const m = base + p.h * CREST_WOBBLE * nB.fbm(rx / N * 3 + 7, rz / N * 3 + 53, 2);
          if (m > mount) mount = m;
        }
        if (mount > 0) {
          mount += PEAK_TEX * Math.min(1, mount / 4) * nB.fbm(u * 5 + 31, v * 5 + 71, 3);
          // spurs and gullies running down the flanks
          mount += SPUR_AMP * smoothstep(3, 10, mount) * (nA.ridged(u * 7 + 17, v * 7 + 41, 2) - 0.55);
        }
        // the landforms: a volcano, a caldera, towers, mesas, a rift, a salt pan
        ctx.e = e; ctx.mount = mount;
        lf.shape(ctx, cont);
        e = ctx.e; mount = ctx.mount;
        // everything so far stands on the lift, landforms and all, as it stood on the sea before
        const reliefMount = mount;
        e += lift;
        if (mount > 0) mount += lift;
        const baseE = e;
        if (mount > e) e = mount;
        ctx.lift = lift;
        e = lf.glacier(ctx, e);
        // ---- the great ranges and the tablelands, which stand on nothing but themselves ----
        let benchHere = rh.bench;
        if (rh.m > e) { e = rh.m; if (rh.core) pCore[i] = 1; }
        else if (rh.bench && rh.m < e && rh.m > baseE - 1) e = rh.m;
        let plateauRock = false, plateauTop = false;
        if (U > 0.02) {
          const ph = geo.plateauAt(gx, gz);
          if (ph.m > e) {
            e = ph.m;
            benchHere = false;
            if (ph.wall) pMesa[i] = 1;
            plateauRock = ph.rock;
            plateauTop = ph.top;
            if (ph.sealed || ph.wall) pNoTown[i] = 1;
          }
        }
        pBase[i] = baseE;
        // a flat biome holds all its land to a few steps above the sea
        if (rs && rs.cap !== undefined) e += (Math.min(e, rs.cap) - e) * rw;
        pMountMask[i] = ctx.mask >= 0 ? ctx.mask : smoothstep(2, 7, reliefMount);
        if (rh.mask > pMountMask[i] && rh.m >= e - 0.01) pMountMask[i] = rh.mask;
        if (benchHere || plateauTop) { pMountMask[i] = 0; pBench[i] = 1; }
        if (plateauRock) pMountMask[i] = Math.max(pMountMask[i], 0.6);

        // ---- the shore: the land climbs out of the water and no faster ----
        // a long, slow field: cliff country gives way to beach country over a hundred tiles of
        // coast, so the lift below never has to arrive faster than the ground is allowed to climb;
        // fjord country is all cliff, and its land between the fingers stands high
        const fz = lf.fjordZone(u, v);
        let cliffAmt = Math.max(smoothstep(-0.35, 0.45, nB.fbm(u * 1.4 + 40, v * 1.4 + 40, 1)), fz);
        if (rs && rs.cliff !== undefined) cliffAmt += (rs.cliff - cliffAmt) * rw;
        if (fz > 0) e += 7 * fz * smoothstep(4, 16, cd);
        pCliff[i] = cliffAmt > 0.62 && cd <= 7 ? 1 : 0;
        // coast distance is only counted so far: beyond it the shore has nothing more to say
        if (cd < COAST_CAP) e = Math.min(e, SHORE * cd + CLIFF_LIFT * cliffAmt);
        pE[i] = clamp(SEA + e, 0, Math.min(ROOF + 2, capOf(U) + 12));
        // the rivers run in the land, set into it a step or two below their banks
        const carved = rr.carve[i] < pE[i] - 0.5;
        if (rr.carve[i] < pE[i]) pE[i] = Math.max(0, rr.carve[i]);
        if (carved) { pCore[i] = 0; pMesa[i] = 0; benchHere = false; }
        pTemp[i] = clamp(tempRaw - 0.025 * e, 0, 1);

        // ragged snow and tree lines rather than contour rings: snow by height and climate, mountain by relief
        const lineNoise = nA.fbm(u * 9 + 3, v * 9 + 61, 2);
        const standsOut = pE[i] - (SEA + baseE);
        const snowAlt = 19 + 0.8 * lift + 22 * U + 2.2 * lineNoise;
        if (lift > 0.5) pSnow[i] = Math.min(255, Math.round(snowAlt + 4));
        if (pMountMask[i] > 0.5 && pE[i] >= snowAlt && !plateauRock) pBiome[i] = Biome.Snow;
        else if (pMountMask[i] > 0.5 && standsOut >= 5 + 1.6 * lineNoise && !plateauRock) pBiome[i] = Biome.Mountain;
        else if (cd <= 2 && pCliff[i]) pBiome[i] = Biome.SeaCliff;
        else if (cd <= 2) pBiome[i] = Biome.Beach;
        else if (arid > 0.5) pBiome[i] = Biome.Desert;
        else if (moisture > 0.63) pBiome[i] = Biome.Forest;
        else if (hillMask > 0.5) pBiome[i] = Biome.Hills;
        else pBiome[i] = Biome.Plains;
        if (ctx.biome !== 255 && cd > 1) pBiome[i] = ctx.biome;
        pSurf[i] = ctx.surface;
        if (erg > 0.3 && pBiome[i] === Biome.Desert) pSurf[i] = Surface.Sand;
        if (rs && rw > 0.5 && ctx.biome === 255) {
          const b = pBiome[i];
          const open = b === Biome.Plains || b === Biome.Hills || b === Biome.Forest || b === Biome.Desert;
          // every off-road tile of the Sands is sand
          if (rs.kind === 'sands' && (open || b === Biome.Beach)) pSurf[i] = Surface.Sand;
          // the Icefield's heights are snow the year round
          else if (rs.kind === 'icefield' && open && pE[i] >= SEA + 6) pBiome[i] = Biome.Snow;
          // bog in the Moors' hollows; half the Fens is swamp
          else if (rs.kind === 'moors' && open && cd > 3 && hillRaw < 0.3 && nB.fbm(u * 11 + 5, v * 11 + 9, 2) > 0.05) { pBiome[i] = Biome.Marsh; pSurf[i] = Surface.Marsh; }
          else if (rs.kind === 'fens' && open && cd > 2 && pE[i] < SEA + 1.8 && nB.fbm(u * 9 + 3, v * 9 + 1, 2) > -0.1) { pBiome[i] = Biome.Marsh; pSurf[i] = Surface.Marsh; }
          // the Mangroves' low ground is swamp too, between its creeks
          else if (rs.kind === 'mangrove' && open && cd > 3 && pE[i] < SEA + 1.4 && nB.fbm(u * 9 + 3, v * 9 + 1, 2) > 0.1) { pBiome[i] = Biome.Marsh; pSurf[i] = Surface.Marsh; }
          // old flows across the Fire Coast: tongues of black rock nothing is built on
          // (a few broad flows on the higher ground, never the low coast the towns are built on)
          else if (rs.lava && open && cd > 8 && pMountMask[i] < 0.5 && hillRaw > 0.5 && nB.fbm(u * 2.6 + 31, v * 2.6 + 13, 2) > 0.66 - 0.4 * rs.lava) {
            pBiome[i] = Biome.Lava; pSurf[i] = Surface.Lava; pNoTown[i] = 1;
          }
          // and salt crust over the Salt Pan's flats, beyond the pan itself
          else if (rs.salt && open && cd > 6 && pMountMask[i] < 0.5 && hillRaw < 0.55 && nB.fbm(u * 3.5 + 11, v * 3.5 + 57, 2) > 0.5 - 0.6 * rs.salt) {
            pBiome[i] = Biome.Salt; pSurf[i] = Surface.Salt; pNoTown[i] = 1;
          }
        }
        if (bad > 0.3 && (pBiome[i] === Biome.Desert || pBiome[i] === Biome.Hills)) { pSurf[i] = Surface.Rock; pBad[i] = 1; pBiome[i] = Biome.Canyon; }
        // a mountain is stepped where it stands well above its own foot, however high that foot has been lifted
        // Only the tops of the tallest peaks are stepped rock: every other mountain is smooth ground a car
        // with the grip can climb. (A great range's flanks are built at a grade the ground may take; only
        // its core is stepped.)
        if (pMountMask[i] >= 0.5 && standsOut >= 36 && !benchHere && !(rh.m >= e - 0.01 && rh.m > 0)) pTerr[i] = 1;
        // tablelands and their mesas: banded rock walls and talus, dry or grassy tops
        if (plateauRock) { pBiome[i] = Biome.Canyon; pSurf[i] = Surface.Rock; }
        else if (plateauTop && cd > 2) pBiome[i] = arid > 0.35 ? Biome.Desert : Biome.Plains;
        // a bench cut for a mountain village is meadow
        if (benchHere && cd > 2 && pBiome[i] !== Biome.Snow) pBiome[i] = moisture > 0.63 ? Biome.Forest : Biome.Plains;
        if (benchHere && pBiome[i] === Biome.Snow) pBiome[i] = Biome.Plains;
        // canyon walls: stepped, banded rock
        if (rr.canyon[i] && rr.carve[i] < SEA + e) {
          pBiome[i] = Biome.Canyon;
          pSurf[i] = Surface.Rock;
          if (rr.wall[i]) pCanyonWall[i] = 1;
        }
        if (ctx.noTown) pNoTown[i] = 1;
        if (ctx.lake !== -128) pLakeHint[i] = ctx.lake;
        if (ctx.mesaWall) pMesa[i] = 1;
        const own = px >= PAD && pz >= PAD && px < PAD + N && pz < PAD + N;
        if (own) {
          if (fz > 0.3 && cd < 12) { fjordTiles++; fjordX += px - PAD; fjordZ += pz - PAD; }
          if (erg > 0.5) { duneTiles++; duneX += px - PAD; duneZ += pz - PAD; }
          if (bad > 0.5) { badTiles++; badX += px - PAD; badZ += pz - PAD; }
          if (cont && lf.rift(u, v) > 0.7) { riftTiles++; riftX += px - PAD; riftZ += pz - PAD; }
        }
      }
    }
  }

  // Anything steeper than the ground may be is stepped and walled, like a terrace. The shapes above are
  // built to stay under the grade, but a tableland's scarp or a canyon's side can come out steeper where
  // its distance field stretches; walled, that is a cliff, where unwalled it would be a cascade for the
  // legaliser to chase. It reads only the padded elevation, so two counties decide it alike.
  {
    const wet = (p: number) => !pLand[p] || rr.chan[p] || rr.lake[p];
    for (let pz = 1; pz < P - 1; pz++) {
      for (let px = 1; px < P - 1; px++) {
        const p = pz * P + px;
        if (wet(p) || pTerr[p] || pCore[p] || pMesa[p] || pCanyonWall[p]) continue;
        const h = pE[p];
        let steep = 0;
        for (const q of [p - 1, p + 1, p - P, p + P]) if (!wet(q)) steep = Math.max(steep, Math.abs(pE[q] - h));
        if (steep > 0.95) { pTerr[p] = 1; if (pMountMask[p] < 0.5) pMountMask[p] = 0.5; }
      }
    }
  }
  PROBE.on?.('pE0', pE.slice());
  // the railway reads the ground either side of a land border from here, before anything local touches it
  const pE0 = cont ? pE.slice() : null;
  const pLand0 = cont ? pLand.slice() : null;

  // How steep the ground ever got. With everything above bounded this stays under MAX_GRADE, which
  // is the whole reason the seam holds; the corner assertion in the console watches the consequence.
  {
    let worst = 0;
    for (let pz = 0; pz < P - 1; pz++) {
      for (let px = 0; px < P - 1; px++) {
        const i = pz * P + px;
        if (!pLand[i]) continue;
        if (pLand[i + 1]) worst = Math.max(worst, Math.abs(pE[i + 1] - pE[i]));
        if (pLand[i + P]) worst = Math.max(worst, Math.abs(pE[i + P] - pE[i]));
      }
    }
    w.stats.maxSlope = Math.round(worst * 1000) / 1000;
  }

  // ======== crop the cell out of the padded grid ========
  const land = new Uint8Array(NN);
  const mountMask = new Float32Array(NN);
  const cliffBand = new Uint8Array(NN);
  const moisture = new Float32Array(NN);
  const oceanDist = new Uint16Array(NN);
  const E = w.elev;
  const cropDistances = (): void => {
    for (let z = 0; z < N; z++) {
      for (let x = 0; x < N; x++) {
        const i = z * N + x, p = (z + PAD) * P + x + PAD;
        w.coastDist[i] = pCoast[p];
        oceanDist[i] = pOcean[p];
      }
    }
  };
  for (let z = 0; z < N; z++) {
    for (let x = 0; x < N; x++) {
      const i = z * N + x, p = (z + PAD) * P + x + PAD;
      land[i] = pLand[p];
      mountMask[i] = pMountMask[p];
      cliffBand[i] = pCliff[p];
      moisture[i] = pMoist[p];
      E[i] = pE[p];
      w.biome[i] = pBiome[p];
      w.temp[i] = pTemp[p];
    }
  }
  cropDistances();
  const noTown = new Uint8Array(NN);
  const lakeHint = new Int8Array(NN);
  /** The great rivers' channels and lakes on this cell, and their water level. */
  const great = new Uint8Array(NN);
  const greatLvl = new Int8Array(NN).fill(-128);
  const snowLine = new Uint8Array(NN);
  const benchMask = new Uint8Array(NN);
  const canyonMask = new Uint8Array(NN);
  for (let z = 0; z < N; z++) {
    for (let x = 0; x < N; x++) {
      const i = z * N + x, p = (z + PAD) * P + x + PAD;
      if (pLand[p] && (rr.chan[p] || rr.lake[p]) && rr.lvl[p] > -128) { great[i] = rr.lake[p] ? 2 : 1; greatLvl[i] = rr.lvl[p]; }
      snowLine[i] = pSnow[p];
      benchMask[i] = pBench[p];
      canyonMask[i] = rr.canyon[p];
    }
  }
  w.snowLine = snowLine;
  for (let z = 0; z < N; z++) {
    for (let x = 0; x < N; x++) {
      const i = z * N + x, p = (z + PAD) * P + x + PAD;
      w.surface[i] = pSurf[p];
      noTown[i] = pNoTown[p];
      lakeHint[i] = pLakeHint[p];
    }
  }
  for (let z = 0; z < N; z++) {
    for (let x = 0; x < N; x++) {
      const i = z * N + x, p = (z + PAD) * P + x + PAD;
      w.regionK[i] = pRegK[p];
      w.regionW[i] = Math.round(pRegW[p] * 255);
    }
  }
  // the landforms this cell is known by
  for (const f of lf.placed) {
    const lx = f.gx - ox, lz = f.gz - oz;
    if (lx < 0 || lz < 0 || lx >= N || lz >= N) continue;
    w.landmarks.push({ kind: f.kind, name: f.name, x: lx, z: lz, r: f.r, data: f.data });
  }
  const regional = (kind: 'fjordCoast' | 'dunes' | 'badlands' | 'skerries' | 'riftValley', n: number, sx: number, sz: number, min: number) => {
    if (n < min) return;
    const x = sx / n, z = sz / n;
    w.landmarks.push({ kind, name: landformName(kind, seedHash, ox + x, oz + z), x, z, r: Math.sqrt(n / Math.PI) });
  };
  regional('fjordCoast', fjordTiles, fjordX, fjordZ, 600);
  regional('dunes', duneTiles, duneX, duneZ, 900);
  regional('badlands', badTiles, badX, badZ, 400);
  // a scatter of a few rocks is not yet a named field of skerries
  regional('skerries', skerries, skX, skZ, 100);
  regional('riftValley', riftTiles, riftX, riftZ, 500);
  // a coast that is fjords is named for them
  if (fjordTiles >= 2600 && (w.kind === 'continent' || w.kind === 'full' || w.kind === 'small')) w.name = landformName('fjordCoast', seedHash, ox + fjordX / fjordTiles, oz + fjordZ / fjordTiles);
  /** Redo the distances after something local moved the coastline, padded so the borders still agree. */
  const recomputeCoast = (): void => {
    for (let z = 0; z < N; z++) for (let x = 0; x < N; x++) pLand[(z + PAD) * P + x + PAD] = land[z * N + x];
    redistance();
    cropDistances();
  };

  // ======== 3b. causeways: land bridges to whichever island neighbours share a strait ========
  const causeway = new Uint8Array(NN);
  carveCauseways(w, seedHash, land, E, causeway);
  if (w.straits.length) recomputeCoast();
  /** Each causeway tile's height as laid, so anything that digs through one later can be undone. */
  const deckE = w.straits.length ? E.slice() : null;
  let landCount = 0;
  for (let i = 0; i < NN; i++) landCount += land[i];
  w.stats.land = landCount;

  // ======== 3c. broad beaches: stretches of coast eased right down to the waterline ========
  const beaches = growBeaches(w, land, E, new Uint8Array(NN), rng, coastal ? shape.beaches : 0, band);
  for (const b of beaches) w.spots.push({ kind: 'beach', x: b.x, z: b.z, r: b.r, name: beachName(h, w.spots.length) });
  for (let i = 0; i < NN; i++) if (causeway[i] || w.feature[i] === Feature.Beach) w.biome[i] = Biome.Beach;

  // ======== 4. lakes, the sinks an inland county needs ========
  const lakeLvl = new Int8Array(NN).fill(-128);
  if (cont) w.stats.lakes = digLakes(w, land, lakeLvl, rng, band, coastal ? 2 : 4, noTown);
  // oases, waterholes, tarns: a biome's own lakes, on an island as much as on a county
  if (spec?.lakes) w.stats.lakes += digLakes(w, land, lakeLvl, rng, band, spec.lakes, noTown);
  /** Ground the flood must leave alone: a lava crater, a salt pan. Water-holding landforms go in lakeLvl. */
  const dry = new Uint8Array(NN);
  for (let i = 0; i < NN; i++) {
    const hint = lakeHint[i];
    if (hint === -128 || !land[i]) continue;
    if (hint > 0) {
      // a caldera's lake: a flat bed a step under its surface
      lakeLvl[i] = hint;
      E[i] = Math.min(E[i], hint - 1.2);
      w.biome[i] = Biome.Ocean;
    } else if (hint === -2) {
      lakeLvl[i] = Math.round(E[i]) + 1;
    } else dry[i] = 1;
  }
  for (let i = 0; i < NN; i++) if (w.biome[i] === Biome.Salt) dry[i] = 1;
  // the local landforms that dig before the flood: tarns, oases, rift lakes, sinkholes
  const local = localLandforms(w, { land, E, lakeLvl, mountMask, moisture, rng, band, seedHash, coastal, cont, noTown, causeway, cliffBand, landmarksFrom: lf });
  local.beforeRivers();

  // ======== 5. rivers and streams ========
  /**
   * Where the water goes. An island drains to the ocean; a county drains to its lakes and, failing
   * those, out over its own border into the next county — which is what the water really does.
   * Without that second outlet the priority flood has nowhere to put the rain, fills half the
   * county to its spill level and leaves a flat inland sea where there should be meadow.
   */
  const sink = new Uint8Array(NN);
  for (let i = 0; i < NN; i++) if (lakeLvl[i] > -128 || dry[i] || great[i]) sink[i] = 1;
  if (band) {
    for (let z = 0; z < N; z++) {
      for (let x = 0; x < N; x++) {
        if (x >= band && z >= band && x < N - band && z < N - band) continue;
        sink[z * N + x] = 1;
      }
    }
  }
  const wetter = spec?.rivers ?? 1;
  /** Where the rivers crossing this county's borders come in and join a river or a lake: a watercourse reaching one has somewhere to go. */
  const crossingMouths: number[] = [];
  const { river } = computeRivers(E, land, moisture, 650 / wetter, 230 / wetter, salt, sink);
  for (let i = 0; i < NN; i++) if (causeway[i] || lakeLvl[i] > -128) river[i] = 0;
  if (band) {
    // A river that would leave the cell is cut at the band: no local carving may touch the seam.
    // The priority flood inside computeRivers raises depressions to their spill level, and where
    // a basin spills depends on the whole cell, so the ground it touched is put back too — that
    // one line is the difference between two counties agreeing on their border and not.
    for (let z = 0; z < N; z++) {
      for (let x = 0; x < N; x++) {
        if (x >= band && z >= band && x < N - band && z < N - band) continue;
        const i = z * N + x;
        river[i] = 0;
        // but not a causeway's deck: pE was taken before it was laid, and holds the sea bed there
        if (!causeway[i]) E[i] = pE[(z + PAD) * P + x + PAD];
      }
    }
    // the rivers that cross this county's borders, carried on in to meet its own
    for (let d = 0; d < 4; d++) {
      const low = d < 2;   // this cell is the lower one of the pair on its +x and +z sides
      const ch = riverChannel(seedHash, d === 2 ? cx - 1 : cx, d === 3 ? cz - 1 : cz, d % 2);
      if (!ch) continue;
      const [gx, gz] = ch.ends[low ? 0 : 1];
      const step = low ? -1 : 1;   // one tile further into this cell than the channel's inner end
      const lx = gx - ox + (d % 2 === 0 ? step : 0), lz = gz - oz + (d % 2 === 1 ? step : 0);
      w.stats.riverCrossings++;
      // one that found a river or a lake is on its way somewhere; one that ran out is tidied like any other
      if (joinRiver(land, river, lakeLvl, E, band, lx, lz, salt)) crossingMouths.push(idx(Math.max(0, Math.min(N - 1, lx)), Math.max(0, Math.min(N - 1, lz))));
    }
  }

  // the great rivers keep their own channels: 3 in the river table, which every local tool leaves alone
  for (let i = 0; i < NN; i++) if (great[i]) river[i] = 3;

  // the local landforms that follow the rivers: deltas, oxbows, mangroves, tombolos
  local.afterRivers(river);
  if (local.coastMoved) recomputeCoast();

  // ======== 5b. town sites, flattened before farms and corners see the elevation ========
  // a biome keeps its towns: no county of it is only farmland
  const roster = rosterOf(seedHash, cx, cz).towns;
  // no town on a volcano's cone, in a salt pan, among the towers or on a glacier
  const reserve = new Uint8Array(NN);
  for (let i = 0; i < NN; i++) reserve[i] = causeway[i] | noTown[i];
  // ======== 5b'. villages up in big country: benches, passes and ridge tops, and the canyon rims ========
  const perched: TownPlan[] = [];
  if (cont && (ranges.length || riverNet.edges.length)) {
    for (const r of ranges) {
      for (const b of r.benches) {
        // the bench was levelled where the warped ground reads it; the tile that reads there lies back along the warp
        const [wx, wz] = geo.rangeWarp(b.x, b.z);
        const lx = 2 * b.x - wx - ox, lz = 2 * b.z - wz - oz;
        if (lx < 0 || lz < 0 || lx >= N || lz >= N) continue;
        const got = placeVillage(w, perched, land, river, mountMask, reserve, lx, lz, b.kind, band);
        if (DEBUG.bench) console.log(`bench ${b.kind} (${cx},${cz}) local ${lx.toFixed(0)},${lz.toFixed(0)} h ${b.h.toFixed(1)} E ${E[idx(Math.floor(lx), Math.floor(lz))]?.toFixed(1)} -> ${got ? 'placed' : 'no'}`);
      }
    }
    // a village on a canyon's rim: level tableland within a few tiles of the drop
    let rims = 0;
    for (let z = band + 16; z < N - band - 16 && rims < 2; z += 6) {
      for (let x = band + 16; x < N - band - 16 && rims < 2; x += 6) {
        const i = idx(x, z);
        if (!benchMask[i] || canyonMask[i] || hash2(x, z, salt + 91) > 0.35) continue;
        let near = false;
        for (let dz = -12; dz <= 12 && !near; dz += 3) for (let dx = -12; dx <= 12 && !near; dx += 3) {
          if (inB(x + dx, z + dz) && canyonMask[idx(x + dx, z + dz)]) near = true;
        }
        if (near && placeVillage(w, perched, land, river, mountMask, reserve, x, z, 'rim', band)) rims++;
      }
    }
  }
  const townPlans = planTowns(w, land, river, mountMask, cliffBand, rng, roster, reserve, band, spec ? siteBias(w, spec, land, river, lakeLvl, cliffBand) : undefined, spec?.margin, perched);
  // a desert town without its oasis gets one dug beside it
  if (spec?.site === 'oasis') digOases(w, townPlans, land, lakeLvl, river);
  w.mega = townPlans.some((p) => p.kind === 'mega');
  if (w.mega) {
    // a channel wandering out to sea can run along a causeway; the causeway stands, and dams the
    // channel's far end out in open water rather than leave the neighbour's half ending in the sea
    if (deckE) {
      for (let i = 0; i < NN; i++) {
        if (!causeway[i]) continue;
        land[i] = 1;
        E[i] = deckE[i];
        w.biome[i] = Biome.Beach;
      }
      // and laid again over the channel, so where it took the shore a causeway landed on, it is carried on to firm ground
      carveCauseways(w, seedHash, land, E, causeway, true);
      for (let i = 0; i < NN; i++) if (causeway[i]) { w.biome[i] = Biome.Beach; river[i] = 0; }
    }
    // the channel a megalopolis is built around changes the coastline, so distances are redone
    recomputeCoast();
    for (let i = 0; i < NN; i++) if (!land[i] && E[i] > SEA - 1) E[i] = SEA - 1 - Math.floor(Math.min(Math.max(1, oceanDist[i]) - 1, 8) / 2);
  }
  // a canal town dug into the coast, on an ordinary cell: its Grand Canal moves the coastline as a channel does
  const canalMask = spec ? null : planVenice(w, townPlans, land, river, causeway, seedHash, band);
  if (canalMask) recomputeCoast();
  // GEN 53: the hot-spring towns among the rest, each with its stream cut through the square (world/onsen.ts)
  if (NEXT_WORLD && !spec) planOnsen(w, townPlans, { w, land, river, mountMask, band, causeway, plans: townPlans }, seedHash);
  // GEN 53: the lake towns among the rest, each wrapped round the lake cut in its square (world/lakes.ts)
  if (NEXT_WORLD && !spec) planLakes(w, townPlans, { w, land, river, mountMask, band, causeway, plans: townPlans }, seedHash);
  // GEN 53: the city plans' lakes held at their levels, and their water and banks marked for the corners (world/plans)
  const planMask = NEXT_WORLD ? planWater(w, townPlans, lakeLvl) : null;
  if (planMask?.moved) recomputeCoast();
  // ======== 5c. harbours: yards and piers raised into land, basins dredged into the sea ========
  const portPlans = coastal
    ? planPorts(w, land, river, cliffBand, townPlans, rng, shape.majorPorts, shape.minorPorts, band)
    : [];

  // ======== 6. farms, and the places people work ========
  // a megalopolis's international takes its pick of the open ground before the farms spread over it
  const airfields = airfieldsOf(seedHash, cx, cz, w.kind, shape, spec);
  const intl = w.mega && airfields > 0 ? growIntl(w, land, E, river, rng, band, causeway) : null;
  // one county in seven lays out a motor-racing circuit (world/circuits.ts), where the open ground is big
  // and flat enough: before the farms, as the international is, or they would have it all
  // (not where a railway runs: boxed in, a line would take the shortest way, over the track)
  const circuit = !w.mega && cell01(seedHash, cx, cz, CIRCUIT_SALT) < CIRCUIT_CHANCE && !railLines(seedHash, cx, cz).length
    ? planCircuit(w, land, E, river, lakeLvl, mulberry32(hashCell(seedHash, cx, cz, CIRCUIT_SALT + 1)), band,
      CIRCUIT_DESIGNS[Math.floor(cell01(seedHash, cx, cz, CIRCUIT_SALT + 3) * CIRCUIT_DESIGNS.length) % CIRCUIT_DESIGNS.length])
    : null;
  // an inland county trades in what it grows and digs rather than in what comes off a ship
  const fields = growFarms(w, E, river, rng, coastal ? shape.fields : shape.fields + 3, band);
  // the biome's wonder, carved before the works so they keep out of its way; one ordinary cell in
  // five gets the moated castle instead (a hashed roll, so no other cell's draws move)
  // GEN 53 (world/nextWorld.ts): now and then one of the ancient wonders in its place, or on a warm ordinary
  // cell; the Colossus falls back to the Pharos where no shore takes its harbour, and either to what was there
  const ancient = NEXT_WORLD ? ancientWonder(seedHash, cx, cz, spec, w, land, coastal) : null;
  const ancientSite = ancient
    ? planWonder(w, land, E, river, lakeLvl, rng, ANCIENT_WONDERS[ancient], band)
      ?? (ancient === 'colossus' ? planWonder(w, land, E, river, lakeLvl, rng, ANCIENT_WONDERS.pharos, band) : null)
    : null;
  const wonder = ancientSite ? ancientSite : spec && regionWonder(seedHash, cx, cz) ? planWonder(w, land, E, river, lakeLvl, rng, spec, band)
    : !spec && cell01(seedHash, cx, cz, CASTLE_SALT) < CASTLE_CHANCE
      // three ordinary wonders in five are the moated castle; the others are the golden temple and the spaceport
      ? planWonder(w, land, E, river, lakeLvl, rng, ISLAND_WONDERS[Math.floor(cell01(seedHash, cx, cz, CASTLE_SALT + 7) * ISLAND_WONDERS.length) % ISLAND_WONDERS.length], band)
      : null;
  if (wonder?.moved) recomputeCoast();
  // 0.7.0: now and then a private beach resort on a warm sandy shore (world/beachResorts.ts), on a generator of its own
  const resort = NEXT_WORLD && cell01(seedHash, cx, cz, RESORT_SALT) < RESORT_CHANCE
    ? planBeachResort(w, land, E, river, mulberry32(hashCell(seedHash, cx, cz, RESORT_SALT + 1)), band) : null;
  const works = growWorks(w, land, E, river, rng, {
    quarries: shape.quarries + (coastal ? 0 : 1), pistes: shape.pistes, airfields,
  }, band, causeway, intl);
  if (wonder) works.unshift(wonder.site);
  if (circuit) works.unshift(circuit);
  if (resort) works.unshift(resort);
  // 0.7.0: the fields in their new shapes, now every site has chosen its ground (world/biomes.ts reshapeFields)
  if (NEXT_WORLD) reshapeFields(w, E, river, fields, band);

  // watercourses that lead nowhere: cut at the seam band, stopped by a town, or run out in a field
  tidyRivers(w, river, land, E, lakeLvl, noTown, band, townPlans, works, causeway, crossingMouths, salt);

  // ======== 6b. the railway: its platform, its curve and its vertical line ========
  const railCtx: RailCtx = { w, seedHash, land, E, river, lakeLvl, towns: townPlans, works, fields, causeway, pE0, pLand0, P, PAD };
  const tr0 = performance.now();
  const railPlan = planRail(railCtx);
  w.stats.railMs += performance.now() - tr0;

  // ======== 7. per-tile corners, on the padded grid so both sides of a border agree ========
  for (let z = 0; z < N; z++) {
    for (let x = 0; x < N; x++) {
      const i = z * N + x, p = (z + PAD) * P + x + PAD;
      pE[p] = E[i];
      pLand[p] = land[i];
      pBiome[p] = w.biome[i];
      pCliff[p] = cliffBand[i];
      pMountMask[p] = mountMask[i];   // softenSite switches terracing off under a town
      if (mountMask[i] < 0.5) { pTerr[p] = 0; pCore[p] = 0; }
    }
  }
  const pC = new Int8Array(PP * 4);
  {
    const G = new Float32Array((P + 1) * (P + 1));
    for (let z = 0; z <= P; z++) {
      for (let x = 0; x <= P; x++) {
        let sum = 0, n = 0;
        for (let dz = -1; dz <= 0; dz++) for (let dx = -1; dx <= 0; dx++) {
          const tx = x + dx, tz = z + dz;
          if (tx < 0 || tz < 0 || tx >= P || tz >= P) continue;
          sum += pE[tz * P + tx]; n++;
        }
        G[z * (P + 1) + x] = Math.round(sum / n);
      }
    }
    for (let z = 0; z < P; z++) {
      for (let x = 0; x < P; x++) {
        const b = (z * P + x) * 4;
        pC[b] = G[z * (P + 1) + x];
        pC[b + 1] = G[z * (P + 1) + x + 1];
        pC[b + 2] = G[(z + 1) * (P + 1) + x + 1];
        pC[b + 3] = G[(z + 1) * (P + 1) + x];
      }
    }
  }
  PROBE.on?.('pCraw', pC.slice());
  /**
   * The forced sea-bed rim, worked out per padded tile from the cell that contains it rather than
   * from this one. A cell whose neighbour fades to water at its own edge then lays the rim down in
   * exactly the place the neighbour will, instead of each patching only its own side afterwards.
   */
  const forceRim = (): void => {
    for (let pz = 0; pz < P; pz++) {
      const gz = oz + pz - PAD;
      const lz = gz - Math.floor(gz / N) * N;
      for (let px = 0; px < P; px++) {
        const i = pz * P + px;
        if (pFade[i] > 0) continue;
        const gx = ox + px - PAD;
        const lx = gx - Math.floor(gx / N) * N;
        if (lx >= 2 && lz >= 2 && lx < N - 2 && lz < N - 2) continue;
        const b = i * 4;
        pC[b] = pC[b + 1] = pC[b + 2] = pC[b + 3] = RIM_DEPTH;
      }
    }
  };

  // the great rivers' beds: flat, a step or two under the water, walled from their banks
  for (let p = 0; p < PP; p++) {
    if (!pLand[p] || !(rr.chan[p] || rr.lake[p]) || rr.lvl[p] <= -128) continue;
    const b = p * 4;
    const bed = Math.min(Math.floor(pE[p]), rr.lvl[p] - 1);
    pC[b] = pC[b + 1] = pC[b + 2] = pC[b + 3] = bed;
    pFlags[p] |= Flag.River | Flag.Corridor;
  }
  // a canal town's canals and its ground, set flat outright so each bank is a quay wall (world/canals.ts)
  if (canalMask) {
    setCanalCorners(canalMask, E, (i, h) => {
      const x = i % N, z = (i - x) / N, p = (z + PAD) * P + x + PAD, b = p * 4;
      pC[b] = pC[b + 1] = pC[b + 2] = pC[b + 3] = h;
      pFlags[p] |= w.flags[i] & Flag.Corridor;
    });
  }
  // and a city plan's water and banks the same way (world/plans/water.ts)
  if (planMask) {
    planCorners(planMask.mask, E, (i, h) => {
      const x = i % N, z = (i - x) / N, p = (z + PAD) * P + x + PAD, b = p * 4;
      pC[b] = pC[b + 1] = pC[b + 2] = pC[b + 3] = h;
      pFlags[p] |= w.flags[i] & Flag.Corridor;
    });
  }
  // terraces are pointwise on global inputs, so two cells cut the same steps into the same mountain
  applyTerraces(pC, pFlags, pTerr, pE, P, -99, 3);
  // a great range's core stands in cliff bands, and a canyon's walls step down in fours
  applyTerraces(pC, pFlags, pCore, pE, P, -99, 4);
  applyTerraces(pC, pFlags, pCanyonWall, pE, P, -99, 4);
  // a mesa's walls step down in threes whatever their height; badlands step at every level
  applyTerraces(pC, pFlags, pMesa, pE, P, -99, 3);
  applyTerraces(pC, pFlags, pBad, pE, P, -99, 1);
  forceRim();
  // River crossings: cut through the seam band on the padded grid, from global inputs, so the
  // county either side cuts exactly the same channel. Every border in reach of this grid is
  // checked, not only this cell's, since the padding reaches along a neighbour's borders too.
  const pRiver = new Uint8Array(PP);
  if (band) {
    for (let kz = cz - 1; kz <= cz + 1; kz++) {
      for (let kx = cx - 1; kx <= cx + 1; kx++) {
        for (const axis of [0, 1]) {
          const ch = riverChannel(seedHash, kx, kz, axis);
          if (!ch) continue;
          for (const [gx, gz] of ch.tiles) {
            const px = gx - ox + PAD, pz = gz - oz + PAD;
            if (px < 0 || pz < 0 || px >= P || pz >= P) continue;
            const p = pz * P + px;
            // a mountain's terraces and the sea both stop it, identically on both sides
            if (!pLand[p] || pRiver[p] || (pFlags[p] & Flag.Terrace) || pMountMask[p] >= 0.5) continue;
            const b = p * 4;
            const bed = Math.min(pC[b], pC[b + 1], pC[b + 2], pC[b + 3]) - 2;
            pC[b] = pC[b + 1] = pC[b + 2] = pC[b + 3] = bed;
            pRiver[p] = 1;
          }
        }
      }
    }
  }
  const c = w.corners;
  for (let z = 0; z < N; z++) {
    for (let x = 0; x < N; x++) {
      const i = z * N + x, p = (z + PAD) * P + x + PAD;
      for (let k = 0; k < 4; k++) c[i * 4 + k] = pC[p * 4 + k];
      w.flags[i] |= pFlags[p];
      if (pRiver[p]) w.flags[i] |= Flag.River;
    }
  }

  // local carving: river beds, fields, canyons and harbours, all of them clear of the seam band
  for (let i = 0; i < NN; i++) {
    if (river[i] && river[i] !== 3) {
      const b = i * 4;
      const bed = Math.min(c[b], c[b + 1], c[b + 2], c[b + 3]) - (river[i] === 2 ? 2 : 1);
      c[b] = c[b + 1] = c[b + 2] = c[b + 3] = bed;
      w.flags[i] |= river[i] === 2 ? Flag.River : Flag.Stream;
    }
  }
  for (const f of fields) for (const t of f.tiles) {
    const b = t * 4;
    c[b] = c[b + 1] = c[b + 2] = c[b + 3] = f.level;
  }
  w.stats.canyons = applyCanyons(w, river, rng, 4, band);
  // gorges, cascades, sinkholes, caves, lava tubes and natural bridges: carved before the walls
  local.carve(river, keepClearMask(railPlan.drafts, townPlans, works));
  w.stats.fields = fields.length;
  const portMask = shapePorts(w, portPlans);
  // the causeway decks are laid from their own heights so both sides of a border agree
  layDecks(c, causeway, land, E);

  // ======== 8. walls, steep zones, legalise — again on the padded grid ========
  for (let z = 0; z < N; z++) {
    for (let x = 0; x < N; x++) {
      const i = z * N + x, p = (z + PAD) * P + x + PAD;
      for (let k = 0; k < 4; k++) pC[p * 4 + k] = c[i * 4 + k];
      pFlags[p] |= w.flags[i];
      if (portMask[i] === 1) pFlags[p] |= Flag.Corridor;
      pBiome[p] = w.biome[i];
    }
  }
  {
    const wallX = new Uint8Array(PP);
    const wallZ = new Uint8Array(PP);
    const diagLimit = new Uint8Array(PP).fill(1);
    const wallable = (i: number) => (pFlags[i] & (Flag.Terrace | Flag.Corridor | Flag.Ramp)) !== 0;
    // A terrace is a step by design, and its every edge is walled rather than only the tall ones:
    // an unwalled one-step edge off a mountain's stack is a wire the legaliser can run a correction
    // down, and on a continent that wire would reach the border.
    const terraced = (i: number, j: number) => ((pFlags[i] | pFlags[j]) & Flag.Terrace) !== 0;
    const cliffShore = (i: number, j: number) => (pCliff[i] && !pLand[j]) || (pCliff[j] && !pLand[i]);
    for (let z = 0; z < P; z++) {
      for (let x = 0; x < P; x++) {
        const i = z * P + x;
        const b = i * 4;
        // a steep diagonal only in a great range's jagged core: every other mountain tile is one a car can climb
        if (pCore[i]) diagLimit[i] = 2;
        if (x < P - 1) {
          const j = i + 1, r = j * 4;
          const mm = Math.max(Math.abs(pC[b + 1] - pC[r]), Math.abs(pC[b + 2] - pC[r + 3]));
          if (mm >= 1 && terraced(i, j)) wallX[i] = 1;
          else if (mm >= 2 && (wallable(i) || wallable(j) || cliffShore(i, j))) wallX[i] = 1;
        }
        if (z < P - 1) {
          const j = i + P, d = j * 4;
          const mm = Math.max(Math.abs(pC[b + 3] - pC[d]), Math.abs(pC[b + 2] - pC[d + 1]));
          if (mm >= 1 && terraced(i, j)) wallZ[i] = 1;
          else if (mm >= 2 && (wallable(i) || wallable(j) || cliffShore(i, j))) wallZ[i] = 1;
        }
      }
    }
    PROBE.on?.('pCpre', pC.slice());
    w.stats.passes = legalise(pC, wallX, wallZ, diagLimit, P, LEGALISE_REACH);
  }
  forceRim();
  PROBE.on?.('pCrim', pC.slice());
  for (let z = 0; z < N; z++) {
    for (let x = 0; x < N; x++) {
      const i = z * N + x, p = (z + PAD) * P + x + PAD;
      for (let k = 0; k < 4; k++) c[i * 4 + k] = pC[p * 4 + k];
    }
  }
  // the causeway decks go back exactly where the neighbour expects them; the rim already has
  layDecks(c, causeway, land, E);


  // ======== 8b. the railway settles into the finished ground: cuttings, platforms, tile bits ========
  const tr1 = performance.now();
  finishRail(railCtx, railPlan);
  w.stats.railMs += performance.now() - tr1;

  // a waterfall's banks brought back up where the legaliser eased them under its pools (world/waterfalls.ts)
  holdFalls(w, lakeLvl, land);

  // ======== 9. water surfaces ========
  // a desert's rivers are wadis: the channel is cut, but it only holds water near an oasis
  const dryBed = new Uint8Array(NN);
  if (spec?.dryRivers) {
    const wet = new Uint8Array(NN);
    for (let i = 0; i < NN; i++) {
      if (lakeLvl[i] <= -128) continue;
      const x = i % N, z = (i - x) / N;
      for (let dz = -12; dz <= 12; dz += 2) for (let dx = -12; dx <= 12; dx += 2) if (inB(x + dx, z + dz)) wet[idx(x + dx, z + dz)] = 1;
    }
    for (let i = 0; i < NN; i++) {
      if (!(w.flags[i] & (Flag.River | Flag.Stream)) || wet[i] || !land[i] || w.regionW[i] < 128) continue;
      dryBed[i] = 1;
      w.biome[i] = Biome.Canyon;
    }
  }
  for (let i = 0; i < NN; i++) {
    if (!land[i]) w.water[i] = SEA;
    else if (lakeLvl[i] > -128) w.water[i] = lakeLvl[i];
    else if (dryBed[i]) continue;
    else if (w.flags[i] & Flag.River) w.water[i] = minCorner(w, i) + 2;
    else if (w.flags[i] & Flag.Stream) w.water[i] = minCorner(w, i) + 1;
  }
  // the great rivers' water, at the level the whole river agrees on
  for (let i = 0; i < NN; i++) if (great[i] && greatLvl[i] > -128 && land[i]) w.water[i] = greatLvl[i];
  local.water();
  for (let pass = 0; pass < 2; pass++) {
    const add = new Int8Array(NN).fill(-1);
    for (let i = 0; i < NN; i++) {
      if (w.water[i] >= 0 || causeway[i] || (w.rail[i] & (RailBit.Track | RailBit.Pad))) continue;
      const x = i % N, z = (i - x) / N;
      const mc = minCorner(w, i);
      for (let d = 0; d < 4; d++) {
        const nx = x + DIRS[d][0], nz = z + DIRS[d][1];
        if (!inB(nx, nz)) continue;
        const j = idx(nx, nz);
        const wl = w.water[j];
        if (wl >= 0 && mc < wl && wl - mc <= 2) add[i] = Math.max(add[i], wl);
      }
    }
    for (let i = 0; i < NN; i++) if (add[i] >= 0) w.water[i] = add[i];
  }

  // ======== 9b. towns: roads, lots and buildings ========
  // the harbours' and the works' building lots are claimed first, so no town street or county road is routed
  // under a hangar or a warehouse that goes up after it (the user, 7 Oct 2026)
  reservePorts(w, portPlans);
  reserveWorks(w, works);
  buildTowns(w, townPlans, rng, spec);
  w.links = linkTowns(w);
  buildPorts(w, portPlans, rng);
  buildWorks(w, works, rng);
  linkStraits(w, causeway);
  linkCrossings(w, seedHash);
  linkWorks(w);
  // 0.7.0: a mine whose road reaches no town is given up (world/mines.ts)
  if (NEXT_WORLD) dropStrandedMines(w);
  // the station buildings and their forecourt roads, from a generator of their own so nothing else shifts
  railBuildings(w, railPlan, mulberry32(h ^ 0x7a11), (gate) => linkGate(w, gate));
  // wherever the line has cut the land in two with no road over it, a level crossing where it runs straight
  if (w.rails.length) {
    buildEdges(w);
    const split = components(w);
    linkRailSplits(w, split.comp, split.sizes, band);
  }
  placeCountryside(w, fields, rng, band, spec, (gate) => linkLane(w, gate));
  // what stands along the road and out on the land: truck stops, a drive-in, mills, wall and stones
  placeRoadside(w, rng, band, (gate) => linkLane(w, gate));
  placeCustoms(w, rng, seedHash);
  // the Auto Shop, the dealer and the tavern: real buildings of their kind with a kerb out front
  placeStorefronts(w);
  // the story chains' stages (docs/storychains.html), last of all the buildings so every other building keeps
  // the id it had: a naval dry dock on the coast of half the counties that have one, and a launch complex out
  // in the open country of about a third of them, where no wonder has one; each on its own random stream, each
  // joined to the county's roads by a paved road a car can climb (linkGate), not a haul track that climbs anything
  placeNavalDock(w, mulberry32(hashString(`${seedHash}|${w.cx},${w.cz}|navalDock`)), band, (gate) => linkGate(w, gate));
  placeSpacePad(w, mulberry32(hashString(`${seedHash}|${w.cx},${w.cz}|spacePad`)), band, (gate) => linkGate(w, gate));
  // GEN 53 (world/nextWorld.ts): ranches out in the open grass country, a yard of buildings on the edge of a great
  // fenced pasture (world/ranches.ts), after every other building on a stream of their own, so none of them moves
  if (NEXT_WORLD) placeRanches(w, mulberry32(hashString(`${seedHash}|${w.cx},${w.cz}|ranches`)), band, spec, (gate) => linkLane(w, gate, 70, true));
  // GEN 53: a canyon's rim village gets a mule trail down to the platform, a ranch at its foot and a cable car across
  // the gap (world/canyonWorks.ts), on a stream of its own after the ranches, so nothing else moves
  if (NEXT_WORLD && w.towns.some((t) => t.perch === 'rim')) {
    const cs = placeCanyonWorks(w, mulberry32(hashString(`${seedHash}|${w.cx},${w.cz}|canyon`)), band, canyonMask);
    Object.assign(w.stats, { trails: cs.trails, trailTiles: cs.trailTiles, canyonRanches: cs.ranches, cableCars: cs.cableCars });
  }
  // GEN 54 (world/nextWorld.ts NEXT_080, held for 0.8.0): works beside the railway and out at sea, each set on a stream
  // of its own after every other building, so nothing else moves (world/railside.ts, world/undersea.ts)
  if (NEXT_080) {
    placeRailside(w, mulberry32(hashString(`${seedHash}|${w.cx},${w.cz}|railside`)), band, (gate) => linkLane(w, gate));
    placeUndersea(w, mulberry32(hashString(`${seedHash}|${w.cx},${w.cz}|undersea`)), band);
  }
  // and a road still under a solid building, whatever put it there, is cut there and joined again round it
  w.stats.mended = mendBlockedRoads(w);

  // ======== 10. drivability, spawn, POIs, tracks ========
  buildEdges(w);
  const { comp, sizes } = components(w);
  let big = 0;
  for (let k = 1; k < sizes.length; k++) if (sizes[k] > sizes[big]) big = k;
  w.stats.drivable = sizes[big] ?? 0;

  const spawnCands: number[] = [];
  for (let i = 0; i < NN; i++) {
    if (comp[i] !== big || w.biome[i] !== Biome.Plains || !isFlat(w, i) || w.water[i] >= 0 || w.coastDist[i] < 15) continue;
    if (w.flags[i] & Flag.Field) continue;
    spawnCands.push(i);
  }
  let spawnTile = spawnCands.length ? spawnCands[Math.floor(rng() * spawnCands.length)] : -1;
  if (spawnTile < 0) {
    for (let i = 0; i < NN; i++) if (comp[i] === big && waterDepth(w, i) === 0) { spawnTile = i; break; }
  }
  if (spawnTile < 0) spawnTile = idx(N >> 1, N >> 1);
  w.spawn = { x: (spawnTile % N) + 0.5, z: Math.floor(spawnTile / N) + 0.5, heading: Math.floor(rng() * 4) * Math.PI / 2 };

  const reach = reachable(w, spawnTile, TOMATO);
  let reachCount = 0;
  for (let i = 0; i < NN; i++) if (reach[i] && land[i]) reachCount++;
  w.stats.reachable = reachCount;

  placePois(w, reach, fields, rng, coastal ? shape.cabins : shape.cabins + 8);
  // hot springs, sea arches, basalt columns, hoodoos and erratics: the points of interest
  local.pointsOfInterest(reach);
  layTracks(w, TOMATO);
  // a rare grove of giant trees, sited last so it lands on none of the above (no rng draws)
  placeGroves(w, moisture, seedHash, band);

  // a waterfall's pools let down to any bank the towns and roads lowered after it was cut, then the
  // brooks over the finished ground, from hashes (world/waterfalls.ts, world/brooks.ts)
  sealFalls(w);
  w.brooks = traceBrooks(w, seedHash);
  // jump ramps over the rivers, canyons and cliff edges, and boost pads on the long straights, on a random
  // stream of their own and last of all, so nothing else in the county moves for them (world/jumpsGen.ts)
  placeJumps(w, mulberry32(hashString(`${seedHash}|${w.cx},${w.cz}|jumps`)), band);

  let peak = 0;
  for (let k = 0; k < NN * 4; k++) if (w.corners[k] > peak) peak = w.corners[k];
  w.peak = peak;
  w.stats.genMs = performance.now() - t0;
  return w;
}
