import type { KindSpec } from './townKinds';
import { Lot } from './tiles';
import { hashString } from './rng';
import type { Layout, TownPlan } from './towns';

/**
 * An onsen town's own buildings (GEN 53, world/onsen.ts): the ryokan in four builds (the Meiji-era Fukuzumirō on
 * Hakone's Hayakawa, Ginzan's tall timber inns facing each other over the river, a concrete resort hotel up the
 * slope, a family minshuku), the grand bathhouse after Dōgo Onsen Honkan, Kusatsu's yubatake in the square,
 * Beppu's hells, a foot bath, Hakone's ropeway over Ōwakudani's sulphur vents and the torii standing in the lake
 * at Hakone Shrine. The little public baths (Kinosaki's seven sotoyu) are the Terraces' bathhouse. One table, spread
 * into the game's per-kind tables as world/playKinds.ts is; the models are in render/buildings/onsen*.ts.
 */

export const ONSEN_KINDS = [
  'ryokan', 'fukuzumiro', 'resortRyokan', 'minshuku', 'dogoHonkan', 'yubatake', 'jigoku', 'ashiyu', 'ropeway', 'lakeTorii',
] as const;

export type OnsenKind = (typeof ONSEN_KINDS)[number];

interface Info {
  label: string;
  icon: string;
  /** The lot in tiles: W across its front (a range rolled per building), D deep. */
  size: [number | [number, number], number];
  floors?: number | [number, number];
  /** How tall the model stands, in world units (towns.ts buildingHeight): per floor when it has floors. */
  h: number;
  /** What it costs to knock down (economy.ts), which sets a lot's floor price. */
  price: number;
  /** As an HQ (hqGrade.ts). */
  grade: 0 | 1 | 2 | 3 | 4 | 5;
  zone: KindSpec['zone'];
  lot: Lot;
  waterside?: KindSpec['waterside'];
  apart?: number;
  /** An open lot: a car may cross it (the foot bath's paving, the torii's landing). */
  open?: boolean;
  /** What kind of place a trip there is (game/traffic.ts TAG_OF). */
  tag: 'work' | 'leisure' | 'home';
}

const ONSEN_INFO: Record<OnsenKind, Info> = {
  ryokan: { label: 'Ryokan', icon: '🏯', size: [2, 2], floors: [3, 4], h: 0.42, price: 1290, grade: 3, zone: 'any', lot: Lot.Plaza, waterside: 'prefer', apart: 2, tag: 'leisure' },
  fukuzumiro: { label: 'Fukuzumirō', icon: '🏮', size: [3, 3], floors: 3, h: 1.45, price: 2490, grade: 4, zone: 'any', lot: Lot.Gravel, waterside: 'prefer', apart: 60, tag: 'leisure' },
  resortRyokan: { label: 'Resort ryokan', icon: '🏨', size: [4, 3], floors: [5, 8], h: 0.62, price: 2990, grade: 4, zone: 'edge', lot: Lot.Plaza, apart: 14, tag: 'leisure' },
  minshuku: { label: 'Minshuku', icon: '🛏️', size: [[1, 2], 1], floors: 2, h: 0.36, price: 690, grade: 2, zone: 'mid', lot: Lot.Gravel, apart: 3, tag: 'leisure' },
  dogoHonkan: { label: 'Grand bathhouse', icon: '♨️', size: [3, 3], floors: 3, h: 1.7, price: 2190, grade: 5, zone: 'core', lot: Lot.Plaza, apart: 60, tag: 'leisure' },
  yubatake: { label: 'Yubatake', icon: '♨️', size: [4, 3], h: 0.55, price: 899, grade: 0, zone: 'core', lot: Lot.Plaza, apart: 60, tag: 'leisure' },
  jigoku: { label: 'Hell pool', icon: '🌋', size: [3, 3], h: 0.6, price: 699, grade: 0, zone: 'edge', lot: Lot.Gravel, apart: 10, tag: 'leisure' },
  ashiyu: { label: 'Foot bath', icon: '🦶', size: [2, 1], h: 0.4, price: 199, grade: 0, zone: 'any', lot: Lot.Plaza, waterside: 'prefer', apart: 6, open: true, tag: 'leisure' },
  ropeway: { label: 'Ropeway', icon: '🚡', size: [6, 3], h: 2.1, price: 1890, grade: 2, zone: 'edge', lot: Lot.Gravel, apart: 60, tag: 'leisure' },
  lakeTorii: { label: 'Lake torii', icon: '⛩️', size: [2, 1], h: 0.85, price: 399, grade: 0, zone: 'any', lot: Lot.Gravel, waterside: true, apart: 60, open: true, tag: 'leisure' },
};

const pick = <T>(f: (i: Info) => T): Record<OnsenKind, T> => Object.fromEntries(ONSEN_KINDS.map((k) => [k, f(ONSEN_INFO[k])])) as Record<OnsenKind, T>;

/** Spread into townKinds' KIND_SPEC (only with NEXT_WORLD on). */
export const ONSEN_SPEC = pick((i): KindSpec => ({
  w: i.size[0], d: i.size[1], zone: i.zone, lot: i.lot, gap: 0,
  ...(i.floors !== undefined ? { floors: i.floors } : {}),
  ...(i.waterside ? { waterside: i.waterside } : {}),
  ...(i.apart ? { apart: i.apart } : {}),
  ...(i.open ? { solid: false } : {}),
}));
/** How tall each stands (towns.ts buildingHeight). */
export function onsenHeight(kind: OnsenKind, floors: number): number {
  const i = ONSEN_INFO[kind];
  return i.floors !== undefined && kind !== 'fukuzumiro' && kind !== 'dogoHonkan' ? floors * 0.26 + i.h : i.h;
}
export const ONSEN_PRICE = pick((i) => i.price);
export const ONSEN_ICON = pick((i) => i.icon);
export const ONSEN_LABEL = pick((i) => i.label);
export const ONSEN_GRADE = pick((i) => i.grade);
/** The gallery's lot (dev/sizes.ts): the widest it rolls, and the most floors. */
export const ONSEN_SIZE = pick((i): [number, number, number] => [typeof i.size[0] === 'number' ? i.size[0] : i.size[0][1], i.size[1], typeof i.floors === 'number' ? i.floors : i.floors?.[1] ?? 1]);
export const ONSEN_TAG = pick((i) => i.tag);
export const isOnsenKind = (k: string): k is OnsenKind => k in ONSEN_INFO;

/**
 * Where world/towns.ts calls out to the onsen towns (world/onsen.ts fills it in when it is loaded, which
 * world/generate.ts does), so towns.ts needn't import them and they may import towns.ts. Only ever called with
 * NEXT_WORLD on.
 */
export const ONSEN_HOOKS: { lay?: (c: Layout, p: TownPlan) => boolean } = {};

/** The real hot-spring town an onsen town is modelled on (world/onsen.ts), in the order a plan's note keeps it. */
export const ONSEN_FLAVOURS = ['hakone', 'kusatsu', 'kinosaki', 'ginzan', 'beppu', 'dogo'] as const;
export type OnsenFlavour = (typeof ONSEN_FLAVOURS)[number];
export const FLAVOUR_LABEL: Record<OnsenFlavour, string> = {
  hakone: 'Hakone', kusatsu: 'Kusatsu', kinosaki: 'Kinosaki', ginzan: 'Ginzan', beppu: 'Beppu', dogo: 'Dōgo',
};

/**
 * What an onsen town is called: one of Japan's hot-spring towns, picked by a hash of the name it was first given (no
 * rng is drawn), each once in a county, with Onsen after it. A town named for one of the six models is built like it:
 * one in three takes its model's own name, and no other ever does.
 */
const ONSEN_NAMES = [
  'Arima', 'Gero', 'Shibu', 'Nyūtō', 'Yufuin', 'Noboribetsu', 'Zaō', 'Yudanaka', 'Shima', 'Ikaho', 'Atami', 'Ibusuki',
  'Kurokawa', 'Shirahama', 'Yamanaka', 'Wakura', 'Tamatsukuri', 'Hōshi', 'Unazuki', 'Nozawa', 'Minakami', 'Shuzenji',
  'Yugawara', 'Naruko', 'Takaragawa', 'Kawayu', 'Jōzankei', 'Sōunkyō', 'Akiu', 'Iizaka', 'Ureshino', 'Takeo', 'Unzen',
  'Kirishima', 'Misasa', 'Yumura', 'Hirayu', 'Yunishigawa', 'Kinugawa', 'Nasu', 'Tsuetate', 'Yunotsu', 'Hanamaki', 'Owani',
];

export function onsenName(first: string, id: number, taken: Set<string>, flavour?: number): string {
  const h = hashString(`${first}#${id}#onsen`) >>> 0;
  const own = flavour !== undefined ? FLAVOUR_LABEL[ONSEN_FLAVOURS[flavour] ?? 'hakone'] : null;
  if (own && h % 3 === 0 && !taken.has(`${own} Onsen`)) { taken.add(`${own} Onsen`); return `${own} Onsen`; }
  for (let k = 0; k < ONSEN_NAMES.length; k++) {
    const name = `${ONSEN_NAMES[(h + k) % ONSEN_NAMES.length]} Onsen`;
    if (!taken.has(name)) { taken.add(name); return name; }
  }
  return `${ONSEN_NAMES[h % ONSEN_NAMES.length]} Onsen`;
}
