import { N, Biome, Flag, RailBit, OPEN_SEA, World, DIRS, inB, idx, edgeMismatch, owner, waterDepth, steepness, tileMean } from './tiles';
import type { CarStats } from '../game/cars';
import { MinHeap } from './rivers';
import { RAIL_HOP, railLift, ridesRails } from './railSurface';

/** What stops a car at an edge: nothing, something it rides up against (a curb, a slope, deep water), or a wall. */
export enum Block { None = 0, Soft = 1, Hard = 2 }

/**
 * Can a car with these stats drive from tile i across edge d? At the edge of the island it looks
 * into the neighbour when one is resident, so a causeway carries traffic straight across the border.
 */
export function canCross(w: World, i: number, d: number, s: CarStats, throughWalls = false): boolean {
  return crossBlock(w, i, d, s, throughWalls) === Block.None;
}

/**
 * Why a car can't cross edge d of tile i, if it can't. A building or the end of the world is a wall,
 * and so are the rails to a car too low-slung to cross them; a curb too tall, ground too steep, water
 * too deep or a railway bank too high is something it rides up against. With `throughWalls` a blocked tile
 * is not itself a wall: the caller meets the building's actual walls inside it (footprint.ts solidAt).
 */
export function crossBlock(w: World, i: number, d: number, s: CarStats, throughWalls = false): Block {
  const x = i % N, z = (i - x) / N;
  const nx = x + DIRS[d][0], nz = z + DIRS[d][1];
  let ow = w, j: number;
  if (inB(nx, nz)) j = idx(nx, nz);
  else {
    const o = owner(w, nx, nz);
    if (o.w === OPEN_SEA || o.w === w) return Block.Hard;   // nothing resident out there
    ow = o.w;
    j = idx(o.x, o.z);
  }
  if (ow.blocked[j] && !throughWalls) return Block.Hard;
  // the ballast: most cars bump over it where the rails ride low; a level crossing (a road over the rails) is plain road
  if ((ow.rail[j] & RailBit.Track) && !ow.road[j]) {
    if (!ridesRails(s)) return Block.Hard;
    if (railLift(ow, j) > s.curb + RAIL_HOP) return Block.Soft;
  }
  // amphibious: afloat, only the water surface matters
  if (s.swimSpeed && waterDepth(w, i) > 0 && waterDepth(ow, j) > 0 && Math.abs(w.water[i] - ow.water[j]) <= 1) return Block.None;
  if (waterDepth(ow, j) > s.wade) return Block.Soft;
  if (edgeMismatch(w, i, d) > s.curb) return Block.Soft;
  if (steepness(ow, j) > s.maxGrade && tileMean(ow, j) > tileMean(w, i)) return Block.Soft;
  return Block.None;
}

/** Track at ground level with no road over it: no edge of the car-agnostic graph runs there (cars may still bump across it, see crossBlock). */
export const railBlocks = (w: World, i: number): boolean => (w.rail[i] & RailBit.Track) !== 0 && !w.road[i];

/** Car-agnostic drivable edges: matching corners and no deep water on either side. */
export function buildEdges(w: World): void {
  const NN = N * N;
  for (let i = 0; i < NN; i++) {
    let bits = 0;
    if (waterDepth(w, i) <= 1 && !w.blocked[i] && !railBlocks(w, i)) {
      const x = i % N, z = (i - x) / N;
      for (let d = 0; d < 4; d++) {
        const nx = x + DIRS[d][0], nz = z + DIRS[d][1];
        if (!inB(nx, nz)) continue;
        const j = idx(nx, nz);
        if (waterDepth(w, j) > 1 || w.blocked[j] || railBlocks(w, j)) continue;
        if (edgeMismatch(w, i, d) !== 0) continue;
        bits |= 1 << d;
      }
    }
    w.edges[i] = bits;
  }
  // a bridge deck carries the road over water or a gorge the ground edges above cannot cross
  for (let i = 0; i < NN; i++) {
    const axis = w.deckAxis[i];
    if (!axis) continue;
    const x = i % N, z = (i - x) / N;
    // (a raised road's platform, axis 3, is open on every side)
    for (const d of axis === 1 ? [0, 2] : axis === 2 ? [1, 3] : [0, 1, 2, 3]) {
      const nx = x + DIRS[d][0], nz = z + DIRS[d][1];
      if (!inB(nx, nz)) continue;
      const j = idx(nx, nz);
      // along the deck, or off its end onto the abutment
      if (w.deckAxis[j] !== axis && (waterDepth(w, j) > 1 || w.blocked[j] || railBlocks(w, j))) continue;
      w.edges[i] |= 1 << d;
      w.edges[j] |= 1 << ((d + 2) % 4);
    }
  }
}

/** Recompute the drivable edges of the border ring only, after a neighbour island arrives or leaves. */
export function refreshSeams(w: World): void {
  for (let k = 0; k < N; k++) {
    for (const i of [idx(0, k), idx(N - 1, k), idx(k, 0), idx(k, N - 1)]) {
      let bits = 0;
      if (waterDepth(w, i) <= 1 && !w.blocked[i] && !railBlocks(w, i)) {
        const x = i % N, z = (i - x) / N;
        for (let d = 0; d < 4; d++) {
          const nx = x + DIRS[d][0], nz = z + DIRS[d][1];
          const o = owner(w, nx, nz);
          if (o.w === OPEN_SEA && !inB(nx, nz)) continue;
          const j = idx(o.x, o.z);
          if (waterDepth(o.w, j) > 1 || o.w.blocked[j] || railBlocks(o.w, j)) continue;
          if (edgeMismatch(w, i, d) !== 0) continue;
          bits |= 1 << d;
        }
      }
      w.edges[i] = bits;
    }
  }
}

/**
 * The seam assertion: how many corners along the borders this cell shares with a resident
 * neighbour disagree where they had no business disagreeing.
 *
 * A step between two mountain terraces, either side of a sea cliff, or on the sea bed is ground
 * both cells worked out identically and a car was never going to cross; those are counted as
 * `walls`. A step between two pieces of ordinary drivable ground is a `crack` — a cliff across a
 * field that would stop a car dead at the border — and on a continent it should always be zero.
 * Costs nothing and would catch a regression in the padded pipeline in a second.
 */
export function seamCheck(w: World): { crack: number; wall: number; worst: number; where: string[] } {
  let crack = 0, wall = 0, worst = 0;
  const where: string[] = [];
  const plain = (u: World, t: number): boolean =>
    u.water[t] < 0 && u.biome[t] !== Biome.Mountain && u.biome[t] !== Biome.Snow
    && u.biome[t] !== Biome.SeaCliff && u.biome[t] !== Biome.Canyon
    && !(u.flags[t] & (Flag.Terrace | Flag.Corridor | Flag.Ramp));
  for (let d = 0; d < 4; d++) {
    const nb = w.nbr[d];
    if (!nb) continue;
    for (let k = 0; k < N; k++) {
      const x = d === 0 ? N - 1 : d === 2 ? 0 : k;
      const z = d === 1 ? N - 1 : d === 3 ? 0 : k;
      const i = idx(x, z);
      const m = edgeMismatch(w, i, d);
      if (m === 0 || m === 99) continue;
      const o = owner(w, x + DIRS[d][0], z + DIRS[d][1]);
      if (o.w !== nb) continue;
      const j = idx(o.x, o.z);
      if (plain(w, i) && plain(nb, j)) {
        crack++;
        if (where.length < 8) where.push(`${w.cx},${w.cz} side ${d} at ${k} (${m} steps)`);
      } else wall++;
      worst = Math.max(worst, m);
    }
  }
  return { crack, wall, worst, where };
}

/** Undirected connected components over w.edges. Returns labels and sizes. */
export function components(w: World): { comp: Int32Array; sizes: number[] } {
  const NN = N * N;
  const comp = new Int32Array(NN).fill(-1);
  const sizes: number[] = [];
  const queue = new Int32Array(NN);
  for (let s = 0; s < NN; s++) {
    if (comp[s] >= 0 || w.edges[s] === 0) continue;
    const id = sizes.length;
    let head = 0, tail = 0;
    queue[tail++] = s;
    comp[s] = id;
    let size = 0;
    while (head < tail) {
      const i = queue[head++];
      size++;
      const x = i % N, z = (i - x) / N;
      const bits = w.edges[i];
      for (let d = 0; d < 4; d++) {
        if (!(bits & (1 << d))) continue;
        const j = idx(x + DIRS[d][0], z + DIRS[d][1]);
        if (comp[j] < 0) { comp[j] = id; queue[tail++] = j; }
      }
    }
    sizes.push(size);
  }
  return { comp, sizes };
}

/** Directed reachability for a specific car from a start tile. */
export function reachable(w: World, start: number, s: CarStats): Uint8Array {
  const NN = N * N;
  const seen = new Uint8Array(NN);
  const queue = new Int32Array(NN);
  let head = 0, tail = 0;
  queue[tail++] = start;
  seen[start] = 1;
  while (head < tail) {
    const i = queue[head++];
    const x = i % N, z = (i - x) / N;
    for (let d = 0; d < 4; d++) {
      const j = idx(x + DIRS[d][0], z + DIRS[d][1]);
      const onDeck = (w.deckAxis[i] || (inB(x + DIRS[d][0], z + DIRS[d][1]) && w.deckAxis[j])) && (w.edges[i] & (1 << d));
      if (!onDeck && !canCross(w, i, d, s)) continue;
      if (!seen[j]) { seen[j] = 1; queue[tail++] = j; }
    }
  }
  return seen;
}

/** A* over drivable edges for the given car; cost favours flat, dry, already-tracked tiles. */
export function astar(w: World, from: number, to: number, s: CarStats, trackFlag: number): number[] | null {
  const NN = N * N;
  const g = new Float32Array(NN).fill(Infinity);
  const prev = new Int32Array(NN).fill(-1);
  const closed = new Uint8Array(NN);
  const tx = to % N, tz = (to - tx) / N;
  const heap = new MinHeap();
  g[from] = 0;
  heap.push(0, from);
  let expansions = 0;
  while (heap.size) {
    const i = heap.pop();
    if (closed[i]) continue;
    closed[i] = 1;
    if (i === to) break;
    if (++expansions > 250000) return null;
    const x = i % N, z = (i - x) / N;
    for (let d = 0; d < 4; d++) {
      if (!canCross(w, i, d, s)) continue;
      const nx = x + DIRS[d][0], nz = z + DIRS[d][1];
      const j = idx(nx, nz);
      if (closed[j]) continue;
      let cost = 1 + 1.5 * Math.abs(tileMean(w, j) - tileMean(w, i));
      if (waterDepth(w, j) > 0) cost += 2.5;
      if (w.flags[j] & trackFlag) cost -= 0.35;
      if (w.road[j]) cost -= 0.5;
      const ng = g[i] + cost;
      if (ng < g[j]) {
        g[j] = ng;
        prev[j] = i;
        heap.push(ng + Math.abs(nx - tx) + Math.abs(nz - tz), j);
      }
    }
  }
  if (!closed[to]) return null;
  const path: number[] = [];
  for (let i = to; i >= 0; i = prev[i]) path.push(i);
  return path.reverse();
}
