import type { KindSpec } from './townKinds';
import { Lot } from './tiles';

/**
 * A ranch's own buildings (GEN 53, world/ranches.ts): the arch over its gate with the ranch's name on it, the
 * hands' bunkhouse, an open-sided hay barn and a round corral. The ranch house, the barn, the stables, the silo and
 * the pump windmill out in the pasture are the kinds the country builds already. One table, spread into the
 * game's per-kind tables (townKinds, towns' heights, economy, estate, hqGrade, cargo labels, traffic tags, the
 * gallery's sizes), as world/wildKinds.ts is. The models are in render/buildings/ranch.ts.
 */

export const RANCH_KINDS = ['ranchGate', 'bunkhouse', 'hayBarn', 'ranchCorral'] as const;

export type RanchKind = (typeof RANCH_KINDS)[number];

interface Info {
  label: string;
  icon: string;
  /** The lot in tiles: W across its front, D deep. */
  size: [number, number];
  /** How tall the model stands, in world units (towns.ts buildingHeight). */
  h: number;
  /** What it costs to knock down (economy.ts). */
  price: number;
  /** As an HQ (hqGrade.ts). */
  grade: 0 | 1 | 2;
  /** An open lot: nothing stops a car (under the arch, inside the corral's rails). */
  open?: boolean;
  lot: Lot;
}

const RANCH_INFO: Record<RanchKind, Info> = {
  ranchGate: { label: 'Ranch gate', icon: '🤠', size: [3, 1], h: 1.05, price: 199, grade: 0, open: true, lot: Lot.None },
  bunkhouse: { label: 'Bunkhouse', icon: '🛏️', size: [2, 1], h: 0.62, price: 899, grade: 1, lot: Lot.None },
  hayBarn: { label: 'Hay barn', icon: '🌾', size: [2, 2], h: 0.85, price: 599, grade: 1, lot: Lot.None },
  ranchCorral: { label: 'Corral', icon: '🐎', size: [3, 3], h: 0.3, price: 299, grade: 0, open: true, lot: Lot.None },
};

const pick = <T>(f: (i: Info) => T): Record<RanchKind, T> => Object.fromEntries(RANCH_KINDS.map((k) => [k, f(RANCH_INFO[k])])) as Record<RanchKind, T>;

/** Spread into townKinds' KIND_SPEC (no town builds them: listed for their sizes and the Passport's Buildings page). */
export const RANCH_SPEC = pick((i): KindSpec => ({
  w: i.size[0], d: i.size[1], zone: 'edge', lot: i.lot, apart: 40, ...(i.open ? { solid: false } : {}),
}));
export const RANCH_HEIGHT = pick((i) => i.h);
export const RANCH_PRICE = pick((i) => i.price);
export const RANCH_ICON = pick((i) => i.icon);
export const RANCH_LABEL = pick((i) => i.label);
export const RANCH_GRADE = pick((i) => i.grade);
export const RANCH_SIZE = pick((i) => i.size);
const isRanchKind = (k: string): k is RanchKind => k in RANCH_INFO;

/** What a ranch is called before the word Ranch: a brand burned into its cattle, or the country it sits in. */
const RANCH_NAMES = [
  'Lazy K', 'Double R', 'Circle T', 'Bar 7', 'Rocking J', 'Flying W', 'Running M', 'Diamond S', 'Crooked C', 'Triple H',
  'Broken Arrow', 'Lone Star', 'Silver Spur', 'Big Sky', 'Red Mesa', 'Dry Creek', 'Elk Horn', 'Coyote Springs', 'Blue Sage',
  'Cottonwood', 'Saddle Butte', 'Twin Pines', 'Sundown', 'Painted Rock', 'High Plains', 'Thunder Ridge', 'Wagon Wheel',
  'Horseshoe', 'Buffalo Gap', 'Longhorn', 'Bar None', 'Lucky 7', 'Hat Creek', 'Sweetwater', 'Rimrock', 'Juniper Flat',
];

/** The name burned into a ranch's arch, from its gate's seed: the arch and the map read the same one. */
export const ranchBrand = (seed: number): string => RANCH_NAMES[(seed >>> 0) % RANCH_NAMES.length];
