import { N, World, RoadType, Biome, Flag, DIRS, idx, waterDepth, steepness, minCorner, maxCorner, edgeMismatch, EDGE_MINE, type Jump } from './tiles';
import { isJunction, layGenerated, rebuildRoadTables, shapeOf } from './roads';
import { linkJump } from './links';
import { buildEdges, components } from './graph';
import { AIR_G, KICK_AT, arcClears, jumpSurface, lipOf } from './jumps';
import type { Rng } from './rng';

/**
 * Laying the jumps and the boost pads (world/jumps.ts), last of all the worldgen so nothing else moves: GEN 52.
 *
 * A jump wants a straight, gentle run-up of RUN tiles ending at the kicker on a bank or a cliff's edge; a gap
 * of MIN_GAP..MAX_GAP tiles straight ahead that a car could not simply drive across (water, or ground well
 * below the lip); and a landing tile with OUT more straight tiles after it. Its arc must clear the gap
 * (jumps.ts arcClears), both ends are joined to the county's roads, and the two ends must be joined to each
 * other some other way too (a bridge, a ford, the long way round), so nobody who takes it is ever stranded.
 */

const RUN = 6, OUT = 3;
const MIN_GAP = 3, MAX_GAP = 11;
/** The most jumps a county gets, how far apart they stand, and how far their roads may reach for the network. */
const MAX_JUMPS = 3, APART = 40, REACH = 50;
/** Boost strips on the county's own long straights: how many, how far apart, and the shortest straight that gets one. */
const MAX_STRIPS = 5, STRIP_APART = 30, STRIP_RUN = 16;
/** Slowest and steepest launches a jump may need (tiles/s, world units/s). */
const V_MIN = 3.2, VY_MIN = 1.2, VY_MAX = 7.5;
/** The most a jump may drop from its lip to its landing, in world units. */
const MAX_DROP = 6;
/** Candidate kickers looked at before the county settles for what it has found. */
const LOOK = 6000;

/** The mean height (steps) of tile i's side facing DIRS[d]. */
const edgeHeight = (w: World, i: number, d: number) => (w.corners[i * 4 + EDGE_MINE[d][0]] + w.corners[i * 4 + EDGE_MINE[d][1]]) / 2;

const KIND_SCORE: Record<Jump['kind'], number> = { river: 3, canyon: 3, cliff: 2.5, water: 2, gap: 1 };

/** The launch a jump from kicker `kick` to `land` along d needs, or null if no sensible one lands it. */
function launch(w: World, kick: number, land: number, d: number, gap: number): { v: number; vy: number } | null {
  const D = gap + 1 - (KICK_AT - 0.5);
  const probe: Jump = { kick, land, d, gap, kind: 'gap', v: 1, vy: 0 };
  const y0 = lipOf(w, probe).y;
  const yL = jumpSurface(w, (land % N) + 0.5, Math.floor(land / N) + 0.5);
  if (y0 - yL > MAX_DROP) return null;
  let v = Math.min(8.2, Math.max(4.6, 4.2 + 0.3 * D));
  let T = D / v;
  let vy = (yL - y0 + (AIR_G * T * T) / 2) / T;
  if (vy < VY_MIN) {
    // a long drop: a hop off the lip, and the jump's speed whatever carries it to the landing in the time it falls
    vy = VY_MIN;
    T = (vy + Math.sqrt(vy * vy + 2 * AIR_G * (y0 - yL))) / AIR_G;
    v = D / T;
    if (v < V_MIN) return null;
  }
  if (vy > VY_MAX) return null;
  return { v, vy };
}

export function placeJumps(w: World, rng: Rng, band: number): void {
  const lo = band + 8, hi = N - band - 8;
  const inside = (x: number, z: number) => x >= lo && z >= lo && x < hi && z < hi;
  /**
   * Ground a jump's road along d can be laid on: open country, dry, nothing on it, and level along the jump
   * (flat, or a plain tilt a step across it): the slowest tank must make the run-up from a standstill.
   */
  const free = (i: number, d: number, edge = false) => {
    if (!(w.townId[i] < 0 && w.portId[i] < 0 && !w.road[i] && !w.rail[i] && !w.blocked[i] && !w.deckAxis[i] && w.feature[i] === 0 &&
      w.water[i] < 0 && w.biome[i] !== Biome.Ocean && steepness(w, i) <= 1 &&
      !(w.flags[i] & (Flag.Field | Flag.Poi | Flag.Track | Flag.Ramp | Flag.Corridor)))) return false;
    // the kicker and the landing may lean a step either way: the one throws whatever comes at it, the other is met at speed
    if (edge) return true;
    const c = w.corners, b = i * 4;
    return d % 2 === 0 ? c[b] === c[b + 1] && c[b + 3] === c[b + 2] : c[b] === c[b + 3] && c[b + 1] === c[b + 2];
  };
  /** A tile the arc may pass over: nothing standing on it, and nothing a car drives along under it. */
  const open = (i: number) => !w.blocked[i] && !w.deckAxis[i] && !w.rail[i] && !w.road[i] && !(w.flags[i] & Flag.Poi) && w.portId[i] < 0;
  const step = (i: number, d: number, k: number) => i + (DIRS[d][0] + DIRS[d][1] * N) * k;

  interface Cand { jump: Jump; score: number }
  const cands: Cand[] = [];
  const pairs: number[] = [];
  for (let z = lo; z < hi; z++) for (let x = lo; x < hi; x++) {
    const i = idx(x, z);
    for (let d = 0; d < 4; d++) {
      // (a kicker never leans up toward its lip: a car crawling onto it is thrown, not rolled back)
      if (!free(i, d, true) || edgeHeight(w, i, d) > edgeHeight(w, i, (d + 2) & 3)) continue;
      const nx = x + DIRS[d][0], nz = z + DIRS[d][1];
      const j = idx(nx, nz);
      // the bank or the edge: water ahead, or ground falling well away
      if (waterDepth(w, j) > 0 || maxCorner(w, j) <= minCorner(w, i) - 2 || minCorner(w, j) <= minCorner(w, i) - 3) pairs.push(i * 4 + d);
    }
  }
  // looked at in a shuffled order of the county's own, so where they go is the seed's and nothing else's
  for (let k = pairs.length - 1; k > 0; k--) {
    const r = Math.floor(rng() * (k + 1));
    [pairs[k], pairs[r]] = [pairs[r], pairs[k]];
  }
  for (let n = 0; n < Math.min(LOOK, pairs.length); n++) {
    const kick = pairs[n] >> 2, d = pairs[n] & 3;
    const kx = kick % N, kz = (kick - kx) / N;
    // the run-up: straight, gentle and joined edge to edge, every tile of it free
    let ok = true;
    for (let k = 1; k <= RUN && ok; k++) {
      const t = step(kick, d, -k);
      const tx = kx - DIRS[d][0] * k, tz = kz - DIRS[d][1] * k;
      ok = inside(tx, tz) && free(t, d) && edgeMismatch(w, t, d) === 0;
    }
    if (!ok) continue;
    // the gap, then the first tile it can land on
    const base = minCorner(w, kick);
    let land = -1, gap = 0, deep = 0, wet = 0, river = 0, canyon = 0;
    for (let g = 1; g <= MAX_GAP + 1; g++) {
      const tx = kx + DIRS[d][0] * g, tz = kz + DIRS[d][1] * g;
      if (!inside(tx, tz)) break;
      const t = idx(tx, tz);
      if (g - 1 >= MIN_GAP && free(t, d, true)) { land = t; gap = g - 1; break; }
      if (!open(t)) break;
      const water = waterDepth(w, t) > 0;
      // a tile of the gap is one a car couldn't just roll across: water, or ground well below the lip
      if (!water && minCorner(w, t) > base - 2) break;
      if (water || maxCorner(w, t) <= base - 2) deep++;
      if (water) wet++;
      if (w.flags[t] & (Flag.River | Flag.Stream)) river++;
      if (w.biome[t] === Biome.Canyon) canyon++;
    }
    if (land < 0 || deep * 2 < gap) continue;
    // the landing and the road on after it
    const lx = land % N, lz = (land - lx) / N;
    for (let k = 1; k <= OUT && ok; k++) {
      const tx = lx + DIRS[d][0] * k, tz = lz + DIRS[d][1] * k;
      ok = inside(tx, tz) && free(idx(tx, tz), d) && edgeMismatch(w, step(land, d, k - 1), d) === 0;
    }
    if (!ok) continue;
    const go = launch(w, kick, land, d, gap);
    if (!go) continue;
    const lipY = lipOf(w, { kick, land, d, gap, kind: 'gap', v: go.v, vy: go.vy }).y;
    const landY = jumpSurface(w, lx + 0.5, lz + 0.5);
    const kind: Jump['kind'] = river && wet ? 'river' : canyon ? 'canyon' : lipY - landY >= 1.5 ? 'cliff' : wet ? 'water' : 'gap';
    const jump: Jump = { kick, land, d, gap, kind, v: go.v, vy: go.vy };
    const arc = arcClears(w, jump);
    // a jump worth the name: daylight under it, not a hop over a ditch
    if (!arc.ok || arc.air < 0.8) continue;
    cands.push({ jump, score: KIND_SCORE[kind] + Math.min(3, arc.air) * 0.5 + gap * 0.08 });
  }
  cands.sort((a, b) => b.score - a.score || a.jump.kick - b.jump.kick);

  const at = (i: number) => [i % N, Math.floor(i / N)];
  for (const c of cands) {
    if (w.jumps.length >= MAX_JUMPS) break;
    const j = c.jump;
    const [kx, kz] = at(j.kick);
    if (w.jumps.some((o) => { const [ox, oz] = at(o.kick); return Math.hypot(ox - kx, oz - kz) < APART; })) continue;
    if (!build(w, j, step)) continue;
    w.jumps.push(j);
  }
  // a new array, so anything that indexed the old one (jumps.ts) looks again
  w.jumps = w.jumps.slice();
  placeStrips(w, rng, lo, hi);
  buildEdges(w);
}

/**
 * Lay jump j's roads and pads, and keep them only if the run-up and the landing both join the network,
 * join each other some other way, and the arc still clears with the roads in. Leaves nothing behind if not.
 */
function build(w: World, j: Jump, step: (i: number, d: number, k: number) => number): boolean {
  const runup: number[] = [], landing: number[] = [], gapTiles: number[] = [];
  for (let k = RUN; k >= 1; k--) runup.push(step(j.kick, j.d, -k));
  runup.push(j.kick);
  for (let k = 1; k <= j.gap; k++) gapTiles.push(step(j.kick, j.d, k));
  for (let k = 0; k <= OUT; k++) landing.push(step(j.land, j.d, k));
  // the free tiles may have been taken by an earlier jump's link roads
  for (const t of [...runup, ...landing]) if (w.road[t] || w.blocked[t]) return false;
  const roads = w.roads.length;
  // the link roads are kept off everything but the two ends they start from: no lane laid along the
  // run-up, and no bridge thrown over the gap the jump is for
  const held = [...runup.slice(1), ...gapTiles, ...landing.slice(0, -1)].filter((t) => !w.blocked[t]);
  for (const t of held) w.blocked[t] = 1;
  const joined = linkJump(w, runup[0], REACH) && linkJump(w, landing[landing.length - 1], REACH);
  for (const t of held) w.blocked[t] = 0;
  const undo = () => {
    w.roads.length = roads;
    rebuildRoadTables(w);
    for (const t of [...runup, ...landing]) w.boost[t] = 0;
  };
  if (!joined) { undo(); return false; }
  layGenerated(w, RoadType.Paved, runup, -1);
  layGenerated(w, RoadType.Paved, landing, -1);
  // two pads on the run-up, for the roar before the kicker
  w.boost[runup[RUN - 4]] = j.d + 1;
  w.boost[runup[RUN - 2]] = j.d + 1;
  const kept = runup.every((t) => w.road[t]) && landing.every((t) => w.road[t]) && gapTiles.every((t) => !w.road[t] && !w.deckAxis[t]);
  if (!kept || !arcClears(w, j).ok) { undo(); return false; }
  // and the long way round: the two ends joined without the jump, so a car that lands is never cut off
  buildEdges(w);
  const { comp } = components(w);
  if (comp[runup[0]] < 0 || comp[runup[0]] !== comp[landing[landing.length - 1]]) { undo(); return false; }
  return true;
}

/**
 * Boost strips on the county's long straight roads out in the country: a pad near each end of the straight,
 * each pointing along it, so traffic both ways gets one with the straight still ahead of it.
 */
function placeStrips(w: World, rng: Rng, lo: number, hi: number): void {
  const NARROW = new Set([RoadType.Dirt, RoadType.Paved, RoadType.TwoLane, RoadType.Gravel]);
  const runs: { tiles: number[]; d: number }[] = [];
  const ok = (r: { type: RoadType }, t: number) => {
    const x = t % N, z = (t - x) / N;
    return x >= lo && z >= lo && x < hi && z < hi && w.townId[t] < 0 && !w.deckAxis[t] && !isJunction(w, t) &&
      w.road[t] === r.type && w.roadCover[t] === 1 && !w.boost[t] && !w.jumps.some((j) => j.kick === t || j.land === t);
  };
  for (const r of w.roads) {
    if (!NARROW.has(r.type) || shapeOf(r.type) !== false) continue;
    const n = r.nodes;
    let s = 0;
    while (s < n.length - 1) {
      const dd = n[s + 1] - n[s];
      if (Math.abs(dd) !== 1 && Math.abs(dd) !== N) { s++; continue; }
      let e = s + 1;
      while (e + 1 < n.length && n[e + 1] - n[e] === dd) e++;
      const tiles = n.slice(s, e + 1);
      // the longest stretch of it the pads may stand on
      let a = 0;
      while (a < tiles.length) {
        if (!ok(r, tiles[a])) { a++; continue; }
        let b = a;
        while (b + 1 < tiles.length && ok(r, tiles[b + 1])) b++;
        if (b - a + 1 >= STRIP_RUN) runs.push({ tiles: tiles.slice(a, b + 1), d: dd === 1 ? 0 : dd === N ? 1 : dd === -1 ? 2 : 3 });
        a = b + 1;
      }
      s = e;
    }
  }
  for (let k = runs.length - 1; k > 0; k--) {
    const r = Math.floor(rng() * (k + 1));
    [runs[k], runs[r]] = [runs[r], runs[k]];
  }
  const placed: number[] = [];
  for (const run of runs) {
    if (placed.length >= MAX_STRIPS) break;
    const m = run.tiles[run.tiles.length >> 1], mx = m % N, mz = (m - mx) / N;
    if (placed.some((p) => Math.hypot((p % N) - mx, Math.floor(p / N) - mz) < STRIP_APART)) continue;
    placed.push(m);
    w.boost[run.tiles[3]] = run.d + 1;
    w.boost[run.tiles[run.tiles.length - 4]] = ((run.d + 2) & 3) + 1;
  }
}

/** Jump j's run-up (kicker last) and landing road (landing tile first), for the gate. */
export function jumpTiles(j: Jump): { runup: number[]; landing: number[] } {
  const s = (i: number, k: number) => i + (DIRS[j.d][0] + DIRS[j.d][1] * N) * k;
  const runup: number[] = [], landing: number[] = [];
  for (let k = RUN; k >= 1; k--) runup.push(s(j.kick, -k));
  runup.push(j.kick);
  for (let k = 0; k <= OUT; k++) landing.push(s(j.land, k));
  return { runup, landing };
}
