import { N, Biome, Flag, RoadType, idx, inB } from '../../tiles';
import { put, type TownPlan } from '../../towns';
import { LAYERS } from '../layers';
import { CARVERS, Dig, nearestSeaSide } from '../water';
import { COMPASS, avenue, dfCores, dfFlat, etoile, finishTown, rect, reserve, ring, spokes, type Pt } from '../kit';
import { discTiles, gridLines, lakeOn } from './shared';
import { gridAround } from './grids';
import type { PlanCtx } from '../types';

/**
 * Corridors and regions (docs/cityplans.html): plans that aren't one blob. Copenhagen's fingers and the linear
 * city reach past the town's square along arms (its footprint is not square: the arms are the town's ground,
 * kept as its claims), Singapore's new towns, the Randstad's ring of cores round a green heart, and Los Angeles.
 */

/** A band of ground `half` either side of the line from (ax, az) running `len` tiles along compass step (dx, dz). */
function bandTiles(ax: number, az: number, dx: number, dz: number, len: number, half: number): number[] {
  const out = new Set<number>();
  const diag = dx !== 0 && dz !== 0;
  const nx = -dz, nz = dx;   // the band's normal
  for (let s = 0; s <= len; s++) {
    const x = ax + dx * s, z = az + dz * s;
    for (let o = -half; o <= half; o++) {
      const tx = Math.round(x + nx * o * (diag ? 0.5 : 1)), tz = Math.round(z + nz * o * (diag ? 0.5 : 1));
      if (inB(tx, tz)) out.add(idx(tx, tz));
      if (diag && inB(tx + dx, tz)) out.add(idx(tx + dx, tz));
    }
  }
  return [...out];
}

/** Can these tiles be a town's arm: dry land, off the seam band, no causeway, no other town? */
function armClear(p: TownPlan, ctx: PlanCtx, tiles: number[]): boolean {
  const { w, land, band, causeway } = ctx;
  for (const i of tiles) {
    const x = i % N, z = (i - x) / N;
    if (x >= p.x0 && z >= p.z0 && x < p.x0 + p.size && z < p.z0 + p.size) continue;
    if (x < band + 3 || z < band + 3 || x >= N - band - 3 || z >= N - band - 3) return false;
    if (!land[i] || w.biome[i] === Biome.Ocean || w.biome[i] === Biome.Town) return false;
    if (causeway?.[i]) return false;
    // nor within a margin of another town's square
    for (const q of ctx.plans) {
      if (q === (p as unknown)) continue;
      if (x >= q.x0 - 8 && z >= q.z0 - 8 && x < q.x0 + q.size + 8 && z < q.z0 + q.size + 8) return false;
    }
  }
  return true;
}

/** Take these tiles into the town as arms: the ground eased gentle, held as town ground, its biome kept to give back. */
function takeArms(p: TownPlan, ctx: PlanCtx, tiles: number[]): void {
  const { w, river } = ctx, E = w.elev;
  const c = (p.carved ??= {});
  const arms = (c.arms ??= []);
  const bio = (c.armBiome ??= new Uint8Array(N * N));
  const set = new Set(tiles);
  // eased toward the mean of the ground round each tile, so a street can run the arm's length
  const next = new Map<number, number>();
  for (const i of set) {
    const x = i % N, z = (i - x) / N;
    let s = 0, n = 0;
    for (let dz = -3; dz <= 3; dz++) for (let dx = -3; dx <= 3; dx++) if (inB(x + dx, z + dz)) { s += E[idx(x + dx, z + dz)]; n++; }
    next.set(i, E[i] * 0.3 + (s / n) * 0.7);
  }
  for (const i of set) {
    const x = i % N, z = (i - x) / N;
    if (x >= p.x0 && z >= p.z0 && x < p.x0 + p.size && z < p.z0 + p.size) continue;
    E[i] = next.get(i)!;
    if (river[i] === 1) river[i] = 0;
    w.flags[i] &= ~Flag.Corridor;
    bio[i] = w.biome[i];
    w.biome[i] = Biome.Town;
    arms.push(i);
  }
}

// ---------------------------------------------------------------------------------------------
// the Finger Plan: Copenhagen

CARVERS.fingers = (p, ctx, rng) => {
  const S = p.size, cx = p.x0 + S / 2, cz = p.z0 + S / 2;
  const sea = nearestSeaSide(new Dig(p, ctx), 40);
  const away = sea < 0 ? -1 : [0, 1, 2, 3].indexOf(sea);
  // the five fingers: the compass steps pointing away from the sea, the longest that will go
  const len = Math.round(S * 0.6), half = p.kind === 'mega' ? 6 : 5;
  const want = COMPASS.filter(([dx, dz]) => {
    if (away < 0) return true;
    const [sx, sz] = [[1, 0], [0, 1], [-1, 0], [0, -1]][away];
    return dx * sx + dz * sz <= 0;
  });
  const order = want.slice().sort(() => rng() - 0.5);
  const taken: [number, number][] = [];
  for (const [dx, dz] of order) {
    if (taken.length >= 5) break;
    const f = dx && dz ? Math.SQRT1_2 : 1;
    const ax = Math.round(cx + dx * (S / 2) * (dx && dz ? 1 : 1)), az = Math.round(cz + dz * (S / 2));
    for (const L of [len, Math.round(len * 0.7), Math.round(len * 0.45)]) {
      const tiles = bandTiles(ax, az, dx, dz, Math.round(L * f), half);
      if (!armClear(p, ctx, tiles)) continue;
      takeArms(p, ctx, tiles);
      taken.push([dx, dz]);
      (p.carved!.note ??= {})[`f${taken.length - 1}`] = COMPASS.findIndex(([a, b]) => a === dx && b === dz) * 1000 + Math.round(L * f);
      break;
    }
  }
  if (taken.length < 3) { if (p.carved) { delete p.carved.arms; } return false; }
  (p.carved!.note!).n = taken.length;
  return true;
};

LAYERS.fingers = (c, p) => {
  const S = p.size, x0 = p.x0, z0 = p.z0, n = p.carved?.note?.n ?? 0;
  if (!n) return false;
  const cx = x0 + S / 2, cz = z0 + S / 2;
  // the palm: the old town, a dense grid, its harbour canals left to the sea
  gridAround(c, gridLines(x0, x0 + S, 6), gridLines(z0, z0 + S, 6), []);
  const stations: Pt[] = [[cx, cz]];
  const axes: number[] = [];
  for (let k = 0; k < n; k++) {
    const code = p.carved!.note![`f${k}`];
    const [dx, dz] = COMPASS[Math.floor(code / 1000)], L = code % 1000;
    const diag = dx !== 0 && dz !== 0;
    const a: Pt = [cx + dx * (S / 2 - 6), cz + dz * (S / 2 - 6)], b: Pt = [cx + dx * (S / 2 + L - 2), cz + dz * (S / 2 + L - 2)];
    // the finger's spine: four lanes (a divided pair on a diagonal) and, square ones, a street either side
    const spine = avenue(c, diag ? RoadType.TwoLane : RoadType.FourLane, a, b, { main: true, four: diag });
    c.ends(spine);
    axes.push(...spine);
    if (!diag) for (const o of [-4, 4]) avenue(c, RoadType.TwoLane, [a[0] - dz * o, a[1] + dx * o], [b[0] - dz * o, b[1] + dx * o], { main: false });
    // a station every so often along it, the town densest round each
    for (let s = 14; s < L; s += 16) {
      const at: Pt = [cx + dx * (S / 2 + s), cz + dz * (S / 2 + s)];
      stations.push(at);
      put(c, 'busStation', { near: at, maxDist: 4 });
      if (!diag) avenue(c, RoadType.TwoLane, [at[0] - dz * 5, at[1] + dx * 5], [at[0] + dz * 5, at[1] - dx * 5], { main: false });
    }
  }
  c.anchors.seat = [cx + 3, cz + 3];
  c.anchors.palace = [cx - 4, cz + 3];
  c.anchors.landmark = [cx + 2, cz - 3];
  c.dfAt = (x, z) => {
    const palm = Math.hypot(x - cx, z - cz) / (S * 0.6);
    let st = Infinity;
    for (const [sx, sz] of stations.slice(1)) st = Math.min(st, Math.hypot(x - sx, z - sz) / 14);
    return Math.min(palm, 0.3 + st * 0.5);
  };
  finishTown(c, { grow: 24, axis: axes });
  return true;
};

// ---------------------------------------------------------------------------------------------
// the linear city: Soria y Mata's Ciudad Lineal, The Line

CARVERS.linear = (p, ctx, rng) => {
  const S = p.size, cx = p.x0 + S / 2, cz = p.z0 + S / 2;
  const half = p.kind === 'mega' ? 9 : 7;
  const first: 0 | 1 = rng() < 0.5 ? 0 : 1;
  for (const axis of [first, (1 - first) as 0 | 1]) {
    const [dx, dz] = axis === 0 ? [1, 0] : [0, 1];
    const got: number[][] = [];
    for (const sgn of [-1, 1]) {
      let L = 0;
      // as far out each way as the ground will take it, in steps
      for (const tryL of [100, 80, 64, 48, 36, 24]) {
        const t = bandTiles(Math.round(cx + sgn * dx * (S / 2)), Math.round(cz + sgn * dz * (S / 2)), sgn * dx, sgn * dz, tryL, half);
        if (armClear(p, ctx, t)) { got.push(t); L = tryL; break; }
      }
      (p.carved ??= {}).note ??= {};
      p.carved.note![sgn < 0 ? 'back' : 'fwd'] = L;
    }
    if (got.length === 2 || (got.length === 1 && got[0].length > 20 * half)) {
      for (const t of got) takeArms(p, ctx, t);
      p.carved!.note!.axis = axis;
      return true;
    }
  }
  if (p.carved) delete p.carved.note;
  return false;
};

LAYERS.linear = (c, p) => {
  const S = p.size, x0 = p.x0, z0 = p.z0, note = p.carved?.note;
  if (!note) return false;
  const axis = note.axis as 0 | 1, back = note.back ?? 0, fwd = note.fwd ?? 0;
  const cx = x0 + S / 2, cz = z0 + S / 2;
  // s along the band, u across it
  const P = (s: number, u: number): Pt => (axis === 0 ? [s + 0.5, u + 0.5] : [u + 0.5, s + 0.5]);
  const sMid = axis === 0 ? cx : cz, uMid = Math.round(axis === 0 ? cz : cx);
  const sA = Math.round(sMid - S / 2 - back + 1), sB = Math.round(sMid + S / 2 + fwd - 2);
  const half = c.t.kind === 'mega' ? 9 : 7;
  // the spine: a boulevard the whole length, a tram street beside it, service streets at the band's edges
  const spine = avenue(c, RoadType.FourLane, P(sA, uMid), P(sB, uMid), { main: true });
  c.ends(spine);
  avenue(c, RoadType.Paved, P(sA, uMid - 3), P(sB, uMid - 3), { main: false });
  for (const o of [-half + 2, half - 2]) avenue(c, RoadType.TwoLane, P(sA, uMid + o), P(sB, uMid + o), { main: false });
  for (let s = sA + 3; s < sB - 2; s += 6) avenue(c, RoadType.TwoLane, P(s, uMid - half + 2), P(s, uMid + half - 2), { main: false, route: false });
  // the square away from the band: kept as green strips either side
  const strip: number[] = [];
  for (let z = z0; z < z0 + S; z++) for (let x = x0; x < x0 + S; x++) {
    const u = axis === 0 ? z : x;
    if (Math.abs(u - uMid) > half) strip.push(idx(x, z));
  }
  reserve(c, strip);
  // the stops along it, the civic buildings strung out between them, the hall at the middle stop
  for (let s = sA + 10; s < sB; s += 20) put(c, 'busStation', { near: P(s, uMid + 4), maxDist: 4 });
  c.anchors.seat = P(Math.round(sMid), uMid + 5);
  c.anchors.landmark = P(Math.round(sMid) + 6, uMid - 5);
  c.anchors.museum = P(Math.round(sMid) - 14, uMid + 5);
  c.anchors.stadium = P(Math.round(sMid) + 24, uMid + 5);
  c.dfAt = dfFlat(0.35);
  finishTown(c, { grow: 4, axis: spine });
  return true;
};

// ---------------------------------------------------------------------------------------------
// new towns: Singapore

CARVERS.newtowns = (p, ctx) => {
  // the central catchment's reservoir
  const S = p.size;
  lakeOn(p, ctx, discTiles(p, [[p.x0 + S * 0.5, p.z0 + S * 0.46, S * 0.08], [p.x0 + S * 0.56, p.z0 + S * 0.4, S * 0.05]]));
  (p.carved ??= {}).seaSide = nearestSeaSide(new Dig(p, ctx), 30);
  return true;
};

LAYERS.newtowns = (c, p) => {
  const S = p.size, x0 = p.x0, z0 = p.z0;
  const cx = x0 + S / 2, cz = z0 + S / 2, side = p.carved?.seaSide ?? 1;
  const toward: Pt = [side === 0 ? 1 : side === 2 ? -1 : 0, side === 1 || side < 0 ? 1 : side === 3 ? -1 : 0];
  // the core on the bay side, a fine grid
  const core: Pt = [cx + toward[0] * S * 0.36, cz + toward[1] * S * 0.36];
  const cs = Math.round(S * 0.2);
  for (let k = -cs; k <= cs; k += 5) {
    avenue(c, RoadType.TwoLane, c.clampPt(core[0] + k, core[1] - cs / 2), c.clampPt(core[0] + k, core[1] + cs / 2), { main: false });
    avenue(c, RoadType.TwoLane, c.clampPt(core[0] - cs, core[1] + k / 2), c.clampPt(core[0] + cs, core[1] + k / 2), { main: false });
  }
  // the catchment: forest kept round the reservoir
  reserve(c, [...discTiles(p, [[cx, cz - S * 0.04, S * 0.17]], 2)]);
  // the new towns in a ring round it, each a ring road round its hub
  const hubs: Pt[] = [];
  for (let k = 0; k < 5; k++) {
    const a = Math.atan2(toward[1], toward[0]) + Math.PI * (0.45 + k * 0.275);
    const hub: Pt = [cx + Math.cos(a) * S * 0.33, cz + Math.sin(a) * S * 0.33];
    hubs.push(hub);
    ring(c, RoadType.TwoLane, hub[0], hub[1], 6, 3, { main: false });
    spokes(c, RoadType.TwoLane, hub[0], hub[1], 1, 6, COMPASS.slice(0, 4), { main: false });
    put(c, 'busStation', { near: hub, maxDist: 3 });
    put(c, 'mall', { near: [hub[0] + 3, hub[1] + 3], maxDist: 5 });
  }
  // the expressways: round the ring of towns, and in from each to the core
  for (let k = 0; k < hubs.length; k++) c.street(RoadType.FourLane, [hubs[k], hubs[(k + 1) % hubs.length]]);
  for (const h of hubs) c.ends(c.street(RoadType.TwoLane, [h, core]));
  // the roles round the bay
  c.anchors.landmark = [core[0] - toward[1] * 4, core[1] - toward[0] * 4];
  c.anchors.seat = [core[0] + toward[1] * 6, core[1] + toward[0] * 6];
  c.anchors.garden = [core[0] + toward[0] * 6, core[1] + toward[1] * 6];
  put(c, 'botanicalGarden', { near: [core[0] + toward[0] * 8, core[1] + toward[1] * 8], maxDist: 8 });
  c.dfAt = dfCores(c, [core, ...hubs], S * 0.22);
  finishTown(c, { grow: 26 });
  return true;
};

// ---------------------------------------------------------------------------------------------
// polycentric: the Randstad, the Ruhr

LAYERS.polycentric = (c, p) => {
  const S = p.size, x0 = p.x0, z0 = p.z0;
  const q = Math.round(S * 0.36);
  const cores: Pt[] = [[x0 + q / 2 + 1, z0 + q / 2 + 1], [x0 + S - q / 2 - 1, z0 + q / 2 + 1], [x0 + q / 2 + 1, z0 + S - q / 2 - 1], [x0 + S - q / 2 - 1, z0 + S - q / 2 - 1]];
  // four cores, each with a plan of its own: a grid, an étoile, a ring and radials, a grid with a diagonal
  const [A, B, C, D] = cores;
  gridAround(c, gridLines(A[0] - q / 2, A[0] + q / 2, 5), gridLines(A[1] - q / 2, A[1] + q / 2, 5), [[x0 + q, z0, x0 + S, z0 + S], [x0, z0 + q, x0 + S, z0 + S]]);
  etoile(c, RoadType.TwoLane, B[0], B[1], 3, Math.round(q * 0.45), COMPASS);
  ring(c, RoadType.TwoLane, C[0], C[1], Math.round(q * 0.3), Math.round(q * 0.12));
  ring(c, RoadType.TwoLane, C[0], C[1], Math.round(q * 0.15), 3);
  spokes(c, RoadType.TwoLane, C[0], C[1], 2, Math.round(q * 0.48), COMPASS.slice(0, 4));
  for (let k = -q / 2 + 2; k < q / 2; k += 6) {
    avenue(c, RoadType.TwoLane, [D[0] + k, D[1] - q / 2 + 1], [D[0] + k, D[1] + q / 2 - 1], { main: false, route: false });
    avenue(c, RoadType.TwoLane, [D[0] - q / 2 + 1, D[1] + k], [D[0] + q / 2 - 1, D[1] + k], { main: false, route: false });
  }
  avenue(c, RoadType.TwoLane, [D[0] - q / 2 + 1, D[1] - q / 2 + 1], [D[0] + q / 2 - 2, D[1] + q / 2 - 2], { four: true });
  // the motorway ring between them, and the green heart it runs round: farmland kept open
  const ring4 = ring(c, RoadType.FourLane, x0 + S / 2, z0 + S / 2, Math.round(S * 0.3), 0, { main: true });
  for (const k of cores) c.ends(c.street(RoadType.TwoLane, [k, [x0 + S / 2 + (k[0] - x0 - S / 2) * 0.6, z0 + S / 2 + (k[1] - z0 - S / 2) * 0.6]]));
  reserve(c, rect(x0 + S * 0.3, z0 + S * 0.3, Math.round(S * 0.4), Math.round(S * 0.4)).filter((i) => !c.w.road[i]));
  // the roles: the parliament in one, the port's town in one, the university in one
  c.anchors.seat = [A[0] + 2, A[1] + 2];
  c.anchors.palace = [B[0] + 5, B[1] + 5];
  c.anchors.landmark = [D[0] + 2, D[1] - 2];
  c.anchors.museum = [C[0] + 4, C[1] + 4];
  put(c, 'parliament', { near: [B[0] - 5, B[1] + 5], maxDist: 5 });
  put(c, 'university', { near: [C[0] - 5, C[1] - 5], maxDist: 6 });
  c.dfAt = dfCores(c, cores, q * 0.8);
  finishTown(c, { grow: 20, axis: ring4 });
  return true;
};

// ---------------------------------------------------------------------------------------------
// the freeway city: Los Angeles

LAYERS.freeway = (c, p) => {
  const S = p.size, x0 = p.x0, z0 = p.z0;
  const F = Math.round(S * 0.32);
  const xs = gridLines(x0, x0 + S, F), zs = gridLines(z0, z0 + S, F);
  // the low grid of streets over everything, then the freeways through it (and one on the diagonal)
  gridAround(c, gridLines(x0, x0 + S, 6), gridLines(z0, z0 + S, 6), []);
  for (const x of xs) c.ends(avenue(c, RoadType.FourLane, [x, z0 + 1], [x, z0 + S - 1], { main: true }));
  for (const z of zs) c.ends(avenue(c, RoadType.FourLane, [x0 + 1, z], [x0 + S - 1, z], { main: true }));
  const diag = avenue(c, RoadType.TwoLane, [x0 + 2.5, z0 + S - 2.5], [x0 + S * 0.6, z0 + S - S * 0.6 + 2], { four: true, main: true });
  // a ring round every interchange
  for (const x of xs) for (const z of zs) ring(c, RoadType.TwoLane, x - 0.5, z - 0.5, 4, 2, { main: false });
  // several small downtowns rather than one; the observatory on the hill
  const towns: Pt[] = [[x0 + S * 0.55, z0 + S * 0.5], [x0 + S * 0.2, z0 + S * 0.55], [x0 + S * 0.75, z0 + S * 0.2], [x0 + S * 0.8, z0 + S * 0.82]];
  c.anchors.seat = [towns[0][0] + 3, towns[0][1] + 3];
  c.anchors.landmark = towns[0];
  c.anchors.stadium = [x0 + S * 0.4, z0 + S * 0.2];
  put(c, 'observatory', { highest: true, zone: 'any' });
  c.dfAt = dfCores(c, towns, S * 0.2);
  finishTown(c, { grow: 10, axis: diag });
  return true;
};
