/// <reference lib="webworker" />
import { generateWorld } from './generate';
import { surveyOf, type CellSurvey } from './survey';
import { hqLotsOf, type HqLot } from '../game/hqCarry';

/**
 * `survey` asks only for the county at a glance (world/survey.ts): the world itself is thrown away here.
 * With `world` (a copy of an island in memory, the player's edits and all) nothing is generated: that
 * world is surveyed instead, so a changed county is surveyed off the main thread (Surveyor.later).
 */
export interface GenRequest { id: number; seed: string; cx: number; cz: number; survey?: boolean; world?: Record<string, unknown>; lots?: boolean; hero?: number }
export interface GenReply { id: number; cx: number; cz: number; world: Record<string, unknown>; survey?: CellSurvey; lots?: HqLot[]; hero?: HeroBits | null; failed?: boolean }

/** `hero`: what a picture of one building needs (world/farHero.ts), its kind, size, look and its town's style; null when there is none of that uid. */
export interface HeroBits { kind: string; arch: string; w: number; d: number; floors: number; seed: number; facing: number; style?: string; derelict?: boolean }

/** Every ArrayBuffer behind the island's typed arrays, so they move rather than copy. */
function buffers(w: Record<string, unknown>): Transferable[] {
  const out: Transferable[] = [];
  for (const v of Object.values(w)) if (ArrayBuffer.isView(v)) out.push(v.buffer as ArrayBuffer);
  return out;
}

self.onmessage = (e: MessageEvent<GenRequest>) => {
  const { id, cx, cz, survey, lots } = e.data;
  // a survey that throws answers 'failed' rather than taking the worker down (an uncaught error there
  // closed the region map's only worker for good: the user's map stuck at one county, 22 Oct 2026)
  if ((survey && !lots) || e.data.hero !== undefined) {
    try { reply(e.data); } catch { (self as unknown as Worker).postMessage({ id, cx, cz, world: {}, failed: true, ...(e.data.hero !== undefined ? { hero: null } : {}) } satisfies GenReply); }
    return;
  }
  reply(e.data);
};

function reply(q: GenRequest): void {
  const { id, seed, cx, cz, survey, world, lots } = q;
  if (world) {
    const s = surveyOf(world as unknown as Parameters<typeof surveyOf>[0]);
    (self as unknown as Worker).postMessage({ id, cx, cz, world: {}, survey: s } satisfies GenReply, buffers(s as unknown as Record<string, unknown>));
    return;
  }
  const w = generateWorld(seed, cx, cz);
  // one building's look, for a card's picture of a county that isn't loaded (world/farHero.ts): the world is thrown away
  if (q.hero !== undefined) {
    const b = w.allBuildings.find((x) => x.uid === q.hero);
    const hero: HeroBits | null = b && !b.gone ? {
      kind: b.kind, arch: b.style ?? w.towns.find((t) => t.buildings.includes(b))?.style ?? 'classic', w: b.w, d: b.d, floors: b.floors,
      seed: b.seed, facing: b.facing, ...(b.style ? { style: b.style } : {}), ...(b.derelict ? { derelict: true } : {}),
    } : null;
    (self as unknown as Worker).postMessage({ id, cx, cz, world: {}, hero } satisfies GenReply);
    return;
  }
  // every building in the county a fleet could make its HQ (game/hqCarry.ts): the world is thrown away
  if (lots) {
    (self as unknown as Worker).postMessage({ id, cx, cz, world: {}, lots: hqLotsOf(w) } satisfies GenReply);
    return;
  }
  if (survey) {
    const s = surveyOf(w);
    (self as unknown as Worker).postMessage({ id, cx, cz, world: {}, survey: s } satisfies GenReply, buffers(s as unknown as Record<string, unknown>));
    return;
  }
  // neighbour links are main-thread state and must not travel
  const out = { ...w } as unknown as Record<string, unknown>;
  delete out.nbr;
  // the county at a glance too, worked out here rather than on the main thread as the cell arrives
  // (its map stamp and survey were a tenth of a second there); used unless the save has changed the cell
  const s = surveyOf(w);
  (self as unknown as Worker).postMessage({ id, cx, cz, world: out, survey: s } satisfies GenReply, [...buffers(out), ...buffers(s as unknown as Record<string, unknown>)]);
}
