/**
 * Big country: the geology that belongs to a whole continent rather than to one county.
 *
 * Minecraft's height update decided where the land goes high from a few slow fields and then built it
 * from explicit shapes; so does this. Three fields — how far inland (the macro `contField`), how
 * uplifted, how worn — decide what kind of country a place is, and four families of shapes build it:
 * great ranges along hashed spines, tablelands whose edges break up into mesas, buttes and spires, the
 * rivers that drain the high ground all the way to the sea, and the canyons those rivers cut where
 * they cross a tableland.
 *
 * Every function here is pure in the global tile. A county asks about the tiles of its padded grid and
 * gets exactly the answer its neighbour gets for the same tiles, which is the whole of why a range or a
 * river two thousand tiles long lines up at every border it crosses. Nothing floods, erodes or searches
 * per county; the rivers are traced over a coarse lattice built only from the fields, so any county can
 * trace any river.
 */
import { N, SEA } from './tiles';
import { Noise2D, smoothstep, clamp } from './noise';
import { mulberry32, hash2 } from './rng';
import { CONT_THR, cellKind, contField, continentality, worldMode } from './macro';
import { blobScale } from './landforms';

// ---------------- heights ----------------

/** The highest land an ordinary place reaches, in steps: the world as it was. */
const BASE_CAP = 24;
/** The roof: the highest any land may stand, in steps, in the heart of a high-country zone. */
export const ROOF = 96;
/** The broad rise every tile of a high-country zone stands on, in steps at full uplift. */
const UPLAND = 14;
/**
 * How much a continent's heart rises over its coasts, in steps, for the rivers' routing only: it is what
 * they run down to the sea, but it never lifts the ground itself, so a lowland county is as it was.
 */
const TILT = 8;
/** How many lattice steps downstream a river looks to set its level, so it never runs uphill. */
const LEVEL_LOOK = 24;

/** The height cap at an uplift of U. */
export const capOf = (U: number): number => BASE_CAP + (ROOF - BASE_CAP) * U;

// ---------------- great ranges ----------------

/** Ranges are hash-placed one per square of this many tiles, and only where the land is uplifted. */
const RANGE_GRID = 480;
/** Tiles the ground a range stands on is pushed about, so its foot wanders. */
const RANGE_WARP = 16;
/** Foothills run this far out beyond the foot of a range's body. */
const FOOTHILLS = 110;
/**
 * A range's crest below this many steps is smooth all the way up, a mountain any car with the grip can
 * drive over. Only the few taller crests stand in a jagged walled core, and only over their top share.
 */
const CORE_MIN = 62;
const CORE_SHARE = 0.18;

/** A village's bench cut into a mountainside, a saddle levelled for a pass village, or a knoll's top. */
export interface Bench { x: number; z: number; h: number; r: number; kind: 'shelf' | 'pass' | 'summit'; name: number }

export interface Range {
  /** The spine as x, z pairs, the crest at each point, and the arc length at each. */
  pts: number[]; crest: number[]; s: number[];
  /** The crest at its highest, in steps above zero. */
  h: number;
  /** Passes: where along the spine (arc length), how deep the crest dips there (a share), how long the dip is. */
  passes: { s: number; dip: number; w: number }[];
  benches: Bench[];
  /** Bounding box of the spine, grown by everything the range reaches. */
  x0: number; z0: number; x1: number; z1: number;
}

/** What a range does at a tile. */
interface RangeHit {
  /** The range's body, in steps above zero (0 where none reaches). */
  m: number;
  /** Foothills laid over the lowland, in steps. */
  foot: number;
  /** In the walled core: cliff bands, stepped every few levels. */
  core: boolean;
  /** How mountainous the tile is, 0..1, for the biome. */
  mask: number;
  /** A bench levels the ground here: town land, not mountain. */
  bench: boolean;
}

// ---------------- tablelands ----------------

/** Mesas, buttes and spires stand on a lattice of this many tiles, below a tableland's edge. */
const BUTTE_GRID = 44;
/** How far out from a tableland's edge the broken country runs, in tiles. */
const BREAKUP = 150;

/** A mesa, butte or spire standing below a tableland's edge. */
interface Butte {
  x: number; z: number; r: number; top: number; base: number; ax: number; aspect: number;
  /** The one direction a road can climb it (NaN for none). */
  ramp: number;
  shape: ((ang: number) => number) | null;
  reach: number;
}

interface PlateauHit {
  /** The ground a tableland or a butte puts here, in steps (−Infinity for none). */
  m: number;
  /** A sheer face: walled at every few levels. */
  wall: boolean;
  /** A flat top a town may take: the table itself, or a mesa's top. */
  top: boolean;
  /** Rock: the banded walls and talus. */
  rock: boolean;
  /** 0..1: how far into a tableland this is (1 on the table, 0 off it). */
  on: number;
  /** The top of a butte no road climbs: flat, and no place for a town. */
  sealed: boolean;
}

// ---------------- great rivers ----------------

/** The coarse lattice the rivers are traced over, in tiles. */
const RC = 32;
/** The longest a river is traced, in lattice steps: any source further than this cannot reach a county. */
const TRACE = 48;
/** A source must stand at least this high, in steps, to start a great river. */
const SOURCE_MIN = SEA + 13;
/** The furthest a valley's carving reaches from its river, in tiles. */
const VALLEY_REACH = 80;

/** One stretch of great river, between two lattice points, with everything needed to carve it. */
interface RiverEdge {
  ax: number; az: number; bx: number; bz: number;
  /** Water level at each end, in steps (whole). */
  la: number; lb: number;
  /** Width in tiles at each end. */
  wa: number; wb: number;
  /** Flow at the downstream end (sources, weighted by how far they have come). */
  flow: number;
  /** Through a tableland: cut as a canyon. */
  canyon: boolean;
  /** Lateral wander, tiles, and its sign, from a hash of the edge. */
  amp: number; amp2: number;
  /** The samples of its curve, x, z pairs. */
  curve: number[];
}

/** A lake a great river ends in, having found no way lower. */
interface RiverLake { x: number; z: number; r: number; level: number; salt: number }

interface RiverNet { edges: RiverEdge[]; lakes: RiverLake[]; mouths: { x: number; z: number }[] }

/** What the rivers do to the padded grid: the carving, the channel, its level, and the canyon walls. */
interface RiverRaster {
  /** The most the ground may stand at each tile after carving, in steps (Infinity for untouched). */
  carve: Float32Array;
  /** 1 on the channel. */
  chan: Uint8Array;
  /** Water level on the channel and in the lakes, steps (−128 for none). */
  lvl: Int8Array;
  /** 1 on a canyon's walls, which are stepped and walled. */
  wall: Uint8Array;
  /** 1 anywhere a canyon was cut, for the biome and the colour. */
  canyon: Uint8Array;
  /** 1 on a terminal lake. */
  lake: Uint8Array;
  /** Tiles from the channel's centreline (for anything that wants the river's banks). */
  dist: Float32Array;
}

// ---------------- the fields ----------------

const cache = new Map<number, Geology>();

/** The geology of a seed, built once per worker and kept for a few seeds. */
export function geologyFor(seedHash: number): Geology {
  let g = cache.get(seedHash);
  if (!g) {
    g = new Geology(seedHash);
    if (cache.size > 2) cache.delete(cache.keys().next().value as number);
    cache.set(seedHash, g);
  }
  return g;
}

/**
 * Test hooks: `force` puts a high-country zone at a global tile whatever the seed rolled, for the gate,
 * so every seed checks a range, a tableland, a canyon and a great river. Keyed by seed hash.
 */
const GEO_FORCE = new Map<number, { x: number; z: number; r: number }>();

export class Geology {
  private nU: Noise2D;
  private nW: Noise2D;
  private nP: Noise2D;
  private nR: Noise2D;
  private kinds = new Map<number, boolean>();
  private rangeMemo = new Map<number, Range | null>();
  private hcMemo = new Map<number, number>();
  private nextMemo = new Map<number, number>();
  private butteMemo = new Map<number, Butte | null>();
  private netMemo = new Map<string, RiverNet>();
  /** Every source a window has traced, so a county next door reuses the walk. */
  private traceMemo = new Map<number, number[]>();
  readonly on: boolean;

  constructor(readonly seedHash: number) {
    const rng = mulberry32(seedHash ^ 0x6e01061c);
    this.nU = new Noise2D(rng);
    this.nW = new Noise2D(rng);
    this.nP = new Noise2D(rng);
    this.nR = new Noise2D(rng);
    // an archipelago has no continents, so no high country: every question answers nothing, fast
    this.on = worldMode() !== 'islands';
  }

  // ---- where ----

  private isCont(cx: number, cz: number): boolean {
    const k = (cx + 32768) * 65536 + (cz + 32768);
    let v = this.kinds.get(k);
    if (v === undefined) {
      v = cellKind(this.seedHash, cx, cz) === 'continent';
      if (this.kinds.size > 40000) this.kinds.clear();
      this.kinds.set(k, v);
    }
    return v;
  }

  /**
   * How clear of every coast a tile is, 0..1: deep inside the macro field, and far from any cell that
   * is not a county. Both parts are continuous in the tile, so nothing jumps at a border; together they
   * keep high ground well away from any sea, where the shore clamp would otherwise cut it off in a cliff.
   */
  coastGuard(gx: number, gz: number): number {
    const m = contField(this.seedHash, gx / N, gz / N) - CONT_THR;
    const inland = smoothstep(0.07, 0.17, m);
    if (inland <= 0) return 0;
    const cx = Math.floor(gx / N), cz = Math.floor(gz / N);
    let d = 256;
    for (let dz = -1; dz <= 1; dz++) {
      for (let dx = -1; dx <= 1; dx++) {
        if (this.isCont(cx + dx, cz + dz)) continue;
        const x0 = (cx + dx) * N, z0 = (cz + dz) * N;
        const ex = Math.max(x0 - gx, 0, gx - (x0 + N)), ez = Math.max(z0 - gz, 0, gz - (z0 + N));
        d = Math.min(d, Math.hypot(ex, ez));
      }
    }
    return inland * smoothstep(48, 200, d);
  }

  /** How uplifted the land is, 0..1: zero almost everywhere, one in the heart of a high-country zone. */
  uplift(gx: number, gz: number): number {
    if (!this.on) return 0;
    const raw = 0.5 + 0.5 * this.nU.fbm(gx / N * 0.12 + 3.7, gz / N * 0.12 - 8.1, 3);
    let u = smoothstep(0.63, 0.83, raw);
    const f = GEO_FORCE.get(this.seedHash);
    if (f) u = Math.max(u, smoothstep(f.r, f.r * 0.35, Math.hypot(gx - f.x, gz - f.z)));
    if (u <= 0) return 0;
    return u * this.coastGuard(gx, gz);
  }

  /** How worn the land is, 0..1: low is jagged, high is rolling. */
  wear(gx: number, gz: number): number {
    return clamp(0.5 + 0.75 * this.nW.fbm(gx / N * 0.25 + 11.3, gz / N * 0.25 + 5.9, 2), 0, 1);
  }

  /** The broad rise under a high-country zone, in steps: part of every tile's lowland there. */
  lift(_gx: number, _gz: number, U: number): number {
    return UPLAND * U;
  }

  // ---- great ranges ----

  private range(i: number, j: number): Range | null {
    const key = (i + 32768) * 65536 + (j + 32768);
    if (this.rangeMemo.has(key)) return this.rangeMemo.get(key)!;
    const s = this.seedHash & 0xffff;
    const h = (k: number) => hash2(i, j, s + 5100 + k);
    let out: Range | null = null;
    const cx = (i + 0.2 + 0.6 * h(1)) * RANGE_GRID, cz = (j + 0.2 + 0.6 * h(2)) * RANGE_GRID;
    const Uc = this.uplift(cx, cz);
    // a tableland country is flat-topped: ranges rise round it, not through it
    if (Uc > 0.08 && h(3) < 0.95 && this.tableGate(cx, cz) < 0.5) {
      const ang = this.nR.fbm(cx / N * 0.08 + 17, cz / N * 0.08 + 3, 2) * Math.PI * 2;
      const L = 900 + 1100 * h(4);
      const ux = Math.cos(ang), uz = Math.sin(ang);
      const H = Math.min(ROOF - SEA, 32 + 64 * Math.sqrt(Uc) * (0.8 + 0.2 * h(5)));
      const pts: number[] = [], crest: number[] = [], sArr: number[] = [];
      const K = 6;
      for (let k = 0; k < K; k++) {
        const t = k / (K - 1) - 0.5;
        const wob = (hash2(i * 7 + k, j, s + 5200) - 0.5) * 220 * (k === 0 || k === K - 1 ? 0.4 : 1);
        const x = cx + ux * L * t - uz * wob, z = cz + uz * L * t + ux * wob;
        pts.push(x, z);
        // the crest follows the uplift under it and tapers toward the spine's ends
        const Up = this.uplift(x, z);
        const end = 0.55 + 0.45 * Math.sin(Math.PI * (k / (K - 1)));
        const flat = 1 - 0.85 * this.tableGate(x, z);
        crest.push(Math.max(10, H * end * flat * (0.35 + 0.65 * smoothstep(0, 0.6, Up)) * (0.85 + 0.3 * hash2(i, j * 5 + k, s + 5300))));
        sArr.push(k === 0 ? 0 : sArr[k - 1] + Math.hypot(x - pts[k * 2 - 2], z - pts[k * 2 - 1]));
      }
      const len = sArr[K - 1];
      const passes: Range['passes'] = [];
      const nPass = 1 + (h(6) < 0.55 ? 1 : 0);
      for (let p = 0; p < nPass; p++) {
        // a pass is where a road crosses and a village stands: somewhere in the middle of a county if it can be
        let sv = len * (0.28 + 0.44 * hash2(i, j, s + 5400 + p));
        for (let k = 0; k < 12; k++) {
          const cand = len * (0.25 + 0.5 * hash2(i, j, s + 5430 + p * 16 + k));
          const t = cand / len, idx = Math.min(K - 2, Math.floor(t * (K - 1))), f = t * (K - 1) - idx;
          const x = pts[idx * 2] + (pts[idx * 2 + 2] - pts[idx * 2]) * f, z = pts[idx * 2 + 1] + (pts[idx * 2 + 3] - pts[idx * 2 + 1]) * f;
          const lx = ((x % N) + N) % N, lz = ((z % N) + N) % N;
          if (lx > 80 && lx < N - 80 && lz > 80 && lz < N - 80 && passes.every((q) => Math.abs(q.s - cand) > 200)) { sv = cand; break; }
        }
        passes.push({ s: sv, dip: 0.5 + 0.12 * hash2(i, j, s + 5410 + p), w: 34 + 16 * hash2(i, j, s + 5420 + p) });
      }
      const hMax = Math.max(...crest);
      const reach = bodyWidth(hMax) + FOOTHILLS + RANGE_WARP + 4;
      let x0 = Infinity, z0 = Infinity, x1 = -Infinity, z1 = -Infinity;
      for (let k = 0; k < K; k++) { x0 = Math.min(x0, pts[k * 2]); x1 = Math.max(x1, pts[k * 2]); z0 = Math.min(z0, pts[k * 2 + 1]); z1 = Math.max(z1, pts[k * 2 + 1]); }
      out = { pts, crest, s: sArr, h: hMax, passes, benches: [], x0: x0 - reach, z0: z0 - reach, x1: x1 + reach, z1: z1 + reach };
      this.placeBenches(out, i, j);
    }
    this.rangeMemo.set(key, out);
    if (this.rangeMemo.size > 4000) this.rangeMemo.delete(this.rangeMemo.keys().next().value as number);
    return out;
  }

  /** The villages a range makes room for: one at each pass, and shelves cut into its flanks. */
  private placeBenches(r: Range, i: number, j: number): void {
    const s = this.seedHash & 0xffff;
    const at = (sv: number): { x: number; z: number; nx: number; nz: number } => {
      for (let k = 1; k < r.s.length; k++) {
        if (sv > r.s[k] && k < r.s.length - 1) continue;
        const t = clamp((sv - r.s[k - 1]) / Math.max(1e-6, r.s[k] - r.s[k - 1]), 0, 1);
        const ax = r.pts[k * 2 - 2], az = r.pts[k * 2 - 1], bx = r.pts[k * 2], bz = r.pts[k * 2 + 1];
        const l = Math.hypot(bx - ax, bz - az) || 1;
        return { x: ax + (bx - ax) * t, z: az + (bz - az) * t, nx: -(bz - az) / l, nz: (bx - ax) / l };
      }
      return { x: r.pts[0], z: r.pts[1], nx: 0, nz: 1 };
    };
    // A town keeps well clear of a county's borders, so a bench is only worth cutting where the tile it
    // levels (back along the warp) lies in the middle of some county.
    const interior = (x: number, z: number): boolean => {
      const [wx, wz] = this.rangeWarp(x, z);
      const lx = (((2 * x - wx) % N) + N) % N, lz = (((2 * z - wz) % N) + N) % N;
      return lx > 70 && lx < N - 70 && lz > 70 && lz < N - 70;
    };
    const len = r.s[r.s.length - 1];
    const used: number[] = [];
    // a pass village sits on the saddle itself
    for (const p of r.passes) {
      const q = at(p.s);
      const c = crestAt(r, p.s);
      if (c < 18 || !interior(q.x, q.z)) continue;
      r.benches.push({ x: q.x, z: q.z, h: c - 1, r: 19, kind: 'pass', name: Math.floor(hash2(Math.floor(q.x), Math.floor(q.z), s + 5500) * 1e6) });
      used.push(p.s);
    }
    // shelves partway up the flanks, on either side; a low ridge's village takes its top instead
    const want = 1 + Math.floor(hash2(i, j, s + 5600) * 3);
    let made = 0;
    for (let k = 0; k < 24 && made < want; k++) {
      const sv = len * (0.1 + 0.8 * hash2(i, j, s + 5610 + k));
      if (used.some((u) => Math.abs(u - sv) < 110)) continue;
      const c = crestAt(r, sv);
      const q = at(sv);
      if (c < 30) {
        if (c < 16 || !interior(q.x, q.z) || c < 1.1 + UPLAND * this.uplift(q.x, q.z) + 7) continue;
        r.benches.push({ x: q.x, z: q.z, h: c - 1.5, r: 18, kind: 'summit', name: Math.floor(hash2(i + k, j, s + 5660) * 1e6) });
      } else {
        const f = 0.36 + 0.22 * hash2(i, j, s + 5620 + k);
        const d = distForHeight(c, f * c);
        const side = hash2(i, j, s + 5630 + k) < 0.5 ? -1 : 1;
        const bx = q.x + q.nx * d * side, bz = q.z + q.nz * d * side;
        // a shelf is only a shelf where it stands well above the upland round the range
        if (!interior(bx, bz) || f * c < 1.1 + UPLAND * this.uplift(bx, bz) + 8) continue;
        r.benches.push({ x: bx, z: bz, h: f * c, r: 18, kind: 'shelf', name: Math.floor(hash2(i, j + k, s + 5640) * 1e6) });
      }
      used.push(sv);
      made++;
    }
  }

  /** Every great range whose reach touches the box, in global tiles. */
  rangesNear(x0: number, z0: number, x1: number, z1: number): Range[] {
    if (!this.on) return [];
    const out: Range[] = [];
    const m = 1500;
    const i0 = Math.floor((x0 - m) / RANGE_GRID), i1 = Math.floor((x1 + m) / RANGE_GRID);
    const j0 = Math.floor((z0 - m) / RANGE_GRID), j1 = Math.floor((z1 + m) / RANGE_GRID);
    for (let j = j0; j <= j1; j++) {
      for (let i = i0; i <= i1; i++) {
        const r = this.range(i, j);
        if (!r || r.x1 < x0 || r.z1 < z0 || r.x0 > x1 || r.z0 > z1) continue;
        out.push(r);
      }
    }
    return out;
  }

  /** The warped point a tile reads its ranges from. */
  rangeWarp(gx: number, gz: number): [number, number] {
    const u = gx / N, v = gz / N;
    return [gx + RANGE_WARP * this.nR.fbm(u * 1.9 + 41, v * 1.9 + 7, 2), gz + RANGE_WARP * this.nR.fbm(u * 1.9 - 13, v * 1.9 + 29, 2)];
  }

  /** What the great ranges do at a tile. */
  rangeAt(ranges: Range[], gx: number, gz: number): RangeHit {
    const hit: RangeHit = { m: 0, foot: 0, core: false, mask: 0, bench: false };
    if (!ranges.length) return hit;
    const [wx, wz] = this.rangeWarp(gx, gz);
    const u = gx / N, v = gz / N;
    for (const r of ranges) {
      if (wx < r.x0 || wz < r.z0 || wx > r.x1 || wz > r.z1) continue;
      // nearest point on the spine
      let best = Infinity, bs = 0;
      for (let k = 1; k < r.s.length; k++) {
        const ax = r.pts[k * 2 - 2], az = r.pts[k * 2 - 1], bx = r.pts[k * 2], bz = r.pts[k * 2 + 1];
        const vx = bx - ax, vz = bz - az, l2 = vx * vx + vz * vz;
        const t = clamp(((wx - ax) * vx + (wz - az) * vz) / l2, 0, 1);
        const dx = wx - ax - vx * t, dz = wz - az - vz * t;
        const dd = dx * dx + dz * dz;
        if (dd < best) { best = dd; bs = r.s[k - 1] + (r.s[k] - r.s[k - 1]) * t; }
      }
      let d = Math.sqrt(best);
      // the ends of the spine round off rather than stopping square
      const len = r.s[r.s.length - 1];
      const past = Math.max(0, -bs, bs - len);
      d = Math.hypot(d, past);
      let c = crestAt(r, clamp(bs, 0, len));
      // summits and cols along the crest
      c *= 0.9 + 0.2 * (0.5 + 0.5 * this.nR.fbm(bs * 0.012 + r.pts[0] * 0.001, r.h * 0.1, 2));
      const bw = bodyWidth(c);
      let m = body(d, c);
      if (m > 0) {
        // spurs and gullies down the flanks, kept gentle enough to leave the slope bound alone
        m += 1.4 * smoothstep(4, 14, m) * (this.nR.ridged(u * 9 + 5, v * 9 + 3, 2) - 0.55);
      }
      const coreLine = c * (1 - coreOf(c));
      // by distance, not height: the spurs may dip the ground, never the wall that has to stand there
      const core = c >= CORE_MIN && d <= (coreOf(c) * c) / 1.8 + 1;
      // foothills: rolling ground rising toward the range, fading out beyond its foot
      const ft = smoothstep(bw + FOOTHILLS, bw * 0.6, d);
      const foot = ft > 0 ? ft * (3 + 0.09 * c) * this.nR.billow(u * 4.4 + 9, v * 4.4 + 1, 3) : 0;
      if (m > hit.m) {
        hit.m = m; hit.core = core;
        hit.mask = smoothstep(0.1 * c, 0.3 * c, m);
      }
      hit.foot = Math.max(hit.foot, foot);
      // the benches: level ground cut in and built out, blended back to the slope at the ground's own grade
      for (const b of r.benches) {
        const db = Math.hypot(wx - b.x, wz - b.z);
        if (db > b.r + 30) continue;
        const slack = Math.max(0, db - b.r) * 0.75;
        const here = Math.max(hit.m, 0);
        const lev = clamp(here, b.h - slack, b.h + slack);
        if (db <= b.r + 30 && Math.abs(lev - here) > 1e-6) {
          hit.m = lev;
          if (db <= b.r) { hit.core = false; hit.mask = 0; hit.bench = true; }
          else hit.core = hit.core && lev >= coreLine;
        }
        if (db <= b.r + 2) { hit.bench = true; hit.mask = 0; hit.core = false; }
      }
    }
    return hit;
  }

  // ---- tablelands ----

  /** The tableland field: its value, the threshold, the table's height, and how much it is gated in. */
  private tableRaw(gx: number, gz: number): { v: number; thr: number; pt: number; base: number; g: number } | null {
    const U = this.uplift(gx, gz);
    if (U < 0.12) return null;
    const W = this.wear(gx, gz);
    const g = smoothstep(0.12, 0.5, U) * smoothstep(0.66, 0.4, W);
    if (g <= 0) return null;
    const v = 0.5 + 0.5 * this.nP.fbm(gx / N * 0.9 + 2.3, gz / N * 0.9 + 7.1, 3);
    // The gate decides where tables stand (the threshold), never how tall they are: a table's height
    // over the upland is a slow field of its own, so its top stays level however fast the gate changes.
    const tall = 24 + 12 * (0.5 + 0.5 * this.nP.fbm(gx / N * 0.35 + 51.1, gz / N * 0.35 - 9.4, 2));
    return { v, thr: 1.0 - 0.48 * g, pt: 1.1 + UPLAND * U + tall, base: 1.1 + UPLAND * U, g };
  }

  /** How much of a tableland country this is, 0..1: where the tables stand, whether or not one does here. */
  tableGate(gx: number, gz: number): number {
    const U = this.uplift(gx, gz);
    if (U < 0.12) return 0;
    return smoothstep(0.12, 0.5, U) * smoothstep(0.66, 0.4, this.wear(gx, gz));
  }

  /** Signed distance to a tableland's edge (tiles, positive on the table), and its height, or null off the gate. */
  tableAt(gx: number, gz: number): { sd: number; pt: number; base: number } | null {
    const r = this.tableRaw(gx, gz);
    if (!r) return null;
    const e = 3;
    const vx = 0.5 + 0.5 * this.nP.fbm((gx + e) / N * 0.9 + 2.3, gz / N * 0.9 + 7.1, 3) - (0.5 + 0.5 * this.nP.fbm((gx - e) / N * 0.9 + 2.3, gz / N * 0.9 + 7.1, 3));
    const vz = 0.5 + 0.5 * this.nP.fbm(gx / N * 0.9 + 2.3, (gz + e) / N * 0.9 + 7.1, 3) - (0.5 + 0.5 * this.nP.fbm(gx / N * 0.9 + 2.3, (gz - e) / N * 0.9 + 7.1, 3));
    const grad = Math.max(1e-4, Math.hypot(vx, vz) / (2 * e));
    return { sd: clamp((r.v - r.thr) / grad, -400, 400), pt: r.pt, base: r.base };
  }

  /** A butte on the lattice below a tableland's edge, all its shape worked out once, or null where there is none. */
  private butte(i: number, j: number): Butte | null {
    const key = (i + 32768) * 65536 + (j + 32768);
    if (this.butteMemo.has(key)) return this.butteMemo.get(key)!;
    const s = this.seedHash & 0xffff;
    const hs = (k: number) => hash2(i, j, s + 5710 + k);
    const x = (i + 0.15 + 0.7 * hash2(i, j, s + 5700)) * BUTTE_GRID, z = (j + 0.15 + 0.7 * hash2(i, j, s + 5701)) * BUTTE_GRID;
    const t = hash2(i, j, s + 5702) < 0.62 ? this.tableAt(x, z) : null;
    let out: Butte | null = null;
    if (t && t.sd < -10 && t.sd > -BREAKUP) {
      // mesas nearest the table, buttes further out, spires last
      const f = clamp((-t.sd - 10) / (BREAKUP - 10), 0, 1);
      const r = (30 - 26.5 * Math.pow(f, 0.65)) * (0.7 + 0.5 * hs(1));
      const top = t.base + (t.pt - t.base) * (0.96 - 0.36 * f) * (0.9 + 0.1 * hs(2));
      out = {
        x, z, r, top, base: t.base, ax: hs(3) * Math.PI, aspect: 1 + 0.45 * hs(4), ramp: r >= 12 && hs(6) < 0.5 ? hs(5) * Math.PI * 2 : NaN,
        shape: r > 5 ? blobScale(x, z, 4471 + (s & 0xff), 0.14) : null,
        reach: r * 1.5 + ((top - t.base) * 0.55) / 1.6 + ((top - t.base) * 0.45) / 0.55 + 4,
      };
      // a mesa's ramp runs all the way down to the country below
      if (!Number.isNaN(out.ramp)) out.reach = Math.max(out.reach, r * 1.5 + (top - t.base) / 0.55 + 4);
    }
    this.butteMemo.set(key, out);
    if (this.butteMemo.size > 20000) this.butteMemo.delete(this.butteMemo.keys().next().value as number);
    return out;
  }

  /** The tablelands, and the mesas, buttes and spires their edges break into, at a tile. */
  plateauAt(gx: number, gz: number): PlateauHit {
    const hit: PlateauHit = { m: -Infinity, wall: false, top: false, rock: false, on: 0, sealed: false };
    if (!this.on) return hit;
    const t = this.tableAt(gx, gz);
    const u = gx / N, v = gz / N;
    const sd = t ? t.sd : -1e9, pt = t ? t.pt : 0, rel = t ? t.pt - t.base : 0;
    hit.on = smoothstep(-4, 6, sd);
    if (!t) { /* no table here, but a butte's skirt may still reach */ } else if (sd >= 0) {
      hit.m = pt + 1.6 * this.nP.billow(u * 6 + 3, v * 6 + 9, 2);
      hit.top = sd > 3;
    } else {
      const a = -sd;
      const wr = (rel * 0.5) / 2.0;
      // here and there a road climbs the scarp: a ramp at a road's grade where a slow field crosses a line
      const q = Math.abs(this.nP.fbm(gx / N * 1.3 + 31.7, gz / N * 1.3 + 17.3, 2));
      if (q < 0.045) hit.m = pt - 0.34 * a;
      else if (a <= wr) { hit.m = pt - 2.0 * a; hit.wall = true; hit.rock = true; }
      else { hit.m = pt - rel * 0.5 - 0.55 * (a - wr); hit.rock = hit.m > pt - rel * 0.7; }
    }
    if (sd < 4) {
      const gi = Math.floor(gx / BUTTE_GRID), gj = Math.floor(gz / BUTTE_GRID);
      for (let dj = -2; dj <= 2; dj++) {
        for (let di = -2; di <= 2; di++) {
          const b = this.butte(gi + di, gj + dj);
          if (!b) continue;
          const ex = gx - b.x, ez = gz - b.z;
          if (ex * ex + ez * ez > b.reach * b.reach) continue;
          const along = ex * Math.cos(b.ax) + ez * Math.sin(b.ax), across = -ex * Math.sin(b.ax) + ez * Math.cos(b.ax);
          const ang = Math.atan2(ez, ex);
          const d = Math.hypot(along / b.aspect, across) / (b.shape ? b.shape(ang) : 1);
          const spire = b.r < 4;
          let ramp = false;
          if (!Number.isNaN(b.ramp)) {
            let da = ang - b.ramp;
            da = Math.atan2(Math.sin(da), Math.cos(da));
            ramp = Math.abs(da) < 0.13;
          }
          let m: number, wall = false, topHere = false;
          // only a mesa a road can climb is a place for a village
          if (d <= b.r) { m = b.top; topHere = !Number.isNaN(b.ramp); }
          else if (ramp) m = b.top - 0.55 * (d - b.r);
          else if (spire) { m = b.top - 2.4 * (d - b.r); wall = true; }
          else {
            const tall = b.top - b.base, run = (tall * 0.55) / 1.6;
            if (d - b.r <= run) { m = b.top - 1.6 * (d - b.r); wall = true; }
            else m = b.top - tall * 0.55 - 0.55 * (d - b.r - run);
          }
          if (m > hit.m) { hit.m = m; hit.wall = wall; hit.top = topHere; hit.rock = d > b.r && m > b.top - (b.top - b.base) * 0.7; hit.sealed = d <= b.r && !topHere; }
        }
      }
    }
    return hit;
  }

  // ---- great rivers ----

  /** The coarse lattice point (i, j): where it stands (jittered), in global tiles. */
  private nodePos(i: number, j: number): [number, number] {
    const s = this.seedHash & 0xffff;
    return [(i + 0.5 + 0.7 * (hash2(i, j, s + 5800) - 0.5)) * RC, (j + 0.5 + 0.7 * (hash2(i, j, s + 5801) - 0.5)) * RC];
  }

  private nodeSea(i: number, j: number): boolean {
    const [x, z] = this.nodePos(i, j);
    if (!this.isCont(Math.floor(x / N), Math.floor(z / N))) return true;
    return contField(this.seedHash, x / N, z / N) < CONT_THR + 0.02;
  }

  /**
   * The lowest the ground can be at a tile, before any local relief: the lowland's floor, lifted over a
   * high-country zone, and the great ranges standing on it. The rivers run down this and their water is
   * set by it, so a river never stands above the ground either side of it. The tablelands are left out
   * on purpose: a river keeps to the country's own level and cuts straight through a table, which is
   * what a canyon is.
   */
  floorAt(gx: number, gz: number): number {
    const U = this.uplift(gx, gz);
    let h = SEA + 1.1 + this.lift(gx, gz, U);
    if (U > 0) {
      const rs = this.rangesNear(gx - 1, gz - 1, gx + 1, gz + 1);
      if (rs.length) h = Math.max(h, SEA + this.rangeAt(rs, gx, gz).m - 3);
    }
    return h;
  }

  /** The floor at lattice point (i, j), and what the water runs down there (the floor tilted toward the sea). */
  private nodeFloor(i: number, j: number): [number, number] {
    const key = (i + 32768) * 65536 + (j + 32768);
    let v = this.hcMemo.get(key);
    if (v === undefined) {
      const [x, z] = this.nodePos(i, j);
      v = this.nodeSea(i, j) ? -100 : this.floorAt(x, z);
      if (this.hcMemo.size > 200000) this.hcMemo.clear();
      this.hcMemo.set(key, v);
    }
    if (v <= -100) return [-100, -100];
    const [x, z] = this.nodePos(i, j);
    return [v, v + TILT * continentality(this.seedHash, x / N, z / N)];
  }

  private nodeH(i: number, j: number): number {
    return this.nodeFloor(i, j)[1];
  }

  /**
   * The level a river holds at lattice point k before its own flow cuts it deeper: a step under the floor,
   * but never under anything downstream within reach, so the water only ever falls toward the sea. A
   * function of the point and the fixed walk below it, so every county works out the same number.
   */
  private baseLevel(k: number): number {
    let m = -Infinity, kk = k;
    for (let n = 0; n <= LEVEL_LOOK; n++) {
      const i = Math.floor(kk / 65536) - 32768, j = (kk % 65536) - 32768;
      const f = this.nodeFloor(i, j)[0];
      m = Math.max(m, f <= -100 ? SEA : Math.floor(f) - 1);
      const nx = this.next(i, j);
      if (nx < 0) break;
      kk = nx;
    }
    return Math.max(SEA, m);
  }

  /** Where the water goes from lattice point (i, j): the key of its lowest neighbour, −1 for a pit, −2 at the sea. */
  private next(i: number, j: number): number {
    const key = (i + 32768) * 65536 + (j + 32768);
    let v = this.nextMemo.get(key);
    if (v === undefined) {
      const h = this.nodeH(i, j);
      if (h <= -100) v = -2;
      else {
        let best = h, bi = 0, bj = 0;
        for (let dj = -1; dj <= 1; dj++) {
          for (let di = -1; di <= 1; di++) {
            if (!di && !dj) continue;
            // a diagonal step is longer, so it must fall further to win
            const hn = this.nodeH(i + di, j + dj) + (di && dj ? 0.12 : 0);
            if (hn < best - 1e-9) { best = hn; bi = di; bj = dj; }
          }
        }
        v = best < h ? (i + bi + 32768) * 65536 + (j + bj + 32768) : -1;
      }
      if (this.nextMemo.size > 200000) this.nextMemo.clear();
      this.nextMemo.set(key, v);
    }
    return v;
  }

  /** The walk from a source, as lattice keys, ending at the sea, a pit, or the trace's length. */
  private trace(key: number): number[] {
    const have = this.traceMemo.get(key);
    if (have) return have;
    const out = [key];
    let k = key;
    for (let n = 0; n < TRACE; n++) {
      const i = Math.floor(k / 65536) - 32768, j = (k % 65536) - 32768;
      const nx = this.next(i, j);
      if (nx < 0) break;
      out.push(nx);
      k = nx;
    }
    if (this.traceMemo.size > 20000) this.traceMemo.clear();
    this.traceMemo.set(key, out);
    return out;
  }

  /**
   * Every great river that reaches the box, with its levels, widths and lakes. Sources are hashed onto
   * the high lattice points of a window as wide as the longest trace, so a neighbouring county collects
   * the same sources, walks them the same way and adds up the same flows.
   */
  riversNear(x0: number, z0: number, x1: number, z1: number): RiverNet {
    const net: RiverNet = { edges: [], lakes: [], mouths: [] };
    if (!this.on) return net;
    const memoKey = `${x0},${z0},${x1},${z1}`;
    const have = this.netMemo.get(memoKey);
    if (have) return have;
    const s = this.seedHash & 0xffff;
    const reach = TRACE * RC * 1.42 + VALLEY_REACH + RC;
    const i0 = Math.floor((x0 - reach) / RC / 4), i1 = Math.floor((x1 + reach) / RC / 4);
    const j0 = Math.floor((z0 - reach) / RC / 4), j1 = Math.floor((z1 + reach) / RC / 4);
    /** Per lattice key: the flow through it, and whether it lies on a trace that touches the box. */
    const flow = new Map<number, number>();
    const traces: number[][] = [];
    for (let bj = j0; bj <= j1; bj++) {
      for (let bi = i0; bi <= i1; bi++) {
        if (hash2(bi, bj, s + 5810) > 0.6) continue;
        const i = bi * 4 + Math.floor(hash2(bi, bj, s + 5811) * 4), j = bj * 4 + Math.floor(hash2(bi, bj, s + 5812) * 4);
        const [x, z] = this.nodePos(i, j);
        // cheap first: only uplifted ground is high enough to start one
        if (this.uplift(x, z) < 0.08) continue;
        const h = this.nodeH(i, j);
        if (h < SOURCE_MIN) continue;
        // tableland country is canyon country: its rivers start in box canyons cut into the table
        const tg = this.tableGate(x, z);
        if (hash2(bi, bj, s + 5813) > clamp((h - SOURCE_MIN + 4) / 22 + 0.6 * tg, 0, 0.95)) continue;
        traces.push(this.trace((i + 32768) * 65536 + (j + 32768)));
      }
    }
    // flow: every source counts, and counts for more the further it has come
    for (const tr of traces) {
      tr.forEach((k, n) => flow.set(k, (flow.get(k) ?? 0) + 1 + 0.12 * n));
    }
    const levelOf = (k: number): number => {
      const f = flow.get(k) ?? 1;
      // a bigger river has cut itself deeper
      return Math.max(SEA, this.baseLevel(k) - Math.min(2, Math.floor(f / 4)));
    };
    const widthOf = (f: number) => Math.min(10, 0.8 + 1.45 * Math.sqrt(f));
    const seen = new Set<string>();
    const lakes = new Set<number>();
    for (const tr of traces) {
      for (let n = 0; n + 1 < tr.length; n++) {
        const a = tr[n], b = tr[n + 1];
        const ek = `${a}>${b}`;
        if (seen.has(ek)) continue;
        seen.add(ek);
        const ai = Math.floor(a / 65536) - 32768, aj = (a % 65536) - 32768;
        const bi = Math.floor(b / 65536) - 32768, bj = (b % 65536) - 32768;
        const [ax, az] = this.nodePos(ai, aj);
        const [bx, bz] = this.nodePos(bi, bj);
        if (Math.max(ax, bx) < x0 - VALLEY_REACH - 20 || Math.min(ax, bx) > x1 + VALLEY_REACH + 20
          || Math.max(az, bz) < z0 - VALLEY_REACH - 20 || Math.min(az, bz) > z1 + VALLEY_REACH + 20) continue;
        const bSea = this.nodeH(bi, bj) <= -100;
        const fa = flow.get(a) ?? 1, fb = flow.get(b) ?? fa;
        const la = levelOf(a), lb = bSea ? SEA : Math.min(la, levelOf(b));
        // near a tableland: its tiles may cut a canyon wherever the table stands
        const near = (x: number, z: number) => { const t = this.tableAt(x, z); return !!t && t.sd > -70; };
        const canyon = near(ax, az) || (!bSea && near(bx, bz)) || near((ax + bx) / 2, (az + bz) / 2);
        const eh = (k: number) => hash2(ai * 3 + bi, aj * 3 + bj, s + 5820 + k);
        const len = Math.hypot(bx - ax, bz - az);
        const amp = (eh(1) < 0.5 ? -1 : 1) * Math.min(9, 0.2 * len) * (0.5 + 0.5 * eh(2));
        const amp2 = (eh(3) - 0.5) * Math.min(5, 0.1 * len);
        const curve: number[] = [];
        const px = -(bz - az) / (len || 1), pz = (bx - ax) / (len || 1);
        for (let q = 0; q <= 12; q++) {
          const t = q / 12;
          const off = amp * Math.sin(Math.PI * t) + amp2 * Math.sin(2 * Math.PI * t);
          curve.push(ax + (bx - ax) * t + px * off, az + (bz - az) * t + pz * off);
        }
        net.edges.push({ ax, az, bx, bz, la, lb, wa: widthOf(fa), wb: widthOf(fb), flow: fb, canyon, amp, amp2, curve });
        if (bSea) net.mouths.push({ x: bx, z: bz });
      }
      // a river that found no way lower ends in a lake
      const last = tr[tr.length - 1];
      const li = Math.floor(last / 65536) - 32768, lj = (last % 65536) - 32768;
      if (this.next(li, lj) === -1 && !lakes.has(last)) {
        lakes.add(last);
        const [lx, lz] = this.nodePos(li, lj);
        const f = flow.get(last) ?? 1;
        if (lx > x0 - 60 && lx < x1 + 60 && lz > z0 - 60 && lz < z1 + 60) {
          net.lakes.push({ x: lx, z: lz, r: Math.min(26, 9 + 2.4 * Math.sqrt(f)), level: levelOf(last), salt: (li * 31 + lj) & 0xfff });
        }
      }
    }
    this.netMemo.set(memoKey, net);
    if (this.netMemo.size > 16) this.netMemo.delete(this.netMemo.keys().next().value as string);
    return net;
  }

  /**
   * Carve the rivers into a padded grid of W × W tiles whose first tile is global (gx0, gz0). The
   * channel is set a step or two into the floodplain, the floodplain into the land, and a canyon's
   * stair of walls and benches into a tableland; everything is a min over the edges near a tile, so
   * two edges meeting at a lattice point blend without a seam.
   */
  rasterRivers(net: RiverNet, gx0: number, gz0: number, W: number): RiverRaster {
    const WW = W * W;
    const r: RiverRaster = {
      carve: new Float32Array(WW).fill(Infinity), chan: new Uint8Array(WW), lvl: new Int8Array(WW).fill(-128),
      wall: new Uint8Array(WW), canyon: new Uint8Array(WW), lake: new Uint8Array(WW), dist: new Float32Array(WW).fill(Infinity),
    };
    const s = this.seedHash & 0xffff;
    for (const e of net.edges) {
      let x0 = Infinity, z0 = Infinity, x1 = -Infinity, z1 = -Infinity;
      for (let q = 0; q < e.curve.length; q += 2) {
        x0 = Math.min(x0, e.curve[q]); x1 = Math.max(x1, e.curve[q]); z0 = Math.min(z0, e.curve[q + 1]); z1 = Math.max(z1, e.curve[q + 1]);
      }
      const R = VALLEY_REACH;
      const px0 = Math.max(0, Math.floor(x0 - R - gx0)), px1 = Math.min(W - 1, Math.ceil(x1 + R - gx0));
      const pz0 = Math.max(0, Math.floor(z0 - R - gz0)), pz1 = Math.min(W - 1, Math.ceil(z1 + R - gz0));
      if (px0 > px1 || pz0 > pz1) continue;
      const nSeg = e.curve.length / 2 - 1;
      for (let pz = pz0; pz <= pz1; pz++) {
        const gz = gz0 + pz + 0.5;
        for (let px = px0; px <= px1; px++) {
          const gx = gx0 + px + 0.5;
          // nearest point on the curve
          let best = Infinity, bt = 0;
          for (let q = 0; q < nSeg; q++) {
            const ax = e.curve[q * 2], az = e.curve[q * 2 + 1], bx = e.curve[q * 2 + 2], bz = e.curve[q * 2 + 3];
            const vx = bx - ax, vz = bz - az, l2 = vx * vx + vz * vz || 1;
            const t = clamp(((gx - ax) * vx + (gz - az) * vz) / l2, 0, 1);
            const dx = gx - ax - vx * t, dz = gz - az - vz * t;
            const dd = dx * dx + dz * dz;
            if (dd < best) { best = dd; bt = (q + t) / nSeg; }
          }
          const d = Math.sqrt(best);
          if (d > R) continue;
          const i = pz * W + px;
          const lv = Math.floor(e.la + (e.lb - e.la) * bt + 1e-6);
          const half = (e.wa + (e.wb - e.wa) * bt) / 2;
          let carve: number, wall = false, cut = false;
          // the valley: a channel set into a floodplain, set into the land
          const plain = 3 + half * 1.4;
          const ov = d - half;
          const valley = ov <= 0 ? lv - (half > 3 ? 2 : 1.4) : ov <= plain ? lv + 2 : lv + 2 + 0.6 * (ov - plain);
          const tb = e.canyon ? this.tableAt(gx, gz) : null;
          const k = tb ? smoothstep(-34, -4, tb.sd) : 0;
          if (k > 0 && tb) {
            // a canyon's stair: inner gorge, a platform, the red wall, a talus slope, the caprock
            const wear = this.wear(gx, gz);
            const tip = SEA + tb.pt;
            const plat = 3 + 11 * wear * (0.6 + 0.4 * (0.5 + 0.5 * Math.sin(gx * 0.021 + gz * 0.017 + (s & 63))));
            const depth = Math.max(0, tip - lv);
            const upper = 8 + Math.max(0, depth - 27) / 0.5;
            const legs: [number, number, boolean][] = [[3.2, 8, true], [plat, 0.15 * plat, false], [3.2, 8, true], [upper, 0.5 * upper, false], [2, 5, true], [60, 30, false]];
            let h = lv + 1, o = d - half;
            if (o <= 0) carve = lv - 1.5;
            else {
              carve = NaN;
              for (const [len, rise, isWall] of legs) {
                if (o <= len) { carve = h + (rise * o) / len; wall = isWall; break; }
                o -= len; h += rise;
              }
              if (Number.isNaN(carve)) carve = h + 0.5 * o;
            }
            carve = valley + (carve - valley) * k;
            wall = wall && k > 0.5;
            cut = k > 0.5 && d > half;
          } else carve = valley;
          if (carve < r.carve[i]) {
            r.carve[i] = carve;
            r.wall[i] = wall ? 1 : 0;
            r.canyon[i] = cut ? 1 : 0;
          }
          if (d < r.dist[i]) r.dist[i] = d;
          if (d <= half) {
            r.chan[i] = 1;
            r.lvl[i] = r.lvl[i] === -128 ? lv : Math.min(r.lvl[i], lv);
          }
        }
      }
    }
    for (const L of net.lakes) {
      const shape = blobScale(L.x, L.z, 4481 + L.salt, 0.25);
      const px0 = Math.max(0, Math.floor(L.x - L.r * 1.4 - 10 - gx0)), px1 = Math.min(W - 1, Math.ceil(L.x + L.r * 1.4 + 10 - gx0));
      const pz0 = Math.max(0, Math.floor(L.z - L.r * 1.4 - 10 - gz0)), pz1 = Math.min(W - 1, Math.ceil(L.z + L.r * 1.4 + 10 - gz0));
      for (let pz = pz0; pz <= pz1; pz++) {
        for (let px = px0; px <= px1; px++) {
          const gx = gx0 + px + 0.5, gz = gz0 + pz + 0.5;
          const d = Math.hypot(gx - L.x, gz - L.z) / shape(Math.atan2(gz - L.z, gx - L.x));
          const i = pz * W + px;
          const carve = d <= L.r ? L.level - 1.5 - 1.5 * (1 - d / L.r) : L.level + 1 + 0.6 * (d - L.r);
          if (carve < r.carve[i]) { r.carve[i] = carve; r.wall[i] = 0; }
          if (d <= L.r) { r.lake[i] = 1; r.lvl[i] = L.level; }
        }
      }
    }
    return r;
  }
}

/** The share of a crest its walled core takes: none below CORE_MIN. */
const coreOf = (c: number): number => (c >= CORE_MIN ? CORE_SHARE : 0);

/** How far from its spine a range of crest c reaches before it meets the lowland. */
function bodyWidth(c: number): number {
  const k = coreOf(c);
  return (k * c) / 1.8 + ((0.75 - k) * c) / 0.58 + (0.25 * c) / 0.4;
}

/**
 * A range's body at distance d from its spine: for the tallest a jagged walled core under the crest,
 * then long smooth flanks at a grade the ground may take, and a gentle skirt.
 */
function body(d: number, c: number): number {
  const k = coreOf(c);
  const d1 = (k * c) / 1.8, d2 = d1 + ((0.75 - k) * c) / 0.58;
  if (d <= d1) return c - 1.8 * d;
  if (d <= d2) return c * (1 - k) - 0.58 * (d - d1);
  return c * 0.25 - 0.4 * (d - d2);
}

/** The distance from the spine at which a range of crest c stands h high. */
function distForHeight(c: number, h: number): number {
  let lo = 0, hi = bodyWidth(c);
  for (let k = 0; k < 30; k++) {
    const m = (lo + hi) / 2;
    if (body(m, c) > h) lo = m; else hi = m;
  }
  return (lo + hi) / 2;
}

/** The crest at arc length s, with the passes taken out. */
function crestAt(r: Range, s: number): number {
  let k = 1;
  while (k < r.s.length - 1 && s > r.s[k]) k++;
  const t = clamp((s - r.s[k - 1]) / Math.max(1e-6, r.s[k] - r.s[k - 1]), 0, 1);
  let c = r.crest[k - 1] + (r.crest[k] - r.crest[k - 1]) * t;
  for (const p of r.passes) {
    const q = (s - p.s) / p.w;
    c *= 1 - p.dip * Math.exp(-q * q);
  }
  return c;
}
