import { N, World, RoadType, RailBit, Biome, Feature, Flag, Under, DIRS, EDGE_MINE, idx, inB, edgeMismatch, steepness, waterDepth, type Road, type Town } from './tiles';
import { ROAD_INFO, findRoute, layGenerated, layRoad, nodeTiles, ownDeckClash, rebuildRoadTables, resolveBridges, shapeOf, straightenRoute, wetCost, type RouteCost } from './roads';
import { railBlocks } from './graph';
import { crossingAt, landBorder } from './macro';
import { cutCorners } from './diagonalRoutes';
import { NEXT_WORLD } from './nextWorld';

/**
 * Country roads: fairly direct, happy to join an existing road, bridging rivers when they must. Where
 * the land climbs faster than a road likes they wind rather than charge straight up: that, on a big
 * enough mountain, is a flight of switchbacks.
 */
const LINK: RouteCost = { climb: 2.5, slope: 0.8, turn: 0.3, reuse: 0.5, crowd: 0, grade: 0.45, gradePen: 7 };
/** A second or third road between the same two towns: it must find its own way, not merge with the first. */
const ALT: RouteCost = { climb: 2.5, slope: 0.8, turn: 0.3, reuse: 1, crowd: 2.5, grade: 0.45, gradePen: 7 };
/**
 * The longest bridge a generated road may throw, in tiles: a great river near its mouth or a canyon at
 * its narrows. Anything longer than an ordinary span is hung from towers.
 */
const LONG_SPAN = 40;
const SUSPENSION_FROM = 13;
/** An access road to a quarry or a ski field: it was cut to reach a hillside, so it climbs cheaply. */
const HAUL: RouteCost = { climb: 0.9, slope: 0.3, turn: 0.25, reuse: 0.4, crowd: 0 };

const centre = (t: Town): [number, number] => [t.x0 + t.size / 2, t.z0 + t.size / 2];

/** Road tiles of town t, nearest (px, pz) first, no two within `apart` tiles of each other. */
function roadsToward(w: World, t: Town, px: number, pz: number, want: number, apart = 14): number[] {
  const cands: { i: number; d: number }[] = [];
  for (let z = t.z0; z < t.z0 + t.size; z++) {
    for (let x = t.x0; x < t.x0 + t.size; x++) {
      const i = z * N + x;
      if (!w.road[i] || w.blocked[i] || w.deckAxis[i] || w.townId[i] !== t.id) continue;
      cands.push({ i, d: Math.hypot(x + 0.5 - px, z + 0.5 - pz) });
    }
  }
  cands.sort((a, b) => a.d - b.d);
  const out: number[] = [];
  for (const c of cands) {
    const x = c.i % N, z = (c.i - x) / N;
    if (out.every((o) => Math.hypot((o % N) - x, Math.floor(o / N) - z) >= apart)) out.push(c.i);
    if (out.length >= want) break;
  }
  return out;
}

/** Steps of air a road in a megalopolis county keeps over the water it bridges. */
const MEGA_RISE = 2;

interface LinkResult { from: string; to: string; built: boolean; tiles: number; bridges: number }

/** One road between two tiles, routed over the terrain within a padded box. Returns its length. */
function lay(w: World, from: number, to: number, type: RoadType, cost: RouteCost): { tiles: number; bridges: number } | null {
  const fx = from % N, fz = (from - fx) / N, tx = to % N, tz = (to - tx) / N, pad = 24;
  const box: [number, number, number, number] = [Math.min(fx, tx) - pad, Math.min(fz, tz) - pad, Math.max(fx, tx) + pad + 1, Math.max(fz, tz) + pad + 1];
  // a road between towns may throw a long bridge where it must; a farm track or a quarry road may not
  const span = cost === HAUL ? ROAD_INFO[type].span : Math.max(ROAD_INFO[type].span, LONG_SPAN);
  const wet = wetCost(type);
  const found = findRoute(w, from, to, false, box, cost, span, wet) ?? findRoute(w, from, to, false, [0, 0, N, N], cost, span, wet);
  if (!found || found.nodes.length < 2) return null;
  // a country road runs in long straights, not a staircase across the fields; out in the open it may cut a
  // long corner on the diagonal (world/diagonalRoutes.ts), but a quarry's or a farm's track keeps its corners
  const straight = straightenRoute(w, found, cost, 48, wet);
  const pulled = cost === HAUL ? straight : cutCorners(w, straight, type);
  // pulled straight, it must still keep out from under its own bridges (findRoute's search already does)
  const route = ownDeckClash(w, pulled.nodes, pulled.bridges, false).length ? found : pulled;
  // a megalopolis's roads cross its water well clear of it, never down at the waterline
  const spans = resolveBridges(w, type, route.nodes, route.bridges, w.mega ? MEGA_RISE : 0);
  for (const b of spans) if (!b.tunnel && b.peak === undefined && b.to - b.from >= SUSPENSION_FROM) b.suspension = true;
  layGenerated(w, type, route.nodes, -1, spans);
  return { tiles: route.nodes.length, bridges: spans.length };
}

/**
 * Roads between towns. A megalopolis is the hub of its island: each satellite suburb is joined to
 * it by two or three separate streets entering at different points, so commuting never comes down
 * to one road. Otherwise each small city runs a road to the big city and each suburb or rural town
 * one to whichever city is nearest.
 */
export function linkTowns(w: World): LinkResult[] {
  // with no big city, the biggest of its small cities is the hub, so rival towns are joined up too
  const hub = w.towns.find((t) => t.kind === 'mega') ?? w.towns.find((t) => t.kind === 'metro')
    ?? w.towns.filter((t) => t.kind === 'city').reduce<Town | undefined>((a, b) => (!a || b.size > a.size ? b : a), undefined);
  let cities = w.towns.filter((t) => t.kind === 'city' || t.kind === 'metro' || t.kind === 'mega');
  // an island with no city at all still joins up: its biggest town becomes the hub
  if (!cities.length && w.towns.length > 1) cities = [w.towns.reduce((a, b) => (b.size > a.size ? b : a))];
  const pairs: [Town, Town, RoadType, number][] = [];
  for (const t of w.towns) {
    // the hub, and a stand-in hub that is only a suburb, has nobody to join but the towns joining it
    if (t === hub || (cities.length === 1 && t === cities[0] && t.kind !== 'city' && t.kind !== 'metro' && t.kind !== 'mega')) continue;
    if (t.parent !== undefined && hub) { pairs.push([t, hub, RoadType.TwoLane, 2 + (t.id % 2)]); continue; }
    if (t.kind === 'city' && hub) { pairs.push([t, hub, RoadType.TwoLane, 1]); continue; }
    if (t.kind === 'suburb' || t.kind === 'rural') {
      const [cx, cz] = centre(t);
      let target: Town | null = null, bestD = Infinity;
      for (const c of cities) {
        const [ox, oz] = centre(c);
        const d = Math.hypot(ox - cx, oz - cz);
        if (d < bestD) { bestD = d; target = c; }
      }
      if (target) pairs.push([t, target, t.kind === 'suburb' ? RoadType.TwoLane : RoadType.Paved, 1]);
    }
  }

  const results: LinkResult[] = [];
  for (const [a, b, type, want] of pairs) {
    const [bx, bz] = centre(b);
    const froms = roadsToward(w, a, bx, bz, want);
    let built = 0, tiles = 0, bridges = 0;
    froms.forEach((from, k) => {
      const tos = roadsToward(w, b, (from % N) + 0.5, Math.floor(from / N) + 0.5, k + 1);
      const to = tos[Math.min(k, tos.length - 1)];
      if (to === undefined) return;
      const r = lay(w, from, to, type, k === 0 ? LINK : ALT);
      if (!r) return;
      built++;
      tiles += r.tiles;
      bridges += r.bridges;
    });
    results.push({ from: a.name, to: b.name, built: built > 0, tiles, bridges });
  }
  return results;
}

/** The nearest tile carrying a road that a car could join, or -1. */
function nearestRoad(w: World, from: number, skip?: ReadonlySet<number>): number {
  const fx = from % N, fz = (from - fx) / N;
  let best = -1, bestD = Infinity;
  for (let z = 0; z < N; z++) {
    for (let x = 0; x < N; x++) {
      const i = z * N + x;
      if (!w.road[i] || w.blocked[i] || w.deckAxis[i] || skip?.has(i)) continue;
      const d = Math.hypot(x - fx, z - fz);
      if (d < bestD) { bestD = d; best = i; }
    }
  }
  return best;
}

/**
 * A road down the middle of every causeway leaving the island, carried on to meet the island's own
 * network. Both sides of a strait build their half from the same hash, so the two meet at the border.
 */
export function linkStraits(w: World, causeway: Uint8Array): void {
  for (const st of w.straits) {
    const [dx, dz] = DIRS[st.dir];
    let x = st.dir === 0 ? N - 1 : st.dir === 2 ? 0 : st.at;
    let z = st.dir === 1 ? N - 1 : st.dir === 3 ? 0 : st.at;
    const nodes: number[] = [];
    while (inB(x, z) && causeway[idx(x, z)] && nodes.length < N) {
      nodes.push(idx(x, z));
      x -= dx; z -= dz;
    }
    if (nodes.length < 2) continue;
    layRoad(w, RoadType.Paved, nodes, -1);
    const end = nodes[nodes.length - 1];
    // the nearest road that isn't this one's own: the causeway road just laid was always the nearest,
    // so the link was never made and the causeway ended in a stub (GEN 40)
    const target = nearestRoad(w, end, new Set(nodes));
    if (target >= 0 && target !== end && !lay(w, end, target, RoadType.Paved, LINK)) lay(w, end, target, RoadType.Dirt, HAUL);
  }
}

/** Tiles of dead-straight road either side of a border crossing, so the two halves meet head-on. */
const CROSSING_STUB = 8;

/**
 * A crossing's stub laid dead straight over terraced ground was a staircase: flat tiles a step apart,
 * which no car can climb (the user, 7 Oct 2026). Grade it into a ramp instead. Its corners on the border
 * line are left exactly as they are, so the two counties still meet without a crack; from there the
 * height moves at most a step a tile toward the ground where the stub joins the county's own road, every
 * lane of it alike. A climb too steep for the stub's length keeps what it can't make up at its inland end,
 * where the road joining it is routed (findRoute) over whatever slope is left.
 */
function gradeStub(w: World, d: number, tiles: number[], n: number): void {
  const [dx, dz] = DIRS[d];
  // how far in from the border a tile is: 0 on the border row
  const depth = (i: number) => { const x = i % N, z = (i - x) / N; return d === 0 ? N - 1 - x : d === 2 ? x : d === 1 ? N - 1 - z : z; };
  const rows: number[][] = [];
  for (const t of tiles) { const k = depth(t); if (k < n) (rows[k] ??= []).push(t); }
  if (!rows[0]?.length) return;
  const c = w.corners, out = EDGE_MINE[d], inn = EDGE_MINE[(d + 2) & 3];
  const mean = (list: number[], pair: readonly [number, number]) => list.reduce((s, t) => s + c[t * 4 + pair[0]] + c[t * 4 + pair[1]], 0) / (list.length * 2);
  // the seam's height, and the ground the stub runs into just past its inland end
  const start = Math.round(mean(rows[0], out));
  const beyond = rows[n - 1]?.map((t) => t - dx - dz * N).filter((t) => t >= 0 && t < N * N && inB((t % N), Math.floor(t / N))) ?? [];
  const goal = beyond.length ? Math.round(mean(beyond, out)) : Math.round(mean(rows[n - 1] ?? rows[0], inn));
  let h = start;
  for (let k = 0; k < n; k++) {
    const row = rows[k];
    if (!row?.length) break;
    // the next edge: a step nearer the goal, never more
    const next = h + Math.max(-1, Math.min(1, goal - h));
    for (const t of row) {
      // the border row keeps its seam corners; every other row starts where the last one ended
      if (k > 0) { c[t * 4 + out[0]] = h; c[t * 4 + out[1]] = h; }
      c[t * 4 + inn[0]] = next; c[t * 4 + inn[1]] = next;
    }
    h = next;
  }
}

/**
 * The safety net (the user, 7 Oct 2026): once every building stands, a generated road that still runs under
 * a solid one is cut where it does, and the pieces either side are joined again round it (a proper road if
 * one can be laid, else a dirt track). A four-lane avenue is only cut: its pieces end at the lot. Returns how
 * many roads were mended; `npm run roadblocks` holds generation to none needing it.
 */
export function mendBlockedRoads(w: World): number {
  const kept: Road[] = [];
  const gaps: { a: number; b: number; type: RoadType }[] = [];
  let mended = 0;
  for (const r of w.roads) {
    if (r.town === undefined) { kept.push(r); continue; }
    const wide = shapeOf(r.type);
    const bad = (n: number) => nodeTiles(n, wide).some((t) => w.blocked[t] && !w.deckAxis[t]);
    // nodes a bridge carries over are not on the ground
    const decked = new Set<number>();
    for (const b of r.bridges ?? []) for (let k = b.from + 1; k < b.to; k++) decked.add(k);
    if (!r.nodes.some((n, k) => !decked.has(k) && bad(n))) { kept.push(r); continue; }
    mended++;
    const runs: { start: number; nodes: number[] }[] = [];
    let run: number[] = [], start = 0;
    r.nodes.forEach((n, k) => {
      if (!decked.has(k) && bad(n)) { if (run.length > 1) runs.push({ start, nodes: run }); run = []; return; }
      if (!run.length) start = k;
      run.push(n);
    });
    if (run.length > 1) runs.push({ start, nodes: run });
    runs.forEach(({ start: s, nodes }, q) => {
      const tiles = new Set<number>();
      for (const n of nodes) for (const t of nodeTiles(n, wide)) tiles.add(t);
      const piece: Road = { type: r.type, nodes, tiles: [...tiles], town: r.town };
      const spans = r.bridges?.filter((b) => b.from >= s && b.to <= s + nodes.length - 1);
      if (spans?.length) piece.bridges = spans.map((b) => ({ ...b, from: b.from - s, to: b.to - s }));
      kept.push(piece);
      const next = runs[q + 1];
      if (next && !wide) gaps.push({ a: nodes[nodes.length - 1], b: next.nodes[0], type: r.type });
    });
  }
  if (!mended) return 0;
  w.roads = kept;
  rebuildRoadTables(w);
  for (const g of gaps) if (!lay(w, g.a, g.b, g.type, LINK)) lay(w, g.a, g.b, RoadType.Dirt, HAUL);
  return mended;
}

/**
 * The roads that carry on across a land border, which is the causeway pattern with the water taken
 * out. Both counties name the crossing from the same shared edge, lay their own half from the
 * border tile inland and join it to whatever road they already have, so the player drives from one
 * county into the next on a road neither of them planned as a whole.
 */
export function linkCrossings(w: World, seedHash: number): void {
  for (let d = 0; d < 4; d++) {
    if (!landBorder(seedHash, w.cx, w.cz, d)) continue;
    const [dx, dz] = DIRS[d];
    for (const { at, wide } of crossingAt(seedHash, w.cx, w.cz, d)) {
      const a = Math.max(4, Math.min(N - 5, at));
      let x = d === 0 ? N - 1 : d === 2 ? 0 : a;
      let z = d === 1 ? N - 1 : d === 3 ? 0 : a;
      const type = wide ? RoadType.TwoLane : RoadType.Paved;
      const nodes: number[] = [];
      for (let k = 0; k < CROSSING_STUB; k++) {
        if (!inB(x, z)) break;
        const i = idx(x, z);
        if (w.water[i] >= 0 || w.blocked[i]) break;
        nodes.push(i);
        x -= dx; z -= dz;
      }
      if (nodes.length < 2) continue;
      const road = layRoad(w, type, nodes, -1);
      gradeStub(w, d, road.tiles, nodes.length);
      const end = nodes[nodes.length - 1];
      // the nearest road that isn't the stub's own (it always was, so no crossing was ever joined up), and
      // failing a proper road, a dirt track that climbs whatever it has to: a crossing left on its own was
      // a strip of road in the woods with a customs post at each end (GEN 40)
      const target = nearestRoad(w, end, new Set(nodes));
      if (target >= 0 && target !== end && !lay(w, end, target, type, LINK)) lay(w, end, target, RoadType.Dirt, HAUL);
    }
  }
}

/**
 * An access road to every quarry, ski field and airfield. They are out of the way by nature, so the
 * road simply strikes out from the site gate and joins whatever it finds first; an airport gets a
 * proper two-lane approach, a quarry the dirt track its lorries have worn in.
 */
export function linkWorks(w: World): void {
  for (const g of w.works) {
    const lost = g.kind === 'wonder' && g.buildings.some((b) => b.kind === 'lostTemple' || b.kind === 'pyramid' || b.kind === 'greatKopje');
    const type = g.kind === 'airfield' ? (g.major ? RoadType.TwoLane : RoadType.Paved)
      : g.kind === 'ski' || g.kind === 'resort' || g.kind === 'mine' || (g.kind === 'wonder' && !lost) ? RoadType.Paved : RoadType.Dirt;
    // pick a gate tile nothing is standing on
    let from = g.gate;
    if (g.kind === 'airfield') {
      // generated roads keep off an airfield's ground, so its approach starts just outside the fence:
      // at the open tile nearest the gate that a road can be laid from (hangars can box the nearest in)
      const gx = from % N, gz = (from - gx) / N;
      const cands: { i: number; d: number }[] = [];
      for (let z = Math.max(0, gz - 12); z <= Math.min(N - 1, gz + 12); z++) {
        for (let x = Math.max(0, gx - 12); x <= Math.min(N - 1, gx + 12); x++) {
          const i = idx(x, z);
          if (w.feature[i] === Feature.Airfield || w.blocked[i] || w.water[i] >= 0 || w.biome[i] === Biome.Ocean) continue;
          if (!DIRS.some(([dx, dz]) => inB(x + dx, z + dz) && w.feature[idx(x + dx, z + dz)] === Feature.Airfield)) continue;
          cands.push({ i, d: Math.abs(x - gx) + Math.abs(z - gz) });
        }
      }
      cands.sort((p, q) => p.d - q.d);
      for (const c of cands.slice(0, 8)) {
        const target = nearestRoad(w, c.i);
        if (target < 0 || target === c.i) break;
        if (lay(w, c.i, target, type, LINK) || lay(w, c.i, target, RoadType.Dirt, HAUL)) break;
      }
      continue;
    } else if (w.blocked[from]) {
      const gx = from % N, gz = (from - gx) / N;
      let found = -1;
      for (let r = 1; r <= 6 && found < 0; r++) {
        for (let d = 0; d < 4 && found < 0; d++) {
          const nx = gx + DIRS[d][0] * r, nz = gz + DIRS[d][1] * r;
          if (inB(nx, nz) && !w.blocked[idx(nx, nz)] && w.water[idx(nx, nz)] < 0) found = idx(nx, nz);
        }
      }
      if (found < 0) continue;
      from = found;
    }
    const target = nearestRoad(w, from);
    if (target < 0 || target === from) continue;
    // a quarry track will climb whatever it has to
    if (lay(w, from, target, type, HAUL) || lay(w, from, target, RoadType.Dirt, HAUL)) continue;
    // GEN 53 (world/nextWorld.ts): a wonder across a river from every road bridges it, as a road between towns
    // would, rather than standing with no way in (a haul road's bridges are too short for most rivers); where no
    // bridge will land there, it tries the next nearest stretches of road, further along or the other way
    // (as does a mine's or a resort's haul road, 0.7.0)
    if (!NEXT_WORLD || (g.kind !== 'wonder' && g.kind !== 'mine' && g.kind !== 'resort')) continue;
    const skip = new Set<number>();
    for (let t = 0, to = target; t < 4 && to >= 0 && to !== from; t++) {
      if (lay(w, from, to, type, LINK) || lay(w, from, to, RoadType.Dirt, HAUL)) break;
      const tx = to % N, tz = (to - tx) / N;
      for (let z = Math.max(0, tz - 16); z <= Math.min(N - 1, tz + 16); z++) {
        for (let x = Math.max(0, tx - 16); x <= Math.min(N - 1, tx + 16); x++) if (w.road[idx(x, z)]) skip.add(idx(x, z));
      }
      to = nearestRoad(w, from, skip);
    }
  }
}

/** A paved road from a station's forecourt gate to the nearest street, as an airfield gets one. */
export function linkGate(w: World, from: number): void {
  if (w.blocked[from]) return;
  const target = nearestRoad(w, from);
  if (target < 0 || target === from) return;
  if (!lay(w, from, target, RoadType.Paved, LINK)) lay(w, from, target, RoadType.Dirt, HAUL);
}

/**
 * A jump's run-up or landing road (world/jumps.ts) joined to the nearest road within `reach` tiles: paved
 * where it can be, a dirt track where it can't. True once `from` is on the network.
 */
export function linkJump(w: World, from: number, reach: number): boolean {
  const target = nearestRoad(w, from);
  if (target < 0) return false;
  if (target === from) return true;
  const fx = from % N, fz = (from - fx) / N, tx = target % N, tz = (target - tx) / N;
  if (Math.hypot(tx - fx, tz - fz) > reach) return false;
  return !!(lay(w, from, target, RoadType.Paved, LINK) ?? lay(w, from, target, RoadType.Dirt, HAUL));
}

/** A farm lane: a dirt track from a farmyard gate to the nearest road, if one is near enough to bother. */
export function linkLane(w: World, from: number, reach = 70, hard = false): void {
  if (w.blocked[from]) return;
  const target = nearestRoad(w, from);
  if (target < 0 || target === from) return;
  const fx = from % N, fz = (from - fx) / N, tx = target % N, tz = (target - tx) / N;
  if (Math.hypot(tx - fx, tz - fz) > reach) return;
  if (lay(w, from, target, RoadType.Dirt, HAUL) || !hard) return;
  // `hard` (a ranch's lane, 0.7.0): where the nearest road can't be reached as a farm track, it may bridge what lies
  // between, and failing that it tries the next nearest stretches of road
  const skip = new Set<number>();
  for (let t = 0, to = target; t < 6 && to >= 0 && to !== from; t++) {
    if (lay(w, from, to, RoadType.Dirt, LINK)) return;
    const ux = to % N, uz = (to - ux) / N;
    for (let z = Math.max(0, uz - 4); z <= Math.min(N - 1, uz + 4); z++) for (let x = Math.max(0, ux - 4); x <= Math.min(N - 1, ux + 4); x++) if (w.road[idx(x, z)]) skip.add(idx(x, z));
    to = nearestRoad(w, from, skip);
    if (to >= 0 && Math.hypot((to % N) - fx, Math.floor(to / N) - fz) > reach) return;
  }
}

/** Two pieces of drivable land at least this big, parted by the railway, get a crossing between them. */
const SPLIT_MIN = 300;
/** The most tiles a crossing's run spans between drivable ground on the two sides. */
const CROSSING_SPAN = 6;
/** Tiles of straight approach a crossing keeps either side of the rails, where the ground allows. */
const CROSSING_APPROACH = 3;
/** How far off square a road would rather cross a curving line, and the most it may: sines of about 25° and 45°. */
const EASY_SKEW = 0.42, MAX_SKEW = 0.72;

/** The nearest road tile a car could join inside drivable component `id`, and how far it is, or -1. */
function nearestRoadIn(w: World, from: number, comp: Int32Array, id: number): { tile: number; d: number } {
  const fx = from % N, fz = (from - fx) / N;
  let tile = -1, d = Infinity;
  for (let i = 0; i < N * N; i++) {
    if (comp[i] !== id || !w.road[i] || w.blocked[i] || w.deckAxis[i]) continue;
    const x = i % N, z = (i - x) / N;
    const dd = Math.abs(x - fx) + Math.abs(z - fz);
    if (dd < d) { d = dd; tile = i; }
  }
  return { tile, d };
}

/**
 * The running line's heading over each tile of ground-level track, from the path samples across the
 * track's width: a unit vector, NaN where two lines disagree, and whether any of it rides a bank.
 */
function trackHeadings(w: World): { hx: Float32Array; hz: Float32Array; bank: Uint8Array } {
  const hx = new Float32Array(N * N), hz = new Float32Array(N * N), bank = new Uint8Array(N * N);
  const seen = new Uint8Array(N * N);
  for (const p of w.rails) {
    const n = p.s.length;
    for (let i = 0; i < n; i++) {
      const u = p.under[i];
      if (u !== Under.Ground && u !== Under.Cutting && u !== Under.Embank) continue;
      const a = Math.max(0, i - 2), b = Math.min(n - 1, i + 2);
      let dx = p.xz[b * 2] - p.xz[a * 2], dz = p.xz[b * 2 + 1] - p.xz[a * 2 + 1];
      const len = Math.hypot(dx, dz) || 1;
      dx /= len; dz /= len;
      for (const o of [-0.45, 0, 0.45]) {
        const tx = Math.floor(p.xz[i * 2] - dz * o), tz = Math.floor(p.xz[i * 2 + 1] + dx * o);
        if (!inB(tx, tz)) continue;
        const t = idx(tx, tz);
        if (u === Under.Embank) bank[t] = 1;
        if (!seen[t]) { hx[t] = dx; hz[t] = dz; seen[t] = 1; }
        else if (!(Math.abs(hx[t] * dx + hz[t] * dz) >= 0.9)) hx[t] = hz[t] = NaN;
      }
    }
  }
  return { hx, hz, bank };
}

/**
 * Level crossings wherever the railway has cut the land in two. The border crossings only put roads
 * over the line where the macro layer runs one, so a line can wall off a headland or half an island
 * with nothing to drive across on. Every pair of big drivable pieces that face each other over
 * ground-level track gets one road across, kept `band` tiles clear of the borders and joined to the
 * nearest road of each piece. It crosses square where the line runs straight if it can; failing
 * that, nearly square over a gentle curve, and last of all over a low bank. Pieces already joined,
 * by another crossing or round the end of the line, are left alone.
 *
 * `comp` and `sizes` are the drivable components of the world as it stands; nothing random is drawn,
 * so the roads follow from the ground alone.
 */
export function linkRailSplits(w: World, comp: Int32Array, sizes: number[], band: number): number {
  const parent = sizes.map((_, k) => k);
  const find = (k: number): number => { while (parent[k] !== k) k = parent[k] = parent[parent[k]]; return k; };
  const big = (k: number) => k >= 0 && sizes[k] > SPLIT_MIN;
  const lo = Math.max(band, 4), hi = N - lo;
  const inside = (x: number, z: number) => x >= lo && z >= lo && x < hi && z < hi;
  const { hx, hz, bank } = trackHeadings(w);
  /** Can a road run from `from` onto tile i along d? The sine of the angle it crosses track at (0 for none), or -1. */
  const enter = (from: number, i: number, d: number): number => {
    if (w.biome[i] === Biome.Ocean || w.blocked[i] || (w.flags[i] & Flag.Poi) || w.deckAxis[i] || w.feature[i] === Feature.Airfield) return -1;
    if (waterDepth(w, i) > 1 || steepness(w, i) > 1 || edgeMismatch(w, from, d) !== 0) return -1;
    const rb = w.rail[i];
    if (rb & (RailBit.Pad | RailBit.Loop)) return -1;
    if (!(rb & RailBit.Track)) return 0;
    if (rb & (RailBit.Deck | RailBit.Tunnel) || Number.isNaN(hx[i]) || (hx[i] === 0 && hz[i] === 0)) return -1;
    // the line's heading along the road is how far off square it crosses
    const skew = Math.abs(d % 2 === 0 ? hx[i] : hz[i]);
    return skew <= MAX_SKEW ? skew : -1;
  };

  interface Cand { nodes: number[]; a: number; b: number; ends: [number, number]; score: number }
  const best = new Map<string, Cand>();
  for (let t = 0; t < N * N; t++) {
    if (!railBlocks(w, t)) continue;
    const tx = t % N, tz = (t - tx) / N;
    if (!inside(tx, tz)) continue;
    for (const d of [0, 1]) {
      const back = d + 2;
      const [dx, dz] = DIRS[d];
      // start from the near rail of the line only, then step back off its margin to drivable ground
      if (inB(tx - dx, tz - dz) && railBlocks(w, idx(tx - dx, tz - dz))) continue;
      let x = tx, z = tz, k = 0;
      while (k <= CROSSING_SPAN && inB(x - dx, z - dz) && !w.edges[idx(x - dx, z - dz)]) { x -= dx; z -= dz; k++; }
      if (!inB(x - dx, z - dz) || k > CROSSING_SPAN) continue;
      const a = idx(x - dx, z - dz);
      const nodes = [a];
      let ok = true, skew = 0, banked = 0;
      x = a % N; z = (a - x) / N;
      for (;;) {
        x += dx; z += dz;
        if (!inB(x, z) || !inside(x, z) || nodes.length > CROSSING_SPAN + 1) { ok = false; break; }
        const i = idx(x, z);
        const sk = enter(nodes[nodes.length - 1], i, d);
        if (sk < 0) { ok = false; break; }
        skew = Math.max(skew, sk);
        banked |= bank[i];
        nodes.push(i);
        if (w.edges[i]) break;
      }
      if (!ok || nodes.length < 3) continue;
      const b = nodes[nodes.length - 1];
      const ca = comp[a], cb = comp[b];
      if (!big(ca) || !big(cb) || ca === cb) continue;
      // straight approaches either side, as far as the ground carries a road
      for (let e = 0; e < CROSSING_APPROACH; e++) {
        const f = nodes[0], fx = f % N, fz = (f - fx) / N;
        if (!inB(fx - dx, fz - dz)) break;
        const g = idx(fx - dx, fz - dz);
        if (comp[g] !== ca || enter(f, g, back) !== 0) break;
        nodes.unshift(g);
      }
      for (let e = 0; e < CROSSING_APPROACH; e++) {
        const f = nodes[nodes.length - 1], fx = f % N, fz = (f - fx) / N;
        if (!inB(fx + dx, fz + dz)) break;
        const g = idx(fx + dx, fz + dz);
        if (comp[g] !== cb || enter(f, g, d) !== 0) break;
        nodes.push(g);
      }
      const ra = nearestRoadIn(w, nodes[0], comp, ca), rb = nearestRoadIn(w, nodes[nodes.length - 1], comp, cb);
      // square over straight level track first, then near roads on both sides, then a short run
      const score = (skew > 0.05 ? 150 : 0) + (skew > EASY_SKEW ? 150 : 0) + (banked ? 300 : 0) + skew * 100
        + Math.min(ra.d, 200) + Math.min(rb.d, 200) + nodes.length * 0.5;
      const key = ca < cb ? `${ca}-${cb}` : `${cb}-${ca}`;
      const have = best.get(key);
      if (!have || score < have.score) best.set(key, { nodes, a: ca, b: cb, ends: [ra.tile, rb.tile], score });
    }
  }

  let laid = 0;
  for (const c of [...best.values()].sort((p, q) => p.score - q.score)) {
    if (find(c.a) === find(c.b)) continue;
    layRoad(w, RoadType.Paved, c.nodes, -1);
    parent[find(c.a)] = find(c.b);
    laid++;
    // on to the roads each side already had, found before the crossing was there to be nearest
    for (const [end, to] of [[c.nodes[0], c.ends[0]], [c.nodes[c.nodes.length - 1], c.ends[1]]]) {
      if (to >= 0 && !c.nodes.includes(to)) lay(w, end, to, RoadType.Paved, LINK);
    }
  }
  return laid;
}
