/**
 * The local landforms: everything small enough to be placed by the cell's own rng, kept at least
 * band + 24 tiles inside it so no neighbour ever needs to know. Tarns and oases are dug before the
 * rivers run; deltas, oxbows, mangroves and tombolos follow the rivers and the coast; gorges,
 * cascades, sinkholes, caves, lava tubes and natural bridges are carved into the tile corners; and
 * the points of interest — hot springs, sea arches, basalt columns, hoodoos, erratics — are laid
 * out beside the cabins and the lighthouse.
 */
import {
  N, SEA, STEP, Biome, Flag, Surface, World, DIRS, REGION_KINDS, idx, inB, minCorner, waterDepth, steepness,
  type Landmark, type LandformKind,
} from './tiles';
import { applyCanyons } from './carve';
import { cellNoise, hash2 } from './rng';
import type { Rng } from './rng';
import { blobScale, landformName, type Landforms } from './landforms';
import { carveWaterfalls } from './waterfalls';

interface LocalInputs {
  land: Uint8Array; E: Float32Array; lakeLvl: Int8Array; mountMask: Float32Array; moisture: Float32Array;
  rng: Rng; band: number; seedHash: number; coastal: boolean; cont: boolean; noTown: Uint8Array;
  causeway: Uint8Array; cliffBand: Uint8Array; landmarksFrom: Landforms;
}

/** The Mangroves' `regionK`. */
const SWAMP = REGION_KINDS.indexOf('mangrove') + 1;

export function localLandforms(w: World, inp: LocalInputs) {
  const { land, E, lakeLvl, mountMask, rng, band, seedHash, noTown, causeway } = inp;
  const NN = N * N;
  const keep = band ? band + 24 : 10;
  const inner = (x: number, z: number, m = 0) => x >= keep + m && z >= keep + m && x < N - keep - m && z < N - keep - m;
  const name = (kind: LandformKind, x: number, z: number) => landformName(kind, seedHash, w.ox + x, w.oz + z);
  const mark = (kind: LandformKind, x: number, z: number, r: number, data?: number[]): Landmark => {
    const l: Landmark = { kind, name: name(kind, x, z), x, z, r, data };
    w.landmarks.push(l);
    return l;
  };
  const has = (kind: LandformKind) => w.landmarks.find((l) => l.kind === kind);
  const pickTile = (tries: number, ok: (x: number, z: number, i: number) => unknown): number => {
    const span = N - 2 * keep;
    if (span < 10) return -1;
    for (let k = 0; k < tries; k++) {
      const x = keep + Math.floor(rng() * span), z = keep + Math.floor(rng() * span);
      if (ok(x, z, idx(x, z))) return idx(x, z);
    }
    return -1;
  };
  /** A bowl dug into E with a lake at `level` wherever the bed ends up below it. */
  const bowl = (x: number, z: number, R: number, depth: number, level: number) => {
    const shape = blobScale(w.ox + x, w.oz + z, 4411);
    const reach = Math.ceil(R * 1.35);
    for (let dz = -reach; dz <= reach; dz++) {
      for (let dx = -reach; dx <= reach; dx++) {
        if (!inB(x + dx, z + dz)) continue;
        const d = Math.hypot(dx, dz) / shape(Math.atan2(dz, dx));
        if (d > R) continue;
        const j = idx(x + dx, z + dz);
        if (!land[j]) continue;
        const t = 1 - d / R;
        E[j] -= depth * t * t * (3 - 2 * t);
        mountMask[j] = 0;
        if (E[j] < level - 0.2) { lakeLvl[j] = level; w.biome[j] = Biome.Ocean; noTown[j] = 1; }
      }
    }
  };

  const out = {
    coastMoved: false,

    // ======== before the rivers: sinks the flood must respect ========
    beforeRivers(): void {
      // tarns: a cirque on a mountainside, its lake a step under the lowest point of its lip
      let tarns = 0;
      const wantTarns = rng() < 0.5 ? 1 : rng() < 0.5 ? 2 : 0;
      for (let attempt = 0; attempt < 3 && tarns < wantTarns; attempt++) {
        const t = pickTile(260, (x, z, i) => land[i] && mountMask[i] > 0.5 && E[i] >= SEA + 9 && E[i] <= SEA + 17 && inner(x, z, 8) && !noTown[i] &&
          !w.landmarks.some((l) => Math.hypot(l.x - x, l.z - z) < l.r + 10));
        if (t < 0) break;
        const x = t % N, z = (t - x) / N, R = 4 + Math.floor(rng() * 3);
        // the cirque's outline, and its lip just outside it
        const shape = blobScale(w.ox + x, w.oz + z, 4421, 0.3);
        let lip = Infinity;
        for (let a = 0; a < 24; a++) {
          const ang = (a / 24) * Math.PI * 2, rr = (R + 1) * shape(ang) + 0.5;
          const lx = Math.round(x + Math.cos(ang) * rr), lz = Math.round(z + Math.sin(ang) * rr);
          if (inB(lx, lz)) lip = Math.min(lip, E[idx(lx, lz)]);
        }
        const level = Math.floor(lip) - 1;
        if (!Number.isFinite(level) || level < SEA + 6) continue;
        // a cirque is a scoop, not a coin: longer one way, with a bay or two
        const reach = Math.ceil(R * 1.4);
        for (let dz = -reach; dz <= reach; dz++) {
          for (let dx = -reach; dx <= reach; dx++) {
            const d = Math.hypot(dx, dz) / shape(Math.atan2(dz, dx));
            if (d > R || !inB(x + dx, z + dz)) continue;
            const j = idx(x + dx, z + dz);
            E[j] = Math.min(E[j], level - 1 - 1.5 * (1 - d / R));
            mountMask[j] = 0;
            lakeLvl[j] = level;
            w.biome[j] = Biome.Ocean;
            noTown[j] = 1;
          }
        }
        mark('tarn', x, z, R);
        tarns++;
      }
      // an oasis: a bowl lake in the hollow between two dunes, in one erg in three
      const erg = has('dunes');
      if (erg && rng() < 0.4) {
        const t = pickTile(300, (x, z, i) => land[i] && w.surface[i] === Surface.Sand && w.coastDist[i] > 16 && inner(x, z, 6));
        if (t >= 0) {
          const x = t % N, z = (t - x) / N;
          bowl(x, z, 6, 3, Math.round(E[t]) - 1);
          mark('dunes', x, z, 6, [1]).name = name('dunes', x, z).replace('the ', '').replace(' Erg', ' Oasis');
        }
      }
      // the rift's floor holds a string of long lakes
      if (inp.cont && has('riftValley')) {
        const lf = inp.landmarksFrom;
        let made = 0;
        const lakes: [number, number][] = [];
        for (let k = 0; k < 400 && made < 3; k++) {
          const x = keep + Math.floor(rng() * (N - 2 * keep)), z = keep + Math.floor(rng() * (N - 2 * keep));
          const i = idx(x, z);
          if (!land[i] || lf.rift((w.ox + x) / N, (w.oz + z) / N) < 0.92 || lakes.some(([a, b]) => Math.hypot(a - x, b - z) < 34)) continue;
          bowl(x, z, 8 + Math.floor(rng() * 4), 3, Math.round(E[i]) - 1);
          lakes.push([x, z]);
          made++;
        }
      }
    },

    // ======== after the rivers: the coast and the lowland water ========
    afterRivers(river: Uint8Array): void {
      const temp = w.temp;
      // rain sinks straight into lava rock and salt: no river crosses either
      for (let i = 0; i < NN; i++) if (river[i] && (w.biome[i] === Biome.Lava || w.biome[i] === Biome.Salt)) river[i] = 0;
      // ---- mangroves: a warm wet shore standing in the shallows ----
      let mangroves = 0, mx = 0, mz = 0;
      // an atoll's motus are too narrow to lose to the swamp: its shores stay sand
      if (inp.coastal && w.kind !== 'atoll') {
        for (let z = keep; z < N - keep; z++) {
          for (let x = keep; x < N - keep; x++) {
            const i = idx(x, z);
            // the Mangroves are mangrove on every low shore, and further in from it
            const swamp = w.regionK[i] === SWAMP && w.regionW[i] > 128;
            if (!land[i] || w.coastDist[i] > (swamp ? 6 : 4) || E[i] > SEA + 3.2) continue;
            if (!swamp && (temp[i] < 0.75 || inp.moisture[i] < 0.56)) continue;
            // a warm coast in the wet band only: the tropics' swamps, not every sheltered shore
            if (!swamp && cellNoise(seedHash, (w.ox + x) / N, (w.oz + z) / N, 3.1, 43) < 0.56) continue;
            const b = w.biome[i];
            if (b !== Biome.Beach && b !== Biome.Plains && b !== Biome.Forest) continue;
            if (causeway[i] || w.feature[i] || inp.cliffBand[i] || river[i] === 2) continue;
            // nor the shore a causeway lands on, or it would end a tile short in the swamp
            if (nearCauseway(causeway, x, z, 3)) continue;
            if (cellNoise(seedHash, (w.ox + x) / 48, (w.oz + z) / 48, 1, 91) < (swamp ? 0.3 : 0.45)) continue;
            land[i] = 0;
            E[i] = SEA - 1;
            w.biome[i] = Biome.Mangrove;
            w.surface[i] = Surface.Marsh;
            w.blocked[i] = 1;
            noTown[i] = 1;
            river[i] = 0;
            mangroves++; mx += x; mz += z;
          }
        }
        if (mangroves >= 30) { mark('mangroves', mx / mangroves, mz / mangroves, Math.sqrt(mangroves)); out.coastMoved = true; }
        else if (mangroves) out.coastMoved = true;
      }

      // ---- a delta: where a big river meets a flat coast, uncommonly ----
      if (inp.coastal && rng() < 0.4) {
        const mouths: number[] = [];
        for (let z = keep; z < N - keep; z++) {
          for (let x = keep; x < N - keep; x++) {
            const i = idx(x, z);
            if (river[i] !== 2 || E[i] > SEA + 2.5 || inp.cliffBand[i]) continue;
            for (const [dx, dz] of DIRS) if (inB(x + dx, z + dz) && !land[idx(x + dx, z + dz)] && w.biome[idx(x + dx, z + dz)] === Biome.Ocean) { mouths.push(i); break; }
          }
        }
        if (mouths.length) {
          const m = mouths[Math.floor(rng() * mouths.length)];
          const mx0 = m % N, mz0 = (m - mx0) / N;
          // which way the sea lies
          let ox = 0, oz = 0;
          for (let dz = -8; dz <= 8; dz++) for (let dx = -8; dx <= 8; dx++) {
            if (inB(mx0 + dx, mz0 + dz) && !land[idx(mx0 + dx, mz0 + dz)]) { ox += dx; oz += dz; }
          }
          const ol = Math.hypot(ox, oz) || 1;
          ox /= ol; oz /= ol;
          const ax = mx0 - ox * 22, az = mz0 - oz * 22;
          let marsh = 0;
          for (let dz = -30; dz <= 30; dz++) {
            for (let dx = -30; dx <= 30; dx++) {
              const x = Math.round(mx0 + dx), z = Math.round(mz0 + dz);
              if (!inner(x, z)) continue;
              const i = idx(x, z);
              const vx = x - ax, vz = z - az, vl = Math.hypot(vx, vz);
              if (vl < 4 || vl > 30) continue;
              if ((vx * ox + vz * oz) / vl < Math.cos(0.72)) continue;
              if (land[i]) {
                if (E[i] > SEA + 3.8 || w.biome[i] === Biome.Town) continue;
                E[i] = SEA + 1;
                w.biome[i] = Biome.Marsh;
                w.surface[i] = Surface.Marsh;
                noTown[i] = 1;
                river[i] = 0;
                marsh++;
              } else if (w.biome[i] === Biome.Ocean && vl < 40) {
                E[i] = Math.max(E[i], SEA - 1);
              }
            }
          }
          // the distributaries: three to six streams fanning out to the sea
          const arms = 3 + Math.floor(rng() * 4);
          for (let a = 0; a < arms; a++) {
            const ang = Math.atan2(oz, ox) + (a / (arms - 1) - 0.5) * 1.2;
            let x = ax + Math.cos(ang) * 5, z = az + Math.sin(ang) * 5;
            for (let s = 0; s < 40; s++) {
              x += Math.cos(ang + Math.sin(s * 0.4 + a) * 0.35);
              z += Math.sin(ang + Math.sin(s * 0.4 + a) * 0.35);
              const tx = Math.round(x), tz = Math.round(z);
              if (!inB(tx, tz)) break;
              const i = idx(tx, tz);
              if (!land[i]) break;
              if (w.biome[i] === Biome.Marsh) river[i] = 1;
            }
          }
          if (marsh > 40) mark('delta', mx0, mz0, 24);
        }
      }

      // ---- oxbows: crescents of still water cut off beside a lowland river ----
      let bows = 0;
      // meanders cut off are something a river does now and then, not on every lowland cell
      const bowTries = hash2(w.cx, w.cz, (seedHash ^ 2201) | 0) < 0.35 ? 500 : 0;
      for (let tries = 0; tries < bowTries && bows < 3; tries++) {
        const x = keep + 8 + Math.floor(rng() * (N - 2 * keep - 16)), z = keep + 8 + Math.floor(rng() * (N - 2 * keep - 16));
        const i = idx(x, z);
        if (river[i] !== 2 || E[i] > SEA + 6) continue;
        const b = w.biome[i];
        if (b !== Biome.Plains && b !== Biome.Forest && b !== Biome.Hills) continue;
        // the river's direction, from its neighbours
        let rx = 0, rz = 0;
        for (let dz = -2; dz <= 2; dz++) for (let dx = -2; dx <= 2; dx++) {
          if (inB(x + dx, z + dz) && river[idx(x + dx, z + dz)] === 2) { rx += dx * Math.sign(dx || 1); rz += dz * Math.sign(dx || 1); }
        }
        const rl = Math.hypot(rx, rz);
        if (rl < 1) continue;
        const side = rng() < 0.5 ? 1 : -1;
        const px = (-rz / rl) * side, pz = (rx / rl) * side;
        const cx = x + px * 7, cz = z + pz * 7, R = 4.5;
        const tiles: number[] = [];
        let ok = true;
        for (let dz = -6; dz <= 6 && ok; dz++) {
          for (let dx = -6; dx <= 6; dx++) {
            const tx = Math.round(cx + dx), tz = Math.round(cz + dz);
            const dd = Math.hypot(tx - cx, tz - cz);
            if (Math.abs(dd - R) > 0.85 || (tx - cx) * px + (tz - cz) * pz < -1.5) continue;
            if (!inner(tx, tz)) { ok = false; break; }
            const j = idx(tx, tz);
            if (!land[j] || river[j] || lakeLvl[j] > -128 || Math.abs(E[j] - E[i]) > 1.2 || w.biome[j] === Biome.Town) { ok = false; break; }
            tiles.push(j);
          }
        }
        if (!ok || tiles.length < 8) continue;
        const level = Math.round(E[i]);
        for (const j of tiles) { E[j] = level - 1.3; lakeLvl[j] = level; w.biome[j] = Biome.Ocean; noTown[j] = 1; }
        if (!bows) mark('oxbows', x, z, 10);
        bows++;
      }

      // ---- a tombolo: a sandbar from a beach out to an islet ----
      if (inp.coastal && rng() < 0.35) {
        const seen = new Uint8Array(NN);
        for (let z = keep; z < N - keep && !has('tombolo'); z++) {
          for (let x = keep; x < N - keep && !has('tombolo'); x++) {
            const s = idx(x, z);
            if (!land[s] || seen[s]) continue;
            // a small piece of land: an islet or a skerry
            const comp: number[] = [s];
            seen[s] = 1;
            for (let h = 0; h < comp.length && comp.length <= 30; h++) {
              const cx = comp[h] % N, cz = (comp[h] - cx) / N;
              for (const [dx, dz] of DIRS) {
                if (!inB(cx + dx, cz + dz)) continue;
                const j = idx(cx + dx, cz + dz);
                if (land[j] && !seen[j]) { seen[j] = 1; comp.push(j); }
              }
            }
            if (comp.length > 30) continue;
            const ix = x, iz = z;
            // the nearest broad sand within forty tiles
            let best = -1, bestD = 40;
            for (let dz = -40; dz <= 40; dz += 2) for (let dx = -40; dx <= 40; dx += 2) {
              const tx = ix + dx, tz = iz + dz;
              if (!inner(tx, tz)) continue;
              const j = idx(tx, tz);
              if (!land[j] || w.biome[j] !== Biome.Beach || comp.includes(j)) continue;
              const d = Math.hypot(dx, dz);
              if (d < bestD && d > 12) { bestD = d; best = j; }
            }
            if (best < 0) continue;
            const bx = best % N, bz = (best - bx) / N;
            const steps = Math.ceil(bestD);
            let okLine = true;
            const line: number[] = [];
            for (let k = 0; k <= steps; k++) {
              const t = k / steps, cx = ix + (bx - ix) * t + Math.sin(t * Math.PI) * 3, cz = iz + (bz - iz) * t;
              const tx = Math.round(cx), tz = Math.round(cz);
              if (!inner(tx, tz)) { okLine = false; break; }
              line.push(idx(tx, tz));
              if (k % 2 === 0 && inB(tx + 1, tz)) line.push(idx(tx + 1, tz));
            }
            if (!okLine) continue;
            for (const j of line) {
              if (land[j]) continue;
              land[j] = 1;
              E[j] = SEA + 0.6;
              w.biome[j] = Biome.Beach;
              w.surface[j] = Surface.Sand;
              noTown[j] = 1;
            }
            out.coastMoved = true;
            mark('tombolo', (ix + bx) / 2, (iz + bz) / 2, bestD / 2);
          }
        }
      }
    },

    // ======== carved into the corners, before the walls go up ========
    carve(river: Uint8Array, avoid?: Uint8Array): void {
      const c = w.corners;
      const level = (i: number) => Math.round((c[i * 4] + c[i * 4 + 1] + c[i * 4 + 2] + c[i * 4 + 3]) / 4);
      const setLevel = (i: number, v: number) => { c[i * 4] = c[i * 4 + 1] = c[i * 4 + 2] = c[i * 4 + 3] = v; };
      const flatish = (i: number) => steepness(w, i) <= 1;

      // ---- gorges: the canyon cut, wherever a big river runs through high ground ----
      const gorges: [number, number][] = [];
      applyCanyons(w, river, rng, 5, band, 'gorge', gorges);
      if (gorges.length) mark('gorge', gorges[0][0], gorges[0][1], 14);

      // ---- a great waterfall: horseshoe, curtain, cataract, plunge, stair... (world/waterfalls.ts) ----
      carveWaterfalls({ w, land, lakeLvl, river, noTown, seedHash, keep, avoid });

      // ---- a cascade: a river stepping down a mountainside in pools and falls ----
      if (rng() < 0.6) {
        for (let tries = 0; tries < 1500; tries++) {
          const s = pickTile(1, (x, z, i) => river[i] && river[i] !== 3 && minCorner(w, i) >= SEA + 5 && inner(x, z, 4));
          if (s < 0) continue;
          // walk downstream along the river, always to the lowest river neighbour
          const path = [s];
          const seen = new Set(path);
          let cur = s;
          for (let k = 0; k < 22; k++) {
            const x = cur % N, z = (cur - x) / N;
            let next = -1, low = Infinity;
            for (const [dx, dz] of DIRS) {
              if (!inB(x + dx, z + dz)) continue;
              const j = idx(x + dx, z + dz);
              if (!river[j] || river[j] === 3 || seen.has(j) || !inner(x + dx, z + dz)) continue;
              if (minCorner(w, j) < low) { low = minCorner(w, j); next = j; }
            }
            if (next < 0) break;
            path.push(next); seen.add(next); cur = next;
          }
          const top = minCorner(w, s), foot = minCorner(w, path[path.length - 1]);
          if (path.length < 8 || top - foot < 5) continue;
          let run = top;
          for (const i of path) {
            run = Math.min(run, minCorner(w, i));
            // pools two steps apart: every drop becomes a fall
            setLevel(i, top - Math.ceil((top - run) / 2) * 2);
            w.flags[i] |= Flag.Corridor;
          }
          const f = path[path.length - 1], fx = f % N, fz = (f - fx) / N;
          mark('cascade', fx, fz, 6, [minCorner(w, f)]);
          break;
        }
      }

      // ---- sinkholes: uncommon among the towers, rare on plain ground ----
      const karst = has('karstTowers');
      if (rng() < (karst ? 0.35 : 0.1)) {
        const t = pickTile(300, (x, z, i) => {
          if (!land[i] || river[i] || w.coastDist[i] < 20 || !inner(x, z, 8) || !flatish(i)) return false;
          const b = w.biome[i];
          if (b !== Biome.Plains && b !== Biome.Forest && b !== Biome.Hills) return false;
          for (let dz = -9; dz <= 9; dz++) for (let dx = -9; dx <= 9; dx++) {
            const j = idx(x + dx, z + dz);
            if (w.biome[j] === Biome.Town || w.flags[j] & (Flag.Field | Flag.Corridor | Flag.Terrace) || river[j] || lakeLvl[j] > -128) return false;
          }
          return true;
        });
        if (t >= 0) {
          const x = t % N, z = (t - x) / N;
          const R = 2.5 + rng() * 2, depth = 5 + Math.floor(rng() * 4), rim = level(t), bottom = rim - depth;
          const warm = w.temp[t] > 0.55;
          for (let dz = -5; dz <= 5; dz++) for (let dx = -5; dx <= 5; dx++) {
            if (Math.hypot(dx, dz) > R) continue;
            const j = idx(x + dx, z + dz);
            setLevel(j, bottom);
            w.flags[j] |= Flag.Corridor;
            noTown[j] = 1;
            if (warm) lakeLvl[j] = bottom + 2;
            else w.surface[j] = Surface.Cave;
          }
          // the one way out: a ramp climbing a step a tile
          const d = Math.floor(rng() * 4);
          for (let k = 0; k < depth + 1; k++) {
            const tx = Math.round(x + DIRS[d][0] * (R + k)), tz = Math.round(z + DIRS[d][1] * (R + k));
            if (!inB(tx, tz)) break;
            const j = idx(tx, tz);
            const v = bottom + k + 1;
            if (v >= level(j)) break;
            setLevel(j, v);
            w.flags[j] |= Flag.Corridor;
            lakeLvl[j] = -128;
          }
          mark('sinkhole', x, z, R, [warm ? 1 : 0]).name = warm ? name('sinkhole', x, z).replace('Sinkhole', 'Cenote') : name('sinkhole', x, z);
        }
      }

      // ---- a cave tunnel: a road-width passage straight through a ridge ----
      if (rng() < 0.6) {
        for (let tries = 0; tries < 4000; tries++) {
          const a = pickTile(1, (x, z, i) => land[i] && !river[i] && flatish(i) && inner(x, z, 2) && w.biome[i] !== Biome.Town && !(w.flags[i] & (Flag.Field | Flag.Terrace)) && lakeLvl[i] === -128);
          if (a < 0) continue;
          const ax = a % N, az = (a - ax) / N, la = level(a);
          const d = Math.floor(rng() * 4);
          let len = -1, roof = la;
          for (let k = 1; k <= 20; k++) {
            const tx = ax + DIRS[d][0] * k, tz = az + DIRS[d][1] * k;
            if (!inner(tx, tz)) break;
            const j = idx(tx, tz);
            if (river[j] || lakeLvl[j] > -128 || !land[j]) break;
            const lj = level(j);
            if (lj >= la + 5) { roof = Math.max(roof, Math.max(c[j * 4], c[j * 4 + 1], c[j * 4 + 2], c[j * 4 + 3])); continue; }
            if (k >= 6 && Math.abs(lj - la) <= 2 && flatish(j) && !(w.flags[j] & Flag.Terrace)) len = k;
            break;
          }
          if (len < 0) continue;
          const lb = level(idx(ax + DIRS[d][0] * len, az + DIRS[d][1] * len));
          for (let k = 1; k < len; k++) {
            const j = idx(ax + DIRS[d][0] * k, az + DIRS[d][1] * k);
            setLevel(j, Math.round(la + ((lb - la) * k) / len));
            w.flags[j] = (w.flags[j] & ~Flag.Terrace) | Flag.Corridor;
            w.surface[j] = Surface.Cave;
            w.cleared[j] = 1;
            noTown[j] = 1;
          }
          mark('caveTunnel', ax + DIRS[d][0] * (len / 2), az + DIRS[d][1] * (len / 2), len / 2, [ax, az, d, len, roof]);
          break;
        }
      }

      // ---- the lava tube across a lava field: a trench with a rock roof over half of it ----
      const field = has('lavaField');
      if (field) {
        const ang = rng() * Math.PI * 2, L = 12 + Math.floor(rng() * 8);
        const sx = field.x - Math.cos(ang) * L / 2, sz = field.z - Math.sin(ang) * L / 2;
        const tube: number[] = [];
        for (let k = 0; k <= L; k++) {
          const tx = Math.round(sx + Math.cos(ang) * k), tz = Math.round(sz + Math.sin(ang) * k);
          if (!inner(tx, tz)) break;
          for (const j of [idx(tx, tz), idx(Math.min(N - 1, tx + 1), tz)]) {
            if (tube.includes(j) || !land[j] || w.biome[j] !== Biome.Lava) continue;
            setLevel(j, level(j) - 2);
            w.flags[j] |= Flag.Corridor;
            tube.push(j);
          }
        }
        if (tube.length > 6) field.data = [sx, sz, sx + Math.cos(ang) * L, sz + Math.sin(ang) * L];
      }

      // ---- a natural bridge: a rock deck left spanning a narrow canyon or gorge ----
      if ((w.landmarks.some((l) => l.kind === 'gorge') || w.stats.canyons > 0) && rng() < 0.4) {
        for (let tries = 0; tries < 900; tries++) {
          const s = pickTile(1, (x, z, i) => land[i] && !(w.flags[i] & Flag.Corridor) && flatish(i) && inner(x, z, 2) && !river[i]);
          if (s < 0) continue;
          const sx = s % N, sz = (s - sx) / N, ls = level(s);
          const d = Math.floor(rng() * 4);
          let gap = 0, far = -1;
          for (let k = 1; k <= 8; k++) {
            const tx = sx + DIRS[d][0] * k, tz = sz + DIRS[d][1] * k;
            if (!inner(tx, tz)) break;
            const j = idx(tx, tz);
            if (w.flags[j] & Flag.Corridor) { if (level(j) > ls - 3) break; gap++; continue; }
            if (gap >= 3 && Math.abs(level(j) - ls) <= 0 && flatish(j)) far = k;
            break;
          }
          if (far < 0 || gap > 7) continue;
          const h = ls * STEP;
          const along = d % 2 === 0 ? 1 : 2;
          for (let k = 1; k < far; k++) {
            const j = idx(sx + DIRS[d][0] * k, sz + DIRS[d][1] * k);
            w.deckAxis[j] = along; w.deckLo[j] = h; w.deckHi[j] = h;
          }
          mark('naturalBridge', sx + DIRS[d][0] * (far / 2), sz + DIRS[d][1] * (far / 2), far / 2, [sx, sz, d, far, h]);
          break;
        }
      }
    },

    // ======== water surfaces the landforms own ========
    water(): void {
      // a volcano's crater lake sits a step above the lowest ground in the crater
      const v = has('volcano');
      if (v && !(v.data?.[0])) {
        let floor = Infinity;
        const tiles: number[] = [];
        for (let dz = -6; dz <= 6; dz++) for (let dx = -6; dx <= 6; dx++) {
          const tx = Math.round(v.x + dx), tz = Math.round(v.z + dz);
          if (!inB(tx, tz) || Math.hypot(dx, dz) > 5.5) continue;
          const i = idx(tx, tz);
          tiles.push(i);
          floor = Math.min(floor, minCorner(w, i));
        }
        for (const i of tiles) if (minCorner(w, i) <= floor + 1) w.water[i] = floor + 1;
      }
    },

    // ======== the points of interest ========
    pointsOfInterest(reach: Uint8Array): void {
      const volcano = has('volcano');
      const lavaField = has('lavaField');
      const clear = (i: number): boolean => !!land[i] && waterDepth(w, i) === 0 && !w.road[i] && !w.blocked[i] && w.townId[i] < 0 && w.portId[i] < 0 &&
        !(w.flags[i] & (Flag.Field | Flag.Poi | Flag.Track | Flag.Ramp | Flag.Corridor));
      const takeTile = (i: number, solid = false) => { w.flags[i] |= Flag.Poi; if (solid) w.blocked[i] = 1; };

      // ---- hot springs, and a geyser in one in two ----
      const nearVolcano = !!volcano;
      if (rng() < (nearVolcano ? 0.6 : 0.12)) {
        const t = pickTile(500, (x, z, i) => {
          if (!clear(i) || !reach[i] || steepness(w, i) > 0 || !inner(x, z, 3)) return false;
          if (nearVolcano ? Math.hypot(x - volcano!.x, z - volcano!.z) > 80 || Math.hypot(x - volcano!.x, z - volcano!.z) < volcano!.r * 0.6 : mountMask[i] < 0.3) return false;
          for (let dz = -2; dz <= 2; dz++) for (let dx = -2; dx <= 2; dx++) if (!clear(idx(x + dx, z + dz)) || steepness(w, idx(x + dx, z + dz)) > 0) return false;
          return true;
        });
        if (t >= 0) {
          const x = t % N, z = (t - x) / N;
          const pools = 3 + Math.floor(rng() * 3), geyser = rng() < 0.5 ? 1 : 0;
          const data = [geyser, Math.floor(rng() * 1e6), pools];
          for (let k = 0; k < pools; k++) data.push(x + 0.5 + (rng() - 0.5) * 3.2, z + 0.5 + (rng() - 0.5) * 3.2, 0.35 + rng() * 0.3);
          for (let dz = -1; dz <= 1; dz++) for (let dx = -1; dx <= 1; dx++) takeTile(idx(x + dx, z + dz));
          mark('hotSprings', x + 0.5, z + 0.5, 3, data);
        }
      }

      // ---- a sea arch and its stacks on a cliff coast ----
      if (inp.coastal && rng() < 0.35) {
        const t = pickTile(800, (x, z, i) => land[i] && w.biome[i] === Biome.SeaCliff && inner(x, z, 3) && !w.road[i] && w.townId[i] < 0 && w.portId[i] < 0);
        if (t >= 0) {
          const x = t % N, z = (t - x) / N;
          for (let d = 0; d < 4; d++) {
            const sx = x + DIRS[d][0], sz = z + DIRS[d][1], fx = x + DIRS[d][0] * 2, fz = z + DIRS[d][1] * 2;
            if (!inB(fx, fz) || land[idx(sx, sz)] || land[idx(fx, fz)] || w.portId[idx(sx, sz)] >= 0) continue;
            const data = [x, z, d, level0(w, t)];
            let stacks = 0;
            for (let k = 0; k < 30 && stacks < 3; k++) {
              const tx = x + DIRS[d][0] * (3 + Math.floor(rng() * 4)) + Math.floor((rng() - 0.5) * 7), tz = z + DIRS[d][1] * (3 + Math.floor(rng() * 4)) + Math.floor((rng() - 0.5) * 7);
              if (!inB(tx, tz)) continue;
              const j = idx(tx, tz);
              if (land[j] || waterDepth(w, j) > 3 || w.portId[j] >= 0 || w.blocked[j]) continue;
              w.blocked[j] = 1;
              data.push(tx + 0.5, tz + 0.5, 1.2 + rng() * 1.4);
              stacks++;
            }
            takeTile(t);
            mark('seaArch', x + 0.5, z + 0.5, 4, data);
            break;
          }
        }
      }

      // ---- basalt columns stepping into the sea, near a volcano or its lava ----
      if ((volcano || lavaField) && rng() < 0.6) {
        const src = volcano ?? lavaField!;
        const t = pickTile(900, (x, z, i) => land[i] && w.coastDist[i] <= 1 && (w.biome[i] === Biome.Beach || w.biome[i] === Biome.SeaCliff) &&
          Math.hypot(x - src.x, z - src.z) < 120 && inner(x, z, 3) && clear(i));
        if (t >= 0) {
          const x = t % N, z = (t - x) / N;
          const data: number[] = [];
          for (let dz = -3; dz <= 3; dz++) for (let dx = -3; dx <= 3; dx++) {
            const j = idx(x + dx, z + dz);
            if (!land[j] || w.coastDist[j] > 2 || !clear(j)) continue;
            w.surface[j] = Surface.Basalt;
            w.flags[j] |= Flag.Poi;
            data.push(x + dx, z + dz, w.coastDist[j]);
          }
          if (data.length >= 18) mark('basaltColumns', x + 0.5, z + 0.5, 4, data);
        }
      }

      // ---- hoodoos: a cluster of stone pillars on badland or canyon ground ----
      if ((has('badlands') || w.stats.canyons > 0) && rng() < 0.3) {
        const t = pickTile(800, (x, z, i) => clear(i) && (w.surface[i] === Surface.Rock || w.biome[i] === Biome.Canyon) && inner(x, z, 8));
        if (t >= 0) {
          const x = t % N, z = (t - x) / N;
          const n = 8 + Math.floor(rng() * 13), data: number[] = [];
          for (let k = 0; k < n * 3 && data.length < n * 3; k++) {
            const px = x + 0.5 + (rng() - 0.5) * 12, pz = z + 0.5 + (rng() - 0.5) * 12;
            const j = idx(Math.floor(px), Math.floor(pz));
            if (!clear(j)) continue;
            const h = 0.6 + rng() * 1.4;
            data.push(px, pz, h);
            takeTile(j, h > 1.5);
          }
          if (data.length >= 24) mark('hoodoos', x + 0.5, z + 0.5, 7, data);
        }
      }

      // ---- erratics: boulders the ice left behind, strung out across cold open ground ----
      const data: number[] = [];
      const glacier = has('glacier');
      for (let z = keep; z < N - keep; z += 2) {
        for (let x = keep; x < N - keep; x += 2) {
          const i = idx(x, z);
          const b = w.biome[i];
          const cold = w.temp[i] < 0.42 || (glacier && Math.hypot(x - glacier.x, z - glacier.z) < glacier.r * 2);
          if (!cold || (b !== Biome.Hills && b !== Biome.Plains && b !== Biome.Mountain) || !clear(i)) continue;
          const line = Math.abs(cellNoise(seedHash, (w.ox + x) / 22, (w.oz + z) / 22, 1, 95) - 0.5);
          if (line > 0.03 || hash2(w.ox + x, w.oz + z, 9301) > 0.3) continue;
          const s = 2.5 + hash2(w.ox + x, w.oz + z, 9302) * 2.5;
          data.push(x + 0.5, z + 0.5, s);
          takeTile(i, s > 4);
          if (data.length >= 3 * 60) break;
        }
      }
      if (data.length >= 18) {
        const n = data.length / 3;
        let sx = 0, sz = 0;
        for (let k = 0; k < n; k++) { sx += data[k * 3]; sz += data[k * 3 + 1]; }
        mark('erratics', sx / n, sz / n, 20, data);
      }
    },
  };
  return out;
}

/** Is any causeway tile within r tiles (Chebyshev) of (x, z)? */
function nearCauseway(causeway: Uint8Array, x: number, z: number, r: number): boolean {
  for (let dz = -r; dz <= r; dz++) {
    for (let dx = -r; dx <= r; dx++) {
      const nx = x + dx, nz = z + dz;
      if (nx >= 0 && nz >= 0 && nx < N && nz < N && causeway[nz * N + nx]) return true;
    }
  }
  return false;
}

function level0(w: World, i: number): number {
  const c = w.corners;
  return Math.max(c[i * 4], c[i * 4 + 1], c[i * 4 + 2], c[i * 4 + 3]);
}

/** Put the natural bridges' decks back after the road tables are rebuilt. */
export function naturalDecks(w: World): void {
  for (const l of w.landmarks) {
    if (l.kind !== 'naturalBridge' || !l.data) continue;
    const [sx, sz, d, far, h] = l.data;
    for (let k = 1; k < far; k++) {
      const j = idx(sx + DIRS[d][0] * k, sz + DIRS[d][1] * k);
      w.deckAxis[j] = d % 2 === 0 ? 1 : 2; w.deckLo[j] = h; w.deckHi[j] = h;
    }
  }
}
