import { N, Flag, World, idx, inB, waterDepth, type Building, type UnderseaKind } from './tiles';
import type { Rng } from './rng';

/**
 * Works out at sea (held for 0.8.0, world/nextWorld.ts NEXT_080; the user, 28 Oct 2026). Eight stand on the seabed,
 * where only a submarine that has dived and sounded takes goods up or sets them down (game/cargo.ts buildSites marks
 * their sites `seabed`): pearl beds, a research habitat, a drowned village, a cable junction, a vent field, a nodule
 * field, a reef observatory and a listening post. Two float at the surface, any boat's to come alongside: a kelp
 * farm and salmon pens. None blocks a boat (KIND_SPEC solid false). Placed on a random stream of their own after
 * every other building (generate.ts), so nothing else in a county moves.
 */

/** Surface works: drawn at the water line (their `level` is the water's), served by any boat. */
export const AFLOAT_KINDS: ReadonlySet<string> = new Set<UnderseaKind>(['kelpFarm', 'salmonPens']);
export const UNDERSEA_KINDS: readonly UnderseaKind[] = [
  'pearlBeds', 'seaHabitat', 'drownedVillage', 'cableJunction', 'ventField', 'noduleField', 'reefObservatory', 'listeningPost', 'kelpFarm', 'salmonPens',
];
export const isUndersea = (k: string): k is UnderseaKind => (UNDERSEA_KINDS as readonly string[]).includes(k);

interface Row {
  kind: UnderseaKind;
  w: number; d: number;
  chance: number;
  /** The least water over every tile of the lot, in steps (a Guppy dives in 3, a Leviathan in 4). */
  depth: number;
  /** Tiles from the nearest land, the lot's middle: [nearest, furthest]. */
  shore: [number, number];
  /** Warm water only, cold only, or either. */
  climate?: 'warm' | 'cold';
  /** The cooler the better (scored), anywhere short of the tropics. */
  cool?: boolean;
  /** Wants to be near one of these kinds ashore (within `by` tiles): the score falls with distance. */
  near?: { kinds: Set<string>; by: number };
}

const ROWS: Row[] = [
  { kind: 'pearlBeds', w: 3, d: 3, chance: 0.5, depth: 3, shore: [3, 14], climate: 'warm' },
  { kind: 'seaHabitat', w: 4, d: 4, chance: 0.35, depth: 4, shore: [8, 32] },
  { kind: 'drownedVillage', w: 6, d: 5, chance: 0.3, depth: 3, shore: [4, 18] },
  { kind: 'cableJunction', w: 3, d: 2, chance: 0.45, depth: 4, shore: [12, 60], near: { kinds: new Set(['substation', 'powerPlant', 'commsTower', 'radioMast']), by: 70 } },
  { kind: 'ventField', w: 4, d: 4, chance: 0.3, depth: 5, shore: [20, 80] },
  { kind: 'noduleField', w: 5, d: 5, chance: 0.35, depth: 5, shore: [18, 80] },
  { kind: 'reefObservatory', w: 4, d: 3, chance: 0.35, depth: 3, shore: [3, 12], climate: 'warm', near: { kinds: new Set(['beachResort', 'hotel', 'aquarium']), by: 60 } },
  { kind: 'listeningPost', w: 3, d: 3, chance: 0.3, depth: 4, shore: [15, 80], near: { kinds: new Set(['navalDock', 'militaryBase', 'borderFort']), by: 90 } },
  // kelp grows best in cool water, but is farmed anywhere that isn't tropical
  { kind: 'kelpFarm', w: 5, d: 4, chance: 0.45, depth: 3, shore: [4, 16], cool: true },
  { kind: 'salmonPens', w: 5, d: 5, chance: 0.45, depth: 3, shore: [3, 12], near: { kinds: new Set(['cannery', 'fishFarm', 'minorPort']), by: 50 } },
];

/** Works keep at least this far apart, and this far from a harbour's pier, in tiles. */
const APART = 20, OFF_PIER = 12;

/** Water joined to the open sea (not a lake or a canal). */
const ocean = (w: World, i: number): boolean => w.water[i] >= 0 && w.coastDist[i] === 0;

/** The undersea works of a county with open sea and a harbour to bring their goods to. */
export function placeUndersea(w: World, rng: Rng, band: number): Building[] {
  const out: Building[] = [];
  if (!w.ports.length) return out;
  const land = shoreDistance(w, 90);
  const piers = w.ports.map((p) => ({ x: p.root % N, z: Math.floor(p.root / N) }));
  const lo = band + 2, hi = N - band - 2;
  const lotOk = (x: number, z: number, wx: number, wz: number, need: number) => {
    if (x < lo || z < lo || x + wx > hi || z + wz > hi) return false;
    for (let zz = z; zz < z + wz; zz++) for (let xx = x; xx < x + wx; xx++) {
      if (!inB(xx, zz)) return false;
      const i = idx(xx, zz);
      if (!ocean(w, i) || w.blocked[i] || w.road[i] || w.rail[i] || (w.flags[i] & Flag.Poi) || waterDepth(w, i) < need) return false;
    }
    return true;
  };
  const buildings = w.allBuildings.filter((b) => !b.gone);
  // the county's climate from its land (the sea's own temperature reads warm everywhere): the middle of its dry tiles
  const dry: number[] = [];
  for (let i = 0; i < N * N; i += 7) if (w.water[i] < 0) dry.push(w.temp[i]);
  dry.sort((a, b) => a - b);
  const climate = dry.length ? dry[dry.length >> 1] : 0.5;
  for (const row of ROWS) {
    if (rng() >= row.chance) continue;
    const ashore = row.near ? buildings.filter((b) => row.near!.kinds.has(b.kind)) : [];
    let best: { x: number; z: number; score: number } | null = null;
    for (let tries = 0; tries < 320; tries++) {
      const x = lo + Math.floor(rng() * (hi - lo - row.w)), z = lo + Math.floor(rng() * (hi - lo - row.d));
      const mx = x + Math.floor(row.w / 2), mz = z + Math.floor(row.d / 2), mi = idx(mx, mz);
      const sd = land[mi];
      if (sd < row.shore[0] || sd > row.shore[1]) continue;
      if (row.climate && (row.climate === 'warm' ? climate <= 0.55 : climate > 0.45)) continue;
      if (!lotOk(x, z, row.w, row.d, row.depth)) continue;
      if (piers.some((p) => Math.abs(p.x - mx) < OFF_PIER && Math.abs(p.z - mz) < OFF_PIER)) continue;
      if (out.some((b) => Math.abs(b.x - x) < APART && Math.abs(b.z - z) < APART)) continue;
      if (row.cool && climate > 0.75) continue;
      let score = rng() * 6;
      if (ashore.length) {
        const d = Math.min(...ashore.map((b) => Math.hypot(b.x + b.w / 2 - mx, b.z + b.d / 2 - mz)));
        if (d > row.near!.by) continue;
        score += row.near!.by - d;
      }
      if (!best || score > best.score) best = { x, z, score };
    }
    if (best) out.push(put(w, rng, row.kind, best.x, best.z, row.w, row.d));
  }
  return out;
}

/**
 * A works on its lot. On the seabed the floor under it is dug level to its lowest corner (deeper, never shallower);
 * at the surface nothing below is touched and it stands at the water's level. Neither blocks a boat.
 */
function put(w: World, rng: Rng, kind: UnderseaKind, x: number, z: number, wx: number, wz: number): Building {
  const afloat = AFLOAT_KINDS.has(kind);
  let low = 127;
  for (let zz = z; zz < z + wz; zz++) for (let xx = x; xx < x + wx; xx++) for (let q = 0; q < 4; q++) low = Math.min(low, w.corners[idx(xx, zz) * 4 + q]);
  const level = afloat ? w.water[idx(x + Math.floor(wx / 2), z + Math.floor(wz / 2))] : low;
  const b: Building = {
    kind, x, z, w: wx, d: wz, facing: Math.floor(rng() * 4) as Building['facing'], floors: 1, seed: Math.floor(rng() * 2 ** 31), solid: false, level, uid: w.allBuildings.length,
  };
  w.allBuildings.push(b);
  w.countryside.push(b);
  for (let zz = z; zz < z + wz; zz++) for (let xx = x; xx < x + wx; xx++) {
    const i = idx(xx, zz);
    w.flags[i] |= Flag.Poi;
    if (!afloat) for (let q = 0; q < 4; q++) w.corners[i * 4 + q] = low;
  }
  return b;
}

/** Tiles from the nearest land (or lake, or canal) for every ocean tile, up to `far`. */
function shoreDistance(w: World, far: number): Uint8Array {
  const d = new Uint8Array(N * N).fill(255);
  let q: number[] = [];
  for (let i = 0; i < N * N; i++) if (!ocean(w, i)) { d[i] = 0; q.push(i); }
  for (let step = 1; step <= far && q.length; step++) {
    const next: number[] = [];
    for (const i of q) {
      const x = i % N, z = (i - x) / N;
      for (const [dx, dz] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
        const tx = x + dx, tz = z + dz;
        if (!inB(tx, tz)) continue;
        const j = idx(tx, tz);
        if (d[j] !== 255) continue;
        d[j] = step;
        next.push(j);
      }
    }
    q = next;
  }
  return d;
}
