/**
 * The macro layer: what every cell on the endless lattice holds, worked out from hashes alone.
 *
 * Nothing in here ever looks at a generated cell, so any cell can know what its neighbours are —
 * whether the land runs on across a border, where a causeway or a road crossing lands, what the
 * continent it belongs to is called — without generating them. That is what lets two cells that
 * never see each other agree on the strip of terrain they share.
 */
import { N, REGION_KINDS, type CellKind, type RegionKind } from './tiles';
import { REGIONS } from './regions';
import { cell01, cellNoise, hashCell } from './rng';

import type { WorldMode } from '../title/api';
export type { WorldMode };

/** Above this, the macro field is continental land rather than open archipelago. */
export const CONT_THR = 0.601;

// ---------------- world modes ----------------

/**
 * The three world shapes, carried as a suffix on the seed so the worker, which only ever receives
 * the seed string, knows which it is in. No suffix is 'both': the world every existing seed means.
 */
const MODE_SUFFIX: Record<WorldMode, string> = { both: '', islands: '-isles', mainland: '-main' };
/** The words a mode suffix is made of; a random seed never ends in one. */
const RESERVED_SEED_WORDS = ['isles', 'main'] as const;

/** Split a seed into its base and the mode its suffix names. */
export function parseSeed(seed: string): { base: string; mode: WorldMode } {
  for (const mode of ['islands', 'mainland'] as const) {
    const suf = MODE_SUFFIX[mode];
    if (seed.length > suf.length && seed.endsWith(suf)) return { base: seed.slice(0, -suf.length), mode };
  }
  return { base: seed, mode: 'both' };
}

/** The same base seed with its suffix replaced by this mode's (or removed, for 'both'). */
export function seedWithMode(seed: string, mode: WorldMode): string {
  return parseSeed(seed).base + MODE_SUFFIX[mode];
}

/**
 * The mode the macro layer is answering for. Module-level: generation runs to completion on one
 * thread and the main thread only ever has one world loaded. The seed hash is the hash of the whole
 * seed, suffix and all, so every seed-keyed cache is already separate per mode.
 */
let MODE: WorldMode = 'both';
export function setWorldMode(mode: WorldMode): void { MODE = mode; }
export function worldMode(): WorldMode { return MODE; }

/**
 * The mainland's threshold on the raw field: low enough that about five cells in six are counties.
 * contField adds CONT_THR − MAIN_THR in mainland mode, so every reader keeps comparing to CONT_THR.
 */
const MAIN_THR = 0.3;
/**
 * The mainland's guaranteed bay north of home, which keeps (0,0) a coastal county. The field is
 * read at a cell's corner for its kind but across 0..1 for its tiles, so the bay is an ellipse over
 * the middle column: it holds the corners (0,-1), (1,-1) (and usually (0,-2), (1,-2)) under the
 * sea, spares (1,0) and (-1,0), and reaches about ninety tiles into home's north side, past the
 * seam band, so a harbour can stand on it.
 */
const BAY: readonly [number, number] = [0.5, -1.3];
const BAY_R: readonly [number, number] = [0.7, 2.04];
/** The middle of home's tiles, which the mainland floor keeps dry. */
const HOME_MID: readonly [number, number] = [0.5, 0.6];
/** What the mainland leaves to the sea rolls: open water, rocks and a few small islands, never a full one. */
const MAIN_SHARE: [CellKind, number][] = [['sea', 0.55], ['islet', 0.3], ['small', 0.15]];

/**
 * How often each remaining kind turns up among the cells the macro field left to the archipelago.
 * These are relative shares: the continental cells are taken out first, so the mix of islands to
 * open sea is exactly what it was before continents existed.
 */
const KIND_SHARE: [CellKind, number][] = [['full', 0.55], ['small', 0.2], ['islet', 0.1], ['sea', 0.15]];
/**
 * One full island in ten grows a megalopolis instead of the usual four towns. On a continent only a
 * coastal county can (its shipping channel needs a sea), and those are a sixth of a continent's
 * counties, so they take the roll at a higher rate: a main line meets a big city every few counties,
 * not once in a day's flying. A county whose kind came from one corner while its middle is sea never
 * gets one: it would have nowhere to put it.
 */
const MEGA_CHANCE = 0.1, MEGA_CHANCE_COUNTY = 0.24;
/** Chance that two neighbouring islands are joined by a causeway (above the 0.5 percolation threshold). */
const STRAIT_CHANCE = 0.6;
/** A second road across the same land border, so a continent is a lattice rather than a chain. */
const SECOND_CROSSING = 0.4;

/** Every seed keeps a continent this many cells east of the origin, so one is always a short sail away. */
const HOME_CONT: readonly [number, number] = [4, 0];
const HOME_CONT_R = 3.5;
/**
 * Home is always an island, so the field is held under the sea over it: a disc round the middle of
 * home's tiles (cell (0,0) spans 0..1 here). The disc holds all four of home's corners under water,
 * so no neighbour whose kind is read at one of them is a county, and it reaches over the strip of
 * any county beside home that faces it, so that county's coast is drawn by the field rather than
 * cut square by its fade.
 */
const HOME_ISLE: readonly [number, number] = [0.5, 0.5];
const HOME_ISLE_R = 1.25;

/**
 * The macro land field, over cell coordinates. Fractional coordinates are allowed and interpolate,
 * so the same field read at tile resolution draws a coastline that is the same line whichever cell
 * happens to be drawing it.
 */
export function contField(seedHash: number, cx: number, cz: number): number {
  const f = (cellNoise(seedHash, cx, cz, 7, 21) + 0.5 * cellNoise(seedHash, cx, cz, 3, 22)) / 1.5;
  // an archipelago has no continents: the field sits a whole unit under water everywhere
  if (MODE === 'islands') return f - 1;
  if (MODE === 'mainland') {
    let g = f + (CONT_THR - MAIN_THR);
    // home is always a county: a floor over the middle of its tiles (cell (0,0) spans 0..1 here)
    const dh = Math.hypot(cx - HOME_MID[0], cz - HOME_MID[1]);
    if (dh < 0.8) {
      const e = dh <= 0.4 ? 0 : (dh - 0.4) / 0.4;
      g = Math.max(g, (CONT_THR + 0.1) * (1 - e * e * (3 - 2 * e)));
    }
    const db = Math.hypot((cx - BAY[0]) / BAY_R[0], (cz - BAY[1]) / BAY_R[1]);
    if (db >= 1) return g;
    // a smooth ceiling, the floor inverted: held under the threshold over the inner three quarters,
    // rising clear of any value the field can take by its edge
    const e = db <= 0.75 ? 0 : (db - 0.75) / 0.25;
    return Math.min(g, CONT_THR - 0.12 + 0.8 * e * e * (3 - 2 * e));
  }
  let g = f;
  const d = Math.hypot(cx - HOME_CONT[0], cz - HOME_CONT[1]) / HOME_CONT_R;
  if (d < 1) {
    const t = 1 - d;
    // a smooth floor rather than an added bump, so the coastline stays continuous through it
    g = Math.max(g, (CONT_THR + 0.16) * t * t * (3 - 2 * t));
  }
  const di = Math.hypot(cx - HOME_ISLE[0], cz - HOME_ISLE[1]) / HOME_ISLE_R;
  if (di >= 1) return g;
  // the bay's ceiling again: under the threshold over the inner three fifths, clear of the field by the edge
  const e = di <= 0.6 ? 0 : (di - 0.6) / 0.4;
  return Math.min(g, CONT_THR - 0.12 + 0.8 * e * e * (3 - 2 * e));
}

/** How deep inside a continent a point lies: 0 at the edge of the blob, 1 well inland. */
export function continentality(seedHash: number, cx: number, cz: number): number {
  const t = (contField(seedHash, cx, cz) - CONT_THR) / 0.11;
  return t <= 0 ? 0 : t >= 1 ? 1 : t * t * (3 - 2 * t);
}

/** What the cell at (cx, cz) holds. The origin cell is always a full island, so every world starts well. */
export function cellKind(seedHash: number, cx: number, cz: number): CellKind {
  const raw = rawKind(seedHash, cx, cz);
  return raw === 'islet' && featureAt(seedHash, cx, cz, 'atoll') ? 'atoll' : raw;
}

/** The kind before any landform reshapes it: an atoll is an islet that became a ring. */
function rawKind(seedHash: number, cx: number, cz: number): CellKind {
  if (MODE === 'mainland') {
    if ((cx === 0 && cz === 0) || contField(seedHash, cx, cz) > CONT_THR) return 'continent';
  } else {
    if (cx === 0 && cz === 0) return 'full';
    if (MODE === 'both' && contField(seedHash, cx, cz) > CONT_THR) return 'continent';
  }
  let r = cell01(seedHash, cx, cz, 1);
  for (const [kind, share] of MODE === 'mainland' ? MAIN_SHARE : KIND_SHARE) {
    if (r < share) return kind;
    r -= share;
  }
  return 'sea';
}

/** A continental cell with open water somewhere on it: one of the eight around it is not continental. */
export function coastalContinent(seedHash: number, cx: number, cz: number): boolean {
  // an atoll is only ever an islet reshaped, so the raw kind answers "continent or not" exactly
  if (rawKind(seedHash, cx, cz) !== 'continent') return false;
  for (let dz = -1; dz <= 1; dz++) {
    for (let dx = -1; dx <= 1; dx++) {
      if (!dx && !dz) continue;
      if (rawKind(seedHash, cx + dx, cz + dz) !== 'continent') return true;
    }
  }
  return false;
}

/** A megalopolis needs a shipping channel, so on a continent it only grows where there is a coast. */
export function hasMega(seedHash: number, cx: number, cz: number): boolean {
  if (!megaRoll(seedHash, cx, cz, cellKind(seedHash, cx, cz))) return false;
  // a biome refuses a megalopolis, save the glass city in the dunes and the strip city on the sand
  const r = regionAt(seedHash, cx, cz);
  return !r || !!REGIONS[r].mega;
}

/** The megalopolis roll for a cell of this kind, before its biome has a say. */
function megaRoll(seedHash: number, cx: number, cz: number, kind: CellKind): boolean {
  if (kind === 'full') return cell01(seedHash, cx, cz, 2) < MEGA_CHANCE;
  if (kind !== 'continent' || !coastalContinent(seedHash, cx, cz)) return false;
  return cell01(seedHash, cx, cz, 2) < MEGA_CHANCE_COUNTY && landable(seedHash, cx, cz);
}

/** The two cells either side of side `d` of (cx, cz), named by the lower one so both ask the same question. */
function sharedEdge(cx: number, cz: number, d: number): [number, number, number, number, number] {
  const axis = d % 2 === 0 ? 0 : 1;
  const ax = d === 2 ? cx - 1 : cx;
  const az = d === 3 ? cz - 1 : cz;
  return [ax, az, axis === 0 ? ax + 1 : ax, axis === 0 ? az : az + 1, axis];
}

/**
 * Where a causeway crosses the border on side d of cell (cx, cz), or -1 for none. Causeways join
 * islands over water, and an island to the coast of a continent beside it; a border between two
 * counties is land all the way, and gets a road crossing instead.
 */
export function straitAt(seedHash: number, cx: number, cz: number, d: number): number {
  const [ax, az, bx, bz, axis] = sharedEdge(cx, cz, d);
  const ka = cellKind(seedHash, ax, az), kb = cellKind(seedHash, bx, bz);
  if (ka === 'sea' || kb === 'sea' || (ka === 'continent' && kb === 'continent')) return -1;
  // an atoll is all thin motus round a lagoon: nowhere to land a causeway, so it is reached by boat
  if (ka === 'atoll' || kb === 'atoll') return -1;
  if (cell01(seedHash, ax, az, 300 + axis) >= STRAIT_CHANCE) return -1;
  // a county whose kind its corner gave it, with no land in the middle to land on, gets no causeway
  if ((ka === 'continent' && !landable(seedHash, ax, az)) || (kb === 'continent' && !landable(seedHash, bx, bz))) return -1;
  // keep the landing in the middle half of the border, where the run inland is short
  return Math.round(N * 0.25 + cell01(seedHash, ax, az, 400 + axis) * N * 0.5);
}

/**
 * Does a county hold land a causeway can land on? Its kind is read at one corner, so the macro field
 * can clear the threshold there and fall short over every tile of it. Sampled over the middle of
 * the cell, where a causeway's landing is looked for, with a margin for the coast's noise.
 */
function landable(seedHash: number, cx: number, cz: number): boolean {
  for (let j = 0; j < 7; j++) {
    for (let i = 0; i < 7; i++) {
      if (contField(seedHash, cx + 0.2 + i * 0.1, cz + 0.2 + j * 0.1) > CONT_THR + 0.03) return true;
    }
  }
  return false;
}

/**
 * Where the roads cross the border on side d of cell (cx, cz): one or two tiles, named from the
 * shared edge exactly as a causeway is. Every border between two continental cells gets one, so
 * the counties are joined into a lattice rather than strung into a chain.
 */
export function crossingAt(seedHash: number, cx: number, cz: number, d: number): { at: number; wide: boolean }[] {
  const [ax, az, bx, bz, axis] = sharedEdge(cx, cz, d);
  if (cellKind(seedHash, ax, az) !== 'continent' || cellKind(seedHash, bx, bz) !== 'continent') return [];
  const wide = cell01(seedHash, ax, az, 560 + axis) < 0.45;
  const out = [{ at: Math.round(N * 0.12 + cell01(seedHash, ax, az, 500 + axis) * N * 0.34), wide }];
  if (cell01(seedHash, ax, az, 520 + axis) < SECOND_CROSSING) {
    out.push({ at: Math.round(N * 0.54 + cell01(seedHash, ax, az, 540 + axis) * N * 0.34), wide: false });
  }
  return out;
}

/** Share of borders between two counties that a river runs across. */
const RIVER_CHANCE = 0.55;
/** A river never crosses a border this near to where a road does, so neither has to bridge the other there. */
const RIVER_ROAD_GAP = 16;

/**
 * Where a river crosses side d of cell (cx, cz), or -1 for none — named from the shared edge like
 * a causeway, so both counties cut the same channel through the strip of ground they share and
 * each joins it to its own rivers further in. Only a border between two counties has one.
 */
export function riverAt(seedHash: number, cx: number, cz: number, d: number): number {
  const [ax, az, bx, bz, axis] = sharedEdge(cx, cz, d);
  if (cellKind(seedHash, ax, az) !== 'continent' || cellKind(seedHash, bx, bz) !== 'continent') return -1;
  if (cell01(seedHash, ax, az, 600 + axis) >= RIVER_CHANCE) return -1;
  const at = Math.round(N * 0.15 + cell01(seedHash, ax, az, 620 + axis) * N * 0.7);
  for (const c of crossingAt(seedHash, cx, cz, d)) if (Math.abs(c.at - at) < RIVER_ROAD_GAP) return -1;
  return at;
}

/** How a river crossing wanders either side of its border: a phase from the shared edge. */
export function riverPhase(seedHash: number, cx: number, cz: number, d: number): number {
  const [ax, az, , , axis] = sharedEdge(cx, cz, d);
  return cell01(seedHash, ax, az, 640 + axis) * Math.PI * 2;
}

/**
 * Share of whole islands and counties that keep a land dealer whatever size their towns are
 * (world/storefronts.ts places it). Known from the hash alone, so a new game's start can be chosen
 * where dealers are in reach before any cell is generated (world/spawn.ts). Cells with a metropolis
 * still get their dealer as before; this only adds to them.
 */
const DEALER_PLAN = 0.45;

/** Does cell (cx, cz) keep a land dealer by the plan (world/spawn.ts counts on it)? */
export function plannedDealer(seedHash: number, cx: number, cz: number): boolean {
  const k = cellKind(seedHash, cx, cz);
  if (k !== 'continent' && k !== 'full') return false;
  return cell01(seedHash, cx, cz, 2711) < DEALER_PLAN;
}

/** True when land, rather than water, runs across side d of this cell. */
export function landBorder(seedHash: number, cx: number, cz: number, d: number): boolean {
  if (cellKind(seedHash, cx, cz) !== 'continent') return false;
  const nx = cx + (d === 0 ? 1 : d === 2 ? -1 : 0);
  const nz = cz + (d === 1 ? 1 : d === 3 ? -1 : 0);
  return cellKind(seedHash, nx, nz) === 'continent';
}

// ---------------- names ----------------

const A = [
  'Amber', 'Bramble', 'Cinder', 'Drift', 'Ember', 'Fennel', 'Gale', 'Harrow', 'Ivory', 'Juniper',
  'Kelp', 'Lantern', 'Marrow', 'Nettle', 'Osprey', 'Pebble', 'Quill', 'Rook', 'Saffron', 'Thistle',
  'Umber', 'Verdant', 'Wicker', 'Yarrow',
];
const B = [
  'hollow', 'reach', 'spit', 'strand', 'bay', 'point', 'shoal', 'haven', 'cove', 'bank',
  'marsh', 'ridge', 'crag', 'meadow', 'fell', 'sound', 'wold', 'combe',
];
const SUFFIX: Record<CellKind, string[]> = {
  full: [' Island', ' Isle', ' Island', ' Land'],
  small: [' Isle', ' Island', ' Key'],
  islet: [' Rock', ' Skerry', ' Reef', ' Cay'],
  sea: [' Deep'],
  atoll: [' Atoll'],
  continent: [''],
};
/** What a continent's name is made of: grander, and never an island word. */
const CONT_B = ['fell', 'march', 'gard', 'holt', 'mere', 'wold', 'reach', 'vale', 'moor', 'heath'];
const COUNTY = ['County', 'Shire', 'Downs', 'Marches', 'Vale', 'Weald', 'Fells', 'Flats', 'Hundred', 'Riding'];

/** The name of the cell itself: an island's name, or a continental cell's county. */
export function cellName(seedHash: number, cx: number, cz: number, kind: CellKind): string {
  const h = hashCell(seedHash, cx, cz);
  const a = A[h % A.length];
  // a biome island is named for what it is: Amber Sands, Cinder Cay, Drift Fens
  const region = kind === 'full' || kind === 'small' ? regionAt(seedHash, cx, cz) : null;
  if (region) {
    const suf = REGIONS[region].islandSuffix;
    return a + suf[(h >>> 11) % suf.length];
  }
  // an island that is its landform is named for it
  if (kind === 'full' && featureAt(seedHash, cx, cz, 'volcano')) return `${VOLC_A[h % VOLC_A.length]}${VOLC_B[(h >>> 4) % VOLC_B.length]} Isle`;
  if (kind === 'full' && featureAt(seedHash, cx, cz, 'caldera')) return `${a}${B[(h >>> 5) % B.length]} Caldera`;
  if (kind === 'atoll') return `${a} Atoll`;
  if (kind === 'continent' && featureAt(seedHash, cx, cz, 'saltFlat')) return `the ${a} Saltings`;
  if (kind === 'continent') return `${a} ${COUNTY[(h >>> 7) % COUNTY.length]}`;
  const b = B[(h >>> 5) % B.length];
  return `${a}${b}${SUFFIX[kind][(h >>> 11) % SUFFIX[kind].length]}`;
}

/** How many cells of a continent may be walked before it is simply named where it is. */
const NAME_CAP = 400;

/**
 * A continent is named once, not once a cell. A bounded walk over cell kinds finds the blob's
 * lowest cell, and every cell in the same blob finds the same one; a continent too big to walk
 * falls back to a name per macro-noise cell, which is good enough for something that size.
 */
export function continentName(seedHash: number, cx: number, cz: number): string {
  let ax = cx, az = cz;
  const seen = new Set<string>([`${cx},${cz}`]);
  const queue: [number, number][] = [[cx, cz]];
  let capped = false;
  for (let h = 0; h < queue.length; h++) {
    const [x, z] = queue[h];
    if (z < az || (z === az && x < ax)) { ax = x; az = z; }
    if (queue.length >= NAME_CAP) { capped = true; break; }
    for (let d = 0; d < 4; d++) {
      const nx = x + (d === 0 ? 1 : d === 2 ? -1 : 0), nz = z + (d === 1 ? 1 : d === 3 ? -1 : 0);
      const k = `${nx},${nz}`;
      if (seen.has(k) || cellKind(seedHash, nx, nz) !== 'continent') continue;
      seen.add(k);
      queue.push([nx, nz]);
    }
  }
  if (capped) { ax = Math.round(cx / 6) * 6; az = Math.round(cz / 6) * 6; }
  const h = hashCell(seedHash, ax, az, 77);
  return `${A[h % A.length]}${CONT_B[(h >>> 9) % CONT_B.length]}`;
}

// ---------------- landforms ----------------

const VOLC_A = ['Ash', 'Cinder', 'Ember', 'Smoke', 'Sulphur', 'Obsidian', 'Brim', 'Scoria'];
const VOLC_B = ['fall', 'peak', 'horn', 'crown', 'maw', 'top'];

/** The five steps of rarity: the chance per eligible cell, and how near home one is promised. */
export const RARITY = { common: 1 / 2, uncommon: 1 / 4, rare: 1 / 12, veryRare: 1 / 40, legendary: 1 / 150 } as const;
const PROMISE = { rare: 6, veryRare: 12, legendary: 20 } as const;

/** The landforms a whole cell is given, decided from hashes alone like its kind. */
type CellFeature = 'volcano' | 'caldera' | 'atoll' | 'saltFlat' | 'karstTowers' | 'mesaCountry';

const FEATURE_RULE: Record<CellFeature, { rarity: keyof typeof RARITY; salt: number }> = {
  volcano: { rarity: 'rare', salt: 800 },
  caldera: { rarity: 'veryRare', salt: 810 },
  atoll: { rarity: 'rare', salt: 820 },
  saltFlat: { rarity: 'rare', salt: 830 },
  karstTowers: { rarity: 'rare', salt: 840 },
  mesaCountry: { rarity: 'rare', salt: 850 },
};

/**
 * The climate of a place, in cells: how warm and how wet. The same bands the tiles are coloured by,
 * smooth across borders, so a macro decision and the ground under it agree about where it is cold.
 */
export function climateAt(seedHash: number, u: number, v: number): { temp: number; wet: number } {
  const temp = 1.25 - v * 0.055 + (cellNoise(seedHash, u, v, 5.5, 7) - 0.5) * 0.7;
  const wet = cellNoise(seedHash, u, v, 3.1, 43);
  return { temp: temp < 0 ? 0 : temp > 1 ? 1 : temp, wet };
}

/** Could this cell hold the landform at all? */
function eligible(seedHash: number, cx: number, cz: number, f: CellFeature): boolean {
  const kind = rawKind(seedHash, cx, cz);
  if (f === 'atoll') return kind === 'islet';
  const region = regionAt(seedHash, cx, cz);
  if (region && REGIONS[region].forbid?.includes(f)) return false;
  const land = kind === 'full' || kind === 'small' || kind === 'continent';
  const mega = hasMegaRaw(seedHash, cx, cz, kind);
  const { temp, wet } = climateAt(seedHash, cx + 0.5, cz + 0.5);
  switch (f) {
    case 'volcano': return !mega && (kind === 'full' || (kind === 'continent' && coastalContinent(seedHash, cx, cz))) && !(cx === 0 && cz === 0);
    case 'caldera': return !mega && kind === 'full' && !(cx === 0 && cz === 0);
    case 'saltFlat': return !mega && kind === 'continent' && continentality(seedHash, cx + 0.5, cz + 0.5) > 0.35;
    // one giant a cell: the towers and the mesas give way to anything rarer
    case 'karstTowers': return !mega && land && temp > 0.55 && wet > 0.45 && !giant(seedHash, cx, cz);
    case 'mesaCountry': return !mega && land && temp > 0.4 && wet < 0.55 && !giant(seedHash, cx, cz) && !featureAt(seedHash, cx, cz, 'karstTowers');
  }
}

function giant(seedHash: number, cx: number, cz: number): boolean {
  return featureAt(seedHash, cx, cz, 'volcano') || featureAt(seedHash, cx, cz, 'caldera') || featureAt(seedHash, cx, cz, 'saltFlat');
}

function hasMegaRaw(seedHash: number, cx: number, cz: number, kind: CellKind): boolean {
  if (!megaRoll(seedHash, cx, cz, kind)) return false;
  const r = regionAt(seedHash, cx, cz);
  return !r || !!REGIONS[r].mega;
}

const promised = new Map<string, [number, number] | null>();
/** Promises being worked out right now: asking for one of these again would read a half-made answer. */
const promising = new Set<string>();

/**
 * The one cell near home the seed promises a rare landform on: of every eligible cell within the
 * promise radius, the one with the lowest roll. Order-independent, so any cell can ask.
 */
export function guaranteedCell(seedHash: number, f: CellFeature): [number, number] | null {
  const key = `${seedHash}:${f}`;
  if (promised.has(key)) return promised.get(key)!;
  const rule = FEATURE_RULE[f];
  const R = PROMISE[rule.rarity as keyof typeof PROMISE] ?? 0;
  // eligible() may ask other features, and they this one; a cycle back here must fail loudly, since
  // any answer it got (and featureAt cached) would depend on which cell happened to ask first
  if (promising.has(key)) throw new Error(`guaranteedCell: ${f} depends on itself`);
  promising.add(key);
  let best: [number, number] | null = null, bestRoll = Infinity;
  try {
    for (let cz = -R; cz <= R; cz++) {
      for (let cx = -R; cx <= R; cx++) {
        if (cx * cx + cz * cz > R * R || !eligible(seedHash, cx, cz, f)) continue;
        const roll = cell01(seedHash, cx, cz, rule.salt + 50);
        if (roll < bestRoll) { bestRoll = roll; best = [cx, cz]; }
      }
    }
  } finally {
    promising.delete(key);
  }
  promised.set(key, best);
  if (promised.size > 64) promised.delete(promised.keys().next().value as string);
  return best;
}

/** The landforms that stand alone: two salt pans, tower fields or mesa countries are never within this many cells. */
const LONER: Partial<Record<CellFeature, number>> = { saltFlat: 2, karstTowers: 2, mesaCountry: 2 };
const featureCache = new Map<string, boolean>();

/**
 * A biome that asks for a landform has it in every one of its cells, whatever the climate or the roll:
 * the Fire Coast its volcano, the Salt Pan its pan, Dragon Bay its towers, the Red Rock its mesas.
 */
function asked(seedHash: number, cx: number, cz: number, f: CellFeature): boolean {
  if (f === 'atoll' || f === 'caldera' || (cx === 0 && cz === 0)) return false;
  const region = regionAt(seedHash, cx, cz);
  if (!region || !REGIONS[region].ask?.includes(f)) return false;
  const kind = rawKind(seedHash, cx, cz);
  return kind === 'full' || kind === 'continent';
}

/** The roll or the promise, before a lone landform looks round at its neighbours. */
function featureRolled(seedHash: number, cx: number, cz: number, f: CellFeature): boolean {
  if (asked(seedHash, cx, cz, f)) return true;
  if (!eligible(seedHash, cx, cz, f)) return false;
  // a caldera island is never also a volcano island; the rarer one wins
  if (f === 'volcano' && featureAt(seedHash, cx, cz, 'caldera')) return false;
  const rule = FEATURE_RULE[f];
  if (cell01(seedHash, cx, cz, rule.salt) < RARITY[rule.rarity]) return true;
  const g = guaranteedCell(seedHash, f);
  return !!g && g[0] === cx && g[1] === cz;
}

/**
 * Does this cell carry the landform? A roll against its rarity, or the seed's promise. A lone kind
 * gives way to one of its own nearby: the promised cell always stands, otherwise the lower roll.
 */
export function featureAt(seedHash: number, cx: number, cz: number, f: CellFeature): boolean {
  const key = `${seedHash}:${f}:${cx},${cz}`;
  const hit = featureCache.get(key);
  if (hit !== undefined) return hit;
  let out = featureRolled(seedHash, cx, cz, f);
  const R = LONER[f];
  if (out && R && !asked(seedHash, cx, cz, f)) {
    const g = guaranteedCell(seedHash, f);
    const promisedHere = !!g && g[0] === cx && g[1] === cz;
    const roll = cell01(seedHash, cx, cz, FEATURE_RULE[f].salt);
    for (let dz = -R; dz <= R && out; dz++) {
      for (let dx = -R; dx <= R; dx++) {
        if ((!dx && !dz) || !featureRolled(seedHash, cx + dx, cz + dz, f)) continue;
        const theirs = !!g && g[0] === cx + dx && g[1] === cz + dz;
        const r2 = cell01(seedHash, cx + dx, cz + dz, FEATURE_RULE[f].salt);
        if (theirs || (!promisedHere && (r2 < roll || (r2 === roll && (dz < 0 || (dz === 0 && dx < 0)))))) { out = false; break; }
      }
    }
  }
  featureCache.set(key, out);
  if (featureCache.size > 50000) featureCache.delete(featureCache.keys().next().value as string);
  return out;
}

/** Where in its cell a cell-anchored landform sits, in local tiles, and how big it is. */
export function featurePlace(seedHash: number, cx: number, cz: number, f: CellFeature): { x: number; z: number; r: number; roll: number } {
  const salt = FEATURE_RULE[f].salt;
  const j = (k: number) => cell01(seedHash, cx, cz, salt + k);
  const R: Record<CellFeature, [number, number]> = {
    volcano: [46, 58], caldera: [36, 44], atoll: [84, 96], saltFlat: [34, 56], karstTowers: [34, 52], mesaCountry: [40, 56],
  };
  const [r0, r1] = R[f];
  const r = r0 + j(1) * (r1 - r0);
  // off-centre by as much as keeps the whole shape clear of the band a neighbour shares
  const slack = f === 'atoll' ? 0 : Math.max(0, 128 - 64 - r) * 0.8;
  return { x: 128 + (j(2) - 0.5) * 2 * slack, z: 128 + (j(3) - 0.5) * 2 * slack, r, roll: j(4) };
}

// ---------------- biomes ----------------

/** The chance per eligible cell, per biome kind, that it rolls an anchor. */
const REGION_ROLL = 1 / 6;
/**
 * No two anchors of any kind stand within this many cells (Chebyshev) of each other. The scope
 * started from five; measured over twenty seeds, five with greedy spacing keeps only 3.5% of cells
 * inside a biome, and four about 5%: still a few minutes of driving between one and the next.
 */
export const REGION_SPACING = 4;
/** A continental anchor spreads over counties this near it. */
const BLOB_R = 2;
/** The most counties a blob holds besides its anchor. */
const BLOB_MAX = 5;
/** The first biome is promised within this many cells of home, and every kind within the second. */
const FIRST_PROMISE = 4;
const KIND_PROMISE = 20;

const REGION_SALT = 1100;

/** Could this cell anchor this biome: the right kind of cell, in the right climate band? */
function regionEligible(seedHash: number, cx: number, cz: number, k: RegionKind): boolean {
  if (cx === 0 && cz === 0) return false;
  const spec = REGIONS[k];
  const kind = rawKind(seedHash, cx, cz);
  if (!spec.cells.includes(kind)) return false;
  if (kind === 'continent' && spec.coastal && !coastalContinent(seedHash, cx, cz)) return false;
  const { temp, wet } = climateAt(seedHash, cx + 0.5, cz + 0.5);
  if (spec.temp && (temp < spec.temp[0] || temp > spec.temp[1])) return false;
  if (spec.wet && (wet < spec.wet[0] || wet > spec.wet[1])) return false;
  return true;
}

const regionRoll = (seedHash: number, cx: number, cz: number, ki: number): number => cell01(seedHash, cx, cz, REGION_SALT + ki);

interface Promised { cells: Map<string, { kind: RegionKind; eff: number }> }
const promiseCache = new Map<number, Promised>();

/**
 * The cells the seed promises a biome on, worked out once per seed: first the lowest-rolling
 * eligible cell of any kind near home, then for each kind the lowest-rolling eligible cell within
 * twenty that keeps its distance from every promise already made. A promise is an anchor whatever
 * it rolled, and wins any spacing contest, so nothing nearer can take its place.
 */
function promises(seedHash: number): Promised {
  let p = promiseCache.get(seedHash);
  if (p) return p;
  p = { cells: new Map() };
  promiseCache.set(seedHash, p);
  if (promiseCache.size > 8) promiseCache.delete(promiseCache.keys().next().value as number);
  const taken: [number, number][] = [];
  const clear = (cx: number, cz: number) => taken.every(([x, z]) => Math.max(Math.abs(x - cx), Math.abs(z - cz)) > REGION_SPACING);
  const out = p;
  const choose = (R: number, kinds: number[], eff: number) => {
    let best: [number, number, number] | null = null, bestRoll = Infinity;
    for (let cz = -R; cz <= R; cz++) {
      for (let cx = -R; cx <= R; cx++) {
        if (cx * cx + cz * cz > R * R || !clear(cx, cz)) continue;
        for (const ki of kinds) {
          if (!regionEligible(seedHash, cx, cz, REGION_KINDS[ki])) continue;
          const roll = regionRoll(seedHash, cx, cz, ki);
          if (roll < bestRoll) { bestRoll = roll; best = [cx, cz, ki]; }
        }
      }
    }
    if (!best) return;
    taken.push([best[0], best[1]]);
    out.cells.set(`${best[0]},${best[1]}`, { kind: REGION_KINDS[best[2]], eff });
  };
  const all = REGION_KINDS.map((_, i) => i);
  choose(FIRST_PROMISE, all, -2);
  // the pickiest kinds choose first: with twenty kinds keeping their distance, one that can only stand on a
  // dry continent in a narrow band of warmth found every place it could have gone already taken
  const room = all.map((ki) => {
    let n = 0;
    for (let cz = -KIND_PROMISE; cz <= KIND_PROMISE; cz++) {
      for (let cx = -KIND_PROMISE; cx <= KIND_PROMISE; cx++) {
        if (cx * cx + cz * cz <= KIND_PROMISE * KIND_PROMISE && regionEligible(seedHash, cx, cz, REGION_KINDS[ki])) n++;
      }
    }
    return n;
  });
  for (const ki of [...all].sort((a, b) => room[a] - room[b] || a - b)) {
    if ([...out.cells.values()].some((v) => v.kind === REGION_KINDS[ki])) continue;
    choose(KIND_PROMISE, [ki], -1 + ki * 0.001);
  }
  return p;
}

/** The lowest roll this cell makes for any biome it could anchor, or null when it makes none. */
function candidate(seedHash: number, cx: number, cz: number): { kind: RegionKind; eff: number } | null {
  const pr = promises(seedHash).cells.get(`${cx},${cz}`);
  if (pr) return pr;
  let best: { kind: RegionKind; eff: number } | null = null;
  for (let ki = 0; ki < REGION_KINDS.length; ki++) {
    const roll = regionRoll(seedHash, cx, cz, ki);
    if (roll >= REGION_ROLL || (best && roll >= best.eff)) continue;
    if (!regionEligible(seedHash, cx, cz, REGION_KINDS[ki])) continue;
    best = { kind: REGION_KINDS[ki], eff: roll };
  }
  return best;
}

const anchorCache = new Map<string, RegionKind | null>();
function cached<T>(cache: Map<string, T>, key: string, make: () => T): T {
  if (cache.has(key)) return cache.get(key)!;
  const v = make();
  cache.set(key, v);
  if (cache.size > 20000) cache.delete(cache.keys().next().value as string);
  return v;
}

/**
 * The biome this cell anchors, if any: it rolled one (or was promised one) and no cell within the
 * spacing rolled lower. Every cell scans the same neighbourhood, so the answer never depends on
 * which cell asked first.
 */
export function regionAnchor(seedHash: number, cx: number, cz: number): RegionKind | null {
  return cached(anchorCache, `${seedHash}:${cx},${cz}`, () => {
    const me = candidate(seedHash, cx, cz);
    if (!me) return null;
    // Greedy by roll: a candidate gives way only to a lower-rolling candidate nearby that is itself
    // an anchor. Rolls strictly fall along any chain of that question, so it always ends, and every
    // cell reaches the same answer whichever cell asked first.
    for (let dz = -REGION_SPACING; dz <= REGION_SPACING; dz++) {
      for (let dx = -REGION_SPACING; dx <= REGION_SPACING; dx++) {
        if (!dx && !dz) continue;
        const o = candidate(seedHash, cx + dx, cz + dz);
        // ties broken by position, so exactly one of two equal rolls wins
        if (!o || !(o.eff < me.eff || (o.eff === me.eff && (dz < 0 || (dz === 0 && dx < 0))))) continue;
        if (regionAnchor(seedHash, cx + dx, cz + dz)) return null;
      }
    }
    return me.kind;
  });
}

const blobCache = new Map<string, Set<string>>();

/**
 * The counties a continental anchor spreads over: its neighbours within two whose noise clears the
 * bar and that join up with it through one another, strongest first, up to six in all.
 */
function blobOf(seedHash: number, ax: number, az: number, kind: RegionKind): Set<string> {
  return cached(blobCache, `${seedHash}:${ax},${az}`, () => {
    const ki = REGION_KINDS.indexOf(kind);
    const out = new Set<string>([`${ax},${az}`]);
    const score = (cx: number, cz: number) => cellNoise(seedHash, cx, cz, 2, 900 + ki);
    // grow by the best frontier cell, so a capped blob keeps its strongest, connected counties
    for (let n = 0; n < BLOB_MAX; n++) {
      let best: [number, number] | null = null, bestS = 0.45;
      for (const key of out) {
        const [x, z] = key.split(',').map(Number);
        for (let d = 0; d < 4; d++) {
          const nx = x + (d === 0 ? 1 : d === 2 ? -1 : 0), nz = z + (d === 1 ? 1 : d === 3 ? -1 : 0);
          if (Math.max(Math.abs(nx - ax), Math.abs(nz - az)) > BLOB_R || out.has(`${nx},${nz}`)) continue;
          if (rawKind(seedHash, nx, nz) !== 'continent' || (nx === 0 && nz === 0) || nearRival(seedHash, nx, nz, ax, az)) continue;
          const s = score(nx, nz);
          if (s > bestS) { bestS = s; best = [nx, nz]; }
        }
      }
      if (!best) break;
      out.add(`${best[0]},${best[1]}`);
    }
    return out;
  });
}

/**
 * Another anchor near enough that its blob could come up against this county. Both blobs refuse
 * such a county, so two biomes' counties are always at least two cells apart and the fade between
 * them never has to decide which biome a tile belongs to.
 */
function nearRival(seedHash: number, cx: number, cz: number, ax: number, az: number): boolean {
  const R = 2 * BLOB_R;
  for (let dz = -R; dz <= R; dz++) {
    for (let dx = -R; dx <= R; dx++) {
      const x = cx + dx, z = cz + dz;
      if (x === ax && z === az) continue;
      if (regionAnchor(seedHash, x, z)) return true;
    }
  }
  return false;
}

const regionCache = new Map<string, RegionKind | null>();

/**
 * Which biome a cell is part of. An island anchor is its biome entirely, and each islet beside it
 * joins it one time in two; a continental anchor spreads over a blob of counties.
 */
export function regionAt(seedHash: number, cx: number, cz: number): RegionKind | null {
  return cached(regionCache, `${seedHash}:${cx},${cz}`, () => {
    const own = regionAnchor(seedHash, cx, cz);
    if (own) return own;
    const kind = rawKind(seedHash, cx, cz);
    if (kind === 'continent') {
      for (let dz = -BLOB_R; dz <= BLOB_R; dz++) {
        for (let dx = -BLOB_R; dx <= BLOB_R; dx++) {
          const a = regionAnchor(seedHash, cx + dx, cz + dz);
          if (!a || rawKind(seedHash, cx + dx, cz + dz) !== 'continent') continue;
          if (blobOf(seedHash, cx + dx, cz + dz, a).has(`${cx},${cz}`)) return a;
        }
      }
    } else if (kind === 'islet' && !(cx === 0 && cz === 0)) {
      for (let d = 0; d < 4; d++) {
        const nx = cx + (d === 0 ? 1 : d === 2 ? -1 : 0), nz = cz + (d === 1 ? 1 : d === 3 ? -1 : 0);
        const a = regionAnchor(seedHash, nx, nz);
        const nk = rawKind(seedHash, nx, nz);
        if (a && (nk === 'full' || nk === 'small') && cell01(seedHash, cx, cz, 1250 + d) < 0.5) return a;
      }
    }
    return null;
  });
}

/**
 * A cell that holds its biome's wonder. A biome island is its own anchor and rolls once; on a continent
 * the anchor county rolls and so does every other county of the blob, so a biome the size of five
 * counties shows two or three of its wonders rather than one at most. A promised biome always shows it,
 * so the first one met is worth the trip.
 */
/** Is this one of the cells the seed promises a biome on (and so its wonder)? */
export function promisedBiome(seedHash: number, cx: number, cz: number): boolean {
  return promises(seedHash).cells.has(`${cx},${cz}`);
}

export function regionWonder(seedHash: number, cx: number, cz: number): boolean {
  const r = regionAt(seedHash, cx, cz);
  if (!r) return false;
  if (promises(seedHash).cells.has(`${cx},${cz}`)) return true;
  const anchor = regionAnchor(seedHash, cx, cz) === r;
  return cell01(seedHash, cx, cz, 1300) < (anchor ? 0.6 : 0.45);
}

/**
 * How much of a biome reaches a global tile: the kind (1 + index, 0 for none) and a weight 0..1.
 *
 * An island is its cell's membership outright, since its borders are sea. On a continent the
 * membership of the four nearest cell centres is interpolated, warped a little so the edge is not
 * a straight line, and eased, so both counties either side of a blob's edge compute the same
 * number tile for tile. A non-continental cell counts as a member where it touches one.
 */
export class RegionField {
  private member = new Map<number, number>();
  private kindOf = new Map<number, number>();
  constructor(private seedHash: number) {}

  private key(cx: number, cz: number): number { return (cx + 4096) * 8192 + (cz + 4096); }

  /** 1 + index of the biome a cell belongs to, or 0. */
  cellRegion(cx: number, cz: number): number {
    const k = this.key(cx, cz);
    let v = this.kindOf.get(k);
    if (v === undefined) {
      const r = regionAt(this.seedHash, cx, cz);
      v = r ? REGION_KINDS.indexOf(r) + 1 : 0;
      this.kindOf.set(k, v);
    }
    return v;
  }

  /** The kind that counts at a cell centre when interpolating across a continent. */
  private effective(cx: number, cz: number): number {
    const k = this.key(cx, cz);
    let v = this.member.get(k);
    if (v === undefined) {
      v = this.cellRegion(cx, cz);
      if (!v && rawKind(this.seedHash, cx, cz) !== 'continent') {
        for (let dz = -1; dz <= 1 && !v; dz++) for (let dx = -1; dx <= 1 && !v; dx++) {
          if ((dx || dz) && rawKind(this.seedHash, cx + dx, cz + dz) === 'continent') v = this.cellRegion(cx + dx, cz + dz);
        }
      }
      this.member.set(k, v);
    }
    return v;
  }

  at(gx: number, gz: number): { k: number; w: number } {
    const cx = Math.floor(gx / N), cz = Math.floor(gz / N);
    if (rawKind(this.seedHash, cx, cz) !== 'continent') {
      const k = this.cellRegion(cx, cz);
      return { k, w: k ? 1 : 0 };
    }
    const u = gx / N, v = gz / N;
    const wu = u - 0.5 + (cellNoise(this.seedHash, u, v, 1.1, 951) - 0.5) * 0.5;
    const wv = v - 0.5 + (cellNoise(this.seedHash, u, v, 1.1, 953) - 0.5) * 0.5;
    const i0 = Math.floor(wu), j0 = Math.floor(wv), t = wu - i0, s = wv - j0;
    const c00 = this.effective(i0, j0), c10 = this.effective(i0 + 1, j0), c01 = this.effective(i0, j0 + 1), c11 = this.effective(i0 + 1, j0 + 1);
    const k = c00 || c10 || c01 || c11;
    if (!k) return { k: 0, w: 0 };
    const m = (c: number) => (c === k ? 1 : 0);
    const val = (m(c00) * (1 - t) + m(c10) * t) * (1 - s) + (m(c01) * (1 - t) + m(c11) * t) * s;
    const e = Math.min(1, Math.max(0, (val - 0.3) / 0.4));
    return { k, w: e * e * (3 - 2 * e) };
  }
}
