/**
 * How a biome bends its towns without a builder per biome: where it likes to put them, the oasis a
 * desert town needs, and the biome's own placements once a town's core is down. The swap table,
 * the style taste, the surface and the names are plain data in regions.ts and are applied by
 * buildTowns and the Layout; this file holds the parts that have to look at the ground.
 */
import { N, SEA, Biome, DIRS, Lot, World, idx, inB, type BuildingKind, type TownKind } from './tiles';
import type { RegionSpec } from './regions';
import type { Building } from './tiles';

/** A summed-area table over a per-tile value. */
class Sum {
  private s = new Float64Array((N + 1) * (N + 1));
  constructor(f: (i: number) => number) {
    const M = N + 1;
    for (let z = 0; z < N; z++) {
      let row = 0;
      for (let x = 0; x < N; x++) {
        row += f(z * N + x);
        this.s[(z + 1) * M + x + 1] = this.s[z * M + x + 1] + row;
      }
    }
  }
  over(x0: number, z0: number, x1: number, z1: number): number {
    const M = N + 1, c = (v: number) => Math.max(0, Math.min(N, v));
    x0 = c(x0); z0 = c(z0); x1 = c(x1); z1 = c(z1);
    const s = this.s;
    return s[z1 * M + x1] - s[z0 * M + x1] - s[z1 * M + x0] + s[z0 * M + x0];
  }
}

/** A term added to planTowns' score for a site (lower is better). */
export type SiteBias = (x0: number, z0: number, size: number) => number;

/**
 * The biome's taste in town sites, as an O(1) term on the ordinary score: the Shallows want the
 * coast, the Sands an oasis, the Heights a valley floor by a river, the Whitewash a cliff top, the
 * Fens the highest dry ground, the Moors the lee of a hill.
 */
export function siteBias(w: World, spec: RegionSpec, land: Uint8Array, river: Uint8Array, lakeLvl: Int8Array, cliff: Uint8Array): SiteBias | undefined {
  const E = w.elev;
  const height = new Sum((i) => E[i]);
  switch (spec.site) {
    case 'coast': {
      const shore = new Sum((i) => (land[i] && w.coastDist[i] <= 10 ? 1 : 0));
      return (x0, z0, s) => -6 * shore.over(x0 - 8, z0 - 8, x0 + s + 8, z0 + s + 8) / ((s + 16) * (s + 16));
    }
    case 'oasis': {
      const lake = new Sum((i) => (lakeLvl[i] > -128 ? 1 : 0));
      return (x0, z0, s) => (lake.over(x0 - 10, z0 - 10, x0 + s + 10, z0 + s + 10) > 0 ? -2 : 0);
    }
    case 'valley': {
      const wet = new Sum((i) => (river[i] || lakeLvl[i] > -128 ? 1 : 0));
      return (x0, z0, s) => height.over(x0, z0, x0 + s, z0 + s) / (s * s) * 0.18 - (wet.over(x0 - 10, z0 - 10, x0 + s + 10, z0 + s + 10) > 0 ? 1.5 : 0);
    }
    case 'cliffTop': {
      const edge = new Sum((i) => cliff[i]);
      return (x0, z0, s) => -Math.min(3, edge.over(x0 - 8, z0 - 8, x0 + s + 8, z0 + s + 8) * 0.03);
    }
    case 'levee':
      return (x0, z0, s) => -height.over(x0, z0, x0 + s, z0 + s) / (s * s) * 0.5;
    case 'lee':
      return (x0, z0, s) => height.over(x0, z0, x0 + s, z0 + s) / (s * s) * 0.1;
    default:
      return undefined;
  }
}

/**
 * Every desert town sits beside water. A town planned with no lake within reach gets a small bowl
 * dug just outside its footprint, on the side nearest the island's middle, and palms will find it.
 */
export function digOases(w: World, plans: { x0: number; z0: number; size: number }[], land: Uint8Array, lakeLvl: Int8Array, river: Uint8Array): void {
  const E = w.elev;
  for (const p of plans) {
    let near = false;
    for (let z = p.z0 - 12; z < p.z0 + p.size + 12 && !near; z += 2) {
      for (let x = p.x0 - 12; x < p.x0 + p.size + 12; x += 2) if (inB(x, z) && lakeLvl[idx(x, z)] > -128) { near = true; break; }
    }
    if (near) continue;
    const cx = p.x0 + p.size / 2, cz = p.z0 + p.size / 2;
    // try each side, nearest the middle first
    const sides = [0, 1, 2, 3].sort((a, b) => {
      const da = Math.hypot(cx + DIRS[a][0] * p.size - N / 2, cz + DIRS[a][1] * p.size - N / 2);
      const db = Math.hypot(cx + DIRS[b][0] * p.size - N / 2, cz + DIRS[b][1] * p.size - N / 2);
      return da - db;
    });
    for (const d of sides) {
      const R = 5;
      const ox = Math.round(cx + DIRS[d][0] * (p.size / 2 + 9)), oz = Math.round(cz + DIRS[d][1] * (p.size / 2 + 9));
      let ok = inB(ox - R - 2, oz - R - 2) && inB(ox + R + 2, oz + R + 2);
      for (let dz = -R - 1; dz <= R + 1 && ok; dz++) {
        for (let dx = -R - 1; dx <= R + 1; dx++) {
          const i = idx(ox + dx, oz + dz);
          if (!land[i] || w.biome[i] === Biome.Town || river[i] || E[i] < SEA + 1.5) { ok = false; break; }
        }
      }
      if (!ok) continue;
      const lv = Math.round(E[idx(ox, oz)]) - 1;
      for (let dz = -R; dz <= R; dz++) {
        for (let dx = -R; dx <= R; dx++) {
          const d2 = Math.hypot(dx, dz);
          if (d2 > R) continue;
          const i = idx(ox + dx, oz + dz);
          const t = 1 - d2 / R;
          E[i] -= 2.6 * t * t * (3 - 2 * t);
          if (E[i] < lv - 0.2) { lakeLvl[i] = lv; w.biome[i] = Biome.Ocean; }
        }
      }
      break;
    }
  }
}

/** What the placement calls look like from here, so this file need not import the Layout. */
interface Placer {
  put(kind: BuildingKind, over?: Record<string, unknown>): Building | null;
  rng(): number;
  kind: TownKind;
}

/**
 * The biome's own buildings in a town, placed once its core is down and before the filler, so the
 * souk gets its square and the pagoda its corner before houses take them.
 */
export function regionExtras(c: Placer, spec: RegionSpec): void {
  const big = c.kind === 'city' || c.kind === 'metro' || c.kind === 'mega';
  const mid = big || c.kind === 'suburb';
  const n = (rural: number, suburb: number, city: number) => (big ? city : mid ? suburb : rural);
  const many = (kind: BuildingKind, k: number, over?: Record<string, unknown>) => { for (let i = 0; i < k; i++) c.put(kind, over); };
  switch (spec.kind) {
    case 'sands':
      c.put('souk');
      if (big) c.put('caravanserai');
      many('windTower', n(1, 2, 4));
      if (!mid) c.put('tentCamp');
      break;
    case 'icefield':
      many('sauna', n(1, 1, 2));
      c.put('sledKennels');
      many('fishRacks', n(1, 2, 3));
      break;
    case 'shallows':
      many('beachClub', n(1, 1, 2));
      many('tikiBar', n(1, 2, 3));
      if (mid) { c.put('marina'); c.put('boardwalk'); many('resortVillas', n(0, 2, 3)); }
      if (big) c.put('golfCourse');
      break;
    case 'green':
      many('stiltHouse', n(2, 3, 4));
      if (mid) c.put('tradingPost');
      c.put('plantation');
      break;
    case 'heights':
      c.put('dairy');
      if (mid) c.put('funicular');
      break;
    case 'moors':
      c.put('distillery');
      many('croft', n(2, 2, 1));
      break;
    case 'veldt':
      c.put('rangerPost');
      if (!mid) c.put('kraal');
      if (big) c.put('safariLodge');
      break;
    case 'fens':
      many('shrimpShack', n(1, 2, 3));
      c.put('airboatDock');
      many('stiltHouse', n(2, 2, 1));
      break;
    case 'terraces':
      c.put('pagoda');
      many('shrine', n(1, 2, 3));
      c.put('teaHouse');
      if (mid) c.put('bathhouse');
      many('riceTerraces', n(1, 1, 2));
      break;
    case 'whitewash':
      many('blueChapel', 3);
      c.put('windmillRow');
      many('taverna', n(1, 2, 3));
      break;
    case 'goldhills':
      break;
    case 'firecoast':
      c.put('hotSpringBaths');
      many('turfHouse', n(3, 3, 2));
      if (mid) c.put('geothermalPlant');
      break;
    case 'fjords':
      many('boatShed', n(2, 3, 4));
      many('rorbu', n(3, 4, 4));
      if (mid) c.put('fishFarm');
      break;
    case 'bigtimber':
      c.put('loggingCamp');
      c.put('lookoutTower');
      if (mid) { c.put('seaplaneBase'); c.put('lumberYard'); }
      if (big) c.put('paperMill');
      break;
    case 'redrock':
      c.put('roadhouse');
      many('pueblo', n(1, 2, 3));
      if (mid) c.put('mineHeadframe');
      break;
    case 'dragonbay':
      c.put('karstPagoda');
      many('junkMooring', n(1, 2, 3));
      c.put('floatingVillage');
      many('riceTerraces', n(1, 1, 2));
      many('shrine', n(1, 1, 2));
      break;
    case 'steppe':
      many('yurtCamp', n(2, 2, 1));
      c.put('horseCorral');
      c.put('ovoo');
      break;
    case 'saltpan':
      c.put('saltWorks');
      if (mid) c.put('saltHotel');
      c.put('trainCemetery');
      break;
    case 'mangrove':
      many('stiltVillage', n(1, 1, 2));
      c.put('airboatDock');
      c.put('shrimpFarm');
      many('stiltHouse', n(2, 2, 1));
      break;
    case 'lavender':
      many('lavenderField', n(2, 2, 1));
      c.put('perfumery');
      many('dovecote', n(1, 1, 2));
      many('bastide', n(1, 1, 0));
      break;
  }
}

/** Kinds that sit on the town's lot finish differently in a biome: sand streets in the desert. */
export function regionLot(spec: RegionSpec | null, df: number, base: Lot): Lot {
  if (!spec) return base;
  if (spec.kind === 'sands' && base === Lot.Lawn) return Lot.Sand;
  if (spec.kind === 'whitewash' && base === Lot.Lawn && df < 0.6) return Lot.Plaza;
  if ((spec.kind === 'redrock' || spec.kind === 'saltpan') && base === Lot.Lawn) return Lot.Sand;
  if (spec.kind === 'steppe' && base === Lot.Lawn) return Lot.Yard;
  return base;
}
