import type { Building, BuildingKind } from './tiles';
import { boxes } from './regionShapesC';

/**
 * Which parts of the September 2026 expansion's buildings block vehicles, in the model's local frame
 * (origin mid-lot, +z the way it faces, W across and D deep), measured off the models as drawn. Kinds
 * left out fill their lot. The ones that matter most are the lots a car is meant to drive onto: the drag
 * strip, the speed strip, the proving ground, the hill-climb lane, the trail through the giant tree.
 * See footprint.ts.
 */
type Solid = (lx: number, lz: number) => boolean;
const any = (...list: Solid[]): Solid => (x, z) => list.some((f) => f(x, z));
const disc = (cx: number, cz: number, r: number): Solid => (x, z) => Math.hypot(x - cx, z - cz) <= r;

export const EXPANSION_SHAPES: Partial<Record<BuildingKind, (W: number, D: number, b: Building) => Solid>> = {
  // ---- the driver's destinations ----
  // the hut and its terrace; the strip by the sign and the bays along the front are open
  summitCafe: () => boxes({ x: -0.3, z: -0.2, w: 1.2, d: 1.3 }),
  // the wall and the viewing strip at the back; the pull-in is open
  scenicOverlook: () => boxes({ x: 0, z: -0.55, w: 1.9, d: 0.7 }),
  // the lane runs across the lot along x and is open end to end; the hut, the arch legs and the stand block
  hillClimb: () => boxes({ x: -0.95, z: -0.74, w: 0.52, d: 0.32 }, { x: -0.3, z: 0.66, w: 0.24, d: 0.24 }, { x: -0.3, z: -0.66, w: 0.24, d: 0.24 },
    { x: 1.14, z: 0.76, w: 0.36, d: 0.26 }),
  // the tent row and the caravan at the back; the yard in front is gravel to drive round
  // (from the lot's W and D, as the model is: a 4 x 3 lot can be drawn 3 wide and 4 deep)
  rallyStage: (W, D) => boxes({ x: -W / 2 + 1.57, z: -D / 2 + 0.68, w: 2.74, d: 0.96 }, { x: W / 2 - 0.55, z: -D / 2 + 0.5, w: 0.72, d: 0.56 }),
  // two lanes the length of the lot between low walls: only the walls, the tower and the stand block
  dragStrip: (_W, D) => boxes({ x: -1.05, z: 0, w: 0.08, d: D - 0.1 }, { x: 1.05, z: 0, w: 0.08, d: D - 0.1 },
    { x: 1.25, z: -D / 2 + 2.0, w: 0.32, d: 0.58 }, { x: 1.24, z: -D / 2 + 3.45, w: 0.32, d: 1.9 }),
  // the banking along the back, the workshop and the tower; the pad and the test lanes are open. Worked
  // from the lot's own W and D as the model is (buildings/motoring.ts): a 10 x 8 lot facing along its long
  // side is drawn 8 wide and 10 deep, and the old fixed boxes left an invisible wall in front of the
  // banking and the workshop there (the user, 21 Oct 2026)
  provingGround: (W, D) => {
    const hw = W / 2, hd = D / 2;
    return boxes({ x: -hw + 3.1, z: -hd + 0.825, w: 5.6, d: 1.26 }, { x: hw - 1.15, z: -hd + 0.95, w: 1.9, d: 1.5 },
      { x: hw - 2.65, z: -hd + 0.85, w: 0.74, d: 0.74 });
  },
  // the cabin; the lane out onto the ice is open
  iceRoadCheckpoint: () => boxes({ x: -0.48, z: -0.22, w: 0.72, d: 0.46 }),
  // the building and the totem; the forecourt, the lorry park and the car park are open
  motorwayServices: (W, D) => boxes({ x: -W / 2 + 1.95, z: -D / 2 + 0.65, w: 3.5, d: 1.0 }, { x: -W / 2 + 0.4, z: D / 2 - 0.4, w: 0.5, d: 0.2 }),

  // ---- institutions ----
  // the stages, the backlot fronts and the trailers; the lane from the gate to the stage doors is open
  filmStudio: () => boxes({ x: -0.4, z: -1.4, w: 4.8, d: 1.8 }, { x: 2.5, z: -1.7, w: 0.6, d: 0.6 }, { x: 1.8, z: 0.5, w: 1.9, d: 0.8 },
    { x: -1.82, z: 1.0, w: 1.75, d: 0.3 }),
  // the barracks, the parked column, the shelter and the huts; the entry road, the square and the pad are open
  militaryBase: () => boxes({ x: -1.95, z: -1.4, w: 2.7, d: 2.0 }, { x: -2.22, z: 0.95, w: 2.45, d: 0.5 }, { x: -2.22, z: 1.85, w: 2.45, d: 0.5 },
    { x: 2.55, z: -1.75, w: 1.8, d: 1.7 }, { x: 0.4, z: -2.05, w: 0.5, d: 0.5 }, { x: 1.1, z: -1.6, w: 0.9, d: 0.5 }),
  // the rampart all round; the gate tunnel and its bridge are open
  borderFort: () => (x, z) => Math.abs(x) <= 1.9 && Math.abs(z) <= 1.9 && !(Math.abs(x) <= 0.22 && z >= 0.8),
  // the station, the pylon and the kiosk
  cableCarStation: () => boxes({ x: -0.15, z: 0.47, w: 1.3, d: 0.75 }, { x: -0.15, z: -0.5, w: 0.45, d: 0.45 }, { x: 0.7, z: 0.62, w: 0.38, d: 0.38 }),
  // the dome, the lab row and the radome
  researchDome: () => any(disc(-0.4, -0.4, 0.93), boxes({ x: 0.37, z: 0.8, w: 1.85, d: 0.8 }), disc(1.02, -1.0, 0.25)),
  // the permanent fence, stage deck and loos (the summer stages come and go); the field is open
  festivalGrounds: () => boxes({ x: 0, z: -2.15, w: 1.9, d: 1.1 }, { x: -2.58, z: -0.35, w: 0.25, d: 1.3 }),

  // ---- heavy industry and energy ----
  // the plant along the back and the spheres; the yard at the front is open
  refinery: (W) => boxes({ x: 0, z: -1.35, w: W, d: 2.3 }, { x: 1.22, z: 0, w: 1.45, d: 0.7 }, { x: -2.0, z: 0.55, w: 1.3, d: 0.6 }),
  // the furnace block, the incline, the shed and the slag; the front is open
  steelworks: () => boxes({ x: -1.5, z: -1.45, w: 3.0, d: 2.1 }, { x: -1.1, z: 0.52, w: 0.7, d: 1.85 }, { x: 1.42, z: -1.25, w: 2.85, d: 2.1 },
    { x: 2.1, z: 1.15, w: 1.6, d: 1.1 }),
  textileMill: () => boxes({ x: -0.7, z: -0.85, w: 2.3, d: 0.95 }, { x: 1.4, z: -0.95, w: 1.0, d: 0.7 }, { x: 1.18, z: 0.26, w: 1.35, d: 1.05 },
    { x: 0.65, z: -0.55, w: 0.46, d: 0.46 }),
  paperMill: (W, D) => boxes({ x: 0, z: (-D / 2 + 0.95) / 2, w: W, d: D / 2 + 0.95 }),
  cementPlant: (W) => boxes({ x: 0, z: -0.9, w: W, d: 2.2 }, { x: -0.65, z: 0.32, w: 1.2, d: 0.65 }, { x: -1.78, z: 0.12, w: 1.15, d: 1.05 }),
  // the stacks and the gantries; the lanes between them and the gate are open
  containerTerminal: () => boxes({ x: -0.72, z: -1.75, w: 4.05, d: 1.2 }, { x: -0.72, z: -0.35, w: 4.05, d: 1.2 }, { x: 2.45, z: -1.18, w: 0.9, d: 2.25 }),
  autoPlant: () => boxes({ x: -0.8, z: -1.45, w: 5.1, d: 1.8 }, { x: 2.68, z: -1.05, w: 1.35, d: 2.6 }, { x: -1.02, z: 0.52, w: 4.55, d: 1.45 }),
  // the panel banks; the tracks between and in front are open
  solarFarm: () => boxes({ x: -1.52, z: -0.35, w: 2.56, d: 4.0 }, { x: 1.52, z: -0.35, w: 2.56, d: 4.0 }, { x: 2.28, z: 1.46, w: 1.03, d: 0.98 }),
  // the dam and its tower; the water either side is the sea's
  tidalBarrage: () => boxes({ x: 0, z: -0.12, w: 8, d: 0.75 }, { x: 3.45, z: -0.2, w: 0.9, d: 1.1 }),
  pumpedHydro: () => any((x, z) => (x / 2.38) ** 2 + ((z + 0.95) / 0.95) ** 2 <= 1,
    boxes({ x: -0.75, z: 0.25, w: 1.2, d: 1.1 }, { x: -0.75, z: 1.06, w: 1.7, d: 0.6 }, { x: 1.35, z: 0.87, w: 2.1, d: 1.15 })),

  // ---- the Fire Coast, the Fjordlands, the Big Timber ----
  geothermalPlant: (_W, D) => boxes({ x: 0, z: -0.15, w: 4, d: D - 0.6 }),
  hotSpringBaths: () => boxes({ x: 0, z: 0, w: 2.4, d: 2.4 }),
  // the church, the terrace and its walls; only the front beyond the steps is open
  arcticCathedral: () => boxes({ x: 0, z: -0.5, w: 10.6, d: 10.0 }),
  greatGeyser: () => any(disc(0.3, -0.9, 4.4), boxes({ x: 2.4, z: 5.38, w: 1.2, d: 0.6 })),
  loggingCamp: () => boxes({ x: -0.85, z: -0.25, w: 0.7, d: 1.75 }, { x: 0.35, z: 1.05, w: 1.45, d: 0.5 }, { x: 0.65, z: -0.95, w: 1.15, d: 0.62 },
    { x: 0.55, z: 0.1, w: 0.56, d: 0.4 }),
  // the colossal trunk in two halves either side of the tunnel, the lesser giants, the fence and the kiosk;
  // the trail through the tunnel and on up the lot is open
  giantTree: () => any(boxes({ x: -0.72, z: 0, w: 0.75, d: 2.2 }, { x: 0.72, z: 0, w: 0.75, d: 2.2 }, { x: 2.0, z: 5.45, w: 0.9, d: 0.75 }),
    disc(-3.7, -3.2, 0.6), disc(3.6, -3.6, 0.6), disc(-4.2, 1.6, 0.6), disc(4.0, 1.2, 0.6), disc(0.9, -4.6, 0.6)),

  // ---- the Red Rock ----
  // the three buttes on their skirts; the ground between them and the loop track are open
  monumentButtes: (W, D) => any(disc(-W / 2 + 3.0, -1.6, 2.3), disc(W / 2 - 3.0, -0.9, 2.2), disc(0.4, -D / 2 + 2.9, 2.35)),

  // ---- the Salt Pan, the Mangroves, the Lavender Plateau ----
  saltWorks: () => boxes({ x: -0.35, z: -0.85, w: 2.7, d: 1.1 }, { x: 1.3, z: -0.5, w: 0.5, d: 0.8 }, { x: 1.28, z: 0.8, w: 0.85, d: 0.7 }),
  saltHotel: () => boxes({ x: -0.28, z: -0.32, w: 1.15, d: 0.85 }, { x: 0.64, z: -0.18, w: 0.4, d: 1.35 }),
  // the engines and wagons stand askew on their stubs of track; between them is open
  trainCemetery: () => boxes({ x: -0.65, z: -0.88, w: 1.25, d: 0.34 }, { x: 0.55, z: 0.12, w: 1.25, d: 0.5 }, { x: -0.8, z: 0.88, w: 1.25, d: 0.45 },
    { x: 1.0, z: -0.9, w: 0.62, d: 0.28 }, { x: 1.2, z: 0.9, w: 0.62, d: 0.28 }),
  // three tiles of salt down the middle are the course; only the tower and the pits stand beside it
  speedStrip: (_W, D) => boxes({ x: 2.45, z: D / 2 - 4.15, w: 0.64, d: 0.64 }, { x: -2.35, z: -D / 2 + 1.2, w: 0.5, d: 1.5 }),
  shrimpFarm: () => boxes({ x: -0.4, z: -0.28, w: 1.8, d: 2.05 }, { x: 1.0, z: -0.45, w: 0.62, d: 1.3 }),
  perfumery: () => boxes({ x: -0.32, z: -0.2, w: 0.95, d: 1.15 }, { x: 0.48, z: -0.35, w: 0.65, d: 0.8 }),
  bastide: () => boxes({ x: -0.18, z: -0.42, w: 0.95, d: 0.62 }, { x: 0.53, z: -0.4, w: 0.5, d: 0.52 }),
  // the church, the cloister and the ranges at the back; the lavender and the path up to the door are open
  lavenderAbbey: () => boxes({ x: -0.8, z: -4.4, w: 7.2, d: 1.5 }, { x: 0, z: -4.15, w: 1.4, d: 2.9 }, { x: -3.05, z: -2.1, w: 4.7, d: 3.2 },
    { x: 4.3, z: -4.7, w: 1.9, d: 1.0 }),

  // ---- things to find ----
  // the street down the middle of the ghost town runs along x and is open
  ghostTown: (W) => boxes({ x: 0, z: -1.5, w: W - 0.4, d: 1.3 }, { x: 0, z: 1.5, w: W - 0.4, d: 1.3 }),
};
