import * as THREE from 'three';

/**
 * The characters on Tokyo's blade signs (kit.ts `bladeSign`): one a storey, top to bottom, spelling out
 * what is inside — an izakaya, sushi, karaoke, a pharmacy — and the capitals a stadium spells its team with. They are drawn once into a texture atlas
 * (white on clear, a cell a character) and laid on the signs as little quads of their own, so the
 * town's vertex-coloured mesh stays as it is.
 */

/** What a sign says, read downwards. */
export const SIGN_WORDS = [
  '居酒屋', '寿司', 'カラオケ', '焼肉', '薬局', '喫茶', '本屋', '麻雀', '銀行', '美容室', '食堂', '酒場',
  '茶屋', '映画', '旅館', '電気', '質屋', 'ホテル', '中華', '洋食', '定食', '古着', '整体', '歯科',
  'そば', 'うどん', '天ぷら', '餃子', 'バー', 'ゲーム', 'パチンコ', '靴',
];

/** Every character any word needs, in the atlas's order. */
const LATIN = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789&'-.!";
/** Words only the restaurants spell (render/buildings/eateries.ts): ramen, and dim sum. */
const EXTRA = 'ラーメン点心';
/** Osaka's own lettering (render/buildings/osaka.ts): Dōtonbori, the tower, the arcade, crab, puffer fish, takoyaki. */
export const OSAKA_WORDS = ['道頓堀', '通天閣', '心斎橋筋', 'かに', 'ふぐ', 'たこ焼き', '串カツ', 'くいだおれ', '大阪'];
/** An onsen town's (render/buildings/onsen*.ts): its inns' names, the baths, the hells, the ropeway. */
const ONSEN_WORDS = ['福住楼', '道後温泉', 'ゆ', '民宿', '旅館', '能登屋', '藤屋', '松乃家', '古山閣', '湯畑', '足湯', '海地獄', '血の池', '白池', '坊主', 'ロープウェイ', 'ホテル',
  // 0.7.0 (render/buildings/models070.ts): Kinosaki's and Kusatsu's public baths, the kōban, the post office, the shops
  '一の湯', '御所の湯', '柳湯', '大滝乃湯', '交番', '郵便局', '酒屋', '和菓子', '豆腐'];
const CHARS = [...new Set(SIGN_WORDS.join('') + EXTRA + LATIN + OSAKA_WORDS.join('') + ONSEN_WORDS.join(''))];
/** Cells a side of the atlas. */
const GRID = Math.ceil(Math.sqrt(CHARS.length));
const CELL = 64;

let material: THREE.MeshBasicMaterial | null = null;

/** Where a character sits in the atlas: its cell's corners in texture space. */
export function glyphUv(ch: string): { u0: number; v0: number; u1: number; v1: number } {
  const i = Math.max(0, CHARS.indexOf(ch));
  const col = i % GRID, row = Math.floor(i / GRID);
  // the canvas is flipped as it is uploaded: its top row is at v = 1
  return { u0: col / GRID, u1: (col + 1) / GRID, v0: 1 - (row + 1) / GRID, v1: 1 - row / GRID };
}

/**
 * The atlas's material, drawn the first time a sign needs it. White characters, lit day and night, tinted by
 * each quad's vertex colour: white for Tokyo's blades and the stadiums, a neon colour for a theatre's name
 * (render/buildings/neon.ts).
 */
export function glyphMaterial(): THREE.MeshBasicMaterial {
  if (material) return material;
  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = GRID * CELL;
  const g = canvas.getContext('2d')!;
  g.fillStyle = '#fff';
  g.textAlign = 'center';
  g.textBaseline = 'middle';
  g.font = `700 ${Math.round(CELL * 0.78)}px "Yu Gothic", "Meiryo", "Hiragino Sans", "Noto Sans JP", "MS Gothic", sans-serif`;
  CHARS.forEach((ch, i) => {
    const col = i % GRID, row = Math.floor(i / GRID);
    const cx = col * CELL + CELL / 2, cy = row * CELL + CELL / 2;
    if (LATIN.includes(ch)) {
      // a stadium's lettering (render/buildings/stadiums.ts): a tall, narrow sports face
      g.save();
      g.font = `${Math.round(CELL * 0.86)}px Impact, "Arial Narrow", "Arial Black", sans-serif`;
      g.fillText(ch, cx, cy + CELL * 0.04);
      g.restore();
    } else if (ch === 'ー') {
      // written down a sign, the long-vowel bar stands upright
      g.save();
      g.translate(cx, cy);
      g.rotate(Math.PI / 2);
      g.fillText(ch, 0, CELL * 0.03);
      g.restore();
    } else g.fillText(ch, cx, cy + CELL * 0.03);
  });
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 4;
  material = new THREE.MeshBasicMaterial({
    map: tex, vertexColors: true, transparent: true, depthWrite: false, side: THREE.DoubleSide,
    polygonOffset: true, polygonOffsetFactor: -2, polygonOffsetUnits: -2,
  });
  return material;
}
