import { N, Feature, Lot, World, idx, inB, type Work } from './tiles';
import { DECKS, DECK_TAKES } from './decks';
import { planStands, planStrips, type PlanStrip } from './airportPlans';

/**
 * Runways (docs/rides.html): where an airfield's strip lies, which way it points, where a jet waits on
 * the apron and how it gets from there to either end. Everything is read back from the finished Work
 * and its tiles, the way cutAirfield laid them out, so nothing new is generated and GEN_VERSION stays.
 * Points are in world tiles (a cell's local tiles plus its origin), so a jet flying over a border
 * still finds the runway on the other side.
 */
export interface Runway {
  name: string;
  major: boolean;
  /** The cell it belongs to, and that cell's origin. */
  w: World;
  /** Threshold ends of the usable length (world tiles, on the centreline). */
  ax: number; az: number; bx: number; bz: number;
  /** Unit vector from A to B, and the heading that flies it (x = sin h, z = cos h). */
  ux: number; uz: number; heading: number;
  /** Threshold to threshold, and the strip's half-width, in tiles. */
  len: number; half: number;
  /** The ground's height, world units, and the pad level in steps. */
  y: number;
  /** Unit vector across the strip toward the apron. */
  sx: number; sz: number;
  /** How far across (from the centreline) the taxi line runs, on the shoulder between strip and apron. */
  taxiOff: number;
  /** The two live stands on the apron, at either end, nose toward the strip. */
  stands: { x: number; z: number; heading: number }[];
  /** A carrier's flight deck (world/decks.ts): it moves, it has no overrun, and the catapult makes it fit more. */
  deck?: boolean;
  /**
   * A two-runway international (world/airportPlans.ts, 0.7.0): the other runway, at right angles, sharing this one's
   * apron and stands (the same array) and its lock (the two cross, or meet at a corner). `second` on the other one:
   * the airport is the first, so anything that lists airports rather than strips (cargo, dealers) skips it.
   */
  pair?: Runway;
  second?: true;
}

const cache = new WeakMap<World, Runway[]>();

/** Every runway in a cell, worked out once per world (and again if its tiles change). */
export function runwaysOf(w: World): Runway[] {
  const hit = cache.get(w);
  if (hit && (hit as Runway[] & { rev?: number }).rev === w.revision) return hit;
  const list = w.works.filter((g) => g.kind === 'airfield').flatMap((g) => (g.plan ? twinOf(w, g) : [runwayOf(w, g)])).filter((r): r is Runway => !!r);
  (list as Runway[] & { rev?: number }).rev = w.revision;
  cache.set(w, list);
  return list;
}

/**
 * Rebuild the strip's rectangle from a Work, mirroring cutAirfield: an international is 48 × 5 with a
 * 12-deep apron, a municipal 26 × 3 with 6; facing 1 runs the strip along x, and the strip is the
 * first `wid` rows of the block on its low side.
 */
export function runwayOf(w: World, g: Work): Runway | null {
  const major = g.major;
  const len = major ? 48 : 26, wid = major ? 5 : 3, apron = major ? 12 : 6;
  const depth = wid + apron;
  const alongX = g.facing === 1;
  const x0 = alongX ? g.x - len / 2 : g.x - Math.round(depth / 2);
  const z0 = alongX ? g.z - Math.round(depth / 2) : g.z - len / 2;
  // along and across, in local tiles, to a point
  const at = (along: number, across: number): [number, number] => (alongX ? [x0 + along, z0 + across] : [x0 + across, z0 + along]);
  const [ax, az] = at(2, wid / 2), [bx, bz] = at(len - 2, wid / 2);
  // the strip must really be there (a cell edited since, or a layout this doesn't know, gives no runway)
  const mid = at(len / 2, 0.5);
  const i = inB(Math.floor(mid[0]), Math.floor(mid[1])) ? idx(Math.floor(mid[0]), Math.floor(mid[1])) : -1;
  if (i < 0 || w.feature[i] !== Feature.Airfield) return null;
  const ux = alongX ? 1 : 0, uz = alongX ? 0 : 1;
  const sx = alongX ? 0 : 1, sz = alongX ? 1 : 0;
  const standAcross = wid + apron * (2 / 3);
  const standAlong = major ? 8 : 5.5;
  const stands = [standAlong, len - standAlong].map((along) => {
    const [x, z] = at(along, standAcross);
    // nose toward the strip
    return { x: x + w.ox, z: z + w.oz, heading: Math.atan2(-sx, -sz) };
  });
  return {
    name: g.name, major, w,
    ax: ax + w.ox, az: az + w.oz, bx: bx + w.ox, bz: bz + w.oz,
    ux, uz, heading: Math.atan2(ux, uz),
    len: len - 4, half: wid / 2,
    y: g.level * 0.5, sx, sz,
    taxiOff: wid / 2 + 1,
    stands,
  };
}

/** A two-runway international's runways, the x-running one first: its pair, sharing the apron's two stands. */
function twinOf(w: World, g: Work): Runway[] {
  const p = g.plan!;
  const stands = planStands(p).map((s) => ({ x: s.x + w.ox, z: s.z + w.oz, heading: s.heading }));
  const [a, b] = planStrips(p).map((s) => stripRunway(w, g, s, stands));
  if (!a || !b) return [];
  a.pair = b; b.pair = a; b.second = true;
  return [a, b];
}

/** One strip of a plan as a runway: thresholds two tiles in from either end, the taxiway on its apron side. */
function stripRunway(w: World, g: Work, s: PlanStrip, stands: Runway['stands']): Runway | null {
  const mx = Math.floor(s.alongX ? s.x0 + s.len / 2 : s.x0 + s.wid / 2), mz = Math.floor(s.alongX ? s.z0 + s.wid / 2 : s.z0 + s.len / 2);
  if (!inB(mx, mz) || w.feature[idx(mx, mz)] !== Feature.Airfield) return null;
  const ux = s.alongX ? 1 : 0, uz = s.alongX ? 0 : 1;
  const ax = s.alongX ? s.x0 + 2 : s.x0 + s.wid / 2, az = s.alongX ? s.z0 + s.wid / 2 : s.z0 + 2;
  return {
    name: g.name, major: true, w,
    ax: ax + w.ox, az: az + w.oz, bx: ax + ux * (s.len - 4) + w.ox, bz: az + uz * (s.len - 4) + w.oz,
    ux, uz, heading: Math.atan2(ux, uz),
    len: s.len - 4, half: s.wid / 2,
    y: g.level * 0.5, sx: s.alongX ? 0 : s.side, sz: s.alongX ? s.side : 0,
    taxiOff: s.wid / 2 + 1,
    stands,
  };
}

/** The runway a two-runway airport's lock is kept by (its first): one mover at a time on either strip, since they cross or meet. */
export const lockOf = (r: Runway): Runway => (r.second && r.pair ? r.pair : r);

/**
 * Which of an airport's runways movement `n` uses: the one more into the wind (`wind`, the heading it blows
 * toward), but every third the other, so a two-runway airport's crosswind runway sees traffic too. One runway: it.
 */
export function stripFor(r: Runway, wind: number, n: number): Runway {
  const o = r.pair;
  if (!o) return r;
  const into = (q: Runway) => Math.abs(Math.cos(q.heading - wind));
  const first = into(r) >= into(o) ? r : o;
  return Math.abs(n) % 3 === 2 ? (first === r ? o : r) : first;
}

/** Every runway in the cells in memory that is an airport of its own (a two-runway airport once, by its first). */
export const allAirports = (): Runway[] => allRunways().filter((r) => !r.second);

/** Where a world point lies against a runway: distance along from A, and across from the centreline (toward the apron positive). */
export function frameOf(r: Runway, gx: number, gz: number): { along: number; across: number } {
  const dx = gx - r.ax, dz = gz - r.az;
  return { along: dx * r.ux + dz * r.uz, across: dx * r.sx + dz * r.sz };
}

/** A point on the runway's frame, back in world tiles. */
export function pointOf(r: Runway, along: number, across: number): { x: number; z: number } {
  return { x: r.ax + r.ux * along + r.sx * across, z: r.az + r.uz * along + r.sz * across };
}

/** On the paved strip itself (including the painted thresholds and a tile of overrun each end). */
export function onStrip(r: Runway, gx: number, gz: number): boolean {
  const f = frameOf(r, gx, gz);
  const over = r.deck ? 0.2 : 2;
  return f.along >= -over && f.along <= r.len + over && Math.abs(f.across) <= r.half;
}

/** Is local tile (x, z) of w part of an airfield (strip, shoulder or apron)? */
export function airfieldTile(w: World, x: number, z: number): boolean {
  const tx = Math.floor(x), tz = Math.floor(z);
  if (!inB(tx, tz)) return false;
  const i = idx(tx, tz);
  return w.feature[i] === Feature.Airfield && (w.lot[i] === Lot.Runway || w.lot[i] === Lot.Paved || w.lot[i] === Lot.Apron || w.lot[i] === Lot.Gravel);
}

/** The cells a jet can see runways in: set by main.ts from the resident worlds whenever they change. */
export const AIRSPACE = { worlds: [] as World[] };

/** Every runway in the resident cells. */
export function allRunways(): Runway[] {
  return AIRSPACE.worlds.flatMap((w) => runwaysOf(w));
}

/** Does a jet that needs `need` tiles of runway fit this one? */
export const fitsRunway = (need: number, r: Runway): boolean => (r.deck ? need <= DECK_TAKES : r.len >= need);

/**
 * Every runway the player's planes may use: the airfields' and the carriers' flight decks. (Ambient
 * air traffic sticks to allRunways: no CPU airliner lands on your carrier.)
 */
export function jetRunways(): Runway[] {
  const fields = allRunways();
  return DECKS.length ? [...fields, ...DECKS.map((d) => d.runway)] : fields;
}

/** The runway nearest a world point that fits, or null. */
export function nearestRunway(gx: number, gz: number, need: number, within = Infinity): Runway | null {
  let best: Runway | null = null, bestD = within;
  for (const r of allRunways()) {
    if (!fitsRunway(need, r)) continue;
    const d = Math.hypot((r.ax + r.bx) / 2 - gx, (r.az + r.bz) / 2 - gz);
    if (d < bestD) { bestD = d; best = r; }
  }
  return best;
}

/** A point at the centre of a cell, for runways the macro says exist but that aren't generated yet. */
export const cellCentre = (cx: number, cz: number) => ({ x: cx * N + N / 2, z: cz * N + N / 2 });
