import { hex, scale, type RGB } from '../../world/biomes';
import type { Rng } from '../../world/rng';
import { DARK, type Kit } from './kit';
import { drum } from './concessions';

/**
 * A horse-drawn carriage for park tours: an open landau, its hood folded down behind two passengers, the coachman
 * up on his box in a top hat with his whip, and a team of one or two horses. Drawn facing +z, the carriage round
 * its own middle on the ground and the team round theirs, so a rig can steer each along a path on its own
 * (carriageBody, horseTeam); horseCarriage draws the two together, the team TEAM_AHEAD in front.
 *
 * The team comes in two strides (the trot's diagonal pairs one way, then the other), for a rig to swap between.
 */

interface CarriagePalette {
  body: RGB; trim: RGB; wheel: RGB; seat: RGB; hood: RGB;
  horse: RGB; mane: RGB; coat: RGB; passengers: [RGB, RGB]; skins: [RGB, RGB, RGB]; hat: RGB;
}

const BODIES = [0x1f2a24, 0x2a2a30, 0x5a1e24, 0x1f3550, 0x2f4a32];
const TRIMS = [0xd4a72c, 0xb8862c, 0xe8e0c8, 0x9a2a2a];
const WHEELS = [0xd4a72c, 0x9a2a2a, 0x1f2a24, 0xe8e0c8];
const SEATS = [0x8e1b2b, 0x3a2a22, 0x2f5a3a, 0x6a4a2a];
const HORSES = [0x6a4430, 0x8a5a36, 0x3a2a22, 0xf4f2ec, 0x9a9690, 0xb07a4a];
const DRESS = [0xe2412f, 0x2f7fb5, 0xf2c14e, 0x3f9b4a, 0xf4f2ec, 0x8e5cc7, 0xff7fae, 0x2bb3a3];
const SKIN = [0xf1c7a1, 0xd9a07a, 0x9a6a48, 0x6a4632, 0xf4d9bf];

const one = (r: Rng, a: readonly number[]): RGB => hex(a[Math.floor(r() * a.length) % a.length]);

/** A carriage's colours, its team's and its people's. */
export function carriagePalette(r: Rng): CarriagePalette {
  const horse = one(r, HORSES);
  const light = horse[0] + horse[1] + horse[2] > 2.2;
  return {
    body: one(r, BODIES), trim: one(r, TRIMS), wheel: one(r, WHEELS), seat: one(r, SEATS), hood: hex(0x1e1e22),
    horse, mane: light ? hex(0xd8d2c6) : scale(horse, 0.45), coat: one(r, [0x1e1e22, 0x3a2a22, 0x5a1e24]),
    passengers: [one(r, DRESS), one(r, DRESS)], skins: [one(r, SKIN), one(r, SKIN), one(r, SKIN)],
    hat: one(r, [0xf6e7c8, 0xe2412f, 0xf4f2ec]),
  };
}

/** From the carriage's middle to its team's, along its heading. */
export const TEAM_AHEAD = 0.29;

/** One horse facing +z, its middle at (x, z): `stride` picks which diagonal pair of legs is reaching forward. */
function horse(k: Kit, x: number, z: number, pal: CarriagePalette, stride: number): void {
  const c = pal.horse, m = pal.mane;
  k.box(x, 0.08, z, 0.048, 0.056, 0.145, c);
  k.bar([x, 0.12, z + 0.06], [x, 0.183, z + 0.094], 0.016, c);
  k.bar([x, 0.143, z + 0.047], [x, 0.2, z + 0.083], 0.006, m);
  k.bar([x, 0.191, z + 0.089], [x, 0.16, z + 0.138], 0.0135, c);
  k.box(x, 0.147, z + 0.136, 0.022, 0.017, 0.014, scale(c, 0.7));
  for (const s of [-1, 1]) k.box(x + s * 0.007, 0.196, z + 0.087, 0.005, 0.014, 0.005, c);
  k.bar([x, 0.128, z - 0.072], [x, 0.064, z - 0.094], 0.0075, m);
  // the trot: one diagonal pair reaching forward while the other pushes back
  for (const [lx, lz, pair] of [[-1, 1, 0], [1, -1, 0], [1, 1, 1], [-1, -1, 1]] as [number, number, number][]) {
    const swing = (pair === stride ? 1 : -1) * 0.02, hx = x + lx * 0.0145, hz = z + lz * 0.055;
    k.bar([hx, 0.085, hz], [hx, 0.01, hz + swing], 0.0072, c);
    k.box(hx, 0, hz + swing, 0.014, 0.011, 0.016, DARK);
  }
  // the collar and the saddle pad of the harness
  k.box(x, 0.11, z + 0.064, 0.053, 0.026, 0.017, DARK);
  k.box(x, 0.134, z - 0.004, 0.053, 0.007, 0.034, DARK);
}

/** A team of `n` horses facing +z round their middle: stride 0 or 1. */
export function horseTeam(k: Kit, pal: CarriagePalette, stride: number, n: 1 | 2 = 2, z = 0): void {
  if (n === 1) { horse(k, 0, z, pal, stride); return; }
  horse(k, -0.034, z, pal, stride);
  horse(k, 0.034, z, pal, 1 - stride);
  k.bar([-0.034, 0.12, z + 0.065], [0.034, 0.12, z + 0.065], 0.004, DARK);
}

/** The landau facing +z round its middle, with its coachman and two passengers; `n` horses' worth of shafts or pole. */
export function carriageBody(k: Kit, pal: CarriagePalette, n: 1 | 2 = 2): void {
  // wheels, big behind and small in front, on their axles and the perch between them
  for (const s of [-1, 1]) {
    drum(k, s * 0.1, 0.068, -0.1, 0.068, 0.012, DARK, 'x', pal.wheel, 12);
    drum(k, s * 0.088, 0.05, 0.085, 0.05, 0.011, DARK, 'x', pal.wheel, 10);
  }
  k.bar([-0.094, 0.068, -0.1], [0.094, 0.068, -0.1], 0.006, DARK);
  k.bar([-0.083, 0.05, 0.085], [0.083, 0.05, 0.085], 0.006, DARK);
  k.bar([0, 0.066, -0.1], [0, 0.054, 0.085], 0.007, DARK);
  // the open body, a stripe round it
  k.box(0, 0.075, -0.025, 0.15, 0.075, 0.23, pal.body);
  k.box(0, 0.126, -0.025, 0.154, 0.01, 0.234, pal.trim);
  // the rear seat, its back and the hood folded down behind
  k.box(0, 0.15, -0.08, 0.13, 0.014, 0.075, pal.seat);
  k.box(0, 0.15, -0.128, 0.15, 0.058, 0.022, pal.body);
  drum(k, 0, 0.19, -0.158, 0.026, 0.154, pal.hood, 'x', pal.hood, 8);
  // the coachman's box and footboard
  k.box(0, 0.15, 0.06, 0.13, 0.055, 0.045, pal.body);
  k.box(0, 0.205, 0.06, 0.12, 0.01, 0.04, pal.seat);
  k.box(0, 0.108, 0.11, 0.12, 0.01, 0.04, pal.body);
  for (const s of [-1, 1]) {
    k.box(s * 0.072, 0.15, 0.085, 0.006, 0.05, 0.006, DARK);
    k.box(s * 0.072, 0.2, 0.085, 0.014, 0.022, 0.014, pal.trim);
  }
  // the pole out to a pair, or shafts either side of one horse
  if (n === 2) k.bar([0, 0.07, 0.1], [0, 0.118, TEAM_AHEAD + 0.07], 0.006, DARK);
  else for (const s of [-1, 1]) k.bar([s * 0.05, 0.08, 0.1], [s * 0.033, 0.115, TEAM_AHEAD + 0.06], 0.005, DARK);
  // two passengers, one in a sun hat
  for (const [s, i] of [[-1, 0], [1, 1]] as [number, 0 | 1][]) {
    k.box(s * 0.034, 0.164, -0.084, 0.038, 0.046, 0.028, pal.passengers[i]);
    k.box(s * 0.034, 0.21, -0.084, 0.024, 0.024, 0.024, pal.skins[i]);
  }
  k.cyl(-0.034, 0.234, -0.084, 0.024, 0.004, pal.hat, 10);
  k.cyl(-0.034, 0.238, -0.084, 0.013, 0.012, pal.hat, 8);
  // the coachman in his top hat, whip up, reins out to the team
  k.box(0, 0.215, 0.058, 0.04, 0.05, 0.028, pal.coat);
  k.box(0, 0.265, 0.058, 0.024, 0.024, 0.024, pal.skins[2]);
  k.cyl(0, 0.289, 0.058, 0.02, 0.004, DARK, 10);
  k.cyl(0, 0.293, 0.058, 0.012, 0.03, DARK, 8);
  k.bar([0.024, 0.235, 0.072], [0.055, 0.34, 0.15], 0.0022, DARK);
  for (const s of [-1, 1]) k.bar([s * 0.012, 0.235, 0.075], [s * 0.03, 0.17, TEAM_AHEAD + 0.09], 0.0016, DARK);
}

/** The whole turnout, standing: the carriage round its middle and the team TEAM_AHEAD in front of it. */
function horseCarriage(k: Kit, pal: CarriagePalette, n: 1 | 2 = 2, stride = 0): void {
  carriageBody(k, pal, n);
  horseTeam(k, pal, stride, n, TEAM_AHEAD);
}
