  ramenShop: { label: 'Ramen shop', icon: '🍜', cuisine: 'Japanese' },
  sushiBar: { label: 'Sushi bar', icon: '🍣', cuisine: 'Japanese' },
  dumplingHouse: { label: 'Dumpling house', icon: '🥟', cuisine: 'Chinese' },
  noodleBar: { label: 'Noodle bar', icon: '🍲', cuisine: 'Southeast Asian' },
  trattoria: { label: 'Trattoria', icon: '🍕', cuisine: 'Italian' },
  curryHouse: { label: 'Curry house', icon: '🍛', cuisine: 'Indian' },
  deli: { label: 'Deli', icon: '🥪', cuisine: 'sandwiches' },
  taqueria: { label: 'Taqueria', icon: '🌮', cuisine: 'Mexican' },
