  victorian: { chippy: 2, curryHouse: 1, deli: 0.6 },
  mediterranean: { trattoria: 3, kebabShop: 1 },
  adobe: { taqueria: 3 },
  timber: { deli: 1.5, chippy: 0.6 },
  pastel: { taqueria: 1, deli: 1 },
