const DEFAULT_HOME: Menu = { deli: 1 };

/** What a big city imports: every kitchen, by how common it is out in the world. */
const WORLD: Record<FoodKind, number> = {
  ramenShop: 1, sushiBar: 1.1, dumplingHouse: 1, noodleBar: 0.8, trattoria: 1.4, curryHouse: 1.2, deli: 1.2, taqueria: 1, kebabShop: 1, chippy: 0.5,
};

/** The styles whose streets stay up after dark under neon: one more arcade in a town of any size that has them. */
const NEON_TOWNS = new Set<string>(['tokyo', 'japanese', 'vegas', 'cyberpunk', 'hongkong', 'osaka']);

/** How many places to eat a town of each size has (`odds` that a village has one at all), and the share from its own kitchen. */
const PLAN: Record<TownKind, { n: [number, number]; odds: number; home: number }> = {
  rural: { n: [1, 1], odds: 0.55, home: 1 },
  suburb: { n: [1, 2], odds: 1, home: 0.85 },
  city: { n: [2, 3], odds: 1, home: 0.65 },
  metro: { n: [4, 6], odds: 1, home: 0.45 },
  mega: { n: [8, 10], odds: 1, home: 0.3 },
};

export function homeMenu(style: Arch | string): Menu {
  return HOME[style as Arch] ?? DEFAULT_HOME;
}

/** One kitchen off a menu by weight (the menu's own key order, so the same roll always gives the same pick). */
function pickFrom(menu: Menu, rng: Rng): FoodKind | null {
  let total = 0;
  for (const k of FOOD_KINDS) total += menu[k] ?? 0;
  if (total <= 0) return null;
  let t = rng() * total;
  for (const k of FOOD_KINDS) {
    t -= menu[k] ?? 0;
    if (t < 0) return k;
  }
  return null;
}

/**
 * The places to eat, the arcades and (in a small city) the bowling alley a town of this size and style
 * gets, in the order to place them. Home kitchens may repeat (a Tokyo has more than one ramen counter),
 * each repeat a third as likely as the last; the world's never do.
 */
export function eateryRoster(style: Arch | string, tier: TownKind, rng: Rng): BuildingKind[] {
  const plan = PLAN[tier];
  const out: BuildingKind[] = [];
  const home: Menu = { ...homeMenu(style) };
  const world: Menu = { ...WORLD };
  if (rng() < plan.odds) {
    const n = plan.n[0] + Math.floor(rng() * (plan.n[1] - plan.n[0] + 1));
    for (let i = 0; i < n; i++) {
      // the first is always the town's own; after that the share decides
      const own = i === 0 || rng() < plan.home;
      const k = own ? pickFrom(home, rng) ?? pickFrom(world, rng) : pickFrom(world, rng) ?? pickFrom(home, rng);
      if (!k) break;
      out.push(k);
      if (home[k] !== undefined) home[k] = home[k]! / 3;
      delete world[k];
    }
  }
  const neon = NEON_TOWNS.has(style) ? 1 : 0;
  const arcades = tier === 'mega' ? 2 : tier === 'metro' ? 1 + (rng() < 0.5 ? 1 : 0) : tier === 'city' ? (rng() < 0.7 ? 1 : 0) : tier === 'suburb' ? (rng() < 0.3 ? 1 : 0) : 0;
  for (let k = arcades + (tier === 'rural' ? 0 : neon); k > 0; k--) out.push('arcade');
  if (tier === 'city' && rng() < 0.5) out.push('bowlingAlley');
  return out;
}
