import * as THREE from 'three';
import { N, STEP, SEA, CHUNK, Biome, Feature, Flag, Lot, Surface, Under, World, DIRS, EDGE_MINE, EDGE_THEIRS, inB, idx, useDiag02, tileMean, minCorner } from '../world/tiles';
import { C, hex, mix, scale, type RGB } from '../world/biomes';
import { hash2 } from '../world/rng';
import { PADDY_REGIONS, cropPatch, fieldPlan, tulipBand } from '../world/crops';
import { REGION_KINDS } from '../world/tiles';
import { NEXT_WORLD } from '../world/nextWorld';
import { REGIONS, regionOf, type PaletteKey } from '../world/regions';
import { brookFalls, brookWater } from './brooks';
import { SEASON_GLSL, WEATHER_GLSL, WEATHER_VERT_GLSL, WORLD_Y_VERT, seasonUniforms } from './season';

const terrainMaterial = new THREE.MeshStandardMaterial({ vertexColors: true, flatShading: true, roughness: 0.95, metalness: 0 });
/**
 * The see-through cut: ground standing between the camera and what it follows, and higher than that, is
 * stippled away, the way RollerCoaster Tycoon let you see a coaster through a hill. A canyon's walls and a
 * ridge behind the car stop hiding it. `uCutR` 0 switches it off.
 */
export const CUTAWAY = {
  uCutA: { value: new THREE.Vector3() },
  uCutB: { value: new THREE.Vector3() },
  uCutR: { value: 0 },
};
/**
 * Grass greens turn through the year, and snow settles on anything high enough. A biome moves the
 * snow line per vertex (aRegion: weight, snow line, kind), and the weather lays a wet sheen and
 * puddles, drifts cloud shadows, shimmers the distance in the heat and lets mist lie in the valleys.
 */
terrainMaterial.onBeforeCompile = (shader) => {
  seasonUniforms(shader);
  Object.assign(shader.uniforms, CUTAWAY);
  shader.vertexShader = shader.vertexShader
    .replace('#include <common>', `#include <common>
attribute vec3 aRegion;
varying float vWorldY;
varying vec3 vWorldP;
varying vec3 vRegion;
${WEATHER_VERT_GLSL}`)
    .replace('#include <begin_vertex>', `#include <begin_vertex>
  vRegion = aRegion;
  vWorldP = (modelMatrix * vec4(transformed, 1.0)).xyz;
  transformed.y += hazeWobble(vWorldP);${WORLD_Y_VERT}`);
  shader.fragmentShader = shader.fragmentShader
    .replace('#include <common>', `#include <common>
varying float vWorldY;
varying vec3 vWorldP;
varying vec3 vRegion;
uniform vec3 uCutA;
uniform vec3 uCutB;
uniform float uCutR;
${SEASON_GLSL}
${WEATHER_GLSL}
/** Snow under a biome: weight 0 is ordinary ground; a line of 99 never snows, -1 snows as normal. */
float regionSnow(float y, vec3 r) {
  float ordinary = snowCover(y);
  if (r.x <= 0.001) return ordinary;
  float own;
  if (r.y > 98.0) own = 0.0;
  else if (r.y < -0.5) own = ordinary;
  else {
    float line = smoothstep(r.y, r.y + 1.2, y);
    if (abs(r.z - 9.0) < 0.5) line *= uWinter;   // the Terraces: the peaks go white in winter only
    own = max(line, uSnow * smoothstep(uSnowLine, uSnowLine + 1.6, y));
  }
  return mix(ordinary, own, clamp(r.x, 0.0, 1.0));
}`)
    .replace('#include <color_fragment>', `#include <color_fragment>
  if (uCutR > 0.0) {
    vec3 ab = uCutB - uCutA;
    float t = clamp(dot(vWorldP - uCutA, ab) / max(dot(ab, ab), 1e-4), 0.0, 1.0);
    float d = length(vWorldP - (uCutA + ab * t));
    // only what stands above the followed point and between it and the eye, in a cone that opens toward the eye
    if (t > 0.015 && vWorldP.y > uCutA.y + 0.9 && d < uCutR * (0.4 + 2.2 * t)) {
      vec2 px = floor(gl_FragCoord.xy);
      if (mod(px.x + px.y, 2.0) < 1.0 || d < uCutR * (0.25 + 1.4 * t)) discard;
    }
  }
  // a biome that never snows never turns either: the tropics and the desert keep their colour
  float wxTropic = vRegion.y > 98.0 ? clamp(vRegion.x, 0.0, 1.0) : 0.0;
  diffuseColor.rgb = mix(turnSeason(diffuseColor.rgb, 1.0), diffuseColor.rgb, wxTropic);
  // the Golden Hills turn the other way: gold through the dry summer and autumn, green in the winter rains
  if (abs(vRegion.z - ${REGION_KINDS.indexOf('goldhills') + 1}.0) < 0.5) {
    vec3 c0 = diffuseColor.rgb;
    float gold = clamp((c0.r - c0.b) * 3.0, 0.0, 1.0) * step(c0.b, c0.g);
    float wet = clamp(vRegion.x, 0.0, 1.0) * gold * (uWinter * 0.85 + uSpring * 0.95);
    diffuseColor.rgb = mix(c0, vec3(0.45, 0.66, 0.30) * (0.75 + 0.5 * dot(c0, vec3(0.333))), wet);
  }
  float wxSnow = regionSnow(vWorldY, vRegion);
  diffuseColor.rgb = mix(diffuseColor.rgb, vec3(0.94, 0.96, 0.99), wxSnow * 0.92);
  // alpenglow: at dusk and dawn the high peaks go rose, the higher the more
  if (uAlpen > 0.01) diffuseColor.rgb = mix(diffuseColor.rgb, diffuseColor.rgb * vec3(1.25, 0.82, 0.8) + vec3(0.12, 0.02, 0.05), uAlpen * smoothstep(26.0, 36.0, vWorldY) * 0.55);
  // rain darkens the ground and pools on the flat tiles
  float wxWet = uWet * (1.0 - wxSnow);
  float wxPuddle = 0.0;
  if (wxWet > 0.001) {
    float wxFlat = abs(normalize(cross(dFdx(vWorldP), dFdy(vWorldP))).y);
    wxPuddle = wxWet * smoothstep(0.55, 1.0, uWet) * smoothstep(0.97, 0.995, wxFlat)
      * smoothstep(0.66, 0.7, wxNoise(vWorldP.xz * 1.1) * 0.75 + wxNoise(vWorldP.xz * 3.1) * 0.25);
    diffuseColor.rgb *= 1.0 - 0.22 * wxWet;
    diffuseColor.rgb = mix(diffuseColor.rgb, uSkyCol * 0.85, wxPuddle * 0.55);
  }
  diffuseColor.rgb *= cloudShade(vWorldP.xz);`)
    .replace('#include <roughnessmap_fragment>', `#include <roughnessmap_fragment>
  roughnessFactor = mix(roughnessFactor, 0.45, wxWet);
  roughnessFactor = mix(roughnessFactor, 0.06, wxPuddle);`)
    .replace('#include <fog_fragment>', `gl_FragColor.rgb = weatherAir(gl_FragColor.rgb, vWorldP);
  #include <fog_fragment>`);
};

/**
 * The lakes and rivers draw first of everything see-through: before the markings that read through faded
 * buildings (render/drape.ts SEEN_THROUGH), so a ring on the water lies over it rather than under it.
 */
const WATER_ORDER = -20;

const waterMaterial = new THREE.MeshStandardMaterial({
  vertexColors: true, flatShading: true, transparent: true, opacity: 0.8, roughness: 0.3, metalness: 0, depthWrite: false,
});
/**
 * A window in the water round a dived submarine (docs/underwater.html): x, z and radius in world tiles, and how
 * open it is (0 shut, 1 open). The water thins there so the sub, the seabed and the rings on it can be seen.
 * Always in the shader, only its values change, so diving never recompiles it.
 */
const SUB_WINDOW = { value: new THREE.Vector4(0, 0, 1, 0) };
export function setWaterWindow(x: number, z: number, r: number, open: number): void {
  SUB_WINDOW.value.set(x, z, Math.max(0.5, r), Math.max(0, Math.min(1, open)));
}
/** In deep winter the shallows skin over with ice; the deep stays open water. The Icefield's never thaw. */
waterMaterial.onBeforeCompile = (shader) => {
  seasonUniforms(shader);
  shader.uniforms.uSub = SUB_WINDOW;
  shader.vertexShader = shader.vertexShader
    .replace('#include <common>', `#include <common>
attribute float aShallow;
attribute vec3 aRegion;
varying float vShallow;
varying vec3 vRegion;
varying vec3 vWorldP;`)
    .replace('#include <begin_vertex>', `#include <begin_vertex>
  vShallow = aShallow;
  vRegion = aRegion;
  vWorldP = (modelMatrix * vec4(transformed, 1.0)).xyz;`);
  shader.fragmentShader = shader.fragmentShader
    .replace('#include <common>', `#include <common>
uniform float uFreeze;
uniform vec4 uSub;
varying float vShallow;
varying vec3 vRegion;
varying vec3 vWorldP;
${WEATHER_GLSL}`)
    .replace('#include <color_fragment>', `#include <color_fragment>
  float polar = abs(vRegion.z - 2.0) < 0.5 ? clamp(vRegion.x, 0.0, 1.0) : 0.0;
  float ice = clamp(max(uFreeze, polar) * vShallow, 0.0, 1.0);
  diffuseColor.rgb = mix(diffuseColor.rgb, vec3(0.83, 0.90, 0.94), ice * 0.9);
  diffuseColor.a = mix(diffuseColor.a, 0.98, ice);
  float subWin = uSub.w * (1.0 - smoothstep(uSub.z * 0.5, uSub.z, distance(vWorldP.xz, uSub.xy)));
  diffuseColor.a = mix(diffuseColor.a, 0.3, subWin);
  diffuseColor.rgb *= cloudShade(vWorldP.xz);`)
    .replace('#include <fog_fragment>', `gl_FragColor.rgb = weatherAir(gl_FragColor.rgb, vWorldP);
  #include <fog_fragment>`);
};

class Builder {
  pos: number[] = [];
  col: number[] = [];
  /** Optional per-vertex channel; the water uses it to say how shallow it is. */
  extra: number[] = [];
  /** The biome under what is drawn next, for the shaders: weight, snow line, kind (see aRegion). */
  reg: number[] = [];
  private r0 = 0; private r1 = -1; private r2 = 0;
  /** No biome under what is drawn next: plain ground for the shaders. */
  plain(): void { this.r0 = 0; this.r1 = -1; this.r2 = 0; }
  region(w: World, i: number): void {
    const k = w.regionK[i];
    const spec = k ? regionOf(k) : null;
    this.r0 = k ? w.regionW[i] / 255 : 0;
    this.r1 = !spec || spec.snowLine === undefined ? -1 : spec.snowLine === null ? 99 : spec.snowLine;
    this.r2 = k;
    // high country keeps its own snow line, higher than the ordinary one: a tableland is not white
    const hi = w.snowLine[i];
    if (hi > 0 && this.r1 < 98) {
      const line = hi * STEP;
      this.r1 = this.r1 < 0 ? line : Math.max(this.r1, line);
      this.r0 = 1;
    }
  }
  tri(ax: number, ay: number, az: number, bx: number, by: number, bz: number, cx: number, cy: number, cz: number, ca: RGB, cb: RGB, cc: RGB, e = -1): void {
    this.pos.push(ax, ay, az, bx, by, bz, cx, cy, cz);
    this.col.push(ca[0], ca[1], ca[2], cb[0], cb[1], cb[2], cc[0], cc[1], cc[2]);
    if (e >= 0) this.extra.push(e, e, e);
    this.reg.push(this.r0, this.r1, this.r2, this.r0, this.r1, this.r2, this.r0, this.r1, this.r2);
  }
  build(name = ''): THREE.BufferGeometry | null {
    if (this.pos.length === 0) return null;
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute(this.pos, 3));
    g.setAttribute('color', new THREE.Float32BufferAttribute(this.col, 3));
    if (name && this.extra.length === this.pos.length / 3) g.setAttribute(name, new THREE.Float32BufferAttribute(this.extra, 1));
    g.setAttribute('aRegion', new THREE.Float32BufferAttribute(this.reg, 3));
    g.computeVertexNormals();
    g.computeBoundingSphere();
    return g;
  }
}

function cornerXZ(k: number, tx: number, tz: number): [number, number] {
  return [tx + (k === 1 || k === 2 ? 1 : 0), tz + (k === 2 || k === 3 ? 1 : 0)];
}

// ---------------- a biome's palette ----------------

/** Which palette key each ordinary colour is, by identity: a tile's colour is one of these arrays until it is mixed. */
const KEY_OF = new Map<RGB, PaletteKey>(
  (Object.keys(C) as (keyof typeof C)[]).filter((k) => !Array.isArray(C[k][0])).map((k) => [C[k] as RGB, k as PaletteKey]),
);
/** Each biome's palette as RGB, looked up once. */
const REGION_RGB = REGION_KINDS.map((k) => {
  const p = REGIONS[k].palette, out = new Map<PaletteKey, RGB>();
  for (const key of Object.keys(p) as PaletteKey[]) out.set(key, hex(p[key]!));
  return { pal: out, crops: REGIONS[k].crops?.map(hex) ?? null, paddy: PADDY_REGIONS.has(k) };
});
const PADDY = hex(0x9ccfd8), PADDY_BUND = hex(0x7a8a5a);
/** A bulb field's bands from afar (world/crops.ts TULIP_KINDS order), and a corn maze's trodden paths. */
const PALM_FLOOR = hex(0x557a3c), PALM_TRACK = hex(0x8a7650);
const TULIP_GROUND = [0xd8463c, 0xf0d040, 0xee8cb8, 0xf2efe4, 0x8a52c0].map(hex), MAZE_PATH = hex(0xc4a46e);

/** A colour pulled toward what the biome under the tile paints it, by how far into the biome it is. */
function tint(w: World, i: number, col: RGB, key?: PaletteKey): RGB {
  const k = w.regionK[i];
  if (!k || !w.regionW[i]) return col;
  const alt = REGION_RGB[k - 1].pal.get(key ?? KEY_OF.get(col)!);
  return alt ? mix(col, alt, w.regionW[i] / 255) : col;
}

/** Top-surface colour for a tile. */
function tileColor(w: World, i: number): RGB {
  const x = i % N, z = (i - x) / N;
  const b = w.biome[i];
  const jitter = 1 + (hash2(x, z, 1) - 0.5) * 0.09;
  let col: RGB;
  if (w.water[i] >= 0) {
    if (b === Biome.Lagoon) col = C.lagoonBed;
    else if (b === Biome.Mangrove || b === Biome.Marsh) col = C.marshPool;
    else if (b === Biome.Lava) col = C.lava;
    else if (b === Biome.Ocean || b === Biome.Beach || b === Biome.SeaCliff) col = C.bedSand;
    else if (b === Biome.Canyon || b === Biome.Desert) col = C.bedCanyon;
    else col = C.bedMud;
    return scale(tint(w, i, col), jitter);
  }
  // a working quarry face and a groomed piste read as their own ground, whatever grew there before
  if (w.feature[i] === Feature.Quarry) {
    const bench = Math.floor(Math.abs(tileMean(w, i))) % 4 < 2 ? C.quarry : C.quarryCut;
    return scale(bench, jitter);
  }
  if (w.feature[i] === Feature.Piste) return scale(C.piste, jitter * 0.99 + 0.005);
  // ground a landform owns reads as that ground, whatever biome it sits in
  const surf = w.surface[i];
  if (surf === Surface.Rock && (b === Biome.Canyon || b === Biome.Desert || b === Biome.Hills)) {
    // badland bands: the colour cycles with the level, so every terrace is a stripe
    return scale(C.badBands[((Math.round(tileMean(w, i)) % 4) + 4) % 4], jitter);
  }
  if (surf === Surface.Basalt) return scale(C.basalt, jitter * (1 - 0.06 * w.coastDist[i]));
  if (surf === Surface.Cave) return scale(C.cave, jitter);
  if (surf === Surface.Sand && b === Biome.Desert) {
    // dune crests catch the light, the hollows between them do not
    const up = (w.corners[i * 4 + 1] + w.corners[i * 4 + 2]) - (w.corners[i * 4] + w.corners[i * 4 + 3]);
    return scale(tint(w, i, up >= 0 ? C.dune : C.duneShade), jitter);
  }
  switch (b) {
    case Biome.Plains: col = C.plains; break;
    case Biome.Hills: col = C.hills; break;
    case Biome.Forest: col = C.forest; break;
    case Biome.Beach: col = C.beach; break;
    case Biome.SeaCliff: col = C.cliffTop; break;
    case Biome.Desert: col = C.desert; break;
    case Biome.Canyon: col = C.canyon; break;
    case Biome.Mountain: {
      const t = Math.min(1, Math.max(0, (tileMean(w, i) - 9) / 10));
      col = mix(tint(w, i, C.mountainLow), tint(w, i, C.mountainHigh), t);
      break;
    }
    case Biome.Snow: col = C.snow; break;
    case Biome.Lava: {
      // cooled black rock, warmer brown near the vents
      col = hash2(x, z, 5) < 0.18 ? C.lavaWarm : C.lava;
      break;
    }
    case Biome.Salt: {
      // a salt pan cracks into polygons: a hash of which cell of a coarse grid the tile falls in
      const cell = hash2(Math.floor((x + hash2(z, 3, 9) * 4) / 5), Math.floor((z + hash2(x, 4, 9) * 4) / 5), 17);
      col = cell < 0.5 ? C.salt : mix(C.salt, C.saltCrack, 0.5);
      if (hash2(x, z, 18) < 0.08) col = C.saltCrack;
      break;
    }
    case Biome.Ice: col = ((x * 3 + z * 5) % 13 === 0) ? C.crevasse : C.ice; break;
    case Biome.Marsh: col = hash2(x, z, 6) < 0.25 ? C.marshPool : C.marsh; break;
    case Biome.Mangrove: col = C.mangrove; break;
    case Biome.Lagoon: col = C.lagoonBed; break;
    case Biome.Town:
      switch (w.lot[i]) {
        case Lot.Lawn: col = C.lawn; break;
        case Lot.Paved: col = C.paved; break;
        case Lot.Park: col = C.park; break;
        case Lot.Pitch: col = x & 1 ? C.pitch : C.pitchStripe; break;
        case Lot.Yard: col = C.yard; break;
        case Lot.Asphalt: col = C.asphalt; break;
        case Lot.Plaza: col = C.plaza; break;
        case Lot.Deck: col = ((x + z) & 1) ? C.deck : scale(C.deck, 0.94); break;
        case Lot.Runway: col = C.runway; break;
        case Lot.Apron: col = C.apron; break;
        case Lot.Gravel: col = C.gravel; break;
        case Lot.Piste: col = C.piste; break;
        case Lot.Sand: col = C.beach; break;
        case Lot.Waste: col = hash2(x, z, 41) < 0.3 ? mix(C.lawn, C.yard, 0.75) : mix(C.lawn, C.yard, 0.45); break;
        // a flooded rice terrace: sky in the water, a darker bund every few tiles
        case Lot.Paddy: col = (x % 3 === 0 || z % 3 === 0) ? PADDY_BUND : PADDY; break;
        default: col = C.plains;
      }
      break;
    case Biome.Farm: {
      const fid = w.fieldId[i];
      const patch = cropPatch(x, z, fid, C.crops.length);
      col = C.crops[patch];
      const rk = w.regionK[i];
      // 0.7.0: a whole field of one crop (world/crops.ts fieldPlan)
      const plan = NEXT_WORLD && !(rk && w.regionW[i] > 128) ? fieldPlan(w, fid) : null;
      if (plan && plan.theme !== 'mixed') {
        if (plan.theme === 'maize') col = C.crops[1];
        else if (plan.theme === 'pumpkin') col = C.crops[3];
        else if (plan.theme === 'tulips') col = mix(C.crops[1], TULIP_GROUND[tulipBand(w, x, z)], 0.8);
        else if (plan.theme === 'rice') col = (x % 4 === 0 || z % 4 === 0) ? PADDY_BUND : PADDY;
        // an oil palm plantation's shaded floor, a worn track every few rows
        else if (plan.theme === 'oilPalm') col = (x + z) % 5 === 0 ? PALM_TRACK : PALM_FLOOR;
        else col = plan.paths!.has(i) ? MAZE_PATH : C.crops[1];
      } else if (rk && w.regionW[i] > 128) {
        const r = REGION_RGB[rk - 1];
        // paddies in the wet east and the bayou; the biome's own crops everywhere else
        if (r.paddy) col = (x % 4 === 0 || z % 4 === 0) ? PADDY_BUND : PADDY;
        else if (r.crops) col = r.crops[patch % r.crops.length];
      }
      const stripe = ((x + z) & 1) === 0 ? 1.0 : 0.93;
      col = scale(col, stripe);
      break;
    }
    default: col = C.plains;
  }
  if (b !== Biome.Mountain && b !== Biome.Farm) col = tint(w, i, col);
  // black sand on the beaches under a volcano
  if (b === Biome.Beach && w.landmarks.length) {
    for (const l of w.landmarks) if (l.kind === 'volcano' && Math.hypot(x - l.x, z - l.z) < l.r + 40) { col = C.blackSand; break; }
  }
  if (w.flags[i] & Flag.Track) col = mix(col, tint(w, i, C.track), 0.7);
  return scale(col, jitter);
}

function cliffColours(w: World, i: number): [RGB, RGB] {
  const b = w.biome[i];
  // town pads and quays show retaining walls; wooden piers show planks
  if (b === Biome.Town) return w.lot[i] === Lot.Deck ? [C.deckTop, C.deckBot] : [C.quayTop, C.quayBot];
  // a quarry face is freshly cut rock, whatever the hillside around it is made of
  if (w.feature[i] === Feature.Quarry) return [C.cliffGreyTop, C.cliffGreyBot];
  if (b === Biome.Lava || w.surface[i] === Surface.Basalt) return [C.cliffLavaTop, C.cliffLavaBot];
  if (b === Biome.Ice) return [C.cliffIceTop, C.cliffIceBot];
  if (w.surface[i] === Surface.Rock && (b === Biome.Canyon || b === Biome.Desert)) {
    const band = C.badBands[((Math.round(tileMean(w, i)) % 4) + 4) % 4];
    return [band, scale(band, 0.62)];
  }
  if (b === Biome.Canyon || b === Biome.Desert) return [C.cliffRedTop, C.cliffRedBot];
  if (b === Biome.Mountain || b === Biome.Snow) return [C.cliffGreyTop, C.cliffGreyBot];
  if (b === Biome.SeaCliff || b === Biome.Beach || (w.coastDist[i] <= 8 && b !== Biome.Forest)) return [C.cliffPaleTop, C.cliffPaleBot];
  return [C.cliffEarthTop, C.cliffEarthBot];
}

/**
 * A village perched up in big country (a bench, a pass, a summit, a canyon's rim, a mesa: docs/geology.html) stands
 * on a pad whose edges are walls; from 0.7.0 they are drawn as coursed stone retaining walls, a course a step.
 */
const STONE_A = hex(0xb3a58f), STONE_B = hex(0x9c8f7b), STONE_CAP = hex(0xd4cbb8);
function stonePad(w: World, i: number): boolean {
  if (!NEXT_WORLD || w.biome[i] !== Biome.Town || w.lot[i] === Lot.Deck) return false;
  const t = w.townId[i];
  const town = w.towns[t]?.id === t ? w.towns[t] : w.towns.find((q) => q.id === t);
  return t >= 0 && !!town?.perch;
}

function waterColour(w: World, i: number, depth: number): RGB {
  if (depth <= 1) return tint(w, i, C.waterShallow);
  if (depth === 2) return tint(w, i, C.waterMid);
  return tint(w, i, C.waterDeep);
}

interface ChunkMeshes { terrain: THREE.Mesh; water: THREE.Mesh | null }

export function buildChunk(w: World, cx: number, cz: number): ChunkMeshes {
  const tb = new Builder();
  const wb = new Builder();
  const c = w.corners;
  for (let tz = cz * CHUNK; tz < (cz + 1) * CHUNK; tz++) {
    for (let tx = cx * CHUNK; tx < (cx + 1) * CHUNK; tx++) {
      const i = idx(tx, tz);
      const b = i * 4;
      const c0 = c[b], c1 = c[b + 1], c2 = c[b + 2], c3 = c[b + 3];
      const col = tileColor(w, i);
      tb.region(w, i);
      wb.region(w, i);
      const y0 = c0 * STEP, y1 = c1 * STEP, y2 = c2 * STEP, y3 = c3 * STEP;
      const x0 = tx, x1 = tx + 1, z0 = tz, z1 = tz + 1;
      // slight lightening of the second triangle so folds read even under flat light
      const col2 = scale(col, 0.97);
      if (useDiag02(c0, c1, c2, c3)) {
        tb.tri(x0, y0, z0, x1, y2, z1, x1, y1, z0, col, col, col);
        tb.tri(x0, y0, z0, x0, y3, z1, x1, y2, z1, col2, col2, col2);
      } else {
        tb.tri(x0, y0, z0, x0, y3, z1, x1, y1, z0, col, col, col);
        tb.tri(x1, y1, z0, x0, y3, z1, x1, y2, z1, col2, col2, col2);
      }

      // cliff faces toward lower neighbours
      for (let d = 0; d < 4; d++) {
        const nx = tx + DIRS[d][0], nz = tz + DIRS[d][1];
        if (!inB(nx, nz)) continue;
        const j = idx(nx, nz);
        const m = EDGE_MINE[d], t = EDGE_THEIRS[d];
        const ha = c[b + m[0]], hb = c[b + m[1]];
        const na = c[j * 4 + t[0]], nb = c[j * 4 + t[1]];
        if (ha <= na && hb <= nb) continue;
        const [ax, az] = cornerXZ(m[0], tx, tz);
        const [bx, bz] = cornerXZ(m[1], tx, tz);
        const topA = ha * STEP, topB = hb * STEP;
        const botA = Math.min(ha, na) * STEP, botB = Math.min(hb, nb) * STEP;
        const [ct0, cb0] = cliffColours(w, i);
        const ct = tint(w, i, ct0), cb = tint(w, i, cb0);
        const drop = Math.max(ha - na, hb - nb);
        const cbot = mix(ct, cb, Math.min(1, drop / 4));
        // Winding: triangle (A_top, B_top, B_bot) has normal along (uz, 0, -ux) where (ux, uz) runs
        // along the edge from A to B. Flip when that points away from the neighbour (DIRS[d]).
        const ox = DIRS[d][0], oz = DIRS[d][1];
        const ux = bx - ax, uz = bz - az;
        const flip = uz * ox - ux * oz < 0;
        // a perched village's level pad: its wall laid in stone courses, a step each, under a paler cap (0.7.0)
        if (ha === hb && na === nb && stonePad(w, i)) {
          for (let lv = na; lv < ha; lv++) {
            const y0 = lv * STEP, y1 = (lv + 1) * STEP;
            const col = tint(w, i, lv === ha - 1 ? STONE_CAP : (lv + tx + tz) & 1 ? STONE_A : STONE_B);
            if (!flip) {
              tb.tri(ax, y1, az, bx, y1, bz, bx, y0, bz, col, col, col);
              tb.tri(ax, y1, az, bx, y0, bz, ax, y0, az, col, col, col);
            } else {
              tb.tri(ax, y1, az, bx, y0, bz, bx, y1, bz, col, col, col);
              tb.tri(ax, y1, az, ax, y0, az, bx, y0, bz, col, col, col);
            }
          }
          continue;
        }
        if (!flip) {
          tb.tri(ax, topA, az, bx, topB, bz, bx, botB, bz, ct, ct, cbot);
          tb.tri(ax, topA, az, bx, botB, bz, ax, botA, az, ct, cbot, cbot);
        } else {
          tb.tri(ax, topA, az, bx, botB, bz, bx, topB, bz, ct, cbot, ct);
          tb.tri(ax, topA, az, ax, botA, az, bx, botB, bz, ct, cbot, cbot);
        }
      }

      // water surface
      const wl = w.water[i];
      if (wl >= 0) {
        const depth = wl - minCorner(w, i);
        const lagoon = w.biome[i] === Biome.Lagoon;
        const wc = lagoon ? (depth <= 2 ? C.lagoonShallow : C.lagoonDeep) : w.biome[i] === Biome.Mangrove ? mix(C.waterShallow, C.marsh, 0.35) : waterColour(w, i, depth);
        const wy = wl * STEP - 0.035;
        // how readily this freezes: a puddle skins over, the deep never does, and a lagoon never
        const shallow = lagoon ? 0 : depth <= 1 ? 1 : depth === 2 ? 0.55 : 0;
        wb.tri(x0, wy, z0, x1, wy, z1, x1, wy, z0, wc, wc, wc, shallow);
        wb.tri(x0, wy, z0, x0, wy, z1, x1, wy, z1, wc, wc, wc, shallow);
      }
    }
  }
  // the brooks' thin ribbons share the chunk's water (render/brooks.ts)
  brookWater(wb, w, cx, cz);
  const tg = tb.build()!;
  const terrain = new THREE.Mesh(tg, terrainMaterial);
  terrain.receiveShadow = true;
  // ground with no more than a step of rise in it throws no shadow worth drawing: a shadow draw saved a
  // flat chunk (the lag audit, Oct 2026). A neighbour's hill still shades it; it just shades nothing back
  let lo = Infinity, hi = -Infinity;
  for (let tz = cz * CHUNK; tz < (cz + 1) * CHUNK; tz++) {
    for (let tx = cx * CHUNK; tx < (cx + 1) * CHUNK; tx++) {
      const b = idx(tx, tz) * 4;
      for (let k = 0; k < 4; k++) { const h = c[b + k]; if (h < lo) lo = h; if (h > hi) hi = h; }
    }
  }
  terrain.castShadow = hi - lo > 1;
  let water: THREE.Mesh | null = null;
  const wg = wb.build('aShallow');
  if (wg) {
    water = new THREE.Mesh(wg, waterMaterial);
    water.receiveShadow = true;
    water.renderOrder = WATER_ORDER;
  }
  return { terrain, water };
}

/** A huge plane at sea level, kept under the camera, so the world floats in endless ocean. */
export function buildOceanPlane(): THREE.Mesh {
  const g = new THREE.PlaneGeometry(9000, 9000);
  g.rotateX(-Math.PI / 2);
  const m = new THREE.MeshStandardMaterial({
    color: new THREE.Color(...hex(0x3a86c2)), roughness: 0.35, metalness: 0,
    polygonOffset: true, polygonOffsetFactor: 2, polygonOffsetUnits: 4,   // never win a depth tie
  });
  // it is opaque, just under the water's surface: round a dived submarine it opens with the water's own window
  // (setWaterWindow), or the sub and the seabed under it could never be seen (docs/underwater.html)
  m.onBeforeCompile = (shader) => {
    shader.uniforms.uSub = SUB_WINDOW;
    shader.vertexShader = shader.vertexShader
      .replace('#include <common>', `#include <common>
varying vec3 vOceanP;`)
      .replace('#include <begin_vertex>', `#include <begin_vertex>
  vOceanP = (modelMatrix * vec4(transformed, 1.0)).xyz;`);
    shader.fragmentShader = shader.fragmentShader
      .replace('#include <common>', `#include <common>
uniform vec4 uSub;
varying vec3 vOceanP;`)
      .replace('void main() {', `void main() {
  if (uSub.w > 0.2 && distance(vOceanP.xz, uSub.xy) < uSub.z) discard;`);
  };
  const mesh = new THREE.Mesh(g, m);
  mesh.position.set(0, SEA * STEP - 0.06, 0);
  mesh.receiveShadow = true;
  return mesh;
}

/** Tiles per side of one low-detail quad. */
const LOD = 4;

/**
 * A coarse mesh for one square of an island: 4x4 tiles per quad, coloured by whatever is mostly
 * there. It stands in for the detailed chunks wherever they are not loaded, which is what fills the
 * middle distance, the horizon and the island overview. Hidden again once its chunks arrive.
 */
export function buildIslandLod(w: World, tx0: number, tz0: number, tx1: number, tz1: number): THREE.Mesh | null {
  const b = new Builder();
  const c = w.corners;
  const drop = 0.06;
  // laid a chunk at a time, each chunk's triangles one run of vertices, so the stream can leave out the
  // runs of chunks whose detail is drawn (lodShowChunks): sunk as it is, a coarse quad still stands over
  // a road in a cutting or a gorge between its corners, and drawn over loaded ground it hid the road
  // under a slab the car drove straight through (the user, 7 Oct 2026)
  const runs: number[] = [];
  for (let cz0 = tz0; cz0 < tz1; cz0 += CHUNK) for (let cx0 = tx0; cx0 < tx1; cx0 += CHUNK) {
  const start = b.pos.length / 3;
  for (let z0 = cz0; z0 < cz0 + CHUNK; z0 += LOD) {
    for (let x0 = cx0; x0 < cx0 + CHUNK; x0 += LOD) {
      let wet = 0, sum = 0, best = -1, bestI = -1;
      let lo = 127, hi = -128;
      const tally = new Map<number, number>();
      for (let z = z0; z < z0 + LOD; z++) {
        for (let x = x0; x < x0 + LOD; x++) {
          const i = idx(x, z);
          sum += tileMean(w, i);
          for (let q = 0; q < 4; q++) {
            const v = c[i * 4 + q];
            if (v < lo) lo = v;
            if (v > hi) hi = v;
          }
          if (w.water[i] >= 0) wet++;
          const key = w.biome[i] * 16 + w.lot[i];
          const n = (tally.get(key) ?? 0) + 1;
          tally.set(key, n);
          if (n > best) { best = n; bestI = i; }
        }
      }
      const mean = sum / (LOD * LOD);
      const wetShare = wet / (LOD * LOD);
      // Anything mostly under the sea is left to the ocean plane. Two flat surfaces a few
      // hundredths apart cannot be told apart by the depth buffer at this range, and the pair of
      // them flickering against each other is what made every shoreline shimmer.
      const level = w.water[idx(x0 + Math.floor(LOD / 2), z0 + Math.floor(LOD / 2))];
      if (wetShare > 0.5 && (level === SEA || level < 0)) continue;
      // a mostly-wet block is drawn as its water surface; the rest as its commonest ground
      let y: number, col: RGB;
      if (wetShare > 0.5) {
        const i = idx(x0 + 1, z0 + 1);
        y = (w.water[i] >= 0 ? w.water[i] : SEA) * STEP - 0.035;
        col = tileColor(w, i);
      } else {
        y = mean * STEP;
        col = tileColor(w, bestI);
      }
      // corner heights from the block corners of the real grid, so neighbouring blocks meet
      const h = (gx: number, gz: number) => {
        const tx = Math.min(N - 1, gx), tz = Math.min(N - 1, gz);
        const q = gx >= N ? (gz >= N ? 2 : 1) : gz >= N ? 3 : 0;
        return c[idx(tx, tz) * 4 + q] * STEP;
      };
      const y00 = wetShare > 0.5 ? y : h(x0, z0), y10 = wetShare > 0.5 ? y : h(x0 + LOD, z0);
      const y11 = wetShare > 0.5 ? y : h(x0 + LOD, z0 + LOD), y01 = wetShare > 0.5 ? y : h(x0, z0 + LOD);
      // Sink the block far enough that no part of it can poke through the detailed chunks drawn
      // over it: the quad runs between its corner heights, so dropping it by the block's own relief
      // puts it at or under the real ground everywhere inside it. Without this the two surfaces
      // fight, which showed as a shimmering shoreline wherever the ground was uneven.
      // sink by the block's own relief so it stays under the detailed chunks, but never so far
      // that coastal ground disappears beneath the sea
      const sink = wetShare > 0.5 ? drop : drop + Math.min((hi - lo) * STEP, 0.3);
      b.region(w, bestI >= 0 ? bestI : idx(x0, z0));
      const X0 = x0, X1 = x0 + LOD, Z0 = z0, Z1 = z0 + LOD;
      b.tri(X0, y00 - sink, Z0, X1, y11 - sink, Z1, X1, y10 - sink, Z0, col, col, col);
      b.tri(X0, y00 - sink, Z0, X0, y01 - sink, Z1, X1, y11 - sink, Z1, col, col, col);
    }
  }
  runs.push(start, b.pos.length / 3 - start);
  }
  const g = b.build();
  if (!g) return null;
  // an array of one material, so the geometry's groups decide what is drawn
  const mesh = new THREE.Mesh(g, [terrainMaterial]);
  mesh.userData.chunkRuns = runs;
  g.addGroup(0, b.pos.length / 3, 0);
  mesh.receiveShadow = false;
  mesh.castShadow = false;
  return mesh;
}

/**
 * Draw only the chunks of a coarse block (buildIslandLod) whose detail is not in, `shown(k)` for its k-th
 * chunk in row order. Neighbouring shown chunks are drawn as one run; a block with none left is hidden.
 */
export function lodShowChunks(mesh: THREE.Mesh, shown: (k: number) => boolean): void {
  const runs = mesh.userData.chunkRuns as number[] | undefined;
  if (!runs) return;
  const g = mesh.geometry;
  g.clearGroups();
  let start = -1, end = -1;
  for (let k = 0; k * 2 < runs.length; k++) {
    const s = runs[k * 2], n = runs[k * 2 + 1];
    if (!n || !shown(k)) continue;
    if (s === end) { end = s + n; continue; }
    if (start >= 0) g.addGroup(start, end - start, 0);
    start = s;
    end = s + n;
  }
  if (start >= 0) g.addGroup(start, end - start, 0);
  mesh.visible = g.groups.length > 0;
}

/**
 * The distant railway over one chunk, as a mesh of its own. It is kept apart from the block because
 * a block stays drawn until every one of its chunks has loaded, and a ribbon riding over the rails
 * would paint out the real track of the chunks that already have. The stream hides each chunk's
 * ribbon as soon as that chunk's detail is in.
 */
export function buildLodRails(w: World, tx0: number, tz0: number, tx1: number, tz1: number): THREE.Mesh | null {
  const b = new Builder();
  lodRails(b, w, tx0, tz0, tx1, tz1);
  const g = b.build();
  if (!g) return null;
  const mesh = new THREE.Mesh(g, terrainMaterial);
  mesh.receiveShadow = false;
  mesh.castShadow = false;
  return mesh;
}

const LOD_BALLAST: RGB = hex(0x6f675e);

/**
 * The railway at a distance: a flat 0.7-wide ribbon of ballast colour a hair over the rails, a tile
 * at a time, for every stretch of track whose midpoint lies in the given tiles. Tunnels are left out.
 */
/** Tiles a side of the squares lodRails files the track's stretches under. */
const RAIL_CELL = 16;
/**
 * Every stretch of a cell's track, filed by the square its midpoint is in, worked out once: a cell's
 * ribbons are built a chunk at a time, and each chunk used to walk every point of every line (256 walks
 * a cell on arrival).
 */
const railFiles = new WeakMap<World, { rails: World['rails']; n: number; at: Map<number, [number, number][]> }>();
function railStretches(w: World): Map<number, [number, number][]> {
  const had = railFiles.get(w);
  if (had && had.rails === w.rails && had.n === w.rails.length) return had.at;
  const at = new Map<number, [number, number][]>();
  w.rails.forEach((p, k) => {
    const n = p.s.length;
    for (let i = 0; i + 1 < n; i += RAIL_STRIDE) {
      const j = Math.min(n - 1, i + RAIL_STRIDE);
      const mx = (p.xz[i * 2] + p.xz[j * 2]) / 2, mz = (p.xz[i * 2 + 1] + p.xz[j * 2 + 1]) / 2;
      const key = Math.floor(mz / RAIL_CELL) * 1024 + Math.floor(mx / RAIL_CELL);
      let list = at.get(key);
      if (!list) at.set(key, (list = []));
      list.push([k, i]);
    }
  });
  railFiles.set(w, { rails: w.rails, n: w.rails.length, at });
  return at;
}
const RAIL_STRIDE = 4;

function lodRails(b: Builder, w: World, tx0: number, tz0: number, tx1: number, tz1: number): void {
  if (!w.rails.length) return;
  b.plain();
  const H = 0.35, STRIDE = RAIL_STRIDE;
  const files = railStretches(w);
  for (let cz = Math.floor(tz0 / RAIL_CELL); cz <= Math.floor((tz1 - 1e-6) / RAIL_CELL); cz++) for (let cx = Math.floor(tx0 / RAIL_CELL); cx <= Math.floor((tx1 - 1e-6) / RAIL_CELL); cx++) for (const [k, i] of files.get(cz * 1024 + cx) ?? []) {
    const p = w.rails[k];
    const n = p.s.length;
    {
      const j = Math.min(n - 1, i + STRIDE);
      const mx = (p.xz[i * 2] + p.xz[j * 2]) / 2, mz = (p.xz[i * 2 + 1] + p.xz[j * 2 + 1]) / 2;
      if (mx < tx0 || mx >= tx1 || mz < tz0 || mz >= tz1) continue;
      if (p.under[i] === Under.Tunnel && p.under[j] === Under.Tunnel) continue;
      const nrm = (k: number) => {
        const a = Math.max(0, k - 1), c = Math.min(n - 1, k + 1);
        const dx = p.xz[c * 2] - p.xz[a * 2], dz = p.xz[c * 2 + 1] - p.xz[a * 2 + 1];
        const l = Math.hypot(dx, dz) || 1;
        return [-dz / l * H, dx / l * H];
      };
      const [nax, naz] = nrm(i), [nbx, nbz] = nrm(j);
      const ax = p.xz[i * 2], az = p.xz[i * 2 + 1], bx = p.xz[j * 2], bz = p.xz[j * 2 + 1];
      const ya = p.y[i] + 0.05, yb = p.y[j] + 0.05;
      const c = LOD_BALLAST;
      // wound to face up: (a+n, b+n, b-n) and (a+n, b-n, a-n)
      const up = (x0: number, y0: number, z0: number, x1: number, y1: number, z1: number, x2: number, y2: number, z2: number) => {
        const ny = (z1 - z0) * (x2 - x0) - (x1 - x0) * (z2 - z0);
        if (ny >= 0) b.tri(x0, y0, z0, x1, y1, z1, x2, y2, z2, c, c, c);
        else b.tri(x0, y0, z0, x2, y2, z2, x1, y1, z1, c, c, c);
      };
      up(ax + nax, ya, az + naz, bx + nbx, yb, bz + nbz, bx - nbx, yb, bz - nbz);
      up(ax + nax, ya, az + naz, bx - nbx, yb, bz - nbz, ax - nax, ya, az - naz);
    }
  }
}

/** Water tumbling over a step: a sheet down the face and a plume of foam where it lands. */
const fallMaterial = new THREE.MeshStandardMaterial({
  vertexColors: true, flatShading: true, transparent: true, opacity: 0.86, roughness: 0.22, metalness: 0,
  side: THREE.DoubleSide, depthWrite: false,
});
fallMaterial.onBeforeCompile = (shader) => {
  seasonUniforms(shader);
  shader.vertexShader = shader.vertexShader
    .replace('#include <common>', '#include <common>\nattribute float aFall;\nvarying float vFall;\nvarying vec3 vLocal;')
    .replace('#include <begin_vertex>', '#include <begin_vertex>\n  vFall = aFall;\n  vLocal = transformed;');
  shader.fragmentShader = shader.fragmentShader
    .replace('#include <common>', '#include <common>\nuniform float uTime;\nuniform float uFreeze;\nvarying float vFall;\nvarying vec3 vLocal;')
    .replace('#include <color_fragment>', `#include <color_fragment>
  // bands of white sliding down the face, so the sheet reads as falling rather than painted on
  float slide = fract(vLocal.y * 2.6 + uTime * 1.5 + (vLocal.x + vLocal.z) * 0.35);
  float streak = smoothstep(0.55, 1.0, slide) * vFall;
  diffuseColor.rgb = mix(diffuseColor.rgb, vec3(1.0), 0.28 + 0.45 * streak);
  // it stops running when the winter is hard enough to freeze the shallows
  diffuseColor.rgb = mix(diffuseColor.rgb, vec3(0.88, 0.93, 0.97), uFreeze * 0.8);`);
};

/**
 * Inland water standing higher than the dry ground over its edge (a stream's shallows spread onto a
 * bank that falls away beyond) pours over the lip: a sheet from the surface down to the ground along
 * that edge, and foam where it lands, rather than a flat sheet ending in mid-air. The sea is left be.
 */
function spill(b: Builder, w: World, i: number, j: number, d: number, tx: number, tz: number, wl: number): void {
  if (wl === SEA && w.biome[i] === Biome.Ocean) return;
  const m = EDGE_MINE[d], t = EDGE_THEIRS[d], c = w.corners;
  // the ground at each end of the edge: the higher of the two tiles' corners there
  const ga = Math.max(c[i * 4 + m[0]], c[j * 4 + t[0]]), gb = Math.max(c[i * 4 + m[1]], c[j * 4 + t[1]]);
  if (ga >= wl && gb >= wl) return;
  const [ax, az] = cornerXZ(m[0], tx, tz);
  const [bx, bz] = cornerXZ(m[1], tx, tz);
  const yTop = wl * STEP - 0.03;
  const ya = Math.min(yTop, ga * STEP), yb = Math.min(yTop, gb * STEP);
  const top = C.waterShallow, deep = C.waterMid, foam: RGB = [0.94, 0.98, 1];
  const ox = DIRS[d][0] * 0.04, oz = DIRS[d][1] * 0.04;
  b.tri(ax + ox, yTop, az + oz, bx + ox, yTop, bz + oz, bx + ox, yb, bz + oz, top, top, deep, 1);
  b.tri(ax + ox, yTop, az + oz, bx + ox, yb, bz + oz, ax + ox, ya, az + oz, top, deep, deep, 1);
  // a narrow apron of foam on the ground below, only along the part of the edge that falls
  const fx = DIRS[d][0] * 0.28, fz = DIRS[d][1] * 0.28;
  const fa = ya + 0.015, fb = yb + 0.015;
  b.tri(ax + ox, fa, az + oz, bx + ox, fb, bz + oz, bx + fx, fb, bz + fz, foam, foam, foam, 0);
  b.tri(ax + ox, fa, az + oz, bx + fx, fb, bz + fz, ax + fx, fa, az + fz, foam, foam, foam, 0);
}

/** Height in steps a drop must be before water is drawn tumbling over it. */
const FALL_MIN = 1;

/**
 * Every waterfall whose lip lies in this chunk. A fall is simply a place where two neighbouring
 * pieces of water sit two or more steps apart: a river crossing a terrace, a stream over a canyon
 * wall, or a channel meeting the sea. The face gets a sheet of water and the foot a shelf of foam.
 */
export function buildFallChunk(w: World, cx: number, cz: number): THREE.Mesh | null {
  const b = new Builder();
  const top = C.waterShallow, deep = C.waterMid, foam: RGB = [0.94, 0.98, 1];
  for (let tz = cz * CHUNK; tz < (cz + 1) * CHUNK; tz++) {
    for (let tx = cx * CHUNK; tx < (cx + 1) * CHUNK; tx++) {
      const i = idx(tx, tz);
      const wl = w.water[i];
      if (wl < 0) continue;
      for (let d = 0; d < 4; d++) {
        const nx = tx + DIRS[d][0], nz = tz + DIRS[d][1];
        if (!inB(nx, nz)) continue;
        const j = idx(nx, nz);
        const nl = w.water[j];
        if (nl < 0) { spill(b, w, i, j, d, tx, tz, wl); continue; }
        if (wl - nl < FALL_MIN) continue;
        // the shared edge, as two corners on the ground plane
        const m = EDGE_MINE[d];
        const [ax, az] = cornerXZ(m[0], tx, tz);
        const [bx, bz] = cornerXZ(m[1], tx, tz);
        const yTop = wl * STEP - 0.03, yBot = nl * STEP - 0.03;
        // pull the sheet a hair into the lower tile so it never fights the cliff face behind it
        const ox = DIRS[d][0] * 0.04, oz = DIRS[d][1] * 0.04;
        b.tri(ax + ox, yTop, az + oz, bx + ox, yTop, bz + oz, bx + ox, yBot, bz + oz, top, top, deep, 1);
        b.tri(ax + ox, yTop, az + oz, bx + ox, yBot, bz + oz, ax + ox, yBot, az + oz, top, deep, deep, 1);
        // foam where it lands, spread a little way into the pool below
        const drop = wl - nl;
        const fx = DIRS[d][0] * (0.3 + drop * 0.16), fz = DIRS[d][1] * (0.3 + drop * 0.16);
        const fy = yBot + 0.012;
        b.tri(ax, fy, az, bx, fy, bz, bx + fx, fy, bz + fz, foam, foam, foam, 0);
        b.tri(ax, fy, az, bx + fx, fy, bz + fz, ax + fx, fy, az + fz, foam, foam, foam, 0);
        // a big fall throws up spray: a pale plume rising off the pool, wider than the fall and fading upward
        if (drop >= 3) {
          const mx = (ax + bx) / 2 + DIRS[d][0] * 0.55, mz = (az + bz) / 2 + DIRS[d][1] * 0.55;
          const mh = Math.min(3, drop * STEP * 0.55), mw = 0.8;
          const px = -DIRS[d][1] * mw, pz = DIRS[d][0] * mw;
          const top: RGB = [0.9, 0.95, 0.98];
          b.tri(mx - px, fy, mz - pz, mx + px, fy, mz + pz, mx, fy + mh, mz, foam, foam, top, 0);
          b.tri(mx - DIRS[d][0] * 0.5, fy, mz - DIRS[d][1] * 0.5, mx + DIRS[d][0] * 0.5, fy, mz + DIRS[d][1] * 0.5, mx, fy + mh * 0.8, mz, foam, foam, top, 0);
        }
      }
    }
  }
  // and the little falls where a brook pours over a step
  brookFalls(b, w, cx, cz);
  const g = b.build('aFall');
  if (!g) return null;
  const mesh = new THREE.Mesh(g, fallMaterial);
  mesh.renderOrder = 1;
  return mesh;
}
