import { Flag, N, RoadType, World, type Road } from './tiles';
import { isWide } from './roads';
import { diagRuns, smoothDiagonals } from './diagonals';

/**
 * Curved road pieces. A road is laid as a chain of tiles, so every bend in it is a right angle. Two
 * pieces round those corners off when they are drawn and driven:
 *
 * - a **bend** (one tile): a quarter circle of radius ½ inside the corner tile itself, joining the
 *   middles of its two road edges. Every plain corner gets one, in towns and out.
 * - a **sweep** (two by two): a quarter circle of radius 1½ that starts at the far edge of the tile
 *   before the corner and ends at the far edge of the tile after it, cutting across a corner of the
 *   tile on the inside of the bend. Only out in the open country, where there is straight road either
 *   side and that inside tile is empty, fairly flat ground.
 *
 * Nothing about a road's tiles changes: which tiles are road, their edges, their costs. The curves
 * are worked out from the finished road network and shared by the road mesh, the traffic's routes,
 * the lamps and whatever grows beside the road, so they all agree.
 *
 * The interstate (three tiles wide) takes its corners wider again: a **wide sweep** (size 3) of radius
 * 2½ on its centre line wherever the straights either side leave room and the one tile on the inside of
 * the bend is free, else a radius of 1½ (size 4: its inside kerb pivots on the corner of its block). Those
 * are drawn by the mesh and followed by the traffic lane by lane (`sweepRoute`), but stay out of the table
 * of which tile is a curve: a corner's other users (lamps, props, the narrow roads' `roundCorners` in the
 * traffic) only know the narrow roads' curves.
 *
 * A ramp has no curves of its own: it is drawn, and driven, along `rampLine`, which pulls every staircase
 * of its tiles into the straight line through them.
 */

type CurveSize = 1 | 2 | 3 | 4;

/** One curved corner: the arc from `din` round to `dout` about (ox, oz), in the world's frame. */
export interface Curve {
  size: CurveSize;
  /** Tile before the corner, the corner, and the tile after it, in the road's own order. */
  path: [number, number, number];
  ox: number; oz: number; r: number;
  din: readonly [number, number]; dout: readonly [number, number];
  /** The tile on the inside of a sweep that the road cuts across a corner of (-1 for a bend). */
  inner: number;
}

/** Radius of each size's centreline. */
const CURVE_R: Record<CurveSize, number> = { 1: 0.5, 2: 1.5, 3: 2.5, 4: 1.5 };

/** A point on the curve `phi` of the way round (0 … π/2), `o` to the left of the direction of travel. */
export function curvePoint(c: Curve, phi: number, o = 0): [number, number] {
  const cs = Math.cos(phi), sn = Math.sin(phi);
  const tx = c.din[0] * cs + c.dout[0] * sn, tz = c.din[1] * cs + c.dout[1] * sn;
  return [
    c.ox - c.dout[0] * c.r * cs + c.din[0] * c.r * sn - tz * o,
    c.oz - c.dout[1] * c.r * cs + c.din[1] * c.r * sn + tx * o,
  ];
}

function dirOf(a: number, b: number): number {
  const d = b - a;
  return d === 1 ? 0 : d === N ? 1 : d === -1 ? 2 : d === -N ? 3 : -1;
}
const DX = [1, 0, -1, 0], DZ = [0, 1, 0, -1];

/**
 * Which corners of a road along `nodes` are curved, by node index. `laid` says the road is already in
 * the world's tables; a road still being planned (the builder's ghost) must find its tiles empty.
 * `claimed` holds tiles other sweeps already use, and gains this road's.
 */
export function planCurves(w: World, type: RoadType, nodes: number[], laid: boolean, claimed: Set<number>): Map<number, Curve> {
  const out = new Map<number, Curve>();
  if (type === RoadType.Interstate) return interstateCurves(w, nodes, claimed);
  if (isWide(type) || type === RoadType.Ramp || nodes.length < 3) return out;
  const n = nodes.length;
  const dirs: number[] = [];
  for (let k = 1; k < n; k++) dirs.push(dirOf(nodes[k - 1], nodes[k]));
  /** The tile holds this road alone, crossing exactly the edges `own`. */
  const alone = (t: number, own: number) => {
    if (w.deckAxis[t] || w.rail[t]) return false;
    return laid ? w.roadCover[t] === 1 && w.roadEdges[t] === own : w.road[t] === 0;
  };
  const edgesAt = (k: number) => (k > 0 ? 1 << ((dirs[k - 1] + 2) & 3) : 0) | (k < n - 1 ? 1 << dirs[k] : 0);
  const straight = (k: number) => k > 0 && k < n - 1 && dirs[k - 1] === dirs[k] && dirs[k] >= 0;
  // the corners of a 45° diagonal's staircase are no corners at all: the road runs straight over them (diagonals.ts)
  const diag = new Set<number>();
  for (const r of diagRuns(type, nodes)) for (let k = r.i + 1; k <= r.j; k++) diag.add(k);

  for (let k = 1; k < n - 1; k++) {
    if (diag.has(k)) continue;
    const a = dirs[k - 1], b = dirs[k];
    if (a < 0 || b < 0 || a === b || ((a + 2) & 3) === b) continue;
    const t = nodes[k];
    if (!alone(t, edgesAt(k)) || claimed.has(t)) continue;
    const din = [DX[a], DZ[a]] as const, dout = [DX[b], DZ[b]] as const;
    const cx = (t % N) + 0.5, cz = Math.floor(t / N) + 0.5;
    const make = (size: CurveSize, inner: number): Curve => {
      const r = CURVE_R[size];
      const sx = cx - din[0] * r, sz = cz - din[1] * r;
      return { size, path: [nodes[k - 1], t, nodes[k + 1]], ox: sx + dout[0] * r, oz: sz + dout[1] * r, r, din, dout, inner };
    };
    // a sweep, if the country is open enough for it
    const inner = sweepInner(w, nodes, k, din, dout);
    if (inner >= 0 && straight(k - 1) && straight(k + 1) && k >= 2 && k <= n - 3
      && alone(nodes[k - 1], edgesAt(k - 1)) && alone(nodes[k + 1], edgesAt(k + 1))
      && !claimed.has(nodes[k - 1]) && !claimed.has(nodes[k + 1]) && !claimed.has(inner)) {
      out.set(k, make(2, inner));
      for (const u of [nodes[k - 1], t, nodes[k + 1], inner]) claimed.add(u);
      continue;
    }
    out.set(k, make(1, -1));
    claimed.add(t);
  }
  return out;
}

/** The empty country tile a sweep round corner k would cut across, or -1 if there is none. */
function sweepInner(w: World, nodes: number[], k: number, din: readonly [number, number], dout: readonly [number, number]): number {
  const t = nodes[k];
  const tx = t % N, tz = Math.floor(t / N);
  // the inside of the bend: back along the way in, then on along the way out
  const ix = tx - din[0] + dout[0], iz = tz - din[1] + dout[1];
  if (ix < 0 || iz < 0 || ix >= N || iz >= N) return -1;
  const i = ix + iz * N;
  for (const u of [nodes[k - 1], t, nodes[k + 1], i]) if (w.townId[u] >= 0 || w.portId[u] >= 0) return -1;
  if (w.road[i] || w.blocked[i] || w.water[i] >= 0 || w.rail[i] || w.deckAxis[i] || w.flags[i] & Flag.Field) return -1;
  // fairly flat, and level with the corner, or the road would climb the bank
  const c = w.corners;
  let lo = Infinity, hi = -Infinity;
  for (let q = 0; q < 4; q++) { lo = Math.min(lo, c[i * 4 + q]); hi = Math.max(hi, c[i * 4 + q]); }
  let mid = 0;
  for (let q = 0; q < 4; q++) mid += c[t * 4 + q] / 4;
  if (hi - lo > 1 || Math.abs((lo + hi) / 2 - mid) > 1) return -1;
  return i;
}

// ---------------------------------------------------------------------------------------------
// the whole network's curves, worked out once per change to the roads

interface Plan {
  stamp: number;
  byRoad: Map<Road, Map<number, Curve>>;
  /** The interstate's sweeps (sizes 3 and 4), which the traffic follows lane by lane (sweepRoute). */
  wide: Curve[];
  /** Every tile a curve lies in (inside tiles included), and the curve. */
  byTile: Map<number, Curve>;
  /** Tiles on the inside of a sweep, which the road cuts across: nothing grows or stands there. */
  inner: Set<number>;
  claimed: Set<number>;
}
const PLANS = new WeakMap<World, Plan>();

export function curvePlan(w: World): Plan {
  let p = PLANS.get(w);
  if (p && p.stamp === w.roadStamp) return p;
  p = { stamp: w.roadStamp, byRoad: new Map(), wide: [], byTile: new Map(), inner: new Set(), claimed: new Set() };
  for (const r of w.roads) {
    const cs = planCurves(w, r.type, r.nodes, true, p.claimed);
    p.byRoad.set(r, cs);
    for (const c of cs.values()) {
      if (c.size >= 3) { p.wide.push(c); if (c.inner >= 0) p.inner.add(c.inner); continue; }
      if (c.size === 2) { for (const t of c.path) p.byTile.set(t, c); p.byTile.set(c.inner, c); p.inner.add(c.inner); }
      else p.byTile.set(c.path[1], c);
    }
  }
  PLANS.set(w, p);
  return p;
}

/** The curved corners of a laid road, by node index. */
export const curvesOf = (w: World, r: Road): Map<number, Curve> => curvePlan(w).byRoad.get(r) ?? new Map();

/** Whether a tile lies on the inside of a sweep (keep trees, crops and fences off it). */
export const insideCurve = (w: World, i: number): boolean => curvePlan(w).inner.has(i);

/** Whether a tile is one of the three road tiles of a sweep. */
export function inSweep(w: World, i: number): boolean {
  const c = curvePlan(w).byTile.get(i);
  return !!c && c.size === 2 && c.inner !== i;
}

// ---------------------------------------------------------------------------------------------
// the interstate's sweeps

/**
 * An interstate's corners, by node index: as wide as the straights either side allow (a radius can't
 * reach back past what the corner before it took, or more than halfway along the straight to the next),
 * a wide sweep where its inside tile is free, a tighter one where it isn't, square where neither fits.
 * Never on a deck: a raised interstate turns on a level platform, square.
 */
function interstateCurves(w: World, nodes: number[], claimed: Set<number>): Map<number, Curve> {
  const out = new Map<number, Curve>();
  const n = nodes.length;
  if (n < 3) return out;
  const dirs: number[] = [];
  for (let k = 1; k < n; k++) dirs.push(dirOf(nodes[k - 1], nodes[k]));
  let lastAt = 0, lastR = 0;
  for (let k = 1; k < n - 1; k++) {
    const a = dirs[k - 1], b = dirs[k];
    if (a < 0 || b < 0 || a === b || ((a + 2) & 3) === b) continue;
    const t = nodes[k];
    // the run after it, to the next corner or the end
    let next = k + 1;
    while (next < n - 1 && dirs[next] === b) next++;
    const before = k - lastAt - lastR, after = next < n - 1 ? (next - k) / 2 : next - k;
    const din = [DX[a], DZ[a]] as const, dout = [DX[b], DZ[b]] as const;
    const tx = t % N, tz = Math.floor(t / N);
    if (w.deckAxis[t]) { lastAt = k; lastR = 0; continue; }
    const ix = tx - 2 * din[0] + 2 * dout[0], iz = tz - 2 * din[1] + 2 * dout[1];
    const inner = ix >= 0 && iz >= 0 && ix < N && iz < N ? ix + iz * N : -1;
    const roomy = inner >= 0 && !claimed.has(inner) && !w.road[inner] && !w.blocked[inner] && w.water[inner] < 0 && !w.rail[inner] && !w.deckAxis[inner];
    const size: CurveSize | 0 = roomy && before >= 2.5 && after >= 2.5 ? 3 : before >= 1.5 && after >= 1.5 ? 4 : 0;
    if (!size) { lastAt = k; lastR = 0; continue; }
    const r = CURVE_R[size];
    const cx = tx + 0.5, cz = tz + 0.5;
    const sx = cx - din[0] * r, sz = cz - din[1] * r;
    const c: Curve = { size, path: [nodes[k - 1], t, nodes[k + 1]], ox: sx + dout[0] * r, oz: sz + dout[1] * r, r, din, dout, inner: size === 3 ? inner : -1 };
    out.set(k, c);
    if (size === 3) claimed.add(inner);
    lastAt = k; lastR = r;
  }
  return out;
}

/** Is (x, z) inside an interstate sweep's corner: back along the way in and on along the way out as far as its curve reaches, its block's width across? */
function inSweepBox(c: Curve, x: number, z: number): boolean {
  const cx = (c.path[1] % N) + 0.5, cz = Math.floor(c.path[1] / N) + 0.5;
  const u = (x - cx) * c.din[0] + (z - cz) * c.din[1], v = (x - cx) * c.dout[0] + (z - cz) * c.dout[1];
  return u >= -c.r - 0.01 && u <= 1.51 && v >= -1.51 && v <= c.r + 0.01;
}

/**
 * A CPU route's points round the interstate's sweeps: wherever the route runs into one along either arm
 * and out along the other, the tile middles it took round the corner give way to its own lane's arc (at
 * the offset from the centre line it came in at), so a car stays on the tarmac the mesh draws there rather
 * than cutting across the square corner of the block.
 */
export function sweepRoute(w: World, pts: { x: number; z: number; tile: number }[]): { x: number; z: number; tile: number }[] {
  const wide = curvePlan(w).wide;
  if (!wide.length || pts.length < 3) return pts;
  let out = pts;
  for (const c of wide) {
    const ins = out.map((p) => inSweepBox(c, p.x, p.z));
    const i = ins.indexOf(true);
    if (i <= 0) continue;
    let j = i;
    while (j + 1 < out.length && ins[j + 1]) j++;
    if (j >= out.length - 1 || j - i < 1) continue;
    const cx = (c.path[1] % N) + 0.5, cz = Math.floor(c.path[1] / N) + 0.5;
    const u = (p: { x: number; z: number }) => (p.x - cx) * c.din[0] + (p.z - cz) * c.din[1];
    const v = (p: { x: number; z: number }) => (p.x - cx) * c.dout[0] + (p.z - cz) * c.dout[1];
    // in along the way in and out along the way out, or the reverse: on an arm is past the corner's own block
    const onIn = (p: { x: number; z: number }) => u(p) < -1.49 && Math.abs(v(p)) < 1.5;
    const onOut = (p: { x: number; z: number }) => v(p) > 1.49 && Math.abs(u(p)) < 1.5;
    const fwd = onIn(out[i]) && onOut(out[j]), back = onOut(out[i]) && onIn(out[j]);
    if (!fwd && !back) continue;
    // the lane: where it runs on the arm nearer the start, as an offset to the left of the way in
    const p0 = out[fwd ? i : j];
    const o = (p0.x - cx) * -c.din[1] + (p0.z - cz) * c.din[0];
    const arc: { x: number; z: number; tile: number }[] = [];
    const steps = 10;
    for (let s = 0; s <= steps; s++) {
      const f = s / steps;
      const [x, z] = curvePoint(c, (fwd ? f : 1 - f) * (Math.PI / 2), o);
      arc.push({ x, z, tile: Math.floor(x) + Math.floor(z) * N });
    }
    out = [...out.slice(0, i), ...arc, ...out.slice(j + 1)];
  }
  return out;
}

// ---------------------------------------------------------------------------------------------
// ramps

/**
 * A ramp's centre line through the middles of `tiles` (a ramp's nodes, or the stretch of a route along
 * one): every run of them that one straight line passes through tile by tile — a staircase, the taper where
 * it slants into the interstate — becomes that straight line, and the joins between are rounded a little.
 * The line keeps to the ramp's own tiles, so what is drawn is what is driven.
 */
export function rampLine(tiles: number[]): [number, number][] {
  const n = tiles.length;
  const c = (t: number): [number, number] => [(t % N) + 0.5, Math.floor(t / N) + 0.5];
  if (n < 3) return tiles.map(c);
  const keep: number[] = [0];
  for (let i = 0; i < n - 1;) {
    let best = i + 1;
    for (let j = n - 1; j > i + 1; j--) if (straightThrough(tiles, i, j)) { best = j; break; }
    keep.push(best);
    i = best;
  }
  let line = keep.map((k) => c(tiles[k]));
  // round the joins: two passes of corner cutting, the ends held where they are
  for (let pass = 0; pass < 2 && line.length > 2; pass++) {
    const next: [number, number][] = [line[0]];
    for (let k = 0; k < line.length - 1; k++) {
      const [ax, az] = line[k], [bx, bz] = line[k + 1];
      if (k > 0) next.push([ax * 0.75 + bx * 0.25, az * 0.75 + bz * 0.25]);
      if (k < line.length - 2) next.push([ax * 0.25 + bx * 0.75, az * 0.25 + bz * 0.75]);
    }
    next.push(line[line.length - 1]);
    line = next;
  }
  return line;
}

/** Does the straight line between the middles of tiles[i] and tiles[j] run through exactly tiles i…j, in order? */
function straightThrough(tiles: number[], i: number, j: number): boolean {
  const ax = tiles[i] % N, az = Math.floor(tiles[i] / N), bx = tiles[j] % N, bz = Math.floor(tiles[j] / N);
  const dx = bx - ax, dz = bz - az;
  // a staircase never turns back on itself, so it is exactly as long as the line's own walk over the tiles
  if (Math.abs(dx) + Math.abs(dz) !== j - i) return false;
  const len = Math.hypot(dx, dz), ux = dx / len, uz = dz / len;
  const reach = (Math.abs(ux) + Math.abs(uz)) / 2 - 1e-6;
  for (let k = i + 1; k < j; k++) {
    const x = (tiles[k] % N) - ax, z = Math.floor(tiles[k] / N) - az;
    if (Math.abs(x * uz - z * ux) >= reach) return false;
  }
  return true;
}

/**
 * A CPU route's points along a ramp: each stretch of three or more ramp tiles it takes in a row is swapped
 * for points along that stretch's `rampLine`, so a car takes the slip road's slant the way it is drawn
 * rather than stepping down it tile by tile. Its points along a 45° diagonal go onto the diagonal's line
 * first (diagonals.ts smoothDiagonals), for the same reason.
 */
export function smoothRamps(w: World, pts: { x: number; z: number; tile: number }[]): { x: number; z: number; tile: number }[] {
  // and along a 45° diagonal, the straight line it is drawn as (diagonals.ts)
  pts = smoothDiagonals(w, pts);
  if (pts.length < 4) return pts;
  let any = false;
  for (const p of pts) if (w.road[p.tile] === RoadType.Ramp) { any = true; break; }
  if (!any) return pts;
  const ramp = (k: number) => w.road[pts[k].tile] === RoadType.Ramp;
  const step = (a: number, b: number) => { const d = Math.abs(pts[b].tile - pts[a].tile); return d === 1 || d === N; };
  const out: { x: number; z: number; tile: number }[] = [];
  for (let i = 0; i < pts.length;) {
    // the route's first and last points stay where they are
    let j = i;
    if (i > 0 && ramp(i)) while (j + 1 < pts.length - 1 && ramp(j + 1) && step(j, j + 1)) j++;
    if (j - i < 2) { out.push(pts[i]); i++; continue; }
    const line = rampLine(pts.slice(i, j + 1).map((p) => p.tile));
    // points every half tile along it, its last point left for the next stretch to lay
    for (let k = 0; k < line.length - 1; k++) {
      const [ax, az] = line[k], [bx, bz] = line[k + 1];
      const m = Math.max(1, Math.ceil(Math.hypot(bx - ax, bz - az) / 0.5));
      for (let s = 0; s < m; s++) {
        const x = ax + ((bx - ax) * s) / m, z = az + ((bz - az) * s) / m;
        out.push({ x, z, tile: Math.floor(x) + Math.floor(z) * N });
      }
    }
    i = j;
  }
  return out;
}
