import type { KindSpec } from './townKinds';
import { Lot } from './tiles';

/**
 * Out in the middle of nowhere (GEN 51): thirty odd, funny and lonely things a driver comes across far from
 * any town, most of them toward the county's edge. A monolith on bare ground, a bus rusting in the grass,
 * a ring of cars standing on their noses, a phone box ringing for nobody. One table, spread into the game's
 * per-kind tables (townKinds, towns' heights, economy, estate, hqGrade, cargo labels, traffic tags, the
 * gallery's sizes) and into the roadside placer's rows (world/roadside.ts), so a new one is added here once.
 * The models are in render/buildings/wildA|B|C.ts.
 */

export const WILD_KINDS = [
  // A: the strange and the lonely
  'monolith', 'phoneBox', 'lonelyVending', 'doorToNowhere', 'fieldPiano', 'giantChair', 'shoeTree', 'signForest', 'bigfootStatue', 'giantDuck',
  // B: what was left behind
  'abandonedBus', 'carhenge', 'planeBoneyard', 'derelictFair', 'hauntedHouse', 'bottleHouse', 'meteorCrater', 'whaleBones', 'stoneHeads', 'giantSundial',
  // C: somebody is out here
  'treeHouse', 'balloonField', 'radioArray', 'giantScarecrow', 'campsite', 'apiary', 'prospectorCamp', 'hedgeMaze', 'giantSnowman', 'giantChess',
] as const;

export type WildKind = (typeof WILD_KINDS)[number];

/** Where the roadside placer looks for it (world/roadside.ts): `edge` is far from every town, toward the county's edge. */
type WildWhere = 'edge' | 'forest' | 'high' | 'water' | 'field' | 'shore';

interface Info {
  label: string;
  icon: string;
  /** The lot in tiles (w × d). */
  size: [number, number];
  /** How tall the model stands, in world units (towns.ts buildingHeight). */
  h: number;
  /** What it costs to knock down (economy.ts), which sets a lot's floor price. */
  price: number;
  /** As an HQ (hqGrade.ts): 0 for a lot nobody would run a company from. */
  grade: 0 | 1 | 2;
  where: WildWhere;
  /** The share of counties that have one. */
  chance: number;
  /** Only where it freezes, or only where it never does. */
  climate?: 'cold' | 'warm';
  /** Run a lane out to it from the nearest road. */
  lane?: boolean;
  /** An open lot: nothing stops a car (a crater's floor, a hedge maze, pieces on a board). */
  open?: boolean;
  /** The ground under it. */
  lot?: Lot;
}

