const pick = <T>(f: (i: Info) => T): Record<WildKind, T> => Object.fromEntries(WILD_KINDS.map((k) => [k, f(WILD_INFO[k])])) as Record<WildKind, T>;

/** Spread into townKinds' KIND_SPEC. */
export const WILD_SPEC = pick((i): KindSpec => ({
  w: i.size[0], d: i.size[1], zone: 'edge', lot: i.lot ?? Lot.None, apart: 40, ...(i.open ? { solid: false } : {}),
}));
export const WILD_HEIGHT = pick((i) => i.h);
export const WILD_PRICE = pick((i) => i.price);
export const WILD_ICON = pick((i) => i.icon);
export const WILD_LABEL = pick((i) => i.label);
export const WILD_GRADE = pick((i) => i.grade);
export const WILD_SIZE = pick((i) => i.size);
const isWildKind = (k: string): k is WildKind => k in WILD_INFO;
