import { N, SEA, Biome, Flag, World, idx, inB } from './tiles';
import { cell01, hashCell, mulberry32 } from './rng';
import { NEXT_WORLD } from './nextWorld';
import type { TownPlan } from './towns';

/**
 * Venice: a town on the water whose streets are canals. One coastal town in a few is laid out this way
 * before its ground is set in tiles, the way a megalopolis cuts its shipping channel: a Grand Canal
 * winding in from the sea through the middle of town, a grid of narrower canals (rii) branching off it
 * with a block of houses between each, and the whole square pressed flat just clear of the water. The
 * town is then built in the venice style (world/towns.ts): its houses may face a canal instead of a
 * street, a few brick lanes cross the canals on little bridges, and boats can load and deliver at any
 * door on the water (game/cargo.ts, Site.berth).
 */

/** The share of eligible coastal towns built on canals. */
const VENICE_CHANCE = 0.18;
/**
 * And of the eligible coastal cities and metros that are not a Venice, the share laid out as an Amsterdam:
 * the same Grand Canal in from the sea (the Amstel), but the side canals are half-rings round the old centre
 * on the water (the grachtengordel), crossed by a few radial ones, and the town is built in the Dutch style.
 */
const AMSTERDAM_CHANCE = 0.25;
/**
 * And of those that are neither, the share laid out as an Osaka: the canal in from the sea runs nearly straight
 * through the middle of town (the Dōtonbori), one cross canal cuts it (the Higashi-Yokobori), and the town is
 * built in the osaka style, its buildings fronting the water hung with neon and giant signs.
 */
const OSAKA_CHANCE = 0.16;
/**
 * And of the eligible warm seaside villages, suburbs and cities that are none of those, the share built as an
 * Adriatic old town (GEN 53, world/nextWorld.ts): one wide harbour basin dug in from the sea, quays flat round
 * it, and the rest of the square rising in a gentle hill to the church on its top (Rovinj), built in the
 * adriatic style (world/towns.ts `adriatic`). Off, it is never rolled, and no other town's roll moves.
 */
export const ADRIATIC_CHANCE = 0.35;
const ADRIATIC_KINDS = new Set(['rural', 'suburb', 'city']);
const SALT = 1360;
/** How far from a side of the square the sea may lie for the Grand Canal to run out to it. */
const SEA_REACH = 22;
/** Width in tiles of the Grand Canal, and of a side canal. */
const GRAND = 3, RIO = 2;
/** Depth below sea level: the Grand Canal takes any boat a canal could, a rio the small ones. */
const GRAND_DEPTH = 3, RIO_DEPTH = 2;
/** Blocks between side canals, by the kind of town: a village's are small, a city's big enough for a hall. */
const SPACING: Record<string, number> = { rural: 8, suburb: 9, city: 10, metro: 11 };

/**
 * Pick the canal towns among this cell's plans and dig their canals. Only an ordinary (non-biome) cell,
 * only a town low by the sea, and each one its own hashed roll, so nothing else in the cell moves.
 * Returns whether any were dug, since the coastline has then moved.
 */
export function planVenice(
  w: World, plans: TownPlan[], land: Uint8Array, river: Uint8Array, causeway: Uint8Array | undefined, seedHash: number, band: number,
): Uint8Array | null {
  const mask = new Uint8Array(N * N);
  let dug = false;
  plans.forEach((p, k) => {
    // (a GEN 53 town laid out to a city plan of its own is no canal town: only one on today's layout may be)
    if (p.kind === 'mega' || p.parent !== undefined || p.perch || p.channel || !(p.kind in SPACING) || (p.plan !== undefined && p.plan !== 'grid')) return;
    if (p.level > SEA + 4) return;
    // (Venice's roll first, as it always was, so no Venice moves; an Amsterdam only where that fails)
    const venice = cell01(seedHash, w.cx, w.cz, SALT + k) < VENICE_CHANCE;
    const amsterdam = !venice && (p.kind === 'city' || p.kind === 'metro') && cell01(seedHash, w.cx, w.cz, SALT + 80 + k) < AMSTERDAM_CHANCE;
    // (and an Osaka's roll only where both of those fail, on a salt of its own, so neither of them moves)
    const osaka = !venice && !amsterdam && (p.kind === 'city' || p.kind === 'metro') && cell01(seedHash, w.cx, w.cz, SALT + 120 + k) < OSAKA_CHANCE;
    // (and an Adriatic's on a salt of its own again, only with the next world on: off, nothing here moves)
    const adriatic = NEXT_WORLD && !venice && !amsterdam && !osaka && ADRIATIC_KINDS.has(p.kind)
      && cell01(seedHash, w.cx, w.cz, SALT + 160 + k) < ADRIATIC_CHANCE && warmDry(w, p);
    if (!venice && !amsterdam && !osaka && !adriatic) return;
    const side = seaSide(w, p, land, band);
    if (side < 0) return;
    const rng = mulberry32(hashCell(seedHash, w.cx, w.cz, SALT + 40 + k));
    if (dig(w, p, side, land, river, causeway, band, rng, mask, amsterdam ? 'rings' : osaka ? 'straight' : adriatic ? 'harbour' : 'grid')) {
      p.canals = true;
      p.style = amsterdam ? 'dutch' : osaka ? 'osaka' : adriatic ? 'adriatic' : 'venice';
      dug = true;
    }
  });
  return dug ? mask : null;
}

/**
 * Set a canal town's tile corners outright, over whatever the smoothing made of them: every canal tile
 * flat at its floor, every tile of the town's ground flat just clear of the water, so each bank is a
 * sheer quay wall (the canal tiles carry Flag.Corridor, which lets the wall stand) rather than a slope
 * that swallows the lot beside it. `corner(i)` is the local tile's four corners in the padded grid.
 */
export function setCanalCorners(mask: Uint8Array, E: Float32Array, set: (i: number, h: number) => void): void {
  for (let i = 0; i < mask.length; i++) {
    if (mask[i] === CANAL) set(i, Math.round(E[i]));
    else if (mask[i] === QUAY) set(i, SEA + 1);
  }
}

/** A canal-town mask: a canal tile, and a tile of the town's ground. */
export const CANAL = 1, QUAY = 2;

/** A Mediterranean sort of place: warm, and no snow or ice anywhere on the square. */
function warmDry(w: World, p: TownPlan): boolean {
  let t = 0, n = 0;
  for (let z = p.z0; z < p.z0 + p.size; z++) for (let x = p.x0; x < p.x0 + p.size; x++) {
    if (!inB(x, z)) continue;
    const i = idx(x, z), b = w.biome[i];
    if (b === Biome.Snow || b === Biome.Ice) return false;
    t += w.temp[i];
    n++;
  }
  return n > 0 && t / n > 0.6;
}

/** The side of the square (a DIRS index) the sea is nearest, and within reach, or -1. */
function seaSide(w: World, p: TownPlan, land: Uint8Array, band: number): number {
  let best = -1, bestD = SEA_REACH + 1;
  // (the Grand Canal leaves the side somewhere in its middle half, so the sea is looked for from there)
  for (let d = 0; d < 4; d++) for (const f of [0.3, 0.5, 0.7]) {
    const [ox, oz] = [[1, 0], [0, 1], [-1, 0], [0, -1]][d];
    // march out from the side until the land ends
    const along = Math.round(p.size * f);
    const mx = d === 0 ? p.x0 + p.size - 1 : d === 2 ? p.x0 : p.x0 + along;
    const mz = d === 1 ? p.z0 + p.size - 1 : d === 3 ? p.z0 : p.z0 + along;
    for (let s = 1; s <= SEA_REACH; s++) {
      const x = mx + ox * s, z = mz + oz * s;
      if (!inB(x, z) || x < band || z < band || x >= N - band || z >= N - band) break;
      if (!land[idx(x, z)] && w.elev[idx(x, z)] < SEA) {
        if (s < bestD) { bestD = s; best = d; }
        break;
      }
    }
  }
  return best;
}

/**
 * Dig the canals of the town `p` with the sea off side `side`. Works in the square's own frame: u along
 * the sea side, v in from it. False (and nothing dug) where the Grand Canal cannot reach the sea cleanly.
 */
function dig(
  w: World, p: TownPlan, side: number, land: Uint8Array, river: Uint8Array, causeway: Uint8Array | undefined, band: number, rng: () => number,
  mask: Uint8Array, plan: 'grid' | 'rings' | 'straight' | 'harbour' = 'grid',
): boolean {
  if (plan === 'harbour') return harbour(w, p, side, land, river, causeway, band, rng, mask);
  const S = p.size, E = w.elev;
  const at = (u: number, v: number): [number, number] => {
    switch (side) {
      case 0: return [p.x0 + S - 1 - v, p.z0 + u];
      case 1: return [p.x0 + u, p.z0 + S - 1 - v];
      case 2: return [p.x0 + v, p.z0 + u];
      default: return [p.x0 + u, p.z0 + v];
    }
  };
  const want = new Map<number, number>();   // tile → depth
  const mark = (u: number, v: number, depth: number) => {
    const [x, z] = at(u, v);
    if (!inB(x, z)) return;
    const i = idx(x, z);
    want.set(i, Math.max(want.get(i) ?? 0, depth));
  };

  // ---- the Grand Canal: in from the sea, a reversed S across the town, ending in a basin ----
  // (an Osaka's canal runs all but straight across the town, and on nearly to the far side)
  const straight = plan === 'straight';
  const amp = S * (straight ? 0.03 : 0.17), ph = rng() * Math.PI * 2, turns = 0.7 + rng() * 0.3;
  const mid = S / 2 + (rng() - 0.5) * S * 0.12;
  const centre = (v: number) => mid + amp * Math.sin(ph + (v / S) * Math.PI * 2 * turns);
  const endRoll = rng(), end = straight ? S - 5 : Math.round(S * (0.72 + endRoll * 0.14));
  const grand: number[] = [];
  for (let v = 0; v <= end; v++) {
    const c = Math.round(centre(v));
    for (let o = -(GRAND >> 1); o <= GRAND >> 1; o++) mark(c + o, v, GRAND_DEPTH);
    // a bend steps across one tile at a time, so the canal stays one piece
    const next = Math.round(centre(v + 1));
    if (v < end && next !== c) for (let o = -(GRAND >> 1); o <= GRAND >> 1; o++) mark(next + o, v, GRAND_DEPTH);
    grand.push(c);
  }
  // the basin at its head, where the canal opens out before the church
  const bc = grand[grand.length - 1];
  for (let dv = -2; dv <= 1; dv++) for (let du = -3; du <= 3; du++) mark(bc + du, end + dv, GRAND_DEPTH);

  // out of town to open water: straight on from the mouth until the sea is reached
  const mouth = grand[0];
  let reached = false;
  for (let v = -1; v >= -SEA_REACH - 2; v--) {
    let open = 0;
    for (let o = -(GRAND >> 1); o <= GRAND >> 1; o++) {
      const [x, z] = at(mouth + o, v);
      if (!inB(x, z) || x < band || z < band || x >= N - band || z >= N - band) return false;
      const i = idx(x, z);
      if (causeway && causeway[i]) return false;
      // another town's ground, or a harbour's, is not ours to dig
      if (w.biome[i] === Biome.Town) return false;
      if (!land[i] && E[i] < SEA) open++;
      else mark(mouth + o, v, GRAND_DEPTH);
    }
    if (open === GRAND) { reached = true; break; }
  }
  if (!reached) return false;

  const lo = 2, hi = S - 3;
  if (plan === 'straight') {
    // ---- Osaka: one cross canal cutting the Dōtonbori square across the middle of town ----
    const v = Math.round(S * (0.42 + rng() * 0.1));
    for (let u = lo; u <= hi; u++) for (let o = 0; o < RIO; o++) mark(u, v + o, RIO_DEPTH);
  } else if (plan === 'rings') {
    // ---- Amsterdam's grachten: three half-rings round the old centre on the water, a few cross canals ----
    const cu = S / 2, cv = -S * 0.08, radii = [0.28, 0.48, 0.68].map((f) => S * f);
    for (let v = lo; v <= hi; v++) for (let u = lo; u <= hi; u++) {
      const d = Math.hypot(u - cu, v - cv);
      for (const R of radii) if (d >= R - RIO / 2 && d < R + RIO / 2) mark(u, v, RIO_DEPTH);
    }
    for (let a = 0.4; a < Math.PI - 0.3; a += 0.6) {
      if (rng() < 0.3) continue;
      for (let t = radii[0]; t <= radii[2]; t += 0.5) {
        const u = Math.round(cu + Math.cos(a) * t), v = Math.round(cv + Math.sin(a) * t);
        if (u < lo || u > hi || v < lo || v > hi) continue;
        for (let o = 0; o < RIO; o++) mark(u + o, v, RIO_DEPTH);
      }
    }
  } else {
  // ---- the rii: a grid of narrower canals over the square, a few of their stretches left out ----
  const G = SPACING[p.kind];
  const lines = (from: number) => {
    const out: number[] = [];
    for (let s = from + G + Math.floor(rng() * 3) - 1; s < hi - 3; s += G + Math.floor(rng() * 3) - 1) out.push(s);
    return out;
  };
  const vs = lines(0), us = lines(0);
  // along u at each v: cut into stretches between the crossing canals, each kept or not
  const cuts = (xs: number[]) => [lo, ...xs, hi];
  for (const v of vs) {
    const stops = cuts(us);
    for (let k = 0; k + 1 < stops.length; k++) {
      if (rng() < 0.28) continue;
      for (let u = stops[k]; u <= stops[k + 1]; u++) for (let o = 0; o < RIO; o++) mark(u, v + o, RIO_DEPTH);
    }
  }
  for (const u of us) {
    const stops = cuts(vs);
    for (let k = 0; k + 1 < stops.length; k++) {
      if (rng() < 0.28) continue;
      for (let v = stops[k]; v <= stops[k + 1]; v++) for (let o = 0; o < RIO; o++) mark(u + o, v, RIO_DEPTH);
    }
  }
  }

  // ---- keep only what joins the Grand Canal: a rio cut off by an omitted stretch is filled in again ----
  const [sx, sz] = at(mouth, 0);
  const start = idx(sx, sz);
  if (!want.has(start)) return false;
  const keep = new Set<number>([start]);
  const queue = [start];
  for (let h = 0; h < queue.length; h++) {
    const i = queue[h], x = i % N, z = (i - x) / N;
    for (const [dx, dz] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
      if (!inB(x + dx, z + dz)) continue;
      const j = idx(x + dx, z + dz);
      if (!keep.has(j) && want.has(j)) { keep.add(j); queue.push(j); }
    }
  }

  // ---- the square pressed flat, a step clear of the water, easing out to the country round it ----
  const flat = SEA + 1, EASE = 5;
  p.level = flat;
  for (let z = p.z0 - EASE; z < p.z0 + S + EASE; z++) for (let x = p.x0 - EASE; x < p.x0 + S + EASE; x++) {
    if (!inB(x, z)) continue;
    const i = idx(x, z);
    if (!land[i] || keep.has(i)) continue;
    const out = Math.max(p.x0 - x, x - (p.x0 + S - 1), p.z0 - z, z - (p.z0 + S - 1), 0);
    if (out === 0) { E[i] = flat; mask[i] = QUAY; }
    else if (w.biome[i] !== Biome.Town) { const t = 1 - out / (EASE + 1); E[i] = flat * t + E[i] * (1 - t); }
  }
  // ---- and the canals cut into it, their banks quay walls ----
  for (const i of keep) {
    land[i] = 0;
    river[i] = 0;
    w.biome[i] = Biome.Ocean;
    E[i] = SEA - want.get(i)!;
    w.flags[i] |= Flag.Corridor;
    mask[i] = CANAL;
  }
  return true;
}

/**
 * An Adriatic old town's harbour (Rovinj): one wide basin dug in from the sea side of the square, a channel on out
 * to open water, quays pressed flat a step clear of the water round the basin, and the rest of the square rising
 * in a gentle hill away from it, two or three steps at its top, where the church will stand (towns.ts `adriatic`,
 * KIND_SPEC stEuphemia `highest`). Same frame and masks as dig(); false (nothing dug) where the channel cannot
 * reach the sea cleanly.
 */
function harbour(
  w: World, p: TownPlan, side: number, land: Uint8Array, river: Uint8Array, causeway: Uint8Array | undefined, band: number, rng: () => number,
  mask: Uint8Array,
): boolean {
  const S = p.size, E = w.elev;
  const at = (u: number, v: number): [number, number] => {
    switch (side) {
      case 0: return [p.x0 + S - 1 - v, p.z0 + u];
      case 1: return [p.x0 + u, p.z0 + S - 1 - v];
      case 2: return [p.x0 + v, p.z0 + u];
      default: return [p.x0 + u, p.z0 + v];
    }
  };
  const want = new Set<number>();
  const mark = (u: number, v: number) => { const [x, z] = at(u, v); if (inB(x, z)) want.add(idx(x, z)); };
  // the basin: as wide as a third of the town, a third of the way in, its inner end rounded off
  const mid = Math.round(S / 2 + (rng() - 0.5) * S * 0.2), half = Math.max(3, Math.round(S * 0.15));
  const deep = Math.max(6, Math.round(S * (0.28 + rng() * 0.08)));
  for (let v = 0; v <= deep; v++) {
    const h = v > deep - 3 ? Math.round(half * Math.sqrt(Math.max(0, 1 - ((v - (deep - 3)) / 3.5) ** 2))) : half;
    for (let u = mid - h; u <= mid + h; u++) mark(u, v);
  }
  // the channel out to open water, straight on from the basin's mouth
  const MW = 2;
  let reached = false;
  for (let v = -1; v >= -SEA_REACH - 2; v--) {
    let open = 0;
    for (let o = -MW; o <= MW; o++) {
      const [x, z] = at(mid + o, v);
      if (!inB(x, z) || x < band || z < band || x >= N - band || z >= N - band) return false;
      const i = idx(x, z);
      if (causeway && causeway[i]) return false;
      if (w.biome[i] === Biome.Town) return false;
      if (!land[i] && E[i] < SEA) open++;
      else mark(mid + o, v);
    }
    if (open === 2 * MW + 1) { reached = true; break; }
  }
  if (!reached) return false;
  // how far each tile of the square (and the ease round it) lies from the water, for the hill
  const EASE = 5, x0 = p.x0 - EASE, z0 = p.z0 - EASE, span = S + 2 * EASE;
  const dist = new Int16Array(span * span).fill(-1);
  const queue: number[] = [];
  for (const i of want) {
    const x = i % N, z = (i - x) / N;
    if (x < x0 || z < z0 || x >= x0 + span || z >= z0 + span) continue;
    const li = (z - z0) * span + x - x0;
    dist[li] = 0;
    queue.push(li);
  }
  for (let h = 0; h < queue.length; h++) {
    const li = queue[h], lx = li % span, lz = (li - lx) / span;
    for (const [dx, dz] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
      const nx = lx + dx, nz = lz + dz;
      if (nx < 0 || nz < 0 || nx >= span || nz >= span) continue;
      const nj = nz * span + nx;
      if (dist[nj] < 0) { dist[nj] = dist[li] + 1; queue.push(nj); }
    }
  }
  // the quays flat a step clear of the water, then the hill: two steps on a village, three on a town
  const flat = SEA + 1, top = p.kind === 'rural' ? 2 : 3, reach = S * 0.6;
  const ground = (d: number) => flat + top * Math.max(0, Math.min(1, (d - 3) / reach)) ** 1.2;
  p.level = flat;
  for (let z = z0; z < z0 + span; z++) for (let x = x0; x < x0 + span; x++) {
    if (!inB(x, z)) continue;
    const i = idx(x, z);
    if (!land[i] || want.has(i)) continue;
    const d = dist[(z - z0) * span + x - x0];
    const g = ground(d < 0 ? 99 : d);
    const out = Math.max(p.x0 - x, x - (p.x0 + S - 1), p.z0 - z, z - (p.z0 + S - 1), 0);
    if (out === 0) {
      E[i] = g;
      if (d <= 3) mask[i] = QUAY;
    } else if (w.biome[i] !== Biome.Town) { const t = 1 - out / (EASE + 1); E[i] = g * t + E[i] * (1 - t); }
  }
  // and the harbour cut into it, its sides quay walls
  for (const i of want) {
    land[i] = 0;
    river[i] = 0;
    w.biome[i] = Biome.Ocean;
    E[i] = SEA - GRAND_DEPTH;
    w.flags[i] |= Flag.Corridor;
    mask[i] = CANAL;
  }
  return true;
}
