/**
 * What grows in the fields. A field is cut into 4×4 patches, each one crop; the patch picks the
 * ground colour under it (render/mesher.ts) and the crop standing on it (render/props.ts) from the
 * same hash, so wheat stands on gold earth and maize on green. Paddies grow nothing that stands.
 *
 * 0.7.0 (NEXT_WORLD): now and then a whole field outside the biomes is one crop where the climate suits it
 * (`fieldPlan`): a maize field, a pumpkin patch, a Dutch bulb field striped in bands of colour, a flooded rice
 * paddy; and once in a while a big maize field has a maze cut through it, with a farm stand and hay bales by
 * the way in. Rolled from the field and its county, nothing in the world changes: only what grows and the
 * colour of the ground.
 */
import { N, DIRS, Flag, World, idx, inB } from './tiles';
import { hash2, mulberry32 } from './rng';
import { REGIONS, regionOf, type CropKind } from './regions';
import { RAIL_KEEP_CLEAR } from './fences';
import { NEXT_WORLD } from './nextWorld';

/** The ordinary crops, in the order of the ordinary crop colours: gold, green, yellow, brown. */
const CROP_KINDS: CropKind[] = ['wheat', 'maize', 'sunflower', 'pumpkin'];
const ORDINARY_PATCHES = CROP_KINDS.length;

/** Biomes whose fields are flooded rice terraces. */
export const PADDY_REGIONS = new Set(['terraces', 'fens', 'dragonbay', 'mangrove']);

/** Which of `count` crops a field's patch holds. */
export function cropPatch(x: number, z: number, fieldId: number, count: number): number {
  return Math.floor(hash2(Math.floor(x / 4), Math.floor(z / 4), 7 + fieldId) * count);
}

/** Which way a field's rows run: every tile of a field the same way, so the rows line up. */
export function cropYaw(fieldId: number): number {
  return hash2(fieldId, 3, 29) < 0.5 ? 0 : Math.PI / 2;
}

/** Which band of colour (TULIP_KINDS) a bulb field's tile is in: bands run along the rows, BAND tiles across. */
export function tulipBand(w: World, x: number, z: number): number {
  const id = w.fieldId[idx(x, z)];
  const across = cropYaw(id) === 0 ? z : x;
  return (Math.floor(across / BAND) + Math.floor(hash2(id, 9, 31) * TULIP_KINDS.length)) % TULIP_KINDS.length;
}

// ---------------------------------------------------------------------------------------------
// whole fields (0.7.0)

/** What a whole field is given over to: the ordinary patchwork, or one crop, or a maze cut in maize. */
export type FieldTheme = 'mixed' | 'maize' | 'pumpkin' | 'tulips' | 'rice' | 'oilPalm' | 'maze';
/** A Dutch bulb field's bands, in the order they repeat. */
export const TULIP_KINDS: CropKind[] = ['tulipRed', 'tulipYellow', 'tulipPink', 'tulipWhite', 'tulipPurple'];
/** How wide a bulb field's band of one colour is (tiles). */
const BAND = 3;
/**
 * The share of fields outside the biomes given over to one crop; which crop, by weight among those the field's
 * climate suits (each crop's band of w.temp; rice only warm and by water); and the share of big maize fields with a
 * maze cut in them.
 */
const THEMED = 0.3, MAZE_ODDS = 0.5, MAZE_MIN = 60;
// (w.temp runs warm: most farmland lies between 0.75 and 0.95; palms line a shore above 0.78, spruce grows under 0.3)
const THEMES: { theme: FieldTheme; weight: number; lo: number; hi: number; wet?: boolean }[] = [
  { theme: 'maize', weight: 0.35, lo: 0.3, hi: 0.95 },
  { theme: 'pumpkin', weight: 0.25, lo: 0.3, hi: 0.92 },
  { theme: 'tulips', weight: 0.25, lo: 0.3, hi: 0.9 },
  { theme: 'rice', weight: 0.3, lo: 0.8, hi: 1.01, wet: true },
  { theme: 'oilPalm', weight: 0.3, lo: 0.88, hi: 1.01 },
];
/** Does a crop's climate suit a field of this mean temperature, by water or not? */
export function themeFits(theme: FieldTheme, temp: number, wet: boolean): boolean {
  const t = THEMES.find((q) => q.theme === (theme === 'maze' ? 'maize' : theme));
  return !t || (temp > t.lo && temp < t.hi && (!t.wet || wet));
}

/**
 * A field's plan: its theme, and for a maze its paths, its way in and way out (tiles at the field's edge) and the
 * tile just outside the way in, where the farm stand stands.
 */
interface FieldPlan { theme: FieldTheme; tiles: number; paths?: Set<number>; entry?: number; out?: number; gate?: number }

const PLANS = new WeakMap<World, Map<number, FieldPlan>>();

/** The plan of field `id` in this county (worked out for all its fields the first time one is asked for). */
export function fieldPlan(w: World, id: number): FieldPlan {
  return plansOf(w).get(id) ?? MIXED;
}
/** Every field's plan in this county that is not the ordinary patchwork, by field id. */
export function plansOf(w: World): Map<number, FieldPlan> {
  let m = PLANS.get(w);
  if (!m) { m = planFields(w); PLANS.set(w, m); }
  return m;
}
const MIXED: FieldPlan = { theme: 'mixed', tiles: 0 };

function planFields(w: World): Map<number, FieldPlan> {
  const out = new Map<number, FieldPlan>();
  if (!NEXT_WORLD) return out;
  const byId = new Map<number, number[]>();
  for (let i = 0; i < N * N; i++) {
    if (!(w.flags[i] & Flag.Field)) continue;
    // a biome's fields grow the biome's own crops
    if (w.regionK[i] && w.regionW[i] > 128) continue;
    let l = byId.get(w.fieldId[i]);
    if (!l) { l = []; byId.set(w.fieldId[i], l); }
    l.push(i);
  }
  for (const [id, tiles] of byId) {
    let temp = 0, wet = false;
    for (const i of tiles) {
      temp += w.temp[i];
      const x = i % N, z = (i - x) / N;
      if (!wet) for (let dz = -6; dz <= 6 && !wet; dz += 3) for (let dx = -6; dx <= 6; dx += 3) {
        if (inB(x + dx, z + dz) && (w.flags[idx(x + dx, z + dz)] & (Flag.River | Flag.Stream) || w.water[idx(x + dx, z + dz)] >= 0)) { wet = true; break; }
      }
    }
    temp /= tiles.length;
    let theme: FieldTheme = 'mixed';
    const fit = THEMES.filter((t) => themeFits(t.theme, temp, wet));
    if (fit.length && hash2(id * 7 + 3, w.cx * 131 + w.cz * 977, 97) < THEMED) {
      let pick = hash2(id * 11 + 5, w.cx * 71 + w.cz * 389, 99) * fit.reduce((a, t) => a + t.weight, 0);
      for (const t of fit) { pick -= t.weight; if (pick < 0) { theme = t.theme; break; } }
      if (theme === 'mixed') theme = fit[fit.length - 1].theme;
    }
    const plan: FieldPlan = { theme, tiles: tiles.length };
    if (theme === 'maize' && tiles.length >= MAZE_MIN && hash2(id * 5 + 1, w.cx * 59 + w.cz * 313, 98) < MAZE_ODDS) cutMaze(w, tiles, plan, id);
    out.set(id, plan);
  }
  return out;
}

/**
 * A maze cut through a maize field: paths a tile wide between walls of standing maize, on the field's odd
 * tiles (a perfect maze, every path reaching every other one way only), with a way in from the field's edge
 * and a way out on the far side. Left ordinary maize if the field is too ragged for one.
 */
function cutMaze(w: World, tiles: number[], plan: FieldPlan, id: number): void {
  const field = new Set(tiles);
  let x0 = N, z0 = N;
  for (const i of tiles) { x0 = Math.min(x0, i % N); z0 = Math.min(z0, Math.floor(i / N)); }
  // the cells: field tiles an odd step from the corner, with the whole 3x3 round them in the field (the walls)
  const cell = (i: number) => {
    const x = i % N, z = (i - x) / N;
    if ((x - x0) % 2 !== 1 || (z - z0) % 2 !== 1) return false;
    for (let dz = -1; dz <= 1; dz++) for (let dx = -1; dx <= 1; dx++) if (!inB(x + dx, z + dz) || !field.has(idx(x + dx, z + dz))) return false;
    return true;
  };
  const cells = tiles.filter(cell);
  if (cells.length < 9) return;
  const rng = mulberry32((id * 2654435761) ^ (w.cx * 40503) ^ (w.cz * 97) ^ 0x6d617a65);
  const paths = new Set<number>();
  const seen = new Set<number>([cells[0]]);
  const stack = [cells[0]];
  paths.add(cells[0]);
  while (stack.length) {
    const c = stack[stack.length - 1], x = c % N, z = (c - x) / N;
    const next: number[] = [];
    for (const [dx, dz] of DIRS) {
      if (!inB(x + dx * 2, z + dz * 2)) continue;
      const n = idx(x + dx * 2, z + dz * 2);
      if (!seen.has(n) && cell(n)) next.push(n);
    }
    if (!next.length) { stack.pop(); continue; }
    const n = next[Math.floor(rng() * next.length)];
    paths.add(idx((x + (n % N)) / 2, (z + Math.floor(n / N)) / 2));
    paths.add(n);
    seen.add(n);
    stack.push(n);
  }
  // the way in and the way out: from the cells nearest two opposite edges of the field, straight out through its wall
  const door = (c: number): [number, number] | null => {
    const x = c % N, z = (c - x) / N;
    for (const [dx, dz] of DIRS) {
      const ox = x + dx * 2, oz = z + dz * 2;
      if (!inB(ox, oz) || field.has(idx(ox, oz))) continue;
      return [idx(x + dx, z + dz), idx(ox, oz)];
    }
    return null;
  };
  const edge = cells.filter((c) => door(c) !== null);
  if (edge.length < 2) return;
  const a = edge[Math.floor(rng() * edge.length)];
  let b = edge[0];
  for (const c of edge) if (Math.hypot((c % N) - (a % N), Math.floor(c / N) - Math.floor(a / N)) > Math.hypot((b % N) - (a % N), Math.floor(b / N) - Math.floor(a / N))) b = c;
  const [inDoor, gate] = door(a)!, [outDoor] = door(b)!;
  paths.add(inDoor);
  paths.add(outDoor);
  plan.theme = 'maze';
  plan.paths = paths;
  plan.entry = inDoor;
  plan.out = outDoor;
  plan.gate = gate;
}

/** The crop standing on tile (x, z), or null where nothing does. */
export function cropAt(w: World, x: number, z: number): CropKind | null {
  const i = idx(x, z);
  const fl = w.flags[i];
  if (!(fl & Flag.Field) || fl & (Flag.Track | Flag.Poi | Flag.Ramp)) return null;
  if (w.road[i] || w.cleared[i] || w.rail[i] & RAIL_KEEP_CLEAR || w.water[i] >= 0 || w.blocked[i]) return null;
  if (NEXT_WORLD) {
    const p = fieldPlan(w, w.fieldId[i]);
    switch (p.theme) {
      case 'maize': return 'maize';
      case 'pumpkin': return 'pumpkin';
      case 'rice': return 'rice';
      case 'oilPalm': return 'oilPalm';
      case 'tulips': return TULIP_KINDS[tulipBand(w, x, z)];
      case 'maze': return p.paths!.has(i) ? null : 'maize';
      default: break;
    }
  }
  const patch = cropPatch(x, z, w.fieldId[i], ORDINARY_PATCHES);
  if (w.regionK[i] && w.regionW[i] > 128) {
    const r = regionOf(w.regionK[i])!;
    if (PADDY_REGIONS.has(r.kind)) return null;
    if (r.crops && r.cropKinds) return r.cropKinds[patch % r.cropKinds.length];
  }
  return CROP_KINDS[patch];
}

// every biome that lists crop colours says what grows in them
for (const r of Object.values(REGIONS)) {
  if (r.crops && !PADDY_REGIONS.has(r.kind) && r.cropKinds?.length !== r.crops.length) throw new Error(`${r.kind}: cropKinds must match crops`);
}
