import type { KindSpec } from './townKinds';
import { Lot } from './tiles';
import { hashString } from './rng';
import type { Layout, TownPlan } from './towns';

/**
 * A lake town's own buildings (GEN 53, world/lakes.ts): what stands along the shore of every one (the steamer landing
 * the ferries call at, docks crowded with boats, two-storey boathouses, a bathing beach with its raft offshore), and
 * each flavour's: Okoboji's screened-porch cottages and the amusement park on the shore with its wooden coaster and
 * Ferris wheel; Geneva Lake's Gilded Age estates, their lawns running down to the shore path; Lac Léman's belle époque
 * palace hotels, the Jet d'Eau on its jetty, the flower clock and Chillon on its rock; Lake Como's pastel villas, the
 * terraced gardens of a Villa Carlotta and the lakeside church under its campanile. One table, spread into the game's
 * per-kind tables as world/onsenKinds.ts is; the models are in render/buildings/lake*.ts.
 */

export const LAKE_KINDS = [
  'steamerPier', 'lakeDock', 'lakeBoathouse', 'swimBeach', 'lakeCottage', 'amusementPark', 'lakeEstate', 'grandHotel',
  'jetDeau', 'flowerClock', 'chillon', 'comoVilla', 'villaGarden', 'lakeChurch',
] as const;

export type LakeKind = (typeof LAKE_KINDS)[number];

interface Info {
  label: string;
  icon: string;
  /** The lot in tiles: W across its front (a range rolled per building), D deep. */
  size: [number | [number, number], number];
  floors?: number | [number, number];
  /** How tall the model stands, in world units (towns.ts buildingHeight): per floor when it has floors. */
  h: number;
  /** What it costs to knock down (economy.ts), which sets a lot's floor price. */
  price: number;
  /** As an HQ (hqGrade.ts). */
  grade: 0 | 1 | 2 | 3 | 4 | 5;
  zone: KindSpec['zone'];
  lot: Lot;
  waterside?: KindSpec['waterside'];
  apart?: number;
  /** An open lot: a car may cross it (a landing's planks, the beach's sand). */
  open?: boolean;
  /** What kind of place a trip there is (game/traffic.ts TAG_OF). */
  tag: 'work' | 'leisure' | 'home' | 'dock';
}

