const pick = <T>(f: (i: Info) => T): Record<LakeKind, T> => Object.fromEntries(LAKE_KINDS.map((k) => [k, f(LAKE_INFO[k])])) as Record<LakeKind, T>;

/** Spread into townKinds' KIND_SPEC (only with NEXT_WORLD on). */
export const LAKE_SPEC = pick((i): KindSpec => ({
  w: i.size[0], d: i.size[1], zone: i.zone, lot: i.lot, gap: 0,
  ...(i.floors !== undefined ? { floors: i.floors } : {}),
  ...(i.waterside ? { waterside: i.waterside } : {}),
  ...(i.apart ? { apart: i.apart } : {}),
  ...(i.open ? { solid: false } : {}),
}));
/** How tall each stands (towns.ts buildingHeight). */
export function lakeHeight(kind: LakeKind, floors: number): number {
  const i = LAKE_INFO[kind];
  return i.floors !== undefined ? floors * 0.26 + i.h : i.h;
}
export const LAKE_PRICE = pick((i) => i.price);
export const LAKE_ICON = pick((i) => i.icon);
export const LAKE_LABEL = pick((i) => i.label);
export const LAKE_GRADE = pick((i) => i.grade);
/** The gallery's lot (dev/sizes.ts): the widest it rolls, and the most floors. */
export const LAKE_SIZE = pick((i): [number, number, number] => [typeof i.size[0] === 'number' ? i.size[0] : i.size[0][1], i.size[1], typeof i.floors === 'number' ? i.floors : i.floors?.[1] ?? 1]);
export const LAKE_TAG = pick((i) => i.tag);
export const isLakeKind = (k: string): k is LakeKind => k in LAKE_INFO;

/**
 * Where world/towns.ts calls out to the lake towns (world/lakes.ts fills it in when it is loaded, which
 * world/generate.ts does), so towns.ts needn't import them and they may import towns.ts. Only ever called with
 * NEXT_WORLD on.
 */
export const LAKE_HOOKS: { lay?: (c: Layout, p: TownPlan) => boolean } = {};

/** The real lake a lake town is modelled on (world/lakes.ts), in the order a plan's note keeps it. */
export const LAKE_FLAVOURS = ['okoboji', 'geneva', 'leman', 'como'] as const;
export type LakeFlavour = (typeof LAKE_FLAVOURS)[number];
export const LAKE_AFTER: Record<LakeFlavour, string> = {
  okoboji: 'West Okoboji, Iowa', geneva: 'Geneva Lake, Wisconsin', leman: 'Lac Léman', como: 'Lake Como',
};
/** The style each flavour's town is built in. */
export const LAKE_STYLE = { okoboji: 'lakeside', geneva: 'victorian', leman: 'leman', como: 'como' } as const satisfies Record<LakeFlavour, string>;

