export function lakeName(first: string, id: number, taken: Set<string>, flavour: number): string {
  const names = LAKE_NAMES[LAKE_FLAVOURS[flavour] ?? 'okoboji'];
  const h = hashString(`${first}#${id}#lake`) >>> 0;
  for (let k = 0; k < names.length; k++) {
    const name = names[(h + k) % names.length];
    if (!taken.has(name)) { taken.add(name); return name; }
  }
  return names[h % names.length];
}
