import {
  N, SEA, STEP, Biome, Flag, Lot, World, RoadType, DIRS, idx, inB, waterDepth,
  type Building, type BuildingKind, type Port, type Town, type TownKind,
} from './tiles';
import { findRoute, layGenerated, layRoad, resolveBridges, wetCost, type RouteCost } from './roads';
import { TOWN_MARGIN, buildingHeight, type TownPlan } from './towns';
import { solidMask } from './footprint';
import type { Rng } from './rng';

/**
 * Harbour footprint in the port's own frame: k counts tiles seaward from the root coast tile
 * (k <= 0 is the yard, k >= 1 is over water), j counts tiles to the left of the pier's centreline.
 */
interface Shape {
  pierLen: number; pierHalf: number;       // pier: k 1..pierLen, |j| <= pierHalf
  basinLen: number; basinHalf: number;     // dredged water: k 1..basinLen, |j| <= basinHalf
  yardDepth: number; yardHalf: number;     // yard: k -(yardDepth-1)..0, |j| <= yardHalf
  depth: number;                           // dredged depth in steps
}
/** Three-wide concrete pier; a container ship (Big Blue) berths along each side. */
const MAJOR: Shape = { pierLen: 6, pierHalf: 1, basinLen: 9, basinHalf: 4, yardDepth: 5, yardHalf: 4, depth: 4 };
/** One-wide wooden jetty with room for a speedboat or sailboat on each side. */
const MINOR: Shape = { pierLen: 3, pierHalf: 0, basinLen: 5, basinHalf: 2, yardDepth: 3, yardHalf: 2, depth: 2 };
/** Deck height of every quay and pier, in steps (one step above the sea). */
export const QUAY = SEA + 1;

interface PortPlan { major: boolean; x: number; z: number; d: number; town: number; channel: number[] }

const shapeOf = (p: PortPlan): Shape => (p.major ? MAJOR : MINOR);

/** World tile at k tiles seaward of the root and j tiles to the left. */
function cell(p: PortPlan, k: number, j: number): [number, number] {
  const [dx, dz] = DIRS[p.d];
  return [p.x + dx * k - dz * j, p.z + dz * k + dx * j];
}

type Part = 'yard' | 'pier' | 'basin';

function forCells(p: PortPlan, fn: (x: number, z: number, part: Part, k: number, j: number) => void): void {
  const s = shapeOf(p);
  for (let k = -(s.yardDepth - 1); k <= 0; k++) {
    for (let j = -s.yardHalf; j <= s.yardHalf; j++) { const [x, z] = cell(p, k, j); fn(x, z, 'yard', k, j); }
  }
  for (let k = 1; k <= s.basinLen; k++) {
    for (let j = -s.basinHalf; j <= s.basinHalf; j++) {
      const [x, z] = cell(p, k, j);
      fn(x, z, k <= s.pierLen && Math.abs(j) <= s.pierHalf ? 'pier' : 'basin', k, j);
    }
  }
}

/**
 * Two major ports near the cities and three minor docks near the suburb and rural town, on
 * straight-ish stretches of low coast. Chosen before tile corners exist, so the yard and pier are
 * raised into land and the basin is carved out of the sea bed in the elevation itself.
 */
export function planPorts(w: World, land: Uint8Array, river: Uint8Array, cliffBand: Uint8Array, towns: TownPlan[], rng: Rng, majors = 2, minors = 3, band = 0): PortPlan[] {
  const E = w.elev;
  const coast: number[] = [];
  for (let i = 0; i < N * N; i++) {
    if (!land[i] || w.coastDist[i] !== 1) continue;
    // a harbour raises a yard and dredges a basin: on a continent it keeps out of the seam band
    const x = i % N, z = (i - x) / N;
    if (band && (x < band + 12 || z < band + 12 || x >= N - band - 12 || z >= N - band - 12)) continue;
    coast.push(i);
  }
  // open sea: water that runs out to real ocean depth, rather than a lagoon a ship could never leave.
  // Seeded from the deep rather than from the cell edge, so a bay inside a coastal cell gets its dock.
  const open = new Uint8Array(N * N);
  const queue: number[] = [];
  for (let i = 0; i < N * N; i++) if (!land[i] && E[i] <= SEA - 3 && !open[i]) { open[i] = 1; queue.push(i); }
  for (let k = 0; k < N; k++) for (const i of [k, (N - 1) * N + k, k * N, k * N + N - 1]) if (!land[i] && !open[i]) { open[i] = 1; queue.push(i); }
  for (let h = 0; h < queue.length; h++) {
    const i = queue[h], x = i % N, z = (i - x) / N;
    for (let d = 0; d < 4; d++) {
      const nx = x + DIRS[d][0], nz = z + DIRS[d][1];
      if (nx < 0 || nz < 0 || nx >= N || nz >= N) continue;
      const j = idx(nx, nz);
      if (!land[j] && !open[j]) { open[j] = 1; queue.push(j); }
    }
  }
  const MAJOR_FOR: TownKind[][] = [['mega', 'metro'], ['city', 'mega'], ['suburb', 'metro']];
  const MINOR_FOR: TownKind[][] = [['suburb'], ['rural'], ['rural', 'suburb'], ['suburb', 'rural'], ['rural']];
  const wanted: [boolean, TownKind[]][] = [];
  for (let k = 0; k < majors; k++) wanted.push([true, MAJOR_FOR[k % MAJOR_FOR.length]]);
  for (let k = 0; k < minors; k++) wanted.push([false, MINOR_FOR[k % MINOR_FOR.length]]);
  const plans: PortPlan[] = [];

  for (const [major, kinds] of wanted) {
    const targets = kinds.map((k) => towns.findIndex((t) => t.kind === k)).filter((i) => i >= 0);
    const target = targets.length ? targets[Math.floor(rng() * targets.length)] : -1;
    const tp = target >= 0 ? towns[target] : null;
    const tx = tp ? tp.x0 + tp.size / 2 : N / 2, tz = tp ? tp.z0 + tp.size / 2 : N / 2;
    let best: PortPlan | null = null, bestScore = Infinity;
    for (const i of coast) {
      const x = i % N, z = (i - x) / N;
      for (let d = 0; d < 4; d++) {
        const sx = x + DIRS[d][0], sz = z + DIRS[d][1];
        if (sx < 0 || sz < 0 || sx >= N || sz >= N || !open[idx(sx, sz)]) continue;
        if (plans.some((q) => Math.hypot(q.x - x, q.z - z) < 40)) continue;
        const p: PortPlan = { major, x, z, d, town: target, channel: [] };
        const s = shapeOf(p);
        let ok = true, landInSea = 0, seaInYard = 0;
        forCells(p, (cx, cz, part) => {
          if (!ok) return;
          if (cx < 2 || cz < 2 || cx >= N - 2 || cz >= N - 2) { ok = false; return; }
          const c = idx(cx, cz);
          if (river[c] === 2 || cliffBand[c] || w.biome[c] === Biome.Town || w.biome[c] === Biome.Marsh || w.biome[c] === Biome.Mangrove) { ok = false; return; }
          for (const t of towns) {
            if (cx >= t.x0 - TOWN_MARGIN && cz >= t.z0 - TOWN_MARGIN && cx < t.x0 + t.size + TOWN_MARGIN && cz < t.z0 + t.size + TOWN_MARGIN) { ok = false; return; }
          }
          if (part === 'yard') {
            if (!land[c]) seaInYard++;
            else if (E[c] > SEA + 4) ok = false;
          } else if (land[c]) landInSea++;
        });
        const yardArea = s.yardDepth * (2 * s.yardHalf + 1);
        if (!ok || landInSea > (major ? 6 : 3) || seaInYard > yardArea / 3) continue;
        const score = Math.hypot(x - tx, z - tz) + landInSea * 3 + seaInYard * 2 + rng() * 6;
        if (score < bestScore) { bestScore = score; best = p; }
      }
    }
    if (!best) continue;
    plans.push(best);
    const s = shapeOf(best);
    forCells(best, (cx, cz, part) => {
      const c = idx(cx, cz);
      river[c] = 0;
      if (part === 'basin') {
        land[c] = 0;
        w.biome[c] = Biome.Ocean;
        E[c] = Math.min(E[c], SEA - s.depth);
      } else {
        land[c] = 1;
        w.biome[c] = Biome.Town;
        E[c] = QUAY;
      }
    });
    // a channel from the basin mouth, by the shortest way through open water, out to sea bed that is
    // deep enough on its own (bays and shoals would otherwise trap a ship at its berth), dug three wide
    const [mx, mz] = cell(best, s.basinLen, 0);
    const start = idx(mx, mz), deepE = SEA - s.depth - 1;
    const prev = new Int32Array(N * N).fill(-2);
    prev[start] = -1;
    const queue = [start];
    let goal = -1;
    for (let h = 0; h < queue.length && goal < 0; h++) {
      const i = queue[h], x = i % N, z = (i - x) / N;
      if (i !== start && E[i] <= deepE) { goal = i; break; }
      for (let d2 = 0; d2 < 4; d2++) {
        const nx = x + DIRS[d2][0], nz = z + DIRS[d2][1];
        if (nx < 1 || nz < 1 || nx >= N - 1 || nz >= N - 1) continue;
        const j = idx(nx, nz);
        if (prev[j] !== -2 || land[j]) continue;
        prev[j] = i;
        queue.push(j);
      }
    }
    for (let i = goal; i >= 0; i = prev[i]) {
      const x = i % N, z = (i - x) / N;
      for (let dz = -1; dz <= 1; dz++) {
        for (let dx = -1; dx <= 1; dx++) {
          const c = idx(x + dx, z + dz);
          if (!land[c] && E[c] > SEA - s.depth) { E[c] = SEA - s.depth; best.channel.push(c); }
        }
      }
    }
  }
  return plans;
}

/**
 * After tile corners are built: set the yard and pier flat at quay height and dredge the basin.
 * Returns a mask of port tiles so the legaliser treats their edges as walls (quay faces).
 */
export function shapePorts(w: World, plans: PortPlan[]): Uint8Array {
  const mask = new Uint8Array(N * N);
  const c = w.corners;
  for (const p of plans) {
    const s = shapeOf(p);
    forCells(p, (x, z, part) => {
      const i = idx(x, z), b = i * 4;
      mask[i] = 1;
      w.flags[i] &= ~(Flag.River | Flag.Stream | Flag.Field | Flag.Track);
      for (let q = 0; q < 4; q++) c[b + q] = part === 'basin' ? Math.min(c[b + q], SEA - s.depth) : QUAY;
    });
    for (const i of p.channel) {
      mask[i] = 1;
      for (let q = 0; q < 4; q++) c[i * 4 + q] = Math.min(c[i * 4 + q], SEA - s.depth);
    }
  }
  return mask;
}

/** Ordinary road over land; a little happier to wind than to climb. */
const PORT_ROAD: RouteCost = { climb: 3, slope: 1, turn: 0.4, reuse: 0.6, crowd: 0 };

function nearestTownRoad(w: World, from: number, town: Town | undefined): number {
  const fx = from % N, fz = (from - fx) / N;
  let best = -1, bestD = Infinity;
  for (const t of town ? [town] : w.towns) {
    for (let z = t.z0; z < t.z0 + t.size; z++) {
      for (let x = t.x0; x < t.x0 + t.size; x++) {
        const i = idx(x, z);
        if (!w.road[i] || w.blocked[i]) continue;
        const d = Math.hypot(x - fx, z - fz);
        if (d < bestD) { bestD = d; best = i; }
      }
    }
  }
  return best;
}

/**
 * Make sure a boat needing `need` steps of water can get from the berths to the open sea: find the
 * cheapest water route out (existing deep water is nearly free, shallows cost a lot) and dredge
 * only the shallow tiles along it, three wide, down to `depth`.
 */
function dredgeToSea(w: World, port: Port, need: number, depth: number): void {
  const [b] = berths(port, 0.3);
  const start = idx(Math.floor(b.x), Math.floor(b.z));
  if (w.water[start] !== SEA) return;
  const dist = new Int32Array(N * N).fill(1 << 30);
  const prev = new Int32Array(N * N).fill(-1);
  const buckets: number[][] = [[start]];
  dist[start] = 0;
  let goal = -1;
  for (let cost = 0; cost < buckets.length && goal < 0; cost++) {
    const bucket = buckets[cost];
    if (!bucket) continue;
    for (const i of bucket) {
      if (dist[i] !== cost) continue;
      const x = i % N, z = (i - x) / N;
      if (x < 4 || z < 4 || x >= N - 4 || z >= N - 4) { goal = i; break; }
      for (let d = 0; d < 4; d++) {
        const j = idx(x + DIRS[d][0], z + DIRS[d][1]);
        if (w.water[j] !== SEA) continue;
        const nd = cost + 1 + Math.max(0, need - waterDepth(w, j)) * 20;
        if (nd < dist[j]) { dist[j] = nd; prev[j] = i; (buckets[nd] ??= []).push(j); }
      }
    }
  }
  const c = w.corners;
  for (let i = goal; i >= 0; i = prev[i]) {
    const x = i % N, z = (i - x) / N;
    for (let dz = -1; dz <= 1; dz++) {
      for (let dx = -1; dx <= 1; dx++) {
        const t = idx(x + dx, z + dz);
        if (w.water[t] !== SEA || waterDepth(w, t) >= need) continue;
        // a road on a bank level with the sea stays put: dug out, it would leave a bridge's
        // abutment two steps below the deck it was meant to meet
        if (w.road[t] && !w.deckAxis[t]) continue;
        for (let q = 0; q < 4; q++) c[t * 4 + q] = Math.min(c[t * 4 + q], SEA - depth);
      }
    }
  }
}

function portName(major: boolean, town: Town | undefined, rng: Rng): string {
  const pick = (a: string[]) => a[Math.floor(rng() * a.length)];
  const skip = new Set(['New', 'Grand', 'Great', 'Old', 'Port', 'Fort', 'Mount', 'East', 'Lake', 'St.', 'City']);
  const base = town ? (town.name.split(' ').find((word) => !skip.has(word)) ?? town.name) : pick(['Driftwood', 'Saltmarsh', 'Gull', 'Anchor', 'Kelp']);
  return major ? `Port of ${base}` : `${base} ${pick(['Marina', 'Landing', 'Wharf', 'Quay'])}`;
}

/**
 * Claim (Flag.Poi) the lots of a harbour's yard buildings before any road is routed, so no county road or
 * town street runs under a warehouse, a container stack or a boathouse (the user, 7 Oct 2026). Mirrors the
 * `put`s in buildPorts, both choices of each roll included: change one, change the other. The yard's own
 * road runs down its middle (j = 0), which nothing here claims.
 */
export function reservePorts(w: World, plans: PortPlan[]): void {
  const MAJOR_LOTS: [number, number, number, number][] = [[-3, -1, -4, -2], [-3, -1, 2, 4], [-4, -4, -4, -4], [-4, -2, 2, 4]];
  const MINOR_LOTS: [number, number, number, number][] = [[-2, -1, -2, -1], [-1, -1, 1, 1], [-3, -2, 1, 3]];
  for (const p of plans) {
    for (const [k0, k1, j0, j1] of p.major ? MAJOR_LOTS : MINOR_LOTS) {
      for (let k = k0; k <= k1; k++) for (let j = j0; j <= j1; j++) {
        const [x, z] = cell(p, k, j);
        if (inB(x, z)) w.flags[idx(x, z)] |= Flag.Poi;
      }
    }
  }
}

/** Yard buildings, pier fittings, a road down the yard and one inland to the town it serves. */
export function buildPorts(w: World, plans: PortPlan[], rng: Rng): void {
  plans.forEach((p, id) => {
    const s = shapeOf(p);
    const town = w.towns.find((t) => t.id === p.town);
    const [ax, az] = cell(p, -Math.floor(s.yardDepth / 2), 0);
    const [ex, ez] = cell(p, -(s.yardDepth - 1), 0);
    const port: Port = {
      id, major: p.major, name: portName(p.major, town, rng), x: ax + 0.5, z: az + 0.5, level: QUAY,
      buildings: [], town: town ? town.id : -1, entry: idx(ex, ez), root: idx(p.x, p.z), dir: p.d,
    };
    w.ports.push(port);
    forCells(p, (x, z, part, k) => {
      const i = idx(x, z);
      w.portId[i] = id;
      if (part === 'basin') return;
      w.lot[i] = p.major ? (part === 'pier' || k === 0 ? Lot.Paved : Lot.Asphalt) : (part === 'pier' || k === 0 ? Lot.Deck : Lot.Yard);
    });

    const seaward = p.d, left = (p.d + 1) & 3, right = (p.d + 3) & 3;
    const put = (kind: BuildingKind, k0: number, k1: number, j0: number, j1: number, facing: number, solid: boolean, floors = 1) => {
      const [x0, z0] = cell(p, k0, j0), [x1, z1] = cell(p, k1, j1);
      const b: Building = {
        kind, x: Math.min(x0, x1), z: Math.min(z0, z1), w: Math.abs(x1 - x0) + 1, d: Math.abs(z1 - z0) + 1,
        facing, floors, seed: Math.floor(rng() * 2 ** 31), solid, level: QUAY, uid: w.allBuildings.length,
      };
      w.allBuildings.push(b);
      const top = QUAY * STEP + buildingHeight(b);
      const mask = solid ? solidMask(b) : null;
      for (let z = b.z; z < b.z + b.d; z++) {
        for (let x = b.x; x < b.x + b.w; x++) {
          const i = idx(x, z);
          const blocks = !!mask && !!mask[(z - b.z) * b.w + x - b.x];
          if (blocks) w.blocked[i] = 1;
          if (blocks || kind === 'crane') w.roof[i] = Math.max(w.roof[i], top);
        }
      }
      port.buildings.push(b);
    };

    if (p.major) {
      put('pier', 1, s.pierLen, -1, 1, seaward, false);
      put('quay', 0, 0, -s.yardHalf, s.yardHalf, seaward, false);
      put('crane', 2, 2, -1, 1, seaward, false);
      put('crane', 5, 5, -1, 1, seaward, false);
      put('containers', -3, -1, -4, -2, left, true);
      put('warehouse', -3, -1, 2, 4, right, true);
      put('harbourOffice', -4, -4, -4, -4, left, true, 2);
      // a working harbour in three has a dry dock cut into the far side of its yard
      if (rng() < 0.34) put('dryDock', -4, -2, 2, 4, right, true);
      // the Guild's lifeboat at one harbour in three of the rest (docs/factions.html)
      else if (rng() < 0.35) put('lifeboatStation', -4, -3, 2, 3, right, true);
      else put('containers', -4, -4, 2, 4, right, true);
    } else {
      put('pier', 1, s.pierLen, 0, 0, seaward, false);
      put('boathouse', -2, -1, -2, -1, seaward, true);
      put('shack', -1, -1, 1, 1, right, true);
      // half the fishing harbours land their catch straight into a cannery on the quay
      if (rng() < 0.5) put('cannery', -3, -2, 1, 3, right, true);
      // or the Guild's fish market on the quay (docs/factions.html)
      else if (rng() < 0.6) put('fishMarket', -3, -2, 1, 3, right, true);
      else put('crates', -2, -2, 2, 2, right, true);
    }

    dredgeToSea(w, port, p.major ? 3 : 2, s.depth);

    // down the yard (and along a major pier), then inland to the nearest street of its town
    const type = p.major ? RoadType.TwoLane : RoadType.Paved;
    const [tx, tz] = cell(p, p.major ? s.pierLen : 0, 0);
    const lo = (a: number, b: number) => Math.min(a, b) - 1, hi = (a: number, b: number) => Math.max(a, b) + 2;
    const yard = findRoute(w, idx(tx, tz), port.entry, false, [lo(tx, ex), lo(tz, ez), hi(tx, ex), hi(tz, ez)], PORT_ROAD, 0, wetCost(type));
    if (yard && yard.nodes.length >= 2) layRoad(w, type, yard.nodes, -1);
    const target = nearestTownRoad(w, port.entry, town);
    if (target >= 0) {
      const gx = target % N, gz = (target - gx) / N, pad = 16;
      const path = findRoute(w, port.entry, target, false, [Math.min(ex, gx) - pad, Math.min(ez, gz) - pad, Math.max(ex, gx) + pad + 1, Math.max(ez, gz) + pad + 1], PORT_ROAD, 10, wetCost(type));
      if (path && path.nodes.length >= 2) layGenerated(w, type, path.nodes, -1, resolveBridges(w, type, path.nodes, path.bridges));
    }
  });
}

/** Where a boat of this width moors: centre and heading of the berth on each side of a port's pier. */
export function berths(p: Port, halfWid: number): { x: number; z: number; heading: number }[] {
  const s = p.major ? MAJOR : MINOR;
  const [dx, dz] = DIRS[p.dir];
  const rx = p.root % N, rz = (p.root - rx) / N;
  const along = (1 + s.pierLen) / 2, off = s.pierHalf + 0.5 + halfWid + 0.09;
  const cx = rx + 0.5 + dx * along, cz = rz + 0.5 + dz * along;
  return [1, -1].map((side) => ({ x: cx - dz * off * side, z: cz + dx * off * side, heading: Math.atan2(dx, dz) }));
}
