/**
 * A biome's wonder: the one building half its cells get, so two islands of the same biome are not
 * the same island. The pyramid on flat sand, the temple lost in the forest, the dam across a
 * valley, the pier out to sea, the castle on its crag, the temple at the end of a cape.
 *
 * Like a quarry or an airfield it is carved while the elevation field is still floats, and stood up
 * afterwards by buildWorks as a Work of kind 'wonder', so linkWorks runs a road to its gate.
 */
import { N, SEA, Biome, DIRS, Flag, Lot, World, idx, inB, type BuildingKind } from './tiles';
import type { RegionSpec } from './regions';
import type { WorkSite } from './industry';
import type { Rng } from './rng';
import { ANCIENT_INFO, ANCIENT_KINDS, HARBOUR, harbourLand, type AncientKind } from './ancientKinds';

/** Whatever has a wonder to place: a biome, or an ordinary island's castle. */
type Wonderful = Pick<RegionSpec, 'wonder'>;

/**
 * The wonder of an ordinary island (docs: README, Architecture): a moated castle out in the fields,
 * on one cell in five that belongs to no biome.
 */
const CASTLE: Wonderful = {
  wonder: {
    kind: 'moatedCastle', w: 14, d: 14, where: 'flat',
    name: ['Castle Ravensmoat', 'Moatbury Castle', 'Castle Aldermere', 'Kingsmere Castle', 'Castle Wyvernhold', 'Castle Greywater', 'Castle '],
  },
};

/** The gurdwara in its pool: gold on the water, out where the fields give it room. */
const GOLDEN_TEMPLE: Wonderful = {
  wonder: {
    kind: 'goldenTemple', w: 14, d: 14, where: 'flat',
    name: ['The Golden Temple', 'Amritsar Sahib', 'The Gurdwara of the Pool', 'Harmandir', 'The Golden Temple of '],
  },
};

/** A spaceport out on the flattest ground the county has, with a stage on the pad and the count running. */
export const SPACEPORT: Wonderful = {
  wonder: {
    kind: 'launchPad', w: 14, d: 14, where: 'flat',
    name: ['Kestrel Launch Complex', 'Cape Meridian Spaceport', 'Pad 39', 'The Launch Site', 'Spaceport '],
  },
};

/** An ordinary island's three wonders, in the order a hashed roll walks them. */
export const ISLAND_WONDERS: Wonderful[] = [CASTLE, CASTLE, GOLDEN_TEMPLE, SPACEPORT];

/**
 * The six ancient wonders beside the pyramid (world/ancientKinds.ts, GEN 53): the Colossus astride its own
 * harbour's mouth, the Pharos out on a headland, the gardens, the two temples and the tomb on open ground.
 */
export const ANCIENT_WONDERS = Object.fromEntries(ANCIENT_KINDS.map((kind): [AncientKind, Wonderful] => {
  const i = ANCIENT_INFO[kind];
  return [kind, { wonder: { kind, w: i.size[0], d: i.size[1], where: i.where, name: i.names } }];
})) as Record<AncientKind, Wonderful>;

/** Keep a wonder this far from any town's ground. */
const TOWN_CLEAR: Partial<Record<BuildingKind, number>> = {
  ...Object.fromEntries(ANCIENT_KINDS.map((k) => [k, ANCIENT_INFO[k].clear])),
  pyramid: 60, lostTemple: 50, greatKopje: 30, plantationManor: 16, capeTemple: 12, moatedCastle: 14, mission: 12,
  // the pad wants room round it, the gurdwara only enough to sit apart from the streets
  launchPad: 22, goldenTemple: 16,
  greatGeyser: 16, giantTree: 14, monumentButtes: 24, khanStatue: 20, speedStrip: 14, lavenderAbbey: 12,
};

/** The ground finish a wonder's lot is laid in. */
const FINISH: Partial<Record<BuildingKind, Lot>> = {
  ...Object.fromEntries(ANCIENT_KINDS.map((k) => [k, ANCIENT_INFO[k].lot])),
  pyramid: Lot.Sand, lostTemple: Lot.Gravel, greatKopje: Lot.Yard, plantationManor: Lot.Lawn, iceHotel: Lot.Gravel,
  pleasurePier: Lot.Deck, dam: Lot.Paved, castle: Lot.Gravel, hilltopCastle: Lot.Gravel, capeTemple: Lot.Gravel, moatedCastle: Lot.Lawn, mission: Lot.Yard,
  goldenTemple: Lot.Plaza, launchPad: Lot.Gravel,
  greatGeyser: Lot.Gravel, arcticCathedral: Lot.Paved, giantTree: Lot.Park, monumentButtes: Lot.Sand, cloudTemple: Lot.Gravel,
  khanStatue: Lot.Paved, speedStrip: Lot.Sand, floatingMarket: Lot.Deck, lavenderAbbey: Lot.Yard,
};

interface Ctx {
  w: World; land: Uint8Array; E: Float32Array; river: Uint8Array; lakeLvl: Int8Array; rng: Rng; band: number;
}

/** Mean and spread of the ground over a rectangle, or null if any of it is unusable. */
function survey(c: Ctx, x0: number, z0: number, wx: number, wz: number, lo: number): { mean: number; spread: number; min: number; max: number } | null {
  let min = Infinity, max = -Infinity, sum = 0;
  for (let z = z0; z < z0 + wz; z++) {
    for (let x = x0; x < x0 + wx; x++) {
      if (x < lo || z < lo || x >= N - lo || z >= N - lo) return null;
      const i = idx(x, z);
      if (!c.land[i] || c.river[i] || c.lakeLvl[i] > -128 || c.w.biome[i] === Biome.Town || c.w.feature[i]) return null;
      if (c.w.flags[i] & (Flag.Field | Flag.Corridor)) return null;
      const e = c.E[i];
      if (e < min) min = e;
      if (e > max) max = e;
      sum += e;
    }
  }
  return { mean: sum / (wx * wz), spread: max - min, min, max };
}

/** The nearest town ground to a point, in tiles, looked for no further than `r`. */
function townNear(c: Ctx, x: number, z: number, r: number): number {
  let best = Infinity;
  for (const t of c.w.towns) best = Math.min(best, Math.max(0, Math.abs(x - (t.x0 + t.size / 2)) - t.size / 2, Math.abs(z - (t.z0 + t.size / 2)) - t.size / 2));
  if (best <= r) return best;
  // towns are not built yet at this stage: their pads are already town ground, so look for that
  const step = 3;
  for (let dz = -r; dz <= r; dz += step) {
    for (let dx = -r; dx <= r; dx += step) {
      const tx = x + dx, tz = z + dz;
      if (!inB(tx, tz) || c.w.biome[idx(tx, tz)] !== Biome.Town) continue;
      best = Math.min(best, Math.hypot(dx, dz));
    }
  }
  return best;
}

/** Flatten a rectangle to one level, easing the ground around it over a skirt. */
function level(c: Ctx, x0: number, z0: number, wx: number, wz: number, lv: number, skirt: number): void {
  for (let z = z0 - skirt; z < z0 + wz + skirt; z++) {
    for (let x = x0 - skirt; x < x0 + wx + skirt; x++) {
      if (!inB(x, z)) continue;
      const i = idx(x, z);
      if (!c.land[i] || c.w.biome[i] === Biome.Town) continue;
      const out = Math.max(0, x0 - x, x - (x0 + wx - 1), z0 - z, z - (z0 + wz - 1));
      if (out === 0) c.E[i] = lv;
      else c.E[i] += (lv - c.E[i]) * (1 - out / (skirt + 1));
    }
  }
}

/** Mark the lot as the wonder's ground: cleared of trees, finished, nothing else may build there. */
function claim(c: Ctx, kind: BuildingKind, x0: number, z0: number, wx: number, wz: number): void {
  for (let z = z0; z < z0 + wz; z++) {
    for (let x = x0; x < x0 + wx; x++) {
      const i = idx(x, z);
      c.w.biome[i] = Biome.Town;
      c.w.lot[i] = FINISH[kind] ?? Lot.Gravel;
      c.w.cleared[i] = 1;
      c.river[i] = 0;
    }
  }
}

/** Which way from (x, z) the island's middle lies, as a DIRS index. */
function inward(x: number, z: number): number {
  const dx = N / 2 - x, dz = N / 2 - z;
  return Math.abs(dx) > Math.abs(dz) ? (dx > 0 ? 0 : 2) : dz > 0 ? 1 : 3;
}

function site(kind: BuildingKind, name: string, x0: number, z0: number, wx: number, wz: number, lv: number, facing: number): WorkSite {
  const cx = x0 + wx / 2, cz = z0 + wz / 2;
  const [fx, fz] = DIRS[facing];
  const reach = (facing % 2 === 0 ? wx : wz) / 2 + 1;
  const gx = Math.max(0, Math.min(N - 1, Math.floor(cx + fx * reach))), gz = Math.max(0, Math.min(N - 1, Math.floor(cz + fz * reach)));
  return {
    kind: 'wonder', name, x: Math.floor(cx), z: Math.floor(cz), level: lv, facing, major: true,
    len: Math.max(wx, wz), half: Math.min(wx, wz) / 2, cable: [], gate: idx(gx, gz),
    lot: { kind, x: x0, z: z0, w: wx, d: wz },
  };
}

/** A lot of the given size facing `facing`: across the front is W, deep is D. */
const dims = (W: number, D: number, facing: number): [number, number] => (facing % 2 === 1 ? [W, D] : [D, W]);

/** Flat, dry ground well away from the towns: the pyramid, the lost temple, the kopje, the manor. */
function onFlat(c: Ctx, spec: Wonderful, name: string, loose = 1): WorkSite | null {
  const { kind, w: W, d: D } = spec.wonder;
  const lo = c.band + 10;
  const clear = (TOWN_CLEAR[kind] ?? 12) / loose;
  const rough = (kind === 'lostTemple' || kind === 'greatKopje' ? 6 : 3.5) * loose;
  let best: { x: number; z: number; f: number; lv: number; score: number } | null = null;
  for (let t = 0; t < 700; t++) {
    const f = Math.floor(c.rng() * 4);
    const [wx, wz] = dims(W, D, f);
    const x0 = lo + Math.floor(c.rng() * Math.max(1, N - 2 * lo - wx)), z0 = lo + Math.floor(c.rng() * Math.max(1, N - 2 * lo - wz));
    const s = survey(c, x0 - 3, z0 - 3, wx + 6, wz + 6, lo);
    if (!s || s.spread > rough || s.mean < SEA + 1.5) continue;
    const tn = townNear(c, x0 + wx / 2, z0 + wz / 2, clear + 20);
    if (tn < clear) continue;
    // as near the towns as it is allowed to be, so it is a trip rather than an expedition
    const score = s.spread + Math.min(40, tn - clear) * 0.05 + c.rng() * 0.5;
    if (!best || score < best.score) best = { x: x0, z: z0, f: inward(x0 + wx / 2, z0 + wz / 2), lv: Math.round(s.mean), score };
  }
  if (!best) return null;
  const [wx, wz] = dims(W, D, best.f);
  level(c, best.x, best.z, wx, wz, best.lv, 5);
  claim(c, kind, best.x, best.z, wx, wz);
  return site(kind, name, best.x, best.z, wx, wz, best.lv, best.f);
}

/** High ground: the castle on its crag (near a lake if it can), the hilltop castle near the city. */
function onHigh(c: Ctx, spec: Wonderful, name: string): WorkSite | null {
  const { kind, w: W, d: D } = spec.wonder;
  const lo = c.band + 10;
  const city = [...c.w.towns].sort((a, b) => b.size - a.size)[0];
  let best: { x: number; z: number; lv: number; score: number } | null = null;
  for (let t = 0; t < 900; t++) {
    const x0 = lo + Math.floor(c.rng() * Math.max(1, N - 2 * lo - W)), z0 = lo + Math.floor(c.rng() * Math.max(1, N - 2 * lo - D));
    const s = survey(c, x0, z0, W, D, lo);
    if (!s || s.spread > 5) continue;
    const cx = x0 + W / 2, cz = z0 + D / 2;
    if (townNear(c, cx, cz, 14) < 8) continue;
    let score = -s.mean * 1.5 + s.spread;
    if (kind === 'hilltopCastle' && city) score += Math.max(0, Math.hypot(city.x0 + city.size / 2 - cx, city.z0 + city.size / 2 - cz) - city.size) * 0.12;
    if (kind === 'castle') {
      let lake = 99;
      for (let dz = -24; dz <= 24; dz += 3) for (let dx = -24; dx <= 24; dx += 3) {
        const x = Math.floor(cx + dx), z = Math.floor(cz + dz);
        if (inB(x, z) && c.lakeLvl[idx(x, z)] > -128) lake = Math.min(lake, Math.hypot(dx, dz));
      }
      score += Math.min(lake, 40) * 0.15;
    }
    if (!best || score < best.score) best = { x: x0, z: z0, lv: Math.round(s.mean), score };
  }
  if (!best) return null;
  level(c, best.x, best.z, W, D, best.lv, 4);
  claim(c, kind, best.x, best.z, W, D);
  return site(kind, name, best.x, best.z, W, D, best.lv, inward(best.x + W / 2, best.z + D / 2));
}

/** Beside a lake, or failing one the sea: the ice hotel. */
function byLake(c: Ctx, spec: Wonderful, name: string): WorkSite | null {
  const { kind, w: W, d: D } = spec.wonder;
  const lo = c.band + 10;
  let best: { x: number; z: number; lv: number; score: number } | null = null;
  for (let t = 0; t < 900; t++) {
    const x0 = lo + Math.floor(c.rng() * Math.max(1, N - 2 * lo - W)), z0 = lo + Math.floor(c.rng() * Math.max(1, N - 2 * lo - D));
    const s = survey(c, x0, z0, W, D, lo);
    if (!s || s.spread > 3 || s.mean < SEA + 1) continue;
    let lake = 99, sea = 99;
    for (let dz = -6; dz < D + 6; dz++) for (let dx = -6; dx < W + 6; dx++) {
      const x = x0 + dx, z = z0 + dz;
      if (!inB(x, z)) continue;
      const i = idx(x, z);
      const out = Math.max(-dx, dx - W + 1, -dz, dz - D + 1, 0);
      if (c.lakeLvl[i] > -128) lake = Math.min(lake, out);
      if (!c.land[i]) sea = Math.min(sea, out);
    }
    if (Math.min(lake, sea + 2) > 6) continue;
    if (townNear(c, x0 + W / 2, z0 + D / 2, 12) < 6) continue;
    const score = Math.min(lake, sea + 2) + s.spread + c.rng();
    if (!best || score < best.score) best = { x: x0, z: z0, lv: Math.round(s.mean), score };
  }
  if (!best) return null;
  level(c, best.x, best.z, W, D, best.lv, 3);
  claim(c, kind, best.x, best.z, W, D);
  return site(kind, name, best.x, best.z, W, D, best.lv, inward(best.x + W / 2, best.z + D / 2));
}

/**
 * The pleasure pier: a straight run of coast with open water in front of it. The strip out to sea
 * is raised into land at deck height, walled like a causeway, so the pier is ground the car drives.
 */
function pier(c: Ctx, spec: Wonderful, name: string): { site: WorkSite; moved: boolean } | null {
  const { kind, w: W, d: D } = spec.wonder;
  const inland = 5, out = D - inland;
  const lo = c.band + 12;
  let best: { x: number; z: number; d: number; score: number } | null = null;
  const coast: number[] = [];
  for (let i = 0; i < N * N; i++) if (c.land[i] && c.w.coastDist[i] === 1 && !c.river[i]) coast.push(i);
  for (let t = 0; t < 900 && coast.length; t++) {
    const i = coast[Math.floor(c.rng() * coast.length)];
    const x = i % N, z = (i - x) / N;
    for (let d = 0; d < 4; d++) {
      const [dx, dz] = DIRS[d];
      const px = -dz, pz = dx;      // across the pier
      let ok = true;
      for (let k = -inland + 1; k <= out && ok; k++) {
        for (let o = -(W >> 1); o <= W >> 1 && ok; o++) {
          const tx = x + dx * k + px * o, tz = z + dz * k + pz * o;
          if (tx < lo || tz < lo || tx >= N - lo || tz >= N - lo) { ok = false; break; }
          const j = idx(tx, tz);
          if (k <= 0) ok = !!c.land[j] && c.w.biome[j] !== Biome.Town && Math.abs(c.E[j] - SEA - 1) < 2.5 && !c.river[j];
          else ok = !c.land[j] && c.E[j] < SEA;
        }
      }
      // nothing solid for a few tiles either side of the seaward run, so it stands clear of the shore
      for (let k = 2; k <= out && ok; k += 2) {
        for (const o of [-(W >> 1) - 2, (W >> 1) + 2]) {
          const tx = x + dx * k + px * o, tz = z + dz * k + pz * o;
          if (!inB(tx, tz) || c.land[idx(tx, tz)]) ok = false;
        }
      }
      if (!ok) continue;
      const score = Math.min(60, townNear(c, x, z, 60)) + c.rng() * 4;
      if (!best || score < best.score) best = { x, z, d, score };
    }
  }
  if (!best) return null;
  const [dx, dz] = DIRS[best.d];
  const px = -dz, pz = dx;
  let x0 = N, z0 = N, x1 = -1, z1 = -1;
  for (let k = -inland + 1; k <= out; k++) {
    for (let o = -(W >> 1); o <= W >> 1; o++) {
      const tx = best.x + dx * k + px * o, tz = best.z + dz * k + pz * o;
      const j = idx(tx, tz);
      c.land[j] = 1;
      c.E[j] = SEA + 1;
      // the seaward run is a causeway: its sides are walls into the water, not a slope
      if (k > 0) c.w.flags[j] |= Flag.Corridor;
      x0 = Math.min(x0, tx); z0 = Math.min(z0, tz); x1 = Math.max(x1, tx); z1 = Math.max(z1, tz);
    }
  }
  const wx = x1 - x0 + 1, wz = z1 - z0 + 1;
  claim(c, kind, x0, z0, wx, wz);
  // its gate is at the landward end, not in front of it (the front is the sea)
  const s = site(kind, name, x0, z0, wx, wz, SEA + 1, best.d);
  const gx = best.x - dx * inland, gz = best.z - dz * inland;
  if (inB(gx, gz)) s.gate = idx(gx, gz);
  return { site: s, moved: true };
}

/**
 * The Colossus's harbour: a straight run of low coast with open sea in front, where two moles are built out and
 * turned in toward each other at their heads (ancientKinds.ts HARBOUR). As with the pier, the quay and the moles
 * are raised to deck height and walled into the water; the basin and the mouth between the heads stay sea, and
 * the statue stands astride the mouth with a foot on each head.
 */
function harbour(c: Ctx, spec: Wonderful, name: string): { site: WorkSite; moved: boolean } | null {
  const { kind, w: W, d: D } = spec.wonder;
  const { inland } = HARBOUR, out = D - inland, half = W >> 1;
  const lo = c.band + 12;
  let best: { x: number; z: number; d: number; score: number } | null = null;
  const coast: number[] = [];
  for (let i = 0; i < N * N; i++) if (c.land[i] && c.w.coastDist[i] === 1 && !c.river[i]) coast.push(i);
  for (let t = 0; t < 1400 && coast.length; t++) {
    const i = coast[Math.floor(c.rng() * coast.length)];
    const x = i % N, z = (i - x) / N;
    for (let d = 0; d < 4; d++) {
      const [dx, dz] = DIRS[d];
      const px = -dz, pz = dx;      // across the harbour
      let ok = true, wet = 0, fill = 0;
      // low open shore any part of the lot may be built on (or dredged out of the basin)
      const shore = (j: number) => c.w.biome[j] !== Biome.Town && !c.river[j] && !c.w.feature[j] && !(c.w.flags[j] & (Flag.Field | Flag.Corridor));
      // the lot, and a tile of open sea round its seaward part, so the mouth opens on the sea
      for (let k = -inland + 1; k <= out + 1 && ok; k++) {
        for (let o = -half - 1; o <= half + 1 && ok; o++) {
          if (k <= 0 && Math.abs(o) > half) continue;
          const tx = x + dx * k + px * o, tz = z + dz * k + pz * o;
          if (tx < lo || tz < lo || tx >= N - lo || tz >= N - lo) { ok = false; break; }
          const j = idx(tx, tz);
          const inLot = k <= out && Math.abs(o) <= half;
          if (k > 0 && !c.land[j]) ok = c.E[j] < SEA && c.lakeLvl[j] <= -128;
          else if (k > 0) { ok = inLot && shore(j) && c.E[j] < SEA + 1.5; fill++; }
          else if (!c.land[j]) { ok = c.lakeLvl[j] <= -128; wet++; }
          else ok = shore(j) && Math.abs(c.E[j] - SEA - 1) < 2.5;
        }
      }
      // the quay is built on the shore, not mostly out over the sea, and the harbour mostly in the sea
      if (!ok || wet > W || fill > (W * out) / 4) continue;
      const score = Math.min(60, townNear(c, x, z, 60)) + wet * 0.3 + fill * 0.2 + c.rng() * 4;
      if (!best || score < best.score) best = { x, z, d, score };
    }
  }
  if (!best) return null;
  const [dx, dz] = DIRS[best.d];
  const px = -dz, pz = dx;
  let x0 = N, z0 = N, x1 = -1, z1 = -1;
  for (let k = -inland + 1; k <= out; k++) {
    for (let o = -half; o <= half; o++) {
      const tx = best.x + dx * k + px * o, tz = best.z + dz * k + pz * o;
      x0 = Math.min(x0, tx); z0 = Math.min(z0, tz); x1 = Math.max(x1, tx); z1 = Math.max(z1, tz);
      const j = idx(tx, tz);
      if (!harbourLand(k, o, W, D)) {
        // the basin and the mouth: any shore in them is dredged out to sea
        if (c.land[j]) { c.land[j] = 0; c.E[j] = SEA - 1; c.river[j] = 0; c.w.biome[j] = Biome.Ocean; c.w.cleared[j] = 1; }
        continue;
      }
      c.land[j] = 1;
      c.E[j] = SEA + 1;
      c.river[j] = 0;
      // the moles and the quay's edge are walls into the water, not slopes
      if (k >= 0) c.w.flags[j] |= Flag.Corridor;
      c.w.biome[j] = Biome.Town;
      c.w.lot[j] = FINISH[kind] ?? Lot.Paved;
      c.w.cleared[j] = 1;
    }
  }
  const wx = x1 - x0 + 1, wz = z1 - z0 + 1;
  const s = site(kind, name, x0, z0, wx, wz, SEA + 1, best.d);
  // its gate is at the back of the quay (the front is the sea)
  const gx = best.x - dx * inland, gz = best.z - dz * inland;
  if (inB(gx, gz)) s.gate = idx(gx, gz);
  return { site: s, moved: true };
}

/**
 * The dam: across a river where the valley walls stand high either side, its crest a road, with the
 * valley behind it flooded to just under the crest.
 */
function dam(c: Ctx, spec: Wonderful, name: string): WorkSite | null {
  const { kind, w: W, d: D } = spec.wonder;
  const lo = c.band + 14;
  let best: { x: number; z: number; alongX: boolean; crest: number; score: number } | null = null;
  for (let i = 0; i < N * N; i++) {
    if (!c.river[i]) continue;
    const x = i % N, z = (i - x) / N;
    if (x < lo || z < lo || x >= N - lo || z >= N - lo || c.E[i] < SEA + 2) continue;
    // the river runs along x if its neighbours along x are river too
    const alongX = (inB(x + 1, z) && c.river[idx(x + 1, z)] > 0) || (inB(x - 1, z) && c.river[idx(x - 1, z)] > 0);
    // the wall runs across the river: along z when the river runs along x
    const half = W >> 1;
    let left = -Infinity, right = -Infinity, ok = true;
    for (let o = -half; o < W - half && ok; o++) {
      const tx = alongX ? x : x + o, tz = alongX ? z + o : z;
      if (!inB(tx, tz)) { ok = false; break; }
      const j = idx(tx, tz);
      if (!c.land[j] || c.w.biome[j] === Biome.Town) { ok = false; break; }
      if (o < -2) left = Math.max(left, c.E[j]);
      if (o > 2) right = Math.max(right, c.E[j]);
    }
    if (!ok) continue;
    // a wall no taller than ten steps and no lower than three: a shallow valley gets an embankment
    const sides = Math.min(left, right) - c.E[i];
    if (sides < 0.3) continue;
    const crest = Math.round(c.E[i] + Math.max(3, Math.min(10, sides)));
    const height = sides;
    const score = -height - (c.river[i] === 2 ? 2 : 0) + c.rng() * 2;
    if (!best || score < best.score) best = { x, z, alongX, crest, score };
  }
  if (!best) return null;
  const { x, z, alongX, crest } = best;
  const half = W >> 1, dHalf = D >> 1;
  const x0 = alongX ? x - dHalf : x - half, z0 = alongX ? z - half : z - dHalf;
  const wx = alongX ? D : W, wz = alongX ? W : D;
  // upstream is the higher end of the river through the lot
  const [ux, uz] = alongX ? [1, 0] : [0, 1];
  const up = c.E[idx(x + ux * (dHalf + 3), z + uz * (dHalf + 3))] ?? 0, down = c.E[idx(x - ux * (dHalf + 3), z - uz * (dHalf + 3))] ?? 0;
  const sign = up >= down ? 1 : -1;
  for (let zz = z0; zz < z0 + wz; zz++) {
    for (let xx = x0; xx < x0 + wx; xx++) {
      const j = idx(xx, zz);
      c.land[j] = 1;
      c.E[j] = crest;
      // walled along its faces; its two ends are left to ramp down to meet the road
      const along = alongX ? zz - z0 : xx - x0;
      if (along > 1 && along < W - 2) c.w.flags[j] |= Flag.Corridor;
    }
  }
  claim(c, kind, x0, z0, wx, wz);
  // the reservoir: flood the valley behind the wall up to a step under the crest
  const lake = crest - 1;
  const start = idx(x + ux * sign * (dHalf + 1), z + uz * sign * (dHalf + 1));
  const queue = [start];
  const seen = new Set<number>(queue);
  for (let h = 0; h < queue.length && h < 1400; h++) {
    const j = queue[h];
    const jx = j % N, jz = (j - jx) / N;
    if (!c.land[j] || c.E[j] >= lake - 0.3 || c.w.biome[j] === Biome.Town) continue;
    if (jx < c.band + 4 || jz < c.band + 4 || jx >= N - c.band - 4 || jz >= N - c.band - 4) continue;
    c.lakeLvl[j] = lake;
    c.E[j] = Math.min(c.E[j], lake - 1.2);
    c.river[j] = 0;
    c.w.biome[j] = Biome.Ocean;
    for (let d = 0; d < 4; d++) {
      const nx = jx + DIRS[d][0], nz = jz + DIRS[d][1];
      if (!inB(nx, nz)) continue;
      const n = idx(nx, nz);
      if (n >= x0 + z0 * N && nx >= x0 && nx < x0 + wx && nz >= z0 && nz < z0 + wz) continue;
      if (!seen.has(n)) { seen.add(n); queue.push(n); }
    }
  }
  const facing = alongX ? (sign > 0 ? 0 : 2) : sign > 0 ? 1 : 3;
  const s = site(kind, name, x0, z0, wx, wz, crest, facing);
  // the road comes onto the crest from one end of the wall
  const gx = alongX ? x : x - half - 1, gz = alongX ? z - half - 1 : z;
  if (inB(gx, gz)) s.gate = idx(gx, gz);
  return s;
}

/** The end of a headland: land with the sea on most sides. */
function cape(c: Ctx, spec: Wonderful, name: string): WorkSite | null {
  const { kind, w: W, d: D } = spec.wonder;
  const lo = c.band + 10;
  let best: { x: number; z: number; lv: number; score: number } | null = null;
  const rays: [number, number][] = [];
  for (let k = 0; k < 12; k++) rays.push([Math.cos((k / 12) * Math.PI * 2), Math.sin((k / 12) * Math.PI * 2)]);
  for (let t = 0; t < 1200; t++) {
    const x0 = lo + Math.floor(c.rng() * Math.max(1, N - 2 * lo - W)), z0 = lo + Math.floor(c.rng() * Math.max(1, N - 2 * lo - D));
    const s = survey(c, x0, z0, W, D, lo);
    if (!s || s.spread > 5) continue;
    const cx = x0 + W / 2, cz = z0 + D / 2;
    let open = 0, first = 26;
    for (const [rx, rz] of rays) {
      for (let r = W / 2 + 2; r < 26; r += 2) {
        const x = Math.floor(cx + rx * r), z = Math.floor(cz + rz * r);
        if (!inB(x, z)) break;
        if (!c.land[idx(x, z)]) { open++; first = Math.min(first, r); break; }
      }
    }
    if (open < 6) continue;
    if (townNear(c, cx, cz, 14) < 8) continue;
    // the lighthouse stands at the water's edge, not up the headland behind it
    const score = -open * 2 - s.mean * 0.3 + s.spread + (kind === 'pharos' ? (first - W / 2) * 1.5 : 0);
    if (!best || score < best.score) best = { x: x0, z: z0, lv: Math.round(s.mean), score };
  }
  if (!best) return null;
  level(c, best.x, best.z, W, D, best.lv, 3);
  claim(c, kind, best.x, best.z, W, D);
  return site(kind, name, best.x, best.z, W, D, best.lv, inward(best.x + W / 2, best.z + D / 2));
}

/**
 * Find and carve the wonder's site. Returns the site and whether the coastline moved (the pier
 * raises land out of the sea), or null when nowhere on the cell suits it.
 */
export function planWonder(
  w: World, land: Uint8Array, E: Float32Array, river: Uint8Array, lakeLvl: Int8Array, rng: Rng, spec: Wonderful, band: number,
): { site: WorkSite; moved: boolean } | null {
  const c: Ctx = { w, land, E, river, lakeLvl, rng, band };
  const forms = spec.wonder.name;
  let name = forms[Math.floor(rng() * forms.length)];
  if (name.endsWith(' ')) name += w.name.split(' ')[0];
  switch (spec.wonder.where) {
    case 'flat': { const s = onFlat(c, spec, name) ?? onFlat(c, spec, name, 1.8); return s && { site: s, moved: false }; }
    case 'high': { const s = onHigh(c, spec, name); return s && { site: s, moved: false }; }
    case 'lake': { const s = byLake(c, spec, name); return s && { site: s, moved: false }; }
    // a lighthouse is no use on a hill out of sight of the sea: the Pharos has a headland or nothing
    case 'cape': { const s = cape(c, spec, name) ?? (spec.wonder.kind === 'pharos' ? null : onHigh(c, spec, name)); return s && { site: s, moved: false }; }
    case 'valley': { const s = dam(c, spec, name); return s && { site: s, moved: false }; }
    case 'shore': return pier(c, spec, name);
    case 'harbour': return harbour(c, spec, name);
  }
}
