import { hex, scale, type RGB } from '../../world/biomes';
import { PSEG, inPond, meadowEdge, parkPlan, pondEdge, type Feature, type ParkPath, type ParkPlan, type ParkTheme, type Pond } from '../../world/greatParks';
import { Vis } from '../nightLights';
import { COOL_GLOW, DARK, METAL, STONE, TAU, WARM_GLOW, WATER, WHITE, WOOD, type Draw, type Kit, type P3 } from './kit';
import { mulberry32, type Rng } from '../../world/rng';
import { CONCESSIONS, concessionRow, type StandSpot } from './concessions';
import { TEAM_AHEAD, carriageBody, carriagePalette, horseTeam } from './carriage';

/**
 * A great park (world/greatParks.ts): the lawns, the meadows and fields, the lake and its island, the footpaths and
 * their bridges, the beds and hedges and the park's buildings, all laid flat on the lot from the park's plan. Its
 * trees and low planting are instanced with the country's own (render/props.ts), so they turn with the seasons and
 * cost a draw call a kind rather than a triangle each.
 *
 * Flat things lie in layers a few thousandths apart so no two fight: meadows, fields, the shore, paths, beds, water.
 */

const Y_MEADOW = 0.003, Y_FIELD = 0.007, Y_SHORE = 0.006, Y_PATH = 0.011, Y_BED = 0.015, Y_WATER = 0.012, Y_ISLAND = 0.02;

interface Look { path: RGB; meadow: RGB; shore: RGB; water: RGB; roof: RGB; wall: RGB; bridge: RGB }
const LOOK: Record<ParkTheme, Look> = {
  english: { path: hex(0xd9c9a3), meadow: hex(0x8fcf6a), shore: hex(0xcfc4a0), water: hex(0x5fa6cc), roof: hex(0x4f6b4a), wall: hex(0xf2e6d0), bridge: hex(0xd8cfb8) },
  french: { path: hex(0xebe2cb), meadow: hex(0xa3d97c), shore: hex(0xe3dccb), water: hex(0x63acd8), roof: hex(0x5a5f6b), wall: hex(0xf1f0ea), bridge: hex(0xe3dccb) },
  japanese: { path: hex(0xc6c1b5), meadow: hex(0x79a857), shore: hex(0x9f9a8e), water: hex(0x4f92ad), roof: hex(0x3f4a52), wall: hex(0xe8dcc0), bridge: hex(0xc8372d) },
  prairie: { path: hex(0xc7ad7a), meadow: hex(0xcbbf6e), shore: hex(0xb8b07a), water: hex(0x5a9cc0), roof: hex(0x8a4a3a), wall: hex(0xe8d3b0), bridge: hex(0x8d6d48) },
  tropical: { path: hex(0xdcbba2), meadow: hex(0x79c757), shore: hex(0xeadbb0), water: hex(0x45b6c8), roof: hex(0xa0523d), wall: hex(0xf6e7c8), bridge: hex(0xb8875a) },
  pinewood: { path: hex(0xb58e60), meadow: hex(0x9caa62), shore: hex(0xa69a7c), water: hex(0x4f8eb0), roof: hex(0x5a4436), wall: hex(0x9c7a55), bridge: hex(0x7a5a3a) },
  mediterranean: { path: hex(0xe2c69c), meadow: hex(0xbfbe7a), shore: hex(0xe8e2d4), water: hex(0x5aaedc), roof: hex(0xb5543f), wall: hex(0xf4f0e6), bridge: hex(0xe8e2d4) },
};
const HEDGE = hex(0x3f7d3a), DIRT = hex(0xc49a6c), LINE = hex(0xf4f2ec), MOWN = hex(0x9ad774), GLASS = hex(0xbfe2ea), BRONZE = hex(0x6f6a4a);
const LAMP = hex(0xe8e0c8);

/** A flat polygon lying at height y, as a fan from its middle (it must be star-shaped round that middle). */
function fan(k: Kit, pts: [number, number][], y: number, col: RGB): void {
  let cx = 0, cz = 0;
  for (const [x, z] of pts) { cx += x; cz += z; }
  cx /= pts.length; cz /= pts.length;
  const I: P3 = [cx, y - 1, cz];
  for (let i = 0; i < pts.length; i++) {
    const a = pts[i], b = pts[(i + 1) % pts.length];
    k.tri([cx, y, cz], [a[0], y, a[1]], [b[0], y, b[1]], col, I);
  }
}

/** A flat strip along a run of points, mitred at the joints. */
function ribbon(k: Kit, pts: [number, number][], w: number, y: number, col: RGB): void {
  if (pts.length < 2) return;
  const off: [number, number][] = pts.map((_, i) => {
    const a = pts[Math.max(0, i - 1)], b = pts[Math.min(pts.length - 1, i + 1)];
    const dx = b[0] - a[0], dz = b[1] - a[1], L = Math.hypot(dx, dz) || 1;
    return [-dz / L * w / 2, dx / L * w / 2];
  });
  for (let i = 1; i < pts.length; i++) {
    const a = pts[i - 1], b = pts[i], oa = off[i - 1], ob = off[i];
    k.quad([a[0] + oa[0], y, a[1] + oa[1]], [b[0] + ob[0], y, b[1] + ob[1]], [b[0] - ob[0], y, b[1] - ob[1]], [a[0] - oa[0], y, a[1] - oa[1]], col, [(a[0] + b[0]) / 2, y - 1, (a[1] + b[1]) / 2]);
  }
}

/** Is local (x, z) on one of the drive's tiles? Nothing of the park is drawn there: the road is. */
const onDrive = (p: ParkPlan, x: number, z: number): boolean => {
  if (!p.road) return false;
  const tx = Math.floor(x + p.W / 2), tz = Math.floor(z + p.D / 2);
  return tx >= 0 && tz >= 0 && tx < p.W && tz < p.D && p.roadSet.has(tz * p.W + tx);
};

function drawPath(k: Kit, p: ParkPlan, path: ParkPath, look: Look): void {
  // the ground stretches, broken where the path crosses the drive, and the bridges over the water
  let run: [number, number][] = [];
  const flush = () => { if (run.length >= 2) ribbon(k, run, path.w, Y_PATH, look.path); run = []; };
  for (let i = 0; i < path.pts.length; i++) {
    const [x, z] = path.pts[i];
    if (onDrive(p, x, z) || path.bridge[i]) { flush(); continue; }
    run.push([x, z]);
  }
  flush();
  // bridges: from the last dry point before the water to the first after it, an arch with a rail each side
  for (let i = 1; i < path.pts.length; i++) {
    if (!path.bridge[i] || path.bridge[i - 1]) continue;
    let j = i;
    while (j < path.pts.length - 1 && path.bridge[j]) j++;
    const a = path.pts[i - 1], b = path.pts[j];
    const n = Math.max(3, j - i + 2), rise = p.theme === 'japanese' ? 0.22 : 0.1;
    const deck: P3[] = [];
    for (let s = 0; s <= n; s++) {
      const t = s / n;
      deck.push([a[0] + (b[0] - a[0]) * t, 0.03 + Math.sin(Math.PI * t) * rise, a[1] + (b[1] - a[1]) * t]);
    }
    const dx = b[0] - a[0], dz = b[1] - a[1], L = Math.hypot(dx, dz) || 1, nx = -dz / L, nz = dx / L, hw = path.w / 2 + 0.04;
    for (let s = 1; s < deck.length; s++) {
      const u = deck[s - 1], v = deck[s];
      k.bar(u, v, 0.02, look.bridge);
      k.quad([u[0] + nx * hw, u[1] + 0.02, u[2] + nz * hw], [v[0] + nx * hw, v[1] + 0.02, v[2] + nz * hw], [v[0] - nx * hw, v[1] + 0.02, v[2] - nz * hw], [u[0] - nx * hw, u[1] + 0.02, u[2] - nz * hw], look.bridge, [(u[0] + v[0]) / 2, u[1] - 1, (u[2] + v[2]) / 2]);
      for (const sg of [-1, 1]) k.bar([u[0] + nx * hw * sg, u[1] + 0.09, u[2] + nz * hw * sg], [v[0] + nx * hw * sg, v[1] + 0.09, v[2] + nz * hw * sg], 0.012, look.bridge);
    }
    for (const sg of [-1, 1]) for (const e of [deck[0], deck[deck.length - 1], deck[deck.length >> 1]]) k.box(e[0] + nx * hw * sg, 0, e[2] + nz * hw * sg, 0.03, e[1] + 0.1, 0.03, look.bridge);
    i = j;
  }
}

function drawPond(k: Kit, q: Pond, look: Look, theme: ParkTheme): void {
  const formal = q.kind === 'basin' || q.kind === 'canal' || q.kind === 'quatrefoil';
  const edge = (out: number) => Array.from({ length: PSEG }, (_, i) => pondEdge(q, (i / PSEG) * TAU, out));
  fan(k, edge(formal ? 0.1 : 0.14), Y_SHORE, look.shore);
  fan(k, edge(0), Y_WATER, look.water);
  // a formal basin has a stone kerb standing round it
  if (formal) {
    const kerb = edge(0.05);
    for (let i = 0; i < kerb.length; i++) {
      const a = kerb[i], b = kerb[(i + 1) % kerb.length];
      k.bar([a[0], 0.03, a[1]], [b[0], 0.03, b[1]], 0.035, look.shore);
    }
  }
  if (q.island) {
    const i = q.island, ring: [number, number][] = [];
    for (let s = 0; s < 14; s++) {
      const a = (s / 14) * TAU, r = i.r * (0.9 + 0.12 * Math.sin(a * 3 + i.x));
      ring.push([i.x + Math.cos(a) * r, i.z + Math.sin(a) * r]);
    }
    fan(k, ring.map(([x, z]) => [i.x + (x - i.x) * 1.12, i.z + (z - i.z) * 1.12] as [number, number]), Y_ISLAND - 0.003, look.shore);
    fan(k, ring, Y_ISLAND, theme === 'japanese' ? hex(0x6f9a4a) : MOWN);
  }
}

/** Something drawn turned a quarter-turn's multiple about its own middle (x, z). */
function quarter(yaw: number): number { return ((Math.round(yaw / (Math.PI / 2)) % 4) + 4) % 4; }

function lampPost(k: Kit, x: number, z: number): void {
  k.box(x, 0, z, 0.025, 0.4, 0.025, DARK);
  k.glowBox(x, 0.4, z, 0.06, 0.06, 0.06, LAMP, [17.6, 30, 1.8], WARM_GLOW);
}

function drawFeature(k: Kit, f: Feature, look: Look, theme: ParkTheme, r: () => number): void {
  const { x, z } = f;
  switch (f.kind) {
    case 'plaza':
      k.disc(x, Y_PATH + 0.002, z, f.r, scale(look.path, 1.04), 16);
      break;
    case 'fountain': {
      const st = STONE[Math.floor(r() * STONE.length)] ?? 0xe3dccb, stone = hex(st);
      k.cyl(x, 0, z, 0.36, 0.07, stone, 14);
      k.disc(x, 0.072, z, 0.31, WATER, 14);
      k.cyl(x, 0.07, z, 0.05, 0.16, stone, 8);
      k.cyl(x, 0.23, z, 0.14, 0.03, stone, 10);
      k.cyl(x, 0.26, z, 0.025, 0.14, hex(0xcfe8f4), 6);
      break;
    }
    case 'obelisk':
      k.box(x, 0, z, 0.2, 0.08, 0.2, look.shore);
      k.box(x, 0.08, z, 0.1, 0.62, 0.1, scale(look.shore, 0.95));
      k.cone(x, 0.7, z, 0.072, 0.12, scale(look.shore, 0.95), 4);
      break;
    case 'statue':
      k.box(x, 0, z, 0.16, 0.14, 0.16, look.shore);
      k.box(x, 0.14, z, 0.07, 0.16, 0.05, BRONZE);
      k.dome(x, 0.3, z, 0.035, BRONZE, 6, 2);
      break;
    case 'bandstand': {
      const R = f.r;
      k.cyl(x, 0, z, R, 0.07, look.wall, 8);
      for (let i = 0; i < 8; i++) {
        const a = (i / 8) * TAU + Math.PI / 8;
        k.box(x + Math.cos(a) * R * 0.88, 0.07, z + Math.sin(a) * R * 0.88, 0.025, 0.28, 0.025, WHITE);
      }
      k.cone(x, 0.35, z, R * 1.15, 0.2, look.roof, 8);
      k.tagged(Vis.Weekend, () => k.glowBox(x, 0.3, z, R * 1.2, 0.03, R * 1.2, LAMP, [18, 23, 2], WARM_GLOW));
      break;
    }
    case 'gazebo': {
      const R = f.r;
      k.cyl(x, 0, z, R, 0.04, WOOD, 6);
      for (let i = 0; i < 6; i++) { const a = (i / 6) * TAU; k.box(x + Math.cos(a) * R * 0.85, 0.04, z + Math.sin(a) * R * 0.85, 0.02, 0.22, 0.02, WHITE); }
      k.cone(x, 0.26, z, R * 1.15, 0.16, look.roof, 6);
      break;
    }
    case 'temple': {
      const R = f.r;
      k.cyl(x, 0, z, R, 0.06, look.shore, 10);
      for (let i = 0; i < 6; i++) { const a = (i / 6) * TAU; k.cyl(x + Math.cos(a) * R * 0.78, 0.06, z + Math.sin(a) * R * 0.78, 0.022, 0.26, WHITE, 5); }
      k.cyl(x, 0.32, z, R * 0.92, 0.04, WHITE, 10);
      k.dome(x, 0.36, z, R * 0.82, WHITE, 10, 3);
      break;
    }
    case 'pagoda': {
      const red = hex(0xb8402f), roof = look.roof;
      let y = 0, w = f.r * 1.4;
      for (let s = 0; s < 3; s++) {
        k.box(x, y, z, w * 0.62, 0.14, w * 0.62, s === 0 ? look.wall : red);
        k.hip(x, y + 0.14, z, w, 0.07, w, roof);
        y += 0.2; w *= 0.78;
      }
      k.cyl(x, y, z, 0.012, 0.16, hex(0xd4a72c), 4);
      break;
    }
    case 'teahouse': {
      const q = quarter(f.yaw), wx = q % 2 ? 0.5 : 0.62, wz = q % 2 ? 0.62 : 0.5;
      k.box(x, 0, z, wx + 0.14, 0.05, wz + 0.14, WOOD);
      k.box(x, 0.05, z, wx, 0.2, wz, look.wall);
      k.hip(x, 0.25, z, wx + 0.22, 0.16, wz + 0.22, look.roof);
      k.glowBox(x, 0.08, z, wx * 0.9, 0.1, wz * 0.9, hex(0xfff0c0), [17.5, 22.5, 1.6], WARM_GLOW);
      break;
    }
    case 'boathouse': {
      // the house on the bank, its slip running out over the water the way it faces
      const q = quarter(f.yaw), out: [number, number] = [[0, 1], [1, 0], [0, -1], [-1, 0]][q] as [number, number];
      const along = q % 2 === 1, wx = along ? 0.62 : 0.48, wz = along ? 0.48 : 0.62;
      k.box(x, 0, z, wx, 0.28, wz, look.wall);
      k.gable(x, 0.28, z, wx + 0.06, 0.16, wz + 0.06, look.roof, look.wall, !along);
      k.box(x + out[0] * 0.5, 0.02, z + out[1] * 0.5, along ? 0.5 : 0.36, 0.03, along ? 0.36 : 0.5, WOOD);
      // two rowing boats tied up at the slip
      for (const s of [-0.12, 0.12]) {
        const bx = x + out[0] * 0.56 + (along ? 0 : s), bz = z + out[1] * 0.56 + (along ? s : 0);
        k.box(bx, Y_WATER, bz, along ? 0.24 : 0.08, 0.03, along ? 0.08 : 0.24, pickBoat(r));
      }
      break;
    }
    case 'glasshouse': {
      const q = quarter(f.yaw), along = q % 2 === 1, wx = along ? 0.9 : 1.3, wz = along ? 1.3 : 0.9;
      k.box(x, 0, z, wx, 0.1, wz, look.shore);
      k.box(x, 0.1, z, wx - 0.04, 0.3, wz - 0.04, GLASS);
      k.gable(x, 0.4, z, wx - 0.02, 0.24, wz - 0.02, GLASS, GLASS, along);
      k.dome(x, 0.4, z, Math.min(wx, wz) * 0.32, GLASS, 10, 3);
      k.glowBox(x, 0.12, z, wx - 0.1, 0.24, wz - 0.1, GLASS, [17, 23, 1.2], COOL_GLOW);
      break;
    }
    case 'kiosk': {
      k.box(x, 0, z, 0.24, 0.18, 0.2, look.wall);
      k.gable(x, 0.18, z, 0.3, 0.08, 0.26, r() < 0.5 ? hex(0x3f9b4a) : hex(0xe2412f), look.wall);
      break;
    }
    case 'playground': {
      const red = hex(0xe2412f), blue = hex(0x2f7fb5), yellow = hex(0xf2c14e);
      k.disc(x, Y_PATH, z, f.r, hex(0xe9d9a6), 12);
      k.box(x - 0.2, 0, z - 0.15, 0.1, 0.24, 0.1, blue);
      k.bar([x - 0.2, 0.24, z - 0.1], [x - 0.2, 0.02, z + 0.25], 0.03, yellow);
      for (const s of [-0.2, 0.2]) k.bar([x + 0.25 + s, 0, z], [x + 0.25 + s, 0.3, z], 0.01, red);
      k.bar([x + 0.05, 0.3, z], [x + 0.45, 0.3, z], 0.01, red);
      for (const s of [0.18, 0.32]) k.box(x + s, 0.08, z, 0.07, 0.012, 0.04, DARK);
      break;
    }
    case 'bench': {
      const q = quarter(f.yaw), along = q % 2 === 1;
      k.box(x, 0.03, z, along ? 0.06 : 0.2, 0.03, along ? 0.2 : 0.06, WOOD);
      const back = [[0, -0.03], [-0.03, 0], [0, 0.03], [0.03, 0]][q];
      k.box(x + back[0], 0.06, z + back[1], along ? 0.014 : 0.2, 0.05, along ? 0.2 : 0.014, WOOD);
      break;
    }
    case 'lamp':
      lampPost(k, x, z);
      break;
  }
}

const BOATS = [0xe2412f, 0xf4f2ec, 0x2f7fb5, 0x3f9b4a];
const pickBoat = (r: () => number): RGB => hex(BOATS[Math.floor(r() * BOATS.length)]);

export const greatPark: Draw = (k, W, D, b, r) => {
  const p = parkPlan(b.seed, W, D);
  const look = LOOK[p.theme];
  // the meadows, in their own grass, and the fields mown and marked out on them
  for (const m of p.meadows) fan(k, Array.from({ length: PSEG }, (_, i) => meadowEdge(m, (i / PSEG) * TAU)), Y_MEADOW, look.meadow);
  for (const f of p.fields) {
    const ex = f.yaw ? f.d / 2 : f.w / 2, ez = f.yaw ? f.w / 2 : f.d / 2;
    fan(k, [[f.x - ex, f.z - ez], [f.x + ex, f.z - ez], [f.x + ex, f.z + ez], [f.x - ex, f.z + ez]], Y_FIELD, MOWN);
    if (f.kind === 'ball') {
      // a baseball diamond in one corner: the infield dirt and the bases
      const cx = f.x - ex * 0.35, cz = f.z + ez * 0.25, s = Math.min(ex, ez) * 0.75;
      fan(k, [[cx, cz - s], [cx + s, cz], [cx, cz + s], [cx - s, cz]], Y_FIELD + 0.002, DIRT);
      for (const [dx, dz] of [[0, -s], [s, 0], [0, s], [-s, 0]]) k.box(cx + dx * 0.9, Y_FIELD, cz + dz * 0.9, 0.05, 0.006, 0.05, LINE);
    } else {
      for (const sz of [-1, 1]) k.box(f.x, Y_FIELD, f.z + sz * (ez - 0.06), ex * 2 - 0.12, 0.004, 0.025, LINE);
      for (const sx of [-1, 0, 1]) k.box(f.x + sx * (ex - 0.06), Y_FIELD, f.z, 0.025, 0.004, ez * 2 - 0.12, LINE);
      k.hoop(f.x, Y_FIELD, f.z, Math.min(ex, ez) * 0.3, 0.008, LINE, 12, 'xz');
      for (const sx of [-1, 1]) for (const dz of [-0.14, 0.14]) k.box(f.x + sx * (ex - 0.06), 0, f.z + dz, 0.02, 0.14, 0.02, WHITE);
    }
  }
  for (const q of p.ponds) drawPond(k, q, look, p.theme);
  for (const path of p.paths) drawPath(k, p, path, look);
  // where three paths or more meet, a round of paving
  for (const [x, z, n] of p.junctions) if (!onDrive(p, x, z) && !p.ponds.some((q) => inPond(q, x, z, 0.2))) k.disc(x, Y_PATH + 0.001, z, 0.15 + n * 0.03, look.path, 10);
  for (const bed of p.beds) {
    if (bed.round) {
      k.cyl(bed.x, Y_BED - 0.01, bed.z, bed.w / 2, 0.03, hex(bed.col), 10, hex(bed.col), bed.d / 2);
      k.cyl(bed.x, Y_BED, bed.z, bed.w / 2 + 0.05, 0.01, hex(0x7a5a3a), 10, hex(0x7a5a3a), bed.d / 2 + 0.05);
      continue;
    }
    // a parterre: a flat of flowers inside a clipped box hedge
    const hx = bed.w / 2, hz = bed.d / 2;
    fan(k, [[bed.x - hx, bed.z - hz], [bed.x + hx, bed.z - hz], [bed.x + hx, bed.z + hz], [bed.x - hx, bed.z + hz]], Y_BED, hex(bed.col));
    for (const sz of [-1, 1]) k.box(bed.x, 0, bed.z + sz * hz, bed.w + 0.06, 0.08, 0.06, HEDGE);
    for (const sx of [-1, 1]) k.box(bed.x + sx * hx, 0, bed.z, 0.06, 0.08, bed.d - 0.06, HEDGE);
    k.cone(bed.x, 0, bed.z, 0.07, 0.24, scale(HEDGE, 1.1), 6);
  }
  for (const h of p.hedges) k.hoop(h.x, 0.0, h.z, h.r, 0.04, HEDGE, 16, 'xz');
  for (const f of p.features) drawFeature(k, f, look, p.theme, r);
  // stone posts at the gates, so the way in reads from the road
  for (const [x, z] of p.graph.nodes) {
    if (Math.abs(Math.abs(x) - W / 2) > 0.05 && Math.abs(Math.abs(z) - D / 2) > 0.05) continue;
    if (!p.graph.edges.some(([a, bb]) => p.graph.nodes[a][0] === x && p.graph.nodes[a][1] === z || p.graph.nodes[bb][0] === x && p.graph.nodes[bb][1] === z)) continue;
    const alongX = Math.abs(Math.abs(z) - D / 2) <= 0.05;
    for (const s of [-0.2, 0.2]) k.box(x + (alongX ? s : 0), 0, z + (alongX ? 0 : s), 0.07, 0.2, 0.07, p.theme === 'japanese' ? hex(0x8d6d48) : look.shore);
  }
  // render-only extras on a seed of their own, so nothing above shifts: stands by the paths, carriages on them
  concessionRow(k, standSpots(p, mulberry32((b.seed ^ 0x5eed) >>> 0)));
  carriageTours(k, p, mulberry32((b.seed ^ 0xca77) >>> 0));
  void METAL;
};

// ---- concession stands beside the paths ------------------------------------------------------------------------------

/** The planting that is low enough to stand a queue among; the rest are trees. */
const LOW_PLANTS = new Set<string>(['tuft', 'rock', 'shrub', 'reeds', 'fern', 'heather', 'stoneLantern', 'lavender', 'sunflower']);

function segDist(x: number, z: number, a: [number, number], b: [number, number]): number {
  const dx = b[0] - a[0], dz = b[1] - a[1], L2 = dx * dx + dz * dz;
  const t = L2 > 0 ? Math.max(0, Math.min(1, ((x - a[0]) * dx + (z - a[1]) * dz) / L2)) : 0;
  return Math.hypot(x - a[0] - dx * t, z - a[1] - dz * t);
}
function pathDist(path: ParkPath, x: number, z: number): number {
  let d = Infinity;
  for (let i = 1; i < path.pts.length; i++) d = Math.min(d, segDist(x, z, path.pts[i - 1], path.pts[i]));
  return d;
}

/** Points of a stand group in its own frame: its queue (either way it may bend), and where its picnic tables may go. */
const STAND_QUEUE: [number, number][] = [[0, 0.25], [0.08, 0.4], [-0.08, 0.4], [0.15, 0.44], [-0.15, 0.44]];
const STAND_TABLES: [number, number][] = [[0.46, 0.02], [-0.46, 0.02]];

/**
 * Two to four concession stands where people walk: round the junctions and plazas facing in, and along the paths
 * facing them, best of all by the fields, the lake and the playground. Each stays off the water, the drive, the
 * paths, the park's buildings, fields, beds, hedges and trees, the queue in front included.
 */
function standSpots(p: ParkPlan, r: Rng): StandSpot[] {
  const { W, D } = p;
  const trees = p.plants.filter((pl) => !LOW_PLANTS.has(pl.kind)), low = p.plants.filter((pl) => LOW_PLANTS.has(pl.kind));
  type Use = 'body' | 'queue' | 'table';
  const ok = (x: number, z: number, use: Use): boolean => {
    const m = use === 'body' ? 0.24 : use === 'table' ? 0.13 : 0.06;
    if (Math.abs(x) > W / 2 - 0.5 || Math.abs(z) > D / 2 - 0.5) return false;
    if (p.ponds.some((q) => inPond(q, x, z, use === 'queue' ? 0.12 : 0.3))) return false;
    for (const [dx, dz] of [[0, 0], [m, 0], [-m, 0], [0, m], [0, -m]]) if (onDrive(p, x + dx, z + dz)) return false;
    for (const path of p.paths) if (pathDist(path, x, z) < path.w / 2 + (use === 'queue' ? -0.03 : m)) return false;
    for (const f of p.features) {
      if (use === 'queue' && f.kind === 'plaza') continue;
      if (Math.hypot(f.x - x, f.z - z) < f.r + (use === 'body' ? 0.3 : m + 0.04)) return false;
    }
    for (const f of p.fields) {
      const ex = f.yaw ? f.d / 2 : f.w / 2, ez = f.yaw ? f.w / 2 : f.d / 2;
      if (Math.abs(x - f.x) < ex + m && Math.abs(z - f.z) < ez + m) return false;
    }
    for (const bd of p.beds) if (Math.abs(x - bd.x) < bd.w / 2 + m + 0.05 && Math.abs(z - bd.z) < bd.d / 2 + m + 0.05) return false;
    for (const h of p.hedges) if (Math.abs(Math.hypot(h.x - x, h.z - z) - h.r) < m + 0.06) return false;
    const tg = use === 'body' ? 0.32 : use === 'table' ? 0.22 : 0.13;
    for (const t of trees) if (Math.hypot(t.x - x, t.z - z) < tg) return false;
    if (use !== 'queue') for (const t of low) if (Math.hypot(t.x - x, t.z - z) < m) return false;
    return true;
  };
  // a point of the group's own frame, out in the lot
  const put = (x: number, z: number, yaw: number, [u, v]: [number, number]): [number, number] => {
    const c = Math.cos(yaw), s = Math.sin(yaw);
    return [x + u * c + v * s, z - u * s + v * c];
  };
  const cands: { x: number; z: number; yaw: number; score: number }[] = [];
  const round = (cx: number, cz: number, d: number, score: number) => {
    for (let a = 0; a < 12; a++) {
      const ang = (a / 12) * TAU + r() * 0.2, x = cx + Math.sin(ang) * d, z = cz + Math.cos(ang) * d;
      cands.push({ x, z, yaw: Math.atan2(cx - x, cz - z), score: score + r() });
    }
  };
  for (const [x, z, n] of p.junctions) round(x, z, 0.15 + n * 0.03 + 0.52, 3);
  for (const f of p.features) if (f.kind === 'plaza') round(f.x, f.z, f.r + 0.48, 3.4);
  for (const path of p.paths) {
    let run = 0.4 + r() * 0.4;
    for (let i = 1; i < path.pts.length; i++) {
      const [ax, az] = path.pts[i - 1], [bx, bz] = path.pts[i], L = Math.hypot(bx - ax, bz - az);
      run -= L;
      if (run > 0 || path.bridge[i]) continue;
      run = 0.8;
      for (const sg of [-1, 1]) {
        const nx = (-(bz - az) / (L || 1)) * sg, nz = ((bx - ax) / (L || 1)) * sg, off = path.w / 2 + 0.46;
        const x = bx + nx * off, z = bz + nz * off;
        let score = (path.main ? 1.5 : 0.8) + r() * 0.8;
        if (p.fields.some((f) => Math.hypot(f.x - x, f.z - z) < Math.max(f.w, f.d) / 2 + 1.4)) score += 1.2;
        if (p.ponds.some((q) => inPond(q, x, z, 1.6))) score += 1;
        if (p.features.some((f) => (f.kind === 'playground' || f.kind === 'bandstand' || f.kind === 'boathouse') && Math.hypot(f.x - x, f.z - z) < 2)) score += 0.8;
        cands.push({ x, z, yaw: Math.atan2(-nx, -nz), score });
      }
    }
  }
  cands.sort((a, b) => b.score - a.score);
  const want = Math.max(2, Math.min(4, Math.round((W * D) / 60))), gap = W * D > 120 ? 3.2 : 2.2;
  const out: StandSpot[] = [];
  const first = Math.floor(r() * CONCESSIONS.length);
  for (const c of cands) {
    if (out.length >= want) break;
    if (out.some((o) => Math.hypot(o.x - c.x, o.z - c.z) < gap)) continue;
    if (!ok(c.x, c.z, 'body') || !STAND_QUEUE.every((q) => ok(...put(c.x, c.z, c.yaw, q), 'queue'))) continue;
    const tables = STAND_TABLES.filter((t) => r() < 0.55 && ok(...put(c.x, c.z, c.yaw, t), 'table'));
    out.push({ x: c.x, z: c.z, yaw: c.yaw, variant: CONCESSIONS[(first + out.length) % CONCESSIONS.length], seed: Math.floor(r() * 4294967296), tables });
  }
  return out;
}

// ---- carriage tours round the main paths -------------------------------------------------------------------------------

export interface Route { pts: [number, number][]; ys: number[]; cum: number[]; L: number; closed: boolean; trim: [number, number] }

/** The height of a path's points: on the ground, or up on the arch of the bridge they cross by (as drawPath draws it). */
function pathYs(p: ParkPlan, path: ParkPath): number[] {
  const ys = path.pts.map(() => 0), rise = p.theme === 'japanese' ? 0.22 : 0.1;
  for (let i = 1; i < path.pts.length; i++) {
    if (!path.bridge[i] || path.bridge[i - 1]) continue;
    let j = i;
    while (j < path.pts.length - 1 && path.bridge[j]) j++;
    const a = path.pts[i - 1], b = path.pts[j], span = Math.hypot(b[0] - a[0], b[1] - a[1]) || 1;
    for (let m = i; m < j; m++) ys[m] = 0.05 + Math.sin((Math.PI * Math.hypot(path.pts[m][0] - a[0], path.pts[m][1] - a[1])) / span) * rise;
    i = j;
  }
  return ys;
}

type Walk = { order: [number, boolean][]; closed: boolean; L: number };

/**
 * The routes a carriage can drive: the main paths chained end to end at their nodes, going straight on where the
 * way divides. The longest closed round comes first; failing one, the longest run, driven there and back (and in a
 * big park the longest other run, for a second carriage).
 */
function carriageRoutes(p: ParkPlan): Route[] {
  let pool = p.paths.filter((q) => q.main);
  if (!pool.length) pool = p.paths;
  const key = (pt: [number, number]) => `${Math.round(pt[0] * 20)},${Math.round(pt[1] * 20)}`;
  const ends = pool.map((q) => [key(q.pts[0]), key(q.pts[q.pts.length - 1])]);
  const at = new Map<string, number[]>();
  ends.forEach(([a, b], i) => { for (const e of [a, b]) at.set(e, [...(at.get(e) ?? []), i]); });
  const len = pool.map((q) => q.pts.reduce((n, pt, i) => (i ? n + Math.hypot(pt[0] - q.pts[i - 1][0], pt[1] - q.pts[i - 1][1]) : 0), 0));
  // the way path i (driven forward or back) arrives at its far node (end) or leaves its near one, as an angle
  const dirAt = (i: number, fwd: boolean, end: boolean): number => {
    const q = pool[i].pts, n = q.length;
    const [a, b] = end ? (fwd ? [q[n - 2], q[n - 1]] : [q[1], q[0]]) : (fwd ? [q[0], q[1]] : [q[n - 1], q[n - 2]]);
    return Math.atan2(b[0] - a[0], b[1] - a[1]);
  };
  const walk = (start: number, fwd: boolean, banned: Set<number>): Walk => {
    const used = new Set([start]), order: [number, boolean][] = [[start, fwd]];
    const home = fwd ? ends[start][0] : ends[start][1];
    let cur = fwd ? ends[start][1] : ends[start][0], dir = dirAt(start, fwd, true), L = len[start];
    for (let guard = 0; guard < 64; guard++) {
      if (cur === home && order.length >= 3) return { order, closed: true, L };
      let best = -1, bf = true, bt = Infinity;
      for (const j of at.get(cur) ?? []) {
        if (used.has(j) || banned.has(j)) continue;
        const f = ends[j][0] === cur, d0 = dirAt(j, f, false);
        const turn = Math.abs(Math.atan2(Math.sin(d0 - dir), Math.cos(d0 - dir)));
        if (turn < bt) { bt = turn; best = j; bf = f; }
      }
      if (best < 0 || bt > 1.9) break;
      used.add(best); order.push([best, bf]); L += len[best];
      cur = bf ? ends[best][1] : ends[best][0];
      dir = dirAt(best, bf, true);
    }
    return { order, closed: false, L };
  };
  const rank = (w: Walk) => w.L + (w.closed && w.L > 5 ? 1000 : 0);
  const bestFrom = (banned: Set<number>): Walk | null => {
    let best: Walk | null = null;
    for (let i = 0; i < pool.length; i++) {
      if (banned.has(i)) continue;
      for (const f of [true, false]) { const w = walk(i, f, banned); if (!best || rank(w) > rank(best)) best = w; }
    }
    return best;
  };
  const build = (w: Walk): Route => {
    const pts: [number, number][] = [], ys: number[] = [];
    for (const [i, f] of w.order) {
      const q = pool[i], qy = pathYs(p, q);
      const order = q.pts.map((_, j) => (f ? j : q.pts.length - 1 - j));
      for (const j of order.slice(pts.length ? 1 : 0)) { pts.push(q.pts[j]); ys.push(qy[j]); }
    }
    const cum = [0];
    for (let i = 1; i < pts.length; i++) cum.push(cum[i - 1] + Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]));
    const edge = (pt: [number, number]) => Math.abs(pt[0]) > p.W / 2 - 0.4 || Math.abs(pt[1]) > p.D / 2 - 0.4;
    const trim: [number, number] = w.closed ? [0, 0] : [edge(pts[0]) ? 0.55 : 0.2, edge(pts[pts.length - 1]) ? 0.55 : 0.2];
    return { pts, ys, cum, L: cum[cum.length - 1], closed: w.closed, trim };
  };
  const first = bestFrom(new Set());
  if (!first) return [];
  const out = [build(first)];
  if (!first.closed) {
    const second = bestFrom(new Set(first.order.map(([i]) => i)));
    if (second && second.L > 4) out.push(build(second));
  }
  return out.filter((rt) => rt.L - rt.trim[0] - rt.trim[1] > 1.5);
}

/** A point along a route s tiles from its start: [x, y, z]. */
function routeAt(rt: Route, s: number): [number, number, number] {
  s = rt.closed ? ((s % rt.L) + rt.L) % rt.L : Math.max(0, Math.min(rt.L, s));
  let lo = 0, hi = rt.cum.length - 1;
  while (hi - lo > 1) { const m = (lo + hi) >> 1; if (rt.cum[m] <= s) lo = m; else hi = m; }
  const t = (s - rt.cum[lo]) / ((rt.cum[hi] - rt.cum[lo]) || 1);
  const a = rt.pts[lo], b = rt.pts[hi];
  return [a[0] + (b[0] - a[0]) * t, rt.ys[lo] + (rt.ys[hi] - rt.ys[lo]) * t, a[1] + (b[1] - a[1]) * t];
}
function routeHeading(rt: Route, s: number): number {
  const a = routeAt(rt, s - 0.12), b = routeAt(rt, s + 0.12);
  return Math.atan2(b[0] - a[0], b[2] - a[2]);
}

const CARRIAGE_SPEED = 0.3, CARRIAGE_TURN = 5, CARRIAGE_HOURS: [number, number] = [9, 19];

/**
 * Horse-drawn carriages touring the park by day: round a closed loop of the main paths, or along a run of them and
 * back, turning at each end. One rig: each carriage is three parts, its body and its team in each of two strides,
 * swapped as they trot so the legs go (only two of the three are ever drawn); all are put away out of hours.
 */
function carriageTours(k: Kit, p: ParkPlan, r: Rng): void {
  const routes = carriageRoutes(p);
  if (!routes.length) return;
  const big = p.W * p.D >= 150;
  const cars: { rt: Route; off: number; n: 1 | 2; pal: ReturnType<typeof carriagePalette> }[] = [];
  const add = (rt: Route, off: number) => cars.push({ rt, off, n: r() < 0.6 ? 2 : 1, pal: carriagePalette(r) });
  const r0 = routes[0];
  add(r0, r() * 200);
  if (big && r0.closed && r0.L > 12) add(r0, cars[0].off + r0.L / 2 / CARRIAGE_SPEED);
  else if (big && routes[1]) add(routes[1], r() * 200);
  const parts: ((q: Kit) => void)[] = [];
  for (const c of cars) parts.push((q) => carriageBody(q, c.pal, c.n), (q) => horseTeam(q, c.pal, 0, c.n), (q) => horseTeam(q, c.pal, 1, c.n));
  const ease = (f: number) => f * f * (3 - 2 * f);
  let clock = 0;
  k.rig(0, 0, 0, parts, (objs, dt, hour) => {
    clock += dt;
    const out = hour >= CARRIAGE_HOURS[0] && hour < CARRIAGE_HOURS[1];
    cars.forEach((c, i) => {
      const body = objs[i * 3], A = objs[i * 3 + 1], B = objs[i * 3 + 2];
      if (!out) { body.visible = A.visible = B.visible = false; return; }
      const rt = c.rt, t = clock + c.off;
      // where the carriage is and which way it heads, then where its team is and which way it heads
      let s: number, h: number, team: [number, number, number], th: number;
      if (rt.closed) {
        s = t * CARRIAGE_SPEED; h = routeHeading(rt, s);
        team = routeAt(rt, s + TEAM_AHEAD); th = routeHeading(rt, s + TEAM_AHEAD);
      } else {
        // there, a turn at the far end, back, a turn at the near end
        const lo = rt.trim[0], hi = rt.L - rt.trim[1], run = (hi - lo) / CARRIAGE_SPEED, cyc = 2 * (run + CARRIAGE_TURN);
        const u = ((t % cyc) + cyc) % cyc;
        let turn = -1, back = false;
        if (u < run) { s = lo + u * CARRIAGE_SPEED; h = routeHeading(rt, s); }
        else if (u < run + CARRIAGE_TURN) { s = hi; turn = ease((u - run) / CARRIAGE_TURN); h = routeHeading(rt, hi) + Math.PI * turn; }
        else if (u < 2 * run + CARRIAGE_TURN) { s = hi - (u - run - CARRIAGE_TURN) * CARRIAGE_SPEED; h = routeHeading(rt, s) + Math.PI; back = true; }
        else { s = lo; turn = ease((u - 2 * run - CARRIAGE_TURN) / CARRIAGE_TURN); h = routeHeading(rt, lo) + Math.PI * (1 + turn); }
        if (turn >= 0) {
          const at = routeAt(rt, s);
          team = [at[0] + Math.sin(h) * TEAM_AHEAD, at[1], at[2] + Math.cos(h) * TEAM_AHEAD]; th = h;
        } else {
          const ahead = back ? -TEAM_AHEAD : TEAM_AHEAD;
          team = routeAt(rt, s + ahead); th = routeHeading(rt, s + ahead) + (back ? Math.PI : 0);
        }
      }
      const at = routeAt(rt, s), g = t * 16 + i;
      body.visible = true;
      body.position.set(at[0], at[1] + 0.0025 * Math.abs(Math.sin(g)), at[2]);
      body.rotation.set(0, h, 0);
      for (const o of [A, B]) {
        o.position.set(team[0], team[1] + 0.004 * Math.abs(Math.sin(g)), team[2]);
        o.rotation.order = 'YXZ';
        o.rotation.set(0.025 * Math.sin(g * 2), th, 0);
      }
      A.visible = Math.sin(g) >= 0;
      B.visible = !A.visible;
    });
  });
}
