import { N, SEA, Biome, Feature, Flag, World, DIRS, inB, idx } from './tiles';
import { mulberry32, type Rng } from './rng';
import { NEXT_WORLD } from './nextWorld';

export interface FieldInfo { level: number; tiles: number[]; center: [number, number]; /** What each tile was before it was farmed (0.7.0, for reshapeFields). */ was?: number[] }

/** Grow a few farmland blobs on flat, mid-distance plains. Returns per-field info. */
export function growFarms(w: World, E: Float32Array, river: Uint8Array, rng: Rng, maxFields = 4, band = 0): FieldInfo[] {
  const NN = N * N;
  // a county's farms are worked on a bigger scale than an island's, and up onto the gentler hills
  const broad = w.kind === 'continent';
  const arable = (b: number) => b === Biome.Plains || (broad && b === Biome.Hills);
  const cands: number[] = [];
  for (let i = 0; i < NN; i++) {
    if (!arable(w.biome[i])) continue;
    const cd = w.coastDist[i];
    if (cd < 6) continue;
    if (river[i]) continue;
    // a field is levelled ground: on a continent it keeps out of the strip a neighbour also works out
    const x = i % N, z = (i - x) / N;
    if (band && (x < band + 8 || z < band + 8 || x >= N - band - 8 || z >= N - band - 8)) continue;
    cands.push(i);
  }
  const fields: FieldInfo[] = [];
  let tries = 0;
  while (fields.length < maxFields && tries++ < (broad ? 900 : 400) && cands.length) {
    const seed = cands[Math.floor(rng() * cands.length)];
    const sx = seed % N, sz = (seed - sx) / N;
    let tooClose = false;
    for (const f of fields) {
      if (Math.abs(f.center[0] - sx) + Math.abs(f.center[1] - sz) < (broad ? 30 : 36)) { tooClose = true; break; }
    }
    if (tooClose) continue;
    // local flatness check
    let ok = true;
    for (let dz = -3; dz <= 3 && ok; dz++) for (let dx = -3; dx <= 3; dx++) {
      if (!inB(sx + dx, sz + dz)) { ok = false; break; }
      const j = idx(sx + dx, sz + dz);
      if (Math.abs(E[j] - E[seed]) > 1.2 || !arable(w.biome[j]) || river[j]) { ok = false; break; }
    }
    if (!ok) continue;

    const target = broad ? 60 + Math.floor(rng() * 60) : 30 + Math.floor(rng() * 30);
    const tiles: number[] = [seed];
    const inField = new Set<number>([seed]);
    for (let q = 0; q < tiles.length && tiles.length < target; q++) {
      const i = tiles[q];
      const x = i % N, z = (i - x) / N;
      // prefer growing into a rectangle-ish blob: shuffle dirs. Fisher–Yates, never sort() with a
      // random comparator: how often that calls rng() is up to the engine's sort, so Chrome and node
      // would draw differently from here on and grow two different worlds from one seed
      const order = [0, 1, 2, 3];
      for (let k = 3; k > 0; k--) {
        const j = Math.floor(rng() * (k + 1));
        const t = order[k]; order[k] = order[j]; order[j] = t;
      }
      for (const d of order) {
        const nx = x + DIRS[d][0], nz = z + DIRS[d][1];
        if (!inB(nx, nz)) continue;
        const j = idx(nx, nz);
        if (inField.has(j) || !arable(w.biome[j]) || river[j]) continue;
        if (Math.abs(E[j] - E[seed]) > 1.6) continue;
        if (Math.abs(nx - sx) > (broad ? 10 : 7) || Math.abs(nz - sz) > (broad ? 10 : 7)) continue;
        inField.add(j);
        tiles.push(j);
        if (tiles.length >= target) break;
      }
    }
    if (tiles.length < 16) continue;
    let sum = 0;
    for (const t of tiles) sum += E[t];
    const level = Math.round(sum / tiles.length);
    const id = fields.length;
    const before = NEXT_WORLD ? tiles.map((t) => w.biome[t]) : undefined;
    for (const t of tiles) {
      w.biome[t] = Biome.Farm;
      w.flags[t] |= Flag.Field;
      w.fieldId[t] = id;
    }
    fields.push({ level, tiles, center: [sx, sz], ...(before ? { was: before } : {}) });
  }
  return fields;
}

/**
 * 0.7.0: every field laid out again in one of five shapes round its seed (shapedField), each on a generator of its
 * own. Run once the wonders and works have chosen their ground against the fields as they were (generate.ts), so
 * the farms, those sites and every draw of the county's generator come out as before: nothing after them shifts
 * (town names, lake towns, a wonder's road).
 */
export function reshapeFields(w: World, E: Float32Array, river: Uint8Array, fields: FieldInfo[], band = 0): void {
  const broad = w.kind === 'continent';
  const arable = (b: number) => b === Biome.Plains || (broad && b === Biome.Hills);
  for (const f of fields) f.tiles.forEach((t, k) => { w.biome[t] = f.was![k]; w.flags[t] &= ~Flag.Field; w.fieldId[t] = -1; });
  fields.forEach((f, id) => {
    const seed = idx(f.center[0], f.center[1]);
    const free = (t: number) => arable(w.biome[t]) && w.feature[t] === Feature.None && !(w.flags[t] & Flag.Poi);
    const shaped = (free(seed) ? shapedField(w, E, river, (b) => arable(b), seed, band, mulberry32((seed * 2654435761) ^ (id * 40503) ^ 0xf1e1d), free) : null)
      ?? f.tiles.filter(free);
    let sum = 0;
    for (const t of shaped) { sum += E[t]; w.biome[t] = Biome.Farm; w.flags[t] |= Flag.Field; w.fieldId[t] = id; }
    f.tiles = shaped;
    f.level = Math.round(sum / Math.max(1, shaped.length));
  });
}

/**
 * A field of one of five shapes round its seed tile (0.7.0): a long narrow strip, a big square or oblong (60 to
 * 150 tiles), an L, a round pivot-irrigated field, or a small patch; turned either way. Only the tiles the old
 * growth would have taken are kept (arable, dry, within a step and a half of the seed's height, clear of the
 * seam band), and of those only the piece joined to the seed. Null if that leaves too little.
 */
function shapedField(w: World, E: Float32Array, river: Uint8Array, arable: (b: number) => boolean, seed: number, band: number, r: Rng, free: (t: number) => boolean): number[] | null {
  const sx = seed % N, sz = (seed - sx) / N;
  const cells = new Set<number>();
  const rect = (x0: number, z0: number, wx: number, wz: number) => {
    for (let z = z0; z < z0 + wz; z++) for (let x = x0; x < x0 + wx; x++) if (inB(sx + x, sz + z)) cells.add(idx(sx + x, sz + z));
  };
  const roll = r(), turn = r() < 0.5;
  const box = (a: number, b: number) => (turn ? rect(-(b >> 1), -(a >> 1), b, a) : rect(-(a >> 1), -(b >> 1), a, b));
  if (roll < 0.22) box(13 + Math.floor(r() * 10), 3 + Math.floor(r() * 2));          // a long strip
  else if (roll < 0.5) box(8 + Math.floor(r() * 6), 8 + Math.floor(r() * 5));          // a big square or oblong
  else if (roll < 0.64) {                                                              // an L
    const a = 9 + Math.floor(r() * 4), t = 4 + Math.floor(r() * 2), fx = r() < 0.5 ? 1 : -1, fz = r() < 0.5 ? 1 : -1;
    rect(fx > 0 ? -(a >> 1) : (a >> 1) - a + 1, fz > 0 ? -(a >> 1) : (a >> 1) - t + 1, a, t);
    rect(fx > 0 ? -(a >> 1) : (a >> 1) - t + 1, fz > 0 ? -(a >> 1) : (a >> 1) - a + 1, t, a);
  } else if (roll < 0.8) {                                                             // a round pivot field
    const R = 4 + r() * 2.5;
    for (let dz = -7; dz <= 7; dz++) for (let dx = -7; dx <= 7; dx++) if (Math.hypot(dx, dz) <= R && inB(sx + dx, sz + dz)) cells.add(idx(sx + dx, sz + dz));
  } else box(5 + Math.floor(r() * 3), 4 + Math.floor(r() * 3));                       // a small patch
  const ok = (j: number) => {
    const x = j % N, z = (j - x) / N;
    if (band && (x < band + 8 || z < band + 8 || x >= N - band - 8 || z >= N - band - 8)) return false;
    return arable(w.biome[j]) && free(j) && !river[j] && Math.abs(E[j] - E[seed]) <= 1.6;
  };
  // the piece of it joined to the seed
  const out = [seed], got = new Set(out);
  for (let k = 0; k < out.length; k++) {
    const x = out[k] % N, z = (out[k] - x) / N;
    for (const [dx, dz] of DIRS) {
      if (!inB(x + dx, z + dz)) continue;
      const j = idx(x + dx, z + dz);
      if (cells.has(j) && !got.has(j) && ok(j)) { got.add(j); out.push(j); }
    }
  }
  return out.length >= 16 ? out : null;
}

// ---------------- colours ----------------

export type RGB = [number, number, number];
export function hex(h: number): RGB {
  return [((h >> 16) & 255) / 255, ((h >> 8) & 255) / 255, (h & 255) / 255];
}
export function mix(a: RGB, b: RGB, t: number): RGB {
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
}
export function scale(a: RGB, s: number): RGB { return [a[0] * s, a[1] * s, a[2] * s]; }

