/** A long strand of sand: where it is, and how far it reaches inland. */
interface BeachInfo { x: number; z: number; r: number; tiles: number[] }

/**
 * Broad beaches, here and there along the coast.
 *
 * An ordinary shore is two tiles of sand between the water and whatever grows behind it. A few
 * stretches of every island get something much wider instead: the ground is eased down to just
 * above the waterline over a dozen tiles or more, so there is somewhere to park, somewhere to walk,
 * and in summer somewhere for a crowd to spend the afternoon.
 */
export function growBeaches(
  w: World, land: Uint8Array, E: Float32Array, river: Uint8Array, rng: Rng, count: number, band = 0,
): BeachInfo[] {
  const NN = N * N;
  const out: BeachInfo[] = [];
  if (count <= 0) return out;
  const shore: number[] = [];
  const keep = band + 24;   // a beach eases the ground down over a couple of dozen tiles
  for (let i = 0; i < NN; i++) {
    if (!land[i] || w.coastDist[i] !== 1 || river[i]) continue;
    const x = i % N, z = (i - x) / N;
    if (band && (x < keep || z < keep || x >= N - keep || z >= N - keep)) continue;
    shore.push(i);
  }
  if (!shore.length) return out;

  for (let tries = 0; out.length < count && tries < 300; tries++) {
    const seed = shore[Math.floor(rng() * shore.length)];
    const sx = seed % N, sz = (seed - sx) / N;
    if (out.some((b) => Math.hypot(b.x - sx, b.z - sz) < 55)) continue;
    // a shallow shelf behind it, not a cliff: the ground just inland has to be low already
    let inland = 0, n = 0;
    for (let dz = -4; dz <= 4; dz++) for (let dx = -4; dx <= 4; dx++) {
      if (!inB(sx + dx, sz + dz)) continue;
      const j = idx(sx + dx, sz + dz);
      if (!land[j]) continue;
      inland += E[j];
      n++;
    }
    if (!n || inland / n > SEA + 3.2) continue;

    const r = 13 + Math.floor(rng() * 11);
    const depth = 7 + Math.floor(rng() * 7);
    const tiles: number[] = [];
    for (let dz = -r; dz <= r; dz++) {
      for (let dx = -r; dx <= r; dx++) {
        const x = sx + dx, z = sz + dz;
        if (!inB(x, z)) continue;
        const i = idx(x, z);
        if (!land[i] || river[i]) continue;
        const cd = w.coastDist[i];
        if (cd > depth) continue;
        // round the ends off so it reads as a bay rather than a stamped square
        const fade = 1 - Math.min(1, Math.hypot(dx, dz) / r);
        if (fade <= 0.02) continue;
        // sand rises very gently from the waterline to the back of the beach
        const want = SEA + 0.55 + (cd / depth) * 1.5;
        const t = Math.min(1, fade * 1.6);
        E[i] = Math.min(E[i], want) * t + E[i] * (1 - t);
        if (E[i] < want + 0.4) {
          w.feature[i] = Feature.Beach;
          tiles.push(i);
        }
      }
    }
    if (tiles.length > 90) out.push({ x: sx, z: sz, r, tiles });
  }
  return out;
}
