import { N, Biome, Flag, World, DIRS, inB, idx, isFlat } from './tiles';
import type { Rng } from './rng';
import type { CarStats } from '../game/cars';
import { astar } from './graph';
import type { FieldInfo } from './biomes';

function hasDrivableNeighbour(w: World, i: number): boolean { return w.edges[i] !== 0; }

function farFromOthers(w: World, x: number, z: number, minDist: number): boolean {
  for (const p of w.pois) if (Math.abs(p.x - x) + Math.abs(p.z - z) < minDist) return false;
  return true;
}

/** Cabins, barns and a lighthouse on tiles the starter car can reach. */
export function placePois(w: World, reach: Uint8Array, fields: FieldInfo[], rng: Rng, cabins = 12): void {
  const NN = N * N;
  // never on a road or a corridor kept for one (a causeway's landing on the border is both), nor on the border itself
  const onBorder = (i: number) => { const x = i % N, z = (i - x) / N; return x === 0 || z === 0 || x === N - 1 || z === N - 1; };
  const usable = (i: number) =>
    reach[i] && w.townId[i] < 0 && w.portId[i] < 0 && !w.rail[i] && !w.road[i] && !onBorder(i) && isFlat(w, i) && w.water[i] < 0 &&
    !(w.flags[i] & (Flag.Field | Flag.Poi | Flag.Track | Flag.Ramp | Flag.Corridor)) && hasDrivableNeighbour(w, i);

  // barns: one per field, on a field tile that is flat and reachable
  fields.forEach((f) => {
    const opts = f.tiles.filter((t) => reach[t] && isFlat(w, t) && w.water[t] < 0 && !(w.flags[t] & Flag.Poi));
    if (!opts.length) return;
    const t = opts[Math.floor(rng() * opts.length)];
    const x = t % N, z = (t - x) / N;
    w.pois.push({ type: 'barn', x, z, yaw: Math.floor(rng() * 4) * Math.PI / 2 });
    w.flags[t] |= Flag.Poi;
  });

  // lighthouse: highest reachable flat sea-cliff tile, else a beach tile
  let best = -1, bestH = -Infinity;
  for (let i = 0; i < NN; i++) {
    if (w.biome[i] !== Biome.SeaCliff || !usable(i)) continue;
    const h = w.corners[i * 4] + rng() * 0.5;
    if (h > bestH) { bestH = h; best = i; }
  }
  if (best < 0) {
    const beaches: number[] = [];
    for (let i = 0; i < NN; i++) if (w.biome[i] === Biome.Beach && usable(i)) beaches.push(i);
    if (beaches.length) best = beaches[Math.floor(rng() * beaches.length)];
  }
  if (best >= 0) {
    const x = best % N, z = (best - x) / N;
    w.pois.push({ type: 'lighthouse', x, z, yaw: 0 });
    w.flags[best] |= Flag.Poi;
  }

  // cabins: forest first, then hills, then anywhere reachable
  const pools: number[][] = [[], [], []];
  for (let i = 0; i < NN; i++) {
    if (!usable(i)) continue;
    const b = w.biome[i];
    if (b === Biome.Forest) pools[0].push(i);
    else if (b === Biome.Hills || b === Biome.Mountain) pools[1].push(i);
    else if (b === Biome.Plains || b === Biome.SeaCliff || b === Biome.Desert || b === Biome.Canyon) pools[2].push(i);
  }
  const target = cabins > 0 ? Math.max(1, cabins - 2 + Math.floor(rng() * 4)) : 0;
  let placed = 0;
  for (const pool of pools) {
    let tries = 0;
    while (placed < target && tries++ < 600 && pool.length) {
      const i = pool[Math.floor(rng() * pool.length)];
      const x = i % N, z = (i - x) / N;
      if (!farFromOthers(w, x, z, 22) || (w.flags[i] & Flag.Poi)) continue;
      // avoid being fully hemmed in by trees: needs a flat drivable neighbour to park on
      let park = false;
      for (let d = 0; d < 4 && !park; d++) {
        const nx = x + DIRS[d][0], nz = z + DIRS[d][1];
        if (inB(nx, nz) && (w.edges[i] & (1 << d)) && isFlat(w, idx(nx, nz))) park = true;
      }
      if (!park) continue;
      w.pois.push({ type: 'cabin', x, z, yaw: Math.floor(rng() * 4) * Math.PI / 2 });
      w.flags[i] |= Flag.Poi;
      placed++;
    }
    if (placed >= target) break;
  }
}

/** Dirt tracks: nearest-neighbour chain from spawn through every POI and town, A* between stops. */
export function layTracks(w: World, stats: CarStats): number {
  const start = idx(Math.floor(w.spawn.x), Math.floor(w.spawn.z));
  const remaining = w.pois.map((p) => idx(p.x, p.z));
  for (const t of w.towns) if (t.entry.length) remaining.push(t.entry[0]);
  for (const p of w.ports) remaining.push(p.entry);
  let cur = start;
  let laid = 0;
  while (remaining.length) {
    const cx = cur % N, cz = (cur - cx) / N;
    let bi = 0, bd = Infinity;
    remaining.forEach((t, k) => {
      const tx = t % N, tz = (t - tx) / N;
      const d = Math.abs(tx - cx) + Math.abs(tz - cz);
      if (d < bd) { bd = d; bi = k; }
    });
    const next = remaining.splice(bi, 1)[0];
    const path = astar(w, cur, next, stats, Flag.Track);
    if (path) {
      for (const t of path) {
        if (w.water[t] < 0 && !(w.flags[t] & Flag.Poi) && w.townId[t] < 0 && !w.road[t]) w.flags[t] |= Flag.Track;
      }
      laid++;
    }
    cur = next;
  }
  return laid;
}
