import type { KindSpec } from './townKinds';

/**
 * The factions' own buildings (docs/factions.html, "New buildings"): what each is called, how big it is,
 * how tall its model stands, where a town puts it, what it is worth, its icon and its HQ grade. One table,
 * spread into the game's per-kind tables (townKinds, towns' heights, economy, estate, hqGrade, cargo labels,
 * traffic tags), so a new kind is added here once. The models are in render/buildings/factions*.ts.
 */

export const FACTION_KINDS = [
  // the Constabulary
  'highwayPatrol', 'impoundYard',
  // the Family
  'socialClub', 'chopShop', 'bossVilla',
  // the Ministry
  'embassy', 'motorPool', 'mint', 'hangar18',
  // the Visitors
  'crashSite', 'landingRing', 'cropCircle',
  // the Brotherhood
  'unionHall', 'buildersYard', 'asphaltPlant',
  // the Post
  'sortingOffice', 'mailDock', 'mailboxRow',
  // the Army
  'airbase', 'armyDepot', 'checkpoint',
  // the Studios
  'backlot', 'studioGate', 'premiereTheatre', 'starMansion',
  // the Guild
  'fishMarket', 'netLoft', 'lifeboatStation', 'guildHall',
  // the Press
  'printworks', 'broadcastCentre', 'newsstand',
] as const;

export type FactionKind = (typeof FACTION_KINDS)[number];

interface Info {
  label: string;
  icon: string;
  /** The lot in tiles (w × d) the gallery and the roadside placer use. */
  size: [number, number];
  /** How tall the model stands, in world units (towns.ts buildingHeight). */
  h: number;
  /** What it costs to knock down (economy.ts), which sets a lot's floor price. */
  price: number;
  /** As an HQ (hqGrade.ts): 0 for a lot nobody would run a company from. */
  grade: 0 | 1 | 2 | 3 | 4 | 5 | 6 | 7;
  /** Traffic's tag for it: where a car is going when it goes there. */
  tag: 'work' | 'depot' | 'leisure' | 'shop' | 'home' | 'field' | 'dock';
  /** Placed in towns by its own spec (towns.ts factionSites); the country ones are placed by the roadside placer. */
  spec?: KindSpec;
  /** An open lot: nothing stops a car (a ring of stones, a field). */
  open?: boolean;
}

