const pick = <T>(f: (i: Info) => T | undefined): Record<string, T> =>
  Object.fromEntries(FACTION_KINDS.map((k) => [k, f(FACTION_INFO[k])]).filter(([, v]) => v !== undefined)) as Record<string, T>;

/** Spread into townKinds' KIND_SPEC. */
export const FACTION_SPEC = pick((i) => (i.spec ? { ...i.spec, ...(i.open ? OPEN : {}) } : i.open ? { w: i.size[0], d: i.size[1], ...OPEN } : undefined)) as Partial<Record<FactionKind, KindSpec>>;
export const FACTION_HEIGHT = pick((i) => i.h) as Record<FactionKind, number>;
export const FACTION_PRICE = pick((i) => i.price) as Record<FactionKind, number>;
export const FACTION_ICON = pick((i) => i.icon) as Record<FactionKind, string>;
export const FACTION_LABEL = pick((i) => i.label) as Record<FactionKind, string>;
export const FACTION_GRADE = pick((i) => i.grade) as Record<FactionKind, 0 | 1 | 2 | 3 | 4 | 5 | 6 | 7>;
export const FACTION_TAG = pick((i) => i.tag) as Record<FactionKind, Info['tag']>;
export const FACTION_SIZE = pick((i) => i.size) as Record<FactionKind, [number, number]>;
export const isFactionKind = (k: string): k is FactionKind => k in FACTION_INFO;
